$script:I18n["Remesure après réécriture {0}/{1} : {2} piste(s), {3} saine(s), {4} à surveiller{5}, {6} critique(s) ou illisible(s){7}."] = "Re-measure after rewrite {0}/{1}: {2} track(s), {3} healthy, {4} to watch{5}, {6} critical or unreadable{7}."
