# --- Largeurs ajustees au texte (police, langue) : plus de libelles tronques --------
function Fit-ControlText($parent) {
    foreach ($c in @($parent.Controls)) {
        if ($c -is [System.Windows.Forms.CheckBox] -or $c -is [System.Windows.Forms.RadioButton]) {
            if ($c.Text) { $c.AutoSize = $true }
        } elseif ($c -is [System.Windows.Forms.Button] -and $c.Text -and $c.Text -ne '...') {
            $extra = if ($c.Image) { 46 } else { 24 }
            $need = [System.Windows.Forms.TextRenderer]::MeasureText($c.Text, $c.Font).Width + $extra
            if ($c.Width -lt $need) {
                $delta = $need - $c.Width
                $right = [bool]($c.Anchor -band [System.Windows.Forms.AnchorStyles]::Right)
                $left  = [bool]($c.Anchor -band [System.Windows.Forms.AnchorStyles]::Left)
                if ($right -and -not $left) { $c.Left -= $delta }
                $c.Width = $need
            }
        }
        if ($c.Controls.Count -gt 0) { Fit-ControlText $c }
    }
}

# --- Fenetre de confirmation commune (12.8, D3) : frmConfirm --------------------------
function New-ConfirmPicto([string]$kind) {
    # Pictogramme 120 x 84 du bandeau de frmConfirm (affiche en 100 x 70), dessine en GDI+ comme les vignettes du
    # nettoyage : warn (triangle d avertissement), erase (disquette de donnees barree d une croix), data (disquette de
    # donnees inseree dans le lecteur) ; tout autre nom : vignette du nettoyage (New-CleanPicto : forbid, insert...)
    if (@('warn', 'erase', 'data') -notcontains $kind) { return (New-CleanPicto $kind) }
    $bmp = New-Object System.Drawing.Bitmap(120, 84, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
    $g = [System.Drawing.Graphics]::FromImage($bmp)
    $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
    switch ($kind) {
        'warn' {
            $p = New-Object System.Drawing.Drawing2D.GraphicsPath
            $p.AddPolygon([System.Drawing.PointF[]]@((New-Object System.Drawing.PointF(60, 5)), (New-Object System.Drawing.PointF(106, 79)), (New-Object System.Drawing.PointF(14, 79))))
            $b = New-Object System.Drawing.SolidBrush($script:Theme.Warn); $g.FillPath($b, $p); $b.Dispose()
            $pen = New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(150, 92, 10), [single]3)
            $pen.LineJoin = [System.Drawing.Drawing2D.LineJoin]::Round; $g.DrawPath($pen, $p); $pen.Dispose(); $p.Dispose()
            $bw = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::White)
            $rr = New-RoundRect 55 28 10 32 4; $g.FillPath($bw, $rr); $rr.Dispose()
            $g.FillEllipse($bw, [single]54.5, [single]64, [single]11, [single]11); $bw.Dispose()
        }
        'erase' {
            Draw-PictoFloppy $g 24 2 72 $false
            $pen = New-Object System.Drawing.Pen($script:Theme.Danger, [single]8)
            $pen.StartCap = [System.Drawing.Drawing2D.LineCap]::Round; $pen.EndCap = [System.Drawing.Drawing2D.LineCap]::Round
            $g.DrawLine($pen, [single]32, [single]12, [single]88, [single]72); $g.DrawLine($pen, [single]88, [single]12, [single]32, [single]72)
            $pen.Dispose()
        }
        'data' {
            Draw-PictoFloppy $g 38 0 44 $false $true
            Draw-PictoDrive $g $false
            Draw-PictoArrow $g $script:Theme.Accent 98 10 98 50
        }
    }
    $g.Dispose()
    return $bmp
}

function Set-ConfirmGo([bool]$on) {
    # Bouton principal de frmConfirm : bleu et actif seulement case cochee (comme Set-CleanGo) ; style refait, et ancienne
    # icone liberee, seulement quand il change
    $s = $script:ConfirmDlg
    if (-not $s) { return }
    $b = $s.Go; $b.Enabled = $on
    $st = if ($on) { 'primary' } else { 'normal' }
    if ($s.GoStyle -ne $st) { $s.GoStyle = $st; $old = $b.Image; Set-Btn $b $s.Glyph $st; if ($old) { $old.Dispose() } }
}

function Get-ConfirmShort([string]$heading, [string]$text, [int]$max = 100) {
    # 12.8 : question de frmConfirm en court pour le journal (Show-AppConfirm) : titre du bandeau, sinon premiere phrase du
    # texte ; sur une ligne, $max caracteres au plus (coupe au dernier espace, points de suspension)
    $q = ("$heading" -replace '\s+', ' ').Trim()
    if (-not $q) {
        $t = ("$text" -replace '\s+', ' ').Trim()
        $m = [regex]::Match($t, '^.+?[.!?](?=\s|$)')
        $q = if ($m.Success) { $m.Value } else { $t }
    }
    if ($q.Length -gt $max) {
        $cut = $q.Substring(0, $max - 1); $sp = $cut.LastIndexOf(' ')
        if ($sp -gt $max / 2) { $cut = $cut.Substring(0, $sp) }
        $q = $cut.TrimEnd(' ', ',', ';', ':') + [char]0x2026
    }
    return $q
}

function Show-AppConfirm([string]$Title, [string]$Heading, [string]$Text, [string]$Check = '', [string]$GoText = '', [string]$GoGlyph = '', [string]$Level = 'warn', [string]$Picto = 'warn', [string]$AltText = '', $Combo = $null) {
    # 12.8 (S3) : AltText : second bouton d action (btnConfirmAlt), a gauche du bouton principal, soumis a la meme case ;
    # Combo = @{ Label ; Items ; Text ; Tip ; Map } : liste modifiable sous la case (cmbConfirmCombo, marque de la disquette).
    # Reponse dans $script:ConfirmChoice ('go', 'alt', 'close') et texte de la liste dans $script:ConfirmComboText ; la
    # fonction renvoie toujours $true pour le seul bouton principal
    # Confirmation d une action qui engage une disquette ou le materiel (frmConfirm), au modele de frmClean (A4 § 2.4,
    # R1 a R8) : bandeau de la couleur du niveau (danger, warn, info), avec pictogramme GDI+, titre et texte ; case de
    # confirmation en gras si $Check, qui nomme le lecteur ou la disquette (bouton principal actif et bleu seulement case
    # cochee) ; bouton principal, puis Fermer (CancelButton : Fermer, Echap et la croix refusent). Aucun AcceptButton et
    # focus sur la case, ou sur Fermer sans case : Entree ne confirme rien. Renvoie $true seulement pour le bouton
    # principal, case cochee. Banc : Name frmConfirm, chkConfirm, btnConfirmGo, btnConfirmClose (fins de test par
    # OpenForms ; minuteur de securite de make-test : Fermer). 12.8 (validation du 19/10) : chaque reponse est notee au
    # journal, en une ligne : question en court (Get-ConfirmShort) et reponse, confirmee ou refusee (Fermer, Echap, croix,
    # ou bouton principal sans la case).
    if (-not $GoText) { $GoText = (T 'Continuer') }
    $W = 600; $tw = $W - 128
    # 12.8 (S3) : second bouton : fenetre elargie pour que les trois boutons tiennent sur la ligne (memes largeurs que plus bas)
    if ($AltText) {
        $wGo = [math]::Max(170, [System.Windows.Forms.TextRenderer]::MeasureText($GoText, $script:BtnFontBold).Width + $(if ($GoGlyph) { 56 } else { 32 }))
        $wAlt = [math]::Max(150, [System.Windows.Forms.TextRenderer]::MeasureText($AltText, $script:BtnFont).Width + 32)
        $W = [int][math]::Max($W, $wAlt + 8 + $wGo + 8 + 110); $tw = $W - 128
    }
    $tf = [System.Windows.Forms.TextFormatFlags]::WordBreak -bor [System.Windows.Forms.TextFormatFlags]::NoPrefix
    $gdi = New-Object System.Collections.Generic.List[object]       # images et polices liberees avec la fenetre
    $pal = switch ($Level) {
        'danger' { @{ Back = [System.Drawing.Color]::FromArgb(253, 236, 234); Edge = $script:Theme.Danger; Ink = [System.Drawing.Color]::FromArgb(160, 32, 26); Body = [System.Drawing.Color]::FromArgb(110, 24, 20) } }
        'info'   { @{ Back = [System.Drawing.Color]::FromArgb(234, 241, 251); Edge = $script:Theme.Accent; Ink = $script:Theme.Accent2; Body = [System.Drawing.Color]::FromArgb(40, 46, 58) } }
        default  { @{ Back = [System.Drawing.Color]::FromArgb(253, 243, 228); Edge = $script:Theme.Warn; Ink = [System.Drawing.Color]::FromArgb(138, 74, 0); Body = [System.Drawing.Color]::FromArgb(88, 52, 8) } }
    }
    $dlg = New-Object System.Windows.Forms.Form
    $dlg.Name = 'frmConfirm'; $dlg.Text = $Title
    $dlg.FormBorderStyle = 'FixedDialog'; $dlg.MaximizeBox = $false; $dlg.MinimizeBox = $false; $dlg.ShowInTaskbar = $false
    $dlg.StartPosition = 'CenterParent'; $dlg.Icon = $form.Icon; $dlg.Font = $form.Font; $dlg.BackColor = [System.Drawing.Color]::White
    # Bandeau : pictogramme, titre Semibold 11 et texte, hauteurs mesurees dans la langue de l interface
    $pnl = New-Object System.Windows.Forms.Panel
    $pnl.Name = 'pnlConfirmBanner'; $pnl.Location = New-Object System.Drawing.Point(16, 16); $pnl.BackColor = $pal.Back; $pnl.Tag = $pal.Edge
    $pic = New-Object System.Windows.Forms.PictureBox
    $pic.Name = 'picConfirm'; $pic.Image = New-ConfirmPicto $Picto; $gdi.Add($pic.Image); $pic.SizeMode = 'Zoom'
    $pic.Location = New-Object System.Drawing.Point(8, 10); $pic.Size = New-Object System.Drawing.Size(100, 70)
    $fH = New-Object System.Drawing.Font('Segoe UI Semibold', 11); $gdi.Add($fH)
    $lblH = New-Object System.Windows.Forms.Label
    $lblH.Name = 'lblConfirmTitle'; $lblH.Text = $Heading; $lblH.UseMnemonic = $false; $lblH.Font = $fH; $lblH.ForeColor = $pal.Ink
    $hH = [System.Windows.Forms.TextRenderer]::MeasureText($Heading, $fH, (New-Object System.Drawing.Size($tw, 10000)), $tf).Height
    $lblH.Location = New-Object System.Drawing.Point(118, 10); $lblH.Size = New-Object System.Drawing.Size($tw, ($hH + 2))
    $lblT = New-Object System.Windows.Forms.Label
    $lblT.Name = 'lblConfirmText'; $lblT.Text = $Text; $lblT.UseMnemonic = $false; $lblT.ForeColor = $pal.Body; $lblT.Font = $dlg.Font
    # 12.10 (captures du wiki) : hauteur, la plus grande de la mesure du texte et de celle du Label (son propre decoupage
    # des lignes, qui peut en compter une de plus sur un texte long), comme New-DlgBanner : la derniere ligne d un texte
    # long (« Calibration complete sur une disquette sacrifiee ») etait coupee
    $hT = [math]::Max([System.Windows.Forms.TextRenderer]::MeasureText($Text, $dlg.Font, (New-Object System.Drawing.Size($tw, 10000)), $tf).Height, $lblT.GetPreferredSize((New-Object System.Drawing.Size($tw, 0))).Height)
    $lblT.Location = New-Object System.Drawing.Point(118, ($lblH.Bottom + 4)); $lblT.Size = New-Object System.Drawing.Size($tw, ($hT + 4))
    $pnl.Size = New-Object System.Drawing.Size($W, [math]::Max(90, $lblT.Bottom + 10))
    $pnl.Controls.AddRange(@($pic, $lblH, $lblT))
    $pnl.Add_Paint({ $pen = New-Object System.Drawing.Pen([System.Drawing.Color]$this.Tag, [single]2); $_.Graphics.DrawRectangle($pen, 1, 1, $this.Width - 2, $this.Height - 2); $pen.Dispose() })
    $y = $pnl.Bottom + 14
    # Case de confirmation physique, en gras, sur plusieurs lignes si besoin
    $chk = $null
    if ($Check) {
        $chk = New-Object System.Windows.Forms.CheckBox
        $chk.Name = 'chkConfirm'; $chk.Text = $Check; $chk.Font = $bold; $chk.UseMnemonic = $false
        $chk.CheckAlign = 'TopLeft'; $chk.TextAlign = 'TopLeft'
        $hC = [System.Windows.Forms.TextRenderer]::MeasureText($Check, $bold, (New-Object System.Drawing.Size(($W - 24), 10000)), $tf).Height
        $chk.Location = New-Object System.Drawing.Point(16, $y); $chk.Size = New-Object System.Drawing.Size($W, ($hC + 6))
        $y = $chk.Bottom + 12
    }
    # 12.8 (S3) : liste modifiable (marque de la disquette inseree), libelle a gauche, sous la case
    $cmb = $null; $lblCmb = $null
    if ($Combo) {
        $lblCmb = New-Object System.Windows.Forms.Label
        $lblCmb.Name = 'lblConfirmCombo'; $lblCmb.AutoSize = $true; $lblCmb.UseMnemonic = $false; $lblCmb.Text = [string]$Combo.Label; $lblCmb.Font = $dlg.Font
        $lblCmb.Location = New-Object System.Drawing.Point(16, ($y + 4))
        $cmb = New-Object System.Windows.Forms.ComboBox
        $cmb.Name = 'cmbConfirmCombo'; $cmb.DropDownStyle = 'DropDown'
        foreach ($it in @($Combo.Items)) { if ($it) { [void]$cmb.Items.Add([string]$it) } }
        $cmb.Text = [string]$Combo.Text
        $lx = 16 + $lblCmb.PreferredWidth + 8
        $cmb.Location = New-Object System.Drawing.Point($lx, $y); $cmb.Width = [math]::Max(160, 16 + $W - $lx)
        if ($Combo.Tip -and $tip) { $tip.SetToolTip($cmb, [string]$Combo.Tip) }
        $y = $cmb.Bottom + 12
    }
    # Boutons en bas a droite : action principale avec glyphe, puis Fermer (110 px, CancelButton)
    $btnGo = New-Object System.Windows.Forms.Button
    $btnGo.Name = 'btnConfirmGo'; $btnGo.Text = $GoText; $btnGo.DialogResult = [System.Windows.Forms.DialogResult]::OK
    $btnGo.Size = New-Object System.Drawing.Size([math]::Max(170, [System.Windows.Forms.TextRenderer]::MeasureText($GoText, $script:BtnFontBold).Width + $(if ($GoGlyph) { 56 } else { 32 })), 34)
    $btnCl = New-Object System.Windows.Forms.Button
    $btnCl.Name = 'btnConfirmClose'; $btnCl.Text = (T 'Fermer'); $btnCl.Size = New-Object System.Drawing.Size(110, 34)
    $btnCl.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
    Set-Btn $btnCl '' 'normal'
    $btnCl.Location = New-Object System.Drawing.Point((16 + $W - $btnCl.Width), $y)
    $btnGo.Location = New-Object System.Drawing.Point(($btnCl.Left - 8 - $btnGo.Width), $y)
    # 12.8 (S3) : second bouton d action, style normal, a gauche du bouton principal ; inactif tant que la case n est pas cochee
    $btnAlt = $null
    if ($AltText) {
        $btnAlt = New-Object System.Windows.Forms.Button
        $btnAlt.Name = 'btnConfirmAlt'; $btnAlt.Text = $AltText; $btnAlt.DialogResult = [System.Windows.Forms.DialogResult]::Retry
        $btnAlt.Size = New-Object System.Drawing.Size([math]::Max(150, [System.Windows.Forms.TextRenderer]::MeasureText($AltText, $script:BtnFont).Width + 32), 34)
        Set-Btn $btnAlt '' 'normal'
        $btnAlt.Location = New-Object System.Drawing.Point(($btnGo.Left - 8 - $btnAlt.Width), $y)
        $btnAlt.Enabled = (-not $chk)
    }
    $dlg.ClientSize = New-Object System.Drawing.Size(($W + 32), ($y + $btnCl.Height + 16))
    $dlg.CancelButton = $btnCl                        # pas d AcceptButton : Entree ne confirme rien
    $dlg.Controls.Add($pnl); if ($chk) { $dlg.Controls.Add($chk) }; $dlg.Controls.AddRange(@($btnGo, $btnCl))
    if ($btnAlt) { $dlg.Controls.Add($btnAlt) }
    if ($cmb) { $dlg.Controls.Add($lblCmb); $dlg.Controls.Add($cmb) }
    [void](Set-CleanDlgFit $dlg ([System.Windows.Forms.Screen]::FromControl($form).WorkingArea))
    $prev = $script:ConfirmDlg
    $script:ConfirmDlg = @{ Go = $btnGo; Glyph = $GoGlyph; GoStyle = ''; Alt = $btnAlt }
    Set-ConfirmGo (-not $chk)
    if ($chk) { $chk.Add_CheckedChanged({ Set-ConfirmGo $this.Checked; if ($script:ConfirmDlg.Alt) { $script:ConfirmDlg.Alt.Enabled = $this.Checked } }); $dlg.ActiveControl = $chk }
    else { $dlg.ActiveControl = $btnCl }
    $script:ConfirmChoice = 'close'; $script:ConfirmComboText = $null
    try {
        $dr = if ($form.Visible) { $dlg.ShowDialog($form) } else { $dlg.ShowDialog() }
        $ok = [bool]($dr -eq [System.Windows.Forms.DialogResult]::OK -and (-not $chk -or $chk.Checked))
        $alt = [bool]($btnAlt -and $dr -eq [System.Windows.Forms.DialogResult]::Retry -and (-not $chk -or $chk.Checked))
        $script:ConfirmChoice = if ($ok) { 'go' } elseif ($alt) { 'alt' } else { 'close' }
        if ($cmb) { $script:ConfirmComboText = [string]$cmb.Text }
        $ans = if ($ok) { (T 'confirmée') } elseif ($alt) { (T 'autre choix : « {0} »') -f "$AltText" } else { (T 'refusée (Fermer)') }
        Append-Log ((T "Confirmation : {0} : {1}") -f (Get-ConfirmShort $Heading $Text), $ans)
        return $ok
    } finally {
        $script:ConfirmDlg = $prev
        foreach ($b in @($btnGo, $btnCl, $btnAlt)) { if ($b -and $b.Image) { $i = $b.Image; $b.Image = $null; $i.Dispose() } }
        $dlg.Dispose()
        foreach ($o in $gdi) { try { $o.Dispose() } catch { } }
    }
}

# --- Fenetres de decision (12.8, lot 5) : composants communs au modele de frmClean (A4 § 2.4, R1 a R8) ---------------
# frmCalibConfirm, frmReinsert et frmCalibRedo (Show-TimedConfirm), frmCalibSurface, frmCalibReview, frmOldCalib, frmJitter.
# frmConfirm et frmClean gardent leurs propres fonctions (Set-ConfirmGo, Set-CleanGo, Set-CleanDlgFit), au comportement identique.
function Get-DlgPalette([string]$Level) {
    # Couleurs d un bandeau selon le niveau (A4 R2), celles de frmConfirm : fond, cadre, encre du titre, encre du texte
    switch ($Level) {
        'danger' { return @{ Back = [System.Drawing.Color]::FromArgb(253, 236, 234); Edge = $script:Theme.Danger; Ink = [System.Drawing.Color]::FromArgb(160, 32, 26); Body = [System.Drawing.Color]::FromArgb(110, 24, 20) } }
        'info'   { return @{ Back = [System.Drawing.Color]::FromArgb(234, 241, 251); Edge = $script:Theme.Accent; Ink = $script:Theme.Accent2; Body = [System.Drawing.Color]::FromArgb(40, 46, 58) } }
        default  { return @{ Back = [System.Drawing.Color]::FromArgb(253, 243, 228); Edge = $script:Theme.Warn; Ink = [System.Drawing.Color]::FromArgb(138, 74, 0); Body = [System.Drawing.Color]::FromArgb(88, 52, 8) } }
    }
}

function Draw-DlgBadge($g, [string]$kind, [single]$x, [single]$y, [single]$s) {
    # Icone d etat du lot 3 (D15 : h0 ✓, h1 !, h2 ✗ ; Draw-QualityState) de $s pixels en ($x, $y), avec son liseré blanc
    $st = $g.Save()
    $g.TranslateTransform($x, $y); $g.ScaleTransform([single]($s / 64.0), [single]($s / 64.0))
    Draw-QualityState $g $kind ([single]6)
    $g.Restore($st)
}

function New-DlgPicto([string]$kind, [string]$badge = '') {
    # Pictogramme 120 x 84 d un bandeau de fenetre de decision (affiche en 100 x 70), en GDI+ comme ceux de frmConfirm et du
    # nettoyage : disk (disquette de donnees du logo), drive (disquette inseree dans le lecteur), avec l icone d etat $badge
    # (h0, h1, h2) ; curve (courbes de precompensation A et B) ; jitter (disquette et les trois etats SAIN, A SURVEILLER,
    # CRITIQUE) ; tout autre nom : New-ConfirmPicto (warn, data, erase, vignettes du nettoyage). Libere par l appelant
    if (@('disk', 'drive', 'curve', 'jitter') -notcontains $kind) { return (New-ConfirmPicto $kind) }
    $bmp = New-Object System.Drawing.Bitmap(120, 84, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
    $g = [System.Drawing.Graphics]::FromImage($bmp)
    try {
        $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
        switch ($kind) {
            'disk' {
                Draw-PictoFloppy $g 18 4 72 $false
                if ($badge) { Draw-DlgBadge $g $badge 74 40 40 }
            }
            'drive' {
                Draw-PictoFloppy $g 38 0 44 $false $true
                Draw-PictoDrive $g $true
                if ($badge) { Draw-DlgBadge $g $badge 82 2 34 }
            }
            'curve' {
                $rr = New-RoundRect 6 4 108 76 6
                $b = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::White); $g.FillPath($b, $rr); $b.Dispose()
                $pen = New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(205, 212, 224), [single]1.5); $g.DrawPath($pen, $rr); $pen.Dispose(); $rr.Dispose()
                $pen = New-Object System.Drawing.Pen($script:Theme.Muted, [single]2)
                $g.DrawLines($pen, [System.Drawing.PointF[]]@((New-Object System.Drawing.PointF(20, 14)), (New-Object System.Drawing.PointF(20, 68)), (New-Object System.Drawing.PointF(104, 68)))); $pen.Dispose()
                $pa = @((New-Object System.Drawing.PointF(24, 62)), (New-Object System.Drawing.PointF(38, 55)), (New-Object System.Drawing.PointF(52, 50)), (New-Object System.Drawing.PointF(66, 41)), (New-Object System.Drawing.PointF(80, 36)), (New-Object System.Drawing.PointF(100, 24)))
                $pb = @((New-Object System.Drawing.PointF(24, 58)), (New-Object System.Drawing.PointF(38, 53)), (New-Object System.Drawing.PointF(52, 42)), (New-Object System.Drawing.PointF(66, 38)), (New-Object System.Drawing.PointF(80, 29)), (New-Object System.Drawing.PointF(100, 18)))
                $pen = New-Object System.Drawing.Pen($script:Theme.Accent, [single]3); $pen.LineJoin = [System.Drawing.Drawing2D.LineJoin]::Round
                $g.DrawLines($pen, [System.Drawing.PointF[]]$pa); $pen.Dispose()
                $pen = New-Object System.Drawing.Pen($script:Theme.Flux, [single]3); $pen.LineJoin = [System.Drawing.Drawing2D.LineJoin]::Round
                $pen.DashStyle = [System.Drawing.Drawing2D.DashStyle]::Dash
                $g.DrawLines($pen, [System.Drawing.PointF[]]$pb); $pen.Dispose()
            }
            'jitter' {
                Draw-PictoFloppy $g 4 10 64 $false
                Draw-DlgBadge $g 'h0' 82 3 24; Draw-DlgBadge $g 'h1' 82 30 24; Draw-DlgBadge $g 'h2' 82 57 24
            }
        }
    } finally { $g.Dispose() }
    return $bmp
}

function New-DlgBanner($dlg, [int]$Y, [int]$W, [string]$Heading, [string]$Text, [string]$Level, $Image, $Gdi, [string]$TextName = '') {
    # Bandeau d une fenetre de decision (A4 R2), au modele de frmConfirm : rectangle en (16, $Y), de largeur $W, fond et
    # cadre de la couleur du niveau (Get-DlgPalette : danger, warn, info), pictogramme GDI+ $Image (New-DlgPicto) en 100 x 70,
    # titre $Heading en Semibold 11, texte $Text ; hauteurs mesurees dans la langue de l interface. Fond, cadre, pictogramme
    # et titre sont dessines par la fenetre elle-meme (Draw-DlgBanner, donnees dans $dlg.Tag.Banner) ; le texte est le seul
    # controle du bandeau : un Label de PREMIER NIVEAU de $dlg (Name $TextName), du fond du bandeau. Les fins de test lisent
    # les Label de premier niveau des fenetres de calibration (.Controls, non recursif) et y comptent les PictureBox
    # (« courbe affichee ») : ni titre ni pictogramme n y entrent, et aucun controle ne se superpose a un autre (DrawToBitmap,
    # captures du wiki, dessine les controles superposes dans l ordre inverse). Image et police rangees dans $Gdi (liberees
    # avec la fenetre, Clear-DlgGdi). Renvoie @{ Bottom ; Text }.
    $pal = Get-DlgPalette $Level
    $tw = $W - 128
    $tf = [System.Windows.Forms.TextFormatFlags]::WordBreak -bor [System.Windows.Forms.TextFormatFlags]::NoPrefix
    if ($Image) { $Gdi.Add($Image) }
    $fH = New-Object System.Drawing.Font('Segoe UI Semibold', 11); $Gdi.Add($fH)
    $hH = if ($Heading) { [System.Windows.Forms.TextRenderer]::MeasureText($Heading, $fH, (New-Object System.Drawing.Size($tw, 10000)), $tf).Height + 2 } else { 0 }
    $lbl = New-Object System.Windows.Forms.Label
    if ($TextName) { $lbl.Name = $TextName }
    $lbl.AutoSize = $false; $lbl.UseMnemonic = $false; $lbl.Text = $Text; $lbl.ForeColor = $pal.Body; $lbl.BackColor = $pal.Back; $lbl.Font = $dlg.Font
    # Hauteur : la plus grande de la mesure du texte et de celle du Label (son propre decoupage des lignes, qui peut en
    # compter une de plus sur un texte long)
    $hT = [math]::Max([System.Windows.Forms.TextRenderer]::MeasureText($Text, $dlg.Font, (New-Object System.Drawing.Size($tw, 10000)), $tf).Height, $lbl.GetPreferredSize((New-Object System.Drawing.Size($tw, 0))).Height)
    $lbl.Location = New-Object System.Drawing.Point((16 + 118), ($Y + 10 + $hH + $(if ($hH) { 4 } else { 0 }))); $lbl.Size = New-Object System.Drawing.Size($tw, ($hT + 4))
    $rect = New-Object System.Drawing.Rectangle(16, $Y, $W, [math]::Max(90, $lbl.Bottom - $Y + 10))
    $dlg.Tag = @{ Banner = @{ Rect = $rect; Back = $pal.Back; Edge = $pal.Edge; Ink = $pal.Ink; Image = $Image; Heading = $Heading; Font = $fH; HeadH = $hH; TW = $tw } }
    $dlg.Add_Paint({ Draw-DlgBanner $this $_.Graphics })
    $dlg.Controls.Add($lbl)
    return @{ Bottom = $rect.Bottom; Text = $lbl }
}

function Draw-DlgBanner($dlg, $g) {
    # Dessin du bandeau de New-DlgBanner (Paint de la fenetre), decale du defilement (Set-DlgFit) : fond, cadre de 2 px,
    # pictogramme et titre
    $b = if ($dlg.Tag -is [hashtable]) { $dlg.Tag.Banner } else { $null }
    if (-not $b) { return }
    $o = $dlg.AutoScrollPosition
    $r = $b.Rect; $x = $r.X + $o.X; $y = $r.Y + $o.Y
    $br = New-Object System.Drawing.SolidBrush($b.Back); $g.FillRectangle($br, $x, $y, $r.Width, $r.Height); $br.Dispose()
    $pen = New-Object System.Drawing.Pen($b.Edge, [single]2); $g.DrawRectangle($pen, ($x + 1), ($y + 1), ($r.Width - 2), ($r.Height - 2)); $pen.Dispose()
    if ($b.Image) {
        $g.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
        $g.DrawImage($b.Image, (New-Object System.Drawing.Rectangle(($x + 8), ($y + 10), 100, 70)))
    }
    if ($b.Heading) {
        $tf = [System.Windows.Forms.TextFormatFlags]::WordBreak -bor [System.Windows.Forms.TextFormatFlags]::NoPrefix
        [System.Windows.Forms.TextRenderer]::DrawText($g, [string]$b.Heading, $b.Font, (New-Object System.Drawing.Rectangle(($x + 118), ($y + 10), $b.TW, $b.HeadH)), $b.Ink, $tf)
    }
}

function Get-DlgButtonWidth([string]$text, [string]$glyph = '', [int]$min = 110) {
    # Largeur d un bouton de fenetre de decision (A4 R1, R6) : texte mesure en gras (style principal ou danger), glyphe compris
    return [int][math]::Max($min, [System.Windows.Forms.TextRenderer]::MeasureText($text, $script:BtnFontBold).Width + $(if ($glyph) { 56 } else { 32 }))
}

function Set-BtnFitWidth($btn, [switch]$KeepRight) {
    # 12.8 (FIX5) : bouton d onglet elargi a sa taille preferee (texte, icone et marges de Set-Btn, a appeler apres lui),
    # jamais retreci : texte entier dans les deux langues. $KeepRight : bord droit garde (bouton ancre a droite)
    $w = $btn.GetPreferredSize([System.Drawing.Size]::Empty).Width
    if ($w -le $btn.Width) { return }
    if ($KeepRight) { $btn.Left -= ($w - $btn.Width) }
    $btn.Width = $w
}

function Set-PrimaryEnabled($btn, [bool]$on, [string]$glyph = '') {
    # Bouton principal d une fenetre de decision (A4 R5, R6) : bleu et actif seulement quand son action est permise (case de
    # confirmation cochee), sinon style normal grise (generalisation de Set-ConfirmGo et Set-CleanGo, sans couleur codee en
    # dur). Style et icone refaits seulement quand ils changent (style courant dans Tag), ancienne icone liberee
    if (-not $btn) { return }
    $btn.Enabled = $on
    $st = if ($on) { 'primary' } else { 'normal' }
    if ([string]$btn.Tag -ne $st) { $btn.Tag = $st; $old = $btn.Image; Set-Btn $btn $glyph $st; if ($old) { $old.Dispose() } }
}

function Set-DlgFit($dlg, [System.Drawing.Rectangle]$wa) {
    # Fenetre de decision plus haute que la zone de travail $wa (A4 R1, generalisation de Set-CleanDlgFit) : hauteur ramenee a
    # celle de l ecran avec un defilement vertical, largeur augmentee de la barre de defilement. $true si ajustee
    if ($dlg.Height -le $wa.Height) { return $false }
    $dlg.AutoScroll = $true
    $dlg.Size = New-Object System.Drawing.Size(($dlg.Width + [System.Windows.Forms.SystemInformation]::VerticalScrollBarWidth), $wa.Height)
    return $true
}

function Clear-DlgGdi($dlg, $gdi) {
    # Fermeture d une fenetre de decision (A4 R3) : icones des boutons (Set-Btn) retirees, fenetre liberee, puis images et
    # polices de $gdi. Les icones d etat de qualite (Get-QualityIcon) restent a leur cache : jamais dans $gdi
    $todo = New-Object System.Collections.Generic.Stack[object]
    $todo.Push($dlg)
    while ($todo.Count -gt 0) {
        $c = $todo.Pop()
        foreach ($k in @($c.Controls)) { $todo.Push($k) }
        if ($c -is [System.Windows.Forms.Button] -and $c.Image) { $i = $c.Image; $c.Image = $null; $gdi.Add($i) }
    }
    $dlg.Dispose()
    foreach ($o in $gdi) { try { $o.Dispose() } catch { } }
}
# ============================== FONCTIONS : COEUR, GW ET DETECTION DES LECTEURS ===

# ============================== COMPARAISON : LOGIQUE ==========================
function Invoke-NextChainStep {
    if ($script:Chain.Count -eq 0) { return }
    $step = $script:Chain.Dequeue()
    try {
        & $step
    } catch {
        $script:Chain.Clear(); $script:WriteQueue.Clear()
        Stop-WriteWarmup
        if ($script:Rep) { Stop-WriteCheck }
        Append-Log ((T "ERREUR étape : {0}") -f "$($_.Exception.Message)")
        # Etape de calibration en echec : calibration abandonnee, avec l ecriture qu elle devait preceder
        if ($script:Cal) { Stop-PrecompCalib }
        $script:AfterCalib = ''
        if ($txtCmpResult.Text -like ((T 'Comparaison en cours') + '*')) { $txtCmpResult.Text = ((T "ÉCHEC : {0}") -f "$($_.Exception.Message)") }
        if ($script:Restore) { Stop-Restore ((T "erreur interne : {0}") -f "$($_.Exception.Message)") }
        # 12.8 (lot 3a) : mesure de qualite en cours sans analyse : resultat affiche perime
        if ($script:QualView.State -eq 'run' -and $script:QualView.Kind -eq 'measure') { $script:AlignLoop = $false; Set-QualityStale 'error' }
    }
}

# --- Coeur ---------------------------------------------------------------------
function Get-CommonArgs {
    # 12.11 : la liste du bandeau porte l identite du lecteur (le code d une connexion, ou le nom d un lecteur enregistre) ;
    # --drive recoit sa connexion (Get-DriveConn, 112 : un code y rend lui-meme, un nom n atteint jamais gw)
    $a = @("--drive=$(Get-DriveConn ([string]$cmbDrive.Text))")
    if ($txtDev.Text.Trim()) { $a += "--device=$($txtDev.Text.Trim())" }
    return $a
}

function Set-Busy([bool]$busy) {
    # 12.8 (lot 5, D20) : barre alignee sur Get-AppBusy. Pause d une mesure continue de l onglet Qualite (Get-AppBusy
    # 'quality', aucune commande gw) : « Arreter » actif (il arrete la mesure continue) et « Reinitialiser » inactif,
    # comme pendant la mesure ; onglets actifs, comme en 12.7. Entree dans la pause et sortie sans commande gw : le
    # minuteur principal rappelle Set-Busy quand Get-AppBusy ne correspond plus a $script:QualPauseBar
    $loop = (-not $busy) -and (Get-AppBusy) -eq 'quality'
    $script:QualPauseBar = $loop
    $tabs.Enabled = -not $busy
    $btnStop.Enabled = $busy -or $loop
    $btnCfgSave.Enabled = -not $busy -and -not $script:Restore
    $btnCfgReset.Enabled = -not $busy -and -not $script:Restore -and -not $loop
}

function Get-AppBusy([switch]$Text) {
    # 12.8 (D20) : test unique « operation en cours » de toutes les entrees qui lancent gw ou changent un reglage en cours
    # d usage. Renvoie '' au repos, sinon la raison du refus : un code (restore, calib, check, warmup, detect, gw, chain,
    # quality), ou avec -Text son libelle dans la langue de l interface (« commande gw », « calibration »...). Ordre : la
    # raison la plus precise d abord ; quality (mesure continue de l onglet Qualite) seulement quand rien d autre ne tourne.
    $k = ''
    if ($script:Restore) { $k = 'restore' }
    elseif ($script:Cal) { $k = 'calib' }
    elseif ($script:Rep) { $k = 'check' }
    elseif ($script:WriteWarm) { $k = 'warmup' }
    elseif ($script:Detect) { $k = 'detect' }
    elseif ($script:GwProc -and -not $script:GwProc.HasExited) { $k = 'gw' }
    elseif ($script:Chain.Count -gt 0) { $k = 'chain' }
    elseif ($script:AlignLoop) { $k = 'quality' }
    if (-not $Text -or -not $k) { return $k }
    switch ($k) {
        'restore' { return (T 'restauration') }
        'calib'   { return (T 'calibration') }
        'check'   { return (T 'contrôle après écriture') }
        'warmup'  { return (T 'préchauffage du lecteur') }
        'detect'  { return (T 'détection des lecteurs') }
        'gw'      { return (T 'commande gw') }
        'chain'   { return (T 'séquence d''étapes') }
        default   { return (T 'mesure continue de la qualité') }
    }
}

function Get-LogColor([string]$line) {
    if ($line -match '^>>>') { return $script:LogColors.cmd }
    # 12.8 (lot 1c, point 1) : mesures par cylindre d une passe de calibration (« erreur-type », « standard error ») :
    # donnees, jamais une erreur (le journal masque ne s ouvre pas pour elles)
    if ($line -match '^\[[^\]]+\] (Mesures de la passe .+ \(valeur écrite -> |Pass .+ measurements \(written value -> )') { return $script:LogColors.dim }
    # 12.8.1 : mesure de la disquette sur l image : lectures par cylindre d une passe (donnees) ; arrets de gw repris,
    # pistes ecartees (« illisibles »), facteur borne, peu determine ou non mesure : reserves, jamais une erreur
    if ($line -match '^\[[^\]]+\] (Mesure sur l''image, passe |Measurement on the image, pass )') { return $script:LogColors.dim }
    if ($line -match '^Mesure sur l''image : (gw s''est arrêté|nouvel arrêt de gw|arrêt de gw annoncé|pistes écartées)|^Measurement on the image: (gw stop|tracks left out)|^\[[^\]]+\] (Optimum à la borne|Marge peu sensible|Facteur non mesuré|Optimum at the|Margin barely|Factor not measured)') { return $script:LogColors.warn }
    # Lignes de synthese du controle apres ecriture : simples comptes par etat (« 0 critique(s) » n est pas une erreur)
    if ($line -match '^(Contrôle complet|Full check|Remesure après réécriture|Re-measure after rewrite)\b') { return $script:LogColors.std }
    # 12.8 (lot 3a) : lignes de qualite, une couleur par niveau. « erreurs » / « errors » du texte de SUPPORT SAIN et
    # « critique(s) non comptee(s) » d un controle sans piste faible ne les font plus passer en rouge (motifs generaux
    # ci-dessous) : etat du support SAIN / A SURVEILLER / CRITIQUE ; score moyen EXCELLENT ou BON / MOYEN / MAUVAIS ;
    # bilan du controle apres ecriture sans piste faible
    # 12.10 (lot 1, I-5) : verdict neutre du controle (pistes encore faibles apres reecriture) rouge par son propre motif,
    # sans « support fatigue » ; libelles neutres « non distingues » (plafond, besoin, courbe adaptee) en orange, comme
    # les libelles « probablement fatigue » qu ils remplacent
    if ($line -match '^(Mesure : SUPPORT SAIN|Measurement: MEDIA HEALTHY)\b|^(Mesure : score moyen|Measurement: average score) \d+ \((EXCELLENT|BON|GOOD)\)|^(CONTRÔLE APRÈS ÉCRITURE : \d+/\d+ pistes saines|POST-WRITE CHECK: \d+/\d+ healthy tracks)') { return $script:LogColors.ok }
    if ($line -match '^(Mesure : SUPPORT À SURVEILLER|Measurement: MEDIA TO WATCH)\b|^(Mesure : score moyen|Measurement: average score) \d+ \((MOYEN|AVERAGE)\)') { return $script:LogColors.warn }
    if ($line -match '^(Mesure : SUPPORT CRITIQUE|Measurement: MEDIA CRITICAL)\b|^(Mesure : score moyen|Measurement: average score) \d+ \((MAUVAIS|POOR)\)') { return $script:LogColors.err }
    if ($line -match 'FATAL|ERREUR|ERROR|ECHEC|ÉCHEC|FAILED|Command Failed|Write ?Protect|CRITIQUE|CRITICAL|ILLISIBLE|UNREADABLE|introuvable|not found|code retour : [1-9]|exit code: [1-9]|support fatigué|worn media|encore faible\(s\) après|still weak after|réécriture automatique non lancée|automatic rewrite not started|RESTAURATION ÉCHOUÉE|RESTORE FAILED') { return $script:LogColors.err }
    if ($line -match 'Verify Failure|Retry #|nécessité de nouveaux essais|needed retries|À SURVEILLER|TO WATCH|marginal|DIFF[EÉ]RENT|Interrompu|Interrupted|aborted|non applicable|not applicable|réécriture automatique désactivée|automatic rewrite disabled|Aucune réécriture automatique|No automatic rewrite|non convergée|not converged|NON CONVERGÉE|NOT CONVERGED|Valeurs peu fiables|Unreliable values|Écart à la courbe|Deviation from the curve|Giving up|zone instable|unstable zone|non jugée|not judged|probablement fatigué|probably worn|non distingués|not distinguished') { return $script:LogColors.warn }
    if ($line -match 'All tracks verified|code retour : 0|exit code: 0|SAIN|HEALTHY|IDENTIQUE|IDENTICAL|EXCELLENT|aucune piste n|no track needed|RESTAURATION RÉUSSIE|RESTORE SUCCEEDED') { return $script:LogColors.ok }
    if ($line -match '^T\d+\.\d+\b[^:]*:') { return $script:LogColors.dim }
    return $script:LogColors.std
}

function Append-Log([string]$text) {
    foreach ($line in ($text -split "`r?`n")) {
        $c = Get-LogColor $line
        $txtLog.SelectionStart = $txtLog.TextLength; $txtLog.SelectionLength = 0
        $txtLog.SelectionColor = $c
        $txtLog.AppendText($line + "`n")
        if ($c -eq $script:LogColors.err -and $split.Panel2Collapsed) { Set-LogVisible $true }
    }
    # 12.11 : journal borne par Limit-LogText : debut retire a une fin de ligne, marque de troncature en premiere ligne
    # (avant : au-dela de 400 000 caracteres, les 150 000 premiers retires sans trace, une ligne coupee en son milieu)
    Limit-LogText
    $txtLog.SelectionStart = $txtLog.TextLength
    $txtLog.ScrollToCaret()
}

function Show-AppMessage([string]$text, [string]$title, [string]$buttons = 'OK', [string]$icon = 'Information') {
    # 12.7 : boite de message du code nouveau ou modifie depuis la 12.7 : message ecrit dans le journal, puis affiche. Point
    # unique que les fins de test redefinissent (message enregistre sans affichage : aucune boite modale sur le bureau
    # pendant un banc). Renvoie le DialogResult de la boite.
    Append-Log $text
    return [System.Windows.Forms.MessageBox]::Show($text, $title, $buttons, $icon)
}

function Get-SpecCount([string]$spec) {
    $n = 0
    foreach ($part in ($spec -split ',')) {
        if ($part -match '^(\d+)-(\d+)$') { $n += [int]$Matches[2] - [int]$Matches[1] + 1 }
        elseif ($part -match '^\d+$') { $n++ }
    }
    return $n
}

function Start-Progress([string]$verb, [string[]]$gwArgs = $null) {
    $script:ProgOp = $verb; $script:ProgTotal = 0
    $script:ProgSeen = New-Object 'System.Collections.Generic.HashSet[string]'
    # 12.11 : etat de la commande remis a zero (progression par piste) ; une commande suit : etat de fin de sequence en
    # attente annule (calibration puis ecriture, Set-SeqEnd), commande comptee dans la sequence (Update-SeqEnd)
    $script:ProgHead = ''; $script:ProgKey = ''; $script:ProgRetry = ''; $script:ProgDone = 0
    $script:ProgDirty = $false; $script:ProgFailed = $false
    $script:SeqEnd = $null; $script:SeqCmds = 1 + [int]$script:SeqCmds
    # 12.11 : poids de la commande dans le plan de l etape en cours (New-ProgPlan), d apres ses arguments ; second parametre
    # absent (appels a un argument, lecture de prechauffage, detection des lecteurs) : commande hors de tout plan
    $script:ProgCmd = $null
    if ($script:ProgPlan -and $gwArgs -and $gwArgs.Count -gt 0) {
        $pc = Get-GwCmdUnits $gwArgs
        # 12.11 (L11) : commande prevue dont le plan estime les pistes, absentes de ses arguments (New-ProgPlan, $tracks :
        # ecriture d une image sans c= dans --tracks) : poids de l estimation, corrige par l annonce de gw (Update-Progress)
        $pe = if ([int]$script:ProgPlan.Got -lt @($script:ProgPlan.Cmds).Count) { @($script:ProgPlan.Cmds)[[int]$script:ProgPlan.Got] } else { $null }
        if ($pe -and $pe.Est -and [int]$pc.Tracks -le 0 -and [double]$pc.Per -gt 0) { $pc = Get-GwCmdUnits $gwArgs ([int]$pe.Tracks); $pc.Est = $true }
        $script:ProgCmd = $pc; $script:ProgPlan.Got = 1 + [int]$script:ProgPlan.Got
    }
    $stOp.Text = ((T "{0} en cours...") -f "$verb"); $stTrack.Text = ''; $stOp.Image = $script:StIcons.run
    $stBar.Style = 'Marquee'; $stBar.Visible = $true
}

function Update-Progress([string]$line, [switch]$Defer) {
    # Nettoyage des tetes (Start-HeadClean) : « Pass N: ... » a la fin de chaque passe (passes faites) ; une ligne de passe
    # interrompue par « Command Failed » et les autres lignes sont gardees pour le bilan (Complete-HeadClean)
    if ($script:CleanRun) {
        if ($line -match '^Pass (\d+):') {
            $pn = [int]$Matches[1]
            if ($line -notmatch 'Command Failed|FATAL') { $script:CleanRun.Done = [math]::Max([int]$script:CleanRun.Done, $pn + 1); return }
        }
        $script:CleanRun.Lines.Add($line)
        return
    }
    # 12.11 : etat de la commande d apres la seule lecture de la ligne (Get-GwLineInfo), sans toucher a l interface ;
    # affichage par Show-GwProgress : aussitot, ou une fois par lot de lignes avec -Defer (Read-GwOutput). ProgTotal et
    # ProgSeen gardent leur sens (regle de fin d une commande, 600) ; l annonce « Converting » donne aussi un total, que
    # la regle de fin ne compte pas (Get-EndRuleTotal)
    $i = Get-GwLineInfo $line
    if ($null -ne $i) {
        if ($i.Kind -eq 'head') {
            $script:ProgHead = [string]$i.Verb; $script:ProgTotal = [int]$i.Total
            # Commande d un plan dont les arguments ne donnaient pas les pistes (--tracks=h=0, ou pas de --tracks) : poids
            # complete par l annonce de gw, dans la commande et dans le total du plan si elle y etait prevue. 12.11 (L11) :
            # pistes estimees par le plan (Est, Start-Progress) : poids corrige de l ecart entre l annonce et l estimation
            $pc = $script:ProgCmd
            if ($pc -and ([int]$pc.Tracks -le 0 -or $pc.Est) -and [int]$i.Total -gt 0 -and [double]$pc.Per -gt 0) {
                $add = ([int]$i.Total - [int]$pc.Tracks) * [double]$pc.Per
                $pc.Tracks = [int]$i.Total; $pc.Units = [double]$pc.Units + $add; $pc.Est = $false
                if ($script:ProgPlan -and [int]$script:ProgPlan.Got -le @($script:ProgPlan.Cmds).Count) { $script:ProgPlan.Units = [double]$script:ProgPlan.Units + $add }
            }
        } else {
            [void]$script:ProgSeen.Add([string]$i.Key)
            $script:ProgKey = [string]$i.Key; $script:ProgRetry = [string]$i.Retry
            # Pistes terminees : gw read et gw convert impriment la ligne apres la piste, gw write et gw erase avant de
            # l ecrire ou de l effacer (piste commencee, non finie) ; jamais decroissant pendant une commande
            $d = $script:ProgSeen.Count; if ([string]$i.Op -ne 'read') { $d-- }
            if ($d -gt [int]$script:ProgDone) { $script:ProgDone = $d }
        }
        $script:ProgDirty = $true
    }
    if (-not $Defer) { Show-GwProgress }
}

function Stop-Progress([int]$code) {
    $stBar.Style = 'Continuous'
    # 12.11 : fin de la commande. Echec garde pour la fin de sequence (Update-SeqEnd ne remplace pas « ... en echec ») ;
    # poids de la commande credite au plan de l etape : entier avec le code 0, sinon sa part fixe et ses pistes terminees.
    # Second appel pour la detection des lecteurs (600) : plus de poids a crediter
    $script:ProgFailed = ($code -ne 0)
    $pc = $script:ProgCmd; $script:ProgCmd = $null
    if ($pc -and $script:ProgPlan) {
        $u = [double]$pc.Fixed + (Get-GwProgress).Done * [double]$pc.Per
        if ($code -eq 0 -and $u -lt [double]$pc.Units) { $u = [double]$pc.Units }
        $script:ProgPlan.Done = [double]$script:ProgPlan.Done + $u
    }
    if ($code -eq 0) {
        # 12.11 : commande terminee, la derniere piste vue est finie : pistes terminees = pistes vues (« (82/82, 100 %) »
        # apres une ecriture ou un effacement complets ; image plus courte que l annonce : compte reel, barre pleine)
        if ($script:ProgSeen -and $script:ProgSeen.Count -gt [int]$script:ProgDone) { $script:ProgDone = $script:ProgSeen.Count; $script:ProgDirty = $true }
        Show-GwProgress
        if ($script:ProgTotal -gt 0) { $stBar.Value = $stBar.Maximum }
        $stOp.Text = ((T "{0} terminé(e)  -  {1}") -f "$($script:ProgOp)", "$(Get-Date -Format 'HH:mm:ss')"); $stOp.Image = $script:StIcons.ok
    } else {
        $stOp.Text = ((T "{0} en échec (code {1})  -  {2}") -f "$($script:ProgOp)", "$code", "$(Get-Date -Format 'HH:mm:ss')"); $stOp.Image = $script:StIcons.err
    }
    $stBar.Visible = ($code -eq 0 -and $script:ProgTotal -gt 0)
}

function Reset-GwSequence {
    # gw n a pas pu etre lance : la sequence en cours (ecriture controlee, calibration, comparaison)
    # est abandonnee, sinon le prochain gw termine avec le code 0 reprendrait ses etapes, ecritures comprises.
    $script:Chain.Clear(); $script:WriteQueue.Clear(); $script:Detect = $null
    Stop-WriteWarmup
    if ($script:Rep) { Stop-WriteCheck }
    if ($script:Cal) { Stop-PrecompCalib -GwError }       # 12.8 (VAL01) : passe du nouvel essai : jugement garde
    if ($txtCmpResult.Text -like ((T 'Comparaison en cours') + '*')) { $txtCmpResult.Text = ((T "ÉCHEC : {0}") -f (T 'gw n''a pas pu être lancé.')) }
    if ($script:Restore) { Stop-Restore (T 'gw n''a pas pu être lancé') }
    # 12.8 (lot 3a) : mesure de qualite sans lecture : erreur gw, resultat affiche perime
    if ($script:QualView.State -eq 'run' -and $script:QualView.Kind -eq 'measure') { $script:AlignLoop = $false; $script:AlignNextAt = $null; Set-QualityStale 'gwerror' }
}

function Start-DriveDetect([string]$mode) {
    if (-not (Test-Path -LiteralPath $script:GwExe)) { return }
    if (Get-AppBusy) { return }                           # 12.8 (D20) : aussi pendant un prechauffage ou la mesure continue
    $script:DetectAt = $null
    $cur = Get-DriveConn ([string]$cmbDrive.Text)         # 12.11 : la detection sonde des connexions (celle du lecteur du bandeau d abord)
    $order = @(@($cur) + @($script:DriveIds | Where-Object { $_ -ne $cur }) | Where-Object { $_ })
    if ($mode -eq 'auto' -and $script:DetectNone) {
        $order = @($cur)
        Append-Log ((T "Détection des lecteurs : aucun lecteur au dernier démarrage, seul le lecteur {0} est testé (carte « Tester le Greaseweazle » de l'Accueil : tous les lecteurs).") -f "$cur")
    }
    $script:Detect = @{ Mode = $mode; Queue = (New-Object System.Collections.Queue); Found = @(); Tried = @(); Cur = $cur; Drive = '' }
    foreach ($d in $order) { $script:Detect.Queue.Enqueue($d) }
    Append-Log ((T "Détection des lecteurs : recherche de la piste 0 sur {0} (gw seek : la tête se déplace, sans rotation ni écriture).") -f "$($order -join ', ')")
    Invoke-DriveProbe
}

function Invoke-DriveProbe {
    $dt = $script:Detect
    if (-not $dt) { return }
    if ($dt.Queue.Count -eq 0) { Complete-DriveDetect; return }
    $d = [string]$dt.Queue.Dequeue(); $dt.Drive = $d; $dt.Tried += $d
    $script:GwCapture = New-Object System.Collections.Generic.List[string]
    $a = @('seek', "--drive=$d")
    if ($txtDev.Text.Trim()) { $a += "--device=$($txtDev.Text.Trim())" }
    $a += '0'
    Start-Gw $a
}

function Complete-DriveProbe([int]$code) {
    # Fin d un gw seek de la detection (appele par le timer, quel que soit le code retour)
    $dt = $script:Detect
    if (-not $dt) { return }
    $lines = @(); if ($script:GwCapture) { $lines = @($script:GwCapture) }
    $script:GwCapture = $null
    $txt = $lines -join "`n"
    if ($code -eq 0 -and $txt -notmatch 'Command Failed|FATAL|Track ?0') {
        $dt.Found += $dt.Drive
        if ($dt.Mode -eq 'auto') { Complete-DriveDetect; return }
    } elseif ($txt -match 'Invalid unit number') {
        # Firmware ACK_BAD_UNIT : ligne de selection non cablee sur cette carte (V4 Slim, F7 Slim, F1 de base, F7 v1)
        Append-Log ((T "Lecteur {0} : non pris en charge par cette carte (ligne de sélection absente).") -f "$($dt.Drive)")
    } elseif ($txt -notmatch 'Track 0 not found|Track0 signal') {
        # Erreur sans rapport avec le lecteur (carte absente, port occupe...) : detection abandonnee, cause en clair
        $why = (@($lines | Where-Object { $_.Trim() } | Select-Object -Last 2) -join ' / ') -replace 'FATAL ERROR:?|Command Failed:?', '' -replace '\*', ''
        Append-Log ((T "Détection des lecteurs interrompue : {0}") -f "$($why.Trim())")
        if ($dt.Found.Count -gt 0) { Complete-DriveDetect } else { $script:Detect = $null }
        return
    }
    Invoke-DriveProbe
}

function Complete-DriveDetect {
    $dt = $script:Detect; $script:Detect = $null
    if (-not $dt) { return }
    # 12.11 : barre d etat apres la recherche des lecteurs : « Pret. », sans heure (avant : « gw seek termine(e) »)
    Set-SeqEnd (T 'Prêt.') 'idle' -NoTime
    $script:DetectNone = ($dt.Found.Count -eq 0)
    # A et 2 (broche 14), B et 1 (broche 12) partagent une ligne de selection : gw seek, sans moteur, ne les distingue
    # pas. Une seule entree par paire : A ou B, sauf si 2 ou 1 etait deja le reglage ; l identifiant prefere qui a ete
    # sonde sans repondre cede la place a celui de la paire qui a repondu
    $found = @($dt.Found)
    foreach ($pp in @(@('A', '2'), @('B', '1'))) {
        if (-not (($found -contains $pp[0]) -or ($found -contains $pp[1]))) { continue }
        $keepId = if ($dt.Cur -eq $pp[1]) { $pp[1] } else { $pp[0] }
        $other = if ($keepId -eq $pp[0]) { $pp[1] } else { $pp[0] }
        if ($found -notcontains $keepId -and @($dt.Tried) -contains $keepId) { $sw = $keepId; $keepId = $other; $other = $sw }
        $found = @($found | Where-Object { $_ -ne $other })
        if ($found -notcontains $keepId) { $found += $keepId }
        if ($dt.Mode -ne 'auto') { Append-Log ((T "{0} et {1} utilisent la même ligne de sélection : la détection ne peut pas les distinguer (A ou B : nappe PC avec twist ; 0 à 3 : nappe droite).") -f $pp[0], $pp[1]) }
    }
    $dt.Found = $found
    if ($dt.Found.Count -eq 0) {
        Append-Log (T "Aucun lecteur détecté : vérifiez l'alimentation du lecteur, la nappe et son sens, puis le type de nappe (A ou B : nappe PC avec twist ; 0 à 3 : nappe droite).")
        return
    }
    $pick = if ($dt.Found -contains $dt.Cur) { $dt.Cur } else { [string]$dt.Found[0] }
    if ($dt.Mode -ne 'auto') { Append-Log ((T "Lecteur(s) détecté(s) : {0}.") -f "$($dt.Found -join ', ')") }
    if ($pick -ne $dt.Cur) {
        # 12.8 (D10) : la restauration suit le lecteur du bandeau, sans reglage propre a recaler
        # 12.11 (lot LN-b) : avec des lecteurs enregistres, le lecteur retenu pour la connexion qui repond, le dernier choisi
        # sur elle (Get-DriveForConn, 112) : la detection ne reconnait pas le lecteur branche, une ligne le dit
        $pickD = $pick
        if ($script:DriveReg.Count -gt 0) { $pickD = Get-DriveForConn $pick }
        Set-Combo $cmbDrive $pickD
        Append-Log ((T "Lecteur {0} sélectionné : le lecteur {1} ne répond pas.") -f "$pick", "$($dt.Cur)")
        if ($pickD -cne $pick) { Append-Log ((T 'Connexion {0} : lecteur retenu « {1} », le dernier choisi sur cette connexion. La détection ne reconnaît pas le lecteur branché : vérifiez la liste « Lecteur : » du bandeau.') -f "$pick", "$pickD") }
    } else { Append-Log ((T "Lecteur {0} détecté.") -f "$pick") }
}

function Get-GwDriveKey([string[]]$gwArgs) {
    # Lecteur d une commande gw qui fait tourner le moteur (read, write, erase, clean, rpm) : 'peripherique|lecteur' ;
    # $null pour les autres commandes (seek, info...) ou sans --drive
    $line = ' ' + (($gwArgs | Where-Object { $null -ne $_ }) -join ' ')
    $verb = @($line.Trim() -split '\s+')[0]
    if (@('read', 'write', 'erase', 'clean', 'rpm') -notcontains $verb) { return $null }
    if ($line -notmatch '\s--drive=(\S+)') { return $null }
    $drv = $Matches[1]
    $dev = if ($line -match '\s--device=(\S+)') { $Matches[1] } else { '' }
    return "$dev|$drv"
}

function Start-Gw([string[]]$gwArgs, [switch]$Soft) {
    # Soft : lecture de prechauffage d une ecriture lente (Invoke-WriteWarmup), marquee par appel
    $exe = $script:GwExe
    if (-not (Test-Path -LiteralPath $exe)) {
        Reset-GwSequence
        [void](Show-AppMessage ((T "gw.exe introuvable : {0}`n`nPlacez ce script dans le même répertoire que gw.exe.") -f "$exe") (T 'Erreur') 'OK' 'Error'); return
    }
    if ($script:GwProc -and -not $script:GwProc.HasExited) {
        Append-Log ((T "gw déjà en cours : commande ignorée ({0}).") -f "$($gwArgs -join ' ')")
        if ($script:Chain.Count -gt 0 -or $script:Rep -or $script:Cal -or $script:WriteWarm) { Reset-GwSequence }
        return
    }

    # 12.10 (lot 1, R1-corrections-revue, constat d) : premier gw write de l image d une operation de la Bibliotheque
    # (Set-LibImageWritten) : pose avant Save-Config (configuration de la fin de l operation, E9-3), retire si gw ne demarre pas
    $libWr = Set-LibImageWritten $gwArgs
    if (-not $script:Restore -and -not $script:Detect) { [void](Save-Config) }      # restauration : reglages temporaires ; detection : pas d ecriture a chaque sonde

    $script:GwIsWrite = ($gwArgs.Count -gt 0 -and $gwArgs[0] -eq 'write')
    $verbs = @{ write=(T 'Écriture'); read=(T 'Lecture'); erase=(T 'Effacement'); convert='Conversion'; clean=(T 'Nettoyage'); rpm=(T 'Mesure de vitesse'); update=(T 'Mise à jour firmware') }
    $first = if ($gwArgs.Count -gt 0) { ($gwArgs[0] -split ' ')[0] } else { '' }
    # Lecture de prechauffage (calibration : etape 'warmup' ; ecriture lente : -Soft) : son code retour n arrete pas la
    # sequence ; lecteur de la commande pour DriveActivity (serie d activite mise a jour par le minuteur a la fin de la
    # commande, seulement si le moteur a tourne). Nom distinct du parametre Soft (PowerShell ignore la casse).
    $warmRead = [bool]([bool]$Soft -or ($script:Cal -and $script:Cal.Stage -eq 'warmup' -and $first -eq 'read'))
    # 12.11 : arguments transmis a la progression (poids de la commande dans le plan de l etape, New-ProgPlan), sauf pour
    # une lecture de prechauffage et pour la detection des lecteurs, qui n entrent dans aucun plan
    Start-Progress $(if ($warmRead) { (T 'Préchauffage') } elseif ($verbs.ContainsKey($first)) { $verbs[$first] } else { "gw $first" }) $(if ($warmRead -or $script:Detect) { $null } else { $gwArgs })
    # 12.8.1 (spec-1281.md § A.7) : arret « Failed to verify Track C.H » de la commande, pose par Read-GwOutput (ecriture)
    $script:GwVerifyFail = $null
    if ($script:GwIsWrite) { $script:WriteRetries = @{}; $script:WriteTracks = @{} }
    $script:GwWriteSummary = $false
    # Revue 12.8.2 : gw erase 1.23 intercepte l erreur du Greaseweazle, imprime « Command Failed: ... » et rend le code 0
    # (tools/erase.py) : drapeau pose par Read-GwOutput, lu par la regle de fin (Get-GwEndRule : commande incomplete)
    $script:GwIsErase = ($first -eq 'erase'); $script:GwCmdFailed = $false
    $driveKey = if ($script:Detect) { $null } else { Get-GwDriveKey $gwArgs }
    if ($chkTime.Checked) { $gwArgs = @('--time') + $gwArgs }
    $argLine = $gwArgs -join ' '
    if (-not $script:Detect) { Append-Log ">>> gw $argLine" }
    $script:GwStart = Get-Date; $script:GwLines = 0

    # gw.exe est appele directement (aucun cmd.exe intermediaire) ; sa sortie est redirigee
    # dans le processus et lue par des gestionnaires d'evenements qui remplissent une file
    # thread-safe, videe par le timer de l'interface. Pas de fichier temporaire.
    $script:OutPending = ''
    $script:OutQueue = [System.Collections.Queue]::Synchronized((New-Object System.Collections.Queue))

    $psi = New-Object System.Diagnostics.ProcessStartInfo
    $psi.FileName  = $exe
    $psi.Arguments = $argLine
    $psi.WorkingDirectory       = $script:AppDir
    $psi.UseShellExecute        = $false
    $psi.CreateNoWindow         = $true
    $psi.RedirectStandardOutput = $true
    $psi.RedirectStandardError  = $true
    $psi.StandardOutputEncoding = [System.Text.Encoding]::UTF8
    $psi.StandardErrorEncoding  = [System.Text.Encoding]::UTF8
    $psi.EnvironmentVariables['PYTHONUNBUFFERED'] = '1'
    $psi.EnvironmentVariables['PYTHONIOENCODING'] = 'utf-8'

    $p = New-Object System.Diagnostics.Process
    $p.StartInfo = $psi

    # 12.11 : lancement en trois temps. Jusqu a la 12.10, un seul try couvrait Process.Start et la suite du demarrage :
    # une exception apres le demarrage (flux, Set-Busy, onglet Qualite) passait pour un echec du lancement, et gw
    # tournait sans suivi (sortie non lue, fin non traitee, « Arreter » sans effet, autre commande possible).
    # Temps 1 : Process.Start seul ; son echec est le seul cas « gw n a pas pu etre lance »
    try {
        [void]$p.Start()
    } catch {
        Append-Log ((T "ERREUR lancement : {0}") -f "$($_.Exception.Message)")
        if ($libWr -and $script:OpOverride) { $script:OpOverride.Written = $false }
        $script:GwProc = $null; $script:GwSoft = $false; $script:GwDriveKey = $null
        Reset-GwSequence
        Set-GwLaunchFailedStatus
        Set-Busy $false
        return
    }
    # 12.11 (temps 2) : gw tourne ; suivi du processus pose aussitot, hors de tout try : Start-Gw ne le defait plus
    $script:GwProc = $p
    $script:GwSoft = $warmRead; $script:GwDriveKey = $driveKey
    # 12.11 (temps 3) : suite du demarrage. Une exception ici n est pas un echec du lancement : une ligne au journal,
    # sans toucher au suivi, a la sequence en cours ni a la barre d etat (« ... en cours... »). Le minuteur suit la
    # commande jusqu a sa fin et applique sa regle de fin, « Arreter » l interrompt, Get-AppBusy refuse toute autre
    # operation. Si les flux ont echoue, la sortie de gw n est pas lue (Drain-GwReader accepte une tache nulle)
    try {
        # Lecture asynchrone des deux flux : chaque ReadLineAsync rend une Task que le timer
        # inspecte sans bloquer l'interface. Pas de bloc -Action (inactif sous ShowDialog).
        $script:OutStdoutReader = $p.StandardOutput
        $script:OutStderrReader = $p.StandardError
        $script:OutStdoutTask = $script:OutStdoutReader.ReadLineAsync()
        $script:OutStderrTask = $script:OutStderrReader.ReadLineAsync()
        Set-Busy $true
        # 12.8 (lot 3a) : disquette ecrite ou effacee hors d un controle apres ecriture (calibration, ecriture sans controle,
        # effacement) : le resultat de l onglet Qualite ne la decrit plus
        # 12.8 (FIX3) : verdict du controle precedent (onglet Ecriture) masque
        if (($first -eq 'write' -or $first -eq 'erase') -and -not $script:Rep) { Set-QualityStale 'written'; Hide-WCalVerdict }
    } catch {
        Append-Log ((T "gw est lancé, mais une erreur a suivi son démarrage : {0}. La commande reste suivie jusqu'à sa fin ; « Arrêter » l'interrompt.") -f "$($_.Exception.Message)")
        try { Set-Busy $true } catch { }
        try { $btnStop.Enabled = $true } catch { }   # 12.11 : « Arreter » actif meme si Set-Busy a leve avant de l activer (sa deuxieme instruction)
    }
}

function Set-GwLaunchFailedStatus {
    # 12.10 (relecture de la RC10) : gw.exe n a pas pu etre lance (Process.Start en echec, apres Start-Progress) : barre
    # d etat de l echec, comme Stop-Progress pour un code non nul, au lieu de « … en cours... » avec l icone run et la barre
    # animee. Appelee apres Reset-GwSequence (fin de la sequence, dont Close-Restore) : la cause est au journal
    $stOp.Text = ((T "{0} : gw n'a pas pu être lancé, voir le journal  -  {1}") -f "$($script:ProgOp)", "$(Get-Date -Format 'HH:mm:ss')"); $stOp.Image = $script:StIcons.err
    $stTrack.Text = ''; $stBar.Style = 'Continuous'; $stBar.Visible = $false
    # 12.11 : etat d echec : l etat de fin de sequence pose par Reset-GwSequence (restauration, calibration, controle) est
    # annule, et Update-SeqEnd ne remplace pas cet affichage, qui dit la cause
    $script:SeqEnd = $null; $script:ProgFailed = $true; $script:ProgCmd = $null
}

function Drain-GwReader($reader, [ref]$task) {
    # Vide les lignes disponibles d'un flux ; relance une tache tant qu'elle se complete tout de suite.
    if (-not $reader -or $null -eq $task.Value) { return }
    while ($task.Value.IsCompleted) {
        $line = $null
        try { $line = $task.Value.Result } catch { $task.Value = $null; return }
        if ($null -eq $line) { $task.Value = $null; return }   # fin de flux
        if ($line -ne '') { $script:OutQueue.Enqueue($line) }
        $task.Value = $reader.ReadLineAsync()
    }
}

function Read-GwOutput([bool]$flush) {
    if (-not $script:OutQueue) { return }
    if ($flush) {
        # Processus termine : attendre la fin de flux (EOF) de stdout puis stderr, sinon les dernieres
        # lignes (dont un eventuel message d erreur de gw) restent dans le tube et sont perdues.
        $deadline = (Get-Date).AddSeconds(5)
        foreach ($which in 'out', 'err') {
            while ((Get-Date) -lt $deadline) {
                $t = if ($which -eq 'out') { $script:OutStdoutTask } else { $script:OutStderrTask }
                if ($null -eq $t) { break }
                try { [void]$t.Wait(500) } catch { break }
                if (-not $t.IsCompleted) { continue }
                if ($which -eq 'out') { Drain-GwReader $script:OutStdoutReader ([ref]$script:OutStdoutTask) }
                else                  { Drain-GwReader $script:OutStderrReader ([ref]$script:OutStderrTask) }
            }
        }
    }
    Drain-GwReader $script:OutStdoutReader ([ref]$script:OutStdoutTask)
    Drain-GwReader $script:OutStderrReader ([ref]$script:OutStderrTask)
    $lines = @()
    while ($script:OutQueue.Count -gt 0) {
        $l = [string]$script:OutQueue.Dequeue()
        if ($l -ne '') { $lines += $l }
    }
    if ($lines.Count -eq 0) { return }
    $script:GwLines += $lines.Count
    # 12.11 : etat de la progression mis a jour ligne par ligne, barre d etat peinte une seule fois pour le lot
    foreach ($l in $lines) { Update-Progress $l -Defer }
    Show-GwProgress
    if ($null -ne $script:GwCapture) { foreach ($l in $lines) { $script:GwCapture.Add($l) } }
    if ($script:Detect) { return }                      # detection des lecteurs : sortie analysee, pas affichee
    if ($script:GwIsWrite) {
        foreach ($l in $lines) {
            if ($l -match '^T(\d+)\.(\d+)\b[^:]*:.*Retry #(\d+)') {
                $k = "$($Matches[1]).$($Matches[2])"; $n = [int]$Matches[3]
                if (-not $script:WriteRetries.ContainsKey($k) -or $n -gt $script:WriteRetries[$k]) { $script:WriteRetries[$k] = $n }
            }
            if ($l -match '^T(\d+)\.(\d+)\b[^:]*: Writing Track') {
                $script:WriteTracks["$($Matches[1]).$($Matches[2])"] = $true
                if ($script:EraseLog) { $script:EraseLog.Written["$($Matches[1]).$($Matches[2])"] = $true }   # 12.8.2 (Start-ImageWrite, 170)
            }
            if ($l -match '^(All tracks verified|No tracks verified|\d+ tracks verified)') { $script:GwWriteSummary = $true }
        }
        # 12.8.1 (A.7) : gw 1.23 arrete la commande sur une piste refusee a la verification apres les nouveaux essais
        # (« ** FATAL ERROR: » puis « Failed to verify Track C.H », sur stderr) : premiere occurrence gardee, lue par la
        # mesure sur l image (Invoke-ContentWriteNext) et par la regle douce du minuteur principal (600)
        $vs = Get-GwVerifyStop $lines
        if ($vs -and -not $script:GwVerifyFail) { $script:GwVerifyFail = $vs }
    }
    if ($script:GwIsErase) {
        # Revue 12.8.2 : gw erase imprime « Tc.h: Erasing Track » avant d effacer chaque piste (pistes logiques, comme
        # « Writing Track ») : pistes touchees par l effacement de l operation en cours (EraseLog) ; « Command Failed » :
        # echec avec le code 0
        foreach ($l in $lines) {
            if ($l -match '^Command Failed') { $script:GwCmdFailed = $true }
            elseif ($script:EraseLog -and $l -match '^T(\d+)\.(\d+)\b[^:]*: Erasing Track') { $script:EraseLog.Erased["$($Matches[1]).$($Matches[2])"] = $true }
        }
    }
    if ($lines.Count -gt 0) { Append-Log ($lines -join [Environment]::NewLine) }
}

function Get-GwEndRule([int]$code, [bool]$soft, [bool]$isWrite, [bool]$summary, [int]$progTotal, [int]$progSeen, $verifyFail, [string]$calMode, [bool]$cmdFailed = $false) {
    # Regle de fin d une commande gw (minuteur principal, 600), sans etat : arguments releves par le minuteur apres le
    # dernier Read-GwOutput. Soft : lecture de prechauffage ($soft), ou 12.8.1 (spec-1281.md § A.7) ecriture de la mesure
    # sur l image ($calMode 'content') arretee sur une piste refusee a la verification ($verifyFail, Read-GwOutput), quel
    # que soit le code retour (1 en gw 1.23 ; 0 admis : revue 12.8.1, point 1). Incomplete : arret silencieux avec le code 0
    # (ecriture sans ligne de bilan ; autre commande : moins de la moitie des pistes annoncees), sans effet si Soft.
    # Next : etape suivante de la chaine (code 0 ou Soft). Revue 12.8.2 : $cmdFailed, gw erase arrete par « Command
    # Failed » avec le code 0 (Read-GwOutput) : incomplete quel que soit le nombre de pistes vues (effacement d une ou deux
    # pistes, ou echec sur la derniere) ; l ecriture qui suit n est pas lancee
    if (-not $soft -and $isWrite -and $verifyFail -and $calMode -eq 'content') { $soft = $true }
    $inc = if ($isWrite) { $code -eq 0 -and -not $summary } else { $code -eq 0 -and (($progTotal -gt 0 -and $progSeen * 2 -lt $progTotal) -or $cmdFailed) }
    return @{ Soft = $soft; Incomplete = [bool]$inc; Next = ($code -eq 0 -or $soft) }
}

# --- Journal : borne et export (12.11) -----------------------------------------

function Limit-LogText {
    # 12.11 : journal borne a $script:LogMaxChars caracteres (400 000, 540), appelee par Append-Log apres chaque ajout.
    # Au-dela, le debut est retire pour n en garder que $script:LogKeepChars (250 000 : les 150 000 premiers caracteres au
    # premier depassement, comme avant), mais la coupe est ramenee au debut d une ligne (derniere fin de ligne de la partie
    # retiree ; sans fin de ligne dans cette partie : coupe au caractere) et une marque, premiere ligne du journal, dit
    # combien de caracteres ont ete retires. Depassements suivants : la marque en place est retiree avec le debut sans etre
    # comptee, et son compte est cumule ($script:LogCut : N caracteres retires, Mark marque en place) ; si elle n est plus
    # en tete (journal vide par « Vider »), le compte repart de zero. Seule fonction qui ecrit la marque
    $max = [int]$script:LogMaxChars
    if ($txtLog.TextLength -le $max) { return }
    $t = [string]$txtLog.Text
    $st = $script:LogCut
    $old = 0
    if ($st.Mark -and $t.StartsWith([string]$st.Mark + "`n", [System.StringComparison]::Ordinal)) { $old = ([string]$st.Mark).Length + 1 } else { $st.N = 0 }
    $cut = [math]::Max($old, $t.Length - [int]$script:LogKeepChars)
    # Debut de ligne : derniere fin de ligne de la partie retiree, marque precedente exclue ; ecartee si le journal garde
    # depassait alors la borne, marque comprise (ligne de plus de 150 000 caracteres) : coupe au caractere
    $p = $t.LastIndexOf([char]10, $cut - 1)
    if ($p + 1 -gt $old -and ($t.Length - $p - 1) -le ($max - 1000)) { $cut = $p + 1 }
    $st.N = [int]$st.N + ($cut - $old)
    $st.Mark = (T "[Journal tronqué : les {0} premiers caractères ont été retirés (400 000 au plus sont gardés). Exportez le journal après chaque opération longue.]") -f "$($st.N)"
    $txtLog.ReadOnly = $false
    $txtLog.Select(0, $cut); $txtLog.SelectedText = ''
    $txtLog.Select(0, 0); $txtLog.SelectionColor = $script:LogColors.warn; $txtLog.SelectedText = [string]$st.Mark + "`n"
    $txtLog.ReadOnly = $true
}

function Get-LogExportHeader([datetime]$when = (Get-Date)) {
    # 12.11 : en-tete du journal exporte (Export-LogFile), deux lignes ecrites en tete du fichier seulement, jamais dans le
    # journal affiche : date de l export et versions (application, calcul de calibration, mesure sur l image), puis lecteur
    # du bandeau et lecteur cible de ses ecritures (Get-TargetDrive, 140 ; « (meme lecteur) » sans lecteur cible). Apres
    # « Vider », la ligne de version du demarrage n est plus dans le journal : l en-tete la remplace. Ni chemin, ni nom de
    # compte, ni nom de poste. Tableau protege par la virgule (pas de @() autour de l appel). Date en culture invariante :
    # « / » et « : » d un format .NET sont sinon les separateurs de la culture du poste (13.11.2026 en de-DE, 14.05.09 en
    # fi-FI) ; la ligne s ecrit de la meme facon sur tout poste
    $tgt = Get-TargetDrive
    $src = "$($cmbDrive.Text)"
    # 12.11 (lot LN-b) : avec des lecteurs enregistres, les deux lecteurs avec leur connexion (Get-DriveLabel, 112 :
    # « Sony MPF920 (A) ») : deux journaux faits sur A avec deux lecteurs n ont pas le meme en-tete
    if ($script:DriveReg.Count -gt 0) { $src = Get-DriveLabel $src; if ($tgt) { $tgt = Get-DriveLabel $tgt } }
    $l1 = (T "Journal exporté le {0} par Greaseweazle Studio v{1} ; calcul de calibration v{2}, mesure sur l'image v{3}.") -f $when.ToString('dd/MM/yyyy HH:mm:ss', [System.Globalization.CultureInfo]::InvariantCulture), "$($script:Version)", "$($script:CalibCalc)", "$($script:ContentCalc)"
    $l2 = (T "Lecteur du bandeau : {0} ; lecteur cible de ses écritures : {1}.") -f $src, $(if ($tgt) { $tgt } else { (T '(même lecteur)') })
    return ,@($l1, $l2)
}

function Export-LogFile([string]$path) {
    # 12.11 : export du journal (bouton « Exporter », 540) : les deux lignes de Get-LogExportHeader, puis le texte du
    # journal tel qu il est affiche (marque de troncature comprise, Limit-LogText), avec ses fins de ligne ; codage
    # inchange (Set-Content -Encoding UTF8)
    (((Get-LogExportHeader) -join "`n") + "`n" + $txtLog.Text) | Set-Content -LiteralPath $path -Encoding UTF8
}

# --- Progression par piste : ligne de gw, commande, plan d une etape, fin de sequence (12.11) ---
# Une source, trois niveaux. La ligne : Get-GwLineInfo, seule lecture d une ligne de gw pour la progression. La commande :
# Update-Progress tient l etat (040), Show-GwProgress le peint dans la barre d etat. Le plan : une etape de plusieurs
# commandes (passe de calibration, conditionnement, passe de la mesure sur l image) declare ses commandes par New-ProgPlan ;
# Get-ProgPlanFrac rend son avancement d apres les pistes annoncees par gw, lu par Update-CalibProgress (270) a la place
# du temps ecoule. Affichage seulement : rien ici ne lance, n arrete ni ne juge une operation.

function Get-GwLineInfo([string]$line) {
    # Lecture d une ligne de gw 1.23, sans etat ni interface. $null : ligne sans effet sur la progression. Annonce du jeu
    # de pistes : @{ Kind = 'head' ; Verb = Reading, Writing, Erasing ou Converting ; Total = pistes annoncees }. Ligne de
    # piste « Tc.h...: » : @{ Kind = 'track' ; Key = 'c.h' ; Op = 'erase' (« Erasing Track »), 'write' (« Writing Track »)
    # ou 'read' (toute autre : lecture, conversion, piste sautee) ; Retry = numero d essai, ou '' }. Premier caractere
    # teste avant toute expression ; memes expressions que la 12.10, plus « Converting ». Piste renumerotee (« T1.0 ->
    # Drive 2.0: ») : cle de la piste de l image
    if ($line.Length -lt 5) { return $null }
    $c = $line[0]
    if ($c -ceq 'T') {
        if ($line -notmatch '^T(\d+)\.(\d+)\b[^:]*: ?(Erasing Track|Writing Track)?') { return $null }
        $key = $Matches[1] + '.' + $Matches[2]
        $op = if ($Matches[3] -ceq 'Erasing Track') { 'erase' } elseif ($Matches[3]) { 'write' } else { 'read' }
        $retry = ''
        if ($line.IndexOf('Retry #') -ge 0 -and $line -match 'Retry #(\d+)(?:\.(\d+))?') { $retry = [string]$(if ($Matches[2]) { $Matches[2] } else { $Matches[1] }) }
        return @{ Kind = 'track'; Key = $key; Op = $op; Retry = $retry }
    }
    if ($c -ceq 'R' -or $c -ceq 'W' -or $c -ceq 'E' -or $c -ceq 'C') {
        if ($line -match '^(Reading|Writing|Erasing|Converting)\s+c=([\d,\-]+):h=([\d,\-]+)') {
            return @{ Kind = 'head'; Verb = [string]$Matches[1]; Total = ((Get-SpecCount $Matches[2]) * (Get-SpecCount $Matches[3])) }
        }
    }
    return $null
}

function Get-GwProgress {
    # Etat de la commande gw en cours, ou de la derniere : @{ Known (total annonce par gw) ; Total ; Seen (pistes
    # distinctes vues) ; Done (pistes terminees, au plus le total annonce) ; Key (derniere piste vue) ; Retry (numero
    # d essai, ou '') }. Pour l affichage seulement : la regle de fin d une commande lit ProgTotal et ProgSeen (600)
    $t = [int]$script:ProgTotal
    $d = [int]$script:ProgDone
    if ($t -gt 0 -and $d -gt $t) { $d = $t }
    return @{ Known = ($t -gt 0); Total = $t; Seen = $(if ($script:ProgSeen) { [int]$script:ProgSeen.Count } else { 0 }); Done = $d; Key = [string]$script:ProgKey; Retry = [string]$script:ProgRetry }
}

function Show-GwProgress {
    # Peint la barre et le compteur de la barre d etat d apres l etat de la commande, seulement s il a change (ProgDirty) :
    # une fois par lot de lignes de gw, et non a chaque ligne. Compteur « piste {0}  ({1}/{2}, {3} %) » : {0} piste en
    # cours, {1} et {3} pistes terminees (une ecriture ou un effacement n affiche plus 100 % pendant sa derniere piste).
    # Plus de pistes vues qu annoncees : barre et compteur restent au total annonce, la piste en cours continue de
    # s afficher. Sans annonce reconnue : barre animee, « piste {0} » seul, comme en 12.10
    if (-not $script:ProgDirty) { return }
    $script:ProgDirty = $false
    $g = Get-GwProgress
    if ($g.Known) {
        if ([string]$stBar.Style -ne 'Continuous' -or $stBar.Maximum -ne $g.Total) { $stBar.Style = 'Continuous'; $stBar.Minimum = 0; $stBar.Maximum = $g.Total }
        if ($stBar.Value -ne $g.Done) { $stBar.Value = $g.Done }
    }
    if (-not $g.Key) { return }
    $txt = if ($g.Known) { (T "piste {0}  ({1}/{2}, {3} %)") -f "$($g.Key)", "$($g.Done)", "$($g.Total)", "$([math]::Round(100 * $g.Done / $g.Total, 0))" }
           else { (T "piste {0}") -f "$($g.Key)" }
    if ($g.Retry) { $txt += ((T "  -  essai {0}") -f "$($g.Retry)") }
    if ([string]$stTrack.Text -ne $txt) { $stTrack.Text = $txt }
}

function Get-EndRuleTotal {
    # Total des pistes annoncees que le minuteur principal (600) passe a la regle de fin d une commande (Get-GwEndRule :
    # « moins de la moitie des pistes annoncees » = operation incomplete). 0 pour gw convert : son annonce donne depuis
    # la 12.11 un total a la barre d etat, mais une image peut porter moins de pistes que le jeu annonce ; la regle reste
    # celle de la 12.10, ou ce total n etait pas lu. Autres commandes : $script:ProgTotal, inchange
    if ([string]$script:ProgHead -ceq 'Converting') { return 0 }
    return [int]$script:ProgTotal
}

function Get-GwCmdUnits([string[]]$gwArgs, [int]$tracks = -1) {
    # Poids estime d une commande gw dans le plan d une etape, d apres ses arguments (tableau, ou une seule chaine) :
    # @{ Fixed ; Per ; Tracks ; Units }, Units = Fixed + Tracks x Per, en secondes estimees ($script:ProgCost, 040 :
    # proportions relevees sur les lecteurs d un seul utilisateur, jamais affichees comme des durees). Par piste :
    # effacement ; ecriture, plus le pre-effacement (--pre-erase), plus la verification (sans --no-verify) ; relecture selon
    # --revs. Pistes : c= et h= de --tracks (Get-SpecCount), 0 si elles ne s y lisent pas (l annonce de gw complete alors
    # le poids, Update-Progress) ; $tracks >= 0 : nombre impose. Autre commande (clean, rpm, seek, info...) : poids nul
    $c = $script:ProgCost
    $line = ' ' + ((@($gwArgs) | Where-Object { $null -ne $_ }) -join ' ') + ' '
    $verb = ''
    foreach ($t in @($line.Trim() -split '\s+')) { if ($t -and -not $t.StartsWith('--')) { $verb = $t; break } }
    $per = -1.0
    if ($verb -ceq 'erase') { $per = [double]$c.Erase }
    elseif ($verb -ceq 'write') {
        $per = [double]$c.Write
        if ($line -match '\s--pre-erase\s') { $per += [double]$c.PreErase }
        if ($line -notmatch '\s--no-verify\s') { $per += [double]$c.Verify }
    }
    elseif ($verb -ceq 'read') {
        $per = if ($line -match '\s--revs=(\d+)\s') { [double]$c.ReadBase + [double]$c.ReadRev * [int]$Matches[1] } else { [double]$c.ReadNoRevs }
    }
    if ($per -lt 0) { return @{ Fixed = 0.0; Per = 0.0; Tracks = 0; Units = 0.0 } }
    $n = $tracks
    if ($n -lt 0) {
        $n = 0
        if ($line -match '\s--tracks=(\S+)') {
            $ts = [string]$Matches[1]
            if ($ts -match '(?:^|:)c=([\d,\-]+)') {
                $nc = Get-SpecCount $Matches[1]
                if ($ts -match '(?:^|:)h=([\d,\-]+)') { $n = $nc * (Get-SpecCount $Matches[1]) }
            }
        }
    }
    return @{ Fixed = [double]$c.Fixed; Per = $per; Tracks = [int]$n; Units = ([double]$c.Fixed + [int]$n * $per) }
}

function New-ProgPlan($cmds, $tracks = $null) {
    # Plan d une etape faite de plusieurs commandes gw ($cmds : tableaux d arguments, dans l ordre de leur lancement) :
    # $script:ProgPlan = @{ Units (poids prevu) ; Done (poids des commandes finies) ; Max (plus grande fraction rendue) ;
    # Cmds (poids prevus, par commande) ; Got (commandes recues de Start-Progress) }. Pose la ou l etape construit ses
    # commandes (New-CalibPass, Start-CalibCondition, New-ContentPass ; 12.11, L11 : Start-WriteProgress, Step-WriteProgress,
    # 160) ; retire quand la passe est comptee, a l arret d une calibration, a la fin d une ecriture et au repos
    # (Update-SeqEnd). Ne lance rien et ne modifie aucune commande.
    # 12.11 (L11) : $tracks (facultatif, un nombre par commande, -1 : pistes lues dans ses arguments) : pistes estimees d une
    # commande dont --tracks ne les donne pas (ecriture d une image) ; sans elles, son poids ne serait que sa part fixe
    # jusqu a l annonce de gw, et l etape avancerait trop vite avant elle. Entree marquee Est, corrigee par l annonce
    $u = 0.0
    $l = New-Object System.Collections.Generic.List[object]
    $ti = -1
    foreach ($c in @($cmds)) {
        $ti++
        if ($null -eq $c) { continue }
        $n = if ($null -ne $tracks -and $ti -lt @($tracks).Count) { [int]@($tracks)[$ti] } else { -1 }
        $w = Get-GwCmdUnits ([string[]]@($c)) $n
        if ($n -ge 0) { $w.Est = $true }
        $u += [double]$w.Units
        $l.Add($w)
    }
    $script:ProgPlan = @{ Units = $u; Done = 0.0; Max = 0.0; Cmds = $l.ToArray(); Got = 0 }
    $script:ProgCmd = $null
}

function Get-ProgPlanFrac {
    # Avancement de l etape en cours, de 0 a 1 ; $null sans plan, ou tant que le plan n a recu aucune commande (Start-Gw
    # remplace par un banc de test : l appelant garde alors son calcul par le temps). (poids fini + part de la commande en
    # cours) / max(poids prevu, poids fini + poids de la commande en cours). Part de la commande en cours : des sa
    # premiere ligne de piste, part fixe + pistes terminees x cout par piste ; avant (4 a 6 s en pratique, ou toute la
    # commande si gw n imprime aucune ligne de piste), temps ecoule depuis son lancement, borne a 98 % de son poids.
    # Jamais decroissant dans un plan (Max), 1 au plus : une commande non prevue (reprise d une tete), ou plus de pistes
    # vues que prevu, allonge le plan sans faire reculer la barre, qui attend alors sur place
    $p = $script:ProgPlan
    if (-not $p -or [int]$p.Got -le 0) { return $null }
    $done = [double]$p.Done; $cur = 0.0; $w = 0.0
    $pc = $script:ProgCmd
    if ($pc) {
        $w = [double]$pc.Units
        if ($script:ProgSeen -and $script:ProgSeen.Count -gt 0) {
            $cur = [double]$pc.Fixed + (Get-GwProgress).Done * [double]$pc.Per
            if ($cur -gt $w) { $w = $cur }
        } else {
            $el = if ($script:GwStart -is [datetime]) { ((Get-Date) - $script:GwStart).TotalSeconds } else { 0.0 }
            $cur = [math]::Max(0.0, [math]::Min($el, 0.98 * $w))
        }
    }
    $den = [math]::Max([double]$p.Units, $done + $w)
    $f = if ($den -gt 0) { [math]::Min(1.0, ($done + $cur) / $den) } else { 0.0 }
    if ($f -lt [double]$p.Max) { $f = [double]$p.Max } else { $p.Max = $f }
    return [double]$f
}

function Set-SeqEnd([string]$text, [string]$icon = 'idle', [switch]$NoTime, [switch]$IfNone) {
    # Etat de la barre d etat a poser a la fin de la sequence en cours : le resultat de l operation (restauration,
    # calibration, controle apres ecriture, recherche des lecteurs), sans compteur ni barre. En attente seulement :
    # Update-SeqEnd l applique au repos ; une commande gw qui suit l annule (Start-Progress), un echec du lancement aussi
    # (Set-GwLaunchFailedStatus). Icone : idle, ok ou err ($script:StIcons, 540). Sans -NoTime, l heure suit le texte
    # 12.11 : -IfNone : ne remplace pas un etat deja en attente (arret d une calibration juste apres le verdict d une
    # restauration : Stop-Restore puis Stop-PrecompCalib dans le minuteur et dans le bouton Arreter)
    if ($IfNone -and $null -ne $script:SeqEnd) { return }
    $script:SeqEnd = @{ Text = $text; Icon = $icon; NoTime = [bool]$NoTime }
}

function Clear-SeqEnd {
    # Etat de fin de sequence en attente annule sans qu une commande gw suive : la barre d etat vient de recevoir une
    # consigne qui le remplace (attente de la disquette de destination d une restauration, Enter-RestoreWait, apres une
    # calibration sur une disquette sacrifiee : sans cela, « Annuler » pendant l attente afficherait « Pret. », puis au
    # repos le titre de la calibration)
    $script:SeqEnd = $null
}

function Update-SeqEnd {
    # Minuteur principal (600) : fin de sequence, une fois l application au repos (Get-AppBusy vide). Etat pose par
    # Set-SeqEnd : texte (suivi de l heure), icone, compteur de piste efface, barre masquee. Sans etat pose, apres une
    # sequence de deux commandes gw ou plus : compteur efface et barre masquee, texte de la derniere commande garde ; une
    # commande isolee garde l affichage de la 12.10. Jamais sur un etat d echec de la derniere commande (« ... en echec
    # (code N) », gw non lance : ProgFailed), qui dit la cause : l attente est abandonnee, la barre d etat laissee.
    # Plan de l etape retire. Cout par passage : trois variables, puis Get-AppBusy tant qu une sequence est en cours
    if ($null -eq $script:SeqEnd -and [int]$script:SeqCmds -le 0 -and $null -eq $script:ProgPlan) { return }
    if (Get-AppBusy) { return }
    $e = $script:SeqEnd; $n = [int]$script:SeqCmds
    $script:SeqEnd = $null; $script:SeqCmds = 0; $script:ProgPlan = $null; $script:ProgCmd = $null
    if ($script:ProgFailed) { return }
    if ($e) {
        $stOp.Text = $(if ($e.NoTime) { [string]$e.Text } else { [string]$e.Text + '  -  ' + (Get-Date -Format 'HH:mm:ss') })
        $stOp.Image = $(if ($script:StIcons.ContainsKey([string]$e.Icon)) { $script:StIcons[[string]$e.Icon] } else { $script:StIcons.idle })
        $stTrack.Text = ''; $stBar.Visible = $false
    } elseif ($n -ge 2) { $stTrack.Text = ''; $stBar.Visible = $false }
}
# ============================== FONCTIONS : LECTEURS ENREGISTRES ===============
# 12.11 (lot LN-a, socle sans interface) : un lecteur de disquette peut recevoir un nom. Le nom est alors son identite : le
# texte de la liste du bandeau, la cle de rangement de ses courbes (« nom|cle », « source>cible|cle ») et le champ Drive de
# ses donnees. La connexion (A, B, 0 a 3 : la valeur de --drive) devient un attribut de sa fiche, donne par la seule
# fonction Get-DriveConn. Un lecteur non enregistre garde pour identite le code de sa connexion : tant qu aucun lecteur
# n a ete enregistre, cles, blocs de la configuration et arguments de gw sont ceux de la 12.10 (une fois une copie de
# secours lue ou ecrite, le bloc drives reste ecrit, liste vide comprise : Export-DriveRegistry).
# Etat (040) : $script:DriveReg, registre, table ordonnee nom -> fiche @{ Name ; Conn ; Id ; Created ; From ; At } ;
# $script:DriveLast, connexion -> dernier lecteur enregistre choisi. Le registre n est jamais lu par un index ni par une
# propriete (Get-DriveRecord enumere ses entrees) : un nom fait de chiffres ne peut pas etre pris pour un rang, et aucun
# nom ne peut masquer une propriete de la table. Les mots reserves ($script:DriveReserved, refuses par Test-DriveName)
# protegent en plus la garde « registre non vide » ($script:DriveReg.Count -gt 0) des lignes ajoutees aux fonctions
# existantes.
# Des donnees ne changent d identite que par Edit-DriveData, appelee par les quatre actions du registre (Add-NamedDrive,
# Rename-NamedDrive, Move-NamedDrive, Remove-NamedDrive), qui ne touchent ni liste ni fenetre et rendent une table
# @{ Ok ; Why ; ... } (Why : le texte du refus). L interface (bandeau, confirmation du lecteur branche, fenetre
# « Lecteurs enregistres ») est en fin de module (lot LN-b).

function Test-DriveConnCode([string]$s) {
    # 12.11 : vrai pour une des six connexions (codes du reglage drive, 040) ; comparaison exacte, comme
    # ConvertTo-SettingValue : « a » n est pas une connexion
    foreach ($c in $script:SettingDefs['drive'].Codes) { if ($c -ceq $s) { return $true } }
    return $false
}

function Get-DriveRecord([string]$drive) {
    # 12.11 : fiche d un lecteur enregistre, casse ignoree ; $null pour un lecteur non enregistre ou inconnu. Par
    # enumeration : ni index, ni propriete de la table
    if (-not $drive -or -not $script:DriveReg) { return $null }
    foreach ($e in @($script:DriveReg.GetEnumerator())) { if ([string]$e.Key -eq $drive) { return $e.Value } }
    return $null
}

function Get-DriveConn([string]$drive) {
    # 12.11 : seule fonction qui donne la connexion (valeur de --drive) d un lecteur : un lecteur non enregistre (A, B,
    # 0 a 3) est sa propre connexion ; un lecteur enregistre : celle de sa fiche ; inconnu, ou fiche sans connexion : ''
    # (gw refuse alors la commande : un nom n atteint jamais --drive). Sans autre fonction du module : les tests qui
    # chargent Get-CalibDriveArgsFor ne chargent qu elle
    foreach ($c in $script:SettingDefs['drive'].Codes) { if ($c -ceq $drive) { return [string]$c } }
    if ($drive -and $script:DriveReg) { foreach ($e in @($script:DriveReg.GetEnumerator())) { if ([string]$e.Key -eq $drive) { return [string]$e.Value.Conn } } }
    return ''
}

function Test-DriveRegistered([string]$drive) {
    # 12.11 : vrai pour un nom du registre
    return ($null -ne (Get-DriveRecord $drive))
}

function Get-DriveLabel([string]$drive) {
    # 12.11 : texte d un lecteur la ou sa connexion doit se lire : « TEAC FD-235HF (A) » ; lecteur non enregistre : son
    # code ; fiche sans connexion : « nom (connexion a preciser) » ; nom sans fiche : l identite nue
    $r = Get-DriveRecord $drive
    if (-not $r) { return $drive }
    if ([string]$r.Conn) { return ('{0} ({1})' -f [string]$r.Name, [string]$r.Conn) }
    return ((T '{0} (connexion à préciser)') -f [string]$r.Name)
}

function Get-DriveForConn([string]$conn) {
    # 12.11 : lecteur retenu pour une connexion : le dernier lecteur enregistre choisi sur elle s il y est toujours
    # enregistre, rendu par le nom de sa fiche, a sa casse (Set-Combo choisit par Items.Contains) ; sinon la connexion
    $l = ''
    if ($script:DriveLast) { foreach ($e in @($script:DriveLast.GetEnumerator())) { if ([string]$e.Key -ceq $conn) { $l = [string]$e.Value } } }
    $r = Get-DriveRecord $l
    if ($r -and [string]$r.Conn -ceq $conn) { return [string]$r.Name }
    return $conn
}

function Get-ConnDrives([string]$conn) {
    # 12.11 : lecteurs qu une connexion peut porter : ceux qui y sont enregistres, dans l ordre du registre, puis son
    # lecteur non enregistre s il a des donnees ou s il est le lecteur du bandeau. Elements rendus un a un, sans virgule
    # de protection : l appelant les recueille par @()
    if (-not (Test-DriveConnCode $conn)) { return }
    if ($script:DriveReg) { foreach ($e in @($script:DriveReg.GetEnumerator())) { if ([string]$e.Value.Conn -ceq $conn) { [string]$e.Value.Name } } }
    if ([string]$cmbDrive.Text -ceq $conn -or (Get-DriveData $conn)['Any']) { $conn }
}

function Test-DriveName([string]$name, [string]$self = '', [switch]$Load) {
    # 12.11 : seule decision sur le nom d un lecteur : @{ Ok ; Why (texte du refus) ; Name (nom normalise : espaces des
    # bords retires, espaces repetes ramenes a un seul) }. $self : nom actuel de la fiche modifiee, qui n est pas un
    # doublon d elle-meme, meme a la casse pres. -Load (chargement d une configuration, noms trouves dans les donnees) :
    # regles de structure seules, mots reserves compris ; le nom doit etre deja normalise ; la largeur, qui depend de la
    # police, n est controlee qu a la saisie
    $res = @{ Ok = $false; Why = ''; Name = '' }
    $n = (([string]$name).Trim()) -replace ' {2,}', ' '
    $res.Name = $n
    if (-not $n) { $res.Why = (T 'Donnez un nom au lecteur.'); return $res }
    if ($n.Length -gt [int]$script:DriveNameMax) { $res.Why = ((T 'Nom trop long : {0} caractères au plus.') -f "$([int]$script:DriveNameMax)"); return $res }
    # Lettres, chiffres, espace et - . _ + # ° (U+00B0) : « | » et « > » separent les cles du magasin, « & » marque un
    # raccourci dans un libelle, les parentheses sont reservees a la connexion (« nom (A) »)
    $bad = ''
    foreach ($ch in $n.ToCharArray()) { if ([string]$ch -cnotmatch '^[\p{L}\p{Nd} \-._+#°]$') { $bad = [string]$ch; break } }
    if (-not $bad -and $Load -and $n -cne [string]$name) { $bad = ' ' }
    if ($bad) {
        if ([char]::IsControl($bad[0]) -or ([char]::IsWhiteSpace($bad[0]) -and $bad -ne ' ')) { $bad = ('U+{0:X4}' -f [int]$bad[0]) }
        $res.Why = ((T "Caractère non admis : « {0} ». Un nom se compose de lettres, de chiffres, d'espaces et des signes - . _ + # °") -f $bad)
        return $res
    }
    if ($n -cnotmatch '[A-Za-z0-9]') { $res.Why = (T 'Un nom contient au moins une lettre sans accent ou un chiffre.'); return $res }
    foreach ($c in $script:SettingDefs['drive'].Codes) { if ([string]$c -eq $n) { $res.Why = ((T '« {0} » désigne une connexion : choisissez un autre nom.') -f $n); return $res } }
    # Mots reserves : une table PowerShell rend la valeur d une cle avant sa propre propriete ; une fiche « Count » ferait
    # lever une erreur a la garde « registre non vide » au lieu de la rendre vraie
    foreach ($w in @($script:DriveReserved)) { if ([string]$w -eq $n) { $res.Why = ((T '« {0} » est un mot réservé : choisissez un autre nom.') -f $n); return $res } }
    $dup = Get-DriveRecord $n
    $dupName = if ($dup) { [string]$dup.Name } elseif ($script:DriveReg -and $script:DriveReg.Contains($n)) { $n } else { '' }
    if ($dupName -and -not ($self -and $dupName -eq $self)) { $res.Why = ((T 'Un lecteur enregistré porte déjà ce nom : {0}.') -f $dupName); return $res }
    if (-not $Load -and $form -and $form.Font) {
        # Liste du bandeau elargie et liste « Lecteur cible » : 24 px de moins que leur largeur pour le texte d un element
        $w = [System.Windows.Forms.TextRenderer]::MeasureText($n, $form.Font).Width
        if ($w -gt ([int]$script:DriveListWidth - 24)) { $res.Why = (T "Nom trop large pour s'afficher en entier dans les listes de lecteurs (environ 17 caractères) : raccourcissez-le."); return $res }
    }
    $res.Ok = $true
    return $res
}

function Get-DriveData([string]$drive, $old = $null) {
    # 12.11 : ce qui est range sous un lecteur (code d une connexion ou nom), dans tous les porteurs de l identite :
    # @{ Keys (cles de magasin de ses courbes, courbes d un autre calcul en attente du choix comprises) ; Cross (cles
    # croisees dont il est la source ou la cible) ; Levels, Brands, Factors (niveaux de la calibration rapide, entrees de
    # la memoire par marque, facteurs mesures sur l image) ; Target (son lecteur cible) ; TargetOf (lecteurs dont il est
    # le lecteur cible) ; Last (connexions dont il est le dernier lecteur choisi) ; Latest (date de sa courbe la plus
    # recente) ; Any }. Any : vrai des que Keys, Cross, Levels, Brands, Factors, Target ou TargetOf est non vide (un
    # lecteur qui n apparait que comme cible porte une donnee). $old : courbes en attente du choix pendant Load-Config,
    # avant que $script:OldCalib soit pose. Les champs se lisent par l index (['Keys']) : sur une table, .Keys rendrait
    # ce champ, pas les cles
    $keys = @(); $cross = @(); $levels = @(); $brands = @(); $factors = @(); $tgtOf = @(); $last = @(); $tgt = ''; $latest = ''; $bd = [datetime]::MinValue
    if (-not $drive) { return @{ Keys = @(); Cross = @(); Levels = @(); Brands = @(); Factors = @(); Target = ''; TargetOf = @(); Last = @(); Latest = ''; Any = $false } }
    $oc = $script:OldCalib
    $tabs = @()
    if ($null -ne $script:DriveCurves) { $tabs += ,$script:DriveCurves }
    if ($null -ne $old) { $tabs += ,$old } elseif ($oc -and $null -ne $oc.Curves) { $tabs += ,$oc.Curves }
    foreach ($tb in $tabs) {
        foreach ($e in @($tb.GetEnumerator())) {
            $sk = [string]$e.Key; $cv = $e.Value
            if (-not $cv) { continue }
            $d = [string](Split-DriveCurveKey $sk).Drive
            $x = Split-CrossDrive $d
            $mine = $false
            if ($x) { if ([string]$x.Src -eq $drive -or [string]$x.Tgt -eq $drive) { $cross += $sk; $mine = $true } }
            elseif ($d -eq $drive) { $keys += $sk; $mine = $true }
            if ($mine) { $dt = Get-CurveDate $cv; if (-not $latest -or $dt -gt $bd) { $bd = $dt; $latest = [string]$cv.Date } }
        }
    }
    $lvs = @()
    if ($null -ne $script:LevelShifts) { $lvs += @($script:LevelShifts.GetEnumerator() | ForEach-Object { $_.Value }) }
    if ($null -eq $old -and $oc -and $null -ne $oc.Levels) { $lvs += @($oc.Levels.GetEnumerator() | ForEach-Object { $_.Value }) }
    $levels = @($lvs | Where-Object { $_ -and [string]$_.Drive -eq $drive })
    $brands = @(@($script:LevelBrands) | Where-Object { $_ -and [string]$_.Drive -eq $drive })
    $factors = @(@($script:ContentMeasures) | Where-Object { $_ -and [string]$_.Drive -eq $drive })
    if ($null -ne $script:TargetDrives) {
        foreach ($e in @($script:TargetDrives.GetEnumerator())) {
            if ([string]$e.Key -eq $drive -and [string]$e.Value) { $tgt = [string]$e.Value }
            if ([string]$e.Value -eq $drive) { $tgtOf += [string]$e.Key }
        }
    }
    if ($script:DriveLast) { foreach ($e in @($script:DriveLast.GetEnumerator())) { if ([string]$e.Value -eq $drive) { $last += [string]$e.Key } } }
    $any = ($keys.Count -gt 0 -or $cross.Count -gt 0 -or $levels.Count -gt 0 -or $brands.Count -gt 0 -or $factors.Count -gt 0 -or [bool]$tgt -or $tgtOf.Count -gt 0)
    return @{ Keys = @($keys | Sort-Object); Cross = @($cross | Sort-Object); Levels = $levels; Brands = $brands; Factors = $factors; Target = $tgt; TargetOf = @($tgtOf | Sort-Object); Last = @($last | Sort-Object); Latest = $latest; Any = $any }
}

function Get-DriveDataText($data) {
    # 12.11 : texte des calibrations d un lecteur (Get-DriveData) : « 5 courbe(s) dont 2 croisee(s), derniere : ... »,
    # « 2 courbe(s), derniere : ... » ou « aucune »
    if ($null -eq $data) { return (T 'aucune') }
    $nk = @($data['Keys']).Count; $nx = @($data['Cross']).Count
    if ($nk + $nx -eq 0) { return (T 'aucune') }
    $dt = [string]$data['Latest']; if (-not $dt) { $dt = '?' }
    if ($nx -gt 0) { return ((T '{0} courbe(s) dont {1} croisée(s), dernière : {2}') -f "$($nk + $nx)", "$nx", $dt) }
    return ((T '{0} courbe(s), dernière : {1}') -f "$nk", $dt)
}

function Get-DriveMovedKey([string]$storeKey, [string]$from, [string]$to) {
    # 12.11 : cle de magasin (« lecteur|cle », « source>cible|cle ») quand les donnees de $from passent sous $to ($to
    # vide : retrait). Rend @{ Key (nouvelle cle ; '' : courbe retiree) ; Moved (la cle cite $from) }
    $p = Split-DriveCurveKey $storeKey
    $d = [string]$p.Drive; $k = [string]$p.Key
    $x = Split-CrossDrive $d
    if ($x) {
        $s = [string]$x.Src; $t = [string]$x.Tgt
        if ($s -ne $from -and $t -ne $from) { return @{ Key = $storeKey; Moved = $false } }
        if (-not $to) { return @{ Key = ''; Moved = $true } }
        if ($s -eq $from) { $s = $to }
        if ($t -eq $from) { $t = $to }
        return @{ Key = (Get-DriveCurveKey "$s>$t" $k); Moved = $true }
    }
    if ($d -ne $from) { return @{ Key = $storeKey; Moved = $false } }
    if (-not $to) { return @{ Key = ''; Moved = $true } }
    return @{ Key = (Get-DriveCurveKey $to $k); Moved = $true }
}

function Edit-DriveData([string]$from, [string]$to, [switch]$Check) {
    # 12.11 : seule fonction qui change l identite de donnees : tout ce qui est range sous $from passe sous $to, ou est
    # retire si $to est vide. Porteurs, tous ici : (1) cles de $script:DriveCurves, simples et croisees, la source comme
    # la cible ; (2) champs Drive et Target des courbes deplacees ; (3) $script:OldCalib.Curves et .Levels ;
    # (4) $script:LevelShifts ; (5) $script:LevelBrands ; (6) $script:ContentMeasures ; (7) $script:TargetDrives, comme
    # source et comme cible ; (8) $script:DriveLast. La vue ($script:PrecompCurves) n est jamais ecrite ici :
    # l appelant la refait par Sync-PrecompCurves.
    # Jamais de fusion : refus sans effet si $to porte deja une donnee (Get-DriveData : Any) ou si une cle d arrivee
    # existe deja. $to egal a $from a la casse pres (correction de casse d un nom) : admis, ce refus ne s applique pas.
    # Deux temps : calcul des nouvelles tables et de la liste des champs a reecrire, sans aucun effet, puis affectations
    # simples : tout ou rien. Chaque table est reconstruite a partir d une table vide, cle par cle ; jamais d ajout puis
    # de retrait dans la table en place, qui detruit l entree quand les deux cles ne different que par la casse.
    # -Check : premier temps seul (decision et texte du refus, sans rien changer). Rend @{ Ok ; Why ; N (courbes
    # deplacees ou retirees) }
    $res = @{ Ok = $false; Why = ''; N = 0 }
    if (-not $from) { return $res }
    $same = ($from -eq $to)
    $toConn = Test-DriveConnCode $to
    # 12.11 (relecture de LN-a) : le refus part des que $to porte une donnee (Get-DriveData : Any), courbe ou non : le texte
    # nomme toutes les sortes de donnees, et non les seules calibrations (un lecteur cible choisi suffit)
    $refuse = if ($toConn) { ((T 'La connexion {0} a déjà des données sans nom de lecteur (courbes, lecteur cible, niveaux, mémoire par marque ou facteurs) : le nom ne peut pas être retiré seul.') -f $to) } else { ((T 'Le lecteur {0} a déjà des données (courbes, lecteur cible, niveaux, mémoire par marque ou facteurs) : celles de la connexion {1} ne peuvent pas lui être attribuées.') -f $to, $from) }
    # --- Premier temps : calcul, sans effet -------------------------------------------------------------------------
    $fix = @(); $n = 0; $clash = $false
    $nCurves = @{}; $nOld = [ordered]@{}; $nOldLv = @{}; $nLv = @{}; $nBr = @(); $nCm = @(); $nTd = @{}; $nLast = @{}
    $oc = $script:OldCalib
    $hasOld = [bool]($oc -and $null -ne $oc.Curves); $hasOldLv = [bool]($oc -and $null -ne $oc.Levels)
    try {
        if ($to -and -not $same -and (Get-DriveData $to)['Any']) { $res.Why = $refuse; return $res }
        # (1) (2) (3) courbes du magasin et courbes d un autre calcul en attente du choix
        $src = @()
        if ($null -ne $script:DriveCurves) { $src += ,@($script:DriveCurves, $nCurves) }
        if ($hasOld) { $src += ,@($oc.Curves, $nOld) }
        foreach ($pair in $src) {
            $new = $pair[1]
            foreach ($e in @($pair[0].GetEnumerator())) {
                $sk = [string]$e.Key; $cv = $e.Value
                $m = Get-DriveMovedKey $sk $from $to
                $nk = [string]$m.Key
                if ($m.Moved) {
                    if ($cv) { $n++ }
                    if (-not $nk) { continue }
                    if ($cv) {
                        if ([string]$cv.Drive -eq $from) { $fix += ,@{ O = $cv; F = 'Drive'; V = $to } }
                        if ([string]$cv.Target -eq $from) { $fix += ,@{ O = $cv; F = 'Target'; V = $to } }
                    }
                }
                if ($new.Contains($nk)) { $clash = $true }
                $new.Add($nk, $cv)
            }
        }
        # (3) (4) niveaux de la calibration rapide : meme cle (« cle de courbe|tete », sans lecteur), champ Drive
        $src = @()
        if ($null -ne $script:LevelShifts) { $src += ,@($script:LevelShifts, $nLv) }
        if ($hasOldLv) { $src += ,@($oc.Levels, $nOldLv) }
        foreach ($pair in $src) {
            $new = $pair[1]
            foreach ($e in @($pair[0].GetEnumerator())) {
                $lr = $e.Value
                if ($lr -and [string]$lr.Drive -eq $from) { if (-not $to) { continue }; $fix += ,@{ O = $lr; F = 'Drive'; V = $to } }
                $new.Add([string]$e.Key, $lr)
            }
        }
        # (5) memoire par marque, (6) facteurs mesures sur l image : champ Drive
        foreach ($en in @($script:LevelBrands)) {
            if ($null -eq $en) { continue }
            if ([string]$en.Drive -eq $from) { if (-not $to) { continue }; $fix += ,@{ O = $en; F = 'Drive'; V = $to } }
            $nBr += ,$en
        }
        foreach ($rec in @($script:ContentMeasures)) {
            if ($null -eq $rec) { continue }
            if ([string]$rec.Drive -eq $from) { if (-not $to) { continue }; $fix += ,@{ O = $rec; F = 'Drive'; V = $to } }
            $nCm += ,$rec
        }
        # (7) lecteurs cibles : la source comme la cible
        if ($null -ne $script:TargetDrives) {
            foreach ($e in @($script:TargetDrives.GetEnumerator())) {
                $s = [string]$e.Key; $t = [string]$e.Value
                if ($s -eq $from -or $t -eq $from) {
                    if (-not $to) { continue }
                    if ($s -eq $from) { $s = $to }
                    if ($t -eq $from) { $t = $to }
                }
                if ($nTd.Contains($s)) { $clash = $true }
                $nTd.Add($s, $t)
            }
        }
        # (8) dernier lecteur choisi par connexion : des noms seulement (un nom retire ou rendu a sa connexion en sort)
        if ($script:DriveLast) {
            foreach ($e in @($script:DriveLast.GetEnumerator())) {
                $v = [string]$e.Value
                if ($v -eq $from) { if (-not $to -or $toConn) { continue }; $v = $to }
                $nLast.Add([string]$e.Key, $v)
            }
        }
    } catch {
        if (-not $clash) { $res.Why = ([string]$_.Exception.Message).Trim(); return $res }
    }
    if ($clash) { $res.Why = $refuse; return $res }
    $res.N = $n
    if ($Check) { $res.Ok = $true; return $res }
    # --- Second temps : affectations simples -------------------------------------------------------------------------
    $script:DriveCurves = $nCurves
    if ($hasOld) { $script:OldCalib.Curves = $nOld }
    if ($hasOldLv) { $script:OldCalib.Levels = $nOldLv }
    $script:LevelShifts = $nLv
    $script:LevelBrands = $nBr
    $script:ContentMeasures = $nCm
    $script:TargetDrives = $nTd
    $script:DriveLast = $nLast
    foreach ($f in $fix) { $f.O[[string]$f.F] = [string]$f.V }
    $res.Ok = $true
    return $res
}

function Get-DriveNow {
    # 12.11 : date et heure d une fiche (Created, At), a la seconde, meme forme que _saved
    return (Get-Date).ToString('yyyy-MM-dd HH:mm:ss', [System.Globalization.CultureInfo]::InvariantCulture)
}

function ConvertTo-DriveDate([string]$s) {
    # 12.11 : date d une fiche (yyyy-MM-dd HH:mm:ss) ; MinValue si elle est vide ou illisible
    $d = [datetime]::MinValue
    if ($s -and [datetime]::TryParseExact($s, 'yyyy-MM-dd HH:mm:ss', [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::None, [ref]$d)) { return $d }
    return [datetime]::MinValue
}

function Backup-ConfigForDrives {
    # 12.11 : copie datee, octet pour octet, du fichier de configuration sur disque avant une modification des lecteurs
    # enregistres : <fichier>.lecteurs-<AAAAMMJJ-HHmmss>.bak, date et heure de la copie ; nom deja pris : suffixe -2,
    # -3... avant .bak (une copie n en ecrase jamais une autre). Rotation propre : les $script:DriveBackupKeep copies
    # .lecteurs-*.bak les plus recentes sont gardees ; les copies .ref-*.bak de Backup-ConfigBeforeRef ne sont ni comptees
    # ni touchees. Rend @{ Ok ; Bak ; Why } : un echec ne se confond jamais avec « rien a copier »
    $res = @{ Ok = $false; Bak = ''; Why = '' }
    $cfg = [string]$script:ConfigFile
    $bak = ''; $dir = ''; $leaf = ''
    try {
        $leaf = [System.IO.Path]::GetFileName($cfg); $dir = Split-Path -Parent $cfg
        $stamp = (Get-Date).ToString('yyyyMMdd-HHmmss', [System.Globalization.CultureInfo]::InvariantCulture)
        $base = Join-Path $dir ($leaf + '.lecteurs-' + $stamp)
        $bak = $base + '.bak'; $i = 1
        while (Test-Path -LiteralPath $bak) { $i++; $bak = $base + '-' + $i + '.bak' }
        [System.IO.File]::Copy($cfg, $bak, $false)
        [System.IO.File]::SetLastWriteTime($bak, (Get-Date))
    } catch {
        $msg = ([string]$(if ($_.Exception.InnerException) { $_.Exception.InnerException.Message } else { $_.Exception.Message })).Trim().TrimEnd('.')
        Append-Log ((T "Configuration non copiée avant la modification des lecteurs enregistrés : {0}. Modification annulée : rien n'est changé.") -f "$msg")
        $res.Why = $msg
        return $res
    }
    Append-Log ((T 'Configuration sauvegardée avant la modification des lecteurs enregistrés : {0}') -f "$bak")
    $keep = [math]::Max(1, [int]$script:DriveBackupKeep)
    try {
        $bakName = [System.IO.Path]::GetFileName($bak)
        $all = @(Get-ChildItem -LiteralPath $dir -File -ErrorAction Stop | Where-Object { $_.Name -like ($leaf + '.lecteurs-*.bak') -and $_.Name -ne $bakName } | Sort-Object -Property @{ Expression = { $_.LastWriteTime }; Descending = $true }, @{ Expression = { $_.Name }; Descending = $true })
        foreach ($f in @($all | Select-Object -Skip ($keep - 1))) {
            try { Remove-Item -LiteralPath $f.FullName -Force -ErrorAction Stop; Append-Log ((T "Ancienne sauvegarde de configuration supprimée ({1} gardées) : {0}") -f "$($f.FullName)", "$keep") } catch { }
        }
    } catch { }
    $res.Ok = $true; $res.Bak = $bak
    return $res
}

function Protect-DriveData([string[]]$drives) {
    # 12.11 : avant une modification des donnees de ces lecteurs. Sans aucune donnee sous eux (Get-DriveData : Any faux
    # pour tous) : Ok, sans copie. Sinon : enregistrement (le fichier sur disque devient l etat d avant ; son bloc
    # drives est ecrit meme avec une liste vide, $script:DriveBlockKeep, si bien que la copie d avant la premiere
    # attribution dit « aucun lecteur enregistre »), puis copie datee (Backup-ConfigForDrives). Enregistrement ou copie
    # en echec : Ok faux, l appelant annule la modification. Rend @{ Ok ; Bak ; Copy (une copie a ete faite) ; Why }
    $res = @{ Ok = $true; Bak = ''; Copy = $false; Why = '' }
    $any = $false
    foreach ($d in @($drives)) { if ($d -and (Get-DriveData $d)['Any']) { $any = $true } }
    if (-not $any) { return $res }
    $res.Ok = $false
    $saved = $false
    $script:DriveBlockKeep = $true
    # Le temps de cet enregistrement, une erreur d ecriture du fichier arrete Save-Config (qui la note et rend faux) au
    # lieu d etre seulement affichee : sans cela, la copie qui suit serait celle d un fichier perime
    $eap = $ErrorActionPreference
    try { $ErrorActionPreference = 'Stop'; $saved = [bool](Save-Config) } catch { $saved = $false } finally { $ErrorActionPreference = $eap; $script:DriveBlockKeep = $false }
    if (-not $saved) {
        Append-Log (T "Configuration non enregistrée avant la modification des lecteurs enregistrés. Modification annulée : rien n'est changé.")
        $res.Why = (T "Configuration non sauvegardée : rien n'a été modifié (voir le journal).")
        return $res
    }
    $bk = Backup-ConfigForDrives
    if (-not $bk.Ok) { $res.Why = (T "Configuration non sauvegardée : rien n'a été modifié (voir le journal)."); return $res }
    $res.Ok = $true; $res.Bak = [string]$bk.Bak; $res.Copy = $true
    return $res
}

function New-DriveId([string]$kind = 'L') {
    # 12.11 : identifiant d une fiche neuve, jamais deduit d un compteur : la lettre L (R : fiche refaite d apres les
    # donnees par Repair-DriveRegistry ou a la lecture), la date et l heure a la seconde, un tiret et un rang a deux
    # chiffres parmi les fiches de la meme seconde : « L20261120180211-01 ». Unique dans le registre, inchange par un
    # renommage ou un changement de connexion : il ne range rien, il relie un nom lu dans une copie datee au lecteur
    # d aujourd hui (Resolve-DriveOfEra)
    if ($kind -cne 'R') { $kind = 'L' }
    $used = @{}
    if ($script:DriveReg) { foreach ($e in @($script:DriveReg.GetEnumerator())) { $u = [string]$e.Value.Id; if ($u.Length -gt 1) { $used[$u.Substring(1)] = $true } } }
    while ($true) {
        $stamp = (Get-Date).ToString('yyyyMMddHHmmss', [System.Globalization.CultureInfo]::InvariantCulture)
        for ($r = 1; $r -le 99; $r++) { $tail = ('{0}-{1:00}' -f $stamp, $r); if (-not $used.ContainsKey($tail)) { return ($kind + $tail) } }
        Start-Sleep -Milliseconds 250
    }
}

function New-DriveRegTable($records) {
    # 12.11 : registre construit a partir d une table vide, dans l ordre donne ; rien n est affecte ici
    $t = [ordered]@{}
    foreach ($r in @($records)) { if ($r) { $t.Add([string]$r.Name, $r) } }
    return $t
}

function Get-DriveEditRefusal {
    # 12.11 : refus commun des quatre actions du registre : operation en cours (le texte porte le libelle rendu par
    # Get-AppBusy, la fonction qui decide), ou calibration B en cours ou en attente de sa decision ; '' sinon
    $busy = Get-AppBusy -Text
    if ($busy) { return ((T 'Lecteurs enregistrés : opération en cours ({0}). Réessayez quand elle est terminée.') -f "$busy") }
    if ($script:CalRedo) { return (T "Calibration B en cours ou en attente de décision : terminez-la d'abord.") }
    return ''
}

function Add-NamedDrive([string]$name, [string]$conn, [string]$from = '') {
    # 12.11 : enregistre un lecteur (fiche neuve : Id, Created). Avec $from (une connexion) : nomme le lecteur non
    # enregistre de cette connexion, dont les donnees passent sous le nom (copie datee d abord, des qu il en a une), et
    # pose From et At ; avec le nom d une fiche existante sans aucune donnee : attribution a cette fiche, qui garde son
    # identifiant. Jamais de fusion (refus d Edit-DriveData). Rend @{ Ok ; Why ; Name ; N ; Bak ; Copy }
    $res = @{ Ok = $false; Why = ''; Name = ''; N = 0; Bak = ''; Copy = $false }
    $why = Get-DriveEditRefusal
    if ($why) { $res.Why = $why; return $res }
    if (-not (Test-DriveConnCode $conn) -or ($from -and -not (Test-DriveConnCode $from))) { $res.Why = (T 'Choisissez la connexion du lecteur.'); return $res }
    $rec = $null
    if ($from) { $rec = Get-DriveRecord ([string](Test-DriveName $name).Name) }   # 12.11 : nom normalise (espaces repetes ramenes a un seul), comme Test-DriveName
    $nm = ''
    if ($rec) { $nm = [string]$rec.Name }
    else {
        $tn = Test-DriveName $name
        if (-not $tn.Ok) { $res.Why = [string]$tn.Why; return $res }
        $nm = [string]$tn.Name
    }
    $now = Get-DriveNow
    $newReg = $null
    if (-not $rec) {
        $nrec = @{ Name = $nm; Conn = $conn; Id = (New-DriveId 'L'); Created = $now; From = ''; At = '' }
        if ($from) { $nrec.From = $from; $nrec.At = $now }
        $list = @(); if ($script:DriveReg) { $list = @($script:DriveReg.GetEnumerator() | ForEach-Object { $_.Value }) }
        try { $newReg = New-DriveRegTable (@($list) + @($nrec)) } catch { $res.Why = ((T 'Un lecteur enregistré porte déjà ce nom : {0}.') -f $nm); return $res }
    }
    if ($from) {
        $chk = Edit-DriveData $from $nm -Check
        if (-not $chk.Ok) { $res.Why = [string]$chk.Why; return $res }
        $pr = Protect-DriveData @($from)
        if (-not $pr.Ok) { $res.Why = [string]$pr.Why; return $res }
        $ed = Edit-DriveData $from $nm
        if (-not $ed.Ok) { $res.Why = [string]$ed.Why; return $res }
        $res.N = [int]$ed.N; $res.Bak = [string]$pr.Bak; $res.Copy = [bool]$pr.Copy
    }
    if ($rec) { $rec.Conn = $conn; $rec.From = $from; $rec.At = $now }
    else { $script:DriveReg = $newReg }
    if ($script:DriveChecked -and ([string]$script:DriveChecked -eq $nm -or [string]$script:DriveChecked -eq $from)) { $script:DriveChecked = '' }
    Sync-PrecompCurves
    $res.Ok = $true; $res.Name = $nm
    return $res
}

function Rename-NamedDrive([string]$old, [string]$new) {
    # 12.11 : renomme un lecteur enregistre : ses donnees passent sous le nouveau nom (copie datee d abord, des qu il en
    # a une), la fiche garde son identifiant et son rang ; une correction de casse est un renommage comme un autre. Le
    # registre est reconstruit (la fiche sous l autre casse, affectee puis retiree en place, serait videe). Rend
    # @{ Ok ; Why ; Name ; N ; Bak ; Copy }
    $res = @{ Ok = $false; Why = ''; Name = ''; N = 0; Bak = ''; Copy = $false }
    $why = Get-DriveEditRefusal
    if ($why) { $res.Why = $why; return $res }
    $rec = Get-DriveRecord $old
    if (-not $rec) { return $res }
    $cur = [string]$rec.Name
    $tn = Test-DriveName $new $cur
    if (-not $tn.Ok) { $res.Why = [string]$tn.Why; return $res }
    $nm = [string]$tn.Name
    $res.Name = $nm
    if ($nm -ceq $cur) { $res.Ok = $true; return $res }
    $nrec = @{}
    foreach ($e in @($rec.GetEnumerator())) { $nrec[[string]$e.Key] = $e.Value }
    $nrec.Name = $nm
    $newReg = $null
    try { $newReg = New-DriveRegTable @($script:DriveReg.GetEnumerator() | ForEach-Object { if ([object]::ReferenceEquals($_.Value, $rec)) { $nrec } else { $_.Value } }) }
    catch { $res.Why = ((T 'Un lecteur enregistré porte déjà ce nom : {0}.') -f $nm); return $res }
    $chk = Edit-DriveData $cur $nm -Check
    if (-not $chk.Ok) { $res.Why = [string]$chk.Why; return $res }
    $pr = Protect-DriveData @($cur)
    if (-not $pr.Ok) { $res.Why = [string]$pr.Why; return $res }
    $ed = Edit-DriveData $cur $nm
    if (-not $ed.Ok) { $res.Why = [string]$ed.Why; return $res }
    $script:DriveReg = $newReg
    if ($script:DriveChecked -and ([string]$script:DriveChecked -eq $cur -or [string]$script:DriveChecked -eq $nm)) { $script:DriveChecked = '' }
    Sync-PrecompCurves
    $res.Ok = $true; $res.N = [int]$ed.N; $res.Bak = [string]$pr.Bak; $res.Copy = [bool]$pr.Copy
    return $res
}

function Move-NamedDrive([string]$name, [string]$conn) {
    # 12.11 : change la connexion de la fiche et retire de $script:DriveLast toute entree qui cite ce lecteur ; aucune
    # cle, aucun champ de donnee : les calibrations suivent le nom. Rend @{ Ok ; Why ; Name ; Old (connexion d avant) }
    $res = @{ Ok = $false; Why = ''; Name = ''; Old = '' }
    $why = Get-DriveEditRefusal
    if ($why) { $res.Why = $why; return $res }
    $rec = Get-DriveRecord $name
    if (-not $rec) { return $res }
    if (-not (Test-DriveConnCode $conn)) { $res.Why = (T 'Choisissez la connexion du lecteur.'); return $res }
    $nm = [string]$rec.Name
    $nLast = @{}
    if ($script:DriveLast) { foreach ($e in @($script:DriveLast.GetEnumerator())) { if ([string]$e.Value -ne $nm) { $nLast.Add([string]$e.Key, [string]$e.Value) } } }
    $res.Old = [string]$rec.Conn
    $rec.Conn = $conn
    $script:DriveLast = $nLast
    if ($script:DriveChecked -and [string]$script:DriveChecked -eq $nm) { $script:DriveChecked = '' }
    Sync-PrecompCurves
    $res.Ok = $true; $res.Name = $nm
    return $res
}

function Remove-NamedDrive([string]$name, [switch]$KeepData) {
    # 12.11 : supprime la fiche et ce qui est range sous le nom : ses courbes, les courbes croisees dont il est la
    # source ou la cible, ses niveaux, sa memoire par marque, ses facteurs, son lecteur cible et le choix de ce lecteur
    # comme cible d un autre (copie datee obligatoire d abord, des qu il a une donnee : sans elle, rien n est supprime).
    # -KeepData : retire seulement le nom ; ses donnees vont sous le code de la connexion de sa fiche, la forme qu une
    # 12.10 retrouve ; refus si ce code porte deja une donnee ou si la fiche n a pas de connexion. Rend
    # @{ Ok ; Why ; Name ; Conn ; N ; Bak ; Copy }
    $res = @{ Ok = $false; Why = ''; Name = ''; Conn = ''; N = 0; Bak = ''; Copy = $false }
    $why = Get-DriveEditRefusal
    if ($why) { $res.Why = $why; return $res }
    $rec = Get-DriveRecord $name
    if (-not $rec) { return $res }
    $nm = [string]$rec.Name; $conn = [string]$rec.Conn
    $to = ''
    if ($KeepData) {
        if (-not (Test-DriveConnCode $conn)) { $res.Why = (T 'Choisissez la connexion du lecteur.'); return $res }
        $to = $conn
    }
    $newReg = New-DriveRegTable @($script:DriveReg.GetEnumerator() | ForEach-Object { if (-not [object]::ReferenceEquals($_.Value, $rec)) { $_.Value } })
    $chk = Edit-DriveData $nm $to -Check
    if (-not $chk.Ok) { $res.Why = [string]$chk.Why; return $res }
    $pr = Protect-DriveData @($nm)
    if (-not $pr.Ok) { $res.Why = [string]$pr.Why; return $res }
    $ed = Edit-DriveData $nm $to
    if (-not $ed.Ok) { $res.Why = [string]$ed.Why; return $res }
    $script:DriveReg = $newReg
    if ($script:DriveChecked -and [string]$script:DriveChecked -eq $nm) { $script:DriveChecked = '' }
    Sync-PrecompCurves
    $res.Ok = $true; $res.Name = $nm; $res.Conn = $conn; $res.N = [int]$ed.N; $res.Bak = [string]$pr.Bak; $res.Copy = [bool]$pr.Copy
    return $res
}

function Get-DriveField($o, [string]$name) {
    # 12.11 : champ d un bloc de la configuration, lu dans un objet de ConvertFrom-Json ou dans une table (bloc rendu par
    # Export-DriveRegistry) ; $null s il est absent. Table : par enumeration, sans index (une connexion « 0 » ne doit pas
    # etre prise pour un rang)
    if ($null -eq $o -or $o -is [string] -or $o -is [ValueType] -or $o -is [array]) { return $null }
    if ($o -is [System.Collections.IDictionary]) {
        foreach ($e in @($o.GetEnumerator())) { if ([string]$e.Key -eq $name) { return $e.Value } }
        return $null
    }
    $p = $o.PSObject.Properties[$name]
    if ($null -ne $p) { return $p.Value }
    return $null
}

function Get-DriveBlockItems($block) {
    # 12.11 : entrees de la liste d un bloc drives, une a une : @{ Id ; Name ; Conn ; Created ; From ; At }, textes
    # bruts ; une entree qui n est pas un objet est rendue sans nom (elle sera comptee illisible)
    foreach ($it in @(Get-DriveField $block 'list')) {
        if ($null -eq $it) { continue }
        @{ Id = [string](Get-DriveField $it 'id'); Name = [string](Get-DriveField $it 'name'); Conn = [string](Get-DriveField $it 'conn')
           Created = [string](Get-DriveField $it 'created'); From = [string](Get-DriveField $it 'from'); At = [string](Get-DriveField $it 'at') }
    }
}

function Get-DriveRescuePath {
    # 12.11 : copie de secours du registre, a cote du fichier de configuration : <fichier>.lecteurs (son nom ne finit pas
    # par .bak : ni la rotation des copies, ni leur lecture ne la voient)
    $c = [string]$script:ConfigFile
    if (-not $c) { return '' }
    return ($c + '.lecteurs')
}

function Get-DriveTargetPairs {
    # 12.11 : couples « source, cible » des lecteurs cibles dont l un au moins est un lecteur enregistre, sources
    # triees, un a un : @{ Src ; Tgt }. Une version anterieure, qui ne connait pas les noms, les retire a son premier
    # enregistrement : la copie de secours les garde
    if ($null -eq $script:TargetDrives) { return }
    foreach ($s in @($script:TargetDrives.GetEnumerator() | ForEach-Object { [string]$_.Key } | Sort-Object)) {
        $t = Get-TargetDrive $s
        if ($t -and ((Test-DriveRegistered $s) -or (Test-DriveRegistered $t))) { @{ Src = $s; Tgt = [string]$t } }
    }
}

function Get-DriveRescueText($items, $last, $pairs) {
    # 12.11 : contenu utile de la copie de secours (fiches, dernier lecteur par connexion, couples de lecteurs cibles),
    # en un texte de forme fixe, sans _saved : la copie n est reecrite que s il change
    $l = @()
    foreach ($it in @($items)) { if ($it) { $l += ,([ordered]@{ id = [string]$it.Id; name = [string]$it.Name; conn = [string]$it.Conn; created = [string]$it.Created; from = [string]$it.From; at = [string]$it.At }) } }
    $la = [ordered]@{}
    foreach ($c in $script:SettingDefs['drive'].Codes) { $v = [string](Get-DriveField $last ([string]$c)); if ($v) { $la.Add([string]$c, $v) } }
    $tg = @()
    foreach ($p in @($pairs)) { if ($p) { $tg += ,([ordered]@{ source = [string]$p.Src; target = [string]$p.Tgt }) } }
    return (([ordered]@{ drives = [ordered]@{ list = $l; last = $la }; targets = $tg }) | ConvertTo-Json -Depth 6 -Compress)
}

function Read-DriveRescue {
    # 12.11 : copie de secours du registre : @{ Found ; Ok ; Path ; Items (fiches brutes) ; Last ; Pairs (@{ Src ; Tgt }) ;
    # Text (contenu utile, Get-DriveRescueText) ; Why (fichier illisible) }. Elle ne porte aucune courbe
    $p = Get-DriveRescuePath
    $res = @{ Found = $false; Ok = $false; Path = $p; Items = @(); Last = $null; Pairs = @(); Text = $null; Why = '' }
    if (-not $p -or -not (Test-Path -LiteralPath $p -PathType Leaf)) { return $res }
    $res.Found = $true
    try {
        $o = Get-Content -LiteralPath $p -Raw -Encoding UTF8 -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
        $blk = Get-DriveField $o 'drives'
        $items = @(Get-DriveBlockItems $blk)
        $last = Get-DriveField $blk 'last'
        $pairs = @()
        foreach ($t in @(Get-DriveField $o 'targets')) {
            $s = [string](Get-DriveField $t 'source'); $g = [string](Get-DriveField $t 'target')
            if ($s -and $g) { $pairs += ,@{ Src = $s; Tgt = $g } }
        }
        $res.Items = $items; $res.Last = $last; $res.Pairs = $pairs
        $res.Text = Get-DriveRescueText $items $last $pairs
        $res.Ok = $true
    } catch { $res.Why = ([string]$_.Exception.Message).Trim() }
    return $res
}

function Save-DriveRescue($block) {
    # 12.11 : copie de secours du registre, ecrite par Save-Config apres l ecriture reussie du fichier principal :
    # { _comment, _saved, version, drives, targets }. Ecrite seulement quand son contenu utile differe du dernier lu ou
    # ecrit ($script:DriveRescueText) : Save-Config precede chaque commande gw. Registre devenu vide : reecrite avec une
    # liste vide, jamais supprimee ; registre vide et copie ni lue ni ecrite dans la session : aucun fichier n est cree
    # ni touche. Echec : une ligne de journal, l enregistrement de la configuration reste reussi. Rend vrai si la copie a
    # ete ecrite
    if ($null -eq $block) { return $false }
    $p = Get-DriveRescuePath
    if (-not $p) { return $false }
    $items = @(Get-DriveBlockItems $block)
    if ($items.Count -eq 0 -and $null -eq $script:DriveRescueText) { return $false }
    $pairs = @(Get-DriveTargetPairs)
    $txt = Get-DriveRescueText $items (Get-DriveField $block 'last') $pairs
    if ($null -ne $script:DriveRescueText -and $txt -ceq [string]$script:DriveRescueText) { return $false }
    try {
        $o = [ordered]@{
            _comment = (T 'Copie de secours des lecteurs enregistrés de Greaseweazle Studio (noms, connexions, lecteurs cibles) - régénérée automatiquement.')
            _saved   = (Get-DriveNow)
            version  = [string]$script:Version
            drives   = $block
            targets  = @($pairs | ForEach-Object { [ordered]@{ source = [string]$_.Src; target = [string]$_.Tgt } })
        }
        $o | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath $p -Encoding UTF8 -ErrorAction Stop
        $script:DriveRescueText = $txt
        return $true
    } catch {
        Append-Log ((T 'Copie de secours des lecteurs enregistrés non écrite ({0}) : {1}') -f "$p", "$(([string]$_.Exception.Message).Trim())")
        return $false
    }
}

function Export-DriveRegistry {
    # 12.11 : bloc drives de la configuration : { list : fiches dans l ordre du registre ; last : dernier lecteur
    # enregistre choisi par connexion }. $null avec un registre vide : qui n a jamais enregistre de lecteur garde un
    # fichier aux cles exactes de la 12.10. Bloc a liste vide dans deux cas : l enregistrement que Protect-DriveData fait
    # avant sa copie ($script:DriveBlockKeep), et tant qu une copie de secours a ete lue ou ecrite dans la session
    # ($script:DriveRescueText) : un bloc present fait foi, liste vide comprise
    $recs = @()
    if ($script:DriveReg) { $recs = @($script:DriveReg.GetEnumerator() | ForEach-Object { $_.Value }) }
    if ($recs.Count -eq 0 -and -not $script:DriveBlockKeep -and $null -eq $script:DriveRescueText) { return $null }
    $list = @()
    foreach ($r in $recs) { $list += ,([ordered]@{ id = [string]$r.Id; name = [string]$r.Name; conn = [string]$r.Conn; created = [string]$r.Created; from = [string]$r.From; at = [string]$r.At }) }
    $last = [ordered]@{}
    foreach ($c in $script:SettingDefs['drive'].Codes) { $l = Get-DriveForConn ([string]$c); if ($l -cne [string]$c) { $last.Add([string]$c, $l) } }
    return [ordered]@{ list = $list; last = $last }
}

function Import-DriveRegistry($cfg, $old = $null) {
    # 12.11 : bloc drives de la configuration -> registre ($script:DriveReg, $script:DriveLast, vides d abord). Un bloc
    # present fait foi, liste vide comprise. Bloc absent (fichier enregistre par une version anterieure, ou copie datee
    # plus ancienne remise a sa place : rien ne les distingue) : registre relu dans la copie de secours si elle a des
    # fiches ; $script:DriveRescued, et ses couples de lecteurs cibles en attente ($script:DriveRescuePairs,
    # Restore-DriveRescueTargets). La copie de secours est toujours lue, pour la comparaison de Save-DriveRescue.
    # Jamais d erreur : entree au nom refuse (regles de structure, mots reserves compris), doublon a la casse pres ou
    # identifiant en double : ignoree et comptee (la premiere est gardee) ; identifiant absent ou d une autre forme :
    # fiche gardee avec un identifiant « R... » neuf ; connexion qui n est ni vide ni exactement un des six codes : fiche
    # gardee sans connexion, avec son identifiant. last : ramene au nom de la fiche, a sa casse ; registre relu dans la
    # copie de secours : retenu pour une connexion seulement si le lecteur nomme a une courbe ($old : courbes en attente
    # du choix), ou si le lecteur non enregistre de cette connexion n en a aucune (le bandeau reste sinon sur le lecteur
    # qui porte les courbes)
    $script:DriveReg = [ordered]@{}; $script:DriveLast = @{}; $script:DriveRescuePairs = $null
    $rs = Read-DriveRescue
    $script:DriveRescueText = $(if ($rs.Ok) { [string]$rs.Text } else { $null })
    $blk = Get-DriveField $cfg 'drives'
    $fromRescue = $false
    if ($null -eq $blk) {
        if ($rs.Found -and -not $rs.Ok) { Append-Log ((T 'Copie de secours des lecteurs enregistrés illisible ({0}) : {1}') -f "$($rs.Path)", "$($rs.Why)"); return }
        if (-not $rs.Ok -or @($rs.Items).Count -eq 0) { return }
        $fromRescue = $true
    }
    $items = @(); $lastRaw = $null
    if ($fromRescue) { $items = @($rs.Items); $lastRaw = $rs.Last } else { $items = @(Get-DriveBlockItems $blk); $lastRaw = Get-DriveField $blk 'last' }
    $now = Get-DriveNow
    $bad = 0; $noConn = @(); $ids = @{}; $recs = @()
    foreach ($it in $items) {
        $tn = Test-DriveName ([string]$it.Name) '' -Load
        if (-not $tn.Ok) { $bad++; continue }
        $id = [string]$it.Id
        if ($id -cnotmatch '^[LR]\d{14}-\d{2}$') { $id = '' }
        elseif ($ids.ContainsKey($id)) { $bad++; continue }
        $conn = [string]$it.Conn
        if ($conn -and -not (Test-DriveConnCode $conn)) { $conn = ''; $noConn += [string]$tn.Name }
        $created = [string]$it.Created
        if ((ConvertTo-DriveDate $created) -eq [datetime]::MinValue) { $created = $now }
        $from = [string]$it.From; $at = [string]$it.At
        if (-not (Test-DriveConnCode $from) -or (ConvertTo-DriveDate $at) -eq [datetime]::MinValue) { $from = ''; $at = '' }
        $rec = @{ Name = [string]$tn.Name; Conn = $conn; Id = $id; Created = $created; From = $from; At = $at }
        $tbl = $null
        try { $tbl = New-DriveRegTable (@($recs) + @($rec)) } catch { $bad++; continue }
        $recs += ,$rec
        $script:DriveReg = $tbl
        if ($id) { $ids[$id] = $true }
    }
    foreach ($rec in $recs) { if (-not [string]$rec.Id) { $rec.Id = New-DriveId 'R' } }
    if ($bad -gt 0) { Append-Log ((T 'Lecteurs enregistrés : {0} fiche(s) illisible(s), ignorée(s).') -f "$bad") }
    if ($noConn.Count -gt 0) { Append-Log ((T 'Lecteurs enregistrés : connexion illisible pour {0} : redonnez-la dans « Lecteurs enregistrés » (Accueil).') -f ($noConn -join ', ')) }
    $nLast = @{}
    foreach ($c in $script:SettingDefs['drive'].Codes) {
        $r = Get-DriveRecord ([string](Get-DriveField $lastRaw ([string]$c)))
        if (-not $r -or [string]$r.Conn -cne [string]$c) { continue }
        if ($fromRescue) {
            $dn = Get-DriveData ([string]$r.Name) $old; $dc = Get-DriveData ([string]$c) $old
            if ((@($dn['Keys']).Count + @($dn['Cross']).Count) -eq 0 -and (@($dc['Keys']).Count + @($dc['Cross']).Count) -gt 0) { continue }
        }
        $nLast.Add([string]$c, [string]$r.Name)
    }
    $script:DriveLast = $nLast
    if ($fromRescue) { $script:DriveRescued = $true; $script:DriveRescuePairs = @($rs.Pairs) }
}

function Get-DriveIdentities($old = $null, $targets = $null) {
    # 12.11 : identites citees par les porteurs que lit Get-DriveData, une a une, sans doublon : cles du magasin et
    # courbes en attente du choix ($old pendant Load-Config), la source et la cible d une cle croisee, champ Drive des
    # niveaux, de la memoire par marque et des facteurs mesures, sources et cibles des lecteurs cibles ($targets : bloc
    # targetDrive brut de la configuration, lu avant qu Import-TargetDrives ecarte les lecteurs inconnus)
    $seen = @{}
    $all = @()
    $oc = $script:OldCalib
    $tabs = @()
    if ($null -ne $script:DriveCurves) { $tabs += ,$script:DriveCurves }
    if ($null -ne $old) { $tabs += ,$old } elseif ($oc -and $null -ne $oc.Curves) { $tabs += ,$oc.Curves }
    foreach ($tb in $tabs) {
        foreach ($e in @($tb.GetEnumerator())) {
            $d = [string](Split-DriveCurveKey ([string]$e.Key)).Drive
            $x = Split-CrossDrive $d
            if ($x) { $all += [string]$x.Src; $all += [string]$x.Tgt } else { $all += $d }
        }
    }
    if ($null -ne $script:LevelShifts) { foreach ($e in @($script:LevelShifts.GetEnumerator())) { if ($e.Value) { $all += [string]$e.Value.Drive } } }
    if ($null -eq $old -and $oc -and $null -ne $oc.Levels) { foreach ($e in @($oc.Levels.GetEnumerator())) { if ($e.Value) { $all += [string]$e.Value.Drive } } }
    foreach ($en in @($script:LevelBrands)) { if ($en) { $all += [string]$en.Drive } }
    foreach ($rec in @($script:ContentMeasures)) { if ($rec) { $all += [string]$rec.Drive } }
    if ($null -ne $script:TargetDrives) { foreach ($e in @($script:TargetDrives.GetEnumerator())) { $all += [string]$e.Key; $all += [string]$e.Value } }
    if ($null -ne $targets -and $targets -isnot [string] -and $targets -isnot [ValueType] -and $targets -isnot [array]) {
        # 12.11 (relecture de LN-a) : espaces des bords retires ici seulement, comme Import-TargetDrives les retire
        if ($targets -is [System.Collections.IDictionary]) { foreach ($e in @($targets.GetEnumerator())) { $all += ([string]$e.Key).Trim(); $all += ([string]$e.Value).Trim() } }
        else { foreach ($p in @($targets.PSObject.Properties)) { $all += ([string]$p.Name).Trim(); $all += ([string]$p.Value).Trim() } }
    }
    foreach ($a in $all) {
        $s = [string]$a   # 12.11 : identite telle que la donnee la porte (Get-DriveData compare sans retirer d espace)
        if (-not $s.Trim() -or $seen.ContainsKey($s)) { continue }
        $seen[$s] = $true
        $s
    }
}

function Repair-DriveRegistry($old = $null, $targets = $null) {
    # 12.11 : une identite sans fiche n est jamais devinee : tout nom admis trouve dans un porteur (Get-DriveIdentities)
    # sans etre ni une connexion ni une fiche recoit une fiche sans connexion, d identifiant « R... » ; elle n est pas
    # proposee dans le bandeau et ses calibrations ne servent a aucun autre lecteur tant que sa connexion n est pas
    # rendue. Un nom que refusent les regles de structure (mot reserve compris) ne recoit pas de fiche : ses donnees
    # restent en memoire, hors de toute vue. Une configuration dont tous les porteurs citent une connexion (12.10) ne
    # donne aucune fiche et aucune ligne. Rend les noms qui ont recu une fiche, un a un
    $names = @(); $refused = @()
    $recs = @(); if ($script:DriveReg) { $recs = @($script:DriveReg.GetEnumerator() | ForEach-Object { $_.Value }) }
    $now = Get-DriveNow
    foreach ($d in @(Get-DriveIdentities $old $targets)) {
        if ((Test-DriveConnCode $d) -or (Test-DriveRegistered $d)) { continue }
        $tn = Test-DriveName $d '' -Load
        if (-not $tn.Ok) { $refused += $d; continue }
        $rec = @{ Name = [string]$tn.Name; Conn = ''; Id = (New-DriveId 'R'); Created = $now; From = ''; At = '' }
        $tbl = $null
        try { $tbl = New-DriveRegTable (@($recs) + @($rec)) } catch { $refused += $d; continue }
        $recs += ,$rec
        $script:DriveReg = $tbl
        $names += [string]$tn.Name
    }
    if ($names.Count -gt 0) { Append-Log ((T "Lecteurs présents dans les calibrations, sans fiche : {0}. Redonnez leur connexion dans « Lecteurs enregistrés » (Accueil) ; d'ici là, ils ne sont pas proposés dans le bandeau et leurs calibrations ne servent à aucun autre lecteur.") -f ($names -join ', ')) }
    if ($refused.Count -gt 0) { Append-Log ((T 'Calibrations rangées sous un nom de lecteur non admis ({0}) : elles ne servent à aucun lecteur.') -f ($refused -join ', ')) }
    foreach ($nm in $names) { $nm }
}

function Restore-DriveRescueTargets($old = $null) {
    # 12.11 : apres Import-TargetDrives, quand le registre vient d etre relu dans la copie de secours : retablit par
    # Set-TargetDrive chaque couple de la copie dont la source n a pas de lecteur cible aujourd hui et dont les deux
    # lecteurs sont connus (Get-DriveIds) ; un couple dont la source a un autre lecteur cible n est pas touche. Puis une
    # ligne de journal qui dit ce qui a ete trouve, fiche par fiche (Get-DriveDataText, « aucune » comprise), sans
    # affirmer ni la cause de l absence du bloc, ni que les calibrations sont intactes. Rend les couples retablis, un a
    # un : @{ Src ; Tgt }. Le couple d une fiche relue sans aucune courbe est retabli aussi : ce lecteur cible est alors sa
    # seule donnee, et nommer de ce nom le lecteur d une connexion pour lui rendre ses courbes est refuse (Edit-DriveData,
    # texte qui cite le lecteur cible) tant que ce choix reste
    $pairs = $script:DriveRescuePairs
    if ($null -eq $pairs) { return }
    $script:DriveRescuePairs = $null
    $done = @()
    $ids = Get-DriveIds                    # tableau protege par la virgule : pas de @() autour de l appel
    foreach ($p in @($pairs)) {
        if (-not $p) { continue }
        $s = [string]$p.Src; $t = [string]$p.Tgt
        if (-not $s -or -not $t -or $s -eq $t -or $ids -notcontains $s -or $ids -notcontains $t) { continue }
        if (Get-TargetDrive $s) { continue }
        [void](Set-TargetDrive $s $t)
        $done += ,@{ Src = $s; Tgt = $t }
    }
    $cal = @()
    if ($script:DriveReg) { foreach ($e in @($script:DriveReg.GetEnumerator())) { $cal += ((T '{0} : {1}') -f [string]$e.Value.Name, (Get-DriveDataText (Get-DriveData ([string]$e.Value.Name) $old))) } }
    $tg = if ($done.Count -gt 0) { (@($done | ForEach-Object { "$($_.Src) → $($_.Tgt)" }) -join ', ') } else { (T 'aucun') }
    Append-Log ((T "Lecteurs enregistrés relus dans la copie de secours ({0}) : le fichier de configuration ne les contenait pas (enregistré par une version antérieure, ou copie plus ancienne remise à sa place). Calibrations rangées sous leurs noms : {1}. Lecteurs cibles rétablis depuis cette copie : {2}. Vérifiez le lecteur choisi et son lecteur cible avant d'écrire.") -f "$(Get-DriveRescuePath)", ($cal -join ' ; '), $tg)
    foreach ($d in $done) { $d }
}

function Resolve-DriveOfEra([string]$drive, $eraBlock, [datetime]$when) {
    # 12.11 (pour le retour a une calibration precedente, lot L7) : lecteur d aujourd hui d une courbe lue dans une copie
    # datee de la configuration. $drive : identite lue dans la copie (les deux cotes d une cle croisee se resolvent l un
    # apres l autre) ; $eraBlock : bloc drives de la copie, $null si elle n en a pas ; $when : date de la courbe. Jamais
    # un rang ni un compteur : un identifiant de fiche est date et n est jamais reattribue. Rend @{ Drive (identite
    # d aujourd hui ; '' : aucun lecteur, la courbe ne peut pas etre retablie) ; Era ($drive) ; Sure ; Why } :
    #   id         nom dont la copie a la fiche, et une fiche d aujourd hui porte le meme identifiant (renommee ou non)
    #   ambiguous  meme cas, mais le nom de l epoque est aujourd hui celui d une autre fiche : aucun lecteur
    #   deleted    aucune fiche d aujourd hui pour ce nom ou cet identifiant (lecteur supprime depuis, meme recree sous
    #              le meme nom : sa fiche « L... » est une autre) : aucun lecteur
    #   name       nom sans fiche dans la copie (ou fiche d aujourd hui « R... », refaite d apres les donnees) : la fiche
    #              de ce nom, creee avant la courbe
    #   name-after meme cas, fiche creee apres la courbe : Sure faux
    #   conn-named connexion dont une fiche d aujourd hui a recu les calibrations (From) apres la date de la courbe (la
    #              premiere attribution posterieure, s il y en a plusieurs) : cette fiche, Sure faux
    #   conn       connexion sans attribution posterieure : le lecteur non enregistre de cette connexion
    $res = @{ Drive = ''; Era = $drive; Sure = $false; Why = 'deleted' }
    if (-not $drive) { return $res }
    $recs = @(); if ($script:DriveReg) { $recs = @($script:DriveReg.GetEnumerator() | ForEach-Object { $_.Value }) }
    if (Test-DriveConnCode $drive) {
        $best = $null; $bestAt = [datetime]::MaxValue
        foreach ($r in $recs) {
            if ([string]$r.From -cne $drive) { continue }
            $at = ConvertTo-DriveDate ([string]$r.At)
            if ($at -ne [datetime]::MinValue -and $at -gt $when -and $at -lt $bestAt) { $best = $r; $bestAt = $at }
        }
        if ($best) { $res.Drive = [string]$best.Name; $res.Why = 'conn-named'; return $res }
        $res.Drive = $drive; $res.Sure = $true; $res.Why = 'conn'
        return $res
    }
    $eraId = ''
    foreach ($it in @(Get-DriveBlockItems $eraBlock)) { if ([string]$it.Name -eq $drive) { $eraId = [string]$it.Id; break } }
    $today = Get-DriveRecord $drive
    if ($eraId -cmatch '^[LR]\d{14}-\d{2}$') {
        $byId = $null
        foreach ($r in $recs) { if ([string]$r.Id -ceq $eraId) { $byId = $r; break } }
        if ($byId) {
            if ($today -and [string]$today.Id -cne $eraId) { $res.Why = 'ambiguous'; return $res }
            $res.Drive = [string]$byId.Name; $res.Sure = $true; $res.Why = 'id'
            return $res
        }
        if (-not $today -or [string]$today.Id -cnotlike 'R*') { return $res }
    }
    if (-not $today) { return $res }
    $res.Drive = [string]$today.Name
    $cr = ConvertTo-DriveDate ([string]$today.Created)
    if ($cr -ne [datetime]::MinValue -and $cr -le $when) { $res.Sure = $true; $res.Why = 'name' } else { $res.Why = 'name-after' }
    return $res
}

# ============================== LN-b : INTERFACE DES LECTEURS ENREGISTRES =======
# 12.11 (lot LN-b) : liste « Lecteur : » du bandeau (les six connexions, puis les lecteurs enregistres qui ont une
# connexion) et ses deux dispositions, liaison au reglage drive (Sync-DriveCombo, 120), lecteur a confirmer, confirmation
# du lecteur branche dans les cinq fonctions qui engagent une operation sous l identite du lecteur (Start-ImageWrite,
# Start-LevelCalib, Start-PrecompCalib, Start-ContentMeasure, Start-Restore) et du lecteur cible d une calibration
# croisee (Start-CrossCalib), verrou de la liste pendant une operation, fenetre « Lecteurs enregistres » (frmDrives), qui
# affiche et transmet les gestes : Get-DriveEditPlan et Get-DriveDeletePlan decident et donnent les textes. Sans lecteur
# enregistre, le code de la 12.10 n appelle que Update-DriveChoice (gestionnaire du bandeau : lecteur courant retenu),
# Set-DriveHandChoice (choix a la main), Update-DriveLock (verrou, voulu pour tous) et la carte de l Accueil
# (Get-DrivesCardText, Show-DrivesDialog, 540) : bandeau, textes, journal, configuration et arguments de gw restent ceux
# de la 12.10.

function Get-WriteSourceText {
    # 12.11 (lot LN-b) : seule source du texte « Lecteur qui ecrit : TEAC FD-235HF (A) » (lecteur non enregistre :
    # « Lecteur qui ecrit : A ») : journal de chaque ecriture (Confirm-DriveIdentity -Write) ; libelle de l onglet Ecriture
    # et tete de la ligne « Ce qui va se passer » (lots L9 et L10)
    return ((T 'Lecteur qui écrit : {0}') -f (Get-DriveLabel ([string]$cmbDrive.Text)))
}

function Format-ConnDrives($drives) {
    # 12.11 (lot LN-b) : lecteurs d une connexion en texte (Get-ConnDrives, cibles ecartees d une calibration croisee) :
    # le nom d un lecteur enregistre, « A (non enregistre) » pour un lecteur non enregistre
    $l = @()
    foreach ($d in @($drives)) { if ($d) { $l += $(if (Test-DriveConnCode ([string]$d)) { (T '{0} (non enregistré)') -f [string]$d } else { [string]$d }) } }
    return ($l -join ', ')
}

function Get-DriveListItems {
    # 12.11 (lot LN-b) : elements voulus de la liste du bandeau : les six connexions, puis les lecteurs enregistres qui ont
    # une connexion, dans l ordre du registre (une fiche sans connexion n y est pas : ses courbes ne servent a aucun
    # lecteur tant que sa connexion n est pas rendue). Tableau protege par la virgule (pas de @() autour de l appel)
    $l = @([string[]]$script:SettingDefs['drive'].Codes)
    if ($script:DriveReg) { foreach ($e in @($script:DriveReg.GetEnumerator())) { if ([string]$e.Value.Conn) { $l += [string]$e.Value.Name } } }
    return ,@($l)
}

function Get-DrivesCardText {
    # 12.11 (lot LN-b) : description de la carte « Lecteurs enregistres » de l Accueil (540) : fiches sans connexion
    # comptees (leurs courbes ne servent a aucun lecteur), sinon le texte d origine
    $n = 0
    if ($script:DriveReg) { $n = @($script:DriveReg.GetEnumerator() | Where-Object { -not [string]$_.Value.Conn }).Count }
    if ($n -gt 0) { return ((T '{0} lecteur(s) sans connexion : redonnez-la ici pour retrouver leurs calibrations.') -f "$n") }
    return (T 'Nommer vos lecteurs : plusieurs sur une même connexion, chacun avec ses calibrations.')
}

function Update-DrivesCard {
    # 12.11 (lot LN-b) : texte de la carte « Lecteurs enregistres » (Get-DrivesCardText)
    if (-not $cardDrives) { return }
    $t = Get-DrivesCardText
    if ([string]$cardDrives.Controls[3].Text -cne $t) { $cardDrives.Controls[3].Text = $t }
}

function Update-DriveList([string]$Select = '') {
    # 12.11 (lot LN-b) : elements de la liste du bandeau (Get-DriveListItems) et lecteur choisi : $Select (un element de
    # la liste) s il est donne, sinon le choix garde s il existe encore, sinon le lecteur retenu pour la connexion du
    # reglage (Get-DriveForConn). Ordre impose : element choisi ajoute s il manque, puis choisi (le gestionnaire du
    # bandeau, 520, s execute avec le lecteur final), puis seulement les autres elements retires et remis dans l ordre du
    # registre : le choix n est jamais retire, le texte de la liste n est jamais vide (le gestionnaire n a aucune garde sur
    # un texte vide). Une liste sans poignee (fenetre pas encore affichee, tests) ne deplace pas son choix quand un element
    # est insere avant lui : le choix est repris a la fin, sans changement de texte. Liaisons des reglages gardees pendant
    # la mise a jour, puis reglage drive ramene a la connexion du lecteur choisi ; disposition du bandeau et carte de
    # l Accueil
    $want = Get-DriveListItems
    $nc = @($script:SettingDefs['drive'].Codes).Count
    $cur = [string]$cmbDrive.Text
    $sel = ''
    if ($Select -and $want -ccontains $Select) { $sel = $Select }
    elseif ($cur -and $want -ccontains $cur) { $sel = $cur }
    else { $sel = Get-DriveForConn ([string](Get-Setting 'drive')); if ($want -cnotcontains $sel) { $sel = [string]$want[0] } }
    $have = @($cmbDrive.Items | ForEach-Object { [string]$_ })
    $sv = $script:SettingSync; $script:SettingSync = $true
    try {
        if (($have -join "`n") -cne ($want -join "`n")) {
            if ($have -cnotcontains $sel) { [void]$cmbDrive.Items.Add($sel) }
            if ([string]$cmbDrive.SelectedItem -cne $sel) { $cmbDrive.SelectedItem = $sel }
            for ($i = $cmbDrive.Items.Count - 1; $i -ge $nc; $i--) { if ([string]$cmbDrive.Items[$i] -cne $sel) { $cmbDrive.Items.RemoveAt($i) } }
            $at = $nc; $after = ([array]::IndexOf($want, $sel) -lt $nc)
            for ($i = $nc; $i -lt $want.Count; $i++) {
                $w = [string]$want[$i]
                if ($w -ceq $sel) { $after = $true; continue }
                if ($after) { [void]$cmbDrive.Items.Add($w) } else { $cmbDrive.Items.Insert($at, $w); $at++ }
            }
            if ([string]$cmbDrive.SelectedItem -cne $sel) { $cmbDrive.SelectedIndex = $cmbDrive.Items.IndexOf($sel) }
        } elseif ([string]$cmbDrive.SelectedItem -cne $sel) { $cmbDrive.SelectedItem = $sel }
    } finally { $script:SettingSync = $sv }
    $c = Get-DriveConn ([string]$cmbDrive.Text)
    if ($c -and [string](Get-Setting 'drive') -cne $c) { Set-Setting 'drive' $c $cmbDrive }
    Set-DriveBannerLayout
    Update-DrivesCard
}

function Set-DriveBannerLayout {
    # 12.11 (lot LN-b) : disposition du bandeau. Liste de six elements (aucun lecteur enregistre ayant une connexion) :
    # positions de la 12.10, au pixel pres, libelle « Lecteur : ». Sinon disposition elargie (maquette approuvee le
    # 13/11/2026) : liste de $script:DriveListWidth px (un nom admis s y affiche en entier : Test-DriveName), libelle
    # « Lecteur (A) : » pour un lecteur enregistre, « Lecteur : » pour un lecteur non enregistre, contre la liste ;
    # « COM : » et son champ decales vers le bord droit, « Chrono » remonte sur la rangee de l etat de gw ; « Aide » et
    # « Mode expert » 12 px a gauche du libelle le plus large (« Lecteur (X) : »), place fixe quel que soit le lecteur
    # choisi. Positions de la 12.10 relevees au premier appel (distance au bord droit du bandeau : controles ancres en
    # haut a droite), reprises pour revenir a la disposition de la 12.10 ; les positions elargies en derivent (ecarts de
    # la 12.10 gardes). Infobulle de la liste : celle de la 12.10, suivie des lecteurs enregistres et de leur connexion
    if (-not $cmbDrive -or -not $lblDrive -or -not $pnlTop) { return }
    $W = [int]$pnlTop.Width
    if (-not $script:DriveBanner) {
        $p0 = [ordered]@{}
        $all = [ordered]@{ lblGwStatus = $lblGwStatus; chkTime = $chkTime; txtDev = $txtDev; lblCom = $lblCom; cmbDrive = $cmbDrive; lblDrive = $lblDrive; btnHelpTop = $btnHelpTop; chkExpert = $chkExpert }
        foreach ($n in @($all.Keys)) {
            $c = $all[$n]
            if ($c) { $p0[$n] = @{ C = $c; R = ($W - [int]$c.Left); Top = [int]$c.Top; W = [int]$c.Width } }
        }
        $script:DriveBanner = @{ P = $p0; Tip = $(if ($tip) { [string]$tip.GetToolTip($cmbDrive) } else { '' }) }
    }
    $p = $script:DriveBanner.P
    $wide = ($cmbDrive.Items.Count -gt @($script:SettingDefs['drive'].Codes).Count)
    $d = [string]$cmbDrive.Text
    $lt = if ($wide -and (Test-DriveRegistered $d)) { (T 'Lecteur ({0}) :') -f (Get-DriveConn $d) } else { (T 'Lecteur :') }
    if ([string]$lblDrive.Text -cne $lt) { $lblDrive.Text = $lt }
    if (-not $wide) {
        foreach ($k in @($p.Keys)) {
            $x = $p[$k]
            $x.C.Location = New-Object System.Drawing.Point(($W - [int]$x.R), [int]$x.Top)
            if ($k -eq 'cmbDrive') { $x.C.Width = [int]$x.W }
        }
    } elseif ($p.Contains('chkTime') -and $p.Contains('txtDev') -and $p.Contains('lblCom') -and $p.Contains('cmbDrive')) {
        # Champ COM contre le bord droit de « Chrono » ; « COM : » et la liste a leurs ecarts de la 12.10
        $xR = $W - [int]$p['chkTime'].R + [int]$p['chkTime'].W
        $xDev = $xR - $txtDev.Width
        $xCom = $xDev - ([int]$p['lblCom'].R - [int]$p['txtDev'].R)
        $xCmb = $xCom - ([int]$p['cmbDrive'].R - [int]$p['lblCom'].R - [int]$p['cmbDrive'].W) - [int]$script:DriveListWidth
        $chkTime.Location = New-Object System.Drawing.Point(($W - [int]$p['chkTime'].R), 8)
        $txtDev.Location = New-Object System.Drawing.Point($xDev, [int]$p['txtDev'].Top)
        $lblCom.Location = New-Object System.Drawing.Point($xCom, [int]$p['lblCom'].Top)
        $cmbDrive.Width = [int]$script:DriveListWidth
        $cmbDrive.Location = New-Object System.Drawing.Point($xCmb, [int]$p['cmbDrive'].Top)
        $lblDrive.Location = New-Object System.Drawing.Point(($xCmb - $lblDrive.PreferredWidth), [int]$p['lblDrive'].Top)
        $wMax = 0
        foreach ($k in @($script:SettingDefs['drive'].Codes)) { $wk = [System.Windows.Forms.TextRenderer]::MeasureText(((T 'Lecteur ({0}) :') -f [string]$k), $lblDrive.Font).Width; if ($wk -gt $wMax) { $wMax = $wk } }
        if ($btnHelpTop) {
            $xh = $xCmb - $wMax - 12 - $btnHelpTop.Width
            $btnHelpTop.Location = New-Object System.Drawing.Point($xh, [int]$p['btnHelpTop'].Top)
            if ($chkExpert) { $chkExpert.Location = New-Object System.Drawing.Point($xh, [int]$p['chkExpert'].Top) }
        }
    }
    if ($tip) {
        $t = [string]$script:DriveBanner.Tip
        if ($script:DriveReg.Count -gt 0) {
            $names = @($script:DriveReg.GetEnumerator() | ForEach-Object { Get-DriveLabel ([string]$_.Value.Name) })
            # 12.11 (relecture du lot LN-b) : une phrase par ligne : une infobulle ne coupe ses lignes qu aux retours a la
            # ligne (en une seule ligne, ce texte faisait plus de 1 100 px)
            $t += "`n`n" + ((T "Lecteurs enregistrés : {0}.`nLeurs calibrations sont rangées sous leur nom, quelle que soit leur connexion.`nL'application ne reconnaît pas le lecteur branché : choisissez-le ici chaque fois que vous en changez`n(pour les nommer : Accueil, « Lecteurs enregistrés »).") -f ($names -join ', '))
        }
        if ([string]$tip.GetToolTip($cmbDrive) -cne $t) { $tip.SetToolTip($cmbDrive, $t) }
    }
}

function Sync-DriveCombo {
    # 12.11 (lot LN-b) : reglage drive (une connexion) vers la liste du bandeau quand des lecteurs sont enregistres
    # (Set-SettingCtlValue, 120 : fenetre de nettoyage, Set-Defaults, chargement de la configuration) : rien si le lecteur
    # choisi est deja sur cette connexion, sinon le lecteur retenu pour elle (Get-DriveForConn)
    $c = [string](Get-Setting 'drive')
    if ((Get-DriveConn ([string]$cmbDrive.Text)) -ceq $c) { return }
    Set-Combo $cmbDrive (Get-DriveForConn $c)
}

function Clear-DriveActivity([string]$conn) {
    # 12.11 (lot LN-b) : activite du prechauffage oubliee pour une connexion ($script:DriveActivity, cles
    # « peripherique|connexion », Get-GwDriveKey) : un autre lecteur vient d y etre branche, il est froid
    if (-not $conn -or -not $script:DriveActivity) { return }
    foreach ($k in @($script:DriveActivity.Keys | Where-Object { ([string]$_).EndsWith('|' + $conn) })) { $script:DriveActivity.Remove($k) }
}

function Update-DriveChoice {
    # 12.11 (lot LN-b) : gestionnaire du bandeau (520), apres Sync-PrecompCurves : le texte de la liste vient de changer.
    # Lecteur a confirmer : $script:DriveChecked est vide des qu il differe du lecteur choisi, quel que soit l ordre des
    # evenements de la liste (seuls Set-DriveHandChoice, pour un choix fait dans la liste deroulee, et la case de la
    # confirmation le posent). Avec des lecteurs enregistres : dernier lecteur choisi sur la connexion
    # ($script:DriveLast), activite du prechauffage de la connexion oubliee quand un autre lecteur y est choisi, libelle
    # et disposition du bandeau, libelle du lecteur de la restauration, ligne « Lecteur choisi » quand l un des deux
    # lecteurs est enregistre. Texte vide (liste en reconstruction) ou inchange : rien
    $new = [string]$cmbDrive.Text; $old = [string]$script:DriveCur
    if (-not $new -or $new -ceq $old) { return }
    $script:DriveCur = $new
    if ([string]$script:DriveChecked -cne $new) { $script:DriveChecked = '' }
    if ($script:DriveReg.Count -eq 0) { return }
    $c = Get-DriveConn $new
    if ($c) {
        $nl = @{}
        if ($script:DriveLast) { foreach ($e in @($script:DriveLast.GetEnumerator())) { if ([string]$e.Key -cne $c) { $nl[[string]$e.Key] = [string]$e.Value } } }
        $r = Get-DriveRecord $new
        if ($r) { $nl[$c] = [string]$r.Name }
        $script:DriveLast = $nl
        if ($old -and (Get-DriveConn $old) -ceq $c) { Clear-DriveActivity $c }
    }
    Set-DriveBannerLayout
    Update-RsDrive
    if ($old -and ((Test-DriveRegistered $new) -or (Test-DriveRegistered $old))) { Append-Log ((T 'Lecteur choisi : {0} (avant : {1}).') -f (Get-DriveLabel $new), (Get-DriveLabel $old)) }
}

function Set-DriveHandChoice([bool]$listOpen) {
    # 12.11 (lot LN-b) : SelectionChangeCommitted de la liste du bandeau (510) : seul un choix fait dans la liste deroulee
    # ($listOpen : DroppedDown) vaut confirmation du lecteur branche. Molette (sans effet, 510), fleches ou lettre sur la
    # liste fermee : rien n est pose, la confirmation reste due. Evenement leve avant le changement du texte : le lecteur
    # pose est l ancien, et Update-DriveChoice le vide ensuite. Une hypothese fausse sur ces evenements fait demander la
    # confirmation plus souvent, jamais moins
    if ($listOpen) { $script:DriveChecked = [string]$cmbDrive.SelectedItem }
}

function Test-DriveCheckDue {
    # 12.11 (lot LN-b) : vrai quand le lecteur du bandeau doit etre confirme avant une ecriture, une calibration, une
    # mesure ou une restauration : des lecteurs sont enregistres, le lecteur choisi n a ete ni choisi a la main dans la
    # liste deroulee ni confirme depuis son dernier changement, et sa connexion porte au moins deux lecteurs
    # (Get-ConnDrives), ou le registre vient d etre relu dans sa copie de secours et la connexion porte un lecteur
    # enregistre
    if ($script:DriveReg.Count -eq 0) { return $false }
    $d = [string]$cmbDrive.Text
    if ([string]$script:DriveChecked -and [string]$script:DriveChecked -ceq $d) { return $false }
    $all = @(Get-ConnDrives (Get-DriveConn $d))
    if ($script:DriveRescued -and @($all | Where-Object { Test-DriveRegistered $_ }).Count -ge 1) { return $true }
    return ($all.Count -ge 2)
}

function Confirm-DriveIdentity([switch]$Write, [string]$Target = '') {
    # 12.11 (lot LN-b) : confirmation du lecteur branche, appelee seulement avec des lecteurs enregistres par les cinq
    # fonctions qui engagent une operation sous l identite du lecteur du bandeau (Start-ImageWrite avec -Write,
    # Start-LevelCalib, Start-PrecompCalib, Start-ContentMeasure, Start-Restore) ; due ou non : Test-DriveCheckDue.
    # Fenetre frmConfirm (Show-AppConfirm, niveau warn) : lecteurs de la connexion, lecteur choisi et ses calibrations ;
    # case obligatoire qui nomme le lecteur, ou dit qu il n est aucun des lecteurs enregistres (lecteur non enregistre).
    # Acceptee : lecteur confirme ($script:DriveChecked), les etapes suivantes de la meme operation ne redemandent pas ;
    # refusee (Fermer, Echap, croix) : faux, une ligne de journal, l operation ne part pas (refus note dans la surcharge
    # d une ecriture de la Bibliotheque, comme Test-TargetWriteAllowed). -Write : ligne « Lecteur qui ecrit » au journal
    # (Get-WriteSourceText). -Target (Start-CrossCalib) : lecteur cible d une calibration croisee, confirme a chaque fois
    # que sa connexion porte au moins deux lecteurs : la courbe est rangee « source>cible » et la case de l avertissement
    # de la calibration ne nomme que le lecteur qui ecrit
    $refuse = (T 'Opération annulée : lecteur branché non confirmé.')
    if ($Target) {
        $tc = Get-DriveConn $Target
        $all = @(Get-ConnDrives $tc)
        # 12.11 (relecture du lot LN-b) : lecteur cible non enregistre choisi : il compte parmi les lecteurs de sa
        # connexion, comme le lecteur non enregistre du bandeau dans Get-ConnDrives
        if ($all -cnotcontains $Target) { $all += $Target }
        if ($all.Count -lt 2) { return $true }
        $txt = ((T "La connexion {0} porte plusieurs lecteurs : {1}. L'application ne reconnaît pas celui qui est branché.") -f $tc, (Format-ConnDrives $all)) + "`n`n" + ((T "Lecteur cible de cette calibration croisée : {0}`nLa courbe mesurée servira aux écritures du lecteur {1} destinées à ce lecteur. Si un autre lecteur est branché sur la connexion {2}, fermez cette fenêtre et relancez la calibration croisée avec le bon lecteur cible : mesurée avec un autre lecteur, la courbe serait fausse, sans aucun message d'erreur.") -f (Get-DriveLabel $Target), (Get-DriveLabel ([string]$cmbDrive.Text)), $tc)
        $rt = Get-DriveRecord $Target
        $chk = if ($rt) { (T 'Le lecteur branché sur la connexion {0} est bien « {1} »') -f $tc, [string]$rt.Name } else { (T "Le lecteur branché sur la connexion {0} n'est aucun des lecteurs enregistrés") -f $tc }
        if (Show-AppConfirm -Title (T 'Lecteur branché') -Heading ((T 'Quel lecteur est branché sur la connexion {0} ?') -f $tc) -Text $txt -Check $chk -Level 'warn') { return $true }
        Append-Log $refuse
        if ($script:OpOverride) { $script:OpOverride.Refused = $true }
        return $false
    }
    if (Test-DriveCheckDue) {
        $d = [string]$cmbDrive.Text; $c = Get-DriveConn $d
        $intro = if ($script:DriveRescued) { (T "Vos lecteurs enregistrés viennent d'être relus dans leur copie de secours : le fichier de configuration ne les contenait pas. L'application ne reconnaît pas le lecteur branché sur la connexion {0}.") -f $c }
                 else { (T "La connexion {0} porte plusieurs lecteurs : {1}. L'application ne reconnaît pas celui qui est branché.") -f $c, (Format-ConnDrives @(Get-ConnDrives $c)) }
        $txt = $intro + "`n`n" + ((T "Lecteur choisi dans le bandeau : {0}`nSes calibrations : {1}`n`nL'écriture et la calibration emploient ses courbes et rangent leurs résultats sous son nom. Si un autre lecteur est branché, fermez cette fenêtre et choisissez-le dans la liste « Lecteur : » du bandeau : avec la courbe d'un autre lecteur, la disquette serait mal précompensée, sans aucun message d'erreur.") -f (Get-DriveLabel $d), (Get-DriveDataText (Get-DriveData $d)))
        $rd = Get-DriveRecord $d
        $chk = if ($rd) { (T 'Le lecteur branché sur la connexion {0} est bien « {1} »') -f $c, [string]$rd.Name } else { (T "Le lecteur branché sur la connexion {0} n'est aucun des lecteurs enregistrés") -f $c }
        if (-not (Show-AppConfirm -Title (T 'Lecteur branché') -Heading ((T 'Quel lecteur est branché sur la connexion {0} ?') -f $c) -Text $txt -Check $chk -Level 'warn')) {
            Append-Log $refuse
            if ($script:OpOverride) { $script:OpOverride.Refused = $true }
            return $false
        }
        $script:DriveChecked = $d
    }
    if ($Write) { Append-Log (Get-WriteSourceText) }
    return $true
}

function Update-DriveLock {
    # 12.11 (lot LN-b) : minuteur principal (600) : liste « Lecteur : » du bandeau inactive pendant toute operation
    # (Get-AppBusy), sauf la pause d une mesure continue de l onglet Qualite, avec ou sans lecteur enregistre : une
    # operation commencee avec un lecteur se termine avec lui (une calibration relit la connexion du bandeau a chaque
    # passe, sa cle de rangement est figee au lancement). Un changement fait par le code reste possible
    $b = Get-AppBusy
    $lock = ([bool]$b -and $b -ne 'quality')
    if ($cmbDrive.Enabled -eq $lock) { $cmbDrive.Enabled = -not $lock }
}

function Get-DriveRows {
    # 12.11 (lot LN-b) : lignes de la fenetre « Lecteurs enregistres » : chaque fiche, dans l ordre du registre, puis
    # chaque lecteur non enregistre qui a des donnees (« A (non enregistre) »). Une ligne : @{ Kind ('rec' ou 'conn') ;
    # Drive (identite) ; Conn ; Text, ConnText, Cal (textes des trois colonnes) ; Data (Get-DriveData) }. Tableau protege
    # par la virgule
    $rows = @()
    if ($script:DriveReg) {
        foreach ($e in @($script:DriveReg.GetEnumerator())) {
            $r = $e.Value; $nm = [string]$r.Name; $dt = Get-DriveData $nm
            $rows += ,@{ Kind = 'rec'; Drive = $nm; Conn = [string]$r.Conn; Text = $nm; ConnText = $(if ([string]$r.Conn) { [string]$r.Conn } else { (T 'à préciser') }); Cal = (Get-DriveDataText $dt); Data = $dt }
        }
    }
    foreach ($c in @($script:SettingDefs['drive'].Codes)) {
        $dt = Get-DriveData ([string]$c)
        if ($dt['Any']) { $rows += ,@{ Kind = 'conn'; Drive = [string]$c; Conn = [string]$c; Text = ((T '{0} (non enregistré)') -f [string]$c); ConnText = [string]$c; Cal = (Get-DriveDataText $dt); Data = $dt } }
    }
    return ,@($rows)
}

function Get-DriveEditPlan($row, [string]$name, [string]$conn) {
    # 12.11 (lot LN-b) : seule decision du bouton « Enregistrer » de la fenetre « Lecteurs enregistres », et ses textes,
    # sans rien changer : @{ Kind ; Error ; Note ; Ask ; Text ; Log ; Name ; Conn ; From ; Old ; N ; AskHeading ;
    # AskText ; AskCheck ; AskGo }. $row : ligne choisie (Get-DriveRows), $null pour « Nouveau lecteur ». Kind : new
    # (fiche sans courbe ; Note : la connexion a des calibrations sans nom), adopt (le lecteur non enregistre de la ligne
    # recoit le nom, ou une fiche existante sans aucune donnee), rename (nom change, ne serait-ce que de casse : -cne),
    # move (connexion changee, ou rendue a une fiche sans connexion), rename+move, none (rien a enregistrer). Ask : check
    # (confirmation a case : le lecteur non enregistre a des courbes), yesno (question : des donnees sans courbe) ou vide.
    # Error : refus, texte affiche dans la fenetre. Text : resultat affiche ; Log : lignes du journal (renommer et deplacer
    # a la fois : les deux, le resultat affiche est celui du changement de connexion). N : courbes deplacees
    $p = @{ Kind = ''; Error = ''; Note = ''; Ask = ''; Text = ''; Log = @(); Name = ''; Conn = $conn; From = ''; Old = ''; N = 0; AskHeading = ''; AskText = ''; AskCheck = ''; AskGo = '' }
    $why = Get-DriveEditRefusal
    if ($why) { $p.Error = $why; return $p }
    $nm = [string](Test-DriveName $name).Name
    if (-not $row) {
        $p.Kind = 'new'
        if (-not (Test-DriveConnCode $conn)) { $p.Error = (T 'Choisissez la connexion du lecteur.'); return $p }
        $dc = Get-DriveData $conn
        if ((@($dc['Keys']).Count + @($dc['Cross']).Count) -gt 0) { $p.Note = (T 'La connexion {0} a déjà des calibrations sans nom de lecteur. Pour les garder avec ce lecteur, sélectionnez la ligne « {0} (non enregistré) » et donnez-lui ce nom ; sinon ce lecteur sera calibré à part.') -f $conn }
        $tn = Test-DriveName $name
        if (-not $tn.Ok) { $p.Error = [string]$tn.Why; return $p }
        $p.Name = [string]$tn.Name
        $p.Text = (T 'Lecteur « {0} » enregistré sur la connexion {1}, sans calibration. Choisissez-le dans la liste « Lecteur : » du bandeau quand il est branché.') -f $p.Name, $conn
        $p.Log = @($p.Text)
        return $p
    }
    if ([string]$row.Kind -eq 'conn') {
        $p.Kind = 'adopt'; $p.From = [string]$row.Drive
        if (-not (Test-DriveConnCode $conn)) { $p.Error = (T 'Choisissez la connexion du lecteur.'); return $p }
        $rec = Get-DriveRecord $nm
        if ($rec) { $p.Name = [string]$rec.Name }
        else {
            $tn = Test-DriveName $name
            if (-not $tn.Ok) { $p.Error = [string]$tn.Why; return $p }
            $p.Name = [string]$tn.Name
        }
        $chk = Edit-DriveData $p.From $p.Name -Check
        if (-not $chk.Ok) { $p.Error = [string]$chk.Why; return $p }
        $dt = Get-DriveData $p.From
        $p.N = @($dt['Keys']).Count + @($dt['Cross']).Count
        if ($p.N -gt 0) {
            $p.Ask = 'check'
            $p.AskHeading = (T 'Attribuer à ce lecteur les calibrations de la connexion {0} ?') -f $p.From
            $p.AskText = (T "La connexion {0} a des calibrations faites sans nom de lecteur : {1}.`n`nEn nommant ce lecteur « {2} », vous déclarez qu'elles ont été faites avec lui : elles deviennent les siennes, avec ses niveaux, sa mémoire par marque, ses facteurs mesurés et son lecteur cible. Rien n'est recalculé ni effacé ; la configuration est d'abord copiée dans un fichier « {3}.lecteurs-….bak ». La connexion {0} garde un lecteur non enregistré, sans calibration.`n`nSi elles viennent d'un autre lecteur, fermez cette fenêtre et choisissez « Nouveau lecteur » : il partira sans calibration.") -f $p.From, (Get-DriveDataText $dt), $p.Name, [System.IO.Path]::GetFileName([string]$script:ConfigFile)
            $p.AskCheck = (T 'Les calibrations de la connexion {0} ont été faites avec le lecteur « {1} »') -f $p.From, $p.Name
            $p.AskGo = (T 'Attribuer ces calibrations')
        } elseif ($dt['Any']) {
            $p.Ask = 'yesno'
            $p.AskText = (T 'Le lecteur non enregistré de la connexion {0} n''a aucune calibration. Son lecteur cible, ses niveaux, sa mémoire par marque et ses facteurs mesurés passent sous le nom « {1} ». Continuer ?') -f $p.From, $p.Name
        }
        $p.Text = (T 'Lecteur « {0} » enregistré sur la connexion {1} : les calibrations faites sans nom sur la connexion {2} ({3} courbe(s)) sont maintenant les siennes.') -f $p.Name, $conn, $p.From, "$($p.N)"
        # 12.11 (relecture du lot LN-b) : sans courbe (question T70 : « aucune calibration »), le resultat ne parle pas de
        # calibrations
        if ($p.N -eq 0) { $p.Text = (T 'Lecteur « {0} » enregistré sur la connexion {1} : le lecteur cible, les niveaux, la mémoire par marque et les facteurs mesurés de la connexion {2} sont maintenant les siens.') -f $p.Name, $conn, $p.From }
        $p.Log = @($p.Text)
        return $p
    }
    $rec = Get-DriveRecord ([string]$row.Drive)
    if (-not $rec) { $p.Kind = 'none'; $p.Error = (T 'Rien à enregistrer : le nom et la connexion n''ont pas changé.'); return $p }
    $old = [string]$rec.Name; $oc = [string]$rec.Conn
    $p.Old = $old
    if (-not (Test-DriveConnCode $conn)) { $p.Error = (T 'Choisissez la connexion du lecteur.'); return $p }
    $ren = ($nm -cne $old); $mov = ($conn -cne $oc)
    if (-not $ren -and -not $mov) { $p.Kind = 'none'; $p.Error = (T 'Rien à enregistrer : le nom et la connexion n''ont pas changé.'); return $p }
    $p.Name = $old
    if ($ren) {
        $tn = Test-DriveName $name $old
        if (-not $tn.Ok) { $p.Error = [string]$tn.Why; return $p }
        $p.Name = [string]$tn.Name
        $chk = Edit-DriveData $old $p.Name -Check
        if (-not $chk.Ok) { $p.Error = [string]$chk.Why; return $p }
    }
    $dt = Get-DriveData $old
    $p.N = @($dt['Keys']).Count + @($dt['Cross']).Count
    $p.Kind = if ($ren -and $mov) { 'rename+move' } elseif ($ren) { 'rename' } else { 'move' }
    $l = @()
    if ($ren) { $l += (T "Lecteur « {0} » : il s'appelait « {1} ». Ses calibrations ({2} courbe(s)), ses niveaux, sa mémoire par marque, ses facteurs et ses lecteurs cibles portent son nouveau nom.") -f $p.Name, $old, "$($p.N)" }
    if ($mov) { $l += (T 'Lecteur « {0} » : connexion {1} (avant : {2}). Ses calibrations le suivent. Après un changement de nappe, contrôlez une écriture (onglet Qualité) ou refaites une calibration rapide.') -f $p.Name, $conn, $(if ($oc) { $oc } else { (T 'à préciser') }) }
    $p.Log = $l; $p.Text = [string]$l[-1]
    return $p
}

function Update-DriveUiAfterEdit([string]$Select = '') {
    # 12.11 (lot LN-b) : interface apres une action de la fenetre « Lecteurs enregistres » : fenetre Courbe fermee (elle
    # garderait l ancien nom : seul le gestionnaire du bandeau la ferme), liste et disposition du bandeau
    # (Update-DriveList), liste « Lecteur cible » et case de la mesure, libelle du lecteur de la restauration, profil de
    # l image une fois la fenetre affichee
    if ($script:CurveForm -and -not $script:CurveForm.IsDisposed) { $script:CurveForm.Close() }
    Update-DriveList $Select
    Update-TargetDriveUi; Update-SlowUi
    Update-RsDrive
    if ($form -and $form.Visible) { Update-PrecompForImage $txtWFile.Text }
}

function Invoke-DriveEditPlan($plan) {
    # 12.11 (lot LN-b) : execute la decision de Get-DriveEditPlan : confirmation s il y a lieu (case T37 a T40, ou question
    # T70), action du registre (Add-NamedDrive, Rename-NamedDrive, Move-NamedDrive : elles font la copie datee), interface
    # (Update-DriveUiAfterEdit), journal, enregistrement. Lecteur du bandeau nomme, renomme ou deplace : c est le meme
    # lecteur physique, sans ligne « Lecteur choisi » ; il devient le dernier lecteur de sa connexion, le reglage drive suit
    # sa connexion (Update-DriveList) ; connexion changee : confirmation de nouveau due, activite du prechauffage de la
    # nouvelle connexion oubliee. Un lecteur de plus sur la connexion du lecteur du bandeau : confirmation de nouveau due.
    # Rend @{ Ok ; Text (resultat affiche) ; Error (refus affiche) } ; confirmation refusee : Ok faux, rien n est change
    $res = @{ Ok = $false; Text = ''; Error = '' }
    if (-not $plan) { return $res }
    if ($plan.Error) { $res.Error = [string]$plan.Error; return $res }
    if ($plan.Ask -eq 'check') {
        if (-not (Show-AppConfirm -Title (T 'Lecteurs enregistrés') -Heading $plan.AskHeading -Text $plan.AskText -Check $plan.AskCheck -GoText $plan.AskGo -GoGlyph 'Save' -Level 'warn')) { return $res }
    } elseif ($plan.Ask -eq 'yesno') {
        if ([string](Show-AppMessage $plan.AskText (T 'Lecteurs enregistrés') 'YesNo' 'Question') -ne 'Yes') { return $res }
    }
    $banner = [string]$cmbDrive.Text; $bConn = Get-DriveConn $banner
    $nOnConn = @(Get-ConnDrives $bConn).Count
    $r = $null
    switch ([string]$plan.Kind) {
        'new'         { $r = Add-NamedDrive $plan.Name $plan.Conn }
        'adopt'       { $r = Add-NamedDrive $plan.Name $plan.Conn $plan.From }
        'rename'      { $r = Rename-NamedDrive $plan.Old $plan.Name }
        'move'        { $r = Move-NamedDrive $plan.Old $plan.Conn }
        'rename+move' { $r = Rename-NamedDrive $plan.Old $plan.Name; if ($r.Ok) { $r = Move-NamedDrive $plan.Name $plan.Conn } }
    }
    if (-not $r -or -not $r.Ok) { $res.Error = $(if ($r -and $r.Why) { [string]$r.Why } else { (T "Configuration non sauvegardée : rien n'a été modifié (voir le journal).") }); return $res }
    $now = ''
    # 12.11 (relecture du lot LN-b) : nommer vers la fiche (sans donnee) du lecteur du bandeau : c est lui qui recoit la
    # connexion, il reste le lecteur du bandeau et devient le dernier lecteur de sa nouvelle connexion
    if ($plan.Kind -eq 'adopt' -and ($banner -ceq [string]$plan.From -or $banner -ceq [string]$plan.Name)) { $now = [string]$plan.Name }
    elseif ($plan.Old -and $banner -ceq [string]$plan.Old) { $now = [string]$plan.Name }
    if ($now) {
        $nc = Get-DriveConn $now
        $script:DriveCur = $now
        $nl = @{}
        foreach ($e in @($script:DriveLast.GetEnumerator())) { if ([string]$e.Key -cne $nc) { $nl[[string]$e.Key] = [string]$e.Value } }
        if ($nc) { $nl[$nc] = $now }
        $script:DriveLast = $nl
        if ($nc -cne $bConn) { $script:DriveChecked = ''; Clear-DriveActivity $nc }
    } elseif ($bConn -and @(Get-ConnDrives $bConn).Count -gt $nOnConn) {
        # 12.11 (relecture du lot LN-b) : un lecteur de plus sur la connexion du lecteur du bandeau (nouveau lecteur,
        # lecteur nomme ou deplace vers elle) : il y est peut-etre branche a la place du lecteur choisi, qui n est plus
        # tenu pour confirme
        $script:DriveChecked = ''
    }
    Update-DriveUiAfterEdit $now
    foreach ($l in @($plan.Log)) { Append-Log ([string]$l) }
    [void](Save-Config)
    $res.Ok = $true; $res.Text = [string]$plan.Text
    return $res
}

function Get-DriveDeletePlan($row) {
    # 12.11 (lot LN-b) : seule decision du bouton « Supprimer... » (fiche seulement), et ses textes, sans rien changer :
    # @{ Error ; Name ; Conn ; Any ; Keep ; N ; Heading ; Text ; Check ; Go ; Alt ; Question ; TextDel ; TextKeep }. Avec
    # des donnees (Any) : confirmation a case au niveau danger, qui ne nomme aucune des deux issues (la case commande les
    # deux boutons) ; chaque bouton nomme la sienne ; « Retirer seulement le nom » (Keep) propose quand la fiche a une
    # connexion dont le lecteur non enregistre n a aucune donnee (sinon Remove-NamedDrive -KeepData le refuserait). Sans
    # donnee : question simple. La copie annoncee (texte de la confirmation) est faite par Remove-NamedDrive des que le
    # lecteur a une donnee, le meme champ Any decidant des deux
    $p = @{ Error = ''; Name = ''; Conn = ''; Any = $false; Keep = $false; N = 0; Heading = ''; Text = ''; Check = ''; Go = ''; Alt = ''; Question = ''; TextDel = ''; TextKeep = '' }
    $why = Get-DriveEditRefusal
    if ($why) { $p.Error = $why; return $p }
    $rec = if ($row -and [string]$row.Kind -eq 'rec') { Get-DriveRecord ([string]$row.Drive) } else { $null }
    if (-not $rec) { return $p }
    $nm = [string]$rec.Name; $c = [string]$rec.Conn
    $dt = Get-DriveData $nm
    $p.Name = $nm; $p.Conn = $c; $p.Any = [bool]$dt['Any']
    $p.N = @($dt['Keys']).Count + @($dt['Cross']).Count
    $p.Keep = [bool]($c -and (Test-DriveConnCode $c) -and -not (Get-DriveData $c)['Any'])
    if ($p.Any) {
        $p.Heading = (T 'Supprimer le lecteur « {0} » ?') -f $nm
        $p.Text = (T "Sont retirés : ses calibrations ({0}), ses niveaux, sa mémoire par marque, ses facteurs mesurés et son lecteur cible, ainsi que les courbes croisées dont il est le lecteur cible et le choix de ce lecteur comme cible d'un autre.`n`nL'application ne peut pas annuler cette suppression. Elle copie d'abord la configuration dans « {1}.lecteurs-….bak », dans le même dossier : pour revenir en arrière, fermez l'application, puis remettez cette copie à la place de « {1} ».") -f (Get-DriveDataText $dt), [System.IO.Path]::GetFileName([string]$script:ConfigFile)
        if ($p.Keep) { $p.Text += "`n`n" + ((T '« Retirer seulement le nom » : ses calibrations restent, rangées sous la connexion {0}, sans nom de lecteur.') -f $c); $p.Alt = (T 'Retirer seulement le nom') }
        $p.Check = (T 'Le lecteur « {0} » ne doit plus être enregistré') -f $nm
        $p.Go = (T 'Supprimer avec ses calibrations')
    } else { $p.Question = (T 'Supprimer le lecteur « {0} » ? Il n''a aucune calibration.') -f $nm }
    $p.TextDel = (T 'Lecteur « {0} » supprimé : {1} courbe(s) retirée(s).') -f $nm, "$($p.N)"
    $p.TextKeep = (T 'Nom « {0} » retiré : ses calibrations sont rangées sous la connexion {1}, sans nom de lecteur.') -f $nm, $c
    return $p
}

function Remove-DriveEntry($row) {
    # 12.11 (lot LN-b) : « Supprimer... » de la fenetre « Lecteurs enregistres » : decision et textes de
    # Get-DriveDeletePlan, confirmation, Remove-NamedDrive (avec -KeepData pour « Retirer seulement le nom » ; copie
    # datee faite par elle), interface (Update-DriveUiAfterEdit : lecteur supprime du bandeau remplace par le lecteur non
    # enregistre de sa connexion), journal, enregistrement. Rend @{ Ok ; Text ; Error } ; confirmation refusee : Ok faux
    $res = @{ Ok = $false; Text = ''; Error = '' }
    $p = Get-DriveDeletePlan $row
    if ($p.Error) { $res.Error = [string]$p.Error; return $res }
    if (-not $p.Name) { return $res }
    $keep = $false
    if ($p.Any) {
        $go = [bool](Show-AppConfirm -Title (T 'Lecteurs enregistrés') -Heading $p.Heading -Text $p.Text -Check $p.Check -GoText $p.Go -GoGlyph 'Delete' -Level 'danger' -AltText $p.Alt)
        if (-not $go) {
            if ($p.Alt -and [string]$script:ConfirmChoice -eq 'alt') { $keep = $true } else { return $res }
        }
    } elseif ([string](Show-AppMessage $p.Question (T 'Lecteurs enregistrés') 'YesNo' 'Question') -ne 'Yes') { return $res }
    $r = if ($keep) { Remove-NamedDrive $p.Name -KeepData } else { Remove-NamedDrive $p.Name }
    if (-not $r.Ok) { $res.Error = $(if ($r.Why) { [string]$r.Why } else { (T "Configuration non sauvegardée : rien n'a été modifié (voir le journal).") }); return $res }
    Update-DriveUiAfterEdit
    $res.Text = $(if ($keep) { [string]$p.TextKeep } else { [string]$p.TextDel })
    Append-Log $res.Text
    [void](Save-Config)
    $res.Ok = $true
    return $res
}

function Get-DriveWidestName($font) {
    # 12.11 (lot LN-b) : nom le plus large admis par Test-DriveName dans la police $font (lettres W, les plus larges) :
    # sert a mesurer les textes qui citent un nom (hauteur du texte d etat de la fenetre « Lecteurs enregistres »)
    $n = 'W'
    while ($n.Length -lt [int]$script:DriveNameMax -and [System.Windows.Forms.TextRenderer]::MeasureText(($n + 'W'), $font).Width -le ([int]$script:DriveListWidth - 24)) { $n += 'W' }
    return $n
}

function Get-DrivesStateSamples($font) {
    # 12.11 (lot LN-b) : textes les plus longs du texte d etat de la fenetre « Lecteurs enregistres », avec le nom le plus
    # large admis : sa hauteur est celle du plus haut d entre eux (aucun texte coupe)
    $w = Get-DriveWidestName $font
    return @(
        ((T 'La connexion {0} a déjà des calibrations sans nom de lecteur. Pour les garder avec ce lecteur, sélectionnez la ligne « {0} (non enregistré) » et donnez-lui ce nom ; sinon ce lecteur sera calibré à part.') -f 'A'),
        ((T "Lecteur « {0} » : il s'appelait « {1} ». Ses calibrations ({2} courbe(s)), ses niveaux, sa mémoire par marque, ses facteurs et ses lecteurs cibles portent son nouveau nom.") -f $w, $w, '99'),
        ((T 'Lecteur « {0} » : connexion {1} (avant : {2}). Ses calibrations le suivent. Après un changement de nappe, contrôlez une écriture (onglet Qualité) ou refaites une calibration rapide.') -f $w, 'A', (T 'à préciser')),
        ((T 'Lecteur « {0} » enregistré sur la connexion {1} : les calibrations faites sans nom sur la connexion {2} ({3} courbe(s)) sont maintenant les siennes.') -f $w, 'A', '0', '99'),
        ((T 'Lecteur « {0} » enregistré sur la connexion {1} : le lecteur cible, les niveaux, la mémoire par marque et les facteurs mesurés de la connexion {2} sont maintenant les siens.') -f $w, 'A', '0'),
        ((T 'Lecteur « {0} » enregistré sur la connexion {1}, sans calibration. Choisissez-le dans la liste « Lecteur : » du bandeau quand il est branché.') -f $w, 'A'),
        ((T 'Le lecteur {0} a déjà des données (courbes, lecteur cible, niveaux, mémoire par marque ou facteurs) : celles de la connexion {1} ne peuvent pas lui être attribuées.') -f $w, 'A'),
        ((T 'La connexion {0} a déjà des données sans nom de lecteur (courbes, lecteur cible, niveaux, mémoire par marque ou facteurs) : le nom ne peut pas être retiré seul.') -f 'A'),
        ((T 'Lecteurs enregistrés : opération en cours ({0}). Réessayez quand elle est terminée.') -f (T 'mesure continue de la qualité')),
        ((T "Nom trop large pour s'afficher en entier dans les listes de lecteurs (environ 17 caractères) : raccourcissez-le."))
    )
}

function New-DrivesDialog {
    # 12.11 (lot LN-b) : fenetre « Lecteurs enregistres » (frmDrives), construite sans etre affichee (Show-DrivesDialog
    # l affiche), au modele de frmJitter : bandeau d information (New-DlgBanner, lblDrvText) ; liste lvDrives (Get-DriveRows),
    # colonnes « Lecteur », « Connexion », « Calibrations » (150 + 90 + 379 = 619 px : largeur utile quand la barre
    # verticale parait, aucune barre horizontale) ; « Nom : » (txtDrvName, 24 caracteres au plus), « Connexion : »
    # (cmbDrvConn) ; texte d etat lblDrvState (refus dans l encre du danger, note ou resultat dans l encre neutre ; hauteur
    # du plus haut de ses textes les plus longs, Get-DrivesStateSamples, mesure par le Label lui-meme) ; « Nouveau
    # lecteur », « Supprimer... », « Enregistrer » (principal), « Fermer » (CancelButton, aucun AcceptButton : Entree
    # n enregistre rien). La fenetre ne decide rien (Get-DriveEditPlan, Invoke-DriveEditPlan, Get-DriveDeletePlan,
    # Remove-DriveEntry) et n ouvre aucune boite de message directe (Show-AppConfirm, Show-AppMessage). Rend l etat
    # partage avec ses gestionnaires ($script:DrvDlg) : @{ Dlg ; Lv ; Name ; Conn ; State ; New ; Del ; Save ; Close ;
    # Gdi ; Rows ; Mode ('new' ou 'row') ; Busy }
    $W = 640
    $gdi = New-Object System.Collections.Generic.List[object]
    $dlg = New-Object System.Windows.Forms.Form
    $dlg.Name = 'frmDrives'; $dlg.Text = (T 'Lecteurs enregistrés')
    $dlg.FormBorderStyle = 'FixedDialog'; $dlg.MaximizeBox = $false; $dlg.MinimizeBox = $false; $dlg.ShowInTaskbar = $false
    $dlg.StartPosition = 'CenterParent'; $dlg.Icon = $form.Icon; $dlg.Font = $form.Font; $dlg.BackColor = [System.Drawing.Color]::White
    $text = (T "Un lecteur enregistré a un nom et une connexion au Greaseweazle (A ou B : nappe PC avec twist ; 0 à 3 : nappe droite). Ses calibrations, son lecteur cible et ses facteurs mesurés sont rangés sous son nom : plusieurs lecteurs peuvent partager une connexion, et un lecteur garde ses calibrations quand il change de connexion.`n`nL'application ne reconnaît pas le lecteur branché : celui qui compte est le lecteur choisi dans la liste « Lecteur : » du bandeau. Un lecteur nouveau part sans calibration, avec le profil d'origine.")
    $ban = New-DlgBanner $dlg 16 $W (T 'Vos lecteurs de disquette') $text 'info' (New-DlgPicto 'drive') $gdi 'lblDrvText'
    $y = $ban.Bottom + 14
    $lv = New-Object System.Windows.Forms.ListView
    $lv.Name = 'lvDrives'; $lv.View = 'Details'; $lv.FullRowSelect = $true; $lv.MultiSelect = $false; $lv.HideSelection = $false
    $lv.HeaderStyle = 'Nonclickable'; $lv.Font = $dlg.Font
    $lv.Location = New-Object System.Drawing.Point(16, $y); $lv.Size = New-Object System.Drawing.Size($W, 190)
    [void]$lv.Columns.Add((T 'Lecteur'), 150); [void]$lv.Columns.Add((T 'Connexion'), 90); [void]$lv.Columns.Add((T 'Calibrations'), 379)
    $y = $lv.Bottom + 12
    $lblN = New-Object System.Windows.Forms.Label
    $lblN.Name = 'lblDrvName'; $lblN.Text = (T 'Nom :'); $lblN.AutoSize = $true; $lblN.Location = New-Object System.Drawing.Point(16, ($y + 3))
    $txt = New-Object System.Windows.Forms.TextBox
    $txt.Name = 'txtDrvName'; $txt.Width = 220; $txt.MaxLength = [int]$script:DriveNameMax
    $txt.Location = New-Object System.Drawing.Point((16 + [System.Windows.Forms.TextRenderer]::MeasureText($lblN.Text, $dlg.Font).Width + 6), $y)
    $lblC = New-Object System.Windows.Forms.Label
    $lblC.Name = 'lblDrvConn'; $lblC.Text = (T 'Connexion :'); $lblC.AutoSize = $true; $lblC.Location = New-Object System.Drawing.Point(($txt.Right + 24), ($y + 3))
    $cmb = New-Object System.Windows.Forms.ComboBox
    $cmb.Name = 'cmbDrvConn'; $cmb.DropDownStyle = 'DropDownList'; $cmb.Width = 56
    [void]$cmb.Items.AddRange([object[]]@($script:SettingDefs['drive'].Codes))
    $cmb.Location = New-Object System.Drawing.Point(($lblC.Left + [System.Windows.Forms.TextRenderer]::MeasureText($lblC.Text, $dlg.Font).Width + 6), $y)
    $y += 34
    $fS = New-Object System.Drawing.Font('Segoe UI Semibold', 9.75); $gdi.Add($fS)
    $st = New-Object System.Windows.Forms.Label
    $st.Name = 'lblDrvState'; $st.AutoSize = $false; $st.UseMnemonic = $false; $st.Font = $fS; $st.ForeColor = $script:Theme.Muted
    $st.Location = New-Object System.Drawing.Point(16, $y); $st.Size = New-Object System.Drawing.Size($W, 20)
    # 12.11 (lot LN-b) : hauteur mesuree par le Label lui-meme (son decoupage des lignes) : la maquette donnait 36 px a deux
    # lignes, qui en demandent 40
    $hs = 0
    foreach ($s0 in @(Get-DrivesStateSamples $fS)) { $st.Text = [string]$s0; $h0 = $st.GetPreferredSize((New-Object System.Drawing.Size($W, 0))).Height; if ($h0 -gt $hs) { $hs = $h0 } }
    $st.Text = ''; $st.Height = $hs
    $y = $st.Bottom + 8
    $bNew = New-Object System.Windows.Forms.Button; $bNew.Name = 'btnDrvNew'; $bNew.Text = (T 'Nouveau lecteur'); $bNew.Size = New-Object System.Drawing.Size((Get-DlgButtonWidth $bNew.Text 'Add' 150), 34)
    $bDel = New-Object System.Windows.Forms.Button; $bDel.Name = 'btnDrvDel'; $bDel.Text = (T 'Supprimer…'); $bDel.Size = New-Object System.Drawing.Size((Get-DlgButtonWidth $bDel.Text 'Delete' 130), 34)
    $bSave = New-Object System.Windows.Forms.Button; $bSave.Name = 'btnDrvSave'; $bSave.Text = (T 'Enregistrer'); $bSave.Size = New-Object System.Drawing.Size((Get-DlgButtonWidth $bSave.Text 'Save' 140), 34)
    $bClose = New-Object System.Windows.Forms.Button; $bClose.Name = 'btnDrvClose'; $bClose.Text = (T 'Fermer'); $bClose.Size = New-Object System.Drawing.Size(110, 34)
    $bClose.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
    Set-Btn $bNew 'Add' 'normal'; Set-Btn $bDel 'Delete' 'normal'; Set-Btn $bSave 'Save' 'primary'; Set-Btn $bClose '' 'normal'
    $bNew.Location = New-Object System.Drawing.Point(16, $y); $bDel.Location = New-Object System.Drawing.Point(($bNew.Right + 8), $y)
    $bClose.Location = New-Object System.Drawing.Point((16 + $W - $bClose.Width), $y); $bSave.Location = New-Object System.Drawing.Point(($bClose.Left - 8 - $bSave.Width), $y)
    $dlg.ClientSize = New-Object System.Drawing.Size(($W + 32), ($y + 34 + 16))
    $dlg.CancelButton = $bClose
    $dlg.Controls.AddRange(@($lv, $lblN, $txt, $lblC, $cmb, $st, $bNew, $bDel, $bSave, $bClose))
    $s = @{ Dlg = $dlg; Lv = $lv; Name = $txt; Conn = $cmb; State = $st; New = $bNew; Del = $bDel; Save = $bSave; Close = $bClose; Gdi = $gdi; Rows = @(); Mode = 'new'; Busy = $false }
    $script:DrvDlg = $s
    $lv.Add_SelectedIndexChanged({ $s = $script:DrvDlg; if ($s -and -not $s.Busy) { Set-DrivesDialogInputs $s } })
    $cmb.Add_SelectedIndexChanged({ $s = $script:DrvDlg; if ($s -and -not $s.Busy -and $s.Mode -eq 'new') { Show-DrivesDialogNote $s } })
    $bNew.Add_Click({ if ($script:DrvDlg) { Start-DrivesDialogNew $script:DrvDlg } })
    $bSave.Add_Click({ if ($script:DrvDlg) { [void](Invoke-DrivesDialogSave $script:DrvDlg) } })
    $bDel.Add_Click({ if ($script:DrvDlg) { [void](Invoke-DrivesDialogDelete $script:DrvDlg) } })
    Update-DrivesDialog $s
    Start-DrivesDialogNew $s
    return $s
}

function Get-DrivesDialogRow($s) {
    # 12.11 (lot LN-b) : ligne choisie de frmDrives (Get-DriveRows), lue sur les elements eux-memes (SelectedIndices reste
    # vide tant que la liste n a pas de poignee) ; $null sans choix ou en mode « Nouveau lecteur »
    if (-not $s -or $s.Mode -ne 'row') { return $null }
    for ($i = 0; $i -lt $s.Lv.Items.Count; $i++) { if ($s.Lv.Items[$i].Selected -and $i -lt @($s.Rows).Count) { return $s.Rows[$i] } }
    return $null
}

function Set-DrivesDialogState($s, [string]$text, [bool]$err) {
    # 12.11 (lot LN-b) : texte d etat de frmDrives : refus dans l encre du danger, note ou resultat dans l encre neutre
    $s.State.ForeColor = $(if ($err) { $script:Theme.Danger } else { $script:Theme.Muted })
    $s.State.Text = $text
}

function Update-DrivesDialog($s, [string]$keep = '') {
    # 12.11 (lot LN-b) : lignes de frmDrives (Get-DriveRows) ; $keep : identite de la ligne a choisir ensuite (mode ligne)
    $s.Busy = $true
    try {
        $rows = Get-DriveRows
        $s.Rows = $rows
        $s.Lv.BeginUpdate()
        $s.Lv.Items.Clear()
        foreach ($r in $rows) {
            $it = New-Object System.Windows.Forms.ListViewItem([string]$r.Text)
            [void]$it.SubItems.Add([string]$r.ConnText); [void]$it.SubItems.Add([string]$r.Cal)
            [void]$s.Lv.Items.Add($it)
        }
        $s.Lv.EndUpdate()
        $s.Mode = 'new'
        if ($keep) { for ($i = 0; $i -lt @($rows).Count; $i++) { if ([string]$rows[$i].Drive -ceq $keep) { Select-DrivesDialogRow $s $i; $s.Mode = 'row' } } }
    } finally { $s.Busy = $false }
    if ($s.Mode -eq 'row') { Set-DrivesDialogInputs $s }
}

function Select-DrivesDialogRow($s, [int]$i) {
    # 12.11 (lot LN-b) : une seule ligne choisie dans frmDrives : les autres d abord desselectionnees (une liste sans
    # poignee n applique pas MultiSelect)
    for ($k = 0; $k -lt $s.Lv.Items.Count; $k++) { if ($k -ne $i -and $s.Lv.Items[$k].Selected) { $s.Lv.Items[$k].Selected = $false } }
    if ($i -ge 0 -and $i -lt $s.Lv.Items.Count) { $s.Lv.Items[$i].Selected = $true }
}

function Set-DrivesDialogInputs($s) {
    # 12.11 (lot LN-b) : ligne choisie de frmDrives : nom de la fiche (vide pour un lecteur non enregistre), sa connexion
    # (aucune pour une fiche « a preciser »), « Supprimer... » actif pour une fiche seulement
    $s.Mode = 'row'
    $r = Get-DrivesDialogRow $s
    $s.Busy = $true
    try {
        if (-not $r) { $s.Mode = 'new'; $s.Del.Enabled = $false; return }
        $s.Name.Text = $(if ([string]$r.Kind -eq 'rec') { [string]$r.Drive } else { '' })
        $s.Conn.SelectedIndex = [array]::IndexOf([string[]]@($script:SettingDefs['drive'].Codes), [string]$r.Conn)
        $s.Del.Enabled = ([string]$r.Kind -eq 'rec')
    } finally { $s.Busy = $false }
    Set-DrivesDialogState $s '' $false
}

function Start-DrivesDialogNew($s) {
    # 12.11 (lot LN-b) : « Nouveau lecteur » : aucune ligne choisie, nom vide, connexion proposee : celle du lecteur du
    # bandeau ; note de la connexion (Show-DrivesDialogNote)
    $s.Busy = $true
    try {
        foreach ($it in @($s.Lv.Items)) { $it.Selected = $false }
        $s.Mode = 'new'; $s.Name.Text = ''; $s.Del.Enabled = $false
        $c = Get-DriveConn ([string]$cmbDrive.Text); if (-not $c) { $c = [string](Get-Setting 'drive') }
        $s.Conn.SelectedIndex = [array]::IndexOf([string[]]@($script:SettingDefs['drive'].Codes), $c)
    } finally { $s.Busy = $false }
    Show-DrivesDialogNote $s
}

function Show-DrivesDialogNote($s) {
    # 12.11 (lot LN-b) : « Nouveau lecteur » : note de la connexion choisie avant l enregistrement (Get-DriveEditPlan :
    # elle a des calibrations sans nom de lecteur), dans l encre neutre
    $p = Get-DriveEditPlan $null ([string]$s.Name.Text) ([string]$s.Conn.Text)
    Set-DrivesDialogState $s ([string]$p.Note) $false
}

function Invoke-DrivesDialogSave($s) {
    # 12.11 (lot LN-b) : bouton « Enregistrer » de frmDrives : decision (Get-DriveEditPlan), execution
    # (Invoke-DriveEditPlan) ; refus dans le texte d etat, la fenetre reste ouverte ; resultat dans le texte d etat, liste
    # a jour, ligne du lecteur modifie choisie. Rend le resultat d Invoke-DriveEditPlan
    $row = Get-DrivesDialogRow $s
    $plan = Get-DriveEditPlan $row ([string]$s.Name.Text) ([string]$s.Conn.Text)
    $r = Invoke-DriveEditPlan $plan
    if ($r.Error) { Set-DrivesDialogState $s ([string]$r.Error) $true; return $r }
    if (-not $r.Ok) { return $r }
    Update-DrivesDialog $s ([string]$plan.Name)
    Set-DrivesDialogState $s ([string]$r.Text) $false
    return $r
}

function Invoke-DrivesDialogDelete($s) {
    # 12.11 (lot LN-b) : bouton « Supprimer... » de frmDrives (Remove-DriveEntry) ; ensuite, mode « Nouveau lecteur »
    $r = Remove-DriveEntry (Get-DrivesDialogRow $s)
    if ($r.Error) { Set-DrivesDialogState $s ([string]$r.Error) $true; return $r }
    if (-not $r.Ok) { return $r }
    Update-DrivesDialog $s
    Start-DrivesDialogNew $s
    Set-DrivesDialogState $s ([string]$r.Text) $false
    return $r
}

function Show-DrivesDialog {
    # 12.11 (lot LN-b) : carte « Lecteurs enregistres » de l Accueil (540) : refusee pendant une operation (texte qui porte
    # le libelle rendu par Get-AppBusy, la fonction qui decide : la pause d une mesure continue et une detection des
    # lecteurs en sont), sinon frmDrives (New-DrivesDialog), modale ; images et polices liberees a la fermeture
    $busy = Get-AppBusy -Text
    if ($busy) { [void](Show-AppMessage ((T 'Lecteurs enregistrés : opération en cours ({0}). Réessayez quand elle est terminée.') -f "$busy") (T 'Lecteurs enregistrés') 'OK' 'Information'); return }
    $s = New-DrivesDialog
    [void](Set-DlgFit $s.Dlg ([System.Windows.Forms.Screen]::FromControl($form).WorkingArea))
    try { [void]$s.Dlg.ShowDialog($form) } finally { $script:DrvDlg = $null; Clear-DlgGdi $s.Dlg $s.Gdi }
}
# ============================== FONCTIONS : CONFIGURATION ======================

# --- Reglages a source unique (12.8, point 7) ----------------------------------
# Table $script:SettingDefs (040-etat-formats). Une valeur passe toujours par Set-Setting : bornes et type
# (ConvertTo-SettingValue), stockage (Set-SettingStore), recopie dans les controles d onglet lies sous la garde de
# reentrance $script:SettingSync, puis reglages et affichages dependants (Update-SettingDependents, aiguillage statique).
# Les gestionnaires propres des controles (Update-SlowUi, Update-PrecompForImage...) restent attaches a leurs controles :
# ils s executent a chaque changement, qu il vienne de l utilisateur ou de Set-Setting. Les dialogues (frmHomeCalib,
# frmClean) lisent le reglage a leur ouverture et l ecrivent quand l action est lancee. Un seul Import-Settings
# (Load-Config), Export-Settings (Save-Config) et Reset-Settings (Set-Defaults) pour tous les reglages de la table.

function ConvertTo-SettingValue([string]$k, $v) {
    # Valeur ramenee au type et aux bornes du reglage $k ; absente, tableau ou illisible : defaut. Enum : code exact, ou
    # ancien texte traduit (Legacy, francais ou anglais), ou rang entier (Json 'index', configuration 12.7)
    $d = $script:SettingDefs[$k]
    if (-not $d) { return $null }
    if ($null -eq $v -or $v -is [array]) { return $d.Def }
    switch ($d.Type) {
        'bool' {
            if ($v -is [bool]) { return $v }
            $s = ([string]$v).Trim()
            if ($s -eq 'True') { return $true }
            if ($s -eq 'False') { return $false }
            return $d.Def
        }
        'int' {
            if ($v -is [bool]) { return $d.Def }
            $x = 0.0
            if (-not [double]::TryParse(([string]$v).Trim(), [System.Globalization.NumberStyles]::Float, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$x) -or [double]::IsNaN($x) -or [double]::IsInfinity($x)) { return $d.Def }
            return [int][math]::Max([double]$d.Min, [math]::Min([double]$d.Max, [math]::Round($x)))
        }
        'double' {
            if ($v -is [bool]) { return $d.Def }
            $x = 0.0
            if (-not [double]::TryParse(([string]$v).Trim(), [System.Globalization.NumberStyles]::Float, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$x) -or [double]::IsNaN($x) -or [double]::IsInfinity($x)) { return $d.Def }
            return [double][math]::Max([double]$d.Min, [math]::Min([double]$d.Max, $x))
        }
        'string' {
            # 12.8 (lot 4b) : texte libre (chemin de la liste de reference) ; booleen : defaut
            if ($v -is [bool]) { return $d.Def }
            return ([string]$v).Trim()
        }
        'enum' {
            $s = [string]$v
            foreach ($c in $d.Codes) { if ($c -ceq $s) { return $c } }
            if ($d.Legacy -and $d.Legacy.ContainsKey($s)) { return $d.Legacy[$s] }
            if ($d.Json -eq 'index' -and $v -isnot [bool]) {
                $x = 0.0
                if ([double]::TryParse($s.Trim(), [System.Globalization.NumberStyles]::Float, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$x) -and $x -eq [math]::Floor($x) -and $x -ge 0 -and $x -lt $d.Codes.Count) { return $d.Codes[[int]$x] }
            }
            return $d.Def
        }
    }
    return $d.Def
}

function Get-Setting([string]$k) {
    # Valeur courante du reglage $k. Reglages a variable propre (Var) : la variable, que lisent aussi le code existant,
    # les fins de test et l enveloppe du prechauffage de make-test (CalWarmupMinutes)
    switch ($k) {
        'warmMinutes'        { return [double]$script:CalWarmupMinutes }
        'precompThresholdNs' { return [int]$script:PrecompThresholdNs }
        'jitterOk'           { return [int]$script:JitterOk }
        'jitterWatch'        { return [int]$script:JitterWatch }
        'contentKMid'        { return [double]$script:ContentKMid }     # 12.8.1 : niveaux de la mesure sur l image (276)
        'contentKLow'        { return [double]$script:ContentKLow }
        'contentKeepMeasures' { return [int]$script:ContentKeepMeasures }   # 12.9 (D6) : relectures gardees (276)
    }
    return $script:Settings[$k]
}

function Set-SettingStore([string]$k, $v) {
    # Stockage d une valeur deja bornee ; seuils de jitter : paire bornee par Set-JitterThresholds (A SURVEILLER au moins
    # 10 ns au-dessus de SAIN)
    switch ($k) {
        'warmMinutes'        { $script:CalWarmupMinutes = [double]$v; return }
        'precompThresholdNs' { $script:PrecompThresholdNs = [int]$v; return }
        'jitterOk'           { Set-JitterThresholds ([int]$v) ([int]$script:JitterWatch); return }
        'jitterWatch'        { Set-JitterThresholds ([int]$script:JitterOk) ([int]$v); return }
        'contentKMid'        { $script:ContentKMid = [double]$v; return }
        'contentKLow'        { $script:ContentKLow = [double]$v; return }
        'contentKeepMeasures' { $script:ContentKeepMeasures = [int]$v; return }
    }
    $script:Settings[$k] = $v
}

function Set-SettingCtlValue($c, [string]$k, $v) {
    # Valeur affichee par un controle lie (CheckBox, ComboBox dans l ordre des codes, NumericUpDown borne a ses limites) ;
    # propriete modifiee seulement si elle change (pas d evenement inutile)
    if ($c -is [System.Windows.Forms.CheckBox]) { if ($c.Checked -ne [bool]$v) { $c.Checked = [bool]$v } }
    elseif ($c -is [System.Windows.Forms.ComboBox]) {
        # 12.11 (lot LN-b) : avec des lecteurs enregistres, la liste du bandeau porte des lecteurs et le reglage drive leur
        # connexion : le lecteur choisi reste s il est sur cette connexion, sinon le lecteur retenu pour elle (112)
        if ($k -eq 'drive' -and $script:DriveReg.Count -gt 0) { Sync-DriveCombo; return }
        $i = [array]::IndexOf([string[]]$script:SettingDefs[$k].Codes, [string]$v)
        if ($i -lt $c.Items.Count -and $c.SelectedIndex -ne $i) { $c.SelectedIndex = $i }
    }
    elseif ($c -is [System.Windows.Forms.NumericUpDown]) {
        $x = [decimal]$v
        if ($x -lt $c.Minimum) { $x = $c.Minimum } elseif ($x -gt $c.Maximum) { $x = $c.Maximum }
        if ($c.Value -ne $x) { $c.Value = $x }
    }
}

function Set-Setting([string]$k, $v, $from = $null) {
    # Nouvelle valeur du reglage $k : bornee, stockee si elle change, recopiee dans les controles lies (sauf $from, le
    # controle qui l a changee ; valeur inchangee : controles resynchronises), puis propagee. Garde sauvegardee et
    # retablie : un appel imbrique ne leve pas la garde d un appel en cours
    if (-not $script:SettingDefs.Contains($k)) { return }
    $nv = ConvertTo-SettingValue $k $v
    $cur = Get-Setting $k
    if (-not ($null -ne $cur -and $cur -eq $nv -and $cur.GetType() -eq $nv.GetType())) { Set-SettingStore $k $nv }
    $nv = Get-Setting $k
    $sv = $script:SettingSync; $script:SettingSync = $true
    try {
        if ($script:SettingCtl.ContainsKey($k)) {
            foreach ($c in @($script:SettingCtl[$k])) { if ($c -and -not $c.IsDisposed -and -not [object]::ReferenceEquals($c, $from)) { Set-SettingCtlValue $c $k $nv } }
        }
    } finally { $script:SettingSync = $sv }
    Update-SettingDependents $k
}

function Register-SettingCtl([string]$k, $c) {
    # Liaison directe d un controle d onglet au reglage $k : toute modification du controle (utilisateur, code, fin de
    # test) passe par Set-Setting, sauf sous la garde (recopie par Set-Setting). Aucune valeur posee ici : Set-Defaults,
    # puis Load-Config, initialisent les controles au demarrage
    if (-not $script:SettingCtl.ContainsKey($k)) { $script:SettingCtl[$k] = New-Object System.Collections.ArrayList }
    [void]$script:SettingCtl[$k].Add($c); $script:SettingOf[$c] = $k
    # 12.11 (lot LN-b) : liste du bandeau, element au-dela des six connexions (lecteur enregistre) : le reglage drive recoit
    # sa connexion (Get-DriveConn, 112)
    if ($c -is [System.Windows.Forms.CheckBox]) { $c.Add_CheckedChanged({ if (-not $script:SettingSync) { Set-Setting $script:SettingOf[$this] $this.Checked $this } }) }
    elseif ($c -is [System.Windows.Forms.ComboBox]) { $c.Add_SelectedIndexChanged({ if (-not $script:SettingSync -and $this.SelectedIndex -ge 0) { $kk = $script:SettingOf[$this]; $cd = $script:SettingDefs[$kk].Codes[$this.SelectedIndex]; if ($kk -eq 'drive' -and $this.SelectedIndex -ge @($script:SettingDefs[$kk].Codes).Count) { $cd = Get-DriveConn ([string]$this.SelectedItem) }; Set-Setting $kk $cd $this } }) }
    elseif ($c -is [System.Windows.Forms.NumericUpDown]) { $c.Add_ValueChanged({ if (-not $script:SettingSync) { Set-Setting $script:SettingOf[$this] $this.Value $this } }) }
}

function Update-SettingDependents([string]$k) {
    # Propagation d un changement : aiguillage statique (appels visibles par impact.ps1 et par static-check). Les controles
    # lies portent deja leurs gestionnaires (ecriture lente, mode de calibration, profil, mesure de qualite) ; restent ici
    # les reglages sans controle propre ou affiches ailleurs : duree du prechauffage (textes et cases de l onglet
    # Ecriture), mesure de la disquette (case cochee et verrouillee en test rapide, D5) ; lot 2 : lecteur de la
    # restauration (cadre 1, D10) et ligne du format detecte (D11) ; format de la comparaison (format saisi, ligne du format
    # detecte, D13) ; lot 4b : liste de reference de la Bibliotheque (dechargee, relue a la prochaine demande)
    switch ($k) {
        'warmMinutes'      { Update-SlowUi }
        'levelBeforeWrite' { Update-SlowUi }
        'levelBeforeWriteMode' { Update-SlowUi; Update-RsRules }      # 12.8 (S3) : liste active, texte de la case de la mesure ; 12.10 (relecture de la RC) : regles de la restauration (mesure complete)
        'drive'            { Update-RsDrive }
        'restoreFormat'    { Update-RsFmtFound; Update-RsCalib }   # 12.10 (relecture de la RC) : regles et infobulle selon le lecteur cible
        'compareFormat'    { Update-CmpFmtFound }
        'libDat'           { Reset-LibDat }
    }
}

function Get-SettingText([string]$k, $v) {
    # Texte de la valeur $v dans la langue de l interface (element de la liste liee) : enregistre sous LegacyKey pour une
    # 12.7 ; sans liste liee : le code
    $d = $script:SettingDefs[$k]
    $i = [array]::IndexOf([string[]]$d.Codes, [string]$v)
    if ($i -ge 0 -and $script:SettingCtl.ContainsKey($k)) {
        foreach ($c in @($script:SettingCtl[$k])) { if ($c -is [System.Windows.Forms.ComboBox] -and $i -lt $c.Items.Count) { return [string]$c.Items[$i] } }
    }
    return [string]$v
}

function Reset-Settings {
    # Set-Defaults : defaut de la table pour chaque reglage
    foreach ($k in @($script:SettingDefs.Keys)) { Set-Setting $k $script:SettingDefs[$k].Def }
}

function Import-Settings($cfg, [string[]]$Only = @(), [string[]]$Except = @()) {
    # Load-Config : chaque reglage lu a sa cle (enum : code d abord, sinon ancien texte traduit de LegacyKey), puis
    # Set-Setting ; cle absente : defaut. Duree du prechauffage : lignes de journal de la 12.6 (valeur illisible, ou
    # ramenee aux bornes). Only / Except : reglages lus a cet appel (Load-Config lit chaque reglage une fois, a la
    # place qu il avait en 12.7)
    foreach ($k in @($script:SettingDefs.Keys)) {
        if ($Only.Count -gt 0 -and $Only -notcontains $k) { continue }
        if ($Except -contains $k) { continue }
        $d = $script:SettingDefs[$k]
        $sec = Get-Cfg $cfg $d.Sec $null
        $raw = Get-Cfg $sec $d.Key $null
        if ($d.LegacyKey) {
            $ok = $false
            if ($null -ne $raw -and $raw -isnot [array]) { foreach ($c in $d.Codes) { if ($c -ceq [string]$raw) { $ok = $true } } }
            if (-not $ok) { $raw = Get-Cfg $sec $d.LegacyKey $null }
        }
        $v = ConvertTo-SettingValue $k $raw
        if ($k -eq 'warmMinutes' -and $null -ne $raw) {
            $wd = 0.0
            if ($raw -isnot [bool] -and $raw -isnot [array] -and [double]::TryParse(([string]$raw).Trim(), [System.Globalization.NumberStyles]::Float, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$wd) -and -not [double]::IsNaN($wd) -and -not [double]::IsInfinity($wd)) {
                if ($v -ne $wd) { Append-Log ((T "Préchauffage du lecteur (calWarmupMinutes) de {0} min ramené à {1} min : il va de 0 à {2} min.") -f "$raw", "$v", "$($d.Max)") }
            } else { Append-Log ((T "Préchauffage du lecteur (calWarmupMinutes) illisible ({0}) : {1} min par défaut.") -f "$raw", "$($d.Def)") }
        }
        Set-Setting $k $v
    }
}

function Export-Settings($cfg) {
    # Save-Config : chaque reglage ecrit a sa cle (Json 'index' : rang ; Text : texte traduit aussi sous LegacyKey) ;
    # section creee si elle manque
    foreach ($k in @($script:SettingDefs.Keys)) {
        $d = $script:SettingDefs[$k]
        if (-not $cfg.Contains($d.Sec)) { $cfg[$d.Sec] = @{} }
        $v = Get-Setting $k
        if ($d.Json -eq 'index') { $cfg[$d.Sec][$d.Key] = [int][math]::Max(0, [array]::IndexOf([string[]]$d.Codes, [string]$v)) }
        else { $cfg[$d.Sec][$d.Key] = $v }
        if ($d.Text) { $cfg[$d.Sec][$d.LegacyKey] = Get-SettingText $k $v }
    }
}

function Update-LegacyCleanDefault($cfg) {
    # 12.8 (D9) : nettoyage de l onglet Outils a 3 x 500 ms par defaut ; la 12.7 ecrivait son defaut, 3 x 100 ms, a chaque
    # enregistrement. Configuration d une version anterieure (aucune cle 12.8 : write.calibWarmup, ui.homeCalHeads) avec
    # exactement l ancien defaut : nouveau defaut, ligne de journal ; toute autre valeur est gardee. Load-Config, apres
    # Import-Settings
    if ($null -ne (Get-Cfg (Get-Cfg $cfg 'write' $null) 'calibWarmup' $null) -or $null -ne (Get-Cfg (Get-Cfg $cfg 'ui' $null) 'homeCalHeads' $null)) { return }
    if ((Get-Setting 'cleanPasses') -ne 3 -or (Get-Setting 'cleanLinger') -ne 100) { return }
    Set-Setting 'cleanLinger' $script:SettingDefs['cleanLinger'].Def
    Append-Log ((T "Nettoyage de l'onglet Outils : ancien réglage par défaut (3 passes, {0} ms par position) remplacé par le nouveau, 3 passes de {1} ms par position, comme le préréglage « Standard » de la fenêtre « Nettoyage des têtes ».") -f '100', "$(Get-Setting 'cleanLinger')")
}

function Update-LegacyLevelMode($cfg) {
    # 12.8.1 (spec-1281 § C.6) : liste « Mesure : » de l onglet Ecriture. Configuration d une version anterieure (section
    # write sans contentCalc) a « rapide » : la 12.8 ecrivait son defaut a chaque enregistrement, defaut et choix explicite
    # ne se distinguent pas : mesure sur l image a ecrire, ligne de journal ; « complete » (choix explicite, la 12.8 ayant
    # « rapide » pour defaut) gardee. contentCalc est ecrit au prochain enregistrement : migration faite une fois.
    # Load-Config, apres Import-Settings des reglages de l ecriture lente
    $w = Get-Cfg $cfg 'write' $null
    if ($null -eq $w -or $null -ne (Get-Cfg $w 'contentCalc' $null)) { return }
    if ((Get-Setting 'levelBeforeWriteMode') -ne 'quick') { return }
    Set-Setting 'levelBeforeWriteMode' 'content'
    Append-Log (T "Mesure de la disquette avant l'écriture lente : la liste « Mesure : » passe de « rapide » à « sur l'image à écrire », la nouvelle mesure de la version 12.8.1. Pour revenir à la calibration rapide, choisissez « rapide, au motif ».")
}

function Update-LegacyEraseMode($cfg) {
    # 12.8.2 : case « Effacer avant d ecrire » (write.preErase, auparavant « Pre-effacer chaque piste »). Configuration
    # d une version anterieure (section write sans le marqueur eraseMode = 'hfreq') avec la case decochee : son sens
    # change (double densite : effacement haute frequence, et non plus pre-effacement en continu), elle est recochee une
    # fois, ligne de journal ; Save-Config ecrit le marqueur, le choix suivant de l utilisateur est garde. Load-Config,
    # apres la lecture de la case
    $w = Get-Cfg $cfg 'write' $null
    if ($null -eq $w -or [string](Get-Cfg $w 'eraseMode' '') -eq 'hfreq') { return }
    if ($chkWPreErase.Checked) { return }
    $chkWPreErase.Checked = $true
    Append-Log (T "Case « Effacer avant d'écrire » (auparavant « Pré-effacer chaque piste ») recochée, une seule fois : son effet change dans cette version. Sur une disquette double densité, elle efface désormais les pistes en haute fréquence avant l'écriture, au lieu du pré-effacement en continu qui coûtait de la marge de lecture ; en haute densité, elle pré-efface comme avant. Décochez-la de nouveau si vous ne voulez aucun effacement avant l'écriture.")
}

function Test-ContentLevelSettings($cfg) {
    # 12.8.1 (spec-1281 § A.4) : niveaux moyen et bas de la mesure sur l image (contentKMid, contentKLow, configuration
    # seulement) controles ensemble au chargement : valeurs lisibles et dans les bornes de la table, et bas <= moyen - 0,2 ;
    # sinon les deux defauts, ligne de journal. Load-Config, apres Import-Settings
    $w = Get-Cfg $cfg 'write' $null
    $bad = $false
    foreach ($k in @('contentKMid', 'contentKLow')) {
        $raw = Get-Cfg $w $k $null
        if ($null -eq $raw) { continue }
        $x = ConvertTo-FiniteOrNull $raw
        if ($null -eq $x -or [math]::Abs([double]$x - [double](Get-Setting $k)) -gt 1e-9) { $bad = $true }
    }
    $m = [double](Get-Setting 'contentKMid'); $l = [double](Get-Setting 'contentKLow')
    if ($l -gt $m - 0.2 + 1e-9) { $bad = $true }
    if (-not $bad) { return }
    $rm = Get-Cfg $w 'contentKMid' $m; $rl = Get-Cfg $w 'contentKLow' $l
    $dm = [double]$script:SettingDefs['contentKMid'].Def; $dl = [double]$script:SettingDefs['contentKLow'].Def
    Set-Setting 'contentKMid' $dm; Set-Setting 'contentKLow' $dl
    Append-Log ((T "Niveaux de la mesure sur l'image (contentKMid, contentKLow) incohérents ({0} ; {1}) : {2} et {3} par défaut. Le niveau bas va de 0 à 0,5, le niveau moyen de 0,3 à 0,8, et le niveau bas reste inférieur d'au moins 0,2 au niveau moyen.") -f "$rm", "$rl", (Format-UiNum $dm '0.0#'), (Format-UiNum $dl '0.0#'))
}

# --- Configuration -------------------------------------------------------------
function Set-Defaults {
    $script:CalHardNs = $script:CalHardNsDefault; $script:CalHardNsUser = $script:CalHardNs; Set-CalibScale ''   # 12.7 : bareme double densite
    $script:HomeCalFmt = 'amiga.amigados'
    $txtDev.Text = ''
    $chkTime.Checked = $false

    $txtLibRoot.Text = ''
    $txtLibFilter.Text = ''
    $chkLibImgOnly.Checked = $false
    # 12.8 (lot 4a) : options de la recherche et filtres de la liste des resultats (non enregistres)
    $chkLibInDirs.Checked = $false
    $chkLibHideMod.Checked = $false
    $chkLibOrig.Checked = $false
    if ($cmbLibFmt.Items.Count -gt 0) { $cmbLibFmt.SelectedIndex = 0 }
    if ($cmbLibLang.Items.Count -gt 0) { $cmbLibLang.SelectedIndex = 0 }

    $txtWFile.Text = ''
    $cmbWFmt.SelectedIndex = 0
    $chkWPreErase.Checked = $true
    $chkWEraseEmpty.Checked = $true
    $chkWNoVerify.Checked = $false
    $chkWReverse.Checked = $false
    $chkWHard.Checked = $false
    $chkWTG43.Checked = $false
    $numWRetries.Value = 10
    $chkWPrecomp.Checked = $true
    $txtWPrecomp.Text = $script:PrecompStd
    $txtWPrecomp1.Text = $script:PrecompStd
    $chkWPostCheck.Checked = $true
    $numWRepair.Value = 3
    # 12.8 (point 7) : reglages de la table (lecteur, mode de calibration, ecriture lente, prechauffages et leur duree,
    # mesure de la disquette, profil precomp, seuil de famille, carte « Calibrer le lecteur », mesure de l onglet
    # Qualite, seuils de jitter, nettoyage de l onglet Outils) : defauts de la table, y compris le seuil precompThresholdNs
    # (12.7 : non remis par defaut)
    Reset-Settings
    Update-SlowUi
    $lblWProfileInfo.Text = ''
    $txtWTracks.Text = ''
    $cmbWDensel.SelectedIndex = 0
    $txtWFakeIdx.Text = ''
    $txtWDiskdefs.Text = ''

    $txtRFile.Text = ''
    $cmbRFmt.SelectedIndex = 0
    $numRevs.Value = 5
    $numRRetries.Value = 10
    $txtRTracks.Text = ''
    $chkRRaw.Checked = $false
    $chkRRev.Checked = $false
    $cmbRDensel.SelectedIndex = 0
    $txtRDiskdefs.Text = ''

    $txtCvIn.Text = ''
    $txtCvOut.Text = ''
    $cmbCvFmt.SelectedIndex = 0
    $txtCvTracks.Text = ''

    $cmbAlHead.SelectedIndex = 2
    $txtAlCyls.Text = '0,10,20,30,40,50,60,70'
    $numAlRevs.Value = 3
    $chkAlLoop.Checked = $false
    $numAlPause.Value = 2
    $chkAlGuide.Checked = $false

    $txtCmpRef.Text = ''
    # 12.8 (D13) : format de la comparaison (compareFormat, detection automatique) remis par Reset-Settings
    $numCmpRetries.Value = 10
    $txtCmpResult.Text = (T "Compare le contenu physique d'une disquette à une image de référence (IPF, ADF, SCP, HFE...).`r`n`r`n") +
                         (T "Principe : la référence est convertie par gw dans le format de décodage choisi, la disquette est`r`n") +
                         (T "lue dans ce même format, puis les deux fichiers sont comparés octet par octet, secteur par secteur.`r`n`r`n") +
                         (T "Détection automatique (par défaut) : format déduit de la référence, puis vérifié sur deux pistes de la`r`ndisquette avant la lecture complète.`r`n`r`n") +
                         (T "Limite : seules les pistes décodables dans ce format sont comparées. Les pistes de protection`r`n") +
                         (T "(non-AmigaDOS) d'un IPF n'apparaissent pas dans la comparaison. Le flux brut (SCP) n'est jamais`r`n") +
                         (T "identique d'une lecture à l'autre : il n'existe pas de comparaison bit à bit au niveau flux.")

    $numSeek.Value = 0
    $txtEraseTracks.Text = ''
    $script:CleanPrefs = @{ Wet = $true; Cyls = 80; Preset = 0 }      # fenetre de nettoyage : humide, 80 pistes, Standard
    $numPin.Value = 2
    $cmbPinLvl.SelectedIndex = 0

    foreach ($k in $script:DelayCtrls.Keys) {
        $c = $script:DelayCtrls[$k]
        $c.Chk.Checked = $false
        $c.Num.Value = $c.Def
    }

    # 12.8 (D10, D13) : restauration a un seul lecteur (celui du bandeau) ; format (restore.formatChoice) dans la table
    $txtRsDir.Text = ''; $txtRsName.Text = ''
    Update-RsRules; Reset-RsSteps; Update-RsFmtFound
    $cmbHelpAct.SelectedItem = 'write'
    $txtC.Text = 'write --erase-empty --retries=10 --precomp 40=140 "jeu.ipf"'   # 12.8.2 : sans --pre-erase (disquette double densite)
    Update-CurveButton $txtWFile.Text
    # 12.10 : liste « Lecteur cible » du lecteur du bandeau (choix par lecteur source, gardes comme les calibrations :
    # $script:TargetDrives n est pas remis)
    Update-TargetDriveUi
}

function Backup-ConfigBeforeRef([string[]]$keys, [string]$why = 'replace', [string]$Protect = '') {
    # 12.8 (lot 1c, point 4) : copie octet pour octet du fichier de configuration sur disque (dernier etat enregistre, qui
    # contient encore la reference en place), juste avant qu une reference existante soit remplacee ($why 'replace' :
    # Complete-PrecompCalib, toute calibration complete) ou effacee ('reset' : Reset-CalibProfiles). Rien si aucune des
    # cles n a de courbe (courbe d un autre calcul en attente du choix comprise) ou sans fichier. Nom :
    # <fichier>.ref-<familles>-<AAAAMMJJ-HHMM>.bak, a cote du fichier, date de la plus recente des references remplacees
    # (meme nom : meme reference, copie remplacee par l etat plus recent) ; date de modification de la copie mise a l heure
    # de la copie (rotation : copies les plus recentes, meme apres le retablissement manuel d une ancienne copie).
    # Rotation : ConfigRefBackupKeep copies gardees, les plus anciennes <fichier>.ref-*.bak supprimees (copies de
    # l application seulement), une ligne de journal par fichier. Echec de la copie : une ligne de journal, l operation
    # continue, sans rotation. Retablir une copie reste manuel (application fermee). Renvoie le chemin de la copie ou $null
    # 12.11 (L7) : motif 'back' (Restore-CalibBack, 240 : retour a une calibration precedente, qui annule le retour si la
    # copie echoue) : si le nom calcule existe deja (annuler un retour : la copie d origine de la calibration retablie
    # porte la date de la courbe remplacee), la copie prend le suffixe -r<AAAAMMJJ-HHmmss> avant .bak, puis -2, -3... si ce
    # nom existe aussi : un retour n ecrase jamais une copie. Elle reste couverte par la rotation <fichier>.ref-*.bak.
    # Fichier de configuration absent : echec note comme celui de la copie. $Protect : copie que la rotation de cet appel
    # ne supprime jamais (la copie lue par le retour)
    $oc = $script:OldCalib
    $cvs = @{}
    foreach ($k in @($keys | Where-Object { $_ } | Sort-Object -Unique)) {
        # 12.10 : cle de magasin « lecteur|cle », ou cle de courbe du lecteur courant ; courbes du magasin
        $p = Split-DriveCurveKey $k; $sk = Get-DriveCurveKey $p.Drive $p.Key
        $cv = Get-DriveCurve $p.Drive $p.Key
        if (-not $cv -and $oc -and $oc.Curves -and $oc.Curves.Contains($sk)) { $cv = $oc.Curves[$sk] }
        if ($cv) { $cvs[$sk] = $cv }
    }
    if ($cvs.Count -eq 0) { return $null }
    $cfg = [string]$script:ConfigFile
    if (-not $cfg -or (-not (Test-Path -LiteralPath $cfg -PathType Leaf) -and $why -ne 'back')) { return $null }
    $newest = @($cvs.Keys | Sort-Object { Get-CurveDate $cvs[$_] } -Descending)[0]
    $dt = Get-CurveDate $cvs[$newest]
    $stamp = if ($dt -ne [datetime]::MinValue) { $dt.ToString('yyyyMMdd-HHmm', [System.Globalization.CultureInfo]::InvariantCulture) } else { 'sans-date' }
    $fams = @($cvs.Keys | ForEach-Object { $ck = (Split-DriveCurveKey $_).Key; if ($ck -like 'hd*') { 'hd' } elseif ($ck -like 'long*') { 'long' } else { 'std' } } | Sort-Object -Unique)
    $leaf = [System.IO.Path]::GetFileName($cfg); $dir = Split-Path -Parent $cfg
    $bak = Join-Path $dir ($leaf + '.ref-' + ($fams -join '+') + '-' + $stamp + '.bak')
    if ($why -eq 'back' -and (Test-Path -LiteralPath $bak)) {
        # 12.11 (L7, m6) : nom deja pris : suffixe -r<date de la copie>, puis -2, -3... (jamais d ecrasement)
        $rb = Join-Path $dir ($leaf + '.ref-' + ($fams -join '+') + '-' + $stamp + '-r' + (Get-Date).ToString('yyyyMMdd-HHmmss', [System.Globalization.CultureInfo]::InvariantCulture))
        $bak = $rb + '.bak'; $i = 1
        while (Test-Path -LiteralPath $bak) { $i++; $bak = $rb + '-' + $i + '.bak' }
    }
    $famTxt = (@($fams | ForEach-Object { Get-CalibFamilyName $_ })) -join ', '
    $dateTxt = [string]$cvs[$newest].Date
    try {
        # File.Copy : copie du fichier seul (jamais dans un dossier de ce nom), remplace une copie de meme nom ; 12.11 :
        # jamais avec le motif back
        [System.IO.File]::Copy($cfg, $bak, ($why -ne 'back'))
        [System.IO.File]::SetLastWriteTime($bak, (Get-Date))
    } catch {
        $msg = ([string]$(if ($_.Exception.InnerException) { $_.Exception.InnerException.Message } else { $_.Exception.Message })).Trim().TrimEnd('.')
        if ($why -eq 'reset') { Append-Log ((T "Configuration non sauvegardée avant l'effacement des calibrations ({0}) : {1}. L'effacement continue sans copie.") -f "$famTxt", "$msg") }
        elseif ($why -eq 'back') { Append-Log ((T "Configuration non sauvegardée avant le retour à une calibration précédente ({0}) : {1}. Retour annulé : rien n'est modifié.") -f "$famTxt", "$msg") }
        else { Append-Log ((T "Configuration non sauvegardée avant le remplacement de la référence {0} : {1}. La calibration continue sans copie.") -f "$famTxt", "$msg") }
        return $null
    }
    if ($why -eq 'reset') { Append-Log ((T "Configuration sauvegardée avant l'effacement des calibrations (référence {0} du {1}) : {2}") -f "$famTxt", "$dateTxt", "$bak") }
    elseif ($why -eq 'back') { Append-Log ((T "Configuration sauvegardée avant le retour à une calibration précédente (référence {0} du {1}) : {2}") -f "$famTxt", "$dateTxt", "$bak") }
    else { Append-Log ((T "Configuration sauvegardée avant le remplacement de la référence {0} du {1} : {2}") -f "$famTxt", "$dateTxt", "$bak") }
    $keep = [math]::Max(1, [int]$script:ConfigRefBackupKeep)
    $protName = if ($Protect) { [System.IO.Path]::GetFileName($Protect) } else { '' }
    try {
        $bakName = [System.IO.Path]::GetFileName($bak)
        $all = @(Get-ChildItem -LiteralPath $dir -File -ErrorAction Stop | Where-Object { $_.Name -like ($leaf + '.ref-*.bak') -and $_.Name -ne $bakName } | Sort-Object LastWriteTime -Descending)
        foreach ($f in @($all | Select-Object -Skip ($keep - 1))) {
            if ($protName -and $f.Name -eq $protName) { continue }   # 12.11 (L7) : copie lue par le retour, jamais supprimee ici
            try { Remove-Item -LiteralPath $f.FullName -Force -ErrorAction Stop; Append-Log ((T "Ancienne sauvegarde de configuration supprimée ({1} gardées) : {0}") -f "$($f.FullName)", "$keep") } catch { }
        }
    } catch { }
    return $bak
}

function Export-CurveView($oc) {
    # 12.10 : bloc write.precompCurves : vue du lecteur courant (les neuf cles, haute densite seulement avec une courbe),
    # courbe d un autre calcul en attente du choix comprise ; format de la 12.9, qu elle relit tel quel
    $drv = [string]$cmbDrive.Text
    $curvesCfg = [ordered]@{}
    foreach ($k in $script:CurveKeys) {
        $cv = $script:PrecompCurves[$k]
        $sk = Get-DriveCurveKey $drv $k
        if (-not $cv -and $oc -and $oc.Curves.Contains($sk)) { $cv = $oc.Curves[$sk] }
        if (-not $cv -and $k -like 'hd*') { continue }   # 12.7 : cles haute densite ecrites seulement avec une courbe (configuration DD inchangee)
        $curvesCfg[$k] = ConvertTo-CurveConfig $cv
    }
    return $curvesCfg
}

function Export-DriveCurves($oc) {
    # 12.10 : bloc write.driveCurves : magasin de tous les lecteurs, « lecteur|cle » -> courbe, cles triees ; courbes d un
    # autre calcul en attente du choix gardees telles quelles ; une 12.9 ignore ce bloc (et le perd si elle enregistre)
    $o = [ordered]@{}
    $keys = @(@(Get-DriveCurveKeys) + @($(if ($oc -and $oc.Curves) { @($oc.Curves.Keys) })) | Where-Object { $_ } | Sort-Object -Unique)
    foreach ($sk in $keys) {
        $cv = $script:DriveCurves[$sk]
        if (-not $cv -and $oc -and $oc.Curves.Contains($sk)) { $cv = $oc.Curves[$sk] }
        if ($cv) { $o[$sk] = ConvertTo-CurveConfig $cv }
    }
    return $o
}

function Import-DriveCurves($pcv, $dcv, [string]$drive) {
    # 12.10 : courbes de la configuration -> magasin $script:DriveCurves (vide d abord). Bloc driveCurves ($dcv, 12.10) s il
    # existe ; sinon (configuration 12.9) chaque courbe du bloc precompCurves ($pcv) est rangee sous son lecteur (champ drive),
    # une courbe sans lecteur sous $drive (lecteur de la configuration, global.drive). Courbe d un autre calcul
    # (Test-CurveCalcOk) mise de cote. Rend @{ Old (cle de magasin -> courbe, dans l ordre lu) ; N (courbes reprises) ;
    # Migrated (bloc 12.9 lu) ; Drives (lecteurs des courbes lues, tries) }
    $script:DriveCurves = @{}
    $old = [ordered]@{}; $n = 0; $migrated = $false; $drives = @{}
    if ($dcv) {
        foreach ($p in @($dcv.PSObject.Properties)) {
            $sk = [string]$p.Name
            if ($sk.LastIndexOf('|') -le 0) { continue }
            $cv = ConvertFrom-CurveConfig $p.Value
            if (-not $cv) { continue }
            $kd = [string](Split-DriveCurveKey $sk).Drive
            # Courbe sans lecteur (champ drive vide) sous une cle ordinaire : lecteur de la cle (la calibration rapide et le
            # facteur de marque controlent le lecteur de la courbe) ; cle croisee source>cible (12.10, etape 2) : source (Drive,
            # le lecteur qui ecrit) et cible (Target, le lecteur qui relit) de la cle quand les champs sont vides, sinon gardes
            $kx = Split-CrossDrive $kd
            if ($kx) { if (-not [string]$cv.Drive) { $cv.Drive = [string]$kx.Src }; if (-not [string]$cv.Target) { $cv.Target = [string]$kx.Tgt } }
            elseif (-not [string]$cv.Drive) { $cv.Drive = $kd }
            $drives[$kd] = $true
            if (Test-CurveCalcOk $cv) { $script:DriveCurves[$sk] = $cv; $n++ } else { $old[$sk] = $cv }
        }
    } elseif ($pcv) {
        foreach ($k in $script:CurveKeys) {
            $cv = ConvertFrom-CurveConfig (Get-Cfg $pcv $k $null)
            if (-not $cv) { continue }
            $migrated = $true
            if (-not [string]$cv.Drive) { $cv.Drive = $drive }
            $sk = Get-DriveCurveKey ([string]$cv.Drive) $k
            $drives[[string]$cv.Drive] = $true
            if (Test-CurveCalcOk $cv) { $script:DriveCurves[$sk] = $cv; $n++ } else { $old[$sk] = $cv }
        }
    }
    return @{ Old = $old; N = $n; Migrated = $migrated; Drives = @($drives.Keys | Sort-Object) }
}

function Read-DriveCurves($pcv, $dcv, [string]$drive) {
    # 12.11 (L7) : courbes d une configuration lues sans effet sur le magasin (retour a une calibration precedente,
    # Read-CalibBackup) : memes regles qu au chargement, par Import-DriveCurves elle-meme, appelee telle quelle, le magasin
    # en place etant remis ensuite, meme en cas d erreur (finally) ; une seule lecture des blocs, et Import-DriveCurves
    # reste celle de la 12.10. Rend @{ Curves (cle de magasin -> courbe du calcul actuel ou conservee) ; Old (courbes d un
    # autre calcul) ; N ; Migrated ; Drives }
    $keep = $script:DriveCurves
    $r = $null; $cur = @{}
    try {
        $r = Import-DriveCurves $pcv $dcv $drive
        $cur = $script:DriveCurves
    } finally { $script:DriveCurves = $keep }
    return @{ Curves = $cur; Old = $r.Old; N = $r.N; Migrated = $r.Migrated; Drives = $r.Drives }
}

function Read-CalibBackup([string]$path) {
    # 12.11 (L7) : une copie de la configuration (<fichier>.*.bak : copies .ref-, .calib-, .lecteurs- et copies manuelles),
    # lue sans rien changer : toutes ses courbes, du calcul actuel ou non (Read-DriveCurves : bloc driveCurves, sinon
    # courbes d une configuration 12.9 rangees sous leur lecteur, a defaut sous le lecteur de cette copie), et son bloc
    # drives (registre des lecteurs enregistres de son epoque, $null sans bloc ; Resolve-DriveOfEra, 112). Lecture dans un
    # try : fichier absent ou illisible, JSON tronque : Ok faux, Why (message). Sans bloc write ou sans courbe : Ok vrai,
    # aucune courbe. Rend @{ Ok ; Why ; Path ; Name ; When (date de la copie) ; Curves (cle de magasin -> courbe, cles
    # triees) ; Drives ; Drive (lecteur de la copie, global.drive) }
    $res = @{ Ok = $false; Why = ''; Path = $path; Name = ''; When = [datetime]::MinValue; Curves = [ordered]@{}; Drives = $null; Drive = '' }
    try {
        $res.Name = [System.IO.Path]::GetFileName($path)
        $fi = New-Object System.IO.FileInfo($path)
        if (-not $fi.Exists) { throw (New-Object System.IO.FileNotFoundException($path)) }
        $res.When = $fi.LastWriteTime
        $cfg = [System.IO.File]::ReadAllText($path, [System.Text.Encoding]::UTF8) | ConvertFrom-Json
        $res.Drives = Get-Cfg $cfg 'drives' $null
        $res.Drive = [string](ConvertTo-SettingValue 'drive' (Get-Cfg (Get-Cfg $cfg 'global' $null) 'drive' $null))
        $w = Get-Cfg $cfg 'write' $null
        if ($w) {
            $rd = Read-DriveCurves (Get-Cfg $w 'precompCurves' $null) (Get-Cfg $w 'driveCurves' $null) $res.Drive
            foreach ($sk in @(@($rd.Curves.Keys) + @($rd.Old.Keys) | Sort-Object -Unique)) {
                $cv = $rd.Curves[$sk]; if (-not $cv) { $cv = $rd.Old[$sk] }
                if ($cv) { $res.Curves[[string]$sk] = $cv }
            }
        }
        $res.Ok = $true
    } catch {
        $res.Ok = $false; $res.Curves = [ordered]@{}
        $res.Why = ([string]$(if ($_.Exception.InnerException) { $_.Exception.InnerException.Message } else { $_.Exception.Message })).Trim().TrimEnd('.')
    }
    return $res
}

function Get-CalibBackFiles([int]$Max = 40) {
    # 12.11 (L7) : copies lues par le retour a une calibration precedente : <fichier>.*.bak du dossier de la configuration
    # (copies .ref- et .calib- de l application, .lecteurs- des lecteurs enregistres, copies manuelles), les $Max plus
    # recentes. La copie de secours du registre (<fichier>.lecteurs) n en est pas. Chemins rendus un a un
    $cfg = [string]$script:ConfigFile
    if (-not $cfg) { return }
    $leaf = [System.IO.Path]::GetFileName($cfg); $dir = Split-Path -Parent $cfg
    if (-not $dir -or -not (Test-Path -LiteralPath $dir -PathType Container)) { return }
    $fs = @(Get-ChildItem -LiteralPath $dir -File -ErrorAction SilentlyContinue | Where-Object { $_.Name -like ($leaf + '.*.bak') } | Sort-Object -Property @{ Expression = { $_.LastWriteTime }; Descending = $true }, @{ Expression = { $_.Name }; Descending = $true })
    foreach ($f in @($fs | Select-Object -First ([math]::Max(1, $Max)))) { [string]$f.FullName }
}

function Export-TargetDrives {
    # 12.10 : bloc write.targetDrive : lecteur cible des ecritures par lecteur source (Set-TargetDrive, 140), « source » ->
    # « cible », sources triees ; entrees sans effet (cible vide, egale a la source ou inconnue : Get-TargetDrive) omises ;
    # une 12.9 ignore ce bloc
    $o = [ordered]@{}
    if ($null -eq $script:TargetDrives) { return $o }
    foreach ($s in @($script:TargetDrives.Keys | Sort-Object)) { $t = Get-TargetDrive ([string]$s); if ($t) { $o[[string]$s] = $t } }
    return $o
}

function Import-TargetDrives($o) {
    # 12.10 : bloc write.targetDrive -> $script:TargetDrives (vide d abord) ; objet de la configuration (ConvertFrom-Json) ou
    # table ; entree illisible (source ou cible vide, cible egale a la source, lecteur inconnu de la liste du bandeau :
    # Get-DriveIds) ignoree et comptee. Rend @{ N ; Bad }
    $script:TargetDrives = @{}
    $n = 0; $bad = 0
    if ($null -eq $o -or $o -is [array] -or $o -is [string] -or $o -is [ValueType]) { return @{ N = 0; Bad = 0 } }
    $pairs = @()
    if ($o -is [System.Collections.IDictionary]) { foreach ($k in @($o.Keys)) { $pairs += ,@([string]$k, $o[$k]) } }
    else { foreach ($p in @($o.PSObject.Properties)) { $pairs += ,@([string]$p.Name, $p.Value) } }
    $ids = Get-DriveIds                    # tableau protege par la virgule : pas de @() autour de l appel
    foreach ($pr in $pairs) {
        $s = ([string]$pr[0]).Trim(); $t = ([string]$pr[1]).Trim()
        if (-not $s -or -not $t -or $s -eq $t -or $ids -notcontains $s -or $ids -notcontains $t) { $bad++; continue }
        $script:TargetDrives[$s] = $t; $n++
    }
    return @{ N = $n; Bad = $bad }
}

function Save-Config {
    $delays = @{}
    foreach ($k in $script:DelayCtrls.Keys) {
        $c = $script:DelayCtrls[$k]
        $delays[$k] = @{ on = [bool]$c.Chk.Checked; val = [int]$c.Num.Value }
    }
    $oc = $script:OldCalib          # calibrations d un autre calcul en attente du choix : gardees telles quelles
    # 12.10 : bloc precompCurves = vue du lecteur courant (lisible par une 12.9) ; bloc driveCurves = magasin de tous les
    # lecteurs, cles « lecteur|cle » (Export-DriveCurves) ; niveaux d une reference mise de cote : reference cherchee dans
    # le magasin de leur lecteur
    $curvesCfg = Export-CurveView $oc
    $dcCfg = Export-DriveCurves $oc
    $lvCfg = @(@($script:LevelShifts.Values) | Where-Object { $_ } | ForEach-Object { ConvertTo-LevelConfig $_ })
    if ($oc) { $lvCfg += @(@($oc.Levels.Values) | Where-Object { $_ -and -not (Get-DriveCurve ([string]$_.Drive) ([string]$_.RefKey)) } | ForEach-Object { ConvertTo-LevelConfig $_ }) }
    # 12.8 (lot 1c, § 10.2) : memoire par marque de disquette (une 12.7 l ignore)
    $brCfg = @(@($script:LevelBrands) | Where-Object { $_ } | ForEach-Object { ConvertTo-LevelBrandConfig $_ })
    # 12.8.1 (spec-1281 § C.5) : facteurs mesures des lecteurs (mesure de la disquette sur l image, un enregistrement par
    # tete mesuree) ; une 12.8 les ignore. 12.10 : lecteur cible des ecritures par lecteur source (Export-TargetDrives) ;
    # le bloc targetCorrection de la correction « lecteur cible » Dk n est plus ecrit (une 12.9 relit sa configuration sans lui)
    $cmCfg = @(@($script:ContentMeasures) | Where-Object { $_ } | ForEach-Object { ConvertTo-ContentConfig $_ })
    $tdCfg = Export-TargetDrives
    # 12.11 : lecteurs enregistres (Export-DriveRegistry, 112) : bloc drives, au premier niveau ; $null tant que personne
    # n a enregistre de lecteur (le fichier garde les cles exactes de la 12.10) ; une 12.10 ignore ce bloc et le perd si
    # elle enregistre : la copie de secours <fichier>.lecteurs le garde (Save-DriveRescue, apres l ecriture reussie)
    $drCfg = Export-DriveRegistry
    $cfg = [ordered]@{
        _comment = (T 'Configuration GreaseweazleGUI - régénérée automatiquement. Supprimable sans risque.')
        _saved   = (Get-Date -Format 'yyyy-MM-dd HH:mm:ss')
        window   = @{
            width  = $(if ($form.WindowState -eq 'Normal') { $form.Width }  else { $form.RestoreBounds.Width })
            height = $(if ($form.WindowState -eq 'Normal') { $form.Height } else { $form.RestoreBounds.Height })
            split = $split.SplitterDistance; maximized = ($form.WindowState -eq 'Maximized')
            logVisible = -not $split.Panel2Collapsed
        }
        global   = @{ device = $txtDev.Text; time = [bool]$chkTime.Checked; detectNone = [bool]$script:DetectNone }
        library  = @{ root = $txtLibRoot.Text; imagesOnly = [bool]$chkLibImgOnly.Checked }
        write    = @{
            file = $txtWFile.Text; format = $cmbWFmt.Text
            preErase = [bool]$chkWPreErase.Checked; eraseEmpty = [bool]$chkWEraseEmpty.Checked
            eraseMode = 'hfreq'                # 12.8.2 : marqueur de migration de la case (Update-LegacyEraseMode)
            noVerify = [bool]$chkWNoVerify.Checked; reverse = [bool]$chkWReverse.Checked
            hardSectors = [bool]$chkWHard.Checked; genTg43 = [bool]$chkWTG43.Checked
            retries = [int]$numWRetries.Value
            precompOn = [bool]$chkWPrecomp.Checked; precomp = $txtWPrecomp.Text; precomp1 = $txtWPrecomp1.Text
            postCheck = [bool]$chkWPostCheck.Checked; repairMax = [int]$numWRepair.Value
            precompStd = $(if ($oc -and $oc.Std -and -not $script:PrecompCurves['std']) { $oc.Std } else { $script:PrecompStd })
            precompLong = $(if ($oc -and $oc.Long -and -not $script:PrecompCurves['long']) { $oc.Long } else { $script:PrecompLong })
            precompMaxNs = [int]$script:CalHardNsUser   # borne des valeurs calibrees (300 a 470 ns, 400 par defaut ; 12.7 : celle de la double densite, la haute densite en prend la moitie)
            calibVersion = $script:Version     # version de l application qui a enregistre (information)
            calibCalc = $script:CalibCalc      # calcul de calibration courant ; chaque courbe porte le sien (calc)
            calibAlgo = $script:CalibAlgo
            precompCurves = $curvesCfg
            driveCurves = $dcCfg               # 12.10 : courbes de tous les lecteurs (« lecteur|cle ») ; une 12.9 ignore ce bloc
            levelAlgo = $script:LevelFormat; levelShifts = $lvCfg   # 12.8 (G2) : format 'lvl1', relu par une 12.7
            levelBrand = [string]$script:LevelBrand; levelBrands = $brCfg
            contentCalc = $script:ContentCalc; driveFactors = $cmCfg   # 12.8.1 (marqueur de migration : Update-LegacyLevelMode)
            targetDrive = $tdCfg               # 12.10 : lecteur cible des ecritures, par lecteur source (Export-TargetDrives)
            tracks = $txtWTracks.Text; densel = $cmbWDensel.Text
            fakeIndex = $txtWFakeIdx.Text; diskdefs = $txtWDiskdefs.Text
        }
        read     = @{
            file = $txtRFile.Text; format = $cmbRFmt.Text
            revs = [int]$numRevs.Value; retries = [int]$numRRetries.Value
            tracks = $txtRTracks.Text; raw = [bool]$chkRRaw.Checked; reverse = [bool]$chkRRev.Checked
            densel = $cmbRDensel.Text; diskdefs = $txtRDiskdefs.Text
        }
        convert  = @{ input = $txtCvIn.Text; output = $txtCvOut.Text; format = $cmbCvFmt.Text; tracks = $txtCvTracks.Text }
        # 12.8 (D13) : compare.format (12.7) n est plus ecrit ; le format est compare.formatChoice (Export-Settings)
        compare  = @{ reference = $txtCmpRef.Text; retries = [int]$numCmpRetries.Value }
        align    = @{ head = $cmbAlHead.Text; cyls = $txtAlCyls.Text; revs = [int]$numAlRevs.Value; loop = [bool]$chkAlLoop.Checked; pause = [int]$numAlPause.Value
                      guide = [bool]$chkAlGuide.Checked
                      reference = $(if ($script:AlignRef) { $r = @{}; foreach ($k in $script:AlignRef.Keys) { $r[$k] = [double]$script:AlignRef[$k].Score }; $r } else { $null })
                      referenceLabel = $script:AlignRefLabel }
        tools    = @{
            seek = [int]$numSeek.Value; eraseTracks = $txtEraseTracks.Text
            cleanWet = [bool]$script:CleanPrefs.Wet; cleanCyls = [int]$script:CleanPrefs.Cyls; cleanPreset = [int]$script:CleanPrefs.Preset
            pin = [int]$numPin.Value; pinLevel = $cmbPinLvl.Text
        }
        delays   = $delays
        free     = @{ command = $txtC.Text; helpAction = $cmbHelpAct.Text }
        ui       = @{ expert = [bool]$chkExpert.Checked; homeCalFormat = [string]$script:HomeCalFmt }   # type de la carte Calibration
        # 12.8 (D10, D13) : restore.source, restore.target et restore.format (12.7) ne sont plus ecrits : ils disparaissent
        # au premier enregistrement ; le format est restore.formatChoice, reglage de la table (Export-Settings)
        restore  = @{ folder = $txtRsDir.Text }
    }
    # 12.8 (point 7) : reglages de la table (global.drive ; write.calMode, slowWrite, slowWarmup, calibWarmup,
    # calWarmupMinutes, levelBeforeWrite, levelBeforeWriteMode, contentKMid et contentKLow (12.8.1), precompProfileCode et precompProfile, precompThresholdNs ; ui.homeCalHeads,
    # homeCalCyls et curveTrend (12.9, lot 1, A1-tendance) ; align.presetCode et preset ; quality ; tools.passes et linger ; restore.formatChoice ;
    # compare.formatChoice ; library.dat, lot 4b), puis, pendant
    # une operation surchargee (D4 : ecriture depuis la Bibliotheque ; lot 2 : restauration), reglages de l onglet
    # Ecriture d avant l operation
    if ($drCfg) { $cfg['drives'] = $drCfg }    # 12.11 : lecteurs enregistres
    Export-Settings $cfg
    if ($script:OpOverride) { Set-OpOverrideConfig $cfg }
    try {
        $cfg | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath $script:ConfigFile -Encoding UTF8
        if ($drCfg) { [void](Save-DriveRescue $drCfg) }   # 12.11 : copie de secours du registre, si son contenu a change
        return $true
    } catch {
        Append-Log ((T "ERREUR sauvegarde configuration : {0}") -f "$($_.Exception.Message)")
        return $false
    }
}

function Get-Cfg($obj, [string]$name, $default) {
    if ($null -ne $obj -and ($obj.PSObject.Properties.Name -contains $name) -and $null -ne $obj.$name) { return $obj.$name }
    return $default
}

function Set-Num($ctrl, $value) {
    try {
        $v = [decimal]$value
        if ($v -lt $ctrl.Minimum) { $v = $ctrl.Minimum }
        if ($v -gt $ctrl.Maximum) { $v = $ctrl.Maximum }
        $ctrl.Value = $v
    } catch { }
}

function Set-Combo($ctrl, $value) {
    if ([string]::IsNullOrEmpty($value)) { return }
    if ($ctrl.Items.Contains($value)) { $ctrl.SelectedItem = $value }
    elseif ($ctrl.DropDownStyle -ne 'DropDownList') { $ctrl.Text = $value }
}

function Load-Config {
    if (-not (Test-Path -LiteralPath $script:ConfigFile)) { return $false }
    try {
        $cfg = Get-Content -LiteralPath $script:ConfigFile -Raw -Encoding UTF8 | ConvertFrom-Json
    } catch {
        Append-Log ((T "Configuration illisible, valeurs par défaut conservées : {0}") -f "$($_.Exception.Message)")
        return $false
    }

    $win = Get-Cfg $cfg 'window' $null
    if ($win) {
        $w = [int](Get-Cfg $win 'width' $form.Width); $h = [int](Get-Cfg $win 'height' $form.Height)
        # Largeur enregistree avec le minimum de 800 px des versions anterieures a la 12.6 : portee au minimum actuel, la
        # hauteur enregistree est conservee
        if ($w -ge 800 -and $w -lt $form.MinimumSize.Width) { $w = $form.MinimumSize.Width }
        if ($w -ge $form.MinimumSize.Width -and $h -ge $form.MinimumSize.Height) { $form.Size = New-Object System.Drawing.Size($w, $h) }
        $script:PendingSplit = [int](Get-Cfg $win 'split' 0)
        if ([bool](Get-Cfg $win 'maximized' $false)) { $form.WindowState = 'Maximized' }
        $script:PendingLogVisible = [bool](Get-Cfg $win 'logVisible' $true)
    }

    $g = Get-Cfg $cfg 'global' $null
    $txtDev.Text = [string](Get-Cfg $g 'device' '')
    $chkTime.Checked = [bool](Get-Cfg $g 'time' $false)
    $script:DetectNone = [bool](Get-Cfg $g 'detectNone' $false)

    $l = Get-Cfg $cfg 'library' $null
    $txtLibRoot.Text = [string](Get-Cfg $l 'root' '')
    $chkLibImgOnly.Checked = [bool](Get-Cfg $l 'imagesOnly' $false)

    $w = Get-Cfg $cfg 'write' $null
    $txtWFile.Text = [string](Get-Cfg $w 'file' '')
    Set-Combo $cmbWFmt (Get-Cfg $w 'format' '(auto)')
    $chkWPreErase.Checked   = [bool](Get-Cfg $w 'preErase' $true)
    Update-LegacyEraseMode $cfg                # 12.8.2 : case decochee d une version anterieure recochee une fois
    $chkWEraseEmpty.Checked = [bool](Get-Cfg $w 'eraseEmpty' $true)
    $chkWNoVerify.Checked   = [bool](Get-Cfg $w 'noVerify' $false)
    $chkWReverse.Checked    = [bool](Get-Cfg $w 'reverse' $false)
    $chkWHard.Checked       = [bool](Get-Cfg $w 'hardSectors' $false)
    $chkWTG43.Checked       = [bool](Get-Cfg $w 'genTg43' $false)
    Set-Num $numWRetries (Get-Cfg $w 'retries' 10)
    $chkWPrecomp.Checked    = [bool](Get-Cfg $w 'precompOn' $true)
    # Calibrations : courbe reprise si elle a ete faite avec le calcul de calibration actuel ($script:CalibCalc), quelle que
    # soit la version de l application qui l a faite, ou si l utilisateur l a conservee pour ce calcul (KeptFor). Courbe
    # d un autre calcul : mise de cote ($script:OldCalib) avec son profil de famille et ses niveaux ; au demarrage,
    # l utilisateur choisit de la conserver ou de recalibrer (Resolve-OldCalibrations) ; d ici la, elle n est pas utilisee.
    $calVer = [string](Get-Cfg $w 'calibVersion' '')
    $pcv = Get-Cfg $w 'precompCurves' $null
    $cfgStd = [string](Get-Cfg $w 'precompStd' $script:PrecompStdDefault)
    $cfgLong = [string](Get-Cfg $w 'precompLong' $script:PrecompLongDefault)
    # Premiere 12.3 publiee : elle a abandonne les courbes 12.2 et reecrit la configuration sans elles (sans calibCalc),
    # apres en avoir fait la copie .calib-v12.2.bak : ces courbes y sont relues pour etre proposees au choix
    $fromBak = $null
    $hasCurve = ($pcv -and @($script:CurveKeys | Where-Object { Get-Cfg $pcv $_ $null }).Count -gt 0)
    $bak122 = $script:ConfigFile + '.calib-v12.2.bak'
    if (-not $hasCurve -and $calVer -eq '12.3' -and $null -eq (Get-Cfg $w 'calibCalc' $null) -and (Test-Path -LiteralPath $bak122)) {
        try {
            $bw = Get-Cfg (Get-Content -LiteralPath $bak122 -Raw -Encoding UTF8 | ConvertFrom-Json) 'write' $null
            $bpcv = Get-Cfg $bw 'precompCurves' $null
            if ($bpcv -and @($script:CurveKeys | Where-Object { Get-Cfg $bpcv $_ $null }).Count -gt 0) {
                $pcv = $bpcv; $fromBak = $bak122
                $cfgStd = [string](Get-Cfg $bw 'precompStd' $script:PrecompStdDefault); $cfgLong = [string](Get-Cfg $bw 'precompLong' $script:PrecompLongDefault)
            }
        } catch { }
    }
    # 12.10 : courbes par lecteur (Import-DriveCurves : bloc driveCurves, sinon courbes 12.9 rangees sous leur lecteur, une
    # courbe sans lecteur sous le lecteur de la configuration, lu ici avant Import-Settings) ; vue du lecteur de la
    # configuration (Sync-PrecompCurves, qui pose aussi les profils de famille d apres les courbes communes) ; le changement
    # de lecteur par Import-Settings, plus bas, la reconstruit a l identique (gestionnaire du bandeau, 520)
    $ldDrive = [string](ConvertTo-SettingValue 'drive' (Get-Cfg (Get-Cfg $cfg 'global' $null) 'drive' $null))
    $imp = Import-DriveCurves $pcv $(if ($fromBak) { $null } else { Get-Cfg $w 'driveCurves' $null }) $ldDrive
    $old = $imp.Old
    # 12.11 : lecteurs enregistres (112) : bloc drives, sinon copie de secours du registre ; rien pour une configuration
    # qui n en a jamais eu. Les courbes sont deja rangees : une courbe sans lecteur d une configuration 12.9 reste sous la
    # connexion relue, jamais sous un nom
    Import-DriveRegistry $cfg $old
    # 12.11 (lot LN-b) : lecteur de la configuration : le dernier lecteur enregistre choisi sur la connexion relue s il y
    # est toujours, sinon le lecteur non enregistre (vue, profils de famille et courbes mises de cote de ce lecteur)
    if ($script:DriveReg.Count -gt 0) { $ldDrive = Get-DriveForConn $ldDrive }
    Sync-PrecompCurves $ldDrive
    if ($imp.Migrated) { Append-Log ((T "Configuration d'une version antérieure : {0} courbe(s) de calibration rangée(s) par lecteur ({1}).") -f "$($imp.N + $old.Count)", ((@($imp.Drives)) -join ', ')) }
    # Profil de famille : celui de la courbe commune reprise du lecteur (Sync-PrecompCurves) ; mis de cote avec sa courbe ;
    # profil calibre sans courbe d aucun lecteur (anterieur a 12.1) : abandonne
    $oldStd = $null; $oldLong = $null; $lostProf = $false
    # Courbe commune de la famille sous un lecteur quelconque, reprise (magasin) ou mise de cote ($old) : le profil de la
    # configuration est le sien (une 12.9 enregistrait le profil de sa seule courbe, quel que soit le lecteur du bandeau au
    # dernier enregistrement) ; cle croisee « source>cible » non comptee, sa courbe n entre pas dans la vue
    $anyStd = (@(@(Get-DriveCurveKeys) + @($old.Keys) | Where-Object { (Split-DriveCurveKey $_).Key -eq 'std' -and (Split-DriveCurveKey $_).Drive -notlike '*>*' }).Count -gt 0)
    $anyLong = (@(@(Get-DriveCurveKeys) + @($old.Keys) | Where-Object { (Split-DriveCurveKey $_).Key -eq 'long' -and (Split-DriveCurveKey $_).Drive -notlike '*>*' }).Count -gt 0)
    if (-not $script:PrecompCurves['std']) { if ($old.Contains((Get-DriveCurveKey $ldDrive 'std'))) { $oldStd = $cfgStd } elseif ($cfgStd -ne $script:PrecompStdDefault -and -not $anyStd) { $lostProf = $true } }
    if (-not $script:PrecompCurves['long']) { if ($old.Contains((Get-DriveCurveKey $ldDrive 'long'))) { $oldLong = $cfgLong } elseif ($cfgLong -ne $script:PrecompLongDefault -and -not $anyLong) { $lostProf = $true } }
    # Niveaux de la calibration rapide : gardes avec leur reference (meme courbe, meme lecteur, meme algorithme de niveau) ;
    # ceux d une reference mise de cote le sont avec elle
    # 12.8 (lot 1c, § 12.1) : format 'lvl1' (12.7 et 12.8) ou 'lvl2' ; enregistrement 'lvl1' (relu avec s = b = 0) ou
    # 'lvl2' (forme adaptee)
    $script:LevelShifts = @{}; $oldLv = @{}
    if (@('lvl1', 'lvl2') -contains [string](Get-Cfg $w 'levelAlgo' '')) {
        foreach ($o in @(Get-Cfg $w 'levelShifts' @())) {
            $lr = ConvertFrom-LevelConfig $o
            if (-not $lr -or @('lvl1', 'lvl2') -notcontains [string]$lr.LevelAlgo) { continue }
            # 12.10 : reference dans le magasin du lecteur du niveau (une courbe d un autre lecteur ne reprend pas ses niveaux)
            $rc = Get-DriveCurve ([string]$lr.Drive) ([string]$lr.RefKey); $tgt = $script:LevelShifts
            $osk = Get-DriveCurveKey ([string]$lr.Drive) ([string]$lr.RefKey)
            if (-not $rc -and $old.Contains($osk)) { $rc = $old[$osk]; $tgt = $oldLv }
            if (-not $rc -or [string]$rc.Date -ne [string]$lr.RefDate -or [string]$rc.Drive -ne [string]$lr.Drive) { continue }
            $tgt["$($lr.RefKey)|$($lr.Tag)"] = $lr
        }
    }
    # 12.8 (lot 1c, § 10.2) : memoire par marque ; entrees gardees quelle que soit leur reference (une entree d une autre
    # reference n est plus un point de depart, Test-LevelBrandValid) ; entree illisible : ignoree, une ligne de journal
    $script:LevelBrand = [string](Get-Cfg $w 'levelBrand' '')
    $script:LevelBrands = @(); $brBad = 0
    foreach ($o in @(Get-Cfg $w 'levelBrands' @())) { $en = ConvertFrom-LevelBrandConfig $o; if ($en) { $script:LevelBrands += ,$en } else { $brBad++ } }
    if ($brBad -gt 0) { Append-Log ((T 'Mémoire par marque de disquette : {0} entrée(s) illisible(s) ignorée(s).') -f "$brBad") }
    # 12.8.1 (spec-1281 § C.5) : facteurs mesures des lecteurs (enregistrement illisible : ignore, une ligne de journal).
    # 12.10 : lecteur cible des ecritures par lecteur source (Import-TargetDrives, entree illisible ignoree, une ligne) ;
    # le bloc targetCorrection de la correction « lecteur cible » Dk n est plus lu.
    # Enregistrements d un autre calcul gardes : Get-DriveK ne les retient pas (decision du 25/10/2026 : facteurs gardes
    # apres une recalibration du lecteur, date de la courbe non exigee)
    $script:ContentMeasures = @(); $cmBad = 0
    foreach ($o in @(Get-Cfg $w 'driveFactors' @())) { $rec = ConvertFrom-ContentConfig $o; if ($rec) { $script:ContentMeasures += ,$rec } else { $cmBad++ } }
    if ($cmBad -gt 0) { Append-Log ((T 'Configuration : {0} facteur(s) mesuré(s) illisible(s), ignoré(s).') -f "$cmBad") }
    # 12.11 : une identite sans fiche n est jamais devinee : fiche sans connexion pour tout nom admis trouve dans les
    # donnees lues (Repair-DriveRegistry, 112 ; bloc targetDrive lu brut, avant qu Import-TargetDrives ecarte les lecteurs
    # inconnus) ; aucune pour une configuration dont toutes les donnees citent une connexion (12.10)
    [void](Repair-DriveRegistry $old (Get-Cfg $w 'targetDrive' $null))
    # 12.11 (lot LN-b) : liste du bandeau (les six connexions, puis les lecteurs enregistres qui ont une connexion) et sa
    # disposition (Update-DriveList, 112) ; registre vide et liste de six elements : rien (12.10)
    if ($script:DriveReg.Count -gt 0 -or $cmbDrive.Items.Count -gt @($script:SettingDefs['drive'].Codes).Count) { Update-DriveList }
    $tdi = Import-TargetDrives (Get-Cfg $w 'targetDrive' $null)
    if ([int]$tdi.Bad -gt 0) { Append-Log ((T 'Configuration : {0} lecteur(s) cible illisible(s) ou inconnu(s), ignoré(s).') -f "$($tdi.Bad)") }
    # 12.11 : registre relu dans la copie de secours : lecteurs cibles des lecteurs enregistres retablis depuis elle (une
    # version anterieure les retire), et ligne de journal qui dit ce qui a ete retrouve ; rien sinon
    [void](Restore-DriveRescueTargets $old)
    # Revue 12.8.2 : facteurs d un autre calcul qui ne s appliquent plus (aucune mesure du calcul actuel pour ce lecteur,
    # cette famille et cette tete, Get-StaleDriveFactors) : une ligne a chaque demarrage, jusqu a une nouvelle mesure
    $sdf = Get-StaleDriveFactors
    # 12.9 : facteurs d un autre calcul de mesure sur l image (ContentCalc avant la 12.9) : texte de la montee de calcul
    if ([int]$sdf.Content -gt 0) { Append-Log (T "Facteurs mesurés sur l'image avant la 12.9 : le calcul a changé (marque, courbure en ns, facteur au-delà de 1), ils ne sont plus appliqués. Refaites une mesure sur l'image pour chaque marque.") }
    # Synthese C (A2) : mesures du calcul actuel relues sans etat (configuration reecrite par une version anterieure, qui
    # retire les champs de la 12.9) : Get-DriveK ne les retient plus ; une ligne a chaque demarrage, jusqu a une nouvelle
    # mesure du calcul actuel pour ce lecteur, cette famille et cette tete (comme Get-StaleDriveFactors)
    $cmEt = @{}
    foreach ($cmr in @($script:ContentMeasures)) { if ($cmr -and [string]$cmr.ContentCalc -eq [string]$script:ContentCalc -and [string]$cmr.Etat) { $cmEt["$($cmr.Drive)|$($cmr.Family)|$([int]$cmr.Head)"] = $true } }
    $nNoEtat = @($script:ContentMeasures | Where-Object { $_ -and [string]$_.ContentCalc -eq [string]$script:ContentCalc -and -not [string]$_.Etat -and -not $cmEt.ContainsKey("$($_.Drive)|$($_.Family)|$([int]$_.Head)") }).Count
    if ($nNoEtat -gt 0) { Append-Log ((T "Facteurs mesurés sur l'image : {0} mesure(s) du calcul {1} relue(s) sans marque ni état (configuration réécrite par une version antérieure) : elles ne sont plus appliquées. Refaites une mesure sur l'image pour chaque marque.") -f "$nNoEtat", "$($script:ContentCalc)") }
    # 12.9 (calcul de calibration 12.9) : facteurs d un autre calcul de calibration en plus de ceux d avant la 12.9 (ligne
    # ci-dessus) : les deux lignes s ecrivent
    if ([int]$sdf.N -gt [int]$sdf.Content) { Append-Log ((T "Facteurs de précompensation mesurés sur l'image : {0} mesure(s) du lecteur {1}, faite(s) avec un autre calcul de calibration, ne sont plus appliquées. Après la recalibration du lecteur, refaites une mesure sur l'image ; d'ici là, une écriture sans mesure utilise le facteur 1.") -f "$([int]$sdf.N - [int]$sdf.Content)", ((@($sdf.Drives)) -join ', ')) }
    $script:OldCalib = $null
    $calPurged = $lostProf
    if ($old.Count -gt 0) {
        $calPurged = $true
        $tags = @(@($old.Values) | ForEach-Object { Get-CurveCalc $_ } | Sort-Object -Unique)
        $tag = if ($tags.Count -eq 1 -and $tags[0]) { "v$($tags[0])" } elseif ($calVer) { "v$calVer" } else { 'ancienne' }
        # Copie de la configuration avant tout enregistrement, quel que soit le choix : une fois par passage d un calcul au
        # calcul actuel ; courbes relues dans la copie de la 12.3 publiee : cette copie
        if ($fromBak) { $bak = $fromBak; Append-Log ((T "Courbes de la version 12.2 relues dans la copie faite par la première version 12.3 : {0}") -f "$fromBak") }
        else {
            $bak = $script:ConfigFile + '.calib-' + $tag + '-avant-v' + $script:CalibCalc + '.bak'
            if (-not (Test-Path -LiteralPath $bak)) { try { Copy-Item -LiteralPath $script:ConfigFile -Destination $bak -ErrorAction Stop; Append-Log ((T "Configuration sauvegardée avant le choix sur les anciennes calibrations : {0}") -f "$bak") } catch { $bak = $null } }
        }
        $script:OldCalib = @{ Curves = $old; Std = $oldStd; Long = $oldLong; Levels = $oldLv; Bak = $bak; P0 = $null; P1 = $null }
        Append-Log ((T "Calibrations faites avec un autre calcul de calibration que le calcul actuel (v{0}) : {1}. Elles sont mises de côté jusqu'à votre choix.") -f "$($script:CalibCalc)", ((@($old.Keys | ForEach-Object { (T "{0}, calcul {1}") -f (Get-DriveCurveLabel $_), (Get-CurveCalcText $old[$_] -Plain) })) -join ' ; '))   # 12.10 : lecteur nomme
    }
    if ($lostProf) { Append-Log (T 'Profil de famille calibré sans courbe (version antérieure à 12.1) : profil d''origine rétabli.') }
    # Borne des valeurs calibrees : reglage de la configuration, ramene a 300..470 ns ; valeur illisible : defaut, signale
    $hraw = Get-Cfg $w 'precompMaxNs' $null
    $hn = $script:CalHardNsDefault; $hd = 0.0
    if ($null -ne $hraw) {
        if ($hraw -isnot [bool] -and $hraw -isnot [array] -and [double]::TryParse(([string]$hraw).Trim(), [System.Globalization.NumberStyles]::Float, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$hd) -and -not [double]::IsNaN($hd) -and -not [double]::IsInfinity($hd)) {
            $hn = [int][math]::Round([math]::Max(-1e9, [math]::Min(1e9, $hd)))
        } else { Append-Log ((T "Borne de précompensation (precompMaxNs) illisible ({0}) : {1} ns par défaut.") -f "$hraw", "$($script:CalHardNsDefault)") }
    }
    $script:CalHardNs = [int][math]::Max($script:CalHardMinNs, [math]::Min($script:CalHardMaxNs, $hn))
    if ($script:CalHardNs -ne $hn) { Append-Log ((T "Borne de précompensation (precompMaxNs) de {0} ns ramenée à {1} ns : elle va de {2} à {3} ns. Au-delà de 470 ns, la précompensation déplacerait une transition d'un quart de cellule en long track (1,89 us).") -f "$hraw", "$($script:CalHardNs)", "$($script:CalHardMinNs)", "$($script:CalHardMaxNs)") }
    elseif ($script:CalHardNs -ne $script:CalHardNsDefault) { Append-Log ((T "Borne de précompensation réglée dans la configuration (precompMaxNs) : {0} ns, au lieu de {1} ns par défaut.") -f "$($script:CalHardNs)", "$($script:CalHardNsDefault)") }
    $script:CalHardNsUser = $script:CalHardNs; Set-CalibScale ''   # 12.7 : borne configuree, bareme double densite
    # 12.8 (point 7) : reglages de la table, sauf ceux de l ecriture lente lus plus bas, a la place qu ils avaient en 12.7
    # (apres les champs --precomp) : lecteur, mode de calibration, duree du prechauffage (lignes de journal d une valeur
    # illisible ou ramenee a 0..30 min), profil precomp (code, sinon ancien texte francais ou anglais), seuil de famille,
    # carte « Calibrer le lecteur », mesure de l onglet Qualite, seuils de jitter, nettoyage de l onglet Outils
    $lateKeys = @('slowWrite', 'warmSlowWrite', 'warmFullCalib', 'levelBeforeWrite', 'levelBeforeWriteMode')
    # 12.11 (lot LN-b) : avec des lecteurs enregistres, aucune ligne « Lecteur choisi » au chargement (« avant : A » ne
    # serait que la valeur de Set-Defaults), puis bandeau sur le lecteur retenu pour la connexion du reglage : le reglage
    # seul ne change pas de lecteur sur une meme connexion (Sync-DriveCombo)
    if ($script:DriveReg.Count -gt 0) { $script:DriveCur = '' }
    Import-Settings $cfg -Except $lateKeys
    if ($script:DriveReg.Count -gt 0) { Set-Combo $cmbDrive (Get-DriveForConn ([string](Get-Setting 'drive'))); $script:DriveCur = [string]$cmbDrive.Text }
    Update-LegacyCleanDefault $cfg             # 12.8 (D9) : ancien defaut du nettoyage de l onglet Outils
    Test-ContentLevelSettings $cfg             # 12.8.1 : niveaux de la mesure sur l image, controles ensemble
    $chkWPostCheck.Checked = [bool](Get-Cfg $w 'postCheck' $true)
    $rm = [int](Get-Cfg $w 'repairMax' 3); $numWRepair.Value = [math]::Max(0, [math]::Min(10, $rm))
    $numWRepair.Enabled = $chkWPostCheck.Checked; $lblWRepair.Enabled = $chkWPostCheck.Checked
    $txtWPrecomp.Text  = [string](Get-Cfg $w 'precomp' $script:PrecompStd)
    $txtWPrecomp1.Text = [string](Get-Cfg $w 'precomp1' $txtWPrecomp.Text)
    if ($script:OldCalib) { $script:OldCalib.P0 = $txtWPrecomp.Text; $script:OldCalib.P1 = $txtWPrecomp1.Text }   # retablis si conservees
    # Champs --precomp remplis par une ancienne calibration : profil d origine (sauf profil manuel, choisi par l utilisateur)
    if ($calPurged -and (Get-Setting 'precompProfile') -ne 'manual') { $txtWPrecomp.Text = $script:PrecompStd; $txtWPrecomp1.Text = $script:PrecompStd }
    Import-Settings $cfg -Only $lateKeys       # ecriture lente, prechauffages (D6), mesure de la disquette et son mode (S3)
    Update-LegacyLevelMode $cfg                # 12.8.1 : liste « Mesure : » d une configuration 12.8, rapide -> sur l image
    Update-SlowUi
    Update-TargetDriveUi                       # 12.10 : liste « Lecteur cible » du lecteur du bandeau
    $txtWTracks.Text   = [string](Get-Cfg $w 'tracks' '')
    Set-Combo $cmbWDensel (Get-Cfg $w 'densel' '(non)')
    $txtWFakeIdx.Text  = [string](Get-Cfg $w 'fakeIndex' '')
    $txtWDiskdefs.Text = [string](Get-Cfg $w 'diskdefs' '')

    $r = Get-Cfg $cfg 'read' $null
    $txtRFile.Text = [string](Get-Cfg $r 'file' '')
    Set-Combo $cmbRFmt (Get-Cfg $r 'format' '(auto)')
    Set-Num $numRevs     (Get-Cfg $r 'revs' 5)
    Set-Num $numRRetries (Get-Cfg $r 'retries' 10)
    $txtRTracks.Text = [string](Get-Cfg $r 'tracks' '')
    $chkRRaw.Checked = [bool](Get-Cfg $r 'raw' $false)
    $chkRRev.Checked = [bool](Get-Cfg $r 'reverse' $false)
    Set-Combo $cmbRDensel (Get-Cfg $r 'densel' '(non)')
    $txtRDiskdefs.Text = [string](Get-Cfg $r 'diskdefs' '')

    $c = Get-Cfg $cfg 'convert' $null
    $txtCvIn.Text  = [string](Get-Cfg $c 'input' '')
    $txtCvOut.Text = [string](Get-Cfg $c 'output' '')
    Set-Combo $cmbCvFmt (Get-Cfg $c 'format' '(auto)')
    $txtCvTracks.Text = [string](Get-Cfg $c 'tracks' '')

    $al = Get-Cfg $cfg 'align' $null
    $ref = Get-Cfg $al 'reference' $null
    if ($ref) {
        $script:AlignRef = @{}
        foreach ($prop in $ref.PSObject.Properties) { $script:AlignRef[[string]$prop.Name] = @{ Score = [double]$prop.Value } }
        $script:AlignRefLabel = [string](Get-Cfg $al 'referenceLabel' '')
        $lblAlRef.Text = ((T "Référence : {0} ({1} piste(s))") -f "$($script:AlignRefLabel)", "$($script:AlignRef.Count)")
    }
    Set-Combo $cmbAlHead (Get-Cfg $al 'head' '0+1')
    $txtAlCyls.Text = [string](Get-Cfg $al 'cyls' '0,10,20,30,40,50,60,70')
    $chkAlGuide.Checked = [bool](Get-Cfg $al 'guide' $false)
    Set-Num $numAlRevs (Get-Cfg $al 'revs' 3)
    $chkAlLoop.Checked = [bool](Get-Cfg $al 'loop' $false)
    Set-Num $numAlPause (Get-Cfg $al 'pause' 2)

    $cm = Get-Cfg $cfg 'compare' $null
    $txtCmpRef.Text = [string](Get-Cfg $cm 'reference' '')
    # 12.8 (D13) : compare.format (12.7) non relu, son defaut amiga.amigados n etant pas un choix : compare.formatChoice,
    # lu par Import-Settings, auto par defaut
    Set-Num $numCmpRetries (Get-Cfg $cm 'retries' 10)

    $t = Get-Cfg $cfg 'tools' $null
    Set-Num $numSeek   (Get-Cfg $t 'seek' 0)
    $txtEraseTracks.Text = [string](Get-Cfg $t 'eraseTracks' '')
    # Fenetre de nettoyage : humide sauf false explicite, 40 pistes ou 80, prereglage de duree 0..2
    $cc = 0; [void][int]::TryParse([string](Get-Cfg $t 'cleanCyls' 80), [ref]$cc)
    $cp = 0; [void][int]::TryParse([string](Get-Cfg $t 'cleanPreset' 0), [ref]$cp)
    $script:CleanPrefs = @{ Wet = ([string](Get-Cfg $t 'cleanWet' $true) -ne 'False'); Cyls = $(if ($cc -eq 40) { 40 } else { 80 }); Preset = [math]::Max(0, [math]::Min(2, $cp)) }
    Set-Num $numPin    (Get-Cfg $t 'pin' 2)
    Set-Combo $cmbPinLvl (Get-Cfg $t 'pinLevel' 'H')

    $dl = Get-Cfg $cfg 'delays' $null
    foreach ($k in $script:DelayCtrls.Keys) {
        $ctl = $script:DelayCtrls[$k]
        $e = Get-Cfg $dl $k $null
        if ($null -ne $e) {
            Set-Num $ctl.Num (Get-Cfg $e 'val' $ctl.Def)
            $ctl.Chk.Checked = [bool](Get-Cfg $e 'on' $false)
        }
    }

    $f = Get-Cfg $cfg 'free' $null
    $txtC.Text = [string](Get-Cfg $f 'command' $txtC.Text)
    Set-Combo $cmbHelpAct (Get-Cfg $f 'helpAction' 'write')

    # Configuration d une version precedente (sans section ui) : tous les onglets, comme avant
    $ui = Get-Cfg $cfg 'ui' $null
    $chkExpert.Checked = [bool](Get-Cfg $ui 'expert' ($null -eq $ui))
    # Type de disquette de la carte Calibration de l Accueil : nom de la table (format gw 1.23 ou type d image app.*)
    $hcf = [string](Get-Cfg $ui 'homeCalFormat' '')
    if ($hcf -and ($script:HomeCalApp -contains $hcf -or $script:GwFormats.Contains($hcf))) { $script:HomeCalFmt = $hcf }
    # 12.8 (D10, D13) : restore.source et restore.target ignores (un seul lecteur) ; restore.format (12.7) non relu, son
    # defaut amiga.amigados n etant pas un choix : restore.formatChoice, lu par Import-Settings, auto par defaut
    $rs = Get-Cfg $cfg 'restore' $null
    $txtRsDir.Text = [string](Get-Cfg $rs 'folder' '')

    return $true
}
# ============================== FONCTIONS : BIBLIOTHEQUE =======================

function Start-LibWrite([string]$mode) {
    # Ecriture rapide ou lente de l image selectionnee : parametres de l onglet Ecriture appliques, calibration
    # automatique si elle manque pour la famille de l image, puis ecriture (onglet Ecriture affiche pour le suivi).
    # 12.10 : ecriture pour un lecteur cible (liste « Lecteur cible » de l onglet Ecriture) : courbe croisee telle quelle,
    # refusee sans courbe croisee (Test-TargetWriteAllowed, Start-ImageWrite : fenetre et journal), comme le bouton ECRIRE
    if ($script:GwProc -and -not $script:GwProc.HasExited) { return }
    # 12.10 (lot 1, R1-corrections-revue, constat e) : surcharge encore active (operation de la Bibliotheque, restauration) :
    # Enter-OpOverride la reprendrait sans remettre son etat (Started, Written, image gardee) et la sequence de la seconde
    # operation couperait la premiere. Operation de la Bibliotheque finie, surcharge pas encore levee par le minuteur
    # (Update-OpOverride) : levee ici ; sinon refus, avant toute extraction d archive
    if ($script:OpOverride) {
        if ($script:OpOverride.Kind -eq 'library' -and $script:OpOverride.Started -and (Test-OpIdle)) { Exit-OpOverride }
        else { Show-LibNotice (T 'Une opération est déjà en cours : attendez sa fin ou cliquez sur « Arrêter ».'); return }
    }
    $sel = Resolve-LibSelection
    if (-not $sel) { return }
    if (-not $sel.IsImage) {
        # 12.8 (lot 4a) : message dans le journal et le panneau de details, plus de boite de message
        Show-LibNotice (T 'Ce fichier n''est pas un format image reconnu par gw.'); return
    }
    Append-Log ((T "Image sélectionnée : {0}") -f "$($sel.Path)")
    # 12.8 (D4) : prereglage en surcharge temporaire de l onglet Ecriture, retabli a la fin de l operation
    Enter-OpOverride 'library'
    Set-WritePreset $mode $sel.Path $sel.Source
    Save-LibKeepImg                                 # 12.10 (lot 1, E9-image) : image gardee si elle est ecrite (R1, constat d)
    Update-PrecompForImage $sel.Path
    Show-Tab $tabW
    Start-PresetWrite $mode
    # Rien de lance (refus, calibration annulee, fichier introuvable) : fin tout de suite. Image secteur sans format :
    # Start-PresetWrite demande de le choisir dans l onglet Ecriture, le prereglage y reste (comme en 12.7)
    if (Test-OpIdle) {
        $needFmt = (Test-NeedsFormat $txtWFile.Text) -and -not ($cmbWFmt.Text -and $cmbWFmt.Text -ne '(auto)')
        Exit-OpOverride -Keep:$needFmt
    } elseif ($script:OpOverride) { $script:OpOverride.Started = $true }
}

function Set-LibWriteEnabled([bool]$on) { $btnLibFast.Enabled = $on; $btnLibSlow.Enabled = $on }

function Show-LibNotice([string]$text) {
    # 12.8 (lot 4a) : message de la Bibliotheque dans le journal et en tete du panneau de details (aucune boite de message)
    Append-Log ((T 'Bibliothèque : {0}') -f $text)
    $txtLibInfo.Text = $text + "`r`n`r`n" + $script:LibInfoBase
}

# ============================== BIBLIOTHEQUE : LOGIQUE =========================
function Format-Size([long]$bytes) {
    if ($bytes -ge 1048576) { return ((T '{0:N1} Mo') -f ($bytes / 1MB)) }
    if ($bytes -ge 1024)    { return ((T '{0:N0} Ko') -f ($bytes / 1KB)) }
    return ((T "{0} o") -f "$bytes")
}

function Get-FileKind([string]$name) {
    $e = [System.IO.Path]::GetExtension($name).ToLower()
    if ($e -eq '.zip')               { return 'zip' }
    if ($script:ImgExt -contains $e) { return 'image' }
    if ($script:DocExt -contains $e) { return 'doc' }
    return 'other'
}

function Get-KindPrefix([string]$kind) { return '' }   # remplace par les icones de l'arborescence

function Get-ZipEntries([string]$zipPath) {
    # Entrees d une archive (dossiers exclus) ; Index : rang dans l archive, celui du repertoire central (12.8, lot 4b)
    $out = @()
    try {
        $zip = [System.IO.Compression.ZipFile]::OpenRead($zipPath)
        try {
            $ix = 0
            foreach ($e in $zip.Entries) {
                $ei = $ix; $ix++
                if ($e.FullName.EndsWith('/')) { continue }
                $out += [pscustomobject]@{ FullName = $e.FullName; Length = $e.Length; Kind = (Get-FileKind $e.Name); Index = $ei }
            }
        } finally { $zip.Dispose() }
    } catch {
        Append-Log ((T "ZIP illisible ({0}) : {1}") -f "$([System.IO.Path]::GetFileName($zipPath))", "$($_.Exception.Message)")
    }
    return $out
}

function New-LibNode([string]$text, $tagHash) {
    $n = New-Object System.Windows.Forms.TreeNode
    $n.Text = $text
    $n.Tag  = $tagHash
    $k = $tagHash.Kind
    if ($k -eq 'zipentry') { $k = $tagHash.FileKind }
    if (@('dir','zip','image','doc','other') -notcontains $k) { $k = 'blank' }
    $n.ImageKey = $k; $n.SelectedImageKey = $k
    return $n
}

function New-Placeholder { return (New-LibNode (T '(chargement...)') @{ Kind='placeholder' }) }

function Expand-LibNode($node) {
    if (-not $node -or -not $node.Tag) { return }
    if ($node.Nodes.Count -ne 1 -or $node.Nodes[0].Tag.Kind -ne 'placeholder') { return }

    $form.Cursor = [System.Windows.Forms.Cursors]::WaitCursor
    $treeLib.BeginUpdate()
    try {
        $node.Nodes.Clear()
        if ($node.Tag.Kind -eq 'dir') {
            Populate-LibDir $node
        } elseif ($node.Tag.Kind -eq 'zip') {
            $list = New-Object System.Collections.Generic.List[System.Windows.Forms.TreeNode]
            foreach ($e in (Get-ZipEntries $node.Tag.Path)) {
                if ($chkLibImgOnly.Checked -and $e.Kind -ne 'image') { continue }
                $list.Add((New-LibNode "$(Get-KindPrefix $e.Kind)$($e.FullName)  ($(Format-Size $e.Length))" `
                    @{ Kind='zipentry'; ZipPath=$node.Tag.Path; Entry=$e.FullName; Size=$e.Length; FileKind=$e.Kind; Idx=$e.Index }))
            }
            if ($list.Count -eq 0) { $list.Add((New-LibNode (T '(aucune image)') @{ Kind='none' })) }
            $node.Nodes.AddRange($list.ToArray())
        }
    } finally {
        $treeLib.EndUpdate()
        $form.Cursor = [System.Windows.Forms.Cursors]::Default
    }
}

function Populate-LibDir($node) {
    $path = $node.Tag.Path
    $list = New-Object System.Collections.Generic.List[System.Windows.Forms.TreeNode]
    try {
        foreach ($d in (Get-ChildItem -LiteralPath $path -Directory -ErrorAction Stop | Sort-Object Name)) {
            $sub = New-LibNode $d.Name @{ Kind='dir'; Path=$d.FullName }
            [void]$sub.Nodes.Add((New-Placeholder))
            $list.Add($sub)
        }
        foreach ($f in (Get-ChildItem -LiteralPath $path -File -ErrorAction Stop | Sort-Object Name)) {
            $kind = Get-FileKind $f.Name
            if ($chkLibImgOnly.Checked -and $kind -ne 'image' -and $kind -ne 'zip') { continue }
            $n = New-LibNode "$(Get-KindPrefix $kind)$($f.Name)  ($(Format-Size $f.Length))" @{ Kind=$kind; Path=$f.FullName; Size=$f.Length }
            if ($kind -eq 'zip') { [void]$n.Nodes.Add((New-Placeholder)) }
            $list.Add($n)
        }
    } catch {
        Append-Log ((T "Lecture impossible de {0} : {1}") -f "$path", "$($_.Exception.Message)")
    }
    if ($list.Count -gt 0) { $node.Nodes.AddRange($list.ToArray()) }
}

# --- Recherche asynchrone : s execute dans un runspace separe, l UI ne gele pas
function Stop-LibSearch {
    if ($script:LibPS) {
        try { $script:LibPS.Stop() } catch { }
        try { $script:LibPS.Dispose() } catch { }
    }
    $script:LibPS = $null
    $script:LibAsync = $null
}

function Start-LibSearch([string]$root, [string]$filter, [bool]$imgOnly) {
    # Recherche de repli (index rapide indisponible) : sur-ensemble, chaque mot dans le chemin relatif ; la regle des mots
    # (nom du fichier, ou chemin avec « Aussi dans les dossiers ») s applique a la fin (Complete-LibSearch), comme pour l index
    Stop-LibSearch
    if (-not $script:LibRunspace -or $script:LibRunspace.RunspaceStateInfo.State -ne 'Opened') {
        $script:LibRunspace = [runspacefactory]::CreateRunspace()
        $script:LibRunspace.Open()
    }
    $script:LibSearchFilter = $filter; $script:LibSearchInDirs = [bool]$chkLibInDirs.Checked
    $ps = [powershell]::Create()
    $ps.Runspace = $script:LibRunspace
    [void]$ps.AddScript({
        param($root, $filter, $imgExt, $docExt, $imgOnly)
        $words = @($filter.Split([char[]]@(' '), [System.StringSplitOptions]::RemoveEmptyEntries))
        $rl = $root.TrimEnd('\').Length + 1
        $out = New-Object System.Collections.Generic.List[object]
        Get-ChildItem -LiteralPath $root -File -Recurse -ErrorAction SilentlyContinue |
            ForEach-Object {
                $rel = if ($_.FullName.Length -gt $rl) { $_.FullName.Substring($rl) } else { $_.Name }
                foreach ($w in $words) { if ($rel.IndexOf($w, [System.StringComparison]::OrdinalIgnoreCase) -lt 0) { return } }
                $e = [System.IO.Path]::GetExtension($_.Name).ToLower()
                $kind = if ($e -eq '.zip') { 'zip' } elseif ($imgExt -contains $e) { 'image' } elseif ($docExt -contains $e) { 'doc' } else { 'other' }
                if ($imgOnly -and $kind -ne 'image' -and $kind -ne 'zip') { return }
                $out.Add([pscustomobject]@{ Name = $_.Name; FullName = $_.FullName; Length = $_.Length; Kind = $kind })
            }
        $out.ToArray()
    }).AddArgument($root).AddArgument($filter).AddArgument($script:ImgExt).AddArgument($script:DocExt).AddArgument($imgOnly)
    $script:LibPS = $ps
    $script:LibAsync = $ps.BeginInvoke()

    $lblLibCount.Text = (T 'recherche en cours...')
    $btnLibFilter.Enabled = $false
    $btnLibRefresh.Enabled = $false
    $form.Cursor = [System.Windows.Forms.Cursors]::AppStarting
}

function Complete-LibSearch {
    $root = $txtLibRoot.Text
    $results = @()
    try { $results = @($script:LibPS.EndInvoke($script:LibAsync)) } catch { Append-Log ((T "Recherche : {0}") -f "$($_.Exception.Message)") }
    Stop-LibSearch
    $btnLibFilter.Enabled = $true
    $btnLibRefresh.Enabled = $true
    $form.Cursor = [System.Windows.Forms.Cursors]::Default
    $rootT = $root.TrimEnd('\')
    $ents = [System.Collections.Generic.List[object]]::new()
    foreach ($f in $results) {
        if (-not $f) { continue }
        $rel = $f.FullName
        if ($rel.Length -gt $rootT.Length) { $rel = $rel.Substring($rootT.Length).TrimStart('\') }
        $ents.Add([pscustomobject]@{ Rel = $rel; Size = [long]$f.Length; Kind = $f.Kind })
    }
    $sorted = @($ents | Sort-Object Rel)
    # Tableau garde tel quel (un seul element : pas de deroulement en chaine)
    [string[]]$rels = @(); if ($sorted.Count -gt 0) { $rels = [string[]]@($sorted.Rel) }
    Set-LibResults $root $sorted (Select-LibMatches $rels $script:LibSearchFilter $script:LibSearchInDirs)
}

function Get-LibIndexFile([string]$root) {
    $md5 = [System.Security.Cryptography.MD5]::Create()
    $h = [BitConverter]::ToString($md5.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($root.TrimEnd('\').ToLowerInvariant()))).Replace('-','').Substring(0,16)
    return (Join-Path $script:IndexDir "index-$h.tsv")
}

function Test-LibIndexReady([string]$root) {
    if (-not $script:FastIndexOk) { return $false }
    return ([FastIndex]::Root -eq $root.TrimEnd('\') -and [FastIndex]::Count -gt 0)
}

function Start-LibIndex([bool]$force) {
    if (-not $script:FastIndexOk) { return }
    $root = $txtLibRoot.Text
    if (-not $root -or -not (Test-Path -LiteralPath $root)) { return }
    if ([FastIndex]::Busy) { return }
    $file = Get-LibIndexFile $root
    if (-not $force -and (Test-LibIndexReady $root)) { return }
    if (-not $force -and (Test-Path -LiteralPath $file)) {
        try { if ([FastIndex]::Load($file, $root)) { Show-LibIndexStatus; return } } catch { Append-Log ((T "Index illisible, reconstruction : {0}") -f "$($_.Exception.Message)") }
    }
    # 12.8 (lot 4a) : reindexation demandee : blocs INFO et jeux relus (fichiers ajoutes, remplaces ou deplaces)
    if ($force) { $script:LibIpfCache = @{}; $script:LibSetCache = @{}; $script:LibRecCache = @{}; $script:LibDatState = @{}; $script:LibDatZip = @{} }
    [FastIndex]::StartBuild($root, $file)
    $script:LibIndexing = $true
    $btnLibReindex.Enabled = $false
    Append-Log ((T "Bibliothèque : indexation de {0} en arrière-plan...") -f "$root")
}

function Show-LibIndexStatus {
    if (-not $script:FastIndexOk -or [FastIndex]::Count -eq 0) { return }
    $tip.SetToolTip($lblLibCount, ((T "Index : {0} fichiers, construit le {1}.") -f "$([FastIndex]::Count)", "$([FastIndex]::Built.ToString('dd/MM/yyyy HH:mm'))"))
    if (-not $txtLibFilter.Text.Trim()) { $lblLibCount.Text = ((T "Index : {0} fichiers") -f "$('{0:N0}' -f [FastIndex]::Count)") }
}

function Show-LibIndexResults([string]$root, [string]$filter) {
    # 12.8 (lot 4a, A3 § 4.2 n° 8) : l index cherche chaque mot dans le chemin relatif complet, sans limite (FastIndex
    # inchange : sur-ensemble) ; la regle des mots s applique ensuite au nom du fichier, ou au chemin avec « Aussi dans les
    # dossiers » (Select-LibMatches) ; la liste n analyse et n affiche que les 2 000 premiers (Show-LibResults)
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    $res = [FastIndex]::Search($filter, [bool]$chkLibImgOnly.Checked, [int]::MaxValue)
    [string[]]$rels = @(); if ($res.Count -gt 0) { $rels = [string[]]@($res.Rel) }
    $all = Select-LibMatches $rels $filter ([bool]$chkLibInDirs.Checked)
    $script:LibIndexHits = $res.Count; $script:LibFilterMs = $sw.ElapsedMilliseconds
    Set-LibResults $root $res $all
}

function Update-Library {
    Stop-LibSearch
    Stop-LibWork
    $btnLibFilter.Enabled = $true
    $btnLibRefresh.Enabled = $true
    $form.Cursor = [System.Windows.Forms.Cursors]::Default
    $treeLib.Nodes.Clear()
    $script:LibRendering = $true
    try { $lvLib.Items.Clear(); $lvLib.Groups.Clear() } finally { $script:LibRendering = $false }
    $script:LibAll = $null; $script:LibCand = $null; $script:LibCounts = $null; $script:LibGroups = @{}; $script:LibSetCache = @{}
    Clear-LibDetails
    $lblLibCount.Text = ''

    $root = $txtLibRoot.Text
    $filter = $txtLibFilter.Text.Trim()
    # 12.8 (lot 4a) : recherche saisie -> liste groupee des resultats ; recherche vide -> arborescence (A3 § 4.1)
    Set-LibViewMode ([bool]$filter)
    if (-not $root -or -not (Test-Path -LiteralPath $root)) {
        if ($root) { $lblLibCount.Text = (T 'racine introuvable') }
        $txtLibInfo.Text = (T "Pour commencer :`r`n1. Choisissez le dossier racine de vos images (bouton ...).`r`n2. Dépliez l'arborescence ou utilisez la recherche.`r`n3. Sélectionnez une image puis « Écriture rapide » ou « Écriture lente ».")
        return
    }

    if ($filter) {
        if ($script:FastIndexOk) {
            if (Test-LibIndexReady $root) { Show-LibIndexResults $root $filter; return }
            Start-LibIndex $false
            if (Test-LibIndexReady $root) { Show-LibIndexResults $root $filter; return }
            $script:LibPendingSearch = $true
            $lblLibCount.Text = (T 'indexation en cours...')
            return
        }
        Start-LibSearch $root $filter ([bool]$chkLibImgOnly.Checked)
        return
    }
    # Navigation : l'index est charge (ou construit) en arriere-plan pour que la premiere recherche soit instantanee
    if ($script:FastIndexOk -and -not (Test-LibIndexReady $root)) { Start-LibIndex $false }

    $treeLib.BeginUpdate()
    try {
        $rootNode = New-LibNode (Split-Path -Leaf $root) @{ Kind='dir'; Path=$root }
        [void]$treeLib.Nodes.Add($rootNode)
        Populate-LibDir $rootNode
        $rootNode.Expand()
        $lblLibCount.Text = ((T "{0} élément(s)") -f "$($rootNode.Nodes.Count)")
    } finally { $treeLib.EndUpdate() }
    Show-LibIndexStatus
}

function Show-LibSelection($node) {
    # Arborescence : panneau de details de l element choisi (12.8 : meme panneau que la liste des resultats)
    if (-not $node -or -not $node.Tag -or @('placeholder', 'none') -contains $node.Tag.Kind) { Clear-LibDetails; return }
    Show-LibDetails (Get-LibNodeRecord $node.Tag)
}

function Expand-ZipEntry([string]$zipPath, [string]$entry) {
    if (-not (Test-Path -LiteralPath $script:TempDir)) { [void](New-Item -ItemType Directory -Path $script:TempDir -Force) }
    $dest = Join-Path $script:TempDir ([System.IO.Path]::GetFileName($entry))
    $zip = [System.IO.Compression.ZipFile]::OpenRead($zipPath)
    try {
        $e = $zip.Entries | Where-Object { $_.FullName -eq $entry } | Select-Object -First 1
        if (-not $e) { throw ((T "Entrée introuvable dans l'archive : {0}") -f "$entry") }
        [System.IO.Compression.ZipFileExtensions]::ExtractToFile($e, $dest, $true)
    } finally { $zip.Dispose() }
    return $dest
}

function Get-LibWriteTarget {
    # 12.8 (lot 4a) : element vise par l ecriture : ligne de la liste (recherche saisie) ou noeud de l arborescence ;
    # archive ZIP : entree image choisie dans la liste des documents et entrees du panneau
    $t = $null
    if ($script:LibListMode) { if ($lvLib.SelectedItems.Count -gt 0) { $t = $lvLib.SelectedItems[0].Tag } }
    else { $n = $treeLib.SelectedNode; if ($n -and $n.Tag) { $t = $n.Tag } }
    if ($t -and $t.Kind -eq 'zip') {
        $s = $script:LibSub
        if ($s -and $s.Kind -eq 'zipentry' -and $s.FileKind -eq 'image' -and $s.ZipPath -eq $t.Path) { return $s }
        return $null
    }
    return $t
}

function Resolve-LibSelection {
    # Image ou document selectionne : chemin (entree d archive extraite dans TempDir) et source unique (fichier, ou
    # archive + entree : deux archives peuvent extraire le meme nom de fichier)
    $t = Get-LibWriteTarget
    if (-not $t) { return $null }
    if ($t.Kind -eq 'zipentry') {
        $form.Cursor = [System.Windows.Forms.Cursors]::WaitCursor
        try {
            $p = Expand-ZipEntry $t.ZipPath $t.Entry
            Append-Log ((T "Extrait : {0} -> {1}") -f "$($t.Entry)", "$p")
            # FIX4B (revue du lot 4, C3) : image extraite controlee contre la taille et le CRC-32 annonces par l archive
            # (ZipArchive ne verifie pas les donnees) : une image alteree n est jamais ecrite, meme si la liste de reference
            # dit l archive « officiel »
            if ($t.FileKind -eq 'image') {
                $chk = Test-LibZipEntryData $t.ZipPath $t.Idx $t.Entry $p
                if ($chk -and -not $chk.Ok) {
                    try { [System.IO.File]::Delete($p) } catch { }
                    Show-LibNotice ((T "Image altérée dans l'archive : CRC-32 {0} au lieu de {1}. Écriture annulée.") -f $chk.Got, $chk.Want)
                    return $null
                }
            }
            return @{ Path = $p; IsImage = ($t.FileKind -eq 'image'); Source = "$($t.ZipPath)|$($t.Entry)" }
        } catch {
            Append-Log ((T "Extraction impossible : {0}") -f "$($_.Exception.Message)")
            return $null
        } finally { $form.Cursor = [System.Windows.Forms.Cursors]::Default }
    }
    if ($t.Kind -eq 'image' -or $t.Kind -eq 'doc' -or $t.Kind -eq 'other') {
        return @{ Path = $t.Path; IsImage = ($t.Kind -eq 'image'); Source = $t.Path }
    }
    return $null
}

# ============================== BIBLIOTHEQUE : LISTE DES RESULTATS (12.8, LOT 4A) =
# Recherche saisie : ListView Details groupee par titre court (groupes non repliables : ListViewGroup.CollapsedState
# n existe pas en .NET Framework), colonnes Variante, Disq., Version, Langue, Etat, Format, Taille, Dossier ; tri par
# colonne ; badges (pastille du format et pictogramme d etat du lot 3) ; filtres Format, Langue, copies modifiees,
# originaux. Travail differe (bloc INFO des IPF, disquettes manquantes) par tranches au minuteur principal : ni runspace
# ni bloc C# nouveau, l interface reste disponible pendant la lecture d un partage.

function Set-LibViewMode([bool]$list) {
    $script:LibListMode = $list
    $lvLib.Visible = $list; $treeLib.Visible = -not $list
    foreach ($c in @($cmbLibFmt, $cmbLibLang, $chkLibHideMod, $chkLibOrig)) { $c.Enabled = $list }
}

function Get-LibFormatCode([string]$ext, [string]$kind) {
    # Format affiche : extension en majuscules (4 lettres au plus), ZIP pour une archive
    if ($kind -eq 'zip') { return 'ZIP' }
    if (-not $ext) { return '' }
    $c = $ext.TrimStart('.').ToUpperInvariant()
    if ($c.Length -gt 4) { $c = $c.Substring(0, 4) }
    return $c
}

function Get-LibFormatColor([string]$fmt) {
    # Couleur de la pastille du format : IPF Accent, ADF Floppy, ZIP Zip, flux (SCP, HFE...) WarnInk, documents Muted,
    # autres images secteur Ok ; texte blanc (contraste >= 3:1, element graphique)
    if ($fmt -eq 'IPF') { return $script:Theme.Accent }
    if ($fmt -eq 'ADF') { return $script:Theme.Floppy }
    if ($fmt -eq 'ZIP') { return $script:Theme.Zip }
    if (@('SCP', 'HFE', 'A2R', 'RAW', 'CTR', 'DMK') -contains $fmt) { return $script:Theme.WarnInk }
    if (@('PDF', 'TXT', 'JPG', 'JPEG', 'PNG', 'GIF', 'NFO', 'MD') -contains $fmt) { return $script:Theme.Muted }
    return $script:Theme.Ok
}

function Get-LibRecord([string]$rel, [long]$size, [string]$kind) {
    # Fiche d un fichier de la liste ; nom analyse une fois (cache par chemin relatif et taille)
    $r = $script:LibRecCache[$rel]
    if ($r -and $r.Size -eq $size -and $r.Kind -eq $kind) { return $r }
    $i = $rel.LastIndexOf('\')
    $name = $rel.Substring($i + 1)
    $relDir = if ($i -gt 0) { $rel.Substring(0, $i) } else { '' }
    $dirName = if ($relDir) { $relDir.Substring($relDir.LastIndexOf('\') + 1) } else { $script:LibRootLeaf }
    $info = Get-LibNameInfo $name $dirName
    $path = $script:LibRoot + '\' + $rel
    $dirFull = if ($relDir) { $script:LibRoot + '\' + $relDir } else { $script:LibRoot }
    $r = @{ Rel = $rel; Path = $path; Name = $name; RelDir = $relDir; Size = $size; Kind = $kind; Ext = $info.Ext
            Fmt = (Get-LibFormatCode $info.Ext $kind); Info = $info; SetId = "$dirFull|$($info.SetKey)"; Item = $null; StateText = '' }
    $script:LibRecCache[$rel] = $r
    return $r
}

function Get-LibNodeRecord($tag) {
    # Fiche d un element de l arborescence (dossier, fichier, archive, entree d archive)
    if (-not $tag) { return $null }
    if ($tag.Kind -eq 'dir') { return @{ Kind = 'dir'; Path = $tag.Path } }
    if ($tag.Kind -eq 'zipentry') { return (Get-LibEntryRecord $tag) }
    if (-not $tag.Path) { return $null }
    $name = [System.IO.Path]::GetFileName($tag.Path); $dir = [System.IO.Path]::GetDirectoryName($tag.Path)
    $info = Get-LibNameInfo $name ([System.IO.Path]::GetFileName($dir))
    return @{ Kind = $tag.Kind; Path = $tag.Path; Name = $name; Size = [long]$tag.Size; Ext = $info.Ext; Fmt = (Get-LibFormatCode $info.Ext $tag.Kind)
              Info = $info; SetId = "$dir|$($info.SetKey)"; RelDir = $dir; Rel = $tag.Path; Item = $null; StateText = '' }
}

function Get-LibEntryRecord($e) {
    # Fiche d une entree d archive ZIP (arborescence, ou entree choisie dans le panneau)
    $name = $e.Entry.Substring($e.Entry.LastIndexOf('/') + 1)
    $info = Get-LibNameInfo $name ''
    return @{ Kind = 'zipentry'; ZipPath = $e.ZipPath; Entry = $e.Entry; Size = [long]$e.Size; FileKind = $e.FileKind; Name = $name; Idx = $e.Idx
              Ext = $info.Ext; Fmt = (Get-LibFormatCode $info.Ext $e.FileKind); Info = $info; Path = $e.ZipPath; SetId = ''; Item = $null; StateText = '' }
}

function Get-LibIpfKey($r) {
    if ($r.Kind -eq 'zipentry') { return "$($r.ZipPath)|$($r.Entry)|$($r.Size)" }
    return "$($r.Path)|$($r.Size)"
}

function Read-LibBytes($r, [long[]]$at, [int[]]$len) {
    # Octets aux positions croissantes $at d un fichier, ou d une entree de ZIP (flux decompresse en memoire, sans
    # extraction). Fichier partage en lecture (FileShare.ReadWrite) ; element $null si la lecture est incomplete
    $res = New-Object 'object[]' $at.Count
    $zip = $null; $s = $null
    try {
        if ($r.Kind -eq 'zipentry') {
            $zip = [System.IO.Compression.ZipFile]::OpenRead($r.ZipPath)
            $e = $zip.GetEntry($r.Entry)
            if (-not $e) { return ,$res }
            $s = $e.Open()
        } else {
            $s = [System.IO.File]::Open($r.Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
        }
        $pos = [long]0
        for ($i = 0; $i -lt $at.Count; $i++) {
            if ($s.CanSeek) { [void]$s.Seek($at[$i], [System.IO.SeekOrigin]::Begin); $pos = $at[$i] }
            else {
                $skip = New-Object byte[] 65536
                while ($pos -lt $at[$i]) { $k = $s.Read($skip, 0, [int][math]::Min(65536, $at[$i] - $pos)); if ($k -le 0) { break }; $pos += $k }
                if ($pos -lt $at[$i]) { break }
            }
            $buf = New-Object byte[] $len[$i]; $got = 0
            while ($got -lt $len[$i]) { $k = $s.Read($buf, $got, $len[$i] - $got); if ($k -le 0) { break }; $got += $k }
            $pos += $got
            if ($got -eq $len[$i]) { $res[$i] = $buf }
        }
    } catch { } finally {
        if ($s) { $s.Dispose() }
        if ($zip) { $zip.Dispose() }
    }
    return ,$res
}

function Get-LibIpf($r) {
    # Bloc INFO d un IPF (108 premiers octets), en cache par chemin et taille
    $k = Get-LibIpfKey $r
    $o = $script:LibIpfCache[$k]
    if ($o) { return $o }
    $b = Read-LibBytes $r @(0) @(108)
    $o = Get-IpfInfoBlock $b[0]
    $script:LibIpfCache[$k] = $o
    return $o
}

function Get-LibAdf($r) {
    # Bloc de demarrage (1 024 octets) et bloc racine (880, ou 1760 en haute densite) d un ADF
    $size = [long]$r.Size
    $hd = ($size -gt 0 -and $size % 22528 -eq 0 -and $size / 11264 -gt 84)
    $rootAt = if ($hd) { [long]1760 * 512 } else { [long]880 * 512 }
    $b = Read-LibBytes $r @(0, $rootAt) @(1024, 512)
    return (Get-AdfInfo $b[0] $b[1] $size)
}

function Get-LibRowState($r) {
    # Colonne « Etat » et badge : identification par la liste de reference (12.8, lot 4b : officiel, modifie, inconnu ;
    # « … » en attente), puis, pour un IPF, bloc INFO (lu en differe), puis mentions TOSEC du nom. Pictogramme (lot 3) :
    # h2 image defectueuse ([b] [o] [u] [v]) ou CRC faux ; h1 copie modifiee (mention du nom, ou modifie d apres la liste) ;
    # h0 officiel d apres la liste ; sps structure SPS (disquette du logo) ; h0 image verifiee [!] ; user IPF utilisateur
    # (disquette grise) ; hq bloc INFO illisible ; aucun sinon
    $i = $r.Info; $parts = @(); $icon = ''
    $ds = Get-LibDatQuick $r
    $dk = if ($ds) { [string]$ds.State } else { '' }
    if ($dk -and $dk -ne 'wait') { $parts += (Get-LibDatWord $dk) }
    $ipfKind = ''
    if ($r.Ext -eq '.ipf' -and $r.Kind -ne 'zip') {
        $ipf = $script:LibIpfCache[(Get-LibIpfKey $r)]
        $ipfKind = if ($ipf) { $ipf.Kind } else { 'wait' }
    }
    switch ($ipfKind) {
        'sps'   { $parts += 'SPS' }
        'user'  { $parts += (T 'utilisateur') }
        'crc'   { $parts += (T 'CRC faux') }
        'none'  { $parts += '?' }
        'other' { $parts += '?' }
        'wait'  { $parts += '…' }
    }
    if ($dk -eq 'wait' -and $ipfKind -ne 'wait') { $parts = @('…') + $parts }
    if ($i.FlagText) { $parts += $i.FlagText }
    if ($i.State -eq 'bad' -or $ipfKind -eq 'crc') { $icon = 'h2' }
    elseif ($i.State -eq 'mod' -or $dk -eq 'mod') { $icon = 'h1' }
    elseif ($dk -eq 'ok') { $icon = 'h0' }
    elseif ($ipfKind -eq 'sps') { $icon = 'sps' }
    elseif ($i.State -eq 'ok') { $icon = 'h0' }
    elseif ($ipfKind -eq 'user') { $icon = 'user' }
    elseif ($ipfKind -eq 'none' -or $ipfKind -eq 'other') { $icon = 'hq' }
    $col = $script:Theme.Muted
    switch ($icon) { 'h2' { $col = Get-QualInk 3 } 'h1' { $col = $script:Theme.WarnInk } 'sps' { $col = $script:Theme.Accent } 'h0' { $col = Get-QualInk 0 } }
    if (-not $icon -and $i.FlagText) { $col = [System.Drawing.SystemColors]::WindowText }
    return @{ Text = ($parts -join ' '); Icon = $icon; Color = $col; Ipf = $ipfKind; Dat = $dk }
}

function Get-LibStateIcon([string]$icon) {
    # Pictogramme d etat de 16 px : ceux du lot 3 (h0, h1, h2, hq), disquette du logo pour la structure SPS, grisee pour un
    # IPF utilisateur ; en cache avec les ressources de la qualite (liberees a la fermeture)
    if ($icon -ne 'sps' -and $icon -ne 'user') { return (Get-QualityIcon $icon 16) }
    $k = "ilib$icon"
    $o = $script:QualGdi[$k]
    if ($o) { return $o }
    if ($icon -eq 'user') { $o = New-QualityGreyBitmap (Get-LibStateIcon 'sps') }
    else {
        $o = New-Object System.Drawing.Bitmap(16, 16, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
        $g = [System.Drawing.Graphics]::FromImage($o)
        try { $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias; Draw-PictoFloppy $g 0 0 16 $false } finally { $g.Dispose() }
    }
    $script:QualGdi[$k] = $o
    return $o
}

function New-LibBadge([string]$fmt, [string]$icon) {
    # Badge de 42 x 16 px de la colonne « Variante » : pastille du format, puis pictogramme d etat
    $bmp = New-Object System.Drawing.Bitmap(42, 16, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
    $g = [System.Drawing.Graphics]::FromImage($bmp)
    try {
        $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
        $g.TextRenderingHint = [System.Drawing.Text.TextRenderingHint]::AntiAliasGridFit
        if ($fmt) {
            $rr = New-RoundRect 0.5 2 24 12 3
            $g.FillPath((Get-QualBrush (Get-LibFormatColor $fmt)), $rr); $rr.Dispose()
            $f = Get-QualFont 'Segoe UI' $(if ($fmt.Length -gt 3) { 5 } else { 6 }) 'Bold'
            $g.DrawString($fmt, $f, (Get-QualBrush ([System.Drawing.Color]::White)), (New-Object System.Drawing.RectangleF(0, 2, 25, 12)), (Get-QualSf 'center'))
        }
        if ($icon) { $g.DrawImage((Get-LibStateIcon $icon), 26, 0, 16, 16) }
    } finally { $g.Dispose() }
    return $bmp
}

function Get-LibBadgeKey($r, $st) {
    $k = "$($r.Fmt)|$($st.Icon)"
    if (-not $imgLibBadge.Images.ContainsKey($k)) { $imgLibBadge.Images.Add($k, (New-LibBadge $r.Fmt $st.Icon)) }
    return $k
}

function Set-LibResults([string]$root, $cand, [string[]]$all) {
    # Nouvelle recherche : $cand, candidats de l index ou de la recherche de repli (Rel, Size, Kind ; ordre des chemins) ;
    # $all, chemins relatifs retenus par la regle des mots ; puis liste
    Stop-LibWork
    $rootT = $root.TrimEnd('\')
    if ($script:LibRoot -ne $rootT) { $script:LibRecCache = @{}; $script:LibSetCache = @{} }
    $script:LibRoot = $rootT
    $script:LibRootLeaf = [System.IO.Path]::GetFileName($rootT)
    $script:LibCand = $cand
    $script:LibAll = [string[]]@(); if ($null -ne $all) { $script:LibAll = [string[]]$all }
    # FIX4B (revue du lot 4, C4) : nouvelle recherche ou « Actualiser » : etats d identification lus dans les fichiers
    # revalides en differe (un fichier modifie a taille egale, un ADF ou un emulateur enregistre une partie, n est plus
    # dit « officiel ») ; pas a chaque tri ou filtre
    $script:LibDatRecheck = $true
    Update-LibFormatChoices
    Show-LibResults
}

function Update-LibFormatChoices {
    # Formats presents dans les correspondances (extensions, operateurs vectorises) ; choix courant garde, meme absent
    $cur = if ($cmbLibFmt.SelectedIndex -gt 0) { [string]$cmbLibFmt.SelectedItem } else { '' }
    $set = @{}
    if ($script:LibAll.Count -gt 0) {
        $ext = [string[]](($script:LibAll -replace '^.*\\', '') -replace '^[^.]*$', '' -replace '^.*\.', '')
        foreach ($x in [System.Collections.Generic.HashSet[string]]::new($ext, [System.StringComparer]::OrdinalIgnoreCase)) {
            if (-not $x) { continue }
            $c = $x.ToUpperInvariant(); if ($c.Length -gt 4) { $c = $c.Substring(0, 4) }
            $set[$c] = $true
        }
    }
    if ($cur) { $set[$cur] = $true }
    $script:LibRendering = $true
    try {
        $cmbLibFmt.BeginUpdate()
        $cmbLibFmt.Items.Clear(); [void]$cmbLibFmt.Items.Add((T 'Tous'))
        foreach ($f in @($set.Keys | Sort-Object)) { [void]$cmbLibFmt.Items.Add($f) }
        $cmbLibFmt.SelectedIndex = $(if ($cur) { $cmbLibFmt.Items.IndexOf($cur) } else { 0 })
        $cmbLibFmt.EndUpdate()
    } finally { $script:LibRendering = $false }
}

function Update-LibLangChoices($recs) {
    # Langues presentes dans les fiches analysees (indiquees, ou langue du pays) ; choix courant garde, meme absent
    $cur = if ($cmbLibLang.SelectedIndex -gt 0) { [string]$cmbLibLang.SelectedItem } else { '' }
    $set = @{}
    foreach ($r in $recs) { foreach ($l in $r.Info.LangList) { $set[$l] = $true } }
    if ($cur) { $set[$cur] = $true }
    $script:LibRendering = $true
    try {
        $cmbLibLang.BeginUpdate()
        $cmbLibLang.Items.Clear(); [void]$cmbLibLang.Items.Add((T 'Toutes'))
        foreach ($l in @($set.Keys | Sort-Object)) { [void]$cmbLibLang.Items.Add($l) }
        $cmbLibLang.SelectedIndex = $(if ($cur) { $cmbLibLang.Items.IndexOf($cur) } else { 0 })
        $cmbLibLang.EndUpdate()
    } finally { $script:LibRendering = $false }
}

function Update-LibFilters {
    # Filtre ou tri change : liste refaite depuis les fiches en cache (aucune nouvelle recherche)
    if ($script:LibRendering -or -not $script:LibListMode -or $null -eq $script:LibAll) { return }
    Show-LibResults -Keep
}

function Get-LibSortValue($r, [int]$col) {
    # Partie de cle de tri croissant d une colonne (comparaison ordinale) : nombres sur des chiffres fixes, textes en
    # minuscules. Ordre decroissant : Get-LibDescKeys
    $num = $null
    switch ($col) {
        0 { $s = $(if ($r.Info.Variant) { $r.Info.Variant } else { $r.Info.Base }) }
        1 { $num = [long]$r.Info.DiskNo }
        2 { $s = [string]$r.Info.Version }
        3 { $s = [string]$r.Info.Langs }
        4 { $s = [string](Get-LibRowState $r).Text }
        5 { $s = [string]$r.Fmt }
        6 { $num = [long]$r.Size }
        default { $s = [string]$r.RelDir }
    }
    if ($null -ne $num) { return $num.ToString('D15') }
    return $s.ToLowerInvariant() + [char]0
}

function Get-LibDescKeys([string[]]$vals) {
    # Cles de tri decroissant : rang de chaque valeur dans l ordre ordinal croissant, inverse et ecrit sur 7 chiffres
    # (valeurs egales : meme rang, departagees ensuite par le nom du fichier). Aucune transformation caractere par caractere
    $s = [string[]]$vals.Clone()
    [Array]::Sort([Array]$s, [System.Collections.IComparer][System.StringComparer]::Ordinal)
    $rank = [System.Collections.Generic.Dictionary[string, int]]::new([System.StringComparer]::Ordinal)
    foreach ($v in $s) { if (-not $rank.ContainsKey($v)) { $rank[$v] = $rank.Count } }
    $top = $rank.Count
    $out = New-Object 'string[]' $vals.Length
    for ($i = 0; $i -lt $vals.Length; $i++) { $out[$i] = ($top - $rank[$vals[$i]]).ToString('D7') }
    return ,$out
}

function Get-LibSetSortValue($r, [string]$sep) {
    # FIX4B (revue du lot 4, constat 1) : ordre dans un groupe : images et archives avant les documents, puis jeu de
    # disquettes (variante du jeu, version, langue, mentions, extension), puis disquette. Les disquettes d un meme jeu restent
    # contigues : la copie [cr] allemande en deux disquettes ne s intercale plus entre celles de l original en trois
    $i = $r.Info
    $rank = if ($r.Kind -eq 'doc' -or $r.Kind -eq 'other') { '1' } else { '0' }
    return ($rank + $sep + ([string]$i.SetVariant).ToLowerInvariant() + $sep + ([string]$i.Version).ToLowerInvariant() + $sep + [string]$i.Langs + $sep +
            ([string]$i.FlagText).ToLowerInvariant() + $sep + [string]$r.Ext + $sep + ([long]$i.DiskNo).ToString('D4'))
}

function Sort-LibRecords($recs) {
    # Groupes dans l ordre des titres ; dans un groupe : colonne choisie (croissant ou decroissant), puis jeu de disquettes
    # et disquette (Get-LibSetSortValue) ; nom du fichier en dernier. Cle composee triee par [Array]::Sort (ordinal,
    # natif) : Sort-Object avec des blocs de script prenait plusieurs secondes pour 2 000 lignes sous Windows PowerShell 5.1
    $col = [int]$script:LibSort.Col; $desc = [bool]$script:LibSort.Desc
    $n = $recs.Count
    $keys = New-Object 'string[]' $n; $arr = New-Object 'object[]' $n
    $sep = [string][char]1
    $vals = $null
    if ($col -ge 0) {
        $vals = New-Object 'string[]' $n
        for ($i = 0; $i -lt $n; $i++) { $vals[$i] = Get-LibSortValue $recs[$i] $col }
        if ($desc) { $vals = Get-LibDescKeys $vals }
    }
    for ($i = 0; $i -lt $n; $i++) {
        $r = $recs[$i]; $arr[$i] = $r
        $v = Get-LibSetSortValue $r $sep
        if ($null -ne $vals) { $v = $vals[$i] + $sep + $v }
        $keys[$i] = $r.Info.SortKey + $sep + $r.Info.Key + $sep + $v + $sep + $r.Name.ToLowerInvariant()
    }
    # Surcharge non generique imposee : sinon PowerShell lie Sort<TKey,TValue> sur une copie des lignes (cles seules triees)
    [Array]::Sort([Array]$keys, [Array]$arr, [System.Collections.IComparer][System.StringComparer]::Ordinal)
    return ,$arr
}

function Set-LibSort([int]$col) {
    # Clic sur un en-tete : tri par cette colonne, puis ordre inverse au clic suivant (fleche dans l en-tete)
    if ($script:LibSort.Col -eq $col) { $script:LibSort.Desc = -not $script:LibSort.Desc } else { $script:LibSort.Col = $col; $script:LibSort.Desc = $false }
    for ($j = 0; $j -lt $lvLib.Columns.Count; $j++) {
        $t = $script:LibColTitles[$j]
        $c = $lvLib.Columns[$j]
        if ($j -eq $col) {
            $t += $(if ($script:LibSort.Desc) { ' ▼' } else { ' ▲' })
            # FIX4B (revue du lot 4) : colonne elargie si son titre et la fleche n y tiennent pas (« Langue ▲ »)
            $need = Get-LibColumnWidth $t
            if ($c.Width -lt $need) { $c.Width = $need; $script:LibColAuto[$j] = $need }
        } elseif ($script:LibColAuto[$j] -and $c.Width -eq $script:LibColAuto[$j] -and $j -lt $script:LibColW.Count) {
            # Colonne qui n est plus triee : largeur de depart rendue (sauf si l utilisateur l a changee entre-temps)
            $c.Width = $script:LibColW[$j]; $script:LibColAuto[$j] = 0
        }
        $c.Text = $t
    }
    Update-LibFilters
}

function Get-LibColumnWidth([string]$title, [int]$min = 0) {
    # Largeur d une colonne de la liste : titre mesure dans la police de la liste (celle de la fenetre tant que la liste
    # n est pas placee dans l onglet), plus les marges de l en-tete
    $f = if ($lvLib -and $lvLib.Parent) { $lvLib.Font } else { $form.Font }
    $w = [System.Windows.Forms.TextRenderer]::MeasureText($title, $f).Width + 14
    return [int][math]::Max($min, $w)
}

function New-LibListItem($r) {
    $i = $r.Info
    $st = Get-LibRowState $r
    $it = [System.Windows.Forms.ListViewItem]::new($(if ($i.Variant) { $i.Variant } else { $i.Base }))
    $it.UseItemStyleForSubItems = $false
    [void]$it.SubItems.Add((Get-LibDiskText $i))
    [void]$it.SubItems.Add([string]$i.Version)
    $sl = $it.SubItems.Add([string]$i.Langs); if ($i.LangDerived) { $sl.ForeColor = $script:Theme.Muted }
    $ss = $it.SubItems.Add($st.Text); $ss.ForeColor = $st.Color
    [void]$it.SubItems.Add([string]$r.Fmt)
    [void]$it.SubItems.Add((Format-Size $r.Size))
    [void]$it.SubItems.Add($(if ($r.RelDir) { $r.RelDir } else { '.' }))
    $it.ImageKey = Get-LibBadgeKey $r $st
    $it.ToolTipText = $r.Rel
    $it.Tag = $r
    $r.Item = $it; $r.StateText = $st.Text
    return $it
}

function Update-LibRowState($r, [switch]$Detached) {
    # Bloc INFO lu (en differe ou a la selection) : colonne « Etat » et badge de la ligne mis a jour sur place ; -Detached :
    # ligne gardee d un affichage precedent, remise a jour avant d etre reutilisee
    $it = $r.Item
    if (-not $it) { return }
    if (-not $Detached -and -not $it.ListView) { return }
    $st = Get-LibRowState $r
    if ($it.SubItems[4].Text -eq $st.Text) { return }
    $it.SubItems[4].Text = $st.Text; $it.SubItems[4].ForeColor = $st.Color
    $it.ImageKey = Get-LibBadgeKey $r $st
    $r.StateText = $st.Text
}

function Get-LibMissingText($m, [switch]$Short) {
    # Disquettes manquantes : « manque 3 (jeu de 3) » ; -Short, colonne « Etat » de la liste (100 px) : « manque 3 », le
    # nombre de disquettes du jeu reste dans l infobulle de la ligne et dans le panneau
    if ($m.Known -and -not $Short) { return ((T 'manque {0} (jeu de {1})') -f (Format-LibDiskList $m), $m.Total) }
    return ((T 'manque {0}') -f (Format-LibDiskList $m))
}

function New-LibMissingItem($r, $m) {
    # Ligne « disquettes manquantes » d un jeu, a la fin de son groupe (A3 § 4.2 n° 5) : variante du jeu, texte dans la
    # colonne « Etat » en WarnInk, pictogramme « ! » du lot 3. L en-tete d un groupe n est jamais modifie apres son ajout :
    # sous .NET Framework, ListViewGroup.Header recree la poignee de la liste (toutes les lignes reinserees).
    # FIX4B (revue du lot 4) : texte court dans la colonne (forme longue dans l infobulle et le panneau) ; variante du jeu,
    # sans les crochets propres a une disquette
    $t = Get-LibMissingText $m -Short
    $it = [System.Windows.Forms.ListViewItem]::new($(if ($r.Info.SetVariant) { $r.Info.SetVariant } else { $r.Info.Title }))
    $it.UseItemStyleForSubItems = $false
    [void]$it.SubItems.Add('')
    [void]$it.SubItems.Add([string]$r.Info.Version)
    [void]$it.SubItems.Add([string]$r.Info.Langs)
    $ss = $it.SubItems.Add($t); $ss.ForeColor = $script:Theme.WarnInk
    [void]$it.SubItems.Add([string]$r.Fmt)
    [void]$it.SubItems.Add('')
    [void]$it.SubItems.Add($(if ($r.RelDir) { $r.RelDir } else { '.' }))
    $it.ImageKey = Get-LibBadgeKey @{ Fmt = '' } @{ Icon = 'h1' }
    $it.ToolTipText = (T 'Jeu incomplet : {0}') -f (Get-LibMissingText $m)
    $it.Tag = @{ Kind = 'missing'; Rel = "missing|$($r.SetId)"; Name = ''; Info = $r.Info; Missing = $m; SetId = $r.SetId; Fmt = $r.Fmt; RelDir = $r.RelDir; Path = $r.Path }
    return $it
}

function Add-LibMissingRow($r) {
    # Travail differe : jeu incomplet trouve apres l affichage -> ligne ajoutee a la fin de son groupe (sans recreer la liste)
    $m = $script:LibSetCache[$r.SetId]
    if (-not $m -or -not $m.Missing -or $m.Missing.Count -eq 0) { return }
    $g = $script:LibGroups[$r.Info.Key]
    if (-not $g -or -not $r.Item -or -not $r.Item.ListView) { return }
    $it = New-LibMissingItem $r $m
    $it.Group = $g.Group
    [void]$lvLib.Items.Add($it)
}

function Show-LibResults([switch]$Keep) {
    # Liste des resultats : filtre Format sur toutes les correspondances, 2 000 premieres analysees, puis filtres Langue,
    # copies modifiees et originaux ; groupes dans l ordre des titres, lignes triees ; travail differe relance
    Stop-LibWork
    [void](Get-LibDat)      # 12.8 (lot 4b) : liste de reference enregistree, lue a la premiere demande
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    $max = 2000
    $fmtSel = if ($cmbLibFmt.SelectedIndex -gt 0) { [string]$cmbLibFmt.SelectedItem } else { '' }
    $langSel = if ($cmbLibLang.SelectedIndex -gt 0) { [string]$cmbLibLang.SelectedItem } else { '' }
    $hideMod = [bool]$chkLibHideMod.Checked; $orig = [bool]$chkLibOrig.Checked
    $keepRel = $null
    if ($Keep -and $lvLib.SelectedItems.Count -gt 0) { $keepRel = $lvLib.SelectedItems[0].Tag.Rel }
    # Filtre Format sur toutes les correspondances (chemins), puis fiches des 2 000 premieres dans l ordre des candidats.
    # FIX4B (revue du lot 4) : le total reste celui des correspondances ; les fichiers d un autre format comptent parmi les
    # masques (compteur et infobulle), comme ceux des autres filtres
    $fm = $script:LibAll
    if ($fmtSel -and $fm.Count -gt 0) { $fm = [string[]]@($fm -match ('(?i)\.' + [regex]::Escape($fmtSel) + '[^.\\]*$')) }
    $total = $fm.Count
    $fmtHidden = $script:LibAll.Count - $fm.Count
    $recs = [System.Collections.Generic.List[object]]::new()
    if ($total -gt 0) {
        $set = [System.Collections.Generic.HashSet[string]]::new([string[]]$fm, [System.StringComparer]::Ordinal)
        foreach ($e in $script:LibCand) {
            if ($recs.Count -ge $max) { break }
            if ($set.Contains([string]$e.Rel)) { $recs.Add((Get-LibRecord ([string]$e.Rel) ([long]$e.Size) ([string]$e.Kind))) }
        }
    }
    $script:LibParseMs = $sw.ElapsedMilliseconds
    $tm = [ordered]@{ fiches = $sw.ElapsedMilliseconds }
    Update-LibLangChoices $recs
    $shown = [System.Collections.Generic.List[object]]::new(); $hidden = 0; $script:LibOrigPending = $false
    foreach ($r in $recs) {
        $i = $r.Info
        if ($langSel -and $i.LangList -notcontains $langSel) { $hidden++; continue }
        if ($hideMod -and $i.Modified) { $hidden++; continue }
        if ($orig -and (Test-LibDatOn)) {
            # 12.8 (lot 4b) : liste de reference chargee : fichiers officiels seulement (images et archives)
            $dq = Get-LibDatQuick $r
            if (-not $dq) { $hidden++; continue }
            if ($dq.State -eq 'wait') { $script:LibOrigPending = $true; $hidden++; continue }
            if ($dq.State -ne 'ok') { $hidden++; continue }
        } elseif ($orig) {
            if ($r.Ext -ne '.ipf' -or $r.Kind -eq 'zip') { $hidden++; continue }
            $ipf = $script:LibIpfCache[(Get-LibIpfKey $r)]
            if (-not $ipf) { $script:LibOrigPending = $true; $hidden++; continue }
            if ($ipf.Kind -ne 'sps') { $hidden++; continue }
        }
        $shown.Add($r)
    }
    $tm.filtres = $sw.ElapsedMilliseconds
    $sorted = Sort-LibRecords $shown
    $tm.tri = $sw.ElapsedMilliseconds
    $script:LibRendering = $true
    $lvLib.BeginUpdate()
    try {
        $lvLib.Items.Clear(); $lvLib.Groups.Clear()
        $tm.vidage = $sw.ElapsedMilliseconds
        # Groupes formes d abord (ordre des titres), en-tete complet des la creation : ListViewGroup.Header ne se change
        # plus une fois le groupe dans la liste (sous .NET Framework, chaque changement recree la poignee de la liste)
        $script:LibGroups = @{}; $order = [System.Collections.Generic.List[string]]::new()
        foreach ($r in $sorted) {
            $k = $r.Info.Key
            $g = $script:LibGroups[$k]
            if (-not $g) { $g = @{ Title = $r.Info.Title; Recs = [System.Collections.Generic.List[object]]::new() }; $script:LibGroups[$k] = $g; $order.Add($k) }
            $g.Recs.Add($r)
        }
        $groups = [System.Collections.Generic.List[System.Windows.Forms.ListViewGroup]]::new()
        $items = [System.Collections.Generic.List[System.Windows.Forms.ListViewItem]]::new()
        foreach ($k in $order) {
            $g = $script:LibGroups[$k]
            $g.Group = [System.Windows.Forms.ListViewGroup]::new($k, ((T '{0}  ·  {1} fichier(s)') -f $g.Title, $g.Recs.Count))
            $groups.Add($g.Group)
            $seen = @{}
            # Ligne d un affichage precedent (tri, filtre) reutilisee : seule sa colonne « Etat » est remise a jour
            foreach ($r in $g.Recs) {
                $it = $r.Item
                if ($it -and -not $it.ListView) { $it.Selected = $false; Update-LibRowState $r -Detached } else { $it = New-LibListItem $r }
                $it.Group = $g.Group; $items.Add($it)
            }
            # Jeux incomplets deja connus (cache) : ligne a la fin du groupe
            foreach ($r in $g.Recs) {
                if ($seen.ContainsKey($r.SetId)) { continue }
                $seen[$r.SetId] = $true
                $m = $script:LibSetCache[$r.SetId]
                if ($m -and $m.Missing -and $m.Missing.Count -gt 0) { $it = New-LibMissingItem $r $m; $it.Group = $g.Group; $items.Add($it) }
            }
        }
        $tm.lignes = $sw.ElapsedMilliseconds
        $lvLib.Groups.AddRange($groups.ToArray())
        $tm.groupes = $sw.ElapsedMilliseconds
        $lvLib.Items.AddRange($items.ToArray())
        $tm.ajout = $sw.ElapsedMilliseconds
    } finally { $lvLib.EndUpdate(); $script:LibRendering = $false }
    $script:LibCounts = @{ Total = $script:LibAll.Count; Capped = $recs.Count; Shown = $shown.Count; Hidden = $hidden + $fmtHidden; Max = $max }
    $script:LibRenderMs = $sw.ElapsedMilliseconds
    $tm.total = $sw.ElapsedMilliseconds; $script:LibTimes = $tm
    $kept = $false
    if ($keepRel) {
        foreach ($it in $lvLib.Items) { if ($it.Tag.Rel -eq $keepRel) { $it.Selected = $true; $it.EnsureVisible(); $kept = $true; break } }
    }
    if (-not $kept) { Clear-LibDetails }
    Start-LibWork $recs $shown
    Update-LibCountText
}

function Update-LibCountText {
    # Compteur : resultats, plafond de 2 000, lignes masquees par les filtres, avancement du travail differe
    $c = $script:LibCounts
    if (-not $c) { return }
    $t = if ($c.Hidden -gt 0) { (T '{0} affiché(s), {1} masqué(s)') -f "$('{0:N0}' -f $c.Shown)", "$('{0:N0}' -f $c.Hidden)" }
         elseif ($c.Total -gt $c.Capped) { (T "{0} premiers sur {1}") -f "$('{0:N0}' -f $c.Capped)", "$('{0:N0}' -f $c.Total)" }
         else { (T "{0} résultat(s)") -f "$('{0:N0}' -f $c.Total)" }
    if ($script:LibWork.Count -gt 0) { $t += '  ·  ' + ((T 'analyse {0}/{1}') -f $script:LibWorkDone, $script:LibWorkTotal) }
    $lblLibCount.Text = $t
    $tip.SetToolTip($lblLibCount, ((T "{0} fichier(s) dont le nom correspond ; {1} analysé(s) (2 000 au plus) ; {2} masqué(s) par les filtres ; {3} affiché(s).") -f "$('{0:N0}' -f $c.Total)", "$('{0:N0}' -f $c.Capped)", "$('{0:N0}' -f $c.Hidden)", "$('{0:N0}' -f $c.Shown)"))
}

function Start-LibWork($recs, $shown) {
    # Travail differe : bloc INFO des IPF analyses (etat SPS, filtre « Originaux seulement »), puis jeux a plusieurs
    # disquettes affiches (disquettes manquantes d apres les fichiers du dossier, pas d apres les seuls resultats)
    $script:LibWork.Clear(); $script:LibWorkDone = 0
    foreach ($r in $recs) {
        if ($r.Ext -eq '.ipf' -and $r.Kind -ne 'zip' -and -not $script:LibIpfCache.ContainsKey((Get-LibIpfKey $r))) { $script:LibWork.Enqueue(@{ T = 'ipf'; Rec = $r }) }
    }
    $seen = @{}
    foreach ($r in $shown) {
        if ($r.Info.DiskNo -gt 0 -and -not $seen.ContainsKey($r.SetId) -and -not $script:LibSetCache.ContainsKey($r.SetId)) { $seen[$r.SetId] = $true; $script:LibWork.Enqueue(@{ T = 'set'; Rec = $r }) }
    }
    # 12.8 (lot 4b) : identification par la liste de reference des images et archives dont la taille figure dans la liste
    # (lignes affichees d abord, puis lignes masquees par les filtres, pour « Originaux seulement ») ; FIX4B (C4) : apres
    # une nouvelle recherche, etats deja identifies par lecture revalides aussi (taille et date du fichier, Test-LibDatFresh)
    $recheck = [bool]$script:LibDatRecheck; $script:LibDatRecheck = $false
    if (Test-LibDatOn) {
        $seen = @{}
        foreach ($grp in @($shown, $recs)) {
            foreach ($r in $grp) {
                $q = Get-LibDatQuick $r
                if (-not $q -or ($q.State -ne 'wait' -and -not ($recheck -and $null -ne $q.Ticks))) { continue }
                $k = Get-LibIpfKey $r
                if ($seen.ContainsKey($k)) { continue }
                $seen[$k] = $true; $script:LibWork.Enqueue(@{ T = 'dat'; Rec = $r })
            }
        }
    }
    $script:LibWorkTotal = $script:LibWork.Count
}

function Stop-LibWork { $script:LibWork.Clear(); $script:LibWorkDone = 0; $script:LibWorkTotal = 0 }

function Step-LibWork([int]$budgetMs = 60) {
    # Une tranche du travail differe (minuteur principal, 200 ms) : $budgetMs au plus, puis la main revient a l interface
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    while ($script:LibWork.Count -gt 0 -and $sw.ElapsedMilliseconds -lt $budgetMs) {
        $w = $script:LibWork.Peek()
        if ($w.T -eq 'dat') {
            # 12.8 (lot 4b) : identification ; CRC-32 d un fichier d un seul tenant (bibliotheque ZIP de .NET)
            [void](Step-LibDatWork $w)
            [void]$script:LibWork.Dequeue(); $script:LibWorkDone++
            continue
        }
        [void]$script:LibWork.Dequeue(); $script:LibWorkDone++
        if ($w.T -eq 'ipf') { [void](Get-LibIpf $w.Rec); Update-LibRowState $w.Rec }
        else {
            $cached = $script:LibSetCache.ContainsKey($w.Rec.SetId)
            [void](Get-LibSetMissing $w.Rec)
            if (-not $cached) { Add-LibMissingRow $w.Rec }
        }
    }
    if ($script:LibWork.Count -eq 0) {
        $script:LibWorkTotal = 0
        if ($script:LibOrigPending -and $chkLibOrig.Checked) { $script:LibOrigPending = $false; Show-LibResults -Keep; return }
    }
    Update-LibCountText
}

function Get-LibSetMissing($r) {
    # Disquettes manquantes du jeu de $r, d apres les fichiers de son dossier (meme nom sans la disquette, meme extension) ;
    # cache par jeu. Dossier de publication SPS : tous ses fichiers ; sinon motif « debut du nom* » (filtre par le systeme
    # de fichiers, 500 fichiers au plus)
    if (-not $r -or -not $r.Info -or $r.Info.DiskNo -le 0 -or -not $r.SetId -or $r.Kind -eq 'zipentry') { return $null }
    $id = $r.SetId
    if ($script:LibSetCache.ContainsKey($id)) { return $script:LibSetCache[$id] }
    $res = $null
    try {
        $dir = [System.IO.Path]::GetDirectoryName($r.Path)
        $pat = if ($r.Info.Source -eq 'dir') { '*' } elseif ($r.Info.Prefix) { $r.Info.Prefix + '*' } else { '' }
        if ($pat) {
            $dirName = [System.IO.Path]::GetFileName($dir)
            $list = [System.Collections.Generic.List[object]]::new(); $n = 0; $unknown = 0
            foreach ($f in [System.IO.Directory]::EnumerateFiles($dir, $pat)) {
                $n++; if ($n -gt 500) { break }
                $i2 = Get-LibNameInfo ([System.IO.Path]::GetFileName($f)) $dirName
                if ($i2.SetKey -ne $r.Info.SetKey) { continue }
                if ($i2.DiskNo -gt 0) { $list.Add(@{ DiskNo = $i2.DiskNo; DiskTot = $i2.DiskTot; Letter = $i2.DiskLetter }); continue }
                # FIX4B (revue du lot 4, C2) : fichier du meme jeu sans numero de disquette dans le nom (publication SPS :
                # « SuperCars.ipf », « BodyBlows_BootDisk.ipf ») : numero lu dans le bloc INFO d un IPF ; sinon, ou bloc
                # illisible, aucun manque signale (la disquette « manquante » est peut-etre celle-la)
                $dn = 0
                if ($i2.Ext -eq '.ipf') {
                    try {
                        $ipf = Get-LibIpf @{ Kind = 'image'; Path = $f; Size = (New-Object System.IO.FileInfo($f)).Length }
                        if (($ipf.Kind -eq 'sps' -or $ipf.Kind -eq 'user') -and $ipf.DiskNumber -gt 0 -and $ipf.DiskNumber -le 99) { $dn = [int]$ipf.DiskNumber }
                    } catch { }
                }
                if ($dn -gt 0) { $list.Add(@{ DiskNo = $dn; DiskTot = 0; Letter = $false }) } else { $unknown++ }
            }
            $m = Get-LibMissingDisks @{ s = $list }
            $res = if ($m.ContainsKey('s') -and $unknown -eq 0) { $m['s'] } else { @{ Missing = @(); Total = 0; Known = $false; Letter = $false } }
        }
    } catch { $res = $null }
    $script:LibSetCache[$id] = $res
    return $res
}

# --- Panneau de details ---------------------------------------------------------------------------------------------
function Format-LibIpfDate([long]$d) {
    # Date du bloc INFO (entier AAAAMMJJ) au format JJ/MM/AAAA
    if ($d -lt 19000101 -or $d -gt 29991231) { return '' }
    $s = "$d"
    return "$($s.Substring(6, 2))/$($s.Substring(4, 2))/$($s.Substring(0, 4))"
}

function Get-LibPlatformName([long]$p) {
    switch ($p) {
        1 { return 'Amiga' } 2 { return 'Atari ST' } 3 { return 'PC' } 4 { return 'Amstrad CPC' } 5 { return 'Spectrum' }
        6 { return 'Sam Coupé' } 7 { return 'Archimedes' } 8 { return 'C64' } 9 { return (T 'Atari 8 bits') }
    }
    return "$p"
}

function Get-LibIpfLines($ipf) {
    # Bloc INFO (D18) : « IPF de structure SPS » sans liste, jamais « officiel » (reserve a une correspondance avec une DAT)
    $L = @()
    switch ($ipf.Kind) {
        'sps' {
            $t = (T 'IPF de structure SPS : publication n° {0}, révision {1}') -f $ipf.FileKey, $ipf.FileRev
            if ($ipf.DiskNumber -gt 0) { $t += ((T ', disquette {0}') -f $ipf.DiskNumber) }
            $L += $t
        }
        'user'  { $L += (T 'IPF utilisateur (disk-analyse) : copie personnelle, pas une publication SPS') }
        'crc'   { $L += (T 'IPF : bloc INFO au CRC faux (fichier altéré ou incomplet)') }
        'other' { $L += ((T 'IPF : encodeur inconnu ({0})') -f $ipf.Encoder) }
        default { $L += (T 'IPF : bloc INFO absent ou illisible') }
    }
    if ($ipf.Kind -eq 'sps' -or $ipf.Kind -eq 'user') {
        $p = @()
        $pl = @($ipf.Platforms | ForEach-Object { Get-LibPlatformName $_ }) -join ', '
        if ($pl) { $p += ((T 'Plate-forme : {0}') -f $pl) }
        $d = Format-LibIpfDate $ipf.Date
        if ($d) { $p += ((T 'créé le {0}') -f $d) }
        if ($p.Count -gt 0) { $L += ($p -join ' · ') }
    }
    return $L
}

function Get-LibAdfLines($a) {
    $L = @()
    if ($a.Dos) {
        $fs = $a.Fs; if ($a.Intl) { $fs += ' INTL' }; if ($a.DirCache) { $fs += ' DIRCACHE' }
        $t = (T 'ADF : AmigaDOS {0} (DOS{1})') -f $fs, $a.Flags
        if ($a.RootOk -and $a.Volume) { $t += ((T ', volume « {0} »') -f $a.Volume) }
        elseif (-not $a.RootOk) { $t += (T ', sans bloc racine lisible (chargeur propre)') }
        if ($a.Bootable) { $t += (T ', amorçable') }
        $L += $t
    } elseif ($a.BootRead) {
        $t = T 'ADF : bloc de démarrage non-DOS (chargeur propre, souvent protégé)'
        if ($a.RootOk -and $a.Volume) { $t += ((T ', volume « {0} »') -f $a.Volume) }
        $L += $t
    } else { $L += (T 'ADF : lecture impossible') }
    if ($a.Hd) { $L += (T 'ADF haute densité (bloc racine 1760)') }
    return $L
}

function Get-LibFlagLine($i) {
    # Mentions TOSEC du nom, expliquees
    if (-not $i.FlagText) { return '' }
    $d = @()
    foreach ($f in @($i.Flags | Select-Object -Unique)) {
        $x = switch ($f) {
            'cr' { T 'déplombée' } 'f' { T 'corrigée' } 'h' { T 'modifiée (hack)' } 'm' { T 'modifiée' } 'p' { T 'pirate' }
            't' { T 'entraîneur (trainer)' } 'tr' { T 'traduite' } 'o' { T 'image trop longue (overdump)' }
            'u' { T 'image incomplète (underdump)' } 'v' { T 'virus' } 'b' { T 'image défectueuse (bad dump)' }
            'a' { T 'variante (alternate)' } '!' { T 'image vérifiée' } default { $f }
        }
        $d += $x
    }
    return ((T 'Mentions : {0} ({1})') -f $i.FlagText, ($d -join ', '))
}

function Get-LibNameLines($r) {
    # Ce que dit le nom : variante, disquette, version, langue, mentions
    $i = $r.Info; $L = @()
    if (-not $i) { return $L }
    if ($i.Variant) { $L += ((T 'Variante : {0}') -f $i.Variant) }
    $p = @()
    if ($i.Disk) {
        $d = if ($i.DiskTot -gt 0) { (T 'Disquette {0} sur {1}') -f $i.Disk, $i.DiskTot } else { (T 'Disquette {0}') -f $i.Disk }
        if ($i.Label) { $d += " ($($i.Label))" }
        $p += $d
    }
    if ($i.Version) { $p += ((T 'Version {0}') -f $i.Version) }
    if ($i.Langs) { $p += ((T 'Langue : {0}') -f $i.Langs) }
    if ($p.Count -gt 0) { $L += ($p -join ' · ') }
    $f = Get-LibFlagLine $i
    if ($f) { $L += $f }
    return $L
}

function Get-LibContentLines($r) {
    # Ce que dit le fichier : IPF (bloc INFO) ou ADF (type DOS, volume) ; la ligne de la liste suit
    $L = @()
    try {
        if ($r.Ext -eq '.ipf') { $L += Get-LibIpfLines (Get-LibIpf $r); Update-LibRowState $r }
        elseif ($r.Ext -eq '.adf') { $L += Get-LibAdfLines (Get-LibAdf $r) }
    } catch { $L += ((T 'Lecture impossible : {0}') -f "$($_.Exception.Message)") }
    # 12.8 (lot 4b) : identification par la liste de reference ; CRC-32 d un fichier : calcul en tete du travail differe,
    # ligne remplacee a la fin (Update-LibDatDetails)
    if ((Test-LibDatOn) -and (Test-LibDatEligible $r)) {
        try {
            $s = Resolve-LibDatState $r
            if ($s -and $s.State -eq 'wait') { Request-LibDatWork $r }
            Update-LibRowState $r
        } catch { }
        $d = @(Get-LibDatLines $r)
        if ($d.Count -gt 0) { $L += $d; if ($r.Kind -eq 'image') { $script:LibDatLine = $d -join "`r`n" } }
    }
    return $L
}

function Test-LibPicture([string]$path) { return (@('.jpg', '.jpeg', '.png', '.gif') -contains [System.IO.Path]::GetExtension($path).ToLowerInvariant()) }

function Get-LibRelatedDocs($r) {
    # Documents associes (A3 § 4.2 n° 6) : documents (DocExt) du dossier au titre court du jeu, ou tous ceux du dossier
    # quand c est celui du jeu (dossier de publication SPS, ou dossier au titre du jeu) ; medias selon la convention Pegasus
    # (media\<titre ou nom>\*.png|jpg, a cote de l image ou a la racine). 60 au plus
    $out = [System.Collections.Generic.List[object]]::new()
    if (-not $r -or -not $r.Info) { return ,$out }
    $path = if ($r.Kind -eq 'zipentry') { $r.ZipPath } else { $r.Path }
    if (-not $path) { return ,$out }
    $key = $r.Info.Key
    $seen = @{}
    try {
        $dir = [System.IO.Path]::GetDirectoryName($path)
        $dirName = [System.IO.Path]::GetFileName($dir)
        $gameDir = ($r.Info.Source -eq 'dir') -or ((Get-LibNameInfo $dirName '').Key -eq $key)
        $pat = if ($gameDir) { '*' } elseif ($r.Info.Prefix) { $r.Info.Prefix + '*' } else { '' }
        if ($pat) {
            foreach ($f in [System.IO.Directory]::EnumerateFiles($dir, $pat)) {
                if ($out.Count -ge 60) { break }
                if ($script:DocExt -notcontains [System.IO.Path]::GetExtension($f).ToLowerInvariant()) { continue }
                $nm = [System.IO.Path]::GetFileName($f)
                if (-not $gameDir -and (Get-LibNameInfo $nm $dirName).Key -ne $key) { continue }
                $seen[$f.ToLowerInvariant()] = $true
                $out.Add(@{ Kind = 'doc'; Path = $f; Name = $nm })
            }
        }
        $roots = @($dir)
        if ($script:LibRoot -and $script:LibRoot -ne $dir) { $roots += $script:LibRoot }
        foreach ($mr in $roots) {
            foreach ($nm in @($r.Info.Title, $r.Info.Base | Select-Object -Unique)) {
                if (-not $nm) { continue }
                $md = [System.IO.Path]::Combine($mr, 'media', $nm)
                if (-not [System.IO.Directory]::Exists($md)) { continue }
                foreach ($f in [System.IO.Directory]::EnumerateFiles($md)) {
                    if ($out.Count -ge 60) { break }
                    if (-not (Test-LibPicture $f) -or $seen.ContainsKey($f.ToLowerInvariant())) { continue }
                    $seen[$f.ToLowerInvariant()] = $true
                    $out.Add(@{ Kind = 'doc'; Path = $f; Name = ('media\' + $nm + '\' + [System.IO.Path]::GetFileName($f)); Media = $true })
                }
            }
        }
    } catch { }
    return ,$out
}

function Select-LibThumb($docs) {
    # Vignette : boxFront des medias, sinon une image dont le nom evoque la boite, sinon la premiere image
    $pics = @($docs | Where-Object { Test-LibPicture $_.Path })
    foreach ($d in $pics) { if ([System.IO.Path]::GetFileNameWithoutExtension($d.Path) -ieq 'boxFront') { return $d.Path } }
    foreach ($d in $pics) { if ([System.IO.Path]::GetFileName($d.Path) -match '(?i)box|cover|front|jaquette') { return $d.Path } }
    if ($pics.Count -gt 0) { return $pics[0].Path }
    return ''
}

function Set-LibThumb([string]$path) {
    # Vignette chargee par un flux en memoire (le fichier n est jamais verrouille), reduite au cadre ; ancienne liberee
    $old = $picLibThumb.Image; $picLibThumb.Image = $null
    if ($old) { $old.Dispose() }
    $ok = $false
    if ($path) {
        try {
            $fi = New-Object System.IO.FileInfo($path)
            if ($fi.Exists -and $fi.Length -le 16MB) {
                $bytes = [System.IO.File]::ReadAllBytes($path)
                $ms = New-Object System.IO.MemoryStream(,$bytes)
                try {
                    $img = [System.Drawing.Image]::FromStream($ms)
                    try {
                        # Image de 72 x 72 px, affichee reduite si la page est basse (SizeMode Zoom, Update-LibPanelLayout)
                        $w = 72; $h = 72
                        $sc = [math]::Min([math]::Min($w / $img.Width, $h / $img.Height), 1.0)
                        $tw = [math]::Max(1, [int]($img.Width * $sc)); $th = [math]::Max(1, [int]($img.Height * $sc))
                        $bmp = New-Object System.Drawing.Bitmap($w, $h)
                        $g = [System.Drawing.Graphics]::FromImage($bmp)
                        try {
                            $g.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
                            $g.DrawImage($img, [int](($w - $tw) / 2), [int](($h - $th) / 2), $tw, $th)
                        } finally { $g.Dispose() }
                        $picLibThumb.Image = $bmp; $ok = $true
                    } finally { $img.Dispose() }
                } finally { $ms.Dispose() }
            }
        } catch { }
    }
    $script:LibThumbPath = if ($ok) { $path } else { '' }
    # Texte d information a cote de la vignette, ou sur toute la largeur sans vignette
    Update-LibPanelLayout
}

function Update-LibPanelLayout {
    # FIX4B (revue du lot 4, constat 2) : colonne de droite ajustee a la hauteur de la page (environ 300 px a la taille par
    # defaut avec le journal, et non 340). Entre le titre et les boutons : liste du bas (documents, entrees d archive) en
    # bas, 2 lignes (3 si la place le permet), masquee quand elle est vide ; texte au-dessus ; vignette a gauche du texte,
    # carree, de la hauteur du texte (72 px au plus), masquee sous 40 px : jamais sur la liste du bas. Appelee a chaque
    # affichage du panneau (Set-LibThumb) et au redimensionnement de la page (apres l ancrage des boutons)
    $x = $lblLibTitle.Left; $w = $lblLibTitle.Width
    $top = $lblLibTitle.Bottom + 1
    $bot = $btnLibFast.Top - 3
    $docs = ($lstLibDocs.Items.Count -gt 0)
    if ($docs) {
        $dh = $(if ($bot - $top -ge 170) { 3 } else { 2 }) * $lstLibDocs.ItemHeight + 4
        $lstLibDocs.SetBounds($x, $bot - $dh, $w, $dh)
        $bot -= $dh + 2
    }
    # Visible affecte sans le relire : la lecture rend faux tant que l onglet est cache (etat propre du controle ignore)
    $lstLibDocs.Visible = $docs
    $ih = [int][math]::Max(20, $bot - $top)
    $th = 0
    if ($picLibThumb.Image) { $th = [int][math]::Min(72, $ih); if ($th -lt 40) { $th = 0 } }
    $tx = $x
    if ($th -gt 0) { $picLibThumb.SetBounds($x, $top, $th, $th); $tx = $x + $th + 6 }
    $picLibThumb.Visible = ($th -gt 0)
    $txtLibInfo.SetBounds($tx, $top, $x + $w - $tx, $ih)
}

function Clear-LibDetails {
    $script:LibCur = $null; $script:LibSub = $null; $script:LibSubRecs = @(); $script:LibInfoBase = ''; $script:LibDatLine = ''
    $was = $script:LibRendering; $script:LibRendering = $true
    try { $lstLibDocs.Items.Clear() } finally { $script:LibRendering = $was }
    $lblLibTitle.Text = ''; $txtLibInfo.Clear()
    Set-LibThumb ''
    Set-LibWriteEnabled $false
    $btnLibOpen.Enabled = $false
}

function Show-LibDetails($r) {
    # Panneau de details (A3 § 4.1, § 4.2 n° 4 a 6) : titre ; ce que disent le nom et le fichier (IPF : bloc INFO ; ADF :
    # type DOS et volume) ; disquettes manquantes du jeu ; taille et chemin ; documents associes et vignette. Archive ZIP :
    # ses entrees dans la liste du bas, la premiere image choisie pour l ecriture
    Clear-LibDetails
    if (-not $r) { return }
    if (Test-LibDatEligible $r) { [void](Get-LibDat) }      # 12.8 (lot 4b) : liste lue a la premiere demande
    $script:LibCur = $r
    $L = [System.Collections.Generic.List[string]]::new()
    $title = ''; $docs = $null; $thumb = ''; $subs = @(); $selSub = -1
    switch ($r.Kind) {
        'dir' { $title = [System.IO.Path]::GetFileName($r.Path.TrimEnd('\')); $L.Add((T 'Dossier')); $L.Add($r.Path) }
        'zip' {
            $title = $r.Info.Title
            foreach ($x in (Get-LibNameLines $r)) { $L.Add($x) }
            $ents = @(Get-ZipEntries $r.Path)
            $nImg = @($ents | Where-Object { $_.Kind -eq 'image' }).Count
            $L.Add(((T 'Archive ZIP, {0} : {1} entrée(s), dont {2} image(s)') -f (Format-Size $r.Size), $ents.Count, $nImg))
            # 12.8 (lot 4b) : identification par la liste de reference (repertoire central de l archive)
            $zs = $null
            if (Test-LibDatOn) {
                try { $zs = Resolve-LibDatState $r; Update-LibRowState $r } catch { }
                foreach ($x in (Get-LibDatLines $r)) { $L.Add($x) }
            }
            $m = Get-LibSetMissing $r
            if ($m -and $m.Missing.Count -gt 0) { $L.Add(((T 'Jeu incomplet : {0}') -f (Get-LibMissingText $m))) }
            foreach ($e in $ents) {
                $ew = ''
                if ($zs -and $zs.Zip -and $null -ne $e.Index -and $e.Index -lt $zs.Zip.Entries.Count -and $zs.Zip.Entries[$e.Index] -and $zs.Zip.Dir[$e.Index].Size -eq [long]$e.Length) {
                    $ew = Get-LibDatWord $zs.Zip.Entries[$e.Index].State
                }
                $et = if ($ew) { (T '{0}  (dans l''archive, {1}) : {2}') -f $e.FullName, (Format-Size $e.Length), $ew } else { (T '{0}  (dans l''archive, {1})') -f $e.FullName, (Format-Size $e.Length) }
                $subs += ,@{ Kind = 'zipentry'; ZipPath = $r.Path; Entry = $e.FullName; Size = [long]$e.Length; FileKind = $e.Kind; Idx = $e.Index; Text = $et }
                if ($selSub -lt 0 -and $e.Kind -eq 'image') { $selSub = $subs.Count - 1 }
            }
            $L.Add($r.Path)
            $docs = Get-LibRelatedDocs $r
        }
        'zipentry' {
            $title = $r.Info.Title
            foreach ($x in (Get-LibNameLines $r)) { $L.Add($x) }
            foreach ($x in (Get-LibContentLines $r)) { $L.Add($x) }
            $L.Add(((T "Dans l'archive : {0}") -f [System.IO.Path]::GetFileName($r.ZipPath)))
            $L.Add("$($r.Fmt), $(Format-Size $r.Size)")
            $docs = Get-LibRelatedDocs $r
        }
        'image' {
            $title = $r.Info.Title
            foreach ($x in (Get-LibNameLines $r)) { $L.Add($x) }
            foreach ($x in (Get-LibContentLines $r)) { $L.Add($x) }
            $m = Get-LibSetMissing $r
            if ($m -and $m.Missing.Count -gt 0) { $L.Add(((T 'Jeu incomplet : {0}') -f (Get-LibMissingText $m))) }
            $L.Add("$($r.Fmt), $(Format-Size $r.Size)")
            $L.Add($r.Path)
            $docs = Get-LibRelatedDocs $r
        }
        'doc' {
            $title = $r.Info.Title
            $L.Add(((T "Document ({0}), {1}") -f [System.IO.Path]::GetExtension($r.Path), (Format-Size $r.Size)))
            $L.Add($r.Path)
            if (Test-LibPicture $r.Path) { $thumb = $r.Path }
        }
        'missing' {
            $title = $r.Info.Title
            if ($r.Info.SetVariant) { $L.Add(((T 'Variante : {0}') -f $r.Info.SetVariant)) }
            $L.Add(((T 'Jeu incomplet : {0}') -f (Get-LibMissingText $r.Missing)))
            $L.Add([System.IO.Path]::GetDirectoryName($r.Path))
        }
        default {
            $title = $r.Name
            $L.Add((T 'Fichier non pris en charge'))
            if ($r.Path) { $L.Add($r.Path) }
        }
    }
    if ($docs) {
        foreach ($d in $docs) { $subs += ,@{ Kind = 'doc'; Path = $d.Path; Name = $d.Name; Text = $d.Name } }
        if (-not $thumb) { $thumb = Select-LibThumb $docs }
    }
    $script:LibSubRecs = $subs
    $script:LibRendering = $true
    try { foreach ($s in $subs) { [void]$lstLibDocs.Items.Add($s.Text) } } finally { $script:LibRendering = $false }
    $lblLibTitle.Text = $title
    $script:LibInfoBase = $L -join "`r`n"
    $txtLibInfo.Text = $script:LibInfoBase
    Set-LibThumb $thumb
    Set-LibWriteEnabled ($r.Kind -eq 'image' -or ($r.Kind -eq 'zipentry' -and $r.FileKind -eq 'image'))
    $btnLibOpen.Enabled = ($r.Kind -eq 'doc' -or ($r.Kind -eq 'zipentry' -and $r.FileKind -eq 'doc'))
    if ($selSub -ge 0) { $lstLibDocs.SelectedIndex = $selSub }
}

function Show-LibSubSelection {
    # Element choisi dans la liste du bas : entree d archive (son analyse s ajoute au panneau ; image : cible de l ecriture)
    # ou document (Ouvrir ; image affichee dans la vignette)
    if ($script:LibRendering) { return }
    $i = $lstLibDocs.SelectedIndex
    $s = if ($i -ge 0 -and $i -lt $script:LibSubRecs.Count) { $script:LibSubRecs[$i] } else { $null }
    $script:LibSub = $s
    $cur = $script:LibCur
    $txt = $script:LibInfoBase
    if ($s -and $s.Kind -eq 'zipentry' -and $s.FileKind -eq 'image') {
        $er = Get-LibEntryRecord $s
        $lines = @(Get-LibNameLines $er) + @(Get-LibContentLines $er)
        $txt += "`r`n`r`n" + ((T 'Entrée choisie : {0}') -f $s.Entry)
        if ($lines.Count -gt 0) { $txt += "`r`n" + ($lines -join "`r`n") }
    }
    $txtLibInfo.Text = $txt
    if ($cur -and $cur.Kind -eq 'zip') { Set-LibWriteEnabled ([bool]($s -and $s.Kind -eq 'zipentry' -and $s.FileKind -eq 'image')) }
    $btnLibOpen.Enabled = [bool](Get-LibOpenTarget)
    if ($s -and $s.Kind -eq 'doc' -and (Test-LibPicture $s.Path)) { Set-LibThumb $s.Path }
}

function Get-LibOpenTarget {
    # Document a ouvrir : celui choisi dans la liste du bas, sinon l element selectionne s il est un document
    $s = $script:LibSub
    if ($s -and ($s.Kind -eq 'doc' -or ($s.Kind -eq 'zipentry' -and $s.FileKind -eq 'doc'))) { return $s }
    $c = $script:LibCur
    if ($c -and ($c.Kind -eq 'doc' -or ($c.Kind -eq 'zipentry' -and $c.FileKind -eq 'doc'))) { return $c }
    return $null
}

function Open-LibDoc {
    # Ouvre le document avec l application par defaut (entree d archive extraite dans TempDir)
    $t = Get-LibOpenTarget
    if (-not $t) { return }
    $p = $t.Path
    if ($t.Kind -eq 'zipentry') {
        try { $p = Expand-ZipEntry $t.ZipPath $t.Entry; Append-Log ((T "Extrait : {0} -> {1}") -f "$($t.Entry)", "$p") }
        catch { Append-Log ((T "Extraction impossible : {0}") -f "$($_.Exception.Message)"); return }
    }
    try { Start-Process -FilePath $p } catch { Append-Log ((T "Ouverture impossible : {0}") -f "$($_.Exception.Message)") }
}

function Clear-LibGdi {
    # Fermeture de la fenetre : vignette et badges de la liste
    if ($picLibThumb -and $picLibThumb.Image) { $b = $picLibThumb.Image; $picLibThumb.Image = $null; $b.Dispose() }
    if ($imgLibBadge) { try { $imgLibBadge.Dispose() } catch { } }
}

# ============================== BIBLIOTHEQUE : LISTE DE REFERENCE (12.8, LOT 4B) ==
# D19 (A3 § 3.4 B) : liste (DAT) choisie par l utilisateur (bouton « Liste de reference... »), chemin enregistre (reglage
# libDat), lue a la premiere ouverture de l onglet ou a la premiere recherche ; jamais fournie ni telechargee. Images et
# archives ZIP identifiees : liste des resultats par le travail differe du minuteur (CRC-32 d un fichier par la
# bibliotheque ZIP de .NET ; CRC d une entree d archive lu dans son repertoire central), panneau de details a la selection (element mis en tete du travail differe). « Officiel » n apparait qu avec une liste.

function Test-LibDatOn { return [bool]($script:LibDat -and $script:LibDat.Ok) }

function Test-LibDatEligible($r) {
    # Elements identifies : images, archives ZIP et entrees image d une archive (ni documents ni dossiers)
    return [bool]($r -and ($r.Kind -eq 'image' -or $r.Kind -eq 'zip' -or ($r.Kind -eq 'zipentry' -and $r.FileKind -eq 'image')))
}

function Get-LibDatWord([string]$state) {
    switch ($state) { 'ok' { return (T 'officiel') } 'mod' { return (T 'modifié') } 'unk' { return (T 'inconnu') } }
    return '…'
}

function Format-LibDatEntry($e) {
    if (-not $e) { return '' }
    if ($e.Game) { return ((T '« {0} » du jeu « {1} »') -f $e.Name, $e.Game) }
    return ((T '« {0} »') -f $e.Name)
}

function Get-LibDat {
    # Liste chargee (Ok), lue a la premiere demande si un chemin est enregistre ; une seule lecture par chemin (une liste
    # illisible n est relue qu apres un nouveau choix) ; $null sans liste utilisable
    $p = [string](Get-Setting 'libDat')
    if (-not $p) { return $null }
    if (-not $script:LibDat -or $script:LibDat.Path -ne $p) { Import-LibDatNow }
    if (Test-LibDatOn) { return $script:LibDat }
    return $null
}

function Import-LibDatNow {
    # Lecture de la liste enregistree (curseur d attente), ligne de journal, etat a cote du bouton ; etats remis a zero
    $p = [string](Get-Setting 'libDat')
    $script:LibDatState = @{}; $script:LibDatZip = @{}
    if (-not $p) { $script:LibDat = $null; Update-LibDatLabel; return }
    $was = $form.Cursor; $form.Cursor = [System.Windows.Forms.Cursors]::WaitCursor
    try { $d = Read-LibDat $p } finally { $form.Cursor = $was }
    $script:LibDat = $d
    if ($d.Ok) {
        Append-Log ((T 'Liste de référence : {0} ({1}), {2} entrée(s), {3} fichier(s), lue en {4} s.') -f $d.Name, (Get-LibDatFormatText $d), "$('{0:N0}' -f $d.Games)", "$('{0:N0}' -f $d.Roms)", (Format-UiNum ($d.Ms / 1000.0) '0.0'))
    } else {
        Append-Log ((T 'Liste de référence illisible ({0}) : {1}') -f [System.IO.Path]::GetFileName($p), $d.Error)
    }
    Update-LibDatLabel
}

function Get-LibDatFormatText($d) {
    if ($d.Version) { return ((T '{0}, version {1}') -f $d.Format, $d.Version) }
    return [string]$d.Format
}

function Update-LibDatLabel {
    # Etat de la liste a cote du bouton : aucune ; nom du fichier (lue a l ouverture de l onglet) ; « nom, N entree(s) » ;
    # illisible (message dans l infobulle). Bouton de retrait visible avec une liste
    $p = [string](Get-Setting 'libDat')
    $d = $script:LibDat
    $btnLibDatClear.Visible = [bool]$p
    if (-not $p) {
        $lblLibDat.Text = (T 'aucune'); $lblLibDat.ForeColor = $script:Theme.Muted
        $tip.SetToolTip($lblLibDat, (T 'Aucune liste de référence : les fichiers ne sont pas identifiés.'))
        return
    }
    if (-not $d -or $d.Path -ne $p) {
        $lblLibDat.Text = [System.IO.Path]::GetFileName($p); $lblLibDat.ForeColor = $script:Theme.Muted
        $tip.SetToolTip($lblLibDat, ((T "{0}`nLue à l'ouverture de l'onglet Bibliothèque.") -f $p))
        return
    }
    if (-not $d.Ok) {
        $lblLibDat.Text = (T 'liste illisible'); $lblLibDat.ForeColor = (Get-QualInk 3)
        $tip.SetToolTip($lblLibDat, "$p`n$($d.Error)")
        return
    }
    $lblLibDat.Text = (T '{0}, {1} entrée(s)') -f $d.Name, "$('{0:N0}' -f $d.Games)"
    $lblLibDat.ForeColor = [System.Drawing.SystemColors]::ControlText
    $t = (T 'Liste de référence : {0}') -f $d.Name
    if ($d.Description -and $d.Description -ne $d.Name) { $t += "`n" + $d.Description }
    $t += "`n" + ((T '{0} entrée(s), {1} fichier(s) identifiable(s) ({2})') -f "$('{0:N0}' -f $d.Games)", "$('{0:N0}' -f $d.Roms)", (Get-LibDatFormatText $d))
    $t += "`n" + $p
    $tip.SetToolTip($lblLibDat, $t)
}

function Reset-LibDat {
    # Reglage libDat change (choix, retrait, configuration lue, valeurs par defaut) : liste dechargee, relue a la prochaine
    # demande ; etats d identification et travail differe d identification abandonnes
    $script:LibDat = $null; $script:LibDatState = @{}; $script:LibDatZip = @{}
    Update-LibDatLabel
}

function Select-LibDatFile {
    # Bouton « Liste de reference... » : fichier .dat ou .xml choisi par l utilisateur sur son ordinateur
    $d = New-Object System.Windows.Forms.OpenFileDialog
    try {
        $d.Title = (T 'Liste de référence (DAT)')
        $d.Filter = (T 'Listes de référence (*.dat;*.xml)|*.dat;*.xml|Tous les fichiers (*.*)|*.*')
        $cur = [string](Get-Setting 'libDat')
        if ($cur) { try { $d.InitialDirectory = [System.IO.Path]::GetDirectoryName($cur); $d.FileName = [System.IO.Path]::GetFileName($cur) } catch { } }
        if ($d.ShowDialog() -ne [System.Windows.Forms.DialogResult]::OK) { return }
        Set-LibDatPath $d.FileName
    } finally { $d.Dispose() }
}

function Set-LibDatPath([string]$path) {
    # Liste choisie (lue tout de suite) ou retiree (chemin vide) ; liste des resultats et panneau refaits
    Stop-LibWork
    Set-Setting 'libDat' $path
    if ($path) { Import-LibDatNow } else { Append-Log (T 'Liste de référence retirée.') }
    if ($script:LibListMode -and $null -ne $script:LibAll) { Show-LibResults -Keep }
    elseif ($script:LibCur) { Show-LibDetails $script:LibCur }
}

function Get-LibDatQuick($r) {
    # Etat d identification sans lecture de fichier : en cache, ou decide par la taille et le nom (aucune entree de cette
    # taille) ; @{ State = 'wait' } s il faut lire le fichier ; $null sans liste ou pour un element non identifie
    if (-not (Test-LibDatOn) -or -not (Test-LibDatEligible $r)) { return $null }
    $k = Get-LibIpfKey $r
    $s = $script:LibDatState[$k]
    if ($s) { return $s }
    if ($r.Kind -ne 'zip' -and -not $script:LibDat.BySize.ContainsKey([long]$r.Size)) {
        $s = Get-LibDatMatch $script:LibDat ([long]$r.Size) $r.Name @{}
        $script:LibDatState[$k] = $s
        return $s
    }
    return @{ State = 'wait' }
}

function Get-LibHashStore {
    # Empreintes gardees pour la racine de la Bibliotheque (hash-<md5>.tsv), lues une fois par racine
    $f = Get-LibHashFile ([string]$txtLibRoot.Text)
    if ($script:LibHashFileCur -ne $f -or $null -eq $script:LibHashCache) { $script:LibHashCache = Import-LibHashCache $f; $script:LibHashFileCur = $f }
    return $script:LibHashCache
}

function Get-LibHashCached([string]$path, [long]$size, [long]$ticks) {
    $o = $null
    if ((Get-LibHashStore).TryGetValue((Get-LibHashKey $path $size $ticks), [ref]$o)) { return @{ Crc = $o.Crc; Md5 = $o.Md5; Sha1 = $o.Sha1 } }
    return @{ Crc = ''; Md5 = ''; Sha1 = '' }
}

function Save-LibHash([string]$path, [long]$size, [long]$ticks, $h) {
    $c = Get-LibHashStore
    $c[(Get-LibHashKey $path $size $ticks)] = @{ Crc = $h.Crc; Md5 = $h.Md5; Sha1 = $h.Sha1 }
    Add-LibHashLine $script:LibHashFileCur $path $size $ticks $h
}

function Get-LibZipDat([string]$zipPath) {
    # Archive ZIP identifiee, en cache par chemin, taille et date : repertoire central, etat de chaque entree image et de
    # l archive. Entree dont la liste n a pas de CRC-32 : SHA-1 ou MD5 calcules sur le flux decompresse. $null si illisible
    $fi = New-Object System.IO.FileInfo($zipPath)
    if (-not $fi.Exists) { return $null }
    $ck = "$zipPath|$($fi.Length)|$($fi.LastWriteTimeUtc.Ticks)"
    if ($script:LibDatZip.ContainsKey($ck)) { return $script:LibDatZip[$ck] }
    $z = $null
    $ents = Read-LibZipDir $zipPath
    # FIX4B (C1) : liste, meme d une seule entree ; archive sans entree : inconnu, et non illisible
    if ($null -ne $ents) {
        $z = Get-LibZipDatState $script:LibDat $ents
        if ($z.State -eq 'wait') {
            $zip = [System.IO.Compression.ZipFile]::OpenRead($zipPath)
            try {
                for ($i = 0; $i -lt $ents.Count; $i++) {
                    $s = $z.Entries[$i]
                    if (-not $s -or $s.State -ne 'wait') { continue }
                    $h = @{ Crc = $ents[$i].Crc; Md5 = ''; Sha1 = '' }; $n = 0
                    while ($s.State -eq 'wait' -and $s.Need -ne 'Crc' -and $n -lt 3 -and $i -lt $zip.Entries.Count) {
                        $st = $zip.Entries[$i].Open()
                        try { $h[$s.Need] = Get-LibHashText $s.Need $st } finally { $st.Dispose() }
                        $s = Get-LibDatMatch $script:LibDat ([long]$ents[$i].Size) $ents[$i].Name $h -Common; $n++
                    }
                    if ($s.State -eq 'wait') { $s = @{ State = 'unk' } }
                    $z.Entries[$i] = $s
                }
            } finally { $zip.Dispose() }
            $z = Measure-LibZipDatState $z.Entries
        }
        $z.Dir = $ents
        $z.Ticks = $fi.LastWriteTimeUtc.Ticks; $z.Len = $fi.Length     # FIX4B (C4) : etat revalide si l archive change
    }
    $script:LibDatZip[$ck] = $z
    return $z
}

function Get-LibZipEntryState($z, $r) {
    # Etat d une entree d archive : rang dans l archive (controle par la taille), sinon nom et taille
    if (-not $z) { return @{ State = 'unk'; Err = (T 'archive illisible') } }
    $i = -1
    if ($null -ne $r.Idx -and $r.Idx -ge 0 -and $r.Idx -lt $z.Dir.Count -and $z.Dir[$r.Idx].Size -eq [long]$r.Size) { $i = [int]$r.Idx }
    else { for ($j = 0; $j -lt $z.Dir.Count; $j++) { if ($z.Dir[$j].Name -ceq [string]$r.Entry -and $z.Dir[$j].Size -eq [long]$r.Size) { $i = $j; break } } }
    if ($i -lt 0 -or -not $z.Entries[$i]) {
        $s = Get-LibDatMatch $script:LibDat ([long]$r.Size) $r.Name @{}
        if ($s.State -eq 'wait') { $s = @{ State = 'unk' } }
        $s.Ticks = $z.Ticks; $s.Len = $z.Len
        return $s
    }
    $e = $z.Entries[$i]
    return @{ State = $e.State; Entry = $e.Entry; Hash = @{ Crc = $z.Dir[$i].Crc; Md5 = ''; Sha1 = '' }; Ticks = $z.Ticks; Len = $z.Len }
}

function Test-LibDatFresh($r, $s) {
    # FIX4B (revue du lot 4, C4) : etat identifie par lecture du fichier (ou de son archive) encore valable si la taille et
    # la date de modification n ont pas change. Etat sans date (decide par la taille seule, ou en erreur) : valable
    if (-not $s -or $null -eq $s.Ticks) { return $true }
    try {
        $p = if ($r.Kind -eq 'zipentry') { [string]$r.ZipPath } else { [string]$r.Path }
        $fi = New-Object System.IO.FileInfo($p)
        return [bool]($fi.Exists -and $fi.Length -eq [long]$s.Len -and $fi.LastWriteTimeUtc.Ticks -eq [long]$s.Ticks)
    } catch { return $false }
}

function Resolve-LibDatState($r) {
    # Identification avec lecture : archive ZIP (repertoire central), entree d archive, fichier (empreinte gardee, sinon
    # SHA-1 ou MD5 calcules ici). Etat garde par chemin et taille, avec la date lue (Ticks, Test-LibDatFresh) ;
    # @{ State = 'wait'; Need = 'Crc' }, non garde : CRC-32 du fichier a calculer dans le travail differe (Step-LibDatWork)
    $q = Get-LibDatQuick $r
    $k = Get-LibIpfKey $r
    # FIX4B (C4) : etat garde d un fichier modifie depuis (meme taille, autre date) : identification refaite ; « Originaux
    # seulement » : liste refaite a la fin du travail differe (Step-LibWork)
    if ($q -and $q.State -ne 'wait' -and -not (Test-LibDatFresh $r $q)) {
        [void]$script:LibDatState.Remove($k); $q = Get-LibDatQuick $r; $script:LibOrigPending = $true
    }
    if (-not $q -or $q.State -ne 'wait') { return $q }
    $dat = $script:LibDat
    $s = $null
    try {
        if ($r.Kind -eq 'zip') {
            $z = Get-LibZipDat $r.Path
            $s = if ($z) { @{ State = $z.State; Zip = $z; Ticks = $z.Ticks; Len = $z.Len } } else { @{ State = 'unk'; Err = (T 'archive illisible') } }
        } elseif ($r.Kind -eq 'zipentry') {
            $s = Get-LibZipEntryState (Get-LibZipDat $r.ZipPath) $r
        } else {
            $fi = New-Object System.IO.FileInfo($r.Path)
            if (-not $fi.Exists) { $s = @{ State = 'unk'; Err = (T 'fichier introuvable') } }
            else {
                $tk = $fi.LastWriteTimeUtc.Ticks
                $h = Get-LibHashCached $r.Path $fi.Length $tk
                $s = Get-LibDatMatch $dat $fi.Length $r.Name $h; $n = 0
                while ($s.State -eq 'wait' -and $s.Need -ne 'Crc' -and $n -lt 3) {
                    $fs = [System.IO.File]::Open($r.Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
                    try { $h[$s.Need] = Get-LibHashText $s.Need $fs } finally { $fs.Dispose() }
                    Save-LibHash $r.Path $fi.Length $tk $h
                    $s = Get-LibDatMatch $dat $fi.Length $r.Name $h; $n++
                }
                if ($s.State -eq 'wait') { return $s }
                $s.Hash = $h; $s.Ticks = $tk; $s.Len = $fi.Length
            }
        }
    } catch { $s = @{ State = 'unk'; Err = "$($_.Exception.Message)" } }
    $script:LibDatState[$k] = $s
    return $s
}

function Request-LibDatWork($r) {
    # Element du panneau dont le CRC-32 reste a calculer : en tete du travail differe
    $k = Get-LibIpfKey $r
    $items = $script:LibWork.ToArray()
    $script:LibWork.Clear()
    $script:LibWork.Enqueue(@{ T = 'dat'; Rec = $r })
    foreach ($w in $items) {
        if ($w.T -eq 'dat' -and (Get-LibIpfKey $w.Rec) -eq $k) { continue }
        $script:LibWork.Enqueue($w)
    }
    $script:LibWorkTotal = $script:LibWorkDone + $script:LibWork.Count
}

function Step-LibDatWork($w) {
    # Identification de $w.Rec : etat deja connu, archive, empreinte gardee, ou SHA-1/MD5 ; sinon CRC-32 du fichier
    # (32 Mo au plus), d un seul tenant, par la bibliotheque ZIP native de .NET (Get-LibFileCrc32, aucun calcul en
    # PowerShell). L etat est toujours connu au retour : l appelant retire l element de la file
    $r = $w.Rec
    if (-not (Test-LibDatOn)) { return }
    $k = Get-LibIpfKey $r
    $s = Resolve-LibDatState $r
    if (-not $s -or $s.State -ne 'wait') { Complete-LibDatItem $r; return }
    try {
        $fi = New-Object System.IO.FileInfo($r.Path)
        if ($fi.Length -gt 32MB) { throw (T 'fichier trop gros pour le calcul du CRC-32') }
        $tk = $fi.LastWriteTimeUtc.Ticks
        $h = Get-LibHashCached $r.Path $fi.Length $tk
        $h.Crc = Get-LibFileCrc32 $r.Path
        Save-LibHash $r.Path $fi.Length $tk $h
        $s = Get-LibDatMatch $script:LibDat $fi.Length $r.Name $h
        # FIX4B (C7) : CRC-32 egal a celui d une entree qui fournit aussi un SHA-1 ou un MD5 : cette empreinte est calculee
        # tout de suite (Resolve-LibDatState repart du CRC-32 garde) ; le CRC-32 seul ne suffit pas
        if ($s.State -eq 'wait' -and $s.Need -ne 'Crc') {
            $s2 = Resolve-LibDatState $r
            if ($s2 -and $s2.State -ne 'wait') { Complete-LibDatItem $r; return }
        }
        if ($s.State -eq 'wait') { $s = @{ State = 'unk' } }
        $s.Hash = $h; $s.Ticks = $tk; $s.Len = $fi.Length
    } catch { $s = @{ State = 'unk'; Err = "$($_.Exception.Message)" } }
    $script:LibDatState[$k] = $s
    Complete-LibDatItem $r
}

function Complete-LibDatItem($r) {
    # Etat connu : ligne de la liste et panneau de details mis a jour sur place
    Update-LibRowState $r
    Update-LibDatDetails $r
}

function Update-LibDatDetails($r) {
    # Fichier affiche dans le panneau identifie apres l affichage : ses lignes « Liste de reference » remplacees sur place
    $c = $script:LibCur
    if (-not $c -or $c.Kind -ne 'image' -or -not $script:LibDatLine -or (Get-LibIpfKey $c) -ne (Get-LibIpfKey $r)) { return }
    $new = @(Get-LibDatLines $c) -join "`r`n"
    $old = $script:LibDatLine
    if (-not $new -or $new -eq $old) { return }
    $script:LibInfoBase = $script:LibInfoBase.Replace($old, $new)
    $txtLibInfo.Text = $txtLibInfo.Text.Replace($old, $new)
    $script:LibDatLine = $new
}

function Get-LibDatLines($r) {
    # Lignes « Liste de reference » du panneau : etat et entree correspondante de la liste ; archive ZIP : nombre d images
    # officielles ; empreinte calculee ou lue dans l archive
    if (-not (Test-LibDatOn) -or -not (Test-LibDatEligible $r)) { return @() }
    $n = $script:LibDat.Name
    $s = Get-LibDatQuick $r
    $L = @()
    if ($s.Err) { $L += ((T 'Liste de référence ({0}) : non identifié ({1})') -f $n, $s.Err) }
    elseif ($s.Zip) { $L += ((T 'Liste de référence ({0}) : {1}, {2} image(s) officielle(s) sur {3}') -f $n, (Get-LibDatWord $s.State), $s.Zip.OkCount, $s.Zip.Total) }
    else {
        switch ($s.State) {
            'ok'    { $L += ((T 'Liste de référence ({0}) : officiel, {1}') -f $n, (Format-LibDatEntry $s.Entry)) }
            'mod'   { $L += ((T 'Liste de référence ({0}) : modifié, même nom que {1}, contenu différent') -f $n, (Format-LibDatEntry $s.Entry)) }
            'unk'   { $L += ((T 'Liste de référence ({0}) : inconnu, absent de la liste') -f $n) }
            default { $L += ((T 'Liste de référence ({0}) : identification en cours…') -f $n) }
        }
    }
    if ($s.Hash) {
        if ($s.Hash.Sha1) { $L += ((T 'Empreinte {0} : {1}') -f 'SHA-1', $s.Hash.Sha1) }
        elseif ($s.Hash.Md5) { $L += ((T 'Empreinte {0} : {1}') -f 'MD5', $s.Hash.Md5) }
        elseif ($s.Hash.Crc) { $L += ((T 'Empreinte {0} : {1}') -f 'CRC-32', $s.Hash.Crc) }
    }
    return $L
}
# ============================== FONCTIONS : BIBLIOTHEQUE, ANALYSE (12.8, LOT 4A) ==
# Analyse sans interface des fichiers de la Bibliotheque (A3 § 3 et § 4.2, D18) : noms TOSEC et No-Intro avec replis,
# bloc INFO des IPF (108 premiers octets, CRC-32 IEEE par la bibliotheque ZIP de .NET, A5 § 3.3), blocs de demarrage
# et racine des ADF, disquettes manquantes d un jeu, regle des mots de la recherche. Aucune liste embarquee, aucun
# telechargement : « IPF de structure SPS » se lit dans le fichier, « officiel » est reserve a une correspondance avec une
# DAT locale (lot 4b).

function Initialize-LibRx {
    # Expressions du decoupage des noms, creees une fois (sensibles a la casse sauf (?i))
    $script:LibRx = @{
        Tok       = [regex]'\(([^()]*)\)|\[([^\[\]]*)\]'
        NonAlnum  = [regex]'[^\p{L}\p{N}]+'
        Ver       = [regex]'(?i)\s+(v\d[\w.\-]*(?:\s+rev\s+[\w.\-]+)?|rev\s+[\w.\-]+|r\d+[a-z]?)$'
        Disk      = [regex]'(?i)^(?:dis[kc]|disque|disquette|side|face)\s*([0-9]{1,3}|[a-z])(?:\s*(?:of|sur|/)\s*(?:([0-9]{1,3})|[a-z?]))?(?:\s+side\s+([ab]))?$'
        DiskFb    = [regex]'(?i)(?:^|[\s_\-.,]+)(?:amiga)?(?:diskette|dis[kc]o?|disque|disquette)\s*[-_#]?\s*([0-9]{1,2}|one|two|three|four|five|six|seven|eight|nine|ten|viii|vii|vi|iv|ix|iii|ii|i|v|x|[a-h])(?:\s*(?:of|sur|de|von)\s*([0-9]{1,2}))?(?=$|[\s_\-.,])'
        DiskCamel = [regex]'(?<=[a-z0-9])(?:Amiga)?(?:Diskette|Dis[kc]o?)([0-9]{1,2}|One|Two|Three|Four|Five|Six|Seven|Eight|Nine|Ten|VIII|VII|VI|IV|IX|III|II|I|V|X|[A-H])(?:(?:of|von)([0-9]{1,2}))?$'
        DiskU     = [regex]'[_\-\s]+([0-9]{1,2})$'
        DiskWord  = @{ one = '1'; two = '2'; three = '3'; four = '4'; five = '5'; six = '6'; seven = '7'; eight = '8'; nine = '9'; ten = '10'
                      i = '1'; ii = '2'; iii = '3'; iv = '4'; v = '5'; vi = '6'; vii = '7'; viii = '8'; ix = '9'; x = '10' }
        DiskD     = [regex]'(?i)(?:^|[\s_\-.]+)d([0-9]{1,2})$'
        Date      = [regex]'^(1[89]|20)[0-9x]{2}(-[0-9x]{2}){0,2}$'
        LangT     = [regex]'^[a-z]{2}(-[a-z]{2})*$'
        LangM     = [regex]'^M\d{1,2}$'
        LangN     = [regex]'^[A-Z][a-z](,\s?[A-Z][a-z])*$'
        Country   = [regex]'^[A-Z]{2}(-[A-Z]{2})*$'
        Region    = [regex]'^(World|Europe|USA|Japan|Germany|France|Italy|Spain|UK|Australia|Asia|Korea|Brazil|Canada|Netherlands|Sweden|Scandinavia|Russia|China)(,\s*(World|Europe|USA|Japan|Germany|France|Italy|Spain|UK|Australia|Asia|Korea|Brazil|Canada|Netherlands|Sweden|Scandinavia|Russia|China))*$'
        VerTok    = [regex]'(?i)^(v\d[\w.\-]*|rev\s*[\w.\-]+)$'
        Copy      = [regex]'^(CW|CW-R|FW|GW|GW-R|LW|PD|SW|SW-R)$'
        Flag      = [regex]'^(cr|tr|f|h|m|p|t|o|u|v|b|a)(\d*)(?:\s+(.*))?$'
        SpsNo     = [regex]'^\d{4}$'
        Article   = [regex]'(?i)^(.*?),\s*(the|a|an|le|la|les|l''|der|die|das|el|il)$'
        Trim      = [regex]'[\s\-_,.]+$'
        # FIX4B (revue du lot 4, C2) : crochets d information gardes dans la cle de jeu (machine, densite, video : communs a
        # tout le jeu) ; les autres ([bootable], [WB], [docs], [KS2.0]...) sont propres a une disquette
        SetTag    = [regex]'(?i)^(AGA|ECS|OCS|HD|CD32|CDTV|NTSC|PAL)$'
    }
    # Langue par defaut d un pays (TOSEC : la langue n est indiquee que si elle differe de celle du pays) ou d une region
    $script:LibCountryLang = @{
        AU = 'en'; BR = 'pt'; CA = 'en'; CN = 'zh'; DE = 'de'; DK = 'da'; ES = 'es'; FI = 'fi'; FR = 'fr'; GB = 'en'; GR = 'el'
        IT = 'it'; JP = 'ja'; KR = 'ko'; NL = 'nl'; NO = 'no'; PL = 'pl'; PT = 'pt'; RU = 'ru'; SE = 'sv'; US = 'en'
        USA = 'en'; UK = 'en'; Australia = 'en'; Germany = 'de'; France = 'fr'; Italy = 'it'; Spain = 'es'; Japan = 'ja'
        Netherlands = 'nl'; Sweden = 'sv'; Brazil = 'pt'; Korea = 'ko'; China = 'zh'; Russia = 'ru'; Canada = 'en'
    }
    return $script:LibRx
}

function Get-LibCompact([string]$s) {
    # Forme compacte d un texte, pour comparer titres et mots : minuscules, sans accents, sans ponctuation ni espaces
    if (-not $s) { return '' }
    $rx = $script:LibRx; if (-not $rx) { $rx = Initialize-LibRx }
    return $rx.NonAlnum.Replace($s.Normalize([System.Text.NormalizationForm]::FormD), '').ToLowerInvariant()
}

function Read-LibNameParts([string]$s, $rx) {
    # Decoupe TOSEC / No-Intro : titre (texte avant la premiere parenthese ou le premier crochet ; crochets de tete, comme
    # [BIOS] ou un numero de publication, ecartes), jetons dans l ordre (p : parentheses, b : crochets), texte restant
    $lead = $null; $rest = ''; $pos = 0
    $toks = [System.Collections.Generic.List[object]]::new()
    foreach ($m in $rx.Tok.Matches($s)) {
        $between = $s.Substring($pos, $m.Index - $pos)
        if ($null -eq $lead) {
            if ($between.Trim().Length -eq 0 -and $m.Groups[2].Success) {
                $toks.Add(@('b', $m.Groups[2].Value.Trim())); $pos = $m.Index + $m.Length; continue
            }
            $lead = $between
        } elseif ($between.Trim()) { $rest = ($rest + ' ' + $between.Trim()).Trim() }
        if ($m.Groups[1].Success) { $toks.Add(@('p', $m.Groups[1].Value.Trim())) } else { $toks.Add(@('b', $m.Groups[2].Value.Trim())) }
        $pos = $m.Index + $m.Length
    }
    $tail = $s.Substring($pos)
    if ($null -eq $lead) { $lead = $tail; $tail = '' }
    elseif ($tail.Trim()) { $rest = ($rest + ' ' + $tail.Trim()).Trim() }
    return @{ Lead = $lead.Trim(); Toks = $toks; Rest = $rest }
}

function Find-LibDiskInLead([string]$lead, $rx) {
    # Repli hors convention : numero de disquette en fin de nom (« Jeu - Disk1 », « jeu_d2 », « WizNLiz_Disk1 »,
    # « Jinks_Disk1of2 », « ChampionshipManager93_AmigaDisk1 »). Renvoie le titre sans la disquette, le numero et le total
    foreach ($r in @($rx.DiskFb, $rx.DiskCamel, $rx.DiskD)) {
        $m = $r.Match($lead)
        if (-not $m.Success) { continue }
        $tot = 0; if ($m.Groups.Count -gt 2 -and $m.Groups[2].Success) { $tot = [int]$m.Groups[2].Value }
        $dk = $m.Groups[1].Value; $w = $rx.DiskWord[$dk.ToLowerInvariant()]
        if ($w) { $dk = $w }
        return @{ Title = $lead.Substring(0, $m.Index); Disk = $dk; Tot = $tot }
    }
    return $null
}

function Get-LibNameInfo([string]$name, [string]$dirName = '') {
    # Analyse d un nom de fichier de la Bibliotheque (TOSEC v4, No-Intro, replis hors convention) :
    #  Title (titre court), Key (cle du groupe : titre compact, article final remis en tete), Version, Date, Publisher,
    #  DiskNo / DiskTot / Disk (disquette n sur N, lettre A = 1), DiskLetter, Label (label de media TOSEC), Langs (« en-fr »,
    #  « M3 » ; langue du pays a defaut), LangList, Country, Flags (codes TOSEC : cr, t, !...), FlagText, State (bad : [b] [o]
    #  [u] [v] ; mod : [cr] [f] [h] [m] [p] [t] [tr] ; ok : [!]), Variant (date, editeur, pays, statut, autres mentions),
    #  Sps (numero de publication entre crochets d un dossier SPS), Source (file, ou dir : IPF SPS au nom sans parentheses,
    #  dont le dossier de publication porte le nom TOSEC), Prefix (debut du nom, pour retrouver les autres disquettes),
    #  SetKey (jeu de disquettes : meme nom sans la disquette, ni les mentions [cr] [a]..., ni les crochets d information
    #  propres a une disquette comme [bootable] ou [WB] ; SetVariant : la variante ainsi reduite), Base (nom sans extension),
    #  Modified (mention de copie modifiee), SortKey (titre compact, ordre des groupes)
    $rx = $script:LibRx; if (-not $rx) { $rx = Initialize-LibRx }
    $base = $name; $ext = ''
    $i = $name.LastIndexOf('.')
    if ($i -gt 0 -and $name.Length - $i -le 6) {
        $e = $name.Substring($i)
        if ($e -match '^\.[A-Za-z0-9]{1,5}$' -and $e -notmatch '^\.\d+$') { $ext = $e.ToLowerInvariant(); $base = $name.Substring(0, $i) }
    }
    $fp = Read-LibNameParts $base $rx
    $parts = $fp; $src = 'file'; $fbDisk = $null
    if ($fp.Toks.Count -eq 0) { $fbDisk = Find-LibDiskInLead $fp.Lead $rx }
    # IPF des publications SPS : « WizNLiz_Disk1.ipf » dans « Wiz 'n' Liz (1993)(Psygnosis)[0749] » ; le dossier n est pris
    # que si son titre est celui du fichier (formes compactes egales, ou l une debut de l autre sur 4 caracteres au moins,
    # ou titre du fichier de 8 caracteres au moins contenu dans celui du dossier ; & lu « and ») ; numero final « _1 » admis
    if ($dirName -and $fp.Toks.Count -eq 0 -and $dirName.IndexOf('(') -ge 0) {
        $dp = Read-LibNameParts $dirName $rx
        if ($dp.Toks.Count -gt 0 -and $dp.Lead) {
            $ft = if ($fbDisk) { $fbDisk.Title } else { $fp.Lead }
            $dt = $dp.Lead; $mv = $rx.Ver.Match($dt); if ($mv.Success) { $dt = $dt.Substring(0, $mv.Index) }
            $b = Get-LibCompact ($dt -replace '&', 'and')
            $cand = @(@{ T = $ft; D = $fbDisk })
            if (-not $fbDisk) { $mu = $rx.DiskU.Match($fp.Lead); if ($mu.Success) { $cand += @{ T = $fp.Lead.Substring(0, $mu.Index); D = @{ Title = $fp.Lead.Substring(0, $mu.Index); Disk = $mu.Groups[1].Value; Tot = 0 } } } }
            foreach ($c in $cand) {
                $a = Get-LibCompact ($c.T -replace '&', 'and')
                if ($a.Length -lt 2 -or $b.Length -lt 2) { continue }
                $short = [math]::Min($a.Length, $b.Length)
                if ($a -eq $b -or ($short -ge 4 -and ($a.StartsWith($b) -or $b.StartsWith($a))) -or ($a.Length -ge 8 -and $b.Contains($a))) {
                    $parts = $dp; $src = 'dir'; $fbDisk = $c.D; break
                }
            }
        }
    }
    $lead = $parts.Lead
    $ver = ''
    $mv = $rx.Ver.Match($lead); if ($mv.Success) { $ver = $mv.Groups[1].Value; $lead = $lead.Substring(0, $mv.Index) }
    $diskNo = 0; $diskTot = 0; $disk = ''; $letter = $false; $label = ''
    $date = ''; $pub = ''; $multi = ''; $country = ''; $sps = ''
    $langs = [System.Collections.Generic.List[string]]::new()
    $flags = [System.Collections.Generic.List[string]]::new()
    $flagText = [System.Collections.Generic.List[string]]::new()
    $var = [System.Collections.Generic.List[string]]::new()
    $afterDate = $false; $afterDisk = $false
    foreach ($t in $parts.Toks) {
        $k = $t[0]; $x = $t[1]
        if ($k -eq 'b') {
            $afterDate = $false; $afterDisk = $false
            if ($x -eq '!') { $flags.Add('!'); $flagText.Add('[!]'); continue }
            $mf = $rx.Flag.Match($x)
            if ($mf.Success) { $flags.Add($mf.Groups[1].Value); $flagText.Add("[$x]"); continue }
            if ($rx.SpsNo.IsMatch($x)) { $sps = $x; continue }
            $var.Add("[$x]"); continue
        }
        if ($afterDate) { $pub = $x; $afterDate = $false; $var.Add("($x)"); continue }
        if (-not $disk) {
            $md = $rx.Disk.Match($x)
            if ($md.Success) {
                $disk = $md.Groups[1].Value.ToUpperInvariant()
                if ($md.Groups[2].Success) { $diskTot = [int]$md.Groups[2].Value }
                if ($md.Groups[3].Success) { $disk = $disk + $md.Groups[3].Value.ToUpperInvariant() }
                $afterDisk = $true; continue
            }
        }
        $wasDisk = $afterDisk; $afterDisk = $false
        if (-not $date -and $rx.Date.IsMatch($x)) { $date = $x; $afterDate = $true; $var.Add("($x)"); continue }
        if ($rx.LangT.IsMatch($x)) { foreach ($l in $x.Split('-')) { $langs.Add($l) }; continue }
        if ($rx.LangM.IsMatch($x)) { $multi = $x; continue }
        if ($rx.LangN.IsMatch($x)) { foreach ($l in ($x -split ',\s?')) { $langs.Add($l.ToLowerInvariant()) }; continue }
        if ($rx.Copy.IsMatch($x)) { $var.Add("($x)"); continue }
        if ($rx.Country.IsMatch($x) -or $rx.Region.IsMatch($x)) { $country = $x; $var.Add("($x)"); continue }
        if ($rx.VerTok.IsMatch($x)) { if (-not $ver) { $ver = $x }; continue }
        # Label de media TOSEC : la parenthese qui suit la disquette (« (Disk 1 of 4)(Workbench) »), propre a chaque disquette
        if ($wasDisk) { $label = $x; continue }
        $var.Add("($x)")
    }
    # Disquette hors convention : dans le nom du fichier (meme quand le reste vient du dossier de publication)
    if (-not $disk -and $fbDisk) {
        $disk = $fbDisk.Disk.ToUpperInvariant(); $diskTot = $fbDisk.Tot
        if ($src -eq 'file') { $lead = $fbDisk.Title }
    }
    if ($disk) {
        if ($disk -match '^(\d+)') { $diskNo = [int]$Matches[1] }
        elseif ($disk -match '^[A-Z]') { $diskNo = [int][char]$disk[0] - 64; $letter = $true }
    }
    $title = $rx.Trim.Replace($lead, '').Trim()
    if (-not $title) { $title = $base }
    $kt = $title; $ma = $rx.Article.Match($kt)
    if ($ma.Success) { $kt = $ma.Groups[2].Value + ' ' + $ma.Groups[1].Value }
    $key = Get-LibCompact $kt
    if (-not $key) { $key = $base.ToLowerInvariant() }
    # Langues : indiquees, sinon celle du pays ou de la region (« (DE) » : de) ; « M3 » : trois langues, non detaillees
    $derived = $false
    if ($langs.Count -eq 0 -and -not $multi -and $country) {
        foreach ($c in ($country -split '[-,]\s*')) { $l = $script:LibCountryLang[$c]; if ($l -and -not $langs.Contains($l)) { $langs.Add($l); $derived = $true } }
    }
    $langText = if ($langs.Count -gt 0) { $langs -join '-' } else { $multi }
    $state = ''; $modified = $false
    foreach ($f in $flags) {
        if ($f -eq 'b' -or $f -eq 'o' -or $f -eq 'u' -or $f -eq 'v') { $state = 'bad' }
        elseif ($f -eq 'cr' -or $f -eq 'f' -or $f -eq 'h' -or $f -eq 'm' -or $f -eq 'p' -or $f -eq 't' -or $f -eq 'tr') { $modified = $true }
    }
    if (-not $state -and $modified) { $state = 'mod' }
    if (-not $state -and $flags.Contains('!')) { $state = 'ok' }
    $varText = $var -join ''
    # FIX4B (C2) : variante du jeu, sans les crochets d information propres a une disquette ([bootable], [WB]...) : cle de
    # jeu et ordre des lignes (sinon « (Disk 1 of 2)[WB] » et « (Disk 2 of 2) » formaient deux jeux incomplets)
    $setVar = $varText
    if ($varText.IndexOf('[') -ge 0) {
        $sv = [System.Collections.Generic.List[string]]::new()
        foreach ($v in $var) { if (-not $v.StartsWith('[') -or $rx.SetTag.IsMatch($v.Substring(1, $v.Length - 2))) { $sv.Add($v) } }
        $setVar = $sv -join ''
    }
    # Debut du nom de fichier, pour retrouver les autres disquettes du jeu dans le dossier (motif « prefixe* »)
    $prefix = if ($src -eq 'dir') { '' } elseif ($fp.Toks.Count -eq 0 -and $fbDisk) { $rx.Trim.Replace($fbDisk.Title, '') } else { $rx.Trim.Replace($fp.Lead, '') }
    $setKey = "$key|$($ver.ToLowerInvariant())|$($setVar.ToLowerInvariant())|$langText|$ext"
    return @{
        Title = $title; Key = $key; Version = $ver; Date = $date; Publisher = $pub; Disk = $disk; DiskNo = $diskNo; DiskTot = $diskTot
        DiskLetter = $letter; Label = $label; Langs = $langText; LangList = @($langs); LangDerived = $derived; Multi = $multi; Country = $country
        Flags = @($flags); FlagText = ($flagText -join ' '); State = $state; Modified = $modified; Variant = $varText; SetVariant = $setVar; Sps = $sps; Source = $src
        Prefix = $prefix; SetKey = $setKey; Base = $base; Ext = $ext; Rest = $parts.Rest; SortKey = (Get-LibCompact $title)
    }
}

function Get-LibDiskText($info) {
    # Disquette pour la colonne « Disq. » : « 2/4 », « 2 », « B »
    if (-not $info.Disk) { return '' }
    if ($info.DiskTot -gt 0) { return "$($info.Disk)/$($info.DiskTot)" }
    return $info.Disk
}

function Get-LibMissingDisks($sets) {
    # Disquettes absentes de jeux a plusieurs disquettes. $sets : SetKey -> liste de @{ DiskNo ; DiskTot ; Letter }.
    # Total annonce (« Disk x of y ») : numeros absents de 1 a y ; sans total : trous entre 1 et le plus grand numero present.
    # Renvoie SetKey -> @{ Missing (numeros) ; Total ; Known (total annonce) ; Letter }
    $out = @{}
    foreach ($k in @($sets.Keys)) {
        $have = @{}; $tot = 0; $max = 0; $letter = $false
        foreach ($d in $sets[$k]) {
            $n = [int]$d.DiskNo; if ($n -le 0) { continue }
            $have[$n] = $true; if ($n -gt $max) { $max = $n }
            if ([int]$d.DiskTot -gt $tot) { $tot = [int]$d.DiskTot }
            if ($d.Letter) { $letter = $true }
        }
        if ($max -eq 0) { continue }
        $known = ($tot -gt 0); $n2 = if ($known) { $tot } else { $max }
        if ($n2 -lt 2 -or $n2 -gt 99) { continue }
        $miss = @(for ($j = 1; $j -le $n2; $j++) { if (-not $have.ContainsKey($j)) { $j } })
        if ($miss.Count -gt 0) { $out[$k] = @{ Missing = $miss; Total = $n2; Known = $known; Letter = $letter } }
    }
    return $out
}

function Format-LibDiskList($m) {
    # « 3, 7 » ; disquettes en lettres : « C, G »
    return (@($m.Missing | ForEach-Object { if ($m.Letter) { [string][char](64 + $_) } else { "$_" } }) -join ', ')
}

function Get-LibWordRx([string]$word, [bool]$inDirs) {
    # Expression d un mot de la recherche : ses lettres et chiffres dans l ordre, sans casse, separes au plus par des
    # caracteres qui ne sont ni lettres ni chiffres ; sans $inDirs, dans le nom du fichier seulement (aucune barre oblique
    # inverse apres le mot). Mot sans lettre ni chiffre : $null.
    # FIX4C (relecture finale du lot 4) : elle filtre le sur-ensemble de l index (FastIndex.Search, et Start-LibSearch en
    # repli : mot tel qu il est saisi, sous-chaine du chemin, casse ignoree). La ponctuation omise n est donc pas toleree
    # dans les faits : « kings » ne trouve pas « King's », « king's » ne trouve pas « KingsQuest » ; « king quest » trouve
    # les deux. Recherche sans ponctuation : FastIndex a modifier (12.9, avec une validation de securite, D19)
    # FIX4B (revue du lot 4, C5) : la forme compacte n a plus d accents ; le mot tel qu il est saisi est donc aussi accepte
    # (« Opération » trouve « Opération Stealth », comme en 12.7 : l index cherche le mot brut)
    $c = Get-LibCompact $word
    if (-not $c) { return $null }
    $sep = if ($inDirs) { '[^\p{L}\p{N}]*' } else { '[^\p{L}\p{N}\\]*' }
    $p = (@($c.ToCharArray() | ForEach-Object { [regex]::Escape([string]$_) }) -join $sep)
    $raw = $word.Trim()
    if ($raw -and $raw.ToLowerInvariant() -cne $c) { $p = '(?:' + $p + '|' + [regex]::Escape($raw) + ')' }
    if (-not $inDirs) { $p += '[^\\]*$' }
    return ('(?i)' + $p)
}

function Select-LibMatches([string[]]$rels, [string]$filter, [bool]$inDirs) {
    # 12.8 (A3 § 4.2 n° 8) : chemins relatifs dont le NOM de fichier contient chaque mot (le chemin complet avec $inDirs,
    # comme la 12.7), en ignorant la casse (ponctuation : voir Get-LibWordRx, FIX4C). Filtrage vectorise (operateur
    # -match sur le tableau : 50 000 chemins en moins de 0,1 s sous pwsh 7), ordre garde. $rels : sur-ensemble de l index
    # Affectation directe : un tableau d un seul element ne doit pas devenir une chaine (-match rendrait un booleen)
    [string[]]$cur = @(); if ($null -ne $rels) { $cur = [string[]]$rels }
    foreach ($w in @($filter.Split([char[]]@(' '), [System.StringSplitOptions]::RemoveEmptyEntries))) {
        $rx = Get-LibWordRx $w $inDirs
        if ($rx -and $cur.Count -gt 0) { $cur = [string[]]@($cur -match $rx) }
    }
    return ,$cur
}

function Get-Crc32([byte[]]$Data, [int]$Offset = 0, [int]$Count = -1, [System.IO.Stream]$Stream = $null) {
    # CRC-32 IEEE (celui de zlib, des archives ZIP et des enregistrements IPF, A5 § 3.3) calcule par la bibliotheque ZIP
    # native de .NET, sans aucun calcul en PowerShell (alertes EDR du 20/10/2026, decisions128) : les $Count octets de
    # $Data a partir de $Offset (ou le flux $Stream, lu jusqu a sa fin) vont dans l entree unique d une archive ZIP en
    # memoire, sans compression ; l archive fermee, le CRC est lu dans l en-tete du repertoire central (fin d archive
    # 0x06054B50 dans les 22 derniers octets, l archive n a pas de commentaire ; en-tete central 0x02014B50, CRC au
    # decalage 16, petit-boutiste). Tableau vide : 0. Nom de type qualifie par l assembly : System.IO.Compression n est
    # pas charge par l amorce (seulement System.IO.Compression.FileSystem) ; ce nom le charge depuis le GAC, sans Add-Type
    if ($Count -lt 0) { $Count = $(if ($null -ne $Data) { $Data.Length - $Offset } else { 0 }) }
    $cap = $(if ($Stream -and $Stream.CanSeek) { [int][math]::Min([long]$Stream.Length + 4096, [int]::MaxValue) } else { $Count + 4096 })
    $ms = New-Object System.IO.MemoryStream($cap)
    try {
        $za = [System.IO.Compression.ZipArchive, System.IO.Compression, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089]::new($ms, 'Create', $true)
        try {
            $es = $za.CreateEntry('crc32', 'NoCompression').Open()
            try {
                if ($Stream) { $Stream.CopyTo($es, 65536) } elseif ($Count -gt 0) { $es.Write($Data, $Offset, $Count) }
            } finally { $es.Dispose() }
        } finally { $za.Dispose() }
        $b = $ms.GetBuffer(); $e = [int]$ms.Length - 22
        if ($e -lt 0 -or [BitConverter]::ToUInt32($b, $e) -ne 0x06054B50) { throw (T 'calcul du CRC-32 impossible') }
        $cd = [long][BitConverter]::ToUInt32($b, $e + 16)
        if ($cd + 46 -gt $e -or [BitConverter]::ToUInt32($b, [int]$cd) -ne 0x02014B50) { throw (T 'calcul du CRC-32 impossible') }
        return [long][BitConverter]::ToUInt32($b, [int]$cd + 16)
    } finally { $ms.Dispose() }
}

function Get-IpfInfoBlock([byte[]]$h) {
    # Enregistrements CAPS (12 octets) et INFO (96 octets) en tete d un IPF (A3 § 3.1, A5 § 3.2), valeurs big-endian.
    # Kind : sps (structure de publication SPS : CAPS puis INFO, CRC valides, encodeur 1 CAPS ou 2 SPS, fileKey different de
    # la marque de disk-analyse ; creatorId non teste, il vaut 0 dans les publications SPS, decisions128) ; user (IPF
    # utilisateur de disk-analyse, fileKey 0x843265BB) ; crc (CRC de CAPS ou d INFO faux) ; other (encodeur inconnu) ;
    # none (bloc INFO absent ou illisible). Le bloc INFO n est qu un indice d origine : « officiel » demande une DAT (D18)
    $r = @{ Kind = 'none'; CrcOk = $false; MediaType = 0; Encoder = 0; EncRev = 0; FileKey = 0; FileRev = 0; Origin = 0; MinTrack = 0; MaxTrack = 0
            MinSide = 0; MaxSide = 0; Date = 0; Time = 0; Platforms = @(); DiskNumber = 0; CreatorId = 0 }
    if (-not $h -or $h.Length -lt 108) { return $r }
    $asc = [System.Text.Encoding]::ASCII
    if ($asc.GetString($h, 0, 4) -ne 'CAPS' -or (Get-BE32 $h 4) -ne 12 -or $asc.GetString($h, 12, 4) -ne 'INFO' -or (Get-BE32 $h 16) -ne 96) { return $r }
    $r.MediaType = Get-BE32 $h 24; $r.Encoder = Get-BE32 $h 28; $r.EncRev = Get-BE32 $h 32; $r.FileKey = Get-BE32 $h 36
    $r.FileRev = Get-BE32 $h 40; $r.Origin = Get-BE32 $h 44; $r.MinTrack = Get-BE32 $h 48; $r.MaxTrack = Get-BE32 $h 52
    $r.MinSide = Get-BE32 $h 56; $r.MaxSide = Get-BE32 $h 60; $r.Date = Get-BE32 $h 64; $r.Time = Get-BE32 $h 68
    $r.Platforms = @(foreach ($o in 72, 76, 80, 84) { $p = Get-BE32 $h $o; if ($p -ne 0) { $p } })
    $r.DiskNumber = Get-BE32 $h 88; $r.CreatorId = Get-BE32 $h 92
    # CRC de chaque enregistrement complet, champ CRC (octets 8 a 11 de l enregistrement) mis a zero
    $ok = $true
    foreach ($rec in @(@(0, 12), @(12, 96))) {
        $b = [byte[]]::new($rec[1])
        [Array]::Copy($h, $rec[0], $b, 0, $rec[1])
        $stored = Get-BE32 $b 8
        $b[8] = 0; $b[9] = 0; $b[10] = 0; $b[11] = 0
        if ((Get-Crc32 $b 0 $rec[1]) -ne $stored) { $ok = $false }
    }
    $r.CrcOk = $ok
    if (-not $ok) { $r.Kind = 'crc' }
    elseif ($r.FileKey -eq 0x843265BBL) { $r.Kind = 'user' }
    elseif ($r.Encoder -eq 1 -or $r.Encoder -eq 2) { $r.Kind = 'sps' }
    else { $r.Kind = 'other' }
    return $r
}

function Get-AdfInfo([byte[]]$boot, [byte[]]$root, [long]$size) {
    # ADF (A3 § 4.2 n° 4, A5 § 2) : bloc de demarrage (« DOS » et octet de type : bit 0 FFS, bit 1 INTL, bit 2 DIRCACHE ;
    # somme avec report sur 256 mots longs = 0xFFFFFFFF : amorcable) ; bloc racine 880 (DD, 81 a 83 cylindres compris) ou
    # 1760 (HD) : type 2 en 0, sous-type 1 en 508, somme nulle sur 128 mots longs ; nom du volume : longueur en 432, 30
    # caracteres au plus a partir de 433 (ISO-8859-1)
    $r = @{ Dos = $false; Fs = ''; Flags = -1; Intl = $false; DirCache = $false; Bootable = $false; BootRead = $false; RootOk = $false; Volume = ''; Hd = $false; RootBlock = 880 }
    $r.Hd = ($size -gt 0 -and $size % 22528 -eq 0 -and $size / 11264 -gt 84)
    if ($r.Hd) { $r.RootBlock = 1760 }
    if ($boot -and $boot.Length -ge 1024) {
        $r.BootRead = $true
        if ($boot[0] -eq 0x44 -and $boot[1] -eq 0x4F -and $boot[2] -eq 0x53 -and $boot[3] -le 7) {
            $r.Dos = $true; $f = [int]$boot[3]; $r.Flags = $f
            $r.Fs = if ($f -band 1) { 'FFS' } else { 'OFS' }
            $r.Intl = [bool]($f -band 2); $r.DirCache = [bool]($f -band 4)
            [long]$s = 0
            for ($o = 0; $o -lt 1024; $o += 4) {
                $s += Get-BE32 $boot $o
                if ($s -gt 0xFFFFFFFFL) { $s = ($s -band 0xFFFFFFFFL) + 1 }
            }
            $r.Bootable = ($s -eq 0xFFFFFFFFL)
        }
    }
    if ($root -and $root.Length -ge 512) {
        [long]$s = 0
        for ($o = 0; $o -lt 512; $o += 4) { $s = ($s + (Get-BE32 $root $o)) -band 0xFFFFFFFFL }
        if ((Get-BE32 $root 0) -eq 2 -and (Get-BE32 $root 508) -eq 1 -and $s -eq 0) {
            $r.RootOk = $true
            $n = [int]$root[432]; if ($n -gt 30) { $n = 30 }
            if ($n -gt 0) { $r.Volume = [System.Text.Encoding]::GetEncoding(28591).GetString($root, 433, $n) }
        }
    }
    return $r
}
# ============================== FONCTIONS : BIBLIOTHEQUE, LISTE DE REFERENCE ====
# 12.8 (lot 4b, D19 ; A3 § 3.4 B) : liste de reference (DAT) choisie par l utilisateur sur son ordinateur. Aucune liste
# n est fournie, embarquee ni telechargee par l application. Formats : Logiqx XML (TOSEC, No-Intro), lu par XmlReader
# sans DTD ni resolution externe, et clrmamepro (texte). Identification d un fichier : index par taille et empreinte
# (SHA-1 ou MD5 par la cryptographie .NET, sinon CRC-32 par la bibliotheque ZIP de .NET, Get-Crc32) ; etats sur le
# modele de RomVault : officiel (identique a une entree de la liste), modifie (meme nom qu une entree, contenu different),
# inconnu. Archive ZIP : CRC-32 et taille de chaque entree lus dans le repertoire central, sans decompression ni calcul ;
# image extraite pour l ecriture controlee contre ce CRC-32 (Test-LibZipEntryData, FIX4B).
# Empreintes calculees gardees dans hash-<md5 de la racine>.tsv, a cote de l index. Fonctions sans interface, testables
# au niveau 2. Aucun calcul de CRC en PowerShell (alertes EDR du 20/10/2026).

function New-LibDatIndex([string]$format) {
    # Liste vide : en-tete, compteurs, index par taille et par nom de fichier (sans le dossier, casse ignoree).
    # FIX4C (relecture finale du lot 4) : index ByHash par « taille|type|empreinte » (type C, M ou S : CRC-32, MD5, SHA-1),
    # et « taille|type| » pour les entrees de cette taille qui n ont pas cette empreinte (Get-LibDatMatch)
    return @{ Ok = $false; Error = ''; Format = $format; Name = ''; Description = ''; Version = ''; Path = ''
              Games = 0; Roms = 0; Skipped = 0; Ms = 0
              BySize = [System.Collections.Generic.Dictionary[long, System.Collections.Generic.List[object]]]::new()
              ByName = [System.Collections.Generic.Dictionary[string, System.Collections.Generic.List[object]]]::new([System.StringComparer]::OrdinalIgnoreCase)
              ByHash = [System.Collections.Generic.Dictionary[string, System.Collections.Generic.List[object]]]::new([System.StringComparer]::OrdinalIgnoreCase) }
}

function Add-LibDatRom($dat, [string]$game, [string]$name, [string]$size, [string]$crc, [string]$md5, [string]$sha1) {
    # Entree d une liste : taille obligatoire et au moins une empreinte valide (CRC-32 sur 8 chiffres hexadecimaux, MD5,
    # SHA-1) ; sinon ignoree (comptee dans Skipped). Nom garde sans son dossier
    [long]$sz = -1
    if (-not [long]::TryParse(([string]$size).Trim(), [System.Globalization.NumberStyles]::Integer, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$sz) -or $sz -lt 0) { $dat.Skipped++; return }
    $c = ([string]$crc).Trim().ToUpperInvariant()
    if ($c -match '^[0-9A-F]{1,8}$') { $c = $c.PadLeft(8, '0') } else { $c = '' }
    $m = ([string]$md5).Trim().ToLowerInvariant(); if ($m -notmatch '^[0-9a-f]{32}$') { $m = '' }
    $s = ([string]$sha1).Trim().ToLowerInvariant(); if ($s -notmatch '^[0-9a-f]{40}$') { $s = '' }
    if (-not $c -and -not $m -and -not $s) { $dat.Skipped++; return }
    $leaf = ([string]$name) -replace '^.*[\\/]', ''
    $e = @{ Game = [string]$game; Name = $leaf; Size = $sz; Crc = $c; Md5 = $m; Sha1 = $s; Ord = 0 }
    $l = $null
    if (-not $dat.BySize.TryGetValue($sz, [ref]$l)) { $l = [System.Collections.Generic.List[object]]::new(); $dat.BySize[$sz] = $l }
    $e.Ord = $l.Count
    $l.Add($e)
    # FIX4C : rang Ord dans la liste de sa taille ; index par taille et empreinte, empreinte vide = entree sans cette empreinte
    foreach ($k in "$sz|C|$c", "$sz|M|$m", "$sz|S|$s") {
        $l = $null
        if (-not $dat.ByHash.TryGetValue($k, [ref]$l)) { $l = [System.Collections.Generic.List[object]]::new(); $dat.ByHash[$k] = $l }
        $l.Add($e)
    }
    if ($leaf) {
        $l = $null
        if (-not $dat.ByName.TryGetValue($leaf, [ref]$l)) { $l = [System.Collections.Generic.List[object]]::new(); $dat.ByName[$leaf] = $l }
        $l.Add($e)
    }
    $dat.Roms++
}

function Get-LibDatRx {
    # Expressions du format clrmamepro, creees une fois. FIX4B (revue du lot 4, C6) : aucune n a deux quantificateurs
    # voisins qui se disputent les memes caracteres (« rom ( » suivi de milliers d espaces bloquait l interface 50 s) :
    # duree proportionnelle a la longueur de la ligne ; delai maximal de 1 s par recherche en plus (liste refusee)
    if ($script:LibDatRx) { return $script:LibDatRx }
    $o = [System.Text.RegularExpressions.RegexOptions]::None; $to = [TimeSpan]::FromSeconds(1)
    $script:LibDatRx = @{
        Open    = [regex]::new('^(\w+)\s*\($', $o, $to)
        Kv      = [regex]::new('^(\w+)\s+(?:"([^"]*)"|(.*))$', $o, $to)
        # Forme ecrite par clrmamepro (espaces simples) : nom entre guillemets ou sans espace, size, crc, puis md5 et sha1
        RomFast = [regex]::new('^rom \( name (?:"([^"]*)"|([^\s"]+)) size (\d+) crc "?([0-9A-Fa-f]{1,8})"?(?: md5 "?([0-9A-Fa-f]{32})"?)?(?: sha1 "?([0-9A-Fa-f]{40})"?)? \)$', $o, $to)
        # Jetons : texte entre guillemets (jusqu a la fin si le guillemet n est pas ferme), ou suite de caracteres sans espace
        Tok     = [regex]::new('"[^"]*(?:"|$)|[^\s"]+', $o, $to)
        Hex     = [regex]::new('^"?([0-9A-Fa-f]+)"?$', $o, $to)
        Keys    = [System.Collections.Generic.HashSet[string]]::new([string[]]@('size', 'crc', 'md5', 'sha1', 'sha256', 'merge', 'status', 'flags', 'date', 'region', 'serial', 'offs', 'bios'), [System.StringComparer]::Ordinal)
    }
    return $script:LibDatRx
}

function ConvertFrom-LibDatRomLine([string]$ln) {
    # Ligne « rom ( ... ) » de clrmamepro (rognee) : champs name, size, crc, md5, sha1 ; $null si ce n est pas un fichier
    # decrit sur une ligne (« rom ( » seul ouvre un bloc). FIX4B (C6) : forme courante lue par une expression sans retour
    # arriere, sinon contenu entre la premiere « ( » et la derniere « ) », decoupe en jetons
    $rx = Get-LibDatRx
    $m = $rx.RomFast.Match($ln)
    if ($m.Success) {
        return @{ name = $(if ($m.Groups[1].Success) { $m.Groups[1].Value } else { $m.Groups[2].Value }); size = $m.Groups[3].Value; crc = $m.Groups[4].Value; md5 = $m.Groups[5].Value; sha1 = $m.Groups[6].Value }
    }
    $i = $ln.IndexOf('(')
    if ($i -lt 3 -or -not $ln.StartsWith('rom') -or $ln.Substring(3, $i - 3).Trim().Length -gt 0 -or -not $ln.EndsWith(')') -or $ln.Length - $i -lt 2) { return $null }
    return (ConvertFrom-LibDatRomText $ln.Substring($i + 1, $ln.Length - $i - 2).Trim())
}

function ConvertFrom-LibDatRomText([string]$s) {
    # Champs d une ligne « rom ( ... ) » de clrmamepro : name entre guillemets, ou jusqu au mot-cle suivant (noms avec
    # espaces ou parentheses, ecrits sans guillemets par certains outils, comme la DAT SPS) ; puis size, crc, md5, sha1.
    # FIX4B (C6) : jetons d une expression lineaire, lus dans l ordre ; nom sans guillemets repris tel quel de la ligne
    $rx = Get-LibDatRx
    $f = @{}
    $toks = $rx.Tok.Matches($s)
    $n = $toks.Count; $i = 0
    if ($n -ge 2 -and $toks[0].Value -ceq 'name') {
        $a = $toks[1]
        if ($a.Value.StartsWith('"')) {
            $v = $a.Value.Substring(1); if ($v.EndsWith('"')) { $v = $v.Substring(0, $v.Length - 1) }
            $f['name'] = $v; $i = 2
        } else {
            # Nom jusqu au mot-cle suivant, s il est suivi d un autre jeton (comme « size 1234 »)
            $j = 2
            while ($j -lt $n -and -not ($rx.Keys.Contains($toks[$j].Value) -and $j + 1 -lt $n)) { $j++ }
            $z = $toks[$j - 1]
            $f['name'] = $s.Substring($a.Index, $z.Index + $z.Length - $a.Index); $i = $j
        }
    }
    foreach ($k in 'size', 'crc', 'md5', 'sha1') {
        for ($t = $i; $t + 1 -lt $n; $t++) {
            if ($toks[$t].Value -cne $k) { continue }
            $h = $rx.Hex.Match($toks[$t + 1].Value)
            if ($h.Success) { $f[$k] = $h.Groups[1].Value; break }
        }
    }
    return $f
}

function Read-LibDatClrMamePro([string]$text) {
    # Format texte clrmamepro, ligne par ligne (forme ecrite par clrmamepro et par les outils qui le suivent) : bloc ouvert
    # par « mot ( » en fin de ligne et ferme par « ) » seul ; lignes « cle valeur » (valeur entre guillemets ou non) ;
    # fichier sur une ligne, « rom ( name ... size ... crc ... md5 ... sha1 ... ) ». En-tete : clrmamepro ou emulator ;
    # jeux : game, machine, resource, set ; autres blocs et lignes (disk, sample...) ignores ; « ) » en trop ignoree
    $dat = New-LibDatIndex 'clrmamepro'
    # FIX4B (C6) : expressions sans retour arriere catastrophique (Get-LibDatRx), ligne « rom ( ... ) » lue par
    # ConvertFrom-LibDatRomLine (forme courante d un coup, sinon jetons)
    $rx = Get-LibDatRx
    $rxOpen = $rx.Open; $rxKv = $rx.Kv
    $stack = [System.Collections.Generic.List[object]]::new()
    $cur = $null
    foreach ($raw in $text.Split([char]10)) {
        $ln = $raw.Trim()
        if ($ln.Length -eq 0) { continue }
        if ($cur -and $ln.StartsWith('rom')) {
            $rf = ConvertFrom-LibDatRomLine $ln
            if ($null -ne $rf) { $cur.Roms.Add($rf); continue }
        }
        if ($ln -eq ')') {
            if ($stack.Count -eq 0) { continue }
            $blk = $cur
            $stack.RemoveAt($stack.Count - 1)
            $cur = if ($stack.Count -gt 0) { $stack[$stack.Count - 1] } else { $null }
            $t = $blk.T
            if ($t -eq 'rom') { if ($cur) { $cur.Roms.Add($blk.F) } }
            elseif ($t -eq 'game' -or $t -eq 'machine' -or $t -eq 'resource' -or $t -eq 'set') {
                $dat.Games++
                foreach ($f in $blk.Roms) { Add-LibDatRom $dat ([string]$blk.F['name']) ([string]$f['name']) ([string]$f['size']) ([string]$f['crc']) ([string]$f['md5']) ([string]$f['sha1']) }
            } elseif ($t -eq 'clrmamepro' -or $t -eq 'emulator') {
                $dat.Name = [string]$blk.F['name']; $dat.Description = [string]$blk.F['description']; $dat.Version = [string]$blk.F['version']
            }
            continue
        }
        if ($ln.EndsWith('(')) {
            $m = $rxOpen.Match($ln)
            if ($m.Success) {
                $blk = @{ T = $m.Groups[1].Value.ToLowerInvariant(); F = @{}; Roms = [System.Collections.Generic.List[object]]::new() }
                $stack.Add($blk); $cur = $blk
                continue
            }
        }
        if (-not $cur) { continue }
        $m = $rxKv.Match($ln)
        if ($m.Success) { $cur.F[$m.Groups[1].Value.ToLowerInvariant()] = $(if ($m.Groups[2].Success) { $m.Groups[2].Value } else { $m.Groups[3].Value }) }
    }
    return $dat
}

function Read-LibDatLogiqx([System.IO.Stream]$stream) {
    # Format Logiqx XML : <header> (name, description, version), <game> ou <machine> ou <software>, <rom name size crc
    # md5 sha1/>. DtdProcessing.Ignore : le DOCTYPE est saute sans lire la DTD (ni fichier ni reseau) ; XmlResolver nul :
    # aucune resolution externe. Une entite declaree dans la DTD (interne ou externe) reste donc inconnue : sa reference
    # leve une XmlException, la liste est refusee
    $dat = New-LibDatIndex 'Logiqx XML'
    $set = New-Object System.Xml.XmlReaderSettings
    $set.DtdProcessing = [System.Xml.DtdProcessing]::Ignore
    $set.XmlResolver = $null
    $set.IgnoreComments = $true; $set.IgnoreWhitespace = $true; $set.IgnoreProcessingInstructions = $true
    $set.CloseInput = $false
    $xr = [System.Xml.XmlReader]::Create($stream, $set)
    try {
        $game = ''; $inHeader = $false
        $go = $xr.Read()
        while ($go) {
            $adv = $false
            $nt = $xr.NodeType
            if ($nt -eq [System.Xml.XmlNodeType]::Element) {
                $ln = $xr.LocalName
                if ($ln -eq 'rom') {
                    Add-LibDatRom $dat $game $xr.GetAttribute('name') $xr.GetAttribute('size') $xr.GetAttribute('crc') $xr.GetAttribute('md5') $xr.GetAttribute('sha1')
                } elseif ($ln -eq 'game' -or $ln -eq 'machine' -or $ln -eq 'software') {
                    $game = [string]$xr.GetAttribute('name'); $dat.Games++
                } elseif ($ln -eq 'header') {
                    if (-not $xr.IsEmptyElement) { $inHeader = $true }
                } elseif ($inHeader -and ($ln -eq 'name' -or $ln -eq 'description' -or $ln -eq 'version')) {
                    $v = $xr.ReadElementContentAsString(); $adv = $true
                    if ($ln -eq 'name') { $dat.Name = $v } elseif ($ln -eq 'description') { $dat.Description = $v } else { $dat.Version = $v }
                }
            } elseif ($nt -eq [System.Xml.XmlNodeType]::EndElement -and $xr.LocalName -eq 'header') { $inHeader = $false }
            if ($adv) { $go = -not $xr.EOF } else { $go = $xr.Read() }
        }
    } finally { $xr.Close() }
    return $dat
}

function Read-LibDat([string]$path) {
    # Liste de reference d un fichier : format d apres le premier caractere significatif (« < » : Logiqx XML ; lettre :
    # clrmamepro), 256 Mo au plus. Renvoie l index (Ok, ou Error avec le message)
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    $dat = New-LibDatIndex ''
    try {
        $fi = New-Object System.IO.FileInfo($path)
        if (-not $fi.Exists) { $dat.Error = (T 'fichier introuvable') }
        elseif ($fi.Length -gt 256MB) { $dat.Error = ((T 'fichier trop gros ({0})') -f (Format-Size $fi.Length)) }
        else {
            $fs = [System.IO.File]::Open($path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
            try {
                $head = New-Object byte[] 4096
                $n = $fs.Read($head, 0, 4096)
                $enc = [System.Text.Encoding]::UTF8; $off = 0
                if ($n -ge 2 -and $head[0] -eq 0xFF -and $head[1] -eq 0xFE) { $enc = [System.Text.Encoding]::Unicode; $off = 2 }
                elseif ($n -ge 2 -and $head[0] -eq 0xFE -and $head[1] -eq 0xFF) { $enc = [System.Text.Encoding]::BigEndianUnicode; $off = 2 }
                elseif ($n -ge 3 -and $head[0] -eq 0xEF -and $head[1] -eq 0xBB -and $head[2] -eq 0xBF) { $off = 3 }
                $first = $enc.GetString($head, $off, [math]::Max(0, $n - $off)).TrimStart()
                [void]$fs.Seek(0, [System.IO.SeekOrigin]::Begin)
                $d = $null
                if ($first.StartsWith('<')) { $d = Read-LibDatLogiqx $fs }
                elseif ($first -match '^[A-Za-z]') {
                    $sr = New-Object System.IO.StreamReader($fs, [System.Text.Encoding]::UTF8, $true)
                    $d = Read-LibDatClrMamePro $sr.ReadToEnd()
                } else { $dat.Error = (T 'format non reconnu (ni Logiqx XML ni clrmamepro)') }
                if ($d) {
                    $dat = $d
                    if ($dat.Roms -eq 0) { $dat.Error = (T 'aucune entrée avec une taille et une empreinte') }
                }
            } finally { $fs.Dispose() }
        }
    } catch {
        $e = $_.Exception
        while ($e.InnerException -and $e -is [System.Management.Automation.MethodInvocationException]) { $e = $e.InnerException }
        $dat.Error = if ($e -is [System.Text.RegularExpressions.RegexMatchTimeoutException]) { T 'liste mal formée (ligne trop longue à analyser)' } else { $e.Message }
    }
    $dat.Path = $path
    $dat.Ok = (-not $dat.Error)
    $dat.Ms = $sw.ElapsedMilliseconds
    if (-not $dat.Name) { $dat.Name = [System.IO.Path]::GetFileNameWithoutExtension($path) }
    return $dat
}

function Get-LibDatCompare($e, $h, [bool]$common = $false) {
    # Entree $e de la liste et empreintes connues $h du fichier : $false des qu une empreinte connue des deux cotes
    # differe ; sinon egalite exigee sur l empreinte la plus forte que porte l entree (SHA-1, puis MD5, puis CRC-32) ;
    # $null si le fichier ne l a pas encore (a calculer). FIX4B (revue du lot 4, C7) : un CRC-32 garde en cache ne decide
    # plus seul quand la liste fournit un SHA-1 ou un MD5 (le verdict ne depend plus du cache des empreintes).
    # $common (entree d archive ZIP : seul le CRC-32 du repertoire central est connu sans decompression) : la plus forte
    # des empreintes communes suffit, comme au lot 4b ; les donnees sont controlees avant l ecriture (Test-LibZipEntryData)
    if (($e.Sha1 -and $h.Sha1 -and $e.Sha1 -ne $h.Sha1) -or ($e.Md5 -and $h.Md5 -and $e.Md5 -ne $h.Md5) -or ($e.Crc -and $h.Crc -and $e.Crc -ne $h.Crc)) { return $false }
    if ($common) {
        if (($e.Sha1 -and $h.Sha1) -or ($e.Md5 -and $h.Md5) -or ($e.Crc -and $h.Crc)) { return $true }
        return $null
    }
    $k = if ($e.Sha1) { 'Sha1' } elseif ($e.Md5) { 'Md5' } else { 'Crc' }
    if ($e[$k] -and $h[$k]) { return $true }
    return $null
}

function Get-LibDatMatch($dat, [long]$size, [string]$name, $h, [switch]$Common) {
    # Etat d un fichier de taille $size et de nom $name, d empreintes connues $h (Crc, Md5, Sha1 ; vides si inconnues) :
    #  ok   officiel : meme taille et meme empreinte qu une entree (Entry : celle du meme nom s il y en a une) ;
    #  mod  modifie : aucune entree identique, mais une entree porte le meme nom de fichier (Entry) ;
    #  unk  inconnu : ni empreinte ni nom dans la liste ;
    #  wait empreinte a calculer (Need : Sha1, Md5 ou Crc, la plus forte que porte l entree de meme taille).
    # -Common : comparaison sur la plus forte des empreintes communes (entrees d archive ZIP, Get-LibDatCompare)
    # FIX4C (relecture finale du lot 4 : 2 738 entrees SPS de 1 049 612 octets, 27 ms par appel) : sans empreinte connue,
    # toutes les entrees de cette taille sont a calculer, la premiere donne Need. Sinon, seules sont comparees les entrees
    # qui ont la meme valeur pour une empreinte connue du fichier (index ByHash), ou aucune de ses empreintes connues : les
    # autres different sur une empreinte connue des deux cotes (Get-LibDatCompare : $false). Rang Ord de la liste garde :
    # meme resultat (Entry, Need) que la comparaison de toutes les entrees de cette taille
    $leaf = ([string]$name) -replace '^.*[\\/]', ''
    if ($null -eq $h) { $h = @{} }
    $cands = $null
    if ($dat.BySize.TryGetValue($size, [ref]$cands) -and $cands.Count -gt 0) {
        $hc = [string]$h.Crc; $hm = [string]$h.Md5; $hs = [string]$h.Sha1
        if (-not $hc -and -not $hm -and -not $hs) {
            $e = $cands[0]
            return @{ State = 'wait'; Need = $(if ($e.Sha1) { 'Sha1' } elseif ($e.Md5) { 'Md5' } else { 'Crc' }) }
        }
        if ($null -ne $dat.ByHash) {
            $parts = [System.Collections.Generic.List[object]]::new()
            $miss = $null; $noMiss = $false; $l = $null
            foreach ($p in @(@('C', $hc), @('M', $hm), @('S', $hs))) {
                if (-not $p[1]) { continue }
                if ($dat.ByHash.TryGetValue("$size|$($p[0])|$($p[1])", [ref]$l)) { $parts.Add($l) }
                # Entrees sans aucune des empreintes connues : la plus courte des listes « sans cette empreinte », filtree
                if ($dat.ByHash.TryGetValue("$size|$($p[0])|", [ref]$l)) { if (-not $noMiss -and ($null -eq $miss -or $l.Count -lt $miss.Count)) { $miss = $l } }
                else { $noMiss = $true; $miss = $null }
            }
            if ($null -ne $miss) {
                $none = [System.Collections.Generic.List[object]]::new()
                foreach ($e in $miss) { if ((-not $hc -or -not $e.Crc) -and (-not $hm -or -not $e.Md5) -and (-not $hs -or -not $e.Sha1)) { $none.Add($e) } }
                if ($none.Count -gt 0) { $parts.Add($none) }
            }
            if ($parts.Count -eq 1) { $cands = $parts[0] }
            else {
                $sd = [System.Collections.Generic.SortedDictionary[int, object]]::new()
                foreach ($pl in $parts) { foreach ($e in $pl) { $sd[[int]$e.Ord] = $e } }
                $cands = $sd.Values
            }
        }
        $hit = $null; $need = ''
        foreach ($e in $cands) {
            $m = Get-LibDatCompare $e $h ([bool]$Common)
            if ($null -eq $m) {
                if (-not $need) { $need = if ($e.Sha1) { 'Sha1' } elseif ($e.Md5) { 'Md5' } else { 'Crc' } }
                continue
            }
            if ($m -and (-not $hit -or ($e.Name -ieq $leaf -and $hit.Name -ine $leaf))) { $hit = $e }
        }
        if ($hit) { return @{ State = 'ok'; Entry = $hit } }
        if ($need) { return @{ State = 'wait'; Need = $need } }
    }
    $named = $null
    if ($leaf -and $dat.ByName.TryGetValue($leaf, [ref]$named)) { return @{ State = 'mod'; Entry = $named[0] } }
    return @{ State = 'unk' }
}

function Get-LibFileCrc32([string]$path) {
    # CRC-32 d un fichier entier, lu en flux et calcule par la bibliotheque ZIP native de .NET (Get-Crc32), sans calcul
    # en PowerShell : 8 chiffres hexadecimaux en majuscules
    $fs = [System.IO.File]::Open($path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
    try { return ('{0:X8}' -f (Get-Crc32 -Stream $fs)) } finally { $fs.Dispose() }
}

function Get-LibHashText([string]$algo, [System.IO.Stream]$stream) {
    # SHA-1 ou MD5 d un flux, par la cryptographie .NET (deja utilisee par l index), en hexadecimal minuscule
    $ha = if ($algo -eq 'Sha1') { [System.Security.Cryptography.SHA1]::Create() } else { [System.Security.Cryptography.MD5]::Create() }
    try { return ([BitConverter]::ToString($ha.ComputeHash($stream)).Replace('-', '').ToLowerInvariant()) } finally { $ha.Dispose() }
}

function ConvertFrom-LibZipDir([byte[]]$cd, [int]$count) {
    # Entrees du repertoire central d une archive ZIP (signature 0x02014B50), dans l ordre de ZipArchive.Entries : nom
    # (UTF-8 si le bit 11 est mis, sinon page de codes 437), CRC-32, tailles, dossier ; $null si le repertoire est tronque
    if (-not $script:LibZipEnc) {
        try { $script:LibZipEnc = [System.Text.Encoding]::GetEncoding(437) } catch { $script:LibZipEnc = [System.Text.Encoding]::GetEncoding(28591) }
    }
    $out = [System.Collections.Generic.List[object]]::new()
    $p = 0
    for ($k = 0; $k -lt $count; $k++) {
        if ($p + 46 -gt $cd.Length -or [BitConverter]::ToUInt32($cd, $p) -ne 0x02014B50) { return $null }
        $flags = [BitConverter]::ToUInt16($cd, $p + 8)
        $nl = [BitConverter]::ToUInt16($cd, $p + 28); $xl = [BitConverter]::ToUInt16($cd, $p + 30); $cl = [BitConverter]::ToUInt16($cd, $p + 32)
        if ($p + 46 + $nl -gt $cd.Length) { return $null }
        $enc = if ($flags -band 0x800) { [System.Text.Encoding]::UTF8 } else { $script:LibZipEnc }
        $nm = $enc.GetString($cd, $p + 46, $nl)
        $out.Add(@{ Name = $nm; Crc = ('{0:X8}' -f [BitConverter]::ToUInt32($cd, $p + 16)); CSize = [long][BitConverter]::ToUInt32($cd, $p + 20)
                    Size = [long][BitConverter]::ToUInt32($cd, $p + 24); Dir = $nm.EndsWith('/'); Index = $k })
        $p += 46 + $nl + $xl + $cl
    }
    return ,$out
}

function Read-LibZipDir([string]$path) {
    # Repertoire central d une archive ZIP, sans decompression : fin d archive (0x06054B50, commentaire compris) cherchee
    # dans les 65 557 derniers octets, puis repertoire lu d un bloc. $null si illisible ou ZIP64 (non pris en charge)
    $fs = [System.IO.File]::Open($path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
    try {
        $len = $fs.Length
        if ($len -lt 22) { return $null }
        $tl = [int][math]::Min($len, 65557)
        $tail = New-Object byte[] $tl
        [void]$fs.Seek($len - $tl, [System.IO.SeekOrigin]::Begin)
        $got = 0
        while ($got -lt $tl) { $k = $fs.Read($tail, $got, $tl - $got); if ($k -le 0) { break }; $got += $k }
        if ($got -lt $tl) { return $null }
        $at = -1
        for ($i = $tl - 22; $i -ge 0; $i--) {
            if ($tail[$i] -eq 0x50 -and $tail[$i + 1] -eq 0x4B -and $tail[$i + 2] -eq 5 -and $tail[$i + 3] -eq 6 -and [BitConverter]::ToUInt16($tail, $i + 20) -eq $tl - $i - 22) { $at = $i; break }
        }
        if ($at -lt 0) { return $null }
        $n = [int][BitConverter]::ToUInt16($tail, $at + 10)
        $cdSize = [long][BitConverter]::ToUInt32($tail, $at + 12); $cdOff = [long][BitConverter]::ToUInt32($tail, $at + 16)
        if ($n -eq 0xFFFF -or $cdOff -eq 0xFFFFFFFFL -or $cdSize -gt 64MB -or $cdOff + $cdSize -gt $len) { return $null }
        $cd = New-Object byte[] $cdSize
        [void]$fs.Seek($cdOff, [System.IO.SeekOrigin]::Begin)
        $got = 0
        while ($got -lt $cdSize) { $k = $fs.Read($cd, $got, [int]($cdSize - $got)); if ($k -le 0) { break }; $got += $k }
        if ($got -lt $cdSize) { return $null }
        # FIX4B (revue du lot 4, C1) : liste rendue telle quelle (virgule). « return (liste) » la deroulait : avec une seule
        # entree, l appelant recevait la table de l entree au lieu d une liste (entree d un ZIP TOSEC dite « inconnu »)
        $ents = ConvertFrom-LibZipDir $cd $n
        if ($null -eq $ents) { return $null }
        return ,$ents
    } finally { $fs.Dispose() }
}

function Test-LibZipEntryData([string]$zipPath, $idx, [string]$entry, [string]$file) {
    # FIX4B (revue du lot 4, C3) : entree $entry (rang $idx) extraite dans $file, comparee au repertoire central de
    # l archive (taille et CRC-32) : ZipArchive ne controle pas les donnees decompressees. CRC-32 du fichier extrait par la
    # bibliotheque ZIP native de .NET (Get-LibFileCrc32). @{ Ok ; Want ; Got } ; $null si le controle est impossible
    # (archive illisible ou ZIP64, entree introuvable, fichier absent ou de plus de 256 Mo)
    $dir = Read-LibZipDir $zipPath
    if ($null -eq $dir) { return $null }
    $e = $null
    # Rang dans ZipArchive.Entries = rang dans le repertoire central (lot 4b) ; sinon le nom
    if ($null -ne $idx -and [int]$idx -ge 0 -and [int]$idx -lt $dir.Count -and -not $dir[[int]$idx].Dir) { $e = $dir[[int]$idx] }
    else { foreach ($d in $dir) { if (-not $d.Dir -and $d.Name -ceq $entry) { $e = $d; break } } }
    if (-not $e) { return $null }
    $fi = New-Object System.IO.FileInfo($file)
    if (-not $fi.Exists -or $fi.Length -gt 256MB) { return $null }
    $got = Get-LibFileCrc32 $file
    return @{ Ok = ($fi.Length -eq [long]$e.Size -and $got -eq $e.Crc); Want = $e.Crc; Got = $got; Size = $fi.Length; WantSize = [long]$e.Size }
}

function Get-LibZipDatState($dat, $entries) {
    # Archive ZIP : etat de chaque entree image (taille et CRC-32 du repertoire central), puis de l archive : officiel si
    # toutes ses images le sont ; modifie si une partie seulement l est, ou si une image est modifiee ; inconnu sinon.
    # Entree dont l empreinte manque (liste sans CRC-32) : State wait (a calculer sur le flux decompresse)
    $res = [System.Collections.Generic.List[object]]::new()
    foreach ($e in $entries) {
        if ($e.Dir -or (Get-FileKind ($e.Name -replace '^.*/', '')) -ne 'image') { $res.Add($null); continue }
        $res.Add((Get-LibDatMatch $dat ([long]$e.Size) $e.Name @{ Crc = $e.Crc } -Common))
    }
    return (Measure-LibZipDatState $res)
}

function Measure-LibZipDatState($res) {
    # Etat d une archive d apres l etat de ses entrees image ($null : entree hors images)
    $ok = 0; $mod = 0; $tot = 0; $wait = 0
    foreach ($s in $res) {
        if (-not $s) { continue }
        $tot++
        switch ($s.State) { 'ok' { $ok++ } 'mod' { $mod++ } 'wait' { $wait++ } }
    }
    $st = if ($wait -gt 0) { 'wait' } elseif ($tot -gt 0 -and $ok -eq $tot) { 'ok' } elseif ($ok -gt 0 -or $mod -gt 0) { 'mod' } else { 'unk' }
    return @{ State = $st; OkCount = $ok; Total = $tot; Entries = $res }
}

function Get-LibHashFile([string]$root) {
    # Cache des empreintes d une racine : hash-<16 premiers chiffres du MD5 du chemin>.tsv, a cote de l index
    $md5 = [System.Security.Cryptography.MD5]::Create()
    try { $h = [BitConverter]::ToString($md5.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($root.TrimEnd('\').ToLowerInvariant()))).Replace('-', '').Substring(0, 16) }
    finally { $md5.Dispose() }
    return (Join-Path $script:IndexDir "hash-$h.tsv")
}

function Get-LibHashKey([string]$path, [long]$size, [long]$ticks) { return ($path.ToLowerInvariant() + '|' + $size + '|' + $ticks) }

function Import-LibHashCache([string]$file) {
    # Empreintes gardees : lignes « chemin, taille, date de modification (ticks UTC), CRC-32, MD5, SHA-1 » separees par
    # des tabulations ; une ligne plus recente complete la precedente. Fichier absent ou illisible : cache vide
    $c = [System.Collections.Generic.Dictionary[string, object]]::new()
    try {
        if (-not [System.IO.File]::Exists($file)) { return ,$c }
        foreach ($ln in [System.IO.File]::ReadAllLines($file, [System.Text.Encoding]::UTF8)) {
            if (-not $ln -or $ln.StartsWith('#')) { continue }
            $f = $ln.Split("`t")
            if ($f.Count -lt 6) { continue }
            [long]$sz = 0; [long]$tk = 0
            if (-not [long]::TryParse($f[1], [ref]$sz) -or -not [long]::TryParse($f[2], [ref]$tk)) { continue }
            $k = Get-LibHashKey $f[0] $sz $tk
            $o = $null
            if (-not $c.TryGetValue($k, [ref]$o)) { $o = @{ Crc = ''; Md5 = ''; Sha1 = '' }; $c[$k] = $o }
            if ($f[3] -match '^[0-9A-F]{8}$') { $o.Crc = $f[3] }
            if ($f[4] -match '^[0-9a-f]{32}$') { $o.Md5 = $f[4] }
            if ($f[5] -match '^[0-9a-f]{40}$') { $o.Sha1 = $f[5] }
        }
    } catch { }
    return ,$c
}

function Add-LibHashLine([string]$file, [string]$path, [long]$size, [long]$ticks, $h) {
    # Ajout d une ligne au cache des empreintes (cree avec son en-tete) ; erreur d ecriture ignoree (cache facultatif)
    try {
        $dir = [System.IO.Path]::GetDirectoryName($file)
        if (-not [System.IO.Directory]::Exists($dir)) { [void][System.IO.Directory]::CreateDirectory($dir) }
        $new = -not [System.IO.File]::Exists($file)
        $line = "$path`t$size`t$ticks`t$($h.Crc)`t$($h.Md5)`t$($h.Sha1)"
        if ($new) { $line = "#GWHASH1`tchemin`ttaille`tticks`tcrc32`tmd5`tsha1`r`n" + $line }
        [System.IO.File]::AppendAllText($file, $line + "`r`n", (New-Object System.Text.UTF8Encoding($false)))
    } catch { }
}
# ============================== FONCTIONS : ECRITURE ===========================

function Get-WarmMinutesText([double]$wm) {
    # Duree du prechauffage dans les textes des cases : « 5 min », sinon minutes et secondes (« 2 min 30 s »)
    if ($wm -eq [math]::Floor($wm)) { return "$([int]$wm) min" }
    return (Format-CalDuration (60 * $wm))
}

function Update-SlowUi {
    # Ecriture lente : champ --precomp de la tete 1 actif, le premier champ devient celui de la tete 0
    $on = $chkWSlow.Checked
    $txtWPrecomp1.Enabled = $on; $lblWPrecomp1.Enabled = $on
    $chkWPrecomp.Text = if ($on) { (T 'Précomp. tête 0 (--precomp) :') } else { (T 'Précompensation (--precomp) :') }
    # Prechauffages (12.8, D6) : avant l ecriture lente (case inactive sans ecriture lente) et avant une calibration
    # complete, duree commune (reglage warmMinutes, variable CalWarmupMinutes) ; cases inactives a 0 min. Champ de la duree
    # recopie de la variable sous la garde des liaisons, sans changer le reglage
    $wm = [double]$script:CalWarmupMinutes
    $mt = Get-WarmMinutesText $wm
    $chkWWarm.Text = if ($wm -gt 0) { (T "Préchauffer le lecteur avant l'écriture lente ({0} au plus de lecture sans écriture)") -f "$mt" } else { (T "Préchauffer le lecteur avant l'écriture lente (désactivé : durée du préchauffage à 0)") }
    $chkWWarm.Enabled = ($on -and $wm -gt 0)
    $chkWCalWarm.Text = if ($wm -gt 0) { (T "Préchauffer le lecteur avant la calibration complète ({0} au plus de lecture sans écriture)") -f "$mt" } else { (T "Préchauffer le lecteur avant la calibration complète (désactivé : durée du préchauffage à 0)") }
    $chkWCalWarm.Enabled = ($wm -gt 0)
    $sv = $script:SettingSync; $script:SettingSync = $true
    try {
        $nv = [decimal][math]::Max(0.0, [math]::Min(30.0, $wm))
        if ($numWWarmMin.Value -ne $nv) { $numWWarmMin.Value = $nv }
        # 12.7 point 5 : mesure de la disquette, ecriture lente seulement. 12.8 (D5) : liste au « Test rapide » : la
        # disquette est mesuree (ecriture rapide ou lente, quel que soit le point de depart, memes exclusions partout :
        # Get-LevelWriteSkip) : case cochee et verrouillee, le reglage levelBeforeWrite est garde pour les autres modes
        $quick = ($cmbWCalMode.SelectedIndex -eq 2)
        $show = if ($quick) { $true } else { [bool](Get-Setting 'levelBeforeWrite') }
        if ($chkWLevel.Checked -ne $show) { $chkWLevel.Checked = $show }
    } finally { $script:SettingSync = $sv }
    # 12.10 (relecture de la RC) : texte, etat actif et infobulle de la case de la mesure, etat de la liste « Mesure : » :
    # Update-WLevelUi, d apres l effet du lecteur cible sur l ecriture et la mesure que ferait Start-LevelBeforeWrite
    Update-WLevelUi
}

function Update-WLevelUi {
    # 12.10 (relecture de la RC) : case « Mesurer la disquette » (texte, etat actif, infobulle) et liste « Mesure : » (etat
    # actif), d apres les decisions de l ecriture : effet du lecteur cible sur l ecriture de l onglet (Get-TargetWriteInfo,
    # celui de Start-WriteTabWrite et de Start-PresetWrite, qui ne mesurent pas une ecriture pour un lecteur cible) et
    # mesure que ferait Start-LevelBeforeWrite (Get-LevelBeforeWriteKind : mesure complete d une ecriture lente au « Test
    # rapide »). Appels : Update-SlowUi, sortie d Update-PrecompForImage (image, format, profil, lecteur cible), case
    # --precomp (520). Lecteur cible sans effet (profil Manuel, --precomp decoche, flux ecrit tel quel, FM, GCR) : case
    # ordinaire, infobulle qui le dit (texte du journal de Start-ImageWrite) ; ecriture refusee pour le lecteur cible :
    # infobulle qui le dit. Avant : d apres le seul choix (Get-TargetDrive) : case verrouillee et courbe croisee annoncee
    # dans ces cas, texte du « Test rapide » sans exception pour le lecteur cible, rien de refait au changement de
    # profil, de case --precomp ou d image. Avant l affichage de la fenetre : aucun acces au fichier (racine reseau
    # possible), comme Update-CurveButton ; WLevelTip : infobulle d origine, gardee par 520
    if (-not $chkWLevel -or -not $chkWSlow -or -not $cmbWCalMode) { return }
    $on = [bool]$chkWSlow.Checked
    $quick = ($cmbWCalMode.SelectedIndex -eq 2)
    $p = if ($script:UiReady) { [string]$txtWFile.Text } else { '' }
    $tw = Get-TargetWriteInfo $p ([string]$cmbWFmt.Text) $on
    $ta = [bool]$tw.Applies
    # 12.8 (S3) : mesure complete choisie : duree de la case retiree (celle de la liste fait foi). 12.8.1 (spec-1281 § D.1) :
    # mesure sur l image a ecrire (defaut) : texte propre
    $lm = [string](Get-Setting 'levelBeforeWriteMode')
    $full = ($lm -eq 'complete')
    $lk = Get-LevelBeforeWriteKind $(if ($on) { 'slow' } else { 'fast' }) $false $false
    # 12.11 (lot LN-b) : un lecteur enregistre en jeu (lecteur qui ecrit ou lecteur cible) : texte court, sans les deux
    # lecteurs (avec un nom, le texte a deux lecteurs depasserait la case) ; l infobulle les nomme
    $chkWLevel.Text = if ($quick -and $ta -and $script:DriveReg.Count -gt 0 -and ((Test-DriveRegistered ([string]$tw.Tgt)) -or (Test-DriveRegistered ([string]$tw.Src)))) { (T "Mesurer la disquette avant l'écriture : toujours en « Test rapide », sauf pour un lecteur cible") } elseif ($quick -and $ta) { (T "Mesurer la disquette avant l'écriture : toujours en « Test rapide », sauf pour le lecteur cible {0} (elle relirait avec le lecteur {1})") -f "$($tw.Tgt)", "$($tw.Src)" } elseif ($quick -and $lk -eq 'complete') { (T "Mesurer la disquette avant l'écriture : toujours en « Test rapide » (mesure complète de cette disquette en écriture lente)") } elseif ($quick) { (T "Mesurer la disquette avant l'écriture : toujours en « Test rapide » (niveau de précompensation et état de la surface)") } elseif ($lm -eq 'content') { (T "Mesurer la disquette avant l'écriture lente : précompensation mesurée sur l'image (environ 12 min)") } elseif ($full) { (T "Mesurer la disquette avant l'écriture lente : précompensation et état de la surface") } else { (T "Mesurer la disquette avant l'écriture lente : niveau de précompensation et état de la surface (environ 1 min)") }
    $chkWLevel.Enabled = ($on -and -not $quick -and -not $ta)
    # 12.8 (S3) : liste du mode de la mesure (rapide ou complete) : active en ecriture lente quand la disquette est mesuree
    # (case cochee, ou verrouillee au « Test rapide »)
    if ($cmbWLevelMode) { $cmbWLevelMode.Enabled = ($on -and $chkWLevel.Checked -and -not $ta); $lblWLevelMode.Enabled = $cmbWLevelMode.Enabled }
    if ($script:WLevelTip) {
        $tt = if ($ta -and $tw.Block) { (T "Mesure de la disquette non disponible pour un lecteur cible : elle relirait avec le lecteur {0}, pas avec le lecteur cible {1}. Écriture refusée : {2}") -f "$($tw.Src)", "$($tw.Tgt)", "$($tw.Block)" }
              elseif ($ta) { (T "Mesure de la disquette non disponible pour un lecteur cible : elle relirait avec le lecteur {0}, pas avec le lecteur cible {1}. L'image est écrite avec la courbe croisée telle quelle.") -f "$($tw.Src)", "$($tw.Tgt)" }
              elseif ($tw.Tgt -and $tw.Why) { ((T "Lecteur cible {0} sans effet sur cette écriture : {1}.") -f "$($tw.Tgt)", "$($tw.Why)") + "`n" + [string]$script:WLevelTip }
              else { [string]$script:WLevelTip }
        $tip.SetToolTip($chkWLevel, $tt)
    }
    # 12.11 (L10) : ligne « Ce qui va se passer » (Update-WritePlanUi, 145) : memes appels que la case de la mesure (image,
    # format, profil et courbes, ecriture lente, liste « Calibration precomp », case --precomp, lecteurs, reglages)
    if ($lblWPlan) { Update-WritePlanUi }
}

# Options "comment ecrire" de l ecriture ; la calibration les reprend sans --format ni --diskdefs (Get-CalibDriveArgs, motif HFE)
function Get-WriteFormatArgs {
    $a = @()
    if ($chkWReverse.Checked)    { $a += '--reverse' }
    if ($chkWHard.Checked)       { $a += '--hard-sectors' }
    if ($chkWTG43.Checked)       { $a += '--gen-tg43' }
    if ($cmbWFmt.Text -and $cmbWFmt.Text -ne '(auto)')      { $a += "--format=$($cmbWFmt.Text)" }
    if ($cmbWDensel.Text -ne '(non)') { $a += "--densel=$($cmbWDensel.Text)" }
    if ($txtWFakeIdx.Text.Trim())     { $a += "--fake-index=$($txtWFakeIdx.Text.Trim())" }
    if ($txtWDiskdefs.Text.Trim())    { $a += "--diskdefs=`"$($txtWDiskdefs.Text.Trim())`"" }
    return $a
}

# --- Decisions de l ecriture (12.11, L10) -------------------------------
# Extraites de Start-ImageWrite sans changement de comportement : Start-ImageWrite les appelle, puis ecrit les memes lignes
# de journal et ouvre les memes fenetres, dans le meme ordre ; la ligne « Ce qui va se passer » (Get-WritePlan, 145) tire
# ses segments des memes fonctions. Aucune ligne de journal, aucune fenetre ici.

function Get-WriteHeads([string]$img, [string]$userTs, [bool]$slow, [bool]$eraseEmpty) {
    # Tetes ecrites : @{ Heads ; Err ; OneFace }. Ecriture rapide : 0 et 1 (gw ecrit les tetes du format). Ecriture lente :
    # tetes du champ Pistes (Get-TSpecHeads) ; sans h= explicite, faces de l image (gw part des pistes du format et h=1
    # ajouterait la tete 1 d un format simple face, D64, IMG simple face, IPF une face : avec --erase-empty, toute la face
    # 1 serait effacee). OneFace : image a une seule face (ligne de journal). Err : texte du refus (fenetre de
    # Start-ImageWrite) : aucune tete choisie par le champ Pistes, ou faces de l image inconnues avec « Effacer les pistes
    # vides »
    # 12.11 (L10, revue J) : Gw, tetes que gw ecrit, pour la ligne « Ce qui va se passer » : ecriture rapide, tetes du
    # champ Pistes (h=0 : tete 0 seule ; image a une face gardee apres une ecriture rapide de la Bibliotheque,
    # Get-FaceSafeWrite) ; Heads reste @(0, 1) en ecriture rapide (pistes de l effacement, Get-WriteEraseKeys)
    $r = @{ Heads = @(0, 1); Err = ''; OneFace = $false; Gw = @(0, 1) }
    if (-not $slow) { $r.Gw = Get-TSpecHeads $userTs; return $r }
    $heads = Get-TSpecHeads $userTs
    if ($heads.Count -eq 0) {
        $r.Heads = $heads; $r.Err = (T 'Écriture lente : le champ Pistes ne sélectionne ni la tête 0 ni la tête 1.'); return $r
    }
    if (-not [regex]::IsMatch(":$userTs", ':\s*h\s*=')) {
        $imgSet = Get-ImageTrackSet $img
        if ($null -ne $imgSet) {
            $present = @{}
            foreach ($k in @($imgSet.Keys)) { $present[[int](($k -split '\.')[1])] = $true }
            $heads = @(@(0, 1) | Where-Object { $present.ContainsKey($_) })
            if ($heads.Count -eq 1) { $r.OneFace = $true }
        } elseif ($eraseEmpty) {
            $r.Heads = $heads
            # 12.11 (L12a) : champ Pistes et case « Effacer les pistes vides » dans les options avancees (lot L9) : le refus le dit.
            # Relecture de L12a : emplacement en tete de la consigne, lisible dans les trois lignes de « Ce qui va se passer »
            $r.Err = (T "Écriture lente : nombre de faces de l'image inconnu ({0}).`nDans les options avancées, indiquer les têtes dans le champ Pistes (h=0-1 : double face, h=0 : simple face)`nou décocher « Effacer les pistes vides » : la tête 1 d'un format simple face serait effacée.") -f "$([System.IO.Path]::GetFileName($img))"
            return $r
        }
    }
    $r.Heads = $heads; $r.Gw = $heads
    return $r
}

function Get-WriteErasePlan([string]$img, [string]$fmt, [string]$userTs, [int[]]$heads, [bool]$on) {
    # Effacement avant l ecriture (case « Effacer avant d ecrire », $on) : @{ Mode ; Check ; EraseKeys ; Hd ; Note ; Fb }.
    # Hd : Test-ImageHighDensity ; Check : effacement des reecritures du controle (Get-EraseMode, selon la densite et les
    # options de lecteur seules). Mode : 'none' (case decochee), 'hfreq' (double densite : effacement haute frequence des
    # pistes EraseKeys, Get-WriteEraseKeys, memes elements du champ Pistes), 'pre' (--pre-erase : haute densite, secteurs
    # durs, TG43, --densel, ou pistes de l image inconnues). Note, ligne de journal du repli : 'keys' (pistes inconnues),
    # 'scp' (flux SCP de densite inconnue), 'fb' (options de lecteur, texte Fb de Get-EraseFallbackNote). Cle EraseKeys et
    # non Keys : $r.Keys rendrait les cles de la table
    $r = @{ Mode = 'none'; Check = ''; EraseKeys = $null; Hd = $false; Note = ''; Fb = '' }
    $r.Hd = Test-ImageHighDensity $img $fmt
    $r.Check = Get-EraseMode $r.Hd
    if ($on -and $r.Check -eq 'hfreq') {
        $r.EraseKeys = Get-WriteEraseKeys $img $fmt $userTs ([int[]]$heads)
        if ($null -eq $r.EraseKeys) { $r.Mode = 'pre'; $r.Note = 'keys' } else { $r.Mode = 'hfreq' }
    } elseif ($on) {
        $r.Mode = 'pre'
        if (Test-ScpDensityUnknown $img) { $r.Note = 'scp' }
        elseif (-not $r.Hd) { $fb = Get-EraseFallbackNote; if ($fb) { $r.Note = 'fb'; $r.Fb = $fb } }
    }
    return $r
}

function Get-WriteSpecPlan([string]$img, [string]$fmt, [bool]$slow, $ie) {
    # Profils --precomp transmis (champs de l onglet, case --precomp cochee) : @{ P0 ; P1 ; Flux ; NonMfm ; Nt }, avant la
    # mise a l echelle par le facteur ($ie : Get-ImageEncoding de l image).
    #  - 12.8 (S3-FLUX, decision 2 du 21/10/2026) : image flux ecrite sans --format : gw l ecrit telle quelle et n applique
    #    --precomp qu aux pistes MasterTrack (Test-RawFluxWrite) : --precomp n est plus transmis, ligne de journal (Flux).
    #  - 12.10 (lot 1, B1) : image FM, GCR ou a codage propre : la precompensation de gw (regle du MFM sans type=) et la
    #    courbe du lecteur ne valent que pour le MFM : --precomp n est plus transmis en profil Auto ou force (decision
    #    B-D1), ligne de journal (NonMfm) ; profil Manuel : champ transmis tel quel, avertissement s il ne precise pas
    #    type= (Nt : profils sans type=)
    $r = @{ P0 = $null; P1 = $null; Flux = $false; NonMfm = $false; Nt = @() }
    $pc0 = if ($chkWPrecomp.Checked -and $txtWPrecomp.Text.Trim()) { $txtWPrecomp.Text.Trim() } else { $null }
    $pc1 = if ($chkWPrecomp.Checked -and $txtWPrecomp1.Text.Trim()) { $txtWPrecomp1.Text.Trim() } else { $null }
    if (($pc0 -or $pc1) -and (Test-RawFluxWrite $img $fmt)) { $r.Flux = $true; $pc0 = $null; $pc1 = $null }
    if (($pc0 -or $pc1) -and $ie.NonMfm) {
        if ($cmbWProfile.SelectedIndex -eq 3) {
            $r.Nt = @(@($(if ($slow) { @($pc0, $pc1) } else { @($pc0) })) | Where-Object { $_ -and $_ -notmatch '(^|:)\s*type\s*=' } | Select-Object -Unique)
        } else { $r.NonMfm = $true; $pc0 = $null; $pc1 = $null }
    }
    $r.P0 = $pc0; $r.P1 = $pc1
    return $r
}

function Get-WriteHeadSpecs([string]$userTs, $p0, $p1) {
    # Profil de chaque tete logique d une ecriture lente (0, 1 -> profil ou $null) : les profils $p0 et $p1 sont ceux des
    # tetes physiques (calibration) ; hswap dans le champ Pistes : la tete logique h est ecrite par la tete 1 - h
    $swap = (Get-TSpecExtras $userTs) -match '(^|:)\s*hswap\s*(:|$)'
    $m = @{}
    foreach ($h in 0, 1) { $phys = if ($swap) { 1 - $h } else { $h }; $m[$h] = if ($phys -eq 0) { $p0 } else { $p1 } }
    return $m
}

function Get-WriteCheckPlan([string]$img, [string]$fmt, [bool]$slow, $heads, $headRaw, $p0Raw, [bool]$forced) {
    # Controle de toutes les pistes apres l ecriture : @{ Post ; Forced ; ByCurve ; Blocker }. Demande par la case
    # « Controler toutes les pistes » ou impose : $forced (courbe adaptee par la calibration rapide qui precede, drapeau
    # LevelPostForce) ou, 12.8 (FIX1C, constat 3, G1), profil ecrit qui est la courbe adaptee d une calibration rapide
    # (Test-LevelAdaptedSpec sur les profils non mis a l echelle : $headRaw par tete en ecriture lente, $p0Raw sinon ;
    # ByCurve, ligne de journal). Blocker : raison pour laquelle l analyse de flux ne s applique pas (Get-WriteCheckBlocker),
    # ecriture sans controle
    $r = @{ Post = $false; Forced = [bool]$forced; ByCurve = $false; Blocker = $null }
    if (-not $r.Forced) {
        $wsp = if ($slow) { @($heads | ForEach-Object { $headRaw[$_] }) } else { @($p0Raw) }
        if (Test-LevelAdaptedSpec ([string[]]@($wsp | Where-Object { $_ }))) { $r.Forced = $true; $r.ByCurve = $true }
    }
    $r.Post = ([bool]$chkWPostCheck.Checked -or $r.Forced)
    $r.Blocker = if ($r.Post) { Get-WriteCheckBlocker $img $fmt } else { $null }
    return $r
}

function Start-ImageWrite([switch]$NoWarmup) {
    # Ecriture de l image avec les parametres de l onglet (bouton ECRIRE, ecriture rapide ou lente, fin de calibration automatique)
    # Ecriture lente : prechauffage du lecteur avant la premiere ecriture (Start-WriteWarmup, chaine d ecriture prete) ;
    # NoWarmup : prechauffage passe a la demande de l utilisateur pendant la calibration qui precede
    # 12.8 (lot 1c, G1) : courbe adaptee a cette disquette par la calibration rapide qui precede : controle apres ecriture
    # impose, meme case decochee (drapeau lu une fois)
    $postForce = [bool]$script:LevelPostForce; $script:LevelPostForce = $false
    # 12.8.1 (spec-1281 § A.10) : facteur mesure sur l image par la mesure qui precede (Complete-ContentMeasure, 276), lu
    # une fois, comme LevelPostForce : il ne vaut que pour cette ecriture
    $wfNext = $script:WriteFactorNext; $script:WriteFactorNext = $null
    if (-not (Test-Path -LiteralPath $txtWFile.Text)) {
        [void](Show-AppMessage (T 'Fichier image introuvable.') (T 'Erreur') 'OK' 'Warning'); return
    }
    if ($script:GwProc -and -not $script:GwProc.HasExited) { return }
    # 12.10 : ecriture pour un lecteur cible (liste « Lecteur cible » de l onglet) refusee sans courbe croisee de la famille
    # (Test-TargetWriteAllowed : journal et fenetre) ; $tgtDrive : lecteur cible dont les courbes croisees sont ecrites ('' :
    # meme lecteur, ou lecteur cible sans effet sur cette ecriture, Get-TargetWriteInfo : ligne de journal)
    if (-not (Test-TargetWriteAllowed $txtWFile.Text $cmbWFmt.Text ([bool]$chkWSlow.Checked))) { return }
    # 12.11 (lot LN-b) : avec des lecteurs enregistres, lecteur branche confirme s il y a lieu et ligne « Lecteur qui
    # ecrit » au journal (Confirm-DriveIdentity, 112) ; refus : rien n est ecrit
    if ($script:DriveReg.Count -gt 0 -and -not (Confirm-DriveIdentity -Write)) { return }
    $tw = Get-TargetWriteInfo $txtWFile.Text $cmbWFmt.Text ([bool]$chkWSlow.Checked)
    $tgtDrive = if ($tw.Applies) { [string]$tw.Tgt } else { '' }
    if ($tw.Tgt -and -not $tw.Applies -and $tw.Why) { Append-Log ((T "Lecteur cible {0} sans effet sur cette écriture : {1}.") -f "$($tw.Tgt)", "$($tw.Why)") }
    # Image flux a plusieurs tours : pistes dont le contenu change d un tour a l autre (bits faibles d une protection),
    # que gw ne reproduit pas (il n ecrit que le premier tour) : avertissement, confirmation, pas de reecriture au controle
    $script:ImageUnstable = $null; $script:ImageSrcWeak = $null; $script:ImageNoJudge = $null; $script:ImageScpFailed = $false; $script:ImageSrcOver = $null
    if (-not $script:Restore -and $script:ScpStatsOk -and [System.IO.Path]::GetExtension($txtWFile.Text).ToLower() -eq '.scp') {
        # Analyse (quelques secondes pour un flux complet) mise en cache par fichier, taille et date. 12.8.2 (decision du
        # 27/10/2026) : $ov, pistes deja hors norme par leurs erreurs (Test-SrcOverErr), ni reecrites ni comptees au controle
        $uk = @{}; $ck = @{}; $nj = @{}; $ov = @{}; $failed = $false
        $fi = Get-Item -LiteralPath $txtWFile.Text
        $ckey = "$($fi.FullName)|$($fi.Length)|$($fi.LastWriteTimeUtc.Ticks)"
        if ($script:ScpWeakCache -and $script:ScpWeakCache.Key -eq $ckey -and $null -ne $script:ScpWeakCache.Over) { $uk = $script:ScpWeakCache.Weak.Clone(); $ck = $script:ScpWeakCache.Crit.Clone(); $nj = $script:ScpWeakCache.NoJudge.Clone(); $ov = $script:ScpWeakCache.Over.Clone(); $failed = [bool]$script:ScpWeakCache.Failed }
        else {
            $oldTxt = $stOp.Text; $stOp.Text = (T "Analyse de l'image flux..."); $status.Refresh()
            $form.Cursor = [System.Windows.Forms.Cursors]::WaitCursor
            try {
                $ts = Read-ScpFile $txtWFile.Text
                foreach ($tn in @($ts.Keys)) {
                    $m = Get-TrackMetrics $ts[$tn]
                    $key = "$([math]::Floor([int]$tn / 2)).$([int]$tn % 2)"
                    # Image jugee aux seuils Standard, comme un original en restauration
                    $lv = if ($m.Bad) { 2 } else { Get-HealthLevel $m.Ooc $m.Dr $m.Stab $m.J $script:JitterStdOk $script:JitterStdWatch }
                    if ($m.Weak) { $uk[$key] = $true } elseif ($lv -ge 2) { $ck[$key] = $true }
                    elseif (Test-SrcOverErr $m) { $ov[$key] = $true }
                    # Courte zone instable (raccord ou protection) ou stabilite non mesurable (un seul tour, densite) : une
                    # zone instable relue sur la copie n y sera pas jugee
                    elseif ($m.ShortUnstable -or $m.Blocks -eq 0) { $nj[$key] = $true }
                }
                $script:ScpWeakCache = @{ Key = $ckey; Weak = $uk.Clone(); Crit = $ck.Clone(); NoJudge = $nj.Clone(); Over = $ov.Clone(); Failed = $false }
            } catch { $failed = $true } finally { $form.Cursor = [System.Windows.Forms.Cursors]::Default; $stOp.Text = $oldTxt }
        }
        if ($uk.Count -gt 0) {
            $lst = Format-TrackList (Sort-TrackKeys @($uk.Keys))
            Append-Log ((T "Image flux : {0} piste(s) changent d'un tour à l'autre ({1}) : bits faibles d'une protection contre la copie probable. gw n'en écrit que le premier tour : la protection risque de ne pas fonctionner sur la disquette écrite. Ces pistes ne sont pas réécrites par le contrôle.") -f "$($uk.Count)", "$lst")
            # 12.8 (D3) : confirmation par frmConfirm, case qui nomme le lecteur
            $cq = @{ Title = (T 'Protection contre la copie'); Heading = (T 'Image protégée contre la copie'); Level = 'warn'; Picto = 'forbid'
                     Text = ((T "L'image {0} contient {1} piste(s) dont le contenu change d'un tour à l'autre ({2}) : bits faibles d'une protection contre la copie probable.`n`ngw n'écrit que le premier tour de chaque piste : ces bits seront figés et la protection risque de ne pas fonctionner sur la disquette écrite. N'écrivez jamais cette image sur une disquette d'origine.") -f "$([System.IO.Path]::GetFileName($txtWFile.Text))", "$($uk.Count)", "$lst")
                     Check = ((T "La disquette du lecteur {0} n'est pas une disquette d'origine") -f "$($cmbDrive.Text)"); GoText = (T 'Écrire quand même'); GoGlyph = 'Save' }
            if (-not (Show-AppConfirm @cq)) { Append-Log (T 'Écriture annulée : image protégée non écrite.'); return }
        }
        if ($ck.Count -gt 0) {
            Append-Log ((T "Image flux : {0} piste(s) déjà critique(s) ou illisible(s) dans l'image ({1}) : piste non formatée, protection ou défaut de l'original. gw en écrit le premier tour tel quel : ces pistes ne sont ni réécrites ni comptées par le contrôle.") -f "$($ck.Count)", "$(Format-TrackList (Sort-TrackKeys @($ck.Keys)))")
        }
        $ign = @{}
        foreach ($k in @(@($uk.Keys) + @($ck.Keys) + @($ov.Keys))) { $ign[[string]$k] = $true }
        if ($ign.Count -gt 0) { $script:ImageUnstable = $ign }
        $script:ImageSrcWeak = $uk; $script:ImageNoJudge = $nj; $script:ImageScpFailed = $failed; $script:ImageSrcOver = $ov
    }
    $slow = $chkWSlow.Checked
    $userTs = $txtWTracks.Text.Trim()
    # 12.11 (L10) : tetes ecrites et refus decides par Get-WriteHeads, dont la ligne « Ce qui va se passer » tire aussi son
    # segment ; memes fenetres et ligne de journal, dans le meme ordre
    $wh = Get-WriteHeads $txtWFile.Text $userTs ([bool]$slow) ([bool]$chkWEraseEmpty.Checked)
    if ($wh.Err) { [void](Show-AppMessage $wh.Err (T 'Erreur') 'OK' 'Warning'); return }
    $heads = $wh.Heads
    if ($wh.OneFace) { Append-Log ((T "Écriture lente : image à une seule face, seule la tête {0} est écrite.") -f "$($heads[0])") }
    # 12.8.2 : case « Effacer avant d ecrire » (150, Get-EraseMode). Disquette double densite : effacement haute frequence
    # des pistes ecrites par l operation (Get-WriteEraseKeys, memes elements du champ Pistes), commandes gw erase --hfreq en
    # tete de la file WriteQueue, avant la premiere ecriture (apres le prechauffage de l ecriture lente), puis ecriture
    # sans --pre-erase ; pistes inconnues : pre-effacement, comme avant. Haute densite, flux SCP de densite inconnue,
    # secteurs durs, TG43, --densel : --pre-erase, comme en 12.8.1. Case decochee : aucun effacement.
    # Revue 12.8.2 : $em, effacement de l ecriture (repli 'pre' si ses pistes sont inconnues) ; $emCheck, effacement des
    # reecritures du controle apres ecriture (New-WriteCheck) : selon la densite et les options de lecteur seules, les
    # pistes faibles etant toujours connues. EraseLog : pistes effacees et ecrites par l operation (Read-GwOutput), pour
    # signaler celles qui restent effacees apres un arret (Fail-Restore). 12.11 (L10) : effacement decide par
    # Get-WriteErasePlan (Mode, Check, EraseKeys), dont la ligne « Ce qui va se passer » tire aussi son segment ; memes
    # lignes de journal, dans le meme ordre
    $ep = Get-WriteErasePlan $txtWFile.Text $cmbWFmt.Text $userTs ([int[]]$heads) ([bool]$chkWPreErase.Checked)
    $emCheck = $ep.Check
    $em = $ep.Mode
    $eraseKeys = $ep.EraseKeys; $eraseCmds = @(); $script:EraseLog = $null
    if ($em -eq 'hfreq') {
        $eraseCmds = New-HfreqEraseCmds $eraseKeys (Get-TSpecExtras $userTs)
        if (@($eraseCmds).Count -gt 0) { $script:EraseLog = @{ Owner = 'write'; Round = 0; Erased = @{}; Written = @{} } }
    } elseif ($ep.Note -eq 'keys') {
        Append-Log ((T "Effacement avant l'écriture : pistes de l'image {0} inconnues, l'effacement haute fréquence ne peut pas les viser : pré-effacement de chaque piste (--pre-erase), comme avant.") -f "$([System.IO.Path]::GetFileName($txtWFile.Text))")
    } elseif ($ep.Note -eq 'scp') {
        Append-Log ((T "Effacement avant l'écriture : densité du flux {0} inconnue (module d'analyse SCP indisponible) : pré-effacement de chaque piste (--pre-erase), comme avant.") -f "$([System.IO.Path]::GetFileName($txtWFile.Text))")
    } elseif ($ep.Note -eq 'fb') { Append-Log $ep.Fb }
    # $base : toutes les options sauf --tracks et l image (reprises telles quelles par les reecritures ciblees) ;
    # en ecriture lente, sans --precomp : chaque tete a sa commande et sa valeur
    $base = @('write') + (Get-CommonArgs)
    if ($chkWPreErase.Checked -and $em -ne 'hfreq') { $base += '--pre-erase' }
    if ($chkWEraseEmpty.Checked) { $base += '--erase-empty' }
    if ($chkWNoVerify.Checked)   { $base += '--no-verify' }
    $base += "--retries=$($numWRetries.Value)"
    # Mode Auto, image haute densite (format choisi apres l image, par exemple) : champs attendus de la branche haute densite
    # d Update-PrecompForImage (12.7 : famille hd calibrable : sa courbe, sinon le profil d origine haute densite ; haute
    # densite non calibrable : profil d origine de sa famille, jamais une courbe double densite) ; format revenu en double
    # densite apres coup : profil calibre de nouveau. 12.10 (lot 1, B1) : sauf image FM, GCR ou a codage propre
    # (Get-ImageEncoding), ecrite sans --precomp ci-dessous
    $ie = Get-ImageEncoding $txtWFile.Text $cmbWFmt.Text
    if ($cmbWProfile.SelectedIndex -eq 0 -and $chkWPrecomp.Checked -and -not $ie.NonMfm) {
        if (Get-HighDensityReason $txtWFile.Text $cmbWFmt.Text) {
            $hf = Get-HdCalibFamily $txtWFile.Text $cmbWFmt.Text
            if ($hf) { $af = Get-HdAutoFields $hf ([bool]$chkWSlow.Checked); $e0 = $af.P0; $e1 = $af.P1 }
            else { $e0 = if ((Get-ImageFamily $txtWFile.Text $cmbWFmt.Text) -eq 'long') { $script:PrecompLongDefault } else { $script:PrecompStdDefault }; $e1 = $e0 }
            if ($txtWPrecomp.Text.Trim() -ne $e0 -or $txtWPrecomp1.Text.Trim() -ne $e1) { Update-PrecompForImage $txtWFile.Text }
        } elseif ($script:WProfileHd) { Update-PrecompForImage $txtWFile.Text }
    }
    # 12.10 : ecriture pour un lecteur cible : champs --precomp attendus, ceux des courbes croisees (Set-PrecompFields : par
    # tete en ecriture lente si elles sont a jour, sinon la commune pour les deux tetes) ; champs differents (courbe adaptee
    # d une calibration rapide, champ modifie a la main, case « Ecriture lente » changee depuis) : profil de l image recalcule
    $tc = @($tw.Curves)
    if ($tgtDrive -and $tc.Count -gt 0) {
        if ($txtWPrecomp.Text.Trim() -ne [string]$tc[0].Spec -or ($slow -and $txtWPrecomp1.Text.Trim() -ne [string]$tc[$tc.Count - 1].Spec)) { Update-PrecompForImage $txtWFile.Text }
    }
    # 12.11 (L10) : profils --precomp transmis decides par Get-WriteSpecPlan (flux ecrit tel quel, FM, GCR, profil Manuel),
    # dont la ligne « Ce qui va se passer » tire aussi le controle impose ; memes lignes de journal, dans le meme ordre
    $sp = Get-WriteSpecPlan $txtWFile.Text $cmbWFmt.Text ([bool]$slow) $ie
    if ($sp.Flux) { Append-Log ((T "Image flux {0} écrite telle quelle (sans --format) : gw n'applique pas la précompensation à un flux, --precomp n'est pas transmis.") -f "$([System.IO.Path]::GetFileName($txtWFile.Text))") }
    $nt = @($sp.Nt)
    if ($nt.Count -gt 0) { Append-Log ((T "Profil manuel sur une image en codage {0} : --precomp {1} est transmis tel quel ; sans type=fm ou type=gcr, gw y applique la règle du MFM.") -f "$($ie.Name)", "$($nt -join ' / ')") }
    if ($sp.NonMfm) { Append-Log ((T "Image {0} en codage {1} ({2}) : écrite sans précompensation, --precomp n'est pas transmis. La précompensation de gw et la courbe du lecteur ne valent que pour le MFM.") -f "$([System.IO.Path]::GetFileName($txtWFile.Text))", "$($ie.Name)", "$($ie.Src)") }
    $pc0 = $sp.P0; $pc1 = $sp.P1
    # 12.8.1 (spec-1281 § A.10, decisions du 25/10/2026) : facteur de precompensation de cette ecriture
    # (Get-WriteFactorPlan : k mesure sur l image, sinon k du lecteur ; 12.10 : facteur 1 pour un lecteur cible), applique aux
    # profils des champs --precomp par ConvertTo-ScaledSpec (facteur 1 : profils identiques a l octet a ceux de la v12.8) ;
    # ecriture lente : champs des tetes physiques, donc avant le hswap ; rapide : facteur moyen des deux tetes sur le profil
    # commun. Lignes de journal avant « Ecriture lente : ... » (format inchange, profils mis a l echelle). Profils non mis a
    # l echelle gardes pour Test-LevelAdaptedSpec (compares aux enregistrements de la calibration rapide)
    $pc0Raw = $pc0; $pc1Raw = $pc1
    $wf = Get-WriteFactorPlan $txtWFile.Text $cmbWFmt.Text $slow $wfNext
    if ($wf.Apply) {
        if ($slow) {
            if ($pc0) { $pc0 = ConvertTo-ScaledSpec $pc0 $wf.F0 $wf.Hard }
            if ($pc1) { $pc1 = ConvertTo-ScaledSpec $pc1 $wf.F1 $wf.Hard }
        } elseif ($pc0) { $pc0 = ConvertTo-ScaledSpec $pc0 $wf.FMean $wf.Hard }
    }
    foreach ($wl in @($wf.Lines)) { Append-Log $wl }
    if (-not $slow -and $pc0) { $base += '--precomp'; $base += $pc0 }
    $base += Get-WriteFormatArgs
    $a = $base
    if ($userTs)      { $a += "--tracks=$userTs" }
    $a += "`"$($txtWFile.Text)`""
    $headPc = $null; $headPcRaw = $null
    $script:WriteQueue.Clear()
    # 12.8.2 : effacement haute frequence en tete de la file (Invoke-WriteQueueNext), avant toute ecriture. Revue 12.8.2 :
    # ecriture lente sur une disquette identique a l original (restauration, « Ecraser quand meme ») : chaque tete est
    # effacee juste avant son ecriture (un arret de gw n expose que la tete en cours ; Fail-Restore cite les pistes restees
    # effacees)
    $perHead = ($slow -and $script:Restore -and $script:Restore.OnOriginal -and @($eraseCmds).Count -gt 0)
    if (-not $perHead) { foreach ($ec in $eraseCmds) { $script:WriteQueue.Enqueue([string[]]$ec) } }
    if (@($eraseCmds).Count -gt 0) {
        Append-Log ((T "Effacement haute fréquence avant l'écriture (disquette double densité, lecteur {0}) : pistes {1}, puis écriture sans pré-effacement.") -f "$($cmbDrive.Text)", (Format-EraseTracks $eraseCmds))
        if ($perHead) { Append-Log (T "Écriture sur une disquette identique à l'original : chaque tête est effacée juste avant son écriture.") }
    }
    if ($slow) {
        # Ecriture lente : tete 0 sur tout le disque, puis tete 1 (gw applique --precomp par cylindre seulement).
        # Les champs correspondent aux tetes physiques (calibration) ; hswap : la tete logique h est ecrite par la tete 1 - h
        # (12.11, L10 : Get-WriteHeadSpecs)
        $headPc = Get-WriteHeadSpecs $userTs $pc0 $pc1; $headPcRaw = Get-WriteHeadSpecs $userTs $pc0Raw $pc1Raw
        foreach ($h in $heads) {
            if ($perHead) {
                $hk = @(@($eraseKeys) | Where-Object { ([string]$_ -split '\.')[1] -eq "$h" })
                foreach ($ec in (New-HfreqEraseCmds $hk (Get-TSpecExtras $userTs))) { $script:WriteQueue.Enqueue([string[]]$ec) }
            }
            $cmd = @($base); if ($headPc[$h]) { $cmd += '--precomp'; $cmd += $headPc[$h] }
            $script:WriteQueue.Enqueue([string[]]($cmd + @("--tracks=$(Set-TSpecHead $userTs $h)", "`"$($txtWFile.Text)`"")))
        }
        $none = (T 'aucune')
        Append-Log ((T "Écriture lente : {0} commande(s) gw write, tête 0 puis tête 1 ; precomp tête 0 : {1} ; tête 1 : {2}") -f "$($heads.Count)", "$(if ($headPc[0]) { $headPc[0] } else { $none })", "$(if ($headPc[1]) { $headPc[1] } else { $none })")
    }
    # Prechauffage de l ecriture lente (Start-WriteWarmup) : un cylindre sur 10 des pistes ecrites, tetes ecrites
    $warmTs = if ($slow) { Get-WriteWarmupTSpec $userTs ([int[]]$heads) $txtWFile.Text } else { $null }
    # 12.8 (FIX1C, constat 3, G1) : controle impose aussi quand un profil ecrit est la courbe adaptee d une calibration
    # rapide (bouton Calibrer au test rapide, puis ECRIRE sans nouvelle mesure), meme case decochee ; la ligne de journal
    # est celle de Complete-LevelCalib, ecrite ici quand le drapeau n a pas ete pose. 12.11 (L10) : controle decide par
    # Get-WriteCheckPlan (Post, ByCurve, Blocker), dont la ligne « Ce qui va se passer » tire aussi son segment
    $cp = Get-WriteCheckPlan $txtWFile.Text $cmbWFmt.Text ([bool]$slow) $heads $headPcRaw $pc0Raw ([bool]$postForce)
    if ($cp.ByCurve) { $postForce = $true; Append-Log (T 'Contrôle après écriture imposé : courbe adaptée à cette disquette.') }
    $post = [bool]$cp.Post
    $blocker = $cp.Blocker
    if ($blocker) {
        Append-Log ((T "Contrôle de toutes les pistes non applicable ({0}) : l'analyse de flux est calibrée pour le MFM double densité. Écriture sans contrôle.") -f "$blocker")
    }
    # 12.11 (L11) : barre de l onglet pendant l ecriture et son controle (Start-WriteProgress, 160) : plan des commandes de
    # l ecriture (file : effacements, ecritures par tete ; ou ecriture rapide), pose avant le lancement de la premiere ;
    # affichage seulement, file et commandes inchangees
    $wpCmds = @($script:WriteQueue.ToArray()); if (-not $slow) { $wpCmds += ,$a }
    Start-WriteProgress $wpCmds ([bool]($post -and -not $blocker))
    if ($post -and -not $blocker) {
        # Options de lecteur reprises par les relectures de controle (gw read les accepte toutes)
        $readOpts = @(Get-DriveReadArgs)
        New-WriteCheck $base $txtWFile.Text $userTs ([int]$numWRepair.Value) $readOpts $headPc $emCheck
        # 12.10 : ecriture pour un lecteur cible : le controle relit avec le lecteur qui a ecrit (pas de relecture par la
        # cible) ; reecritures gardees (les pistes faibles pour la source le sont tres probablement pour la cible) ; verdict
        # complete par Complete-WriteCheck (170)
        if ($tgtDrive) { $script:Rep.Target = $tgtDrive; $script:Rep.TargetSrc = [string]$cmbDrive.Text; Append-Log ((T "Contrôle après écriture pour le lecteur cible {0} : relecture par le lecteur {1}, pas par le lecteur cible ; les pistes faibles pour le lecteur {1} sont réécrites (elles le sont très probablement aussi pour le lecteur {0}).") -f "$tgtDrive", "$($cmbDrive.Text)") }
        if ($script:ImageUnstable) { $script:Rep.Ignore = $script:ImageUnstable }
        $script:Rep.SrcWeak = $script:ImageSrcWeak; $script:Rep.NoJudge = $script:ImageNoJudge; $script:Rep.SrcOver = $script:ImageSrcOver
        # SCP non analyse (module absent, restauration : voir Start-RestoreWrite) ou analyse en echec : rien n est juge
        if ([System.IO.Path]::GetExtension($txtWFile.Text).ToLower() -eq '.scp' -and ($script:ImageScpFailed -or ((-not $script:Restore) -and $null -eq $script:ImageNoJudge))) { $script:Rep.UnstDefect = $false }
        $script:Chain.Clear()
        # File WriteQueue : effacement haute frequence (12.8.2), puis en ecriture lente une ecriture par tete
        for ($i = 0; $i -lt $script:WriteQueue.Count; $i++) { $script:Chain.Enqueue({ Invoke-WriteQueueNext }) }
        if (-not $slow) { $script:WriteArgs = $a; $script:Chain.Enqueue({ Start-Gw $script:WriteArgs }) }
        $script:Chain.Enqueue({ Start-WriteCheck })
        if ($slow) { Start-WriteWarmup $warmTs ([bool]$NoWarmup) } else { Invoke-NextChainStep }
    } elseif ($slow) {
        $script:Chain.Clear()
        for ($i = 0; $i -lt $script:WriteQueue.Count; $i++) { $script:Chain.Enqueue({ Invoke-WriteQueueNext }) }
        if ($script:Restore) { $script:Chain.Enqueue({ Invoke-RestoreNext }) }   # restauration sans controle complet
        Start-WriteWarmup $warmTs ([bool]$NoWarmup)
    } elseif ($script:WriteQueue.Count -gt 0) {
        # 12.8.2 : ecriture rapide precedee de l effacement haute frequence (file WriteQueue), puis la restauration ;
        # etapes deja en attente gardees apres l ecriture, comme sans effacement
        $rest = if ($script:Restore) { @() } else { @($script:Chain.ToArray()) }
        $script:Chain.Clear()
        for ($i = 0; $i -lt $script:WriteQueue.Count; $i++) { $script:Chain.Enqueue({ Invoke-WriteQueueNext }) }
        $script:WriteArgs = $a; $script:Chain.Enqueue({ Start-Gw $script:WriteArgs })
        if ($script:Restore) { $script:Chain.Enqueue({ Invoke-RestoreNext }) }
        foreach ($s in $rest) { $script:Chain.Enqueue($s) }
        Invoke-NextChainStep
    } else {
        if ($script:Restore) { $script:Chain.Clear(); $script:Chain.Enqueue({ Invoke-RestoreNext }) }
        Start-Gw $a
    }
}

function Get-CalibState([string]$fam, [bool]$heads, [int]$nCyl = 0) {
    # Etat de la calibration utilisee par l ecriture rapide (courbe commune) ou lente (courbes par tete) :
    #  'ok'      : mesuree sur le motif de test (Method = 'motif') et, par tete, au moins aussi recente que la courbe
    #              commune : sinon Get-FamilyCurves applique la courbe commune aux deux tetes ;
    #  'content' : courbe anterieure au motif, mesuree sur le contenu d une image (biaisee) : refaite ;
    #  'stale'   : courbes par tete anterieures a la calibration commune ;
    #  'short'   : courbe plus courte que l image de nCyl cylindres (> 0) de plus de 4 cylindres (seuil de Get-LevelRef) :
    #              gw appliquerait la valeur de son dernier cylindre a tous les suivants ; refaite. Une courbe plus longue
    #              couvre l image (memes cylindres physiques) : conservee ;
    #  'none'    : absente ou incomplete.
    $keys = @(if ($heads) { "${fam}_h0", "${fam}_h1" } else { $fam })
    $missing = $false
    foreach ($k in $keys) {
        $cv = $script:PrecompCurves[$k]
        if (-not $cv) { $missing = $true } elseif ($cv.Method -ne 'motif') { return 'content' }
    }
    if ($missing) { return 'none' }
    if ($heads -and -not (Test-HeadCurvesCurrent $fam)) { return 'stale' }
    if ($nCyl -gt 0) { foreach ($k in $keys) { if (@($script:PrecompCurves[$k].Values).Count -lt $nCyl - 4) { return 'short' } } }
    return 'ok'
}

function Test-CalibCurrent([string]$fam, [bool]$heads) {
    # Calibration utilisable telle quelle par l ecriture rapide ou lente (voir Get-CalibState)
    return ((Get-CalibState $fam $heads) -eq 'ok')
}

function Set-WritePreset([string]$mode, [string]$path, [string]$source = '') {
    # Parametres d une ecriture rapide ou lente : image entiere, profil Auto, effacement avant l ecriture (case « Effacer
    # avant d ecrire » ; 12.8.2 : haute frequence en double densite, pre-effacement en haute densite), effacement des
    # pistes vides, verification gw, 10 essais, precomp transmise. Rapide : une commande pour les deux tetes, sans controle complet.
    # Lente : tete 0 puis tete 1 (profils par tete), controle de toutes les pistes, 3 passes de reecriture. Les options
    # de lecteur (flippy, densel, fake index, diskdefs, secteurs durs, TG43) decrivent le materiel : conservees, comme
    # les elements step, h0.off, h1.off et hswap du champ Pistes (seuls c= et h= sont retires : image entiere).
    # Format : ADF -> amiga.amigados, ou amiga.amigados_hd d apres la taille ; image secteur brute (IMG, IMA, ST, DSK
    # sans signature CPC) : format conserve si la meme source (fichier, ou entree d archive : deux ZIP peuvent extraire
    # le meme nom) est deja celle de l onglet Ecriture, sinon (auto) et Start-PresetWrite demande de le choisir ;
    # autres images : (auto), gw deduit le format.
    if (-not $source) { $source = $path }
    $same = ($txtWFile.Text -eq $path -and $script:PresetSource -eq $source)
    $txtWFile.Text = $path; $script:PresetSource = $source
    # 12.10 (relecture de la RC) : format pose sous la garde des liaisons : gestionnaires de la liste (520) sans effet,
    # l appelant recalcule le profil (Start-LibWrite, Start-RestoreWrite : Update-PrecompForImage) : plus de calcul du au
    # format (avant, la meme image reprise avec un autre format etait calculee une fois de plus : ligne « Profil precomp » en
    # double au journal) ; le profil et la case « Ecriture lente », poses plus bas hors de la garde, gardent leurs liaisons
    # (un calcul chacun quand ils changent, comme en 12.9)
    $sv = $script:SettingSync; $script:SettingSync = $true
    try {
        if ($path -match '\.adf$') { $cmbWFmt.SelectedItem = $(if (Test-AdfHd $path) { 'amiga.amigados_hd' } else { 'amiga.amigados' }) }
        elseif (-not ($same -and (Test-NeedsFormat $path))) { $cmbWFmt.SelectedIndex = 0 }
    } finally { $script:SettingSync = $sv }
    $cmbWProfile.SelectedIndex = 0
    # Faces de l image : effacement des pistes vides et h= d une image a une face (Get-FaceSafeWrite). 12.10 (lot 1,
    # E9-image, constat I-3) : calcul sorti dans Get-ImageFaces et Get-FaceSafeWrite, repris pour l image gardee a la fin
    # d une operation de la Bibliotheque (Merge-LibKeepState)
    $extras = Get-TSpecExtras $txtWTracks.Text
    $fc = Get-ImageFaces $path
    $fw = Get-FaceSafeWrite $fc ($mode -eq 'slow') $extras $true
    $chkWPreErase.Checked = $true; $chkWEraseEmpty.Checked = $fw.Empty; $chkWNoVerify.Checked = $false
    $numWRetries.Value = 10; $chkWPrecomp.Checked = $true
    $txtWTracks.Text = $fw.Tracks
    $chkWSlow.Checked = ($mode -eq 'slow')
    if ($mode -eq 'slow') {
        $chkWPostCheck.Checked = $true; $numWRepair.Value = 3
        Append-Log (T "Écriture lente : image entière, profil Auto, effacement avant l'écriture (haute fréquence en double densité, pré-effacement en haute densité), effacement des pistes vides, vérification gw, 10 essais, tête 0 puis tête 1, contrôle de toutes les pistes, 3 passes de réécriture.")
    } else {
        $chkWPostCheck.Checked = $false
        Append-Log (T "Écriture rapide : image entière, profil Auto, effacement avant l'écriture (haute fréquence en double densité, pré-effacement en haute densité), effacement des pistes vides, vérification gw, 10 essais, les deux têtes ensemble, sans contrôle complet des pistes.")
        if ($null -ne $fw.Head) { Append-Log ((T "Image à une seule face : seule la tête {0} est écrite (h={0} dans Pistes).") -f "$($fw.Head)") }
    }
    if ($fc.Unknown) { Append-Log (T "Nombre de faces de l'image inconnu : effacement des pistes vides désactivé (seules les pistes présentes dans l'image sont écrites).") }
    if ($extras) { Append-Log ((T "Champ Pistes : éléments de lecteur conservés ({0}).") -f $extras.TrimStart(':')) }
}

function Get-FaceSafeWrite($faces, [bool]$slow, [string]$extras, [bool]$empty) {
    # 12.10 (lot 1, E9-image, constat I-3) : reglages de securite des faces d une image (faces : Get-ImageFaces), communs a
    # Set-WritePreset et a l image gardee apres la Bibliotheque (Merge-LibKeepState). Faces inconnues -> pas d effacement
    # des pistes vides, qui effacerait la face 1 d une image simple face (gw n ecrit alors que les pistes presentes) ; une
    # seule face en ecriture rapide -> h= de cette face dans Pistes (en lente, Start-ImageWrite n ecrit deja que les faces
    # de l image). extras : elements de lecteur du champ Pistes (Get-TSpecExtras) ; empty : effacement voulu sinon.
    # Renvoie @{ Tracks : champ Pistes ; Empty : effacement des pistes vides ; Head : tete de h= pose, $null sinon }
    $r = @{ Tracks = "$extras".TrimStart(':'); Empty = ($empty -and -not $faces.Unknown); Head = $null }
    if (-not $slow -and $null -ne $faces.OneHead) { $r.Head = $faces.OneHead; $r.Tracks = "h=$($faces.OneHead)" + "$extras" }
    return $r
}

# --- Surcharge d operation (12.8, D4) -------------------------------------------
# Une ecriture depuis la Bibliotheque applique son prereglage aux controles de l onglet Ecriture (Set-WritePreset), le
# temps de l operation seulement : l etat d avant (Save-WriteTabState) est ecrit a sa place dans la configuration
# (Save-Config, Set-OpOverrideConfig), puis retabli quand plus rien ne tourne (Update-OpOverride, minuteur principal).
# 12.7 : le prereglage devenait la configuration de l onglet Ecriture. 12.8, lot 2 : la restauration passe aussi par
# cette surcharge (Kind 'restore', Started jamais pose : seule Close-Restore la termine). 12.10 (lot 1, E9-image,
# decisions E9-1 a E9-3) : operation de la Bibliotheque lancee : l onglet garde l image de l operation (Save-LibKeepImg,
# Merge-LibKeepState), dans l onglet comme dans la configuration ; le reste du prereglage reste temporaire.
# 12.10 (lot 1, R1-corrections-revue, constat d) : image gardee seulement si elle a ete ecrite (Written, pose par Start-Gw
# au premier gw write de l image, Set-LibImageWritten) : un arret pendant la calibration, la mesure ou le prechauffage
# retablit tout (E9-2). Constat e : Start-LibWrite refuse une seconde operation tant que la surcharge est active.

function Enter-OpOverride([string]$kind) {
    # Surcharge deja active (operation precedente non terminee) : l etat d origine est garde
    # Finalisation 12.10 : Refused, ecriture pour un lecteur cible refusee pendant l operation (Test-TargetWriteAllowed),
    # pour l avis de fin de la Bibliotheque (Show-LibEndNotice)
    if ($script:OpOverride) { $script:OpOverride.Stopped = $false; $script:OpOverride.Refused = $false; return }
    $script:OpOverride = @{ Kind = $kind; Saved = (Save-WriteTabState); Started = $false; Written = $false; Stopped = $false; Refused = $false }
}

function Exit-OpOverride([switch]$Keep) {
    # Fin de la surcharge : onglet Ecriture retabli et configuration enregistree. Keep : prereglage garde dans l onglet,
    # sans rien retablir (image secteur dont le format est a choisir dans l onglet Ecriture, comme en 12.7)
    $o = $script:OpOverride
    if (-not $o) { return }
    $script:OpOverride = $null
    if ($Keep) { return }
    $opImg = $txtWFile.Text                                   # image de l operation, avant le retour de celle de l onglet
    # 12.10 (lot 1, E9-image) : Bibliotheque : image de l operation gardee si elle a ete ecrite (Merge-LibKeepState ;
    # R1, constat d : Written, et non plus Started)
    $m = if ($o.Kind -eq 'library') { Merge-LibKeepState $o.Saved $o.KeepImg ([bool]$o.Written) } else { $null }
    Restore-WriteTabState $(if ($m) { $m.State } else { $o.Saved })
    # Restauration (12.8, lot 2) : reglages retablis sans ligne de journal, comme en 12.7
    if ($o.Kind -eq 'library') { Show-LibEndNotice $o $opImg $m }
    [void](Save-Config)
}

function Save-LibKeepImg {
    # 12.10 (lot 1, E9-image) : apres Set-WritePreset (Start-LibWrite) : image de l operation de la Bibliotheque, son format,
    # sa source et ses faces (Get-ImageFaces), memorises dans la surcharge pour Merge-LibKeepState
    $o = $script:OpOverride
    if (-not $o -or $o.Kind -ne 'library') { return }
    # 12.10 (lot 1, R1-corrections-revue, constat b) : entree d une archive ZIP (source « archive|entree ») : fichier extrait
    # dans TempDir sous le nom de l entree, qu une autre archive peut remplacer : Archive, image jamais gardee (tout
    # retabli, comme en 12.8), dit par l avis de fin (Show-LibEndNotice)
    $o.KeepImg = @{ File = $txtWFile.Text; Fmt = $cmbWFmt.Text; Source = $script:PresetSource; Faces = (Get-ImageFaces $txtWFile.Text)
                    Archive = "$($script:PresetSource)".Contains('|') }
}

function Set-LibImageWritten([string[]]$gwArgs) {
    # 12.10 (lot 1, R1-corrections-revue, constat d) : Start-Gw, avant le lancement : commande gw write de l image memorisee
    # de l operation de la Bibliotheque (Save-LibKeepImg ; le motif de calibration et la mesure s ecrivent depuis TempDir)
    # -> Written. Renvoie vrai si cette commande l a pose, pour le retirer si gw ne demarre pas
    $o = $script:OpOverride
    if (-not $o -or $o.Kind -ne 'library' -or $o.Written -or -not $o.KeepImg) { return $false }
    if ($gwArgs.Count -eq 0 -or $gwArgs[0] -ne 'write' -or $gwArgs -notcontains "`"$($o.KeepImg.File)`"") { return $false }
    $o.Written = $true
    return $true
}

function Merge-LibKeepState($saved, $keep, [bool]$written) {
    # 12.10 (lot 1, E9-image, decisions E9-1 (a) et E9-2) : etat de l onglet Ecriture a la fin d une operation de la
    # Bibliotheque (Restore-WriteTabState), et a sa place dans la configuration pendant l operation (E9-3). Image ecrite
    # (written : R1, constat d) et memorisee (keep, Save-LibKeepImg) : image, format et source de l operation gardes ; champ
    # Pistes de l onglet d avant sans c= ni h=, qui visaient l image precedente ; le reste retabli de l onglet d avant (saved).
    # Constat I-3 : effacement des pistes vides et h= d une image a une face recalcules pour l image gardee, dans le mode
    # de l onglet d avant (Get-FaceSafeWrite, comme Set-WritePreset) : sinon ECRIRE pourrait effacer la face 1. Non ecrite
    # (refus, calibration annulee ou arretee) : tout retabli. R1, constat b : entree d archive ZIP (keep.Archive) : tout
    # retabli, Archive vrai si l image a ete ecrite. R1, constat c : l onglet d avant avait deja cette image et cette source :
    # son champ Pistes est garde (c= et h= visent la meme image), securite des faces seule (h= ajoute s il n en a pas).
    # Renvoie @{ State : etat a retablir ; Kept : image gardee ; Cut : c= et h= retires du champ d avant ; Head : tete de
    # h= pose, $null sinon ; EmptyOff : effacement des pistes vides de l onglet d avant desactive (faces inconnues) ;
    # Archive : image ecrite d une archive ZIP, non gardee }
    $r = @{ State = $saved; Kept = $false; Cut = ''; Head = $null; EmptyOff = $false; Archive = $false }
    if (-not $written -or -not $keep -or -not $saved) { return $r }
    if ($keep.Archive) { $r.Archive = $true; return $r }
    $s = $saved.Clone()
    $s.File = $keep.File; $s.Fmt = $keep.Fmt; $s.Source = $keep.Source
    # Meme image : meme fichier et meme source (source vide : onglet relu de la configuration, qui ne garde pas la source ;
    # une entree d archive est deja ecartee ci-dessus)
    # 12.10 (lot 1, revue2, R-4) : source comparee seulement si celle de l onglet d avant designe une entree d archive ou
    # une restauration (« | ») : hors archive, la source est le chemin du fichier (Resolve-LibSelection, Parcourir), et
    # une saisie a la main du chemin ne la met pas a jour. Entree d archive ou restauration dans l onglet d avant : pas la
    # meme image (keep.Source n a pas de « | » ici)
    $same = ("$($saved.File)" -eq "$($keep.File)" -and -not "$($saved.Source)".Contains('|'))
    if ($same) {
        $t = "$($saved.Tracks)"
        $hasH = [regex]::IsMatch(":$t", ':\s*h\s*=')
        $fw = Get-FaceSafeWrite $keep.Faces ([bool]$saved.Slow) '' ([bool]$saved.Empty)
        if ($null -ne $fw.Head -and -not $hasH) { $t = if ($t.Trim()) { "h=$($fw.Head):$($t.Trim())" } else { "h=$($fw.Head)" } }
        else { $fw.Head = $null }
        # 12.10 (lot 1, revue2, R-3) : h= explicite garde dans le champ Pistes : gw n ecrit et n efface que les pistes des
        # faces choisies, l effacement des pistes vides de l onglet d avant est garde meme si les faces sont inconnues
        if ($hasH) { $fw.Empty = [bool]$saved.Empty }
        $s.Tracks = $t; $s.Empty = $fw.Empty
    } else {
        $fw = Get-FaceSafeWrite $keep.Faces ([bool]$saved.Slow) (Get-TSpecExtras "$($saved.Tracks)") ([bool]$saved.Empty)
        $s.Tracks = $fw.Tracks; $s.Empty = $fw.Empty
        $r.Cut = Get-TSpecCH "$($saved.Tracks)"
    }
    $r.State = $s; $r.Kept = $true; $r.Head = $fw.Head
    $r.EmptyOff = ([bool]$saved.Empty -and -not $fw.Empty)
    return $r
}

function Get-WriteModeText($s) {
    # 12.10 (lot 1, E9-image) : mode d ecriture d un etat de l onglet Ecriture (Save-WriteTabState), pour l avis de fin de
    # la Bibliotheque
    $t = if ($s.Slow) { (T 'écriture lente') } else { (T 'écriture rapide') }
    if ($s.Post) { $t += (T ', contrôle de toutes les pistes') }
    return $t
}

function Show-LibEndNotice($o, [string]$opImg, $m = $null) {
    # 12.8 (FIX-PISTES, essai du 21/10/2026) : fin d une operation de la Bibliotheque, terminee ou arretee (Stopped : bouton
    # Arreter) : l onglet Ecriture a repris SON image et SON champ Pistes (D4). Ligne de journal et avis a cote du bouton
    # ECRIRE (Set-WTabNotice), qui nomment l image retablie ; apres un arret, comment reprendre : depuis la Bibliotheque,
    # le bouton ECRIRE ecrivant l image de l onglet
    # 12.10 (lot 1, E9-image) : operation lancee (m.Kept, Merge-LibKeepState) : l onglet garde l image de l operation, avec
    # ses autres reglages ; lignes de journal du retrait de c= et h= et de la securite des faces (constat I-3), reprises
    # dans l avis. Non lancee : textes de la 12.8 (tout retabli)
    if ($m -and $m.Kept) {
        $k = $m.State
        $img = if ("$($k.File)".Trim()) { [System.IO.Path]::GetFileName("$($k.File)") } else { (T '(aucune image)') }
        $md = Get-WriteModeText $k
        $fx = ''
        if ($null -ne $m.Head) { $fx += (T " ; h={0} dans le champ Pistes (image à une seule face)") -f "$($m.Head)" }
        if ($m.EmptyOff) { $fx += (T " ; effacement des pistes vides désactivé (faces de l'image inconnues)") }
        if ($o.Stopped) {
            Append-Log ((T "Bibliothèque : opération arrêtée. L'onglet Écriture garde l'image de l'opération, {0} ; ses autres réglages sont rétablis ({1}) et le préréglage de la Bibliothèque n'est pas enregistré. L'écriture de {0} n'est peut-être pas complète : pour la reprendre avec le préréglage de la Bibliothèque, relancez-la depuis la Bibliothèque ; le bouton ÉCRIRE LA DISQUETTE l'écrirait avec les réglages de l'onglet Écriture.") -f "$img", "$md")
        } else {
            Append-Log ((T "Bibliothèque : opération terminée. L'onglet Écriture garde l'image de l'opération, {0} ; ses autres réglages sont rétablis ({1}) et le préréglage de la Bibliothèque n'est pas enregistré.") -f "$img", "$md")
        }
        if ($m.Cut) {
            # Image precedente nommee si l onglet en avait une
            if ("$($o.Saved.File)".Trim()) { Append-Log ((T "Champ Pistes : « {0} » retiré, il visait l'image précédente ({1}).") -f "$($m.Cut)", "$([System.IO.Path]::GetFileName("$($o.Saved.File)"))") }
            else { Append-Log ((T "Champ Pistes : « {0} » retiré, il visait l'image précédente.") -f "$($m.Cut)") }
        }
        if ($null -ne $m.Head) { Append-Log ((T "Image {0} à une seule face : h={1} placé dans le champ Pistes, le bouton ÉCRIRE LA DISQUETTE n'écrit que la tête {1}.") -f "$img", "$($m.Head)") }
        if ($m.EmptyOff) { Append-Log ((T "Nombre de faces de {0} inconnu : effacement des pistes vides désactivé dans l'onglet Écriture (il effacerait la face 1 d'une image à une seule face).") -f "$img") }
        if ($o.Stopped) {
            Set-WTabNotice ((T "Bibliothèque arrêtée : l'image {0} n'est peut-être pas entièrement écrite ; pour reprendre, relancez l'écriture depuis la Bibliothèque. Onglet Écriture : vos réglages d'écriture ({1}){2}.") -f "$img", "$md", "$fx")
        } else {
            Set-WTabNotice ((T "Bibliothèque terminée : l'image {0} reste dans l'onglet Écriture, avec vos réglages d'écriture ({1}){2}.") -f "$img", "$md", "$fx")
        }
        return
    }
    $s = $o.Saved
    $tab = if ("$($s.File)".Trim()) { [System.IO.Path]::GetFileName("$($s.File)") } else { (T '(aucune image)') }
    $trk = if ("$($s.Tracks)".Trim()) { (T ", champ Pistes « {0} »") -f "$("$($s.Tracks)".Trim())" } else { '' }
    $op = if ("$opImg".Trim()) { [System.IO.Path]::GetFileName("$opImg") } else { (T '(aucune image)') }
    # 12.10 (lot 1, R1-corrections-revue, constat b) : image ecrite d une archive ZIP, non gardee (Merge-LibKeepState) :
    # ligne de journal en plus, avis qui le dit. Finalisation 12.10 : ecriture pour un lecteur cible refusee (Refused, pose par
    # Test-TargetWriteAllowed) : rien n a ete lance, journal et avis le disent (avant : operation terminee)
    $arc = ($m -and $m.Archive)
    if ($o.Refused) {
        Append-Log ((T "Bibliothèque : écriture refusée, réglages de l'onglet Écriture rétablis (le préréglage de la Bibliothèque n'est pas enregistré) : {0}{1}.") -f "$tab", "$trk")
    } elseif ($o.Stopped) {
        Append-Log ((T "Bibliothèque : opération arrêtée, réglages de l'onglet Écriture rétablis (le préréglage de la Bibliothèque n'est pas enregistré) : {0}{1}. Pour reprendre l'écriture de {2}, relancez-la depuis la Bibliothèque : le bouton ÉCRIRE LA DISQUETTE écrit l'image de l'onglet Écriture.") -f "$tab", "$trk", "$op")
    } else {
        Append-Log ((T "Bibliothèque : opération terminée, réglages de l'onglet Écriture rétablis (le préréglage de la Bibliothèque n'est pas enregistré) : {0}{1}.") -f "$tab", "$trk")
    }
    if ($arc) { Append-Log ((T "Image {0} extraite d'une archive ZIP : l'onglet Écriture ne la garde pas, son fichier extrait est temporaire et une autre archive peut le remplacer. Pour l'écrire de nouveau, relancez-la depuis la Bibliothèque.") -f "$op") }
    if ($o.Refused) { Set-WTabNotice ((T "Bibliothèque : écriture refusée. Onglet Écriture rétabli : {0}{1}.") -f "$tab", "$trk") }
    elseif ($o.Stopped) {
        if ($arc) { Set-WTabNotice ((T "Bibliothèque arrêtée : l'image {0}, extraite d'une archive ZIP, n'est pas gardée dans l'onglet Écriture ; pour reprendre, relancez l'écriture depuis la Bibliothèque. Onglet Écriture rétabli : {1}{2}.") -f "$op", "$tab", "$trk") }
        else { Set-WTabNotice ((T "Bibliothèque arrêtée : pour reprendre, relancez l'écriture depuis la Bibliothèque. Onglet Écriture rétabli : {0}{1}.") -f "$tab", "$trk") }
    } else {
        if ($arc) { Set-WTabNotice ((T "Bibliothèque terminée : l'image {0}, extraite d'une archive ZIP, n'est pas gardée dans l'onglet Écriture. Onglet Écriture rétabli : {1}{2}.") -f "$op", "$tab", "$trk") }
        else { Set-WTabNotice ((T "Bibliothèque terminée. Onglet Écriture rétabli : {0}{1}.") -f "$tab", "$trk") }
    }
}

function Set-WTabNotice([string]$text) {
    # 12.8 (FIX-PISTES) : avis dans le libelle a cote du bouton ECRIRE (lblWProfileInfo), a l encre du niveau warn de
    # frmConfirm, coupe par des points de suspension (texte complet en infobulle) ; libelle rendu a son style des qu il
    # prend un autre texte (TextChanged : profil d une autre image, calibration...)
    $script:WTabNotice = $text
    $lblWProfileInfo.AutoEllipsis = $true
    $lblWProfileInfo.ForeColor = [System.Drawing.Color]::FromArgb(138, 74, 0)
    $lblWProfileInfo.Text = $text
}

function Clear-WTabNotice {
    if (-not $script:WTabNotice -or $lblWProfileInfo.Text -eq $script:WTabNotice) { return }
    $script:WTabNotice = $null
    # 12.10 (relecture des captures) : points de suspension gardes (520 : tout texte de plus de deux lignes), encre grise
    $lblWProfileInfo.ForeColor = [System.Drawing.Color]::DimGray
}

function Update-WProfileTip {
    # 12.10 (relecture des captures) : texte complet du libelle du profil en infobulle quand il depasse ses deux lignes,
    # aucune infobulle sinon (texte, avis de la Bibliotheque ou largeur changes : 520). L infobulle propre d un Label a
    # points de suspension ne vient pas ici : sa mesure est bornee a la taille du libelle (40 px de haut au plus) ; hauteur
    # mesuree ici a la largeur du libelle, sans borne. 12.11 (L9) : trois lignes, 58 px de haut
    $h = $lblWProfileInfo.GetPreferredSize((New-Object System.Drawing.Size($lblWProfileInfo.Width, 0))).Height
    $tip.SetToolTip($lblWProfileInfo, $(if ($h -gt $lblWProfileInfo.Height) { [string]$lblWProfileInfo.Text } else { '' }))
}

function Update-WCalTip {
    # 12.10 (relecture de la RC) : texte complet du libelle de calibration de l onglet Ecriture ($lblWCal, 520 : une ligne a
    # largeur fixe, points de suspension) en infobulle quand il depasse la largeur du libelle (marge de l icone du verdict
    # comprise), aucune infobulle sinon ; appelee au changement de texte, de taille, de police et de marge (520)
    $tip.SetToolTip($lblWCal, $(if ($lblWCal.PreferredWidth -gt $lblWCal.Width) { [string]$lblWCal.Text } else { '' }))
}

function Get-WProfileText {
    # 12.8 (FIX-PISTES-2) : texte du profil de lblWProfileInfo pour les copies d etat des calibrations (Get-CalibSnapshot,
    # champs d avant une calibration rapide) ; $null quand le libelle porte l avis de fin de la Bibliotheque
    # (Set-WTabNotice) : apres un refus, Update-PrecompForImage pose le texte du profil, l avis n est pas repris
    if ($script:WTabNotice -and $lblWProfileInfo.Text -eq $script:WTabNotice) { return $null }
    return $lblWProfileInfo.Text
}

function Test-OpIdle {
    # Rien ne tourne (gw, etapes, calibration, calibration B, controle, prechauffage, detection, restauration ; la mesure
    # continue de l onglet Qualite n est pas une suite de l operation) et aucune fenetre modale n est ouverte
    if ($script:GwProc -or $script:Cal -or $script:CalRedo -or $script:LevelFieldsPending) { return $false }
    if (@('', 'quality') -notcontains (Get-AppBusy)) { return $false }
    return (@([System.Windows.Forms.Application]::OpenForms | Where-Object { $_.Modal -and $_.Visible -and -not [object]::ReferenceEquals($_, $form) }).Count -eq 0)
}

function Update-OpOverride([bool]$gwDone) {
    # Minuteur principal : fin de l operation surchargee. Verifiee juste apres le traitement de la fin d une commande gw
    # (gwDone), ou a tout autre tick si la fenetre principale peut recevoir le focus (aucune boite de message ouverte)
    $o = $script:OpOverride
    if (-not $o -or -not $o.Started) { return }
    if (-not (Test-OpIdle)) { return }
    if (-not $gwDone -and -not $form.CanFocus) { return }
    Exit-OpOverride
}

function Set-OpOverrideConfig($cfg) {
    # Save-Config pendant une operation surchargee : reglages de l onglet Ecriture d avant l operation. 12.10 (lot 1,
    # E9-image, decision E9-3) : operation de la Bibliotheque lancee : image de l operation, comme a sa fin (Merge-LibKeepState ;
    # R1, constat d : des le premier gw write de l image, Written pose par Start-Gw avant son Save-Config)
    $o = $script:OpOverride; $s = $o.Saved; $w = $cfg['write']
    if ($o.Kind -eq 'library') { $s = (Merge-LibKeepState $s $o.KeepImg ([bool]$o.Written)).State }
    $w['file'] = [string]$s.File; $w['format'] = [string]$s.Fmt; $w['preErase'] = [bool]$s.Pre; $w['eraseEmpty'] = [bool]$s.Empty
    $w['noVerify'] = [bool]$s.NoVer; $w['retries'] = [int]$s.Retries; $w['precompOn'] = [bool]$s.Precomp; $w['precomp'] = [string]$s.P0
    $w['precomp1'] = [string]$s.P1; $w['tracks'] = [string]$s.Tracks; $w['postCheck'] = [bool]$s.Post; $w['repairMax'] = [int]$s.Repair
    $w['slowWrite'] = [bool]$s.Slow; $w['calMode'] = [int][math]::Max(0, [int]$s.CalMode)
    $codes = $script:SettingDefs['precompProfile'].Codes
    $pc = $codes[[math]::Max(0, [math]::Min($codes.Count - 1, [int]$s.Profile))]
    $w['precompProfileCode'] = $pc; $w['precompProfile'] = Get-SettingText 'precompProfile' $pc
}

function Start-PresetWrite([string]$mode, [switch]$NoCalib, [switch]$LevelOnly) {
    # Calibration automatique si elle manque pour la famille de l image (commune en rapide, par tete en lente), puis
    # ecriture. Ecriture directe, sans calibration automatique : flux ecrit tel quel (sans --format, gw ne lui applique
    # pas la precompensation), image haute densite (12.7 : famille hd calibrable : sa courbe si elle existe, sinon le
    # profil d origine haute densite, jamais de calibration automatique), secteurs durs ou lecteur 8 pouces, densite non
    # etablie (conteneur a geometrie libre : IMD, TD0, D88, D64... ; IPF ou HFE dont la cellule sort des plages
    # mesurables), module d analyse SCP indisponible. NoCalib (restauration) : la calibration existante est conservee,
    # jamais refaite.
    $img = $txtWFile.Text
    if (-not $img -or -not (Test-Path -LiteralPath $img)) {
        [void](Show-AppMessage (T 'Fichier image introuvable.') (T 'Erreur') 'OK' 'Warning'); return
    }
    $ext = [System.IO.Path]::GetExtension($img).ToLower()
    $fmt = $cmbWFmt.Text
    $explicit = ($fmt -and $fmt -ne '(auto)')
    if ((Test-NeedsFormat $img) -and -not $explicit) {
        # Avant toute calibration : gw refuserait l ecriture apres coup (« Sector image requires a disk format »)
        [void](Show-AppMessage ((T "Image secteur sans géométrie ({0}) : gw exige le format.`nChoisir le format dans l'onglet Écriture, puis relancer l'écriture.") -f "$ext") (T 'Format requis') 'OK' 'Warning'); return
    }
    # 12.10 (relecture de l etape 3) : lecteur cible choisi (Get-TargetWriteInfo) ; ecriture refusee (haute densite, aucune
    # courbe croisee de la famille, courbes croisees par tete en ecriture rapide) : refus de Start-ImageWrite
    # (Test-TargetWriteAllowed) avant toute ligne de calibration ou de mesure (avant : la branche haute densite disait la
    # calibration appliquee, puis l ecriture etait refusee)
    $tw = Get-TargetWriteInfo $img $fmt ($mode -eq 'slow')
    if ($tw.Block) { Start-ImageWrite; return }
    if (@('.scp', '.raw', '.kf', '.a2r', '.ctr') -contains $ext) {
        # 12.8 (S3-FLUX, decision 2) : aucune mesure avant l ecriture d une image flux ; ligne de journal quand une mesure
        # aurait ete faite pour une image calibrable (test rapide, ou case « Mesurer la disquette » en ecriture lente) ;
        # restauration : ligne de Start-RestoreWrite
        if (-not $script:Restore -and ($cmbWCalMode.SelectedIndex -eq 2 -or (Test-WriteLevelWanted $mode))) { Write-FluxLevelSkip $img $fmt }
        Start-ImageWrite; return
    }
    # 12.10 (lot 1, B1) : image FM, GCR ou a codage propre (Get-ImageEncoding : format, extension ou en-tete, HFE FM
    # compris) : ni calibration ni mesure, elles ne mesurent que le MFM ; Start-ImageWrite ne transmet pas --precomp
    if (Test-NonMfmWrite $img $fmt) { Write-NonMfmSkip $img $fmt; Start-ImageWrite; return }
    $hd = Get-HighDensityReason $img $fmt
    if ($hd) {
        # 12.7 : haute densite calibrable (hd) : courbe de la famille appliquee par le mode Auto si elle existe, profil
        # d origine sinon ; jamais de calibration automatique ni de test rapide avant l ecriture (bareme haute densite
        # provisoire). Haute densite non calibrable : comme en 12.6.
        $hf = Get-HdCalibFamily $img $fmt
        if (-not $hf) { Append-Log ((T "Image haute densité ({0}) : pas de calibration automatique, écriture avec le profil courant.") -f "$hd"); Start-ImageWrite; return }
        $heads = ($mode -eq 'slow')
        $kind = if ($heads) { (T 'par tête') } else { (T 'commune') }
        $nc = (Get-CalibCylinders $img $fmt).NCyl
        $nc = if ($null -eq $nc) { 80 } else { [math]::Max(2, [math]::Min(84, [int]$nc)) }
        $st = Get-CalibState $hf $heads $nc
        $k0 = if ($heads) { "${hf}_h0" } else { $hf }
        $af = Get-HdAutoFields $hf $heads
        $pt = if ($af.P0 -eq $af.P1) { $af.P0 } else { (T "tête 0 : {0} ; tête 1 : {1}") -f "$($af.P0)", "$($af.P1)" }
        if ($st -eq 'ok') { Append-Log ((T "Image haute densité ({0}) : calibration {1} de la famille {2} du {3} appliquée par le mode Auto ; jamais de calibration automatique en haute densité.") -f "$hd", "$kind", (Get-CalibFamilyName $hf), "$($script:PrecompCurves[$k0].Date)") }
        else {
            # Ecriture lente sans courbes par tete, courbe commune presente : la courbe commune est ecrite pour les deux tetes
            $hcv = if ($heads) { Get-HdCommonCurve $hf } else { $null }
            $why = switch ($st) { 'stale' { (T 'courbes par tête antérieures à la courbe commune') } 'short' { (T "courbe plus courte que l'image de {0} cylindres") -f "$nc" } default { if ($hcv) { (T "aucune courbe par tête : courbe commune du {0} pour les deux têtes") -f "$($hcv.Date)" } else { (T 'aucune courbe') } } }
            Append-Log ((T "Image haute densité ({0}) : pas de calibration {1} à jour pour la famille {2} ({3}) : écriture avec le profil {4}, sans calibration automatique (jamais en haute densité). Pour calibrer : carte « Calibrer le lecteur » de l'Accueil, ou bouton « Calibrer » de l'onglet Écriture, avec une disquette haute densité sacrifiée.") -f "$hd", "$kind", (Get-CalibFamilyName $hf), "$why", "$pt")
        }
        if (Test-WriteLevelWanted $mode) { Write-LevelHdNote $hf $heads }    # 12.7 point 5 : pas de mesure en haute densite
        Start-ImageWrite; return
    }
    if ($chkWHard.Checked -or $chkWTG43.Checked) { Append-Log (T 'Secteurs durs ou lecteur 8 pouces (TG43) : pas de calibration automatique, écriture avec le profil courant.'); Start-ImageWrite; return }
    # Format gw explicite de la table non calibrable (FM, codage propre, secteurs durs, 360 tr/min, cellule hors plage :
    # Get-FormatCalibInfo, memes regles que la carte Calibration de l Accueil) : pas de calibration automatique ; GCR :
    # ligne « densite non etablie » ci-dessous, inchangee
    $fci = if ($explicit -and $script:GwFormats.Contains($fmt)) { Get-FormatCalibInfo $fmt } else { $null }
    if ($fci -and -not $fci.Cal -and $fmt -notmatch '^(commodore\.15[47]1|mac\.|apple2\.)') { Append-Log ((T "Format {0} non calibrable ({1}) : pas de calibration automatique, écriture avec le profil courant.") -f "$fmt", "$($fci.Why)"); Start-ImageWrite; return }
    $ddKnown =(@('.adf', '.ipf', '.hfe') -contains $ext) -or ($explicit -and $fmt -notmatch '^(commodore\.15[47]1|mac\.|apple2\.)')
    if (-not $ddKnown) { Append-Log ((T "Densité de l'image non établie ({0}, format déduit par gw) : pas de calibration automatique, écriture avec le profil courant.") -f "$ext"); Start-ImageWrite; return }
    $oor = Get-CellOutOfRange $img
    if ($null -ne $oor) { Append-Log ((T "Cellule de l'image hors des plages mesurables ({0} ns ; 900 à 1 100 ns en haute densité, 1 700 à 2 300 ns en double densité) : pas de calibration automatique, écriture avec le profil courant.") -f "$oor"); Start-ImageWrite; return }
    if (-not $script:ScpStatsOk) { Append-Log (T "Module d'analyse SCP indisponible : pas de calibration automatique, écriture avec le profil courant."); Start-ImageWrite; return }
    # 12.10 : lecteur cible choisi, avec effet sur cette ecriture (Get-TargetWriteInfo) : ni calibration automatique, ni test
    # rapide, ni mesure de la disquette (ils reliraient avec le lecteur du bandeau) : ecriture avec la courbe croisee telle
    # quelle (refus : plus haut, $tw)
    if ($tw.Applies) { Append-Log ((T "Écriture pour le lecteur cible {0} : ni calibration automatique ni mesure de la disquette (elles reliraient avec le lecteur {1}) ; écriture avec la courbe croisée telle quelle.") -f "$($tw.Tgt)", "$($cmbDrive.Text)"); Start-ImageWrite; return }
    if ($NoCalib) {
        if ($LevelOnly) {
            # 12.7 point 5 (arbitrage 15) : mesure exclue quand l image ne recouvrirait pas tout le motif. 12.8 (D5) : avec la
            # liste au test rapide aussi (LevelOnly : restauration avec la case cochee ou la liste au test rapide) :
            # cylindres preserves (c= du champ Pistes), image a une seule face, step=
            $sk = Get-LevelWriteSkip $img $fmt $txtWTracks.Text
            if ($sk) { if ($sk.Why) { Append-Log $sk.Why }; Start-ImageWrite; return }
            Start-LevelBeforeWrite $mode -Restore; return
        }
        Start-ImageWrite; return
    }
    # Test rapide : niveau mesure sur la disquette a ecrire, sur la forme de la calibration complete du lecteur. 12.8 (D5) :
    # memes exclusions que le bouton ECRIRE (Get-LevelWriteSkip : une seule face, h= pose par Set-WritePreset ; c=, step=)
    if ($cmbWCalMode.SelectedIndex -eq 2) {
        $sk = Get-LevelWriteSkip $img $fmt $txtWTracks.Text
        if ($sk) { if ($sk.Why) { Append-Log $sk.Why }; Start-ImageWrite; return }
        Start-LevelBeforeWrite $mode; return
    }
    $fam = Get-ImageFamily $img
    $heads = ($mode -eq 'slow')
    # Cylindres de l image, comme la calibration les prendrait (Test-CalibImage) : courbe plus courte refaite ('short')
    $imgCyl = (Get-CalibCylinders $img $fmt).NCyl
    $imgCyl = if ($null -eq $imgCyl) { 80 } else { [math]::Max(2, [math]::Min(84, [int]$imgCyl)) }
    $state = Get-CalibState $fam $heads $imgCyl
    $kind = if ($heads) { (T 'par tête') } else { (T 'commune') }
    if ($state -eq 'ok') {
        # Courbe non convergee gardee apres un « Annuler » : reutilisee, mais signalee
        $nc = @(@($(if ($heads) { @("${fam}_h0", "${fam}_h1") } else { @($fam) })) | Where-Object { $script:PrecompCurves[$_] -and $script:PrecompCurves[$_].Converged -eq $false })
        $kc = @(@($(if ($heads) { @("${fam}_h0", "${fam}_h1") } else { @($fam) })) | Where-Object { $script:PrecompCurves[$_] -and (Get-CurveCalc $script:PrecompCurves[$_]) -ne (Get-CurveCalcRef $script:PrecompCurves[$_]) })
        if ($kc.Count -gt 0) { Append-Log ((T "Calibration {0} de la famille {1} faite avec le calcul {2} : écriture avec cette courbe, conservée à votre demande. Pour la refaire avec le calcul actuel, bouton « Calibrer » de l'onglet Écriture.") -f "$kind", (Get-CalibFamilyName $fam), (Get-CurveCalcText $script:PrecompCurves[$kc[0]] -Plain)) }
        if ($nc.Count -gt 0) { Append-Log ((T "Calibration {0} de la famille {1} non convergée ({2}) : écriture avec cette courbe. Pour la refaire, bouton « Calibrer » de l'onglet Écriture, de préférence en test fin.") -f "$kind", (Get-CalibFamilyName $fam), "$($script:PrecompCurves[$nc[0]].Date)") }
        # 12.7 point 5 : ecriture lente, case « Mesurer la disquette » : niveau et surface mesures sur la disquette a ecrire
        if (Test-WriteLevelWanted $mode) {
            # Arbitrage 15 : pas de mesure si l image ne recouvre pas tout le motif (une face, step= garde par Set-WritePreset)
            $sk = Get-LevelWriteSkip $img $fmt $txtWTracks.Text
            if ($sk) { if ($sk.Why) { Append-Log $sk.Why }; Start-ImageWrite; return }
            Start-LevelBeforeWrite $mode -Measure; return
        }
        Start-ImageWrite; return
    }
    switch ($state) {
        'content' { Append-Log ((T "La calibration {0} de la famille {1} a été mesurée sur le contenu d'une image, avant le motif de test : elle est refaite.") -f "$kind", (Get-CalibFamilyName $fam)) }
        'stale'   { Append-Log ((T "Courbes par tête de la famille {0} antérieures à la calibration commune : elles sont refaites.") -f (Get-CalibFamilyName $fam)) }
        'short'   {
            $sk = @(if ($heads) { "${fam}_h0", "${fam}_h1" } else { $fam }) | ForEach-Object { @($script:PrecompCurves[$_].Values).Count } | Measure-Object -Minimum
            Append-Log ((T "Calibration {0} de la famille {1} mesurée sur {2} cylindres seulement, image de {3} cylindres : elle est refaite.") -f "$kind", (Get-CalibFamilyName $fam), "$($sk.Minimum)", "$imgCyl")
        }
        default   { Append-Log ((T "Aucune calibration {0} pour la famille {1} : calibration automatique, puis écriture.") -f "$kind", (Get-CalibFamilyName $fam)) }
    }
    $script:AfterCalib = 'write'
    Start-PrecompCalib
    if (-not $script:Cal) { $script:AfterCalib = ''; Append-Log (T 'Écriture annulée : la calibration n''a pas été lancée.') }
}

function Test-WriteLevelWanted([string]$mode) {
    # 12.7 point 5 : mesure de la disquette avant une ecriture lente demandee (case chkWLevel) : ecriture lente, liste
    # « Calibration precomp » au test standard ou au test fin (au test rapide : chemins de la 12.6, inchanges) ; en
    # restauration, liste de l onglet Ecriture d avant la restauration (Restore.Saved, la restauration la met au test fin)
    if ($mode -ne 'slow' -or -not $chkWLevel.Checked) { return $false }
    $cm = if ($script:Restore -and $script:Restore.Saved) { [int]$script:Restore.Saved.CalMode } else { [int]$cmbWCalMode.SelectedIndex }
    return ($cm -ne 2)
}

function Get-WriteLevelKind([string]$img, [string]$fmt) {
    # 12.7 point 5 : image de l onglet Ecriture pour la mesure avant l ecriture lente, memes regles que Start-PresetWrite :
    # 'dd' (calibrable en double densite, calibration rapide possible), 'hd' (haute densite calibrable : pas de
    # calibration rapide, arbitrage 8), '' (non calibrable : flux, image secteur sans format, secteurs durs, TG43, format
    # non calibrable, densite non etablie, cellule hors plage, module d analyse SCP absent)
    $ext = [System.IO.Path]::GetExtension($img).ToLower()
    $explicit = ($fmt -and $fmt -ne '(auto)')
    if (@('.scp', '.raw', '.kf', '.a2r', '.ctr') -contains $ext) { return '' }
    if ((Test-NeedsFormat $img) -and -not $explicit) { return '' }
    if (Test-NonMfmWrite $img $fmt) { return '' }    # 12.10 (lot 1, B1) : FM, GCR ou codage propre (HFE FM compris)
    if (Get-HighDensityReason $img $fmt) { if (Get-HdCalibFamily $img $fmt) { return 'hd' }; return '' }
    if ($chkWHard.Checked -or $chkWTG43.Checked) { return '' }
    $fci = if ($explicit -and $script:GwFormats.Contains($fmt)) { Get-FormatCalibInfo $fmt } else { $null }
    if ($fci -and -not $fci.Cal -and $fmt -notmatch '^(commodore\.15[47]1|mac\.|apple2\.)') { return '' }
    if (-not ((@('.adf', '.ipf', '.hfe') -contains $ext) -or ($explicit -and $fmt -notmatch '^(commodore\.15[47]1|mac\.|apple2\.)'))) { return '' }
    if ($null -ne (Get-CellOutOfRange $img)) { return '' }
    if (-not $script:ScpStatsOk) { return '' }
    return 'dd'
}

function Write-LevelHdNote([string]$hf, [bool]$heads) {
    # 12.7 point 5 : pas de calibration rapide en haute densite (arbitrage 8) : ligne de journal, puis ecriture avec les
    # champs du mode Auto (Get-HdAutoFields : courbes par tete a jour en ecriture lente, sinon courbe commune, sinon
    # profil d origine haute densite)
    $cur = ($heads -and (Test-HeadCurvesCurrent $hf)) -or [bool](Get-HdCommonCurve $hf)
    if ($cur) { Append-Log (T 'Mesure de la disquette non disponible en haute densité : écriture avec la courbe HD du lecteur.') }
    else { Append-Log (T "Mesure de la disquette non disponible en haute densité : écriture avec le profil d'origine.") }
}

function Test-FluxImage([string]$img) {
    # Image flux (SCP, KryoFlux, A2R, CTR) : transitions enregistrees, et non pistes de bits ou secteurs
    return (@('.scp', '.raw', '.kf', '.a2r', '.ctr') -contains [System.IO.Path]::GetExtension("$img").ToLower())
}

function Test-RawFluxWrite([string]$img, [string]$fmt) {
    # 12.8 (S3-FLUX, decision 2 du 21/10/2026) : image flux ecrite sans --format (meme regle que Get-WriteFormatArgs) :
    # gw l ecrit telle quelle et n applique --precomp qu aux pistes MasterTrack (tools/write.py de gw 1.23 : images a
    # cellules ou a secteurs, flux decode par --format) : precompensation ignoree
    return ((Test-FluxImage $img) -and -not ($fmt -and $fmt -ne '(auto)'))
}

function Write-FluxLevelSkip([string]$img, [string]$fmt) {
    # 12.8 (S3-FLUX, decision 2) : aucune mesure de la disquette (calibration rapide ou mesure complete) avant l ecriture
    # d une image flux, depuis le bouton ECRIRE et la Bibliotheque (restauration : Start-RestoreWrite) : ligne de journal.
    # Flux decode par --format : gw lui applique la precompensation, mais la mesure ne se fait pas non plus
    $n = [System.IO.Path]::GetFileName("$img")
    if (Test-RawFluxWrite $img $fmt) { Append-Log ((T "Mesure de la disquette avant l'écriture non faite : image flux {0}, écrite telle quelle, à laquelle gw n'applique pas la précompensation (flux sans --format). Écriture sans mesure.") -f "$n") }
    else { Append-Log ((T "Mesure de la disquette avant l'écriture non faite : image flux {0}, décodée par --format={1} ; la disquette n'est pas mesurée avant l'écriture d'une image flux. Écriture sans mesure.") -f "$n", "$fmt") }
}

function Write-NonMfmSkip([string]$img, [string]$fmt) {
    # 12.10 (lot 1, B1) : ni calibration ni mesure de la disquette avant l ecriture d une image FM, GCR ou a codage propre
    # (Start-PresetWrite, bouton ECRIRE) : ligne de journal. Profil Manuel avec --precomp coche : la ligne de Start-ImageWrite
    # (champ transmis tel quel) la remplace, l ecriture n etant pas sans precompensation
    if (Test-ManualPrecomp) { return }
    $ie = Get-ImageEncoding $img $fmt
    Append-Log ((T "Image {0} en codage {1} : pas de calibration (elle ne mesure que le MFM), écriture sans précompensation.") -f "$([System.IO.Path]::GetFileName("$img"))", "$($ie.Name)")
}

function Test-ManualPrecomp {
    # 12.10 (lot 1, revue2, R-6) : profil Manuel avec --precomp coche : Start-ImageWrite transmet le champ tel quel, meme sur
    # une image FM, GCR ou a codage propre. Textes « ecrite sans precompensation » omis dans ce cas (Write-NonMfmSkip,
    # refus de Test-CalibImage, et raisons de Get-FormatCalibInfo qu il demande, parametre manual)
    return ($cmbWProfile.SelectedIndex -eq 3 -and $chkWPrecomp.Checked)
}

function Get-LevelWriteSkip([string]$img, [string]$fmt, [string]$ts) {
    # 12.7 point 5 (arbitrage 15) : mesure de la disquette avant l ecriture lente exclue quand l image ne recouvrirait pas
    # tout le motif. La mesure ecrit le motif sur 4 a 9 cylindres par tete, sur tout le disque et les deux tetes
    # (Start-LevelCalib : c=...:h=0-1), sans le champ Pistes. Renvoie $null (mesure possible) ou @{ Why } : ligne de
    # journal, vide quand Start-ImageWrite refusera l ecriture lente (son message s affiche alors avant toute ecriture du
    # motif). Cas, dans cet ordre :
    #  - champ Pistes avec c=, h= ou step= (step= : pistes physiques que la mesure, sans le pas, ne vise pas) ;
    #  - faces de l image inconnues avec « Effacer les pistes vides », en ecriture lente : refus de Start-ImageWrite (memes
    #    regles, sans h=). 12.8 (lot 2, PRE-BANC § 4) : en ecriture rapide, ce refus n existe pas (gw ecrit toutes les
    #    pistes du format) : faces du format, comme sans la case (12.8 avant ce correctif : mesure sautee sans ligne) ;
    #  - image a une seule face : faces de l image (Get-ImageTrackSet), sinon tetes du format gw d une image secteur.
    # 12.11 (L10) : Code, cas rendu ('tracks', 'faces', 'face'), lu par Get-WriteLevelPlan ; appelants inchanges
    $ts = "$ts".Trim()
    if ($ts -and [regex]::IsMatch(":$ts", ':\s*(c|h|step)\s*=')) { return @{ Code = 'tracks'; Why = ((T "Mesure de la disquette avant l'écriture non faite : le champ Pistes (« {0} ») limite les pistes écrites ; le motif de test resterait sur des cylindres que l'image ne recouvre pas. Écriture sans mesure.") -f "$ts") } }
    $set = Get-ImageTrackSet $img
    if ($null -eq $set) {
        if ($chkWEraseEmpty.Checked -and $chkWSlow.Checked) { return @{ Code = 'faces'; Why = '' } }
        $fe = if ($fmt -and $fmt -ne '(auto)' -and $script:GwFormats.Contains($fmt)) { $script:GwFormats[$fmt] } else { $null }
        $hs = @(if ($fe -and [int]$fe.Heads -eq 1) { 0 } else { 0, 1 })
    } else { $hs = @(@($set.Keys) | ForEach-Object { [int](([string]$_ -split '\.')[1]) } | Sort-Object -Unique) }
    if ($hs.Count -eq 1) { return @{ Code = 'face'; Why = (T "Mesure de la disquette avant l'écriture non faite : image à une seule face ; le motif de test resterait sur l'autre face, que l'image n'écrit pas. Écriture sans mesure.") } }
    return $null
}

function Start-WriteTabWrite {
    # 12.7 point 5 : bouton ECRIRE de l onglet Ecriture. Ecriture lente avec la case « Mesurer la disquette avant
    # l ecriture lente » (Test-WriteLevelWanted), image calibrable en double densite, profil Auto, --precomp coche, image
    # qui recouvre tout le motif (Get-LevelWriteSkip) : niveau et etat de la surface mesures sur la disquette inseree
    # (Start-LevelBeforeWrite -Measure), puis ecriture. Haute densite : ligne de journal, puis ecriture. Sinon :
    # Start-ImageWrite, comme en 12.6 (jamais de calibration automatique depuis ce bouton en test standard ou fin).
    # 12.8 (D5) : liste au « Test rapide » : meme regle que la Bibliotheque, ecriture rapide ou lente : niveau mesure sur
    # la disquette a ecrire (Start-LevelBeforeWrite ; sans reference utilisable : ecriture refusee, jamais de calibration
    # complete depuis ce bouton, validation du 19/10), memes conditions (densite, profil Auto, --precomp, image qui
    # recouvre le motif)
    # 12.8 (FIX-PISTES, essai du 21/10/2026) : champ Pistes qui retire des pistes de l image (c=, h=) : confirmation qui
    # nomme l image et les pistes (Confirm-PartialWrite), avant toute mesure ou ecriture ; le champ reste enregistre dans
    # la configuration, comme en 12.7. FIX-PISTES-2 : aussi pour step= autre que 1 (pas du lecteur par cylindre)
    # 12.10 : lecteur cible choisi (Get-TargetDrive) : ni mesure de la disquette ni calibration rapide (elles reliraient avec
    # le lecteur du bandeau) : ecriture avec la courbe croisee telle quelle ; refusee sans courbe croisee de la famille
    # (Test-TargetWriteAllowed), avant la confirmation d une ecriture partielle
    # 12.11 (L10) : cascade de la mesure decidee par Get-WriteLevelPlan (Kind, Skip), dont la ligne « Ce qui va se passer »
    # tire aussi son segment ; memes lignes de journal, dans le meme ordre, et memes appels
    $img = $txtWFile.Text
    $mode = if ($chkWSlow.Checked) { 'slow' } else { 'fast' }
    $tgt = Get-TargetDrive
    if ($img -and (Test-Path -LiteralPath $img) -and -not ($script:GwProc -and -not $script:GwProc.HasExited)) {
        if ($tgt -and -not (Test-TargetWriteAllowed $img $cmbWFmt.Text ($mode -eq 'slow'))) { return }
        if (-not (Confirm-PartialWrite $img $cmbWFmt.Text $txtWTracks.Text)) { return }
    }
    $wp = Get-WriteLevelPlan $img $cmbWFmt.Text $mode
    # Lecteur cible sans effet sur cette ecriture (profil Manuel, --precomp decoche, flux, FM, GCR : Get-TargetWriteInfo) :
    # deroule ordinaire, qui ne mesure pas ces ecritures (Start-ImageWrite le dit au journal)
    if ($wp.Skip -eq 'target') {
        if ($wp.Asked) { Append-Log ((T "Mesure de la disquette avant l'écriture non faite : écriture pour le lecteur cible {0} (la mesure relirait avec le lecteur {1}). Écriture avec la courbe croisée telle quelle.") -f "$tgt", "$($cmbDrive.Text)") }
        Start-ImageWrite; return
    }
    if ($wp.Kind -eq 'none' -and -not $wp.Skip) { Start-ImageWrite; return }
    if ($script:GwProc -and -not $script:GwProc.HasExited) { return }
    # 12.8 (S3-FLUX, decision 2 du 21/10/2026) : image flux : jamais de mesure avant l ecriture, ligne de journal
    if ($wp.Skip -eq 'flux') { Write-FluxLevelSkip $img $cmbWFmt.Text; Start-ImageWrite; return }
    # 12.10 (lot 1, B1) : image FM, GCR ou a codage propre : jamais de mesure avant l ecriture, ligne de journal
    if ($wp.Skip -eq 'nonmfm') { Write-NonMfmSkip $img $cmbWFmt.Text; Start-ImageWrite; return }
    if ($wp.Skip -eq 'kind') { Start-ImageWrite; return }
    # Haute densite avant le profil : la mesure n y existe pas, quel que soit le profil ; ligne de la courbe ou du profil
    # d origine seulement quand le mode Auto les applique (profil Auto, --precomp coche)
    if ($wp.Skip -eq 'hd') {
        if ($wp.HdNote) { Write-LevelHdNote $wp.Hf ($mode -eq 'slow') }
        else { Append-Log (T 'Mesure de la disquette non disponible en haute densité.') }
        Start-ImageWrite; return
    }
    # Profil choisi a la main (Manuel, ou profil force) : la mesure decalerait la courbe calibree du profil Auto
    if ($wp.Skip -eq 'profile') { Append-Log ((T "Mesure de la disquette avant l'écriture non faite : profil précomp. « {0} » choisi ; la mesure ne se fait qu'avec le profil Auto.") -f "$($cmbWProfile.Text)"); Start-ImageWrite; return }
    # --precomp decoche : la mesure le cocherait (Set-LevelFields) ; ecriture sans precompensation, comme en 12.6
    if ($wp.Skip -eq 'precomp') { Append-Log (T "Mesure de la disquette avant l'écriture non faite : précompensation désactivée (case --precomp décochée) ; écriture sans précompensation."); Start-ImageWrite; return }
    # Champ Pistes, faces de l image (Get-LevelWriteSkip)
    if ($wp.Skip) { if ($wp.Why) { Append-Log $wp.Why }; Start-ImageWrite; return }
    Start-LevelBeforeWrite $wp.LbMode -Measure:([bool]$wp.LbMeasure)
}

function Get-WriteLevelPlan([string]$img, [string]$fmt, [string]$mode) {
    # 12.11 (L10, extraite de Start-WriteTabWrite sans changement de comportement) : mesure de la disquette avant une
    # ecriture du bouton ECRIRE, decision commune a Start-WriteTabWrite et a la ligne « Ce qui va se passer »
    # (Get-WritePlan, 145) ; aucune ligne de journal, aucune fenetre. Rend @{ Kind ; Skip ; Asked ; Tgt ; Why ; HdNote ; Hf ;
    # LbMode ; LbMeasure } :
    #  - Kind 'quick' (liste « Calibration precomp » au « Test rapide » : Start-LevelBeforeWrite $mode), 'measure' (case
    #    « Mesurer la disquette » en ecriture lente, liste au test standard ou fin : Start-LevelBeforeWrite 'slow' -Measure),
    #    'none' (ecriture sans mesure) ; LbMode et LbMeasure : arguments de Start-LevelBeforeWrite ;
    #  - Skip, mesure demandee (Asked) mais non faite, dans l ordre des tests : 'target' (lecteur cible avec effet ; ligne
    #    de journal seulement si Asked), 'flux', 'nonmfm' (FM, GCR, codage propre), 'kind' (image non calibrable,
    #    Get-WriteLevelKind), 'hd' (HdNote : ligne de la courbe HD, Hf sa famille), 'profile' (profil autre qu Auto),
    #    'precomp' (case --precomp decochee), 'tracks', 'faces' ou 'face' (Get-LevelWriteSkip : Code, Why, ligne de
    #    journal) ; '' avec Kind 'none' : mesure non demandee, ou fichier absent
    $r = @{ Kind = 'none'; Skip = ''; Asked = $false; Tgt = ''; Why = ''; HdNote = $false; Hf = ''; LbMode = $mode; LbMeasure = $false }
    $quick = ((Get-Setting 'calMode') -eq 'level')
    $r.Asked = [bool]($quick -or (Test-WriteLevelWanted $mode))
    $tgt = Get-TargetDrive
    if ($tgt -and (Get-TargetWriteInfo $img $fmt ($mode -eq 'slow')).Applies) { $r.Skip = 'target'; $r.Tgt = $tgt; return $r }
    if (-not $r.Asked -or -not $img -or -not (Test-Path -LiteralPath $img)) { return $r }
    if (Test-FluxImage $img) { $r.Skip = 'flux'; return $r }
    if (Test-NonMfmWrite $img $fmt) { $r.Skip = 'nonmfm'; return $r }
    $k = Get-WriteLevelKind $img $fmt
    if (-not $k) { $r.Skip = 'kind'; return $r }
    $auto = ($cmbWProfile.SelectedIndex -eq 0)
    if ($k -eq 'hd') {
        $r.Skip = 'hd'
        if ($auto -and $chkWPrecomp.Checked) { $r.HdNote = $true; $r.Hf = Get-HdCalibFamily $img $fmt }
        return $r
    }
    if (-not $auto) { $r.Skip = 'profile'; return $r }
    if (-not $chkWPrecomp.Checked) { $r.Skip = 'precomp'; return $r }
    $sk = Get-LevelWriteSkip $img $fmt $txtWTracks.Text
    if ($sk) { $r.Skip = [string]$sk.Code; $r.Why = [string]$sk.Why; return $r }
    if ($quick) { $r.Kind = 'quick'; return $r }
    $r.Kind = 'measure'; $r.LbMode = 'slow'; $r.LbMeasure = $true
    return $r
}

function Confirm-PartialWrite([string]$img, [string]$fmt, [string]$tspec) {
    # 12.8 (FIX-PISTES, essai du 21/10/2026) : bouton ECRIRE avec un champ Pistes qui retire des pistes de l image
    # (Get-WritePartial) : ligne de journal, puis frmConfirm sans case, « Ecrire ces pistes » ou « Fermer » (reponse notee
    # au journal par Show-AppConfirm). La Bibliotheque et la restauration n y passent pas : Set-WritePreset retire c= et h=
    # du champ (h= d une image a une face seulement, qui couvre l image), et la restauration ne pose c= que pour ses
    # cylindres preserves. Renvoie $true quand l ecriture continue.
    # 12.8 (FIX-PISTES-2) : aucune piste de l image dans le champ (Kept 0 : piste vide de l image, cylindres hors de
    # l image) : texte propre, gw n ecrit aucune donnee mais efface ces pistes avec --erase-empty (essai du 21/10/2026 :
    # « T0.0: Erasing Track ») ; step= autre que 1 : texte propre (aucune piste retiree, pas du lecteur par cylindre),
    # seul (titre « Pas du lecteur modifie ») ou apres celui de c= et h=
    $pw = Get-WritePartial $img $fmt $tspec
    if (-not $pw) { return $true }
    $name = [System.IO.Path]::GetFileName($img)
    $logs = @(); $parts = @()
    if ($pw.Partial -and [int]$pw.Kept -eq 0) {
        $er = if ($chkWEraseEmpty.Checked) { ' ' + (T "« Effacer les pistes vides » est cochée : ces pistes de la disquette seront effacées.") } else { '' }
        $logs += ((T "Écriture partielle : aucune piste de {1} dans le champ Pistes ({0}), aucune donnée de l'image ne sera écrite.") -f "$($pw.Spec)", "$name") + $er
        $parts += ((T "Aucune piste de {1} n'est dans le champ Pistes ({0}) : aucune donnée de l'image ne sera écrite.") -f "$($pw.Spec)", "$name") + $er
    } elseif ($pw.Partial) {
        $cnt = if ([int]$pw.Total -ge 0) { (T " ({0} piste(s) sur les {1} de l'image)") -f "$($pw.Kept)", "$($pw.Total)" } else { '' }
        $logs += (T "Écriture partielle : seules les pistes {0} de {1} seront écrites{2} (champ Pistes de l'onglet Écriture).") -f "$($pw.Spec)", "$name", "$cnt"
        $parts += (T "Seules les pistes {0} de {1} seront écrites{2}.") -f "$($pw.Spec)", "$name", "$cnt"
    }
    if ($pw.Step) {
        $logs += (T "Pas du lecteur : {1} sera écrite avec step={0} ({0} pas du lecteur par cylindre au lieu d'un, champ Pistes de l'onglet Écriture).") -f "$($pw.Step)", "$name"
        if ($pw.Partial) { $parts += (T "Le champ Pistes contient aussi step={0} : {0} pas du lecteur par cylindre au lieu d'un.") -f "$($pw.Step)" }
        else { $parts += (T "Le champ Pistes contient step={0} : {1} sera écrite avec {0} pas du lecteur par cylindre au lieu d'un (step=2 sert à écrire une disquette 40 pistes dans un lecteur 80 pistes).") -f "$($pw.Step)", "$name" }
    }
    foreach ($l in $logs) { Append-Log $l }
    if ($pw.Partial) {
        $ttl = (T 'Écriture partielle'); $go = (T 'Écrire ces pistes'); $no = (T "Écriture annulée : écriture partielle non confirmée, rien n'a été écrit.")
        $tail = (T "Le champ Pistes des options avancées de l'onglet Écriture limite l'écriture à ces pistes ; il est gardé d'une session à l'autre. Pour écrire toute l'image, fermez cette fenêtre et videz ce champ.")
    } else {
        $ttl = (T 'Pas du lecteur modifié'); $go = (T 'Écrire avec ce pas'); $no = (T "Écriture annulée : pas du lecteur non confirmé, rien n'a été écrit.")
        $tail = (T "Le champ Pistes des options avancées de l'onglet Écriture est gardé d'une session à l'autre. Pour écrire au pas normal du lecteur, fermez cette fenêtre et retirez step= de ce champ.")
    }
    $cq = @{ Title = $ttl; Heading = $ttl; Level = 'warn'; Picto = 'warn'; Text = ($parts -join ' ') + "`n`n" + $tail; GoText = $go; GoGlyph = 'Save' }
    if (Show-AppConfirm @cq) { return $true }
    Append-Log $no
    return $false
}

# --- Facteur de precompensation et lecteur cible (12.8.1, 12.10) ------
# Courbe ecrite = k_h x courbe, par tete (spec-1281 § A.10, C.3 ; decisions de l utilisateur du 25/10/2026). k_h : mesure
# sur l image qui precede l ecriture (276, $script:WriteFactorNext), sinon k du lecteur : mediane des 3 derniers k* mesures
# pour ce lecteur, cette famille et cette tete (Get-DriveK, 274), garde apres une recalibration du lecteur, 1 sans mesure
# (ecriture de la v12.8). Il s applique a la courbe que la v12.8 aurait ecrite : courbe du lecteur, courbe adaptee d une
# calibration rapide, courbe d une mesure complete ou d une marque. Haute densite, flux, FM, GCR, profil autre qu Auto :
# jamais de facteur. 12.9 (N13) : k du lecteur par marque (marque de la mesure qui precede, sinon derniere marque choisie),
# nommee dans les lignes de journal.
# 12.10 : la correction « lecteur cible » Dk de la 12.8.1 (valeur par tete ajoutee au facteur, champs de l onglet Ecriture,
# bloc targetCorrection de la configuration) est retiree : a sa place, la liste « Lecteur cible » (cmbWTarget, 520) choisit
# le lecteur qui relira la disquette ecrite par le lecteur du bandeau (la source) ; les courbes croisees « source>cible » de
# la calibration croisee (270) sont alors appliquees telles quelles (Set-PrecompFields, 220), sans facteur
# (Get-WriteFactorPlan : le facteur de marque, mesure par la relecture de la source, ne vaut pas pour la cible) ; sans
# courbe croisee pour la famille de l image, l ecriture est refusee (Test-TargetWriteAllowed). Choix memorise par lecteur
# source ($script:TargetDrives, 560 ; write.targetDrive, 120).

function Get-WriteFactorSrcText([string]$drive, [string]$fam, [int]$h, [double]$k, [string]$src, $brand = $null) {
    # Origine du facteur d une tete dans les lignes de journal : mesure sur cette disquette ('mesure'), mesures du lecteur
    # ('lecteur' : derniere, ou mediane des 3 dernieres avec leurs valeurs), aucune mesure ('defaut' : k = 1).
    # 12.9 (N13) : mesures du lecteur pour la marque $brand ($null : derniere marque choisie, Get-DriveK), nommee ; sans
    # mesure de la marque, nombre de mesures d autres marques (jamais empruntees). 12.10 : sans la correction Dk
    $kt = Format-UiNum $k '0.00'
    if ($src -eq 'mesure') { return ((T 'k {0} mesuré sur cette disquette') -f "$kt") }
    $dr = Get-DriveK $drive $fam $h $brand
    $bn = [string]$dr.Brand; if (-not $bn.Trim()) { $bn = (T '(non précisée)') } else { $bn = $bn.Trim() }
    if ($src -eq 'lecteur') {
        if ([int]$dr.N -ge 2) { return ((T 'k {0}, médiane des {1} dernières mesures du lecteur pour la marque « {2} » ({3})') -f "$kt", "$($dr.N)", "$bn", ((@($dr.Ks) | ForEach-Object { Format-UiNum ([double]$_) '0.00' }) -join ' ; ')) }
        $md = if ($dr.Rec -and $dr.Rec.Date) { [string]$dr.Rec.Date } else { '?' }
        return ((T 'k {0} de la dernière mesure du lecteur pour la marque « {1} » (du {2})') -f "$kt", "$bn", "$md")
    }
    # Revue 12.8.2 : mesures de ce lecteur ecartees parce qu elles viennent d un autre calcul (Get-DriveK, Old). 12.9
    # (revue de la phase B, mineur 1) : ecartees seulement par ContentCalc (OldContent) : calcul de la mesure change
    if ([int]$dr.Old -gt 0 -and [int]$dr.OldContent -ge [int]$dr.Old) { return ((T 'k 1 (mesures de ce lecteur faites avant la {0}, calcul de la mesure changé, à refaire pour la marque « {1} »)') -f "$($script:ContentCalc)", "$bn") }
    if ([int]$dr.Old -gt 0) { return (T 'k 1 (mesures de ce lecteur faites avec un autre calcul de calibration, à refaire)') }
    $oth = if ([int]$dr.Other -gt 0) { (T ' ; {0} mesure(s) d''autres marques') -f "$($dr.Other)" } else { '' }
    return ((T 'k 1 (aucune mesure de ce lecteur pour la marque « {0} »{1})') -f "$bn", "$oth")
}

function Get-WriteFactorPlan([string]$img, [string]$fmt, [bool]$slow, $next = $null, [switch]$Peek) {
    # Facteur de precompensation d une ecriture de l onglet Ecriture (Start-ImageWrite), par tete : f_h = k_h, ramene a
    # [0 ; ContentFMax] (Limit-WriteFactor, plafond : 040) ; ecriture rapide : FMean, moyenne des facteurs des deux tetes
    # (decision du 25/10/2026). $next : facteur mesure sur l image ($script:WriteFactorNext), retenu pour le meme lecteur,
    # la meme famille et la meme image seulement. Apply faux, raison Why : fichier absent, profil autre qu Auto, --precomp
    # decoche, image non calibrable en double densite (haute densite, flux, FM, GCR...), famille sans courbe, courbe d un
    # autre lecteur. Lines : lignes de journal, dans l ordre (T-C10 par tete bornee, puis T-C8 ou T-C9 ; sans facteur :
    # facteur du lecteur non applique si k != 1). Hard : borne des profils mis a l echelle (ConvertTo-ScaledSpec : une
    # valeur deja au-dessus, venue d une mesure complete, n est jamais augmentee). Peek : calcul seul, sans les lignes d un
    # facteur non applique (libelle du profil, texte « Ecrire sans mesure » de la confirmation de la mesure sur l image, 276).
    # 12.10 : lecteur cible avec effet sur cette ecriture (Get-TargetWriteInfo : profil Auto ou force, --precomp coche, image
    # MFM a laquelle --precomp est transmis) : facteur 1, jamais applique (Apply faux, Target = cible, Fam, Curves = courbes
    # croisees ecrites) ; lignes « Ecriture pour le lecteur cible ... : courbe croisee ..., facteur 1,00 » et « Facteur de
    # marque non applique » ; sans courbe croisee (ou haute densite) : Why « aucune courbe croisee », Target vide (l ecriture
    # est refusee par Test-TargetWriteAllowed). Lecteur cible sans effet : facteur comme pour le meme lecteur
    $drive = [string]$cmbDrive.Text
    $hard = [int]$script:CalHardNsUser; if ($hard -le 0) { $hard = [int]$script:CalHardNs }
    $fMax = [double]$script:ContentFMax
    $r = @{ Apply = $false; Why = ''; F0 = 1.0; F1 = 1.0; FMean = 1.0; K = @{ 0 = 1.0; 1 = 1.0 }; Src = @{ 0 = 'defaut'; 1 = 'defaut' }
            Hard = $hard; Fam = ''; Line = ''; Lines = @(); Target = ''; Curves = @() }
    $tw = Get-TargetWriteInfo $img $fmt $slow
    if ($tw.Applies) {
        $r.Fam = [string]$tw.Fam
        $tc = @($tw.Curves)
        if ($tc.Count -eq 0) { $r.Why = (T 'aucune courbe croisée {0} → {1}') -f "$drive", "$($tw.Tgt)"; return $r }
        $r.Target = [string]$tw.Tgt; $r.Curves = $tc
        if ($Peek) { return $r }
        $r.Line = (T "Écriture pour le lecteur cible {0} : {1}, facteur 1,00.") -f "$($tw.Tgt)", (Get-TargetCurvesText $drive ([string]$tw.Tgt) ([string]$tw.Fam) $tc)
        $r.Lines = @($r.Line, ((T "Facteur de marque non appliqué : écriture pour le lecteur cible {0} (le facteur est mesuré par la relecture du lecteur {1}, il ne vaut pas pour le lecteur cible).") -f "$($tw.Tgt)", "$drive"))
        return $r
    }
    $fam = ''
    if (-not $img -or -not (Test-Path -LiteralPath $img)) { $r.Why = (T 'Fichier image introuvable.') }
    elseif ($cmbWProfile.SelectedIndex -ne 0) { $r.Why = (T 'profil précomp. « {0} »') -f "$($cmbWProfile.Text)" }
    elseif (-not $chkWPrecomp.Checked) { $r.Why = (T 'précompensation désactivée') }
    else {
        $kind = Get-WriteLevelKind $img $fmt
        if ($kind -ne 'dd') {
            $r.Why = if ($kind -eq 'hd' -or (Get-HighDensityReason $img $fmt)) { (T 'image haute densité') } else { (T 'image non calibrable en double densité') }
        } else {
            # Courbes que le mode Auto ecrit (Set-PrecompFields : par tete a jour en ecriture lente, sinon commune) ; tableau
            # protege par Get-FamilyCurves (pas de @() autour de l appel)
            $fam = Get-ImageFamily $img $fmt
            $cvs = Get-FamilyCurves $fam $slow
            $oth = @(@($cvs) | Where-Object { [string]$_.Drive -ne $drive } | ForEach-Object { if ($_.Drive) { [string]$_.Drive } else { '?' } } | Sort-Object -Unique)
            if (@($cvs).Count -eq 0) { $r.Why = (T 'aucune courbe du lecteur') }
            elseif ($oth.Count -gt 0) { $r.Why = (T "courbe d'un autre lecteur ({0})") -f ($oth -join ', ') }
            else { $r.Apply = $true; $r.Fam = $fam }
        }
    }
    if (-not $r.Apply) {
        if ($Peek) { return $r }
        if ($img -and (Test-Path -LiteralPath $img)) {
            $fk = Get-ImageFamily $img $fmt
            if (@('std', 'long') -contains $fk) {
                $k0 = [double](Get-DriveK $drive $fk 0).K; $k1 = [double](Get-DriveK $drive $fk 1).K
                if ($k0 -ne 1 -or $k1 -ne 1) { $r.Line = (T 'Facteur mesuré du lecteur {0} (tête 0 × {1}, tête 1 × {2}) non appliqué à cette écriture : {3}.') -f "$drive", (Format-UiNum $k0 '0.00'), (Format-UiNum $k1 '0.00'), "$($r.Why)" }
            }
        }
        if ($r.Line) { $r.Lines = @($r.Line) }
        return $r
    }
    $useNext = ($null -ne $next -and [string]$next.Drive -eq $drive -and [string]$next.Fam -eq $fam -and [string]$next.Img -eq $img)
    # 12.9 (N13) : marque de la mesure ou de la fenetre « Mesure de la disquette » qui precede ($next.Brand), sinon derniere
    # marque choisie (ecritures sans fenetre : rapide, Bibliotheque, restauration, test rapide)
    $brand = if ($useNext -and $null -ne $next.Brand) { [string]$next.Brand } else { [string]$script:LevelBrand }
    $bn = if ($brand.Trim()) { $brand.Trim() } else { (T '(non précisée)') }
    $txt = @{}; $lines = @()
    foreach ($h in 0, 1) {
        $k = $null; $src = 'defaut'
        if ($useNext -and $next.K) {
            $kv = $next.K[$h]; if ($null -eq $kv) { $kv = $next.K["$h"] }
            if ($null -ne $kv) {
                $k = [double]$kv; $sv = $null
                if ($next.Src) { $sv = $next.Src[$h]; if ($null -eq $sv) { $sv = $next.Src["$h"] } }
                $src = if ($sv) { [string]$sv } else { 'mesure' }
            }
        }
        if ($null -eq $k -or [double]::IsNaN($k) -or [double]::IsInfinity($k)) { $dr = Get-DriveK $drive $fam $h $brand; $k = [double]$dr.K; $src = [string]$dr.Src }
        $lim = Limit-WriteFactor $k $fMax
        if ($lim.Clamped) { $lines += (T 'Facteur de la tête {0} ramené de {1} à {2} (il va de 0 à {3}).') -f "$h", (Format-UiNum $k '0.00'), (Format-UiNum ([double]$lim.F) '0.00'), (Format-UiNum $fMax '0.0#') }
        $r.K[$h] = $k; $r.Src[$h] = $src
        if ($h -eq 0) { $r.F0 = [double]$lim.F } else { $r.F1 = [double]$lim.F }
        $txt[$h] = Get-WriteFactorSrcText $drive $fam $h $k $src $brand
    }
    $r.FMean = [double](Limit-WriteFactor (($r.F0 + $r.F1) / 2) $fMax).F
    $r.Brand = $brand
    if ($slow) {
        $r.Line = (T "Facteur de précompensation de cette écriture (lecteur {0}, marque « {1} ») : tête 0 × {2} ({3}) ; tête 1 × {4} ({5}). Courbe écrite = facteur × courbe, bornée à 0..{6} ns ; une valeur déjà au-dessus n'est jamais augmentée.") -f "$drive", "$bn", (Format-UiNum $r.F0 '0.00'), "$($txt[0])", (Format-UiNum $r.F1 '0.00'), "$($txt[1])", "$hard"
    } else {
        $r.Line = (T "Facteur de précompensation de cette écriture rapide (lecteur {0}, marque « {1} ») : × {2}, moyenne des deux têtes (tête 0 × {3}, {4} ; tête 1 × {5}, {6}). Courbe écrite = facteur × courbe, bornée à 0..{7} ns ; une valeur déjà au-dessus n'est jamais augmentée.") -f "$drive", "$bn", (Format-UiNum $r.FMean '0.00'), (Format-UiNum $r.F0 '0.00'), "$($txt[0])", (Format-UiNum $r.F1 '0.00'), "$($txt[1])", "$hard"
    }
    $r.Lines = @($lines) + @($r.Line)
    # Finalisation 12.10 : conseil de mesure de la disquette apres la ligne du facteur (Get-WriteFactorHint) ; jamais pour
    # -Peek (libelle du profil, confirmation de la mesure : ni ligne, ni test de la mesure possible)
    if (-not $Peek) {
        $hint = Get-WriteFactorHint $img $fmt $slow $drive $fam $brand $r.Src
        if ($hint) { $r.Lines = @($r.Lines) + @($hint) }
    }
    return $r
}

function Get-WriteFactorHint([string]$img, [string]$fmt, [bool]$slow, [string]$drive, [string]$fam, [string]$brand, $src) {
    # Finalisation 12.10 (analyse long track du 08/11/2026 : le meilleur facteur varie de +/- 0,2 d une disquette a l autre
    # d une meme marque) : ligne de journal qui conseille de mesurer la disquette, rendue a Get-WriteFactorPlan quand le
    # facteur s applique (profil Auto, --precomp coche, double densite, courbe du lecteur, sans lecteur cible), chaine vide
    # sinon :
    #  - facteur tire de la memoire de la marque (Src lecteur : aucune mesure de cette disquette dans cette ecriture), et
    #    mesures listees au journal pour une tete (Get-DriveK : 2 ou 3, arrondies a 0,01 comme au journal) ecartees de 0,2
    #    ou plus ;
    #  - image long track ecrite avec k 1 faute de toute mesure de la marque sur ce lecteur (Src defaut aux deux tetes).
    # Seulement si la mesure sur l image est possible pour cette ecriture et n y est pas deja demandee : ni restauration, ni
    # liste Calibration precomp au Test rapide (mesure au motif, ligne de Start-LevelBeforeWrite), case Mesurer la disquette
    # non cochee pour cette ecriture (Test-WriteLevelWanted), image qui recouvre tout le motif (Get-LevelWriteSkip) et
    # mesurable sur son contenu (Test-ContentMeasurable : MFM double densite, champ Pistes vide, courbe du lecteur assez
    # longue, 20 cylindres)
    if ($script:Restore -or $cmbWCalMode.SelectedIndex -eq 2) { return '' }
    if (Test-WriteLevelWanted $(if ($slow) { 'slow' } else { 'fast' })) { return '' }
    $spread = -1.0
    foreach ($h in 0, 1) {
        if ([string]$src[$h] -ne 'lecteur') { continue }
        $dr = Get-DriveK $drive $fam $h $brand
        if ([int]$dr.N -lt 2) { continue }
        $ks = @(@($dr.Ks) | ForEach-Object { [math]::Round([double]$_, 2) })
        $sp = [math]::Round([double]($ks | Measure-Object -Maximum).Maximum - [double]($ks | Measure-Object -Minimum).Minimum, 2)
        if ($sp -gt $spread) { $spread = $sp }
    }
    $bn = if ($brand.Trim()) { $brand.Trim() } else { (T '(non précisée)') }
    # Relecture de la finalisation : consigne selon l ecriture. Ecriture lente : case Mesurer la disquette decochee (sinon
    # Test-WriteLevelWanted ci-dessus) : la cocher. Ecriture rapide : jamais mesuree, case cochee ou non (Test-WriteLevelWanted
    # rend faux hors ecriture lente) : ecrire en ecriture lente, sans demander de cocher une case peut-etre deja cochee
    $how = if ($slow) { (T "cochez « Mesurer la disquette avant l'écriture lente », avec la mesure « sur l'image à écrire »") } else { (T "écrivez l'image en écriture lente, avec « Mesurer la disquette avant l'écriture lente » cochée et la mesure « sur l'image à écrire »") }
    $line = ''
    if ($spread -ge 0.2) { $line = (T "Les mesures de la marque « {0} » sur ce lecteur varient de {1} d'une disquette à l'autre : pour mesurer celle-ci avant l'écriture, {2}.") -f "$bn", (Format-UiNum $spread '0.00'), "$how" }
    elseif ($fam -eq 'long' -and [string]$src[0] -eq 'defaut' -and [string]$src[1] -eq 'defaut') { $line = (T "Aucun facteur mesuré pour la marque « {0} » sur ce lecteur : en long track, le meilleur facteur s'écarte souvent de 1 ; pour le mesurer, {1}.") -f "$bn", "$how" }
    if (-not $line) { return '' }
    if (Get-LevelWriteSkip $img $fmt $txtWTracks.Text) { return '' }
    try { if (-not (Test-ContentMeasurable $img $fmt).Ok) { return '' } } catch { return '' }
    return $line
}

function Get-WriteFactorNote([string]$path) {
    # Complement du libelle du profil Auto double densite (Update-PrecompForImage, T-C12) : facteur different de 1 que
    # recevrait une ecriture de l onglet (Get-WriteFactorPlan -Peek, ecriture lente ou rapide selon la case) ; vide avec un
    # facteur 1 (libelle de la v12.8) ; 12.10 : vide pour un lecteur cible (facteur 1, la courbe croisee est nommee entre les
    # parentheses du libelle : Get-WProfileSpec, 220)
    $wf = Get-WriteFactorPlan $path $cmbWFmt.Text ([bool]$chkWSlow.Checked) $null -Peek
    if (-not $wf.Apply) { return '' }
    if ($chkWSlow.Checked) {
        if ($wf.F0 -eq 1.0 -and $wf.F1 -eq 1.0) { return '' }
        return ((T " ; facteur appliqué à l'écriture : tête 0 × {0}, tête 1 × {1}") -f (Format-UiNum $wf.F0 '0.00'), (Format-UiNum $wf.F1 '0.00'))
    }
    if ($wf.FMean -eq 1.0) { return '' }
    return ((T " ; facteur appliqué à l'écriture rapide : × {0}, moyenne des deux têtes") -f (Format-UiNum $wf.FMean '0.00'))
}

function Update-WriteFactorNote {
    # Complement du libelle refait apres un changement du facteur (lecteur du bandeau), sans refaire le profil ni les champs
    # --precomp : seulement si le libelle est encore celui qu a pose Update-PrecompForImage
    $n = $script:WFactorNote
    if (-not $n -or [string]$lblWProfileInfo.Text -ne ([string]$n.Base + [string]$n.Note)) { return }
    $x = Get-WriteFactorNote $txtWFile.Text
    if ($x -eq [string]$n.Note) { return }
    $n.Note = $x; $lblWProfileInfo.Text = [string]$n.Base + $x
}

# --- Lecteur cible des ecritures (12.10, conception-croisee § 4) ------

function Get-DriveIds {
    # 12.10 : lecteurs de la liste du bandeau (codes du reglage drive, 040 : A, B, 0 a 3), source unique des lecteurs cibles ;
    # tableau protege par la virgule
    # 12.11 : lecteurs connus : les six connexions (lecteurs non enregistres), puis les lecteurs enregistres, dans l ordre
    # du registre ($script:DriveReg, 040 : noms lus par enumeration, sans fonction du module 112 ; la garde « registre non
    # vide » lit Count, qu aucun nom ne peut masquer : mots reserves de Test-DriveName). Registre vide ou absent : la
    # ligne de la 12.10
    if ($script:DriveReg -and $script:DriveReg.Count -gt 0) { return ,@(@([string[]]$script:SettingDefs['drive'].Codes) + @($script:DriveReg.GetEnumerator() | ForEach-Object { [string]$_.Key })) }
    return ,@([string[]]$script:SettingDefs['drive'].Codes)
}

function Get-TargetDrive([string]$src = '') {
    # 12.10 : lecteur cible des ecritures du lecteur source $src (vide : lecteur du bandeau) : '' sans lecteur cible (meme
    # lecteur), ou si le choix memorise est la source elle-meme ou un lecteur inconnu de la liste du bandeau (Get-DriveIds) ;
    # avant la creation de l etat (520 s execute avant 560) : ''
    if (-not $src) { $src = [string]$cmbDrive.Text }
    if (-not $src -or $null -eq $script:TargetDrives -or -not $script:TargetDrives.ContainsKey($src)) { return '' }
    $t = [string]$script:TargetDrives[$src]
    if (-not $t -or $t -eq $src -or (Get-DriveIds) -notcontains $t) { return '' }
    return $t
}

function Set-TargetDrive([string]$src, [string]$tgt) {
    # 12.10 : lecteur cible des ecritures du lecteur source : $tgt vide, egal a la source ou inconnu : entree retiree (meme
    # lecteur). Rend l ancien choix ('' : meme lecteur). Enregistre par Save-Config (write.targetDrive), comme les reglages
    $old = Get-TargetDrive $src
    if (-not $src) { return $old }
    if ($null -eq $script:TargetDrives) { $script:TargetDrives = @{} }
    if (-not $tgt -or $tgt -eq $src -or (Get-DriveIds) -notcontains $tgt) { [void]$script:TargetDrives.Remove($src) } else { $script:TargetDrives[$src] = $tgt }
    return $old
}

function Get-TargetDriveItems([string]$src) {
    # 12.10 : elements de la liste « Lecteur cible » : « (meme lecteur) », puis les lecteurs du bandeau sauf la source
    # (Get-CrossCalibTargets, 240, tableau protege par la virgule : entre parentheses, pas dans @()) ; tableau protege par
    # la virgule
    return ,@(@((T '(même lecteur)')) + (Get-CrossCalibTargets (Get-DriveIds) $src))
}

function Get-TargetCurves([string]$fam, [bool]$slow, [string]$src = '', [string]$tgt = '') {
    # 12.10 : courbes croisees « source>cible » de la famille appliquees a une ecriture pour le lecteur cible : par tete en
    # ecriture lente si elles sont presentes et au moins aussi recentes que la courbe commune, sinon la courbe commune
    # (Get-DriveFamilyCurves, 220). Courbes rendues une par une dans le pipeline : l appelant les recueille par @() (aucune
    # sans lecteur cible ou sans courbe croisee : tableau vide)
    if (-not $src) { $src = [string]$cmbDrive.Text }
    if (-not $tgt) { $tgt = Get-TargetDrive $src }
    if (-not $tgt) { return }
    $cv = Get-DriveFamilyCurves "$src>$tgt" $fam $slow
    foreach ($c in @($cv)) { if ($c) { $c } }
}

function Get-TargetCurvesText([string]$src, [string]$tgt, [string]$fam, $cvs) {
    # 12.10 : courbes croisees appliquees a une ecriture, dans les lignes de journal : « courbe croisee A → 0 (Standard 2 us,
    # test fin, 01/11/2026 17:49, calcul v12.10) », ou « courbes croisees A → 0 par tete (Standard 2 us, test fin, tete 0 du ...,
    # tete 1 du ..., calcul v12.10) » ; test (champ Test de la courbe) et calcul de la premiere courbe
    $l = @($cvs | Where-Object { $_ })
    if ($l.Count -eq 0) { return ((T 'aucune courbe croisée {0} → {1}') -f "$src", "$tgt") }
    $c0 = $l[0]
    $test = if ([string]$c0.Test -eq 'fine') { (T 'test fin') } else { (T 'test standard') }
    $calc = Get-CurveCalcText $c0 -Plain
    if ($l.Count -ge 2) { return ((T "courbes croisées {0} → {1} par tête ({2}, {3}, tête 0 du {4}, tête 1 du {5}, calcul {6})") -f "$src", "$tgt", (Get-CalibFamilyName $fam), "$test", "$($c0.Date)", "$($l[1].Date)", "$calc") }
    return ((T "courbe croisée {0} → {1} ({2}, {3}, {4}, calcul {5})") -f "$src", "$tgt", (Get-CalibFamilyName $fam), "$test", "$($c0.Date)", "$calc")
}

function Get-WriteImageFamily([string]$img, [string]$fmt) {
    # 12.10 (relecture de la RC, fix2) : famille de calibration d une image ecrite en profil Auto, commune a l ecriture pour
    # un lecteur cible (Get-TargetWriteInfo : courbes croisees ecrites) et au bouton « Courbe » de l onglet Ecriture
    # (Update-CurveButton) : Get-ImageFamily (haute densite calibrable, cellule d un IPF ou d un HFE), puis pour un flux SCP
    # decode par un format, cellule mesuree par Get-ScpCellInfo (module d analyse present) sous le seuil des long tracks,
    # comme Update-PrecompForImage. Lit le fichier (appelants : fichier present, fenetre affichee)
    $f = Get-ImageFamily $img $fmt
    if ($f -eq 'std' -and $script:ScpStatsOk -and [System.IO.Path]::GetExtension($img).ToLower() -eq '.scp') {
        try { $ci = Get-ScpCellInfo $img; if ($ci -and [double]$ci.CellNs -lt $script:PrecompThresholdNs) { $f = 'long' } } catch { }
    }
    return $f
}

function Get-TargetWriteInfo([string]$img, [string]$fmt, [bool]$slow) {
    # 12.10 : lecteur cible d une ecriture de l onglet Ecriture (Start-ImageWrite, Get-WriteFactorPlan, Start-WriteTabWrite,
    # Start-PresetWrite, Get-TargetWriteBlock) : @{ Src (lecteur du bandeau, qui ecrit) ; Tgt (lecteur cible, '' : meme
    # lecteur) ; Applies (courbes croisees ecrites) ; Why (raison d un lecteur cible sans effet) ; Fam ; Curves (courbes
    # croisees appliquees, Get-TargetCurves) ; Block (raison du refus de l ecriture, '' sinon) }. Sans effet : profil Manuel
    # (champ de l utilisateur transmis tel quel), --precomp decoche, fichier absent, image a laquelle --precomp n est pas
    # transmis (flux ecrit tel quel, FM, GCR, codage propre : Start-ImageWrite). Famille : celle du profil force (standard,
    # long track), sinon celle de l image comme le mode Auto (Get-ImageFamily ; flux SCP : cellule mesuree par
    # Get-ScpCellInfo, comme Update-PrecompForImage). Refus : image haute densite en Auto (la calibration croisee n existe
    # qu en double densite), aucune courbe croisee « source>cible » de la famille (par tete a jour en ecriture lente, sinon
    # commune, comme Set-PrecompFields). Relecture de l etape 3 : ecriture rapide avec des courbes croisees par tete
    # seulement (calibration croisee faite avec « Ecriture lente » cochee) : refus qui le dit (avant : « aucune courbe
    # croisee... lancez Calibrer pour un lecteur cible », qu une calibration faite de meme n aurait pas leve). 12.10
    # (relecture de la RC) : BlockKind, nature du refus ('hd', 'head' : courbes par tete seulement, 'none' : aucune courbe
    # croisee ; '' sans refus) : refus annonce en tete du libelle du profil (Get-WTargetHead, 220)
    $src = [string]$cmbDrive.Text
    $r = @{ Src = $src; Tgt = (Get-TargetDrive $src); Applies = $false; Why = ''; Fam = ''; Curves = @(); Block = ''; BlockKind = '' }
    if (-not $r.Tgt) { return $r }
    if ($cmbWProfile.SelectedIndex -eq 3) { $r.Why = (T 'profil Manuel, champ --precomp transmis tel quel'); return $r }
    if (-not $chkWPrecomp.Checked) { $r.Why = (T 'précompensation désactivée'); return $r }
    if (-not $img -or -not (Test-Path -LiteralPath $img)) { return $r }
    if (Test-RawFluxWrite $img $fmt) { $r.Why = (T 'image flux écrite telle quelle, sans précompensation'); return $r }
    $ie = Get-ImageEncoding $img $fmt
    if ($ie.NonMfm) { $r.Why = (T 'image en codage {0}, écrite sans précompensation') -f "$($ie.Name)"; return $r }
    $r.Applies = $true
    $p = [int]$cmbWProfile.SelectedIndex
    if ($p -eq 1) { $r.Fam = 'std' }
    elseif ($p -eq 2) { $r.Fam = 'long' }
    elseif (Get-HighDensityReason $img $fmt) {
        $r.Block = (T "Écriture pour le lecteur cible {0} impossible en haute densité : la calibration croisée n'existe qu'en double densité (standard, long track). Choisissez « (même lecteur) » dans la liste « Lecteur cible » de l'onglet Écriture, ou le profil Manuel.") -f "$($r.Tgt)"; $r.BlockKind = 'hd'
        return $r
    } else {
        # 12.10 (relecture de la RC, fix2) : famille commune avec le bouton « Courbe » (Update-CurveButton)
        $r.Fam = Get-WriteImageFamily $img $fmt
    }
    $r.Curves = @(Get-TargetCurves $r.Fam $slow $src $r.Tgt)
    if ($r.Curves.Count -eq 0 -and -not $slow -and @(Get-TargetCurves $r.Fam $true $src $r.Tgt).Count -ge 2) { $r.Block = (T "Les courbes croisées {0} → {1} de la famille {2} sont par tête (calibration croisée faite avec « Écriture lente » cochée) : elles ne servent qu'à une écriture lente. Cochez « Écriture lente » dans l'onglet Écriture, ou choisissez « Écriture lente » dans la Bibliothèque ; pour une écriture rapide, relancez « Calibrer pour un lecteur cible… » avec « Écriture lente » décochée (courbe commune).") -f "$src", "$($r.Tgt)", (Get-CalibFamilyName $r.Fam); $r.BlockKind = 'head' }
    elseif ($r.Curves.Count -eq 0) { $r.Block = (T "Aucune courbe croisée {0} → {1} pour la famille {2} : lancez « Calibrer pour un lecteur cible… » (onglet Écriture, lecteur {0} dans le bandeau, lecteur cible {1}), ou choisissez « (même lecteur) » dans la liste « Lecteur cible ».") -f "$src", "$($r.Tgt)", (Get-CalibFamilyName $r.Fam); $r.BlockKind = 'none' }
    return $r
}

function Get-TargetWriteBlock([string]$img, [string]$fmt, [bool]$slow) {
    # 12.10 : raison du refus d une ecriture pour un lecteur cible (Test-TargetWriteAllowed, Start-RestoreWrite), '' quand
    # l ecriture est possible ou que le lecteur cible est sans effet sur elle (Get-TargetWriteInfo)
    return [string](Get-TargetWriteInfo $img $fmt $slow).Block
}

function Test-TargetWriteAllowed([string]$img, [string]$fmt, [bool]$slow) {
    # 12.10 : debut de Start-ImageWrite (bouton ECRIRE, Bibliotheque, restauration, fin d une calibration automatique) :
    # ecriture pour un lecteur cible refusee sans courbe croisee de la famille (Get-TargetWriteBlock) : fenetre
    # (Show-AppMessage, qui ecrit aussi le texte au journal, repondue par le banc), rien n est ecrit. Vrai quand l ecriture
    # continue
    $why = Get-TargetWriteBlock $img $fmt $slow
    if (-not $why) { return $true }
    # Finalisation 12.10 : refus note dans la surcharge d une operation de la Bibliotheque (avis de fin : Show-LibEndNotice)
    if ($script:OpOverride) { $script:OpOverride.Refused = $true }
    [void](Show-AppMessage ((T "Écriture refusée : {0}") -f "$why") (T 'Écriture refusée') 'OK' 'Warning')
    return $false
}

function Set-TargetDriveLayout {
    # 12.10 : positions de la liste « Lecteur cible » sur la ligne de la liste « Mesure : » : libelle 14 px apres la liste,
    # puis la liste, largeur du libelle mesuree dans la police de la fenetre (anglais compris) ; bas de la liste a celui de
    # la liste « Mesure : ». 12.10 (relecture des captures) : bas a 513 px, 3 px au-dessus du bas de l onglet (516 px a la
    # taille par defaut, journal replie) : pas de defilement ; a 517 px, la barre de defilement apparaissait
    if (-not $cmbWTarget -or -not $lblWTarget) { return }
    $x = $cmbWLevelMode.Right + 14
    $lblWTarget.Location = New-Object System.Drawing.Point($x, $lblWLevelMode.Top)
    $x += [System.Windows.Forms.TextRenderer]::MeasureText($lblWTarget.Text, $form.Font).Width + 6
    $cmbWTarget.Location = New-Object System.Drawing.Point($x, $cmbWLevelMode.Top)
}

function Update-TargetDriveUi {
    # 12.10 : liste « Lecteur cible » de l onglet Ecriture : elements (« (meme lecteur) », puis les lecteurs du bandeau sauf
    # celui du bandeau, la source : Get-TargetDriveItems) et choix memorise pour cette source (Get-TargetDrive), sous la
    # garde des liaisons (gestionnaire sans effet), infobulle, positions. Creation de l onglet (520), Load-Config,
    # Set-Defaults, changement de lecteur du bandeau (520, suivi d Update-SlowUi pour la case de la mesure)
    if (-not $cmbWTarget -or -not $lblWTarget) { return }
    $src = [string]$cmbDrive.Text
    $tgt = Get-TargetDrive $src
    $sv = $script:SettingSync; $script:SettingSync = $true
    try {
        $items = [string[]](Get-TargetDriveItems $src)   # tableau protege par la virgule : pas de @() autour de l appel
        $cur = @($cmbWTarget.Items | ForEach-Object { [string]$_ })
        if (($cur -join "`n") -ne ($items -join "`n")) { $cmbWTarget.Items.Clear(); foreach ($it in $items) { [void]$cmbWTarget.Items.Add([string]$it) } }
        $i = 0
        if ($tgt) { $j = [array]::IndexOf([string[]]$items, $tgt); if ($j -gt 0) { $i = $j } }
        if ($cmbWTarget.SelectedIndex -ne $i) { $cmbWTarget.SelectedIndex = $i }
    } finally { $script:SettingSync = $sv }
    # 12.10 (relecture de la RC) : cas sans effet et refus (Get-TargetWriteInfo) dits dans l infobulle ; fix1 : refus de la
    # haute densite en profil Auto seulement (un profil force ecrit avec la courbe croisee de sa famille), codage propre
    # (M2FM, Data General) parmi les cas sans effet, famille du profil force
    $tt = (T "Lecteur qui relira la disquette écrite par le lecteur {0}, celui du bandeau.`n« (même lecteur) » : écriture ordinaire, avec la courbe du lecteur {0} et le facteur de marque.`nUn autre lecteur : l'image est écrite avec la courbe croisée « {0} → lecteur cible » mesurée par « Calibrer pour un lecteur cible… », telle quelle (facteur 1) ; sans courbe croisée pour la famille de l'image (ou du profil forcé), l'écriture est refusée. La mesure de la disquette avant l'écriture et la calibration automatique ne sont pas proposées (elles reliraient avec le lecteur {0}) ; le contrôle après écriture relit avec le lecteur {0}.`nSans effet sur l'écriture (le journal le dit) avec le profil Manuel, la case --precomp décochée, une image flux écrite telle quelle ou une image FM, GCR ou à codage propre ; écriture refusée en haute densité avec le profil Auto, et en écriture rapide quand les courbes croisées sont par tête seulement.`nLe choix est mémorisé pour le lecteur {0}.") -f "$src"
    $tip.SetToolTip($lblWTarget, $tt); $tip.SetToolTip($cmbWTarget, $tt)
    Set-TargetDriveLayout
    # 12.11 (L9) : libelle « Lecteur qui ecrit » du cadre 2, au-dessus de la liste (Update-WSourceLabel, 145)
    if ($lblWSource) { Update-WSourceLabel }
}

function Set-TargetDriveFromUi {
    # 12.10 : gestionnaire SelectedIndexChanged de la liste « Lecteur cible » : choix memorise pour le lecteur du bandeau
    # (Set-TargetDrive ; element 0 : meme lecteur), ligne de journal quand il change, case de la mesure (Update-SlowUi) et
    # profil de l image recalcule (Update-PrecompForImage : courbes croisees, ou courbes du lecteur). Rien sous la garde des
    # liaisons (Update-TargetDriveUi)
    if ($script:SettingSync -or -not $cmbWTarget) { return }
    $src = [string]$cmbDrive.Text
    if (-not $src) { return }
    $tgt = if ($cmbWTarget.SelectedIndex -gt 0) { [string]$cmbWTarget.SelectedItem } else { '' }
    $old = Set-TargetDrive $src $tgt
    $new = Get-TargetDrive $src
    if ($new -ne $old) {
        $same = (T '(même lecteur)')
        Append-Log ((T 'Lecteur cible des écritures du lecteur {0} : {1} (avant : {2}).') -f "$src", $(if ($new) { $new } else { $same }), $(if ($old) { $old } else { $same }))
    }
    Update-SlowUi
    Update-PrecompForImage $txtWFile.Text
}
# ============================== FONCTIONS : ONGLET ECRITURE ====================
# 12.11 (L9) : onglet Ecriture en trois etapes (cadre « 1. Image a ecrire », cadre « 2. Disquette et lecteur », bouton
# ECRIRE avec le lien et la ligne de ses options avancees), toujours visibles et a la meme place dans les deux vues ; le
# cadre « Options avancees » ($grpWAdv, 520) vient dessous, affiche avec la case « Mode expert » seulement. Une option
# avancee repliee garde sa valeur et son effet : le lien la compte, la ligne a droite du bouton la nomme
# (Get-WriteAdvChanges, seule decision). Controles crees par 520 ; positions « a la suite » posees ici, une fois la
# fenetre construite (600, apres Fit-ControlText) et a chaque changement de « Mode expert »
# 12.11 (L10) : la ligne a droite du bouton devient « Ce qui va se passer » (Get-WritePlan) : lecteur qui ecrit,
# effacement, mesure de la disquette, tetes, controle, lecteur cible, options avancees ; un refus la remplace. Chaque
# segment vient de la fonction qui decide l ecriture (140, 260) ; plan garde en memoire par signature des entrees
# (Get-WritePlanCached) ; coupe qui ne retire que des segments descriptifs (Show-WritePlan)

function Get-WriteAdvDefs {
    # 12.11 (L9) : options avancees de l ecriture, dans l ordre du cadre : @{ Ctl (controle) ; Def (valeur par defaut :
    # case, nombre, rang de la liste ou texte) ; Label (libelle qui la nomme, cle du libelle de 520 ; case : son propre
    # texte) }. Valeurs par defaut de Set-Defaults (120) ; reglages lies (profil, prechauffages et leur duree) : celles de
    # $script:SettingDefs (040). Les champs --precomp n y sont pas : le profil les remplit. Table rendue a l appel : les
    # controles n existent qu apres 520
    $pp = [array]::IndexOf([string[]]$script:SettingDefs['precompProfile'].Codes, [string]$script:SettingDefs['precompProfile'].Def)
    return @(
        @{ Ctl = $chkWEraseEmpty; Def = $true; Label = '' }
        @{ Ctl = $chkWNoVerify; Def = $false; Label = '' }
        @{ Ctl = $numWRetries; Def = 10; Label = (T 'Essais :') }
        @{ Ctl = $numWRepair; Def = 3; Label = (T 'Passes de réécriture :') }
        @{ Ctl = $cmbWProfile; Def = $pp; Label = (T 'Profil précomp. :') }
        @{ Ctl = $chkWPrecomp; Def = $true; Label = '' }
        @{ Ctl = $txtWTracks; Def = ''; Label = (T 'Pistes :') }
        @{ Ctl = $cmbWDensel; Def = 0; Label = (T 'Densel :') }
        @{ Ctl = $txtWFakeIdx; Def = ''; Label = (T 'Fake index :') }
        @{ Ctl = $chkWReverse; Def = $false; Label = '' }
        @{ Ctl = $txtWDiskdefs; Def = ''; Label = (T 'Diskdefs :') }
        @{ Ctl = $chkWHard; Def = $false; Label = '' }
        @{ Ctl = $chkWTG43; Def = $false; Label = '' }
        @{ Ctl = $chkWWarm; Def = [bool]$script:SettingDefs['warmSlowWrite'].Def; Label = '' }
        @{ Ctl = $chkWCalWarm; Def = [bool]$script:SettingDefs['warmFullCalib'].Def; Label = '' }
        @{ Ctl = $numWWarmMin; Def = [double]$script:SettingDefs['warmMinutes'].Def; Label = (T 'Durée du préchauffage :') }
    )
}

function Get-WriteAdvChanges {
    # 12.11 (L9) : options avancees differentes de leur valeur par defaut (Get-WriteAdvDefs), seule decision du compte du
    # lien et des noms de la ligne a droite du bouton ECRIRE (Update-WAdvLink), dans les deux vues : une option repliee
    # s applique quand meme. Rend leurs noms, dans l ordre du cadre : case cochee, son texte ; case decochee, son texte
    # suivi de « : decochee » ; liste, nombre ou champ, son libelle et sa valeur (« Pistes : c=0-39 »). Champs compares
    # sans les espaces des bords, comme Start-ImageWrite et Get-WriteFormatArgs (140) les transmettent. Noms rendus un a un :
    # l appelant les recueille par @()
    $names = @()
    foreach ($d in @(Get-WriteAdvDefs)) {
        $c = $d.Ctl
        if (-not $c) { continue }
        if ($c -is [System.Windows.Forms.CheckBox]) {
            if ([bool]$c.Checked -eq [bool]$d.Def) { continue }
            $n = ([string]$c.Text).TrimEnd(' ', ':')
            $names += $(if ($c.Checked) { $n } else { (T '{0} : décochée') -f $n })
        } elseif ($c -is [System.Windows.Forms.NumericUpDown]) {
            if ([double]$c.Value -eq [double]$d.Def) { continue }
            $v = if ([object]::ReferenceEquals($c, $numWWarmMin)) { Get-WarmMinutesText ([double]$c.Value) } else { [string]$c.Value }
            $names += ('{0} {1}' -f [string]$d.Label, $v)
        } elseif ($c -is [System.Windows.Forms.ComboBox]) {
            if ([int]$c.SelectedIndex -eq [int]$d.Def) { continue }
            $names += ('{0} {1}' -f [string]$d.Label, [string]$c.Text)
        } else {
            $v = ([string]$c.Text).Trim()
            if ($v -eq [string]$d.Def) { continue }
            $names += ('{0} {1}' -f [string]$d.Label, $v)
        }
    }
    return $names
}

function Update-WAdvLink([switch]$Typing) {
    # 12.11 (L9) : texte du lien des options avancees : « Masquer les options avancees » quand elles sont affichees (case
    # « Mode expert »), sinon « Options avancees… », avec le compte des options modifiees. Appels : changement d une option
    # avancee (gestionnaires de Register-WAdvCtl), Set-WriteTabLayout. 12.11 (L10) : ligne a droite du bouton ECRIRE par
    # Update-WritePlanUi (« Ce qui va se passer », ou, sans image, les options modifiees nommees, texte du lot L9) ;
    # Typing : frappe dans un champ ou texte d une case change, la phrase deja affichee n est pas recalculee
    if (-not $lnkWAdv -or -not $lblWPlan) { return }
    $ch = @(Get-WriteAdvChanges)
    $lnkWAdv.Text = if ($chkExpert.Checked) { (T 'Masquer les options avancées') } elseif ($ch.Count -gt 0) { (T 'Options avancées : {0} modifiée(s)…') -f "$($ch.Count)" } else { (T 'Options avancées…') }
    Update-WritePlanUi -Typing:$Typing
}

function Update-WPlanTip {
    # 12.11 (L9) : texte complet de la ligne a droite du bouton ECRIRE en infobulle quand il depasse ses trois lignes,
    # aucune infobulle sinon (texte ou taille changes : 520), comme Update-WProfileTip (140). 12.11 (L10) : phrase dont la
    # coupe a retire des segments (Show-WritePlan) : texte complet en infobulle
    $full = [string]$script:WPlanFull
    if ($full -and [string]$lblWPlan.Text -cne $full) { $tip.SetToolTip($lblWPlan, $full); return }
    $h = $lblWPlan.GetPreferredSize((New-Object System.Drawing.Size($lblWPlan.Width, 0))).Height
    $tip.SetToolTip($lblWPlan, $(if ($h -gt $lblWPlan.Height) { [string]$lblWPlan.Text } else { '' }))
}

function Register-WAdvCtl($c) {
    # 12.11 (L9) : gestionnaire ajoute a une option avancee (520) : lien et ligne a jour a chaque changement de sa valeur,
    # et de son texte pour une case (texte de l ecriture lente, duree du prechauffage) ; sans effet sur la valeur. 12.11
    # (L10) : texte d une case (Update-SlowUi, qui finit par Update-WLevelUi) et frappe dans un champ : lien seul tant que
    # la phrase est affichee (Typing) ; champ quitte : phrase recalculee
    if ($c -is [System.Windows.Forms.CheckBox]) { $c.Add_CheckedChanged({ Update-WAdvLink }); $c.Add_TextChanged({ Update-WAdvLink -Typing }) }
    elseif ($c -is [System.Windows.Forms.NumericUpDown]) { $c.Add_ValueChanged({ Update-WAdvLink }) }
    elseif ($c -is [System.Windows.Forms.ComboBox]) { $c.Add_SelectedIndexChanged({ Update-WAdvLink }) }
    elseif ($c -is [System.Windows.Forms.TextBox]) { $c.Add_TextChanged({ Update-WAdvLink -Typing:([bool]$this.Focused) }); $c.Add_Leave({ Update-WritePlanUi }) }
}

function Register-WPlanCtl($c) {
    # 12.11 (L10) : gestionnaire ajoute a un controle de l onglet qui change l ecriture sans passer par Update-WLevelUi
    # (520) : case « Effacer avant d ecrire », case « Controler toutes les pistes », champs --precomp ; frappe dans un champ :
    # phrase recalculee quand il est quitte ; champs remplis par Update-PrecompForImage (WProfileBuilding) : phrase
    # recalculee une fois, par Update-WLevelUi a sa sortie
    if ($c -is [System.Windows.Forms.CheckBox]) { $c.Add_CheckedChanged({ Update-WritePlanUi }) }
    elseif ($c -is [System.Windows.Forms.TextBox]) { $c.Add_TextChanged({ Update-WritePlanUi -Typing:([bool]$this.Focused) }); $c.Add_Leave({ Update-WritePlanUi }) }
}

function Get-WritePlan {
    # 12.11 (L10, specification « onglet-ecriture » § 2.5, corrigee par B1 du plan) : ce que ferait le bouton ECRIRE
    # (Start-WriteTabWrite) avec l onglet tel qu il est : @{ Refuse ; Segs }. Refuse : texte d un refus connu, dans l ordre
    # ou le clic les rencontre (fichier image absent, Start-ImageWrite ; lecteur cible, Get-TargetWriteInfo ; « Test
    # rapide » sans reference, Get-LevelBeforeWritePlan ; tetes, Get-WriteHeads) : il remplace la phrase. Segs : segments
    # @{ T ; Crit }, dans l ordre : lecteur qui ecrit (Get-WriteSourceText), effacement (Get-WriteErasePlan), mesure
    # (Get-WriteLevelPlan puis Get-LevelBeforeWritePlan : texte de la liste « Mesure : » de la mesure faite), tetes
    # (Get-WriteHeads), controle (Get-WriteCheckPlan, sur les profils de Get-WriteSpecPlan et Get-WriteHeadSpecs), lecteur
    # cible (Get-TargetWriteInfo, Get-TargetCurvesText), options avancees (Get-WriteAdvChanges). Crit : mesure refusee
    # (sans mesure, avec sa raison), mesure autre que celle de la liste (repli), controle impose ou non applicable, lecteur
    # cible sans effet : jamais retires par la coupe ; S, leur forme courte (le fait sans sa raison). Aucune ligne de
    # journal, aucune fenetre ; lit l image (appelant : Get-WritePlanCached)
    $img = [string]$txtWFile.Text; $fmt = [string]$cmbWFmt.Text
    $slow = [bool]$chkWSlow.Checked
    $mode = if ($slow) { 'slow' } else { 'fast' }
    $userTs = ([string]$txtWTracks.Text).Trim()
    $r = @{ Refuse = ''; Segs = @() }
    $ex = $false; try { $ex = [bool](Test-Path -LiteralPath $img) } catch { }
    if (-not $ex) { $r.Refuse = (T 'Fichier image introuvable.'); return $r }
    $tw = Get-TargetWriteInfo $img $fmt $slow
    if ($tw.Block) { $r.Refuse = (T "Écriture refusée : {0}") -f "$($tw.Block)"; return $r }
    $wp = Get-WriteLevelPlan $img $fmt $mode
    $lp = $null
    if ($wp.Kind -ne 'none') {
        $lp = Get-LevelBeforeWritePlan ([string]$wp.LbMode) $false ([bool]$wp.LbMeasure)
        if ($lp.Refuse) { $r.Refuse = (T "Écriture refusée : le test rapide n'a pas de référence utilisable pour cette image ({0}).") -f "$($lp.Why)"; return $r }
    }
    $wh = Get-WriteHeads $img $userTs $slow ([bool]$chkWEraseEmpty.Checked)
    if ($wh.Err) { $r.Refuse = ([string]$wh.Err).Replace("`n", ' '); return $r }
    $sg = New-Object System.Collections.ArrayList
    [void]$sg.Add(@{ T = (Get-WriteSourceText); Crit = $false })
    # Effacement. 12.11 (L10, revue J) : effacement haute frequence sans piste a effacer (champ Pistes hors des pistes de
    # l image) : aucune commande gw erase ni --pre-erase (Start-ImageWrite, New-HfreqEraseCmds), « sans effacement »
    $ep = Get-WriteErasePlan $img $fmt $userTs ([int[]]@($wh.Heads)) ([bool]$chkWPreErase.Checked)
    $et = if ($ep.Mode -eq 'hfreq' -and @($ep.EraseKeys).Count -gt 0) { (T 'effacement haute fréquence des pistes') } elseif ($ep.Mode -eq 'pre') { (T 'pré-effacement de chaque piste') } else { (T 'sans effacement') }
    [void]$sg.Add(@{ T = $et; Crit = $false })
    # Mesure de la disquette : omise quand aucune n est demandee. Forme courte d un segment critique (S, sans sa raison) :
    # employee par la coupe quand les segments critiques ne tiennent pas entiers (Show-WritePlan)
    $mt = ''; $mc = $true; $ms = ''; $nw = ''
    $sk = [string]$wp.Skip
    if ($sk -eq 'target') { if ($wp.Asked) { $nw = (T 'lecteur cible {0}') -f "$($wp.Tgt)" } }
    elseif ($sk -eq 'flux') { $nw = (T 'image flux') }
    elseif ($sk -eq 'nonmfm') { $nw = (T 'image en codage {0}') -f "$((Get-ImageEncoding $img $fmt).Name)" }
    elseif ($sk -eq 'kind') { $nw = (T 'image non calibrable') }
    elseif ($sk -eq 'hd') { $nw = (T 'haute densité') }
    elseif ($sk -eq 'profile') { $nw = (T 'profil « {0} »') -f "$($cmbWProfile.Text)" }
    elseif ($sk -eq 'precomp') { $nw = (T 'précompensation désactivée') }
    elseif ($sk -eq 'tracks') { $nw = (T 'champ Pistes') }
    elseif ($sk -eq 'face') { $nw = (T 'image à une seule face') }
    elseif (-not $sk -and $lp) {
        if ($lp.Kind -eq 'none') { $nw = [string]$lp.Why }
        else {
            $kt = Get-SettingText 'levelBeforeWriteMode' ([string]$lp.Kind)
            if ($lp.Cm -and $lp.Kind -ne 'content') {
                $mt = (T "mesure de la disquette : {0}, au lieu de la mesure sur l'image ({1})") -f "$kt", "$($lp.Cm.Why)"
                $ms = (T "mesure de la disquette : {0}, au lieu de la mesure sur l'image") -f "$kt"
            } else { $mt = (T 'mesure de la disquette : {0}') -f "$kt" }
            $mc = ([string]$lp.Kind -ne [string](Get-Setting 'levelBeforeWriteMode'))
        }
    }
    if ($nw) { $mt = (T 'sans mesure de la disquette ({0})') -f "$nw"; $ms = (T 'sans mesure de la disquette') }
    if ($mt) { [void]$sg.Add(@{ T = $mt; Crit = $mc; S = $ms }) }
    # Tetes
    $hs = @($wh.Gw)
    $ht = if ($hs.Count -eq 1) { (T 'écriture de la tête {0} seule') -f "$($hs[0])" } elseif ($hs.Count -ge 2 -and -not $slow) { (T 'écriture des deux têtes ensemble') } elseif ($hs.Count -ge 2) { (T 'écriture tête 0 puis tête 1') } else { '' }
    if ($ht) { [void]$sg.Add(@{ T = $ht; Crit = $false }) }
    # Controle : profils transmis par Start-ImageWrite (avant le facteur), pour la courbe adaptee qui l impose ; drapeau
    # de la calibration rapide qui precede (LevelPostForce), lu comme Start-ImageWrite le lit
    $sp = Get-WriteSpecPlan $img $fmt $slow (Get-ImageEncoding $img $fmt)
    $hr = if ($slow) { Get-WriteHeadSpecs $userTs $sp.P0 $sp.P1 } else { $null }
    # 12.11 (L10, revue J) : calibration rapide ou mesure complete avant l ecriture (Kind 'quick' ou 'complete') : elle
    # remplace les champs --precomp (Set-LevelFields) et remet le drapeau LevelPostForce (Start-LevelCalib) ; le controle
    # impose se decide apres elle (Complete-LevelCalib, Complete-DiskMeasure), pas d apres les champs actuels
    $fresh = ($lp -and @('quick', 'complete') -contains [string]$lp.Kind)
    $cp = if ($fresh) { Get-WriteCheckPlan $img $fmt $slow $wh.Heads @{ 0 = $null; 1 = $null } $null $false } else { Get-WriteCheckPlan $img $fmt $slow $wh.Heads $hr $sp.P0 ([bool]$script:LevelPostForce) }
    $rep = [int]$numWRepair.Value
    if ($cp.Blocker) { [void]$sg.Add(@{ T = ((T 'contrôle de toutes les pistes non applicable ({0})') -f "$($cp.Blocker)"); Crit = $true; S = (T 'contrôle de toutes les pistes non applicable') }) }
    elseif ($cp.Forced -and -not $chkWPostCheck.Checked) { [void]$sg.Add(@{ T = $(if ($rep -gt 0) { (T 'contrôle de toutes les pistes imposé par la courbe adaptée à cette disquette, {0} passe(s) de réécriture au plus') -f "$rep" } else { (T 'contrôle de toutes les pistes imposé par la courbe adaptée à cette disquette, sans réécriture') }); Crit = $true; S = (T 'contrôle de toutes les pistes imposé') }) }
    elseif ($cp.Post) { [void]$sg.Add(@{ T = $(if ($rep -gt 0) { (T 'contrôle de toutes les pistes, {0} passe(s) de réécriture au plus') -f "$rep" } else { (T 'contrôle de toutes les pistes, sans réécriture') }); Crit = $false }) }
    else { [void]$sg.Add(@{ T = (T 'contrôle complet non demandé'); Crit = $false }) }
    # Lecteur cible : courbes croisees ecrites (texte du journal de Start-ImageWrite), ou sans effet (meme texte)
    if ($tw.Applies) { [void]$sg.Add(@{ T = ((T 'pour le lecteur cible {0} : {1}') -f "$($tw.Tgt)", (Get-TargetCurvesText ([string]$tw.Src) ([string]$tw.Tgt) ([string]$tw.Fam) $tw.Curves)); Crit = $false }) }
    elseif ($tw.Tgt -and $tw.Why) {
        $x = (T "Lecteur cible {0} sans effet sur cette écriture : {1}.") -f "$($tw.Tgt)", "$($tw.Why)"
        if ($x.EndsWith('.')) { $x = $x.Substring(0, $x.Length - 1) }
        [void]$sg.Add(@{ T = ($x.Substring(0, 1).ToLower() + $x.Substring(1)); Crit = $true; S = ((T 'lecteur cible {0} sans effet') -f "$($tw.Tgt)") })
    }
    # Options avancees modifiees (le lien les compte)
    $ch = @(Get-WriteAdvChanges)
    if ($ch.Count -gt 0) { [void]$sg.Add(@{ T = ((T 'options avancées : {0}') -f ($ch -join ', ')); Crit = $false }) }
    $r.Segs = @($sg)
    return $r
}

function Get-WritePlanSig {
    # 12.11 (L10) : signature des entrees de Get-WritePlan, cle de la memoire de Get-WritePlanCached : langue ; image, sa
    # taille et sa date (un seul acces au fichier, Get-Item : racine reseau possible) ; format ; lecteur du bandeau et son
    # libelle (Get-DriveLabel : identite et connexion) ; lecteur cible ; cases, listes et champs de l onglet qui changent
    # l ecriture ou la phrase (dont la liste « Calibration precomp » et la liste « Mesure : », par leurs reglages) ; options
    # avancees modifiees ; restauration en cours ; controle impose par la calibration rapide qui precede (LevelPostForce) ;
    # module d analyse SCP ; borne precompMaxNs ; courbes du magasin par
    # lecteur et de la vue du lecteur courant (cle, date, lecteur, methode, nombre de valeurs) ; courbes adaptees des
    # calibrations rapides (cle, modele, profil)
    $img = [string]$txtWFile.Text
    $fi = 'absent'
    try { $it = Get-Item -LiteralPath $img -ErrorAction Stop; $fi = "$($it.GetType().Name)|$($it.Length)|$($it.LastWriteTimeUtc.Ticks)" } catch { }
    $cv = New-Object System.Text.StringBuilder
    foreach ($st in @($script:DriveCurves, $script:PrecompCurves)) {
        if ($st) { foreach ($k in @(@($st.Keys) | Sort-Object)) { $c = $st[$k]; if ($c) { [void]$cv.Append("$k=$($c.Date)|$($c.Drive)|$($c.Method)|$(@($c.Values).Count);") } } }
        [void]$cv.Append('#')
    }
    $ls = ''
    if ($script:LevelShifts) { $ls = (@(@($script:LevelShifts.Keys) | Sort-Object | ForEach-Object { $x = $script:LevelShifts[$_]; if ($x) { "$_=$($x.Model)|$($x.Spec)|$(@($x.Values).Count)" } }) -join ';') }
    $rs = if ($script:Restore) { "1|$(if ($script:Restore.Saved) { $script:Restore.Saved.CalMode })" } else { '0' }
    $rs += "|$([bool]$script:LevelPostForce)"
    $parts = @([string]$script:Lang, $img, $fi, [string]$cmbWFmt.Text, [string]$cmbDrive.Text, (Get-DriveLabel ([string]$cmbDrive.Text)), (Get-TargetDrive),
               "$($chkWSlow.Checked)|$($chkWPreErase.Checked)|$($chkWEraseEmpty.Checked)|$($chkWPostCheck.Checked)|$($numWRepair.Value)|$($chkWLevel.Checked)|$($cmbWCalMode.SelectedIndex)",
               "$($cmbWProfile.SelectedIndex)|$($chkWPrecomp.Checked)|$($chkWHard.Checked)|$($chkWTG43.Checked)", [string]$txtWPrecomp.Text, [string]$txtWPrecomp1.Text, [string]$txtWTracks.Text, [string]$cmbWDensel.Text,
               [string](Get-Setting 'calMode'), [string](Get-Setting 'levelBeforeWriteMode'), (@(Get-WriteAdvChanges) -join '|'),
               $rs, "$($script:ScpStatsOk)|$($script:CalHardNsUser)", $cv.ToString(), $ls)
    return ($parts -join "`n")
}

function Get-WritePlanCached {
    # 12.11 (L10) : plan de la ligne (Get-WritePlan) garde en memoire avec la signature de ses entrees (Get-WritePlanSig) :
    # recalcule seulement quand l une d elles change (image remplacee ou modifiee, format, lecteur ou sa connexion, lecteur
    # cible, reglages de l onglet, courbes) ; sinon, un seul acces au fichier (date de l image)
    $sig = Get-WritePlanSig
    if ($script:WPlanMemo -and [string]$script:WPlanMemo.Sig -ceq $sig) { return $script:WPlanMemo.Plan }
    $p = Get-WritePlan
    $script:WPlanMemo = @{ Sig = $sig; Plan = $p }
    return $p
}

function Format-WritePlan($segs, [switch]$Cut) {
    # 12.11 (L10) : phrase de la ligne : segments separes par « ; », majuscule au premier ; Cut : segments retires par la
    # coupe, phrase finie par « ; … » (texte complet en infobulle)
    $j = (@(@($segs) | ForEach-Object { [string]$_.T }) -join (T ' ; '))
    if ($j.Length -gt 0) { $j = $j.Substring(0, 1).ToUpper() + $j.Substring(1) }
    if ($Cut) { return ((T 'Ce qui va se passer : {0} ; …') -f $j) }
    return ((T 'Ce qui va se passer : {0}.') -f $j)
}

function Get-WPlanHeight([string]$t) {
    # 12.11 (L10) : hauteur du texte $t dans la ligne (meme police, meme largeur, memes options de dessin que $lblWPlan),
    # mesuree sur un libelle de mesure jamais affiche ni ajoute a la fenetre, comme Update-WPlanTip mesure la ligne
    if (-not $script:WPlanMeasure) { $script:WPlanMeasure = New-Object System.Windows.Forms.Label }
    $m = $script:WPlanMeasure
    $m.Font = $lblWPlan.Font; $m.UseMnemonic = $lblWPlan.UseMnemonic; $m.AutoEllipsis = $lblWPlan.AutoEllipsis
    $m.Text = $t
    return $m.GetPreferredSize((New-Object System.Drawing.Size($lblWPlan.Width, 0))).Height
}

function Show-WritePlan {
    # 12.11 (L10) : affiche le plan courant ($script:WPlanCur) dans la ligne, a sa largeur (appel aussi au changement de
    # taille, 520 : sans recalcul du plan). Refus : seul, a l encre d avertissement, en tete ; ses derniers mots peuvent
    # passer sous les points de suspension, texte complet en infobulle. Phrase : entiere si elle tient dans les trois
    # lignes ; sinon, segments descriptifs retires du dernier au premier jusqu a ce qu elle tienne, jamais un segment
    # critique (Crit : mesure refusee ou repliee, controle impose ou non applicable, lecteur cible sans effet) ; s ils ne
    # tiennent pas encore, segments critiques ramenes a leur forme courte (S : le fait sans sa raison), du dernier au
    # premier ; phrase finie par « ; … » et texte complet en infobulle (Update-WPlanTip)
    if (-not $lblWPlan) { return }
    $p = $script:WPlanCur
    if (-not $p) { Update-WPlanTip; return }
    if ($p.Refuse) {
        $full = [string]$p.Refuse; $shown = $full
        $lblWPlan.ForeColor = $script:Theme.WarnInk
    } else {
        $segs = @($p.Segs)
        $full = Format-WritePlan $segs
        $shown = $full
        if ((Get-WPlanHeight $full) -gt $lblWPlan.Height) {
            $keep = New-Object System.Collections.ArrayList
            foreach ($s in $segs) { [void]$keep.Add($s) }
            for ($i = $keep.Count - 1; $i -ge 0 -and $keep.Count -gt 1; $i--) {
                if ($keep[$i].Crit) { continue }
                $keep.RemoveAt($i)
                $shown = Format-WritePlan @($keep) -Cut
                if ((Get-WPlanHeight $shown) -le $lblWPlan.Height) { break }
            }
            for ($i = $keep.Count - 1; $i -ge 0 -and (Get-WPlanHeight $shown) -gt $lblWPlan.Height; $i--) {
                if (-not $keep[$i].Crit -or -not $keep[$i].S) { continue }
                $keep[$i] = @{ T = [string]$keep[$i].S; Crit = $true; S = '' }
                $shown = Format-WritePlan @($keep) -Cut
            }
        }
        $lblWPlan.ResetForeColor()
    }
    $script:WPlanFull = $full
    if ($lblWPlan.Text -cne $shown) { $lblWPlan.Text = $shown } else { Update-WPlanTip }
}

function Update-WritePlanUi([switch]$Typing) {
    # 12.11 (L10) : ligne a droite du bouton ECRIRE. Avant l affichage de la fenetre (aucun acces au fichier au demarrage,
    # racine reseau possible, comme Update-WLevelUi) ou sans image : options avancees modifiees seules, texte du lot L9
    # (« Options avancees : Sans verification. », vide sans option modifiee). Sinon : plan de Get-WritePlanCached, affiche
    # par Show-WritePlan. Typing (frappe dans un champ) ou profil en cours de calcul (Update-PrecompForImage, qui finit par
    # Update-WLevelUi) : phrase deja affichee gardee. Erreur du calcul : texte du lot L9, rien au journal ni a l ecran
    # ($script:WPlanError la garde). Appels : fin d Update-WLevelUi (140), Update-WAdvLink, Register-WAdvCtl,
    # Register-WPlanCtl
    if (-not $lblWPlan) { return }
    if ($script:UiReady -and [string]$txtWFile.Text) {
        if (($Typing -or $script:WProfileBuilding) -and $script:WPlanCur) { return }
        $p = $null
        try { $p = Get-WritePlanCached; $script:WPlanError = '' } catch { $script:WPlanError = [string]$_.Exception.Message; $script:WPlanMemo = $null }
        if ($p) { $script:WPlanCur = $p; Show-WritePlan; return }
    }
    $script:WPlanCur = $null; $script:WPlanFull = ''
    $ch = @(Get-WriteAdvChanges)
    $t = ''
    if ($ch.Count -gt 0) {
        $t = (T 'options avancées : {0}') -f ($ch -join ', ')
        $t = $t.Substring(0, 1).ToUpper() + $t.Substring(1) + '.'
    }
    $lblWPlan.ResetForeColor()
    if ($lblWPlan.Text -cne $t) { $lblWPlan.Text = $t } else { Update-WPlanTip }
}

function Switch-WAdvView {
    # 12.11 (L9) : clic du lien des options avancees : inverse la case « Mode expert » du bandeau (reglage ui.expert de la
    # configuration, qui affiche aussi les onglets techniques), sauf quand elle est inactive (restauration en cours, 300)
    if (-not $chkExpert.Enabled) { return }
    $chkExpert.Checked = -not $chkExpert.Checked
}

function Update-WSourceLabel {
    # 12.11 (L9, decision DL4) : libelle « Lecteur qui ecrit » du cadre « 2. Disquette et lecteur » : texte de
    # Get-WriteSourceText (112 : lecteur du bandeau, nom et connexion de sa fiche), sur la ligne du titre du cadre, aligne
    # sur son bord droit (ancre a droite : il suit la largeur de la fenetre). Appel : Update-TargetDriveUi (140), au
    # changement de lecteur du bandeau, a Load-Config, a Set-Defaults et apres une action de la fenetre « Lecteurs
    # enregistres » (connexion changee sans que le texte du bandeau change)
    if (-not $lblWSource -or -not $grpWOpt) { return }
    $lblWSource.Text = Get-WriteSourceText
    $lblWSource.Left = $grpWOpt.DisplayRectangle.Right - $lblWSource.PreferredWidth
}

function Set-WriteTabLayout {
    # 12.11 (L9) : disposition de l onglet Ecriture. Places a la suite, mesurees dans la police de la fenetre : rangee 1
    # du cadre 2 (quatre cases, 24 px entre elles), liste « Mesure : » apres son libelle, liste « Lecteur cible »
    # (Set-TargetDriveLayout, 140), libelle du lecteur qui ecrit (Update-WSourceLabel) ; champs des options avancees apres
    # leur libelle, cases du materiel apres le bouton de « Diskdefs : ». Vue : cadre des options avancees affiche avec
    # « Mode expert » (seule difference entre les deux vues),
    # lien et ligne (Update-WAdvLink), onglet remis en haut. Seules les places dans les cadres changent : cadres, bouton,
    # lien et ligne gardent celles de 520 (un onglet defile ne decale rien). Appels : demarrage (600, apres Fit-ControlText,
    # qui fixe la largeur des cases), changement de « Mode expert » (520)
    if (-not $grpWAdv -or -not $lnkWAdv) { return }
    $f = $form.Font
    $x = 12
    foreach ($c in @($chkWPreErase, $chkWSlow, $chkWPostCheck, $chkWUnattended)) {
        $c.Location = New-Object System.Drawing.Point($x, 22)
        $x += $c.PreferredSize.Width + 24
    }
    $cmbWLevelMode.Left = $lblWLevelMode.Left + [System.Windows.Forms.TextRenderer]::MeasureText($lblWLevelMode.Text, $f).Width + 8
    Set-TargetDriveLayout
    Update-WSourceLabel
    $numWRetries.Left = $lblWRetries.Left + [System.Windows.Forms.TextRenderer]::MeasureText($lblWRetries.Text, $f).Width + 6
    $numWRepair.Left = $lblWRepair.Left + [System.Windows.Forms.TextRenderer]::MeasureText($lblWRepair.Text, $f).Width + 6
    # Rangee de « Diskdefs : » : cases du materiel a 8 px du bouton et l une de l autre ; en mode expert, l onglet defile a
    # la taille par defaut et sa barre verticale retire 17 px au cadre : la case TG43 tient dans le cadre (maquette : 314 et
    # 525, case TG43 coupee de 5 px par la barre)
    $chkWHard.Left = $btnWDiskdefs.Right + 8
    $chkWTG43.Left = $chkWHard.Left + $chkWHard.PreferredSize.Width + 8
    $numWWarmMin.Left = $lblWWarmMin.Left + [System.Windows.Forms.TextRenderer]::MeasureText($lblWWarmMin.Text, $f).Width + 8
    $lblWWarmMinU.Left = $numWWarmMin.Right + 6
    $grpWAdv.Visible = [bool]$chkExpert.Checked
    Update-WAdvLink
    $tabW.AutoScrollPosition = New-Object System.Drawing.Point(0, 0)
}
# ============================== FONCTIONS : PISTES, OPTIONS DE LECTURE, HAUTE DENSITE ===

function Get-TrackKeyOrder([string]$k) {
    $p = $k -split '\.'
    return ([int]$p[0] * 2 + [int]$p[1])
}

function Sort-TrackKeys($keys) {
    # La virgule empeche PowerShell de transformer un tableau vide en $null au retour de la fonction
    return ,@(@($keys) | Where-Object { $_ } | Sort-Object { Get-TrackKeyOrder $_ })
}

function Format-TrackList($keys, [int]$max = 24) {
    # Liste de pistes pour le journal, tronquee au-dela de $max entrees
    $k = @($keys)
    if ($k.Count -le $max) { return ($k -join ', ') }
    return ((@($k[0..($max - 1)]) -join ', ') + ((T " ... (+{0})") -f "$($k.Count - $max)"))
}

function Get-ImageTrackSet([string]$path) {
    # Pistes presentes dans l image ('cyl.tete' -> $true), $null si non determinable
    $set = @{}
    $ext = [System.IO.Path]::GetExtension($path).ToLower()
    try {
        switch ($ext) {
            '.ipf' {
                $d = [System.IO.File]::ReadAllBytes($path); $pos = 0
                while ($pos + 12 -le $d.Length) {
                    $id = [System.Text.Encoding]::ASCII.GetString($d, $pos, 4); $ln = Get-BE32 $d ($pos + 4)
                    if ($ln -lt 12) { break }
                    if ($id -eq 'IMGE' -and $pos + 12 + 44 -le $d.Length) {
                        $cyl  = Get-BE32 $d ($pos + 12)          # piste (cylindre)
                        $side = Get-BE32 $d ($pos + 16)          # face
                        $bits = Get-BE32 $d ($pos + 12 + 36)     # bits de la piste
                        $blk  = Get-BE32 $d ($pos + 12 + 40)     # nombre de blocs : 0 = piste vide
                        if ($blk -gt 0 -and $bits -gt 0 -and $cyl -lt 200 -and $side -le 1) { $set["$cyl.$side"] = $true }
                    } elseif ($id -eq 'DATA' -and $pos + 16 -le $d.Length) { $ln += Get-BE32 $d ($pos + 12) }
                    $pos += $ln
                }
            }
            '.hfe' {
                $fs = [System.IO.File]::OpenRead($path)
                try { $h = New-Object byte[] 16; [void]$fs.Read($h, 0, 16) } finally { $fs.Dispose() }
                $nt = [int]$h[9]; $ns = [math]::Max(1, [math]::Min(2, [int]$h[10]))
                for ($c = 0; $c -lt $nt; $c++) { for ($hd = 0; $hd -lt $ns; $hd++) { $set["$c.$hd"] = $true } }
            }
            '.adf' {
                $n = Get-ImageCylinders $path
                if ($null -ne $n) { for ($c = 0; $c -lt $n; $c++) { $set["$c.0"] = $true; $set["$c.1"] = $true } }
            }
            '.scp' {
                # 12.8 (decision 3 du 21/10/2026) : copie de flux : pistes presentes dans la table des pistes de l en-tete
                # (168 entrees, decalage non nul) ; octet 10 : 0 les deux faces (piste = cylindre x 2 + face), 1 ou 2 une
                # seule face (0 ou 1), numerotee cylindre x 2 + face ou, a l ancienne, par cylindre
                $fs = [System.IO.File]::OpenRead($path)
                $hb = New-Object byte[] (16 + 4 * 168)
                try { $nr = $fs.Read($hb, 0, $hb.Length) } finally { $fs.Dispose() }
                if ($nr -eq $hb.Length -and [System.Text.Encoding]::ASCII.GetString($hb, 0, 3) -eq 'SCP') {
                    $ss = [int]$hb[10]
                    $idx = @(0..167 | Where-Object { [BitConverter]::ToUInt32($hb, 16 + 4 * $_) -ne 0 })
                    if ($ss -eq 1 -or $ss -eq 2) {
                        $hd = $ss - 1
                        $paired = (@($idx | Where-Object { $_ % 2 -ne $hd }).Count -eq 0)
                        foreach ($t in $idx) { $c = if ($paired) { [int][math]::Floor($t / 2) } else { $t }; $set["$c.$hd"] = $true }
                    } else {
                        foreach ($t in $idx) { $set["$([int][math]::Floor($t / 2)).$($t % 2)"] = $true }
                    }
                }
            }
        }
    } catch { $set = @{} }
    if ($set.Count -gt 0) { return $set }
    return $null
}

function Get-ImageFaces([string]$path) {
    # 12.10 (lot 1, E9-image, constat I-3) : faces de l image d apres Get-ImageTrackSet, pour Get-FaceSafeWrite (Set-WritePreset
    # et image gardee apres la Bibliotheque). @{ Unknown : pistes de l image non determinables ; OneHead : tete de l unique
    # face, $null si deux faces ou faces inconnues }
    $set = Get-ImageTrackSet $path
    $r = @{ Unknown = ($null -eq $set); OneHead = $null }
    if (-not $r.Unknown) {
        $hs = @(@($set.Keys) | ForEach-Object { [int](([string]$_ -split '\.')[1]) } | Sort-Object -Unique)
        if ($hs.Count -eq 1) { $r.OneHead = $hs[0] }
    }
    return $r
}

function Get-TSpecExtras([string]$tspec) {
    # Elements du TSPEC utilisateur autres que c= et h= (step, h0.off, h1.off, hswap...) : conserves
    # tels quels dans les reecritures et relectures ciblees, pour viser les memes pistes physiques.
    if (-not $tspec) { return '' }
    $x = @($tspec -split ':' | Where-Object { $_.Trim() -and $_ -notmatch '^\s*[ch]\s*=' })
    if ($x.Count -eq 0) { return '' }
    return ':' + ($x -join ':')
}

function Get-TSpecCH([string]$tspec) {
    # 12.10 (lot 1, E9-image) : elements c= et h= du TSPEC utilisateur (complement de Get-TSpecExtras), joints par ':' ;
    # chaine vide s il n y en a pas
    return (@("$tspec" -split ':' | Where-Object { $_ -match '^\s*[ch]\s*=' } | ForEach-Object { $_.Trim() }) -join ':')
}

function Get-TSpecHeads([string]$tspec) {
    # Tetes 0 et 1 retenues par le TSPEC utilisateur (h=0, h=1, h=0-1, h=0,1) ; les deux si h= est absent
    $m = [regex]::Match(":$tspec", ':\s*h\s*=\s*([^:]*)')
    if (-not $m.Success) { return ,@(0, 1) }
    $hs = @()
    foreach ($r in ($m.Groups[1].Value -split ',')) {
        if ($r -match '^\s*(\d+)\s*-\s*(\d+)\s*$') { for ($i = [int]$Matches[1]; $i -le [int]$Matches[2]; $i++) { $hs += $i } }
        elseif ($r -match '^\s*(\d+)\s*$') { $hs += [int]$Matches[1] }
    }
    return ,@(@(0, 1) | Where-Object { $hs -contains $_ })
}

function Set-TSpecHead([string]$tspec, [int]$h) {
    # TSPEC utilisateur restreint a la tete h : c=, step, h0.off, h1.off et hswap conserves. Sans c=, gw garde
    # les cylindres par defaut du format (ou c=0-81), comme l ecriture normale.
    $parts = @($tspec -split ':' | Where-Object { $_.Trim() -and $_ -notmatch '^\s*h\s*=' })
    return ((@($parts) + "h=$h") -join ':')
}

function Get-TSpecSelection([string]$tspec) {
    # 12.8 (FIX-PISTES) : pistes retenues par c= et h= du champ Pistes, syntaxe de gw (c=0-79, c=0,10,20, c=0-79/2 ; h=0,
    # h=0-1, h=0,1). Renvoie @{ Cyls : cylindres retenus (table), $null sans c= ou si c= est illisible ; Heads : tetes 0
    # et 1 retenues (Get-TSpecHeads) ; Restricts : c= ou h= present ; Ok : $false si c= est illisible (cylindres inconnus) }
    $r = @{ Cyls = $null; Heads = @(0, 1); Restricts = $false; Ok = $true }
    $ts = "$tspec".Trim()
    if (-not $ts) { return $r }
    $mc = [regex]::Match(":$ts", ':\s*c\s*=\s*([^:]*)')
    if ($mc.Success) {
        $r.Restricts = $true
        $cy = @{}
        foreach ($p in ($mc.Groups[1].Value -split ',')) {
            $m = [regex]::Match($p, '^\s*(\d{1,3})\s*(?:-\s*(\d{1,3})\s*(?:/\s*(\d{1,2})\s*)?)?$')
            if (-not $m.Success) { $r.Ok = $false; break }
            $s = [int]$m.Groups[1].Value
            $e = if ($m.Groups[2].Success) { [int]$m.Groups[2].Value } else { $s }
            $st = if ($m.Groups[3].Success) { [math]::Max(1, [int]$m.Groups[3].Value) } else { 1 }
            for ($c = $s; $c -le $e; $c += $st) { $cy[$c] = $true }
        }
        if ($r.Ok) { $r.Cyls = $cy }
    }
    # Get-TSpecHeads rend son tableau sans le derouler (virgule) : pas de @() autour, qui l emboiterait
    if ([regex]::IsMatch(":$ts", ':\s*h\s*=')) { $r.Restricts = $true; $r.Heads = Get-TSpecHeads $ts }
    return $r
}

function Test-TSpecKey($sel, [string]$k) {
    # Piste 'cyl.tete' retenue par une selection de Get-TSpecSelection
    $p = $k -split '\.'
    if (@($sel.Heads) -notcontains [int]$p[1]) { return $false }
    return ($null -eq $sel.Cyls -or $sel.Cyls.ContainsKey([int]$p[0]))
}

function Get-WritePartial([string]$img, [string]$fmt, [string]$tspec) {
    # 12.8 (FIX-PISTES, essai du 21/10/2026) : ecriture partielle demandee par c= ou h= du champ Pistes, c est-a-dire des
    # pistes de l image qui ne seraient pas ecrites. $null quand le champ n en retire aucune : champ vide, elements de
    # lecteur seuls (step, hswap, h0.off, h1.off : toutes les pistes ecrites), c= et h= qui couvrent toute l image, ou
    # aucune tete retenue (h=2 : refus de Start-ImageWrite ou erreur de gw, inchanges). Sinon @{ Spec : c= et h= du champ ;
    # Kept : pistes de l image ecrites ; Total : pistes de l image, -1 si inconnues }. Pistes de l image : Get-ImageTrackSet,
    # sinon cylindres (Get-ImageCylinders) et faces du format gw ; inconnues : partielle des que c= est present ou qu une
    # seule tete est retenue.
    # 12.8 (FIX-PISTES-2) : step= autre que 1 (pas du lecteur par cylindre, decision A « c=, h=, step= ») est aussi
    # signale, seul ou avec c= et h= ; seul le bouton ECRIRE consulte cette fonction (Confirm-PartialWrite), jamais la
    # Bibliotheque ni la restauration. Renvoie alors @{ Partial : c= ou h= retirent des pistes (Spec, Kept, Total comme
    # ci-dessus ; sinon Spec vide, Kept et Total a -1) ; Step : valeur de step=, 0 si absent ou egal a 1 }.
    $sel = Get-TSpecSelection $tspec
    if (@($sel.Heads).Count -eq 0) { return $null }
    $ms = [regex]::Match(":$tspec", ':\s*step\s*=\s*(\d{1,2})\s*(?=:|$)')
    $step = if ($ms.Success -and [int]$ms.Groups[1].Value -ne 1) { [int]$ms.Groups[1].Value } else { 0 }
    $p = $null
    if ($sel.Restricts) {
        $spec = Get-TSpecCH $tspec
        $set = Get-ImageTrackSet $img
        if ($null -eq $set) {
            $n = Get-ImageCylinders $img
            if ($null -ne $n -and [int]$n -gt 0) {
                $fe = if ($fmt -and $fmt -ne '(auto)' -and $script:GwFormats.Contains($fmt)) { $script:GwFormats[$fmt] } else { $null }
                $hs = @(if ($fe -and [int]$fe.Heads -eq 1) { 0 } else { 0, 1 })
                $set = @{}
                for ($c = 0; $c -lt [int]$n; $c++) { foreach ($h in $hs) { $set["$c.$h"] = $true } }
            }
        }
        if ($null -eq $set -or -not $sel.Ok) {
            # Pistes de l image inconnues : h=0-1 seul ne retire rien
            if (-not ($sel.Ok -and $null -eq $sel.Cyls -and @($sel.Heads).Count -eq 2)) { $p = @{ Spec = $spec; Kept = -1; Total = -1 } }
        } else {
            $kept = @(@($set.Keys) | Where-Object { Test-TSpecKey $sel $_ }).Count
            if ($kept -lt $set.Count) { $p = @{ Spec = $spec; Kept = $kept; Total = $set.Count } }
        }
    }
    if (-not $p -and -not $step) { return $null }
    if ($p) { $p.Partial = $true } else { $p = @{ Partial = $false; Spec = ''; Kept = -1; Total = -1 } }
    $p.Step = $step
    return $p
}

function Get-TrackGroups($keys) {
    # Pistes -> TSPEC exacts (aucune piste en trop) : cylindres a deux faces en h=0-1, puis face 0 seule, puis face 1 seule
    $heads = @{}
    foreach ($k in @($keys)) {
        $p = $k -split '\.'; $c = [int]$p[0]; $hd = [int]$p[1]
        if (-not $heads.ContainsKey($c)) { $heads[$c] = @{} }
        $heads[$c][$hd] = $true
    }
    $both = @(); $h0 = @(); $h1 = @()
    foreach ($c in ($heads.Keys | Sort-Object)) {
        if ($heads[$c].ContainsKey(0) -and $heads[$c].ContainsKey(1)) { $both += [int]$c }
        elseif ($heads[$c].ContainsKey(0)) { $h0 += [int]$c } else { $h1 += [int]$c }
    }
    $g = @()
    if ($both.Count -gt 0) { $g += "c=$(Format-CylList $both):h=0-1" }
    if ($h0.Count -gt 0)   { $g += "c=$(Format-CylList $h0):h=0" }
    if ($h1.Count -gt 0)   { $g += "c=$(Format-CylList $h1):h=1" }
    return ,$g
}

function Test-AdfHd([string]$path) {
    # ADF haute densite : multiple de 22 528 octets (2 faces x 22 secteurs x 512) au-dela de 84 cylindres double
    # densite, meme regle que Get-ImageCylinders et New-CalibPattern
    try { $len = (Get-Item -LiteralPath $path).Length } catch { return $false }
    return ($len -gt 0 -and $len % 22528 -eq 0 -and $len / 11264 -gt 84)
}

function Test-NeedsFormat([string]$path) {
    # Image secteur brute, sans geometrie : gw exige --format (classe IMG pour .img, .ima et .st ; .dsk sans signature
    # CPC, dsk.py : un DSK Apricot est lu par Apridisk, derive d IMG, qui exige aussi le format)
    $ext = [System.IO.Path]::GetExtension($path).ToLower()
    if (@('.img', '.ima', '.st') -contains $ext) { return $true }
    if ($ext -ne '.dsk') { return $false }
    try {
        $fs = [System.IO.File]::OpenRead($path)
        try { $b = New-Object byte[] 24; $n = $fs.Read($b, 0, 24) } finally { $fs.Dispose() }
        $s = [System.Text.Encoding]::ASCII.GetString($b, 0, $n)
        if ($s.StartsWith('MV - CPC') -or $s.StartsWith('EXTENDED CPC DSK')) { return $false }
    } catch { }
    return $true
}

function Test-HdFormat([string]$fmt) {
    # Formats gw a 500 ou 1000 kbit/s (diskdefs) : *_hd, *.1200, *.1440, *.1600, *.1680, *.dmf, *.2880, pc98.2hd/2hs,
    # *.hd, *.ed, os9.80dshd_*, luxor.1000.*, hp.mmfm.* (cellule de 1 us), raw.500, raw.1000
    if (-not $fmt) { return $false }
    return ($fmt -match '(_hd|dshd_\d+|\.(1200|1440|1600|1680|dmf|2880|2hd|2hs|hd|ed))$' -or $fmt -match '^(raw\.(500|1000)$|luxor\.1000\.|hp\.mmfm\.)')
}

function Get-CellOutOfRange([string]$path) {
    # Cellule d une image IPF ou HFE hors des plages que la calibration sait mesurer : ScpStats exige des 2T entre
    # 3 et 5 us, soit une cellule de 1,5 a 2,5 us ; marges retenues 1 700 a 2 300 ns (MFM double densite, long track
    # compris) et, 12.7, 900 a 1 100 ns (haute densite). Renvoie la cellule arrondie (ns), $null si elle est dans une
    # plage ou non lue (autres formats).
    $ext = [System.IO.Path]::GetExtension($path).ToLower()
    $info = $null
    try { switch ($ext) { '.ipf' { $info = Get-IpfCellInfo $path } '.hfe' { $info = Get-HfeCellInfo $path } } } catch { return $null }
    if ($null -eq $info -or [double]::IsNaN([double]$info.CellNs)) { return $null }
    $cn = [double]$info.CellNs
    if (-not (($cn -ge 1700 -and $cn -le 2300) -or ($cn -ge 900 -and $cn -le 1100))) { return [int][math]::Round($cn, 0) }
    return $null
}

function Get-DriveReadArgs {
    # Options de lecteur de l onglet Ecriture utilisables en relecture (controle apres ecriture, calibration) : sans
    # --fake-index, un lecteur sans capteur d index ne relit rien
    $o = @()
    if ($chkWReverse.Checked)         { $o += '--reverse' }
    if ($cmbWDensel.Text -ne '(non)') { $o += "--densel=$($cmbWDensel.Text)" }
    if ($txtWFakeIdx.Text.Trim())     { $o += "--fake-index=$($txtWFakeIdx.Text.Trim())" }
    return $o
}

function Get-HighDensityReason([string]$path, [string]$fmt) {
    # Image ou format haute densite ; $null sinon. 12.7 : une haute densite calibrable a sa propre famille (hd,
    # Get-HdCalibFamily), distincte des familles double densite (standard 2 us, long track 1,89 us).
    # Sans format explicite : format implicite de gw pour l extension (HDM, XDF, FDI, DIM, DCP : pc98.2hd ou 2hs ;
    # D2M, D4M : CMD FD2000 HD, FD4000 ED), image secteur brute de 1 200 000 octets ou plus, mode de la premiere
    # piste d un IMD. 12.10 (lot 1, B1) : formats implicites lus dans la table unique $script:ExtDefaultFmt (040)
    $ext = [System.IO.Path]::GetExtension($path).ToLower()
    if (-not $fmt -or $fmt -eq '(auto)') {
        if ($script:ExtDefaultFmt.ContainsKey($ext)) { $fmt = $script:ExtDefaultFmt[$ext] }
    }
    if (Test-HdFormat $fmt) { return ((T "format haute densité {0}") -f "$fmt") }
    try {
        if ($ext -eq '.adf' -and (Test-AdfHd $path)) { return (T 'ADF haute densité') }
        if (@('.img', '.ima', '.st', '.dsk', '.msa') -contains $ext) {
            $len = (Get-Item -LiteralPath $path).Length
            if ($len -ge 1200000) { return ((T "image secteur de {0} octets") -f "$len") }
        }
        if ($ext -eq '.imd') {
            # IMD : en-tete texte termine par 0x1A, puis mode de la premiere piste (0 = FM, 3 = MFM a 500 kbit/s)
            $fs = [System.IO.File]::OpenRead($path)
            try { $b = New-Object byte[] 65536; $n = $fs.Read($b, 0, $b.Length) } finally { $fs.Dispose() }
            $i = [Array]::IndexOf($b, [byte]0x1A, 0, $n)
            if ($i -ge 0 -and $i + 1 -lt $n -and ($b[$i + 1] -eq 0 -or $b[$i + 1] -eq 3)) { return (T 'image IMD à 500 kbit/s') }
        }
        $info = $null
        switch ($ext) { '.ipf' { $info = Get-IpfCellInfo $path } '.hfe' { $info = Get-HfeCellInfo $path } }
        if ($null -ne $info -and $info.CellNs -lt 1500) { return ((T "image haute densité, cellule {0} ns") -f "$([math]::Round($info.CellNs, 0))") }
    } catch { }
    return $null
}

function Get-HdCalibFamily([string]$path, [string]$fmt) {
    # 12.7 : famille de calibration haute densite d une image : 'hd' (MFM, 1 us par cellule, 300 tr/min) ou $null (double
    # densite, ou haute densite non calibrable : ED, codages propres, 360 tr/min). Format explicite de la table, ou
    # implicite de l extension (meme table que Get-HighDensityReason) : sa famille (Get-FormatCalibInfo), le format
    # l emporte ; sinon ADF HD ; sinon IPF ou HFE de cellule 900 a 1 100 ns (cellule lue pour un tour de 200 ms : un HFE
    # haute densite a 360 tr/min se lit a 1 200 ns, hors plage, comme en 12.6). 12.10 (lot 1, B1) : formats implicites de
    # la table unique $script:ExtDefaultFmt (040) ; cellule physique des HFE FM et Apple II (Get-HfeCellInfo)
    $ext = [System.IO.Path]::GetExtension($path).ToLower()
    $f = $fmt
    if (-not $f -or $f -eq '(auto)') {
        $f = if ($script:ExtDefaultFmt.ContainsKey($ext)) { $script:ExtDefaultFmt[$ext] } else { '' }
    }
    if ($f -and $script:GwFormats.Contains($f)) {
        if ([string](Get-FormatCalibInfo $f).Cal -eq 'hd') { return 'hd' }
        return $null
    }
    try {
        if ($ext -eq '.adf' -and (Test-AdfHd $path)) { return 'hd' }
        $info = $null
        switch ($ext) { '.ipf' { $info = Get-IpfCellInfo $path } '.hfe' { $info = Get-HfeCellInfo $path } }
        if ($null -ne $info -and [double]$info.CellNs -ge 900 -and [double]$info.CellNs -le 1100) { return 'hd' }
    } catch { }
    return $null
}

function Get-ImageEncoding([string]$path, [string]$fmt) {
    # 12.10 (lot 1, B1) : codage d une image a ecrire. Enc : 'mfm', 'fm', 'fm0' (piste 0 en FM, les autres en MFM), 'gcr',
    # 'other' (codage propre au systeme : M2FM, Data General) ou '' (inconnu : MFM suppose, comme en 12.8) ;
    # Src : origine, pour le journal ; Name : nom du codage dans les textes ; NonMfm : FM, GCR ou codage propre, ecrits sans
    # --precomp (Start-ImageWrite : la precompensation de gw, regle du MFM par defaut, et la courbe du lecteur ne valent
    # que pour le MFM). Ordre : format explicite de la table GwFormats (amiga et bit : MFM ; c64, a2 et mac : GCR ; scan :
    # inconnu) ; sans format explicite, format implicite de gw pour l extension ($script:ExtDefaultFmt) ; sinon en-tete :
    # HFE (octet 11, Get-HfeCellInfo ; 0xFF, valeur par defaut de gw : inconnu, decision B-D2), IMD (mode de la premiere
    # piste : 0 a 2 en FM) ou D88 (drapeau 0x40 du premier secteur : FM, d88.py). Format explicite absent de la table (gw
    # plus recent, fichier diskdefs) : en-tete seul. 12.10 (lot 1, R1-corrections-revue, constat a) : secteurs durs ('hard')
    # au codage de leur famille, comme les codecs de gw 1.23 (micropolis.py : mfm_encode ; northstar.py : mode fm ou mfm
    # du format) : northstar.fm.* en FM, micropolis.* et northstar.mfm.* en MFM (--precomp transmis, comme en 12.8)
    $r = @{ Enc = ''; Src = ''; Name = ''; NonMfm = $false }
    $ext = [System.IO.Path]::GetExtension("$path").ToLower()
    $f = ''; $src = ''
    if ($fmt -and $fmt -ne '(auto)') { if ($script:GwFormats.Contains($fmt)) { $f = $fmt; $src = (T "format {0}") -f "$fmt" } }
    elseif ($script:ExtDefaultFmt.ContainsKey($ext)) { $f = $script:ExtDefaultFmt[$ext]; $src = (T "format {0} déduit de l'extension {1}") -f "$f", "$ext" }
    if ($f) {
        $e = [string]$script:GwFormats[$f].Enc
        $r.Enc = switch ($e) { 'amiga' { 'mfm' } 'bit' { 'mfm' } 'c64' { 'gcr' } 'a2' { 'gcr' } 'mac' { 'gcr' } 'm2fm' { 'other' } 'dg' { 'other' } 'hard' { if ($f -match '^northstar\.fm\.') { 'fm' } elseif ($f -match '^(micropolis|northstar\.mfm)\.') { 'mfm' } else { 'other' } } 'scan' { '' } default { $e } }
        if ($r.Enc) { $r.Src = $src }
    } elseif ($path -and (Test-Path -LiteralPath $path)) {
        try {
            if ($ext -eq '.hfe') { $r.Enc = [string](Get-HfeCellInfo $path).Enc; $src = (T 'en-tête HFE') }
            elseif ($ext -eq '.imd') {
                # En-tete texte termine par 0x1A, puis mode de la premiere piste (imd.py : 0 a 2 en FM, 3 a 5 en MFM)
                $fs = [System.IO.File]::OpenRead($path)
                try { $b = New-Object byte[] 65536; $n = $fs.Read($b, 0, $b.Length) } finally { $fs.Dispose() }
                $i = [Array]::IndexOf($b, [byte]0x1A, 0, $n)
                if ($i -ge 0 -and $i + 1 -lt $n -and $b[$i + 1] -le 5) { $r.Enc = $(if ($b[$i + 1] -le 2) { 'fm' } else { 'mfm' }) }
                $src = (T 'en-tête IMD')
            } elseif ($ext -eq '.d88') {
                # En-tete de 32 octets, table des pistes (decalages sur 4 octets) a l offset 0x20 ; premiere piste presente :
                # en-tete de son premier secteur (16 octets), drapeau de densite a l offset 6
                $fs = [System.IO.File]::OpenRead($path)
                try {
                    $b = New-Object byte[] 688; $n = $fs.Read($b, 0, $b.Length); $o = [int64]0
                    for ($t = 0; $t -lt 164 -and 36 + 4 * $t -le $n; $t++) { $o = [int64][BitConverter]::ToUInt32($b, 32 + 4 * $t); if ($o -ne 0) { break } }
                    if ($o -ge 32 -and $o + 16 -le $fs.Length) {
                        $sh = New-Object byte[] 16; [void]$fs.Seek($o, [System.IO.SeekOrigin]::Begin)
                        if ($fs.Read($sh, 0, 16) -eq 16) { $r.Enc = $(if ($sh[6] -eq 0x40) { 'fm' } else { 'mfm' }) }
                    }
                } finally { $fs.Dispose() }
                $src = (T 'en-tête D88')
            }
        } catch { $r.Enc = '' }
        if ($r.Enc) { $r.Src = $src }
    }
    $r.NonMfm = (@('fm', 'gcr', 'other') -contains $r.Enc)
    $r.Name = switch ($r.Enc) { 'fm' { (T 'FM') } 'gcr' { (T 'GCR') } 'other' { (T 'propre au système') } default { '' } }
    return $r
}

function Test-NonMfmWrite([string]$img, [string]$fmt) {
    # 12.10 (lot 1, B1) : image FM, GCR ou a codage propre (Get-ImageEncoding) : ecrite sans --precomp en profil Auto ou
    # force (decision B-D1), sans calibration ni mesure de la disquette avant l ecriture
    return [bool](Get-ImageEncoding $img $fmt).NonMfm
}

function Test-ScpHighDensity([string]$path) {
    # Flux MFM double densite : aucun intervalle sous 3 us (2T = 4 us). Haute densite : 2T = 2 us, donc
    # une large part d intervalles sous 2,6 us. Premier tour de la premiere piste presente.
    $d = [System.IO.File]::ReadAllBytes($path)
    if ($d.Length -lt 700 -or [System.Text.Encoding]::ASCII.GetString($d, 0, 3) -ne 'SCP') { return $false }
    $res = ($d[11] + 1) * 25
    for ($t = 0; $t -lt 168; $t++) {
        $o = [BitConverter]::ToUInt32($d, 16 + 4 * $t)
        if ($o -eq 0) { continue }
        $ln = [BitConverter]::ToUInt32($d, $o + 8); $doff = [BitConverter]::ToUInt32($d, $o + 12)
        $flux = [ScpStats]::Decode($d, [int]($o + $doff), [int]$ln, $res)
        if ($flux.Count -lt 1000) { continue }
        $short = @($flux | Where-Object { $_ -gt 500 -and $_ -lt 2600 }).Count
        return ($short -gt 0.2 * $flux.Count)
    }
    return $false
}

# --- Effacement avant l ecriture (12.8.2) ----------------------------------------------------------------------------
# Essais du 27/10/2026 (E1, E2, E5) : un lecteur haute densite (Sony MPF920-Z) qui ecrit des disquettes double densite
# (cellule 2 us) perd 35 a 65 ns de marge, relue sur un lecteur double densite, avec le pre-effacement de gw
# (--pre-erase : effacement en courant continu, WGATE sans WDATA, 1,1 tour avant chaque essai d ecriture) ; un effacement
# haute frequence des pistes par le lecteur qui ecrit (gw erase --hfreq), puis une ecriture sans --pre-erase, gagne +61 /
# +64 ns sur cette methode. Regle « double densite » : toute ecriture, mesure ou calibration dont l image ou la famille
# n est pas haute densite : effacement haute frequence ('hfreq') ; haute densite, non essayee : pre-effacement de la
# 12.8.1 ('pre'). --erase-empty inchange (pistes absentes de l image, effacees en continu par gw : sans donnees).

function Test-ScpDensityUnknown([string]$img) {
    # Flux SCP dont la densite n est pas mesurable : module d analyse SCP absent (Test-ScpHighDensity a besoin de ScpStats)
    return ((-not $script:ScpStatsOk) -and [System.IO.Path]::GetExtension("$img").ToLower() -eq '.scp')
}

function Test-ImageHighDensity([string]$img, [string]$fmt) {
    # Image haute densite pour l effacement avant l ecriture : famille hd (Get-ImageFamily), haute densite non calibrable
    # (Get-HighDensityReason : ED, 360 tr/min, codages propres...) ou flux SCP haute densite (Test-ScpHighDensity, module
    # d analyse SCP present) ; flux SCP de densite inconnue (Test-ScpDensityUnknown) : traite comme haute densite, donc
    # pre-effacement de la 12.8.1 (revue 12.8.2) ; autre densite inconnue ou fichier illisible : double densite, comme
    # Get-ImageFamily
    try {
        if ((Get-ImageFamily $img $fmt) -eq 'hd') { return $true }
        if (Get-HighDensityReason $img $fmt) { return $true }
        if (Test-ScpDensityUnknown $img) { return $true }
        if ($script:ScpStatsOk -and [System.IO.Path]::GetExtension("$img").ToLower() -eq '.scp' -and (Test-Path -LiteralPath $img) -and (Test-ScpHighDensity $img)) { return $true }
    } catch { }
    return $false
}

function Get-EraseFallbackNote {
    # Options de lecteur de l onglet Ecriture qui imposent le pre-effacement de la 12.8.1 (Get-EraseMode) : texte de la
    # ligne de journal, $null sinon. gw erase 1.23 n accepte que --device, --drive, --revs, --tracks, --hfreq et
    # --fake-index : secteurs durs (gw erase mesure la duree d un tour sur l index, qu un disque a secteurs durs
    # fausserait) ; TG43 et --densel (revue 12.8.2) : broche 2, que gw erase ne regle pas, l effacement se ferait dans un
    # autre etat de la broche que l ecriture (5,25 pouces haute densite bivitesse, 8 pouces : non essaye)
    if ($chkWHard.Checked -or $chkWTG43.Checked) { return (T "Effacement avant l'écriture : secteurs durs ou lecteur 8 pouces (TG43), que gw erase ne prend pas en charge : pré-effacement de chaque piste (--pre-erase), comme avant.") }
    if ($cmbWDensel.Text -and $cmbWDensel.Text -ne '(non)') { return ((T "Effacement avant l'écriture : broche 2 du lecteur réglée (--densel={0}), que gw erase ne règle pas : pré-effacement de chaque piste (--pre-erase), comme avant.") -f "$($cmbWDensel.Text)") }
    return $null
}

function Get-EraseMode([bool]$hd) {
    # Effacement avant une ecriture : 'hfreq' (double densite) ou 'pre' (haute densite ; options de lecteur que gw erase ne
    # prend pas en charge, Get-EraseFallbackNote : secteurs durs, TG43, --densel)
    if ($hd -or (Get-EraseFallbackNote)) { return 'pre' }
    return 'hfreq'
}

function Get-CalibEraseEst([bool]$hd) {
    # Duree estimee de l effacement haute frequence d une passe de calibration, en s par piste (0 sans effacement) :
    # EraseEstTrack (565, essai E5 : 52 pistes en 19 s), compte dans les durees annoncees et l estimation de la barre
    if ((Get-EraseMode $hd) -eq 'hfreq') { return [double]$script:EraseEstTrack }
    return 0.0
}

function Get-EraseDriveArgs {
    # Options de lecteur de l ecriture (Get-WriteFormatArgs) que gw erase accepte : --fake-index seul (lecteur sans capteur
    # d index) ; gw erase n a ni --densel ni --reverse
    return @(Get-WriteFormatArgs | Where-Object { $_ -match '^--fake-index=' })
}

function Get-EraseTSpecs($keys) {
    # Pistes 'cyl.tete' (tetes 0 et 1) -> TSPEC exacts de gw erase, aucune piste en trop : cylindres a deux faces en h=0-1,
    # puis face 0 seule, puis face 1 seule (memes groupes que Get-TrackGroups), cylindres en plages (Format-CylRanges, 276 :
    # « 0-39,41-79 »). Tableau protege par la virgule : pas de @() autour de l appel
    $hs = @{}
    foreach ($k in @($keys)) {
        if ("$k" -notmatch '^(\d+)\.([01])$') { continue }
        $c = [int]$Matches[1]; $h = [int]$Matches[2]
        if (-not $hs.ContainsKey($c)) { $hs[$c] = @{} }
        $hs[$c][$h] = $true
    }
    $g = [ordered]@{ '0-1' = @(); '0' = @(); '1' = @() }
    foreach ($c in @($hs.Keys | Sort-Object)) {
        $n = if ($hs[$c].ContainsKey(0) -and $hs[$c].ContainsKey(1)) { '0-1' } elseif ($hs[$c].ContainsKey(0)) { '0' } else { '1' }
        $g[$n] += [int]$c
    }
    return ,@(foreach ($n in @($g.Keys)) { if (@($g[$n]).Count -gt 0) { "c=$(Format-CylRanges ([int[]]@($g[$n]))):h=$n" } })
}

function New-HfreqEraseCmds($keys, [string]$extras = '', $driveArgs = $null) {
    # Commandes gw erase --hfreq des pistes 'cyl.tete' : une par TSPEC de Get-EraseTSpecs (une seule quand toutes les pistes
    # ont les memes tetes, trois au plus), lecteur et port de l ecriture, --fake-index de l onglet Ecriture ($driveArgs ;
    # $null : Get-CommonArgs et Get-EraseDriveArgs), elements de lecteur du champ Pistes ($extras, forme de
    # Get-TSpecExtras : step, hswap, h0.off, h1.off, memes pistes physiques que l ecriture). Tableau de string[], vide sans
    # piste ; protege par la virgule : pas de @() autour de l appel
    $da = if ($null -ne $driveArgs) { @($driveArgs) } else { @(@(Get-CommonArgs) + @(Get-EraseDriveArgs)) }
    $out = New-Object System.Collections.Generic.List[object]
    foreach ($ts in (Get-EraseTSpecs $keys)) {
        $out.Add([string[]](@('erase') + $da + @('--hfreq', "--tracks=$ts$extras")))
    }
    return ,$out.ToArray()
}

function Format-EraseTracks($cmds) {
    # Pistes des commandes de New-HfreqEraseCmds pour le journal : valeurs de --tracks, separees par « ; »
    return ((@(foreach ($c in @($cmds)) { foreach ($a in @($c)) { if ("$a" -like '--tracks=*') { "$a".Substring(9) } } })) -join ' ; ')
}

function Get-TSpecKeys([string]$tspec) {
    # Pistes 'cyl.tete' d un TSPEC a c= lisible (« c=0-4,10:h=0-1 » ; sans h= : tetes 0 et 1, comme Get-TSpecSelection) ;
    # tableau vide sans c= ou c= illisible. Protege par la virgule : pas de @() autour de l appel
    $sel = Get-TSpecSelection $tspec
    if (-not $sel.Ok -or $null -eq $sel.Cyls) { return ,@() }
    $k = @(foreach ($c in @($sel.Cyls.Keys)) { foreach ($h in @($sel.Heads)) { "$c.$h" } })
    return ,(Sort-TrackKeys $k)
}

function Get-ImageDefaultGwFormat([string]$img) {
    # Format que gw 1.23 prend sans --format pour l extension (default_format des classes d image : adf.py, d64.py,
    # d81.py) ; $null sinon (SCP, HFE, IPF, MSA, DSK, EDSK... : pistes par defaut c=0-81:h=0-1, tools/write.py)
    switch ([System.IO.Path]::GetExtension("$img").ToLower()) {
        '.adf' { return 'amiga.amigados' }
        '.d64' { return 'commodore.1541' }
        '.d71' { return 'commodore.1571' }
        '.d81' { return 'commodore.1581' }
    }
    return $null
}

function Get-ImageGeometryTrackSet([string]$path) {
    # 12.8.2 (revue) : pistes d une image secteur double densite dont l en-tete donne la geometrie ('cyl.tete' -> $true),
    # pour l effacement avant l ecriture seulement (Get-WriteEraseKeys ; Get-ImageTrackSet et ses autres usages sont
    # inchanges) ; $null sinon. Lecture conforme a gw 1.23 (image/msa.py, edsk.py, dsk.py) :
    #  - MSA (Atari ST) : 10 octets big-endian, signature 0E 0F, secteurs par piste, faces - 1, premier et dernier
    #    cylindre (inclus) ; plus de 12 secteurs par piste (haute densite, que la taille du fichier compresse ne revele
    #    pas toujours a Get-HighDensityReason) : $null ;
    #  - DSK et EDSK (Amstrad CPC) : signature « MV - CPC » ou « EXTENDED CPC DSK », cylindres a 0x30, faces a 0x31 ; EDSK :
    #    table des tailles de piste a 0x34 (par 256 octets, cylindre x faces + face, 0 = piste absente) ; DSK : taille
    #    commune a 0x32. Piste de plus de 6 656 octets (plus de 12 secteurs de 512 : haute densite) : $null. DSK sans ces
    #    signatures (image brute, --format exige) : $null
    $ext = [System.IO.Path]::GetExtension("$path").ToLower()
    if (@('.msa', '.dsk', '.edsk') -notcontains $ext) { return $null }
    $set = @{}
    try {
        $fs = [System.IO.File]::OpenRead($path)
        try { $b = New-Object byte[] 256; $n = $fs.Read($b, 0, 256) } finally { $fs.Dispose() }
        if ($ext -eq '.msa') {
            if ($n -lt 10 -or $b[0] -ne 0x0E -or $b[1] -ne 0x0F) { return $null }
            $spt = [int]$b[2] * 256 + [int]$b[3]; $ns = [int]$b[4] * 256 + [int]$b[5] + 1
            $st = [int]$b[6] * 256 + [int]$b[7]; $et = [int]$b[8] * 256 + [int]$b[9]
            if ($spt -lt 1 -or $spt -gt 12 -or $ns -lt 1 -or $ns -gt 2 -or $st -gt $et -or $et -gt 99) { return $null }
            for ($c = $st; $c -le $et; $c++) { for ($h = 0; $h -lt $ns; $h++) { $set["$c.$h"] = $true } }
        } else {
            if ($n -lt 0x34) { return $null }
            $sig = [System.Text.Encoding]::ASCII.GetString($b, 0, 16)
            $nc = [int]$b[0x30]; $ns = [int]$b[0x31]
            if ($nc -lt 1 -or $ns -lt 1 -or $ns -gt 2) { return $null }
            if ($sig.StartsWith('EXTENDED CPC DSK')) {
                if (0x34 + $nc * $ns -gt $n) { return $null }
                for ($i = 0; $i -lt $nc * $ns; $i++) {
                    $sz = [int]$b[0x34 + $i]
                    if ($sz -gt 0x1A) { return $null }
                    if ($sz -gt 0) { $set["$([int][math]::Floor($i / $ns)).$($i % $ns)"] = $true }
                }
            } elseif ($sig.StartsWith('MV - CPC')) {
                if ([int]$b[0x32] + 256 * [int]$b[0x33] -gt 0x1A00) { return $null }
                for ($c = 0; $c -lt $nc; $c++) { for ($h = 0; $h -lt $ns; $h++) { $set["$c.$h"] = $true } }
            } else { return $null }
        }
    } catch { return $null }
    if ($set.Count -gt 0) { return $set }
    return $null
}

function Get-WriteEraseKeys([string]$img, [string]$fmt, [string]$userTs, [int[]]$heads) {
    # Pistes 'cyl.tete' qu une ecriture d image ecrit (Start-ImageWrite), d apres gw 1.23 (tools/write.py) : gw parcourt
    # les pistes du format (explicite, sinon format implicite de l extension, Get-ImageDefaultGwFormat ; sans format :
    # c=0-81:h=0-1), dont c= et h= du champ Pistes remplacent les cylindres et les tetes, et n ecrit que celles que l image
    # contient. Pistes de l image : Get-ImageTrackSet, sinon geometrie de l en-tete (Get-ImageGeometryTrackSet : MSA, DSK et
    # EDSK), sinon toutes les pistes du format explicite ; retenues aussi par les tetes ecrites ($heads : faces de l image
    # en ecriture lente). Revue 12.8.2 : cylindres de l image au-dela du format (ADF de 84 cylindres en amiga.amigados) ou
    # au-dela de 81 sans format (SCP, HFE, IPF de 84 cylindres) : jamais effaces, gw ne les ecrit pas. Pistes absentes de
    # l image : non comptees (--erase-empty les efface en continu, elles ne portent pas de donnees). $null : pistes
    # inconnues (image sans table de pistes ni geometrie lisible ni format explicite, format absent de la table GwFormats,
    # c= illisible) ; l ecriture garde alors le pre-effacement. Protege par la virgule
    $sel = Get-TSpecSelection $userTs
    if (-not $sel.Ok) { return $null }
    $explicit = ($fmt -and $fmt -ne '(auto)')
    $fn = if ($explicit) { $fmt } else { Get-ImageDefaultGwFormat $img }
    $fe = $null
    if ($fn) {
        if (-not $script:GwFormats.Contains($fn)) { return $null }
        $fe = $script:GwFormats[$fn]
        if ([int]$fe.Cyls -le 0) { return $null }
    }
    $fh = @(if ($fe -and [int]$fe.Heads -eq 1) { 0 } else { 0, 1 })
    $set = Get-ImageTrackSet $img
    if ($null -eq $set) { $set = Get-ImageGeometryTrackSet $img }
    if ($null -eq $set) {
        if (-not $explicit -or -not $fe) { return $null }
        $set = @{}
        for ($c = 0; $c -lt [int]$fe.Cyls; $c++) { foreach ($h in $fh) { $set["$c.$h"] = $true } }
    }
    $nc = if ($fe) { [int]$fe.Cyls } else { 82 }
    $hasH = [regex]::IsMatch(":$userTs", ':\s*h\s*=')
    $keys = @(@($set.Keys) | Where-Object {
        $p = ([string]$_ -split '\.'); $c = [int]$p[0]; $h = [int]$p[1]
        (Test-TSpecKey $sel $_) -and @($heads) -contains $h -and ($null -ne $sel.Cyls -or $c -lt $nc) -and ($hasH -or $fh -contains $h)
    })
    return ,(Sort-TrackKeys $keys)
}
# ============================== FONCTIONS : ECRITURE LENTE : FILE ET PRECHAUFFAGE ===

function Get-WriteWarmupTSpec([string]$userTs, [int[]]$heads, [string]$image) {
    # Pistes du prechauffage d une ecriture lente : un cylindre sur 10 de la zone ecrite, son premier et son dernier
    # (comme le test standard de la calibration), tetes ecrites, elements step, hswap, h0.off et h1.off du champ Pistes
    # conserves (memes pistes physiques que l ecriture). Zone : c= du champ Pistes, sinon cylindres de l image
    # (Get-ImageCylinders), sinon 40 cylindres, valables sur tout lecteur (40 pistes et step=2 compris)
    $hs = if (@($heads).Count -ge 2) { '0-1' } else { "$(@($heads)[0])" }
    $extras = Get-TSpecExtras $userTs
    $cyls = @()
    $m = [regex]::Match(":$userTs", ':\s*c\s*=\s*([^:]*)')
    if ($m.Success -and $m.Groups[1].Value.Trim()) {
        foreach ($r in ($m.Groups[1].Value -split ',')) {
            if ($r -match '^\s*(\d+)\s*-\s*(\d+)\s*$') { $cyls += @([int]$Matches[1]..[int]$Matches[2]) }
            elseif ($r -match '^\s*(\d+)\s*$') { $cyls += [int]$Matches[1] }
            else { return "c=$($m.Groups[1].Value.Trim()):h=$hs$extras" }      # forme non lue : c= repris tel quel
        }
    } else {
        $n = Get-ImageCylinders $image
        if ($null -eq $n) { $n = 40 }
        $cyls = @(0..([math]::Max(1, [math]::Min(84, [int]$n)) - 1))
    }
    $s = @($cyls | Sort-Object -Unique)
    $pick = @(@($s | Where-Object { $_ % 10 -eq 0 }) + @($s[0], $s[-1]))
    return "c=$(Format-CylList ([int[]]$pick)):h=$hs$extras"
}

function Invoke-WriteQueueNext {
    # Ecriture lente : commande gw write suivante (une par tete) ; pistes et retries de la precedente cumules pour le controle.
    # 12.8.2 : la file commence par les commandes gw erase --hfreq de l effacement avant l ecriture (Start-ImageWrite,
    # ecriture rapide comprise)
    if ($script:WriteQueue.Count -eq 0) { return }
    Merge-RepRetries
    Start-Gw ([string[]]$script:WriteQueue.Dequeue())
}

function Start-WriteWarmup([string]$tspec, [bool]$noWarm) {
    # Prechauffage du lecteur avant une ecriture lente (fin de Start-ImageWrite, chaine d ecriture prete : onglet Ecriture,
    # Bibliotheque, restauration, reprise apres une calibration) : memes regles que celui de la calibration
    # (CalWarmupMinutes, Get-CalWarmupPlan : duree reduite ou prechauffage saute si le lecteur vient de servir, calibration
    # qui precede comprise ; lectures gw read sans ecriture, echecs toleres). Sans prechauffage (reglage a 0, case
    # « Prechauffer le lecteur » decochee, prechauffage passe pendant la calibration qui precede, lecteur deja actif) :
    # chaine lancee tout de suite. Sinon la chaine d ecriture est mise de cote (WriteWarm.Rest) pendant les lectures, puis
    # reprise telle quelle (Invoke-WriteWarmup) ; libelle et barre de l onglet Ecriture retablis a la fin.
    $script:WriteWarm = $null
    $drv = $cmbDrive.Text
    if ([double]$script:CalWarmupMinutes -le 0) { Invoke-NextChainStep; return }
    if (-not $chkWWarm.Checked) { Append-Log ((T "Préchauffage du lecteur {0} non demandé (case « Préchauffer le lecteur avant l'écriture lente » décochée) : écriture lente tout de suite.") -f "$drv"); Invoke-NextChainStep; return }
    if ($noWarm) { Append-Log ((T "Préchauffage du lecteur {0} passé à votre demande pendant la calibration : écriture lente tout de suite.") -f "$drv"); Invoke-NextChainStep; return }
    $plan = Get-CalWarmupPlan (Get-GwDriveKey (@('read') + (Get-CommonArgs))) ([double]$script:CalWarmupMinutes)
    $actTxt = Format-CalDuration ([math]::Round($plan.Active)); $idleTxt = Format-CalDuration ([math]::Round($plan.Idle))
    if ($plan.Skip) {
        Append-Log ((T "Préchauffage du lecteur {0} sauté : lecteur déjà en activité pendant {1} (dernière commande terminée il y a {2}).") -f "$drv", "$actTxt", "$idleTxt")
        Invoke-NextChainStep; return
    }
    $durTxt = Format-CalDuration ([math]::Round($plan.Sec))
    if ($plan.Reduced) { Append-Log ((T "Préchauffage du lecteur {0} : {1} de lecture sans écriture avant l'écriture lente, pour stabiliser sa température (durée réduite : lecteur déjà en activité pendant {2}, dernière commande terminée il y a {3}).") -f "$drv", "$durTxt", "$actTxt", "$idleTxt") }
    else { Append-Log ((T "Préchauffage du lecteur {0} : {1} de lecture sans écriture avant l'écriture lente, pour stabiliser sa température.") -f "$drv", "$durTxt") }
    if (-not (Test-Path -LiteralPath $script:TempDir)) { [void](New-Item -ItemType Directory -Path $script:TempDir -Force) }
    $scp = Join-Path $script:TempDir 'write-warmup.scp'
    # Options d index et de densite de l ecriture (Get-WriteFormatArgs) : --fake-index et --densel par Get-DriveReadArgs,
    # --hard-sectors et --gen-tg43 ajoutees ici quand l ecriture les utilise (gw read 1.23 les declare, dans les memes
    # groupes exclusifs que gw write : --hard-sectors / --fake-index, --densel / --gen-tg43)
    $ro = @(Get-DriveReadArgs)
    if ($chkWHard.Checked) { $ro += '--hard-sectors' }
    if ($chkWTG43.Checked) { $ro += '--gen-tg43' }
    Hide-WCalVerdict                                      # 12.8 (FIX3) : verdict du controle precedent, non retabli a la fin
    $script:WriteWarm = @{
        Drive = $drv; Rest = @($script:Chain.ToArray()); WarmSec = [double]$plan.Sec; WarmStart = (Get-Date)
        WarmReads = 0; WarmFails = 0; WarmFailRun = 0; WarmDurs = @(); WarmReadStart = $null; WarmSkip = $false; WarmScp = $scp
        WarmArgs = @(@('read') + (Get-CommonArgs) + $ro + @('--revs=3', "--tracks=$tspec", "`"$scp`""))
        LblText = $lblWCal.Text; LblVisible = $lblWCal.Visible; PbVisible = $pbWCal.Visible
    }
    $script:Chain.Clear()
    $pbWCal.Value = 0; $pbWCal.Visible = $true; $lblWCal.Visible = $true
    Invoke-WriteWarmup
}

function Invoke-WriteWarmup {
    # Lecture de prechauffage suivante, ou fin : meme regle que Invoke-CalibWarmup (CalWarmupMinReads lectures au moins,
    # arret a la duree ou avant une lecture qui la depasserait de plus d une demi-lecture), sur demande (bouton « Passer le
    # prechauffage » : apres la lecture en cours) ou apres CalWarmupMaxFails lectures de suite sans aboutir (code non nul,
    # ou code 0 et lecture incomplete : l ecriture commence et signale le defaut s il persiste). Fin : chaine d ecriture
    # mise de cote reprise telle quelle
    $w = $script:WriteWarm
    if (-not $w) { return }
    $failed = $false
    if ($w.WarmReadStart -is [datetime]) {
        $w.WarmDurs += ((Get-Date) - $w.WarmReadStart).TotalSeconds; $w.WarmReadStart = $null
        $code = [int]$script:GwLastCode
        if ($code -ne 0 -or [bool]$script:GwLastIncomplete) {
            $w.WarmFails++; $w.WarmFailRun++
            if ($w.WarmFails -eq 1) { Append-Log ((T "Préchauffage du lecteur {0} : la lecture n'a pas abouti (code {1}) ; sans effet sur l'écriture, le préchauffage continue.") -f "$($w.Drive)", "$code") }
        } else { $w.WarmFailRun = 0 }
        $failed = ([int]$w.WarmFailRun -ge $script:CalWarmupMaxFails)
    }
    if (Test-Path -LiteralPath $w.WarmScp) { Remove-Item -LiteralPath $w.WarmScp -Force -ErrorAction SilentlyContinue }
    $left = $w.WarmSec - ((Get-Date) - $w.WarmStart).TotalSeconds
    $avg = if (@($w.WarmDurs).Count -gt 0) { (@($w.WarmDurs) | Measure-Object -Average).Average } else { 0.0 }
    if ($failed -or ($w.WarmSkip -and $w.WarmReads -ge 1) -or ($w.WarmReads -ge $script:CalWarmupMinReads -and ($left -le 0 -or $left -lt $avg / 2))) {
        $elTxt = Format-CalDuration ([math]::Round(((Get-Date) - $w.WarmStart).TotalSeconds))
        if ($failed) { Append-Log ((T "Préchauffage du lecteur {0} arrêté après {1} lectures de suite sans aboutir (Greaseweazle, lecteur ou disquette absent ?) : l'écriture commence, elle signalera le défaut s'il persiste.") -f "$($w.Drive)", "$($w.WarmFailRun)") }
        elseif ($w.WarmFails -gt 0) { Append-Log ((T "Préchauffage du lecteur {0} terminé : {1} lecture(s) en {2}, dont {3} sans aboutir (sans effet sur l'écriture).") -f "$($w.Drive)", "$($w.WarmReads)", "$elTxt", "$($w.WarmFails)") }
        else { Append-Log ((T "Préchauffage du lecteur {0} terminé : {1} lecture(s) en {2}.") -f "$($w.Drive)", "$($w.WarmReads)", "$elTxt") }
        $script:WriteWarm = $null
        # Libelle et barre de l onglet Ecriture comme avant le prechauffage (ecriture, controle apres ecriture)
        $lblWCal.Text = $w.LblText; $lblWCal.Visible = [bool]$w.LblVisible; $pbWCal.Visible = [bool]$w.PbVisible
        if ($script:Restore -and $script:Restore.Cur -eq 5) { Set-RsStep 5 'run' }      # detail « prechauffage » retire
        $script:Chain.Clear()
        foreach ($s in @($w.Rest)) { $script:Chain.Enqueue($s) }
        Invoke-NextChainStep; return
    }
    $w.WarmReads++; $w.WarmReadStart = Get-Date; $script:GwLastCode = 0; $script:GwLastIncomplete = $false
    Update-WriteWarmupProgress
    $script:Chain.Clear()
    $script:Chain.Enqueue({ Start-Gw ([string[]]$script:WriteWarm.WarmArgs) -Soft })
    $script:Chain.Enqueue({ Invoke-WriteWarmup })
    Invoke-NextChainStep
}

function Update-WriteWarmupProgress {
    # Barre et libelle de l onglet Ecriture pendant le prechauffage d une ecriture lente (minuteur) : duree ecoulee sur la
    # duree prevue, avancement et temps restant en tete (libelle coupe a la largeur de l onglet) ; passe a la demande : fin
    # de la lecture en cours
    $w = $script:WriteWarm
    if (-not $w) { return }
    $g = Get-WarmupLeft $w
    # 12.11 (L11) : ecriture suivie par la barre de l onglet (Start-WriteProgress) : la barre est celle de toute
    # l operation, prechauffage compris (Get-WriteProgPct), et ne recule pas quand l ecriture commence ; le libelle garde
    # l avancement du prechauffage. Restauration : barre du prechauffage seul, comme en 12.10
    $pbWCal.Value = $(if ($script:WriteProg) { Get-WriteProgPct } else { $g.Pct })
    $lblWCal.Text = if ($w.WarmSkip) { (T 'Préchauffage du lecteur {0} passé : fin de la lecture en cours.') -f "$($w.Drive)" }
                    else { (T "Préchauffage avant l'écriture : {2} %, reste environ {3} (lecteur {0}, lecture {1}, sans écriture)") -f "$($w.Drive)", "$($w.WarmReads)", "$($g.Pct)", (Format-CalDuration ([math]::Round($g.Left))) }
}

function Stop-WriteWarmup {
    # Abandon pendant le prechauffage d une ecriture lente (Arreter, gw non lance, erreur d etape, restauration en echec) :
    # chaine d ecriture mise de cote abandonnee, rien n est ecrit ; sans effet hors prechauffage (idempotent)
    if (-not $script:WriteWarm) { return }
    $script:WriteWarm = $null
    $pbWCal.Visible = $false
    $lblWCal.Text = (T 'Préchauffage interrompu : écriture annulée.')
    Append-Log (T 'Écriture annulée : préchauffage du lecteur interrompu.')
}

# --- 12.11 (L11) : barre de l onglet Ecriture pendant une ecriture et son controle --------------------------------------
# Une ecriture lancee par Start-ImageWrite (140 : bouton ECRIRE, Bibliotheque, fin d une calibration ou d une mesure) suit
# une seule barre, qui ne recule pas : prechauffage d une ecriture lente (temps ecoule sur la duree prevue), ecriture
# (effacements et ecritures de la file, ou ecriture rapide : plan de l etape, Get-ProgPlanFrac, 110, d apres les pistes que
# gw annonce et traite), puis passes du controle apres ecriture (relecture de toutes les pistes, reecritures). Chaque etape
# compte pour son poids estime (Get-GwCmdUnits, $script:ProgCost : secondes estimees, proportions seulement ; prechauffage :
# sa duree prevue). Le libelle donne l etape en cours : texte du prechauffage (Update-WriteWarmupProgress), « Ecriture :
# x % » (avancement de l ecriture seule), textes des passes du controle (Invoke-RepNextCmd, 170) ; a la fin, verdict du
# controle, « Ecriture terminee. » ou « Ecriture interrompue : voir le journal. », barre masquee. Restauration exclue :
# onglet verrouille, ligne d avancement et barre d etat propres (Update-RestoreProgress, 300). Affichage seulement : rien
# ici ne lance, n arrete ni ne juge une operation, aucune commande n est modifiee.

function Get-WriteProgUnits($cmds, [bool]$check) {
    # Poids estimes : @{ Write (commandes $cmds) ; Check (relecture de toutes les pistes ecrites par le controle, 3 tours,
    # comme Add-RepReads, 170 ; 0 sans controle) ; Tracks (pistes estimees par commande, pour New-ProgPlan ; -1 quand
    # --tracks les donne) }. Commande gw write dont --tracks ne donne pas c= et h= (champ Pistes vide, ou sans c=) :
    # cylindres de c=, sinon 80, fois les tetes de h=, sinon 2 ; l annonce de gw corrige l estimation (Update-Progress)
    $tr = New-Object System.Collections.Generic.List[int]
    $w = 0.0; $nw = 0
    foreach ($c in @($cmds)) {
        $a = [string[]]@($c)
        $u = Get-GwCmdUnits $a
        $n = -1
        if ($a.Count -gt 0 -and [string]$a[0] -ceq 'write') {
            if ([int]$u.Tracks -le 0) {
                $ts = ''
                foreach ($x in $a) { if ([string]$x -clike '--tracks=*') { $ts = ([string]$x).Substring(9) } }
                $nc = 80; $nh = 2
                if ($ts -match '(?:^|:)c=([\d,\-]+)') { $nc = Get-SpecCount $Matches[1] }
                if ($ts -match '(?:^|:)h=([\d,\-]+)') { $nh = Get-SpecCount $Matches[1] }
                $n = [int][math]::Max(1, $nc * $nh)
                $u = Get-GwCmdUnits $a $n
            }
            $nw += [int]$u.Tracks
        }
        $tr.Add($n)
        $w += [double]$u.Units
    }
    $r = if ($check -and $nw -gt 0) { [double](Get-GwCmdUnits ([string[]]@('read', '--revs=3')) $nw).Units } else { 0.0 }
    return @{ Write = $w; Check = $r; Tracks = $tr.ToArray() }
}

function Get-WriteProgText($pct, [bool]$check) {
    # Libelle de l onglet pendant l ecriture : avancement de l ecriture seule, controle de toutes les pistes annonce ensuite
    if ($check) { return ((T 'Écriture : {0} %, contrôle de toutes les pistes ensuite') -f "$pct") }
    return ((T 'Écriture : {0} %') -f "$pct")
}

function Start-WriteProgress($cmds, [bool]$check) {
    # Start-ImageWrite (140), file construite, avant le lancement de la premiere commande : plan des commandes de l ecriture
    # ($cmds : effacements et ecritures de la file, ou ecriture rapide ; pistes estimees quand --tracks ne les donne pas),
    # etat de l operation, libelle et barre a zero. $check : controle de toutes les pistes ensuite (Get-WriteCheckPlan, sans
    # raison qui l empeche). Restauration : rien, l onglet garde l affichage de la 12.10
    $script:WriteProg = $null
    if ($script:Restore) { return }
    $u = Get-WriteProgUnits $cmds $check
    New-ProgPlan $cmds $u.Tracks
    $t = Get-WriteProgText 0 $check
    $script:WriteProg = @{ Check = $check; Warm = 0.0; Write = [math]::Max(1.0, [double]$u.Write); CheckEst = [double]$u.Check
                           Done = 0.0; Pass = 0.0; Seg = 'write'; F = 0.0; Max = 0; Text = $t }
    $lblWCal.Text = $t; $lblWCal.Visible = $true
    $pbWCal.Value = 0; $pbWCal.Visible = $true
}

function Step-WriteProgress($cmds) {
    # Start-RepPending (170) : passe du controle (relecture de toutes les pistes, puis chaque passe de reecriture) : plan de
    # ses commandes ($cmds, file de la passe, non modifiee) ; poids des etapes faites gardes. Une passe de reecriture,
    # imprevisible, allonge l operation : la barre attend sur place
    $wp = $script:WriteProg
    if (-not $wp) { return }
    if ($wp.Seg -eq 'check') { $wp.Done = [double]$wp.Done + [double]$wp.Pass }
    $u = Get-WriteProgUnits $cmds $false
    $wp.Seg = 'check'; $wp.Pass = [math]::Max(1.0, [double]$u.Write)
    New-ProgPlan $cmds $u.Tracks
}

function Get-WriteProgPct {
    # Valeur de la barre, de 0 a 99 tant que l operation tourne, jamais decroissante (Max) : (poids des etapes faites +
    # fraction de l etape en cours x son poids) / poids de toutes les etapes. Prechauffage (WriteWarm) : temps ecoule sur la
    # duree prevue (Get-WarmupLeft, 270), ecriture et controle a venir ; ecriture : fraction du plan (Get-ProgPlanFrac, 0
    # tant qu aucune commande n est recue), controle estime a venir ; passe du controle : fraction de son plan. Une etape
    # plus longue que prevu fait attendre la barre sur place
    $wp = $script:WriteProg
    if (-not $wp) { return 0 }
    $ww = $script:WriteWarm
    if ($ww) {
        if ($wp.Seg -ne 'warm') { $wp.Seg = 'warm'; $wp.Warm = [math]::Max(1.0, [double]$ww.WarmSec) }
        $f = [double](Get-WarmupLeft $ww).Pct / 100.0
        $a = 0.0; $cur = [double]$wp.Warm; $rest = [double]$wp.Write + [double]$wp.CheckEst
    } else {
        if ($wp.Seg -eq 'warm') { $wp.Seg = 'write' }
        $pf = Get-ProgPlanFrac
        $f = if ($null -ne $pf) { [double]$pf } else { 0.0 }
        if ($wp.Seg -eq 'check') { $a = [double]$wp.Warm + [double]$wp.Write + [double]$wp.Done; $cur = [double]$wp.Pass; $rest = 0.0 }
        else { $wp.F = $f; $a = [double]$wp.Warm; $cur = [double]$wp.Write; $rest = [double]$wp.CheckEst }
    }
    $den = $a + $cur + $rest
    $v = if ($den -gt 0) { [int][math]::Floor(100.0 * ($a + $f * $cur) / $den) } else { 0 }
    $v = [math]::Max(0, [math]::Min(99, $v))
    if ($v -lt [int]$wp.Max) { $v = [int]$wp.Max } else { $wp.Max = $v }
    return $v
}

function Update-WriteProgress {
    # Minuteur principal (600), apres le prechauffage : valeur de la barre et libelle de l ecriture ; fin de l operation
    # (plus de gw, d etape en attente ni de controle) : Complete-WriteProgress. Pendant le prechauffage, barre et libelle
    # viennent d Update-WriteWarmupProgress ; pendant le controle, le libelle est celui de sa passe (Invoke-RepNextCmd)
    $wp = $script:WriteProg
    if (-not $wp -or $script:WriteWarm) { return }
    if (-not ($script:GwProc -or $script:Chain.Count -gt 0 -or $script:Rep)) { Complete-WriteProgress; return }
    # 12.11 (L11) : libelle pris par une autre etape avant la fin de gw (Arreter : Stop-WriteWarmup, Stop-WriteCheck ; gw
    # tue mais pas encore fini) : ni barre ni libelle de l ecriture, la fin le garde (Get-WriteProgEnd)
    if ($wp.Seg -ne 'check' -and [string]$lblWCal.Text -cne [string]$wp.Text) { return }
    $v = Get-WriteProgPct
    if ($pbWCal.Value -ne $v) { $pbWCal.Value = $v }
    if ($wp.Seg -ne 'write') { return }
    $t = Get-WriteProgText ([int][math]::Floor(100.0 * [double]$wp.F)) ([bool]$wp.Check)
    $wp.Text = $t
    if ([string]$lblWCal.Text -cne $t) { $lblWCal.Text = $t }
}

function Get-WriteProgEnd($wp) {
    # Fin de l operation : texte du libelle, ou $null quand une autre etape l a pris (verdict du controle, prechauffage
    # interrompu, controle sans piste a relire), qui est garde. Ecriture terminee : commandes prevues toutes finies (plan de
    # l ecriture entier, Get-ProgPlanFrac) et la derniere sans echec (ProgFailed : code non nul, gw non lance ;
    # GwLastIncomplete : code 0 mais operation incomplete, 600) ; sinon interrompue (erreur, arret, gw introuvable)
    if (-not $wp -or [string]$lblWCal.Text -cne [string]$wp.Text) { return $null }
    if ($wp.Seg -ne 'check') {
        $pf = Get-ProgPlanFrac
        if ($null -eq $pf -or [double]$pf -lt 1.0 - 1e-9 -or $script:ProgFailed -or $script:GwLastIncomplete) { return (T 'Écriture interrompue : voir le journal.') }
    }
    return (T 'Écriture terminée.')
}

function Complete-WriteProgress {
    # Fin de l operation (Update-WriteProgress) : libelle de fin (Get-WriteProgEnd), barre masquee, plan de l ecriture retire
    $wp = $script:WriteProg; $script:WriteProg = $null
    if (-not $wp) { return }
    $t = Get-WriteProgEnd $wp
    if ($t) { $lblWCal.Text = $t; $lblWCal.Visible = $true }
    $pbWCal.Visible = $false
    if (-not $script:Cal) { $script:ProgPlan = $null }
}
# ============================== FONCTIONS : CONTROLE APRES ECRITURE ============

function Get-WriteCheckBlocker([string]$path, [string]$fmt) {
    # Raison pour laquelle l analyse de flux (calibree MFM double densite, cellule 2 us) ne s applique pas ; $null sinon
    if ($chkWHard.Checked) { return (T 'secteurs durs') }
    if ($chkWTG43.Checked) { return (T 'lecteur 8 pouces (TG43)') }
    $hd = Get-HighDensityReason $path $fmt
    if ($hd) { return $hd }
    # 12.10 (lot 1, B1) : codage de l image par Get-ImageEncoding (format explicite de la table, sinon format implicite de
    # l extension, sinon en-tete HFE, IMD ou D88) ; textes inchanges, l image FM (SSD, DSD, HFE, IMD, D88) s y ajoute.
    # GCR et FM : les criteres sont ceux du MFM. Piste 0 en FM, les autres en MFM (codage fm0 de la table : tsc.flex.*,
    # olivetti.m20...) : la piste 0 serait jugee avec les criteres du MFM et pourrait etre reecrite a tort ; controle bloque
    # pour tout le format
    $ext = [System.IO.Path]::GetExtension($path).ToLower()
    $ie = Get-ImageEncoding $path $fmt
    $fx = ($fmt -and $fmt -ne '(auto)')
    if ($ie.Enc -eq 'gcr') { if ($fx) { return ((T "format GCR {0}") -f "$fmt") }; return ((T "image GCR {0}") -f "$ext") }
    if ($ie.Enc -eq 'fm') { if ($fx) { return ((T "format FM {0}") -f "$fmt") }; return ((T "image FM {0}") -f "$ext") }
    if ($ie.Enc -eq 'fm0' -and $fx) { return ((T "piste 0 en FM, format {0}") -f "$fmt") }
    # Images GCR sans format implicite de gw (G64, NIB, WOZ), et extension GCR avec un format MFM explicite, comme en 12.8
    if (@('.d64', '.d71', '.g64', '.nib', '.woz', '.do', '.po') -contains $ext) { return ((T "image GCR {0}") -f "$ext") }
    try {
        if ($ext -eq '.scp' -and $script:ScpStatsOk -and (Test-ScpHighDensity $path)) { return (T 'flux SCP haute densité') }
    } catch { }
    return $null
}

function New-WriteCheck([string[]]$base, [string]$image, [string]$userTSpec, [int]$max, [string[]]$readOpts, $headPrecomp, [string]$eraseMode = '') {
    # $headPrecomp : ecriture lente, --precomp par tete logique (0, 1 -> profil ou $null) ; $base est alors sans --precomp
    # 12.8.2 : $eraseMode, effacement des reecritures (Invoke-WriteCheckAnalysis) : 'hfreq' (double densite) ou 'pre'
    # (haute densite, flux SCP de densite inconnue, secteurs durs, TG43, --densel : Get-EraseMode) ; vide : d apres l image
    # et le format de l onglet (150). Revue 12.8.2 : jamais le repli « pistes de l image inconnues » de l ecriture
    # (Start-ImageWrite, $emCheck) : les pistes faibles sont toujours connues
    $script:WriteTracks = @{}; $script:WriteRetries = @{}   # rien d une ecriture precedente dans le perimetre
    if (-not $eraseMode) { $eraseMode = Get-EraseMode (Test-ImageHighDensity $image $cmbWFmt.Text) }
    $script:Rep = @{
        Base = @($base); Image = $image; UserTSpec = $userTSpec; Max = [math]::Max(0, $max); EraseMode = $eraseMode
        Common = @(Get-CommonArgs); ReadOpts = @($readOpts)   # lecteur et port memorises au clic : les relectures visent le meme disque
        HeadPrecomp = $headPrecomp; Written = @{}              # Written : pistes ecrites, cumulees sur les commandes (ecriture lente)
        Round = 0; Scope = $null; Weak = @(); State = @{}; Retries = @{}; Rewrites = @{}
        Pending = (New-Object System.Collections.Queue); Scps = @(); Safety = $false; Measured = 0
        # Zone instable relue sur la copie = defaut de la copie, sauf source capable d en porter (voir Set-CopyUnstable)
        UnstDefect = (-not (Test-SourceMayHaveWeak $image)); NoJudge = $null; SrcWeak = $null
        SrcOver = $null                                        # 12.8.2 : pistes deja hors norme dans la source (Test-SrcOverErr)
    }
    # Une mesure continue de l onglet Qualite ecraserait le resultat du controle : elle est arretee
    $script:AlignLoop = $false; $script:AlignNextAt = $null; $script:AlLastMove = 0
    # 12.11 (L11) : ecriture suivie par la barre de l onglet (Start-WriteProgress, 160, appelee juste avant) : libelle et
    # barre sont les siens ; restauration (barre de l onglet non posee) : libelle de la 12.10, barre masquee
    if (-not $script:WriteProg) {
        $lblWCal.Text = (T 'Écriture en cours, contrôle de toutes les pistes ensuite.')
        $pbWCal.Visible = $false; $lblWCal.Visible = $true
    }
    # 12.8 (lot 3a) : resultat de l onglet Qualite grise et marque « controle en cours » pendant l ecriture et le controle
    Set-QualityPending 'check'
}

function Test-SourceMayHaveWeak([string]$path) {
    # Sources dont gw ecrit les zones faibles comme une zone sans flux (une transition toutes les 32 cellules, track.py
    # MasterTrack.force_random_weak), relue volontairement instable : IPF (CAPS), HFE v3 (opcode Rand), EDSK (secteur
    # stocke en plusieurs copies). Flux .raw, .kf, .a2r, .ctr : non analyses. Fichier illisible : prudence.
    $ext = [System.IO.Path]::GetExtension($path).ToLower()
    if (@('.ipf', '.raw', '.kf', '.a2r', '.ctr') -contains $ext) { return $true }
    if (@('.hfe', '.dsk', '.edsk') -notcontains $ext) { return $false }
    try {
        $fs = [System.IO.File]::OpenRead($path)
        try { $b = New-Object byte[] 16; $n = $fs.Read($b, 0, 16) } finally { $fs.Dispose() }
        $s = [System.Text.Encoding]::ASCII.GetString($b, 0, $n)
        return ($s.StartsWith('HXCHFEV3') -or $s.StartsWith('EXTENDED CPC DSK'))
    } catch { return $true }
}

function Test-RepFakeIndex($rep) {
    # 12.8.2 (S11) : relectures du controle avec un index simule (--fake-index des options de relecture, Rep.ReadOpts, ou
    # de l ecriture, Rep.Base) : la jonction d ecriture n est pas a l index relu, la zone de l index est comptee
    return (@(@($rep.ReadOpts) + @($rep.Base) | Where-Object { "$_" -match '^--fake-index=' }).Count -gt 0)
}

function Test-SrcOverErr($m) {
    # 12.8.2 (decision du 27/10/2026) : piste de la source (original en restauration, image SCP de l onglet Ecriture) deja
    # hors norme par ses erreurs, au-dela du seuil SAIN (HealthErrOk, Get-HealthLevel) : protection (Copylock) ou defaut
    # d origine, qu une reecriture ne peut pas corriger. Le controle de la copie l ignore comme une piste critique : ni
    # reecrite, ni comptee faible. Piste illisible : non (deja critique).
    return ($null -ne $m -and -not $m.Bad -and [double]$m.Ooc -gt $script:HealthErrOk)
}

function Set-CopyUnstable($rep, [string]$k, $m) {
    # gw ecrit un tour fige de la source : une zone instable d un tour a l autre relue sur la copie ne vient pas de la
    # source quand celle-ci n en contient pas a cette piste (image secteur, HFE v1/v2, piste stable d un SCP analyse).
    # Elle signale alors un defaut de la copie (usure ou defaut localise) : la piste est faible et reecrite.
    # Pistes instables, critiques ou (12.8.2) deja hors norme de la source (Rep.Ignore) : traitees a part. Non jugees
    # (Unjudged : ni reecrites ni comptees saines) : source qui peut porter des zones faibles (Test-SourceMayHaveWeak), SCP
    # non analysable, piste que la source porte avec une courte zone instable ou que l analyse n a pas pu mesurer
    # (Rep.NoJudge).
    if (-not $m -or $m.Bad -or -not $m.Weak) { return }
    if ($rep.Ignore -and $rep.Ignore.ContainsKey($k)) { return }
    if (-not $rep.UnstDefect -or ($rep.NoJudge -and $rep.NoJudge.ContainsKey($k))) { $m.Unjudged = $true; return }
    $m.CopyDefect = $true
    if ($m.Level -lt 1) { $m.Level = 1 }
}

function Merge-RepRetries {
    # Retries et pistes ecrites de la derniere ecriture gw (remis a zero a chaque nouvelle ecriture) -> cumul du controle
    $rep = $script:Rep
    if (-not $rep) { return }
    foreach ($k in @($script:WriteTracks.Keys)) { $rep.Written[$k] = $true }
    foreach ($k in @($script:WriteRetries.Keys)) {
        $n = [int]$script:WriteRetries[$k]
        if (-not $rep.Retries.ContainsKey($k) -or $n -gt $rep.Retries[$k]) { $rep.Retries[$k] = $n }
    }
}

function Add-RepReads($groups, [string]$extras) {
    # Relectures en flux d un groupe de TSPEC, un fichier SCP par commande
    $rep = $script:Rep
    if (-not (Test-Path -LiteralPath $script:TempDir)) { [void](New-Item -ItemType Directory -Path $script:TempDir -Force) }
    $rep.Scps = @(); $i = 0
    foreach ($g in @($groups)) {
        $scp = Join-Path $script:TempDir ("check-r{0}-{1}.scp" -f $rep.Round, $i)
        if (Test-Path -LiteralPath $scp) { Remove-Item -LiteralPath $scp -Force }
        $rep.Pending.Enqueue([string[]](@('read') + $rep.Common + $rep.ReadOpts + @('--revs=3', "--tracks=$g$extras", "`"$scp`"")))
        $rep.Scps += $scp; $i++
    }
}

function Start-RepPending {
    # Une etape de chaine par commande en file, puis l analyse
    $rep = $script:Rep
    # 12.11 (L11) : passe du controle dans la barre de l onglet (Step-WriteProgress, 160) : plan de ses commandes, file de
    # la passe inchangee ; affichage seulement
    Step-WriteProgress @($rep.Pending.ToArray())
    $script:Chain.Clear()
    for ($i = 0; $i -lt $rep.Pending.Count; $i++) { $script:Chain.Enqueue({ Invoke-RepNextCmd }) }
    $script:Chain.Enqueue({ Invoke-WriteCheckAnalysis })
    Invoke-NextChainStep
}

function Invoke-RepNextCmd {
    $rep = $script:Rep
    if (-not $rep -or $rep.Pending.Count -eq 0) { return }
    Merge-RepRetries
    $cmd = [string[]]$rep.Pending.Dequeue()
    if ($rep.Round -eq 0) { $lblWCal.Text = (T 'Contrôle après écriture : relecture de toutes les pistes...') }
    elseif ($cmd[0] -eq 'write') { $lblWCal.Text = ((T "Contrôle après écriture : réécriture {0}/{1} de {2} piste(s) faible(s)...") -f "$($rep.Round)", "$($rep.Max)", "$($rep.Weak.Count)") }
    elseif ($cmd[0] -eq 'erase') { $lblWCal.Text = ((T "Contrôle après écriture : effacement haute fréquence avant la réécriture {0}/{1} de {2} piste(s) faible(s)...") -f "$($rep.Round)", "$($rep.Max)", "$($rep.Weak.Count)") }
    else { $lblWCal.Text = ((T "Contrôle après écriture : remesure {0}/{1} de {2} piste(s)...") -f "$($rep.Round)", "$($rep.Max)", "$($rep.Weak.Count)") }
    Set-QualityRunText $lblWCal.Text                      # 12.8 (lot 3a) : etape du controle sur la carte de l onglet Qualite
    Start-Gw $cmd
}

function Enter-CheckTab {
    # 12.10 (lot 1, E11) : onglet Qualite & alignement affiche pendant la relecture du controle apres ecriture, pour tout
    # controle hors restauration (ECRIRE, Bibliotheque, controle impose : E11-2) ; onglet d avant memorise pour le retour
    # (Exit-CheckTab). Restauration exclue (E11-3) : pages verrouillees par Set-RsLock, etape « Controler toutes les
    # pistes » de l onglet Restauration
    if ($script:Restore -or $script:CheckTabReturn) { return }
    $script:CheckTabReturn = $tabs.SelectedTab
    if ($tabs.SelectedTab -ne $tabAl) { Show-Tab $tabAl }
}

function Exit-CheckTab {
    # 12.10 (lot 1, E11) : fin, arret ou erreur du controle : retour a l onglet d avant (E11-1), sauf si l utilisateur en a
    # choisi un autre entre-temps (onglets actifs entre deux commandes gw ; Set-Busy inchange)
    $t = $script:CheckTabReturn; $script:CheckTabReturn = $null
    if ($t -and $t -ne $tabAl -and $tabs.SelectedTab -eq $tabAl -and $tabs.TabPages.Contains($t)) { $tabs.SelectedTab = $t }
}

function Start-WriteCheck {
    # Etape de chaine apres l ecriture initiale (code retour 0) : relecture de toutes les pistes ecrites
    $rep = $script:Rep
    if (-not $rep) { return }
    Merge-RepRetries
    if (-not $script:ScpStatsOk) {
        Append-Log (T 'Contrôle après écriture : module d''analyse SCP indisponible, contrôle ignoré.'); $script:Rep = $null; Set-QualityStale 'checkabort'
        if ($script:Restore) { Stop-Restore (T 'contrôle des pistes indisponible') }
        return
    }
    # Perimetre = pistes que gw a reellement ecrites (lignes « Writing Track » ; une piste vide effacee n en a pas),
    # limitees a l image quand ses pistes sont connues. A defaut : pistes de l image, puis 80 x 2.
    # 12.8 (FIX-PISTES, essai du 21/10/2026) : toujours limite aux pistes retenues par c= et h= du champ Pistes (ecriture de
    # c=0:h=0 dont la piste est vide dans l image : 158 pistes de l image relues auparavant) ; c= illisible : non limite
    $img = Get-ImageTrackSet $rep.Image
    $sel = Get-TSpecSelection $rep.UserTSpec
    if (@($sel.Heads).Count -eq 0) { $sel.Heads = @(0, 1) }
    $set = @{}; $cut = 0
    foreach ($k in @($rep.Written.Keys)) {
        if ($null -ne $img -and -not $img.ContainsKey($k)) { continue }
        if (Test-TSpecKey $sel $k) { $set[$k] = $true } else { $cut++ }
    }
    if ($set.Count -eq 0) {
        $all = $img
        if ($null -eq $all) {
            $all = @{}
            $n = Get-ImageCylinders $rep.Image; if ($null -eq $n) { $n = 80 }
            for ($c = 0; $c -lt [int]$n; $c++) { $all["$c.0"] = $true; $all["$c.1"] = $true }
        }
        $cut = 0
        foreach ($k in @($all.Keys)) { if (Test-TSpecKey $sel $k) { $set[$k] = $true } else { $cut++ } }
        if ($set.Count -eq 0 -and $cut -gt 0 -and -not $script:Restore) {
            # Aucune piste de l image dans le champ Pistes (piste vide de l image, effacee ou sautee par gw) : rien a relire,
            # aucun verdict ; resultat de l onglet Qualite marque perime avec la raison
            Append-Log ((T "Contrôle après écriture : aucune piste de l'image dans le champ Pistes (« {0} ») : rien à relire (piste vide de l'image, effacée ou sautée par gw).") -f "$($rep.UserTSpec.Trim())")
            $script:Rep = $null
            $pbWCal.Visible = $false; $lblWCal.Text = (T 'Contrôle après écriture : aucune piste à relire.'); $lblWCal.Visible = $true
            Set-QualityStale 'checknone'
            return
        }
    }
    $rep.Scope = $set
    $rep.Round = 0
    $groups = Get-TrackGroups @($set.Keys)                # pistes exactes ecrites, memes elements step/offsets que l ecriture
    if ($cut -gt 0) { Append-Log ((T "Contrôle après écriture : relecture en flux de {0} piste(s) de l'image, celles du champ Pistes (« {1} ») (3 tours).") -f "$($set.Count)", "$($rep.UserTSpec.Trim())") }
    else { Append-Log ((T "Contrôle après écriture : relecture en flux de {0} piste(s) de l'image (3 tours).") -f "$($set.Count)") }
    $rep.Pending.Clear()
    Enter-CheckTab                                        # 12.10 (lot 1, E11) : seulement si une relecture commence
    Add-RepReads $groups (Get-TSpecExtras $rep.UserTSpec)
    Start-RepPending
}

function Invoke-WriteCheckAnalysis {
    $rep = $script:Rep
    if (-not $rep) { return }
    Merge-RepRetries
    if ($rep.Round -gt 0) {
        # Passe terminee : toutes ses ecritures et relectures ont rendu le code 0
        foreach ($k in @($rep.Weak)) { $rep.Rewrites[$k] = 1 + $(if ($rep.Rewrites.ContainsKey($k)) { [int]$rep.Rewrites[$k] } else { 0 }) }
    }
    $tracks = @{}
    $fake = Test-RepFakeIndex $rep
    foreach ($scp in $rep.Scps) {
        if (-not (Test-Path -LiteralPath $scp)) { Append-Log (T 'Contrôle après écriture : fichier SCP absent, analyse impossible.'); Stop-WriteCheck; return }
        try { $t = Read-ScpFile $scp -NoIndexZone:$fake } catch { Append-Log ((T "Contrôle après écriture : {0}") -f "$($_.Exception.Message)"); Stop-WriteCheck; return }
        foreach ($tn in $t.Keys) { $tracks[[int]$tn] = $t[$tn] }
    }
    # Pistes attendues : premier controle = image (ou TSPEC utilisateur relu, limite a l image) ; ensuite = pistes reecrites
    if ($rep.Round -eq 0) { $expected = @($rep.Scope.Keys) } else { $expected = @($rep.Weak) }
    $expected = Sort-TrackKeys $expected
    $watch = @(); $crit = @(); $healthy = 0
    foreach ($k in $expected) {
        $tn = Get-TrackKeyOrder $k
        if ($tracks.ContainsKey($tn)) { $m = Get-TrackMetrics $tracks[$tn] }
        else { $m = Get-TrackMetrics @(); $m.Missing = $true }
        Set-CopyUnstable $rep $k $m
        $rep.State[$k] = $m
        if ($m.Bad -or $m.Level -ge 2) { $crit += $k } elseif ($m.Level -eq 1) { $watch += $k }
        elseif (-not $m.Unjudged -and -not ($m.Weak -and $rep.Ignore -and $rep.Ignore.ContainsKey($k))) { $healthy++ }
    }
    $unjK = @($expected | Where-Object { $rep.State[$_].Unjudged -and -not $rep.State[$_].Bad -and $rep.State[$_].Level -lt 1 })
    if ($unjK.Count -gt 0 -and $rep.Round -eq 0) { Append-Log ((T "Contrôle : zone instable sur {0} piste(s) non jugée(s) ({1}) : la source peut en contenir (protection) sans que l'application puisse le vérifier. Ni réécrites ni comptées comme saines.") -f "$($unjK.Count)", "$(Format-TrackList $unjK)") }
    $defK = @($expected | Where-Object { $rep.State[$_].CopyDefect })
    if ($defK.Count -gt 0) { Append-Log ((T "Contrôle : zone instable d'un tour à l'autre sur la copie, piste(s) {0} : la source n'en contient pas, défaut probable du support. Ces pistes sont traitées comme faibles.") -f "$(Format-TrackList $defK)") }
    # 12.8.2 (S11, S12) : hors classe de la zone de l index (jonction d ecriture de gw) ecartes du comptage, avec la
    # distance a l index la plus grande, et pistes dont la stabilite n a pas pu etre mesuree sur tours alignes : une
    # ligne par analyse ; index simule : une ligne au premier controle
    # 12.10 (S13) : so / sot, hors classe reproductibles retires ; sov, pistes au-dela du plafond ScpStructMax par tour (tout
    # compte), sauf celles que le controle ne compte pas (Rep.Ignore : deja critiques, non reproductibles ou hors norme dans
    # la source, ligne a part)
    $zo = 0; $zt = 0; $zf = 0; $fb = @(); $so = 0; $sot = 0; $sov = @()
    foreach ($k in $expected) {
        $ms = $rep.State[$k]; $z = [int]$ms.ZoneOoc
        if ([int]$ms.StructOoc -gt 0) { $so += [int]$ms.StructOoc; $sot++ }
        if ([int]$ms.StructOver -gt 0 -and -not ($rep.Ignore -and $rep.Ignore.ContainsKey($k))) { $sov += $k }
        if ($z -gt 0) { $zo += $z; $zt++; if ([int]$ms.ZoneFarNs -gt $zf) { $zf = [int]$ms.ZoneFarNs } }
        if ($ms.StabFallback) { $fb += $k }
    }
    if ($zo -gt 0) { Append-Log ((T "Contrôle après écriture : {0} intervalle(s) hors classe du raccord d'écriture de gw, dans la zone de ± 1 ms autour de l'index (jusqu'à {2} ms), non compté(s), sur {1} piste(s) relue(s) en 3 tours.") -f "$zo", "$zt", (Format-UiNum ($zf / 1e6) '0.00')) }
    if ($so -gt 0) { Append-Log ((T "Contrôle après écriture : {0} intervalle(s) hors classe reproductibles d'un tour à l'autre à la même position, sur {1} piste(s), non compté(s) : raccord d'écriture d'une longue piste ou protection.") -f "$so", "$sot") }   # 12.10 (S13)
    if ($sov.Count -gt 0) { Append-Log ((T "Contrôle après écriture : {0} piste(s) avec plus de {1} intervalles hors classe reproductibles par tour, tous comptés comme erreurs (au-delà d'un raccord d'écriture ou d'une protection : défaut du support ou écriture à revoir) : {2}.") -f "$($sov.Count)", "$($script:ScpStructMax)", "$(Format-TrackList $sov)") }
    if ($fb.Count -gt 0) { Append-Log ((T "Contrôle après écriture : stabilité de {0} piste(s) jugée sur l'écart du nombre de flux entre les tours, faute de repère commun pour les aligner : {1}.") -f "$($fb.Count)", "$(Format-TrackList $fb)") }
    if ($fake -and $rep.Round -eq 0) { Append-Log (T "Contrôle après écriture : index simulé (--fake-index), la zone de l'index est comptée comme le reste de la piste.") }
    if ($rep.Ignore) {
        # Restauration d un flux ou image SCP : pistes deja critiques ou non reproductibles (zone instable), non comptees.
        # 12.8.2 (decision du 27/10/2026) : pistes deja hors norme par leurs erreurs dans la source (Rep.SrcOver, aussi dans
        # Rep.Ignore : Copylock, defaut d origine), non reecrites, signalees par une ligne a part
        $ign = @(@($watch) + @($crit) | Where-Object { $rep.Ignore.ContainsKey($_) })
        $ovr = @($ign | Where-Object { $rep.SrcOver -and $rep.SrcOver.ContainsKey($_) })
        $ign = @($ign | Where-Object { -not ($rep.SrcOver -and $rep.SrcOver.ContainsKey($_)) })
        if ($ign.Count -gt 0 -and $rep.Round -eq 0) { Append-Log ((T "Contrôle : {0} piste(s) non reproductible(s) ou déjà critique(s) dans la source, non comptée(s) : {1}") -f "$($ign.Count)", "$(Format-TrackList $ign)") }
        if ($ovr.Count -gt 0 -and $rep.Round -eq 0) { Append-Log ((T "Contrôle : {0} piste(s) déjà hors norme dans l'original, non réécrite(s) : {1}") -f "$($ovr.Count)", "$(Format-TrackList (Sort-TrackKeys $ovr))") }
        $watch = @($watch | Where-Object { -not $rep.Ignore.ContainsKey($_) }); $crit = @($crit | Where-Object { -not $rep.Ignore.ContainsKey($_) })
    }
    $weak = Sort-TrackKeys (@($watch) + @($crit))
    $lw = if ($watch.Count -gt 0) { " : $(Format-TrackList $watch)" } else { '' }
    $lc = if ($crit.Count -gt 0) { " : $(Format-TrackList $crit)" } else { '' }
    if ($rep.Round -eq 0) {
        $rep.Measured = $expected.Count
        Append-Log ((T "Contrôle complet : {0} piste(s) mesurée(s), {1} saine(s), {2} à surveiller{3}, {4} critique(s) ou illisible(s){5}.") -f "$($expected.Count)", "$healthy", "$($watch.Count)", "$lw", "$($crit.Count)", "$lc")
    } else {
        Append-Log ((T "Remesure après réécriture {0}/{1} : {2} piste(s), {3} saine(s), {4} à surveiller{5}, {6} critique(s) ou illisible(s){7}.") -f "$($rep.Round)", "$($rep.Max)", "$($expected.Count)", "$healthy", "$($watch.Count)", "$lw", "$($crit.Count)", "$lc")
    }
    $rep.Weak = $weak
    if ($expected.Count -eq 0) { Append-Log (T 'Contrôle après écriture : aucune piste mesurée.'); Complete-WriteCheck; return }
    if ($weak.Count -eq 0) { Complete-WriteCheck; return }
    # Garde-fou sur un controle large seulement : une selection de quelques pistes doit pouvoir etre reecrite
    # Garde-fou calcule aux seuils Standard : un reglage strict du jitter fait reecrire davantage, sans faux diagnostic
    $weakStd = @($weak | Where-Object { $s = $rep.State[$_]; $s.Bad -or (Get-HealthLevel $s.Ooc $s.Dr $s.Stab $s.J $script:JitterStdOk $script:JitterStdWatch) -ge 1 })
    if ($rep.Round -eq 0 -and $expected.Count -ge 20 -and $weakStd.Count * 2 -gt $expected.Count) {
        $rep.Safety = $true
        Append-Log ((T "Plus de la moitié des pistes sont faibles ({0}/{1}) : format non MFM, disquette inadaptée ou lecteur en défaut. Aucune réécriture automatique.") -f "$($weakStd.Count)", "$($expected.Count)")
        Complete-WriteCheck; return
    }
    if ($rep.Round -ge $rep.Max) { Complete-WriteCheck; return }
    # Passe de reecriture : pistes faibles seules, puis remesure de ces seules pistes. 12.8.2 : double densite
    # (Rep.EraseMode 'hfreq') : effacement haute frequence des pistes faibles (gw erase --hfreq, memes elements du champ
    # Pistes), toujours, quelle que soit la case « Effacer avant d ecrire » (comme le pre-effacement force d avant), puis
    # reecriture sans --pre-erase ; haute densite (et autres cas 'pre') : pre-effacement force. Revue 12.8.2 : chaque
    # reecriture est precedee de l effacement de ses seules pistes (meme --tracks), et non toutes les pistes de la passe
    # d abord : un arret de gw n expose que les pistes de la commande en cours ; pistes effacees de la passe (EraseLog,
    # Read-GwOutput) restees sans ecriture : marquees illisibles par Update-RepPartial
    $rep.Round++
    Append-Log ((T "Réécriture des pistes faibles, passe {0}/{1} : {2}") -f "$($rep.Round)", "$($rep.Max)", "$(Format-TrackList $weak)")
    $groups = Get-TrackGroups $weak
    $extras = Get-TSpecExtras $rep.UserTSpec
    $hf = ([string]$rep.EraseMode -eq 'hfreq')
    $wbase = @($rep.Base)
    if ($hf) { $wbase = @($wbase | Where-Object { $_ -ne '--pre-erase' }) } elseif ($wbase -notcontains '--pre-erase') { $wbase += '--pre-erase' }
    $rep.Pending.Clear()
    # Lecteur et port memorises au clic (Rep.Common, comme les relectures) et --fake-index de l ecriture (Rep.Base)
    $eda = @(@($rep.Common) + @(@($rep.Base) | Where-Object { $_ -match '^--fake-index=' }))
    $wts = @()
    if ($null -ne $rep.HeadPrecomp) {
        # Ecriture lente : une reecriture par tete, chacune avec sa precompensation
        foreach ($h in 0, 1) {
            $cs = @($weak | Where-Object { ($_ -split '\.')[1] -eq "$h" } | ForEach-Object { [int](($_ -split '\.')[0]) })
            if ($cs.Count -eq 0) { continue }
            $cmd = @($wbase); if ($rep.HeadPrecomp[$h]) { $cmd += @('--precomp', $rep.HeadPrecomp[$h]) }
            $wts += @{ Ts = "c=$(Format-CylList $cs):h=$h$extras"; Cmd = $cmd }
        }
    } else {
        foreach ($g in $groups) { $wts += @{ Ts = "$g$extras"; Cmd = $wbase } }
    }
    $ers = @()
    foreach ($wt in $wts) {
        if ($hf) { $ec = [string[]](@('erase') + $eda + @('--hfreq', "--tracks=$($wt.Ts)")); $rep.Pending.Enqueue($ec); $ers += ,$ec }
        $rep.Pending.Enqueue([string[]](@($wt.Cmd) + @("--tracks=$($wt.Ts)", "`"$($rep.Image)`"")))
    }
    $script:EraseLog = $null
    if ($hf -and $ers.Count -gt 0) {
        $script:EraseLog = @{ Owner = 'check'; Round = [int]$rep.Round; Erased = @{}; Written = @{} }
        Append-Log ((T "Effacement haute fréquence des pistes faibles avant leur réécriture (disquette double densité) : {0}.") -f (Format-EraseTracks $ers))
    }
    Add-RepReads $groups $extras
    Start-RepPending
}

function Show-WriteCheckTable($rep) {
    # Etat final de chaque piste controlee (derniere mesure) dans l onglet Qualite, avec reecritures et retries
    $keys = Sort-TrackKeys @($rep.State.Keys)
    $last = @{}; $total = 0.0; $count = 0; $nBad = 0
    # 12.8 (lot 3b) : icone d etat de 16 px devant le texte de la colonne Etat
    $lvAl.Columns[1].Width = $(if (@($rep.State.Values | Where-Object { $_.Weak }).Count -gt 0) { 302 } else { 222 })
    $lvAl.BeginUpdate()
    try {
        $lvAl.Items.Clear()
        foreach ($k in $keys) {
            $m = $rep.State[$k]
            $mark = ''
            if ($rep.Rewrites.ContainsKey($k)) { $mark = ((T " (réécrite x{0})") -f "$($rep.Rewrites[$k])") }
            elseif ($rep.Retries.ContainsKey($k)) { $mark = ((T " (essais x{0})") -f "$($rep.Retries[$k])") }
            [void]$lvAl.Items.Add((New-AlignRow $k $m $mark '-' -1))
            if ($m.Bad) { $last[$k] = @{ Score = 9999; Jitter = 0; Asym = 0; Err = 0; Stab = 0; Cell = 0 }; $nBad++; continue }
            $last[$k] = @{ Score = $m.Score; Jitter = $m.J; Asym = $m.Asym; Err = $m.Ooc; Stab = $m.Stab; Cell = $m.Cell }
            $total += $m.Score; $count++
        }
    } finally { $lvAl.EndUpdate() }
    # Bandeau des zones instables d apres la derniere mesure du controle (efface celui d une mesure precedente)
    $inIgn = { param($k) $rep.Ignore -and $rep.Ignore.ContainsKey($k) }
    $defK = @($keys | Where-Object { $rep.State[$_].CopyDefect })
    $srcK = @($keys | Where-Object { $rep.State[$_].Weak -and (& $inIgn $_) -and $rep.SrcWeak -and $rep.SrcWeak.ContainsKey($_) })
    $crtK = @($keys | Where-Object { $rep.State[$_].Weak -and (& $inIgn $_) -and -not ($rep.SrcWeak -and $rep.SrcWeak.ContainsKey($_)) })
    $unkK = @($keys | Where-Object { $rep.State[$_].Unjudged -and -not (& $inIgn $_) })
    Set-UnstableBanner @(
        $(if ($defK.Count -gt 0) { (T "Zone instable sur la copie, défaut probable du support (la source n'en contient pas) : {0}") -f "$(Format-TrackList $defK)" }),
        $(if ($srcK.Count -gt 0) { (T "Zone instable de la source (protection probable, non reproductible) : {0}") -f "$(Format-TrackList $srcK)" }),
        $(if ($crtK.Count -gt 0) { (T "Zone instable sur une piste déjà critique dans la source : {0}") -f "$(Format-TrackList $crtK)" }),
        $(if ($unkK.Count -gt 0) { (T "Zone instable non jugée (la source peut contenir une protection) : {0}") -f "$(Format-TrackList $unkK)" }))
    $script:AlignLast = $last
    # 12.8 (lot 3) : resultat du controle sur la carte de l onglet Qualite ; son etat (COPIE SAINE, pistes faibles) suit
    # dans Complete-WriteCheck (Set-QualityCheckState)
    $res = @{ Kind = 'check'; Score = $null; Lvl = 3; Count = $count; Bad = $nBad; Health = -1; CheckLvl = -1; Weak = 0; HealthText = ''; HealthSub = '' }
    if ($count -gt 0) {
        $avg = [math]::Round($total / $count, 0); $lvl = Get-AlLevel 'score' $avg
        $res.Score = $avg; $res.Lvl = $lvl
        $res.ScoreText = ((T "Contrôle après écriture : score moyen {0} ({1}) sur {2} piste(s) lisible(s)") -f "$avg", "$($script:AlNames[$lvl])", "$count")
    } else {
        $res.ScoreText = (T 'Aucune piste analysable')
    }
    # 12.11 : resume de l asymetrie des pistes lisibles (Get-AsymSummary : signe commun, part du score moyen) : infobulle
    # de la carte et journal ; l en-tete de l export le recalcule sur les lignes du tableau, meme fonction
    $res.AsymText = Get-AsymSummaryText (Get-AsymSummary @($keys | ForEach-Object { $rep.State[$_] }))
    if ($res.AsymText) { Append-Log ((T "Contrôle après écriture : {0}") -f $res.AsymText) }
    Set-QualityResult $res
}

function Complete-WriteCheck([switch]$GwError) {
    $rep = $script:Rep; $script:Rep = $null
    if (-not $rep) { return }
    Show-WriteCheckTable $rep
    $n = $rep.State.Count
    $weak = @(@($rep.Weak) | Where-Object { $_ })
    $nRew = $rep.Rewrites.Count
    # Pistes ignorees (non reproductibles ou deja critiques) : ni saines ni faibles, signalees a part ; de meme les pistes
    # a zone instable non jugee
    $ignK = @(@($rep.State.Keys) | Where-Object { $rep.Ignore -and $rep.Ignore.ContainsKey($_) -and ($rep.State[$_].Bad -or $rep.State[$_].Level -ge 1 -or $rep.State[$_].Weak) })
    $unjK = @(@($rep.State.Keys) | Where-Object { $rep.State[$_].Unjudged -and -not $rep.State[$_].Bad -and $rep.State[$_].Level -lt 1 -and -not ($rep.Ignore -and $rep.Ignore.ContainsKey($_)) })
    $nOk = $n - $ignK.Count - $unjK.Count
    # 12.8.2 : pistes deja hors norme dans la source (Rep.SrcOver) citees a part des pistes non reproductibles ou critiques
    $ovrK = @($ignK | Where-Object { $rep.SrcOver -and $rep.SrcOver.ContainsKey($_) })
    $ignC = @($ignK | Where-Object { -not ($rep.SrcOver -and $rep.SrcOver.ContainsKey($_)) })
    if ($GwError) {
        # gw a echoue pendant une passe de reecriture : les pistes de la passe restent faibles
        # 12.10 (lot 1, I-5) : verdict neutre, l usure du support n est pas presumee
        $txt = ((T "CONTRÔLE APRÈS ÉCRITURE interrompu par une erreur gw à la passe {0}/{1} : {2} piste(s) faible(s) ou non remesurée(s) : {3}  ->  disquette ou lecteur en défaut, non distingués") -f "$($rep.Round)", "$($rep.Max)", "$($weak.Count)", "$(Format-TrackList $weak)"); $lvl = 3
    } elseif ($n -eq 0) {
        $txt = (T 'CONTRÔLE APRÈS ÉCRITURE : aucune piste mesurée.'); $lvl = 3
    } elseif ($weak.Count -eq 0) {
        $txt = ((T "CONTRÔLE APRÈS ÉCRITURE : {0}/{1} pistes saines") -f "$nOk", "$n")
        if ($ignC.Count -gt 0) { $txt += ((T ", {0} piste(s) non reproductible(s) ou déjà critique(s) non comptée(s) : {1}") -f "$($ignC.Count)", "$(Format-TrackList (Sort-TrackKeys $ignC))") }
        if ($ovrK.Count -gt 0) { $txt += ((T ", {0} piste(s) déjà hors norme dans l'original non comptée(s) : {1}") -f "$($ovrK.Count)", "$(Format-TrackList (Sort-TrackKeys $ovrK))") }
        if ($unjK.Count -gt 0) { $txt += ((T ", {0} piste(s) à zone instable non jugée(s) : {1}") -f "$($unjK.Count)", "$(Format-TrackList (Sort-TrackKeys $unjK))") }
        if ($nRew -gt 0) { $txt += ((T ", après réécriture de {0} piste(s) en {1} passe(s)") -f "$nRew", "$($rep.Round)") }
        $lvl = 0
    } elseif ($rep.Safety) {
        $txt = ((T "CONTRÔLE APRÈS ÉCRITURE : {0}/{1} pistes faibles, réécriture automatique non lancée (plus de la moitié des pistes)  ->  vérifier le format, la disquette et le lecteur") -f "$($weak.Count)", "$n"); $lvl = 3
    } elseif ($rep.Max -eq 0) {
        $txt = ((T "CONTRÔLE APRÈS ÉCRITURE : {0}/{1} piste(s) faible(s) : {2}  (réécriture automatique désactivée)") -f "$($weak.Count)", "$n", "$(Format-TrackList $weak)"); $lvl = 2
    } else {
        # 12.10 (lot 1, I-5) : verdict neutre (esprit du libelle 12.8 de la calibration) : l usure n est pas presumee, une
        # autre disquette reste conseillee
        $txt = ((T "CONTRÔLE APRÈS ÉCRITURE : {0} piste(s) encore faible(s) après {1} passe(s) de réécriture : {2}  ->  autre type de disquette ou usure, non distingués ; essayez une autre disquette") -f "$($weak.Count)", "$($rep.Round)", "$(Format-TrackList $weak)"); $lvl = 3
    }
    # 12.10 : ecriture pour un lecteur cible (Rep.Target, Rep.TargetSrc : Start-ImageWrite) : le verdict rappelle que la
    # relecture est celle du lecteur qui a ecrit, pas celle du lecteur cible
    if ($rep.Target) { $txt += ((T " (relu par le lecteur {0}, pas par le lecteur cible {1})") -f "$($rep.TargetSrc)", "$($rep.Target)") }
    Append-Log $txt
    # Bilan exploitable par la restauration (accroche : le controle vide la chaine d etapes, rien ne le suit)
    $short = if ($GwError) { (T 'contrôle interrompu par une erreur gw') } elseif ($lvl -eq 0) { (T "{0}/{1} pistes saines") -f "$nOk", "$n" }
             elseif ($n -eq 0) { (T 'aucune piste mesurée') } else { (T "{0} piste(s) faible(s) : {1}") -f "$($weak.Count)", "$(Format-TrackList $weak)" }
    # 12.11 : barre d etat en fin de sequence (Set-SeqEnd, 110) : le bilan court du controle, a la place de « Lecture
    # termine(e) » et du compteur de la derniere relecture ; icone du niveau (0 : ok, 3 : err, sinon neutre). En
    # restauration, la relecture de comparaison puis le verdict de la restauration le remplacent
    Set-SeqEnd ((T "Contrôle après écriture : {0}") -f "$short") $(if ($lvl -le 0) { 'ok' } elseif ($lvl -ge 3) { 'err' } else { 'idle' })
    # 12.8 (lot 3) : verdict sur la carte de l onglet Qualite (texte complet dans l infobulle) et dans l onglet Ecriture,
    # avec l icone d etat (niveau 0 : h0, 2 : h1, 3 : h2) et son encre
    Set-QualityCheckState $lvl $txt $short $weak.Count
    Set-WCalVerdict $txt $(if ($lvl -le 0) { 'h0' } elseif ($lvl -le 2) { 'h1' } else { 'h2' })
    $script:LastCheck = @{ Ok = ($lvl -eq 0); Level = $lvl; Text = $txt; Short = $short; Weak = $weak; Measured = $n; Rounds = $rep.Round; Rewrites = $nRew; GwError = [bool]$GwError }
    if ($script:Restore) {
        if ($GwError) { Stop-Restore (T 'erreur gw pendant le contrôle des pistes') } else { Invoke-RestoreNext }
        return
    }
    # 12.10 (lot 1, E11) : retour a l onglet d avant le controle (verdict dans l onglet Ecriture, detail dans l onglet
    # Qualite) ; en 12.8, l onglet Qualite restait affiche a la fin
    Exit-CheckTab
}

function Update-RepPartial {
    # Passe interrompue par gw : une relecture terminee implique que les ecritures de la passe l ont precedee.
    # Les pistes remesurees prennent leur nouvelle mesure ; les autres restent « faibles ou non remesurees ».
    $rep = $script:Rep
    $remeasured = @{}
    $fake = Test-RepFakeIndex $rep
    foreach ($scp in @($rep.Scps)) {
        if (-not (Test-Path -LiteralPath $scp)) { continue }
        try { $t = Read-ScpFile $scp -NoIndexZone:$fake } catch { continue }
        foreach ($tn in @($t.Keys)) {
            $k = "$([math]::Floor([int]$tn / 2)).$([int]$tn % 2)"
            if (@($rep.Weak) -notcontains $k) { continue }
            $mm = Get-TrackMetrics $t[$tn]; Set-CopyUnstable $rep $k $mm
            $rep.State[$k] = $mm
            $rep.Rewrites[$k] = 1 + $(if ($rep.Rewrites.ContainsKey($k)) { [int]$rep.Rewrites[$k] } else { 0 })
            $remeasured[$k] = $true
        }
    }
    # Revue 12.8.2 : pistes faibles de la passe effacees en haute frequence (lignes « Erasing Track », EraseLog de la passe)
    # sans ligne « Writing Track » ensuite, ni remesure : vierges, et non plus a leur mesure d avant la passe ; marquees
    # illisibles (absentes de la relecture), une ligne de journal
    $el = $script:EraseLog
    if ($el -and [string]$el.Owner -eq 'check' -and [int]$el.Round -eq [int]$rep.Round) {
        $blank = Sort-TrackKeys @(@($rep.Weak) | Where-Object { $el.Erased.ContainsKey([string]$_) -and -not $el.Written.ContainsKey([string]$_) -and -not $remeasured.ContainsKey($_) })
        foreach ($k in $blank) { $mm = Get-TrackMetrics @(); $mm.Missing = $true; $rep.State[$k] = $mm }
        if (@($blank).Count -gt 0) { Append-Log ((T "Contrôle après écriture : piste(s) effacée(s) en haute fréquence et non réécrite(s) après l'arrêt de gw : {0}. Elles sont vierges sur la disquette : réécrivez l'image.") -f "$(Format-TrackList $blank)") }
    }
    $rep.Weak = Sort-TrackKeys @(@($rep.Weak) | Where-Object { -not $remeasured.ContainsKey($_) -or $rep.State[$_].Bad -or $rep.State[$_].Level -ge 1 })
}

function Stop-WriteCheck([switch]$GwError) {
    # Abandon (bouton Arreter, erreur gw, operation incomplete, fichier manquant) : rien n est reecrit ensuite.
    # Erreur gw pendant une passe de reecriture : verdict et tableau avec les mesures deja acquises.
    if (-not $script:Rep) { return }
    if ($GwError -and $script:Rep.Round -gt 0 -and $script:Rep.State.Count -gt 0) { Update-RepPartial; Complete-WriteCheck -GwError; return }
    $script:Rep = $null
    Exit-CheckTab                                         # 12.10 (lot 1, E11) : sans effet si la relecture n a pas commence
    Set-WCalVerdict (T 'Contrôle après écriture interrompu.') 'h1'     # 12.8 (lot 3) : icone d etat dans l onglet Ecriture
    Append-Log (T 'Contrôle après écriture interrompu.')
    Set-QualityStale 'checkabort'                         # 12.8 (lot 3a) : resultat de l onglet Qualite perime
    if ($script:Restore) { Stop-Restore (T 'contrôle des pistes interrompu') }
}
# ============================== FONCTIONS : COMPARAISON ========================

function Get-DecodedExt([string]$fmt) {
    if ($fmt -like 'amiga.*') { return '.adf' }
    if ($fmt -like 'atarist.*') { return '.st' }
    return '.img'
}

function Get-SectorsPerTrack([string]$fmt) {
    switch ($fmt) {
        'amiga.amigados'    { return 11 }
        'amiga.amigados_hd' { return 22 }
        'ibm.720'           { return 9 }
        'ibm.1440'          { return 18 }
        'ibm.360'           { return 9 }
        'atarist.720'       { return 9 }
        'atarist.800'       { return 10 }
        'atarist.880'       { return 11 }
        default             { return 0 }
    }
}

function Get-BadSectorIndexes([byte[]]$b) {
    # Index des blocs de 512 octets remplis par gw du motif « -=[BAD SECTOR]=- » (secteur manquant a la lecture ou a la
    # conversion : codecs AmigaDOS et IBM de gw 1.23) ; tableau vide sinon
    $pat = [System.Text.Encoding]::ASCII.GetBytes('-=[BAD SECTOR]=-')
    $list = New-Object System.Collections.Generic.List[int]
    if ($null -eq $b) { return ,$list.ToArray() }
    for ($s = 0; $s + 512 -le $b.Length; $s += 512) {
        $same = $true
        for ($i = 0; $i -lt 512; $i++) { if ($b[$s + $i] -ne $pat[$i % 16]) { $same = $false; break } }
        if ($same) { $list.Add([int]($s / 512)) }
    }
    return ,$list.ToArray()
}

function Get-CmpFormatChoice {
    # 12.8 (D13) : choix de la liste du format de la comparaison, d apres le texte affiche (un texte pose par le code ne
    # remet pas SelectedIndex a -1) : 'auto' pour « (detection automatique) » (premier element, par defaut), sinon le
    # format choisi ou saisi (liste modifiable : tout format de gw, comme en 12.7)
    if ([string]$cmbCmpFmt.Text -eq $script:CmpAutoItem) { return 'auto' }
    return ([string]$cmbCmpFmt.Text).Trim()
}

function Update-CmpFmtFound {
    # 12.8 (D13) : reglage compareFormat (Update-SettingDependents) : liste resynchronisee quand elle n affiche pas le
    # reglage (format saisi hors de la liste, que la liaison ne sait pas choisir ; texte saisi remplace par Set-Defaults
    # ou Load-Config), sous la garde des liaisons ; une saisie en cours n est jamais touchee : seul un format valide met
    # le reglage a jour (gestionnaire TextChanged, 530). Ligne sous la liste : « Format detecte a la lecture » en
    # detection automatique, vide sinon ; le resultat de la detection y reste apres une comparaison, jusqu au prochain choix
    if (-not $lblCmpFmtFound) { return }
    $v = [string](Get-Setting 'compareFormat')
    if ((Get-CmpFormatChoice) -cne $v) {
        $i = [array]::IndexOf([string[]]$script:SettingDefs['compareFormat'].Codes, $v)
        $sv = $script:SettingSync; $script:SettingSync = $true
        try {
            $cmbCmpFmt.SelectedIndex = -1
            if ($i -ge 0 -and $i -lt $cmbCmpFmt.Items.Count) { $cmbCmpFmt.SelectedIndex = $i } else { $cmbCmpFmt.Text = $v }
        } finally { $script:SettingSync = $sv }
    }
    $t = $(if ((Get-CmpFormatChoice) -eq 'auto') { (T 'Format détecté à la lecture') } else { '' })
    $lblCmpFmtFound.Text = $t; $tip.SetToolTip($lblCmpFmtFound, $t)
}

function Start-Compare {
    # 12.7 : reference convertie dans le format choisi (copiee si elle est deja decodee), disquette lue dans ce format,
    # puis comparaison octet par octet (Compare-Images). 12.8 (lot 2, point 6 ; A1 § 4.2 ; D8, D13 ; decisions128) :
    #  - detection automatique (premier element de la liste, par defaut) : format de la reference sans disque
    #    (Get-RefImageFormat), ou par decodage de ses pistes 0.0 et 0.1 (IPF, SCP, HFE : Start-CompareRefDecode) ; puis
    #    sonde de deux pistes de la disquette dans ce format ; aucun secteur : format de la disquette detecte
    #    (Invoke-DiskFormatDetect) et resultat « formats differents » sans lecture complete ;
    #  - lectures de la disquette avec les options de lecteur de l onglet Ecriture (Get-DriveReadArgs), comme la
    #    restauration ;
    #  - reference secteur de plus de cylindres que le format (ADF de 81 a 83 cylindres) : gw ne lit que les cylindres de
    #    la definition du format (read.py v1.23 : « Out of range for format », piste non emise) ; FIX2 : plus de --tracks
    #    au-dela du format (sans effet, tete deplacee pour rien, sans borne), les cylindres suivants sont signales en
    #    reserve et non comptes comme differents.
    $ref = $txtCmpRef.Text
    if (-not $ref -or -not (Test-Path -LiteralPath $ref)) {
        [void](Show-AppMessage (T 'Image de référence introuvable.') (T 'Erreur') 'OK' 'Warning'); return
    }
    $choice = Get-CmpFormatChoice
    if (-not $choice) {
        [void](Show-AppMessage (T 'Choisissez un format de décodage.') (T 'Erreur') 'OK' 'Warning'); return
    }
    if (Get-AppBusy) { return }                           # 12.8 (D20) : test d occupation unique

    if (-not (Test-Path -LiteralPath $script:TempDir)) { [void](New-Item -ItemType Directory -Path $script:TempDir -Force) }
    $script:CmpStamp   = Get-Date -Format 'yyyyMMdd-HHmmss'
    $script:CmpRefName = [System.IO.Path]::GetFileName($ref)
    $script:CmpRefPath = $ref
    $script:CmpRetries = [int]$numCmpRetries.Value
    $script:CmpAuto    = $null
    $script:Chain.Clear()
    if ($choice -ne 'auto') { Start-CompareWith $choice; return }

    $ri = Get-RefImageFormat $ref
    $script:CmpAuto = @{ Ref = $ri; RefWhy = $ri.Why; Disk = ''; Cands = @(); Results = @(); Idx = 0 }
    $txtCmpResult.Text = ((T "Comparaison en cours...`r`nReference : {0}`r`nFormat    : {1}") -f "$ref", (T 'détection automatique'))
    $lblCmpFmtFound.Text = (T 'Format détecté à la lecture')
    Append-Log ((T "=== Comparaison : {0} ({1}) ===") -f "$($script:CmpRefName)", (T 'détection automatique'))
    if ($ri.Need -eq 'decode') { $script:CmpAuto.Cands = @($ri.Cands); Start-CompareRefDecode; return }
    if (-not $ri.Format) { Stop-CompareAuto ((T "format de la référence non reconnu ({0}) : choisissez le format de décodage dans la liste.") -f $ri.Why); return }
    Append-Log ((T "Comparaison : format de la référence {0} ({1}).") -f $ri.Format, $ri.Why)
    Start-CompareWith $ri.Format
}

function Stop-CompareAuto([string]$why) {
    # Detection automatique sans format de reference : rien n est lu sur la disquette
    $script:Chain.Clear(); $script:GwCapture = $null; $script:CmpAuto = $null
    $txtCmpResult.Text = ((T "ÉCHEC : {0}") -f $why)
    $lblCmpFmtFound.Text = $why; $tip.SetToolTip($lblCmpFmtFound, $why)
    Append-Log ((T "Comparaison impossible : {0}") -f $why)
}

function Start-CompareRefDecode {
    # IPF, SCP, HFE en detection automatique : pistes 0.0 et 0.1 de la reference decodees par gw avec chaque candidat de
    # Get-RefImageFormat, jusqu au premier dont les deux pistes sont completes ; puis Select-RefDecodeFormat
    $a = $script:CmpAuto
    if (-not $a) { return }
    if ($a.Idx -ge @($a.Cands).Count) { Complete-CompareRefDecode; return }
    $f = [string]@($a.Cands)[$a.Idx]
    $out = Join-Path $script:TempDir ("cmp-$($script:CmpStamp)-reference-sonde$($a.Idx)" + (Get-DecodedExt $f))
    $script:CmpGwArgs = @('convert', "--format=$f", '--tracks=c=0:h=0-1', "`"$($script:CmpRefPath)`"", "`"$out`"")
    $script:GwCapture = New-Object System.Collections.Generic.List[string]
    $script:Chain.Enqueue({ Start-Gw $script:CmpGwArgs })
    $script:Chain.Enqueue({ Step-CompareRefDecode })
    Invoke-NextChainStep
}

function Step-CompareRefDecode {
    $a = $script:CmpAuto
    if (-not $a) { return }
    $lines = @(if ($script:GwCapture) { @($script:GwCapture) } else { @() }); $script:GwCapture = $null
    $a.Results = @($a.Results) + ,@{ Fmt = [string]@($a.Cands)[$a.Idx]; Lines = $lines }
    $a.Idx++
    $sel = Select-RefDecodeFormat $a.Results
    if ($sel.Format -and @($sel.Inc).Count -eq 0) { $a.Idx = @($a.Cands).Count }   # deux pistes completes : la suite est inutile
    Start-CompareRefDecode
}

function Complete-CompareRefDecode {
    $a = $script:CmpAuto
    if (-not $a) { return }
    $sel = Select-RefDecodeFormat $a.Results
    if (-not $sel.Format) { Stop-CompareAuto ((T "format de la référence non reconnu ({0}) : choisissez le format de décodage dans la liste.") -f ($a.RefWhy + ' ; ' + $sel.Text)); return }
    $a.RefWhy = $a.RefWhy + ' : ' + $sel.Text
    Append-Log ((T "Comparaison : format de la référence {0} ({1}).") -f $sel.Format, $a.RefWhy)
    Start-CompareWith $sel.Format
}

function Get-CompareReadArgs([string]$out, [switch]$Probe) {
    # Lecture de la disquette (12.8, D8 : options de lecteur de l onglet Ecriture) : sonde des pistes 0.0 et 0.1 (2 tours,
    # sans nouvel essai), ou lecture complete (essais de l onglet ; cylindres du format, FIX2)
    $a = @('read') + (Get-CommonArgs) + @(Get-DriveReadArgs)
    if ($Probe) { $a += @("--format=$($script:CmpFmt)", '--tracks=c=0:h=0-1', '--revs=2', '--retries=0') }
    else { $a += @("--retries=$($script:CmpRetries)", "--format=$($script:CmpFmt)") }
    return @($a + @("`"$out`""))
}

function Start-CompareWith([string]$fmt) {
    # Comparaison dans le format $fmt (choisi, ou detecte pour la reference) : reference copiee ou convertie, puis
    # disquette lue (detection automatique : sonde de deux pistes d abord, Step-CompareProbe), puis Compare-Images
    $ref = $script:CmpRefPath
    $ext = Get-DecodedExt $fmt
    $st = $script:CmpStamp
    $script:CmpRefDecoded = Join-Path $script:TempDir "cmp-$st-reference$ext"
    $script:CmpDiskRead   = Join-Path $script:TempDir "cmp-$st-disquette$ext"
    $script:CmpProbe      = Join-Path $script:TempDir "cmp-$st-sonde$ext"
    $script:CmpFmt        = $fmt
    $script:CmpRefCyls    = 0
    $copy = ([System.IO.Path]::GetExtension($ref).ToLower() -eq $ext)
    $g = Get-FormatGeometry $fmt
    if ($copy) {
        # Reference deja decodee de plus de cylindres que le format (decisions128) : FIX2, gw ne lit que les cylindres du
        # format ; les suivants sont signales (Compare-Images), sans --tracks
        $ri = $(if ($script:CmpAuto) { $script:CmpAuto.Ref } else { Get-RefImageFormat $ref })
        if ($ri -and $ri.Format -eq $fmt -and $null -ne $ri.Cyls -and $g -and [int]$ri.Cyls -gt $g.Cyls) { $script:CmpRefCyls = [int]$ri.Cyls }
    }
    $shown = $(if ($script:CmpAuto) { (T "{0} (détecté : {1})") -f $fmt, $script:CmpAuto.RefWhy } else { $fmt })
    $txtCmpResult.Text = ((T "Comparaison en cours...`r`nReference : {0}`r`nFormat    : {1}") -f "$ref", "$shown")
    if (-not $script:CmpAuto) { Append-Log ((T "=== Comparaison : {0} ({1}) ===") -f "$($script:CmpRefName)", "$fmt") }
    if ($script:CmpRefCyls -gt 0) { Append-Log ((T "Comparaison : référence de {0} cylindres ; gw ne lit que les {1} cylindres du format {2} : les cylindres {1} à {3} ne seront pas comparés.") -f "$($script:CmpRefCyls)", "$($g.Cyls)", $fmt, "$($script:CmpRefCyls - 1)") }

    # Etapes = scriptblocks simples (pas de GetNewClosure : un closure tourne dans un
    # module dynamique qui ne voit ni les fonctions du script ni la portee $script:)
    $script:Chain.Clear()
    if ($copy) {
        $script:Chain.Enqueue({
            Copy-Item -LiteralPath $script:CmpRefPath -Destination $script:CmpRefDecoded -Force
            Append-Log (T 'Référence déjà au format décodé : copiée sans conversion.')
            Invoke-NextChainStep
        })
    } else {
        $script:Chain.Enqueue({
            Start-Gw @('convert', "--format=$($script:CmpFmt)", "`"$($script:CmpRefPath)`"", "`"$($script:CmpRefDecoded)`"")
        })
    }
    if ($script:CmpAuto) {
        $script:Chain.Enqueue({ $script:GwCapture = New-Object System.Collections.Generic.List[string]; Start-Gw (Get-CompareReadArgs $script:CmpProbe -Probe) })
        $script:Chain.Enqueue({ Step-CompareProbe })
    } else {
        $script:Chain.Enqueue({ Start-Gw (Get-CompareReadArgs $script:CmpDiskRead) })
        $script:Chain.Enqueue({ Compare-Images })
    }
    Invoke-NextChainStep
}

function Step-CompareProbe {
    # Detection automatique, apres la sonde : au moins un secteur au format de la reference -> lecture complete ; aucun ->
    # format de la disquette detecte, puis « formats differents » sans lecture complete (Complete-CompareDetect)
    $a = $script:CmpAuto
    if (-not $a) { return }
    $lines = @(if ($script:GwCapture) { @($script:GwCapture) } else { @() }); $script:GwCapture = $null
    $t = Get-GwTrackSectors $lines; $f = 0; $n = 0
    foreach ($k in @('0.0', '0.1')) { if ($t[$k]) { $f += [int]$t[$k].Found; $n += [int]$t[$k].Total } }
    if ($n -eq 0) { $g = Get-FormatGeometry $script:CmpFmt; if ($g) { $n = 2 * $g.Spt } }
    $a.Disk = (T "{0}/{1} secteurs sur les pistes 0.0 et 0.1") -f "$f", "$n"
    if ($f -gt 0) {
        Append-Log ((T "Comparaison : sonde de la disquette au format {0}, {1} : lecture complète.") -f $script:CmpFmt, $a.Disk)
        $script:Chain.Enqueue({ Start-Gw (Get-CompareReadArgs $script:CmpDiskRead) })
        $script:Chain.Enqueue({ Compare-Images })
        Invoke-NextChainStep
        return
    }
    Append-Log ((T "Comparaison : aucun secteur au format {0} sur les pistes 0.0 et 0.1 de la disquette : détection de son format, sans lecture complète.") -f $script:CmpFmt)
    Invoke-DiskFormatDetect 'compare' ''
}

function Complete-CompareDetect($res) {
    # Format de la disquette detecte apres une sonde sans secteur (Complete-DiskFormatDetect) : meme format que la
    # reference -> lecture complete quand meme (FIX2 : quelle que soit l action de la restauration, pistes protegees
    # comprises : Compare-Images les signale) ; sinon resultat « DIFFERENT : formats differents », sans lecture complete
    $a = $script:CmpAuto
    if (-not $a) { return }
    if ($res.Format -and $res.Format -eq $script:CmpFmt) {
        $a.Disk = $a.Disk + ' ; ' + ((T "format {0} détecté ensuite") -f $res.Format)
        Append-Log ((T "Comparaison : format {0} détecté sur la disquette, celui de la référence : lecture complète.") -f $res.Format)
        $script:Chain.Enqueue({ Start-Gw (Get-CompareReadArgs $script:CmpDiskRead) })
        $script:Chain.Enqueue({ Compare-Images })
        Invoke-NextChainStep
        return
    }
    $disk = $(if ($res.Kind -eq 'blank' -or $res.Kind -eq 'nofile') { (T 'aucune donnée lisible') } elseif ($res.Format) { $res.Format } else { (T 'format non reconnu') })
    # FIX2 : ligne « Disquette » propre a la comparaison (format reconnu ou non, scores des decodeurs), sans l action de la
    # restauration (« copie exacte du flux… »)
    $dn = $(if ($res.Kind -eq 'blank' -or $res.Kind -eq 'nofile') { (T 'aucune donnée lisible') } elseif ($res.Format -and $res.Name) { "$($res.Name) ($($res.Format))" } elseif ($res.Format) { $res.Format } else { (T 'format non reconnu') })
    if ($res.Kind -eq 'protect' -and $res.Format) { $dn += ' ; ' + (T 'piste 0.0 ou 0.1 incomplète') }
    $lines = New-Object System.Collections.Generic.List[string]
    $lines.Add(((T "Référence : {0}") -f "$($script:CmpRefName)"))
    $lines.Add(((T "Format    : {0} (détecté : {1} ; disquette {2})") -f $script:CmpFmt, $a.RefWhy, $a.Disk))
    $lines.Add(((T "Disquette : {0} ; détection : {1}") -f $dn, "$($res.Score)"))
    $lines.Add('')
    $lines.Add(((T "RÉSULTAT : DIFFÉRENT - formats différents (référence {0}, disquette {1})") -f $script:CmpFmt, $disk))
    $lines.Add(((T "           aucun secteur au format {0} sur les pistes 0.0 et 0.1 de la disquette : pas de lecture complète.") -f $script:CmpFmt))
    $txtCmpResult.Text = ($lines -join "`r`n")
    $t = (T "Référence {0}, disquette {1}") -f $script:CmpFmt, $disk
    $lblCmpFmtFound.Text = $t; $tip.SetToolTip($lblCmpFmtFound, $t)
    Append-Log ((T "Comparaison : DIFFÉRENT - formats différents (référence {0}, disquette {1})") -f $script:CmpFmt, $disk)
    $script:CmpAuto = $null
    Show-Tab $tabCmp
}

function Compare-Images {
    $refPath = $script:CmpRefDecoded
    $dskPath = $script:CmpDiskRead
    $fmt     = $script:CmpFmt
    if (-not (Test-Path -LiteralPath $refPath) -or -not (Test-Path -LiteralPath $dskPath)) {
        $txtCmpResult.Text = ((T "ÉCHEC : un des deux fichiers décodés est absent.`r`n{0}`r`n{1}") -f "$refPath", "$dskPath")
        Append-Log (T 'Comparaison impossible : fichier décodé manquant.')
        return
    }
    $form.Cursor = [System.Windows.Forms.Cursors]::WaitCursor
    try {
        $a = [System.IO.File]::ReadAllBytes($refPath)
        $b = [System.IO.File]::ReadAllBytes($dskPath)
        $sha = [System.Security.Cryptography.SHA1]::Create()
        $ha = [System.BitConverter]::ToString($sha.ComputeHash($a)).Replace('-','')
        $hb = [System.BitConverter]::ToString($sha.ComputeHash($b)).Replace('-','')

        # 12.8 (decisions128) : reference de plus de cylindres que le format, disquette relue sur autant de cylindres
        # (Start-CompareWith) : les cylindres que gw n a pas relus (disquette decodee plus courte d un nombre entier de
        # cylindres, au moins ceux du format) ne sont pas comptes comme differents ; ils sont signales
        $g = Get-FormatGeometry $fmt
        $skip = ''; $aCmp = $a
        if ($script:CmpRefCyls -gt 0 -and $g -and $b.Length -lt $a.Length) {
            $cb = $g.Heads * $g.Spt * 512
            if ($b.Length % $cb -eq 0 -and $b.Length / $cb -ge $g.Cyls) {
                $nb = [int]($b.Length / $cb)
                $skip = (T "cylindres {0} à {1} de la référence non relus : gw a lu la disquette sur {2} cylindres au format {3}") -f "$nb", "$($script:CmpRefCyls - 1)", "$nb", $fmt
                $aCmp = New-Object byte[] $b.Length; [Array]::Copy($a, $aCmp, $b.Length)
            }
        }

        $sectorSize = 512
        if ($script:FastCompare) {
            $diffSectors = [GwCompare]::DiffSectors($aCmp, $b, $sectorSize)
            $diffBytes   = [GwCompare]::DiffBytes($aCmp, $b)
        } else {
            $n = [Math]::Max($aCmp.Length, $b.Length); $diffBytes = 0
            $set = New-Object System.Collections.Generic.HashSet[int]
            for ($i = 0; $i -lt $n; $i++) {
                if ($i -ge $aCmp.Length -or $i -ge $b.Length -or $aCmp[$i] -ne $b[$i]) { $diffBytes++; [void]$set.Add([int][Math]::Floor($i / $sectorSize)) }
            }
            $diffSectors = @($set | Sort-Object)
        }
        $same = ($ha -eq $hb) -or ($skip -and @($diffSectors).Count -eq 0)

        # FIX2 : secteurs illisibles des deux cotes (motif « -=[BAD SECTOR]=- » de gw dans la reference convertie et dans
        # la lecture de la disquette : piste protegee, copie de flux ratee) : egaux octet pour octet, mais non compares ;
        # jamais « IDENTIQUE » sans reserve
        $badA = Get-BadSectorIndexes $aCmp
        $setB = New-Object 'System.Collections.Generic.HashSet[int]'
        foreach ($x in (Get-BadSectorIndexes $b)) { [void]$setB.Add([int]$x) }
        $both = @($badA | Where-Object { $setB.Contains([int]$_) })
        $bothTxt = ''
        if ($both.Count -gt 0) {
            $spt0 = Get-SectorsPerTrack $fmt; $hd0 = 2
            if ($g) { $spt0 = $g.Spt; $hd0 = $g.Heads }
            $tk = @{}
            if ($spt0 -gt 0) { foreach ($sIdx in $both) { $tr = [int][Math]::Floor([int]$sIdx / $spt0); $tk["$([int][Math]::Floor($tr / $hd0)).$($tr % $hd0)"] = $true } }
            $bothTxt = (T "{0} secteur(s) illisible(s) des deux côtés, non comparé(s) (pistes {1})") -f "$($both.Count)", "$(Format-TrackList (Sort-TrackKeys @($tk.Keys)))"
        }

        $lines = New-Object System.Collections.Generic.List[string]
        $lines.Add(((T "Référence : {0}") -f "$($script:CmpRefName)"))
        if ($script:CmpAuto) { $lines.Add(((T "Format    : {0} (détecté : {1} ; disquette {2})") -f $fmt, $script:CmpAuto.RefWhy, $script:CmpAuto.Disk)) }
        else { $lines.Add(((T "Format    : {0}") -f "$fmt")) }
        $lines.Add(((T "Taille    : référence {0} o / disquette {1} o") -f "$($a.Length)", "$($b.Length)"))
        $lines.Add(((T "SHA1 ref  : {0}") -f "$ha"))
        $lines.Add(((T "SHA1 disq : {0}") -f "$hb"))
        $lines.Add('')
        if ($same -and $bothTxt) {
            $lines.Add(((T "RÉSULTAT : IDENTIQUE SUR LES SECTEURS LUS - {0}") -f $bothTxt))
            $lines.Add((T '           Ces secteurs portent des deux côtés le motif « secteur illisible » de gw (piste protégée, ou copie'))
            $lines.Add(((T "           ratée) : ils ne sont pas vérifiés. Les autres secteurs correspondent octet pour octet au format {0}.") -f "$fmt"))
            if ($skip) { $lines.Add('           ' + ((T "Réserve : {0}.") -f $skip)) }
            Append-Log (((T "Comparaison : IDENTIQUE sur les secteurs lus ({0} octets) ; {1}") -f "$($aCmp.Length)", $bothTxt) + $(if ($skip) { ' ; ' + $skip } else { '' }))
        } elseif ($same) {
            $lines.Add((T 'RÉSULTAT : IDENTIQUE - la disquette correspond octet pour octet à la référence'))
            $lines.Add(((T "           sur l'ensemble des pistes décodables au format {0}.") -f "$fmt"))
            if ($skip) { $lines.Add('           ' + ((T "Réserve : {0}.") -f $skip)) }
            Append-Log (((T "Comparaison : IDENTIQUE ({0} octets)") -f "$($aCmp.Length)") + $(if ($skip) { ' ; ' + $skip } else { '' }))
        } else {
            $totalSectors = [Math]::Ceiling([Math]::Max($aCmp.Length, $b.Length) / $sectorSize)
            $lines.Add(((T "RÉSULTAT : DIFFÉRENT - {0} octet(s) sur {1} secteur(s) / {2}") -f "$diffBytes", "$($diffSectors.Count)", "$totalSectors"))
            if ($aCmp.Length -ne $b.Length) { $lines.Add((T '           (tailles différentes : vérifier le format de décodage)')) }
            if ($skip) { $lines.Add('           ' + ((T "Réserve : {0}.") -f $skip)) }
            if ($bothTxt) { $lines.Add('           ' + ((T "Réserve : {0}.") -f $bothTxt)) }
            $lines.Add('')
            # 12.8 : secteurs et faces de la geometrie du format (formats a une face, formats hors de la liste)
            $spt = Get-SectorsPerTrack $fmt; $hds = 2
            if ($g) { $spt = $g.Spt; $hds = $g.Heads }
            $shown = 0
            $byTrack = [ordered]@{}
            foreach ($sIdx in $diffSectors) {
                if ($spt -gt 0) {
                    $trk = [int][Math]::Floor($sIdx / $spt); $sec = $sIdx % $spt
                    $key = ((T "Cyl {0} Head {1} (piste {2})") -f "$([int][Math]::Floor($trk / $hds))", "$($trk % $hds)", "$trk")
                    if (-not $byTrack.Contains($key)) { $byTrack[$key] = New-Object System.Collections.Generic.List[int] }
                    $byTrack[$key].Add($sec)
                } else {
                    if ($shown -lt 40) { $lines.Add(((T "secteur logique {0} (offset 0x{1:X})") -f $sIdx, ($sIdx * $sectorSize))) }
                    $shown++
                }
            }
            if ($spt -gt 0) {
                $lines.Add(((T "Pistes en écart ({0}) :") -f "$($byTrack.Count)"))
                foreach ($k in $byTrack.Keys) {
                    if ($shown -ge 60) { $lines.Add('  ...'); break }
                    $secs = $byTrack[$k]
                    $lines.Add(((T "  {0,-28} secteurs : {1}") -f $k, (($secs | Sort-Object) -join ',')))
                    $shown++
                }
                if ($byTrack.Count -gt 0) {
                    $lines.Add('')
                    $lines.Add((T 'Une piste dont TOUS les secteurs diffèrent est probablement illisible'))
                    $lines.Add((T 'ou non-AmigaDOS (protection) ; quelques secteurs isolés = support marginal.'))
                }
            } elseif ($shown -gt 40) { $lines.Add(((T "  ... {0} autre(s)") -f "$($shown - 40)")) }
            Append-Log ((T "Comparaison : DIFFÉRENT - {0} octet(s), {1} secteur(s)") -f "$diffBytes", "$($diffSectors.Count)")
        }
        $lines.Add('')
        $lines.Add((T "Fichiers décodés conservés :"))
        $lines.Add("  $refPath")
        $lines.Add("  $dskPath")
        $txtCmpResult.Text = ($lines -join "`r`n")
        if ($script:CmpAuto) {
            $t = (T "{0} : {1} ; disquette {2}") -f $fmt, $script:CmpAuto.RefWhy, $script:CmpAuto.Disk
            $lblCmpFmtFound.Text = $t; $tip.SetToolTip($lblCmpFmtFound, $t)
        }
        Show-Tab $tabCmp
    } catch {
        $txtCmpResult.Text = ((T "ERREUR pendant la comparaison : {0}") -f "$($_.Exception.Message)")
        Append-Log ((T "Comparaison : erreur {0}") -f "$($_.Exception.Message)")
    } finally {
        $form.Cursor = [System.Windows.Forms.Cursors]::Default
        $script:CmpAuto = $null
    }
}
# ============================== FONCTIONS : DETECTION DU FORMAT ================
# 12.8 (lot 2, points 4 et 6 ; A1 § 3.3, 3.4 et 4.2 ; decisions128 : regle PC / Atari ST sur critere positif, ADF de 81 a
# 83 cylindres ; D12) : format d une disquette (restauration en detection automatique ; comparaison quand la sonde de la
# disquette ne trouve aucun secteur au format de la reference) et d une image de reference (comparaison).
#  - Invoke-DiskFormatDetect enchaine les commandes gw dans $script:Chain : D0 lecture ibm.scan --raw de deux pistes, D1
#    densite et pistes critiques du flux, D2 decodage Amiga hors ligne, D4 secteur de demarrage, D5 (FIX2) flux de trois
#    cylindres de plus quand la piste 0 est vierge (restauration, double densite) ; Select-DiskFormat,
#    fonction pure, decide d apres leurs lignes ; Complete-DiskFormatDetect rend le resultat a la restauration ou a la
#    comparaison.
#  - Get-RefImageFormat : format d une image de reference sans disque (ADF : taille ; ST, IMG, IMA : BPB puis taille), ou
#    candidats a decoder par gw sur deux pistes (IPF, SCP, HFE), departages par Select-RefDecodeFormat (fonction pure).

function Get-FormatGeometry([string]$fmt) {
    # Cylindres, faces et secteurs de 512 octets par piste des formats secteur de la detection (diskdefs de gw 1.23 :
    # diskdefs_amiga.cfg, diskdefs_ibm.cfg, diskdefs_atarist.cfg, relus le 20/10/2026) ; $null pour un autre format
    switch ($fmt) {
        'amiga.amigados'    { return @{ Cyls = 80; Heads = 2; Spt = 11 } }
        'amiga.amigados_hd' { return @{ Cyls = 80; Heads = 2; Spt = 22 } }
        'atarist.360'       { return @{ Cyls = 80; Heads = 1; Spt = 9 } }
        'atarist.400'       { return @{ Cyls = 80; Heads = 1; Spt = 10 } }
        'atarist.440'       { return @{ Cyls = 80; Heads = 1; Spt = 11 } }
        'atarist.720'       { return @{ Cyls = 80; Heads = 2; Spt = 9 } }
        'atarist.800'       { return @{ Cyls = 80; Heads = 2; Spt = 10 } }
        'atarist.880'       { return @{ Cyls = 80; Heads = 2; Spt = 11 } }
        'ibm.160'           { return @{ Cyls = 40; Heads = 1; Spt = 8 } }
        'ibm.180'           { return @{ Cyls = 40; Heads = 1; Spt = 9 } }
        'ibm.320'           { return @{ Cyls = 40; Heads = 2; Spt = 8 } }
        'ibm.360'           { return @{ Cyls = 40; Heads = 2; Spt = 9 } }
        'ibm.720'           { return @{ Cyls = 80; Heads = 2; Spt = 9 } }
        'ibm.800'           { return @{ Cyls = 80; Heads = 2; Spt = 10 } }
        'ibm.1200'          { return @{ Cyls = 80; Heads = 2; Spt = 15 } }
        'ibm.1440'          { return @{ Cyls = 80; Heads = 2; Spt = 18 } }
        'ibm.1680'          { return @{ Cyls = 80; Heads = 2; Spt = 21 } }
        'ibm.2880'          { return @{ Cyls = 80; Heads = 2; Spt = 36 } }
    }
    return $null
}

function Get-GeometryFormat([int]$cyls, [int]$heads, [int]$spt, [string[]]$order) {
    # Format d une geometrie (BPB) parmi $order : memes faces et secteurs par piste, cylindres du format a +3 pres
    # (disquettes de 81 a 83 cylindres) ; cylindres exacts d abord ; '' si aucun
    foreach ($exact in @($true, $false)) {
        foreach ($f in $order) {
            $g = Get-FormatGeometry $f
            if (-not $g -or $g.Heads -ne $heads -or $g.Spt -ne $spt) { continue }
            if ($exact -and $cyls -eq $g.Cyls) { return $f }
            if (-not $exact -and $cyls -gt $g.Cyls -and $cyls -le $g.Cyls + 3) { return $f }
        }
    }
    return ''
}

function Get-SizeFormat([long]$size, [string[]]$order) {
    # Format d une image secteur d apres sa seule taille, parmi $order (cylindres du format, puis jusqu a 3 de plus) ;
    # $null si aucun
    foreach ($d in 0..3) {
        foreach ($f in $order) {
            $g = Get-FormatGeometry $f
            if ($g -and $size -eq [long]($g.Cyls + $d) * $g.Heads * $g.Spt * 512) { return @{ Format = $f; Cyls = $g.Cyls + $d } }
        }
    }
    return $null
}

function Get-BootSectorInfo($b) {
    # Secteur de demarrage (512 octets) : octet 0, somme des 256 mots big-endian (0x1234 : amorcable Atari ST), signature
    # 0x55AA, BPB (octets par secteur 0x0B, total des secteurs 0x13, secteurs par piste 0x18, faces 0x1A ; Bpb : valeurs
    # plausibles) ; $null sans secteur ou pour un secteur non lu (motif « -=[BAD SECTOR]=- » de gw)
    if ($null -eq $b -or $b.Length -lt 512) { return $null }
    $pat = [System.Text.Encoding]::ASCII.GetBytes('-=[BAD SECTOR]=-'); $isBad = $true
    for ($i = 0; $i -lt 512; $i++) { if ($b[$i] -ne $pat[$i % 16]) { $isBad = $false; break } }
    if ($isBad) { return $null }
    $sum = 0
    for ($i = 0; $i -lt 512; $i += 2) { $sum = ($sum + 256 * [int]$b[$i] + [int]$b[$i + 1]) -band 0xFFFF }
    $bps = [int]$b[11] + 256 * [int]$b[12]; $total = [int]$b[19] + 256 * [int]$b[20]
    $spt = [int]$b[24] + 256 * [int]$b[25]; $heads = [int]$b[26] + 256 * [int]$b[27]
    return @{ Byte0 = [int]$b[0]; StSum = $sum; StPositive = ([int]$b[0] -eq 0x60 -or $sum -eq 0x1234); Sig = ([int]$b[510] -eq 0x55 -and [int]$b[511] -eq 0xAA)
              Bps = $bps; Total = $total; Spt = $spt; Heads = $heads
              Bpb = ($bps -eq 512 -and $spt -ge 1 -and $spt -le 63 -and $heads -ge 1 -and $heads -le 2 -and $total -gt 0) }
}

function Read-FileHead([string]$path, [int]$n = 512) {
    # Premiers octets d un fichier ; $null s il est illisible ou plus court
    try {
        $fs = [System.IO.File]::OpenRead($path)
        try { $b = New-Object byte[] $n; $got = $fs.Read($b, 0, $n) } finally { $fs.Dispose() }
        if ($got -lt $n) { return $null }
        return ,$b
    } catch { return $null }
}

function Get-IpfFormattedCyls([string]$path) {
    # Cylindres formates d un IPF : derniere piste IMGE ayant des blocs, plus un (Get-ImageCylinders compte aussi les
    # IMGE vides : 82 ou 84 pour un IPF de 80 cylindres formates, L2-DATA ecart 3) ; $null si illisible
    try {
        $d = [System.IO.File]::ReadAllBytes($path); $max = -1; $pos = 0
        while ($pos + 12 -le $d.Length) {
            $id = [System.Text.Encoding]::ASCII.GetString($d, $pos, 4); $ln = Get-BE32 $d ($pos + 4)
            if ($ln -lt 12) { break }
            if ($id -eq 'IMGE' -and $pos + 12 + 44 -le $d.Length) {
                $t = Get-BE32 $d ($pos + 12)
                if ((Get-BE32 $d ($pos + 12 + 40)) -gt 0 -and $t -gt $max -and $t -lt 200) { $max = $t }
            } elseif ($id -eq 'DATA' -and $pos + 16 -le $d.Length) { $ln += Get-BE32 $d ($pos + 12) }
            $pos += $ln
        }
        if ($max -ge 0) { return [int]($max + 1) }
    } catch { }
    return $null
}

function Get-RefImageFormat([string]$path) {
    # Format d une image de reference de la comparaison, sans disque (A1 § 4.2, decisions128, a5 § 2.3 et 4). Renvoie
    # Format ('' : inconnu), Cyls (cylindres de l image, $null si inconnus), Need ('decode' : IPF, SCP, HFE, a decoder
    # par gw sur les pistes 0.0 et 0.1 avec les candidats Cands, dans l ordre), HD, Why (texte du resultat) :
    #  - ADF : AmigaDOS toujours (un ADF ne represente que des pistes AmigaDOS ; signature DOS ou NDOS sans role), haute
    #    densite selon Test-AdfHd, cylindres d apres la taille (81 a 83 : la comparaison relit ces cylindres) ;
    #  - ST (atarist.*), IMG et IMA (ibm.*, puis atarist.* pour une face de 80 pistes, sans equivalent ibm.*) : BPB du
    #    secteur 0 si son total de secteurs fait la taille du fichier, sinon la taille seule ; un .st de 901 120 octets est
    #    un atarist.880 : l extension decide, a taille egale avec un ADF ;
    #  - IPF, SCP, HFE : densite (cellule IPF ou HFE, Test-ScpHighDensity pour un SCP), puis decodage par gw : AmigaDOS,
    #    puis les formats IBM du plus grand nombre de secteurs au plus petit (un decodeur fixe a 9 secteurs en trouve
    #    aussi 9 sur une piste de 10).
    $r = @{ Format = ''; Cyls = $null; Need = ''; HD = $false; Cands = @(); Why = '' }
    $ext = [System.IO.Path]::GetExtension($path).ToLower()
    try { $size = [long](Get-Item -LiteralPath $path -ErrorAction Stop).Length } catch { $r.Why = (T 'image de référence illisible'); return $r }
    $sz = Format-UiNum ([double]$size) '#,0'
    if ($ext -eq '.adf') {
        $r.HD = [bool](Test-AdfHd $path)
        $r.Format = $(if ($r.HD) { 'amiga.amigados_hd' } else { 'amiga.amigados' })
        $unit = $(if ($r.HD) { 22528 } else { 11264 })
        if ($size -gt 0 -and $size % $unit -eq 0) { $r.Cyls = [int]($size / $unit) }
        $r.Why = (T "référence {0} de {1} octets") -f 'ADF', $sz
        if ($null -ne $r.Cyls -and $r.Cyls -ne 80) { $r.Why += ((T ", {0} cylindres") -f "$($r.Cyls)") }
        return $r
    }
    if (@('.st', '.img', '.ima') -contains $ext) {
        $kind = $(if ($ext -eq '.st') { 'ST' } else { 'IMG' })
        $order = if ($ext -eq '.st') { @('atarist.720', 'atarist.800', 'atarist.880', 'atarist.360', 'atarist.400', 'atarist.440') }
                 else { @('ibm.720', 'ibm.1440', 'ibm.360', 'ibm.1200', 'ibm.800', 'ibm.1680', 'ibm.2880', 'ibm.180', 'ibm.160', 'ibm.320', 'atarist.360', 'atarist.400', 'atarist.440', 'atarist.880') }
        $bi = Get-BootSectorInfo (Read-FileHead $path 512)
        if ($bi -and $bi.Bpb -and [long]$bi.Total * 512 -eq $size -and $bi.Total % ($bi.Heads * $bi.Spt) -eq 0) {
            $c = [int]($bi.Total / ($bi.Heads * $bi.Spt))
            $f = Get-GeometryFormat $c $bi.Heads $bi.Spt $order
            if ($f) {
                $r.Format = $f; $r.Cyls = $c
                $r.Why = (T "référence {0} de {1} octets, BPB {2} x {3} x {4}") -f $kind, $sz, "$c", "$($bi.Heads)", "$($bi.Spt)"
                return $r
            }
        }
        $m = Get-SizeFormat $size $order
        if ($m) { $r.Format = $m.Format; $r.Cyls = $m.Cyls; $r.Why = (T "référence {0} de {1} octets") -f $kind, $sz; return $r }
        $r.Why = (T "référence {0} de {1} octets : taille et BPB non reconnus") -f $kind, $sz
        return $r
    }
    if (@('.ipf', '.scp', '.hfe') -contains $ext) {
        $r.Need = 'decode'
        try {
            if ($ext -eq '.ipf') { $r.HD = ([double](Get-IpfCellInfo $path).CellNs -lt 1500); $r.Cyls = Get-IpfFormattedCyls $path }
            elseif ($ext -eq '.hfe') { $r.HD = ([double](Get-HfeCellInfo $path).CellNs -lt 1500) }
            else { $r.HD = [bool](Test-ScpHighDensity $path) }
        } catch { }
        $r.Cands = $(if ($r.HD) { @('amiga.amigados_hd', 'ibm.1440') } else { @('amiga.amigados', 'atarist.880', 'atarist.800', 'ibm.720') })
        $r.Why = (T "référence {0} de {1} octets, décodée par gw sur les pistes 0.0 et 0.1") -f $ext.TrimStart('.').ToUpper(), $sz
        return $r
    }
    $r.Why = (T "extension {0} non prise en charge par la détection automatique") -f $ext
    return $r
}

function Get-GwTrackSectors($lines) {
    # Bilan par piste des lignes de gw (read ou convert avec un format) : « T0.0: IBM MFM (9/9 sectors) from Raw Flux
    # (...) », « T0.1: IBM Empty from ... », « T0.0: AmigaDOS (11/11 sectors) from ... » ; cle « cyl.tete » -> Mode, Found,
    # Total (derniere ligne de la piste). Ignorees : « Unknown mark », grille et bilan de print_summary, « Giving up »,
    # avertissements « Out of range », flux sans decodeur (faux gw : « T0.0: Raw Flux (...) »)
    $t = @{}
    foreach ($l in @($lines)) {
        $s = [string]$l
        if ($s -match '^T(\d+)\.(\d+)\b[^:]*:\s*(IBM MFM|IBM FM|IBM Empty|AmigaDOS)\b(?:\s*\((\d+)/(\d+) sectors\))?') {
            $f = 0; $n = 0
            if ($Matches[4]) { $f = [int]$Matches[4]; $n = [int]$Matches[5] }
            $t["$([int]$Matches[1]).$([int]$Matches[2])"] = @{ Mode = $Matches[3]; Found = $f; Total = $n }
        }
    }
    return $t
}

function New-DiskFormatResult([string]$kind, [string]$fmt, [string]$action, [string]$text, [string]$score, [string]$tail, [string]$name = '', [string]$why = '') {
    # Resultat de Select-DiskFormat ; Log : ligne de journal (scores des decodeurs, decision). FIX2 : Name (nom court du
    # format reconnu : ligne du cadre 1, ligne « Disquette » de la comparaison), Why (raison courte d une copie de flux ou
    # d un arret : etape 2, ligne du cadre 1), Score (scores des decodeurs) ; NeedBoot et BootFmt (D4 a faire, format de
    # decodage du secteur de demarrage), NeedProbe (D5 a faire : piste 0 vierge en restauration)
    return @{ Format = $fmt; Action = $action; Kind = $kind; Text = $text; Log = ((T "Détection du format : {0} ; {1}.") -f $score, $tail); NeedBoot = $false
              BootFmt = ''; NeedProbe = $false; Name = $name; Why = $why; Score = $score }
}

function Get-UnknownFormatResult([bool]$hd, [string]$why, [string]$score) {
    # Format inconnu (A1 § 3.4) : copie exacte du flux en double densite ; arret en haute densite, une copie de flux haute
    # densite ne pouvant pas etre controlee (regle de la 12.7, Complete-RestoreRead)
    if ($hd) {
        return New-DiskFormatResult 'unknown' '' 'stop' ((T "format haute densité non reconnu ({0}) : une copie de flux ne pourrait pas être contrôlée. Si vous connaissez le format, choisissez-le dans la liste.") -f $why) $score (T 'format haute densité non reconnu, arrêt avant toute écriture') '' (T 'format haute densité non reconnu')
    }
    return New-DiskFormatResult 'unknown' '' 'flux' ((T "Format non reconnu ({0}) : copie exacte du flux, sans comparaison par secteur.") -f $why) $score (T 'format non reconnu, copie exacte du flux') '' (T 'format non reconnu')
}

function Select-DiskFormat($m) {
    # Fonction pure (A1 § 3.3 et 3.4, decisions128, D12). $m : D0 (lignes de gw de la lecture ibm.scan --raw des pistes
    # 0.0 et 0.1), D2 (lignes du decodage Amiga hors ligne de ce flux), AmigaFmt (format de D2), HD (densite du flux,
    # Test-ScpHighDensity), Tracks et Crit (pistes du flux et pistes critiques, Get-TrackMetrics), Boot (secteur 0 de la
    # piste 0.0 decode en ibm.720 par D4, ou $null) et BootDone (D4 faite, meme sans secteur). Regles, dans l ordre :
    #  1. aucun secteur, et toutes les pistes du flux critiques (ou aucune piste) : disquette vierge, absente ou tetes
    #     sales -> arret ;
    #  2. D3 : un decodeur est retenu s il donne une piste complete et au moins deux fois plus de secteurs valides que
    #     l autre (AmigaDOS contre IBM) ; sinon format inconnu (ambiguite) ;
    #  3. AmigaDOS : format de D2. Une piste incomplete, en double densite : protection contre la copie probable -> copie
    #     exacte du flux d office (D12, mode automatique), sans lecture secteur qui echouerait sur les pistes protegees ;
    #  4. IBM : codage MFM et meme nombre de secteurs sur les deux faces, sinon inconnu (FM, une seule face lisible).
    #     9 secteurs en double densite : « Atari ST » sur critere positif seulement (octet 0 = 0x60, BRA.S du 68000, ou
    #     somme des 256 mots big-endian du secteur de demarrage = 0x1234 : atarist.720) ; sinon « 9 secteurs de 512 octets,
    #     format PC » (ibm.720 ; ibm.360 si le BPB annonce 720 secteurs sur 2 faces), sans affirmer la machine d origine :
    #     0x55AA ne joue aucun role (images ST de mtools) et les donnees sont les memes. 10 et 11 secteurs en double
    #     densite : atarist.800 et atarist.880 ; 18 en haute densite : ibm.1440 ; autre nombre : inconnu. Piste incomplete
    #     en double densite : protection probable, copie exacte du flux ;
    #  5. format inconnu : copie exacte du flux en double densite, arret en haute densite.
    # FIX2 (relecture adverse du lot 2) :
    #  - regle 1, restauration en double densite ($m.CanProbe) : avant de conclure a une disquette vierge, D5 lit trois
    #    cylindres de plus (1, 40, 79 ; Lemmings disque 2 : piste 0 non formatee). Donnees sur l un d eux ($m.ProbeData) :
    #    piste 0 non formatee, protection probable, copie exacte du flux ; sinon arret ;
    #  - regle 4 : D4 pour tout format IBM retenu (9, 10, 11 secteurs en double densite, 18 en haute densite), avec ce
    #    format ($res.BootFmt). Un BPB plausible qui annonce plus de secteurs que le format n en lit (disquette de 81 a 83
    #    cylindres) : copie exacte du flux en double densite, arret en haute densite (gw ne lit que les cylindres du format :
    #    une copie secteur les perdrait) ; ibm.360 seulement si le champ Pistes contient step=2 ($m.Step2), sinon ibm.720
    #    (lecture des 80 cylindres, sans perte).
    # Renvoie Format ('' : aucun ; format reconnu d une disquette protegee), Action (sector : lecture secteur ; flux :
    # copie exacte du flux ; stop : arret avant toute ecriture), Kind (amiga, pc, st, protect, extended, unknown, blank),
    # Text (rapport, infobulle du cadre 1, raison d un arret), Log (journal : scores de chaque decodeur et decision), Name,
    # Why, Score, NeedBoot (D4 pas encore faite : nouvel appel avec Boot et BootDone), NeedProbe (D5 pas encore faite :
    # nouvel appel avec ProbeDone, ProbeData, ProbeTracks).
    $ibm = Get-GwTrackSectors $m.D0
    $ami = Get-GwTrackSectors $m.D2
    $af = $(if ($m.AmigaFmt) { [string]$m.AmigaFmt } else { 'amiga.amigados' })
    $hd = [bool]$m.HD
    $nAmi = 0; $nAmiT = 0; $nIbm = 0; $aFull = 0; $iFull = 0; $aInc = @(); $parts = @()
    foreach ($k in @('0.0', '0.1')) {
        $a = $ami[$k]
        if ($a -and $a.Mode -eq 'AmigaDOS' -and $a.Total -gt 0) {
            $nAmi += $a.Found; $nAmiT += $a.Total
            if ($a.Found -eq $a.Total) { $aFull++ } else { $aInc += $k }
        } else { $aInc += $k }
        $b = $ibm[$k]
        if ($b -and $b.Total -gt 0 -and ($b.Mode -eq 'IBM MFM' -or $b.Mode -eq 'IBM FM')) {
            $nIbm += $b.Found
            if ($b.Found -eq $b.Total) { $iFull++ }
            $parts += "$($b.Mode) $($b.Found)/$($b.Total)"
        } else { $parts += (T 'vide') }
    }
    if ($nAmiT -eq 0) { $nAmiT = 2 * [int](Get-FormatGeometry $af).Spt }
    $score = (T "AmigaDOS {0}/{1}, IBM {2} (pistes 0.0 et 0.1 : {3})") -f "$nAmi", "$nAmiT", "$nIbm", ($parts -join ', ')
    if ($nAmi -eq 0 -and $nIbm -eq 0) {
        if ([int]$m.Tracks -le 0 -or [int]$m.Crit -ge [int]$m.Tracks) {
            $tail = (T "aucun secteur, {0} piste(s) critique(s) sur {1} dans le flux") -f "$([int]$m.Crit)", "$([int]$m.Tracks)"
            if ($m.CanProbe -and -not $hd -and [int]$m.Tracks -gt 0) {
                # FIX2 : piste 0 vierge en double densite (restauration) : D5, trois cylindres de plus, avant de conclure
                if (-not $m.ProbeDone) { $res = New-DiskFormatResult 'blank' '' '' '' $score ''; $res.NeedProbe = $true; return $res }
                if ([int]$m.ProbeData -gt 0) {
                    return New-DiskFormatResult 'protect' '' 'flux' ((T "Piste 0 sans donnée lisible, mais données sur {0} des {1} pistes sondées (cylindres 1, 40 et 79) : piste 0 non formatée, protection contre la copie probable. Copie exacte du flux, sans comparaison par secteur.") -f "$([int]$m.ProbeData)", "$([int]$m.ProbeTracks)") $score ((T "{0} ; données sur {1} des {2} pistes sondées : piste 0 non formatée, copie exacte du flux") -f $tail, "$([int]$m.ProbeData)", "$([int]$m.ProbeTracks)") '' (T 'piste 0 non formatée')
                }
                $tail += ' ; ' + ((T "aucune donnée sur les {0} pistes sondées (cylindres 1, 40 et 79)") -f "$([int]$m.ProbeTracks)")
            }
            return New-DiskFormatResult 'blank' '' 'stop' (T 'aucune donnée lisible : disquette vierge, absente ou têtes sales') $score $tail '' (T 'aucune donnée lisible')
        }
        return Get-UnknownFormatResult $hd (T 'aucun secteur reconnu') $score
    }
    if ($nAmi -gt 0 -and $aFull -ge 1 -and $nAmi -ge 2 * $nIbm) {
        $name = $(if ($af -eq 'amiga.amigados_hd') { (T "Amiga haute densité ({0})") -f $af } else { (T "Amiga double densité ({0})") -f $af })
        $short = $(if ($af -eq 'amiga.amigados_hd') { (T 'Amiga haute densité') } else { (T 'Amiga double densité') })
        $lab = (T "{0}, {1}/{2} secteurs") -f $name, "$nAmi", "$nAmiT"
        if ($aInc.Count -gt 0 -and -not $hd) {
            $k = $aInc[0]; $x = $ami[$k]
            $fx = $(if ($x) { [int]$x.Found } else { 0 }); $tx = $(if ($x -and $x.Total -gt 0) { [int]$x.Total } else { [int](Get-FormatGeometry $af).Spt })
            $res = New-DiskFormatResult 'protect' $af 'flux' ((T "{0} : piste {1} incomplète ({2}/{3} secteurs), protection contre la copie probable. Copie exacte du flux, sans comparaison par secteur.") -f $name, $k, "$fx", "$tx") $score ((T "protection contre la copie probable (piste {0} incomplète), copie exacte du flux") -f $k) $short (T 'protection contre la copie probable')
            return $res
        }
        return New-DiskFormatResult 'amiga' $af 'sector' $lab $score ((T "format retenu : {0}") -f $af) $short
    }
    if ($nIbm -gt 0 -and $iFull -ge 1 -and $nIbm -ge 2 * $nAmi) {
        $t0 = $ibm['0.0']; $t1 = $ibm['0.1']
        if (($t0 -and $t0.Mode -eq 'IBM FM') -or ($t1 -and $t1.Mode -eq 'IBM FM')) { return Get-UnknownFormatResult $hd (T 'codage FM') $score }
        $n0 = $(if ($t0 -and $t0.Mode -eq 'IBM MFM') { [int]$t0.Total } else { 0 }); $n1 = $(if ($t1 -and $t1.Mode -eq 'IBM MFM') { [int]$t1.Total } else { 0 })
        if ($n0 -ne $n1 -or $n0 -eq 0) { return Get-UnknownFormatResult $hd ((T "{0} et {1} secteurs sur les deux faces") -f "$n0", "$n1") $score }
        $spt = $n0; $fmt = ''; $kind = 'pc'; $bootTxt = ''; $note = ''
        # FIX2 : D4 pour tout format IBM retenu, decode avec ce format (9 secteurs : ibm.720, memes secteurs qu atarist.720)
        $bootFmt = $(if (-not $hd -and $spt -eq 9) { 'ibm.720' } elseif (-not $hd -and $spt -eq 10) { 'atarist.800' } elseif (-not $hd -and $spt -eq 11) { 'atarist.880' } elseif ($hd -and $spt -eq 18) { 'ibm.1440' } else { '' })
        if (-not $bootFmt) { return Get-UnknownFormatResult $hd ((T "{0} secteurs par piste") -f "$spt") $score }
        if ($null -eq $m.Boot -and -not $m.BootDone) { $res = New-DiskFormatResult 'pc' '' '' '' $score ''; $res.NeedBoot = $true; $res.BootFmt = $bootFmt; return $res }
        $bi = Get-BootSectorInfo $m.Boot
        if ($bi) { $bootTxt = ' (' + ((T "secteur de démarrage : octet 0 = 0x{0:X2}, somme des mots 0x{1:X4}") -f $bi.Byte0, $bi.StSum) + ')' }
        if ($spt -eq 9 -and -not $hd) {
            if ($bi -and $bi.StPositive) { $fmt = 'atarist.720'; $kind = 'st' }
            elseif ($bi -and $bi.Bpb -and $bi.Total -eq 720 -and $bi.Heads -eq 2 -and $bi.Spt -eq 9) {
                if ($m.Step2) { $fmt = 'ibm.360' }
                else {
                    # FIX2 : sans step=2, ibm.360 ne lirait que les cylindres 0 a 39 ; ibm.720 lit les 80 (rien de perdu)
                    $fmt = 'ibm.720'
                    $note = ' ' + (T "Le secteur de démarrage annonce 40 cylindres : pour une disquette 5,25 pouces de 40 pistes dans un lecteur de 80 pistes, indiquez step=2 dans le champ Pistes de l'onglet Écriture.")
                }
            }
            else { $fmt = 'ibm.720' }
        }
        elseif ($spt -eq 18) { $fmt = 'ibm.1440' }
        else { $fmt = $bootFmt; $kind = 'st' }
        $name = $(if ($kind -eq 'st') { (T "Atari ST, {0} secteurs de 512 octets ({1})") -f "$spt", $fmt } else { (T "{0} secteurs de 512 octets, format PC ({1})") -f "$spt", $fmt })
        $short = $(if ($kind -eq 'st') { (T "Atari ST, {0} secteurs") -f "$spt" } else { (T "PC, {0} secteurs") -f "$spt" })
        $inc = @(@('0.0', '0.1') | Where-Object { $ibm[$_].Found -lt $ibm[$_].Total })
        if ($inc.Count -gt 0 -and -not $hd) {
            $k = $inc[0]
            return New-DiskFormatResult 'protect' $fmt 'flux' ((T "{0} : piste {1} incomplète ({2}/{3} secteurs), protection contre la copie probable. Copie exacte du flux, sans comparaison par secteur.") -f $name, $k, "$($ibm[$k].Found)", "$($ibm[$k].Total)") $score ((T "protection contre la copie probable (piste {0} incomplète), copie exacte du flux") -f $k) $short (T 'protection contre la copie probable')
        }
        # FIX2 : BPB plausible qui annonce plus de secteurs que le format n en lit : gw ne lirait que les cylindres du format
        $g = Get-FormatGeometry $fmt
        if ($bi -and $bi.Bpb -and $g -and [int]$bi.Total -gt $g.Cyls * $g.Heads * $g.Spt) {
            $bc = [int][math]::Ceiling([int]$bi.Total / ([int]$bi.Heads * [int]$bi.Spt))
            $why = (T "le secteur de démarrage annonce {0} secteurs ({1} cylindres de {2} face(s) et {3} secteurs), le format {4} n'en lit que {5} ({6} cylindres)") -f "$($bi.Total)", "$bc", "$($bi.Heads)", "$($bi.Spt)", $fmt, "$($g.Cyls * $g.Heads * $g.Spt)", "$($g.Cyls)"
            if ($hd) {
                return New-DiskFormatResult 'extended' $fmt 'stop' ((T "{0} : {1} ; une copie de flux haute densité ne pourrait pas être contrôlée : arrêt avant toute écriture.") -f $name, $why) $score (((T "format haute densité étendu ({0} cylindres annoncés), arrêt avant toute écriture") -f "$bc") + $bootTxt) $short (T 'format haute densité étendu')
            }
            return New-DiskFormatResult 'extended' $fmt 'flux' ((T "{0} : {1}. Copie exacte du flux, sans comparaison par secteur.") -f $name, $why) $score (((T "format étendu ({0} cylindres annoncés), copie exacte du flux") -f "$bc") + $bootTxt) $short (T 'format étendu au-delà de ses cylindres')
        }
        return New-DiskFormatResult $kind $fmt 'sector' (((T "{0}, {1}/{2} secteurs") -f $name, "$nIbm", "$(2 * $spt)") + $note) $score (((T "format retenu : {0}") -f $fmt) + $bootTxt) $short
    }
    return Get-UnknownFormatResult $hd ((T "ambiguïté : AmigaDOS {0}, IBM {1}") -f "$nAmi", "$nIbm") $score
}

function Select-RefDecodeFormat($results) {
    # Fonction pure (A1 § 4.2, regle de D3) : format d une image IPF, SCP ou HFE d apres le decodage de ses pistes 0.0 et
    # 0.1 par chaque candidat ($results : Fmt, Lines, dans l ordre d essai). Le premier candidat dont les deux pistes sont
    # completes ; sinon celui qui a une piste complete et au moins deux fois plus de secteurs que le second (pistes
    # incompletes : protection probable, signalee) ; sinon inconnu. Renvoie Format ('' : inconnu), Found, Total, Inc
    # (pistes incompletes), Text
    $rows = @()
    foreach ($x in @($results)) {
        if (-not $x) { continue }
        $t = Get-GwTrackSectors $x.Lines; $f = 0; $n = 0; $full = 0; $inc = @()
        foreach ($k in @('0.0', '0.1')) {
            $e = $t[$k]
            if ($e -and $e.Total -gt 0 -and $e.Mode -ne 'IBM Empty') { $f += $e.Found; $n += $e.Total; if ($e.Found -eq $e.Total) { $full++ } else { $inc += $k } }
            else { $inc += $k }
        }
        $rows += ,@{ Fmt = [string]$x.Fmt; Found = $f; Total = $n; Full = $full; Inc = $inc }
    }
    $pick = $null
    foreach ($w in $rows) { if ($w.Full -eq 2) { $pick = $w; break } }
    if (-not $pick -and $rows.Count -gt 0) {
        $s = @($rows | Sort-Object -Property @{ Expression = { [int]$_.Found }; Descending = $true })
        $second = $(if ($s.Count -gt 1) { [int]$s[1].Found } else { 0 })
        if ($s[0].Found -gt 0 -and $s[0].Full -ge 1 -and $s[0].Found -ge 2 * $second) { $pick = $s[0] }
    }
    if (-not $pick) {
        $best = @($rows | ForEach-Object { "$($_.Fmt) $($_.Found)/$($_.Total)" }) -join ', '
        return @{ Format = ''; Found = 0; Total = 0; Inc = @(); Text = ((T "aucun format reconnu sur les pistes 0.0 et 0.1 ({0})") -f $best) }
    }
    $txt = (T "{0}/{1} secteurs sur les pistes 0.0 et 0.1") -f "$($pick.Found)", "$($pick.Total)"
    # FIX2 : les secteurs manquants de ces pistes portent le motif « secteur illisible » de gw dans la reference convertie ;
    # Compare-Images les signale comme non compares (et non plus « la comparaison signalera ces pistes »)
    if (@($pick.Inc).Count -gt 0) { $txt += ' ; ' + ((T "piste(s) {0} incomplète(s) : protection contre la copie probable, ces pistes ne peuvent pas être comparées au format {1}") -f ($pick.Inc -join ', '), $pick.Fmt) }
    return @{ Format = $pick.Fmt; Found = $pick.Found; Total = $pick.Total; Inc = $pick.Inc; Text = $txt }
}

function Get-FmtDetectInput($d) {
    # Entree de Select-DiskFormat d apres l etat de la detection en cours ($script:FmtDetect). FIX2 : sonde D5 en
    # restauration seulement (CanProbe), step=2 dans la geometrie du champ Pistes (Step2)
    return @{ D0 = $d.D0; D2 = $d.D2; AmigaFmt = $d.AmigaFmt; HD = $d.HD; Tracks = $d.Tracks; Crit = $d.Crit; Boot = $d.BootBytes; BootDone = $d.BootDone
              CanProbe = ($d.Owner -eq 'restore'); ProbeDone = $d.ProbeDone; ProbeData = $d.ProbeData; ProbeTracks = $d.ProbeTracks
              Step2 = [bool](":$($d.Extras)" -match ':\s*step\s*=\s*2\s*(:|$)') }
}

function Invoke-DiskFormatDetect([string]$owner, [string]$extras = '') {
    # Detection du format de la disquette inseree (A1 § 3.3), pour la restauration ($owner 'restore') ou la comparaison
    # ('compare'). D0 : une seule lecture physique, ibm.scan --raw sur les pistes 0.0 et 0.1, 2 tours (un secteur a
    # cheval sur l index se decode sur deux tours), sans nouvel essai, avec les options de lecteur (Get-DriveReadArgs, D8)
    # et la geometrie du champ Pistes ($extras : step, hswap). Etapes suivantes dans $script:Chain, lancees par le
    # minuteur a la fin de gw (code 0) : Step-FmtDetectFlux, Step-FmtDetectAmiga, Step-FmtDetectBoot ou (FIX2)
    # Start-FmtDetectProbe et Step-FmtDetectProbe ; fin par
    # Complete-DiskFormatDetect. Erreur de gw : chemin commun de la chaine (restauration arretee, comparaison en echec)
    if (-not (Test-Path -LiteralPath $script:TempDir)) { New-Item -ItemType Directory -Force -Path $script:TempDir | Out-Null }
    $base = Join-Path $script:TempDir ('detect-' + (Get-Date -Format 'yyyyMMdd-HHmmss'))
    $script:FmtDetect = @{ Owner = $owner; Scp = "$base.scp"; Adf = "$base-amiga.adf"; BootImg = "$base-boot.img"; D0 = @(); D2 = @()
                           AmigaFmt = 'amiga.amigados'; HD = $false; Tracks = 0; Crit = 0; BootBytes = $null; BootDone = $false
                           Extras = $extras; ProbeScp = "$base-sonde.scp"; ProbeDone = $false; ProbeData = 0; ProbeTracks = 0 }
    $script:FmtDetectArgs = @('read') + (Get-CommonArgs) + @(Get-DriveReadArgs) + @('--format=ibm.scan', '--raw', '--revs=2', '--retries=0', "--tracks=c=0:h=0-1$extras", "`"$($script:FmtDetect.Scp)`"")
    $script:GwCapture = New-Object System.Collections.Generic.List[string]
    $script:Chain.Clear()
    $script:Chain.Enqueue({ Start-Gw $script:FmtDetectArgs })
    $script:Chain.Enqueue({ Step-FmtDetectFlux })
    Invoke-NextChainStep
}

function Step-FmtDetectFlux {
    # Apres D0 : lignes de gw ; D1 : densite et pistes critiques du flux (jugees aux seuils Standard, comme un original
    # en copie de flux) ; puis D2 : decodage AmigaDOS hors ligne du meme flux (double ou haute densite selon D1)
    $d = $script:FmtDetect
    if (-not $d) { return }
    $d.D0 = @(if ($script:GwCapture) { @($script:GwCapture) } else { @() }); $script:GwCapture = $null
    if (-not (Test-Path -LiteralPath $d.Scp) -or (Get-Item -LiteralPath $d.Scp).Length -eq 0) {
        Complete-DiskFormatDetect (New-DiskFormatResult 'nofile' '' 'stop' (T 'la lecture n''a produit aucun fichier (disquette absente ou lecteur incorrect ?)') (T 'pistes 0.0 et 0.1') (T 'aucun flux lu'))
        return
    }
    if ($script:ScpStatsOk) {
        try { $d.HD = [bool](Test-ScpHighDensity $d.Scp) } catch { $d.HD = $false }
        try {
            # 12.8.2 : lecture avec --fake-index (options de lecteur, Get-DriveReadArgs) : index simule, zone de l index comptee
            $t = Read-ScpFile $d.Scp -NoIndexZone:(@($script:FmtDetectArgs | Where-Object { "$_" -match '^--fake-index=' }).Count -gt 0)
            foreach ($tn in @($t.Keys)) {
                $mm = Get-TrackMetrics $t[$tn]; $d.Tracks++
                $lv = if ($mm.Bad) { 2 } else { Get-HealthLevel $mm.Ooc $mm.Dr $mm.Stab $mm.J $script:JitterStdOk $script:JitterStdWatch }
                if ($lv -ge 2) { $d.Crit++ }
            }
        } catch { }
    }
    $d.AmigaFmt = $(if ($d.HD) { 'amiga.amigados_hd' } else { 'amiga.amigados' })
    $script:FmtDetectArgs = @('convert', "--format=$($d.AmigaFmt)", '--tracks=c=0:h=0-1', "`"$($d.Scp)`"", "`"$($d.Adf)`"")
    $script:GwCapture = New-Object System.Collections.Generic.List[string]
    $script:Chain.Enqueue({ Start-Gw $script:FmtDetectArgs })
    $script:Chain.Enqueue({ Step-FmtDetectAmiga })
    Invoke-NextChainStep
}

function Step-FmtDetectAmiga {
    # Apres D2 : decision ; format IBM : D4, secteur 0 de la piste 0.0 decode hors ligne avec le format retenu (FIX2 :
    # BootFmt ; 9, 10, 11 et 18 secteurs) ; piste 0 vierge en restauration double densite : D5 (FIX2)
    $d = $script:FmtDetect
    if (-not $d) { return }
    $d.D2 = @(if ($script:GwCapture) { @($script:GwCapture) } else { @() }); $script:GwCapture = $null
    $res = Select-DiskFormat (Get-FmtDetectInput $d)
    if ($res.NeedProbe) { Start-FmtDetectProbe; return }
    if (-not $res.NeedBoot) { Complete-DiskFormatDetect $res; return }
    $script:FmtDetectArgs = @('convert', "--format=$($res.BootFmt)", '--tracks=c=0:h=0', "`"$($d.Scp)`"", "`"$($d.BootImg)`"")
    $script:Chain.Enqueue({ Start-Gw $script:FmtDetectArgs })
    $script:Chain.Enqueue({ Step-FmtDetectBoot })
    Invoke-NextChainStep
}

function Start-FmtDetectProbe {
    # FIX2 (D5) : piste 0 sans donnee lisible en double densite (restauration) : lecture du flux de trois cylindres de plus
    # (1, 40 et 79, 2 tours, options et geometrie du lecteur comme D0) avant de conclure a une disquette vierge : une piste
    # 0 non formatee est une protection (Lemmings disque 2 d apres l IPF SPS)
    $d = $script:FmtDetect
    if (-not $d) { return }
    $script:FmtDetectArgs = @('read') + (Get-CommonArgs) + @(Get-DriveReadArgs) + @('--revs=2', "--tracks=c=1,40,79:h=0-1$($d.Extras)", "`"$($d.ProbeScp)`"")
    $script:Chain.Enqueue({ Start-Gw $script:FmtDetectArgs })
    $script:Chain.Enqueue({ Step-FmtDetectProbe })
    Invoke-NextChainStep
}

function Step-FmtDetectProbe {
    # Apres D5 : pistes avec des donnees (ni vierges ni critiques aux seuils Standard, comme D1), puis decision
    $d = $script:FmtDetect
    if (-not $d) { return }
    $d.ProbeDone = $true
    if ((Test-Path -LiteralPath $d.ProbeScp) -and $script:ScpStatsOk) {
        try {
            $t = Read-ScpFile $d.ProbeScp -NoIndexZone:(@($script:FmtDetectArgs | Where-Object { "$_" -match '^--fake-index=' }).Count -gt 0)
            foreach ($tn in @($t.Keys)) {
                $mm = Get-TrackMetrics $t[$tn]; $d.ProbeTracks++
                $lv = if ($mm.Bad) { 2 } else { Get-HealthLevel $mm.Ooc $mm.Dr $mm.Stab $mm.J $script:JitterStdOk $script:JitterStdWatch }
                if ($lv -lt 2) { $d.ProbeData++ }
            }
        } catch { }
    }
    Complete-DiskFormatDetect (Select-DiskFormat (Get-FmtDetectInput $d))
}

function Step-FmtDetectBoot {
    # Apres D4 : secteur de demarrage (absent ou non lu : aucun critere positif Atari ST, format PC), puis decision
    $d = $script:FmtDetect
    if (-not $d) { return }
    $d.BootDone = $true
    if (Test-Path -LiteralPath $d.BootImg) { $d.BootBytes = Read-FileHead $d.BootImg 512 }
    Complete-DiskFormatDetect (Select-DiskFormat (Get-FmtDetectInput $d))
}

function Complete-DiskFormatDetect($res) {
    # Fin de la detection : ligne de journal (scores, decision), puis suite de la restauration ou de la comparaison
    $d = $script:FmtDetect; $script:FmtDetect = $null
    if (-not $d) { return }
    if ($res.Log) { Append-Log $res.Log }
    switch ($d.Owner) {
        'restore' { Complete-RestoreDetection $res }
        'compare' { Complete-CompareDetect $res }
    }
}
# ============================== FONCTIONS : QUALITE ET ALIGNEMENT ==============

# ============================== ALIGNEMENT : LOGIQUE ===========================
function Read-ScpFile([string]$path, [int]$cellsPerRev = 0, [switch]$Finger, [switch]$NoIndexZone) {
    # cellsPerRev > 0 : motif de test connu (calibration) ; la cellule vaut alors duree du tour / nombre de cellules,
    # au lieu de la mediane des intervalles de deux cellules, qui derive quand le decalage residuel est grand.
    # 12.8.2 (S10 a S12) : hors calibration, post-traitement de chaque piste (Set-ScpTrackPost) : premier intervalle de
    # la lecture et zone de l index non comptes, stabilite sur tours alignes ; la calibration (cellsPerRev > 0) garde
    # le comptage d avant (courbes inchangees). -NoIndexZone : index synthetique connu de l appelant (--fake-index) :
    # zone de l index comptee comme le reste de la piste ; de meme pour un SCP non cale sur l index (en-tete, bit 0 des
    # drapeaux, comme gw : image/scp.py) et pour des tours plus courts qu une rotation (secteurs durs lus comme des
    # index : Set-ScpTrackPost, ScpIdxMinRevNs). Revue 12.8.2 : echec du post-traitement d une piste (comptage d avant
    # pour cette piste) : une ligne de journal par fichier, avec le premier message.
    $d = [System.IO.File]::ReadAllBytes($path)
    if ([System.Text.Encoding]::ASCII.GetString($d, 0, 3) -ne 'SCP') { throw (T 'Fichier SCP invalide') }
    $revs = $d[5]; $res = ($d[11] + 1) * 25
    $zone = (-not $NoIndexZone) -and ((($d[8] -band 1) -eq 1) -or $revs -eq 1)
    $script:ScpPostFail = @{ N = 0; Msg = '' }
    $tracks = @{}
    for ($t = 0; $t -lt 168; $t++) {
        $o = [BitConverter]::ToUInt32($d, 16 + 4 * $t)
        if ($o -eq 0) { continue }
        $tn = $d[$o + 3]; $list = @()
        $fl = New-Object 'System.Collections.Generic.List[int[]]'
        for ($r = 0; $r -lt $revs; $r++) {
            $idx  = [BitConverter]::ToUInt32($d, $o + 4 + 12 * $r)
            $ln   = [BitConverter]::ToUInt32($d, $o + 8 + 12 * $r)
            $doff = [BitConverter]::ToUInt32($d, $o + 12 + 12 * $r)
            $flux = [ScpStats]::Decode($d, [int]($o + $doff), [int]$ln, $res)
            $fl.Add($flux)
            $list += [ScpStats]::Analyze($flux, [double]$idx * $res, $cellsPerRev)
        }
        # Stabilite d un tour a l autre (zones instables : bits faibles d une protection, defaut localise) et, sur
        # demande, empreinte de la piste ; pas pour la calibration (motif connu, une passe par valeur de precomp)
        # Double densite seulement (cellule de 1,7 a 2,3 us, long tracks compris) : en haute densite, la cellule estimee
        # sur les intervalles de 3 a 5 us est fausse et les classes aussi
        if ($cellsPerRev -le 0 -and $list.Count -gt 0 -and -not [double]::IsNaN($list[0].Cell) -and $list[0].Cell -ge 1700 -and $list[0].Cell -le 2300) {
            $ins = [ScpStats]::Instability($fl, [double]$list[0].Cell)
            $list[0].Blocks = $ins[0]; $list[0].Unstable = $ins[1]; $list[0].MaxRun = $ins[2]; $list[0].RunPos = $ins[3]
            if ($Finger) { $list[0].Finger = [ScpStats]::Fingerprint($fl[0], [double]$list[0].Cell, 8); $list[0].Rich = [ScpStats]::RichCount($fl[0], [double]$list[0].Cell) }
        }
        if ($cellsPerRev -le 0 -and $list.Count -gt 0) { Set-ScpTrackPost $fl $list $zone }
        $tracks[[int]$tn] = $list
    }
    if ($script:ScpPostFail.N -gt 0) {
        Append-Log ((T "Analyse SCP : calcul 12.8.2 des erreurs et de la stabilité en échec sur {0} piste(s), jugée(s) comme dans les versions précédentes : {1}") -f "$($script:ScpPostFail.N)", "$($script:ScpPostFail.Msg)")
    }
    return $tracks
}

function Read-ScpTrackFlux([string]$path, [int]$tn) {
    # Flux brut de chaque tour d une piste d un SCP (sonde de la restauration en flux)
    $d = [System.IO.File]::ReadAllBytes($path)
    if ([System.Text.Encoding]::ASCII.GetString($d, 0, 3) -ne 'SCP') { throw (T 'Fichier SCP invalide') }
    $revs = $d[5]; $res = ($d[11] + 1) * 25
    $fl = New-Object 'System.Collections.Generic.List[int[]]'
    if ($tn -lt 0 -or $tn -ge 168) { return ,$fl }
    $o = [BitConverter]::ToUInt32($d, 16 + 4 * $tn)
    if ($o -eq 0) { return ,$fl }
    for ($r = 0; $r -lt $revs; $r++) {
        $ln   = [BitConverter]::ToUInt32($d, $o + 8 + 12 * $r)
        $doff = [BitConverter]::ToUInt32($d, $o + 12 + 12 * $r)
        $fl.Add([ScpStats]::Decode($d, [int]($o + $doff), [int]$ln, $res))
    }
    return ,$fl
}

# --- 12.8.2 (S10 a S12) : premier intervalle, zone de l index, stabilite sur tours alignes ----------------------------
# Post-traitement en PowerShell des tours lus par Read-ScpFile (le C# de 030 n est pas modifie) : classes des seuls
# segments utiles (ScpStats.Classes, meme regle que Analyze), sommes de flux en code natif (Linq), aucune boucle
# PowerShell sur tous les intervalles d une piste. Constantes : 040 (ScpIdxZoneNs, ScpIdxMinRevNs, ScpPostWin,
# ScpRevWin, ScpZoneWin, ScpAnchor).
function Get-ScpClassText($flux, [int]$start, [int]$len, [double]$cell, [int]$start2 = 0, [int]$len2 = 0) {
    # Classes de $flux[$start .. $start + $len - 1], suivies de celles de $flux[$start2 .. $start2 + $len2 - 1] : '2' a
    # '5', 'x' hors classe ou trou (ScpStats.Classes, une seule fois pour les deux segments)
    if ($len2 -le 0 -and $start -eq 0 -and $len -eq $flux.Length) { return [ScpStats]::Classes($flux, $cell) }
    $seg = [int[]]::new($len + [math]::Max(0, $len2))
    [Array]::Copy($flux, $start, $seg, 0, $len)
    if ($len2 -gt 0) { [Array]::Copy($flux, $start2, $seg, $len, $len2) }
    return [ScpStats]::Classes($seg, $cell)
}

function Get-ScpEdgeClasses($f, [double]$cell, [int]$k) {
    # Classes des $k premiers et des $k derniers intervalles d un tour : @(debut, fin, indice du premier intervalle de la
    # fin, tour entier). Tour entier si le tour est court, ou si les ScpZoneWin intervalles d un bout ($k >= ScpZoneWin)
    # durent moins de ScpIdxZoneNs (intervalles tres courts : la zone de l index doit etre couverte)
    $n = $f.Length; $zw = [int]$script:ScpZoneWin
    if ($n -le 2 * $k -or [System.Linq.Enumerable]::Sum([System.ArraySegment[int]]::new($f, 0, $zw)) -lt $script:ScpIdxZoneNs -or
        [System.Linq.Enumerable]::Sum([System.ArraySegment[int]]::new($f, $n - $zw + 1, $zw - 1)) -lt $script:ScpIdxZoneNs) {
        $s = Get-ScpClassText $f 0 $n $cell
        return @($s, $s, 0, $true)
    }
    $s = Get-ScpClassText $f 0 $k $cell ($n - $k) $k
    return @($s.Substring(0, $k), $s.Substring($k), ($n - $k), $false)
}

function Get-ScpZoneOoc($f, [string]$hs, [string]$ts, [int]$to, [int]$first) {
    # S11 : intervalles hors classe (pas les trous) qui commencent a moins de ScpIdxZoneNs de l index (debut du tour, a
    # partir de l intervalle $first) ou qui finissent a moins de ScpIdxZoneNs de l index suivant (fin du tour : apres
    # T - ScpIdxZoneNs). $hs : classes du debut du tour, $ts : de la fin, dont le premier intervalle a l indice $to.
    # Revue 12.8.2 : par bout, ecartes seulement s ils forment une seule grappe (raccord d ecriture) : ScpIdxClusterMax
    # intervalles au plus, du debut du premier a la fin du dernier en ScpIdxClusterNs au plus ; sinon aucun (defaut du
    # support a l index : compte). Verification du 27/10/2026 : une grappe qui se prolonge au-dela de la zone (hors classe
    # hors zone a ScpIdxClusterNs au plus de la fin de la grappe) fait compter le bout ; grappes aux deux bouts du tour (de
    # part et d autre de l index) : ScpIdxClusterMax intervalles au plus au total et distances a l index (bout le plus
    # lointain de chaque grappe) de ScpIdxClusterNs au plus en somme, sinon les deux bouts sont comptes. Rend @(hors classe
    # ecartes, distance a l index du bout le plus lointain d une grappe ecartee, en ns). Seuls les intervalles hors classe
    # sont visites, et pas au-dela d une grappe impossible ni de ScpIdxZoneNs + ScpIdxClusterNs ; durees cumulees entre
    # deux d entre eux en code natif.
    $zn = $script:ScpIdxZoneNs; $cn = $script:ScpIdxClusterNs; $cm = [int]$script:ScpIdxClusterMax; $n = $f.Length
    $z = 0; $far = 0
    # Debut du tour : $cum = debut de l intervalle $p ; grappe de $t0 (debut du premier) a $t1 (fin du dernier)
    $p = $hs.IndexOf([char]'x', $first); $last = 0; $cum = 0; $c = 0; $t0 = -1; $t1 = 0; $ok = $true
    while ($p -ge 0) {
        if ($p -gt $last) { $cum += [System.Linq.Enumerable]::Sum([System.ArraySegment[int]]::new($f, $last, $p - $last)) }
        $last = $p
        if ($cum -ge $zn) {
            if ($c -gt 0 -and $f[$p] -lt 20000 -and $cum - $t1 -le $cn) { $ok = $false }
            if (-not $ok -or $c -eq 0 -or $cum -ge $zn + $cn) { break }
        } elseif ($f[$p] -lt 20000) {
            $c++; if ($t0 -lt 0) { $t0 = $cum }; $t1 = $cum + $f[$p]
            if ($c -gt $cm -or $t1 - $t0 -gt $cn) { $ok = $false; break }
        }
        $p = $hs.IndexOf([char]'x', $p + 1)
    }
    $hc = $c; $hf = $t1; $hok = $ok
    # Fin du tour : $tail = duree de la fin de l intervalle $a a la fin du tour ; grappe de $u0 a $u1 avant l index
    $q = $ts.LastIndexOf([char]'x'); $hi = $n; $tail = 0; $c = 0; $u0 = -1; $u1 = 0; $ok = $true
    while ($q -ge 0) {
        $a = $to + $q
        if ($hi - $a - 1 -gt 0) { $tail += [System.Linq.Enumerable]::Sum([System.ArraySegment[int]]::new($f, $a + 1, $hi - $a - 1)) }
        $hi = $a + 1
        if ($tail -ge $zn) {
            if ($c -gt 0 -and $f[$a] -lt 20000 -and $a -ge $first -and $tail - $u1 -le $cn) { $ok = $false }
            if (-not $ok -or $c -eq 0 -or $tail -ge $zn + $cn) { break }
        } elseif ($f[$a] -lt 20000 -and $a -ge $first) {
            $c++; if ($u0 -lt 0) { $u0 = $tail }; $u1 = $tail + $f[$a]
            if ($c -gt $cm -or $u1 - $u0 -gt $cn) { $ok = $false; break }
        }
        if ($q -eq 0) { break }
        $q = $ts.LastIndexOf([char]'x', $q - 1)
    }
    if ($hok -and $ok -and $hc -gt 0 -and $c -gt 0 -and ($hc + $c -gt $cm -or $hf + $u1 -gt $cn)) { $hok = $false; $ok = $false }
    if ($hok -and $hc -gt 0) { $z += $hc; $far = $hf }
    if ($ok -and $c -gt 0) { $z += $c; $far = [math]::Max($far, $u1) }
    return @($z, $far)
}

function Get-ScpZoneEnd($f, [bool]$head, [int]$lim) {
    # Limite de la zone de l index d un tour, par dichotomie (sommes en code natif). Debut : nombre d intervalles qui
    # commencent avant ScpIdxZoneNs, au plus $lim (classes connues) ; fin : indice du premier intervalle qui finit apres
    # T - ScpIdxZoneNs, au moins $n - $lim.
    $n = $f.Length; $zn = $script:ScpIdxZoneNs
    if ($head) {
        $lo = 0; $hi = [math]::Min($n, $lim)
        while ($lo -lt $hi) {
            $mid = [int][math]::Floor(($lo + $hi) / 2)
            if ([System.Linq.Enumerable]::Sum([System.ArraySegment[int]]::new($f, 0, $mid)) -ge $zn) { $hi = $mid } else { $lo = $mid + 1 }
        }
        return $lo
    }
    $lo = [math]::Max(0, $n - $lim); $hi = $n
    while ($lo -lt $hi) {
        $mid = [int][math]::Ceiling(($lo + $hi) / 2)
        if ([System.Linq.Enumerable]::Sum([System.ArraySegment[int]]::new($f, $mid, $n - $mid)) -ge $zn) { $lo = $mid } else { $hi = $mid - 1 }
    }
    return $lo
}

function Test-ScpZoneData($f0, [string]$hs, [string]$ts, [int]$to, [double]$cell) {
    # Revue 12.8.2 : zone de l index du tour 0 qui contient des donnees (le raccord n y est pas : image IPF, bloc WRSP,
    # original non cale sur l index ou ecrit par un Amiga, index simule) : un bloc de Len intervalles entierement dans la
    # zone, sans hors classe, au motif varie (aucune classe sur plus de 80 % du bloc) et present une seule fois a
    # +/- Win2 (critere des ancres, Find-ScpAnchor), dont les deux moities sont aussi uniques : un bloc a cheval sur la
    # rupture de phase d un remplissage periodique (gap 4E coupe par le raccord) a une moitie periodique. Vide (2T),
    # remplissage periodique et raccord : faux ; debut d un secteur (synchro et en-tete) ou secteur coupe : vrai. Suites
    # de 2T sautees d un coup ; pas de ZoneStep apres un bloc trop uniforme ou dont une moitie se repete, de Len / 2 apres
    # un motif periodique ; ZoneTries blocs au plus par bout. $hs, $ts, $to : classes des bouts du tour 0
    # (Get-ScpEdgeClasses) ; $cell : cellule du tour 0. Verification du 27/10/2026 : sans bloc retenu, synchro MFM pres de
    # l index (Test-ScpZoneSync) : un defaut dans le seul bloc riche de la zone, ou un secteur a donnees uniformes (zeros :
    # suites de 2T) a cheval sur l index, ne font plus prendre la zone pour du vide.
    $A = $script:ScpAnchor; $L = [int]$A.Len; $W2 = [int]$A.Win2; $mx = [math]::Floor(0.8 * $L); $h = [int]($L / 2)
    $ord = [System.StringComparison]::Ordinal; $chars = [char[]]'345x'; $cs = @('2', '3', '4', '5')
    foreach ($head in $true, $false) {
        # Zone [$za, $zb) dans $s (noms distincts de $A : PowerShell ne distingue pas la casse)
        if ($head) { $s = $hs; $za = 0; $zb = Get-ScpZoneEnd $f0 $true $hs.Length }
        else { $s = $ts; $za = (Get-ScpZoneEnd $f0 $false $ts.Length) - $to; $zb = $ts.Length }
        $p = $za; $tries = 0
        while ($tries -lt [int]$A.ZoneTries -and $p + $L -le $zb) {
            $p = $s.IndexOfAny($chars, $p)
            if ($p -lt 0 -or $p + $L -gt $zb) { break }
            $tries++
            $blk = $s.Substring($p, $L)
            $ix = $blk.LastIndexOf([char]'x')
            if ($ix -ge 0) { $p += $ix + 1; continue }
            $ok = $true
            foreach ($c in $cs) { if ($L - $blk.Replace($c, '').Length -gt $mx) { $ok = $false; break } }
            if (-not $ok) { $p += [int]$A.ZoneStep; continue }
            $lo = [math]::Max(0, $p - $W2); $hi = [math]::Min($s.Length, $p + $L + $W2)
            if ($s.IndexOf($blk, $lo, $hi - $lo, $ord) -eq $p -and $s.IndexOf($blk, $p + 1, $hi - $p - 1, $ord) -lt 0) {
                $u = $true
                foreach ($o in 0, $h) {
                    $hb = $blk.Substring($o, $h); $q = $p + $o
                    $lo = [math]::Max(0, $q - $W2); $hi = [math]::Min($s.Length, $q + $h + $W2)
                    if ($s.IndexOf($hb, $lo, $hi - $lo, $ord) -ne $q -or $s.IndexOf($hb, $q + 1, $hi - $q - 1, $ord) -ge 0) { $u = $false; break }
                }
                if ($u) { return $true }
                $p += [int]$A.ZoneStep
            } else { $p += $h }
        }
    }
    return (Test-ScpZoneSync $f0 $hs $ts $to $cell)
}

function Test-ScpZoneSync($f0, [string]$hs, [string]$ts, [int]$to, [double]$cell) {
    # Verification du 27/10/2026 : le tour 0 contient-il une double synchro MFM 0x4489 (classes ScpIdxSync) qui commence a
    # moins de ScpIdxZoneNs apres l index (debut du tour, a partir de l intervalle 1) ou a moins de ScpIdxSyncBeforeNs de
    # la fin du tour 0 (secteur a cheval sur l index) ? Seule la premiere synchro du debut et la derniere de la fin sont
    # jugees (les plus proches de l index). Fin du tour 0 classee sur moins de ScpIdxSyncBeforeNs (suites de 2T) et sans
    # synchro : ScpRevWin intervalles de plus avant elle (tout le debut du tour au besoin), raccordes a ses classes.
    # Recherches par les surcharges a quatre arguments (chaine, debut, longueur, Ordinal) : une seule candidate en 5.1.
    $sy = [string]$script:ScpIdxSync; $bn = $script:ScpIdxSyncBeforeNs; $n = $f0.Length; $ord = [System.StringComparison]::Ordinal
    $p = $hs.IndexOf($sy, 1, $hs.Length - 1, $ord)
    if ($p -ge 1 -and [System.Linq.Enumerable]::Sum([System.ArraySegment[int]]::new($f0, 0, $p)) -lt $script:ScpIdxZoneNs) { return $true }
    $q = $ts.LastIndexOf($sy, $ts.Length - 1, $ts.Length, $ord)
    if ($q -ge 0) { return ([System.Linq.Enumerable]::Sum([System.ArraySegment[int]]::new($f0, $to + $q, $n - $to - $q)) -lt $bn) }
    if ($to -le 0 -or [System.Linq.Enumerable]::Sum([System.ArraySegment[int]]::new($f0, $to, $n - $to)) -ge $bn) { return $false }
    $s0 = [math]::Max(0, $to - [int]$script:ScpRevWin)
    if ($s0 -gt 0 -and [System.Linq.Enumerable]::Sum([System.ArraySegment[int]]::new($f0, $s0, $n - $s0)) -lt $bn) { $s0 = 0 }
    $e0 = [math]::Min($n, $to + $sy.Length - 1)
    $seg = Get-ScpClassText $f0 $s0 ($e0 - $s0) $cell
    $q = $seg.LastIndexOf($sy, $seg.Length - 1, $seg.Length, $ord)
    return ($q -ge 0 -and [System.Linq.Enumerable]::Sum([System.ArraySegment[int]]::new($f0, $s0 + $q, $n - $s0 - $q)) -lt $bn)
}

function Find-ScpAnchor($fl, $list, $edges, [string]$s, [int]$to, [bool]$head, [int]$minAbs) {
    # S12 : ancre du tour 0 et sa position dans chaque tour ; tableau des positions absolues, ou $null.
    #  Candidats du tour 0, dans l ordre ($s : classes du debut du tour 0 pour A, de la fin pour B, premier intervalle
    #  d indice $to) : A, premiers blocs de Len intervalles qui commencent apres ScpIdxZoneNs ; B, derniers blocs qui
    #  finissent avant T - ScpIdxZoneNs et commencent apres $minAbs (fin de A). Bloc retenu : aucun intervalle hors
    #  classe ni trou, motif varie (aucune classe sur plus de 80 % du bloc, comme le bloc « riche » de
    #  ScpStats.Instability), une seule fois a +/- Win2 dans le tour 0. Suites de 2T (vide, remplissage) sautees d un
    #  coup ; apres un refus, bloc suivant ; Tries positions et Cand candidats au plus.
    #  Chaque candidat est cherche par sa suite exacte de classes dans chaque tour, autour de la position attendue
    #  (position au tour precedent, plus la derive des deux tours precedents : index synthetique), a +/- Win puis a
    #  +/- Win2, sur les classes du seul segment cherche (prises dans les bouts du tour deja classes, $edges, ou classees
    #  a part) ; retenu s il y est une seule fois dans tous les tours. Revue 12.8.2 : trouve a plus de Win de sa position
    #  attendue dans un tour (derive d un index simule), le bloc doit aussi etre unique dans le tour 0 sur la fenetre
    #  elargie de cet ecart : sinon un double du bloc, pris pour lui dans un tour ou il est abime, fausserait AB ou BA.
    $A = $script:ScpAnchor; $L = [int]$A.Len; $W = [int]$A.Win; $W2 = [int]$A.Win2; $mx = [math]::Floor(0.8 * $L)
    $ord = [System.StringComparison]::Ordinal; $chars = [char[]]'345x'; $cs = @('2', '3', '4', '5')
    $f0 = $fl[0]; $n0 = $f0.Length; $nr = $fl.Count; $zn = $script:ScpIdxZoneNs
    $zl = [int][math]::Ceiling($zn / [math]::Floor(1.65 * [double]$list[0].Cell))
    if ($head) { $p = $zl } else { $e = $s.Length - 1 - $zl }
    $tries = 0; $cand = 0
    while ($tries -lt $A.Tries -and $cand -lt $A.Cand) {
        if ($head) {
            if ($p -ge $s.Length) { break }
            $p = $s.IndexOfAny($chars, $p)
            if ($p -lt 0 -or $p + $L + $W -gt $s.Length) { break }
        } else {
            if ($e -lt 0) { break }
            $e = $s.LastIndexOfAny($chars, $e)
            $p = $e - $L + 1
            if ($e -lt 0 -or $p - $W -lt 0 -or $to + $p -lt $minAbs) { break }
        }
        $tries++
        $b = $s.Substring($p, $L)
        if ($head) { $ix = $b.IndexOf([char]'x'); if ($ix -ge 0) { $p = $p + $ix + 1; continue } }
        else { $ix = $b.LastIndexOf([char]'x'); if ($ix -ge 0) { $e = $p + $ix - 1; continue } }
        $ok = $true
        foreach ($c in $cs) { if ($L - $b.Replace($c, '').Length -gt $mx) { $ok = $false; break } }
        if ($ok) {
            $lo = [math]::Max(0, $p - $W2); $hi = [math]::Min($s.Length, $p + $L + $W2)
            $ok = ($s.IndexOf($b, $lo, $hi - $lo, $ord) -eq $p -and $s.IndexOf($b, $p + 1, $hi - $p - 1, $ord) -lt 0)
        }
        $abs = $to + $p
        if ($ok) {
            if ($head) { $ok = ([System.Linq.Enumerable]::Sum([System.ArraySegment[int]]::new($f0, 0, $abs)) -ge $zn) }
            else { $ok = ([System.Linq.Enumerable]::Sum([System.ArraySegment[int]]::new($f0, $abs + $L, $n0 - $abs - $L)) -ge $zn) }
        }
        if (-not $ok) { if ($head) { $p += $L } else { $e -= $L }; continue }
        # Candidat retenu : position dans les autres tours
        $cand++
        $pos = [int[]]::new($nr); $pos[0] = $abs; $dev = 0
        for ($r = 1; $r -lt $nr -and $ok; $r++) {
            $f = $fl[$r]
            $ex = $pos[$r - 1]; if ($r -ge 2) { $ex += $pos[$r - 1] - $pos[$r - 2] }
            $lo = [math]::Max(0, $ex - $W2); $hi = [math]::Min($f.Length, $ex + $L + $W2)
            $q = -1
            if ($hi - $lo -ge $L) {
                $ed = $edges[$r]; $eh = [string]$ed[0]; $et = [string]$ed[1]; $eo = [int]$ed[2]
                if ($hi -le $eh.Length) { $seg = $eh.Substring($lo, $hi - $lo) }
                elseif ($lo -ge $eo) { $seg = $et.Substring($lo - $eo, $hi - $lo) }
                else { $seg = Get-ScpClassText $f $lo ($hi - $lo) ([double]$list[$r].Cell) }
                $a1 =[math]::Max(0, $ex - $W - $lo); $b1 = [math]::Min($seg.Length, $ex + $L + $W - $lo)
                if ($b1 - $a1 -ge $L) {
                    $q = $seg.IndexOf($b, $a1, $b1 - $a1, $ord)
                    if ($q -ge 0 -and $seg.IndexOf($b, $q + 1, $b1 - $q - 1, $ord) -ge 0) { $q = -2 }
                }
                if ($q -eq -1) {
                    $q = $seg.IndexOf($b, $ord)
                    if ($q -ge 0 -and $seg.IndexOf($b, $q + 1, $ord) -ge 0) { $q = -2 }
                }
            }
            if ($q -lt 0) { $ok = $false } else { $pos[$r] = $lo + $q; $dev = [math]::Max($dev, [math]::Abs($pos[$r] - $ex)) }
        }
        if ($ok -and $dev -gt $W) {
            $lo = [math]::Max(0, $p - $W2 - $dev); $hi = [math]::Min($s.Length, $p + $L + $W2 + $dev)
            $ok = ($s.IndexOf($b, $lo, $hi - $lo, $ord) -eq $p -and $s.IndexOf($b, $p + 1, $hi - $p - 1, $ord) -lt 0)
        }
        if ($ok) { return ,$pos }
        if ($head) { $p += $L } else { $e = $p - 1 }
    }
    return $null
}

function Get-ScpEdgeOoc($f, $e, [int]$skip) {
    # 12.10 (S13, cout) : hors classe (trous exclus) d un tour aux indices que Get-ScpStructOoc ignore, [0, skip) et
    # [max(skip, n - skip), n), comptes sur les classes des bouts deja calculees par Set-ScpTrackPost (Get-ScpEdgeClasses :
    # debut, fin, indice du premier intervalle de la fin, tour entier), sans reclasser le tour. -1 si ces classes ne couvrent
    # pas les deux bouts (aucune deduction possible)
    $n = $f.Length; $hs = [string]$e[0]; $ts = [string]$e[1]; $to = [int]$e[2]
    $a = [math]::Max($skip, $n - $skip); $h = [math]::Min($skip, $n)
    if (-not [bool]$e[3] -and ($hs.Length -lt $h -or $to -gt $a)) { return -1 }
    $k = 0
    $p = $hs.IndexOf([char]'x', 0, $h)
    while ($p -ge 0) { if ($f[$p] -lt 20000) { $k++ }; $p = if ($p + 1 -lt $h) { $hs.IndexOf([char]'x', $p + 1, $h - $p - 1) } else { -1 } }
    if ($a -lt $n) {
        $p = $ts.IndexOf([char]'x', $a - $to)
        while ($p -ge 0) { if ($f[$to + $p] -lt 20000) { $k++ }; $p = $ts.IndexOf([char]'x', $p + 1) }
    }
    return $k
}

function Get-ScpStructOoc($fl, $list, [int]$skip, [int]$cap = -1, $edges = $null) {
    # 12.10 (S13) : par tour, nombre d intervalles hors classe (classe 'x' de ScpStats.Classes, trous de 20 us ou plus
    # exclus : ils sont comptes a part) presents dans TOUS les autres tours a un indice voisin : ScpStructTol intervalles,
    # plus l ecart des comptes de flux entre les deux tours (les tours sont cales sur l index par gw). Indices sous $skip
    # ou au-dela de n - $skip ignores (bouts du tour deja traites par la zone de l index, S11). Constat du 02/11/2026
    # (AlienBreed, long track, TEAC) : le raccord d ecriture d une longue piste tombe la ou l image le place, loin de
    # l index, et laisse 1 a 2 intervalles hors classe par tour, identiques sur les 3 tours : comptes comme erreurs, ils
    # faisaient reecrire 20 a 30 pistes par disquette pour rien. Un petit defaut fixe du support y passe aussi : une
    # reecriture ne le corrigerait pas davantage (au-dela de ScpStructMax par tour : Set-ScpTrackPost). Rend un int[] par tour.
    # Cout (banc scp-real : +38,9 % de calcul) : sortie immediate quand un tour n a aucun hors classe hors des bouts
    # ignores : OutOfClass brut d Analyze (030), pas encore corrige par Set-ScpTrackPost, compte exactement les x de
    # Classes hors trous (meme cellule, memes bornes 0,35 et 2 a 5), moins ceux des bouts ($edges : classes des bouts de
    # Set-ScpTrackPost, Get-ScpEdgeOoc) ; un hors classe retenu devant etre present dans tous les tours, aucun ne l est.
    # Voisin cherche par recherche dichotomique dans les indices croissants de l autre tour (Array.BinarySearch). $cap >= 0 :
    # sortie des que le compte d un tour depasse $cap ; comptes rendus alors partiels (tour en cause a $cap + 1, tours
    # suivants a 0) : ils ne servent plus qu a signaler la piste (Post.StructOver, minorant du total).
    # Relecture de la finalisation 12.10 : premier intervalle du tour 0 jamais compte (S10, Set-ScpTrackPost : meme critere,
    # classe x hors trou, deja retire) ; il reste un voisin pour les autres tours. Avant : avec $skip 0, il pouvait etre
    # retire deux fois et masquer un autre hors classe du tour 0 (aucun cas sur les 1 920 pistes de v1210\struct-cap).
    $nr = $list.Count; $out = [int[]]::new($nr)
    if ($nr -lt 2) { return $out }
    for ($r = 0; $r -lt $nr; $r++) {
        $nx = [int]$list[$r].OutOfClass
        if ($nx -gt 0 -and $skip -gt 0 -and $null -ne $edges) { $eo = Get-ScpEdgeOoc $fl[$r] $edges[$r] $skip; if ($eo -ge 0) { $nx -= $eo } }
        if ($nx -le 0) { return $out }
    }
    $tol = [int]$script:ScpStructTol
    $xs = New-Object object[] $nr
    for ($r = 0; $r -lt $nr; $r++) {
        $f = $fl[$r]; $n = $f.Length
        $s = [ScpStats]::Classes($f, [double]$list[$r].Cell)
        $ix = [System.Collections.Generic.List[int]]::new()
        $p = if ($skip -lt $n) { $s.IndexOf([char]'x', [math]::Max(0, $skip)) } else { -1 }
        while ($p -ge 0 -and $p -lt $n - $skip) {
            if ($f[$p] -lt 20000) { $ix.Add($p) }
            $p = $s.IndexOf([char]'x', $p + 1)
        }
        $xs[$r] = $ix.ToArray()
    }
    for ($r = 0; $r -lt $nr; $r++) {
        foreach ($p in $xs[$r]) {
            if ($r -eq 0 -and $p -eq 0) { continue }
            $all = $true
            for ($q = 0; $q -lt $nr; $q++) {
                if ($q -eq $r) { continue }
                $t = $tol + [math]::Abs($fl[$r].Length - $fl[$q].Length)
                # Premier indice >= p - t de l autre tour (complement du point d insertion si absent) : voisin s il est <= p + t
                $a = $xs[$q]; $i = [System.Array]::BinarySearch($a, [int]($p - $t))
                if ($i -lt 0) { $i = -$i - 1 }
                if ($i -ge $a.Length -or $a[$i] -gt $p + $t) { $all = $false; break }
            }
            if ($all) { $out[$r]++; if ($cap -ge 0 -and $out[$r] -gt $cap) { return $out } }
        }
    }
    return $out
}

function Set-ScpTrackPost($fl, $list, [bool]$zone) {
    # Post-traitement d une piste lue par Read-ScpFile hors calibration. $fl : flux de chaque tour ; $list : ScpRev de
    # chaque tour (Analyze) ; $zone : index reel, cale par gw (S11 permise). Pistes illisibles (jitter non mesure) : rien.
    #  S10 : le premier intervalle du tour 0, tronque par gw (flux.py, cue_at_index), n est pas compte hors classe ; un
    #        premier intervalle de 20 us ou plus reste un trou (verification du 27/10/2026 : gw le tronque, c est un vrai
    #        trou d au moins 20 us). NFlux ne change pas.
    #  S11 : hors classe a moins de ScpIdxZoneNs d un index (Get-ScpZoneOoc), non comptes : jonction d ecriture de gw,
    #        dans l espace entre le dernier et le premier secteur ; trous comptes partout. Double densite (cellule de 1,7
    #        a 2,3 us, classes justes ; verification : et hors classe du tour 0 au plus 5 % des flux, sinon haute densite a
    #        cellule mal estimee ou piste critique de toute facon), tours d au moins ScpIdxMinRevNs (un index par
    #        rotation). Revue 12.8.2 : pas si la zone du tour 0 contient des donnees (Test-ScpZoneData, synchro MFM
    #        comprise) ; par tour et par bout, une seule grappe ecartee.
    #  S12 : stabilite sur tours alignes : ancres A (debut du corps de piste) et B (fin) du tour 0, retrouvees dans chaque
    #        tour (Find-ScpAnchor ; bouts du tour 0, puis tout le tour 0 si aucun couple n y est trouve). StabAl =
    #        max(ecart des comptes de flux de A a B des tours, ecart des comptes de B a A du tour suivant, a travers
    #        l index) : un deplacement de l index ne change aucun compte. Au moins 3 tours (2 : un seul compte de B a A)
    #        d au moins ScpIdxMinRevNs, double densite ; ancre introuvable ou ambigue dans un tour : StabAl -1, Stab
    #        d avant (NFlux) ; Tried : alignement tente (repli signale au journal par l appelant).
    # Ecrit OutOfClass des tours et ajoute au tour 0 la propriete Post = @{ ZoneOoc (hors classe ecartes, tous tours) ;
    # ZoneFarNs (distance a l index de la grappe ecartee la plus lointaine) ; First ('ooc' ou '') ;
    # StabAl ; Tried ; Zone (S11 appliquee) ; ZoneData (zone avec des donnees : S11 non appliquee) ; PA ; PB (positions
    # des ancres) ; 12.10 : StructOoc (S13, retires, tous tours) ; StructOver (S13 non appliquee, plafond depasse) }. Toute erreur : piste laissee au comptage d avant, comptee dans ScpPostFail (journal : Read-ScpFile).
    $nr = $list.Count
    if ($nr -eq 0 -or $fl.Count -ne $nr -or $fl[0].Length -eq 0) { return }
    foreach ($x in $list) { if ([double]::IsNaN([double]$x.Jitter)) { return } }
    $post = @{ ZoneOoc = 0; ZoneFarNs = 0; First = ''; StabAl = -1; Tried = $false; Zone = $false; ZoneData = $false; PA = $null; PB = $null; StructOoc = 0; StructOver = 0 }
    $dOoc = [int[]]::new($nr)
    try {
        $c0 = [double]$list[0].Cell; $v = $fl[0][0]
        if ($v -lt 20000) {
            $q = $v / $c0; $k = [math]::Round($q)
            if ([math]::Abs($q - $k) -gt 0.35 -or $k -lt 2 -or $k -gt 5) { $dOoc[0] = 1; $post.First = 'ooc' }
        }
        if ($c0 -ge 1700 -and $c0 -le 2300 -and 20 * [int]$list[0].OutOfClass -le [int]$list[0].NFlux) {
            # Classes des bouts de chaque tour : ScpPostWin intervalles au tour 0 (ancres), ScpRevWin aux autres (zone de
            # l index et recherche des ancres)
            $edges = New-Object object[] $nr
            for ($r = 0; $r -lt $nr; $r++) { $edges[$r] = Get-ScpEdgeClasses $fl[$r] ([double]$list[$r].Cell) $(if ($r -eq 0) { [int]$script:ScpPostWin } else { [int]$script:ScpRevWin }) }
            $e0 = $edges[0]
            $hs0 = [string]$e0[0]; $ts0 = [string]$e0[1]; $to0 = [int]$e0[2]; $full0 = [bool]$e0[3]
            # Un index par rotation (secteurs durs lus sans --hard-sectors : plusieurs) : zone de l index et tours alignes
            $oneIdx = $true
            foreach ($x in $list) { if ([double]$x.IndexMs * 1e6 -lt $script:ScpIdxMinRevNs) { $oneIdx = $false } }
            if ($zone -and $oneIdx) {
                if (Test-ScpZoneData $fl[0] $hs0 $ts0 $to0 $c0) { $post.ZoneData = $true }
                else {
                    $post.Zone = $true
                    for ($r = 0; $r -lt $nr; $r++) {
                        $e = $edges[$r]
                        $z = Get-ScpZoneOoc $fl[$r] ([string]$e[0]) ([string]$e[1]) ([int]$e[2]) $(if ($r -eq 0) { 1 } else { 0 })
                        $dOoc[$r] += [int]$z[0]; $post.ZoneOoc += [int]$z[0]
                        if ([int]$z[1] -gt $post.ZoneFarNs) { $post.ZoneFarNs = [int]$z[1] }
                    }
                }
            }
            # 12.10 (S13) : hors classe reproductibles d un tour a l autre a la meme position, dans tous les tours : non
            # comptes (StructOoc, Get-ScpStructOoc) ; bouts deja traites par la zone de l index non revisites. Plafond
            # (ScpStructMax, 040) : un tour qui en compte davantage -> aucun retire sur la piste, tout compte comme en
            # 12.9 ; StructOver = reproductibles trouves (tous tours, comptes partiels de Get-ScpStructOoc : au moins
            # ScpStructMax + 1), piste signalee au journal par l appelant
            if ([bool]$script:ScpStructOn -and $nr -ge 2) {
                $smax = [int]$script:ScpStructMax
                $st = if ($post.Zone) { Get-ScpStructOoc $fl $list ([int]$script:ScpRevWin) $smax $edges } else { Get-ScpStructOoc $fl $list 0 $smax }
                $sHi = 0; $sSum = 0
                for ($r = 0; $r -lt $nr; $r++) { $sSum += [int]$st[$r]; if ([int]$st[$r] -gt $sHi) { $sHi = [int]$st[$r] } }
                if ($sHi -gt $smax) { $post.StructOver = $sSum }
                else { for ($r = 0; $r -lt $nr; $r++) { $dOoc[$r] += [int]$st[$r]; $post.StructOoc += [int]$st[$r] } }
            }
            if ($nr -ge 3 -and $oneIdx) {
                $post.Tried = $true
                $L = [int]$script:ScpAnchor.Len; $pa = $null; $pb = $null
                foreach ($att in 0, 1) {
                    $pb = $null
                    $pa = Find-ScpAnchor $fl $list $edges $hs0 0 $true 0
                    if ($null -ne $pa) { $pb = Find-ScpAnchor $fl $list $edges $ts0 $to0 $false ($pa[0] + $L) }
                    if (($null -ne $pa -and $null -ne $pb) -or $full0) { break }
                    # Aucun couple d ancres dans les bouts du tour 0 (secteurs vides, long remplissage) : tout le tour 0
                    $hs0 = Get-ScpClassText $fl[0] 0 $fl[0].Length $c0; $ts0 = $hs0; $to0 = 0; $full0 = $true
                }
                if ($null -ne $pa -and $null -ne $pb) {
                    $aMin = [int]::MaxValue; $aMax = [int]::MinValue; $bMin = [int]::MaxValue; $bMax = [int]::MinValue
                    for ($r = 0; $r -lt $nr; $r++) {
                        $ab = $pb[$r] - $pa[$r]
                        if ($ab -lt $aMin) { $aMin = $ab }; if ($ab -gt $aMax) { $aMax = $ab }
                        if ($r -lt $nr - 1) {
                            $ba = $fl[$r].Length - $pb[$r] + $pa[$r + 1]
                            if ($ba -lt $bMin) { $bMin = $ba }; if ($ba -gt $bMax) { $bMax = $ba }
                        }
                    }
                    if ($aMin -gt 0 -and $bMin -gt 0) { $post.StabAl = [int][math]::Max($aMax - $aMin, $bMax - $bMin); $post.PA = $pa; $post.PB = $pb }
                }
            }
        }
        # Propriete ajoutee avant toute correction : en cas d echec, la piste reste entiere au comptage d avant
        $list[0].PSObject.Properties.Add([System.Management.Automation.PSNoteProperty]::new('Post', $post))
    } catch {
        if ($script:ScpPostFail) { $script:ScpPostFail.N++; if (-not $script:ScpPostFail.Msg) { $script:ScpPostFail.Msg = [string]$_.Exception.Message } }
        return
    }
    for ($r = 0; $r -lt $nr; $r++) { if ($dOoc[$r] -ne 0) { $list[$r].OutOfClass = [math]::Max(0, [int]$list[$r].OutOfClass - $dOoc[$r]) } }   # 12.10 : jamais negatif
}

function Get-AlignCyls {
    $vals = @()
    foreach ($tok in ($txtAlCyls.Text -split '[,; ]+')) {
        if ($tok -match '^\d+$') { $v = [int]$tok; if ($v -ge 0 -and $v -le 83) { $vals += $v } }
    }
    return ($vals | Sort-Object -Unique)
}

function Start-AlignCycle {
    if ($script:GwProc -and -not $script:GwProc.HasExited) { return }
    $cyls = @(Get-AlignCyls)
    if ($cyls.Count -eq 0) {
        [void](Show-AppMessage (T 'Indiquez au moins un cylindre valide (0-83).') (T 'Alignement') 'OK' 'Warning')
        $script:AlignLoop = $false; return
    }
    if (-not (Test-Path -LiteralPath $script:TempDir)) { [void](New-Item -ItemType Directory -Path $script:TempDir -Force) }
    $script:AlignTmp = Join-Path $script:TempDir 'align.scp'
    if (Test-Path -LiteralPath $script:AlignTmp) { Remove-Item -LiteralPath $script:AlignTmp -Force }
    $cspec = ($cyls -join ',')
    $hspec = if ($cmbAlHead.Text -eq '0+1') { '0-1' } else { $cmbAlHead.Text }
    $script:AlignArgs = @('read') + (Get-CommonArgs) + @("--revs=$($numAlRevs.Value)", "--tracks=c=${cspec}:h=$hspec", "`"$($script:AlignTmp)`"")
    # 12.8 (lot 3a) : resultat precedent grise et marque « en cours » jusqu a la fin de l analyse (D16)
    Set-QualityPending 'measure' @{ Drive = [string]$cmbDrive.Text; Heads = [string]$cmbAlHead.Text; Revs = [int]$numAlRevs.Value; NCyl = $cyls.Count }
    $script:Chain.Clear()
    $script:Chain.Enqueue({ Start-Gw $script:AlignArgs })
    $script:Chain.Enqueue({ Invoke-AlignAnalysis })
    Invoke-NextChainStep
}

function Get-AlLevel([string]$kind, [double]$v) {
    switch ($kind) {
        'score'  { if ($v -lt 100) { 0 } elseif ($v -lt 200) { 1 } elseif ($v -lt 400) { 2 } else { 3 } }
        'jitter' { if ($v -lt $script:JitterOk * 0.5) { 0 } elseif ($v -lt $script:JitterOk) { 1 } elseif ($v -lt (Get-JitterRedBound)) { 2 } else { 3 } }
        'asym'   { if ($v -lt 0.02){ 0 } elseif ($v -lt 0.05){ 1 } elseif ($v -lt 0.10){ 2 } else { 3 } }
        'err'    { if ($v -le 0)   { 0 } elseif ($v -le $script:HealthErrOk) { 1 } elseif ($v -le 20)  { 2 } else { 3 } }   # 12.8.2 : borne SAIN de Get-HealthLevel
        'stab'   { if ($v -le 2)   { 0 } elseif ($v -le 5)   { 1 } elseif ($v -le 10)  { 2 } else { 3 } }
        'delta'  { if ($v -le 10)  { 0 } elseif ($v -le 30)  { 1 } elseif ($v -le 100) { 2 } else { 3 } }   # ecart % vs reference
        default  { 3 }
    }
}

function Update-AlignGuide([double]$avg) {
    if ($null -eq $script:AlPos) { $lblAlPos.Text = ''; return }
    $pos = [int]$script:AlPos
    if (-not $script:AlPosScores.ContainsKey($pos) -or $avg -lt $script:AlPosScores[$pos]) { $script:AlPosScores[$pos] = $avg }
    $bestPos = $pos; $bestScore = [double]::PositiveInfinity
    foreach ($k in $script:AlPosScores.Keys) { if ($script:AlPosScores[$k] -lt $bestScore) { $bestScore = $script:AlPosScores[$k]; $bestPos = [int]$k } }
    $lblAlPos.Text = ((T "Position {0}  |  meilleure position : {1} (score {2})") -f "$pos", "$bestPos", "$([math]::Round($bestScore,0))")

    $sens = @{ 1 = "'+'"; -1 = "'-'" }
    $color = 'DimGray'; $txt = ''
    if ($script:AlLastMove -eq 0) {
        if ($script:AlPosScores.Count -le 1) {
            $txt = ((T "Position 0 mesurée (score {0}). Tournez le stepper d'UN PETIT cran dans un sens, puis cliquez sur le bouton correspondant.") -f "$([math]::Round($avg,0))")
            $color = 'RoyalBlue'
        } else {
            $txt = ((T "Position {0} re-mesurée. Meilleure position connue : {1}.") -f "$pos", "$bestPos")
            if ($pos -ne $bestPos) { $txt += ((T " Revenez de {0} cran(s) vers le sens {1} pour la retrouver.") -f "$([math]::Abs($pos-$bestPos))", "$($sens[[math]::Sign($bestPos-$pos)])") }
        }
    } else {
        $prev = $pos - $script:AlLastMove
        $prevScore = if ($script:AlPosScores.ContainsKey($prev)) { $script:AlPosScores[$prev] } else { $null }
        if ($null -eq $prevScore) {
            $txt = ((T "Position {0} mesurée. Pas de mesure à la position précédente : impossible de conclure, continuez.") -f "$pos")
        } elseif ($avg -lt $prevScore * 0.97) {
            $txt = ((T "AMÉLIORATION ({0} -> {1}) : CONTINUEZ dans le sens {2}, encore un cran, puis mesurez.") -f "$([math]::Round($prevScore,0))", "$([math]::Round($avg,0))", "$($sens[$script:AlLastMove])")
            $color = 'Green'
        } elseif ($avg -gt $prevScore * 1.03) {
            # le pas precedent etait-il un optimum (moins bon des deux cotes) ?
            $other = $prev - $script:AlLastMove
            $otherWorse = $script:AlPosScores.ContainsKey($other) -and ($script:AlPosScores[$other] -gt $prevScore * 1.03)
            if ($otherWorse -and $prev -eq $bestPos) {
                $txt = ((T "OPTIMUM TROUVÉ à la position {0} (score {1}) : RECULEZ d'un cran (sens {2}), resserrez les vis, re-mesurez pour contrôle.") -f "$prev", "$([math]::Round($prevScore,0))", "$($sens[-$script:AlLastMove])")
                $color = 'DarkGreen'
            } else {
                $txt = ((T "DÉGRADATION ({0} -> {1}) : RECULEZ d'un cran (sens {2}) pour revenir à la position {3}, puis essayez l'autre sens.") -f "$([math]::Round($prevScore,0))", "$([math]::Round($avg,0))", "$($sens[-$script:AlLastMove])", "$prev")
                $color = 'DarkOrange'
            }
        } else {
            $txt = ((T "Pas de changement net ({0} -> {1}) : cran trop petit ou plateau. Encore un cran dans le sens {2}.") -f "$([math]::Round($prevScore,0))", "$([math]::Round($avg,0))", "$($sens[$script:AlLastMove])")
            $color = 'DimGray'
        }
        if ($pos -ne $bestPos -and $color -ne 'DarkGreen' -and $avg -gt $bestScore * 1.10) {
            $txt += ((T "  (Meilleur connu : position {0}.)") -f "$bestPos")
        }
    }
    $lblAlReco.Text = $txt; $lblAlReco.ForeColor = $color
    Append-Log ((T "Guide alignement : {0}") -f "$txt")
}

function Get-HealthLevel([double]$err, [double]$drop, [double]$stab, [double]$jit, [double]$okT = $script:JitterOk, [double]$watchT = $script:JitterWatch) {
    # Seuils de jitter reglables (Accueil, « Regler le jitter ») ; l asymetrie n entre pas dans l etat. Seuils explicites
    # (Standard 120 / 250 ns) pour juger un ORIGINAL et pour le garde-fou du controle : un reglage strict ne doit faire
    # que reecrire davantage de pistes de la copie, pas rejeter une source lisible ni bloquer les reecritures.
    # 12.8.2 : SAIN jusqu a HealthErrOk erreurs par tour (2 ; 3 jusqu en 12.8.1), meme seuil pour tous les appelants.
    if ($err -le $script:HealthErrOk -and $drop -le 0 -and $stab -le 2 -and $jit -lt $okT) { return 0 }
    if ($err -le 20 -and $drop -le 1 -and $stab -le 10 -and $jit -lt $watchT) { return 1 }
    return 2
}

function Get-JitterRedBound {
    # Borne orange / rouge de la colonne Jitter : toujours au-dessus du seuil SAIN (bande orange non vide)
    return [math]::Max($script:JitterWatch * 0.8, ($script:JitterOk + $script:JitterWatch) / 2)
}

function Update-QualityTip {
    # 12.8.2 : definition des erreurs (premier intervalle et zone de l index non comptes) et de la stabilite (tours alignes),
    # en avant-derniere ligne ; 12.11 : signe de la colonne « Asym. » (Format-AsymCell) en derniere ligne, cle a part
    $tip.SetToolTip($lvAl, (((T "État par piste : SAIN / À SURVEILLER / CRITIQUE, d'après les erreurs, les trous, la stabilité et le jitter.`nJitter : SAIN sous {0} ns, À SURVEILLER sous {1} ns (onglet Accueil, « Régler le jitter »).`nCouleurs de la colonne Jitter : <{2} / <{0} / <{3} ns. Asymétrie : <0,02 / <0,05 / <0,10 (couleur et score seulement, sans effet sur l'état).`nErreurs : intervalles hors classe par tour, sans le premier intervalle de la lecture ; en double densité, sans le raccord d'écriture de gw quand il tient dans la zone de ± 1 ms autour de l'index (sauf index simulé ou données dans cette zone) ; les trous sont comptés partout. Stabilité : écart du nombre de flux entre les tours ; en double densité et à partir de 3 tours, comparés alignés sur les mêmes données.") -f "$($script:JitterOk)", "$($script:JitterWatch)", "$([math]::Round($script:JitterOk * 0.5))", "$([math]::Round((Get-JitterRedBound)))") + "`n" + (T "Signe de l'asymétrie : + intervalles longs relus trop longs (comme après une écriture au-dessus de la précompensation qui les centre pour ce lecteur) ; - trop courts (comme après une écriture au-dessous) ; sans signe : écarts de sens opposés.")))
}

function Set-JitterThresholds([int]$ok, [int]$watch) {
    # Bornes : SAIN de 30 a 300 ns, A SURVEILLER au moins 10 ns au-dessus, 600 ns au plus
    $ok = [math]::Max(30, [math]::Min(300, $ok))
    $watch = [math]::Max($ok + 10, [math]::Min(600, $watch))
    $changed = ($ok -ne [int]$script:JitterOk -or $watch -ne [int]$script:JitterWatch)
    $script:JitterOk = $ok; $script:JitterWatch = $watch
    Update-QualityTip
    # 12.8 (lot 3a) : etats affiches calcules avec les anciens seuils, non recalculables (AlignLast ne garde ni les trous ni
    # les zones instables) : resultat declare perime ; sans effet sans resultat affiche (chargement, Set-Defaults).
    # 12.8 (FIX3) : ni pendant une mesure ou un controle en cours (Reinitialiser des parametres pendant la pause d une
    # mesure continue, passe suivante lancee par le minuteur sous la boite) : son analyse prendra les nouveaux seuils, et
    # l etat « en cours » garde les arrets sur erreur gw de la mesure continue
    if ($changed -and $script:QualView.State -ne 'run') { Set-QualityStale 'thresholds' }
}

function Get-JitterPresets {
    return @(
        @{ Name = (T 'Standard (120 / 250 ns)'); Ok = $script:JitterStdOk; Watch = $script:JitterStdWatch },   # 12.8 : constante unique
        @{ Name = (T 'Strict (90 / 180 ns)'); Ok = 90; Watch = 180 },
        @{ Name = (T 'Très strict (70 / 140 ns)'); Ok = 70; Watch = 140 }
    )
}

function Show-JitterSettings {
    # Reglage des seuils de jitter (etat SAIN / A SURVEILLER / CRITIQUE) : onglet Qualite, controle apres ecriture,
    # restauration. Refuse pendant une operation (un controle en cours changerait de criteres en route) ; 12.8 (D20) :
    # Get-AppBusy, donc aussi pendant un prechauffage, une detection ou la mesure continue de l onglet Qualite
    if (Get-AppBusy) {
        [void](Show-AppMessage (T "Opération en cours : modifiez le réglage du jitter une fois l'opération terminée.") (T 'Réglage du jitter') 'OK' 'Information'); return
    }
    # 12.8 (lot 5, A4 R1 a R8, D15, D17) : bandeau d information, legende des etats avec les icones du lot 3 (✓ SAIN,
    # ! A SURVEILLER, ✗ CRITIQUE) dans l encre de leur niveau (Get-QualInk), options en rangees de 34 px, erreur de saisie
    # dans le texte d etat lblJitState (R7) au lieu d une boite, aucun AcceptButton, images liberees (Clear-DlgGdi)
    $W = 600
    $presets = Get-JitterPresets
    $gdi = New-Object System.Collections.Generic.List[object]
    $dlg = New-Object System.Windows.Forms.Form
    $dlg.Name = 'frmJitter'; $dlg.Text = (T 'Réglage du jitter')
    $dlg.FormBorderStyle = 'FixedDialog'; $dlg.MaximizeBox = $false; $dlg.MinimizeBox = $false; $dlg.ShowInTaskbar = $false
    $dlg.StartPosition = 'CenterParent'; $dlg.Icon = $form.Icon; $dlg.Font = $form.Font; $dlg.BackColor = [System.Drawing.Color]::White
    $text = (T "Le jitter mesure la dispersion des intervalles entre les transitions magnétiques d'une piste, en nanosecondes : plus il est faible, plus la piste est nette.`n`nCes seuils fixent l'état de chaque piste dans l'onglet « Qualité & alignement », dans le contrôle après écriture et dans la restauration. Une piste n'est SAINE que si son jitter est sous le premier seuil, et si ses erreurs, ses trous et sa stabilité sont bons. Au-delà du second seuil, elle est CRITIQUE. Les erreurs ne comptent pas le premier intervalle de la lecture ni, en double densité, le raccord d'écriture de gw dans la zone de ± 1 ms autour de l'index ; en double densité et à partir de 3 tours, la stabilité compare les tours alignés sur les mêmes données.`n`nAprès une écriture avec contrôle de toutes les pistes (écriture lente, restauration), une piste qui n'est pas SAINE est réécrite, dans la limite des passes de réécriture : un réglage plus strict fait réécrire davantage de pistes, donc davantage d'écritures sur la disquette. Le jugement de la disquette d'origine en restauration et le garde-fou (plus de la moitié des pistes faibles : aucune réécriture) gardent les seuils Standard.")
    $ban = New-DlgBanner $dlg 16 $W (T 'Seuils de jitter des pistes') $text 'info' (New-DlgPicto 'jitter') $gdi 'lblJitText'
    $tf = [System.Windows.Forms.TextFormatFlags]::WordBreak -bor [System.Windows.Forms.TextFormatFlags]::NoPrefix
    $y = $ban.Bottom + 14
    # Libelles en x = 16 (legende : icone en x = 16, texte en x = 38), controles alignes apres le plus long libelle
    $l1 = New-Object System.Windows.Forms.Label; $l1.Text = (T 'Préréglage :'); $l1.AutoSize = $true; $l1.Font = $dlg.Font
    $l2 = New-Object System.Windows.Forms.Label; $l2.Text = (T 'SAIN si le jitter est inférieur à :'); $l2.AutoSize = $true; $l2.Font = $dlg.Font; $l2.ForeColor = Get-QualInk 0
    $l3 = New-Object System.Windows.Forms.Label; $l3.Text = (T "À SURVEILLER s'il est inférieur à :"); $l3.AutoSize = $true; $l3.Font = $dlg.Font; $l3.ForeColor = Get-QualInk 2
    $cx = [math]::Max(16 + $l1.PreferredWidth, 38 + [math]::Max($l2.PreferredWidth, $l3.PreferredWidth)) + 12
    $l1.Location = New-Object System.Drawing.Point(16, ($y + 3))
    $cmb = New-Object System.Windows.Forms.ComboBox
    $cmb.Name = 'cmbJitPreset'; $cmb.DropDownStyle = 'DropDownList'; $cmb.Location = New-Object System.Drawing.Point($cx, $y); $cmb.Width = 240
    foreach ($pr in $presets) { [void]$cmb.Items.Add($pr.Name) }
    [void]$cmb.Items.Add((T 'Personnalisé'))
    $y += 34
    $i2 = New-Object System.Windows.Forms.PictureBox; $i2.Image = Get-QualityIcon 'h0' 16; $i2.Location = New-Object System.Drawing.Point(16, ($y + 4)); $i2.Size = New-Object System.Drawing.Size(16, 16)
    $l2.Location = New-Object System.Drawing.Point(38, ($y + 3))
    $numOk = New-Object System.Windows.Forms.NumericUpDown
    $numOk.Name = 'numJitOk'; $numOk.Minimum = 30; $numOk.Maximum = 300; $numOk.Increment = 5; $numOk.Width = 80; $numOk.Location = New-Object System.Drawing.Point($cx, $y)
    $u1 = New-Object System.Windows.Forms.Label; $u1.Text = 'ns'; $u1.AutoSize = $true; $u1.Location = New-Object System.Drawing.Point(($cx + 86), ($y + 3))
    $y += 34
    $i3 = New-Object System.Windows.Forms.PictureBox; $i3.Image = Get-QualityIcon 'h1' 16; $i3.Location = New-Object System.Drawing.Point(16, ($y + 4)); $i3.Size = New-Object System.Drawing.Size(16, 16)
    $l3.Location = New-Object System.Drawing.Point(38, ($y + 3))
    $numWatch = New-Object System.Windows.Forms.NumericUpDown
    $numWatch.Name = 'numJitWatch'; $numWatch.Minimum = 40; $numWatch.Maximum = 600; $numWatch.Increment = 10; $numWatch.Width = 80; $numWatch.Location = New-Object System.Drawing.Point($cx, $y)
    $u2 = New-Object System.Windows.Forms.Label; $u2.Text = 'ns'; $u2.AutoSize = $true; $u2.Location = New-Object System.Drawing.Point(($cx + 86), ($y + 3))
    $y += 34
    $i4 = New-Object System.Windows.Forms.PictureBox; $i4.Image = Get-QualityIcon 'h2' 16; $i4.Location = New-Object System.Drawing.Point(16, ($y + 1)); $i4.Size = New-Object System.Drawing.Size(16, 16)
    $l4 = New-Object System.Windows.Forms.Label; $l4.Text = (T 'Au-delà : CRITIQUE.'); $l4.AutoSize = $true; $l4.ForeColor = Get-QualInk 3; $l4.Location = New-Object System.Drawing.Point(38, $y)
    $y += 26
    $l5 = New-Object System.Windows.Forms.Label; $l5.Text = (T 'Les nouvelles valeurs valent pour les prochaines mesures.'); $l5.AutoSize = $true; $l5.ForeColor = $script:Theme.Muted; $l5.Location = New-Object System.Drawing.Point(16, $y)
    $y += 26
    # Texte d etat (R7) : erreur de saisie, en Semibold et dans l encre du danger ; hauteur de son texte, mesuree
    $fS = New-Object System.Drawing.Font('Segoe UI Semibold', 9.75); $gdi.Add($fS)
    $errTxt = (T "Le seuil À SURVEILLER doit dépasser le seuil SAIN d'au moins 10 ns.")
    $lblSt = New-Object System.Windows.Forms.Label
    $lblSt.Name = 'lblJitState'; $lblSt.AutoSize = $false; $lblSt.UseMnemonic = $false; $lblSt.Font = $fS; $lblSt.ForeColor = Get-QualInk 3
    $lblSt.Location = New-Object System.Drawing.Point(16, $y)
    $lblSt.Size = New-Object System.Drawing.Size($W, ([System.Windows.Forms.TextRenderer]::MeasureText($errTxt, $fS, (New-Object System.Drawing.Size($W, 10000)), $tf).Height + 2))
    $y = $lblSt.Bottom + 8
    $btnDef = New-Object System.Windows.Forms.Button; $btnDef.Name = 'btnJitDefault'; $btnDef.Text = (T 'Valeurs par défaut'); $btnDef.Size = New-Object System.Drawing.Size((Get-DlgButtonWidth $btnDef.Text 'Refresh' 150), 34)
    $btnOk = New-Object System.Windows.Forms.Button; $btnOk.Name = 'btnJitOk'; $btnOk.Text = (T 'Enregistrer'); $btnOk.Size = New-Object System.Drawing.Size((Get-DlgButtonWidth $btnOk.Text 'Save' 140), 34)
    $btnNo = New-Object System.Windows.Forms.Button; $btnNo.Name = 'btnJitCancel'; $btnNo.Text = (T 'Annuler'); $btnNo.Size = New-Object System.Drawing.Size(110, 34)
    $btnNo.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
    Set-Btn $btnDef 'Refresh' 'normal'; Set-Btn $btnOk 'Save' 'primary'; Set-Btn $btnNo '' 'normal'
    $btnDef.Location = New-Object System.Drawing.Point(16, $y)
    $btnNo.Location = New-Object System.Drawing.Point((16 + $W - $btnNo.Width), $y)
    $btnOk.Location = New-Object System.Drawing.Point(($btnNo.Left - 8 - $btnOk.Width), $y)
    $dlg.ClientSize = New-Object System.Drawing.Size(($W + 32), ($y + $btnOk.Height + 16))
    $dlg.CancelButton = $btnNo                        # pas d AcceptButton : Entree n enregistre pas
    $dlg.Controls.AddRange(@($l1, $cmb, $i2, $l2, $numOk, $u1, $i3, $l3, $numWatch, $u2, $i4, $l4, $l5, $lblSt, $btnDef, $btnOk, $btnNo))
    $dlg.ActiveControl = $cmb
    [void](Set-DlgFit $dlg ([System.Windows.Forms.Screen]::FromControl($form).WorkingArea))
    # Etat partage avec les gestionnaires (portee script) : prereglage <-> valeurs, sans boucle ; texte d etat efface a
    # chaque changement de valeur
    $script:JitDlg = @{ Presets = $presets; Cmb = $cmb; Ok = $numOk; Watch = $numWatch; Busy = $false; Dlg = $dlg; State = $lblSt; Err = $errTxt }
    $numOk.Value = $script:JitterOk; $numWatch.Value = $script:JitterWatch
    $sync = {
        $s = $script:JitDlg
        if (-not $s -or $s.Busy) { return }
        $s.State.Text = ''
        $s.Busy = $true
        $i = -1
        for ($k = 0; $k -lt $s.Presets.Count; $k++) { if ($s.Presets[$k].Ok -eq [int]$s.Ok.Value -and $s.Presets[$k].Watch -eq [int]$s.Watch.Value) { $i = $k } }
        $s.Cmb.SelectedIndex = $(if ($i -ge 0) { $i } else { $s.Presets.Count })
        $s.Busy = $false
    }
    & $sync
    $numOk.Add_ValueChanged($sync); $numWatch.Add_ValueChanged($sync)
    $cmb.Add_SelectedIndexChanged({
        $s = $script:JitDlg
        if (-not $s -or $s.Busy -or $s.Cmb.SelectedIndex -lt 0 -or $s.Cmb.SelectedIndex -ge $s.Presets.Count) { return }
        $s.Busy = $true; $s.State.Text = ''
        $pr = $s.Presets[$s.Cmb.SelectedIndex]
        $s.Ok.Value = $pr.Ok; $s.Watch.Value = $pr.Watch
        $s.Busy = $false
    })
    $btnDef.Add_Click({ $script:JitDlg.Cmb.SelectedIndex = 0 })
    $btnOk.Add_Click({
        $s = $script:JitDlg
        # Seuils incoherents : texte d etat (R7), la fenetre reste ouverte
        if ([int]$s.Watch.Value -lt [int]$s.Ok.Value + 10) { $s.State.Text = $s.Err; return }
        $s.Dlg.DialogResult = [System.Windows.Forms.DialogResult]::OK
    })
    try {
        $dr = $dlg.ShowDialog($form)
        if ($dr -eq [System.Windows.Forms.DialogResult]::OK) {
            Set-JitterThresholds ([int]$numOk.Value) ([int]$numWatch.Value)
            [void](Save-Config)
            Append-Log ((T "Réglage du jitter : SAIN sous {0} ns, À SURVEILLER sous {1} ns, CRITIQUE au-delà (prochaines mesures).") -f "$($script:JitterOk)", "$($script:JitterWatch)")
        }
    } finally {
        $script:JitDlg = $null
        Clear-DlgGdi $dlg $gdi
    }
}

# Metriques d une piste (liste de ScpRev, un par tour) : base commune de l onglet Qualite et du
# controle apres ecriture, pour que « piste faible » ait partout la meme definition.
function Get-TrackMetrics($st) {
    # 12.8.2 : Ooc sans le premier intervalle de la lecture ni les hors classe de la zone de l index, Stab sur tours
    # alignes (Read-ScpFile, Set-ScpTrackPost : propriete Post du tour 0) ; ZoneOoc : hors classe ecartes (tous tours) ;
    # ZoneFarNs : distance a l index de la grappe ecartee la plus lointaine ; StabAligned : faux = ecart du nombre de flux
    # (moins de 3 tours, haute densite, secteurs durs, piste sans post-traitement : calibration) ; StabFallback :
    # alignement tente mais sans ancres communes (repli sur l ecart du nombre de flux, signale au journal). 12.10 (S13) :
    # StructOoc : hors classe reproductibles retires (tous tours) ; StructOver : plafond ScpStructMax depasse, aucun retire
    $m = @{ Bad = $false; Missing = $false; J = 0.0; R3 = 0.0; R4 = 0.0; Ooc = 0.0; Dr = 0.0; Cell = 0.0; Stab = 0.0; Asym = 0.0; Score = 9999; Level = 2
            Weak = $false; ShortUnstable = $false; Blocks = 0; Unstable = 0; MaxRun = 0; RunPos = -1; ZoneOoc = 0; ZoneFarNs = 0; StabAligned = $false; StabFallback = $false; StructOoc = 0; StructOver = 0 }
    $list = @($st)
    if ($list.Count -eq 0) { $m.Bad = $true; return $m }
    foreach ($x in $list) { if ([double]::IsNaN($x.Jitter)) { $m.Bad = $true } }
    if ($m.Bad) { return $m }
    $m.J    = ($list | Measure-Object -Property Jitter -Average).Average
    $m.R3   = ($list | Measure-Object -Property R3 -Average).Average
    $m.R4   = ($list | Measure-Object -Property R4 -Average).Average
    $m.Ooc  = ($list | Measure-Object -Property OutOfClass -Average).Average
    $m.Dr   = ($list | Measure-Object -Property Dropouts -Average).Average
    $m.Cell = ($list | Measure-Object -Property Cell -Average).Average
    $nf     = $list | ForEach-Object { $_.NFlux }
    $m.Stab = ($nf | Measure-Object -Maximum).Maximum - ($nf | Measure-Object -Minimum).Minimum
    $pp = $list[0].PSObject.Properties['Post']
    if ($pp -and $pp.Value) {
        $m.ZoneOoc = [int]$pp.Value.ZoneOoc; $m.ZoneFarNs = [int]$pp.Value.ZoneFarNs
        if ($pp.Value.ContainsKey('StructOoc')) { $m.StructOoc = [int]$pp.Value.StructOoc }   # 12.10 (S13)
        if ($pp.Value.ContainsKey('StructOver')) { $m.StructOver = [int]$pp.Value.StructOver }
        if ([int]$pp.Value.StabAl -ge 0) { $m.Stab = [int]$pp.Value.StabAl; $m.StabAligned = $true }
        elseif ($pp.Value.Tried) { $m.StabFallback = $true }
    }
    $m.Asym = [math]::Abs($m.R3 - 1.5) + [math]::Abs($m.R4 - 2.0)
    $m.Score = Get-TrackScore $m
    $m.Level = Get-HealthLevel $m.Ooc $m.Dr $m.Stab $m.J
    # Stabilite d un tour a l autre (Read-ScpFile, premier tour) : blocs de 32 intervalles absents d au moins deux autres
    # tours. Weak : au moins 3 blocs consecutifs (une dizaine d octets), au plus le quart de la piste = bits faibles d une
    # protection probable, ou defaut localise ; non reproductible par une copie, qui n ecrit qu un tour. ShortUnstable :
    # 2 blocs, raccord d ecriture a cheval sur deux blocs ou courte zone de protection : pas d alerte, mais jamais reecrite
    # sur une disquette identique a l original.
    $r0 = $list[0]
    if ($r0.Blocks -gt 0) {
        $m.Blocks = $r0.Blocks; $m.Unstable = $r0.Unstable; $m.MaxRun = $r0.MaxRun; $m.RunPos = $r0.RunPos
        $m.Weak = ($r0.MaxRun -ge 3 -and $r0.Unstable * 4 -le $r0.Blocks)
        $m.ShortUnstable = ($r0.MaxRun -ge 2 -and -not $m.Weak)
    }
    return $m
}

function Get-TrackScore($m) {
    # Note de lecture d une piste (plus basse = mieux) : jitter, asymetrie (x 2000), erreurs, trous, stabilite
    # 12.11 : poids de l asymetrie lu dans $script:ScoreAsymK (040, valeur inchangee), que Get-AsymSummary lit aussi
    return [math]::Round([double]$m.J + [double]$script:ScoreAsymK * [double]$m.Asym + 5 * [double]$m.Ooc + 50 * [double]$m.Dr + [double]$m.Stab, 0)
}

function Get-AsymSign($m) {
    # 12.11 : signe de l asymetrie d une piste, d apres les ecarts des rapports moyens 3T/2T et 4T/2T a leurs valeurs
    # nominales (1,5 et 2) : +1 si les deux sont positifs (intervalles longs relus trop longs), -1 si les deux sont
    # negatifs (trop courts), 0 s ils sont de sens opposes ou nuls, ou si la piste est illisible
    if ($null -eq $m -or $m.Bad) { return 0 }
    $d3 = [double]$m.R3 - 1.5; $d4 = [double]$m.R4 - 2.0
    if ($d3 -gt 0 -and $d4 -gt 0) { return 1 }
    if ($d3 -lt 0 -and $d4 -lt 0) { return -1 }
    return 0
}

function Format-AsymCell($m) {
    # 12.11 : texte de la case « Asym. » du tableau : valeur au format de toujours, precedee du signe de Get-AsymSign
    # quand la case n est pas verte (Get-AlLevel 'asym' au moins 1) et que les deux ecarts vont dans le meme sens ;
    # l export garde la valeur sans signe, a cote de ses colonnes « Ecart 3T » et « Ecart 4T »
    $t = '{0:N3}' -f $m.Asym
    if ((Get-AlLevel 'asym' $m.Asym) -lt 1) { return $t }
    $s = Get-AsymSign $m
    if ($s -gt 0) { return '+' + $t }
    if ($s -lt 0) { return '-' + $t }
    return $t
}

function Get-AsymSummary($ms) {
    # 12.11 : resume de l asymetrie d un resultat, sur ses pistes lisibles : N pistes, Pos et Neg pistes de signe + et -
    # (Get-AsymSign), Med asymetrie mediane, Points part de l asymetrie dans le score moyen (ScoreAsymK x moyenne, le
    # poids de Get-TrackScore), Kind '+' ou '-' quand la mediane sort de la classe verte (Get-AlLevel) et qu au moins
    # AsymSignPct % des pistes portent ce signe (arithmetique entiere), '' sinon. Source unique de la phrase du journal,
    # de l infobulle de la carte et de l en-tete de l export (Get-AsymSummaryText). Lectures gardees du 02/11/2026 (un
    # lecteur, long track) : signe + a la courbe entiere, - au quart de la courbe, aucun resume au facteur mesure
    # $ms : tableau, liste ou table seule ; foreach et non @() : sous PowerShell 7, @() sur une List[object] echoue
    $ok = New-Object System.Collections.Generic.List[object]
    foreach ($x in $ms) { if ($null -ne $x -and -not $x.Bad) { $ok.Add($x) } }
    $s = @{ N = $ok.Count; Pos = 0; Neg = 0; Med = 0.0; Points = 0; Kind = '' }
    if ($ok.Count -eq 0) { return $s }
    $sum = 0.0
    foreach ($m in $ok) {
        $g = Get-AsymSign $m
        if ($g -gt 0) { $s.Pos++ } elseif ($g -lt 0) { $s.Neg++ }
        $sum += [double]$m.Asym
    }
    $s.Med = [double](Get-Median @($ok | ForEach-Object { [double]$_.Asym }))
    $s.Points = [int][math]::Round([double]$script:ScoreAsymK * $sum / $ok.Count)
    if ((Get-AlLevel 'asym' $s.Med) -ge 1) {
        if (100 * $s.Pos -ge [int]$script:AsymSignPct * $s.N) { $s.Kind = '+' }
        elseif (100 * $s.Neg -ge [int]$script:AsymSignPct * $s.N) { $s.Kind = '-' }
    }
    return $s
}

function Get-AsymSummaryText($s, [switch]$Always) {
    # 12.11 : phrase du resume de l asymetrie (Get-AsymSummary) : signe commun, pistes qui le portent, mediane, part du
    # score moyen. Sans signe commun : chaine vide, ou forme courte avec -Always (en-tete de l export) ; sans piste
    # lisible : chaine vide. La phrase reste conditionnelle (« comme apres une ecriture... » : regle etablie sur un seul
    # lecteur) et ne donne aucune consigne : le conseil de mesure reste celui de Get-WriteFactorHint (140)
    if ($null -eq $s -or [int]$s.N -le 0) { return '' }
    $med = Format-UiNum ([double]$s.Med) '0.000'
    if ($s.Kind -eq '+') { return ((T "Asymétrie positive sur {0} piste(s) sur {1} (médiane {2}) : les intervalles longs sont relus trop longs, comme après une écriture au-dessus du niveau de précompensation qui centre les intervalles pour ce lecteur. Elle compte pour {3} point(s) du score moyen et ne change pas l'état des pistes.") -f "$($s.Pos)", "$($s.N)", $med, "$($s.Points)") }
    if ($s.Kind -eq '-') { return ((T "Asymétrie négative sur {0} piste(s) sur {1} (médiane {2}) : les intervalles longs sont relus trop courts, comme après une écriture au-dessous du niveau de précompensation qui centre les intervalles pour ce lecteur. Elle compte pour {3} point(s) du score moyen et ne change pas l'état des pistes.") -f "$($s.Neg)", "$($s.N)", $med, "$($s.Points)") }
    if ($Always) { return ((T 'médiane {0}, sans signe commun ; {1} point(s) du score moyen') -f $med, "$($s.Points)") }
    return ''
}

# Ligne du tableau de l onglet Qualite pour une piste ; $mark complete l etat (ex. « (reecrite x2) »)
function New-AlignRow([string]$lab, $m, [string]$mark, [string]$delta, [int]$deltaLvl) {
    $healthNames = @{ 0=(T 'SAIN'); 1=(T 'À SURVEILLER'); 2=(T 'CRITIQUE') }
    $healthColor = @{ 0=$script:AlColors[0]; 1=$script:AlColors[2]; 2=$script:AlColors[3] }
    $it = New-Object System.Windows.Forms.ListViewItem($lab)
    $it.UseItemStyleForSubItems = $false
    if ($m.Bad) {
        $state = if ($m.Missing) { (T 'ABSENTE') } else { (T 'ILLISIBLE') }
        foreach ($v in @(($state + $mark),'-','-','-','-','-','-','-','-')) { [void]$it.SubItems.Add([string]$v) }
        $it.SubItems[1].BackColor = $script:AlColors[3]; $it.SubItems[1].ForeColor = [System.Drawing.Color]::White; $it.SubItems[1].Font = $bold
        $it.Tag = @{ State = $(if ($m.Missing) { 'h2a' } else { 'h2' }); Score = ''; M = $m }   # 12.8 (lot 3b) : icones 16 px (DrawSubItem) ; 12.10 : M, metriques (export)
        return $it
    }
    $hl = [int]$m.Level
    $wk = if ($m.Weak) { (T ' (zone instable)') } else { '' }
    # Zone instable non jugee (controle d une copie dont la source peut porter des zones faibles) : ni SAINE ni faible
    $stTxt = if ($m.Unjudged -and $hl -eq 0) { (T 'NON JUGÉE') } else { $healthNames[$hl] }
    foreach ($v in @(($stTxt + $wk + $mark), ('{0:N1}' -f $m.Ooc), ('{0:N1}' -f $m.Dr), [string]$m.Stab, ('{0:N0}' -f $m.J), ('{0:N0}' -f $m.Score), $delta, (Format-AsymCell $m), ('{0:N0}' -f $m.Cell))) { [void]$it.SubItems.Add($v) }   # 12.11 : case « Asym. » signee
    $it.SubItems[1].BackColor = $healthColor[$hl]; $it.SubItems[1].ForeColor = $script:AlFg[$(@{0=0;1=2;2=3}[$hl])]
    if ($m.Unjudged -and $hl -eq 0) { $it.SubItems[1].BackColor = $script:AlColors[1]; $it.SubItems[1].ForeColor = $script:AlFg[1] }
    $it.SubItems[1].Font = $bold
    $lvErr = Get-AlLevel 'err' $m.Ooc;    $it.SubItems[2].BackColor = $script:AlColors[$lvErr];  $it.SubItems[2].ForeColor = $script:AlFg[$lvErr]
    $lvDr  = $(if ($m.Dr -le 0) { 0 } elseif ($m.Dr -le 1) { 2 } else { 3 }); $it.SubItems[3].BackColor = $script:AlColors[$lvDr]; $it.SubItems[3].ForeColor = $script:AlFg[$lvDr]
    $lvStb = Get-AlLevel 'stab' $m.Stab;  $it.SubItems[4].BackColor = $script:AlColors[$lvStb];  $it.SubItems[4].ForeColor = $script:AlFg[$lvStb]
    $lvJit = Get-AlLevel 'jitter' $m.J;   $it.SubItems[5].BackColor = $script:AlColors[$lvJit];  $it.SubItems[5].ForeColor = $script:AlFg[$lvJit]
    $lvSc  = Get-AlLevel 'score' $m.Score; $it.SubItems[6].BackColor = $script:AlColors[$lvSc];  $it.SubItems[6].ForeColor = $script:AlFg[$lvSc]
    if ($deltaLvl -ge 0) { $it.SubItems[7].BackColor = $script:AlColors[$deltaLvl]; $it.SubItems[7].ForeColor = $script:AlFg[$deltaLvl] }
    $lvAs  = Get-AlLevel 'asym' $m.Asym;  $it.SubItems[8].BackColor = $script:AlColors[$lvAs];   $it.SubItems[8].ForeColor = $script:AlFg[$lvAs]
    # 12.8 (lot 3b, D15) : icone d etat (colonne Etat) et icone de score (colonne Score), 16 px, dessinees par DrawSubItem
    $it.Tag = @{ State = $(if ($m.Unjudged -and $hl -eq 0) { 'hq' } else { "h$hl" }); Score = "q$lvSc"; M = $m }   # 12.10 : M, metriques de la piste (export du tableau)
    return $it
}

# 12.10 : export du tableau de l onglet Qualite (demande du 01/11/2026 : relever les resultats par piste sans capture
# d ecran). En-tete (libelle, valeur) d apres $script:QualView, puis les colonnes de l ecran et deux de plus : les ecarts
# signes des rapports moyens 3T/2T et 4T/2T a leurs valeurs nominales (1,5 et 2), dont « Asym. » est la somme des valeurs
# absolues ; le signe dit si les intervalles longs sont relus trop longs (+) ou trop courts (-). Valeurs relues dans
# Item.Tag.M (metriques de la piste gardees par New-AlignRow) et ecrites sans separateur de milliers, avec le separateur
# decimal de la langue du poste ; sans Tag.M, texte affiche tel quel
function Get-AlignTableExport {
    $v = $script:QualView
    $r = $v.Res
    $head = New-Object System.Collections.Generic.List[object]
    $head.Add(@((T 'Application'), "Greaseweazle Studio $($script:Version)"))
    $head.Add(@((T 'Export'), (Get-Date -Format 'dd/MM/yyyy HH:mm:ss')))
    $at = if ($v.At) { ([datetime]$v.At).ToString('dd/MM/yyyy HH:mm:ss') } else { '' }
    $kind = switch ([string]$v.Kind) { 'measure' { (T 'Mesure de la disquette') } 'check' { (T 'Contrôle après écriture') } default { '' } }
    if ($v.State -eq 'stale') {
        $kind = (($kind + ' ' + (T '(périmé)')).Trim())
        $why = Get-QualStaleText ([string]$v.Reason) $at
        if ($why) { $kind += " : $why" }
    }
    $head.Add(@((T 'Résultat'), $kind))
    $head.Add(@((T 'Heure du résultat'), $at))
    $ctx = if ($r -and $r.Ctx) { $r.Ctx } else { $null }
    $drive = if ($ctx -and $ctx.Drive) { [string]$ctx.Drive } else { [string]$cmbDrive.Text }
    $head.Add(@((T 'Lecteur'), $drive))
    if ($ctx) { $head.Add(@((T 'Têtes'), [string]$ctx.Heads)); $head.Add(@((T 'Tours'), [string]$ctx.Revs)) }
    if ($r -and $r.HealthText) { $head.Add(@((T 'État du support'), [string]$r.HealthText)) }
    if ($r -and $r.ScoreText) { $head.Add(@((T 'Score'), [string]$r.ScoreText)) }
    if ($script:AlignRefLabel) { $head.Add(@((T 'Référence'), [string]$script:AlignRefLabel)) }
    $cols = @((T 'Piste'), (T 'État'), (T 'Erreurs/tour'), (T 'Trous/tour'), (T 'Stabilité'), (T 'Jitter ns'), 'Score', (T 'vs réf'), 'Asym.', (T 'Écart 3T'), (T 'Écart 4T'), (T 'Cellule ns'))
    $rows = New-Object System.Collections.Generic.List[object]
    foreach ($it in @($lvAl.Items)) {
        $m = if ($it.Tag -is [hashtable] -and $it.Tag.ContainsKey('M')) { $it.Tag.M } else { $null }
        $sub = @(0..9 | ForEach-Object { if ($_ -lt $it.SubItems.Count) { [string]$it.SubItems[$_].Text } else { '' } })
        if ($m -and -not $m.Bad) {
            $rows.Add(@($sub[0], $sub[1], ('{0:0.0}' -f [double]$m.Ooc), ('{0:0.0}' -f [double]$m.Dr), ('{0:0}' -f [double]$m.Stab), ('{0:0}' -f [double]$m.J),
                       ('{0:0}' -f [double]$m.Score), $sub[7], ('{0:0.000}' -f [double]$m.Asym), ('{0:+0.000;-0.000;0.000}' -f ([double]$m.R3 - 1.5)),
                       ('{0:+0.000;-0.000;0.000}' -f ([double]$m.R4 - 2.0)), ('{0:0}' -f [double]$m.Cell)))
        } else {
            $rows.Add(@($sub[0], $sub[1], $sub[2], $sub[3], $sub[4], $sub[5], $sub[6], $sub[7], $sub[8], '-', '-', $sub[9]))
        }
    }
    # 12.11 : ligne « Asymetrie » toujours presente : resume de Get-AsymSummary sur les metriques des lignes (Tag.M), forme
    # courte sans signe commun, « - » sans piste lisible (la correction retiree n ecrivait cette ligne que si elle agissait)
    $asym = Get-AsymSummaryText (Get-AsymSummary @(@($lvAl.Items) | ForEach-Object { if ($_.Tag -is [hashtable] -and $_.Tag.ContainsKey('M')) { $_.Tag.M } })) -Always
    $head.Add(@((T 'Asymétrie'), $(if ($asym) { $asym } else { '-' })))
    $head.Add(@((T 'Pistes'), [string]$rows.Count))
    # .ToArray() et non @() : sous PowerShell 7, @() sur une List[object] d elements tableaux echoue (liaison dynamique)
    return @{ Head = $head.ToArray(); Cols = $cols; Rows = $rows.ToArray() }
}

function Format-CsvField([string]$s, [string]$sep) {
    # Champ entre guillemets (guillemets doubles) s il contient le separateur, un guillemet ou un saut de ligne (RFC 4180)
    if ($s.IndexOf($sep) -ge 0 -or $s.IndexOf('"') -ge 0 -or $s.IndexOf("`n") -ge 0 -or $s.IndexOf("`r") -ge 0) { return '"' + $s.Replace('"', '""') + '"' }
    return $s
}

function ConvertTo-AlignTableText($x, [string]$sep) {
    # Une ligne par entree de l en-tete (libelle, valeur), puis la ligne des colonnes, puis une ligne par piste ; CRLF
    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($h in $x.Head) { $lines.Add((@($h | ForEach-Object { Format-CsvField ([string]$_) $sep }) -join $sep)) }
    $lines.Add((@($x.Cols | ForEach-Object { Format-CsvField ([string]$_) $sep }) -join $sep))
    foreach ($r in $x.Rows) { $lines.Add((@($r | ForEach-Object { Format-CsvField ([string]$_) $sep }) -join $sep)) }
    return (($lines -join "`r`n") + "`r`n")
}

function Get-AlignTableSep([string]$path) {
    # Tabulation pour un fichier .txt ; sinon le separateur de liste de la langue du poste (« ; » en francais, « , » en
    # anglais), celui que le tableur du poste attend dans un .csv
    if ($path -and $path -match '\.txt$') { return "`t" }
    $s = [System.Globalization.CultureInfo]::CurrentCulture.TextInfo.ListSeparator
    if (-not $s) { $s = ';' }
    return $s
}

function Export-AlignTable([string]$path) {
    # Fichier UTF-8 avec BOM (accents lus par le tableur) ; rend le nombre de pistes ecrites, 0 sans tableau
    $x = Get-AlignTableExport
    if ($x.Rows.Count -eq 0) { Append-Log (T 'Qualité : aucun tableau à exporter (lancez une mesure ou un contrôle).'); return 0 }
    [System.IO.File]::WriteAllText($path, (ConvertTo-AlignTableText $x (Get-AlignTableSep $path)), (New-Object System.Text.UTF8Encoding($true)))
    Append-Log ((T "Qualité : tableau de {0} piste(s) exporté dans {1}.") -f "$($x.Rows.Count)", "$path")
    return $x.Rows.Count
}

function Copy-AlignTable {
    # Presse-papiers, champs separes par des tabulations : se colle tel quel dans un tableur ou un message
    $x = Get-AlignTableExport
    if ($x.Rows.Count -eq 0) { Append-Log (T 'Qualité : aucun tableau à copier (lancez une mesure ou un contrôle).'); return 0 }
    [System.Windows.Forms.Clipboard]::SetText((ConvertTo-AlignTableText $x "`t"))
    Append-Log ((T "Qualité : tableau de {0} piste(s) copié dans le presse-papiers.") -f "$($x.Rows.Count)")
    return $x.Rows.Count
}

function Set-UnstableBanner([string[]]$parts) {
    # Bandeau orange des zones instables (onglet Qualite) ; vide : efface un bandeau orange reste d une mesure precedente,
    # sauf pendant le guide d alignement qui utilise la meme ligne
    $parts = @($parts | Where-Object { $_ })
    if ($parts.Count -gt 0) {
        $lblAlReco.Text = ($parts -join '   |   '); $lblAlReco.ForeColor = 'DarkOrange'; $lblAlReco.Visible = $true
        $script:UnstableBannerText = $lblAlReco.Text
    } elseif ($script:UnstableBannerText -and $lblAlReco.Text -eq $script:UnstableBannerText) { $lblAlReco.Text = ''; $script:UnstableBannerText = $null }
    elseif (-not $chkAlGuide.Checked -and $lblAlReco.ForeColor -eq [System.Drawing.Color]::DarkOrange) { $lblAlReco.Text = '' }
}

function Get-UnstableClusters([string[]]$keys, [int]$minRun = 3) {
    # Suites d au moins $minRun cylindres consecutifs instables sur une meme face (« c58-c61 tete 1 ») : une rayure ou une
    # usure touche des pistes voisines, une protection a bits faibles tient en general sur une piste isolee
    $out = @()
    foreach ($h in 0, 1) {
        $cs = @($keys | Where-Object { $_ -match "^\d+\.$h$" } | ForEach-Object { [int](($_ -split '\.')[0]) } | Sort-Object -Unique)
        $i = 0
        while ($i -lt $cs.Count) {
            $j = $i
            while ($j + 1 -lt $cs.Count -and $cs[$j + 1] -eq $cs[$j] + 1) { $j++ }
            if ($j - $i + 1 -ge $minRun) { $out += ((T "c{0}-c{1} tête {2}") -f "$($cs[$i])", "$($cs[$j])", "$h") }
            $i = $j + 1
        }
    }
    return $out
}

function Invoke-AlignAnalysis {
    # 12.8 (lot 3a) : analyse impossible : resultat affiche declare perime (ou carte vide avec la raison)
    if (-not $script:AlignTmp -or -not (Test-Path -LiteralPath $script:AlignTmp)) {
        Append-Log (T 'Mesure : fichier SCP absent, analyse impossible.'); $script:AlignLoop = $false; Set-QualityStale 'noscp'; return
    }
    try { $tracks = Read-ScpFile $script:AlignTmp } catch { Append-Log ((T "Mesure : {0}") -f "$($_.Exception.Message)"); $script:AlignLoop = $false; Set-QualityStale 'noscp'; return }

    $last = @{}; $watch = @(); $crit = @(); $weakL = @(); $critK = @(); $nBad = 0
    $res = @{ Kind = 'measure'; Score = $null; Lvl = 3; Count = 0; Bad = 0; Health = 0; NTracks = 0; WatchKeys = @(); CritKeys = @()
              HealthText = ''; ScoreText = ''; Prev = $null; Best = $null; RefAvg = $null; AsymText = '' }
    $lvAl.Columns[1].Width = 222                          # 12.8 (lot 3b) : icone d etat de 16 px devant le texte
    $lvAl.BeginUpdate()
    try {
        $lvAl.Items.Clear()
        $total = 0.0; $count = 0; $zo = 0; $zt = 0; $zf = 0; $fb = @(); $so = 0; $sot = 0; $sov = @()   # 12.10 (S13) : so / sot / sov
        $ams = New-Object System.Collections.Generic.List[object]     # 12.11 : metriques des pistes, pour le resume de l asymetrie
        foreach ($tn in ($tracks.Keys | Sort-Object)) {
            $st = $tracks[$tn]; $cyl = [math]::Floor($tn / 2); $hd = $tn % 2; $key = "$cyl.$hd"
            $lab = "$cyl.$hd"
            $m = Get-TrackMetrics $st
            $ams.Add($m)
            if ($m.ZoneOoc -gt 0) { $zo += $m.ZoneOoc; $zt++; if ($m.ZoneFarNs -gt $zf) { $zf = $m.ZoneFarNs } }
            if ($m.StructOoc -gt 0) { $so += $m.StructOoc; $sot++ }
            if ($m.StructOver -gt 0) { $sov += $lab }
            if ($m.StabFallback) { $fb += $lab }
            if ($m.Bad) {
                [void]$lvAl.Items.Add((New-AlignRow $lab $m '' '-' -1))
                $last[$key] = @{ Score = 9999; Jitter = 0; Asym = 0; Err = 0; Stab = 0; Cell = 0 }
                $crit += ((T "{0} (illisible)") -f "$lab"); $critK += $lab; $nBad++; continue
            }
            # Zone instable : la piste ne se relit pas pareil d un tour a l autre, elle n est pas propre (protection ou
            # defaut du support, l application ne peut pas trancher sur une disquette inconnue) : au moins A SURVEILLER
            if ($m.Weak -and $m.Level -lt 1) { $m.Level = 1 }
            $sc = $m.Score
            # 12.10 (lot 1, D8) : meilleur score par piste retire avec le graphique, seul a le lire ; meilleur global garde
            $last[$key] = @{ Score = $sc; Jitter = $m.J; Asym = $m.Asym; Err = $m.Ooc; Stab = $m.Stab; Cell = $m.Cell }
            $hl = $m.Level
            if ($m.Weak) { $weakL += $lab }
            if ($hl -eq 1) { $watch += $lab } elseif ($hl -eq 2) { $crit += ((T "{0} ({1} err/tour)") -f "$lab", "$([math]::Round($m.Ooc,0))"); $critK += $lab }

            $delta = '-'; $deltaLvl = -1
            if ($script:AlignRef -and $script:AlignRef.ContainsKey($key) -and $script:AlignRef[$key].Score -gt 0) {
                $pct = ($sc - $script:AlignRef[$key].Score) / $script:AlignRef[$key].Score * 100
                $delta = ('{0:+0;-0;0} %' -f $pct); $deltaLvl = Get-AlLevel 'delta' $pct
            }
            [void]$lvAl.Items.Add((New-AlignRow $lab $m '' $delta $deltaLvl))
            $total += $sc; $count++
        }
        $script:AlignLast = $last
        # 12.11 : resume de l asymetrie (Get-AsymSummary : signe commun, part du score moyen) pour l infobulle de la carte et
        # le journal (apres le score moyen) ; l en-tete de l export le recalcule sur les lignes du tableau, meme fonction
        $res.AsymText = Get-AsymSummaryText (Get-AsymSummary $ams)
        $nTracks = $tracks.Count

        # --- Verdict 1 : etat du support (12.8, lot 3b : carte de resultat ; texte complet dans l infobulle et le journal)
        $res.NTracks = $nTracks; $res.WatchKeys = @($watch); $res.CritKeys = @($critK); $res.Bad = $nBad
        if ($crit.Count -gt 0) {
            $res.Health = 2; $res.HealthText = ((T "SUPPORT CRITIQUE  -  {0} piste(s) en erreur : {1}   ->  dump flux immédiat conseillé") -f "$($crit.Count)", "$($crit -join ', ')")
        } elseif ($watch.Count -gt 0) {
            $res.Health = 1; $res.HealthText = ((T "SUPPORT À SURVEILLER  -  {0}/{1} piste(s) marginale(s) : {2}   ->  dump flux recommandé") -f "$($watch.Count)", "$nTracks", "$($watch -join ', ')")
        } else {
            $res.Health = 0; $res.HealthText = ((T "SUPPORT SAIN  -  {0}/{1} pistes propres (erreurs, trous, stabilité, jitter dans les normes)") -f "$nTracks", "$nTracks")
        }
        Append-Log ((T "Mesure : {0}") -f "$($res.HealthText)")
        # 12.8.2 (S11, S12) : hors classe du raccord ecartes (distance a l index la plus grande), pistes sans tours alignes ;
        # mesure continue : a la premiere passe seulement (revue : le compte change a chaque relecture)
        if (-not $script:AlignLoop -or [int]$script:QualView.Pass -le 1) {
            if ($zo -gt 0) { Append-Log ((T "Mesure : {0} intervalle(s) hors classe du raccord d'écriture, dans la zone de ± 1 ms autour de l'index (jusqu'à {2} ms), non compté(s), sur {1} piste(s).") -f "$zo", "$zt", (Format-UiNum ($zf / 1e6) '0.00')) }
            if ($fb.Count -gt 0) { Append-Log ((T "Mesure : stabilité de {0} piste(s) jugée sur l'écart du nombre de flux entre les tours, faute de repère commun pour les aligner : {1}.") -f "$($fb.Count)", "$($fb -join ', ')") }
            # 12.10 (S13) : raccord d ecriture d une longue piste, protection a intervalles fixes, petit defaut fixe du
            # support ; pistes au-dela du plafond ScpStructMax par tour : tout compte, liste a part
            if ($so -gt 0) { Append-Log ((T "Mesure : {0} intervalle(s) hors classe reproductibles d'un tour à l'autre à la même position, sur {1} piste(s), non compté(s) : raccord d'écriture d'une longue piste ou protection ; un petit défaut fixe du support (jusqu'à {2} intervalles par tour) y passerait aussi.") -f "$so", "$sot", "$($script:ScpStructMax)") }
            if ($sov.Count -gt 0) { Append-Log ((T "Mesure : {0} piste(s) avec plus de {1} intervalles hors classe reproductibles par tour, tous comptés comme erreurs (au-delà d'un raccord d'écriture ou d'une protection : défaut du support ou écriture à revoir) : {2}.") -f "$($sov.Count)", "$($script:ScpStructMax)", "$(Format-TrackList $sov)") }
        }
        if ($weakL.Count -gt 0) { Append-Log ((T "Mesure : zone instable d'un tour à l'autre sur {0} piste(s) : {1}. Bits faibles d'une protection contre la copie probable, ou défaut localisé du support : une copie faite depuis un flux n'en écrit qu'un tour et ne les reproduit pas fidèlement.") -f "$($weakL.Count)", "$($weakL -join ', ')") }
        $clu = @(Get-UnstableClusters $weakL)
        if ($clu.Count -gt 0) { Append-Log ((T "Mesure : pistes instables sur des cylindres voisins d'une même face ({0}) : défaut du support probable (rayure, usure) plutôt qu'une protection.") -f "$($clu -join ', ')") }

        # --- Verdict 2 : score de lecture
        if ($count -gt 0) {
            $avg = [math]::Round($total / $count, 0)
            if (-not $script:AlignBest.ContainsKey('_global') -or $avg -lt $script:AlignBest['_global']) { $script:AlignBest['_global'] = $avg }
            $trend = ''
            if ($null -ne $script:AlignPrev) {
                if ($avg -lt $script:AlignPrev - 2) { $trend = (T '   MIEUX (v)') } elseif ($avg -gt $script:AlignPrev + 2) { $trend = (T '   MOINS BIEN (^)') } else { $trend = (T '   stable') }
            }
            $res.Prev = $script:AlignPrev
            $script:AlignPrev = $avg
            $lvlAvg = Get-AlLevel 'score' $avg
            $refTxt = ''
            if ($script:AlignRef) {
                $refScores = @($script:AlignRef.Values | ForEach-Object { $_.Score } | Where-Object { $_ -lt 9999 })
                if ($refScores.Count -gt 0) { $refAvg = [math]::Round(($refScores | Measure-Object -Average).Average, 0); $refTxt = ((T "   |   référence {0}") -f "$refAvg"); $res.RefAvg = $refAvg }
            }
            $res.Score = $avg; $res.Lvl = $lvlAvg; $res.Count = $count; $res.Best = $script:AlignBest['_global']
            $res.ScoreText = ((T "Qualité de lecture : score {0} - {1}{2}{3}   |   meilleur {4}") -f "$avg", "$($script:AlNames[$lvlAvg])", "$trend", "$refTxt", "$($script:AlignBest['_global'])")
            Append-Log ((T "Mesure : score moyen {0} ({1}){2}") -f "$avg", "$($script:AlNames[$lvlAvg])", "$trend")
            # 12.11 : phrase de l asymetrie ; mesure continue : a la premiere passe seulement, comme les lignes du raccord
            if ($res.AsymText -and (-not $script:AlignLoop -or [int]$script:QualView.Pass -le 1)) { Append-Log ((T "Mesure : {0}") -f $res.AsymText) }
            Update-AlignGuide $avg
            $bn = if ($weakL.Count -gt 0) { ((T "Zone instable d'un tour à l'autre (protection contre la copie ou défaut du support) : {0}") -f "$($weakL -join ', ')") + $(if ($clu.Count -gt 0) { (T " ; cylindres voisins {0} : défaut du support probable") -f "$($clu -join ', ')" } else { '' }) } else { '' }
            Set-UnstableBanner @($bn)
        } else {
            $res.ScoreText = (T 'Aucune piste analysable')
            Set-UnstableBanner @('')                      # 12.8 (FIX3) : bandeau d une mesure precedente retire
        }
    } finally { $lvAl.EndUpdate() }
    Set-QualityResult $res                                # 12.8 (lot 3a) : carte et tableau en couleurs (12.9 : sans graphique)

    if ($script:AlignLoop) { $script:AlignNextAt = (Get-Date).AddSeconds([int]$numAlPause.Value) }
}
# ============================== FONCTIONS : MARGE COMPTEE DES FLUX ==============

# 12.8.1 (lot A, spec-1281.md § B.1) : marge fixe Mfix d une piste relue, pour la mesure de la disquette sur l image (276).
# Les intervalles d un tour (ns, multiples de la resolution du SCP, ScpStats.Decode) sont tries une fois (tri natif, sur
# une copie) ; chaque comptage est une recherche dichotomique native (Array.BinarySearch) sur une cle entiere decalee,
# jamais egale a un element. Horloge fixe du tour : T0 = duree / cellules de l image (ncell0, Get-PatternBits), sauf a plus
# de 5 % de la cellule des 2T (comme ScpStats.Analyze sans motif) ; cellules du tour = somme des arrondis f / T0, une
# recherche par classe ; T = duree / cellules. Marge d un intervalle de classe 2 a 4 : (1/2 - |f/T - k|) T, nulle hors de
# [1,5 T ; 4,5 T[ ; Mfix = quantile 1e-3 des marges des tours regroupes (rang exact, comme rpm_analyse.q1e3), par
# dichotomie sur m. Reference executable : v1281\verif_spec1281.py (ecart de 9,3e-7 ns a rpm_analyse sur 240 pistes
# reelles). Aucun Add-Type ni boucle sur les octets : Decode (C#) reste la seule conversion d octets en intervalles.

function Get-ScpRevTable([byte[]]$d) {
    # Table des tours d un SCP deja lu (memes champs que Read-ScpFile, 190) : resolution (ns par tic), tours par piste et,
    # par numero de piste, la liste des tours @{ Off (octet des donnees) ; Len (mots de 16 bits) ; DurNs (index x res) }.
    # Piste absente (decalage nul), en-tete de piste ou tour hors du fichier : ignores. $null : fichier trop court ou
    # sans signature SCP. Sans type C# : testable au niveau 2 du banc (logic-1281.ps1)
    if ($null -eq $d -or $d.Length -lt 16 + 4 * 168 -or [System.Text.Encoding]::ASCII.GetString($d, 0, 3) -ne 'SCP') { return $null }
    $revs = [int]$d[5]; $res = ([int]$d[11] + 1) * 25
    $tracks = @{}
    for ($t = 0; $t -lt 168; $t++) {
        [int64]$o = [BitConverter]::ToUInt32($d, 16 + 4 * $t)
        if ($o -eq 0 -or $o + 4 + 12 * $revs -gt $d.Length -or [System.Text.Encoding]::ASCII.GetString($d, [int]$o, 3) -ne 'TRK') { continue }
        $list = @()
        for ($r = 0; $r -lt $revs; $r++) {
            [int64]$idx  = [BitConverter]::ToUInt32($d, [int]($o + 4 + 12 * $r))
            [int64]$ln   = [BitConverter]::ToUInt32($d, [int]($o + 8 + 12 * $r))
            [int64]$doff = [BitConverter]::ToUInt32($d, [int]($o + 12 + 12 * $r))
            if ($o + $doff + 2 * $ln -gt $d.Length) { continue }
            $list += @{ Off = [int]($o + $doff); Len = [int]$ln; DurNs = [double]$idx * $res }
        }
        $tracks[[int]$d[$o + 3]] = $list
    }
    return @{ Res = $res; Revs = $revs; Tracks = $tracks }
}

function Read-ScpTrackRevs([string]$path) {
    # Tours bruts de chaque piste d un SCP (relecture de la mesure sur l image) : memes lectures que Read-ScpFile (190),
    # sans Analyze ni Instability. Sortie : @{ Res ; Revs ; Tracks = @{ numero de piste -> List[object] des tours
    # @{ Flux = [int[]] (ns) ; DurNs } } } ; $null : fichier trop court ou sans signature SCP
    $d = [System.IO.File]::ReadAllBytes($path)
    $tt = Get-ScpRevTable $d
    if ($null -eq $tt) { return $null }
    $tracks = @{}
    foreach ($tn in @($tt.Tracks.Keys)) {
        $l = New-Object 'System.Collections.Generic.List[object]'
        foreach ($rv in @($tt.Tracks[$tn])) { $l.Add(@{ Flux = [ScpStats]::Decode($d, [int]$rv.Off, [int]$rv.Len, [int]$tt.Res); DurNs = [double]$rv.DurNs }) }
        $tracks[$tn] = $l
    }
    return @{ Res = $tt.Res; Revs = $tt.Revs; Tracks = $tracks }
}

function Get-SortedCountLe([int[]]$s, [double]$y, [int]$res) {
    # #{f <= y} dans le tableau trie : cle floor(y/res)*res + 1, jamais egale a un element (multiples de res)
    $key = [math]::Floor($y / $res) * $res + 1
    if ($key -ge [int]::MaxValue) { return $s.Length }
    if ($key -le 0) { return 0 }
    $r = [Array]::BinarySearch($s, [int]$key)    # [int] obligatoire : une cle Int64 ferait echouer le comparateur
    return (-$r - 1)
}

function Get-SortedCountLt([int[]]$s, [double]$y, [int]$res) {
    # #{f < y} dans le tableau trie : cle ceil(y/res)*res - 1
    $key = [math]::Ceiling($y / $res) * $res - 1
    if ($key -ge [int]::MaxValue) { return $s.Length }
    if ($key -lt 0) { return 0 }
    $r = [Array]::BinarySearch($s, [int]$key)
    return (-$r - 1)
}

function Get-FluxRevPrep([int[]]$flux, [double]$durNs, [int]$res, [int]$ncell0, [double]$t0Tol = 0.05) {
    # Tour prepare : intervalles tries (S), horloge fixe T0 (duree / ncell0, ou cellule des 2T a plus de t0Tol d ecart :
    # piste d une autre longueur, faux gw du banc), cellules, T, intervalles hors classe Z (hors de [1,5 T ; 4,5 T[) et
    # rangs des bornes 1,5 T et 4,5 T. $null : moins de 3 intervalles, duree ou cellules nulles, plus de 4 096 classes
    if ($null -eq $flux -or $flux.Length -lt 3 -or $durNs -le 0 -or $ncell0 -le 0) { return $null }
    $s = [int[]]$flux.Clone(); [Array]::Sort($s)                       # tri natif, copie : le flux de Decode reste intact
    $n = $s.Length
    $t0 = $durNs / $ncell0; $src = 'duree'
    # Cellule des 2T, comme ScpStats.Analyze a cellsPerRev = 0 : element de rang floor(n2/2) des intervalles de 3 000 a
    # 5 000 ns exclus, divise par 2, si n2 >= 50
    $a = Get-SortedCountLe $s 3000.0 $res; $b = Get-SortedCountLt $s 5000.0 $res
    if ($b - $a -ge 50) {
        $med = [double]$s[$a + [int][math]::Floor(($b - $a) / 2)] / 2.0
        if ([math]::Abs($t0 / $med - 1.0) -gt $t0Tol) { $t0 = $med; $src = 'mediane' }
    }
    # Cellules = somme des arrondis f/T0 (classe k : (k - 1/2) T0 <= f < (k + 1/2) T0), une recherche par classe non vide :
    # k = classe du plus petit intervalle restant, tous les intervalles de cette classe comptes d un coup
    [int64]$cells = 0
    $lo = Get-SortedCountLt $s (0.5 * $t0) $res
    $g = 0
    while ($lo -lt $n -and $g -lt 4096) {
        $k = [math]::Floor($s[$lo] / $t0 + 0.5)
        $hi = Get-SortedCountLt $s (($k + 0.5) * $t0) $res
        $cells += [int64]$k * ($hi - $lo); $lo = $hi; $g++
    }
    if ($lo -lt $n -or $cells -le 0) { return $null }                 # plus de 4 096 classes : bruit, piste vide
    $T = $durNs / $cells
    $lt15 = Get-SortedCountLt $s (1.5 * $T) $res; $lt45 = Get-SortedCountLt $s (4.5 * $T) $res
    return @{ S = $s; N = $n; T = $T; T0 = $t0; T0Src = $src; Cells = $cells; Z = [int64]($lt15 + ($n - $lt45)); Lt15 = $lt15; Lt45 = $lt45 }
}

function Get-FluxMarginCount($r, [double]$m, [int]$res) {
    # Nombre d intervalles de marge <= m dans le tour prepare $r : marge nulle (Z), puis les quatre fenetres de demi-largeur
    # m autour des limites de decodage 1,5 T, 2,5 T, 3,5 T et 4,5 T (disjointes tant que m < T/2)
    $s = $r.S; $T = [double]$r.T
    [int64]$c = $r.Z                                                              # marge nulle
    $c += (Get-SortedCountLe $s (1.5 * $T + $m) $res) - $r.Lt15                   # au-dessus de 1,5 T
    $c += $r.Lt45 - (Get-SortedCountLt $s (4.5 * $T - $m) $res)                   # au-dessous de 4,5 T
    $c += (Get-SortedCountLe $s (2.5 * $T + $m) $res) - (Get-SortedCountLt $s (2.5 * $T - $m) $res)
    $c += (Get-SortedCountLe $s (3.5 * $T + $m) $res) - (Get-SortedCountLt $s (3.5 * $T - $m) $res)
    return $c
}

function Get-FluxMarginQ($preps, [int]$res, [double]$q = 1e-3, [double]$tol = 1e-6, [int]$maxIt = 50) {
    # Quantile q de la marge sur les tours regroupes, rang exact : (k + 1)-ieme plus petite marge, k = floor(q n), comme
    # rpm_analyse.q1e3 ; dichotomie sur m dans [0 ; T/2[ (les quatre fenetres ne se recouvrent pas tant que m < T/2).
    # Sortie : Mfix (0 si les marges nulles suffisent au rang, NaN sans tour), N, Z, K (rang), It (iterations)
    $rs = @($preps | Where-Object { $null -ne $_ })
    if ($rs.Count -eq 0) { return @{ Mfix = [double]::NaN; N = 0; Z = 0; K = 0; It = 0 } }
    [int64]$n = 0; [int64]$z = 0; $tMax = 0.0
    foreach ($r in $rs) { $n += $r.N; $z += $r.Z; if ([double]$r.T -gt $tMax) { $tMax = [double]$r.T } }
    [int64]$k = [math]::Floor($q * $n)
    [int64]$c0 = 0; foreach ($r in $rs) { $c0 += Get-FluxMarginCount $r 0.0 $res }
    if ($c0 -ge $k + 1) { return @{ Mfix = 0.0; N = $n; Z = $z; K = $k; It = 0 } }
    $lo = 0.0; $hi = 0.5 * $tMax; $it = 0
    while (($hi - $lo) -gt $tol -and $it -lt $maxIt) {
        $mid = ($lo + $hi) / 2; [int64]$c = 0
        foreach ($r in $rs) { $c += Get-FluxMarginCount $r $mid $res }
        if ($c -ge $k + 1) { $hi = $mid } else { $lo = $mid }
        $it++
    }
    return @{ Mfix = $hi; N = $n; Z = $z; K = $k; It = $it }
}

function Get-ContentTrackStats($revs, [int]$res, [int]$ncell0) {
    # Bilan d une piste relue (ses tours, Read-ScpTrackRevs) : tours exploitables (Get-FluxRevPrep), marge fixe Mfix de
    # leurs intervalles regroupes, intervalles N et hors classe Z (marge nulle), cellules et intervalles par tour, T moyen,
    # iterations de la dichotomie ; T0Src : origine de l horloge de chaque tour ('duree' ou 'mediane'). Sans tour
    # exploitable : NRev = 0, Mfix = NaN
    $preps = New-Object 'System.Collections.Generic.List[object]'
    foreach ($rv in $revs) {
        if ($null -eq $rv -or $null -eq $rv.Flux) { continue }
        $p = Get-FluxRevPrep ([int[]]$rv.Flux) ([double]$rv.DurNs) $res $ncell0
        if ($null -ne $p) { $preps.Add($p) }
    }
    if ($preps.Count -eq 0) { return @{ NRev = 0; Mfix = [double]::NaN; N = [int64]0; Z = [int64]0; ZFrac = [double]::NaN; Cells = [int64[]]@(); Flux = [int[]]@(); T = [double]::NaN; It = 0; T0Src = [string[]]@() } }
    $mq = Get-FluxMarginQ $preps $res
    $sumT = 0.0; foreach ($p in $preps) { $sumT += [double]$p.T }
    return @{ NRev = $preps.Count; Mfix = [double]$mq.Mfix; N = [int64]$mq.N; Z = [int64]$mq.Z; ZFrac = [double]$mq.Z / [double]$mq.N
              Cells = [int64[]]@($preps | ForEach-Object { [int64]$_.Cells }); Flux = [int[]]@($preps | ForEach-Object { [int]$_.N })
              T = $sumT / $preps.Count; It = [int]$mq.It; T0Src = [string[]]@($preps | ForEach-Object { [string]$_.T0Src }) }
}
# ============================== FONCTIONS : QUALITE, AFFICHAGE (12.8, LOT 3) ===
# Etat unique de l affichage de l onglet Qualite & alignement ($script:QualView, A2 § 2.2) : vide, en cours, resultat,
# perime ; jamais efface pendant une mesure, mais grise et marque (D16). Carte de resultat de la variante A (D14), dessinee
# dans un bitmap (fond de pnlQualCard) : pas de grisage des libelles quand Set-Busy desactive les onglets, pas de
# clignotement en mesure continue. Pictogrammes de score (barres de signal) et d etat (coche, !, croix) en GDI+ (D15),
# couleurs Theme.Ok / Good / WarnInk / Danger (D17). Ressources GDI+ (pinceaux, stylos, polices, formats, icones) en cache
# dans $script:QualGdi, liberees a la fermeture de la fenetre (Clear-QualityGdi).

# --- Ressources GDI+ en cache -----------------------------------------------------------------------------------------
function Get-QualBrush([System.Drawing.Color]$c) {
    $k = 'b' + $c.ToArgb()
    $o = $script:QualGdi[$k]
    if (-not $o) { $o = New-Object System.Drawing.SolidBrush($c); $script:QualGdi[$k] = $o }
    return $o
}

function Get-QualPen([System.Drawing.Color]$c, [single]$w = 1) {
    $k = 'p' + $c.ToArgb() + '|' + $w
    $o = $script:QualGdi[$k]
    if (-not $o) { $o = New-Object System.Drawing.Pen($c, $w); $script:QualGdi[$k] = $o }
    return $o
}

function Get-QualFont([string]$fam, [single]$size, [string]$style = 'Regular') {
    $k = "f$fam|$size|$style"
    $o = $script:QualGdi[$k]
    if (-not $o) { $o = New-Object System.Drawing.Font($fam, $size, [System.Drawing.FontStyle]$style); $script:QualGdi[$k] = $o }
    return $o
}

function Get-QualSf([string]$kind) {
    # Formats du tableau : 'near' / 'center' (cellules : une ligne, points de suspension), 'hnear' / 'hcenter' (en-tetes)
    $k = "s$kind"
    $o = $script:QualGdi[$k]
    if (-not $o) {
        $o = New-Object System.Drawing.StringFormat
        $o.LineAlignment = [System.Drawing.StringAlignment]::Center
        $o.Alignment = $(if ($kind -match 'near$') { [System.Drawing.StringAlignment]::Near } else { [System.Drawing.StringAlignment]::Center })
        if ($kind -notmatch '^h') { $o.FormatFlags = [System.Drawing.StringFormatFlags]::NoWrap; $o.Trimming = [System.Drawing.StringTrimming]::EllipsisCharacter }
        $script:QualGdi[$k] = $o
    }
    return $o
}

function Clear-QualityGdi {
    # Fermeture de la fenetre : pinceaux, stylos, polices, formats et icones du cache, bitmap de la carte
    foreach ($o in @($script:QualGdi.Values)) { try { $o.Dispose() } catch { } }
    $script:QualGdi.Clear()
    if ($pnlQualCard -and $pnlQualCard.BackgroundImage) { $b = $pnlQualCard.BackgroundImage; $pnlQualCard.BackgroundImage = $null; $b.Dispose() }
}

# --- Couleurs et noms des niveaux -------------------------------------------------------------------------------------
function Get-QualLevelColor([int]$lvl) {
    # Couleur d un niveau de score (barres, bord de la carte) : EXCELLENT Ok, BON Good, MOYEN WarnInk, MAUVAIS Danger (D17)
    switch ($lvl) { 0 { return $script:Theme.Ok } 1 { return $script:Theme.Good } 2 { return $script:Theme.WarnInk } default { return $script:Theme.Danger } }
}

function Get-QualInk([int]$lvl) {
    # Encre du texte d un niveau sur fond blanc ou teinte (contraste >= 4,5:1, WCAG 2.1 SC 1.4.3) : vert 20,90,45 (8,3:1),
    # vert-jaune 62,96,26 (7,3:1), Theme.WarnInk (5,3:1), rouge 140,30,25 (9,1:1)
    switch ($lvl) {
        0 { return [System.Drawing.Color]::FromArgb(20, 90, 45) }
        1 { return [System.Drawing.Color]::FromArgb(62, 96, 26) }
        2 { return $script:Theme.WarnInk }
        default { return [System.Drawing.Color]::FromArgb(140, 30, 25) }
    }
}

function Get-QualDimInk {
    # 12.8 (FIX3) : encre grise du texte secondaire pose sur une teinte (carte en cours ou perimee, tableau grise, lignes
    # paires 243,246,250) : 100,106,118, contraste >= 4,5:1 (4,78:1 sur la teinte « cur », 4,98:1 sur « skip », 5,01:1 sur
    # les lignes paires) ; Theme.Muted n y fait que 4,13:1 a 4,33:1 (il reste sur fond blanc : 4,69:1)
    return [System.Drawing.Color]::FromArgb(100, 106, 118)
}

function Get-AlName([int]$lvl) {
    # Nom d un niveau de score dans la langue courante (la table $script:AlNames est fixee au demarrage)
    switch ($lvl) { 0 { return 'EXCELLENT' } 1 { return (T 'BON') } 2 { return (T 'MOYEN') } default { return (T 'MAUVAIS') } }
}

# --- Pictogrammes -----------------------------------------------------------------------------------------------------
function Draw-QualityState($g, [string]$kind, [single]$ring) {
    # Etat sur la grille de 64 : h0 cercle Ok et coche, h1 triangle WarnInk et « ! », h2 cercle Danger et croix, h2a anneau
    # et croix Danger (piste absente), hq cercle Muted et « ? », pend anneau Muted (etape en attente), skip anneau Muted et
    # tiret (etape sans objet). Liseré blanc de $ring unites : lisible sur les cases colorees du tableau.
    $th = $script:Theme; $wh = [System.Drawing.Color]::White
    if ($kind -eq 'h1') {
        $p = New-Object System.Drawing.Drawing2D.GraphicsPath
        $p.AddPolygon([System.Drawing.PointF[]]@((New-Object System.Drawing.PointF(32, 7)), (New-Object System.Drawing.PointF(59, 56)), (New-Object System.Drawing.PointF(5, 56))))
        $pr = New-Object System.Drawing.Pen($wh, [single](8 + 2 * $ring)); $pr.LineJoin = [System.Drawing.Drawing2D.LineJoin]::Round
        $g.DrawPath($pr, $p); $pr.Dispose()
        $pc = New-Object System.Drawing.Pen($th.WarnInk, [single]8); $pc.LineJoin = [System.Drawing.Drawing2D.LineJoin]::Round
        $g.DrawPath($pc, $p); $pc.Dispose()
        $g.FillPath((Get-QualBrush $th.WarnInk), $p); $p.Dispose()
        $rr = New-RoundRect 28.5 20 7 22 3.5; $g.FillPath((Get-QualBrush $wh), $rr); $rr.Dispose()
        $g.FillEllipse((Get-QualBrush $wh), [single]28.25, [single]45, [single]7.5, [single]7.5)
        return
    }
    $c = switch ($kind) { 'h0' { $th.Ok } 'hq' { $th.Muted } 'pend' { $th.Muted } 'skip' { $th.Muted } default { $th.Danger } }
    $g.FillEllipse((Get-QualBrush $wh), [single](4 - $ring), [single](4 - $ring), [single](56 + 2 * $ring), [single](56 + 2 * $ring))
    if (@('h2a', 'pend', 'skip') -contains $kind) {
        $pen = New-Object System.Drawing.Pen($c, [single]6)
        $g.DrawEllipse($pen, [single]7, [single]7, [single]50, [single]50); $pen.Dispose()
    } else { $g.FillEllipse((Get-QualBrush $c), [single]4, [single]4, [single]56, [single]56) }
    $sc = if (@('h2a') -contains $kind) { $c } else { $wh }
    $pen = New-Object System.Drawing.Pen($sc, [single]7)
    $pen.StartCap = [System.Drawing.Drawing2D.LineCap]::Round; $pen.EndCap = [System.Drawing.Drawing2D.LineCap]::Round; $pen.LineJoin = [System.Drawing.Drawing2D.LineJoin]::Round
    switch ($kind) {
        'h0' { $g.DrawLines($pen, [System.Drawing.PointF[]]@((New-Object System.Drawing.PointF(18, 33)), (New-Object System.Drawing.PointF(28, 43)), (New-Object System.Drawing.PointF(46, 23)))) }
        'skip' { $pen.Color = $c; $g.DrawLine($pen, [single]21, [single]32, [single]43, [single]32) }
        'hq' {
            $f = New-Object System.Drawing.Font('Segoe UI Semibold', [single]40, [System.Drawing.FontStyle]::Regular, [System.Drawing.GraphicsUnit]::Pixel)
            $sf = New-Object System.Drawing.StringFormat; $sf.Alignment = [System.Drawing.StringAlignment]::Center; $sf.LineAlignment = [System.Drawing.StringAlignment]::Center
            $g.DrawString('?', $f, (Get-QualBrush $wh), (New-Object System.Drawing.RectangleF(4, 6, 56, 56)), $sf)
            $f.Dispose(); $sf.Dispose()
        }
        'pend' { }
        default { $g.DrawLine($pen, [single]22, [single]22, [single]42, [single]42); $g.DrawLine($pen, [single]42, [single]22, [single]22, [single]42) }
    }
    $pen.Dispose()
}

function Draw-QualityBars16($g, [int]$filled, [System.Drawing.Color]$fill) {
    # Score a 16 px (A2 § 3.1) : 4 barres alignees sur les pixels, x = 0, 4, 8, 12, largeur 3, hauteurs 4, 7, 10, 13, base
    # a la ligne 14, $filled pleines dans $fill, les autres 205,212,224 ; anticrenelage coupe (bords nets). 12.8 (FIX3) :
    # liseré blanc de 1 px autour de chaque barre, a la place de la pastille blanche qui reduisait les barres a 2 px de
    # large et 9 px de haut : lisible sur les cases colorees du tableau (barre pleine de la couleur de la case)
    $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::None
    $wh = Get-QualBrush ([System.Drawing.Color]::White)
    $empty = [System.Drawing.Color]::FromArgb(205, 212, 224)
    for ($i = 0; $i -lt 4; $i++) { $hh = 4 + 3 * $i; $g.FillRectangle($wh, [int](4 * $i - 1), [int](14 - $hh), 5, [int]($hh + 2)) }
    for ($i = 0; $i -lt 4; $i++) {
        $hh = 4 + 3 * $i
        $g.FillRectangle((Get-QualBrush $(if ($i -lt $filled) { $fill } else { $empty })), [int](4 * $i), [int](15 - $hh), 3, [int]$hh)
    }
}

function Draw-QualityBars48($g, [int]$filled, [System.Drawing.Color]$fill, [bool]$outline) {
    # Score sur la grille de 64 : pastille blanche en bas a droite (24,22 ; 40 x 40), 4 barres de 6 unites (hauteurs 8 a 29),
    # $filled pleines dans $fill ; $outline : barres en contour de $fill (mesure en cours)
    $rr = New-RoundRect 24 22 40 40 6
    $g.FillPath((Get-QualBrush ([System.Drawing.Color]::White)), $rr)
    $g.DrawPath((Get-QualPen ([System.Drawing.Color]::FromArgb(205, 212, 224)) 2), $rr); $rr.Dispose()
    $empty = [System.Drawing.Color]::FromArgb(215, 220, 229)
    for ($i = 0; $i -lt 4; $i++) {
        $hh = 8 + 7 * $i; $x = 27.5 + 9 * $i
        if ($outline) { $g.DrawRectangle((Get-QualPen $fill 2), [single]$x, [single](56 - $hh), [single]6, [single]$hh) }
        else { $g.FillRectangle((Get-QualBrush $(if ($i -lt $filled) { $fill } else { $empty })), [single]$x, [single](56 - $hh), [single]6, [single]$hh) }
    }
}

function New-QualityPicto([string]$kind, [int]$size, [string]$badge = '') {
    # Pictogramme de qualite (A2 § 3.1, D15) en GDI+, comme New-CleanPicto (aucune image externe, aucun Add-Type) :
    #  q0..q3 : score EXCELLENT, BON, MOYEN, MAUVAIS, barres de signal (4 a 1 pleine(s)) dans la couleur du niveau ;
    #  s0..s3 : resultat precedent ou perime (barres du niveau en gris) ; none : aucune mesure (barres vides) ;
    #  run : mesure en cours (horloge) ; bad : aucune piste lisible ; h0, h1, h2, h2a, hq, pend, skip : etats (Draw-QualityState).
    # 16 px : jeu de pixels propre (barres sans anticrenelage) ; 48 px : disquette du logo, pastille de barres, horloge ou
    # badge d etat $badge (h1, h2) en haut a droite ; autres tailles (20 px) : etats a l echelle de la grille de 64.
    $bmp = New-Object System.Drawing.Bitmap($size, $size, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
    $g = [System.Drawing.Graphics]::FromImage($bmp)
    try {
        $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
        $g.PixelOffsetMode = [System.Drawing.Drawing2D.PixelOffsetMode]::HighQuality
        $g.TextRenderingHint = [System.Drawing.Text.TextRenderingHint]::AntiAliasGridFit
        $th = $script:Theme
        $lvl = if ($kind -match '^[qs]([0-3])$') { [int]$Matches[1] } else { -1 }
        if ($size -le 16) {
            if ($kind -match '^q[0-3]$') { Draw-QualityBars16 $g (4 - $lvl) (Get-QualLevelColor $lvl) }
            elseif ($kind -match '^s[0-3]$') { Draw-QualityBars16 $g (4 - $lvl) ([System.Drawing.Color]::FromArgb(150, 156, 168)) }
            elseif ($kind -eq 'none') { Draw-QualityBars16 $g 0 $th.Muted }
            elseif ($kind -eq 'run') {
                $pen = Get-QualPen $th.Accent 1.6
                $g.FillEllipse((Get-QualBrush ([System.Drawing.Color]::White)), [single]1.5, [single]1.5, [single]13, [single]13)
                $g.DrawEllipse($pen, [single]1.5, [single]1.5, [single]13, [single]13)
                $g.DrawLine($pen, [single]8, [single]8, [single]8, [single]4.2); $g.DrawLine($pen, [single]8, [single]8, [single]10.8, [single]8)
            } else {
                $g.ScaleTransform([single]($size / 64.0), [single]($size / 64.0))
                Draw-QualityState $g $(if ($kind -eq 'bad') { 'h2' } else { $kind }) ([single](64.0 / $size))
            }
            return $bmp
        }
        $g.ScaleTransform([single]($size / 64.0), [single]($size / 64.0))
        if ($size -lt 40 -or $kind -match '^h|^pend$|^skip$') { Draw-QualityState $g $kind ([single](64.0 / $size)); return $bmp }
        # 48 px : disquette « donnees » du logo (grisee hors resultat), pastille de barres, horloge ou badge d etat
        Draw-PictoFloppy $g 0 1 42 $false
        if ($kind -match '^s[0-3]$|^none$') { $g.FillRectangle((Get-QualBrush ([System.Drawing.Color]::FromArgb(160, 255, 255, 255))), [single]0, [single]0, [single]44, [single]46) }
        switch -regex ($kind) {
            '^q[0-3]$' { Draw-QualityBars48 $g (4 - $lvl) (Get-QualLevelColor $lvl) $false }
            '^s[0-3]$' { Draw-QualityBars48 $g (4 - $lvl) ([System.Drawing.Color]::FromArgb(160, 166, 178)) $false; Draw-PictoClock $g 52 12 10 $th.Muted }
            '^none$' { Draw-QualityBars48 $g 0 $th.Muted $false }
            '^run$' { Draw-QualityBars48 $g 0 $th.Accent $true; Draw-PictoClock $g 52 12 10 $th.Accent }
            '^bad$' {
                $rr = New-RoundRect 24 22 40 40 6; $g.FillPath((Get-QualBrush $th.Danger), $rr); $rr.Dispose()
                $pen = New-Object System.Drawing.Pen([System.Drawing.Color]::White, [single]6)
                $pen.StartCap = [System.Drawing.Drawing2D.LineCap]::Round; $pen.EndCap = [System.Drawing.Drawing2D.LineCap]::Round
                $g.DrawLine($pen, [single]35, [single]33, [single]53, [single]51); $g.DrawLine($pen, [single]53, [single]33, [single]35, [single]51); $pen.Dispose()
            }
        }
        if ($badge -and $kind -match '^q') {
            $st = $g.Save()
            $g.TranslateTransform([single]40, [single]0); $g.ScaleTransform([single](24 / 64.0), [single](24 / 64.0))
            Draw-QualityState $g $badge ([single]8)
            $g.Restore($st)
        }
        return $bmp
    } finally { $g.Dispose() }
}

function New-QualityGreyBitmap($src) {
    # Copie grisee et attenuee d un pictogramme (tableau et carte hors resultat : D16, griser et marquer)
    $bmp = New-Object System.Drawing.Bitmap($src.Width, $src.Height, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
    $g = [System.Drawing.Graphics]::FromImage($bmp)
    $cm = New-Object System.Drawing.Imaging.ColorMatrix
    $cm.Matrix00 = [single]0.3; $cm.Matrix01 = [single]0.3; $cm.Matrix02 = [single]0.3
    $cm.Matrix10 = [single]0.59; $cm.Matrix11 = [single]0.59; $cm.Matrix12 = [single]0.59
    $cm.Matrix20 = [single]0.11; $cm.Matrix21 = [single]0.11; $cm.Matrix22 = [single]0.11
    $cm.Matrix33 = [single]0.55
    $ia = New-Object System.Drawing.Imaging.ImageAttributes
    $ia.SetColorMatrix($cm)
    $g.DrawImage($src, (New-Object System.Drawing.Rectangle(0, 0, $src.Width, $src.Height)), 0, 0, $src.Width, $src.Height, [System.Drawing.GraphicsUnit]::Pixel, $ia)
    $ia.Dispose(); $g.Dispose()
    return $bmp
}

function Get-QualityIcon([string]$kind, [int]$size, [string]$badge = '', [switch]$Grey) {
    # Pictogramme en cache (cree une fois, libere par Clear-QualityGdi)
    $k = "i$kind|$size|$badge|$([bool]$Grey)"
    $o = $script:QualGdi[$k]
    if ($o) { return $o }
    if ($Grey) { $o = New-QualityGreyBitmap (Get-QualityIcon $kind $size $badge) } else { $o = New-QualityPicto $kind $size $badge }
    $script:QualGdi[$k] = $o
    return $o
}

# --- Etat de l affichage ($script:QualView) ---------------------------------------------------------------------------
# State : empty | run | result | stale ; Kind : measure (mesure, continue ou non) ou check (controle apres ecriture) ;
# Has : un resultat existe (Res) ; Reason : code de la raison (stop, error, gwerror, noscp, thresholds, written,
# checkabort, checknone) ; Pass : passe de la mesure continue ; Drive, Heads, Revs, NCyl : mesure en cours ; RunText : etape du
# controle en cours ; Res : dernier resultat (Kind, At, Score, Lvl, Count, Bad, Health, HealthText, ScoreText...).

function Set-QualityPending([string]$kind, $ctx = $null) {
    # Debut d une mesure ou d un controle apres ecriture : resultat precedent grise, marque « en cours », jamais efface
    $v = $script:QualView
    $v.State = 'run'; $v.Kind = $kind; $v.Reason = ''; $v.RunText = ''
    if ($kind -eq 'measure') {
        $v.Pass = $(if ($script:AlignLoop) { [int]$v.Pass + 1 } else { 0 })
        if ($ctx) { $v.Drive = [string]$ctx.Drive; $v.Heads = [string]$ctx.Heads; $v.Revs = [int]$ctx.Revs; $v.NCyl = [int]$ctx.NCyl }
    } else { $v.Pass = 0; $v.RunText = (T "Contrôle après écriture : en attente de la fin de l'écriture") }
    Update-QualityView
}

function Set-QualityRunText([string]$text) {
    # Etape du controle apres ecriture en cours (relecture, reecriture, remesure), sur la carte
    $v = $script:QualView
    if ($v.State -ne 'run' -or $v.Kind -ne 'check' -or -not $text -or $v.RunText -eq $text) { return }
    $v.RunText = $text
    Update-QualityView
}

function Set-QualityResult($res) {
    # Fin d une mesure (Invoke-AlignAnalysis) ou d un controle (Show-WriteCheckTable) : nouveau resultat affiche
    $v = $script:QualView
    if (-not $res.Kind) { $res.Kind = 'measure' }
    $res.At = Get-Date
    if ($res.Kind -eq 'measure' -and $v.State -eq 'run' -and $v.Kind -eq 'measure' -and $v.Drive) { $res.Ctx = @{ Drive = $v.Drive; Heads = $v.Heads; Revs = $v.Revs } }
    $v.Res = $res; $v.State = 'result'; $v.Has = $true; $v.At = $res.At; $v.Reason = ''; $v.Kind = $res.Kind; $v.RunText = ''
    Update-QualityView
}

function Set-QualityStale([string]$reason) {
    # Resultat affiche qui ne correspond plus a la disquette ou aux reglages (arret, erreur, seuils, ecriture) : grise et
    # marque « perime », avec la raison ; sans resultat, la carte reste vide avec la raison d un echec
    $v = $script:QualView
    if ($v.State -eq 'empty') { return }
    $v.Reason = $reason; $v.RunText = ''
    $v.State = $(if ($v.Has) { 'stale' } else { 'empty' })
    Update-QualityView
}

function Reset-QualityView {
    # Bouton Reinitialiser de l onglet : plus aucun resultat
    $v = $script:QualView
    $v.State = 'empty'; $v.Kind = ''; $v.Reason = ''; $v.At = $null; $v.Has = $false; $v.Pass = 0; $v.Res = $null; $v.RunText = ''
    Update-QualityView
}

function Set-QualityCheckState([int]$lvl, [string]$text, [string]$short, [int]$nWeak) {
    # Verdict du controle apres ecriture (Complete-WriteCheck, niveau 0, 2 ou 3) sur le resultat du controle
    $r = $script:QualView.Res
    if (-not $r -or $r.Kind -ne 'check') { return }
    $r.CheckLvl = $lvl; $r.Health = $(if ($lvl -le 0) { 0 } elseif ($lvl -le 2) { 1 } else { 2 }); $r.HealthText = $text; $r.HealthSub = $short; $r.Weak = $nWeak
    Update-QualityView
}

function Get-QualStaleText([string]$reason, [string]$at) {
    # Texte de la raison d un resultat perime ($at : heure du resultat) ou d une carte vide apres un echec
    switch ($reason) {
        'gwerror'    { return (T 'Mesure interrompue (erreur gw)') }
        'noscp'      { return (T 'Mesure impossible : fichier de lecture absent ou illisible') }
        'thresholds' { return (T 'Seuils de jitter modifiés : relancez la mesure') }
        'written'    { return (T 'Disquette écrite depuis la mesure') }
        'checkabort' { return (T 'Contrôle après écriture interrompu.') }
        'checknone'  { return (T 'Contrôle après écriture : aucune piste à relire.') }   # 12.8 (FIX-PISTES) : champ Pistes
        default      { if ($at) { return ((T 'Mesure interrompue : résultat de {0}') -f $at) } else { return '' } }
    }
}

function Get-QualStateTitle($r) {
    if ([int]$r.Health -lt 0) { return '' }
    if ($r.Kind -eq 'check') {
        if ([int]$r.CheckLvl -le 0) { return (T 'COPIE SAINE') }
        if ([int]$r.Weak -gt 0) { return ((T '{0} PISTE(S) FAIBLE(S)') -f "$($r.Weak)") }
        return (T 'Aucune piste analysable')
    }
    switch ([int]$r.Health) { 0 { return (T 'SUPPORT SAIN') } 1 { return (T 'SUPPORT À SURVEILLER') } default { return (T 'SUPPORT CRITIQUE') } }
}

function Get-QualityCardModel($v) {
    # Contenu de la carte (textes, couleurs, pictogrammes) pour l etat $v : fonction sans interface (niveau 2 du banc)
    $th = $script:Theme; $wh = [System.Drawing.Color]::White
    $edge = [System.Drawing.Color]::FromArgb(205, 212, 224)
    $m = @{ Back = $wh; Bar = $edge; Icon = 'none'; Badge = ''; GreyIcon = $false; Score = [string][char]0x2013; ScoreInk = $th.Muted
            Caption = (T 'score · plus bas = mieux'); CaptionInk = $th.Muted; Level = ''; LevelInk = $th.Muted; Line2 = ''; Line2Short = ''; Line2More = @()
            Line2Ink = $th.Muted; StateIcon = ''; State = ''; StateInk = $th.Muted; Sub = ''; SubShort = ''; SubInk = $th.Muted; Chip = ''; ChipBack = $th.Muted
            Tip = ''; Access = '' }
    $r = $v.Res
    $at = if ($r -and $r.At -is [datetime]) { $r.At.ToString('HH:mm') } else { '' }
    # 12.8 (FIX3) : etape d un controle apres ecriture en cours, forme courte sans le prefixe « Controle apres ecriture : »
    # (la pastille « CONTROLE EN COURS » le dit) ; infobulle : resultat precedent remplace a la fin du controle ; ligne 2
    # complete d un resultat avec des pistes illisibles (D15), quand la carte n en montre qu une forme courte
    $runShort = [string]$v.RunText -replace '^[^:]*:\s*', ''
    if ($runShort) { $runShort = $runShort.Substring(0, 1).ToUpper() + $runShort.Substring(1) }
    $prevTip = ''; $fullL2 = ''
    $chipRun = if ($v.Kind -eq 'check') { (T 'CONTRÔLE EN COURS') } elseif ($script:AlignLoop -and [int]$v.Pass -gt 0) { (T 'MESURE CONTINUE · PASSE {0}') -f "$($v.Pass)" } else { (T 'MESURE EN COURS') }
    $show = $null                       # resultat a afficher : $true en couleurs, $false grise
    switch ($v.State) {
        'run' {
            $m.Chip = $chipRun; $m.ChipBack = $th.Accent; $m.Bar = $th.Accent
            if ($v.Has -and $r) { $show = $false }
            else {
                $m.Back = [System.Drawing.Color]::FromArgb(234, 241, 251); $m.Icon = 'run'; $m.Score = [string][char]0x2026; $m.ScoreInk = $th.Accent
                $m.LevelInk = $th.Accent2; $m.Line2Ink = $th.Accent
                if ($v.Kind -eq 'check') { $m.Level = (T 'Contrôle après écriture en cours'); $m.Line2 = $v.RunText; $m.Line2Short = $runShort }
                else {
                    $m.Level = (T 'Mesure en cours')
                    $m.Line2 = (T 'Lecture de {0} cylindre(s), tête(s) {1}, {2} tour(s) (lecteur {3})') -f "$($v.NCyl)", "$($v.Heads)", "$($v.Revs)", "$($v.Drive)"
                }
            }
        }
        'stale' {
            $show = $false
            $m.Back = [System.Drawing.Color]::FromArgb(244, 245, 247); $m.Chip = (T 'PÉRIMÉ'); $m.ChipBack = $th.Muted; $m.Bar = $th.Muted
        }
        'result' { if ($r) { $show = $true } }
        default {
            $m.Level = (T 'Aucune mesure')
            $m.Line2 = Get-QualStaleText $v.Reason ''
            if (-not $m.Line2 -or @('stop', 'error', 'thresholds', 'written') -contains $v.Reason) { $m.Line2 = (T 'Insérez une disquette, puis cliquez sur « MESURER LA DISQUETTE ».') }
            $m.State = (T 'État du support : après la mesure')
        }
    }
    if ($null -ne $show -and $r) {
        $count = [int]$r.Count; $bad = [int]$r.Bad; $lvl = [int]$r.Lvl; $hl = [int]$r.Health
        $m.State = Get-QualStateTitle $r
        $m.StateIcon = $(if ($hl -ge 0) { "h$hl" } else { '' })
        if ($r.Kind -eq 'check') { $m.Sub = [string]$r.HealthSub; $m.SubShort = $m.Sub }
        else {
            $keys = if ($hl -eq 2) { @($r.CritKeys) } elseif ($hl -eq 1) { @($r.WatchKeys) } else { @() }
            $part = switch ($hl) {
                0 { (T '{0}/{1} pistes propres') -f "$($r.NTracks)", "$($r.NTracks)" }
                1 { (T '{0}/{1} piste(s) marginale(s) : {2}') -f "$($keys.Count)", "$($r.NTracks)", "$($keys -join ', ')" }
                default { (T '{0} piste(s) en erreur : {1}') -f "$($keys.Count)", "$($keys -join ', ')" }
            }
            $m.SubShort = $part + ' · ' + $at
            $m.Sub = if ($r.Ctx) { $part + ' · ' + ((T 'lecteur {0}, têtes {1}, {2} tours · {3}') -f "$($r.Ctx.Drive)", "$($r.Ctx.Heads)", "$($r.Ctx.Revs)", $at) } else { $m.SubShort }
        }
        if ($count -le 0) {
            $m.Icon = 'bad'; $m.Level = (T 'Aucune piste analysable'); $m.Line2 = (T 'Vérifiez la disquette, le lecteur et le format')
            $lvl = 3
        } else {
            $m.Score = "$($r.Score)"; $m.Level = Get-AlName $lvl
            $m.Icon = "q$lvl"
            if ($hl -ge 2 -or $bad -gt 0) { $m.Badge = 'h2' } elseif ($hl -eq 1) { $m.Badge = 'h1' }
            if ($r.Kind -eq 'check') {
                # 12.8 (FIX3) : formes courtes (ligne 2 de 272 a 283 px a la taille minimale de la fenetre) : sans le prefixe,
                # puis le nombre de pistes illisibles non comptees seul (D15)
                if ($bad -gt 0) {
                    $m.Line2 = (T 'Contrôle après écriture : sur {0} piste(s) lisible(s), {1} illisible(s) non comptée(s)') -f "$count", "$bad"
                    $m.Line2Short = (T 'sur {0} piste(s) lisible(s), {1} illisible(s) non comptée(s)') -f "$count", "$bad"
                    $m.Line2More = @((T '{0} piste(s) illisible(s) non comptée(s)') -f "$bad")
                } else { $m.Line2 = (T 'Contrôle après écriture : sur {0} piste(s) lisible(s)') -f "$count"; $m.Line2Short = $m.Line2 }
            } else {
                $p1 = @(); $p2 = @()
                if ($null -ne $r.Prev) {
                    if ([double]$r.Score -lt [double]$r.Prev - 2) { $p1 += ((T 'Mieux que la mesure précédente ({0})') -f "$($r.Prev)") }
                    elseif ([double]$r.Score -gt [double]$r.Prev + 2) { $p1 += ((T 'Moins bien que la mesure précédente ({0})') -f "$($r.Prev)") }
                    else { $p1 += (T 'Stable') }
                }
                $p2 += $(if ($null -ne $r.RefAvg) { (T 'meilleur {0} · réf. {1}') -f "$($r.Best)", "$($r.RefAvg)" } else { (T 'meilleur {0}') -f "$($r.Best)" })
                $p3 = @(); if ($bad -gt 0) { $p3 += ((T 'sur {0} piste(s) lisible(s), {1} illisible(s) non comptée(s)') -f "$count", "$bad") }
                $m.Line2 = @(@($p1) + @($p2) + @($p3)) -join ' · '
                # 12.8 (FIX3) : formes courtes, la phrase des pistes illisibles d abord (D15) : sans « meilleur / réf. », puis
                # cette phrase seule, puis le nombre de pistes illisibles non comptees seul
                $m.Line2Short = @(@($p3) + @($p1)) -join ' · '
                if ($bad -gt 0) { $m.Line2More = @($p3[0], ((T '{0} piste(s) illisible(s) non comptée(s)') -f "$bad")) }
            }
            if ($bad -gt 0) { $fullL2 = $m.Line2 }
        }
        if ($show) {
            $m.Bar = $(if ($count -le 0) { $th.Danger } else { Get-QualLevelColor $lvl })
            $m.ScoreInk = Get-QualInk $lvl; $m.LevelInk = Get-QualInk $lvl
            $m.StateInk = Get-QualInk $(if ($hl -le 0) { 0 } elseif ($hl -eq 1) { 2 } else { 3 })
        } else {
            # Resultat precedent (mesure en cours) ou perime : memes textes en gris, pictogrammes gris ; ligne 2 : la raison
            $m.GreyIcon = $true
            $m.Icon = $(if ($count -le 0) { 'bad' } else { "s$lvl" }); $m.Badge = ''; $m.Line2More = @()
            if ($v.State -eq 'stale') { $m.Line2 = Get-QualStaleText $v.Reason $at; $m.Line2Short = $m.Line2 }
            elseif ($v.Kind -eq 'check' -and $v.RunText) {
                # 12.8 (FIX3) : controle apres ecriture en cours : son etape (en attente de l ecriture, relecture, reecriture,
                # remesure) en Accent, comme pour un premier controle ; le resultat precedent grise est explique dans l infobulle
                $m.Line2 = [string]$v.RunText; $m.Line2Short = $runShort; $m.Line2Ink = $th.Accent
                $prevTip = (T 'Résultat précédent ({0}), remplacé à la fin du contrôle') -f $at
            } else {
                $m.Line2 = (T 'Résultat précédent ({0}), remplacé à la fin de la mesure') -f $at
                $m.Line2Short = (T 'Résultat précédent ({0}), remplacé à la fin') -f $at      # 12.8 (FIX3) : tient sur 272 px
            }
        }
    }
    if (-not $m.Line2Short) { $m.Line2Short = $m.Line2 }
    if (-not $m.SubShort) { $m.SubShort = $m.Sub }
    # 12.8 (FIX3) : texte gris pose sur une teinte (en cours, premiere mesure : « cur » 234,241,251 ; perime : « skip »
    # 244,245,247) : gris plus fonce (Get-QualDimInk), pour un contraste >= 4,5:1 ; sur fond blanc, Theme.Muted (4,69:1)
    if ($m.Back.ToArgb() -ne $wh.ToArgb()) {
        $dim = Get-QualDimInk
        foreach ($k in @('ScoreInk', 'CaptionInk', 'LevelInk', 'Line2Ink', 'StateInk', 'SubInk')) { if ($m[$k].ToArgb() -eq $th.Muted.ToArgb()) { $m[$k] = $dim } }
    }
    # Infobulle : etat d affichage, textes complets du resultat (listes de pistes), puis les deux definitions
    $tips = @()
    if ($m.Chip) { $tips += ($m.Chip + ' : ' + $m.Line2) } elseif ($v.State -eq 'empty' -and $m.Line2) { $tips += $m.Line2 }
    if ($prevTip) { $tips += $prevTip }
    if ($show -eq $true -and $fullL2) { $tips += $fullL2 }
    if ($r -and $null -ne $show) { if ($r.HealthText) { $tips += [string]$r.HealthText }; if ($r.ScoreText) { $tips += [string]$r.ScoreText }; if ($r.AsymText) { $tips += [string]$r.AsymText } }   # 12.11 : AsymText, resume de l asymetrie (Get-AsymSummaryText, 190)
    $tips += ''
    $tips += (T "État du support : basé uniquement sur les erreurs, les trous de signal, la stabilité entre tours et le jitter. Erreurs comptées sans le premier intervalle de la lecture ni, en double densité, le raccord d'écriture dans la zone de ± 1 ms autour de l'index ; stabilité mesurée sur des tours alignés (double densité, 3 tours ou plus).`nIndépendant du contenu : comparable d'une disquette à l'autre.")
    $tips += (T "Score de qualité de lecture (plus bas = mieux). Dépend du contenu : à comparer uniquement sur une même image`n(deux lecteurs, deux précompensations, deux réglages).")
    $m.Tip = ($tips -join "`n").Trim()
    $m.Access = @(@($m.Chip, "$($m.Score) $($m.Level)".Trim(), $m.State) | Where-Object { $_ -and $_ -ne [string][char]0x2013 }) -join ' ; '
    return $m
}

# --- Rendu ------------------------------------------------------------------------------------------------------------
function Update-QualityView {
    # Rendu de $script:QualView : carte de resultat, infobulle et tableau (gris hors resultat, D16)
    $script:QualCard = Get-QualityCardModel $script:QualView
    # 12.8 (FIX3) : bandeau orange des zones instables de la derniere mesure (Set-UnstableBanner) grise comme la carte tant
    # que ce resultat n est pas le resultat courant (mesure en cours, perime) ; le guide d alignement, qui utilise la meme
    # ligne, garde ses couleurs
    if ($lblAlReco -and $script:UnstableBannerText -and $lblAlReco.Text -eq $script:UnstableBannerText) {
        $lblAlReco.ForeColor = $(if ($script:QualView.State -eq 'result') { [System.Drawing.Color]::DarkOrange } else { $script:Theme.Muted })
    }
    if (-not $pnlQualCard) { return }
    Render-QualityCard
    $tip.SetToolTip($pnlQualCard, $script:QualCard.Tip)
    $pnlQualCard.AccessibleName = $script:QualCard.Access
    if ($lvAl) { $lvAl.Invalidate() }
}

function Get-QualFitText([string]$long, [string]$short, $font, [int]$w, [string[]]$more = @()) {
    # Texte long s il tient sur $w px, sinon sa forme courte (sans les details repris dans l infobulle) ; 12.8 (FIX3) : puis
    # les formes plus courtes $more, dans l ordre ; aucune ne tient : la derniere (coupee par des points de suspension)
    if (-not $long) { return $short }
    $tf = [System.Windows.Forms.TextFormatFlags]::NoPrefix -bor [System.Windows.Forms.TextFormatFlags]::SingleLine
    $sz = New-Object System.Drawing.Size(32000, 100)
    $cands = @(@($long, $short) + @($more) | Where-Object { $_ })
    foreach ($s in $cands) { if ([System.Windows.Forms.TextRenderer]::MeasureText($s, $font, $sz, $tf).Width -le $w) { return $s } }
    return $cands[-1]
}

function Get-QualityCardLayout([int]$w, [int]$lx, [bool]$hasState, [bool]$hasSub = $true) {
    # Zones de la carte de $w px de large (768 au minimum de la fenetre) : pictogramme et score a gauche, niveau et ligne 2
    # a partir de $lx, separateur et zone d etat a droite ; sans etat a afficher (premiere mesure en cours), pas de
    # separateur : la ligne 2 prend toute la largeur ; etat sans detail (carte vide) : separateur court, ligne 2 aussi
    if (-not $hasState) { return @{ Lx = $lx; Sep = -1; SepBottom = 0; L2W = $w - $lx - 10; StX = $w; StW = 0 } }
    $sep = [int]($lx + ($w - $lx) * 0.5)
    if (-not $hasSub) { return @{ Lx = $lx; Sep = $sep; SepBottom = 28; L2W = $w - $lx - 10; StX = $sep + 12; StW = $w - $sep - 22 } }
    return @{ Lx = $lx; Sep = $sep; SepBottom = 50; L2W = $sep - $lx - 10; StX = $sep + 12; StW = $w - $sep - 22 }
}

function Render-QualityCard {
    # Carte (A2 § 3.2) dessinee dans un bitmap, fond de pnlQualCard : barre de couleur a gauche, pictogramme 48 px, score,
    # legende, niveau, ligne 2, separateur, etat (pictogramme 20 px, titre, detail), pastille d etat d affichage
    $m = $script:QualCard
    if (-not $m -or -not $pnlQualCard) { return }
    $w = [math]::Max(200, [int]$pnlQualCard.ClientSize.Width); $h = [math]::Max(40, [int]$pnlQualCard.ClientSize.Height)
    $fScore = Get-QualFont 'Segoe UI Semibold' 22; $fSmall = Get-QualFont 'Segoe UI' 8.25; $fLevel = Get-QualFont 'Segoe UI Semibold' 12
    $fState = Get-QualFont 'Segoe UI Semibold' 10.5; $fChip = Get-QualFont 'Segoe UI Semibold' 8.25
    $one = [System.Windows.Forms.TextFormatFlags]::NoPrefix -bor [System.Windows.Forms.TextFormatFlags]::SingleLine
    # Colonne du niveau apres la legende du score (« score · plus bas = mieux », plus longue en francais)
    $capW = [System.Windows.Forms.TextRenderer]::MeasureText($m.Caption, $fSmall, (New-Object System.Drawing.Size(32000, 100)), $one).Width
    $lay = Get-QualityCardLayout $w ([math]::Max(180, 66 + $capW + 8)) ([bool]($m.State -or $m.StateIcon)) ([bool]$m.Sub)
    # Bitmap sans canal alpha : le texte GDI (TextRenderer) y est opaque
    $bmp = New-Object System.Drawing.Bitmap($w, $h, [System.Drawing.Imaging.PixelFormat]::Format24bppRgb)
    $g = [System.Drawing.Graphics]::FromImage($bmp)
    try {
        $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
        $g.Clear($m.Back)
        $edge = [System.Drawing.Color]::FromArgb(205, 212, 224)
        $g.DrawRectangle((Get-QualPen $edge 1), 0, 0, ($w - 1), ($h - 1))
        $g.FillRectangle((Get-QualBrush $m.Bar), 0, 0, 5, $h)
        $tf = $one -bor [System.Windows.Forms.TextFormatFlags]::VerticalCenter -bor [System.Windows.Forms.TextFormatFlags]::EndEllipsis
        if ($m.Icon) { $g.DrawImage((Get-QualityIcon $m.Icon 48 $m.Badge -Grey:([bool]$m.GreyIcon)), 12, 5, 48, 48) }
        [System.Windows.Forms.TextRenderer]::DrawText($g, $m.Score, $fScore, (New-Object System.Drawing.Rectangle(64, 0, ($lay.Lx - 68), 40)), $m.ScoreInk, $m.Back, $tf)
        [System.Windows.Forms.TextRenderer]::DrawText($g, $m.Caption, $fSmall, (New-Object System.Drawing.Rectangle(66, 38, ($lay.Lx - 70), 17)), $m.CaptionInk, $m.Back, $tf)
        # Pastille « en cours » / « perime » : au bout de la ligne du niveau, avant le separateur ; en haut a droite de la carte
        # sans zone d etat
        $right = $(if ($lay.Sep -gt 0) { $lay.Sep - 10 } else { $w - 8 })
        $lvW = $right - $lay.Lx
        if ($m.Chip) {
            $cw = [System.Windows.Forms.TextRenderer]::MeasureText($m.Chip, $fChip).Width + 14
            $chipX = $right - $cw
            $rr = New-RoundRect $chipX 8 $cw 18 9; $g.FillPath((Get-QualBrush $m.ChipBack), $rr); $rr.Dispose()
            [System.Windows.Forms.TextRenderer]::DrawText($g, $m.Chip, $fChip, (New-Object System.Drawing.Rectangle($chipX, 8, $cw, 18)), [System.Drawing.Color]::White, $m.ChipBack,
                ($one -bor [System.Windows.Forms.TextFormatFlags]::VerticalCenter -bor [System.Windows.Forms.TextFormatFlags]::HorizontalCenter))
            $lvW = $chipX - 6 - $lay.Lx
        }
        [System.Windows.Forms.TextRenderer]::DrawText($g, $m.Level, $fLevel, (New-Object System.Drawing.Rectangle($lay.Lx, 4, [math]::Max(10, $lvW), 26)), $m.LevelInk, $m.Back, $tf)
        $l2 = Get-QualFitText $m.Line2 $m.Line2Short $fSmall $lay.L2W $m.Line2More
        [System.Windows.Forms.TextRenderer]::DrawText($g, $l2, $fSmall, (New-Object System.Drawing.Rectangle($lay.Lx, 32, $lay.L2W, 20)), $m.Line2Ink, $m.Back, $tf)
        if ($lay.Sep -gt 0) {
            $g.DrawLine((Get-QualPen $edge 1), $lay.Sep, 8, $lay.Sep, [math]::Min(($h - 8), $lay.SepBottom))
            $tx = $lay.StX
            if ($m.StateIcon) { $g.DrawImage((Get-QualityIcon $m.StateIcon 20 -Grey:([bool]$m.GreyIcon)), $lay.StX, 8, 20, 20); $tx = $lay.StX + 26 }
            [System.Windows.Forms.TextRenderer]::DrawText($g, $m.State, $fState, (New-Object System.Drawing.Rectangle($tx, 6, [math]::Max(10, $w - 10 - $tx), 24)), $m.StateInk, $m.Back, $tf)
            $sub = Get-QualFitText $m.Sub $m.SubShort $fSmall $lay.StW
            [System.Windows.Forms.TextRenderer]::DrawText($g, $sub, $fSmall, (New-Object System.Drawing.Rectangle($lay.StX, 32, $lay.StW, 20)), $m.SubInk, $m.Back, $tf)
        }
    } finally { $g.Dispose() }
    $old = $pnlQualCard.BackgroundImage
    $pnlQualCard.BackgroundImage = $bmp
    if ($old) { $old.Dispose() }
}

function Draw-AlSubItem($e, $font) {
    # Case du tableau de l onglet Qualite (DrawSubItem de $lvAl ; fonction pour la tester sans afficher la fenetre : une
    # ListView hors ecran ne recoit jamais ce dessin). Fond de la case (couleur du niveau) ou de la ligne ; gris tant que
    # le resultat affiche n est pas le resultat courant (mesure en cours, perime : D16) ; icone de 16 px (D15) devant
    # l etat (colonne 1) et devant le score (colonne 6), d apres Item.Tag (New-AlignRow) ; pinceaux, stylo et formats en
    # cache (plus d allocation a chaque case)
    $row = $e.Item.Index
    $grey = ($script:QualView.State -ne 'result')
    $baseBg = if ($row % 2) { [System.Drawing.Color]::FromArgb(243, 246, 250) } else { [System.Drawing.Color]::White }
    $bg = if (-not $grey -and $e.SubItem.BackColor -ne [System.Drawing.Color]::Empty -and $e.SubItem.BackColor.ToArgb() -ne [System.Drawing.SystemColors]::Window.ToArgb() -and $e.SubItem.BackColor.ToArgb() -ne 0) { $e.SubItem.BackColor } else { $baseBg }
    $e.Graphics.FillRectangle((Get-QualBrush $bg), $e.Bounds)
    $e.Graphics.DrawLine((Get-QualPen ([System.Drawing.Color]::FromArgb(225, 229, 235)) 1), $e.Bounds.Right - 1, $e.Bounds.Top, $e.Bounds.Right - 1, $e.Bounds.Bottom)
    $fg = if ($grey) { Get-QualDimInk } elseif ($e.SubItem.ForeColor -ne [System.Drawing.Color]::Empty) { $e.SubItem.ForeColor } else { [System.Drawing.Color]::FromArgb(32, 36, 44) }
    $fnt = if ($e.SubItem.Font) { $e.SubItem.Font } else { $font }
    $r = [System.Drawing.RectangleF]::new($e.Bounds.X + 4, $e.Bounds.Y, $e.Bounds.Width - 8, $e.Bounds.Height)
    $ik = ''
    if ($e.Item.Tag -is [hashtable]) { if ($e.ColumnIndex -eq 1) { $ik = [string]$e.Item.Tag.State } elseif ($e.ColumnIndex -eq 6) { $ik = [string]$e.Item.Tag.Score } }
    if ($ik) {
        $e.Graphics.DrawImage((Get-QualityIcon $ik 16 -Grey:$grey), ($e.Bounds.X + 3), ($e.Bounds.Y + [int][math]::Floor(($e.Bounds.Height - 16) / 2)), 16, 16)
        $r = [System.Drawing.RectangleF]::new($e.Bounds.X + 22, $e.Bounds.Y, [math]::Max(1, $e.Bounds.Width - 26), $e.Bounds.Height)
    }
    $e.Graphics.DrawString($e.SubItem.Text, $fnt, (Get-QualBrush $fg), $r, (Get-QualSf $(if ($e.ColumnIndex -eq 0) { 'near' } else { 'center' })))
}

# --- Icones d etat hors de l onglet Qualite : onglet Ecriture, etapes et verdict de la restauration --------------------
function Set-WCalVerdict([string]$text, [string]$kind) {
    # Verdict du controle apres ecriture dans le libelle de l onglet Ecriture : icone d etat 16 px a gauche (h0, h1, h2) et
    # encre de l etat ; retires des que le libelle prend un autre texte (TextChanged de $lblWCal : Clear-WCalVerdict)
    $script:WCalIcon = @{ Kind = $kind; Text = $text }
    $lblWCal.Padding = New-Object System.Windows.Forms.Padding(20, 0, 0, 0)
    $lblWCal.ForeColor = Get-QualInk $(switch ($kind) { 'h0' { 0 } 'h1' { 2 } default { 3 } })
    $lblWCal.Text = $text; $lblWCal.Visible = $true
    $lblWCal.Invalidate()
}

function Clear-WCalVerdict {
    if (-not $script:WCalIcon) { return }
    $script:WCalIcon = $null
    $lblWCal.Padding = New-Object System.Windows.Forms.Padding(0); $lblWCal.ForeColor = [System.Drawing.Color]::DimGray
}

function Hide-WCalVerdict {
    # 12.8 (FIX3) : disquette ecrite ou effacee sans controle apres ecriture (Start-Gw), ou prechauffage d une ecriture
    # (Start-WriteWarmup, qui retablit ensuite le libelle) : le verdict affiche du controle precedent ne la decrit plus ;
    # libelle masque, icone et encre retirees. Sans effet sans verdict affiche (calibration : le libelle a deja change)
    if (-not $script:WCalIcon) { return }
    $lblWCal.Visible = $false
    Clear-WCalVerdict
}

function Draw-WCalIcon($l, $e) {
    if (-not $script:WCalIcon -or $l.Text -ne $script:WCalIcon.Text) { return }
    $e.Graphics.DrawImage((Get-QualityIcon $script:WCalIcon.Kind 16), 1, [int][math]::Max(0, [math]::Floor(($l.Height - 16) / 2)), 16, 16)
}

function Draw-RsStepLabel($l, $e) {
    # Etape de la restauration : icone d etat 16 px (D15, a la place des glyphes), puis le texte sans son glyphe, dans sa
    # couleur, aussi quand Set-Busy desactive les onglets. Le texte du libelle garde son glyphe (infobulle, fins de test).
    $g = $e.Graphics
    $g.FillRectangle((Get-QualBrush $l.BackColor), $l.ClientRectangle)
    $kind = switch ([string]$l.Tag) { 'run' { 'run' } 'ok' { 'h0' } 'fail' { 'h2' } 'warn' { 'h1' } 'skip' { 'skip' } default { 'pend' } }
    $g.DrawImage((Get-QualityIcon $kind 16), 0, [int][math]::Max(0, [math]::Floor(($l.Height - 16) / 2)), 16, 16)
    $txt = [string]$l.Text -replace '^\S+\s+', ''
    $tf = [System.Windows.Forms.TextFormatFlags]::NoPrefix -bor [System.Windows.Forms.TextFormatFlags]::SingleLine -bor [System.Windows.Forms.TextFormatFlags]::VerticalCenter -bor [System.Windows.Forms.TextFormatFlags]::EndEllipsis
    [System.Windows.Forms.TextRenderer]::DrawText($g, $txt, $l.Font, (New-Object System.Drawing.Rectangle(21, 0, [math]::Max(1, $l.Width - 21), $l.Height)), $l.ForeColor, $tf)
}

function Draw-RsResultIcon($e) {
    # Verdict de la restauration : icone d etat 48 px dans la marge gauche (RESTAUREE h0, avec reserve h1, ECHOUEE h2)
    if ($script:RsResultIcon) { $e.Graphics.DrawImage((Get-QualityIcon $script:RsResultIcon 48), 8, 8, 48, 48) }
}
# ============================== FONCTIONS : ACCUEIL : CALIBRATION ET PROGRESSION ===

function Show-HomeCurve {
    # Courbe de la derniere calibration, toutes familles confondues : pour chaque famille, courbes par tete si elles sont
    # a jour, sinon la courbe commune (Get-FamilyCurves) ; on garde la famille dont cette courbe est la plus recente
    $best = $null; $bestDate = [datetime]::MinValue
    foreach ($f in @('std', 'long', 'hd')) {
        $cvs = Get-FamilyCurves $f $true
        if ($cvs.Count -eq 0) { continue }
        $d = Get-CurveDate $cvs[0]
        if ($null -eq $best -or $d -gt $bestDate) { $best = $f; $bestDate = $d }
    }
    if ($best) { Show-PrecompCurve $best $true; return }
    [void](Show-AppMessage (T "Aucune calibration enregistrée.`n`nLa courbe apparaît après une première calibration : bouton « Calibrer » de l'onglet Écriture, ou première écriture depuis la Bibliothèque.") (T 'Courbe de calibration') 'OK' 'Information')
}

# ============================== ACCUEIL : CALIBRATION ==========================
# Carte « Calibrer le lecteur » : type de disquette choisi dans la liste de tous les formats de gw 1.23 ($script:GwFormats)
# et des types d image sans format gw ; famille de calibration ou raison de l absence de calibration ; etat des courbes ;
# courbe ; calibration complete (test standard ou fin, prechauffage compris sauf case decochee) ou rapide, sans image :
# une image de geometrie (HFE du generateur du motif, New-CalibGeometry) tient lieu d image pour Test-CalibImage,
# Get-LevelRef et New-CalibPattern, qui en tirent famille, cylindres et densite comme d une image de l onglet Ecriture.

function Get-FormatCalibInfo([string]$name, [bool]$manual = $false) {
    # 12.10 (lot 1, revue2, R-6) : manual : profil Manuel avec --precomp coche dans l onglet Ecriture (Test-ManualPrecomp,
    # passe par Test-CalibImage ; parametre et non lecture des controles : fonction de niveau logique, sans interface)
    # Calibration d un format gw (table GwFormats). Cal = 'std' ou 'hd' (12.7 : haute densite MFM, 1 us par cellule a
    # 300 tr/min) avec Bits (cellules par piste du motif, celles que Get-PatternBits retient pour une image de ce format :
    # ADF 101 344, ADF HD 202 688, autres haute densite 200 000, autres 100 000), Rpm, NCyl (35 au moins) et Notes ;
    # sinon Why, raison affichee. Group : groupe de la liste de la carte. Ordre des refus : balayage, GCR, FM, codages
    # propres, secteurs durs, tres haute densite (ED), haute densite a 360 tr/min (famille non livree en 12.7, faute de
    # validation sur un lecteur reel), haute densite a une autre vitesse, double densite a une autre vitesse que
    # 300 tr/min, cellule hors plage. Debit de 260 ou 261 kbit/s (Atari) : famille standard, comme l ecriture d une image
    # secteur, avec une note.
    $r = @{ Name = $name; Label = $name; Group = 'other'; Cal = $null; Why = ''; Notes = @(); NCyl = 0; Heads = 0; Bits = 0; BitsSrc = ''; Rate = 0; Rpm = 300 }
    $e = $script:GwFormats[$name]
    if (-not $e) { $r.Why = (T "format absent de la table de l'application (gw plus récent ou fichier diskdefs) : calibrez depuis l'onglet Écriture, avec l'image et ce format"); return $r }
    $r.NCyl = [math]::Max(35, [int]$e.Cyls); $r.Heads = [int]$e.Heads; $r.Rpm = [int]$e.Rpm
    $rate = [int]$e.Rate; $r.Rate = $rate
    $hd = (Test-HdFormat $name) -or $rate -ge 450
    $ed = ($rate -ge 900) -or ($name -match '\.(2880|ed)$')
    $gcr = (@('c64', 'a2', 'mac') -contains $e.Enc)
    $grp = ''
    if ($e.Enc -eq 'amiga') { $grp = $(if ($hd) { 'amiga_hd' } else { 'amiga_dd' }) }
    elseif ($gcr) { $grp = 'gcr' }
    elseif ($e.Enc -eq 'fm') { $grp = 'fm' }
    elseif ($hd) { $grp = 'hd' }
    elseif ($e.Enc -eq 'mfm' -and $name -match '^(ibm|atarist)\.') { $grp = 'pc_dd' }
    # 12.10 (lot 1, B1, decision B-D15) : GCR Macintosh distinct du GCR Commodore ou Apple II ; raisons FM, GCR et codage
    # propre completees par la consequence a l ecriture (Start-ImageWrite ne transmet pas --precomp, Get-ImageEncoding)
    # 12.10 (lot 1, revue2, R-6) : consequence a l ecriture omise si manual est vrai (champ du profil Manuel transmis tel
    # quel, comme Write-NonMfmSkip) ; carte de l Accueil et Bibliotheque (profil Auto) : texte complet. R-5 : secteurs durs
    # northstar.fm.* ecrits en FM (Get-ImageEncoding), sans precompensation comme les autres raisons FM ; micropolis.* et
    # northstar.mfm.* en MFM, --precomp transmis
    $np = if ($manual) { '' } else { (T " ; l'image est écrite sans précompensation") }
    if ($e.Enc -eq 'scan') { $r.Why = (T "format de balayage : gw n'écrit pas une image secteur avec ibm.scan, densité inconnue à l'avance") }
    elseif ($gcr -and $e.Enc -eq 'mac') { $r.Why = (T 'codage GCR Macintosh à zones de vitesse : la calibration ne mesure que le codage MFM') + $np }
    elseif ($gcr) { $r.Why = (T 'codage GCR Commodore ou Apple II (lecteur 5,25 pouces) : la calibration ne mesure que le codage MFM') + $np }
    elseif ($e.Enc -eq 'fm') { $r.Why = (T 'codage FM : la calibration ne mesure que le codage MFM, et la précompensation de gw n''agit pas de la même façon en FM') + $np }
    elseif (@('m2fm', 'dg') -contains $e.Enc) { $r.Why = (T 'codage propre au système (M2FM, Data General) : la calibration ne mesure que le codage MFM') + $np }
    elseif ($e.Enc -eq 'hard' -and $name -match '^northstar\.fm\.') { $r.Why = (T 'disquette à secteurs durs en codage FM : calibration non prise en charge') + $np }
    elseif ($e.Enc -eq 'hard') { $r.Why = (T 'disquette à secteurs durs : calibration non prise en charge') }
    elseif ($ed) { $r.Why = (T "très haute densité (ED) : cellule de 500 ns, trop courte pour l'analyse de la calibration (900 à 1 100 ns en haute densité)") }
    elseif ($hd -and [int]$e.Rpm -eq 360) { $r.Why = (T 'disquette 5,25 pouces haute densité à 360 tr/min : calibration pas encore validée sur un lecteur réel (lecteur 5,25 pouces haute densité nécessaire)') }
    elseif ($hd -and [int]$e.Rpm -ne 300) { $r.Why = ((T "format haute densité à {0} tr/min : la calibration haute densité suppose un lecteur à 300 tr/min") -f "$($e.Rpm)") }
    elseif ($hd) {
        $r.Cal = 'hd'
        if ($e.Enc -eq 'amiga') { $r.Bits = 202688; $r.BitsSrc = (T 'ADF haute densité, horloge AmigaDOS de gw') }
        elseif ($e.Enc -eq 'bit') { $r.Bits = 200000; $r.BitsSrc = (T 'image de cellules (raw), 1 us par cellule') }
        else { $r.Bits = 200000; $r.BitsSrc = (T 'format à secteurs haute densité, 1 us par cellule') }
        # 12.7 : note condensee sur une ligne (zone d information de la fenetre de la carte : etat des trois courbes visible
        # jusqu a la tete 1 sans defilement)
        $r.Notes += (T 'Disquette et lecteur HD nécessaires ; réglages provisoires.')
    }
    elseif ([int]$e.Rpm -ne 300) { $r.Why = ((T "format à {0} tr/min en double densité : aucune famille de calibration à cette vitesse") -f "$($e.Rpm)") }
    elseif ($e.Enc -eq 'bit' -and $rate -ne 250) { $r.Why = ((T "cellule de {0} ns, hors des plages mesurables (900 à 1 100 ns en haute densité, 1 700 à 2 300 ns en double densité)") -f "$([math]::Round(500000 / $rate))") }
    else {
        $r.Cal = 'std'
        if ($e.Enc -eq 'amiga') { $r.Bits = 101344; $r.BitsSrc = (T 'ADF, horloge AmigaDOS de gw') }
        else { $r.Bits = 100000; $r.BitsSrc = (T 'format à secteurs, 2 us par cellule') }
        if ($rate -gt 250) { $r.Notes += ((T "Débit de {0} kbit/s (cellule de {1} ns) : l'écriture de ce format applique la courbe {2}, mesurée à 2 us par cellule (densité plus forte de {3} %).") -f "$rate", "$([math]::Round(500000 / $rate))", (Get-CalibFamilyName 'std'), (Format-UiNum ([math]::Round(100.0 * ($rate - 250) / 250, 1)))) }
    }
    if ($r.Cal) {
        if ($e.Enc -eq 'fm0') { $r.Notes += (T 'Piste 0 en FM : non mesurée, la courbe s''y applique telle quelle.') }
        if ($r.Heads -eq 1) { $r.Notes += (T 'Format simple face : la calibration écrit aussi la face 1 (lecteur double face nécessaire).') }
        if ([int]$e.Cyls -ne 80) { $r.Notes += ((T "{0} cylindres dans la définition de gw.") -f "$($e.Cyls)") }
    }
    if (-not $grp) { $grp = $(if ($r.Cal) { 'other_dd' } else { 'other' }) }
    $r.Group = $grp
    return $r
}

function Get-HomeCalibInfo([string]$name) {
    # Type de disquette de la carte : format gw (Get-FormatCalibInfo) ou type d image de l application sans format gw.
    # 12.10 (relecture de la RC) : raisons d apres l ecriture (Start-ImageWrite, Test-RawFluxWrite, Get-ImageEncoding) : flux
    # decode avec la precompensation quand un format est choisi, IMD et D88 en FM ecrits sans precompensation
    $r = @{ Name = $name; Label = ''; Group = 'long'; Cal = $null; Why = ''; Notes = @(); NCyl = 0; Heads = 0; Bits = 0; BitsSrc = ''; Rate = 0 }
    switch ($name) {
        'app.long' {
            # 105 808 cellules : Get-PatternBits d une image long track illisible (105 820 ramene a un multiple de 16)
            $r.Label = (T 'Amiga longues pistes (IPF, HFE)'); $r.Cal = 'long'; $r.Bits = 105808; $r.NCyl = 80; $r.Heads = 2
            $r.BitsSrc = (T 'long track, 1,89 us par cellule')
            $r.Notes = @((T "Pistes longues d'une protection contre la copie : la cellule réelle et le nombre de cylindres (jusqu'à 84) se lisent dans l'image ; « Calibrer » dans l'onglet Écriture, avec l'image, les reprend exactement."))
            return $r
        }
        'app.flux' { $r.Label = (T 'Flux : SCP, RAW, KF, A2R, CTR'); $r.Why = (T "flux écrit tel quel sans format choisi (gw ne lui applique pas la précompensation) ; avec un format choisi, gw le décode et l'écrit avec la précompensation de sa famille ; pas de calibration sur un flux"); return $r }
        'app.free' {
            $r.Label = (T 'Géométrie libre : IMD, TD0, D88, MSA, DSK CPC'); $r.Group = 'other'
            $r.Why = ((T "densité non établie par l'application : l'écriture ne calibre pas, elle applique la courbe {0} (MFM), ou aucune précompensation pour un IMD ou un D88 en FM (codage lu dans l'en-tête) ; pour la calibrer, choisissez le format gw de la disquette (atarist.720 pour un MSA de 720 Ko, par exemple)") -f (Get-CalibFamilyName 'std'))
            return $r
        }
    }
    return (Get-FormatCalibInfo $name)
}

function Get-HomeCalibList {
    # Liste de la carte : types d image de l application, puis les formats de gw 1.23 dans l ordre de la table
    return @(@(@($script:HomeCalApp) + @($script:GwFormats.Keys)) | ForEach-Object { Get-HomeCalibInfo $_ })
}

function Get-HomeCurveState([string]$fam) {
    # Etat des courbes d une famille : commune et par tete (date, lecteur, test, cylindres, calcul, convergence)
    $lines = @()
    foreach ($k in @($fam, "${fam}_h0", "${fam}_h1")) {
        $cv = $script:PrecompCurves[$k]
        if (-not $cv) { $lines += ((T "{0} : aucune courbe") -f (Get-CurveKeyLabel $k)); continue }
        $tt = if ([string]$cv.Test -eq 'fine') { (T 'test fin') } elseif ([string]$cv.Test -eq 'std') { (T 'test standard') } else { (T 'test non enregistré') }
        $st = (T "{0} : {1}, lecteur {2}, {3}, {4} cylindres, calcul {5}") -f (Get-CurveKeyLabel $k), "$($cv.Date)", "$($cv.Drive)", "$tt", "$(@($cv.Values).Count)", (Get-CurveCalcText $cv)
        if ($cv.Converged -eq $false) { $st += (T ', NON CONVERGÉE') }
        $lines += $st
    }
    if ($script:PrecompCurves["${fam}_h0"] -and $script:PrecompCurves["${fam}_h1"] -and -not (Test-HeadCurvesCurrent $fam)) { $lines += (T 'Courbes par tête antérieures à la courbe commune : non appliquées.') }
    return ($lines -join "`r`n")
}

function New-CalibGeometry($info, [int]$nCyl) {
    # Image de geometrie de la carte : HFE du generateur du motif de test aux cylindres et aux cellules par piste du type
    # choisi. Get-ImageCylinders (en-tete), Get-ImageFamily, Get-PatternBits, Get-CellOutOfRange et Get-HighDensityReason
    # (table des pistes, 8 x (longueur // 2) = cellules) la lisent comme toute image HFE : la calibration complete ou
    # rapide en deduit famille, cylindres et densite. Cellules : 100 000 (2 000 ns), 101 344 (1 973,5 ns), 105 808
    # (1 890,2 ns, sous le seuil PrecompThresholdNs de 1 950 ns par defaut) ; 12.7 : 200 000 (1 000 ns) et 202 688
    # (986,7 ns, AmigaDOS HD) en haute densite. Debit de l en-tete : un tour a la vitesse du type, bits x tr/min / 120 000
    # (regle generale du motif ; 300 tr/min : expression d origine, bits / 400).
    if (-not (Test-Path -LiteralPath $script:TempDir)) { [void](New-Item -ItemType Directory -Path $script:TempDir -Force) }
    $path = Join-Path $script:TempDir 'precomp-geometry.hfe'
    $rpm = if ($info.Rpm) { [int]$info.Rpm } else { 300 }
    $rate = if ($rpm -eq 300) { [int][math]::Round($info.Bits / 400.0) } else { [int][math]::Round($info.Bits * $rpm / 120000.0) }
    [CalibPattern]::WriteHfe($path, $nCyl, [int]$info.Bits, $rate, 20261014)
    return $path
}

function Get-WriteTabFamily {
    # Famille de l image de l onglet Ecriture ; $null sans image, pour un flux ou une image haute densite non calibrable
    # (12.7 : 'hd' pour une haute densite calibrable)
    $p = $txtWFile.Text
    if (-not $p -or -not (Test-Path -LiteralPath $p)) { return $null }
    if (@('.scp', '.raw', '.kf', '.a2r', '.ctr') -contains [System.IO.Path]::GetExtension($p).ToLower()) { return $null }
    if (Get-HighDensityReason $p $cmbWFmt.Text) { return (Get-HdCalibFamily $p $cmbWFmt.Text) }
    return (Get-ImageFamily $p $cmbWFmt.Text)
}

function Start-HomeCalib([string]$name, [string]$test, [bool]$heads, [int]$nCyl, [bool]$warm = $true) {
    # Calibration de la carte, sans image : image de geometrie du type choisi, puis calibration complete (test 'std' ou
    # 'fine' ; warm : prechauffage du lecteur s il est regle) ou rapide ('level'). Pas de fenetre ici hors de celles de la
    # calibration (testable) : renvoie @{ Started ; Why } (Why vide : avertissement refuse par l utilisateur).
    $res = @{ Started = $false; Why = '' }
    if (Get-AppBusy) { $res.Why = (T 'opération en cours'); return $res }
    if (-not $script:ScpStatsOk) { $res.Why = (T "module d'analyse SCP indisponible (Add-Type)"); return $res }
    $info = Get-HomeCalibInfo $name
    if (-not $info.Cal) { $res.Why = $info.Why; return $res }
    $nCyl = [math]::Max(2, [math]::Min(84, $nCyl))
    try { $img = New-CalibGeometry $info $nCyl }
    catch { $res.Why = ((T "image de géométrie impossible à créer : {0}") -f "$($_.Exception.Message)"); return $res }
    # Seuil de famille de la configuration (precompThresholdNs) : la famille deduite de la geometrie doit etre celle du type
    $fam = Get-ImageFamily $img
    if ($fam -ne $info.Cal) { $res.Why = ((T "seuil de famille precompThresholdNs de {0} ns : ce type serait calibré dans la famille {1}") -f "$($script:PrecompThresholdNs)", (Get-CalibFamilyName $fam)); return $res }
    $script:HomeCalFmt = $name
    $geom = @{ Img = $img; Label = [string]$info.Label; Fmt = $name; BitsSrc = [string]$info.BitsSrc; CylSrc = ((T "{0} cylindres choisis dans l'Accueil") -f "$nCyl") }
    $script:AfterCalib = ''
    $tt = switch ($test) { 'level' { (T 'calibration rapide') } 'fine' { (T 'test fin') } default { (T 'test standard') } }
    $kt = if ($heads) { (T 'une courbe par tête') } else { (T 'courbe commune') }
    Append-Log ((T "Calibration depuis l'Accueil : type {0}, famille {1}, {2} cylindres, {3}, {4}.") -f "$($info.Label)", (Get-CalibFamilyName $fam), "$nCyl", "$kt", "$tt")
    if ($test -eq 'level') {
        $lr = Get-LevelRef $fam $heads $cmbDrive.Text $img $false -ForHome
        if (-not $lr.Ok) { $res.Why = ((T "calibration rapide impossible : {0}") -f "$($lr.Why)"); return $res }
        Start-LevelCalib $lr -Geom $geom
    } else {
        Start-PrecompCalib -Geom $geom -Heads $heads -Test $(if ($test -eq 'fine') { 'fine' } else { 'std' }) -NoWarmup:(-not $warm)
    }
    if (-not $script:Cal) { return $res }
    $script:HomeCalBusy = $true
    Update-HomeCalibCard
    $res.Started = $true
    return $res
}

function Update-HomeCalibCard {
    # Carte « Calibrer le lecteur » : progression d une calibration lancee depuis l Accueil (texte de la barre de l onglet
    # Ecriture), puis son bilan jusqu a la prochaine ouverture de la carte. Minuterie principale et Start-HomeCalib.
    # Progression trop longue pour le libelle de la carte (306 x 44, deux lignes) : details de la fin entre parentheses
    # retires (format court : avancement et temps restant en tete), plutot qu une troisieme ligne coupee
    $d = $cardCalib.Controls[3]
    if ($script:Cal -and $script:Cal.Home) {
        $t = $lblWCal.Text
        $tf = [System.Windows.Forms.TextFormatFlags]::WordBreak -bor [System.Windows.Forms.TextFormatFlags]::NoPrefix
        if ([System.Windows.Forms.TextRenderer]::MeasureText($t, $d.Font, (New-Object System.Drawing.Size($d.Width, 10000)), $tf).Height -gt $d.Height) { $t = $t -replace '\s*\([^()]*\)\s*$', '' }
        if ($d.Text -ne $t) { $d.Text = $t }
        $d.ForeColor = $script:Theme.Accent; return
    }
    $script:HomeCalBusy = $false
    $d.Text = $lblWCal.Text; $d.ForeColor = $script:Theme.Muted
}

function Update-HomeCalDescTip {
    # 12.10 (relecture de la RC) : texte complet de la description de la carte « Calibrer le lecteur » (306 x 44, deux
    # lignes, points de suspension : 540) en infobulle quand il depasse ses deux lignes (bilan d une calibration avec un
    # avertissement, recopie de l onglet Ecriture), aucune infobulle sinon ; appelee au changement de texte (540). Hauteur
    # mesuree a la largeur du libelle, sans borne, comme Update-WProfileTip (140)
    $d = $cardCalib.Controls[3]
    $h = $d.GetPreferredSize((New-Object System.Drawing.Size($d.Width, 0))).Height
    $tip.SetToolTip($d, $(if ($h -gt $d.Height) { [string]$d.Text } else { '' }))
}

# ============================== ACCUEIL : PROGRESSION ==========================
# Zone de l Accueil a la place du titre et du sous-titre (12.7) : toute calibration en cours ($script:Cal, rapide et
# prechauffage compris, quel que soit le point de depart) et tout prechauffage d une ecriture lente ($script:WriteWarm) ;
# puis bilan d une calibration lancee depuis l Accueil ($script:Cal.Home), jusqu a « Fermer », l ouverture d une carte ou
# une nouvelle operation. Barre et detail recopies de $pbWCal et $lblWCal (onglet Ecriture).

function Get-HomeProgFit([string]$t, $font, [int]$w) {
    # Texte sur une ligne de $w px : tel quel s il tient, sinon sans ses details de fin entre parentheses (comme
    # Update-HomeCalibCard), sinon coupe par des points de suspension (U+2026) au plus long qui tient, a la fin d un
    # mot si possible
    if (-not $t) { return '' }
    $tf = [System.Windows.Forms.TextFormatFlags]::NoPrefix -bor [System.Windows.Forms.TextFormatFlags]::SingleLine
    $sz = New-Object System.Drawing.Size(32000, 100)
    if ([System.Windows.Forms.TextRenderer]::MeasureText($t, $font, $sz, $tf).Width -le $w) { return $t }
    $s = $t -replace '\s*\([^()]*\)\s*$', ''
    if ($s -ne $t -and [System.Windows.Forms.TextRenderer]::MeasureText($s, $font, $sz, $tf).Width -le $w) { return $s }
    $e = [string][char]0x2026
    $n = 0; $lo = 1; $hi = $s.Length - 1
    while ($lo -le $hi) {
        $mid = [int][math]::Floor(($lo + $hi) / 2)
        if ([System.Windows.Forms.TextRenderer]::MeasureText(($s.Substring(0, $mid).TrimEnd() + $e), $font, $sz, $tf).Width -le $w) { $n = $mid; $lo = $mid + 1 } else { $hi = $mid - 1 }
    }
    if ($n -eq 0) { return $e }
    $p = $s.Substring(0, $n)
    $sp = $p.LastIndexOf(' ')
    if ($s[$n] -ne ' ' -and $sp -gt $n / 2) { $p = $p.Substring(0, $sp) }
    return ($p.TrimEnd(' ', ',', ';', ':', '(') + $e)
}

function Draw-HomeProgText($lbl, $e) {
    # Libelle de la zone desactive avec les onglets (Set-Busy, commande gw en cours) : texte redessine dans sa couleur,
    # sur une ligne, a la place du texte grise ; libelle actif : dessin habituel
    if ($lbl.Enabled -or -not $lbl.Text) { return }
    $b = New-Object System.Drawing.SolidBrush($lbl.BackColor)
    $e.Graphics.FillRectangle($b, $lbl.ClientRectangle); $b.Dispose()
    [System.Windows.Forms.TextRenderer]::DrawText($e.Graphics, $lbl.Text, $lbl.Font, $lbl.ClientRectangle, $lbl.ForeColor, ([System.Windows.Forms.TextFormatFlags]::NoPrefix -bor [System.Windows.Forms.TextFormatFlags]::SingleLine))
}

function Get-HomeProgTitle($cal, $ww) {
    # Titre de la zone pendant une calibration (lecteur, type de la carte ou famille, test, courbes) ou un prechauffage
    # d ecriture lente
    if ($cal) {
        $what = if ($cal.Home -and $cal.Geom -and $cal.Geom.Label) { [string]$cal.Geom.Label } else { Get-CalibFamilyName ([string]$cal.Family) }
        $kt = if ($cal.Slow) { (T 'une courbe par tête') } else { (T 'courbe commune') }
        # 12.8.1 : mesure de la disquette sur l image (276) : image et famille
        if ($cal.Mode -eq 'content') { return ((T 'Mesure de la disquette en cours : lecteur {0}, {1}') -f "$($cal.Drive)", "$([System.IO.Path]::GetFileName([string]$cal.Image)), $what") }
        if ($cal.Mode -eq 'level') { return ((T 'Calibration rapide en cours : lecteur {0}, {1}') -f "$($cal.Drive)", "$what, $kt") }
        $tt = if ($cal.Mode -eq 'fine') { (T 'test fin') } else { (T 'test standard') }
        # 12.10 : calibration croisee : les deux lecteurs
        if ($cal.Cross) { return ((T 'Calibration croisée en cours : écriture par le lecteur {0}, relecture par le lecteur {1}, {2}, {3}') -f "$($cal.Cross.Src)", "$($cal.Cross.Tgt)", "$what", "$tt, $kt") }
        return ((T 'Calibration en cours : lecteur {0}, {1}, {2}') -f "$($cal.Drive)", "$what", "$tt, $kt")
    }
    return ((T "Préchauffage avant l'écriture lente : lecteur {0}") -f "$($ww.Drive)")
}

function Get-CalibDoneTitle([string]$kind) {
    # 12.11 : titre du bilan d une calibration selon sa fin ('ok', 'warn', 'abandon', autre : arretee), extrait de
    # Update-HomeProgress : seule source du titre de la zone de l Accueil et de la barre d etat en fin de calibration
    switch ($kind) {
        'ok'      { return (T 'Calibration terminée : courbe convergée') }
        'warn'    { return (T 'Calibration terminée avec réserves : voir le journal') }
        'abandon' { return (T 'Calibration abandonnée') }
        default   { return (T 'Calibration arrêtée') }
    }
}

function Set-HomeProgDone($cal, [string]$kind, [string]$detail = '') {
    # Bilan d une calibration lancee depuis l Accueil (Complete-PrecompCalib, Complete-LevelCalib, Stop-PrecompCalib) :
    # 'ok', 'warn' (reserves acceptees), 'abandon' (refusee dans la fenetre de decision), 'stop' (arretee, sans mesure
    # exploitable). Detail : premiere raison de la fenetre de decision, sinon le libelle de l onglet Ecriture. Proc : gw
    # en cours a la fin (arret), qui n est pas une nouvelle operation. Sans effet pour une calibration lancee ailleurs.
    # 12.11 : barre d etat en fin de sequence (Set-SeqEnd, 110), quel que soit le point de depart : meme titre que la zone
    # de l Accueil, pour une calibration du lecteur seulement (test standard ou fin : complete, B, croisee). Calibration
    # rapide, mesure de la disquette sur l image (autres modes) et mesure complete d une seule disquette (DiskOnly) : le
    # titre ne les decrit pas, rien n est pose (regle generale d Update-SeqEnd). Calibration arretee ('stop') : le titre ne
    # remplace pas un etat deja en attente (-IfNone : restauration arretee pendant la calibration de son lecteur, dont le
    # verdict « Restauration echouee » vient d etre pose par Stop-Restore, appelee avant Stop-PrecompCalib)
    if ($cal -and @('std', 'fine') -contains [string]$cal.Mode -and -not $cal.DiskOnly) { Set-SeqEnd (Get-CalibDoneTitle $kind) $(if ($kind -eq 'ok') { 'ok' } else { 'idle' }) -IfNone:($kind -eq 'stop') }
    if (-not $cal -or -not $cal.Home) { return }
    if ($detail) { $detail = $detail.Substring(0, 1).ToUpper() + $detail.Substring(1) } else { $detail = [string]$lblWCal.Text }
    $script:HomeProgDone = @{ Kind = $kind; Detail = $detail; Family = [string]$cal.Family; Slow = [bool]$cal.Slow; Proc = $script:GwProc
                              Curve = ((Get-FamilyCurves ([string]$cal.Family) ([bool]$cal.Slow)).Count -gt 0) }
}

function Clear-HomeProgress {
    # « Fermer » de la zone, ouverture d une carte : bilan efface, titre et sous-titre de l Accueil remis
    $script:HomeProgDone = $null
    Update-HomeProgress
}

function Update-HomeProgress {
    # Minuterie principale. Modes : 'prog' (calibration ou prechauffage d ecriture lente en cours), 'hold' (fenetre de
    # decision ouverte apres une progression : titre « decision demandee », barre et detail gardes), 'done' (bilan),
    # 'none' (titre et sous-titre de l Accueil).
    # Un controle n est modifie que si sa valeur change ; l etat affiche est suivi dans HomeProgUi (la propriete Visible
    # d un controle d un onglet non affiche se lit fausse)
    if (-not $tabH -or -not $pnlHomeProg) { return }
    $u = $script:HomeProgUi
    $cal = $script:Cal; $ww = $script:WriteWarm; $d = $script:HomeProgDone
    if ($cal -or $ww) { $mode = 'prog'; if ($d) { $script:HomeProgDone = $null; $d = $null } }
    elseif ($script:HomeProgHold -and (@('prog', 'hold') -contains $u.Mode)) { $mode = 'hold' }
    elseif ($d) {
        # Nouvelle operation (gw hors detection des lecteurs, sequence, controle apres ecriture, restauration) : bilan efface
        $newGw = [bool]($script:GwProc -and -not $script:Detect -and -not [object]::ReferenceEquals($script:GwProc, $d.Proc))
        if ($newGw -or $script:Chain.Count -gt 0 -or $script:Rep -or $script:Restore) { $script:HomeProgDone = $null; $d = $null; $mode = 'none' } else { $mode = 'done' }
    } else { $mode = 'none' }
    $show = ($mode -ne 'none')
    if ($u.Shown -ne $show) {
        $u.Shown = $show
        $pnlHomeProg.Visible = $show; $lblHTitle.Visible = -not $show; $lblHSub.Visible = -not $show
    }
    $u.Mode = $mode
    if (-not $show) { return }
    # Lien du journal seulement s il est utilisable : pendant une commande gw, Set-Busy desactive les onglets, donc la
    # zone ; le bouton « Afficher journal » de la barre reste disponible
    $logLink = [bool]$split.Panel2Collapsed -and [bool]$tabs.Enabled
    if ($mode -eq 'done') {
        $title = Get-CalibDoneTitle ([string]$d.Kind)   # 12.11 : meme titre que la barre d etat en fin de calibration
        $src = [string]$d.Detail; $bar = $false; $curveLink = [bool]$d.Curve; $closeLink = $true
    } else {
        # Fenetre de decision ouverte (mode hold) : calibration terminee, barre et detail de sa fin gardes
        $title = if ($mode -eq 'prog') { Get-HomeProgTitle $cal $ww } else { (T 'Calibration terminée : décision demandée') }
        $src = [string]$lblWCal.Text; $bar = $true; $curveLink = $false; $closeLink = $false
    }
    # Liens a droite du titre (Fermer, Afficher la courbe, Afficher le journal) ; textes et place refaits a chaque
    # changement de liens ou de langue
    $lk = "$($script:Lang)|$([int]$logLink)$([int]$curveLink)$([int]$closeLink)"
    if ($u.Links -ne $lk) {
        $u.Links = $lk
        $lnkHProgLog.Text = (T 'Afficher le journal'); $lnkHProgCurve.Text = (T 'Afficher la courbe'); $lnkHProgClose.Text = (T 'Fermer')
        $x = $pnlHomeProg.Width
        foreach ($p in @(@($lnkHProgClose, $closeLink), @($lnkHProgCurve, $curveLink), @($lnkHProgLog, $logLink))) {
            $p[0].Visible = [bool]$p[1]
            if ($p[1]) { $x -= $p[0].PreferredWidth; $p[0].Left = $x; $x -= 14 }
        }
        $u.TitleW = [math]::Max(80, $x - 4)
        $lblHProgTitle.Width = $u.TitleW
        $u.RawTitle = $null; $u.Src = $null
    }
    if ($u.RawTitle -ne $title -or $null -eq $u.RawTitle) {
        $u.RawTitle = $title
        $t = Get-HomeProgFit $title $lblHProgTitle.Font ([int]$u.TitleW)
        if ($lblHProgTitle.Text -ne $t) { $lblHProgTitle.Text = $t }
    }
    if ($u.Src -ne $src -or $null -eq $u.Src) {
        $u.Src = $src
        $t = Get-HomeProgFit $src $lblHProgDetail.Font $lblHProgDetail.Width
        if ($lblHProgDetail.Text -ne $t) { $lblHProgDetail.Text = $t }
    }
    if ($u.Bar -ne $bar) { $u.Bar = $bar; $pbHProg.Visible = $bar }
    if ($bar) {
        # Barre : valeur et maximum de $pbWCal ; visible pendant toute progression (Visible de $pbWCal se lit faux quand
        # l onglet Ecriture n est pas affiche, il est vrai pendant toute calibration et tout prechauffage)
        if ($pbHProg.Maximum -ne $pbWCal.Maximum) { $pbHProg.Maximum = $pbWCal.Maximum }
        $v = [math]::Max($pbHProg.Minimum, [math]::Min($pbHProg.Maximum, [int]$pbWCal.Value))
        if ($pbHProg.Value -ne $v) { $pbHProg.Value = $v }
    }
}

function Update-HomeCalibDialog {
    # Fenetre de la carte : detail du type choisi, etat des courbes, durees, disponibilite du test rapide, prechauffage,
    # remplacement d une courbe d un autre lecteur ou d une autre geometrie (une courbe par famille, pour tous les lecteurs)
    $s = $script:HcDlg
    if (-not $s -or $s.Busy) { return }
    $s.Busy = $true
    try {
        $info = if ($s.Lv.SelectedItems.Count -gt 0) { $s.Lv.SelectedItems[0].Tag } else { $null }
        # Cylindres du type choisi ; 12.8 (point 7) : type enregistre, a sa premiere selection : cylindres de la derniere
        # calibration lancee (CylInit, reglage homeCalCyls)
        if ($info -and $s.Last -ne $info.Name) {
            $s.Last = $info.Name
            if ($info.Cal) { if ($s.CylInit -and $s.CylInit.Name -eq $info.Name) { Set-Num $s.Cyl $s.CylInit.N } else { Set-Num $s.Cyl $info.NCyl } }
            $s.CylInit = $null
        }
        $ok = [bool]($info -and $info.Cal)
        foreach ($c in @($s.Cyl, $s.Heads, $s.Std, $s.Fine, $s.Go)) { $c.Enabled = $ok }
        # « Calibrer » bleu seulement quand il est actif, sinon style normal grise (comme Set-CleanGo) ; style refait
        # seulement quand il change
        $gs = if ($ok) { 'primary' } else { 'normal' }
        if ($s.GoStyle -ne $gs) { $s.GoStyle = $gs; Set-Btn $s.Go 'Play' $gs }
        $s.Warn.Text = ''; $s.QuickTxt.Text = ''
        $wm = [double]$script:CalWarmupMinutes
        if (-not $info) { $s.Info.Text = (T 'Choisissez un type de disquette dans la liste.'); $s.Quick.Enabled = $false; $s.Curve.Enabled = $false; $s.Warm.Enabled = $false; return }
        if (-not $ok) {
            $s.Info.Text = ((T "{0}`r`n`r`nNon calibrable : {1}.") -f "$($info.Label)", "$($info.Why)")
            $s.Quick.Enabled = $false; $s.Curve.Enabled = $false; $s.Warm.Enabled = $false
            return
        }
        $fam = [string]$info.Cal; $heads = [bool]$s.Heads.Checked; $n = [int]$s.Cyl.Value
        $txt = (T "{0}`r`nFamille de calibration : {1} ({2} cellules par piste, {3} ns par cellule).") -f "$($info.Label)", (Get-CalibFamilyName $fam), "$($info.Bits)", (Format-UiNum ([math]::Round(200000000.0 / [double]$info.Bits, 1)))
        foreach ($nt in @($info.Notes)) { $txt += "`r`n" + $nt }
        $txt += "`r`n`r`n" + (Get-HomeCurveState $fam)
        $s.Info.Text = $txt
        $s.Curve.Enabled = ((Get-FamilyCurves $fam $heads).Count -gt 0)
        # Durees : memes estimations que Start-PrecompCalib (passes prevues, 1,4 s par piste et par phase, plus l effacement
        # haute frequence en double densite (12.8.2, Get-CalibEraseEst) et le conditionnement du lecteur (12.9), sans le
        # prechauffage, annonce par sa case) et Start-LevelCalib (2 passes)
        $np = $script:CalCoarse.Count + $script:CalMaxVerify
        $pt = 1.4 + (Get-CalibEraseEst ($fam -eq 'hd'))
        # 12.9 (correction 1) : conditionnement du lecteur en double densite : une ecriture sans relecture de tous les cylindres
        $cm = if ($fam -ne 'hd' -and [bool]$script:CalScaleDd.CalCondPass) { $n * 2 * (0.7 + (Get-CalibEraseEst $false)) / 60 } else { 0.0 }
        $nStd = @(0..($n - 1) | Where-Object { $_ % 10 -eq 0 }).Count + $(if (($n - 1) % 10 -ne 0) { 1 } else { 0 })
        # 12.8 (D9) : memes noms que la liste « Calibration précomp » de l onglet Ecriture (test standard, fin, rapide)
        $s.Std.Text = ((T "Test standard (calibration complète, 1 cylindre sur 10) : environ {0} min") -f "$([math]::Max(1, [math]::Round($nStd * 2 * $pt * $np / 60 + $cm, 0)))")
        # Haute densite : pas de calibration rapide (12.7), le test fin n en est pas la reference
        $fineMin = "$([math]::Max(1, [math]::Round($n * 2 * $pt * $np / 60 + $cm, 0)))"
        $s.Fine.Text = if ($fam -eq 'hd') { (T "Test fin (calibration complète, tous les cylindres) : environ {0} min") -f $fineMin } else { (T "Test fin (calibration complète, tous les cylindres) : environ {0} min ; référence du test rapide") -f $fineMin }
        $lr = Get-LevelRef $fam $heads $cmbDrive.Text '' $false -NCyl $n -Bits ([int]$info.Bits) -ForHome
        if ($lr.Ok) {
            $lc = @{}
            foreach ($u in @($lr.Units)) { foreach ($c in @(@($u.LCyls) + @($u.Wit) + @($(if ($null -ne $u.Probe) { $u.Probe })))) { $lc[[int]$c] = $true } }
            $s.Quick.Enabled = $true
            # 12.8 (lot 1c) : par tete, 2 passes en general, 3 avec 2 cylindres de controle quand la forme est adaptee
            $qLo = [math]::Max(1, [math]::Round($lc.Count * 2 * $pt * 2 / 60, 0))
            if ($heads) {
                $qHi = [math]::Max($qLo, [math]::Round(($lc.Count + [int]$script:LevelAdaptCtlCyls) * 2 * $pt * 3 / 60, 0))
                $qd = if ($qHi -gt $qLo) { (T '{0} à {1}') -f "$qLo", "$qHi" } else { "$qLo" }
                $s.Quick.Text = ((T "Test rapide (niveau et forme de la disquette insérée) : {0} min") -f "$qd")
            } else { $s.Quick.Text = ((T "Test rapide (niveau de la disquette insérée) : environ {0} min") -f "$qLo") }
            $s.QuickTxt.Text = ((T "Forme reprise de la calibration complète du {0}. Insérez la disquette que vous allez écrire : le profil obtenu ne vaut que pour elle.") -f "$($lr.Units[0].Cv.Date)")
        } else {
            if ($s.Quick.Checked) { $s.Fine.Checked = $true }
            $s.Quick.Enabled = $false
            $s.Quick.Text = (T 'Test rapide (niveau de la disquette insérée)')
            $s.QuickTxt.Text = ((T "Indisponible : {0}.") -f "$($lr.Why)")
        }
        # Prechauffage : calibration complete seulement (la calibration rapide mesure le lecteur dans son etat du moment)
        $s.Warm.Enabled = ($wm -gt 0 -and -not $s.Quick.Checked)
        if (-not $s.Quick.Checked) {
            # Courbe remplacee : tete 0 par tete, sinon la courbe commune (cle calculee directement : affecter le resultat
            # d un if deroulerait un tableau d un seul element en chaine, et $keys[0] serait son premier caractere)
            $cv = $script:PrecompCurves[$(if ($heads) { "${fam}_h0" } else { $fam })]
            # 12.10 : courbes par lecteur : la courbe en place est celle du lecteur du bandeau, plus d avertissement d un autre lecteur
            $w = @()
            if ($cv -and [math]::Abs(@($cv.Values).Count - $n) -gt 4) { $w += ((T "La courbe actuelle couvre {0} cylindres : elle sera remplacée par une courbe de {1} cylindres, appliquée à toutes les images de la famille {2}.") -f "$(@($cv.Values).Count)", "$n", (Get-CalibFamilyName $fam)) }
            $s.Warn.Text = ($w -join "`r`n")
        }
    } finally { $s.Busy = $false }
}

function Show-HomeCalib {
    # Fenetre de la carte « Calibrer le lecteur ». Refusee pendant une operation. « Calibrer » ferme la fenetre, puis
    # Start-HomeCalib affiche l avertissement habituel de la calibration (Show-CalibConfirm) : pas de fenetres modales
    # imbriquees. Le type choisi est enregistre (ui.homeCalFormat) a la fermeture, lance ou non.
    if (Get-AppBusy) {
        [void](Show-AppMessage (T "Opération en cours : ouvrez la calibration une fois l'opération terminée.") (T 'Calibration precomp') 'OK' 'Information'); return
    }
    if ($script:HomeCalDesc) { $cardCalib.Controls[3].Text = $script:HomeCalDesc; $cardCalib.Controls[3].ForeColor = $script:Theme.Muted }
    $dlg = New-Object System.Windows.Forms.Form
    $dlg.Name = 'frmHomeCalib'; $dlg.Text = (T 'Calibrer le lecteur')
    $dlg.FormBorderStyle = 'FixedDialog'; $dlg.MaximizeBox = $false; $dlg.MinimizeBox = $false; $dlg.ShowInTaskbar = $false
    $dlg.StartPosition = 'CenterParent'; $dlg.Icon = $form.Icon; $dlg.Font = $form.Font; $dlg.BackColor = [System.Drawing.Color]::White
    # Hauteur : zone d avertissement de 106 px (deux avertissements de remplacement de courbe, en francais et en anglais)
    $dlg.ClientSize = New-Object System.Drawing.Size(960, 676)
    $htip = New-Object System.Windows.Forms.ToolTip
    $htip.AutoPopDelay = 30000; $htip.InitialDelay = 400; $htip.ReshowDelay = 100
    $intro = New-Object System.Windows.Forms.Label
    $intro.AutoSize = $false; $intro.UseMnemonic = $false; $intro.Location = '16,12'; $intro.Size = '928,40'
    $intro.Text = ((T "Choisissez le type de disquette. La calibration mesure la précompensation du lecteur {0} sur une disquette sacrifiée, à la densité de ce type ; la courbe obtenue s'applique ensuite à toutes les images de sa famille. Aucune image n'est nécessaire.") -f "$($cmbDrive.Text)")
    $lv = New-Object System.Windows.Forms.ListView
    $lv.Name = 'lvHcFmt'; $lv.Location = '16,58'; $lv.Size = '540,556'; $lv.View = 'Details'; $lv.FullRowSelect = $true
    $lv.HideSelection = $false; $lv.MultiSelect = $false; $lv.HeaderStyle = 'Nonclickable'; $lv.ShowItemToolTips = $true
    [void]$lv.Columns.Add((T 'Type'), 300); [void]$lv.Columns.Add((T 'Géométrie'), 80); [void]$lv.Columns.Add((T 'Calibration (famille)'), 136)
    $gn = [ordered]@{ amiga_dd = (T 'Amiga double densité'); amiga_hd = (T 'Amiga haute densité'); pc_dd = (T 'PC et Atari ST double densité')
                      hd = (T 'Haute densité : PC et autres'); long = (T 'Images longues pistes et protégées'); gcr = (T 'GCR : Commodore 64, Apple II, Macintosh')
                      fm = (T 'FM (simple densité)'); other_dd = (T 'Autres formats MFM double densité'); other = (T 'Autres formats') }
    $groups = @{}
    foreach ($k in @($gn.Keys)) { $g = New-Object System.Windows.Forms.ListViewGroup([string]$k, [string]$gn[$k]); [void]$lv.Groups.Add($g); $groups[$k] = $g }
    $sel = $null
    foreach ($info in @(Get-HomeCalibList)) {
        $it = New-Object System.Windows.Forms.ListViewItem([string]$info.Label)
        [void]$it.SubItems.Add($(if ($info.NCyl -gt 0) { "$($info.NCyl) × $($info.Heads)" } else { '-' }))
        [void]$it.SubItems.Add($(if ($info.Cal) { Get-CalibFamilyName $info.Cal } else { (T 'non calibrable') }))
        $it.ToolTipText = $(if ($info.Cal) { ((T "Famille {0}") -f (Get-CalibFamilyName $info.Cal)) } else { [string]$info.Why })
        if (-not $info.Cal) { $it.ForeColor = $script:Theme.Muted }
        $it.Tag = $info; $it.Group = $groups[[string]$info.Group]
        [void]$lv.Items.Add($it)
        if ($info.Name -eq $script:HomeCalFmt) { $sel = $it }
    }
    $tbInfo = New-Object System.Windows.Forms.TextBox
    $tbInfo.Name = 'tbHcInfo'; $tbInfo.Multiline = $true; $tbInfo.ReadOnly = $true; $tbInfo.ScrollBars = 'Vertical'; $tbInfo.TabStop = $false
    $tbInfo.Location = '572,58'; $tbInfo.Size = '372,196'; $tbInfo.BackColor = $script:Theme.Page
    $lblCyl = New-Object System.Windows.Forms.Label; $lblCyl.Text = (T 'Cylindres :'); $lblCyl.AutoSize = $true; $lblCyl.Location = '572,267'
    $numCyl = New-Object System.Windows.Forms.NumericUpDown
    $numCyl.Name = 'numHcCyl'; $numCyl.Minimum = 35; $numCyl.Maximum = 84; $numCyl.Value = 80; $numCyl.Width = 60; $numCyl.Location = '680,264'
    $htip.SetToolTip($numCyl, (T "Cylindres de test : ceux du format par défaut. Un lecteur 5,25 pouces 40 pistes : 40 ; un long track : jusqu'à 84 si le lecteur y accède."))
    # 12.8 (point 7) : choix de la fenetre lus a l ouverture dans les reglages, ecrits au lancement de la calibration :
    # courbe par tete (homeCalHeads, propre a la carte, D9 : cochee par defaut), prechauffage (warmFullCalib, celui de
    # l onglet Ecriture, D6), test (calMode, celui de la liste de l onglet Ecriture), cylindres (homeCalCyls, pour le type
    # enregistre)
    $chkHeads = New-Object System.Windows.Forms.CheckBox
    $chkHeads.Name = 'chkHcHeads'; $chkHeads.Text = (T 'Une courbe par tête (écriture lente et restauration)'); $chkHeads.Location = '572,292'; $chkHeads.Size = '372,24'; $chkHeads.Checked = [bool](Get-Setting 'homeCalHeads')
    $htip.SetToolTip($chkHeads, (T "Coché : une courbe par tête, celle de l'écriture lente et de la restauration.`nDécoché : une courbe commune aux deux têtes, celle de l'écriture rapide."))
    # Prechauffage de la calibration complete : reglage warmFullCalib, case inactive quand la duree vaut 0
    $wm = [double]$script:CalWarmupMinutes
    $wmt = Get-WarmMinutesText $wm
    $chkWarm = New-Object System.Windows.Forms.CheckBox
    $chkWarm.Name = 'chkHcWarm'; $chkWarm.Location = '572,318'; $chkWarm.Size = '372,36'; $chkWarm.Checked = ($wm -gt 0 -and [bool](Get-Setting 'warmFullCalib')); $chkWarm.Enabled = ($wm -gt 0)
    $chkWarm.Text = if ($wm -gt 0) { (T "Préchauffer le lecteur avant la calibration complète ({0} au plus de lecture sans écriture)") -f "$wmt" } else { (T "Préchauffer le lecteur avant la calibration complète (désactivé : durée du préchauffage à 0)") }
    # 12.11 (L12a) : case et duree du prechauffage de l onglet Ecriture dans ses options avancees (lot L9) : l infobulle le dit
    $htip.SetToolTip($chkWarm, (T "Avant une calibration complète (bouton « Calibrer », carte « Calibrer le lecteur » de l'Accueil, calibration automatique avant une écriture) : lectures sans écriture des cylindres de test avant la première passe, pour stabiliser la température du lecteur ; réduites ou sautées si le lecteur vient de servir. Décochée : la calibration commence tout de suite.`nMême réglage dans les options avancées de l'onglet Écriture et dans la fenêtre de la carte « Calibrer le lecteur ». Durée : champ « Durée du préchauffage », dans les options avancées de l'onglet Écriture.`nLa calibration rapide (test rapide) n'a pas de préchauffage propre : avant une écriture lente, elle suit la case « Préchauffer le lecteur avant l'écriture lente »."))
    $rbStd = New-Object System.Windows.Forms.RadioButton;   $rbStd.Name = 'rbHcStd';     $rbStd.Location = '572,356';   $rbStd.Size = '372,36'
    $rbFine = New-Object System.Windows.Forms.RadioButton;  $rbFine.Name = 'rbHcFine';   $rbFine.Location = '572,394';  $rbFine.Size = '372,36'
    $rbQuick = New-Object System.Windows.Forms.RadioButton; $rbQuick.Name = 'rbHcQuick'; $rbQuick.Location = '572,432'; $rbQuick.Size = '372,36'
    $lblQuick = New-Object System.Windows.Forms.Label
    $lblQuick.Name = 'lblHcQuick'; $lblQuick.AutoSize = $false; $lblQuick.UseMnemonic = $false; $lblQuick.Location = '590,468'; $lblQuick.Size = '354,52'; $lblQuick.ForeColor = $script:Theme.Muted
    # Hauteurs mesurees (Segoe UI 9,75) : texte du test rapide 51 px (3 lignes), deux avertissements 102 px en francais
    $lblWarn = New-Object System.Windows.Forms.Label
    $lblWarn.Name = 'lblHcWarn'; $lblWarn.AutoSize = $false; $lblWarn.UseMnemonic = $false; $lblWarn.Location = '572,522'; $lblWarn.Size = '372,104'; $lblWarn.ForeColor = $script:Theme.WarnInk   # 12.8 (FIX5, D17) : encre du texte d avertissement
    $btnCurve = New-Object System.Windows.Forms.Button; $btnCurve.Name = 'btnHcCurve'; $btnCurve.Text = (T 'Afficher la courbe'); $btnCurve.Size = New-Object System.Drawing.Size(190, 34); $btnCurve.Location = '16,628'
    $btnClose = New-Object System.Windows.Forms.Button; $btnClose.Name = 'btnHcClose'; $btnClose.Text = (T 'Fermer'); $btnClose.Size = New-Object System.Drawing.Size(110, 34); $btnClose.Location = '834,628'
    $btnGo = New-Object System.Windows.Forms.Button; $btnGo.Name = 'btnHcGo'; $btnGo.Text = (T 'Calibrer'); $btnGo.Size = New-Object System.Drawing.Size(160, 34); $btnGo.Location = '666,628'
    $btnClose.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
    Set-Btn $btnCurve 'Diagnostic' 'normal'; Set-Btn $btnGo 'Play' 'primary'; Set-Btn $btnClose '' 'normal'
    $dlg.CancelButton = $btnClose                     # pas d AcceptButton : Entree dans la liste ne lance rien
    $dlg.Controls.AddRange(@($intro, $lv, $tbInfo, $lblCyl, $numCyl, $chkHeads, $chkWarm, $rbStd, $rbFine, $rbQuick, $lblQuick, $lblWarn, $btnCurve, $btnGo, $btnClose))
    # Mode par defaut : reglage calMode, celui de l onglet Ecriture (test standard, fin ou rapide) ; rapide indisponible :
    # test fin
    $prevFmt = [string]$script:HomeCalFmt
    switch ([string](Get-Setting 'calMode')) { 'level' { $rbQuick.Checked = $true } 'fine' { $rbFine.Checked = $true } default { $rbStd.Checked = $true } }
    # 12.8 (point 7) : cylindres de la derniere calibration lancee, pour le type enregistre (reglage homeCalCyls, 0 :
    # cylindres du type), appliques a sa premiere selection (Update-HomeCalibDialog)
    $hcc = [int](Get-Setting 'homeCalCyls')
    $cylInit = if ($hcc -ge $numCyl.Minimum -and $hcc -le $numCyl.Maximum) { @{ Name = [string]$script:HomeCalFmt; N = $hcc } } else { $null }
    $script:HcDlg = @{ Dlg = $dlg; Lv = $lv; Info = $tbInfo; Cyl = $numCyl; Heads = $chkHeads; Warm = $chkWarm; Std = $rbStd; Fine = $rbFine; Quick = $rbQuick
                       QuickTxt = $lblQuick; Warn = $lblWarn; Curve = $btnCurve; Go = $btnGo; GoStyle = 'primary'; Busy = $false; Last = ''; Choice = $null; CylInit = $cylInit }
    $lv.Add_SelectedIndexChanged({ Update-HomeCalibDialog })
    $numCyl.Add_ValueChanged({ Update-HomeCalibDialog })
    $chkHeads.Add_CheckedChanged({ Update-HomeCalibDialog })
    foreach ($rb in @($rbStd, $rbFine, $rbQuick)) { $rb.Add_CheckedChanged({ if ($this.Checked) { Update-HomeCalibDialog } }) }
    $btnCurve.Add_Click({
        $s = $script:HcDlg
        if ($s.Lv.SelectedItems.Count -gt 0 -and $s.Lv.SelectedItems[0].Tag.Cal) { Show-PrecompCurve ([string]$s.Lv.SelectedItems[0].Tag.Cal) ([bool]$s.Heads.Checked) -Owner $s.Dlg }
    })
    $btnGo.Add_Click({
        $s = $script:HcDlg
        if ($s.Lv.SelectedItems.Count -eq 0 -or -not $s.Lv.SelectedItems[0].Tag.Cal) { return }
        $t = if ($s.Quick.Checked) { 'level' } elseif ($s.Fine.Checked) { 'fine' } else { 'std' }
        $s.Choice = @{ Name = [string]$s.Lv.SelectedItems[0].Tag.Name; Test = $t; Heads = [bool]$s.Heads.Checked; NCyl = [int]$s.Cyl.Value; Warm = [bool]($s.Warm.Enabled -and $s.Warm.Checked)
                       WarmEn = [bool]$s.Warm.Enabled; WarmChk = [bool]$s.Warm.Checked; QuickEn = [bool]$s.Quick.Enabled }
        $s.Dlg.DialogResult = [System.Windows.Forms.DialogResult]::OK
    })
    $dlg.Add_Shown({ $s = $script:HcDlg; if ($s) { if ($s.Lv.SelectedItems.Count -gt 0) { $s.Lv.SelectedItems[0].EnsureVisible() }; [void]$s.Lv.Focus() } })
    if ($sel) { $sel.Selected = $true; $sel.Focused = $true }
    Update-HomeCalibDialog
    # 12.8 (lot 5, A4 R1) : ecran plus bas que la fenetre (676 px de zone client) : hauteur de la zone de travail, defilement
    [void](Set-DlgFit $dlg ([System.Windows.Forms.Screen]::FromControl($form).WorkingArea))
    $dr = [System.Windows.Forms.DialogResult]::Cancel; $ch = $null; $last = ''
    try { $dr = $dlg.ShowDialog($form) }
    finally {
        if ($script:HcDlg) { $ch = $script:HcDlg.Choice; $last = [string]$script:HcDlg.Last }
        $script:HcDlg = $null; $htip.Dispose(); $dlg.Dispose()
    }
    if ($last) { $script:HomeCalFmt = $last }
    if ($dr -ne [System.Windows.Forms.DialogResult]::OK -or -not $ch) {
        # Type change sans calibration : cylindres retenus effaces (ils valaient pour l ancien type)
        if ($last -and $last -ne $prevFmt) { Set-Setting 'homeCalCyls' 0 }
        [void](Save-Config); return
    }
    $r = Start-HomeCalib $ch.Name $ch.Test $ch.Heads $ch.NCyl $ch.Warm
    # 12.8 (point 7) : choix de la fenetre ecrits dans les reglages une fois la calibration lancee (Start-HomeCalib les
    # recoit en parametres). Prechauffage : seulement si la case etait active (calibration complete, duree non nulle).
    # Test : celui de la liste de l onglet Ecriture, sauf quand le test rapide etait indisponible et la liste au test
    # rapide : la calibration complete en test fin lancee ici en devient la reference, le mode de l onglet est garde
    if ($r.Started) {
        Set-Setting 'homeCalHeads' $ch.Heads
        Set-Setting 'homeCalCyls' $ch.NCyl
        if ($ch.WarmEn) { Set-Setting 'warmFullCalib' $ch.WarmChk }
        if ($ch.QuickEn -or (Get-Setting 'calMode') -ne 'level') { Set-Setting 'calMode' $ch.Test }
    } elseif ($last -and $last -ne $prevFmt) { Set-Setting 'homeCalCyls' 0 }
    [void](Save-Config)
    if (-not $r.Started -and $r.Why) {
        # 12.8 (lot 5) : Show-AppMessage ecrit le message au journal (plus de ligne de journal en double)
        [void](Show-AppMessage ((T "Calibration non lancée : {0}.") -f "$($r.Why)") (T 'Calibration precomp') 'OK' 'Information')
    }
}
# ============================== FONCTIONS : NETTOYAGE DES TETES ================

# ============================== NETTOYAGE DES TETES : PICTOGRAMMES =============
# Vignettes 120 x 84 des etapes du nettoyage, dessinees en GDI+ comme le logo (aucun fichier image) : disquette 3,5
# pouces du logo, facade de lecteur, fleches, gouttes, horloge. Couleurs du theme.

function Draw-PictoFloppy($g, [single]$x, [single]$y, [single]$s, [bool]$cleaning, [bool]$flip = $false) {
    # Disquette 3,5 pouces du logo (repere 0..64) en ($x, $y), cote $s, volet en haut ; $flip : volet en bas (vers la
    # fente du lecteur). Nettoyage : corps bleu, tissu dans la fenetre du volet, etiquette CLEAN ; donnees : flux du logo
    $st = $g.Save()
    if ($flip) { $g.TranslateTransform([single]($x + $s), [single]($y + $s)); $g.RotateTransform([single]180) }
    else { $g.TranslateTransform($x, $y) }
    $g.ScaleTransform([single]($s / 64.0), [single]($s / 64.0))
    $body = New-Object System.Drawing.Drawing2D.GraphicsPath
    $body.AddPolygon([System.Drawing.PointF[]]@((New-Object System.Drawing.PointF(5, 4)), (New-Object System.Drawing.PointF(53, 4)),
        (New-Object System.Drawing.PointF(60, 11)), (New-Object System.Drawing.PointF(60, 58)), (New-Object System.Drawing.PointF(57, 61)),
        (New-Object System.Drawing.PointF(8, 61)), (New-Object System.Drawing.PointF(5, 58))))
    $cBody = if ($cleaning) { [System.Drawing.Color]::FromArgb(58, 104, 160) } else { $script:Theme.Floppy }
    $bBody = New-Object System.Drawing.SolidBrush($cBody)
    $bMetal = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(205, 212, 222))
    $bLabel = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(248, 249, 252))
    $g.FillPath($bBody, $body)
    $pShutter = New-RoundRect 17 4 30 20 2; $g.FillPath($bMetal, $pShutter); $pShutter.Dispose()   # 12.8 (FIX5) : chemin libere
    if ($cleaning) {
        $hb = New-Object System.Drawing.Drawing2D.HatchBrush([System.Drawing.Drawing2D.HatchStyle]::Weave, [System.Drawing.Color]::FromArgb(170, 188, 214), [System.Drawing.Color]::White)
        $g.FillRectangle($hb, [single]34, [single]7, [single]11, [single]14); $hb.Dispose()
    } else { $g.FillRectangle($bBody, [single]36, [single]8, [single]7, [single]12) }
    $pLabel = New-RoundRect 11 31 42 26 2.5; $g.FillPath($bLabel, $pLabel); $pLabel.Dispose()
    if ($cleaning) {
        $f = New-Object System.Drawing.Font('Segoe UI', [single]11, [System.Drawing.FontStyle]::Bold, [System.Drawing.GraphicsUnit]::Pixel)
        $sf = New-Object System.Drawing.StringFormat; $sf.Alignment = 'Center'; $sf.LineAlignment = 'Center'
        # disquette retournee : etiquette lisible quand meme (dernier trace avant Restore)
        $rc = New-Object System.Drawing.RectangleF(11, 31, 42, 26)
        if ($flip) { $g.TranslateTransform([single]32, [single]44); $g.RotateTransform([single]180); $rc = New-Object System.Drawing.RectangleF(-21, -13, 42, 26) }
        $g.DrawString('CLEAN', $f, $bBody, $rc, $sf)
        $f.Dispose(); $sf.Dispose()
    } else {
        $pen = New-Object System.Drawing.Pen($script:Theme.Flux, [single]2.6); $pen.LineJoin = [System.Drawing.Drawing2D.LineJoin]::Round
        $xs = @(14, 18, 18, 22, 22, 28, 28, 31, 31, 37, 37, 41, 41, 45, 45, 50); $ys = @(48, 48, 39, 39, 48, 48, 39, 39, 48, 48, 39, 39, 48, 48, 39, 39)
        $g.DrawLines($pen, [System.Drawing.PointF[]]@(for ($i = 0; $i -lt $xs.Count; $i++) { New-Object System.Drawing.PointF($xs[$i], $ys[$i]) }))
        $pen.Dispose()
    }
    $bBody.Dispose(); $bMetal.Dispose(); $bLabel.Dispose(); $body.Dispose()
    $g.Restore($st)
}

function Draw-PictoDrive($g, [bool]$on) {
    # Facade de lecteur 3,5 pouces en bas de la vignette : fente, voyant (vert : moteur en marche), bouton d ejection
    # 12.8 (FIX5) : chemins de New-RoundRect liberes
    $p = New-RoundRect 6 56 108 26 4
    $b = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(64, 70, 84)); $g.FillPath($b, $p); $b.Dispose(); $p.Dispose()
    $b = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(18, 22, 30)); $g.FillRectangle($b, [single]20, [single]62, [single]80, [single]5); $b.Dispose()
    $p = New-RoundRect 80 72 16 5 2
    $b = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(150, 156, 168)); $g.FillPath($b, $p); $b.Dispose(); $p.Dispose()
    $cl = if ($on) { [System.Drawing.Color]::FromArgb(90, 220, 110) } else { [System.Drawing.Color]::FromArgb(48, 78, 58) }
    $b = New-Object System.Drawing.SolidBrush($cl); $g.FillRectangle($b, [single]24, [single]73, [single]10, [single]3); $b.Dispose()
}

function Draw-PictoArrow($g, [System.Drawing.Color]$c, [single]$x1, [single]$y1, [single]$x2, [single]$y2) {
    $pen = New-Object System.Drawing.Pen($c, [single]3)
    $pen.CustomEndCap = New-Object System.Drawing.Drawing2D.AdjustableArrowCap(3, 3)
    $g.DrawLine($pen, $x1, $y1, $x2, $y2); $pen.Dispose()
}

function Fill-PictoDrop($g, $brush, [single]$cx, [single]$cy, [single]$r) {
    # Goutte : cercle de rayon $r centre en ($cx, $cy), pointe 2,2 $r au-dessus du centre
    $p = New-Object System.Drawing.Drawing2D.GraphicsPath
    $p.AddArc([single]($cx - $r), [single]($cy - $r), [single](2 * $r), [single](2 * $r), [single]-27, [single]234)
    $p.AddLine($p.GetLastPoint(), (New-Object System.Drawing.PointF($cx, [single]($cy - 2.2 * $r))))
    $p.CloseFigure(); $g.FillPath($brush, $p); $p.Dispose()
}

function Draw-PictoClock($g, [single]$cx, [single]$cy, [single]$r, $color = $null) {
    # 12.8 (lot 3) : couleur du trait en parametre (Theme.Accent par defaut) : pictogrammes de qualite en cours et perimes
    $pen = New-Object System.Drawing.Pen($(if ($color) { [System.Drawing.Color]$color } else { $script:Theme.Accent }), [single]2.5)
    $g.FillEllipse([System.Drawing.Brushes]::White, [single]($cx - $r), [single]($cy - $r), [single](2 * $r), [single](2 * $r))
    $g.DrawEllipse($pen, [single]($cx - $r), [single]($cy - $r), [single](2 * $r), [single](2 * $r))
    $g.DrawLine($pen, $cx, $cy, $cx, [single]($cy - 0.65 * $r)); $g.DrawLine($pen, $cx, $cy, [single]($cx + 0.5 * $r), $cy)
    $pen.Dispose()
}

function New-CleanPicto([string]$kind) {
    # Vignette d une etape : disk (disquette de nettoyage), drops (alcool sur le tissu), insert, run (zigzag de la tete),
    # dry (retirer, laisser secher), forbid (disquette de donnees barree : avertissement)
    $bmp = New-Object System.Drawing.Bitmap(120, 84, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
    $g = [System.Drawing.Graphics]::FromImage($bmp)
    $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
    $g.TextRenderingHint = [System.Drawing.Text.TextRenderingHint]::AntiAliasGridFit
    switch ($kind) {
        'disk' { Draw-PictoFloppy $g 26 2 80 $true }
        'drops' {
            Draw-PictoFloppy $g 2 18 66 $true
            # flacon incline vers la fenetre du volet, trois gouttes
            $st = $g.Save(); $g.TranslateTransform([single]96, [single]30); $g.RotateTransform([single]-100)
            $bw = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::White); $pen = New-Object System.Drawing.Pen($script:Theme.Accent, [single]2)
            $bp = New-RoundRect -13 -10 26 30 4; $g.FillPath($bw, $bp); $g.DrawPath($pen, $bp)
            $g.FillRectangle($bw, [single]-5, [single]-19, [single]10, [single]9); $g.DrawRectangle($pen, [single]-5, [single]-19, [single]10, [single]9)
            $g.Restore($st)
            $f = New-Object System.Drawing.Font('Segoe UI', [single]10, [System.Drawing.FontStyle]::Bold, [System.Drawing.GraphicsUnit]::Pixel)
            $sf = New-Object System.Drawing.StringFormat; $sf.Alignment = 'Center'; $sf.LineAlignment = 'Center'
            $bt = New-Object System.Drawing.SolidBrush($script:Theme.Accent)
            $g.DrawString('IPA', $f, $bt, (New-Object System.Drawing.RectangleF(84, 50, 30, 14)), $sf)
            $bd = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(70, 150, 230))
            Fill-PictoDrop $g $bd 70 32 3.2; Fill-PictoDrop $g $bd 60 26 3.2; Fill-PictoDrop $g $bd 50 34 3.2
            $bw.Dispose(); $pen.Dispose(); $f.Dispose(); $sf.Dispose(); $bt.Dispose(); $bd.Dispose(); $bp.Dispose()
        }
        'insert' {
            Draw-PictoFloppy $g 38 0 44 $true $true
            Draw-PictoDrive $g $false
            Draw-PictoArrow $g $script:Theme.Accent 98 10 98 50
        }
        'run' {
            Draw-PictoDrive $g $true
            # va-et-vient de la tete sur toute la surface : zigzag termine par une fleche
            $pen = New-Object System.Drawing.Pen($script:Theme.Flux, [single]3); $pen.LineJoin = [System.Drawing.Drawing2D.LineJoin]::Round
            $pen.CustomEndCap = New-Object System.Drawing.Drawing2D.AdjustableArrowCap(3, 3)
            $xs = @(12, 26, 40, 54, 68, 82, 96, 110); $pts = for ($i = 0; $i -lt $xs.Count; $i++) { New-Object System.Drawing.PointF($xs[$i], $(if ($i % 2) { 12 } else { 40 })) }
            $g.DrawLines($pen, [System.Drawing.PointF[]]$pts); $pen.Dispose()
        }
        'dry' {
            Draw-PictoFloppy $g 10 0 44 $true $true
            Draw-PictoDrive $g $false
            Draw-PictoArrow $g $script:Theme.Accent 62 46 62 8
            Draw-PictoClock $g 92 26 18
        }
        'forbid' {
            Draw-PictoFloppy $g 24 2 72 $false
            $pen = New-Object System.Drawing.Pen($script:Theme.Danger, [single]7)
            $g.DrawEllipse($pen, [single]22, [single]4, [single]76, [single]76); $g.DrawLine($pen, [single]35, [single]17, [single]85, [single]67)
            $pen.Dispose()
        }
    }
    $g.Dispose()
    return $bmp
}

function Get-CleanSeconds([int]$passes, [int]$linger, [int]$cyls) {
    # Duree estimee de gw clean avec les delais d usine du firmware (pas 10 ms, stabilisation 15 ms, moteur 750 ms) :
    # meme parcours que clean.py, tete partant du cylindre 0. Estimation : les reglages de l onglet Delais l allongent
    $step = [math]::Max([math]::Floor($cyls / 8), 2)
    $pos = 0; $steps = 0; $stops = 0
    for ($p = 0; $p -lt $passes; $p++) {
        for ($c = 0; $c -lt $cyls; $c += $step) {
            foreach ($t in @([math]::Min($c + $step - 1, $cyls - 1), $c)) { $steps += [math]::Abs($t - $pos); $pos = $t; $stops++ }
        }
    }
    return 0.75 + 0.010 * $steps + $stops * (0.015 + $linger / 1000.0)
}

function Get-CleanPresets {
    # Standard : 3 passes de 500 ms, environ 30 s (un cycle de la notice 3M) ; Courte : reglage de gw ; Longue : 8 passes
    return @(
        @{ Name = (T 'Standard : 3 passes, 500 ms par position'); Passes = 3; Linger = 500 },
        @{ Name = (T 'Courte : 3 passes, 100 ms par position (réglage de gw)'); Passes = 3; Linger = 100 },
        @{ Name = (T 'Longue : 8 passes, 500 ms par position'); Passes = 8; Linger = 500 }
    )
}

function Test-GwIdle {
    # Aucune operation en cours (12.8, D20 : Get-AppBusy, test unique : gw, chaine d etapes, controle, calibration,
    # restauration, detection, prechauffage d ecriture, mesure continue de l onglet Qualite). Garde pour frmClean et le banc
    return -not (Get-AppBusy)
}

function Get-CleanStepTexts([bool]$wet, [string]$drive, [string]$dur) {
    # Textes des cinq vignettes de la procedure ; sechage : notice du kit d abord, CleanDryMinutes a defaut. Espaces
    # insecables dans la duree, apres « et devant : ; % » : aucun signe isole en debut de ligne dans les vignettes etroites
    $nb = [string][char]0x00A0
    $t = @(
        (T 'Une disquette à tissu, vendue pour cet usage. Jamais une disquette de données.'),
        $(if ($wet) { (T "Quelques gouttes d'alcool isopropylique (90 % ou plus) sur le tissu, par la fenêtre du volet : humide, pas détrempé.") } else { (T 'Disquette sèche : rien à faire à cette étape.') }),
        ((T 'Insérez-la dans le lecteur {0}, volet en avant, comme une disquette ordinaire.') -f "$drive"),
        ((T 'Cochez la case, puis « Lancer le nettoyage ». La tête va et vient pendant {0} environ ; le bruit est normal.') -f "$($dur.Replace(' ', $nb))"),
        $(if ($wet) { ((T "Retirez-la, puis laissez sécher les têtes le temps indiqué par la notice du kit (à défaut, {0} min par prudence) avant d'insérer une disquette de données.") -f "$($script:CleanDryMinutes)") } else { (T 'Retirez-la : le lecteur est prêt.') })
    )
    return @($t | ForEach-Object { (($_ -replace ' ([:;%»])', "$nb`$1") -replace '« ', "«$nb") })
}

function Start-HeadClean([string]$drive, [int]$cyls, [int]$passes, [int]$linger, [bool]$wet) {
    # gw clean sur le lecteur $drive ; $script:CleanRun suit la commande (Update-Progress : passes vues, autres lignes).
    # --cyls seulement s il differe du defaut de gw (80). $false si gw n a pas demarre
    $est = Get-CleanSeconds $passes $linger $cyls
    $kind = if ($wet) { (T 'humide') } else { (T 'sèche') }
    Append-Log ((T 'Nettoyage des têtes du lecteur {0} : {1} passe(s) en zigzag sur {2} cylindres, {3} ms à chaque position, durée estimée {4} ; disquette de nettoyage {5}.') -f "$drive", "$passes", "$cyls", "$linger", (Format-CalDuration ([math]::Round($est))), "$kind")
    $a = @('clean', "--drive=$drive")
    if ($txtDev.Text.Trim()) { $a += "--device=$($txtDev.Text.Trim())" }
    if ($cyls -ne 80) { $a += "--cyls=$cyls" }
    $a += @("--passes=$passes", "--linger=$linger")
    Start-Gw $a
    if (-not ($script:GwProc -and $script:GwProc.StartInfo.Arguments -match '(^|\s)clean\s')) { return $false }
    $script:CleanRun = @{ Drive = $drive; Passes = $passes; Done = 0; Lines = (New-Object System.Collections.Generic.List[string])
                          Stopped = $false; Wet = $wet; Est = $est; Start = Get-Date }
    return $true
}

function Stop-HeadClean {
    # Arreter (fenetre de nettoyage) ou fermeture de la fenetre pendant le nettoyage. gw tue ne coupe pas le moteur :
    # le firmware le coupe a la fin du delai watchdog (10 s par defaut, onglet Delais). gw deja termine : bilan normal
    $r = $script:CleanRun
    if (-not $r -or $r.Stopped) { return }
    if (-not ($script:GwProc -and -not $script:GwProc.HasExited)) { return }
    $r.Stopped = $true
    try { $script:GwProc.Kill($true) } catch { try { $script:GwProc.Kill() } catch { } }
    Append-Log (T '*** Interrompu par l''utilisateur ***')
}

function Complete-HeadClean {
    # Fin de gw clean : bilan dans le journal et texte de fin de la fenetre. Renvoie @{ Ok ; Text ; Color }
    $r = $script:CleanRun; $script:CleanRun = $null
    if (-not $r) { return @{ Ok = $false; Text = ''; Color = $null } }
    $code = [int]$script:GwLastCode
    $lines = @($r.Lines | Where-Object { $_.Trim() })
    $failed = (-not $r.Stopped) -and ($code -ne 0 -or @($lines | Where-Object { $_ -match 'Command Failed|FATAL' }).Count -gt 0 -or $r.Done -lt $r.Passes)
    $ok = (-not $r.Stopped) -and (-not $failed)
    $dryAt = (Get-Date).AddMinutes($script:CleanDryMinutes).ToString('HH:mm')
    $parts = @()
    if ($ok) { $parts += (T 'Nettoyage terminé : retirez la disquette de nettoyage.') }
    elseif ($r.Stopped) { $parts += (T "Nettoyage interrompu. Le moteur du lecteur peut tourner encore jusqu'à la fin du délai de sécurité du Greaseweazle (watchdog, 10 s par défaut) : attendez qu'il s'arrête, puis retirez la disquette de nettoyage.") }
    else {
        # Raison : deux dernieres lignes utiles, sans le debut de la ligne de passe ni les prefixes d erreur de gw ; code 0
        # sans erreur signalee mais passes manquantes : nombre de passes vues, puis la derniere ligne de gw
        $useful = @($lines | ForEach-Object { ((($_ -replace '^Pass \d+:[\d ]*', '') -replace 'FATAL ERROR:?|Command Failed:?', '') -replace '\*', '').Trim() } | Where-Object { $_ })
        if ($code -eq 0 -and @($lines | Where-Object { $_ -match 'Command Failed|FATAL' }).Count -eq 0) {
            $why = ((T "gw s'est arrêté après {0} passe(s) sur {1}") -f "$($r.Done)", "$($r.Passes)")
            if ($useful.Count -gt 0) { $why += ' / ' + $useful[-1] }
        } else {
            $why = (@($useful) | Select-Object -Last 2) -join ' / '
            if (-not $why) { $why = ((T "gw a retourné le code {0}, voir le journal") -f "$code") }
        }
        Append-Log ((T 'ÉCHEC du nettoyage des têtes : {0}') -f "$why")
        $parts += (T "Le nettoyage n'a pas abouti : retirez la disquette de nettoyage, vérifiez le lecteur choisi et son câblage (carte « Tester le Greaseweazle » de l'Accueil), puis relancez.")
    }
    if ($r.Wet -and ($ok -or $r.Done -gt 0 -or $r.Stopped)) { $parts += ((T "Disquette humide : laissez sécher les têtes le temps indiqué par la notice du kit avant d'insérer une disquette de données ; à défaut, attendez par prudence jusqu'à {0}.") -f "$dryAt") }
    elseif ($ok) { $parts += (T 'Le lecteur est prêt.') }
    if ($ok) { $parts += (T "Comptez cette utilisation sur l'étiquette de la disquette de nettoyage : elle s'use.") }
    $text = $parts -join ' '
    Append-Log $text
    $color = if ($ok) { $script:Theme.Ok } elseif ($r.Stopped) { $script:Theme.Warn } else { $script:Theme.Danger }
    return @{ Ok = $ok; Text = $text; Color = $color; Outcome = $(if ($ok) { 'ok' } elseif ($r.Stopped) { 'stop' } else { 'fail' }) }
}

function Get-CleanDlgOptions {
    # Options choisies dans la fenetre de nettoyage, avec la duree estimee
    $s = $script:CleanDlg
    $pr = $s.Presets[[math]::Max(0, $s.Dur.SelectedIndex)]
    $cyls = if ($s.Cyls.SelectedIndex -eq 1) { 40 } else { 80 }
    return @{ Drive = [string]$s.Drive.SelectedItem; Cyls = $cyls; Passes = [int]$pr.Passes; Linger = [int]$pr.Linger; Wet = [bool]$s.Wet.Checked
              Est = (Get-CleanSeconds ([int]$pr.Passes) ([int]$pr.Linger) $cyls) }
}

function Set-CleanTiles([int]$cur, [string]$endTag = '') {
    # Vignettes : avant $cur faites (vert), $cur en cours (bleu), apres a faire ; etape 2 grisee avec une disquette seche.
    # endTag 'stop' ou 'fail' (fin du nettoyage interrompu ou en echec) : la vignette juste avant $cur (4, « Lancer le
    # nettoyage ») est marquee interrompue (orange) ou en echec (rouge), et non faite
    $s = $script:CleanDlg
    for ($i = 0; $i -lt $s.Tiles.Count; $i++) {
        $t = $s.Tiles[$i]
        $tag = if ($cur -lt 0 -or $i -gt $cur) { 'todo' } elseif ($i -lt $cur) { 'done' } else { 'cur' }
        if ($i -eq $cur - 1 -and @('stop', 'fail') -contains $endTag) { $tag = $endTag }
        if ($i -eq 1 -and -not $s.Wet.Checked) { $tag = 'skip' }
        $t.Panel.Tag = $tag
        $t.Panel.BackColor = switch ($tag) {
            'done' { [System.Drawing.Color]::FromArgb(236, 247, 240) }
            'cur'  { [System.Drawing.Color]::FromArgb(234, 241, 251) }
            'skip' { [System.Drawing.Color]::FromArgb(244, 245, 247) }
            'stop' { [System.Drawing.Color]::FromArgb(253, 243, 228) }
            'fail' { [System.Drawing.Color]::FromArgb(253, 236, 234) }
            default { [System.Drawing.Color]::White }
        }
        $t.Title.ForeColor = if ($tag -eq 'skip') { $script:Theme.Muted } else { $script:Theme.Accent2 }
        $t.Panel.Invalidate()
    }
}

function Update-CleanDlg {
    # Textes des etapes et duree estimee d apres les options ; vignettes selon la case de confirmation
    $s = $script:CleanDlg
    if (-not $s -or $s.Phase -eq 'run') { return }
    $o = Get-CleanDlgOptions
    $dur = Format-CalDuration ([math]::Round($o.Est))
    $txt = Get-CleanStepTexts $o.Wet $o.Drive $dur
    for ($i = 0; $i -lt 5; $i++) { $s.Tiles[$i].Desc.Text = $txt[$i] }
    $s.Est.Text = ((T 'durée estimée : {0}') -f "$dur")
    # Case de confirmation : elle nomme le lecteur choisi (decochee a chaque changement de lecteur ou de type)
    $s.Chk.Text = ((T "J'ai inséré une disquette de nettoyage dans le lecteur {0}") -f "$($o.Drive)")
    if ($s.Phase -eq 'ready') { Set-CleanTiles $(if ($s.Chk.Checked) { 3 } else { -1 }) }
}

function Set-CleanGo([bool]$on) {
    # Bouton « Lancer le nettoyage » : bleu seulement quand il est actif (case cochee), sinon style normal grise ; style
    # (et icone) refait seulement quand il change
    $s = $script:CleanDlg; $b = $s.Go
    $b.Enabled = $on
    $st = if ($on) { 'primary' } else { 'normal' }
    if ($s.GoStyle -ne $st) { $s.GoStyle = $st; Set-Btn $b 'Repair' $st }
}

function Set-CleanDlgPhase([string]$phase, [string]$text = '', $color = $null, [string]$outcome = '') {
    # Etat de la fenetre : ready (options modifiables), run (gw clean en cours), end (termine, arrete ou en echec ;
    # outcome 'ok', 'stop' ou 'fail' de Complete-HeadClean : vignette 4 faite, interrompue ou en echec)
    $s = $script:CleanDlg
    if (-not $s) { return }
    if ($phase -eq 'end' -and $s.Chk.Checked) { $s.Busy = $true; $s.Chk.Checked = $false; $s.Busy = $false }   # nouvelle confirmation pour relancer
    $s.Phase = $phase
    $run = ($phase -eq 'run')
    foreach ($c in @($s.Drive, $s.Cyls, $s.Wet, $s.Dry, $s.Dur, $s.Chk)) { $c.Enabled = -not $run }
    $s.Go.Visible = -not $run; $s.Stop.Visible = $run; $s.Bar.Visible = $run
    Set-CleanGo ((-not $run) -and $s.Chk.Checked)
    if ($run) { $s.Bar.Value = 0 }
    $s.State.ForeColor = if ($color) { $color } else { $script:Theme.Accent2 }
    $s.State.Text = $text
    if ($phase -eq 'end') { Set-CleanTiles 4 $outcome } else { Set-CleanTiles $(if ($run -or $s.Chk.Checked) { 3 } else { -1 }) }
}

function Set-CleanDlgFit($dlg, [System.Drawing.Rectangle]$wa) {
    # Ecran trop petit pour la fenetre de nettoyage (zone de travail $wa) : hauteur ramenee a celle de l ecran avec un
    # defilement vertical, largeur augmentee de la barre de defilement (pas de defilement horizontal). $true si ajustee
    if ($dlg.Height -le $wa.Height) { return $false }
    $dlg.AutoScroll = $true
    $dlg.Size = New-Object System.Drawing.Size(($dlg.Width + [System.Windows.Forms.SystemInformation]::VerticalScrollBarWidth), $wa.Height)
    return $true
}

function New-CleanDialog([int]$Passes = 0, [int]$Linger = 0) {
    # Construit la fenetre de nettoyage (sans l afficher) et $script:CleanDlg. $Passes > 0 : reglage de l onglet Outils.
    # Hauteurs des textes (vignettes, avertissement, etat) mesurees dans la langue de l interface
    $W = 880; $tw = 168; $gap = [int](($W - 5 * $tw) / 4)    # largeur : hauteur de la fenetre sous 720 px (ecran 1366 x 768)
    $tf = [System.Windows.Forms.TextFormatFlags]::WordBreak -bor [System.Windows.Forms.TextFormatFlags]::NoPrefix
    $gdi = New-Object System.Collections.Generic.List[object]       # images et polices liberees avec la fenetre
    $dlg = New-Object System.Windows.Forms.Form
    $dlg.Name = 'frmClean'; $dlg.Text = (T 'Nettoyage des têtes')
    $dlg.FormBorderStyle = 'FixedDialog'; $dlg.MaximizeBox = $false; $dlg.MinimizeBox = $false; $dlg.ShowInTaskbar = $false
    $dlg.StartPosition = 'CenterParent'; $dlg.Icon = $form.Icon; $dlg.Font = $form.Font; $dlg.BackColor = [System.Drawing.Color]::White
    $ctip = New-Object System.Windows.Forms.ToolTip
    $ctip.AutoPopDelay = 30000; $ctip.InitialDelay = 400; $ctip.ReshowDelay = 100

    # Avertissement, en tete et en rouge
    $pnlW = New-Object System.Windows.Forms.Panel
    $pnlW.Name = 'pnlCleanWarn'; $pnlW.Location = New-Object System.Drawing.Point(16, 16); $pnlW.BackColor = [System.Drawing.Color]::FromArgb(253, 236, 234)
    $picW = New-Object System.Windows.Forms.PictureBox
    $picW.Image = New-CleanPicto 'forbid'; $gdi.Add($picW.Image); $picW.SizeMode = 'Zoom'; $picW.Location = New-Object System.Drawing.Point(8, 10); $picW.Size = New-Object System.Drawing.Size(100, 70)
    $fWT = New-Object System.Drawing.Font('Segoe UI Semibold', 11); $gdi.Add($fWT)
    $lblWT = New-Object System.Windows.Forms.Label
    $lblWT.Name = 'lblCleanWarnTitle'; $lblWT.Text = (T 'NE LANCEZ JAMAIS LE NETTOYAGE AVEC UNE VRAIE DISQUETTE'); $lblWT.UseMnemonic = $false; $lblWT.AutoEllipsis = $true
    $lblWT.Font = $fWT; $lblWT.ForeColor = [System.Drawing.Color]::FromArgb(160, 32, 26)
    $lblWT.Location = New-Object System.Drawing.Point(118, 10); $lblWT.Size = New-Object System.Drawing.Size(($W - 128), 24)
    $wTxt = (T "Pendant le nettoyage, la tête balaie toute la surface en va-et-vient, moteur en marche, pour frotter sa saleté contre le tissu. Une vraie disquette (données, original ou disquette vierge à garder) risquerait d'être rayée par cette saleté et de perdre ses données, sans retour possible. N'insérez qu'une disquette de nettoyage, et suivez d'abord la notice de son kit.")
    $lblW = New-Object System.Windows.Forms.Label
    $lblW.Name = 'lblCleanWarn'; $lblW.Text = $wTxt; $lblW.UseMnemonic = $false; $lblW.ForeColor = [System.Drawing.Color]::FromArgb(110, 24, 20)
    $hw = [System.Windows.Forms.TextRenderer]::MeasureText($wTxt, $dlg.Font, (New-Object System.Drawing.Size(($W - 128), 10000)), $tf).Height
    $lblW.Location = New-Object System.Drawing.Point(118, 38); $lblW.Size = New-Object System.Drawing.Size(($W - 128), ($hw + 4))
    $pnlW.Size = New-Object System.Drawing.Size($W, [math]::Max(90, $lblW.Bottom + 10))
    $pnlW.Controls.AddRange(@($picW, $lblWT, $lblW))
    $pnlW.Add_Paint({ $pen = New-Object System.Drawing.Pen($script:Theme.Danger, [single]2); $_.Graphics.DrawRectangle($pen, 1, 1, $this.Width - 2, $this.Height - 2); $pen.Dispose() })

    # Procedure en cinq vignettes ; hauteur des textes : la plus grande de toutes les variantes (humide / seche)
    $titles = @((T '1. Disquette de nettoyage'), (T '2. Humidifier le tissu'), (T '3. Insérer'), (T '4. Lancer le nettoyage'), (T '5. Retirer, laisser sécher'))
    $kinds = @('disk', 'drops', 'insert', 'run', 'dry')
    $fT = New-Object System.Drawing.Font('Segoe UI Semibold', 9.75); $gdi.Add($fT)
    $tsz = New-Object System.Drawing.Size(($tw - 8), 10000)
    $hT = 0; foreach ($s in $titles) { $hT = [math]::Max($hT, [System.Windows.Forms.TextRenderer]::MeasureText($s, $fT, $tsz, $tf).Height) }
    $hD = 0
    foreach ($v in @((Get-CleanStepTexts $true 'A' '88 min 88 s'), (Get-CleanStepTexts $false 'A' '88 min 88 s'))) {   # duree la plus large
        foreach ($s in $v) { $hD = [math]::Max($hD, [System.Windows.Forms.TextRenderer]::MeasureText($s, $dlg.Font, $tsz, $tf).Height) }
    }
    $yT = $pnlW.Bottom + 14
    $tiles = @()
    for ($i = 0; $i -lt 5; $i++) {
        $p = New-Object System.Windows.Forms.Panel
        $p.Name = "pnlCleanStep$($i + 1)"; $p.Tag = 'todo'; $p.BackColor = [System.Drawing.Color]::White
        $p.Location = New-Object System.Drawing.Point((16 + $i * ($tw + $gap)), $yT); $p.Size = New-Object System.Drawing.Size($tw, (92 + $hT + 4 + $hD + 8))
        $pic = New-Object System.Windows.Forms.PictureBox
        $pic.Image = New-CleanPicto $kinds[$i]; $gdi.Add($pic.Image); $pic.Location = New-Object System.Drawing.Point([int](($tw - 120) / 2), 4); $pic.Size = New-Object System.Drawing.Size(120, 84)
        $lt = New-Object System.Windows.Forms.Label
        $lt.Name = "lblCleanTitle$($i + 1)"; $lt.Text = $titles[$i]; $lt.UseMnemonic = $false; $lt.Font = $fT; $lt.ForeColor = $script:Theme.Accent2
        $lt.Location = New-Object System.Drawing.Point(4, 92); $lt.Size = New-Object System.Drawing.Size(($tw - 8), $hT)
        $ld = New-Object System.Windows.Forms.Label
        $ld.Name = "lblCleanStep$($i + 1)"; $ld.UseMnemonic = $false; $ld.ForeColor = [System.Drawing.Color]::FromArgb(70, 76, 88)
        $ld.Location = New-Object System.Drawing.Point(4, (96 + $hT)); $ld.Size = New-Object System.Drawing.Size(($tw - 8), $hD)
        $p.Controls.AddRange(@($pic, $lt, $ld))
        $p.Add_Paint({
            $c = switch ([string]$this.Tag) { 'cur' { $script:Theme.Accent } 'done' { $script:Theme.Ok } 'stop' { $script:Theme.Warn } 'fail' { $script:Theme.Danger } default { [System.Drawing.Color]::FromArgb(205, 212, 224) } }
            $pen = New-Object System.Drawing.Pen($c, [single]$(if (@('cur', 'stop', 'fail') -contains [string]$this.Tag) { 2 } else { 1 }))
            $_.Graphics.DrawRectangle($pen, 0, 0, $this.Width - 1, $this.Height - 1); $pen.Dispose()
        })
        $tiles += @(@{ Panel = $p; Title = $lt; Desc = $ld })
    }

    # Options
    $y = $yT + $tiles[0].Panel.Height + 14
    $l1 = New-Label (T 'Lecteur :') (New-Object System.Drawing.Point(16, ($y + 3)))
    $cmbD = New-Object System.Windows.Forms.ComboBox
    $cmbD.Name = 'cmbCleanDrive'; $cmbD.DropDownStyle = 'DropDownList'; $cmbD.Width = 56; $cmbD.Location = New-Object System.Drawing.Point(110, $y)
    # 12.8 (point 7) : reglage « drive » lu a l ouverture, ecrit au lancement du nettoyage (lecteur du bandeau)
    [void]$cmbD.Items.AddRange([string[]]$script:SettingDefs['drive'].Codes)
    $cmbD.SelectedItem = [string](Get-Setting 'drive'); if ($cmbD.SelectedIndex -lt 0) { $cmbD.SelectedIndex = 0 }
    $l2 = New-Label (T 'Type :') (New-Object System.Drawing.Point(190, ($y + 3)))
    $cmbC = New-Object System.Windows.Forms.ComboBox
    $cmbC.Name = 'cmbCleanCyls'; $cmbC.DropDownStyle = 'DropDownList'; $cmbC.Location = New-Object System.Drawing.Point(250, $y); $cmbC.Width = ($W + 16 - 250)
    [void]$cmbC.Items.AddRange(@((T 'Lecteur 80 pistes : 3,5 pouces, ou 5,25 pouces haute densité'), (T 'Lecteur 40 pistes : 5,25 pouces double densité (360 Ko)')))
    $cmbC.SelectedIndex = $(if ([int]$script:CleanPrefs.Cyls -eq 40) { 1 } else { 0 })
    $ctip.SetToolTip($cmbC, (T "Course de la tête pendant le nettoyage (--cyls). Un lecteur 40 pistes ne doit pas être envoyé au-delà de sa butée."))
    $y += 34
    $l3 = New-Label (T 'Disquette :') (New-Object System.Drawing.Point(16, ($y + 3)))
    $rbWet = New-Object System.Windows.Forms.RadioButton
    $rbWet.Name = 'rbCleanWet'; $rbWet.Text = (T 'humide (alcool isopropylique)'); $rbWet.AutoSize = $true; $rbWet.Checked = [bool]$script:CleanPrefs.Wet
    $rbWet.Location = New-Object System.Drawing.Point(110, ($y + 1))
    $rbDry = New-Object System.Windows.Forms.RadioButton
    $rbDry.Name = 'rbCleanDry'; $rbDry.Text = (T 'sèche'); $rbDry.AutoSize = $true; $rbDry.Checked = -not $rbWet.Checked
    $rbDry.Location = New-Object System.Drawing.Point((110 + [System.Windows.Forms.TextRenderer]::MeasureText($rbWet.Text, $dlg.Font).Width + 40), ($y + 1))
    $y += 34
    $l4 = New-Label (T 'Durée :') (New-Object System.Drawing.Point(16, ($y + 3)))
    $presets = @(Get-CleanPresets)
    if ($Passes -gt 0) { $presets += @(@{ Name = ((T 'Réglage de l''onglet Outils : {0} passe(s), {1} ms par position') -f "$Passes", "$Linger"); Passes = $Passes; Linger = $Linger }) }
    $cmbT = New-Object System.Windows.Forms.ComboBox
    $cmbT.Name = 'cmbCleanDur'; $cmbT.DropDownStyle = 'DropDownList'; $cmbT.Location = New-Object System.Drawing.Point(110, $y); $cmbT.Width = 420
    foreach ($pr in $presets) { [void]$cmbT.Items.Add($pr.Name) }
    $cmbT.SelectedIndex = $(if ($Passes -gt 0) { $presets.Count - 1 } else { [math]::Max(0, [math]::Min(2, [int]$script:CleanPrefs.Preset)) })
    $lEst = New-Label '' (New-Object System.Drawing.Point(542, ($y + 3))); $lEst.Name = 'lblCleanEst'; $lEst.ForeColor = $script:Theme.Muted
    $y += 36
    $chk = New-Object System.Windows.Forms.CheckBox
    $chk.Name = 'chkCleanOk'; $chk.Text = ((T "J'ai inséré une disquette de nettoyage dans le lecteur {0}") -f "$($cmbD.Text)"); $chk.AutoSize = $true; $chk.Font = $bold; $chk.UseMnemonic = $false
    $chk.Location = New-Object System.Drawing.Point(16, $y)
    $y += 28
    $bar = New-Object System.Windows.Forms.ProgressBar
    $bar.Name = 'pbClean'; $bar.Location = New-Object System.Drawing.Point(16, $y); $bar.Size = New-Object System.Drawing.Size($W, 16); $bar.Maximum = 1000; $bar.Visible = $false
    # Etat : hauteur du plus long texte de fin (echec ou arret suivi du sechage, succes humide), 3 lignes au moins
    $fS = New-Object System.Drawing.Font('Segoe UI Semibold', 9.75); $gdi.Add($fS)
    $wetEnd = ((T "Disquette humide : laissez sécher les têtes le temps indiqué par la notice du kit avant d'insérer une disquette de données ; à défaut, attendez par prudence jusqu'à {0}.") -f '00:00')
    $hS = 0
    foreach ($e in @(((T 'Nettoyage terminé : retirez la disquette de nettoyage.') + ' ' + $wetEnd + ' ' + (T "Comptez cette utilisation sur l'étiquette de la disquette de nettoyage : elle s'use.")),
                     ((T "Nettoyage interrompu. Le moteur du lecteur peut tourner encore jusqu'à la fin du délai de sécurité du Greaseweazle (watchdog, 10 s par défaut) : attendez qu'il s'arrête, puis retirez la disquette de nettoyage.") + ' ' + $wetEnd),
                     ((T "Le nettoyage n'a pas abouti : retirez la disquette de nettoyage, vérifiez le lecteur choisi et son câblage (carte « Tester le Greaseweazle » de l'Accueil), puis relancez.") + ' ' + $wetEnd))) {
        $hS = [math]::Max($hS, [System.Windows.Forms.TextRenderer]::MeasureText($e, $fS, (New-Object System.Drawing.Size($W, 10000)), $tf).Height)
    }
    $hS = [math]::Max($hS, 3 * $fS.Height)
    $lblS = New-Object System.Windows.Forms.Label
    $lblS.Name = 'lblCleanState'; $lblS.UseMnemonic = $false; $lblS.Font = $fS
    $lblS.Location = New-Object System.Drawing.Point(16, ($y + 20)); $lblS.Size = New-Object System.Drawing.Size($W, ($hS + 4))
    $y = $lblS.Bottom + 8
    $btnGo = New-Object System.Windows.Forms.Button
    $btnGo.Name = 'btnCleanStart'; $btnGo.Text = (T 'Lancer le nettoyage'); $btnGo.Size = New-Object System.Drawing.Size(230, 34); $btnGo.Enabled = $false
    $btnStp = New-Object System.Windows.Forms.Button
    $btnStp.Name = 'btnCleanStop'; $btnStp.Text = (T 'Arrêter'); $btnStp.Size = New-Object System.Drawing.Size(130, 34); $btnStp.Visible = $false
    $btnCl = New-Object System.Windows.Forms.Button
    $btnCl.Name = 'btnCleanClose'; $btnCl.Text = (T 'Fermer'); $btnCl.Size = New-Object System.Drawing.Size(110, 34)
    $btnCl.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
    Set-Btn $btnGo 'Repair' 'primary'; Set-Btn $btnStp 'Stop' 'danger'; Set-Btn $btnCl '' 'normal'
    $btnCl.Location = New-Object System.Drawing.Point((16 + $W - $btnCl.Width), $y)
    $btnGo.Location = New-Object System.Drawing.Point(($btnCl.Left - 8 - $btnGo.Width), $y)
    $btnStp.Location = New-Object System.Drawing.Point(($btnCl.Left - 8 - $btnStp.Width), $y)
    $dlg.ClientSize = New-Object System.Drawing.Size(($W + 32), ($y + $btnCl.Height + 16))
    $dlg.CancelButton = $btnCl                        # pas d AcceptButton : Entree ne lance pas le nettoyage
    $dlg.Controls.AddRange(@($pnlW) + @($tiles | ForEach-Object { $_.Panel }) + @($l1, $cmbD, $l2, $cmbC, $l3, $rbWet, $rbDry, $l4, $cmbT, $lEst, $chk, $bar, $lblS, $btnGo, $btnStp, $btnCl))
    [void](Set-CleanDlgFit $dlg ([System.Windows.Forms.Screen]::FromControl($form).WorkingArea))

    $script:CleanDlg = @{ Dlg = $dlg; Tiles = $tiles; Drive = $cmbD; Cyls = $cmbC; Wet = $rbWet; Dry = $rbDry; Dur = $cmbT; Est = $lEst
                          Chk = $chk; Bar = $bar; State = $lblS; Go = $btnGo; Stop = $btnStp; Close = $btnCl; Presets = $presets
                          Phase = 'ready'; Busy = $false; Tmr = $null; Tip = $ctip; Gdi = $gdi; GoStyle = 'primary' }
    $upd = { Update-CleanDlg }
    # Lecteur ou type change apres la confirmation : case decochee (son gestionnaire desactive « Lancer le nettoyage »),
    # la disquette de nettoyage doit etre confirmee pour le nouveau lecteur. Avant Update-CleanDlg (vignettes a jour)
    $reset = { $s = $script:CleanDlg; if ($s -and $s.Phase -ne 'run' -and $s.Chk.Checked) { $s.Chk.Checked = $false } }
    $cmbD.Add_SelectedIndexChanged($reset); $cmbC.Add_SelectedIndexChanged($reset)
    $cmbD.Add_SelectedIndexChanged($upd); $cmbC.Add_SelectedIndexChanged($upd); $cmbT.Add_SelectedIndexChanged($upd); $rbWet.Add_CheckedChanged($upd)
    $chk.Add_CheckedChanged({
        $s = $script:CleanDlg
        if (-not $s -or $s.Busy -or $s.Phase -eq 'run') { return }
        $s.Phase = 'ready'; $s.State.Text = ''
        Set-CleanGo $this.Checked
        Set-CleanTiles $(if ($this.Checked) { 3 } else { -1 })
    })
    $btnGo.Add_Click({
        $s = $script:CleanDlg
        if (-not $s -or -not $s.Chk.Checked -or $script:CleanRun) { return }
        if (-not (Test-GwIdle)) { $s.State.ForeColor = $script:Theme.Warn; $s.State.Text = (T "Une commande gw est en cours : attendez qu'elle se termine, puis relancez."); return }
        $o = Get-CleanDlgOptions
        # choix memorises (enregistres par Start-Gw) ; le reglage de l onglet Outils n est pas un prereglage. 12.8 (point 7) :
        # lecteur choisi ecrit dans le reglage « drive » (bandeau), comme tout choix d une fenetre au lancement de l action :
        # avant Start-HeadClean (l enregistrement fait par Start-Gw le contient), lecteur d avant remis si gw n a pas demarre
        $script:CleanPrefs = @{ Wet = $o.Wet; Cyls = $o.Cyls; Preset = $(if ($s.Dur.SelectedIndex -le 2) { $s.Dur.SelectedIndex } else { $script:CleanPrefs.Preset }) }
        $prevDrive = Get-Setting 'drive'
        Set-Setting 'drive' $o.Drive
        if (-not (Start-HeadClean $o.Drive $o.Cyls $o.Passes $o.Linger $o.Wet)) { Set-Setting 'drive' $prevDrive; $s.State.ForeColor = $script:Theme.Danger; $s.State.Text = (T "gw n'a pas pu être lancé : voir le journal."); return }
        Set-CleanDlgPhase 'run' ((T 'Nettoyage en cours sur le lecteur {0}...') -f "$($o.Drive)")
    })
    $btnStp.Add_Click({ Stop-HeadClean })
    # Fermer, Echap ou la croix pendant le nettoyage : arret, et la fenetre reste ouverte sur le texte de fin (retirer,
    # laisser secher). Fermer et Echap passent par DialogResult (CloseReason None), la croix par UserClosing
    $dlg.Add_FormClosing({
        if (-not $script:CleanRun) { return }
        Stop-HeadClean
        if ($_.CloseReason -eq [System.Windows.Forms.CloseReason]::UserClosing -or $_.CloseReason -eq [System.Windows.Forms.CloseReason]::None) { $_.Cancel = $true }
    })
    # Suivi : barre (passes terminees ou temps ecoule sur la duree estimee, 99 % au plus tant que gw tourne), puis bilan
    # quand le minuteur principal a traite la fin de gw ($script:GwProc remis a $null)
    $tmr = New-Object System.Windows.Forms.Timer
    $tmr.Interval = 250
    $tmr.Add_Tick({
        $s = $script:CleanDlg; $r = $script:CleanRun
        if (-not $s -or -not $r -or $s.Phase -ne 'run') { return }
        if ($script:GwProc) {
            $el = ((Get-Date) - $r.Start).TotalSeconds
            $v = [math]::Max(1000.0 * $r.Done / [math]::Max(1, $r.Passes), 1000.0 * $el / [math]::Max(1.0, $r.Est))
            $s.Bar.Value = [int][math]::Min(990.0, $v)
            $s.State.Text = ((T 'Nettoyage en cours sur le lecteur {0} : passe {1} sur {2}, reste environ {3}.') -f "$($r.Drive)", "$([math]::Min($r.Passes, $r.Done + 1))", "$($r.Passes)", (Format-CalDuration ([math]::Round([math]::Max(0.0, $r.Est - $el)))))
            return
        }
        $res = Complete-HeadClean
        Set-CleanDlgPhase 'end' $res.Text $res.Color $res.Outcome
    })
    $script:CleanDlg.Tmr = $tmr
    Set-CleanGo $false
    Update-CleanDlg
    return $dlg
}

function Show-CleanDialog([int]$Passes = 0, [int]$Linger = 0) {
    # Nettoyage des tetes : carte de l Accueil ; bouton NETTOYER de l onglet Outils ($Passes / $Linger de cet onglet)
    if (-not (Test-GwIdle)) {
        [void](Show-AppMessage (T "Opération en cours : lancez le nettoyage une fois l'opération terminée ou arrêtée.") (T 'Nettoyage des têtes') 'OK' 'Information'); return
    }
    $dlg = New-CleanDialog $Passes $Linger
    $s = $script:CleanDlg
    $s.Tmr.Start()
    try { [void]$dlg.ShowDialog($form) }
    finally {
        $s.Tmr.Stop(); $s.Tmr.Dispose()
        if ($script:CleanRun) { Stop-HeadClean; [void](Complete-HeadClean) }   # fenetre fermee par le systeme pendant le nettoyage
        $script:CleanDlg = $null
        $s.Tip.Dispose(); $dlg.Dispose()
        foreach ($o in $s.Gdi) { try { $o.Dispose() } catch { } }
    }
}
# ============================== FONCTIONS : PROFIL PRECOMP =====================

# ============================== PROFIL PRECOMP : DETECTION =====================
function Get-BE32([byte[]]$b, [int]$o) {
    return ([int64]$b[$o] * 16777216) + ([int64]$b[$o+1] * 65536) + ([int64]$b[$o+2] * 256) + [int64]$b[$o+3]
}

# IPF : mediane des bits par piste (enregistrements IMGE) -> cellule nominale a 300 tr/min
function Get-IpfCellInfo([string]$path) {
    $d = [System.IO.File]::ReadAllBytes($path)
    if ([System.Text.Encoding]::ASCII.GetString($d, 0, 4) -ne 'CAPS') { throw (T 'Signature IPF absente') }
    $bits = New-Object System.Collections.Generic.List[int64]; $dos = 0; $n = 0
    $pos = 0
    while ($pos + 12 -le $d.Length) {
        $id = [System.Text.Encoding]::ASCII.GetString($d, $pos, 4)
        $ln = Get-BE32 $d ($pos + 4)
        if ($ln -lt 12) { break }
        if ($id -eq 'IMGE' -and $pos + 12 + 44 -le $d.Length) {
            $trkbits = Get-BE32 $d ($pos + 12 + 36)
            $blkcnt  = Get-BE32 $d ($pos + 12 + 40)
            if ($blkcnt -gt 0 -and $trkbits -gt 0) { $bits.Add($trkbits); $n++; if ($blkcnt -eq 11) { $dos++ } }
        } elseif ($id -eq 'DATA' -and $pos + 16 -le $d.Length) {
            $ln += Get-BE32 $d ($pos + 12)
        }
        $pos += $ln
    }
    if ($bits.Count -eq 0) { throw (T 'Aucune piste formatée dans l''IPF') }
    $sorted = $bits | Sort-Object
    $med = [int64]$sorted[[int]($sorted.Count / 2)]
    # 12.11 : MaxBits, piste la plus longue (cellule la plus courte) : plafond par disquette (Get-PatternBits, 240)
    return @{ CellNs = [double](200000000.0 / $med); Bits = $med; MaxBits = [int64]($bits | Measure-Object -Maximum).Maximum; Tracks = $n; DosTracks = $dos; Source = (T 'IPF (bits par piste)') }
}

# SCP : cellule mesuree sur les premieres pistes presentes (revolution 0)
function Get-ScpCellInfo([string]$path) {
    $d = [System.IO.File]::ReadAllBytes($path)
    if ([System.Text.Encoding]::ASCII.GetString($d, 0, 3) -ne 'SCP') { throw (T 'Signature SCP absente') }
    $res = ($d[11] + 1) * 25; $cells = @(); $t = 0
    while ($t -lt 168 -and $cells.Count -lt 4) {
        $o = [BitConverter]::ToUInt32($d, 16 + 4 * $t); $t++
        if ($o -eq 0) { continue }
        $ln = [BitConverter]::ToUInt32($d, $o + 8); $doff = [BitConverter]::ToUInt32($d, $o + 12)
        $flux = [ScpStats]::Decode($d, [int]($o + $doff), [int]$ln, $res)
        $st = [ScpStats]::Analyze($flux, 0)
        if (-not [double]::IsNaN($st.Cell)) { $cells += $st.Cell }
    }
    if ($cells.Count -eq 0) { throw (T 'Aucune piste analysable dans le SCP') }
    $avg = ($cells | Measure-Object -Average).Average
    return @{ CellNs = $avg; Bits = [int64](200000000.0 / $avg); Tracks = $cells.Count; DosTracks = -1; Source = (T 'SCP (flux mesuré)') }
}

# HFE : debit binaire declare dans l en-tete (kbit/s) -> cellule = 500 000 / debit
function Get-HfeCellInfo([string]$path) {
    # Densite d un HFE telle que gw l ecrit (hfe.py) : par face, 8 x (longueur // 2) bits, la longueur (octets, deux
    # faces) etant lue dans la table des pistes (bloc ToUInt16(18), une entree de 4 octets par cylindre : bloc des
    # donnees, longueur) ; gw cale chaque piste sur un tour du lecteur, d ou une cellule de 200 ms / bits a 300 tr/min
    # (mediane des pistes). Table retenue si elle suit l en-tete, est complete et designe pour au moins la moitie des
    # cylindres des donnees presentes dans le fichier. HFE v3 (opcodes dans le flux de bits) ou table inexploitable :
    # 400 x debit de l en-tete.
    $fs = [System.IO.File]::OpenRead($path)
    try {
        $h = New-Object byte[] 32; [void]$fs.Read($h, 0, 32)
        $sig = [System.Text.Encoding]::ASCII.GetString($h, 0, 8)
        if ($sig -notmatch '^HXCPICFE|^HXCHFEV3') { throw (T 'Signature HFE absente') }
        $rate = [BitConverter]::ToUInt16($h, 12)          # en-tete HFE : bitRate (kbit/s) a l offset 12
        if ($rate -le 0) { throw (T 'Débit HFE nul') }
        if ($rate -lt 100 -or $rate -gt 1000) { throw ((T "Débit HFE invalide ({0} kbit/s)") -f "$rate") }
        $bits = [int64](400 * [int]$rate); $src = ((T "HFE (débit {0} kbit/s)") -f "$rate")
        # 12.11 : MaxBits, piste la plus longue lue dans la table des pistes ; 0 : densite tiree du seul debit de l en-tete
        # (HFE v3, table inexploitable), longueur des pistes inconnue : plafond par disquette de 470 ns (Get-PatternBits, 240)
        $max = [int64]0
        # 12.10 (lot 1, B1) : octet d encodage (offset 11, table EncodingType de hfe.py) : FM 0x02, 0x03, 0x04, 0x0E, 0x14 ;
        # GCR 0x06 a 0x09 (Apple II), 0x10 (Macintosh), 0x12 (C64), 0x13 (Victor 9000) ; codage propre 0x0F (M2FM du DEC
        # RX02) ; MFM 0x00, 0x01, 0x05, 0x0C, 0x0D ; 0xFF (valeur que gw ecrit par defaut) et autres : inconnu (''), MFM
        # suppose comme en 12.8 (decision B-D2). FM et Apple II sont enregistres a double debit (convention HFE, emit_track
        # de hfe.py) : DoubleRate, cellule physique double de celle des bits du fichier. MFM et inconnu : cellule et bits
        # inchanges (densite du motif de Get-PatternBits)
        $eb = [int]$h[11]
        $enc = if (@(2, 3, 4, 14, 20) -contains $eb) { 'fm' } elseif (@(6, 7, 8, 9, 16, 18, 19) -contains $eb) { 'gcr' } elseif ($eb -eq 15) { 'other' } elseif (@(0, 1, 5, 12, 13) -contains $eb) { 'mfm' } else { '' }
        $dbl = ($enc -eq 'fm' -or ($eb -ge 6 -and $eb -le 9))
        $nCyl = [int]$h[9]; $tlBase = [int][BitConverter]::ToUInt16($h, 18)
        if ($sig -eq 'HXCPICFE' -and $nCyl -gt 0 -and $tlBase -ge 1) {
            $tl = New-Object byte[] (4 * $nCyl)
            [void]$fs.Seek([int64]$tlBase * 512, [System.IO.SeekOrigin]::Begin)
            $got = $fs.Read($tl, 0, $tl.Length)
            if ($got -eq $tl.Length) {
                $flen = $fs.Length
                $lens = @(@(for ($i = 0; $i + 4 -le $got; $i += 4) {
                    $off = [int64][BitConverter]::ToUInt16($tl, $i); $l = [int][BitConverter]::ToUInt16($tl, $i + 2)
                    if ($l -ge 2 -and $off -gt $tlBase -and $off * 512 + $l -le $flen + 512) { 8 * [int64][math]::Floor($l / 2) }
                }) | Sort-Object)
                if ($lens.Count -gt 0 -and $lens.Count -ge [math]::Ceiling($nCyl / 2)) {
                    $med = [int64]$lens[[int][math]::Floor($lens.Count / 2)]
                    if ($med -ge 20000 -and $med -le 600000) { $bits = $med; $max = [int64]$lens[$lens.Count - 1]; $src = ((T "HFE ({0} bits par piste, débit {1} kbit/s)") -f "$med", "$rate") }
                }
            }
        }
    } finally { $fs.Dispose() }
    $cell = [double](200000000.0 / $bits)
    if ($dbl) { $cell *= 2; $bits = [int64][math]::Floor($bits / 2); $max = [int64][math]::Floor($max / 2) }   # 12.10 (lot 1, B1) : double debit (FM, Apple II)
    return @{ CellNs = $cell; Bits = $bits; MaxBits = $max; Tracks = -1; DosTracks = -1; Source = $src; EncByte = $eb; Enc = $enc; DoubleRate = $dbl }
}

function Get-CurveDate($cv) {
    # Date d une courbe (dd/MM/yyyy HH:mm, separateur de la culture courante a l enregistrement) ; MinValue si illisible
    $d = [datetime]::MinValue
    if (-not $cv -or -not $cv.Date) { return $d }
    foreach ($ci in @([System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.CultureInfo]::CurrentCulture)) {
        if ([datetime]::TryParseExact([string]$cv.Date, 'dd/MM/yyyy HH:mm', $ci, [System.Globalization.DateTimeStyles]::None, [ref]$d)) { return $d }
    }
    return [datetime]::MinValue
}

function Test-HeadCurvesCurrent([string]$fam) {
    # Courbes par tete applicables : les deux presentes et au moins aussi recentes que la courbe commune de la famille
    # (une calibration commune posterieure, apres un changement de lecteur par exemple, les rend perimees).
    $h0 = $script:PrecompCurves["${fam}_h0"]; $h1 = $script:PrecompCurves["${fam}_h1"]
    if (-not $h0 -or -not $h1 -or -not $h0.Spec -or -not $h1.Spec) { return $false }
    $one = $script:PrecompCurves[$fam]
    if (-not $one) { return $true }
    return ((Get-CurveDate $h0) -ge (Get-CurveDate $one))
}

function Get-FamilyCurves([string]$family, [bool]$preferHeads) {
    # Courbes appliquees a la famille : par tete en ecriture lente si elles sont a jour, sinon la courbe commune
    if ($preferHeads -and (Test-HeadCurvesCurrent $family)) { return ,@($script:PrecompCurves["${family}_h0"], $script:PrecompCurves["${family}_h1"]) }
    $one = $script:PrecompCurves[$family]
    if ($one) { return ,@($one) }
    return ,@()
}

function Get-DriveFamilyCurves([string]$drive, [string]$family, [bool]$preferHeads) {
    # 12.10 : courbes d un lecteur du magasin (cle « lecteur », ou « source>cible » pour les courbes croisees) appliquees a
    # la famille, memes regles que Get-FamilyCurves : par tete si elles sont presentes et au moins aussi recentes que la
    # courbe commune, sinon la courbe commune ; tableau protege par la virgule (pas de @() autour de l appel)
    $h0 = Get-DriveCurve $drive "${family}_h0"; $h1 = Get-DriveCurve $drive "${family}_h1"; $one = Get-DriveCurve $drive $family
    if ($preferHeads -and $h0 -and $h1 -and $h0.Spec -and $h1.Spec -and (-not $one -or (Get-CurveDate $h0) -ge (Get-CurveDate $one))) { return ,@($h0, $h1) }
    if ($one) { return ,@($one) }
    return ,@()
}

function Get-HeadSpec([string]$fam, [int]$h) {
    # Profil calibre d une tete (ecriture lente), $null si la famille n a pas de calibration par tete
    $cv = $script:PrecompCurves["${fam}_h$h"]
    if ($cv -and $cv.Spec) { return [string]$cv.Spec }
    return $null
}

function Set-PrecompFields([string]$spec, [string]$fam) {
    # Champs --precomp : commun (tete 0 en ecriture lente) et tete 1. Ecriture lente : profils calibres par tete
    # de la famille s ils sont a jour, sinon le profil commun pour les deux tetes. Renvoie le complement du libelle.
    # 12.10 : lecteur cible choisi dans l onglet Ecriture (Get-TargetDrive, 140) : courbes croisees « source>cible » de la
    # famille (Get-TargetCurves : par tete a jour en ecriture lente, sinon commune, pour les deux tetes) a la place des
    # courbes du lecteur ; sans courbe croisee : champs remplis comme sans lecteur cible, complement qui annonce le refus
    # de l ecriture (Test-TargetWriteAllowed, 140). Relecture de l etape 3 : famille haute densite (hd : pas de calibration
    # croisee) : champs remplis comme sans lecteur cible, complement $tn qui annonce le refus sans proposer la calibration
    # croisee ; ecriture rapide avec des courbes croisees par tete seulement : complement qui le dit (Get-TargetWriteInfo).
    # Finalisation 12.10 : courbes croisees dans les champs : aucun complement, la courbe croisee est nommee entre les
    # parentheses du libelle a la place du profil propre du lecteur source (Get-WProfileSpec, Get-TargetProfileText)
    $chkWPrecomp.Checked = $true
    $tgt = Get-TargetDrive
    # 12.10 (relecture de la RC) : refus du lecteur cible annonce en tete du libelle par Sync-WTargetHead, d apres le refus
    # de l ecriture elle-meme (Get-TargetWriteInfo, 140), et non plus par un complement rendu ici, qui pouvait annoncer un
    # refus qui n avait pas lieu (flux ecrit tel quel en profil force, case --precomp decochee) ; haute densite : champs et
    # complements comme sans lecteur cible
    if ($tgt -and @('std', 'long') -contains $fam) {
        $src = [string]$cmbDrive.Text
        $cvs = @(Get-TargetCurves $fam ([bool]$chkWSlow.Checked) $src $tgt)
        if ($cvs.Count -ge 2) { $txtWPrecomp.Text = [string]$cvs[0].Spec; $txtWPrecomp1.Text = [string]$cvs[1].Spec; return '' }
        if ($cvs.Count -eq 1) { $txtWPrecomp.Text = [string]$cvs[0].Spec; $txtWPrecomp1.Text = [string]$cvs[0].Spec; return '' }
        # sans courbe croisee : champs du profil de la famille, ecriture refusee (refus en tete du libelle : Sync-WTargetHead)
        $txtWPrecomp.Text = $spec; $txtWPrecomp1.Text = $spec
        return ''
    }
    if ($chkWSlow.Checked -and (Test-HeadCurvesCurrent $fam)) {
        $txtWPrecomp.Text = Get-HeadSpec $fam 0; $txtWPrecomp1.Text = Get-HeadSpec $fam 1
        return (T ' ; écriture lente : profils calibrés tête 0 et tête 1 appliqués')
    }
    $txtWPrecomp.Text = $spec; $txtWPrecomp1.Text = $spec
    if (-not $chkWSlow.Checked) { return '' }
    if ((Get-HeadSpec $fam 0) -and (Get-HeadSpec $fam 1)) { return (T ' ; écriture lente : courbes par tête antérieures au profil commun, profil commun pour les deux têtes') }
    return (T ' ; écriture lente : même profil pour les deux têtes (aucune calibration par tête pour cette famille)')
}

function Get-TargetProfileText([string]$fam) {
    # Finalisation 12.10 : courbes croisees que Set-PrecompFields met dans les champs pour le lecteur cible de l onglet
    # Ecriture (Get-TargetCurves, memes regles : par tete a jour en ecriture lente, sinon commune), nommees dans le libelle
    # du profil a la place du profil propre du lecteur source : sens, test, date (courbes par tete : une date si les deux
    # tetes ont la meme), calcul. Chaine vide sans lecteur cible, hors double densite ou sans courbe croisee. Texte court : le
    # libelle (lblWProfileInfo, 520 : 502 x 40 px, deux lignes, AutoSize faux) n a pas la place de la famille ni du calcul
    # conserve de Get-TargetCurvesText, qui restent au journal de l ecriture
    $tgt = Get-TargetDrive
    if (-not $tgt -or @('std', 'long') -notcontains $fam) { return '' }
    $src = [string]$cmbDrive.Text
    $cvs = @(Get-TargetCurves $fam ([bool]$chkWSlow.Checked) $src $tgt)
    if ($cvs.Count -eq 0) { return '' }
    $c0 = $cvs[0]
    $test = if ([string]$c0.Test -eq 'fine') { (T 'test fin') } else { (T 'test standard') }
    $calc = Get-CurveCalcText $c0 -Plain
    if ($cvs.Count -ge 2) {
        if ([string]$cvs[1].Date -eq [string]$c0.Date) { return ((T 'courbes croisées {0} → {1} par tête, {2}, {3}, calcul {4}') -f "$src", "$tgt", "$test", "$($c0.Date)", "$calc") }
        return ((T 'courbes croisées {0} → {1} par tête, {2}, tête 0 du {3}, tête 1 du {4}, calcul {5}') -f "$src", "$tgt", "$test", "$($c0.Date)", "$($cvs[1].Date)", "$calc")
    }
    if ($chkWSlow.Checked) { return ((T 'courbe croisée {0} → {1} pour les deux têtes, {2}, {3}, calcul {4}') -f "$src", "$tgt", "$test", "$($c0.Date)", "$calc") }
    return ((T 'courbe croisée {0} → {1}, {2}, {3}, calcul {4}') -f "$src", "$tgt", "$test", "$($c0.Date)", "$calc")
}

function Get-WProfileSpec([string]$spec, [string]$fam, [bool]$asIs = $false) {
    # Finalisation 12.10 : texte entre les parentheses du libelle du profil, apres Set-PrecompFields : courbes croisees du
    # lecteur cible quand les champs les portent (Get-TargetProfileText), sinon le profil $spec. $asIs : profil seul (image
    # a laquelle --precomp n est pas transmis : flux ecrit tel quel, FM, GCR ; le complement du libelle le dit)
    if (-not $asIs) { $t = Get-TargetProfileText $fam; if ($t) { return $t } }
    return $spec
}

function Get-HdProfile([string]$hf) {
    # 12.7 : profil commun d une famille haute densite : Spec de sa courbe commune, sinon profil d origine haute densite
    # (pas de champ de configuration : il suit la courbe, retablie avec elle par Restore-CalibState)
    $cv = $script:PrecompCurves[$hf]
    if ($cv -and $cv.Spec) { return [string]$cv.Spec }
    return $script:PrecompHdDefault
}

function Get-HdCommonCurve([string]$hf) {
    # 12.7 : courbe commune d une famille haute densite dont Get-HdProfile tire le profil commun ; $null sans elle
    $cv = $script:PrecompCurves[$hf]
    if ($cv -and $cv.Spec) { return $cv }
    return $null
}

function Get-HdAutoFields([string]$hf, [bool]$slow) {
    # 12.7 : champs --precomp du mode Auto pour une image haute densite calibrable (meme regle que Set-PrecompFields)
    if ($slow -and (Test-HeadCurvesCurrent $hf)) { return @{ P0 = [string](Get-HeadSpec $hf 0); P1 = [string](Get-HeadSpec $hf 1) } }
    $s = Get-HdProfile $hf
    return @{ P0 = $s; P1 = $s }
}

function Set-WProfileText([string]$base, [string]$note) {
    # 12.8.1 (spec-1281 § D.4) : libelle du profil Auto double densite et son complement « facteur » (T-C12,
    # Get-WriteFactorNote), gardes separement : Update-WriteFactorNote refait le complement seul
    $script:WFactorNote = @{ Base = $base; Note = $note }
    $lblWProfileInfo.Text = $base + $note
}

function Get-WTargetHead([string]$path) {
    # 12.10 (relecture de la RC) : refus du lecteur cible que le libelle du profil annonce en tete : celui de l ecriture
    # elle-meme (Get-TargetWriteInfo, 140 : BlockKind), en texte court (deux lignes du libelle, 520 : 502 x 40 px, avec le
    # profil d origine de la famille), majuscule initiale, suivi du separateur du complement (« ; » precede d une espace en
    # francais) ; '' sans refus (meme lecteur, profil Manuel, --precomp decoche, image sans precompensation, courbe croisee)
    $ti = Get-TargetWriteInfo $path ([string]$cmbWFmt.Text) ([bool]$chkWSlow.Checked)
    $n = switch ([string]$ti.BlockKind) {
        'hd'   { (T " ; lecteur cible {0} : écriture refusée en haute densité (la calibration croisée n'existe qu'en double densité)") -f "$($ti.Tgt)" }
        'head' { (T ' ; courbes croisées {1} → {0} par tête : écriture rapide refusée (cochez « Écriture lente »)') -f "$($ti.Tgt)", "$($ti.Src)" }
        'none' { (T ' ; aucune courbe croisée {1} → {0} : écriture refusée (« Calibrer pour un lecteur cible… »)') -f "$($ti.Tgt)", "$($ti.Src)" }
        default { '' }
    }
    $n = [string]$n
    $core = $n.TrimStart(' ', ';')
    if (-not $core) { return '' }
    return $core.Substring(0, 1).ToUpper() + $core.Substring(1) + $n.Substring(0, $n.Length - $core.Length)
}

function Sync-WTargetHead([switch]$IfOwn) {
    # 12.10 (relecture de la RC) : refus en tete du libelle du profil accorde au refus reel de l ecriture pour l image du
    # libelle ($script:WProfilePath ; Get-WTargetHead) : en sortie d Update-PrecompForImage, et au changement de la case
    # « Precompensation (--precomp) » (520, -IfOwn : seulement si le libelle est celui du profil, $script:WProfileLabel ou
    # base et complement « facteur », et non un avis de la Bibliotheque, un bilan de calibration ou un texte restaure).
    # Ancienne tete retiree si le libelle la porte encore ($script:WTargetHead), nouvelle tete mise ; base du complement
    # « facteur » (Set-WProfileText, Update-WriteFactorNote) accordee de meme. Apres un profil calibre ou le detail d une
    # image analysee, un refus place en fin passait au-dela des deux lignes du libelle, cache par les points de suspension
    $txt = [string]$lblWProfileInfo.Text
    $n = $script:WFactorNote
    $fn = ($n -and $txt -eq ([string]$n.Base + [string]$n.Note))
    if ($IfOwn -and -not $fn -and $txt -ne [string]$script:WProfileLabel) { return }
    $want = ''
    try { $want = Get-WTargetHead ([string]$script:WProfilePath) } catch { $want = '' }
    $have = [string]$script:WTargetHead
    if ($have -and -not $txt.StartsWith($have, [System.StringComparison]::Ordinal)) { $have = '' }
    $script:WTargetHead = $want
    if ($want -ne $have) {
        if ($fn -and ([string]$n.Base).StartsWith($have, [System.StringComparison]::Ordinal)) { $n.Base = $want + ([string]$n.Base).Substring($have.Length) }
        $txt = $want + $txt.Substring($have.Length)
        $lblWProfileInfo.Text = $txt
    }
    $script:WProfileLabel = $txt
}

function Update-PrecompForImage([string]$path) {
    # 12.10 (relecture de la RC) : bouton « Courbe » (Update-CurveButton) recalcule en sortie (finally), apres le profil et la
    # case --precomp recochee par Set-PrecompFields (gestionnaire de la case inactif d ici la) ; avant : en entree, d apres la
    # case encore decochee (courbe propre du lecteur montree a la place de la courbe croisee ecrite)
    $script:WProfileHd = $false
    $script:WFactorNote = $null
    $script:WProfilePath = $path
    # 12.10 (relecture de la RC) : refus du lecteur cible en tete du libelle a chaque sortie (finally : Sync-WTargetHead ;
    # corps garde a son retrait) ; gestionnaire de la case --precomp (recochee par Set-PrecompFields) inactif d ici la.
    # $script:WTargetHead n est pas remis a vide : un corps interrompu avant le nouveau libelle laisse l ancien avec sa tete,
    # que Sync-WTargetHead remplace au lieu d en ajouter une seconde ; un libelle refait ne la porte pas (tete ignoree)
    $script:WProfileBuilding = $true
    try {
    $mode = $cmbWProfile.Text
    if ($mode -eq (T 'Manuel')) { $lblWProfileInfo.Text = (T 'Profil manuel : --precomp non modifié.'); return }
    # 12.10 (lot 1, B1) : image FM, GCR ou a codage propre (Get-ImageEncoding) : --precomp n est pas transmis
    # (Start-ImageWrite), en profil Auto comme en profil force (decision B-D1) ; champs remplis comme avant (ils servent si
    # le format change), complement $nmNote a la place de celui de Set-PrecompFields
    $ie = if ($path -and (Test-Path -LiteralPath $path)) { Get-ImageEncoding $path $cmbWFmt.Text } else { $null }
    $nmNote = if ($ie -and $ie.NonMfm) { (T " ; image en codage {0} ({1}) : --precomp n'est pas transmis") -f "$($ie.Name)", "$($ie.Src)" } else { '' }
    # 12.10 (relecture de la RC) : $fxNote (image flux ecrite telle quelle, voir plus bas) calcule ici pour le profil force
    # aussi : son libelle ne nomme plus un profil ou une courbe croisee que gw ne recoit pas
    $fxNote = if ($path -and (Test-Path -LiteralPath $path) -and (Test-RawFluxWrite $path $cmbWFmt.Text)) { (T " ; image flux écrite telle quelle (sans --format) : gw n'applique pas la précompensation, --precomp n'est pas transmis") } else { '' }
    # Finalisation 12.10 : parentheses du libelle : courbes croisees du lecteur cible quand les champs les portent (Get-WProfileSpec)
    if ($mode -eq (T 'Standard 2 us'))      { $x = Set-PrecompFields $script:PrecompStd 'std';   $lblWProfileInfo.Text = ((T "Profil forcé : standard 2 us ({0})") -f (Get-WProfileSpec $script:PrecompStd 'std' ([bool]($nmNote -or $fxNote)))) + $(if ($nmNote) { $nmNote } elseif ($fxNote) { $fxNote } else { $x }); return }
    if ($mode -eq (T 'Long track 1,89 us')) { $x = Set-PrecompFields $script:PrecompLong 'long'; $lblWProfileInfo.Text = ((T "Profil forcé : long track ({0})") -f (Get-WProfileSpec $script:PrecompLong 'long' ([bool]($nmNote -or $fxNote)))) + $(if ($nmNote) { $nmNote } elseif ($fxNote) { $fxNote } else { $x }); return }
    # Auto
    if (-not $path -or -not (Test-Path -LiteralPath $path)) { $lblWProfileInfo.Text = ''; return }
    if ($nmNote) {
        $x = Set-PrecompFields $script:PrecompStd 'std'
        $lblWProfileInfo.Text = (T "Auto : image en codage {0} ({1}) -> sans précompensation (--precomp n'est pas transmis)") -f "$($ie.Name)", "$($ie.Src)"
        Append-Log ((T "Profil precomp : {0}") -f "$($lblWProfileInfo.Text)")
        return
    }
    $ext = [System.IO.Path]::GetExtension($path).ToLower()
    # 12.8 (S3-FLUX, decision 2 du 21/10/2026) : image flux sans --format (Test-RawFluxWrite) : gw n y applique pas la
    # precompensation ; champs remplis comme avant (ils servent si un format est choisi), mais le libelle ne les dit plus
    # « appliques » : complement $fxNote a la place de celui de Set-PrecompFields
    # ($fxNote : calcule en tete de la fonction, profil force compris)
    # Image haute densite (12.7) : calibrable (famille hd) -> profil calibre de sa famille, par tete en ecriture lente si
    # les courbes par tete sont a jour, sinon profil d origine haute densite ; non calibrable (ED, codages propres,
    # 360 tr/min) -> profil d origine de sa famille double densite, comme en 12.6. Pour les deux tetes, ecriture lente
    # comprise ; jamais une courbe double densite (jusqu a CalHardNs ns, trop forte pour une cellule de 1 us).
    $hd = Get-HighDensityReason $path $cmbWFmt.Text
    if ($hd) {
        $hf = Get-HdCalibFamily $path $cmbWFmt.Text
        if ($hf) {
            $spec = Get-HdProfile $hf
            $x = Set-PrecompFields $spec $hf
            # Profil commun dit calibre seulement s il vient de la courbe commune ; sans elle, en ecriture lente avec des
            # courbes par tete a jour, le profil d origine n est pas ecrit : le complement de Set-PrecompFields nomme les
            # profils des tetes
            $fn = Get-CalibFamilyName $hf
            $hcv = Get-HdCommonCurve $hf
            if ($hcv) { $fl = (T "Auto : image haute densité ({0}) -> profil calibré {1} ({2})") -f "$hd", "$fn", "$spec" }
            elseif ($chkWSlow.Checked -and (Test-HeadCurvesCurrent $hf)) { $fl = (T "Auto : image haute densité ({0}) -> {1}") -f "$hd", "$fn" }
            else { $fl = (T "Auto : image haute densité ({0}) -> profil d'origine {1} ({2}), non calibré : calibrez le lecteur en haute densité (carte « Calibrer le lecteur » de l'Accueil)") -f "$hd", "$fn", "$spec" }
            $lblWProfileInfo.Text = $fl + $(if ($fxNote) { $fxNote } else { $x })
        } else {
            $hf = Get-ImageFamily $path $cmbWFmt.Text
            $def = if ($hf -eq 'long') { $script:PrecompLongDefault } else { $script:PrecompStdDefault }
            $chkWPrecomp.Checked = $true; $txtWPrecomp.Text = $def; $txtWPrecomp1.Text = $def
            # 12.10 (relecture de la RC) : lecteur cible : refus de l ecriture (Get-TargetWriteInfo, 140, refuse toute image
            # haute densite en Auto) annonce en tete du libelle comme pour la haute densite calibrable (Sync-WTargetHead)
            $lblWProfileInfo.Text = ((T "Auto : image haute densité ({0}) -> profil d'origine {1} ({2}) : calibration non disponible pour cette image") -f "$hd", (Get-CalibFamilyName $hf), "$def") + $fxNote
        }
        Append-Log ((T "Profil precomp : {0}") -f "$($lblWProfileInfo.Text)")
        $script:WProfileHd = $true
        return
    }
    $info = $null
    try {
        switch ($ext) {
            '.ipf' { $info = Get-IpfCellInfo $path }
            '.scp' { if ($script:ScpStatsOk) { $info = Get-ScpCellInfo $path } }
            '.hfe' { $info = Get-HfeCellInfo $path }
        }
    } catch { Append-Log ((T "Détection du profil impossible ({0}) : {1}") -f "$ext", "$($_.Exception.Message)"); $info = $null }
    if ($null -eq $info) {
        # formats secteur (ADF, IMG, ST...) : cellule standard par definition ; 12.8 (S3-FLUX) : flux non analyse (KryoFlux,
        # A2R, CTR, SCP sans module d analyse) : dit « image flux », et non « image secteur »
        $x = Set-PrecompFields $script:PrecompStd 'std'
        if (Test-FluxImage $path) { $lblWProfileInfo.Text = ((T "Auto : image flux ({0}) -> standard 2 us ({1})") -f "$ext", (Get-WProfileSpec $script:PrecompStd 'std' ([bool]$fxNote))) + $(if ($fxNote) { $fxNote } else { $x }); return }
        # 12.8.1 : facteur de precompensation different de 1 (mesure du lecteur) : complement
        Set-WProfileText (((T "Auto : image secteur ({0}) -> standard 2 us ({1})") -f "$ext", (Get-WProfileSpec $script:PrecompStd 'std')) + $x) (Get-WriteFactorNote $path)
        return
    }
    $long = $info.CellNs -lt $script:PrecompThresholdNs
    $x = if ($long) { Set-PrecompFields $script:PrecompLong 'long' } else { Set-PrecompFields $script:PrecompStd 'std' }
    if ($fxNote) { $x = $fxNote }
    # Finalisation 12.10 : courbes croisees du lecteur cible dans les champs : elles sont nommees dans les parentheses, le
    # detail de la detection est reduit a l extension (largeur du libelle : deux lignes, anglais compris ; la famille reste)
    $sp = if ($fxNote) { '' } else { Get-TargetProfileText $(if ($long) { 'long' } else { 'std' }) }
    if ($sp) { $head = (T "Auto : image {0} -> ") -f "$ext" }
    else {
        $detail = ((T "cellule {0} ns, {1} bits/piste") -f "$([math]::Round($info.CellNs,0))", "$($info.Bits)")
        if ($info.DosTracks -ge 0 -and $info.Tracks -gt 0) { $detail += ((T ", {0}/{1} pistes DOS") -f "$($info.DosTracks)", "$($info.Tracks)") }
        $head = (T "Auto : {0} : {1} -> ") -f "$($info.Source)", "$detail"
        $sp = if ($long) { $script:PrecompLong } else { $script:PrecompStd }
    }
    Set-WProfileText ($head + $(if ($long) { ((T "LONG TRACK ({0})") -f "$sp") } else { ((T "standard 2 us ({0})") -f "$sp") }) + $x) (Get-WriteFactorNote $path)
    Append-Log ((T "Profil precomp : {0}") -f "$($lblWProfileInfo.Text)")
    # 12.10 (relecture de la RC) : case de la mesure accordee a l effet du lecteur cible sur cette image (Update-WLevelUi, 140)
    } finally { $script:WProfileBuilding = $false; Sync-WTargetHead; Update-WLevelUi; Update-CurveButton $path }
}
# ============================== FONCTIONS : CALIBRATION : COURBES ==============

function Set-CalibScale([string]$fam) {
    # 12.7 : bareme de la famille calibree ('hd' : CalScaleHd ; autre ou vide : double densite, objets d origine) et borne
    # CalHardNs (haute densite : moitie de la borne configuree CalHardNsUser). Appele avant la creation de $script:Cal
    # (Start-PrecompCalib, Start-LevelCalib, Restart-PrecompCalib), au chargement de la configuration, par Set-Defaults et,
    # au repos, par le minuteur principal (filet de securite). Affectations explicites : pas de Set-Variable (portee des
    # tests).
    $hd = ($fam -eq 'hd')
    $t = if ($hd) { $script:CalScaleHd } else { $script:CalScaleDd }
    $script:CalCoarse = $t.CalCoarse; $script:CalMaxNs = $t.CalMaxNs; $script:CalBracketMargin = $t.CalBracketMargin
    $script:CalBracketStep = $t.CalBracketStep; $script:CalTrendSig = $t.CalTrendSig; $script:CalTrendRefSig = $t.CalTrendRefSig
    $script:CalContraMaxNs = $t.CalContraMaxNs; $script:CalDevNs = $t.CalDevNs; $script:CalDenseStep = $t.CalDenseStep
    $script:CalExtrapSigMin = $t.CalExtrapSigMin; $script:CalSigMax = $t.CalSigMax; $script:CalInterpDefault = $t.CalInterpDefault
    $script:CalSurfShiftMax = $t.CalSurfShiftMax; $script:CalCmpPointNs = $t.CalCmpPointNs; $script:CalCmpZoneNs = $t.CalCmpZoneNs
    $script:CalCmpSpotNs = $t.CalCmpSpotNs; $script:CalCmpPrefNs = $t.CalCmpPrefNs; $script:CalCmpLocalNs = $t.CalCmpLocalNs
    $script:LevelTauOk = $t.LevelTauOk; $script:LevelTauMax = $t.LevelTauMax
    # 12.9 : corrections 1, 2 et 4 du calcul, et decalage commun de l ecriture de verification retire des residus (CalVOffOn,
    # Get-VerifyOffset) : vrais en double densite, faux en haute densite (calcul HD inchange)
    $script:CalCondPass = [bool]$t.CalCondPass; $script:CalLatin = [bool]$t.CalLatin; $script:CalDentOn = [bool]$t.CalDentOn
    $script:CalVOffOn = [bool]$t.CalVOffOn
    $script:CalHardNs = if ($hd) { [int][math]::Round([double]$script:CalHardNsUser * $script:CalHdK) } else { $script:CalHardNsUser }
    $script:CalScaleFam = if ($hd) { 'hd' } else { 'dd' }
}

function Test-CurveHd($cv) {
    # 12.7 : courbe de la famille haute densite : motif de plus de 150 000 cellules (200 000, 202 688 ; DD 105 820 au plus)
    return [bool]($cv -and $null -ne $cv.Bits -and [int]$cv.Bits -ge 150000)
}

function Get-CurveDevNs($cv) {
    # 12.7 : ecart notable d une courbe enregistree (point marque, legende) : bareme de sa famille, hors de toute calibration
    if (Test-CurveHd $cv) { return [double]$script:CalScaleHd.CalDevNs }
    return [double]$script:CalScaleDd.CalDevNs
}

function Get-ImageCylinders([string]$path) {
    # Nombre de cylindres de l image, $null si non determinable
    $ext = [System.IO.Path]::GetExtension($path).ToLower()
    try {
        switch ($ext) {
            '.adf' {
                $len = (Get-Item -LiteralPath $path).Length
                if ($len % 11264 -eq 0) {                                   # 11264 = 2 faces x 11 secteurs x 512 (DD)
                    $c = $len / 11264
                    if ($c -gt 84 -and $len % 22528 -eq 0) { $c = $len / 22528 }   # HD : 22 secteurs
                    return [int]$c
                }
            }
            '.ipf' {
                $d = [System.IO.File]::ReadAllBytes($path); $max = -1; $pos = 0
                while ($pos + 12 -le $d.Length) {
                    $id = [System.Text.Encoding]::ASCII.GetString($d, $pos, 4); $ln = Get-BE32 $d ($pos + 4)
                    if ($ln -lt 12) { break }
                    if ($id -eq 'IMGE' -and $pos + 16 -le $d.Length) {
                        $t = Get-BE32 $d ($pos + 12)                       # champ track = cylindre
                        if ($t -gt $max -and $t -lt 200) { $max = $t }
                    } elseif ($id -eq 'DATA' -and $pos + 16 -le $d.Length) { $ln += Get-BE32 $d ($pos + 12) }
                    $pos += $ln
                }
                if ($max -ge 0) { return [int]($max + 1) }
            }
            '.hfe' {
                $fs = [System.IO.File]::OpenRead($path)
                try { $h = New-Object byte[] 16; [void]$fs.Read($h, 0, 16) } finally { $fs.Dispose() }
                if ($h[9] -gt 0) { return [int]$h[9] }                     # number_of_track
            }
        }
    } catch { }
    return $null
}

function Get-ImageFamily([string]$path, [string]$fmt = '') {
    # 12.7 : 'hd' pour une haute densite calibrable (Get-HdCalibFamily, format explicite ou implicite compris), sinon 'long'
    # si la cellule de l image est sous le seuil (long tracks), 'std' sinon : meme logique que le mode Auto
    $hf = Get-HdCalibFamily $path $fmt; if ($hf) { return $hf }
    $ext = [System.IO.Path]::GetExtension($path).ToLower()
    $info = $null
    try {
        switch ($ext) {
            '.ipf' { $info = Get-IpfCellInfo $path }
            '.hfe' { $info = Get-HfeCellInfo $path }
        }
    } catch { $info = $null }
    if ($null -ne $info -and $info.CellNs -lt $script:PrecompThresholdNs) { return 'long' }
    return 'std'
}

function Format-CylList([int[]]$cyls) {
    $s = @($cyls | Sort-Object -Unique)
    $contig = $true
    for ($i = 1; $i -lt $s.Count; $i++) { if ($s[$i] -ne $s[$i - 1] + 1) { $contig = $false; break } }
    if ($contig -and $s.Count -gt 1) { return "$($s[0])-$($s[-1])" }
    return ($s -join ',')
}

function Get-CalibTrackScore($st) {
    # Score de qualite (jitter 2T + asymetrie 3T/4T + hors classe) sur les tours lisibles ; 9999 = illisible
    foreach ($x in $st) { if ([double]::IsNaN($x.Jitter) -or [double]::IsNaN($x.R3) -or [double]::IsNaN($x.R4)) { return 9999 } }
    $j   = ($st | Measure-Object -Property Jitter -Average).Average
    $r3  = ($st | Measure-Object -Property R3 -Average).Average
    $r4  = ($st | Measure-Object -Property R4 -Average).Average
    $ooc = ($st | Measure-Object -Property OutOfClass -Average).Average
    return ($j + 2000 * ([math]::Abs($r3 - 1.5) + [math]::Abs($r4 - 2.0)) + 5 * $ooc)
}


function Get-CalibFamilyName([string]$family) {
    if ($family -eq 'long') { return (T 'Long track 1,89 us') }
    if ($family -eq 'hd') { return (T 'Haute densité 1 us') }
    return (T 'Standard 2 us')
}

function Get-SpecValue([string]$spec, [int]$cyl) {
    # Valeur de precomp appliquee par gw au cylindre : derniere entree c=ns dont c <= cylindre (entrees croissantes)
    $v = 0
    foreach ($m in [regex]::Matches($spec, '(\d+)\s*=\s*(\d+)')) { if ([int]$m.Groups[1].Value -le $cyl) { $v = [int]$m.Groups[2].Value } }
    return $v
}

function Get-CurveX([string]$model, [double]$c, [int]$maxCyl) {
    # Abscisse du modele pour le cylindre c. u = 0 (exterieur) a 1 (dernier cylindre de l image).
    # Rayon relatif : 3,5" de 39,5 a 24,7 mm (rapport 0,625) ; 5,25" 40 ou 80 pistes : rapport voisin (0,63).
    $u = $c / [math]::Max(1, $maxCyl)
    $r = 1.0 - 0.375 * $u
    switch ($model) {
        'inv'  { return 1.0 / $r }
        'inv2' { return 1.0 / ($r * $r) }
        default { return $u }
    }
}

function Get-Median($a) {
    $s = @($a | ForEach-Object { [double]$_ } | Sort-Object)
    if ($s.Count -eq 0) { return 0.0 }
    if ($s.Count % 2 -eq 1) { return [double]$s[[int][math]::Floor($s.Count / 2)] }
    return ([double]$s[$s.Count / 2 - 1] + [double]$s[$s.Count / 2]) / 2
}

function Get-IsolatedPoints($cs, $est, $sig) {
    # Donnees denses (test fin, mesures complementaires) : point isole = au moins un voisin mesure a 3 cylindres au plus
    # de chaque cote (2 au plus par cote), ecart a la mediane des voisins > max(15 ns ; 4 incertitudes) alors que les
    # deux cotes s accordent (ecart < meme seuil) : defaut ponctuel de la disquette de calibration, non suivi par la
    # courbe. 10 % des points et 4 au plus, jamais le premier ni le dernier. 15 ns : CalDevNs (bareme de la famille, 12.7).
    $cand = @()
    for ($i = 1; $i -lt $cs.Count - 1; $i++) {
        $c = [int]$cs[$i]
        $left = @(); for ($j = $i - 1; $j -ge 0 -and $left.Count -lt 2; $j--) { if ($c - [int]$cs[$j] -le 3) { $left += [double]$est[[int]$cs[$j]] } else { break } }
        $right = @(); for ($j = $i + 1; $j -lt $cs.Count -and $right.Count -lt 2; $j++) { if ([int]$cs[$j] - $c -le 3) { $right += [double]$est[[int]$cs[$j]] } else { break } }
        if ($left.Count -eq 0 -or $right.Count -eq 0) { continue }
        $s = if ($sig -and $sig.ContainsKey($c)) { [double]$sig[$c] } else { 5.0 }
        $thr = [math]::Max($script:CalDevNs, 4.0 * $s)
        $r = [double]$est[$c] - (Get-Median (@($left) + @($right)))
        if ([math]::Abs($r) -gt $thr -and [math]::Abs((Get-Median $left) - (Get-Median $right)) -lt $thr) { $cand += ,@($c, $r) }
    }
    $max = [int][math]::Min(4, [math]::Floor($cs.Count * 0.1))
    $out = @{}
    if ($max -le 0) { return $out }
    foreach ($x in @($cand | Sort-Object { -[math]::Abs([double]$_[1]) } | Select-Object -First $max)) { $out[[int]$x[0]] = [double]$x[1] }
    return $out
}

function Get-FitDents($fit, [switch]$Admitted) {
    # 12.9 (correction 4) : dents d une courbe (Fit.Dents) sans les $null (courbe ou fixture sans ce champ : @($null) compte
    # 1) ; -Admitted : sans celles que la verification a retirees (Conf faux)
    if (-not $fit) { return @() }
    return @(@($fit.Dents) | Where-Object { $null -ne $_ -and (-not $Admitted -or $_.Conf -ne $false) })
}

function Get-PavaFit([double[]]$y, [double[]]$w, [int]$from, [int]$to, [bool]$inc) {
    # PAVA ponderee sur y[from..to), croissante ($inc) ou decroissante : port de CurveFit.Pava (030). Fonction pure
    $v = New-Object System.Collections.Generic.List[double]
    $wt = New-Object System.Collections.Generic.List[double]
    $cnt = New-Object System.Collections.Generic.List[int]
    for ($i = $from; $i -lt $to; $i++) {
        if ($inc) { $v.Add($y[$i]) } else { $v.Add(-$y[$i]) }
        $wt.Add($w[$i]); $cnt.Add(1)
        while ($v.Count -ge 2 -and $v[$v.Count - 2] -gt $v[$v.Count - 1]) {
            $a = $v.Count - 2; $b = $v.Count - 1
            $ww = $wt[$a] + $wt[$b]
            if ($ww -gt 0) { $v[$a] = ($v[$a] * $wt[$a] + $v[$b] * $wt[$b]) / $ww } else { $v[$a] = ($v[$a] + $v[$b]) / 2 }
            $wt[$a] = $ww; $cnt[$a] = $cnt[$a] + $cnt[$b]
            $v.RemoveAt($b); $wt.RemoveAt($b); $cnt.RemoveAt($b)
        }
    }
    $o = New-Object double[] ($to - $from); $k = 0
    for ($j = 0; $j -lt $v.Count; $j++) {
        $x = $v[$j]; if (-not $inc) { $x = -$x }
        for ($c = 0; $c -lt $cnt[$j]; $c++) { $o[$k] = $x; $k++ }
    }
    return ,$o
}

function Split-CurveDents([int[]]$cs, [double[]]$ys, [double[]]$ws, [int]$K, [int]$t1, [int]$t2, [double[]]$fy0, $dents, [int]$maxCyl, [int]$maxN = 2) {
    # 12.9 (correction 4 ; v129\cal2\donnees\dent.py, make_extra) : apres SegFit, inchange (segments en indices : [0, t1)
    # croissant, [t1, t2) decroissant, [t2, n) croissant ; K = 0 : [0, n) croissant), chaque dent (@{ C1 ; C2 ; Drop },
    # cylindres testes consecutifs de $cs, tous deux dans le meme segment croissant ; $maxN au plus, les plus fortes ; une
    # dent au changement de sens de SegFit est ignoree) coupe ce segment :
    # croissant jusqu a C1, decroissant d un seul point (C2, sa valeur mesuree), croissant ensuite. Chaque morceau croissant
    # est refait par PAVA ponderee (Get-PavaFit) ; le segment decroissant de SegFit garde ses valeurs. Segments en
    # cylindres comme ceux de SegFit (Lo = Hi precedent + 1 ; Hi = dernier cylindre teste du morceau, maxCyl pour le
    # dernier). Fonction pure. Renvoie @{ Fy ; Segs ; Dents (dents appliquees) } ; aucune dent appliquee : Fy = $fy0, Segs $null
    $n = $cs.Count
    $rng = New-Object System.Collections.Generic.List[object]
    if ($K -eq 0) { $rng.Add(@(0, $n, 1)) }
    elseif ($K -eq 1) { $rng.Add(@(0, $t1, 1)); $rng.Add(@($t1, $n, -1)) }
    else { $rng.Add(@(0, $t1, 1)); $rng.Add(@($t1, $t2, -1)); if ($t2 -lt $n) { $rng.Add(@($t2, $n, 1)) } }
    $at = @{}
    foreach ($d in @($dents | Where-Object { $null -ne $_ })) {
        $i = [array]::IndexOf($cs, [int]$d.C1); $j = [array]::IndexOf($cs, [int]$d.C2)
        if ($i -lt 0 -or $j -ne $i + 1) { continue }
        $in = $false
        foreach ($g in $rng) { if ([int]$g[2] -eq 1 -and $i -ge [int]$g[0] -and $i -lt [int]$g[1] - 1) { $in = $true; break } }
        if ($in) { $at[$i] = $d }
    }
    if ($at.Count -gt [math]::Max(0, $maxN)) {
        $top = @(@($at.Keys | ForEach-Object { [int]$_ }) | Sort-Object @{ Expression = { -[double]$at[$_].Drop } }, @{ Expression = { $_ } } | Select-Object -First ([math]::Max(0, $maxN)))
        $a2 = @{}; foreach ($i in $top) { $a2[[int]$i] = $at[[int]$i] }; $at = $a2
    }
    $pieces = New-Object System.Collections.Generic.List[object]; $ok = @()
    foreach ($g in $rng) {
        if ([int]$g[2] -ne 1) { $pieces.Add(@([int]$g[0], [int]$g[1], -1, $true)); continue }
        $st = [int]$g[0]
        foreach ($i in @($at.Keys | ForEach-Object { [int]$_ } | Sort-Object)) {
            if ($i -lt $st -or $i -ge [int]$g[1] - 1) { continue }
            $pieces.Add(@($st, ($i + 1), 1, $false)); $pieces.Add(@(($i + 1), ($i + 2), -1, $false))
            $st = $i + 2; $ok += ,$at[$i]
        }
        if ($st -lt [int]$g[1]) { $pieces.Add(@($st, [int]$g[1], 1, $false)) }
    }
    if ($ok.Count -eq 0) { return @{ Fy = $fy0; Segs = $null; Dents = @() } }
    $fy = New-Object double[] $n
    foreach ($pc in $pieces) {
        $a = [int]$pc[0]; $b = [int]$pc[1]
        if ([bool]$pc[3]) { for ($i = $a; $i -lt $b; $i++) { $fy[$i] = $fy0[$i] } }
        elseif ($b - $a -eq 1) { $fy[$a] = $ys[$a] }
        else { $pv = Get-PavaFit $ys $ws $a $b ([int]$pc[2] -eq 1); for ($i = $a; $i -lt $b; $i++) { $fy[$i] = $pv[$i - $a] } }
    }
    $segs = @(); $lo = 0
    for ($q = 0; $q -lt $pieces.Count; $q++) {
        $hi = if ($q -lt $pieces.Count - 1) { [int]$cs[[int]$pieces[$q][1] - 1] } else { $maxCyl }
        $segs += ,@{ Lo = $lo; Hi = $hi; Dir = [int]$pieces[$q][2] }
        $lo = $hi + 1
    }
    return @{ Fy = $fy; Segs = $segs; Dents = $ok }
}

function Merge-CurveDentSegs($segs, [int]$c1, [int]$c2) {
    # 12.9 (correction 4) : dent retiree (non confirmee par la verification) : les trois segments qu elle a crees
    # (croissant jusqu a c1, decroissant c1+1..c2, croissant ensuite) redeviennent un seul segment croissant ; valeurs de la
    # courbe inchangees. Fonction pure. Renvoie les segments (tels quels si la dent n y est pas)
    $s = @(@($segs) | Where-Object { $null -ne $_ })
    for ($i = 1; $i -lt $s.Count; $i++) {
        if ([int]$s[$i].Dir -ne -1 -or [int]$s[$i].Lo -ne $c1 + 1 -or [int]$s[$i].Hi -ne $c2) { continue }
        if ([int]$s[$i - 1].Dir -ne 1 -or [int]$s[$i - 1].Hi -ne $c1) { continue }
        $hi = $c2; $last = $i
        if ($i + 1 -lt $s.Count -and [int]$s[$i + 1].Dir -eq 1) { $hi = [int]$s[$i + 1].Hi; $last = $i + 1 }
        $res = @()
        for ($k = 0; $k -lt $s.Count; $k++) {
            if ($k -eq $i - 1) { $res += ,@{ Lo = [int]$s[$i - 1].Lo; Hi = $hi; Dir = 1 } }
            elseif ($k -lt $i - 1 -or $k -gt $last) { $res += ,$s[$k] }
        }
        return $res
    }
    return $s
}

function Fit-PrecompCurve($est, $sig, [int]$maxCyl, $kinds = $null, [bool]$dense = $false, $Dents = $null) {
    # Courbe de precompensation par cylindre a partir des estimations des cylindres testes.
    # Moindres carres ponderes (poids = 1 / incertitude^2) de p = A + B.x, B >= 0, pour trois formes
    # physiquement plausibles (densite lineaire croissante vers l interieur) : x = cylindre, 1/rayon,
    # 1/rayon^2 ; la forme de plus faible ecart pondere est retenue. Si elle n explique pas les mesures
    # (chi2 reduit > 4 avec au moins 4 points), interpolation monotone des mesures lissees (PAVA).
    # Donnees denses : points isoles ecartes (poids nul : la courbe passe par l interpolation de leurs voisins)
    # 12.9 (correction 4) : $Dents, dents locales admises (@{ C1 ; C2 }, Get-CalibDents) : chemin monotone par segments
    # impose (CurveFit), puis coupure des segments croissants qui les contiennent (Split-CurveDents) ; Breaks reste celui
    # de SegFit (260 et 265 lisent Breaks[0]) ; Dents : dents appliquees (vide sans dent)
    $csAll = @($est.Keys | ForEach-Object { [int]$_ } | Sort-Object)
    if ($csAll.Count -eq 0) { return $null }
    $dl = @(@($Dents) | Where-Object { $null -ne $_ })                                     # 12.9
    $outl = @{}
    if ($dense -and $csAll.Count -ge 8) { $outl = Get-IsolatedPoints $csAll $est $sig }
    $cs = @($csAll | Where-Object { -not $outl.ContainsKey($_) })
    $ys = @($cs | ForEach-Object { [double]$est[$_] })
    $ws = @($cs | ForEach-Object { $s = if ($sig -and $sig.ContainsKey($_)) { [math]::Max(1.0, [double]$sig[$_]) } else { 5.0 }; 1.0 / ($s * $s) })
    $best = $null
    foreach ($model in 'lin', 'inv', 'inv2') {
        $xs = @($cs | ForEach-Object { Get-CurveX $model $_ $maxCyl })
        $sw = 0.0; $sx = 0.0; $sy = 0.0
        for ($i = 0; $i -lt $cs.Count; $i++) { $sw += $ws[$i]; $sx += $ws[$i] * $xs[$i]; $sy += $ws[$i] * $ys[$i] }
        $mx = $sx / $sw; $my = $sy / $sw
        $sxx = 0.0; $sxy = 0.0
        for ($i = 0; $i -lt $cs.Count; $i++) { $sxx += $ws[$i] * ($xs[$i] - $mx) * ($xs[$i] - $mx); $sxy += $ws[$i] * ($xs[$i] - $mx) * ($ys[$i] - $my) }
        $b = if ($cs.Count -ge 2 -and $sxx -gt 0) { [math]::Max(0.0, $sxy / $sxx) } else { 0.0 }
        $a = $my - $b * $mx
        $ssr = 0.0
        for ($i = 0; $i -lt $cs.Count; $i++) { $e = $ys[$i] - ($a + $b * $xs[$i]); $ssr += $ws[$i] * $e * $e }
        if ($null -eq $best -or $ssr -lt $best.Ssr) { $best = @{ Model = $model; A = $a; B = $b; Ssr = $ssr } }
    }
    $chi = $best.Ssr / [math]::Max(1, $cs.Count - 2)
    $vals = New-Object int[] ($maxCyl + 1)
    if ($cs.Count -ge 4 -and ($chi -gt 4.0 -or ($dl.Count -gt 0 -and $script:CurveFitOk))) {   # 12.9 : dents
        # Monotone par segments (CurveFit) : le besoin peut redescendre une ou deux fois, seulement sur une chute nette
        # (plus de 15 ns et de 3 incertitudes) entre deux mesures encadrees ; sinon croissant (PAVA). Puis lineaire
        # entre cylindres testes.
        $fyS = $null; $model = 'iso'; $breaks = @(); $segs = $null; $applied = @()
        if ($script:CurveFitOk) {
            $rel = [bool[]]@($cs | ForEach-Object { -not $kinds -or -not $kinds.ContainsKey($_) -or $kinds[$_] -eq 'interp' })
            $sg = @($cs | ForEach-Object { if ($sig -and $sig.ContainsKey($_)) { [math]::Max(1.0, [double]$sig[$_]) } else { 5.0 } })
            $minDrop = [math]::Max($script:CalDevNs, 3.0 * [math]::Sqrt(2.0) * (Get-Median $sg))
            $r = [CurveFit]::SegFit([double[]]$ys, [double[]]$ws, $rel, 4.0 * [math]::Log($cs.Count), $minDrop)
            $K = [int]$r[0]
            $fyS = @($r[4..($r.Count - 1)])
            if ($K -ge 1) {
                $pk = [int]$cs[[int]$r[1] - 1]
                $tr = if ($K -eq 2) { [int]$cs[[int]$r[2] - 1] } else { $maxCyl }
                $model = 'seg'
                $breaks = if ($K -eq 2) { @($pk, $tr) } else { @($pk) }
                $segs = @(@{ Lo = 0; Hi = $pk; Dir = 1 }, @{ Lo = $pk + 1; Hi = $tr; Dir = -1 })
                if ($K -eq 2 -and $tr -lt $maxCyl) { $segs += @{ Lo = $tr + 1; Hi = $maxCyl; Dir = 1 } }
            }
            # 12.9 (correction 4) : dents coupees dans les segments croissants de SegFit (Breaks inchange), CalDentMax au plus
            if ($dl.Count -gt 0) {
                $dmx = if ($null -ne $script:CalDentMax) { [int]$script:CalDentMax } else { 2 }
                $sp = Split-CurveDents ([int[]]$cs) ([double[]]$ys) ([double[]]$ws) $K ([int]$r[1]) ([int]$r[2]) ([double[]]$fyS) $dl $maxCyl $dmx
                if (@($sp.Dents).Count -gt 0) { $fyS = @($sp.Fy); $segs = $sp.Segs; $model = 'seg'; $applied = @($sp.Dents) }
            }
        }
        if ($null -ne $fyS) {
            $fy = $fyS
            for ($c = 0; $c -le $maxCyl; $c++) {
                if ($c -le $cs[0]) { $v = $fy[0] }
                elseif ($c -ge $cs[-1]) { $v = $fy[-1] }
                else {
                    $j = 0; while ($cs[$j + 1] -lt $c) { $j++ }
                    $tt = ($c - $cs[$j]) / [double]($cs[$j + 1] - $cs[$j])
                    $v = $fy[$j] + $tt * ($fy[$j + 1] - $fy[$j])
                }
                $vals[$c] = [int][math]::Max(0, [math]::Min($script:CalHardNs, [math]::Round($v, 0)))
            }
            return @{ Model = $model; A = $null; B = $null; Chi = $chi; Values = $vals; Breaks = $breaks; Segs = $segs; Outliers = @($outl.Keys); Dents = $applied }
        }
        # Repli sans CurveFit : interpolation monotone croissante (PAVA pondere sur les mesures)
        $blocks = New-Object System.Collections.Generic.List[object]
        for ($i = 0; $i -lt $cs.Count; $i++) {
            $blocks.Add(@{ SW = $ws[$i]; SWY = $ws[$i] * $ys[$i]; N = 1 })
            while ($blocks.Count -ge 2) {
                $p = $blocks[$blocks.Count - 2]; $q = $blocks[$blocks.Count - 1]
                if ($p.SWY / $p.SW -le $q.SWY / $q.SW) { break }
                $blocks.RemoveAt($blocks.Count - 1); $blocks.RemoveAt($blocks.Count - 1)
                $blocks.Add(@{ SW = $p.SW + $q.SW; SWY = $p.SWY + $q.SWY; N = $p.N + $q.N })
            }
        }
        $fy = @(); foreach ($bk in $blocks) { for ($k = 0; $k -lt $bk.N; $k++) { $fy += $bk.SWY / $bk.SW } }
        for ($c = 0; $c -le $maxCyl; $c++) {
            if ($c -le $cs[0]) { $v = $fy[0] }
            elseif ($c -ge $cs[-1]) { $v = $fy[-1] }
            else {
                $j = 0; while ($cs[$j + 1] -lt $c) { $j++ }
                $t = ($c - $cs[$j]) / [double]($cs[$j + 1] - $cs[$j])
                $v = $fy[$j] + $t * ($fy[$j + 1] - $fy[$j])
            }
            $vals[$c] = [int][math]::Max(0, [math]::Min($script:CalHardNs, [math]::Round($v, 0)))
        }
        return @{ Model = 'iso'; A = $null; B = $null; Chi = $chi; Values = $vals; Breaks = @(); Segs = $null; Outliers = @($outl.Keys); Dents = @() }
    }
    for ($c = 0; $c -le $maxCyl; $c++) {
        $v = $best.A + $best.B * (Get-CurveX $best.Model $c $maxCyl)
        $vals[$c] = [int][math]::Max(0, [math]::Min($script:CalHardNs, [math]::Round($v, 0)))
    }
    return @{ Model = $best.Model; A = $best.A; B = $best.B; Chi = $chi; Values = $vals; Breaks = @(); Segs = $null; Outliers = @($outl.Keys); Dents = @() }
}

function Add-CurveCorrection($values, $delta, $segs = $null) {
    # Valeurs par cylindre + corrections locales (ns) mesurees aux cylindres verifies, segment par segment (courbe
    # monotone par segments : jamais d interpolation ni de lissage a travers un changement de sens) : interpolation
    # lineaire des corrections des cylindres verifies du segment (0 la ou le residu est dans la tolerance), constante
    # jusqu aux bords du segment, puis lissage monotone dans le sens du segment (PAVA) et arrondi a l entier.
    $v = @($values); $n = $v.Count
    if (-not $segs) { $segs = @(@{ Lo = 0; Hi = $n - 1; Dir = 1 }) }
    $out = New-Object int[] $n
    for ($c = 0; $c -lt $n; $c++) { $out[$c] = [int]$v[$c] }
    foreach ($sg in @($segs)) {
        $lo = [math]::Max(0, [int]$sg.Lo); $hi = [math]::Min($n - 1, [int]$sg.Hi)
        if ($hi -lt $lo) { continue }
        $ks = @($delta.Keys | ForEach-Object { [int]$_ } | Where-Object { $_ -ge $lo -and $_ -le $hi } | Sort-Object)
        if ($ks.Count -gt 0 -and @($segs).Count -gt 1) {
            # Ancrage aux bords : cylindre verifie le plus proche dans le segment voisin (sommet ou creux), pour que la
            # correction parte de la sienne au lieu de s appliquer telle quelle jusqu au changement de sens
            $kl = @($delta.Keys | ForEach-Object { [int]$_ } | Where-Object { $_ -lt $lo } | Sort-Object)
            $kr = @($delta.Keys | ForEach-Object { [int]$_ } | Where-Object { $_ -gt $hi } | Sort-Object)
            if ($kl.Count -gt 0) { $ks = @(@($kl[-1]) + $ks) }
            if ($kr.Count -gt 0) { $ks = @($ks + @($kr[0])) }
        }
        $raw = New-Object double[] ($hi - $lo + 1)
        for ($c = $lo; $c -le $hi; $c++) {
            $d = 0.0
            if ($ks.Count -gt 0) {
                if ($c -le $ks[0]) { $d = [double]$delta[$ks[0]] }
                elseif ($c -ge $ks[-1]) { $d = [double]$delta[$ks[-1]] }
                else {
                    $j = 0; while ($ks[$j + 1] -lt $c) { $j++ }
                    $tt = ($c - $ks[$j]) / [double]($ks[$j + 1] - $ks[$j])
                    $d = [double]$delta[$ks[$j]] + $tt * ([double]$delta[$ks[$j + 1]] - [double]$delta[$ks[$j]])
                }
            }
            $raw[$c - $lo] = ([double]$v[$c] + $d) * [int]$sg.Dir
        }
        $blocks = New-Object System.Collections.Generic.List[object]
        foreach ($x in $raw) {
            $blocks.Add(@{ S = $x; N = 1 })
            while ($blocks.Count -ge 2) {
                $p = $blocks[$blocks.Count - 2]; $q = $blocks[$blocks.Count - 1]
                if ($p.S / $p.N -le $q.S / $q.N) { break }
                $blocks.RemoveAt($blocks.Count - 1); $blocks.RemoveAt($blocks.Count - 1)
                $blocks.Add(@{ S = $p.S + $q.S; N = $p.N + $q.N })
            }
        }
        $c = $lo
        foreach ($bk in $blocks) { $m = [int][math]::Max(0, [math]::Min($script:CalHardNs, [math]::Round($bk.S / $bk.N * [int]$sg.Dir, 0))); for ($k = 0; $k -lt $bk.N; $k++) { $out[$c++] = $m } }
    }
    return ,$out
}

function Get-CurveSteps($values, $breaks, [double]$stepNs) {
    # 12.10 (lot 1, A1-tendance) : marches franches d une courbe (affichage seul) : cylindres c d une marche entre c et c+1,
    # dans un segment des changements de sens (Breaks : coupure entre b et b+1). Marche : ecart d au moins max(stepNs ;
    # 4 ecarts robustes des differences premieres, 1,4826 x MAD), et ecart des medianes des 3 cylindres de part et d autre
    # (c-2 a c, c+1 a c+3, bornes du segment) d au moins le meme seuil : un pic isole n est pas une marche
    $v = @($values); $n = $v.Count
    if ($n -lt 2) { return ,@() }
    $cut = @(@($breaks) | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_ } | Where-Object { $_ -ge 0 -and $_ -lt $n - 1 } | Sort-Object -Unique)
    $d = @(); for ($c = 0; $c -lt $n - 1; $c++) { if ($cut -notcontains $c) { $d += [double]$v[$c + 1] - [double]$v[$c] } }
    $rs = 0.0
    if ($d.Count -gt 0) { $md = Get-Median $d; $rs = 1.4826 * (Get-Median @($d | ForEach-Object { [math]::Abs($_ - $md) })) }
    $thr = [math]::Max($stepNs, 4.0 * $rs)
    $out = @(); $lo = 0
    foreach ($hi in @(@($cut) + @($n - 1))) {
        for ($c = $lo; $c -lt $hi; $c++) {
            if ([math]::Abs([double]$v[$c + 1] - [double]$v[$c]) -lt $thr) { continue }
            $left = @($v[([math]::Max($lo, $c - 2))..$c]); $right = @($v[($c + 1)..([math]::Min($hi, $c + 3))])
            if ([math]::Abs((Get-Median $right) - (Get-Median $left)) -ge $thr) { $out += $c }
        }
        $lo = $hi + 1
    }
    return ,@($out)
}

function Get-CurveTrend($values, $breaks, [double]$stepNs) {
    # 12.10 (lot 1, A1-tendance, D1) : tendance lissee de la courbe retenue, pour l affichage seul (fenetre Courbe) : aucun
    # effet sur l ecriture, les courbes enregistrees ni le calcul de calibration. Segments coupes aux changements de sens
    # (Breaks) et aux marches franches (Get-CurveSteps) ; dans chaque segment, moindres carres quadratiques locaux
    # (Savitzky-Golay, +-4 cylindres), fenetre tronquee aux bords du segment, sans contrainte de monotonie ; segment de
    # moins de 3 cylindres : valeurs recopiees. Valeurs negatives ramenees a 0. Renvoie un double[] de la taille de la courbe
    $v = @($values); $n = $v.Count
    $out = New-Object double[] $n
    for ($c = 0; $c -lt $n; $c++) { $out[$c] = [double]$v[$c] }
    if ($n -lt 3) { return ,$out }
    $cut = @(@($breaks) | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_ } | Where-Object { $_ -ge 0 -and $_ -lt $n - 1 })
    $steps = Get-CurveSteps $v $breaks $stepNs       # tableau protege (operateur virgule) : pas de @() autour de l appel
    $cut = @(@($cut) + @($steps) | Sort-Object -Unique)
    $lo = 0
    foreach ($hi in @(@($cut) + @($n - 1))) {
        if ($hi - $lo + 1 -ge 3) {
            for ($c = $lo; $c -le $hi; $c++) {
                # Valeur en c de la parabole des moindres carres sur [c-4 ; c+4] borne au segment (x = j - c) : regle de Cramer
                $s0 = 0.0; $s1 = 0.0; $s2 = 0.0; $s3 = 0.0; $s4 = 0.0; $t0 = 0.0; $t1 = 0.0; $t2 = 0.0
                for ($j = [math]::Max($lo, $c - 4); $j -le [math]::Min($hi, $c + 4); $j++) {
                    $x = [double]($j - $c); $x2 = $x * $x; $y = [double]$v[$j]
                    $s0 += 1.0; $s1 += $x; $s2 += $x2; $s3 += $x2 * $x; $s4 += $x2 * $x2; $t0 += $y; $t1 += $x * $y; $t2 += $x2 * $y
                }
                $dm = $s0 * ($s2 * $s4 - $s3 * $s3) - $s1 * ($s1 * $s4 - $s3 * $s2) + $s2 * ($s1 * $s3 - $s2 * $s2)
                if ([math]::Abs($dm) -lt 1e-9) { continue }
                $p0 = ($t0 * ($s2 * $s4 - $s3 * $s3) - $s1 * ($t1 * $s4 - $s3 * $t2) + $s2 * ($t1 * $s3 - $s2 * $t2)) / $dm
                $out[$c] = [math]::Max(0.0, $p0)
            }
        }
        $lo = $hi + 1
    }
    return ,$out
}

function Get-CurveTrendFor($cv) {
    # 12.10 (lot 1, A1-tendance) : tendance d une courbe a donnees denses (au moins CurveTrendMinCyls cylindres mesures :
    # test fin ou mesures complementaires) : @{ Trend ; Steps }, $null sinon. Seuil de marche CurveTrendStepNs, haute
    # densite : x CalHdK (bareme de la famille de la courbe)
    if (-not $cv -or @(@($cv.Cyls) | Where-Object { $null -ne $_ }).Count -lt $script:CurveTrendMinCyls) { return $null }
    $v = @($cv.Values)
    if ($v.Count -lt 3) { return $null }
    $st = if (Test-CurveHd $cv) { $script:CurveTrendStepNs * $script:CalHdK } else { $script:CurveTrendStepNs }
    return @{ Trend = (Get-CurveTrend $v $cv.Breaks $st); Steps = (Get-CurveSteps $v $cv.Breaks $st) }
}

function Build-CurveProfile($values) {
    # Valeurs par cylindre -> profil --precomp : une entree c=ns a chaque changement (gw : valeur pour c et au-dela)
    $v = @($values)
    if ($v.Count -eq 0) { return '' }
    $parts = @("0=$($v[0])")
    for ($c = 1; $c -lt $v.Count; $c++) { if ($v[$c] -ne $v[$c - 1]) { $parts += "$c=$($v[$c])" } }
    return ($parts -join ':')
}

function Get-CurveModelName([string]$model) {
    if ($model -match '^(.+)\+c$') { return (Get-CurveModelName $Matches[1]) + (T ' + corrections locales') }
    switch ($model) {
        'lin'  { return (T 'linéaire') }
        'inv'  { return (T '1/rayon') }
        'inv2' { return (T '1/rayon²') }
        'iso'  { return (T 'monotone interpolée') }
        'seg'  { return (T 'monotone par segments') }
        default { return $model }
    }
}

function Format-CurveTable($cvs, [bool]$trend = $false) {
    # Tableau texte des valeurs par cylindre (10 par ligne), profil --precomp, puis mesures avec leur origine, l ecart
    # de la courbe et le residu de la derniere verification, pour chaque courbe. 12.10 (lot 1, A1-tendance) : trend (case
    # « Tendance lissee » de la fenetre Courbe) : ligne de la tendance sous les valeurs d une courbe a donnees denses
    $lines = @()
    $kn = @{ witness = (T 'témoin de marche'); probe = (T 'témoin du plafond') }
    foreach ($cv in @($cvs)) {
        if ($lines.Count -gt 0) { $lines += ''; $lines += '' }
        $lrs = Get-CurveLevelRecs $cv
        foreach ($rec in @($lrs)) {
            $vk = if ([string]$rec.Shape -eq 'mismatch') { 'mismatch' } else { [string]$rec.Verdict }
            $vt = @{ ok = (T 'conforme'); approx = (T 'approximative'); mismatch = (T 'NON CONFORME'); sat = (T 'non vérifiée, plafond atteint'); low = (T 'non vérifiée, plancher atteint'); few = (T 'non vérifiée, trop peu de cylindres mesurés'); adapte = (T 'adaptée à cette disquette'); mesure = (T 'mesurée sur cette disquette') }[$vk]
            $hp = if ($null -eq $rec.Head) { '' } else { (T '[tête {0}] ') -f "$($rec.Head)" }
            # 12.8 (S3) : courbe d une mesure complete de cette disquette : ecart moyen a la reference, sans niveau mesure
            if ([string]$rec.Model -eq 'mesure') { $lines += ($hp + ((T "Dernière mesure complète d'une disquette ({0}, lecteur {1}) : courbe mesurée sur tous ses cylindres, écart moyen à cette référence {2} ns ; {3} passe(s) ; profil appliqué : {4}") -f "$($rec.Date)", "$($rec.Drive)", ('{0:+0;-0;0}' -f [int]$rec.Delta), "$($rec.Passes)", "$($rec.Spec)")) }
            else { $lines += ($hp + ((T "Dernière calibration rapide ({0}, lecteur {1}) : niveau {2} ns ± {3} ; écart de forme {4} ns ; forme {5} ; {6} passe(s) ; profil appliqué : {7}") -f "$($rec.Date)", "$($rec.Drive)", ('{0:+0;-0;0}' -f [int]$rec.Delta), (Format-LevelNum $rec.SE), (Format-LevelNum $rec.Tau), "$vt", "$($rec.Passes)", "$($rec.Spec)")) }
            for ($i = 0; $i -lt @($rec.Cyls).Count; $i++) {
                $kd = [string]$rec.Kinds[$i]; $kt = if ($kn.ContainsKey($kd)) { $kn[$kd] } else { Get-KindName $kd }
                $lines += ((T "  c{0,-3} zéro {1,6:0.0} ± {2,4:0.0}  écart à la forme {3,6:+0.0;-0.0;0.0}  {4}") -f [int]$rec.Cyls[$i], [double]$rec.Zs[$i], [double]$rec.Sigs[$i], $(if ([double]::IsNaN([double]$rec.Est)) { '-' } else { [double]$rec.Ds[$i] - [double]$rec.Est }), "$kt")
            }
            $hv = @(@($rec.Hist) | ForEach-Object { [double]$_.Delta })
            if ($hv.Count -gt 0) { $lines += ((T "Niveaux mesurés avec cette référence : médiane {0} ns, de {1} à {2} ns, {3} disquette(s).") -f ('{0:+0;-0;0}' -f [math]::Round((Get-Median $hv), 0)), ('{0:+0;-0;0}' -f ($hv | Measure-Object -Minimum).Minimum), ('{0:+0;-0;0}' -f ($hv | Measure-Object -Maximum).Maximum), "$($hv.Count)") }
            $lines += ''
        }
        if ($null -ne $cv.Head) { $lines += ((T "Tête {0} : courbe {1}") -f "$($cv.Head)", (Get-CurveModelName $cv.Model)) }
        $lines += ((T "Calcul de calibration : {0}") -f (Get-CurveCalcText $cv))
        if ($cv.Converged -eq $false) { $lines += (T 'NON CONVERGÉE : résidu hors tolérance après la dernière vérification (voir « résidu »).') }
        $v = @($cv.Values)
        $lines += @(((T "Profil --precomp : {0}") -f "$($cv.Spec)"), '', ('cyl  ' + ((0..9 | ForEach-Object { '{0,5}' -f "+$_" }) -join '')))
        for ($c0 = 0; $c0 -lt $v.Count; $c0 += 10) {
            $row = @(); for ($c = $c0; $c -lt [math]::Min($v.Count, $c0 + 10); $c++) { $row += ('{0,5}' -f $v[$c]) }
            $lines += ('{0,3}  ' -f $c0) + ($row -join '')
        }
        $lines += ''
        # 12.10 (lot 1, A1-tendance) : ecart de la tendance lissee a la courbe retenue (min, max, moyenne quadratique) et
        # marches gardees (marche entre c et c+1)
        $tr = if ($trend) { Get-CurveTrendFor $cv } else { $null }
        if ($tr) {
            $dv = @(for ($c = 0; $c -lt $v.Count; $c++) { [double]$tr.Trend[$c] - [double]$v[$c] })
            $rms = [math]::Sqrt((@($dv | ForEach-Object { $_ * $_ }) | Measure-Object -Sum).Sum / [math]::Max(1, $dv.Count))
            $stx = if (@($tr.Steps).Count) { (@($tr.Steps) | ForEach-Object { "c$_/c$([int]$_ + 1)" }) -join ', ' } else { (T 'aucune') }
            $lines += ((T "Tendance lissée (affichage seul, sans effet sur l'écriture) : écart à la courbe retenue de {0} à {1} ns, {2} ns en moyenne quadratique ; marches gardées : {3}.") -f (Format-UiNum (($dv | Measure-Object -Minimum).Minimum) '+0.0;-0.0;0.0'), (Format-UiNum (($dv | Measure-Object -Maximum).Maximum) '+0.0;-0.0;0.0'), (Format-UiNum $rms '0.0'), "$stx")
            $lines += ''
        }
        $lines += (T "Mesures (cylindre : estimation ± incertitude en ns, origine, courbe retenue et écart, résidu de vérification) :")
        for ($i = 0; $i -lt @($cv.Cyls).Count; $i++) {
            $c = [int]$cv.Cyls[$i]
            $kind = if ($cv.Kinds -and $i -lt @($cv.Kinds).Count) { Get-KindName $cv.Kinds[$i] } else { '' }
            $cur = if ($c -lt $v.Count) { $v[$c] } else { $null }
            $dev = if ($null -ne $cur) { '{0:+0;-0;0}' -f ($cur - [double]$cv.Ys[$i]) } else { '' }
            # Zone non reproductible (verifications contradictoires) : valeur retenue sans mesure a cette valeur
            $res = if (@($cv.Contra) -contains $c) { (T 'zone non reproductible') }
                   elseif ($cv.Res -and $i -lt @($cv.Res).Count -and -not [double]::IsNaN([double]$cv.Res[$i])) { (T 'résidu {0}') -f ('{0:+0.0;-0.0;0.0}' -f [double]$cv.Res[$i]) } else { '' }
            $lines += ("  c{0,-3} {1,6:0.0} ± {2,4:0.0}  {3,-11} {4} {5,4} ({6,4})  {7}" -f $c, [double]$cv.Ys[$i], [double]$cv.Sig[$i], $kind, (T 'courbe'), $cur, $dev, $res).TrimEnd()
        }
    }
    return ($lines -join "`r`n")
}

function Draw-PrecompCurve($g, $size, [bool]$trend = $false) {
    # Une courbe (profil commun) ou une par tete (ecriture lente). Mesures selon leur origine : point plein = encadree
    # par deux mesures, cercle creux = extrapolee, carre creux = plafonnee ; anneau rouge = ecart a la courbe > max(15 ns ; 3 incertitudes).
    # Zone hachuree : au-dessus de la plus forte precomp mesuree (extrapolation).
    $cvs = @(@($script:CurveData) | Where-Object { $_ })
    if ($cvs.Count -eq 0) { return }
    $multi = $cvs.Count -gt 1
    # 12.7 point 2 : comparaison des calibrations A et B (copies marquees Series 'A' ou 'B', Show-CalibReview) : couleur par
    # tete, B en tirets, zones de desaccord ($script:CurveZones) en bandes verticales. Sans Series : dessin inchange
    $cmp = (@($cvs | Where-Object { $_.Series }).Count -gt 0)
    # 12.10 (lot 1, A1-tendance) : trend (fenetre Courbe, case « Tendance lissee ») : tendance lissee des courbes a donnees
    # denses (Get-CurveTrendFor), pointille fin de la couleur de la courbe ; ni en comparaison A/B, ni sur les courbes
    # decalees de la derniere disquette. Sans trend (fenetre de decision, fins de test) : dessin inchange
    $trends = @{}
    if ($trend -and -not $cmp) { for ($k = 0; $k -lt $cvs.Count; $k++) { $tv = Get-CurveTrendFor $cvs[$k]; if ($tv) { $trends[$k] = $tv } } }
    # Niveaux de la derniere calibration rapide, superposes a chaque courbe (Set-CurveLevelData)
    $lvls = @{}; $hasLevel = $false
    for ($k = 0; $k -lt $cvs.Count; $k++) {
        # Affectation directe : un if renverrait un enregistrement seul deroule (table de hachage, pas tableau)
        $lvls[$k] = @()
        if ($script:CurveLevel -and $script:CurveLevel.ContainsKey($k)) { $lvls[$k] = @($script:CurveLevel[$k]) }
        if ($lvls[$k].Count -gt 0) { $hasLevel = $true }
    }
    $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
    $g.Clear([System.Drawing.Color]::White)
    $W = $size.Width; $H = $size.Height
    $nRec = @(@($lvls.Values) | ForEach-Object { $_ }).Count       # un enregistrement de niveau par ligne de legende
    $L = 56; $R = 20; $Tp = $(if ($hasLevel) { 92 + 20 * [math]::Max(0, $nRec - 1) } else { 72 }); $Bm = 40
    # 12.10 (captures du wiki) : tendance de plusieurs courbes (une par tete) : sa legende a sa propre ligne, sous les
    # libelles des courbes (a la suite, elle sortait de la fenetre a sa largeur par defaut) ; niveaux une ligne plus bas
    $trRow = ($trends.Count -gt 0 -and $multi)
    if ($trRow) { $Tp += 20 }
    $zones = @(@($script:CurveZones) | Where-Object { $_ })
    if ($cmp) {
        # Legende : une ligne par tete (A puis B), plus une ligne pour les zones de desaccord
        $nh = @($cvs | Where-Object { $null -ne $_.Head } | ForEach-Object { [int]$_.Head } | Sort-Object -Unique).Count
        $Tp = 72 + 20 * ([math]::Max(1, $nh) - 1) + $(if ($zones.Count) { 20 } else { 0 })
    }
    $pw = $W - $L - $R; $ph = $H - $Tp - $Bm
    if ($pw -lt 60 -or $ph -lt 40) { return }
    $nC = 2; foreach ($cv in $cvs) { $nC = [math]::Max($nC, @($cv.Values).Count) }
    $maxC = $nC - 1
    $top = 0.0; $maxX = 0
    foreach ($cv in $cvs) {
        foreach ($x in @($cv.Values)) { if ($x -gt $top) { $top = $x } }
        for ($i = 0; $i -lt @($cv.Cyls).Count; $i++) { $t = [double]$cv.Ys[$i] + [double]$cv.Sig[$i]; if ($t -gt $top) { $top = $t } }
        if ($cv.MaxX -and [int]$cv.MaxX -gt $maxX) { $maxX = [int]$cv.MaxX }
    }
    foreach ($k in @($trends.Keys)) { foreach ($x in @($trends[$k].Trend)) { if ($x -gt $top) { $top = $x } } }
    foreach ($k in @($lvls.Keys)) { foreach ($rec in $lvls[$k]) {
        foreach ($x in @($rec.Values)) { if ($x -gt $top) { $top = $x } }
        for ($i = 0; $i -lt @($rec.Zs).Count; $i++) { $tz = [double]$rec.Zs[$i] + [double]$rec.Sigs[$i]; if ($tz -gt $top) { $top = $tz } }
    } }
    $step = if ($top -le 120) { 20 } elseif ($top -le 400) { 50 } else { 100 }      # pas de 50 jusqu a la borne CalHardNs
    $ymax = [math]::Max(2 * $step, [math]::Ceiling($top / $step) * $step)
    $fx = { param($c) $L + $pw * $c / $maxC }
    $fy = { param($v) $Tp + $ph * (1.0 - $v / $ymax) }
    $font = New-Object System.Drawing.Font('Segoe UI', 8.25)
    $fontB = New-Object System.Drawing.Font('Segoe UI Semibold', 9.75)
    $grid = New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(228, 232, 238), 1)
    $axis = New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(150, 156, 166), 1)
    $err = New-Object System.Drawing.Pen($script:Theme.Muted, 1.2)
    $flag = New-Object System.Drawing.Pen($script:Theme.Danger, 1.8)
    $txt = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(70, 76, 88))
    $red = New-Object System.Drawing.SolidBrush($script:Theme.Danger)
    $gray = New-Object System.Drawing.SolidBrush($script:Theme.Muted)
    $grayPen = New-Object System.Drawing.Pen($script:Theme.Muted, 1.6)
    $hatch = New-Object System.Drawing.Drawing2D.HatchBrush([System.Drawing.Drawing2D.HatchStyle]::BackwardDiagonal, [System.Drawing.Color]::FromArgb(222, 226, 232), [System.Drawing.Color]::White)
    $colors = @($script:Theme.Accent, $script:Theme.Flux)
    $pens = @(); $dots = @(); $hollow = @()
    for ($i = 0; $i -lt $cvs.Count; $i++) {
        $col = if ($cmp) { $colors[[math]::Min($(if ($null -ne $cvs[$i].Head) { [int]$cvs[$i].Head } else { 0 }), 1)] } else { $colors[[math]::Min($i, 1)] }
        $dc = if ($multi) { $col } else { $script:Theme.Flux }
        $pn = New-Object System.Drawing.Pen($col, 2.2)
        if ($cmp -and [string]$cvs[$i].Series -eq 'B') { $pn.DashStyle = [System.Drawing.Drawing2D.DashStyle]::Dash }
        $pens += $pn
        $dots += (New-Object System.Drawing.SolidBrush($dc))
        $hollow += (New-Object System.Drawing.Pen($dc, 1.6))
    }
    try {
        if ($maxX -gt 0 -and $maxX -lt $ymax) {
            $yh = & $fy $maxX
            $g.FillRectangle($hatch, [float]$L, [float]$Tp, [float]$pw, [float]($yh - $Tp))
        }
        # Zones de desaccord entre A et B : bande verticale de Lo - 0,5 a Hi + 0,5 cylindre
        if ($cmp -and $zones.Count) {
            $zb = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(56, $script:Theme.Warn))
            try {
                foreach ($z in $zones) {
                    $xa = & $fx ([math]::Max(0.0, [double]$z.Lo - 0.5)); $xb = & $fx ([math]::Min([double]$maxC, [double]$z.Hi + 0.5))
                    $g.FillRectangle($zb, [float]$xa, [float]$Tp, [float]([math]::Max(2.0, $xb - $xa)), [float]$ph)
                }
            } finally { $zb.Dispose() }
        }
        for ($v = 0; $v -le $ymax; $v += $step) {
            $y = & $fy $v
            $g.DrawLine($grid, $L, $y, $L + $pw, $y)
            $s = "$v"; $sz = $g.MeasureString($s, $font)
            $g.DrawString($s, $font, $txt, $L - 6 - $sz.Width, $y - $sz.Height / 2)
        }
        $ticks = @(0..$maxC | Where-Object { $_ % 10 -eq 0 }); if ($ticks -notcontains $maxC) { $ticks += $maxC }
        foreach ($c in $ticks) {
            $x = & $fx $c
            $g.DrawLine($grid, $x, $Tp, $x, $Tp + $ph)
            $s = "$c"; $sz = $g.MeasureString($s, $font)
            $g.DrawString($s, $font, $txt, $x - $sz.Width / 2, $Tp + $ph + 4)
        }
        $g.DrawLine($axis, $L, $Tp + $ph, $L + $pw, $Tp + $ph); $g.DrawLine($axis, $L, $Tp, $L, $Tp + $ph)
        $g.DrawString('ns', $font, $txt, 8, $Tp - 16)
        $s = (T 'cylindre'); $sz = $g.MeasureString($s, $font); $g.DrawString($s, $font, $txt, $L + $pw - $sz.Width, $Tp + $ph + 20)
        # Changements de sens du besoin (courbe monotone par segments) : trait vertical pointille
        $dash = New-Object System.Drawing.Pen($script:Theme.Muted, 1)
        $dash.DashStyle = [System.Drawing.Drawing2D.DashStyle]::Dash
        try { foreach ($cv in $cvs) { foreach ($bc in @($cv.Breaks)) { if ($null -ne $bc -and [int]$bc -le $maxC) { $xb = & $fx ([int]$bc); $g.DrawLine($dash, $xb, $Tp, $xb, $Tp + $ph) } } } } finally { $dash.Dispose() }
        # 12.9 (correction 4) : dents locales du besoin (DentLo : dernier cylindre avant la baisse) : trait vertical pointille
        $dot = New-Object System.Drawing.Pen($script:Theme.Muted, 1)
        $dot.DashStyle = [System.Drawing.Drawing2D.DashStyle]::Dot
        try { foreach ($cv in $cvs) { foreach ($dc in @(@($cv.DentLo) | Where-Object { $null -ne $_ })) { if ([int]$dc -le $maxC) { $xb = & $fx ([int]$dc); $g.DrawLine($dot, $xb, $Tp, $xb, $Tp + $ph) } } } } finally { $dot.Dispose() }
        for ($k = 0; $k -lt $cvs.Count; $k++) {
            $cv = $cvs[$k]; $vals = @($cv.Values)
            $pts = New-Object 'System.Drawing.PointF[]' $vals.Count
            for ($c = 0; $c -lt $vals.Count; $c++) { $pts[$c] = New-Object System.Drawing.PointF([float](& $fx $c), [float](& $fy $vals[$c])) }
            if ($pts.Count -ge 2) { $g.DrawLines($pens[$k], $pts) }
            for ($i = 0; $i -lt @($cv.Cyls).Count; $i++) {
                $x = & $fx $cv.Cyls[$i]; $yv = [double]$cv.Ys[$i]; $sg = [double]$cv.Sig[$i]
                $y1 = & $fy ([math]::Min($ymax, $yv + $sg)); $y2 = & $fy ([math]::Max(0, $yv - $sg))
                $g.DrawLine($err, $x, $y1, $x, $y2); $g.DrawLine($err, $x - 3, $y1, $x + 3, $y1); $g.DrawLine($err, $x - 3, $y2, $x + 3, $y2)
                $y = & $fy $yv
                $kind = if ($cv.Kinds -and $i -lt @($cv.Kinds).Count) { [string]$cv.Kinds[$i] } else { 'interp' }
                switch ($kind) {
                    'outlier' { $g.DrawLine($hollow[$k], $x - 4, $y - 4, $x + 4, $y + 4); $g.DrawLine($hollow[$k], $x - 4, $y + 4, $x + 4, $y - 4) }
                    'extrap' { $g.FillEllipse([System.Drawing.Brushes]::White, $x - 3.5, $y - 3.5, 7, 7); $g.DrawEllipse($hollow[$k], $x - 3.5, $y - 3.5, 7, 7) }
                    'cap'    { $g.FillRectangle([System.Drawing.Brushes]::White, $x - 3.5, $y - 3.5, 7, 7); $g.DrawRectangle($hollow[$k], $x - 3.5, $y - 3.5, 7, 7) }
                    default  { $g.FillEllipse($dots[$k], $x - 3.5, $y - 3.5, 7, 7) }
                }
                if (Test-CurvePointFlag $cv $i) { $g.DrawEllipse($flag, $x - 7, $y - 7, 14, 14) }
            }
            if ($trends.ContainsKey($k)) {
                # 12.10 (lot 1, A1-tendance) : tendance lissee par-dessus la courbe et les mesures (donnees denses : un point
                # par cylindre la cacherait), couleur de la courbe assombrie pour rester visible sur son trait
                $tvs = @($trends[$k].Trend); $pc = $pens[$k].Color
                $tpn = New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb([int]($pc.R * 0.6), [int]($pc.G * 0.6), [int]($pc.B * 0.6)), 1.4)
                $tpn.DashStyle = [System.Drawing.Drawing2D.DashStyle]::Dot
                try {
                    $tps = New-Object 'System.Drawing.PointF[]' $tvs.Count
                    for ($c = 0; $c -lt $tvs.Count; $c++) { $tps[$c] = New-Object System.Drawing.PointF([float](& $fx $c), [float](& $fy $tvs[$c])) }
                    if ($tps.Count -ge 2) { $g.DrawLines($tpn, $tps) }
                } finally { $tpn.Dispose() }
            }
            # Courbe decalee de la derniere disquette (tirets) et mesures du niveau (losanges)
            foreach ($rec in $lvls[$k]) {
                $col = if ($null -ne $rec.Head -and -not $multi) { $colors[[math]::Min([int]$rec.Head, 1)] } else { $colors[[math]::Min($k, 1)] }
                $dp = New-Object System.Drawing.Pen($col, 1.6); $dp.DashStyle = [System.Drawing.Drawing2D.DashStyle]::Dash
                $mp = New-Object System.Drawing.Pen($col, 1.4)
                try {
                    $rv = @($rec.Values)
                    $lp = New-Object 'System.Drawing.PointF[]' $rv.Count
                    for ($c = 0; $c -lt $rv.Count; $c++) { $lp[$c] = New-Object System.Drawing.PointF([float](& $fx $c), [float](& $fy $rv[$c])) }
                    if ($lp.Count -ge 2) { $g.DrawLines($dp, $lp) }
                    for ($i = 0; $i -lt @($rec.Cyls).Count; $i++) {
                        $x = & $fx ([int]$rec.Cyls[$i]); $zv = [double]$rec.Zs[$i]; $sz2 = [double]$rec.Sigs[$i]; $y = & $fy $zv
                        if ($sz2 -gt 0) { $y1 = & $fy ([math]::Min($ymax, $zv + $sz2)); $y2 = & $fy ([math]::Max(0, $zv - $sz2)); $g.DrawLine($err, $x, $y1, $x, $y2) }
                        $kd = [string]$rec.Kinds[$i]
                        if ($kd -eq 'outlier') { $g.DrawLine($mp, $x - 4, $y - 4, $x + 4, $y + 4); $g.DrawLine($mp, $x - 4, $y + 4, $x + 4, $y - 4) }
                        elseif ($kd -eq 'cap') { $g.DrawRectangle($mp, $x - 3.5, $y - 3.5, 7, 7) }
                        else {
                            $dm = @((New-Object System.Drawing.PointF([float]$x, [float]($y - 5))), (New-Object System.Drawing.PointF([float]($x + 5), [float]$y)), (New-Object System.Drawing.PointF([float]$x, [float]($y + 5))), (New-Object System.Drawing.PointF([float]($x - 5), [float]$y)))
                            $g.FillPolygon([System.Drawing.Brushes]::White, [System.Drawing.PointF[]]$dm); $g.DrawPolygon($mp, [System.Drawing.PointF[]]$dm)
                        }
                    }
                } finally { $dp.Dispose(); $mp.Dispose() }
            }
        }
        # Titre (non convergence en rouge) et legende sur deux lignes
        $cv0 = $cvs[0]; $v0 = @($cv0.Values)
        if ($cmp) {
            $cA = @($cvs | Where-Object { [string]$_.Series -eq 'A' }); $cB = @($cvs | Where-Object { [string]$_.Series -eq 'B' })
            $title = ((T "{0} : lecteur {1}, calibrations A ({2}) et B ({3})") -f "$($cv0.Family)", "$($cv0.Drive)", "$(if ($cA.Count) { $cA[0].Date })", "$(if ($cB.Count) { $cB[0].Date })")
        }
        elseif ($multi) { $title = ((T "{0} : lecteur {1}, {2}, une courbe par tête") -f "$($cv0.Family)", "$($cv0.Drive)", "$($cv0.Date)") }
        else { $title = ((T "{0} : lecteur {1}, {2}, courbe {3}, de {4} à {5} ns") -f "$($cv0.Family)", "$($cv0.Drive)", "$($cv0.Date)", (Get-CurveModelName $cv0.Model), "$($v0[0])", "$($v0[-1])") }
        $title += ', ' + ((T "calcul {0}") -f (Get-CurveCalcText $cv0))     # version du calcul de calibration de la courbe
        $g.DrawString($title, $fontB, $txt, $L, 8)
        $tx = $L + 12 + $g.MeasureString($title, $fontB).Width
        if ($cmp) {
            # Non convergence de chaque calibration, nommee
            foreach ($sr in @(@('A', $cA), @('B', $cB))) {
                if (@($sr[1] | Where-Object { $_.Converged -eq $false }).Count -eq 0) { continue }
                $s = if ($sr[0] -eq 'A') { (T 'A NON CONVERGÉE') } else { (T 'B NON CONVERGÉE') }
                $g.DrawString($s, $fontB, $red, $tx, 8); $tx += 12 + $g.MeasureString($s, $fontB).Width
            }
        }
        elseif (@($cvs | Where-Object { $_.Converged -eq $false }).Count -gt 0) {
            $g.DrawString((T 'NON CONVERGÉE'), $fontB, $red, $tx, 8); $tx += 12 + $g.MeasureString((T 'NON CONVERGÉE'), $fontB).Width
        }
        if (@(@($lvls.Values) | ForEach-Object { $_ } | Where-Object { $_.Verdict -eq 'mismatch' -or $_.Shape -eq 'mismatch' }).Count -gt 0) { $g.DrawString((T 'FORME NON CONFORME'), $fontB, $red, $tx, 8) }
        $ly = 30; $x2 = $L
        $g.FillEllipse($gray, $x2, $ly + 3, 7, 7); $s = (T 'mesure encadrée'); $g.DrawString($s, $font, $txt, $x2 + 11, $ly); $x2 += 24 + $g.MeasureString($s, $font).Width
        $g.DrawEllipse($grayPen, $x2, $ly + 3, 7, 7); $s = (T 'extrapolée'); $g.DrawString($s, $font, $txt, $x2 + 11, $ly); $x2 += 24 + $g.MeasureString($s, $font).Width
        $g.DrawRectangle($grayPen, $x2, $ly + 3, 7, 7); $s = (T 'plafonnée'); $g.DrawString($s, $font, $txt, $x2 + 11, $ly); $x2 += 24 + $g.MeasureString($s, $font).Width
        if (@($cvs | Where-Object { @($_.Kinds) -contains 'outlier' }).Count -gt 0) { $g.DrawLine($grayPen, $x2, $ly + 3, $x2 + 7, $ly + 10); $g.DrawLine($grayPen, $x2, $ly + 10, $x2 + 7, $ly + 3); $s = (T 'isolée'); $g.DrawString($s, $font, $txt, $x2 + 11, $ly); $x2 += 24 + $g.MeasureString($s, $font).Width }
        if (@($cvs | Where-Object { @($_.Breaks).Count -gt 0 }).Count -gt 0) { $dl = New-Object System.Drawing.Pen($script:Theme.Muted, 1); $dl.DashStyle = [System.Drawing.Drawing2D.DashStyle]::Dash; $g.DrawLine($dl, $x2 + 3, $ly + 1, $x2 + 3, $ly + 12); $dl.Dispose(); $s = (T 'changement de sens'); $g.DrawString($s, $font, $txt, $x2 + 11, $ly); $x2 += 24 + $g.MeasureString($s, $font).Width }
        # 12.9 (correction 4) : dent locale du besoin (trait pointille), distincte d un changement de sens (tirets)
        if (@($cvs | Where-Object { @(@($_.DentLo) | Where-Object { $null -ne $_ }).Count -gt 0 }).Count -gt 0) { $dl = New-Object System.Drawing.Pen($script:Theme.Muted, 1); $dl.DashStyle = [System.Drawing.Drawing2D.DashStyle]::Dot; $g.DrawLine($dl, $x2 + 3, $ly + 1, $x2 + 3, $ly + 12); $dl.Dispose(); $s = (T 'baisse locale du besoin'); $g.DrawString($s, $font, $txt, $x2 + 11, $ly); $x2 += 24 + $g.MeasureString($s, $font).Width }
        $g.DrawEllipse($flag, $x2 - 1, $ly + 1, 11, 11); $s = (T 'écart > {0} ns et > 3 incertitudes') -f (Format-UiNum (Get-CurveDevNs $cvs[0])); $g.DrawString($s, $font, $txt, $x2 + 13, $ly); $x2 += 26 + $g.MeasureString($s, $font).Width
        # 12.10 (lot 1, A1-tendance) : tendance lissee avant « au-dela des mesures » ; ligne trop longue (largeur de la
        # fenetre) : en fin de deuxieme ligne, apres les courbes
        $trLeg = ''; $trL1 = $false
        if ($trends.Count -gt 0) {
            $trLeg = (T 'tendance lissée (affichage seul)')
            $trL1 = (-not $trRow) -and ($x2 + 33 + $g.MeasureString($trLeg, $font).Width + 20 + $g.MeasureString((T 'au-delà des mesures'), $font).Width -le $W - $R)
            if ($trL1) {
                $dl = New-Object System.Drawing.Pen($script:Theme.Muted, 1.4); $dl.DashStyle = [System.Drawing.Drawing2D.DashStyle]::Dot
                try { $g.DrawLine($dl, $x2, $ly + 7, $x2 + 16, $ly + 7) } finally { $dl.Dispose() }
                $g.DrawString($trLeg, $font, $txt, $x2 + 20, $ly); $x2 += 33 + $g.MeasureString($trLeg, $font).Width
            }
        }
        $g.FillRectangle($hatch, $x2, $ly + 2, 16, 10); $g.DrawRectangle($grid, $x2, $ly + 2, 16, 10); $g.DrawString((T 'au-delà des mesures'), $font, $txt, $x2 + 20, $ly)
        $ly = 50; $x2 = $L
        if ($cmp) {
            # Une ligne par tete (courbe commune : une seule), A puis B ; puis les zones de desaccord
            $hk = @(@($cvs | ForEach-Object { if ($null -ne $_.Head) { "$([int]$_.Head)" } else { 'c' } }) | Sort-Object -Unique)
            foreach ($hh in $hk) {
                $x2 = $L
                foreach ($sr in 'A', 'B') {
                    for ($k = 0; $k -lt $cvs.Count; $k++) {
                        $cv = $cvs[$k]
                        if ([string]$cv.Series -ne $sr -or $(if ($null -ne $cv.Head) { "$([int]$cv.Head)" } else { 'c' }) -ne $hh) { continue }
                        $vals = @($cv.Values)
                        $lab = if ($null -eq $cv.Head) { $sr } else { (T "{0}, tête {1}") -f "$sr", "$($cv.Head)" }
                        $g.DrawLine($pens[$k], $x2, $ly + 7, $x2 + 22, $ly + 7)
                        $s = (T "{0} : courbe {1}, de {2} à {3} ns") -f "$lab", (Get-CurveModelName $cv.Model), "$($vals[0])", "$($vals[-1])"
                        $g.DrawString($s, $font, $txt, $x2 + 28, $ly)
                        $x2 += 28 + $g.MeasureString($s, $font).Width + 24
                    }
                }
                $ly += 20
            }
            if ($zones.Count) {
                $zb = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(56, $script:Theme.Warn))
                try { $g.FillRectangle($zb, $L, $ly + 2, 16, 10) } finally { $zb.Dispose() }
                $g.DrawString((T 'désaccord entre A et B'), $font, $txt, $L + 20, $ly)
            }
        }
        else {
            for ($k = 0; $k -lt $cvs.Count; $k++) {
                $cv = $cvs[$k]; $vals = @($cv.Values)
                $g.DrawLine($pens[$k], $x2, $ly + 7, $x2 + 22, $ly + 7)
                $s = if ($multi) { ((T "tête {0} : courbe {1}, de {2} à {3} ns") -f "$($cv.Head)", (Get-CurveModelName $cv.Model), "$($vals[0])", "$($vals[-1])") } else { (T 'précompensation retenue par cylindre') }
                $g.DrawString($s, $font, $txt, $x2 + 28, $ly)
                $x2 += 28 + $g.MeasureString($s, $font).Width + 24
            }
            if ($trLeg -and -not $trL1) {
                if ($trRow) { $ly += 20; $x2 = $L }
                $dl = New-Object System.Drawing.Pen($script:Theme.Muted, 1.4); $dl.DashStyle = [System.Drawing.Drawing2D.DashStyle]::Dot
                try { $g.DrawLine($dl, $x2, $ly + 7, $x2 + 22, $ly + 7) } finally { $dl.Dispose() }
                $g.DrawString($trLeg, $font, $txt, $x2 + 28, $ly)
            }
        }
        if ($hasLevel) {
            # Troisieme ligne : courbe decalee, mesure du niveau, niveau par enregistrement
            $ly = $(if ($trRow) { 90 } else { 70 }); $x2 = $L
            $dl = New-Object System.Drawing.Pen($script:Theme.Muted, 1.6); $dl.DashStyle = [System.Drawing.Drawing2D.DashStyle]::Dash
            $g.DrawLine($dl, $x2, $ly + 7, $x2 + 22, $ly + 7); $dl.Dispose()
            # 12.8 (S3) : courbe d une mesure complete de cette disquette (enregistrements 'mesure' seulement)
            $allMes = (@(@($lvls.Values) | ForEach-Object { $_ } | Where-Object { [string]$_.Model -ne 'mesure' }).Count -eq 0)
            $s = if ($allMes) { (T 'courbe mesurée (dernière disquette)') } else { (T 'courbe décalée (dernière disquette)') }; $g.DrawString($s, $font, $txt, $x2 + 28, $ly); $x2 += 28 + $g.MeasureString($s, $font).Width + 16
            $dm = @((New-Object System.Drawing.PointF([float]($x2 + 4), [float]($ly + 2))), (New-Object System.Drawing.PointF([float]($x2 + 9), [float]($ly + 7))), (New-Object System.Drawing.PointF([float]($x2 + 4), [float]($ly + 12))), (New-Object System.Drawing.PointF([float]($x2 - 1), [float]($ly + 7))))
            $g.DrawPolygon($grayPen, [System.Drawing.PointF[]]$dm)
            $s = (T 'mesure du niveau'); $g.DrawString($s, $font, $txt, $x2 + 13, $ly); $x2 += 13 + $g.MeasureString($s, $font).Width + 24
            # 12.8 (L6-TEXTES) : verdict 'adapte' (calibration rapide adaptative), meme libelle que Format-CurveTable
            $vn = @{ ok = (T 'conforme'); approx = (T 'approximative'); mismatch = (T 'NON CONFORME'); sat = (T 'non vérifiée, plafond atteint'); low = (T 'non vérifiée, plancher atteint'); few = (T 'non vérifiée, trop peu de cylindres mesurés'); adapte = (T 'adaptée à cette disquette'); mesure = (T 'mesurée sur cette disquette') }
            $ri = 0
            # 12.8 (L6-POLISH) : lignes dans l ordre des courbes (tete 0, puis tete 1), comme les lignes des courbes ; les
            # valeurs d une table de hachage ne suivent pas l ordre de ses cles (la tete 1 venait avant la tete 0)
            foreach ($rec in @(@($lvls.Keys) | Sort-Object | ForEach-Object { $lvls[$_] })) {
                if ($ri -gt 0) { $ly += 20; $x2 = $L }; $ri++
                $vk = if ([string]$rec.Shape -eq 'mismatch') { 'mismatch' } else { [string]$rec.Verdict }
                $vt = if ($vn.ContainsKey($vk)) { $vn[$vk] } else { $vk }
                $s = if ([string]$rec.Model -eq 'mesure') { (T "tête {0} : courbe mesurée sur cette disquette, écart moyen {1} ns ({2})") -f "$($rec.Head)", ('{0:+0;-0;0}' -f [int]$rec.Delta), "$($rec.Date)" }
                     elseif ($null -eq $rec.Head) { (T "niveau de la dernière disquette : {0} ns ± {1}, forme {2} ({3})") -f ('{0:+0;-0;0}' -f [int]$rec.Delta), (Format-LevelNum $rec.SE), "$vt", "$($rec.Date)" }
                     else { (T "tête {0} : niveau {1} ns ± {2}, forme {3} ({4})") -f "$($rec.Head)", ('{0:+0;-0;0}' -f [int]$rec.Delta), (Format-LevelNum $rec.SE), "$vt", "$($rec.Date)" }
                $g.DrawString($s, $font, $txt, $x2, $ly); $x2 += $g.MeasureString($s, $font).Width + 20
            }
        }
    } finally {
        foreach ($o in @($font, $fontB, $grid, $axis, $err, $flag, $txt, $red, $gray, $grayPen, $hatch) + $pens + $dots + $hollow) { $o.Dispose() }
    }
}

function Show-PrecompCurve([string]$family, [bool]$preferHeads, $Owner = $null) {
    # Owner : fenetre proprietaire (carte Calibration de l Accueil : sa fenetre modale ; sinon la fenetre principale)
    # 12.10 : courbes de la famille du lecteur courant (vue), fenetre commune Show-CurvesWindow
    $cvs = Get-FamilyCurves $family $preferHeads
    Show-CurvesWindow $cvs $Owner
}

function Show-CurvesWindow($cvs, $Owner = $null) {
    # 12.10 : fenetre Courbe des courbes donnees (Get-FamilyCurves : courbes du lecteur courant ; Get-DriveFamilyCurves :
    # courbes croisees « source>cible » a la fin d une calibration croisee, 270) ; rien sans courbe. Titre complete par
    # les deux lecteurs d une courbe croisee (champ Target)
    $cvs = @($cvs | Where-Object { $_ })
    if ($cvs.Count -eq 0) { return }
    if ($script:CurveForm -and -not $script:CurveForm.IsDisposed) { $script:CurveForm.Close() }
    $script:CurveData = $cvs
    Set-CurveLevelData $cvs
    # 12.8 (lot 5, A4 P6) : Name frmCurve (banc : minuteur de securite de make-test), police de la fenetre principale,
    # bouton Fermer en bas a droite (Echap). Fenetre non modale et redimensionnable, comme en 12.7 ; hauteur augmentee de
    # celle de la rangee du bouton (courbe de meme taille)
    $f = New-Object System.Windows.Forms.Form
    $f.Name = 'frmCurve'
    $f.Text = if ($cvs.Count -gt 1) { ((T "Courbe de précompensation - {0}, une courbe par tête") -f "$($cvs[0].Family)") } else { ((T "Courbe de précompensation - {0}") -f "$($cvs[0].Family)") }
    if ($cvs[0].Target) { $f.Text += ((T " (croisée : écriture par le lecteur {0}, relecture par le lecteur {1})") -f "$($cvs[0].Drive)", "$($cvs[0].Target)") }   # 12.10
    $f.Size = New-Object System.Drawing.Size(920, 610); $f.MinimumSize = New-Object System.Drawing.Size(520, 410)
    # 12.8 (FIX5) : hauteur ramenee a celle de la zone de travail (1366 x 768 a 125 % : environ 566 px) ; la courbe (Fill)
    # se reduit, la rangee du bouton Fermer reste visible
    $wa = [System.Windows.Forms.Screen]::FromControl($form).WorkingArea
    if ($f.Height -gt $wa.Height) { $f.Height = $wa.Height }
    $f.StartPosition = 'CenterParent'; $f.Icon = $form.Icon; $f.Font = $form.Font; $f.BackColor = [System.Drawing.Color]::White
    $tb = New-Object System.Windows.Forms.TextBox
    $tb.Multiline = $true; $tb.ReadOnly = $true; $tb.ScrollBars = 'Vertical'; $tb.Dock = 'Bottom'; $tb.Height = 170
    $tb.TabStop = $false; $tb.HideSelection = $true          # pas de texte tout selectionne a l ouverture
    $tb.Font = New-Object System.Drawing.Font('Consolas', 9.75); $tb.BackColor = $script:Theme.Page
    # 12.10 (lot 1, A1-tendance) : tableau et courbe nommes (case « Tendance lissee »), tendance selon le reglage curveTrend
    $tb.Name = 'txtCurveTable'
    $tb.Text = Format-CurveTable $cvs ([bool](Get-Setting 'curveTrend'))
    $pb = New-Object System.Windows.Forms.PictureBox
    $pb.Name = 'picCurve'; $pb.Dock = 'Fill'; $pb.BackColor = [System.Drawing.Color]::White
    $pb.Add_Paint({ Draw-PrecompCurve $_.Graphics $this.ClientSize ([bool](Get-Setting 'curveTrend')) })
    $pb.Add_Resize({ $this.Invalidate() })
    $pnlBtn = New-Object System.Windows.Forms.Panel
    $pnlBtn.Dock = 'Bottom'; $pnlBtn.Height = 50; $pnlBtn.BackColor = [System.Drawing.Color]::White
    $btnClose = New-Object System.Windows.Forms.Button
    $btnClose.Name = 'btnCurveClose'; $btnClose.Text = (T 'Fermer'); $btnClose.Size = New-Object System.Drawing.Size(110, 34)
    $btnClose.Location = New-Object System.Drawing.Point(($pnlBtn.ClientSize.Width - 122), 8); $btnClose.Anchor = 'Top,Right'
    Set-Btn $btnClose '' 'normal'
    $btnClose.Add_Click({ $this.FindForm().Close() })     # fenetre non modale : DialogResult ne la fermerait pas
    $pnlBtn.Controls.Add($btnClose)
    # 12.10 (lot 1, A1-tendance, D1) : case « Tendance lissee » a gauche de la rangee du bouton : etat lu dans le reglage
    # curveTrend a l ouverture (avant le gestionnaire), ecrit par Set-Setting au clic, puis courbe et tableau refaits.
    # Info-bulle propre a la fenetre, liberee avec elle (Tag)
    $chkTrend = New-Object System.Windows.Forms.CheckBox
    $chkTrend.Name = 'chkCurveTrend'; $chkTrend.Text = (T 'Tendance lissée'); $chkTrend.AutoSize = $true
    $chkTrend.Location = New-Object System.Drawing.Point(12, 14); $chkTrend.Checked = [bool](Get-Setting 'curveTrend')
    $chkTrend.Add_CheckedChanged({
        Set-Setting 'curveTrend' $this.Checked
        $fc = $this.FindForm(); if (-not $fc) { return }
        $fc.Controls['txtCurveTable'].Text = Format-CurveTable $script:CurveData $this.Checked
        $fc.Controls['picCurve'].Invalidate()
    })
    $ctip = New-Object System.Windows.Forms.ToolTip
    $ctip.AutoPopDelay = 30000; $ctip.InitialDelay = 400; $ctip.ReshowDelay = 100
    $ctip.SetToolTip($chkTrend, (T "Courbe lissée sur ±4 cylindres, marches et changements de sens gardés. Affichage seul : l'écriture utilise toujours la courbe retenue."))
    $pnlBtn.Controls.Add($chkTrend)
    $f.Tag = $ctip
    $f.Add_FormClosed({ if ($this.Tag -is [System.Windows.Forms.ToolTip]) { $this.Tag.Dispose(); $this.Tag = $null } })
    $f.CancelButton = $btnClose
    # Ancrage dans l ordre inverse de la pile : rangee du bouton tout en bas, puis tableau, puis courbe (Fill)
    $f.Controls.Add($tb); $f.Controls.Add($pb); $f.Controls.Add($pnlBtn); $pb.BringToFront()
    $script:CurveForm = $f
    if ($null -eq $Owner) { $Owner = $form }
    $f.Show($Owner)
    $tb.Select(0, 0); $pb.Focus() | Out-Null
}

function Update-CurveButton([string]$path) {
    # Bouton « Courbe » : actif si une courbe calibree (commune ou par tete) existe pour la famille de l image courante
    # Avant l affichage de la fenetre : aucun acces au fichier (racine reseau possible) ; le gestionnaire Shown recalcule.
    # 12.8 (lot 2) : cadre « 2. Calibration du lecteur » de la restauration mis a jour en meme temps (memes courbes)
    Update-RsCalib
    if (-not $script:UiReady) { $path = '' }
    $fam = 'std'
    # 12.10 (relecture de la RC, fix2) : image flux ecrite telle quelle (Test-RawFluxWrite : sans format, gw n y applique pas
    # la precompensation) : bouton grise ; flux decode par un format : famille de l ecriture (Get-WriteImageFamily, celle de
    # Get-TargetWriteInfo : cellule mesuree d un SCP). Avant : bouton grise pour toute extension de flux, format choisi
    # compris, alors que l ecriture applique la courbe du lecteur ou la courbe croisee
    # 12.10 (relecture de la RC, r12) : image FM, GCR ou a codage propre (Test-NonMfmWrite) hors profil Manuel : --precomp
    # n est pas transmis non plus (Start-ImageWrite, 140) : bouton grise aussi (un flux decode par commodore.1541 ou
    # mac.800 ouvrait la courbe standard du lecteur, que l ecriture n applique pas)
    $wf = [string]$cmbWFmt.Text
    if ($path -and ((Test-RawFluxWrite $path $wf) -or ($cmbWProfile.SelectedIndex -ne 3 -and (Test-Path -LiteralPath $path) -and (Test-NonMfmWrite $path $wf)))) { $script:CurveFamily = 'std'; $btnWCurve.Enabled = $false; return }
    # 12.10 (relecture de la RC) : case « Precompensation (--precomp) » decochee : Start-ImageWrite ne transmet aucun
    # --precomp, profil Manuel compris : bouton grise ; avant : courbe propre du lecteur, lecteur cible choisi compris. Avec
    # une image seulement (sans image : courbe du lecteur pour la famille du profil force, sinon standard)
    if ($path -and -not $chkWPrecomp.Checked) { $script:CurveFamily = 'std'; $btnWCurve.Enabled = $false; return }
    # 12.10 (relecture de la RC) : famille de la decision d ecriture, comme Get-TargetWriteInfo (140) : profil force
    # « Standard 2 us » ou « Long track 1,89 us » : famille du profil (Set-PrecompFields, 220) ; Auto et Manuel : famille de
    # l image (Get-WriteImageFamily) ; Auto sur une image haute densite non calibrable : profil d origine de sa famille double
    # densite, aucune courbe calibree (Update-PrecompForImage, Start-ImageWrite) : bouton grise. Avant : famille de l image
    # dans tous les cas (profil Long track sur un ADF : courbe standard montree, courbe long track ecrite)
    $p = [int]$cmbWProfile.SelectedIndex
    if ($path -and (Test-Path -LiteralPath $path)) {
        $hdo = $false
        if ($p -eq 0) { try { $hdo = [bool]((Get-HighDensityReason $path $wf) -and -not (Get-HdCalibFamily $path $wf)) } catch { $hdo = $false } }
        if ($hdo) { $script:CurveFamily = 'std'; $btnWCurve.Enabled = $false; return }
        if ($p -ne 1 -and $p -ne 2) { try { $fam = Get-WriteImageFamily $path $wf } catch { $fam = 'std' } }
    }
    if ($p -eq 1) { $fam = 'std' } elseif ($p -eq 2) { $fam = 'long' }
    $script:CurveFamily = $fam
    # 12.10 (relecture de la RC) : courbes du bouton (Get-WCurveSet, celles du clic) : courbes croisees ecrites pour un
    # lecteur cible avec effet, sinon celles du lecteur ; avant : courbes du lecteur seulement, bouton grise sans elles
    $btnWCurve.Enabled = (Get-WCurveSet $path $fam).Count -gt 0
}

function Get-WCurveSet([string]$path, [string]$fam) {
    # 12.10 (relecture de la RC) : courbes du bouton « Courbe » de l onglet Ecriture (etat actif : Update-CurveButton ; clic :
    # Show-WCurve) : courbes croisees « source>cible » que l ecriture applique pour un lecteur cible avec effet
    # (Get-TargetWriteInfo, celles de Start-ImageWrite), sinon courbes du lecteur pour la famille de l image
    # (Get-FamilyCurves). Tableau protege par la virgule (pas de @() autour de l appel)
    # 12.10 (relecture de la RC) : $fam : famille de la decision d ecriture (Update-CurveButton : profil force, sinon image)
    $slow = [bool]$chkWSlow.Checked
    $tw = Get-TargetWriteInfo $path ([string]$cmbWFmt.Text) $slow
    # 12.10 (relecture de la RC, fix1) : ecriture pour le lecteur cible refusee (Block : aucune courbe croisee, haute
    # densite, courbes par tete seules en ecriture rapide) : aucune courbe, bouton grise ; avant : courbes propres du
    # lecteur, que l ecriture n applique pas
    if ($tw.Applies -and $tw.Block) { return ,@() }
    if ($tw.Applies -and @($tw.Curves).Count -gt 0) { return ,@($tw.Curves) }
    $c = Get-FamilyCurves $fam $slow
    return ,$c
}

function Show-WCurve {
    # 12.10 (relecture de la RC) : clic sur « Courbe » de l onglet Ecriture : courbes de Get-WCurveSet (fenetre commune
    # Show-CurvesWindow : titre « croisee » pour une courbe croisee) ; avant : Show-PrecompCurve, courbes du lecteur
    $p = if ($script:UiReady) { [string]$txtWFile.Text } else { '' }
    Show-CurvesWindow (Get-WCurveSet $p ([string]$script:CurveFamily))
}

function Get-CurveCalc($cv) {
    # Version du calcul de calibration d une courbe ; courbe anterieure a ce champ : version de l application qui l a
    # faite (le calcul changeait alors avec chaque version) ; '' si aucune (anterieure a 12.1)
    if (-not $cv) { return '' }
    if ($cv.Calc) { return [string]$cv.Calc }
    return [string]$cv.Version
}

function Test-CurveCalcBefore($cv, [string]$calc) {
    # 12.10 : courbe faite avec un calcul anterieur a $calc (« 12.9 », « 12.10 »), versions comparees par [version] (12.10
    # vient apres 12.9) ; courbe sans version (anterieure a 12.1) : anterieure ; version illisible : non
    $c = Get-CurveCalc $cv
    if (-not $c) { return $true }
    $v = $null; $r = $null
    if (-not [version]::TryParse($c, [ref]$v) -or -not [version]::TryParse($calc, [ref]$r)) { return $false }
    return ($v -lt $r)
}

function Get-CurveCalcRef($cv) {
    # 12.7 : version du calcul attendue pour une courbe : CalibCalcHd (famille haute densite), sinon CalibCalc
    if (Test-CurveHd $cv) { return $script:CalibCalcHd }
    return $script:CalibCalc
}

function Test-CurveCalcOk($cv) {
    # Courbe utilisable : faite avec le calcul actuel de sa famille, ou conservee par l utilisateur pour ce calcul
    if (-not $cv) { return $false }
    $ref = Get-CurveCalcRef $cv
    return ((Get-CurveCalc $cv) -eq $ref -or [string]$cv.KeptFor -eq $ref)
}

function Get-CurveCalcText($cv, [switch]$Plain) {
    # « v12.3 » ; courbe d un autre calcul conservee : « v12.2, conservé (calcul actuel v12.3) » (calcul de sa famille)
    $c = Get-CurveCalc $cv
    $ref = Get-CurveCalcRef $cv
    $ct = if ($c) { "v$c" } else { (T 'antérieur à 12.1') }
    if ($Plain -or $c -eq $ref) { return $ct }
    return ((T "{0}, conservé (calcul actuel v{1})") -f "$ct", "$ref")
}

function Get-CurveMaxNs($cv) {
    # Borne des valeurs d une courbe : enregistree depuis le calcul 12.4 (CalHardNs au moment du calcul, champ MaxNs) ;
    # 300 ns pour une courbe qui ne l a pas (toutes les courbes jusqu au calcul 12.3, valeurs bornees a 300)
    if ($cv -and $null -ne $cv.MaxNs -and [int]$cv.MaxNs -gt 0) { return [int]$cv.MaxNs }
    return 300
}

function Test-CurveAtMax($cv) {
    # Courbe qui atteint la borne de son calcul : valeur a la borne avec un residu de verification positif (encore
    # sous-compensee), ou mesure plafonnee au-dessus (type 'cap' haut)
    if (-not $cv -or $null -eq $cv.Cyls) { return $false }
    $mx = Get-CurveMaxNs $cv; $v = @($cv.Values); $cs = @($cv.Cyls)
    $ks = @(); if ($null -ne $cv.Kinds) { $ks = @($cv.Kinds) }
    $ys = @(); if ($null -ne $cv.Ys) { $ys = @($cv.Ys) }
    $rs = @(); if ($null -ne $cv.Res) { $rs = @($cv.Res) }
    for ($i = 0; $i -lt $cs.Count; $i++) {
        $c = [int]$cs[$i]
        if ($i -lt $ks.Count -and $i -lt $ys.Count -and [string]$ks[$i] -eq 'cap' -and [double]$ys[$i] -ge $mx - 0.5) { return $true }
        if ($c -lt $v.Count -and [int]$v[$c] -ge $mx -and $i -lt $rs.Count -and $null -ne $rs[$i]) {
            $r = [double]$rs[$i]
            if (-not [double]::IsNaN($r) -and $r -gt 0) { return $true }
        }
    }
    return $false
}

function ConvertTo-CurveConfig($cv) {
    if (-not $cv) { return $null }
    $o = [ordered]@{ family = $cv.Family; head = $cv.Head; drive = $cv.Drive; date = $cv.Date; model = $cv.Model; spec = $cv.Spec; method = $cv.Method
                       values = @($cv.Values); cyls = @($cv.Cyls); ys = @($cv.Ys); sig = @($cv.Sig)
                       kinds = @($cv.Kinds); res = @(@($cv.Res) | ForEach-Object { if ($null -eq $_ -or [double]::IsNaN([double]$_)) { $null } else { [double]$_ } })
                       converged = $(if ($null -eq $cv.Converged) { $null } else { [bool]$cv.Converged }); maxx = $cv.MaxX; version = $cv.Version
                       algo = $cv.Algo; calc = $cv.Calc; keptFor = $cv.KeptFor; breaks = @($cv.Breaks); slope = $cv.Slope; bits = $cv.Bits; test = $cv.Test
                       maxNs = $(if ($null -ne $cv.MaxNs) { [int]$cv.MaxNs } else { $null })
                       target = [string]$cv.Target }   # 12.10 : lecteur qui relit (courbe croisee), vide pour une courbe ordinaire
    # Zone non reproductible (calcul 12.6) : enregistree seulement si elle existe
    $ct = @(@($cv.Contra) | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_ })
    if ($ct.Count -gt 0) { $o.contra = $ct }
    # 12.9 (correction 4) : dents locales du besoin (calcul 12.9), tableaux plats, enregistres seulement s il y en a, comme
    # la zone non reproductible
    $dl = @(@($cv.DentLo) | Where-Object { $null -ne $_ })
    if ($dl.Count -gt 0) { $o.dentLo = @($cv.DentLo | ForEach-Object { [int]$_ }); $o.dentHi = @($cv.DentHi | ForEach-Object { [int]$_ }); $o.dentNs = @($cv.DentNs | ForEach-Object { [double]$_ }) }
    return $o
}

function ConvertTo-LevelConfig($r) {
    # Resultat d une calibration rapide (tableau plat dans la configuration, profondeur JSON limitee)
    if (-not $r) { return $null }
    return [ordered]@{ refKey = $r.RefKey; tag = $r.Tag; head = $r.Head; drive = $r.Drive; date = $r.Date; refDate = $r.RefDate; refTest = $r.RefTest
                       delta = $r.Delta; est = $r.Est; se = $r.SE; tau = $r.Tau; verdict = $r.Verdict; shape = $r.Shape; reasons = @($r.Reasons); conv = [bool]$r.Conv; passes = $r.Passes
                       cyls = @($r.Cyls); zs = @($r.Zs); ds = @($r.Ds); sigs = @($r.Sigs); kinds = @($r.Kinds); values = @($r.Values); spec = $r.Spec
                       sat = @($r.Sat); floor = @($r.Floor); hist = @(@($r.Hist) | ForEach-Object { [ordered]@{ date = $_.Date; delta = $_.Delta } })
                       version = $r.Version; algo = $r.Algo; levelAlgo = $r.LevelAlgo
                       # 12.8 (lot 1c, § 12.1) : forme adaptee (s, b, modele), mode, marque, cylindres de controle, pente
                       s = $(if ($null -ne $r.S) { [double]$r.S } else { 0.0 }); b = $(if ($null -ne $r.B) { [double]$r.B } else { 0.0 })
                       model = $(if ($r.Model) { [string]$r.Model } else { 'M0' }); mode = $(if ($r.Mode) { [string]$r.Mode } else { 'lvl1' })
                       brand = [string]$r.Brand; ctl = @(@($r.Ctl) | Where-Object { $null -ne $_ }); k = $r.K }
}

function ConvertTo-LevelBrandConfig($en) {
    # 12.8 (lot 1c, § 10.2) : entree de la memoire de marque (tableau plat dans la configuration, profondeur JSON limitee)
    # 12.8 (S3) : courbe complete d une tete mesuree par « Mesure complete de cette disquette » (curve, curveDate,
    # curveCalc, curveMaxNs, curveSrc), ecrite seulement quand elle existe : une entree (a, s, b) s ecrit comme avant
    if (-not $en) { return $null }
    $o = [ordered]@{ brand = [string]$en.Brand; drive = [string]$en.Drive; refKey = [string]$en.RefKey; tag = [string]$en.Tag; head = $en.Head
                     family = [string]$en.Family; refDate = [string]$en.RefDate; levelAlgo = 'lvl2'; model = [string]$en.Model
                     a = [double]$en.A; s = [double]$en.S; b = [double]$en.B; n = [int]$en.N; date = [string]$en.Date
                     levels = @(@($en.Levels) | Where-Object { $_ } | ForEach-Object { [ordered]@{ date = [string]$_.Date; delta = [int]$_.Delta } })
                     shapes = @(@($en.Shapes) | Where-Object { $_ } | ForEach-Object { [ordered]@{ date = [string]$_.Date; s = [double]$_.S; b = [double]$_.B } }) }
    if ($null -ne $en.Curve -and @($en.Curve).Count -ge 2) {
        $o.curve = @(@($en.Curve) | ForEach-Object { [int]$_ }); $o.curveDate = [string]$en.CurveDate; $o.curveCalc = [string]$en.CurveCalc
        $o.curveMaxNs = [int]$en.CurveMaxNs; $o.curveSrc = [string]$en.CurveSrc
    }
    return $o
}

function ConvertFrom-LevelBrandConfig($o) {
    # Entree illisible : $null (ignoree par Load-Config, une ligne de journal)
    if (-not $o) { return $null }
    try {
        $en = @{ Brand = ([string]$o.brand).Trim(); Drive = [string]$o.drive; RefKey = [string]$o.refKey; Tag = [string]$o.tag
                 Head = $(if ($null -ne $o.head) { [int]$o.head } else { $null }); Family = [string]$o.family; RefDate = [string]$o.refDate
                 LevelAlgo = [string]$o.levelAlgo; Model = $(if ($o.model) { [string]$o.model } else { 'M0' }); A = [double]$o.a; S = [double]$o.s; B = [double]$o.b
                 N = [int]$o.n; Date = [string]$o.date
                 Levels = @(@($o.levels) | Where-Object { $_ } | ForEach-Object { @{ Date = [string]$_.date; Delta = [int]$_.delta } })
                 Shapes = @(@($o.shapes) | Where-Object { $_ } | ForEach-Object { @{ Date = [string]$_.date; S = [double]$_.s; B = [double]$_.b } })
                 # 12.8 (S3) : courbe complete d une tete (absente d une entree a, s, b : $null)
                 Curve = $null; CurveDate = ''; CurveCalc = ''; CurveMaxNs = 0; CurveSrc = '' }
        if ($null -ne $o.curve -and @($o.curve).Count -ge 2) {
            $en.Curve = [int[]]@(@($o.curve) | ForEach-Object { [int]$_ }); $en.CurveDate = [string]$o.curveDate; $en.CurveCalc = [string]$o.curveCalc
            $en.CurveMaxNs = $(if ($null -ne $o.curveMaxNs) { [int]$o.curveMaxNs } else { 0 }); $en.CurveSrc = [string]$o.curveSrc
        }
        if (-not $en.Brand -or -not $en.RefKey -or -not $en.RefDate) { return $null }
        return $en
    } catch { return $null }
}

function ConvertFrom-LevelConfig($o) {
    if (-not $o) { return $null }
    try {
        $r = @{ RefKey = [string]$o.refKey; Tag = [string]$o.tag; Head = $(if ($null -ne $o.head) { [int]$o.head } else { $null }); Drive = [string]$o.drive
                Date = [string]$o.date; RefDate = [string]$o.refDate; RefTest = [string]$o.refTest; Delta = [int]$o.delta; Est = [double]$o.est; SE = [double]$o.se
                Tau = [double]$o.tau; Verdict = [string]$o.verdict; Shape = [string]$o.shape; Reasons = [string[]]@($o.reasons); Conv = [bool]$o.conv; Passes = [int]$o.passes
                Cyls = [int[]]@($o.cyls); Zs = [double[]]@($o.zs); Ds = [double[]]@($o.ds); Sigs = [double[]]@($o.sigs); Kinds = [string[]]@($o.kinds)
                Values = [int[]]@($o.values); Spec = [string]$o.spec; Sat = [int[]]@(@($o.sat) | Where-Object { $null -ne $_ }); Floor = [int[]]@(@($o.floor) | Where-Object { $null -ne $_ })
                Hist = @(@($o.hist) | Where-Object { $_ } | ForEach-Object { @{ Date = [string]$_.date; Delta = [int]$_.delta } })
                Version = [string]$o.version; Algo = [string]$o.algo; LevelAlgo = [string]$o.levelAlgo
                # 12.8 (lot 1c, § 12.1) : champs absents d un enregistrement lvl1 : s = b = 0, M0, lvl1, sans marque
                S = $(if ($null -ne $o.s) { [double]$o.s } else { 0.0 }); B = $(if ($null -ne $o.b) { [double]$o.b } else { 0.0 })
                Model = $(if ($o.model) { [string]$o.model } else { 'M0' }); Mode = $(if ($o.mode) { [string]$o.mode } else { 'lvl1' })
                Brand = [string]$o.brand; Ctl = [int[]]@(@($o.ctl) | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_ })
                K = $(if ($null -ne $o.k) { [double]$o.k } else { $null }) }
        if (-not $r.RefKey -or $r.Values.Count -lt 2 -or $r.Cyls.Count -ne $r.Zs.Count) { return $null }
        return $r
    } catch { return $null }
}

function ConvertFrom-CurveConfig($o) {
    if (-not $o) { return $null }
    try {
        $cv = @{ Family = [string]$o.family; Head = $(if ($null -ne $o.head) { [int]$o.head } else { $null }); Drive = [string]$o.drive; Date = [string]$o.date
                 Model = [string]$o.model; Spec = [string]$o.spec; Method = $(if ($o.method) { [string]$o.method } else { 'image' })
                 Values = [int[]]@($o.values); Cyls = [int[]]@($o.cyls); Ys = [double[]]@($o.ys); Sig = [double[]]@($o.sig)
                 Kinds = $null; Res = $null; Converged = $null; MaxX = 0; Version = [string]$o.version; Algo = [string]$o.algo
                 Calc = [string]$o.calc; KeptFor = [string]$o.keptFor; Target = [string]$o.target   # 12.10 : vide avant la 12.10
                 Breaks = [int[]]@(@($o.breaks) | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_ }) }
        if ($cv.Values.Count -lt 2 -or $cv.Cyls.Count -ne $cv.Ys.Count -or $cv.Cyls.Count -ne $cv.Sig.Count) { return $null }
        # Champs ajoutes en v11.9 : absents d une courbe plus ancienne
        if ($o.kinds -and @($o.kinds).Count -eq $cv.Cyls.Count) { $cv.Kinds = [string[]]@($o.kinds) }
        if ($o.res -and @($o.res).Count -eq $cv.Cyls.Count) { $cv.Res = [double[]]@(@($o.res) | ForEach-Object { if ($null -eq $_) { [double]::NaN } else { [double]$_ } }) }
        if ($null -ne $o.converged) { $cv.Converged = [bool]$o.converged }
        if ($o.maxx) { $cv.MaxX = [int]$o.maxx }
        # Champs de la calibration rapide (12.3) : absents d une courbe plus ancienne
        $cv.Slope = $(if ($null -ne $o.slope) { [double]$o.slope } else { $null })
        $cv.Bits = $(if ($o.bits) { [int]$o.bits } else { 0 })
        $cv.Test = [string]$o.test
        # Borne des valeurs (calcul 12.4) : absente d une courbe plus ancienne, qui vaut alors 300 (Get-CurveMaxNs)
        $cv.MaxNs = $(if ($null -ne $o.maxNs) { [int]$o.maxNs } else { $null })
        # Zone non reproductible, verifications contradictoires (calcul 12.6) : absente d une courbe plus ancienne
        $cv.Contra = [int[]]@(@($o.contra) | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_ })
        # Dents locales du besoin (calcul 12.9) : absentes d une courbe plus ancienne ; longueurs differentes : ignorees
        $cv.DentLo = [int[]]@(@($o.dentLo) | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_ })
        $cv.DentHi = [int[]]@(@($o.dentHi) | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_ })
        $cv.DentNs = [double[]]@(@($o.dentNs) | Where-Object { $null -ne $_ } | ForEach-Object { [double]$_ })
        if ($cv.DentLo.Count -ne $cv.DentHi.Count -or $cv.DentLo.Count -ne $cv.DentNs.Count) { $cv.DentLo = [int[]]@(); $cv.DentHi = [int[]]@(); $cv.DentNs = [double[]]@() }
        return $cv
    } catch { return $null }
}
# ============================== FONCTIONS : CALIBRATION : MESURE, DERIVE, REPRISE ===

function New-CalibUnit($head) {
    # Unite de calibration : les deux tetes ensemble (Head = $null, profil commun) ou une seule tete (ecriture lente).
    # 12.7 : Face (tete -> cylindre -> mesures des passes de mesure, sans effet sur la courbe) ; OneFace ('c|tete' : cylindre
    # de la courbe commune mesure sans cette face a une passe au moins)
    # 12.9 (correction 2) : Coarse (cylindre -> mesures brutes des passes de mesure par face, carre latin), CoarseZ (cylindre ->
    # mesures de l unite par passe, decalage de passe retire : Get-CalibDents), PassAlpha (face -> decalages estimes)
    # 12.9 : VOff (decalage commun de l ecriture de la derniere verification complete, Get-VerifyOffset : @{ V ; M ; E ; N ;
    # Removed }, pose par Invoke-CalibAnalysis ; $null tant qu aucune verification complete n a ete jugee)
    # 12.10 : VSlope (erreur de modele aux forts besoins de la derniere verification complete, Get-VerifySlope : @{ V ; B ;
    # SB ; A ; N ; Ok ; Why }) ; SlopeBad : cylindres de la tendance a corriger a cette verification (consomme par le jugement)
    $prefix = if ($null -eq $head) { '' } else { ((T '[tête {0}] ') -f "$head") }
    return @{ Head = $head; Prefix = $prefix; Results = @{}; Est = @{}; Sig = @{}; Kind = @{}; Bracket = @{}; Warn = $null; Fit = $null; Slope = $null; Profile = ''; Verify = @{}
              Dense = @{}; VerifyList = $null; VerifyP = @{}; Outliers = @(); Own = @{}; Trend = @{}; VerifyPrev = @{}; Witness = @(); ReadLast = @{}; Writes = @{}; WitCand = 0; WitMin = 0
              EstPass = @{}; Face = @{}; OneFace = @{}; DriftHold = $null; Coarse = @{}; CoarseZ = @{}; PassAlpha = @{}; VOff = $null; VSlope = $null; SlopeBad = $null }
}

function Get-PatternBits([string]$family, [string]$img) {
    # Cellules par piste du motif de test (voir New-CalibPattern) : densite de l image ; la calibration rapide compare
    # celle de l image a celle de sa reference. 12.11 : Known, cellules tirees de l image (codec AmigaDOS d un ADF, bits par piste d un IPF ou d un HFE) et non valeur par defaut de la famille : seule densite que le plafond par disquette retient sans format gw (Get-DiskCapBits, 265)
    # 12.11 : CapBits, cellules de la piste la plus longue de l image (IPF, HFE : MaxBits de Get-IpfCellInfo et de
    # Get-HfeCellInfo, 220 ; cellule la plus courte ecrite), au moins celles du motif : seule densite que lit le plafond par
    # disquette. Known faux pour un HFE dont la longueur des pistes n est pas lue (HFE v3, table inexploitable : densite
    # tiree du seul debit de l en-tete, MaxBits a 0). Bits, la densite du motif, ne change pas (mediane des pistes)
    $bits = 100000; $src = (T 'format à secteurs, 2 us par cellule'); $known = $false; $cap = [int64]0
    $ext = [System.IO.Path]::GetExtension($img).ToLower()
    try {
        switch ($ext) {
            '.adf' {
                $len = (Get-Item -LiteralPath $img).Length; $known = $true
                if ($len % 22528 -eq 0 -and $len / 11264 -gt 84) { $bits = 202688; $src = (T 'ADF haute densité, horloge AmigaDOS de gw') }
                else { $bits = 101344; $src = (T 'ADF, horloge AmigaDOS de gw') }
            }
            '.ipf' { $info = Get-IpfCellInfo $img; if ($info.Bits -ge 50000 -and $info.Bits -le 260000) { $bits = [int]$info.Bits; $src = (T 'IPF, bits par piste de l''image'); $known = $true; $cap = [int64]$info.MaxBits } }
            '.hfe' { $info = Get-HfeCellInfo $img; if ($info.Bits -ge 50000 -and $info.Bits -le 260000) { $bits = [int]$info.Bits; $src = (T 'HFE, bits par piste de l''image'); $cap = [int64]$info.MaxBits; $known = ($cap -gt 0) } }
        }
    } catch { }
    if ($family -eq 'long' -and $bits -eq 100000) { $bits = 105820; $src = (T 'long track, 1,89 us par cellule'); $known = $false; $cap = [int64]0 }
    elseif ($family -eq 'hd' -and $bits -eq 100000) { $bits = 200000; $src = (T 'format à secteurs haute densité, 1 us par cellule'); $known = $false; $cap = [int64]0 }   # 12.7
    $bits -= $bits % 16
    return @{ Bits = $bits; Source = $src; Known = $known; CapBits = [int][math]::Min([int64]2000000000, [math]::Max([int64]$bits, $cap)) }
}

function New-CalibPattern([string]$family, [string]$img, [int]$nCyl, [int]$Rpm = 300) {
    # Motif de test independant du contenu de l image : HFE de donnees pseudo-aleatoires codees MFM (graine fixe, contenu
    # reproductible) a la DENSITE de l image. gw cale chaque piste ecrite sur un tour du lecteur (write.py, facteur
    # drive_ticks_per_rev / ticks_to_index) : la densite ne depend que du nombre de cellules par piste.
    #  ADF : celui du codec AmigaDOS de gw, horloge 14/7 093 790 s, (int(0,2 / horloge) + 31) & ~31 = 101 344 cellules
    #        (1 973,5 ns) en DD, 202 688 en HD ;
    #  IPF et HFE : bits par piste de l image (mediane ; HFE v3 : 400 x debit) ;
    #  autres formats a secteurs (IMG, ST...) : 100 000 cellules de 2 us ; long track illisible : 1,89 us ; haute densite
    #  (12.7) : 200 000 cellules de 1 us.
    # Rpm : vitesse du type de disquette (300 tr/min pour toutes les familles calibrees en 12.7) : debit de l en-tete HFE,
    # bits x tr/min / 120 000 (regle generale), et cellule d un tour.
    # Une piste pauvre en motifs (secteurs vides) reduit la mesure du decalage de pic a quelques dizaines d occurrences
    # (en-tetes, syncs) : resultat plus bruite et biaise de quelques ns (jusqu a ~15 ns en simulation). Ici toutes les
    # pistes ont la meme richesse de motifs : calibration reproductible, independante de l image.
    $pb = Get-PatternBits $family $img
    $bits = $pb.Bits; $src = $pb.Source
    # Debit de l en-tete HFE (kbit/s) : un tour a Rpm tr/min ; 300 tr/min : expression d origine
    $rate = if ($Rpm -eq 300) { [int][math]::Round($bits / 400.0) } else { [int][math]::Round($bits * $Rpm / 120000.0) }
    $path = Join-Path $script:TempDir 'precomp-pattern.hfe'
    [CalibPattern]::WriteHfe($path, $nCyl, $bits, $rate, 20261014)
    $cell = if ($Rpm -eq 300) { 200000000.0 / $bits } else { (60000000000.0 / $Rpm) / $bits }
    return @{ Path = $path; Bits = $bits; Rate = $rate; CellNs = $cell; Source = $src; Rpm = $Rpm; Known = [bool]$pb.Known; CapBits = [int]$pb.CapBits }   # 12.11 : Known, densite tiree de l image, et CapBits, cellules de sa piste la plus longue (Get-PatternBits)
}

function Get-CalibDriveArgs {
    # Options de lecteur de l ecriture reprises par la calibration, sans --format ni --diskdefs : le motif est un HFE
    return @(Get-WriteFormatArgs | Where-Object { $_ -notmatch '^--(format|diskdefs)=' })
}

# --- Calibration croisee (12.10) ---------------------------------------------------
# La source (lecteur du bandeau, $cal.Drive) ecrit le motif, la cible le relit ; la disquette passe de l un a l autre a la
# main (Invoke-CalibSwap, 270). Courbe enregistree sous « source>cible|cle » (Get-CalibStoreDrive), champ Target = cible.

function Get-CalibDriveArgsFor([string]$verb) {
    # 12.10 : arguments de lecteur (--drive, --device) des commandes gw d une calibration. Calibration croisee
    # ($script:Cal.Cross = @{ Src ; Tgt }) : erase, write et prechauffage sur la source, le lecteur qui ecrit ; read sur
    # la cible, le lecteur qui relit ; port du bandeau. Sinon Get-CommonArgs (lecteur du bandeau), comme avant
    $cal = $script:Cal
    if (-not $cal -or -not $cal.Cross) { return @(Get-CommonArgs) }
    $d = if ($verb -eq 'read') { [string]$cal.Cross.Tgt } else { [string]$cal.Cross.Src }
    $a = @("--drive=$(Get-DriveConn $d)")   # 12.11 : Src et Tgt sont des identites (code ou nom) ; --drive recoit leur connexion (112)
    if ($txtDev.Text.Trim()) { $a += "--device=$($txtDev.Text.Trim())" }
    return $a
}

function Get-CalibStoreDrive($cal) {
    # 12.10 : lecteur de magasin des courbes d une calibration (Set-DriveCurve, Get-CalibSnapshot, Backup-ConfigBeforeRef) :
    # « source>cible » pour une calibration croisee, sinon le lecteur de la calibration
    if ($cal -and $cal.Cross) { return "$($cal.Cross.Src)>$($cal.Cross.Tgt)" }
    return [string]$cal.Drive
}

function Split-CrossDrive([string]$drive) {
    # 12.10 : lecteur de magasin « source>cible » d une courbe croisee -> @{ Src ; Tgt } ; $null pour un lecteur ordinaire
    if ($drive -match '^([^>|]+)>([^>|]+)$') { return @{ Src = [string]$Matches[1]; Tgt = [string]$Matches[2] } }
    return $null
}

function Get-CrossCalibTargets([string[]]$ids, [string]$src, [switch]$OtherConn) {
    # 12.10 : lecteurs cibles possibles d une calibration croisee : ceux de la liste du bandeau, sauf la source ; tableau
    # protege par la virgule (pas de @() autour de l appel)
    # 12.11 (lot LN-b) : -OtherConn, avec des lecteurs enregistres : sans les lecteurs de la connexion de la source
    # (Get-DriveConn, 112) : les deux lecteurs d une calibration croisee sont branches en meme temps, chacun sur sa
    # connexion. Sans le commutateur, ou registre vide : resultat de la 12.10
    if ($OtherConn -and $script:DriveReg.Count -gt 0) {
        $sc = Get-DriveConn $src
        return ,@(@($ids) | ForEach-Object { [string]$_ } | Where-Object { $_ -and $_ -ne $src -and (Get-DriveConn $_) -cne $sc })
    }
    return ,@(@($ids) | ForEach-Object { [string]$_ } | Where-Object { $_ -and $_ -ne $src })
}

function Get-CrossSwapEstimate([int]$nPassEst, [bool]$fine, [int]$maxRetest, [int]$maxVerify = 2) {
    # 12.10 : echanges de disquette d une calibration croisee (E) : deux par passe (vers la cible avant la relecture, retour
    # vers la source avant l ecriture suivante), sauf apres la derniere relecture ; au plus, avec l encadrement, les
    # mesures complementaires du test standard (2) et le nouvel essai
    # 12.11 : au moins : une premiere verification sans cylindre a corriger termine la calibration (Invoke-CalibAnalysis,
    # 270) ; les autres verifications prevues ($maxVerify - 1, comptees dans $nPassEst) n ont alors pas lieu : avec 3 passes
    # de mesure et 2 verifications, 4 relectures, donc 7 echanges et non 9. Le maximum ne change pas
    $n = [math]::Max(1, $nPassEst)
    $nMin = [math]::Max(1, $nPassEst - [math]::Max(0, $maxVerify - 1))
    $extra = 1 + $(if ($fine) { 0 } else { 2 }) + [math]::Max(0, $maxRetest)
    return @{ Min = (2 * $nMin - 1); Max = (2 * ($n + $extra) - 1) }
}

function Get-CrossTargetIndex([string[]]$targets, [string]$preselect) {
    # 12.11 : rang, dans la liste des lecteurs cibles de la fenetre de choix d une calibration croisee (Show-CrossCalibDialog,
    # 250), du lecteur a preselectionner : le lecteur cible de l onglet Ecriture (Get-TargetDrive, 140, transmis par
    # Start-CrossCalib). 0, le premier de la liste comme en 12.10, sans lecteur cible ou s il n est pas dans la liste.
    # Simple preselection : rien n est memorise ni lance tant que la fenetre n est pas validee
    if (-not $preselect -or $null -eq $targets) { return 0 }
    return [math]::Max(0, [array]::IndexOf($targets, $preselect))
}

function Get-CurveKeyLabel([string]$key) {
    # 'std' -> « Standard 2 us (commune) », 'long_h1' -> « Long track 1,89 us (tete 1) » ; 12.10 : une cle de magasin
    # (« lecteur|cle ») donne le libelle de sa cle de courbe, sans le lecteur (Get-DriveCurveLabel l ajoute)
    $k = (Split-DriveCurveKey $key).Key
    $fam = if ($k -like 'hd*') { 'hd' } elseif ($k -like 'long*') { 'long' } else { 'std' }
    $kind = if ($k -match '_h(\d)$') { (T "tête {0}") -f "$($Matches[1])" } else { (T 'commune') }
    return ("{0} ({1})" -f (Get-CalibFamilyName $fam), $kind)
}

# --- Courbes par lecteur (12.10) ----------------------------------------------------
# Magasin $script:DriveCurves (560) : « lecteur|cle » -> courbe ; $script:PrecompCurves : vue du lecteur courant (bandeau),
# que tout le code existant continue de lire. Toute ecriture d une courbe passe par Set-DriveCurve ; la vue est reconstruite
# par Sync-PrecompCurves au chargement (Load-Config), au changement de lecteur du bandeau (520) et a la remise a zero.

function Get-DriveCurveKey([string]$drive, [string]$key) {
    # Cle de magasin d une courbe : « lecteur|cle » (lecteur qui ecrit ; courbe croisee : « source>cible|cle »)
    return "$drive|$key"
}

function Split-DriveCurveKey([string]$storeKey) {
    # Cle de magasin -> @{ Drive ; Key } ; une cle de courbe seule (sans « | ») est celle du lecteur courant
    $i = $storeKey.LastIndexOf('|')
    if ($i -lt 0) { return @{ Drive = [string]$cmbDrive.Text; Key = $storeKey } }
    return @{ Drive = $storeKey.Substring(0, $i); Key = $storeKey.Substring($i + 1) }
}

function Get-DriveCurve([string]$drive, [string]$key) {
    # Courbe du magasin pour un lecteur et une cle de courbe ; $null sans courbe
    if ($null -eq $script:DriveCurves) { return $null }
    return $script:DriveCurves[(Get-DriveCurveKey $drive $key)]
}

function Set-DriveCurve([string]$drive, [string]$key, $cv) {
    # Seule ecriture d une courbe : magasin (entree retiree quand $cv est $null), puis vue du lecteur courant quand $drive
    # est celui du bandeau. Appelee a la fin d une calibration (270), a la conservation des courbes d un autre calcul
    # (Resolve-OldCalibrations), au retablissement (Restore-CalibState) et au chargement (Import-DriveCurves)
    if ($null -eq $script:DriveCurves) { $script:DriveCurves = @{} }
    $sk = Get-DriveCurveKey $drive $key
    if ($null -eq $cv) { $script:DriveCurves.Remove($sk) } else { $script:DriveCurves[$sk] = $cv }
    if ($drive -eq [string]$cmbDrive.Text) { $script:PrecompCurves[$key] = $cv }
}

function Sync-PrecompCurves([string]$drive = '') {
    # Vue du lecteur courant (ou de $drive) reconstruite pour les neuf cles : PrecompCurves[k] = DriveCurves["lecteur|k"],
    # sinon $null. Profils de famille standard et long track : Spec de la courbe commune de ce lecteur, sinon profil
    # d origine (un lecteur sans calibration ecrit avec le profil d origine, jamais avec la courbe d un autre lecteur ;
    # la haute densite tire deja son profil de sa courbe, Get-HdProfile)
    if (-not $drive) { $drive = [string]$cmbDrive.Text }
    foreach ($k in $script:CurveKeys) { $script:PrecompCurves[$k] = Get-DriveCurve $drive $k }
    $cs = $script:PrecompCurves['std']; $cl = $script:PrecompCurves['long']
    $script:PrecompStd = $(if ($cs -and $cs.Spec) { [string]$cs.Spec } else { $script:PrecompStdDefault })
    $script:PrecompLong = $(if ($cl -and $cl.Spec) { [string]$cl.Spec } else { $script:PrecompLongDefault })
}

function Get-DriveCurveKeys([string]$drive = '') {
    # Cles de magasin des courbes presentes, triees ; $drive : celles de ce lecteur seulement
    if ($null -eq $script:DriveCurves) { return @() }
    $ks = @($script:DriveCurves.Keys | Where-Object { $script:DriveCurves[$_] })
    if ($drive) { $ks = @($ks | Where-Object { (Split-DriveCurveKey $_).Drive -eq $drive }) }
    return @($ks | Sort-Object)
}

function Get-DriveCurveLabel([string]$storeKey) {
    # « Standard 2 us (commune), lecteur A » : libelle d une cle de magasin (listes de Load-Config, Resolve-OldCalibrations,
    # Reset-CalibProfiles) ; cle croisee « source>cible » (12.10) : « ..., ecriture par le lecteur A pour le lecteur 0 »
    $p = Split-DriveCurveKey $storeKey
    $x = Split-CrossDrive ([string]$p.Drive)
    if ($x) { return ((T "{0}, écriture par le lecteur {1} pour le lecteur {2}") -f (Get-CurveKeyLabel $p.Key), "$($x.Src)", "$($x.Tgt)") }
    return ((T "{0}, lecteur {1}") -f (Get-CurveKeyLabel $p.Key), "$($p.Drive)")
}

function Resolve-OldCalibrations {
    # Calibrations d un autre calcul (Load-Config) : conserver ou recalibrer. Fermeture de la fenetre : decision remise au
    # prochain demarrage, calibrations gardees dans la configuration mais non utilisees d ici la.
    $o = $script:OldCalib
    if (-not $o) { return }
    $items = @(@($o.Curves.Keys) | ForEach-Object { $cv = $o.Curves[$_]; (T "{0} : calcul {1}, lecteur {2}, {3}") -f (Get-CurveKeyLabel $_), (Get-CurveCalcText $cv -Plain), "$($cv.Drive)", "$($cv.Date)" })
    $txt = ((T "Ces calibrations ont été faites avec un autre calcul de calibration que le calcul actuel (v{0}) :") -f "$($script:CalibCalc)") + "`n" + ((@($items) | ForEach-Object { "  - $_" }) -join "`n") + "`n`n" +
           (T "Recalibrer (conseillé) : ces calibrations sont abandonnées et leurs profils reviennent aux valeurs d'origine. Recalibrez chaque lecteur concerné depuis la carte « Calibrer le lecteur » de l'Accueil, sur une disquette sacrifiée ; d'ici là, en « Test rapide », l'écriture d'une image calibrable est refusée.`nConserver ces courbes : elles restent utilisées telles quelles ; la fenêtre Courbe et le journal rappellent leur calcul. Le calcul ayant changé, une nouvelle calibration peut donner une courbe plus juste.")
    # 12.10 (relecture des captures) : phrase de la 12.3 (reference du test rapide) seulement pour une courbe d un calcul
    # anterieur a 12.3 (Test-CurveCalcBefore, 230) ; elle s affichait pour toute courbe, celles du calcul 12.9 comprises
    if (@(@($o.Curves.Keys) | Where-Object { Test-CurveCalcBefore $o.Curves[$_] '12.3' }).Count -gt 0) { $txt += ' ' + (T "Une courbe antérieure à la 12.3 ne peut pas servir de référence au test rapide (pente et densité non enregistrées).") }
    $txt += "`n" + (T "Fermer la fenêtre (ou Échap) : décision au prochain démarrage ; d'ici là, ces calibrations ne sont pas utilisées.")
    # 12.9 : courbes double densite d un calcul anterieur : ce que le calcul 12.9 change (conseil de recalibrer).
    # 12.10 (captures du wiki) : paragraphe reserve aux courbes d un calcul anterieur a 12.9 (il s affichait aussi pour
    # des courbes du calcul 12.9, celles de tout utilisateur de la 12.9) ; paragraphe du calcul 12.10 pour les courbes
    # d un calcul anterieur a 12.10 ; courbe d un calcul posterieur (configuration d une version plus recente) : aucun
    if (@(@($o.Curves.Keys) | Where-Object { -not (Test-CurveHd $o.Curves[$_]) -and (Test-CurveCalcBefore $o.Curves[$_] '12.9') }).Count -gt 0) { $txt += "`n`n" + (T "Depuis le calcul 12.9, la calibration double densité conditionne le lecteur par une écriture avant de mesurer, répartit ses niveaux de mesure sur les cylindres et suit une baisse locale du besoin propre au lecteur. Les courbes double densité d'un calcul antérieur pouvaient être trop hautes de quelques nanosecondes sur les premiers cylindres, et rester non convergées autour d'une telle baisse : recalibrer est conseillé.") }
    # 12.10 (relecture des captures) : paragraphe du calcul 12.10 juste aussi pour une courbe anterieure a 12.9 (mesuree a
    # 0, 100 et 200 ns) : niveaux 0, 30 et 100 ns attribues au calcul 12.9, extrapolations du long track au calcul 12.9
    if (@(@($o.Curves.Keys) | Where-Object { -not (Test-CurveHd $o.Curves[$_]) -and (Test-CurveCalcBefore $o.Curves[$_] '12.10') }).Count -gt 0) { $txt += "`n`n" + (T "Depuis le calcul 12.10, la vérification corrige l'erreur de modèle d'un lecteur à fort besoin au-delà du plus fort niveau mesuré, et les passes de mesure du long track écrivent 0, 60 et 200 ns (0, 30 et 100 ns avec le calcul 12.9). Une courbe long track du calcul 12.9 reposait surtout sur des extrapolations ; sur un lecteur à fort besoin, une courbe double densité d'un calcul antérieur pouvait rester trop haute d'environ 3 ns aux cylindres intérieurs : recalibrer est conseillé.") }
    # Courbe a la borne de son calcul : conservee, elle y reste (le calcul actuel admet des valeurs plus hautes)
    $atMax = @(@($o.Curves.Keys) | Where-Object { Test-CurveAtMax $o.Curves[$_] })
    foreach ($mx in @($atMax | ForEach-Object { Get-CurveMaxNs $o.Curves[$_] } | Where-Object { $_ -lt $script:CalHardNs } | Sort-Object -Unique)) {
        $kl = @($atMax | Where-Object { (Get-CurveMaxNs $o.Curves[$_]) -eq $mx } | ForEach-Object { Get-DriveCurveLabel $_ })   # 12.10 : cle de magasin, lecteur nomme
        $ct = if ($kl.Count -gt 1) { (T "Courbes au plafond de {0} ns de leur calcul : {1}. Conservées, elles y restent ; le calcul actuel va jusqu'à {2} ns.") } else { (T "Courbe au plafond de {0} ns de son calcul : {1}. Conservée, elle y reste ; le calcul actuel va jusqu'à {2} ns.") }
        $txt += "`n`n" + ($ct -f "$mx", ($kl -join ', '), "$($script:CalHardNs)")
    }
    if ($o.Bak -and (Test-Path -LiteralPath $o.Bak)) { $txt += "`n`n" + ((T "Copie de la configuration d'avant ce choix : {0}") -f "$([System.IO.Path]::GetFileName([string]$o.Bak))") }
    # 12.8 (lot 5, A4 R1 a R8, modele frmClean) : bandeau (texte lblOldText, Label de premier niveau), boutons a la largeur
    # de leur texte, « Fermer » (decision remise, comme la croix) en CancelButton et focus initial, aucun AcceptButton :
    # Entree n abandonne plus les courbes ; images liberees (Clear-DlgGdi) ; ajustement aux petits ecrans (Set-DlgFit)
    $W = 700
    $gdi = New-Object System.Collections.Generic.List[object]
    $dlg = New-Object System.Windows.Forms.Form
    $dlg.Name = 'frmOldCalib'; $dlg.Text = (T 'Calibrations d''un autre calcul'); $dlg.StartPosition = 'CenterParent'; $dlg.Icon = $form.Icon; $dlg.Font = $form.Font
    $dlg.FormBorderStyle = 'FixedDialog'; $dlg.MaximizeBox = $false; $dlg.MinimizeBox = $false; $dlg.ShowInTaskbar = $false; $dlg.BackColor = [System.Drawing.Color]::White
    $ban = New-DlgBanner $dlg 16 $W (T 'Recalibrer ou conserver ces courbes ?') $txt 'warn' (New-DlgPicto 'curve') $gdi 'lblOldText'
    $y = $ban.Bottom + 14
    $btnCl = New-Object System.Windows.Forms.Button
    $btnCl.Name = 'btnOldClose'; $btnCl.Text = (T 'Fermer'); $btnCl.Size = New-Object System.Drawing.Size(110, 34); $btnCl.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
    $btnRedo = New-Object System.Windows.Forms.Button
    $btnRedo.Name = 'btnOldRedo'; $btnRedo.Text = (T 'Recalibrer (conseillé)'); $btnRedo.Size = New-Object System.Drawing.Size((Get-DlgButtonWidth $btnRedo.Text 'Diagnostic' 170), 34)
    $btnRedo.DialogResult = [System.Windows.Forms.DialogResult]::Abort
    $btnKeep = New-Object System.Windows.Forms.Button
    $btnKeep.Name = 'btnOldKeep'; $btnKeep.Text = (T 'Conserver ces courbes'); $btnKeep.Size = New-Object System.Drawing.Size((Get-DlgButtonWidth $btnKeep.Text '' 150), 34)
    $btnKeep.DialogResult = [System.Windows.Forms.DialogResult]::OK
    Set-Btn $btnRedo 'Diagnostic' 'primary'; Set-Btn $btnKeep '' 'normal'; Set-Btn $btnCl '' 'normal'
    $btnCl.Location = New-Object System.Drawing.Point((16 + $W - $btnCl.Width), $y)
    $btnRedo.Location = New-Object System.Drawing.Point(($btnCl.Left - 8 - $btnRedo.Width), $y)
    $btnKeep.Location = New-Object System.Drawing.Point(($btnRedo.Left - 8 - $btnKeep.Width), $y)
    $dlg.ClientSize = New-Object System.Drawing.Size(($W + 32), ($y + 34 + 16))
    $dlg.Controls.AddRange(@($btnKeep, $btnRedo, $btnCl))
    $dlg.CancelButton = $btnCl; $dlg.ActiveControl = $btnCl   # Echap, croix et Fermer : decision remise ; Entree : Fermer
    [void](Set-DlgFit $dlg ([System.Windows.Forms.Screen]::FromControl($form).WorkingArea))
    $dlg.Add_Shown({ $this.Activate(); try { [System.Media.SystemSounds]::Exclamation.Play() } catch { } })
    try { $dr = $dlg.ShowDialog($form) } finally { Clear-DlgGdi $dlg $gdi }
    $list = (@($o.Curves.Keys | ForEach-Object { (T "{0}, calcul {1}") -f (Get-DriveCurveLabel $_), (Get-CurveCalcText $o.Curves[$_] -Plain) })) -join ' ; '   # 12.10 : lecteur nomme
    if ($dr -eq [System.Windows.Forms.DialogResult]::OK) {
        # Conservees pour le calcul actuel : reprises sans question aux demarrages suivants, calcul rappele a l usage
        # 12.10 : cles de magasin « lecteur|cle » : chaque courbe retourne sous son lecteur (vue du lecteur courant mise a jour)
        foreach ($k in @($o.Curves.Keys)) { $cv = $o.Curves[$k]; $cv.KeptFor = (Get-CurveCalcRef $cv); $p = Split-DriveCurveKey $k; Set-DriveCurve $p.Drive $p.Key $cv }
        if ($o.Std) { $script:PrecompStd = $o.Std }
        if ($o.Long) { $script:PrecompLong = $o.Long }
        foreach ($k in @($o.Levels.Keys)) { $script:LevelShifts[$k] = $o.Levels[$k] }
        $script:OldCalib = $null
        if ($cmbWProfile.Text -ne (T 'Manuel')) {
            # Champs enregistres (faits avec ces courbes), puis recalcules pour l image choisie le cas echeant
            if ($null -ne $o.P0) { $txtWPrecomp.Text = $o.P0; $txtWPrecomp1.Text = $o.P1 }
            if ($txtWFile.Text) { Update-PrecompForImage $txtWFile.Text }
        }
        Append-Log ((T "Calibrations d'un autre calcul conservées à votre demande : {0}. Elles sont utilisées telles quelles (calcul actuel v{1}).") -f "$list", "$($script:CalibCalc)")
    } elseif ($dr -eq [System.Windows.Forms.DialogResult]::Abort) {
        $script:OldCalib = $null
        Append-Log ((T "Calibrations d'un autre calcul abandonnées : {0}. Ces courbes sont retirées et leurs profils reviennent aux valeurs d'origine ; recalibrez chaque lecteur concerné depuis la carte « Calibrer le lecteur » de l'Accueil (en « Test rapide », l'écriture d'une image calibrable est refusée d'ici là).") -f "$list")
        # 12.10 : les courbes du calcul actuel (haute densite du calcul 12.7, courbes deja recalibrees) restent : les nommer
        $kept = @(Get-DriveCurveKeys)
        if ($kept.Count -gt 0) { Append-Log ((T "Calibrations du calcul actuel gardées : {0}.") -f ((@($kept | ForEach-Object { Get-DriveCurveLabel $_ })) -join ' ; ')) }
    } else {
        Append-Log (T 'Calibrations d''un autre calcul : décision remise au prochain démarrage ; elles ne sont pas utilisées d''ici là.')
        return
    }
    Update-CurveButton $txtWFile.Text
    [void](Save-Config)
}

function Get-CalibResetAfterText {
    # 12.10 (relecture de la RC, fix1) : suite de l effacement des calibrations (calibrations automatiques et refus qui
    # suivent : Start-PresetWrite, Start-WriteTabWrite, Start-LevelBeforeWrite, Start-RestoreWrite), texte commun au message
    # de Reset-CalibProfiles et a l infobulle du bouton (520) ; avant : infobulle a part, sans la restauration
    return (T "Ensuite, le mode Auto applique les profils d'origine :`n- « Test standard » ou « Test fin » : « Écriture rapide » et « Écriture lente » de la Bibliothèque calibrent d'abord le lecteur ; « ÉCRIRE LA DISQUETTE » écrit sans calibrer ;`n- « Test rapide » : l'écriture d'une image calibrable en double densité est refusée sans nouvelle calibration complète du lecteur, à faire sur une disquette sacrifiée depuis la carte « Calibrer le lecteur » de l'Accueil ;`n- restauration d'une copie secteur par secteur en double densité : chaque tête est d'abord calibrée en test fin.")
}

function Reset-CalibProfiles {
    # Efface toutes les calibrations : courbes communes et par tete de toutes les familles (haute densite comprise, 12.7) ;
    # profils de famille remis aux valeurs d origine. Refuse pendant une operation (calibration, ecriture, controle, sequence en cours) ;
    # 12.8 (D20) : Get-AppBusy, donc aussi pendant une detection des lecteurs, un prechauffage ou la mesure continue
    if (Get-AppBusy) {
        [void](Show-AppMessage (T 'Opération en cours : attendre la fin de la calibration ou de l''écriture.') (T 'Effacer les calibrations') 'OK' 'Warning'); return
    }
    # 12.10 : courbes de tous les lecteurs (magasin), cles « lecteur|cle »
    $curves = @(Get-DriveCurveKeys)
    # Calibrations d un autre calcul en attente du choix : effacees aussi
    $pend = @(if ($script:OldCalib) { @($script:OldCalib.Curves.Keys | Where-Object { -not $script:DriveCurves.ContainsKey($_) }) })
    $curves = @(@($curves) + $pend | Sort-Object -Unique)
    $changed = ($script:PrecompStd -ne $script:PrecompStdDefault) -or ($script:PrecompLong -ne $script:PrecompLongDefault)
    # 12.8.1 (spec-1281 § B.5, decision du 25/10/2026) : facteurs mesures des lecteurs (mesure de la disquette sur l image)
    # effaces avec les calibrations ; 12.10 : les courbes croisees sont effacees avec les autres, le lecteur cible choisi
    # ($script:TargetDrives) est garde
    $nCm = @(@($script:ContentMeasures) | Where-Object { $_ }).Count
    if ($curves.Count -eq 0 -and -not $changed -and $nCm -eq 0) {
        [void](Show-AppMessage (T 'Aucune calibration enregistrée : les profils sont déjà ceux d''origine.') (T 'Effacer les calibrations') 'OK' 'Information'); return
    }
    $list = if ($curves.Count -gt 0) { (@($curves | ForEach-Object { Get-DriveCurveLabel $_ }) -join ' ; ') } else { (T 'aucune') }   # 12.10 : lecteur nomme
    # 12.8 (L6-TEXTES) : texte aligne sur le comportement reel. Copie de la configuration (Backup-ConfigBeforeRef, seulement
    # s il y a une courbe) ; ensuite : Bibliotheque au test standard ou fin, calibration automatique (Start-PresetWrite) ;
    # bouton ECRIRE, jamais de calibration (Start-WriteTabWrite) ; test rapide, ecriture refusee sans reference
    # (Start-LevelBeforeWrite) ; restauration secteur en double densite, calibration par tete en test fin (Start-RestoreWrite)
    $msg = (T "Effacer toutes les calibrations de précompensation ?`n`nCourbes : {0}.`nProfils de famille remis aux valeurs d'origine : standard {1}, long track {2}.`nLes niveaux de la calibration rapide et la mémoire par marque sont effacés aussi.") -f "$list", "$($script:PrecompStdDefault)", "$($script:PrecompLongDefault)"
    # 12.11 (L7) : retour aux courbes de la copie par « Revenir a une calibration precedente… » (Start-CalibBack), sans
    # fermer l application ; la remise de la copie a la place du fichier reste le seul moyen de tout retrouver
    if ($curves.Count -gt 0) { $msg += "`n`n" + ((T "L'application copie d'abord la configuration dans « {0}.ref-….bak », dans le même dossier. Ensuite, « Revenir à une calibration précédente… » rétablit les courbes de cette copie, une calibration à la fois ; les niveaux, la mémoire par marque et les facteurs mesurés effacés ne reviennent qu'en remettant la copie à la place de « {0} », application fermée.") -f [System.IO.Path]::GetFileName([string]$script:ConfigFile)) }
    $msg += "`n`n" + (Get-CalibResetAfterText)
    # 12.10 (relecture de la RC) : lecteurs cibles gardes (Get-TargetDrive de chaque lecteur du bandeau) : leurs courbes
    # croisees sont effacees, les ecritures et restaurations pour eux refusees (Get-TargetWriteInfo, Get-RestoreTargetInfo) ;
    # avant : non dit, a cote des calibrations automatiques annoncees. 12.10 (relecture de la RC, fix1) : refus limites aux
    # ecritures precompensees hors profil Manuel et aux restaurations en copie secteur (cas sans effet de ces fonctions)
    $kept = @((Get-DriveIds) | ForEach-Object { $tk = Get-TargetDrive ([string]$_); if ($tk) { "$_ → $tk" } })
    if ($kept.Count -gt 0) { $msg += "`n" + ((T "- lecteur cible gardé ({0}) : les écritures précompensées pour ce lecteur cible (hors profil Manuel) et les restaurations en copie secteur pour lui sont refusées jusqu'à une nouvelle calibration croisée (« Calibrer pour un lecteur cible… »), ou choisissez « (même lecteur) » dans la liste « Lecteur cible ».") -f ($kept -join ', ')) }
    # 12.7 : courbe haute densite effacee : profil d origine haute densite, jamais de calibration automatique
    if (@($curves | Where-Object { (Split-DriveCurveKey "$_").Key -like 'hd*' }).Count -gt 0) { $msg += "`n" + ((T "Haute densité : profil d'origine {0}, sans calibration automatique ; recalibrez depuis la carte « Calibrer le lecteur » de l'Accueil.") -f "$($script:PrecompHdDefault)") }
    if ($nCm -gt 0) { $msg += "`n" + ((T "Les {0} facteur(s) mesuré(s) des lecteurs (mesure de la disquette sur l'image) sont effacés aussi : les écritures suivantes reprennent le facteur 1 jusqu'à une nouvelle mesure.") -f "$nCm") }
    # 12.7 : boite par Show-AppMessage (code modifie), comme les autres messages de la 12.7
    $r = Show-AppMessage $msg (T 'Effacer les calibrations') 'YesNo' 'Warning'
    if ($r -ne 'Yes') { return }
    # 12.8 (lot 1c, point 4) : copie du fichier de configuration avant l effacement des courbes (sans courbe : rien)
    [void](Backup-ConfigBeforeRef @($curves) 'reset')
    $script:DriveCurves = @{}; Sync-PrecompCurves          # 12.10 : magasin vide, vue du lecteur courant vide, profils d origine
    $script:LevelShifts = @{}; $script:OldCalib = $null
    # 12.8 (lot 1c, § 10.5) : memoires par marque effacees avec les calibrations (apres la copie ci-dessus)
    $script:LevelBrands = @()
    $script:ContentMeasures = @()                                     # 12.8.1 : facteurs mesures
    $script:PrecompStd = $script:PrecompStdDefault; $script:PrecompLong = $script:PrecompLongDefault
    if ($script:CurveForm -and -not $script:CurveForm.IsDisposed) { $script:CurveForm.Close() }
    Update-PrecompForImage $txtWFile.Text
    $pbWCal.Visible = $false; $lblWCal.Visible = $true; $lblWCal.Text = (T 'Calibrations effacées.')
    Append-Log ((T "Calibrations effacées : {0} courbe(s) ({1}) ; profils standard et long track remis aux valeurs d'origine ({2} ; {3}).") -f "$($curves.Count)", "$list", "$($script:PrecompStdDefault)", "$($script:PrecompLongDefault)")
    if ($nCm -gt 0) { Append-Log ((T "Facteurs mesurés des lecteurs effacés avec les calibrations ({0}).") -f "$nCm") }
    [void](Save-Config)
}

# --- Retour a une calibration precedente (12.11, lot L7) ----------------------------------------
# Copies de la configuration (Get-CalibBackFiles, Read-CalibBackup, 120) -> lignes (Get-CalibBackItems) -> decision unique
# d une ligne (Get-CalibBackInfo : lecteur d aujourd hui par Resolve-DriveOfEra, 112 ; colonne « Lecteur », detail, bouton)
# -> fenetre (Show-CalibBackDialog, 250) -> action (Restore-CalibBack). Seules les courbes de la ligne changent ; l etat
# actuel est d abord copie (Backup-ConfigBeforeRef, motif back), d ou un retour s annule de la meme facon.

function Get-CalibBackFamily([string]$key) {
    # 12.11 (L7) : famille d une cle de courbe : 'std_h0' -> 'std', 'long' -> 'long', 'hd_h1' -> 'hd'
    if ($key -like 'hd*') { return 'hd' }
    if ($key -like 'long*') { return 'long' }
    return 'std'
}

function Get-CalibBackHeadsText([string[]]$keys) {
    # 12.11 (L7) : colonne « Courbes » d une ligne : « commune », « par tete » (les deux tetes), « tete {0} » (une seule)
    $ks = @($keys | ForEach-Object { [string]$_ })
    $hs = @($ks | Where-Object { $_ -match '_h\d$' })
    $parts = @()
    if (@($ks | Where-Object { $_ -notmatch '_h\d$' }).Count -gt 0) { $parts += (T 'commune') }
    if (@($hs | Where-Object { $_ -like '*_h0' }).Count -gt 0 -and @($hs | Where-Object { $_ -like '*_h1' }).Count -gt 0) { $parts += (T 'par tête') }
    else { foreach ($k in $hs) { if ($k -match '_h(\d)$') { $parts += ((T 'tête {0}') -f "$($Matches[1])") } } }
    return ($parts -join ', ')
}

function Get-CalibBackTestText([string]$test) {
    # 12.11 (L7) : test d une courbe (champ Test, mode de sa calibration) ; '-' pour une courbe qui ne le dit pas
    if ($test -eq 'fine') { return (T 'test fin') }
    if ($test -eq 'std') { return (T 'test standard') }
    return '-'
}

function Test-CalibBackSameCurve($a, $b) {
    # 12.11 (L7) : meme courbe : meme date, meme calcul, memes valeurs
    if (-not $a -or -not $b) { return $false }
    return ([string]$a.Date -eq [string]$b.Date -and (Get-CurveCalc $a) -eq (Get-CurveCalc $b) -and (@($a.Values) -join ',') -eq (@($b.Values) -join ','))
}

function Get-CalibBackInfo($item) {
    # 12.11 (L7) : decision unique sur une ligne (Get-CalibBackItems), lue par la fenetre (colonne « Lecteur », detail,
    # bouton « Retablir cette calibration ») et par l action (Restore-CalibBack, Start-CalibBack). Lecteur d aujourd hui :
    # Resolve-DriveOfEra (112) pour le lecteur de la copie, et pour chaque cote d une cle croisee, avec le bloc drives de la
    # copie et la date de la courbe ; jamais un rang ni un compteur. Sans lecteur d aujourd hui pour un cote (lecteur
    # supprime depuis, ou lien ambigu) : ligne non retablissable. Lien incertain (connexion dont un lecteur enregistre a
    # recu les calibrations apres la courbe, nom d une fiche creee apres elle) : retablie seulement apres une confirmation
    # a case. Rend @{ Ok ; Drive (lecteur de magasin d aujourd hui) ; Sides (resultats de Resolve-DriveOfEra) ; Sure ;
    # NeedCheck ; CheckNow ; CheckEra (lecteurs nommes par la confirmation) ; Same (courbes identiques a celles en place :
    # ligne non listee) ; DriveText ; Labels ; Replace ; Add ; Pending (cles de magasin : courbe en place, sans courbe, en
    # attente du choix « garder ou recalibrer ») ; Backup (12.11, relecture : cles copiees avant le retour, Replace et
    # Pending ; vide : aucune copie, Restore-CalibBack) ; OtherCalc ; CalcText (12.11, relecture : colonne « Calcul » de la
    # fenetre) ; HeadsStale ; Text (detail) }
    $res = @{ Ok = $false; Drive = ''; Sides = @(); Sure = $false; NeedCheck = $false; CheckNow = ''; CheckEra = ''; Same = $false; DriveText = ''
              Labels = @(); Replace = @(); Add = @(); Pending = @(); Backup = @(); OtherCalc = $false; CalcText = ''; HeadsStale = $false; Text = '' }
    if (-not $item) { return $res }
    $names = @($item.CurveKeys | ForEach-Object { [string]$_ })
    if ($names.Count -eq 0) { return $res }
    $x = Split-CrossDrive ([string]$item.EraDrive)
    $sides = if ($x) { @([string]$x.Src, [string]$x.Tgt) } else { @([string]$item.EraDrive) }
    $rs = @()
    foreach ($d in $sides) { $rs += ,(Resolve-DriveOfEra $d $item.Era ([datetime]$item.When)) }
    $res.Sides = $rs
    $res.Ok = (@($rs | Where-Object { -not [string]$_.Drive }).Count -eq 0)
    $res.Sure = ($res.Ok -and @($rs | Where-Object { -not $_.Sure }).Count -eq 0)
    $res.NeedCheck = ($res.Ok -and -not $res.Sure)
    if ($res.Ok) { $res.Drive = $(if ($x) { '{0}>{1}' -f [string]$rs[0].Drive, [string]$rs[1].Drive } else { [string]$rs[0].Drive }) }
    # Colonne « Lecteur », phrases du lien, lecteurs nommes par la confirmation
    $txts = @(); $why = @(); $now = @(); $era = @()
    foreach ($r in $rs) {
        $e = [string]$r.Era; $d = [string]$r.Drive
        switch ([string]$r.Why) {
            'deleted' { $txts += ((T '{0} (lecteur supprimé depuis)') -f $e); $why += ((T "Le lecteur « {0} » de cette copie n'est plus enregistré : cette calibration ne peut pas être rétablie.") -f $e) }
            'ambiguous' { $txts += $e; $why += ((T "Le lecteur « {0} » de cette copie ne peut pas être relié avec certitude à un lecteur d'aujourd'hui.") -f $e) }
            'conn-named' { $txts += ((T "{0} (à l'époque : {1})") -f $d, $e); $why += ((T "Cette calibration a été faite sur la connexion {0}, avant que son lecteur soit enregistré sous le nom « {1} » : ne la rétablissez que si elle a été faite avec ce lecteur.") -f $e, $d) }
            'name-after' { $txts += $d; $why += ((T "Cette calibration porte le nom « {0} », mais le lecteur enregistré aujourd'hui sous ce nom l'a été après elle : ne la rétablissez que si elle a été faite avec ce lecteur.") -f $e) }
            default { if ($d -and $d -cne $e) { $txts += ((T "{0} (à l'époque : {1})") -f $d, $e) } elseif ($d) { $txts += $d } else { $txts += $e } }
        }
        if ($d -and -not $r.Sure) { $now += $d; $era += $e }
    }
    $res.DriveText = ($txts -join ' → ')
    $res.CheckNow = ($now -join ' → '); $res.CheckEra = ($era -join ' → ')
    # Courbes remplacees, ajoutees, en attente du choix ; courbes par tete plus anciennes que la commune en place
    $base = if ($res.Ok) { $res.Drive } else { [string]$item.EraDrive }
    $res.Labels = @($names | ForEach-Object { Get-DriveCurveLabel (Get-DriveCurveKey $base $_) })
    $cv0 = $item.Curves[$names[0]]
    $res.OtherCalc = -not [bool]$item.CalcOk
    $same = $res.Ok; $oneDate = ''
    if ($res.Ok) {
        foreach ($k in $names) {
            $sk = Get-DriveCurveKey $res.Drive $k
            $cur = Get-DriveCurve $res.Drive $k
            if ($cur) { $res.Replace += $sk; if (-not (Test-CalibBackSameCurve $cur $item.Curves[$k])) { $same = $false } }
            else { $res.Add += $sk; $same = $false }
            # Courbe de cette cle en attente du choix « garder ou recalibrer », en place ou non : retiree de l attente
            if ($script:OldCalib -and $script:OldCalib.Curves -and $script:OldCalib.Curves.Contains($sk)) { $res.Pending += $sk }
        }
        $res.Backup = @(@(@($res.Replace) + @($res.Pending)) | Sort-Object -Unique)
        $fam = [string]$item.Family
        if (@($names | Where-Object { $_ -match '_h\d$' }).Count -gt 0 -and $names -notcontains $fam) {
            $one = Get-DriveCurve $res.Drive $fam
            if ($one -and (Get-CurveDate $one) -gt [datetime]$item.When) { $res.HeadsStale = $true; $oneDate = [string]$one.Date }
        }
    }
    $res.Same = $same
    # Detail
    $t = @()
    # Calcul : texte de la colonne « Calcul » (courbe d un autre calcul deja conservee : « v12.9, conserve (calcul actuel
    # v12.10) ») ; courbe d un autre calcul non conservee : son calcul seul, la phrase qui suit dit ce qu il en sera
    $calcTxt = if ($item.CalcOk) { Get-CurveCalcText $cv0 } else { Get-CurveCalcText $cv0 -Plain }
    # 12.11 (relecture de L7) : colonne « Calcul » de la fenetre (New-CalibBackDialog, 250), decidee ici
    $res.CalcText = if ($item.CalcOk) { $calcTxt } else { (T '{0} (autre calcul)') -f $calcTxt }
    $t += ((T "À rétablir : {0} ; calibration du {1}, {2}, calcul {3}.") -f ($res.Labels -join ' ; '), [string]$item.Date, (Get-CalibBackTestText ([string]$item.Test)), $calcTxt)
    $t += $why
    if ($res.Ok) {
        # 12.11 (relecture de L7) : courbes en place remplacees, puis, a part, courbes en attente du choix (elles ne sont pas
        # en place) ; sans aucune des deux, pas de copie (Backup vide) ; une courbe ajoutee n est retiree par aucun retour
        $rp = @(@($res.Replace) | ForEach-Object { Get-DriveCurveLabel $_ })
        if ($rp.Count -gt 0) { $t += ((T 'Courbes en place remplacées : {0}.') -f ($rp -join ' ; ')) } else { $t += (T "Aucune courbe en place n'est remplacée.") }
        $pd = @(@($res.Pending) | ForEach-Object { Get-DriveCurveLabel $_ })
        if ($pd.Count -gt 0) { $t += ((T "Courbes en attente du choix « garder ou recalibrer » retirées de l'attente : {0}.") -f ($pd -join ' ; ')) }
        $addOnly = @(@($res.Add) | Where-Object { @($res.Pending) -notcontains $_ })
        if (@($res.Backup).Count -eq 0) { $t += (T "Aucune copie n'est faite avant ce retour : il ne s'annule pas par ce bouton, qui rétablit des courbes et n'en retire aucune.") }
        elseif ($addOnly.Count -gt 0) { $t += ((T 'Courbes ajoutées, sans courbe en place : {0}. Elles restent en place si vous annulez ce retour.') -f ((@($addOnly | ForEach-Object { Get-DriveCurveLabel $_ })) -join ' ; ')) }
        if ($res.OtherCalc) { $t += ((T "Calcul {0}, autre que le calcul actuel (v{1}) : ces courbes seront conservées telles quelles, comme avec « Conserver ces courbes » au démarrage ; une nouvelle calibration peut donner une courbe plus juste.") -f (Get-CurveCalcText $cv0 -Plain), (Get-CurveCalcRef $cv0)) }
        if ($res.HeadsStale) { $t += ((T "Ces courbes par tête sont plus anciennes que la courbe commune en place de ce lecteur ({0}) : l'écriture lente ne les appliquera pas tant que cette courbe commune est plus récente.") -f $oneDate) }
        $t += (T "Les niveaux de la calibration rapide mesurés avec les courbes remplacées ne s'appliqueront plus. Les autres courbes, les réglages, la mémoire par marque et les facteurs mesurés ne changent pas.")
    }
    $fw = [datetime]$item.FileWhen
    $t += ((T 'Copie lue : {0}, du {1}.') -f [string]$item.FileName, $fw.ToString('dd/MM/yyyy HH:mm', [System.Globalization.CultureInfo]::InvariantCulture))
    $res.Text = ($t -join "`n")
    return $res
}

function Get-CalibBackItems($backups) {
    # 12.11 (L7) : lignes de la fenetre « Revenir a une calibration precedente », d apres les copies lues (Read-CalibBackup,
    # 120) : une ligne par calibration complete, soit les courbes d une copie de meme lecteur de magasin (lecteur, ou
    # « source>cible »), de meme famille et de meme date (les deux courbes par tete d une calibration partagent leur date).
    # Ligne dont toutes les courbes sont identiques a celles en place sous le lecteur d aujourd hui (Get-CalibBackInfo :
    # date, calcul, valeurs) : non listee. Calibration presente dans plusieurs copies : une ligne, celle d une copie qui la
    # relie avec certitude a un lecteur d aujourd hui s il y en a, puis de la copie la plus recente. Tri : date de
    # calibration decroissante. Lignes rendues une a une : @{ EraDrive (lecteur de magasin dans la copie) ; Family ;
    # CurveKeys (cles de courbe) ; Curves (cle de courbe -> courbe) ; Date ; When ; Test ; Calc ; CalcOk ; Era (bloc drives
    # de la copie) ; File ; FileName ; FileWhen }. Une calibration plus recente que celle en place est listee aussi : c est
    # ainsi qu un retour s annule
    $groups = [ordered]@{}
    foreach ($b in @($backups)) {
        if (-not $b -or -not $b.Ok) { continue }
        foreach ($sk in @($b.Curves.Keys)) {
            $cv = $b.Curves[$sk]
            if (-not $cv) { continue }
            $p = Split-DriveCurveKey ([string]$sk)
            $fam = Get-CalibBackFamily ([string]$p.Key)
            $gk = "$($b.Path)`n$($p.Drive)`n$fam`n$([string]$cv.Date)"
            if (-not $groups.Contains($gk)) {
                $groups[$gk] = @{ EraDrive = [string]$p.Drive; Family = $fam; CurveKeys = @(); Curves = @{}; Date = [string]$cv.Date; When = (Get-CurveDate $cv); Test = [string]$cv.Test
                                  Calc = (Get-CurveCalc $cv); CalcOk = $true; Era = $b.Drives; File = [string]$b.Path; FileName = [string]$b.Name; FileWhen = $b.When }
            }
            $g = $groups[$gk]
            $g.CurveKeys = @($g.CurveKeys) + @([string]$p.Key)
            $g.Curves[[string]$p.Key] = $cv
            if (-not (Test-CurveCalcOk $cv)) { $g.CalcOk = $false }
        }
    }
    $best = [ordered]@{}
    foreach ($g in @($groups.Values)) {
        $g.CurveKeys = @($g.CurveKeys | Sort-Object)
        $inf = Get-CalibBackInfo $g
        if ($inf.Same) { continue }
        $sig = "{0}`n{1}`n{2}`n{3}" -f $(if ($inf.Ok) { [string]$inf.Drive } else { '?' + [string]$g.EraDrive }), $g.Family, $g.Date, ((@($g.CurveKeys | ForEach-Object { "$_=$(Get-CurveCalc $g.Curves[$_])=$(@($g.Curves[$_].Values) -join ',')" })) -join ';')
        if ($best.Contains($sig)) {
            $o = $best[$sig]
            if (($inf.Sure -and -not $o.Sure) -or ([bool]$inf.Sure -eq [bool]$o.Sure -and [datetime]$g.FileWhen -gt [datetime]$o.Item.FileWhen)) { $best[$sig] = @{ Item = $g; Sure = [bool]$inf.Sure } }
        } else { $best[$sig] = @{ Item = $g; Sure = [bool]$inf.Sure } }
    }
    $sorted = @(@($best.Values) | Sort-Object -Property @{ Expression = { [datetime]$_.Item.When }; Descending = $true }, @{ Expression = { [string]$_.Item.EraDrive } }, @{ Expression = { [string]$_.Item.Family } })
    foreach ($e in $sorted) { $e.Item }
}

function Restore-CalibBack($item, [switch]$Confirmed) {
    # 12.11 (L7) : retablit les courbes d une ligne (Get-CalibBackItems), et elles seules, sous le lecteur que designe
    # Get-CalibBackInfo (Resolve-DriveOfEra) ; leurs champs Drive et Target sont reecrits pour ce lecteur. Refus : ligne sans
    # lecteur d aujourd hui, ligne au lien incertain sans -Confirmed (confirmation a case de Start-CalibBack), operation en
    # cours, calibration B en attente. L etat actuel est d abord sauvegarde : Save-Config, puis copie des cles remplacees
    # (Backup-ConfigBeforeRef, motif back, la copie lue protegee de la rotation) ; l un ou l autre en echec alors qu une
    # courbe serait remplacee : retour annule, rien n est modifie. Ne changent pas : les autres courbes (autres lecteurs,
    # courbes croisees), les reglages, les niveaux, la memoire par marque, les facteurs mesures, les lecteurs cibles. Courbe
    # d un autre calcul : conservee pour le calcul actuel (KeptFor, comme « Conserver ces courbes » au demarrage). Courbes de
    # ces cles en attente du choix ($script:OldCalib) : retirees de l attente, et les niveaux de la calibration rapide mis de
    # cote avec elles repris dans $script:LevelShifts, comme « Conserver ces courbes » (Resolve-OldCalibrations ; Load-Config
    # ne garde au demarrage suivant que ceux d une courbe de meme date). Rend $true si le retour est fait
    $info = Get-CalibBackInfo $item
    if (-not $info.Ok -or $info.Same) { return $false }
    if ($info.NeedCheck -and -not $Confirmed) { return $false }
    if ((Get-AppBusy) -or $script:CalRedo) { return $false }
    $names = @($item.CurveKeys | ForEach-Object { [string]$_ })
    $repl = @($info.Backup)   # 12.11 (relecture) : cles a copier d abord, decidees par Get-CalibBackInfo (detail de la fenetre)
    $title = (T 'Revenir à une calibration précédente')
    # Sauvegarde d abord. Le temps de cet enregistrement, une erreur d ecriture arrete Save-Config (qui la note et rend faux)
    # au lieu d etre seulement affichee : sans cela, la copie qui suit serait celle d un fichier perime (comme
    # Protect-DriveData, 112)
    $saved = $false
    $eap = $ErrorActionPreference
    try { $ErrorActionPreference = 'Stop'; $saved = [bool](Save-Config) } catch { $saved = $false } finally { $ErrorActionPreference = $eap }
    if ($repl.Count -gt 0) {
        $bak = $null
        if ($saved) { $bak = Backup-ConfigBeforeRef $repl 'back' ([string]$item.File) }
        if (-not $saved -or -not $bak) {
            [void](Show-AppMessage (T "Retour annulé : l'état actuel n'a pas pu être sauvegardé (voir le journal). Rien n'est modifié.") $title 'OK' 'Warning')
            return $false
        }
    }
    # Courbes de la ligne, sous le lecteur d aujourd hui
    $x = Split-CrossDrive ([string]$info.Drive)
    $src = if ($x) { [string]$x.Src } else { [string]$info.Drive }
    $tgt = if ($x) { [string]$x.Tgt } else { '' }
    foreach ($k in $names) {
        $cv = $item.Curves[$k]
        $cv.Drive = $src; $cv.Target = $tgt
        if (-not (Test-CurveCalcOk $cv)) { $cv.KeptFor = (Get-CurveCalcRef $cv) }
        Set-DriveCurve ([string]$info.Drive) $k $cv
    }
    if ($script:OldCalib -and $script:OldCalib.Curves) {
        foreach ($sk in @($info.Pending)) {
            [void]$script:OldCalib.Curves.Remove($sk)
            # 12.11 (L7) : niveaux de la calibration rapide mis de cote avec cette courbe : repris comme avec « Conserver ces
            # courbes » (Resolve-OldCalibrations) ; ils ne s appliquent qu a une courbe de meme date (RefDate)
            if ($script:OldCalib.Levels) {
                foreach ($lk in @($script:OldCalib.Levels.Keys)) {
                    $lr = $script:OldCalib.Levels[$lk]
                    if ($lr -and (Get-DriveCurveKey ([string]$lr.Drive) ([string]$lr.RefKey)) -eq $sk) { $script:LevelShifts[$lk] = $lr; [void]$script:OldCalib.Levels.Remove($lk) }
                }
            }
        }
        if ($script:OldCalib.Curves.Count -eq 0) { $script:OldCalib = $null }
    }
    Sync-PrecompCurves
    if ($script:CurveForm -and -not $script:CurveForm.IsDisposed) { $script:CurveForm.Close() }
    Update-PrecompForImage $txtWFile.Text
    Update-CurveButton $txtWFile.Text
    $pbWCal.Visible = $false; $lblWCal.Visible = $true; $lblWCal.Text = (T 'Calibration précédente rétablie.')
    $rp = @($repl | ForEach-Object { Get-DriveCurveLabel $_ })
    $cv0 = $item.Curves[$names[0]]
    Append-Log ((T "Calibration précédente rétablie : {0} (calibration du {1}, calcul {2}), lue dans {3}. Courbes remplacées : {4}.") -f ($info.Labels -join ' ; '), [string]$item.Date, (Get-CurveCalcText $cv0), [string]$item.File, $(if ($rp.Count -gt 0) { $rp -join ' ; ' } else { (T 'aucune') }))
    [void](Save-Config)
    return $true
}

function Start-CalibBack {
    # 12.11 (L7) : bouton « Revenir a une calibration precedente… » (btnWCalBack, 520). Refus pendant une operation (message
    # de « Effacer les calibrations ») ou quand une calibration B attend sa decision ; lecture des copies (une ligne de
    # journal par copie illisible) ; aucune ligne : message ; fenetre de choix (Show-CalibBackDialog, 250) ; ligne au lien
    # incertain (Get-CalibBackInfo : NeedCheck) : confirmation a case qui nomme le lecteur d aujourd hui et celui de
    # l epoque ; puis Restore-CalibBack. Rend $true si le retour est fait
    $title = (T 'Revenir à une calibration précédente')
    if (Get-AppBusy) { [void](Show-AppMessage (T 'Opération en cours : attendre la fin de la calibration ou de l''écriture.') $title 'OK' 'Warning'); return $false }
    if ($script:CalRedo) { [void](Show-AppMessage (T "Calibration B en cours ou en attente de décision : terminez-la d'abord.") $title 'OK' 'Warning'); return $false }
    $files = @(Get-CalibBackFiles)
    # 12.11 (relecture de L7) : aucune copie : message propre, au lieu de « aucune des 0 copie(s) »
    if ($files.Count -eq 0) { [void](Show-AppMessage ((T 'Aucune calibration précédente à rétablir : le dossier « {0} » ne contient aucune copie de la configuration (« {1}.….bak »).') -f (Split-Path -Parent ([string]$script:ConfigFile)), [System.IO.Path]::GetFileName([string]$script:ConfigFile)) $title 'OK' 'Information'); return $false }
    $reads = @(); $skipped = @()
    foreach ($f in $files) {
        $b = Read-CalibBackup $f
        if (-not $b.Ok) { Append-Log ((T 'Copie de la configuration illisible, ignorée : {0} ({1}).') -f "$f", "$($b.Why)"); $skipped += [string]$b.Name; continue }
        if (@($b.Curves.Keys).Count -eq 0) { $skipped += [string]$b.Name; continue }
        $reads += ,$b
    }
    $items = @(Get-CalibBackItems $reads)
    if ($items.Count -eq 0) {
        [void](Show-AppMessage ((T "Aucune calibration précédente à rétablir : aucune des {0} copie(s) de la configuration lue(s) dans « {1} » ne contient de courbe différente des courbes en place.") -f "$($files.Count)", (Split-Path -Parent ([string]$script:ConfigFile))) $title 'OK' 'Information')
        return $false
    }
    $pick = Show-CalibBackDialog $items $files.Count $skipped
    if (-not $pick) { return $false }
    $info = Get-CalibBackInfo $pick
    if (-not $info.Ok) { return $false }
    if ($info.NeedCheck) {
        $ok = Show-AppConfirm -Title $title -Heading ((T 'Rétablir cette calibration pour le lecteur « {0} » ?') -f $info.CheckNow) -Text $info.Text -Check ((T "Cette calibration a bien été faite avec le lecteur « {0} » (à l'époque : {1})") -f $info.CheckNow, $info.CheckEra) -GoText (T 'Rétablir cette calibration') -GoGlyph 'History' -Level 'warn' -Picto 'warn'
        if (-not $ok) { return $false }
    }
    return [bool](Restore-CalibBack $pick -Confirmed:([bool]$info.NeedCheck))
}

function Get-CalibTrackMeasure($st) {
    # Decalage de pic d une piste (moyenne des tours mesurables) et son erreur-type (ns) ; $null si aucun tour mesurable.
    # Erreur-type : celle d Analyze (dispersion dans les quatre contextes) combinee sur les tours, a defaut la
    # dispersion entre tours.
    $vals = @(); $ses = @()
    foreach ($x in @($st)) {
        if ($null -eq $x -or $null -eq $x.Shift -or [double]::IsNaN([double]$x.Shift)) { continue }
        $vals += [double]$x.Shift
        $se = $x.ShiftSE
        if ($null -ne $se -and -not [double]::IsNaN([double]$se) -and [double]$se -gt 0) { $ses += [double]$se }
    }
    if ($vals.Count -eq 0) { return $null }
    $m = ($vals | Measure-Object -Average).Average
    $se = [double]::NaN
    if ($ses.Count -eq $vals.Count) { $q = 0.0; foreach ($s in $ses) { $q += $s * $s }; $se = [math]::Sqrt($q) / $vals.Count }
    elseif ($vals.Count -ge 2) { $q = 0.0; foreach ($v in $vals) { $q += ($v - $m) * ($v - $m) }; $se = [math]::Sqrt($q / ($vals.Count - 1)) / [math]::Sqrt($vals.Count) }
    return @{ Shift = $m; SE = $se }
}

function Add-CalibPoint($points, [int]$x, $m) {
    # Mesure (Shift, SE, Score) a la precomp x pour un cylindre ; deux mesures a la meme valeur sont moyennees
    if ($points.ContainsKey($x)) {
        $o = $points[$x]
        $se = if (-not [double]::IsNaN([double]$o.SE) -and -not [double]::IsNaN([double]$m.SE)) { [math]::Sqrt($o.SE * $o.SE + $m.SE * $m.SE) / 2 } else { [double]::NaN }
        $points[$x] = @{ Shift = ($o.Shift + $m.Shift) / 2; SE = $se; Score = $m.Score }
    } else { $points[$x] = $m }
}

function Limit-CalibZero([double]$x0, [double]$sig, [string]$kind, [double]$a, [bool]$own) {
    # Zero borne a 0..CalHardNs (« plafonnee » au-dela). Au-dela du plafond des passes de mesure (CalMaxNs), il garde son
    # type (encadre ou extrapole) : la verification ecrit la courbe a cette valeur et la mesure.
    $k = $kind; $v = $x0
    if ($v -lt 0) { $v = 0.0; $k = 'cap' }
    if ($v -gt $script:CalHardNs) { $v = [double]$script:CalHardNs; $k = 'cap' }
    return @{ Est = $v; Sig = [math]::Min($script:CalSigMax, [math]::Max(1.0, $sig)); Kind = $k; Slope = $a; Own = $own }
}

function Get-CalibZero($points, [double]$pooledSlope) {
    # Precomp qui annule le decalage d un cylindre, d apres ses mesures (precomp -> Shift, SE) :
    #  - encadree : deux mesures de signes opposes -> interpolation lineaire entre elles (pente locale) ;
    #  - sinon extrapolee depuis les deux mesures les plus proches du zero (pente locale, ou pente commune si elle
    #    n est pas nettement negative) : la pente s aplatit au-dela de la plage mesuree, d ou une incertitude
    #    elargie de 25 % de la distance extrapolee ; si la mesure la plus proche est deja sur le zero (decalage dans
    #    2 erreurs-types), le zero est mesure et non extrapole : « encadree », sans l incertitude minimale de 5 ns ;
    #  - bornee a 0..CalHardNs : « plafonnee » (Limit-CalibZero).
    # Renvoie @{ Est; Sig; Kind = interp|extrap|cap; Slope; Own } ou $null (moins de deux mesures).
    $xs = @($points.Keys | ForEach-Object { [int]$_ } | Sort-Object)
    if ($xs.Count -lt 2) { return $null }
    $s = @($xs | ForEach-Object { [double]$points[$_].Shift })
    $e = @($xs | ForEach-Object { $v = $points[$_].SE; if ($null -eq $v -or [double]::IsNaN([double]$v) -or [double]$v -le 0) { 2.0 } else { [double]$v } })
    for ($i = 0; $i -lt $xs.Count - 1; $i++) {
        if ($s[$i] -gt 0 -and $s[$i + 1] -le 0) {
            $a = ($s[$i + 1] - $s[$i]) / ($xs[$i + 1] - $xs[$i])
            $x0 = $xs[$i] + $s[$i] / (-$a)
            $sig = [math]::Sqrt($e[$i] * $e[$i] + $e[$i + 1] * $e[$i + 1]) / [math]::Abs($a)
            return (Limit-CalibZero $x0 $sig 'interp' $a ($a -lt -0.2))
        }
    }
    $under = $s[-1] -gt 0
    $j = if ($under) { $xs.Count - 2 } else { 0 }
    $a = ($s[$j + 1] - $s[$j]) / ($xs[$j + 1] - $xs[$j])
    $own = $a -lt -0.2
    if (-not $own) { $a = $pooledSlope }
    $xr = if ($under) { $xs[-1] } else { $xs[0] }
    $sr = if ($under) { $s[-1] } else { $s[0] }
    $er = if ($under) { $e[-1] } else { $e[0] }
    $x0 = $xr + $sr / (-$a)
    $sig = [math]::Sqrt([math]::Pow($er / [math]::Abs($a), 2) + [math]::Pow(0.25 * [math]::Abs($x0 - $xr), 2))
    if ([math]::Abs($sr) -le 2.0 * $er) { return (Limit-CalibZero $x0 $sig 'interp' $a $own) }
    return (Limit-CalibZero $x0 ([math]::Max($script:CalExtrapSigMin, $sig)) 'extrap' $a $own)
}

function Get-BracketSpec($bracket) {
    # Profil --precomp d une passe d encadrement : une entree c=ns par cylindre a encadrer (seuls ceux-la sont ecrits)
    return ((@($bracket.Keys | ForEach-Object { [int]$_ } | Sort-Object) | ForEach-Object { "$_=$($bracket[$_])" }) -join ':')
}

function Get-CalibLatinW([int[]]$cyls, [int[]]$levels, [int]$pass) {
    # 12.9 (correction 2) : niveau ecrit a chaque cylindre de test a la passe de mesure $pass (0..n-1), carre latin : le
    # cylindre de rang i (cylindres de test tries) recoit levels[(i + pass) mod n] ; sur les n passes, chaque cylindre recoit
    # chaque niveau une fois, et deux cylindres de test voisins n ont jamais le meme niveau a une passe (regle de
    # Get-ContentLevel, 274, appliquee cylindre par cylindre). Meme niveau pour les deux tetes. Fonction pure. Renvoie
    # cylindre -> niveau (ns)
    $w = @{}
    $cs = [int[]]@($cyls | Sort-Object -Unique)
    $n = @($levels).Count
    if ($n -eq 0) { return $w }
    for ($i = 0; $i -lt $cs.Count; $i++) { $w[$cs[$i]] = [int]$levels[($i + $pass) % $n] }
    return $w
}

function Get-ProjOrth([double[]]$v, [double[]]$e1, [double[]]$e2) {
    # Projection de v sur l orthogonal de deux vecteurs orthonormes e1 et e2 : v - (v.e1) e1 - (v.e2) e2. Fonction pure
    $d1 = 0.0; $d2 = 0.0
    for ($i = 0; $i -lt $v.Count; $i++) { $d1 += $v[$i] * $e1[$i]; $d2 += $v[$i] * $e2[$i] }
    $w = New-Object double[] $v.Count
    for ($i = 0; $i -lt $v.Count; $i++) { $w[$i] = $v[$i] - $d1 * $e1[$i] - $d2 * $e2[$i] }
    return ,$w
}

function Get-CalibPassOffsets($obs, [int[]]$levels, [int]$nPass, [int]$minCyl = 6) {
    # 12.9 (correction 2 ; modele M2 de v129\cal2\donnees\sim.py, estimate_offsets) : decalage propre a chaque passe de
    # mesure d une face. Par cylindre c et passe p : y = a_c + b_c W + somme_j g_j 1[W = L_j] (j = 2..n-1, niveaux tries)
    # + alpha_p (alpha_0 = 0). Ordonnee et pente propres retirees par projection, cylindre par cylindre, sur l orthogonal de
    # (1, W) ; restent n - 2 effets de niveau et n - 1 decalages, moindres carres non ponderes (equations normales,
    # Solve-ContentLinear, 274). Un cylindre compte s il a n mesures a n niveaux distincts (passes uniformes : systeme
    # singulier). Decalages rendus centres (somme nulle) : leur moyenne, commune a toutes les mesures, ne s identifie pas.
    # Fonction pure. $obs : lignes @{ C ; P ; W ; Y } d une face (Y : decalage lu, ns). Renvoie @{ Ok ; Why ('passes',
    # 'cylindres', 'singulier', 'ddl') ; Alpha (double[n], centres) ; SE (double[n]) ; NCyl ; Df ; S (ecart-type residuel) }
    $n = [int]$nPass
    $out = @{ Ok = $false; Why = ''; Alpha = (New-Object double[] ([math]::Max(1, $n))); SE = (New-Object double[] ([math]::Max(1, $n))); NCyl = 0; Df = 0; S = [double]::NaN }
    $lv = [int[]]@(@($levels) | ForEach-Object { [int]$_ } | Sort-Object -Unique)
    $ng = [math]::Max(0, $lv.Count - 2)
    $q = $ng + $n - 1
    if ($n -lt 2 -or $q -le 0) { $out.Why = 'passes'; return $out }
    # Tableaux simples (et non List[object]) : @() sur une liste generique de hashtables echoue sous pwsh 7 (.NET 10)
    $byC = @{}
    foreach ($o in @($obs | Where-Object { $null -ne $_ })) {
        $c = [int]$o.C
        if (-not $byC.ContainsKey($c)) { $byC[$c] = @() }
        $byC[$c] += ,$o
    }
    $Gm = New-Object 'double[][]' $q
    for ($a = 0; $a -lt $q; $a++) { $Gm[$a] = New-Object double[] $q }
    $gv = New-Object double[] $q
    $kept = New-Object System.Collections.Generic.List[object]
    foreach ($c in @($byC.Keys | Sort-Object)) {
        $ob = @($byC[$c])
        $m = $ob.Count
        if ($m -ne $n) { continue }
        $wv = [double[]]@($ob | ForEach-Object { [double]$_.W })
        if (@($wv | Sort-Object -Unique).Count -ne $m) { continue }
        # Base orthonormee de (1, W)
        $e1 = New-Object double[] $m; $e2 = New-Object double[] $m
        $mw = 0.0; foreach ($x in $wv) { $mw += $x }; $mw /= $m
        $nn = 0.0
        for ($i = 0; $i -lt $m; $i++) { $e1[$i] = 1.0 / [math]::Sqrt($m); $e2[$i] = $wv[$i] - $mw; $nn += $e2[$i] * $e2[$i] }
        $nn = [math]::Sqrt($nn)
        for ($i = 0; $i -lt $m; $i++) { $e2[$i] = $e2[$i] / $nn }
        # Colonnes projetees : effets de niveau (indicatrices des niveaux 2..n-1), puis passes 1..n-1 (indicatrices)
        $Zc = New-Object 'double[][]' $q
        for ($j = 0; $j -lt $q; $j++) {
            $col = New-Object double[] $m
            for ($i = 0; $i -lt $m; $i++) {
                if ($j -lt $ng) { $col[$i] = [double]([int]$ob[$i].W -eq $lv[$j + 2]) }
                else { $col[$i] = [double]([int]$ob[$i].P -eq ($j - $ng + 1)) }
            }
            $Zc[$j] = Get-ProjOrth $col $e1 $e2
        }
        $yv = Get-ProjOrth ([double[]]@($ob | ForEach-Object { [double]$_.Y })) $e1 $e2
        for ($a = 0; $a -lt $q; $a++) {
            for ($i = 0; $i -lt $m; $i++) { $gv[$a] += $Zc[$a][$i] * $yv[$i] }
            for ($b = 0; $b -lt $q; $b++) { $s = 0.0; for ($i = 0; $i -lt $m; $i++) { $s += $Zc[$a][$i] * $Zc[$b][$i] }; $Gm[$a][$b] += $s }
        }
        $kept.Add(@{ Z = $Zc; Y = $yv })
    }
    $out.NCyl = $kept.Count
    if ($kept.Count -lt [math]::Max($minCyl, $q + 3)) { $out.Why = 'cylindres'; return $out }
    $sol = Solve-ContentLinear $Gm $gv
    if ($null -eq $sol) { $out.Why = 'singulier'; return $out }
    $ssr = 0.0
    foreach ($k in $kept) {
        for ($i = 0; $i -lt $k.Y.Count; $i++) { $r = [double]$k.Y[$i]; for ($j = 0; $j -lt $q; $j++) { $r -= $k.Z[$j][$i] * $sol[$j] }; $ssr += $r * $r }
    }
    $df = $kept.Count * ($n - 2) - $q
    if ($df -le 0) { $out.Why = 'ddl'; return $out }
    $s2 = $ssr / $df
    # Inverse de G (colonnes), pour l erreur-type des decalages centres : Var(alpha_p - moyenne) = s2 c' G^-1 c,
    # c_k = 1[k = p] - 1/n sur les decalages k = 1..n-1 (alpha_0 = 0)
    $inv = New-Object 'double[][]' $q
    for ($j = 0; $j -lt $q; $j++) {
        $ej = New-Object double[] $q; $ej[$j] = 1.0
        $colj = Solve-ContentLinear $Gm $ej
        if ($null -eq $colj) { $out.Why = 'singulier'; return $out }
        $inv[$j] = $colj
    }
    $al = New-Object double[] $n
    for ($p = 1; $p -lt $n; $p++) { $al[$p] = [double]$sol[$ng + $p - 1] }
    $mean = 0.0; foreach ($x in $al) { $mean += $x }; $mean /= $n
    for ($p = 0; $p -lt $n; $p++) {
        $v = 0.0
        for ($k1 = 1; $k1 -lt $n; $k1++) {
            $f1 = [double]($k1 -eq $p) - 1.0 / $n
            for ($k2 = 1; $k2 -lt $n; $k2++) { $f2 = [double]($k2 -eq $p) - 1.0 / $n; $v += $f1 * $f2 * $inv[$ng + $k1 - 1][$ng + $k2 - 1] }
        }
        $out.SE[$p] = [math]::Sqrt([math]::Max(0.0, $s2 * $v))
        $out.Alpha[$p] = $al[$p] - $mean
    }
    $out.Ok = $true; $out.Df = $df; $out.S = [math]::Sqrt([math]::Max(0.0, $s2))
    return $out
}

function Get-InterpEst($u, [int]$c) {
    # Estimation interpolee lineairement entre les cylindres estimes qui encadrent c, cible d une passe de mesure : bornee
    # a 0..CalMaxNs (plafond des passes de mesure)
    $cs = @($u.Est.Keys | ForEach-Object { [int]$_ } | Sort-Object)
    if ($cs.Count -eq 0) { return $script:CalInterpDefault }
    $v = if ($c -le $cs[0]) { [double]$u.Est[$cs[0]] } elseif ($c -ge $cs[-1]) { [double]$u.Est[$cs[-1]] } else {
        $j = 0; while ($cs[$j + 1] -lt $c) { $j++ }
        [double]$u.Est[$cs[$j]] + ($c - $cs[$j]) / [double]($cs[$j + 1] - $cs[$j]) * ([double]$u.Est[$cs[$j + 1]] - [double]$u.Est[$cs[$j]])
    }
    return [int][math]::Max(0, [math]::Min($script:CalMaxNs, [math]::Round($v, 0)))
}

function Start-CalibDensify($cal) {
    # Test standard : une chute du besoin entre deux cylindres testes voisins (plus de 15 ns et de 3 incertitudes), ou
    # une estimation loin de la courbe provisoire, declenche des mesures complementaires sur les cylindres intermediaires
    # (chute : tous ceux entre les deux, plus 2 de part et d autre ; ecart : c-4, c-2, c-1, c+1, c+2, c+4), en deux
    # passes : A a la valeur interpolee, B de l autre cote du zero (pente commune). Les cylindres qui bordent la zone
    # sont remesures a leur estimation. 2 zones et 30 cylindres au plus. Renvoie $true si une passe est lancee.
    if ($cal.Mode -eq 'fine' -or $cal.Densified) { return $false }
    $zones = New-Object System.Collections.Generic.List[object]
    foreach ($u in $cal.Units) {
        $cs = @($u.Est.Keys | ForEach-Object { [int]$_ } | Sort-Object)
        if ($cs.Count -lt 3) { continue }
        for ($i = 0; $i -lt $cs.Count - 1; $i++) {
            $ci = $cs[$i]; $cj = $cs[$i + 1]
            $thr = [math]::Max($script:CalDevNs, 3.0 * [math]::Sqrt([double]$u.Sig[$ci] * [double]$u.Sig[$ci] + [double]$u.Sig[$cj] * [double]$u.Sig[$cj]))
            $drop = [double]$u.Est[$ci] - [double]$u.Est[$cj]
            if ($drop -gt $thr -and $cj - $ci -gt 1) { $zones.Add(@{ Lo = $ci; Hi = $cj; Kind = 'drop'; Sev = $drop }) }
        }
        $fit = Fit-PrecompCurve $u.Est $u.Sig $cal.MaxCyl $u.Kind $false
        if ($fit) {
            foreach ($c in $cs) {
                $dv = $fit.Values[$c] - [double]$u.Est[$c]
                if ([math]::Abs($dv) -gt [math]::Max($script:CalDevNs, 3.0 * [double]$u.Sig[$c])) { $zones.Add(@{ Lo = $c; Hi = $c; Kind = 'dev'; Sev = [math]::Abs($dv) }) }
            }
        }
    }
    if ($zones.Count -eq 0) { return $false }
    $tested = @{}; foreach ($c in $cal.Cyls) { $tested[[int]$c] = $true }
    $new = @{}; $bounds = @{}; $kept = 0; $skipped = @(); $names = @(); $drops = @()
    # Chutes d abord (par severite), puis ecarts ; un ecart deja couvert par une chute retenue (a 2 cylindres pres)
    # ne compte pas : il ne doit pas prendre la place d une autre chute
    foreach ($z in @($zones | Sort-Object @{ Expression = { [int]($_.Kind -ne 'drop') } }, @{ Expression = { -[double]$_.Sev } })) {
        if ($z.Kind -ne 'drop' -and @($drops | Where-Object { [int]$z.Lo -ge [int]$_.Lo - 2 -and [int]$z.Lo -le [int]$_.Hi + 2 }).Count -gt 0) { continue }
        # (parentheses : la virgule est prioritaire sur l addition en PowerShell)
        $cand = if ($z.Kind -eq 'drop') { @(@(([int]$z.Lo + 1)..([int]$z.Hi - 1)) + @(([int]$z.Lo - 2), ([int]$z.Hi + 2))) } else { @(([int]$z.Lo - 4), ([int]$z.Lo - 2), ([int]$z.Lo - 1), ([int]$z.Lo + 1), ([int]$z.Lo + 2), ([int]$z.Lo + 4)) }
        $add = @($cand | Where-Object { $_ -ge 0 -and $_ -le $cal.MaxCyl -and -not $tested.ContainsKey([int]$_) -and -not $new.ContainsKey([int]$_) })
        $nm = if ($z.Kind -eq 'drop') { (T "chute entre c{0} et c{1}") -f "$($z.Lo)", "$($z.Hi)" } else { (T "écart à c{0}") -f "$($z.Lo)" }
        if ($add.Count -eq 0) { continue }                                   # zone deja couverte (autre tete)
        if ($kept -ge 2 -or $new.Count + $add.Count -gt 30) { $skipped += $nm; continue }
        foreach ($c in $add) { $new[[int]$c] = $true }
        $bounds[[int]$z.Lo] = $true; $bounds[[int]$z.Hi] = $true
        $kept++; $names += $nm
        if ($z.Kind -eq 'drop') { $drops += $z }
    }
    foreach ($s in $skipped) { Append-Log ((T "Calibration : zone {0} non complétée (2 zones et 30 cylindres au plus) : test fin conseillé.") -f "$s") }
    if ($new.Count -eq 0) { return $false }
    $newL = [int[]]@($new.Keys | Sort-Object)
    $bndL = [int[]]@($bounds.Keys | Where-Object { $tested.ContainsKey([int]$_) } | Sort-Object)
    $cal.Densified = $true; $cal.DenseNew = $newL; $cal.DensePass = 'A'
    $cal.Cyls = [int[]]@(@($cal.Cyls) + @($newL) | Sort-Object -Unique)
    $cal.CylList = Format-CylList $cal.Cyls; $cal.TSpec = "c=$($cal.CylList):h=0-1"
    foreach ($u in $cal.Units) {
        foreach ($c in $newL) { $u.Results[$c] = @{} }
        $u.Dense = @{}
        foreach ($c in $newL) { $u.Dense[$c] = Get-InterpEst $u $c }
        foreach ($c in $bndL) { if ($u.Est.ContainsKey($c)) { $u.Dense[$c] = [int][math]::Max(0, [math]::Min($script:CalMaxNs, [math]::Round([double]$u.Est[$c], 0))) } }
    }
    Append-Log ((T "Calibration : anomalie de la courbe ({0}) : mesures complémentaires des cylindres {1}, en deux passes, pour distinguer une marche, une rampe ou un point isolé.") -f "$($names -join ' ; ')", "$(Format-CylList $newL)")
    $cal.Stage = 'densify'; $cal.TotalPasses += 2
    New-CalibPass
    return $true
}

function Set-CalibDenseB($cal) {
    # Passe B : chaque cylindre ajoute est ecrit de l autre cote du zero predit par sa mesure A (pente commune),
    # a 15 ns au moins de la valeur A (CalDenseStep, 12.7) ; les cylindres qui bordent la zone sont remesures a la meme
    # valeur (repetition)
    foreach ($u in $cal.Units) {
        $slope = if ($null -ne $u.Slope -and [double]$u.Slope -lt -0.2) { [double]$u.Slope } else { -2.0 }
        $nd = @{}
        foreach ($c in @($u.Dense.Keys | ForEach-Object { [int]$_ })) {
            if ($cal.DenseNew -notcontains $c) { $nd[$c] = [int]$u.Dense[$c]; continue }
            $x1 = [int]$u.Dense[$c]; $pts = $u.Results[$c]
            if (-not $pts -or -not $pts.ContainsKey($x1)) { continue }
            $z = $x1 + [double]$pts[$x1].Shift / (-$slope)
            $dir = if ($z -ge $x1) { 1 } else { -1 }
            $x2 = [int][math]::Round($z + $script:CalDenseStep * $dir)
            if ([math]::Abs($x2 - $x1) -lt $script:CalDenseStep) { $x2 = $x1 + $script:CalDenseStep * $dir }
            $x2 = [int][math]::Max(0, [math]::Min($script:CalMaxNs, $x2))
            if ($x2 -eq $x1) { $x2 = if ($x1 -ge $script:CalDenseStep) { $x1 - $script:CalDenseStep } else { $x1 + $script:CalDenseStep } }
            $nd[$c] = $x2
        }
        $u.Dense = $nd
    }
}

function Get-TrendEstimates($u, [int]$maxCyl, [bool]$dense, $dents = $null) {
    # Zero d un cylindre encore sous-compense au plafond des passes de mesure (CalMaxNs), extrapole de ses mesures : garde
    # tel quel s il est proche (incertitude <= CalTrendSig) avec une pente propre. Sinon combine (moyenne ponderee par
    # l inverse des variances) avec la tendance de la courbe : droite ponderee de pente >= 0 sur les CalTrendN derniers
    # cylindres fiables (incertitude <= 6 ns, ni plafonnes, ni isoles, ni eux-memes combines) qui le precedent dans le meme
    # segment croissant, a CalTrendSpan cylindres au plus (3 fois plus en test standard). Incertitude de la tendance :
    # erreur-type de la prediction (elargie si les points s ecartent de la droite) et 25 % de la hausse extrapolee depuis
    # le dernier cylindre fiable (meme regle qu une extrapolation propre).
    # Copies : u.Est, u.Sig et u.Kind restent la mesure propre (controle Dev, journal, courbe enregistree) ; type
    # transitoire 'trend' (non fiable pour SegFit), jamais enregistre. Renvoie @{ Est; Sig; Kind; Info (c -> detail) }.
    # 12.9 (correction 4) : $dents, dents de la courbe (Start-CalibFit) : segments de la courbe provisoire coupes a chaque
    # dent, la tendance ne traverse pas une dent
    $est = @{}; $sig = @{}; $kind = @{}; $info = @{}
    foreach ($k in @($u.Est.Keys)) { $est[[int]$k] = [double]$u.Est[$k]; $sig[[int]$k] = [double]$u.Sig[$k]; $kind[[int]$k] = [string]$u.Kind[$k] }
    $res = @{ Est = $est; Sig = $sig; Kind = $kind; Info = $info }
    # 12.8 (S3-HIGH) : cylindres mesures autour de leur besoin par la mesure directe (Reach, mesure complete de cette
    # disquette seulement) : zero de la corde de leurs deux ecritures, jamais combine avec la tendance
    $cand = @($est.Keys | ForEach-Object { [int]$_ } | Where-Object { $kind[$_] -eq 'extrap' -and $est[$_] -gt $script:CalMaxNs -and ($sig[$_] -gt $script:CalTrendSig -or ($u.Own -and $u.Own.ContainsKey($_) -and -not $u.Own[$_])) -and -not ($u.Reach -and $u.Reach.ContainsKey($_)) } | Sort-Object)
    if ($cand.Count -eq 0) { return $res }                      # cas courant : aucune combinaison
    $f0 = Fit-PrecompCurve $u.Est $u.Sig $maxCyl $u.Kind $dense -Dents $dents
    $segs = @(if ($f0 -and $f0.Segs) { @($f0.Segs) } else { @{ Lo = 0; Hi = $maxCyl; Dir = 1 } })
    $outl = @{}; if ($f0) { foreach ($c in @($f0.Outliers)) { if ($null -ne $c) { $outl[[int]$c] = $true } } }
    $cs = @($est.Keys | ForEach-Object { [int]$_ } | Sort-Object)
    $span = if ($dense) { [int]$script:CalTrendSpan } else { 3 * [int]$script:CalTrendSpan }
    $minRef = if ($dense) { 3 } else { 2 }
    foreach ($c in $cand) {
        $sg = @($segs | Where-Object { $c -ge [int]$_.Lo -and $c -le [int]$_.Hi })
        if ($sg.Count -eq 0 -or [int]$sg[0].Dir -ne 1) { continue }        # segment decroissant : pas de tendance montante
        $lo = [math]::Max([int]$sg[0].Lo, $c - $span)
        $ref = @($cs | Where-Object { $_ -lt $c -and $_ -ge $lo -and -not $outl.ContainsKey($_) -and $kind[$_] -ne 'cap' -and $kind[$_] -ne 'trend' -and [double]$u.Sig[$_] -le $script:CalTrendRefSig } | Select-Object -Last ([int]$script:CalTrendN))
        if ($ref.Count -lt $minRef) { continue }
        $sw = 0.0; $sx = 0.0; $sy = 0.0
        foreach ($r in $ref) { $w = 1.0 / [math]::Pow([math]::Max(1.0, [double]$u.Sig[$r]), 2); $sw += $w; $sx += $w * $r; $sy += $w * [double]$u.Est[$r] }
        $mx = $sx / $sw; $my = $sy / $sw; $sxx = 0.0; $sxy = 0.0
        foreach ($r in $ref) { $w = 1.0 / [math]::Pow([math]::Max(1.0, [double]$u.Sig[$r]), 2); $sxx += $w * ($r - $mx) * ($r - $mx); $sxy += $w * ($r - $mx) * ([double]$u.Est[$r] - $my) }
        if ($sxx -le 0) { continue }
        $b = [math]::Max(0.0, $sxy / $sxx); $a = $my - $b * $mx
        $chi = 0.0; foreach ($r in $ref) { $w = 1.0 / [math]::Pow([math]::Max(1.0, [double]$u.Sig[$r]), 2); $chi += $w * [math]::Pow([double]$u.Est[$r] - ($a + $b * $r), 2) }
        $chi = $chi / [math]::Max(1, $ref.Count - 2)
        $pred = $a + $b * $c
        $rise = [math]::Max(0.0, $pred - [double]$u.Est[$ref[-1]])
        $sT = [math]::Max(1.0, [math]::Sqrt((1.0 / $sw + [math]::Pow($c - $mx, 2) / $sxx) * [math]::Max(1.0, $chi) + [math]::Pow(0.25 * $rise, 2)))
        $wo = 1.0 / [math]::Pow([math]::Max(1.0, $sig[$c]), 2); $wt = 1.0 / ($sT * $sT)
        # Plancher : la plus forte precomp ecrite au cylindre, encore sous-compensee (zero extrapole au-dela)
        $xr = 0.0
        if ($u.Results -and $u.Results.ContainsKey($c) -and $u.Results[$c].Count -gt 0) { $xr = [double](@($u.Results[$c].Keys | ForEach-Object { [int]$_ }) | Measure-Object -Maximum).Maximum }
        $v = [math]::Max($xr, [math]::Min([double]$script:CalHardNs, ($wo * $est[$c] + $wt * $pred) / ($wo + $wt))); $sv = 1.0 / [math]::Sqrt($wo + $wt)
        $info[$c] = @{ Own = $est[$c]; OwnSig = $sig[$c]; Trend = $pred; TrendSig = $sT; Est = $v; Sig = $sv }
        $est[$c] = $v; $sig[$c] = $sv; $kind[$c] = 'trend'
    }
    return $res
}

function Start-CalibFit($cal) {
    # Courbe par unite d apres les estimations (points isoles ecartes sur des donnees denses ; zero extrapole incertain
    # au-dela du plafond des passes de mesure combine avec la tendance de la courbe, Get-TrendEstimates), puis premiere
    # passe de verification de tous les cylindres estimes
    $dense = ($cal.Mode -eq 'fine' -or [bool]$cal.Densified)
    foreach ($u in $cal.Units) {
        # Estimation des seules passes de mesure (apres encadrement et mesures complementaires, avant toute verification et
        # sans la tendance) : troisieme mesure des verifications contradictoires (Get-VerifyDrift)
        $u.EstPass = @{}; foreach ($k in @($u.Est.Keys)) { $u.EstPass[[int]$k] = [double]$u.Est[$k] }
        # 12.9 (correction 4) : dents locales du besoin, mesurees par les passes de mesure (cylindres testes voisins dont les
        # passes encadrent le zero : test fin en pratique), appliquees par Fit-PrecompCurve (segments croissants de SegFit,
        # CalDentMax au plus) ; Get-CalibDents en rend CalDentMax + 2 : la chute de la rupture c43/c44, rendue aussi puis
        # ecartee par Split-CurveDents, n evince pas une vraie dent
        $dc = @()
        if ($cal.Dent -and $u.CoarseZ -and $u.CoarseZ.Count -gt 0) {
            $stp = [math]::Max([double]$script:CalDevNs / [double]$script:CalStepDevDiv, [double]$script:CalResidual)
            $zk = @{}; foreach ($k in @($u.CoarseZ.Keys)) { if ([string]$u.Kind[[int]$k] -eq 'interp') { $zk[[int]$k] = $u.CoarseZ[$k] } }
            $dc = @(Get-CalibDents $zk ([double]$u.Slope) @($cal.Values).Count $stp ([int]$script:CalDentGap) ([int]$script:CalDentMax + 2))
        }
        $tr = Get-TrendEstimates $u $cal.MaxCyl $dense $dc
        $u.Trend = $tr.Info
        if ($tr.Info.Count -gt 0) {
            $tt = (@($tr.Info.Keys | Sort-Object | ForEach-Object { $ti = $tr.Info[$_]; (T "c{0} : extrapolation {1} ± {2} ns, tendance {3} ± {4} ns, retenu {5} ns") -f "$_", (Format-LevelNum $ti.Own), (Format-LevelNum $ti.OwnSig), (Format-LevelNum $ti.Trend), (Format-LevelNum $ti.TrendSig), (Format-LevelNum $ti.Est) })) -join ' ; '
            Append-Log ($u.Prefix + ((T "Besoin au-delà de {0} ns, zéro extrapolé incertain (loin des mesures ou sans pente propre) : combiné avec la tendance de la courbe ({1}). La vérification écrit la courbe à ces cylindres et la mesure.") -f "$($script:CalMaxNs)", "$tt"))
            $u.Fit = Fit-PrecompCurve $tr.Est $tr.Sig $cal.MaxCyl $tr.Kind $dense -Dents $dc
        } else { $u.Fit = Fit-PrecompCurve $u.Est $u.Sig $cal.MaxCyl $u.Kind $dense -Dents $dc }
        $u.Outliers = @($u.Fit.Outliers | ForEach-Object { [int]$_ } | Sort-Object)
        foreach ($c in $u.Outliers) { if ($u.Kind.ContainsKey($c)) { $u.Kind[$c] = 'outlier' } }
        $u.Profile = Build-CurveProfile $u.Fit.Values
        Append-Log ($u.Prefix + ((T "Courbe ajustée : {0} (écart réduit {1}), de {2} ns au cylindre 0 à {3} ns au cylindre {4} ; profil : {5}") -f (Get-CurveModelName $u.Fit.Model), "$([math]::Round($u.Fit.Chi, 2))", "$($u.Fit.Values[0])", "$($u.Fit.Values[-1])", "$($cal.MaxCyl)", "$($u.Profile)"))
        if ($u.Outliers.Count -gt 0) { Append-Log ($u.Prefix + ((T "Point(s) isolé(s) écarté(s) de la courbe : {0} : écart avec les cylindres voisins, défaut ponctuel probable de la disquette de calibration, non suivi.") -f (($u.Outliers | ForEach-Object { "c$_" }) -join ', '))) }
        # 12.9 (correction 4) : seules les dents appliquees par la courbe (la chute de la rupture c43/c44, ecartee, ne l est pas)
        foreach ($d in @(Get-FitDents $u.Fit)) { Append-Log ($u.Prefix + ((T "Dent locale du besoin entre c{0} et c{1} : baisse de {2} ns mesurée par les passes de mesure (au moins {3} ns à chaque passe), qui persiste au cylindre suivant : la courbe la suit ; la vérification la contrôlera.") -f "$($d.C1)", "$($d.C2)", (Format-LevelNum $d.Drop), (Format-LevelNum $d.Min))) }
        $u.Verify = @{}; $u.VerifyP = @{}; $u.VerifyList = $null; $u.VerifyPrev = @{}; $u.Witness = @(); $u.ReadLast = @{}; $u.WitCand = 0; $u.WitMin = 0; $u.DriftHold = $null; $u.VOff = $null
    }
    $cal.Stage = 'verify'; $cal.VerifyCount = 1
    New-CalibPass
}

function Get-ResidualTol($meas) {
    # Tolerance du residu d une verification : CalResidual, elargie a 3 erreurs-types quand la mesure est plus bruitee
    # (un residu dans le bruit ne justifie ni une correction ni une alerte de non-convergence)
    $se = [double]::NaN
    if ($null -ne $meas -and $null -ne $meas.SE) { $se = [double]$meas.SE }
    if ([double]::IsNaN($se)) { return [double]$script:CalResidual }
    return [math]::Max([double]$script:CalResidual, 3.0 * $se)
}

function Get-VerifyOffset($u, [int]$minCyl, [double]$sigK, [double]$maxNs, [double]$maxLevel = -1.0, [double]$homNs = -1.0) {
    # 12.9 : decalage commun de l ecriture d une verification complete (une commande gw par unite : tous les cylindres
    # estimes ecrits a la suite, comme l image). Chaque commande d ecriture decale de quelques ns tous les cylindres qu elle
    # ecrit (journal du 01/11/2026 : +3,85 ns en mediane sur 80 cylindres, 76 residus positifs sur 80) : juge cylindre par
    # cylindre, ce decalage passait pour une erreur de la courbe (24 cylindres retenus, 32 reajustes a tort). Estimateur :
    # mediane des residus bruts des cylindres verifies hors points isoles et hors limites physiques (plafond encore
    # sous-compense, plancher encore sur-compense : saturation, pas decalage d ecriture) ; erreur-type E = 1,2533 x
    # max(1 ; 1,4826 MAD) / racine de n, comme la derive des temoins (Get-VerifyDrift). Retire (Ok) si n >= minCyl, |m| > sigK E
    # et |m| <= maxNs ; sinon Why : 'cylindres' (trop peu), 'nonsig' (dans le bruit), 'borne' (au-dela de maxNs : lecteur ou
    # support instable depuis les passes de mesure, residus juges tels quels). Fonction pure : ne modifie pas l unite.
    # Banc 129-voff (N1, C5) : seuls les cylindres dont le zero est interpole entre deux niveaux mesures comptent (valeur
    # ecrite <= $maxLevel, niveau maximal des passes de mesure de la famille par defaut, et Kind 'interp' quand l unite le
    # connait) : au-dela, le residu porte l erreur de modele de l extrapolation ou de l encadrement (reponse non lineaire,
    # fort besoin), qui passerait pour un decalage d ecriture et ne serait plus corrigee. Le decalage estime vaut pour
    # toute la commande : il est retire de tous les cylindres de l unite (Invoke-CalibAnalysis).
    # Banc 129-voff2 (U4-U12, X1) : les cylindres retenus sont groupes sur la piste (besoins les plus faibles) : une erreur
    # regionale de la courbe a cet endroit passerait pour un decalage commun. Garde d homogeneite : le decalage n est retire
    # que s il est le meme ailleurs, ecart <= $homNs (CalVOffHomNs par defaut) entre la mediane des retenus et celle des
    # autres cylindres verifies (5 au moins), et entre les deux moities de la piste parmi les retenus (4 au moins chacune) ;
    # sinon Why 'regional' (Dz : ecart maximal constate, Mn : mediane des autres cylindres).
    # Renvoie @{ Ok ; Why ; M ; E ; N ; Mn ; Dz } (N : cylindres retenus pour l estimation)
    $vals = @($u.Fit.Values)
    if ($maxLevel -lt 0) { $maxLevel = [double](@($script:CalCoarse) | Measure-Object -Maximum).Maximum }
    $rn = @(); $rc = @()
    $r = @(foreach ($k in @($u.Verify.Keys)) {
        $c = [int]$k
        if (@($u.Outliers) -contains $c) { continue }
        $m = $u.Verify[$k]
        if ($null -eq $m -or $null -eq $m.Shift) { continue }
        $x = [double]$m.Shift
        if ([double]::IsNaN($x)) { continue }
        $p = $null
        if ($u.VerifyP -and $u.VerifyP.ContainsKey($c)) { $p = [int]$u.VerifyP[$c] } elseif ($c -lt $vals.Count) { $p = [int]$vals[$c] }
        if ($null -ne $p -and (($x -gt 0 -and $p -ge $script:CalHardNs) -or ($x -lt 0 -and $p -le 0))) { continue }
        if ($null -eq $p -or [double]$p -gt $maxLevel -or ($u.Kind -and $u.Kind.ContainsKey($c) -and [string]$u.Kind[$c] -ne 'interp')) { $rn += $x; continue }
        $rc += $c
        $x
    })
    $res = @{ Ok = $false; Why = ''; M = 0.0; E = [double]::NaN; N = $r.Count; Mn = [double]::NaN; Dz = 0.0 }
    if ($r.Count -lt [math]::Max(1, $minCyl)) { $res.Why = 'cylindres'; return $res }
    $m = [double](Get-Median $r)
    $s = [math]::Max(1.0, 1.4826 * [double](Get-Median @($r | ForEach-Object { [math]::Abs([double]$_ - $m) })))
    $res.M = $m; $res.E = 1.2533 * $s / [math]::Sqrt([double]$r.Count)
    if ([math]::Abs($m) -gt $maxNs) { $res.Why = 'borne'; return $res }
    if ([math]::Abs($m) -le $sigK * $res.E) { $res.Why = 'nonsig'; return $res }
    if ($homNs -lt 0) { $homNs = [double]$script:CalVOffHomNs }
    $dz = 0.0
    if ($rn.Count -ge 5) { $res.Mn = [double](Get-Median $rn); $dz = [math]::Abs($m - [double]$res.Mn) }
    $ord = @($rc | Sort-Object); $half = [int][math]::Floor($ord.Count / 2)
    if ($half -ge 4) {
        $lo = @(); $hi = @()
        for ($i = 0; $i -lt $ord.Count; $i++) { $v = [double]$u.Verify[[int]$ord[$i]].Shift; if ($i -lt $half) { $lo += $v } else { $hi += $v } }
        $dz = [math]::Max($dz, [math]::Abs([double](Get-Median $lo) - [double](Get-Median $hi)))
    }
    $res.Dz = $dz
    if ($dz -gt $homNs) { $res.Why = 'regional'; return $res }
    $res.Ok = $true
    return $res
}

function Get-VerifyOffsetM($u) {
    # 12.9 : decalage commun retire des residus de la derniere verification complete de l unite (VOff, Invoke-CalibAnalysis) ;
    # 0 sans retrait (dans le bruit, au-dela de la borne, trop peu de cylindres, haute densite, aucune verification complete)
    if ($null -ne $u -and $null -ne $u.VOff -and [bool]$u.VOff.Removed) { return [double]$u.VOff.M }
    return 0.0
}

function Get-CalLevels([string]$family) {
    # 12.10 : niveaux des passes de mesure de la famille : CalCoarse (bareme pose par Set-CalibScale), multiplies par
    # CalLevelKLong en long track, arrondis a l entier ; standard et haute densite : CalCoarse tel quel
    $k = if ($family -eq 'long') { [double]$script:CalLevelKLong } else { 1.0 }
    return [int[]]@(@($script:CalCoarse) | ForEach-Object { [int][math]::Round([double]$_ * $k) })
}

function Get-TracksAsym($tracks) {
    # 12.10 : asymetrie de reference : par piste (numero gw : 2 x cylindre + tete), moyenne sur les tours des rapports
    # 3T/2T - 1,5 et 4T/2T - 2 du motif relu (ScpStats), tours sans valeur ignores ; piste sans valeur : absente
    $out = @{}
    foreach ($tn in @($tracks.Keys)) {
        $d3 = @(); $d4 = @()
        foreach ($x in @($tracks[$tn])) {
            if ($null -eq $x -or [double]::IsNaN([double]$x.R3) -or [double]::IsNaN([double]$x.R4)) { continue }
            $d3 += ([double]$x.R3 - 1.5); $d4 += ([double]$x.R4 - 2.0)
        }
        if ($d3.Count -eq 0) { continue }
        $out[[int]$tn] = @((($d3 | Measure-Object -Average).Average), (($d4 | Measure-Object -Average).Average))
    }
    return $out
}

function Get-UnitAsymRef($cal, $u) {
    # 12.10 : asymetrie de reference de l unite pour la courbe enregistree : cylindres mesures (ordre croissant), ecarts
    # arrondis a 4 decimales ; tete de l unite, ou moyenne des deux tetes pour l unite commune ; sans releve : tableaux vides
    $res = @{ Cyl = [int[]]@(); D3 = [double[]]@(); D4 = [double[]]@() }
    if ($null -eq $cal.AsymRef -or $cal.AsymRef.Count -eq 0) { return $res }
    $heads = if ($null -eq $u.Head) { @(0, 1) } else { @([int]$u.Head) }
    $cyl = @(); $d3 = @(); $d4 = @()
    foreach ($c in @($cal.AsymRef.Keys | ForEach-Object { [int]([math]::Floor([int]$_ / 2)) } | Sort-Object -Unique)) {
        $a3 = @(); $a4 = @()
        foreach ($h in $heads) { $tn = 2 * $c + $h; if ($cal.AsymRef.ContainsKey($tn)) { $a3 += [double]$cal.AsymRef[$tn][0]; $a4 += [double]$cal.AsymRef[$tn][1] } }
        if ($a3.Count -eq 0) { continue }
        $cyl += $c; $d3 += [math]::Round((($a3 | Measure-Object -Average).Average), 4); $d4 += [math]::Round((($a4 | Measure-Object -Average).Average), 4)
    }
    $res.Cyl = [int[]]$cyl; $res.D3 = [double[]]$d3; $res.D4 = [double[]]$d4
    return $res
}

function Get-VerifySlope($u, [double]$maxLevel, [int]$minCyl, [double]$sigK, [double]$minSlope, [double]$minNs) {
    # 12.10 : erreur de modele aux forts besoins. Au-dela du niveau maximal des passes de mesure (CalCoarse, 100 ns), le zero
    # d un cylindre est extrapole ou encadre. Calibration TEAC du 01/11/2026 et essai 5 du 02/11/2026 (4 ecritures aux
    # profils calibres) : le residu suit la valeur ecrite, -0,045 ns/ns de 100 a 215 ns sur la tete 0 (rien sur la tete 1),
    # soit 3 ns de surcompensation aux cylindres interieurs, sous la tolerance cylindre par cylindre (CalResidual) et
    # classes ecarts locaux isoles par Get-ResidualFlags, donc jamais corriges. Estimateur : pente de Theil-Sen (mediane des
    # pentes par paires) du residu juge (Shift, centre du decalage commun) en fonction de la valeur ecrite, sur les cylindres
    # verifies ecrits au-dela de $maxLevel, hors points isoles et limites physiques (memes exclusions que Get-VerifyOffset) ;
    # niveau A = mediane de (residu - B (p - maxLevel)) ; incertitude SB = 1,2533 x max(1 ; 1,4826 MAD des residus a la
    # droite) / racine de la somme des carres des ecarts en p. Ok si n >= minCyl, |B| >= minSlope et |B| > sigK SB ; sinon
    # Why : 'cylindres' (trop peu), 'faible' (pente negligeable), 'nonsig' (dans le bruit). Fit : residu de la droite par
    # cylindre ; Bad : cylindres dont |Fit| > minNs, a corriger a leur zero mesure meme dans la tolerance
    # (Invoke-CalibAnalysis, avec les residus retenus de Get-ResidualFlags). PMin, PMax, FMin, FMax : valeurs ecrites
    # extremes et residus de la droite a ces valeurs (journal). Fonction pure : ne modifie pas l unite.
    $vals = @($u.Fit.Values)
    if ($maxLevel -lt 0) { $maxLevel = [double](@($script:CalCoarse) | Measure-Object -Maximum).Maximum }
    $pts = @()
    foreach ($k in @($u.Verify.Keys)) {
        $c = [int]$k
        if (@($u.Outliers) -contains $c) { continue }
        $m = $u.Verify[$k]
        if ($null -eq $m -or $null -eq $m.Shift) { continue }
        $x = [double]$m.Shift
        if ([double]::IsNaN($x)) { continue }
        $p = $null
        if ($u.VerifyP -and $u.VerifyP.ContainsKey($c)) { $p = [int]$u.VerifyP[$c] } elseif ($c -lt $vals.Count) { $p = [int]$vals[$c] }
        if ($null -eq $p -or [double]$p -le $maxLevel) { continue }
        if (($x -gt 0 -and $p -ge $script:CalHardNs) -or ($x -lt 0 -and $p -le 0)) { continue }
        $pts += ,@($c, [double]$p, $x)
    }
    $res = @{ Ok = $false; Why = ''; B = 0.0; SB = [double]::NaN; A = 0.0; X0 = $maxLevel; N = $pts.Count; Fit = @{}; Bad = @{}; PMin = 0.0; PMax = 0.0; FMin = 0.0; FMax = 0.0 }
    if ($pts.Count -lt [math]::Max(3, $minCyl)) { $res.Why = 'cylindres'; return $res }
    $sl = @()
    for ($i = 0; $i -lt $pts.Count; $i++) {
        for ($j = $i + 1; $j -lt $pts.Count; $j++) {
            $dx = [double]$pts[$j][1] - [double]$pts[$i][1]
            if ([math]::Abs($dx) -gt 1e-9) { $sl += (([double]$pts[$j][2] - [double]$pts[$i][2]) / $dx) }
        }
    }
    if ($sl.Count -eq 0) { $res.Why = 'cylindres'; return $res }
    $b = [double](Get-Median $sl)
    $a = [double](Get-Median @($pts | ForEach-Object { [double]$_[2] - $b * ([double]$_[1] - $maxLevel) }))
    $xm = ($pts | ForEach-Object { [double]$_[1] } | Measure-Object -Average).Average
    $sxx = 0.0; foreach ($q in $pts) { $sxx += ([double]$q[1] - $xm) * ([double]$q[1] - $xm) }
    $rr = @($pts | ForEach-Object { [double]$_[2] - ($a + $b * ([double]$_[1] - $maxLevel)) })
    $mr = [double](Get-Median $rr)
    $mad = [double](Get-Median @($rr | ForEach-Object { [math]::Abs([double]$_ - $mr) }))
    $res.B = $b; $res.A = $a
    $res.SB = if ($sxx -gt 0) { 1.2533 * [math]::Max(1.0, 1.4826 * $mad) / [math]::Sqrt($sxx) } else { [double]::NaN }
    $res.PMin = ($pts | ForEach-Object { [double]$_[1] } | Measure-Object -Minimum).Minimum
    $res.PMax = ($pts | ForEach-Object { [double]$_[1] } | Measure-Object -Maximum).Maximum
    $res.FMin = $a + $b * ([double]$res.PMin - $maxLevel); $res.FMax = $a + $b * ([double]$res.PMax - $maxLevel)
    foreach ($q in $pts) { $res.Fit[[int]$q[0]] = $a + $b * ([double]$q[1] - $maxLevel) }
    if ([math]::Abs($b) -lt $minSlope) { $res.Why = 'faible'; return $res }
    if ([double]::IsNaN($res.SB) -or [math]::Abs($b) -le $sigK * $res.SB) { $res.Why = 'nonsig'; return $res }
    foreach ($q in $pts) { if ([math]::Abs([double]$res.Fit[[int]$q[0]]) -gt $minNs) { $res.Bad[[int]$q[0]] = $true } }
    $res.Ok = $true
    return $res
}

function Add-DriftWitnesses($u) {
    # Verification ciblee : des cylindres non modifies sont reecrits a leur valeur inchangee et relus avec les cylindres
    # modifies. Leur valeur ecrite ne change pas : l ecart de leur residu d une verification a l autre mesure directement la
    # derive du lecteur entre les deux passes (temperature, contact de la tete), sans dependre de la pente. Repartis sur la
    # piste, sans condition sur leur residu (pas de biais de selection), et seulement s ils ne depassent pas le nombre
    # maximal d ecritures par piste que la calibration atteint de toute facon.
    $u.Witness = @(); $u.WitCand = 0
    # Minimum de temoins : 4 en test standard (peu de cylindres non modifies), sinon CalDriftMinWit ; garde avec l unite
    $u.WitMin = if ($script:Cal -and $script:Cal.Mode -ne 'fine' -and -not [bool]$script:Cal.Densified) { 4 } else { [int]$script:CalDriftMinWit }
    if (@($u.VerifyList).Count -eq 0) { return }
    $vals = @($u.Fit.Values)
    # 12.9 (revue RT7, M1) : passe du nouvel essai : cylindres gardes (zone non reproductible, cylindres non reproductibles :
    # DriftHold.P) exclus des temoins, leur relecture mesure la zone et non la derive du lecteur (Get-VerifyDrift calcule D
    # avant de les remettre dans Contra ou NonRepro) ; sans nouvel essai, DriftHold vide : aucun effet
    $hold = if ($u.DriftHold -and $u.DriftHold.P) { $u.DriftHold.P } else { @{} }
    $cand = @($u.Verify.Keys | ForEach-Object { [int]$_ } | Where-Object {
        @($u.VerifyList) -notcontains $_ -and @($u.Outliers) -notcontains $_ -and $u.VerifyP.ContainsKey($_) -and $_ -lt $vals.Count -and
        [int]$vals[$_] -eq [int]$u.VerifyP[$_] -and [int]$vals[$_] -gt 0 -and [int]$vals[$_] -lt $script:CalHardNs -and -not $hold.ContainsKey($_) } | Sort-Object)
    # 12.8 (lot 1b) : jamais au-dela du nombre d ecritures par piste annonce par l avertissement (WriteMax), repli compris.
    # Sans effet a la verification 2 (une piste n est ecrite qu une fois par passe) ; passe du nouvel essai : piste deja
    # ecrite WriteMax fois exclue
    if ($script:Cal -and [int]$script:Cal.WriteMax -gt 0 -and $null -ne $u.Writes) {
        $wcap = [int]$script:Cal.WriteMax
        $cand = @($cand | Where-Object { 1 + [int]$u.Writes[[int]$_] -le $wcap })
    }
    if ($null -ne $u.Writes -and $u.Writes.Count -gt 0) {
        $wmax = [int](@($u.Writes.Values) | Measure-Object -Maximum).Maximum
        $vmax = [int](@(@($u.VerifyList) | ForEach-Object { 1 + [int]$u.Writes[[int]$_] }) | Measure-Object -Maximum).Maximum
        $lim = [math]::Max($wmax, $vmax)
        $low = @($cand | Where-Object { 1 + [int]$u.Writes[[int]$_] -le $lim })
        # Repli : une ecriture de plus sur quelques pistes plutot qu aucune mesure de derive
        if ($low.Count -ge [int]$u.WitMin) { $cand = $low }
    }
    $u.WitCand = $cand.Count
    $k = [math]::Min([int]$script:CalDriftWitness, $cand.Count)
    if ($k -lt [int]$u.WitMin) { return }
    $w = @(for ($i = 0; $i -lt $k; $i++) { [int]$cand[[int][math]::Floor(($i + 0.5) * $cand.Count / $k)] })
    $u.Witness = $w
    $u.VerifyList = @(@($u.VerifyList) + $w | Sort-Object -Unique)
}

function Get-VerifyDrift($u) {
    # Derive du lecteur entre les deux dernieres verifications, mesuree sur les temoins (meme valeur ecrite les deux fois) :
    # D = mediane de (residu nouveau - residu precedent), incertitude E = 1,2533 S / racine du nombre de temoins. Les residus
    # des cylindres relus a la derniere verification sont juges sans ce decalage (ramenes au repere de la verification
    # precedente, sur laquelle la courbe a ete corrigee).
    # Verifications contradictoires (Contra) : cylindre corrige (p1 -> p2) dont le residu de la derniere verification r2'
    # (derive D retiree, 0 si non mesuree) est hors de sa tolerance du cote de p1, et dont le residu de la verification
    # precedente r1 est du cote de p2 (hors de sa tolerance), ou dans sa tolerance (cylindre deplace avec ses voisins par le
    # lissage, sans que la verification 1 l ait demande) : les deux verifications placent le besoin entre p1 et p2 mais leurs
    # estimations se contredisent. Valeur retenue Z : mediane de l estimation des passes de mesure (EstPass) et des
    # zeros des deux verifications (pente commune), moyenne des deux zeros sans EstPass, bornee a [min(p1,p2) ; max(p1,p2)] ;
    # E = ecart entre les deux zeros. Toujours traite ainsi, quelle que soit la longueur de la suite (Set-VerifyContra).
    # Ecart minimal : un candidat dont E ne depasse pas la tolerance de la verification 1 convertie en ns de precomp par la
    # meme pente (CalContraMinNs si elle n est pas convertible) est en accord. Zone : suite de candidats voisins (comme les
    # suites ci-dessous) dont un au moins depasse ce seuil, candidats en accord compris ; une suite dont tous les candidats
    # sont en accord (cylindre isole, typiquement) n est pas une contradiction : jugee par les regles qui suivent (non
    # reproductible, ecart local ou non converge), residu enregistre.
    # Non reproductible : temoin dont l ecart s eloigne de D de plus de max(3 tolerances ; 4 S) ; cylindre corrige dont le
    # residu, derive retiree, va a l inverse du changement prevu par la pente commune de plus de cette limite, ou au-dela du
    # changement prevu entier de plus de cette limite alors que r2' reste hors de sa tolerance (hors contradiction : r1 a
    # l oppose de la correction, comme le c81 de U5). Une reponse
    # plus faible que prevu, ou nulle, n est pas une non-reproductibilite : le cylindre est juge normalement. Une suite d au
    # moins 3 candidats voisins (2 cylindres au plus, ou consecutifs parmi les cylindres relus) de meme sens est un ecart
    # systematique, jugee normalement elle aussi. DC / NC : ecart median des cylindres corriges a leur prediction (derive
    # comprise), a comparer a D (les temoins isoles derivent-ils comme les blocs corriges ?). Sys : candidats d une suite
    # systematique ; un temoin qui en fait partie est juge sur sa relecture, derive retiree, et non sur sa mesure precedente.
    # 12.9 (RT7) : apres un nouvel essai, zone et cylindres non reproductibles de la verification d avant gardes
    # (DriftHold, Add-VerifyDriftHold) ; sans nouvel essai, aucun effet.
    $res = @{ Use = $false; D = 0.0; S = [double]::NaN; SRaw = [double]::NaN; E = [double]::NaN; NW = 0; NC = 0; DC = [double]::NaN; NonRepro = @{}; Sys = @{}; Contra = @{} }
    if (-not $u.VerifyPrev -or $u.VerifyPrev.Count -eq 0) { return (Add-VerifyDriftHold $u $res @('Contra', 'NonRepro')) }
    $sl = if ($null -ne $u.Slope -and [double]$u.Slope -lt -0.2) { [double]$u.Slope } else { -2.0 }
    $wit = @(); $cor = @()
    foreach ($k in @($u.VerifyPrev.Keys)) {
        $c = [int]$k
        if (-not $u.Verify.ContainsKey($c) -or -not $u.VerifyP.ContainsKey($c) -or @($u.Outliers) -contains $c) { continue }
        $p1 = [double]$u.VerifyPrev[$c].P; $r1 = [double]$u.VerifyPrev[$c].Shift
        $p2 = [double]$u.VerifyP[$c]; $r2 = [double]$u.Verify[$c].Shift
        if ([double]::IsNaN($r1) -or [double]::IsNaN($r2)) { continue }
        $o = @{ C = $c; Obs = $r2 - $r1; Exp = $sl * ($p2 - $p1); P1 = $p1; R1 = $r1; P2 = $p2; R2 = $r2 }
        # 12.8 (lot 1b) : temoin = cylindre choisi par Add-DriftWitnesses (Witness). Passe du nouvel essai : cylindres vises
        # ou voisins relus a leur valeur inchangee, choisis pour leur residu : ni temoins ni corriges (juges sur leur
        # relecture, derive retiree). Verification 2 : tout cylindre relu a sa valeur inchangee est un temoin (inchange)
        if ($p2 -eq $p1) { if (@($u.Witness) -contains $c) { $wit += ,$o } } else { $cor += ,$o }
    }
    $res.NW = $wit.Count
    $wm = if ($u.WitMin) { [int]$u.WitMin } else { [int]$script:CalDriftMinWit }
    $d = 0.0; $s = 1.0
    if ($wit.Count -ge $wm) {
        $dw = @($wit | ForEach-Object { [double]$_.Obs })
        $d = [double](Get-Median $dw)
        $sr = 1.4826 * [double](Get-Median @($dw | ForEach-Object { [math]::Abs($_ - $d) }))
        $s = [math]::Max(1.0, $sr)
        $res.Use = $true; $res.D = $d; $res.S = $s; $res.SRaw = $sr; $res.E = 1.2533 * $s / [math]::Sqrt([double]$wit.Count)
    }
    # Verifications contradictoires (derive retiree si elle est mesuree) : candidats, puis zones
    $cnd = @{}
    foreach ($o in $cor) {
        $c = [int]$o.C; $p1 = [double]$o.P1; $p2 = [double]$o.P2; $r1 = [double]$o.R1; $r2 = [double]$o.R2 - $d
        $dir = [math]::Sign($p2 - $p1)
        # r2' hors tolerance du cote de p1 ; r1 hors tolerance : du cote de p2 (dans sa tolerance : tout signe)
        if ([math]::Sign($r2) -ne -$dir -or [math]::Abs($r2) -le (Get-ResidualTol $u.Verify[$c])) { continue }
        if ([math]::Abs($r1) -gt (Get-ResidualTol $u.VerifyPrev[$c].Meas) -and [math]::Sign($r1) -ne $dir) { continue }
        $z1 = $p1 - $r1 / $sl; $z2 = $p2 - $r2 / $sl
        # Ecart minimal : zeros a moins de la tolerance de la verification 1 (ns de precomp, pente sl comme E) : accord
        $tp = [double](Get-ResidualTol $u.VerifyPrev[$c].Meas) / [math]::Abs($sl)
        if ([double]::IsNaN($tp) -or [double]::IsInfinity($tp) -or $tp -le 0) { $tp = [double]$script:CalContraMinNs }
        $zp = $null
        if ($u.EstPass -and $u.EstPass.ContainsKey($c) -and -not [double]::IsNaN([double]$u.EstPass[$c])) { $zp = [double]$u.EstPass[$c] }
        $zm = if ($null -ne $zp) { [double](Get-Median @($zp, $z1, $z2)) } else { ($z1 + $z2) / 2.0 }
        $zm = [math]::Max([math]::Min($p1, $p2), [math]::Min([math]::Max($p1, $p2), $zm))
        $zc = [int][math]::Max(0, [math]::Min($script:CalHardNs, [math]::Round($zm, 0)))
        $cnd[$c] = @{ Z = $zc; Z1 = $z1; Z2 = $z2; ZP = $zp; E = [math]::Abs($z2 - $z1); P1 = $p1; P2 = $p2; Low = ([math]::Abs($z2 - $z1) -le $tp) }
    }
    # Zone : suite de candidats voisins (2 cylindres au plus, ou consecutifs parmi les cylindres relus) dont un au moins
    # depasse l ecart minimal ; une suite dont tous les candidats sont en accord n est pas une contradiction
    $rl = @(@($wit + $cor) | ForEach-Object { [int]$_.C } | Sort-Object)
    $kc = @($cnd.Keys | ForEach-Object { [int]$_ } | Sort-Object)
    $ia = 0
    while ($ia -lt $kc.Count) {
        $ja = $ia
        while ($ja -lt $kc.Count - 1 -and (($kc[$ja + 1] - $kc[$ja] -le 2) -or ([array]::IndexOf($rl, $kc[$ja + 1]) - [array]::IndexOf($rl, $kc[$ja]) -eq 1))) { $ja++ }
        $hi = $false; for ($q = $ia; $q -le $ja; $q++) { if (-not $cnd[$kc[$q]].Low) { $hi = $true } }
        if ($hi) { for ($q = $ia; $q -le $ja; $q++) { $ce = $cnd[$kc[$q]]; $res.Contra[$kc[$q]] = @{ Z = $ce.Z; Z1 = $ce.Z1; Z2 = $ce.Z2; ZP = $ce.ZP; E = $ce.E; P1 = $ce.P1; P2 = $ce.P2 } } }
        $ia = $ja + 1
    }
    # 12.9 (RT7) : zone gardee avant les cylindres non reproductibles, comme une zone de cette verification
    [void](Add-VerifyDriftHold $u $res @('Contra'))
    if (-not $res.Use) { return (Add-VerifyDriftHold $u $res @('NonRepro')) }
    $lim = [math]::Max(3.0 * [double]$script:CalResidual, 4.0 * $s)
    $cand = @{}
    foreach ($o in @($wit + $cor)) {
        if ($res.Contra.ContainsKey([int]$o.C)) { continue }                 # verifications contradictoires : mediane
        $ob = [double]$o.Obs - $d; $ex = [double]$o.Exp
        # A l inverse du changement prevu ; ou au-dela du changement prevu entier, r2' encore hors tolerance
        $nr = if ($ex -eq 0) { [math]::Abs($ob) -gt $lim } else {
            $sgx = [math]::Sign($ex)
            (($ob * $sgx) -lt (-$lim)) -or ((($ob * $sgx) -gt ([math]::Abs($ex) + $lim)) -and ([math]::Abs([double]$o.R2 - $d) -gt (Get-ResidualTol $u.Verify[[int]$o.C])))
        }
        if ($nr) { $cand[[int]$o.C] = $o }
    }
    # Suites de candidats voisins de meme sens : ecart systematique, pas une mesure non reproductible
    $cs = @($cand.Keys | ForEach-Object { [int]$_ } | Sort-Object)
    # Voisins : 2 cylindres au plus, ou consecutifs parmi les cylindres relus (test standard, un cylindre sur 10)
    $all = @(@($wit + $cor) | ForEach-Object { [int]$_.C } | Sort-Object)
    $i = 0
    while ($i -lt $cs.Count) {
        $j = $i
        while ($j -lt $cs.Count - 1 -and (($cs[$j + 1] - $cs[$j] -le 2) -or ([array]::IndexOf($all, $cs[$j + 1]) - [array]::IndexOf($all, $cs[$j]) -eq 1)) -and [math]::Sign([double]$cand[$cs[$j + 1]].Obs - $d - [double]$cand[$cs[$j + 1]].Exp) -eq [math]::Sign([double]$cand[$cs[$i]].Obs - $d - [double]$cand[$cs[$i]].Exp)) { $j++ }
        if ($j - $i + 1 -lt 3) {
            for ($q = $i; $q -le $j; $q++) { $o = $cand[$cs[$q]]; $res.NonRepro[[int]$cs[$q]] = @{ Z1 = [double]$o.P1 - [double]$o.R1 / $sl; Z2 = [double]$o.P2 - ([double]$o.R2 - $d) / $sl } }
        }
        else { for ($q = $i; $q -le $j; $q++) { $res.Sys[[int]$cs[$q]] = $true } }   # ecart systematique : juge sur la relecture
        $i = $j + 1
    }
    $kc = @($cor | Where-Object { -not $res.NonRepro.ContainsKey([int]$_.C) } | ForEach-Object { [double]$_.Obs - [double]$_.Exp })
    if ($kc.Count -gt 0) { $res.NC = $kc.Count; $res.DC = [double](Get-Median $kc) }
    return (Add-VerifyDriftHold $u $res @('NonRepro'))
}

function Add-VerifyDriftHold($u, $res, [string[]]$fields) {
    # 12.9 (RT7, L2-b) : un nouvel essai part malgre une zone non reproductible (Contra) ou des cylindres non reproductibles
    # (NonRepro) loin des cylindres vises ; sa passe ne garde dans VerifyPrev que les cylindres qu elle relit, et
    # Get-VerifyDrift ne verrait plus ces cylindres. Start-CalibRetest les garde (DriftHold : Contra, NonRepro, et P,
    # valeur ecrite de chacun a la derniere verification d avant) ; ils sont remis dans le resultat ($res, champs $fields)
    # tant que leur valeur ecrite n a pas change : cylindre non relu, ou relu a la meme valeur (temoin de derive, voisin
    # d un cylindre vise : rien de nouveau sur la contradiction). Relu a une autre valeur : juge sur la passe. Un cylindre
    # deja dans Contra ou NonRepro de $res y reste. Zone gardee trouvee sans derive mesuree (DriftHold.Use faux) :
    # ContraNoDrift, lu par la reserve de la zone (Complete-PrecompCalib, Get-CalibUnitReserve) a la place de Use, qui ne
    # vaut que pour la passe du nouvel essai. Sans DriftHold (aucun nouvel essai) : $res inchange. Renvoie $res
    $h = $u.DriftHold
    if (-not $h -or -not $h.P) { return $res }
    foreach ($f in @($fields)) {
        if (-not $h[$f]) { continue }
        foreach ($k in @($h[$f].Keys)) {
            $c = [int]$k
            if ($res.Contra.ContainsKey($c) -or $res.NonRepro.ContainsKey($c)) { continue }
            if (-not $h.P.ContainsKey($c) -or -not $u.VerifyP -or -not $u.VerifyP.ContainsKey($c) -or [int]$u.VerifyP[$c] -ne [int]$h.P[$c]) { continue }
            $res[$f][$c] = $h[$f][$k]
            if ($f -eq 'Contra' -and -not $h.Use) { $res.ContraNoDrift = $true }
        }
    }
    return $res
}

function Set-VerifyContra($u) {
    # Apres la derniere verification, avant le bilan : cylindres aux verifications contradictoires (Get-VerifyDrift) ramenes
    # a leur valeur retenue (mediane bornee a l intervalle des deux valeurs ecrites). Correction par segments de la courbe
    # (Add-CurveCorrection : 0 aux autres cylindres verifies, monotonie par segments conservee), nouveau profil ; pas de
    # nouvelle passe d ecriture. Les cylindres verifies hors zone sont des points fixes (residu mesure a leur valeur) : la
    # cible d un cylindre de la zone est bornee par ses voisins fixes du meme segment, dans le sens du segment, pour que le
    # lissage croissant ne deplace aucun d eux sans mesure. Filet : un cylindre fixe deplace malgre tout (test standard :
    # cylindre interpole entre la zone et lui) est releve dans ContraMoved (residu non enregistre, ligne de journal).
    # Renvoie le nombre de cylindres de la zone dont la valeur change.
    $u.ContraMoved = @()
    if (-not $u.Fit -or -not $u.Profile) { return 0 }
    $dft = Get-VerifyDrift $u
    if ($dft.Contra.Count -eq 0) { return 0 }
    $vals = @($u.Fit.Values); $delta = @{}; $n = 0
    foreach ($k in @($u.Verify.Keys)) {
        $c = [int]$k
        if (@($u.Outliers) -contains $c -or $c -ge $vals.Count) { continue }
        $delta[$c] = 0.0
    }
    $segs = if ($u.Fit.Segs) { @($u.Fit.Segs) } else { @(@{ Lo = 0; Hi = $vals.Count - 1; Dir = 1 }) }
    $fix = @($delta.Keys | ForEach-Object { [int]$_ } | Where-Object { -not $dft.Contra.ContainsKey($_) } | Sort-Object)
    foreach ($k in @($dft.Contra.Keys)) {
        $c = [int]$k
        if (-not $delta.ContainsKey($c)) { continue }
        $sg = $null; foreach ($g in $segs) { if ($c -ge [int]$g.Lo -and $c -le [int]$g.Hi) { $sg = $g; break } }
        $t = [double]$dft.Contra[$c].Z
        if ($sg) {
            # Voisins fixes du segment, a gauche et a droite ; segment decroissant : bornes inversees
            $fl = @($fix | Where-Object { $_ -ge [int]$sg.Lo -and $_ -lt $c }); $fr = @($fix | Where-Object { $_ -gt $c -and $_ -le [int]$sg.Hi })
            $a = if ($fl.Count) { [double]$vals[$fl[-1]] } else { $null }; $b = if ($fr.Count) { [double]$vals[$fr[0]] } else { $null }
            if ([int]$sg.Dir -lt 0) { $x = $a; $a = $b; $b = $x }
            if ($null -ne $a) { $t = [math]::Max($t, $a) }
            if ($null -ne $b) { $t = [math]::Min($t, $b) }
        }
        $delta[$c] = $t - [double]$vals[$c]; if ($delta[$c] -ne 0) { $n++ }
    }
    if ($n -eq 0) { return 0 }
    $newVals = Add-CurveCorrection $u.Fit.Values $delta $u.Fit.Segs
    $newProfile = Build-CurveProfile $newVals
    if ($newProfile -eq $u.Profile) { return 0 }
    $base = ([string]$u.Fit.Model) -replace '\+c$', ''
    $u.Fit = @{ Model = "$base+c"; A = $u.Fit.A; B = $u.Fit.B; Chi = $u.Fit.Chi; Values = $newVals; Breaks = $u.Fit.Breaks; Segs = $u.Fit.Segs; Outliers = $u.Fit.Outliers; Dents = @(Get-FitDents $u.Fit) }
    $u.Profile = $newProfile
    $u.ContraMoved = [int[]]@($fix | Where-Object { [int]$newVals[$_] -ne [int]$vals[$_] })
    return $n
}

function Get-ResidualFlags($u) {
    # Residus de la derniere verification. Bad : residu retenu (correction a la verification, non-convergence au bilan) ;
    # Spot : residu hors tolerance non retenu (ecart local, signale sans correction).
    # Voisinage d un cylindre : cylindres juges a 2 cylindres au plus (distance en cylindres, pas en rang) ; fenetre
    # tronquee, jamais decalee, la ou il en manque (debut ou fin de piste, cylindre non verifie, point isole, cylindre au
    # plafond ou au plancher). Points isoles et limites physiques (plafond, plancher) hors du jugement ; cylindres non
    # reproductibles et verifications contradictoires (Get-VerifyDrift) aussi, mais comptes comme voisins verifies.
    #  - Bruit : ecart-type robuste (MAD) des differences de residu entre cylindres juges consecutifs distants de 2 au
    #    plus, dans le meme segment de la courbe. Moins de CalNoiseMinDiffs differences (test standard, un cylindre sur
    #    10) : regle d origine, tout residu hors de sa tolerance est retenu.
    #  - Seuil d une moyenne de n residus : T(n) = max(CalResidual ; 3 bruits / racine de n). Residu tres grand :
    #    Hard = max(3 CalResidual ; 6 bruits).
    #  - Ecart : suite de cylindres juges consecutifs, distants de 2 au plus, hors tolerance, du meme
    #    signe ; un seul verdict par ecart. Retenu si l un de ses cylindres a moins de 2 voisins (cylindre epars : regle
    #    d origine, la courbe suit sa correction par interpolation entre cylindres verifies), une moyenne de voisinage
    #    au-dela de T, ou un residu au-dela de Hard ; ou si l ecart compte au moins 3 cylindres, ou 2 au bord (aucun
    #    cylindre juge du meme segment au-dela, a 2 cylindres au plus, d un cote : bout de piste, changement de sens,
    #    plafond : marche que la courbe peut suivre et que la fenetre ne peut pas confirmer), avec une moyenne au-dela de
    #    T(longueur) ; ou s il compte 2 cylindres de moyenne au-dela de Hard / racine de 2 (exigence d un residu seul
    #    au-dela de Hard, ramenee a la moyenne de 2).
    $vals = @($u.Fit.Values)
    $segs = @($u.Fit.Segs | Where-Object { $null -ne $_ })
    $pts = New-Object System.Collections.Generic.List[object]
    $dft = Get-VerifyDrift $u
    foreach ($c in @($u.Verify.Keys | ForEach-Object { [int]$_ } | Sort-Object)) {
        # Non reproductible, ou verifications contradictoires (zone non reproductible) : hors du jugement
        if (@($u.Outliers) -contains $c -or $dft.NonRepro.ContainsKey($c) -or $dft.Contra.ContainsKey($c)) { continue }
        $r = [double]$u.Verify[$c].Shift; $mz = $u.Verify[$c]
        # Temoin : valeur inchangee, juge sur sa mesure precedente (repere de la verification precedente, comme les cylindres
        # corriges une fois la derive retiree) ; sa relecture ne sert qu a mesurer la derive. Autre cylindre relu a la
        # derniere verification : juge sans la derive du lecteur mesuree sur les temoins
        if (@($u.Witness) -contains $c -and $u.VerifyPrev -and $u.VerifyPrev.ContainsKey($c) -and -not $dft.Sys.ContainsKey($c)) { $mz = $u.VerifyPrev[$c].Meas; $r = [double]$u.VerifyPrev[$c].Shift }
        elseif ($dft.Use -and $u.ReadLast -and $u.ReadLast.ContainsKey($c)) { $r -= [double]$dft.D }
        # Limites physiques (courbe au plafond encore sous-compensee, au plancher encore sur-compensee) : hors du jugement
        if ($c -lt $vals.Count -and (($r -gt 0 -and [int]$vals[$c] -ge $script:CalHardNs) -or ($r -lt 0 -and [int]$vals[$c] -le 0))) { continue }
        $sg = if ($segs.Count -gt 0) { -1 } else { 0 }
        for ($g = 0; $g -lt $segs.Count; $g++) { if ($c -ge [int]$segs[$g].Lo -and $c -le [int]$segs[$g].Hi) { $sg = $g; break } }
        $pts.Add(@{ C = $c; R = $r; S = $sg; Out = ([math]::Abs($r) -gt (Get-ResidualTol $mz)) })
    }
    $n = $pts.Count
    $bad = @{}; $spot = @()
    $res = @{ Bad = $bad; Spot = $spot; Sigma = [double]::NaN; NDiff = 0; Hard = [double]::NaN; HardPair = [double]::NaN }
    $d = @(for ($i = 1; $i -lt $n; $i++) { if ($pts[$i].S -eq $pts[$i - 1].S -and $pts[$i].C - $pts[$i - 1].C -le 2) { [double]$pts[$i].R - [double]$pts[$i - 1].R } })
    $res.NDiff = $d.Count
    if ($d.Count -lt $script:CalNoiseMinDiffs) {
        foreach ($p in $pts) { if ($p.Out) { $bad[$p.C] = $true } }
        return $res
    }
    $md = [double](Get-Median $d)
    $sig = 1.4826 * [double](Get-Median @($d | ForEach-Object { [math]::Abs($_ - $md) })) / [math]::Sqrt(2.0)
    $t0 = [double]$script:CalResidual
    $hard = [math]::Max(3.0 * $t0, 6.0 * $sig)
    # Voisinage : premier et dernier indice des cylindres juges a 2 cylindres au plus (fenetre tronquee, jamais decalee)
    $lo = New-Object int[] $n; $hi = New-Object int[] $n
    for ($i = 0; $i -lt $n; $i++) {
        $a = $i; while ($a -gt 0 -and $pts[$i].C - $pts[$a - 1].C -le 2) { $a-- }
        $b = $i; while ($b -lt $n - 1 -and $pts[$b + 1].C - $pts[$i].C -le 2) { $b++ }
        $lo[$i] = $a; $hi[$i] = $b
    }
    # Jugement de chaque cylindre hors tolerance d apres son voisinage
    $flag = New-Object bool[] $n
    for ($i = 0; $i -lt $n; $i++) {
        if (-not $pts[$i].Out) { continue }
        $k = $hi[$i] - $lo[$i] + 1
        # Un cylindre non reproductible (ou d une zone non reproductible), hors des moyennes, reste un voisin verifie (pas de
        # bascule dans la regle d origine)
        $kx = @(@($dft.NonRepro.Keys) + @($dft.Contra.Keys) | Where-Object { [math]::Abs([int]$_ - [int]$pts[$i].C) -le 2 }).Count
        if ($k + $kx -lt 3) { $flag[$i] = $true; continue }
        $s = 0.0; for ($j = $lo[$i]; $j -le $hi[$i]; $j++) { $s += [double]$pts[$j].R }
        $tl = [math]::Max($t0, 3.0 * $sig / [math]::Sqrt([double]$k))
        if ([math]::Abs($s / $k) -gt $tl -or [math]::Abs([double]$pts[$i].R) -gt $hard) { $flag[$i] = $true }
    }
    # Ecarts : suites de cylindres consecutifs, hors tolerance, du meme signe, qui peuvent franchir un bord de segment
    # (segment d un seul cylindre au pied d une chute franche) ; un seul verdict par ecart
    $i = 0
    while ($i -lt $n) {
        if (-not $pts[$i].Out) { $i++; continue }
        $j = $i
        while ($j -lt $n - 1 -and $pts[$j + 1].Out -and $pts[$j + 1].C - $pts[$j].C -le 2 -and [math]::Sign([double]$pts[$j + 1].R) -eq [math]::Sign([double]$pts[$i].R)) { $j++ }
        $k = $j - $i + 1
        $keep = $false; $s = 0.0
        for ($q = $i; $q -le $j; $q++) { if ($flag[$q]) { $keep = $true }; $s += [double]$pts[$q].R }
        if (-not $keep -and $k -ge 2) {
            # Au bord : aucun cylindre juge du meme segment au-dela de l ecart, a 2 cylindres au plus, d un cote
            $edge = ($i -eq 0 -or $pts[$i - 1].S -ne $pts[$i].S -or $pts[$i].C - $pts[$i - 1].C -gt 2 -or
                     $j -eq $n - 1 -or $pts[$j + 1].S -ne $pts[$j].S -or $pts[$j + 1].C - $pts[$j].C -gt 2)
            $thr = if ($edge -or $k -ge 3) { [math]::Max($t0, 3.0 * $sig / [math]::Sqrt([double]$k)) } else { $hard / [math]::Sqrt(2.0) }
            if ([math]::Abs($s / $k) -gt $thr) { $keep = $true }
        }
        for ($q = $i; $q -le $j; $q++) { if ($keep) { $bad[$pts[$q].C] = $true } else { $spot += $pts[$q].C } }
        $i = $j + 1
    }
    $res.Spot = $spot; $res.Sigma = $sig; $res.Hard = $hard; $res.HardPair = $hard / [math]::Sqrt(2.0)
    return $res
}

function Get-CalibWarnings($u, [int]$maxCyl) {
    # Bilan de fiabilite d une unite apres la derniere verification :
    #  NonConv : cylindres dont le residu de la derniere verification est retenu par Get-ResidualFlags (ecart regional,
    #            marche au bord, residu tres grand, cylindre epars) ; ou cylindres mesures que la derniere verification
    #            n a pas pu relire (correction eventuelle jamais verifiee) ;
    #  Spot    : ecarts locaux, hors tolerance mais non retenus par Get-ResidualFlags (signales, non corriges) ;
    #  Dev     : cylindres ou la courbe retenue s ecarte de l estimation de plus de max(15 ns ; 3 incertitudes),
    #            typiquement un besoin non croissant lisse par la contrainte croissante ;
    #  Sat     : cylindres encore sous-compenses alors que la valeur ecrite a la derniere verification est a la borne
    #            absolue CalHardNs : le besoin depasse la precomp maximale, une nouvelle calibration n y changera rien
    #            (exclus de NonConv) ;
    #  Floor   : cylindres encore sur-compenses avec une valeur ecrite a la derniere verification a 0 ns (plancher) : meme
    #            principe ;
    #  Beyond  : cylindres dont la courbe depasse le plafond des passes de mesure CalMaxNs (valeurs deduites des mesures,
    #            puis verifiees), information seulement ;
    #  Extrap / Cap : estimations extrapolees au-dela des mesures, ou plafonnees.
    #  Drift / NonRepro : derive du lecteur entre les deux verifications (temoins) et cylindres non reproductibles d une
    #            passe a l autre (Get-VerifyDrift) ; les residus relus a la derniere verification sont juges sans la derive.
    #  Contra  : zone non reproductible, verifications contradictoires (Get-VerifyDrift) : courbe a la mediane des passes de
    #            mesure et des deux verifications (Set-VerifyContra), hors du jugement de convergence (jamais Sat ni Floor :
    #            besoin entre les deux valeurs ecrites). Liste lue par Complete-PrecompCalib (journal, Res, champ contra).
    #  NonConvC / NonConvR (12.8, lot 1b) : cylindres de NonConv, et pour ceux qui ont un residu, le residu juge (R) et la
    #            valeur ecrite a sa mesure (P) : nouvel essai automatique (Get-CalibRetestPlan). Sans effet sur le reste.
    #  12.8 (FIXVAL01) : cylindre dont la valeur d avant le nouvel essai a ete retablie (RtKept, correction sans effet,
    #            Restore-CalibRetestNoEffect) et encore hors tolerance : NON CONVERGE (decisions128.md, « Lot 1b termine »),
    #            quel que soit le jugement de son voisinage apres la passe (ecart local, bruit) ; ni Spot, ni converge.
    #  12.9 (banc cal2, RT8, G4-02 ; revue fix2) : idem pour un cylindre exclu du nouvel essai, quel que soit le motif, et
    #            absent de la relecture de son jugement (RtFull, Start-CalibRetest : piste deja ecrite WriteMax fois, valeur
    #            visee hors des limites, proximite d une zone ou de cylindres non reproductibles, valeur visee inchangee de
    #            la mesure complete) : il garde le residu de la derniere verification d avant le nouvel essai.
    $nonConv = @(); $sat = @(); $floor = @(); $dev = @(); $extrap = @(); $cap = @(); $spot = @(); $beyond = @(); $nonRepro = @(); $contra = @()
    $ncC = @(); $ncR = @{}
    $rAll = @{}                         # 12.9 (L2-a) : residu juge de chaque cylindre verifie (Get-CalibNeedSteps)
    $outl = @{}; foreach ($c in @($u.Outliers)) { $outl[[int]$c] = $true }
    $kept = @{}; foreach ($c in @(@($u.RtKept) + @($u.RtFull))) { if ($null -ne $c) { $kept[[int]$c] = $true } }
    $vals = @($u.Fit.Values)
    $fl = Get-ResidualFlags $u
    $dft = Get-VerifyDrift $u
    foreach ($c in @($u.Verify.Keys | ForEach-Object { [int]$_ } | Sort-Object)) {
        if ($outl.ContainsKey($c)) { continue }
        $r = [double]$u.Verify[$c].Shift; $mz = $u.Verify[$c]
        if (@($u.Witness) -contains $c -and $u.VerifyPrev -and $u.VerifyPrev.ContainsKey($c) -and -not $dft.Sys.ContainsKey($c)) { $mz = $u.VerifyPrev[$c].Meas; $r = [double]$u.VerifyPrev[$c].Shift }
        elseif ($dft.Use -and $u.ReadLast -and $u.ReadLast.ContainsKey($c)) { $r -= [double]$dft.D }
        $out = [math]::Abs($r) -gt (Get-ResidualTol $mz)
        $rAll[$c] = $r
        # Limites physiques jugees a la valeur ecrite quand le residu a ete mesure (avant Set-VerifyContra) : une zone
        # non reproductible (besoin entre p1 et p2) n est jamais au plafond ni au plancher. VerifyP est rempli avec Verify ;
        # sans lui (unite sans valeurs ecrites), valeur de la courbe ; jamais de comparaison avec $null ($null -le 0 est vrai)
        $pw = $null
        if ($u.VerifyP -and $u.VerifyP.ContainsKey($c)) { $pw = [int]$u.VerifyP[$c] } elseif ($c -lt $vals.Count) { $pw = [int]$vals[$c] }
        if ($out -and $null -ne $pw -and $r -gt 0 -and $pw -ge $script:CalHardNs) { $sat += ("c{0} ({1:+0.0;-0.0})" -f $c, $r); continue }
        if ($out -and $null -ne $pw -and $r -lt 0 -and $pw -le 0) { $floor += ("c{0} ({1:+0.0;-0.0})" -f $c, $r); continue }
        if ($dft.Contra.ContainsKey($c)) { $contra += $c; continue }
        if ($dft.NonRepro.ContainsKey($c)) { $z = $dft.NonRepro[$c]; $nonRepro += ((T "c{0} ({1} puis {2} ns)") -f "$c", (Format-LevelNum $z.Z1), (Format-LevelNum $z.Z2)); continue }
        if ($out) {
            $txt = "c{0} ({1:+0.0;-0.0})" -f $c, $r
            if ($fl.Bad.ContainsKey($c) -or $kept.ContainsKey($c)) { $nonConv += $txt; $ncC += $c; $ncR[$c] = @{ R = $r; P = $pw } }
            else { $spot += $txt }            # ecart local non retenu par Get-ResidualFlags
        }
    }
    foreach ($c in @($u.Est.Keys | ForEach-Object { [int]$_ } | Sort-Object)) {
        if (-not $u.Verify.ContainsKey($c) -and -not $outl.ContainsKey($c)) { $nonConv += ("c{0} ({1})" -f $c, (T 'non relu')); $ncC += $c }
    }
    foreach ($c in @($u.Est.Keys | ForEach-Object { [int]$_ } | Sort-Object)) {
        if ($c -lt $vals.Count -and -not $outl.ContainsKey($c)) {
            $dv = $vals[$c] - [double]$u.Est[$c]
            if ([math]::Abs($dv) -gt [math]::Max($script:CalDevNs, 3.0 * [double]$u.Sig[$c])) { $dev += ("c{0} ({1:+0;-0})" -f $c, $dv) }
        }
        if ($u.Kind[$c] -eq 'extrap') { $extrap += "c$c" } elseif ($u.Kind[$c] -eq 'cap') { $cap += "c$c" }
    }
    # Cylindres a la borne absolue avec Sat : couverts par le message du plafond, ce ne sont pas des valeurs deduites
    for ($c = 0; $c -lt $vals.Count; $c++) { $x = [int]$vals[$c]; if ($x -gt $script:CalMaxNs -and ($x -lt $script:CalHardNs -or $sat.Count -eq 0)) { $beyond += $c } }
    # 12.9 (L2-a) : marches du besoin non suivies par la courbe autour des cylindres non converges (conseil seulement) ;
    # seuil de rupture de la courbe (Get-CalibCurve, 230) : max(CalDevNs ; 3 x racine de 2 x incertitude mediane)
    $ncS = [int[]]@($ncC | Sort-Object -Unique)
    $steps = @(); $brk = [double]$script:CalDevNs
    # 12.9 (correction 4) : dents presentes dans la courbe (confirmees, en attente, ou non confirmees a la derniere
    # verification et gardees) : suivies par la courbe, ni marche ni conseil L2-a. Toujours un tableau (unite convergee :
    # vide), jamais $null
    $dCur = @(Get-FitDents $u.Fit)
    if ($ncS.Count -gt 0 -and $u.Est) {
        $estOk = @{}; $sgs = @()
        foreach ($k in @($u.Est.Keys)) {
            $c = [int]$k
            if ($outl.ContainsKey($c)) { continue }
            $estOk[$c] = [double]$u.Est[$k]
            $sgs += $(if ($u.Sig -and $u.Sig.ContainsKey($k)) { [math]::Max(1.0, [double]$u.Sig[$k]) } else { 5.0 })
        }
        $brk = [math]::Max([double]$script:CalDevNs, 3.0 * [math]::Sqrt(2.0) * (Get-Median $sgs))
        $steps = @(Get-CalibNeedSteps $estOk $ncS $rAll $brk)
        if ($dCur.Count -gt 0) { $steps = @($steps | Where-Object { $st = $_; @($dCur | Where-Object { [int]$st.C1 -le [int]$_.C1 -and [int]$st.C2 -ge [int]$_.C2 }).Count -eq 0 }) }
    }
    return @{ NonConv = $nonConv; Sat = $sat; Floor = $floor; Dev = $dev; Extrap = $extrap; Cap = $cap; Isolated = @($u.Outliers | ForEach-Object { "c$_" }); Breaks = @($u.Fit.Breaks)
              Spot = $spot; Sigma = $fl.Sigma; NDiff = $fl.NDiff; Hard = $fl.Hard; HardPair = $fl.HardPair; Beyond = [int[]]$beyond
              Drift = $dft; NonRepro = $nonRepro; Contra = [int[]]$contra; NonConvC = $ncS; NonConvR = $ncR
              Steps = $steps; StepBreak = $brk; Dents = $dCur }
}

function Get-CalibNeedSteps($est, [int[]]$nc, $resid, [double]$maxDrop) {
    # 12.9 (L2-a, journaux du 27 et du 28/10/2026) : « marche non suivie ». Groupe de cylindres non converges contigus
    # (ecart de 2 au plus entre deux d entre eux, CalStepMaxCyl cylindres au plus d un bout a l autre), contre une baisse du
    # besoin estime entre deux cylindres voisins (2 au plus) d au moins max(CalDevNs / CalStepDevDiv ; CalResidual), soit
    # 5 ns en double densite et 4 ns en haute densite (synthese C, D3 : une marche plus petite que la tolerance des
    # residus n explique pas un residu hors tolerance)
    # et sous le seuil de rupture de la courbe ($maxDrop) : la courbe croissante garde un palier, les residus changent de
    # signe de part et d autre (moyenne des 3 cylindres verifies de chaque cote : positive avant, negative apres). Fonction
    # pure. $est, $resid : cylindre -> besoin estime, residu juge. Renvoie @( @{ C1 ; C2 ; Drop ; Cyls ; Dev } ) : marche
    # entre C1 et C2, baisse (ns), cylindres non converges du groupe, ecart absolu maximal de leurs residus
    $out = @()
    $s = [int[]]@($nc | Sort-Object -Unique)
    if ($s.Count -eq 0 -or -not $est) { return $out }
    $minStep = [math]::Max([double]$script:CalDevNs / [double]$script:CalStepDevDiv, [double]$script:CalResidual)
    $ek = [int[]]@($est.Keys | ForEach-Object { [int]$_ } | Sort-Object)
    $groups = @(); $g = @($s[0])
    for ($i = 1; $i -lt $s.Count; $i++) { if ($s[$i] - $s[$i - 1] -le 2) { $g += $s[$i] } else { $groups += , @($g); $g = @($s[$i]) } }
    $groups += , @($g)
    foreach ($gr in $groups) {
        $a = [int]$gr[0]; $b = [int]$gr[-1]
        if ($b - $a + 1 -gt [int]$script:CalStepMaxCyl) { continue }
        $best = $null
        for ($i = 0; $i -lt $ek.Count - 1; $i++) {
            $c1 = $ek[$i]; $c2 = $ek[$i + 1]
            if ($c2 - $c1 -gt 2 -or $c1 -lt $a - 1 -or $c1 -gt $b) { continue }
            $drop = [double]$est[$c1] - [double]$est[$c2]
            if ($drop -lt $minStep -or $drop -ge $maxDrop) { continue }
            $bef = @(); $aft = @()
            for ($q = $c1 - 2; $q -le $c1; $q++) { if ($resid.ContainsKey($q)) { $bef += [double]$resid[$q] } }
            for ($q = $c2; $q -le $c2 + 2; $q++) { if ($resid.ContainsKey($q)) { $aft += [double]$resid[$q] } }
            if ($bef.Count -eq 0 -or $aft.Count -eq 0) { continue }
            if (($bef | Measure-Object -Average).Average -le 0 -or ($aft | Measure-Object -Average).Average -ge 0) { continue }
            if (-not $best -or $drop -gt $best.Drop) { $best = @{ C1 = $c1; C2 = $c2; Drop = $drop } }
        }
        if (-not $best) { continue }
        $dev = 0.0
        foreach ($c in $gr) { if ($resid.ContainsKey([int]$c)) { $dev = [math]::Max($dev, [math]::Abs([double]$resid[[int]$c])) } }
        # Synthese C (D4) : cylindres non relus (sans residu) hors de l explication, ils gardent le conseil « refaire » ;
        # groupe sans aucun cylindre relu : pas de marche
        $rc = [int[]]@($gr | Where-Object { $resid.ContainsKey([int]$_) })
        if ($rc.Count -eq 0) { continue }
        $best.Cyls = $rc; $best.Dev = $dev
        $out += , $best
    }
    return $out
}

function Get-CalibDents($coarse, [double]$pooled, [int]$nPass, [double]$step, [int]$gap = 2, [int]$maxN = 4) {
    # 12.9 (correction 4 ; regle de v129\cal2\donnees\dent.py, find_dents, avec les correctifs de la revue du 31/10/2026) :
    # dents locales du besoin d une unite, mesurees par ses passes de mesure. $coarse : cylindre -> @( @{ P ; W ; Shift } ),
    # mesures de chaque passe (decalage de passe retire). Un cylindre compte s il a ses n mesures et si elles encadrent son
    # zero (au moins un decalage > 0 et un <= 0) : ailleurs le zero ponctuel serait extrapole loin des mesures (lecteur a fort
    # besoin) et sa chute ne se comparerait plus. Zero ponctuel de chaque passe : W + Shift / |pente propre du cylindre|
    # (moindres carres sur ses passes ; pente commune $pooled si elle n est pas nettement negative). Deux cylindres comptes
    # voisins c < c2 (ecart $gap au plus) : chute par passe d_p = z_p(c) - z_p(c2), insensible au decalage commun de la
    # passe. Dent si la chute moyenne atteint $step (seuil de marche), chaque passe $step / 2, et si la chute de c au
    # cylindre compte suivant c3 (ecart $gap au plus de c2) atteint encore $step / 2 : un point bas isole n est pas une
    # dent, et sans c3 (fin de liste) la persistance ne se controle pas : pas de dent. Aucune borne haute : une chute que
    # SegFit prend a son changement de sens (c43/c44) est rendue aussi, puis ecartee par Split-CurveDents (hors d un segment
    # croissant). $maxN dents au plus (les plus fortes). Fonction pure. Renvoie les dents @{ C1 ; C2 ; Drop ; Min ;
    # Conf = $null ; V = 0 ; DV = NaN }, par cylindre croissant
    $zp = @{}
    foreach ($k in @($coarse.Keys)) {
        $c = [int]$k
        $rs = @(@($coarse[$k]) | Where-Object { $null -ne $_ } | Sort-Object { [int]$_.P })
        if ($rs.Count -ne $nPass) { continue }
        $xs = [double[]]@($rs | ForEach-Object { [double]$_.W }); $ys = [double[]]@($rs | ForEach-Object { [double]$_.Shift })
        # Zero encadre par les passes de mesure elles-memes (un decalage de chaque signe)
        if (@($ys | Where-Object { $_ -gt 0 }).Count -eq 0 -or @($ys | Where-Object { $_ -le 0 }).Count -eq 0) { continue }
        $mx = 0.0; $my = 0.0; for ($i = 0; $i -lt $xs.Count; $i++) { $mx += $xs[$i]; $my += $ys[$i] }; $mx /= $xs.Count; $my /= $ys.Count
        $sxx = 0.0; $sxy = 0.0
        for ($i = 0; $i -lt $xs.Count; $i++) { $sxx += ($xs[$i] - $mx) * ($xs[$i] - $mx); $sxy += ($xs[$i] - $mx) * ($ys[$i] - $my) }
        $kc = if ($sxx -gt 0 -and $sxy / $sxx -lt -0.2) { $sxy / $sxx } else { $pooled }
        if ([math]::Abs($kc) -lt 1e-9) { continue }
        $zp[$c] = [double[]]@(for ($i = 0; $i -lt $xs.Count; $i++) { $xs[$i] + $ys[$i] / [math]::Abs($kc) })
    }
    $cs = [int[]]@($zp.Keys | Sort-Object)
    $found = @()
    for ($i = 0; $i -lt $cs.Count - 1; $i++) {
        $c = $cs[$i]; $c2 = $cs[$i + 1]
        if ($c2 - $c -gt $gap) { continue }
        $d = [double[]]@(for ($p = 0; $p -lt $nPass; $p++) { $zp[$c][$p] - $zp[$c2][$p] })
        $dm = ($d | Measure-Object -Average).Average; $dn = ($d | Measure-Object -Minimum).Minimum
        if ($dm -lt $step -or $dn -lt $step / 2.0) { continue }
        if ($i + 2 -ge $cs.Count -or $cs[$i + 2] - $c2 -gt $gap) { continue }
        $c3 = $cs[$i + 2]
        $d3 = (@(for ($p = 0; $p -lt $nPass; $p++) { $zp[$c][$p] - $zp[$c3][$p] }) | Measure-Object -Average).Average
        if ($d3 -lt $step / 2.0) { continue }
        $found += ,@{ C1 = $c; C2 = $c2; Drop = $dm; Min = $dn; Conf = $null; V = 0; DV = [double]::NaN }
    }
    $sel = @($found | Sort-Object @{ Expression = { -[double]$_.Drop } }, @{ Expression = { [int]$_.C1 } } | Select-Object -First ([math]::Max(0, $maxN)))
    return @($sel | Sort-Object @{ Expression = { [int]$_.C1 } })
}

function Update-CalibDents($u, [int]$vNum, [bool]$last, [int[]]$readNow) {
    # 12.9 (correction 4) : confirmation des dents de la courbe par la verification $vNum : dent en attente (Conf $null)
    # dont les deux cylindres ont ete relus a cette passe ; zeros de la verification (valeur ecrite - residu / pente de
    # l unite), baisse z(C1) - z(C2) : confirmee a partir de CalDentConfNs, sinon retiree (segments fusionnes,
    # Merge-CurveDentSegs) ; le decalage commun de la passe s annule dans la difference. Derniere verification : dent non
    # confirmee gardee dans la courbe (aucune passe pour la corriger), marquee non confirmee. Renvoie $true si une dent a ete
    # retiree avant la derniere verification (courbe a reajuster)
    $dl = @(Get-FitDents $u.Fit)
    if ($dl.Count -eq 0) { return $false }
    $sl = if ($null -ne $u.Slope -and [double]$u.Slope -lt -0.2) { [double]$u.Slope } else { -2.0 }
    $thr = [double]$script:CalDentConfNs
    $keep = @(); $redo = $false
    foreach ($d in $dl) {
        if ($null -ne $d.Conf) { $keep += ,$d; continue }
        $c1 = [int]$d.C1; $c2 = [int]$d.C2
        if ($readNow -notcontains $c1 -or $readNow -notcontains $c2 -or -not $u.Verify.ContainsKey($c1) -or -not $u.Verify.ContainsKey($c2) -or -not $u.VerifyP.ContainsKey($c1) -or -not $u.VerifyP.ContainsKey($c2)) { $keep += ,$d; continue }
        $dv = ([double]$u.VerifyP[$c1] - [double]$u.Verify[$c1].Shift / $sl) - ([double]$u.VerifyP[$c2] - [double]$u.Verify[$c2].Shift / $sl)
        $d.V = $vNum; $d.DV = $dv
        if ($dv -ge $thr) {
            $d.Conf = $true; $keep += ,$d
            Append-Log ($u.Prefix + ((T "Dent entre c{0} et c{1} confirmée par la vérification {2} : baisse de {3} ns entre leurs zéros mesurés (au moins {4} ns exigés).") -f "$c1", "$c2", "$vNum", (Format-LevelNum $dv), (Format-LevelNum $thr)))
            continue
        }
        $d.Conf = $false
        if ($last) {
            $keep += ,$d
            Append-Log ($u.Prefix + ((T "Dent entre c{0} et c{1} non confirmée par la dernière vérification ({2} ns, moins de {3} ns) : la courbe reste telle quelle, ses résidus sont jugés normalement.") -f "$c1", "$c2", (Format-LevelNum $dv), (Format-LevelNum $thr)))
            continue
        }
        Append-Log ($u.Prefix + ((T "Dent entre c{0} et c{1} non confirmée par la vérification {2} : baisse de {3} ns entre leurs zéros mesurés, moins de {4} ns ; elle est retirée et la courbe est réajustée sans elle.") -f "$c1", "$c2", "$vNum", (Format-LevelNum $dv), (Format-LevelNum $thr)))
        $u.Fit.Segs = @(Merge-CurveDentSegs $u.Fit.Segs $c1 $c2)
        $redo = $true
    }
    $u.Fit.Dents = $keep
    return $redo
}

function Get-CalibUnitReserve($w) {
    # 12.9 (L2-d) : cylindres en reserve d une unite (Get-CalibWarnings) : non converges (NC), et cylindres de la zone non
    # reproductible (Zone) quand ils figurent aux reserves (Complete-PrecompCalib : ecart entre les verifications au-dela
    # de CalContraMaxNs, ou derive du lecteur non mesuree). Renvoie @{ NC ; Zone }
    $res = @{ NC = [int[]]@(); Zone = [int[]]@() }
    if (-not $w) { return $res }
    $res.NC = [int[]]@(@($w.NonConvC) | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_ } | Sort-Object -Unique)
    $cn = [int[]]@(@($w.Contra) | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_ } | Sort-Object -Unique)
    if ($cn.Count -gt 0) {
        $dft = $w.Drift; $em = 0.0
        foreach ($c in $cn) { if ($dft -and $dft.Contra -and $dft.Contra.ContainsKey($c)) { $em = [math]::Max($em, [double]$dft.Contra[$c].E) } }
        # 12.9 (RT7) : zone gardee d avant un nouvel essai, trouvee sans derive mesuree (ContraNoDrift, Add-VerifyDriftHold)
        if ($em -gt [double]$script:CalContraMaxNs -or -not ($dft -and $dft.Use -and -not $dft.ContraNoDrift)) { $res.Zone = $cn }
    }
    return $res
}

function Get-CalibCommonReserve($ra, $rb) {
    # 12.9 (L2-d) : reserves des calibrations A et B (Get-CalibUnitReserve, meme unite) aux memes cylindres, a 1 pres : un
    # cylindre non converge de l une a 1 cylindre au plus d un cylindre en reserve de l autre (non converge, ou zone non
    # reproductible en reserve ; deux zones seules ne suffisent pas). Les groupes de cylindres non converges touches
    # (ecart de 2 au plus) sont repris en entier. Fonction pure. Renvoie les cylindres tries (vide : aucun)
    $mark = @{}
    foreach ($pair in @(@($ra, $rb), @($rb, $ra))) {
        $x = $pair[0]; $y = $pair[1]
        $yAll = @(@($y.NC) + @($y.Zone) | ForEach-Object { [int]$_ })
        $xs = [int[]]@(@($x.NC) | ForEach-Object { [int]$_ } | Sort-Object -Unique)
        $hit = @{}
        foreach ($c in $xs) {
            foreach ($d in $yAll) {
                if ([math]::Abs($c - $d) -le 1) { $hit[$c] = $true; $mark[$c] = $true; if (@($y.NC) -contains $d -or @($y.Zone) -contains $d) { $mark[$d] = $true } }
            }
        }
        # Groupes de non converges de $x touches : repris en entier
        if ($xs.Count -gt 0) {
            $g = @($xs[0])
            for ($i = 1; $i -le $xs.Count; $i++) {
                if ($i -lt $xs.Count -and $xs[$i] - $xs[$i - 1] -le 2) { $g += $xs[$i]; continue }
                if (@($g | Where-Object { $hit.ContainsKey([int]$_) }).Count -gt 0) { foreach ($c in $g) { $mark[[int]$c] = $true } }
                if ($i -lt $xs.Count) { $g = @($xs[$i]) }
            }
        }
    }
    return [int[]]@($mark.Keys | ForEach-Object { [int]$_ } | Sort-Object)
}

function Split-CalibRetestZone([int[]]$nc, [int[]]$zone, [int]$reach = 2) {
    # 12.9 (L2-b) : nouvel essai d une unite qui a une zone non reproductible (ou des cylindres non reproductibles) : seuls
    # les cylindres non converges a $reach cylindres au plus d un cylindre de la zone en sont exclus, et non plus toute
    # l unite. Fonction pure. Renvoie @{ Keep ; Excl ; Near (cylindres de la zone qui excluent) }
    $keep = @(); $excl = @(); $near = @{}
    foreach ($c in @($nc)) {
        $z = @(@($zone) | Where-Object { [math]::Abs([int]$_ - [int]$c) -le $reach })
        if ($z.Count -gt 0) { $excl += [int]$c; foreach ($d in $z) { $near[[int]$d] = $true } } else { $keep += [int]$c }
    }
    return @{ Keep = [int[]]$keep; Excl = [int[]]$excl; Near = [int[]]@($near.Keys | ForEach-Object { [int]$_ } | Sort-Object) }
}

function Get-KindName([string]$k) {
    switch ($k) { 'interp' { return (T 'encadrée') } 'extrap' { return (T 'extrapolée') } 'cap' { return (T 'plafonnée') } 'outlier' { return (T 'isolée') } default { return '' } }
}

function Test-CurvePointFlag($cv, [int]$i) {
    # Point dont la courbe s ecarte de plus de max(15 ns ; 3 incertitudes) ; 12.7 : 15 ns en double densite, ecart notable
    # du bareme de sa famille (Get-CurveDevNs)
    $c = [int]$cv.Cyls[$i]; $v = @($cv.Values)
    if ($c -ge $v.Count) { return $false }
    if ($cv.Kinds -and $i -lt @($cv.Kinds).Count -and [string]$cv.Kinds[$i] -eq 'outlier') { return $false }
    return ([math]::Abs($v[$c] - [double]$cv.Ys[$i]) -gt [math]::Max((Get-CurveDevNs $cv), 3.0 * [double]$cv.Sig[$i]))
}

# 12.7 point 2 : comparaison de deux calibrations (« Refaire sur une autre disquette ») : fonctions pures, appelees
# par Complete-PrecompCalib, Complete-CalibRedo et Start-PrecompCalib. Aucune valeur de courbe n en depend.
function ConvertTo-EstRecords($cv) {
    # Estimations d une courbe enregistree : cylindre -> @{ Est ; Sig ; Kind }
    $d = @{}
    if (-not $cv -or -not $cv.Cyls -or -not $cv.Ys) { return $d }
    for ($i = 0; $i -lt @($cv.Cyls).Count; $i++) {
        $k = if ($cv.Kinds -and $i -lt @($cv.Kinds).Count) { [string]$cv.Kinds[$i] } else { 'interp' }
        $s = if ($cv.Sig -and $i -lt @($cv.Sig).Count) { [double]$cv.Sig[$i] } else { 5.0 }
        $d[[int]$cv.Cyls[$i]] = @{ Est = [double]$cv.Ys[$i]; Sig = $s; Kind = $k }
    }
    return $d
}

function Get-UnitEstRecords($u) {
    # Estimations d une unite de calibration (toutes passes) : cylindre -> @{ Est ; Sig ; Kind }
    $d = @{}
    foreach ($c in @($u.Est.Keys)) {
        $s = if ($u.Sig.ContainsKey($c)) { [double]$u.Sig[$c] } else { 5.0 }
        $d[[int]$c] = @{ Est = [double]$u.Est[$c]; Sig = $s; Kind = [string]$u.Kind[$c] }
    }
    return $d
}

function Get-FaceEstimates($u) {
    # Zero de chaque face d une unite d apres les seules passes de mesure gardees par face (u.Face : face -> cylindre ->
    # precomp -> @{ Shift ; SE }), pente commune de l unite ; comparaison de deux calibrations seulement, sans effet sur
    # la courbe. Renvoie face -> (cylindre -> @{ Est ; Sig ; Kind }).
    $res = @{}
    $sl = if ($null -ne $u.Slope -and [double]$u.Slope -lt -0.2) { [double]$u.Slope } else { -2.0 }
    foreach ($h in @($u.Face.Keys)) {
        $d = @{}
        foreach ($c in @($u.Face[$h].Keys)) {
            $z = Get-CalibZero $u.Face[$h][$c] $sl
            if ($z) { $d[[int]$c] = @{ Est = [double]$z.Est; Sig = [double]$z.Sig; Kind = [string]$z.Kind } }
        }
        $res[[int]$h] = $d
    }
    return $res
}

function Compare-CurveRecords($X, $Y) {
    # Ecart de Y a X (ns de precomp) sur leurs cylindres encadres communs : niveau (moyenne des differences), forme
    # (ecart-type apres retrait du niveau), bruit sigma (1,4826 MAD des differences d ecart entre cylindres distants de 2
    # au plus, divise par racine 2, 10 differences au moins ; a defaut, mediane des incertitudes combinees), zones de
    # desaccord (CalCmpMinN cylindres consecutifs ou plus, meme signe, chacun au-dela de CalCmpPointNs, moyenne au-dela de
    # max(CalCmpZoneNs ; 3 sigma / racine n)) et ecarts ponctuels (au-dela de max(CalCmpSpotNs ; 4 sigma), hors zone).
    # $null si moins de 4 cylindres communs.
    $cs = @(@($X.Keys) | ForEach-Object { [int]$_ } | Where-Object { $Y.ContainsKey($_) -and [string]$X[$_].Kind -eq 'interp' -and [string]$Y[$_].Kind -eq 'interp' } | Sort-Object)
    if ($cs.Count -lt 4) { return $null }
    $d = @{}; foreach ($c in $cs) { $d[$c] = [double]$Y[$c].Est - [double]$X[$c].Est }
    $lvl = (@($cs | ForEach-Object { $d[$_] }) | Measure-Object -Average).Average
    $e = @{}; $q = 0.0
    foreach ($c in $cs) { $e[$c] = $d[$c] - $lvl; $q += $e[$c] * $e[$c] }
    $sd = [math]::Sqrt($q / ($cs.Count - 1))
    $df = @(); for ($i = 0; $i -lt $cs.Count - 1; $i++) { if ($cs[$i + 1] - $cs[$i] -le 2) { $df += $e[$cs[$i + 1]] - $e[$cs[$i]] } }
    if ($df.Count -ge 10) { $m = Get-Median $df; $sig = 1.4826 * (Get-Median @($df | ForEach-Object { [math]::Abs($_ - $m) })) / [math]::Sqrt(2.0) }
    else { $sig = Get-Median @($cs | ForEach-Object { [math]::Sqrt([double]$X[$_].Sig * [double]$X[$_].Sig + [double]$Y[$_].Sig * [double]$Y[$_].Sig) }) }
    $zones = @(); $run = @()
    foreach ($c in @($cs + @(-1))) {   # -1 : sentinelle de fin
        $ok = ($c -ge 0) -and ([math]::Abs($e[$c]) -gt $script:CalCmpPointNs)
        if ($ok -and $run.Count -gt 0 -and (($e[$c] -gt 0) -eq ($e[$run[-1]] -gt 0))) { $run += $c; continue }
        if ($run.Count -ge $script:CalCmpMinN) {
            $ma = (@($run | ForEach-Object { [math]::Abs($e[$_]) }) | Measure-Object -Average).Average
            if ($ma -gt [math]::Max($script:CalCmpZoneNs, 3.0 * $sig / [math]::Sqrt($run.Count))) {
                $zones += @{ Lo = [int]$run[0]; Hi = [int]$run[-1]; N = $run.Count; Mean = (@($run | ForEach-Object { $e[$_] }) | Measure-Object -Average).Average }
            }
        }
        $run = @(); if ($ok) { $run = @($c) }   # affectation directe : un if deroulerait le tableau d un element
    }
    $spotT = [math]::Max($script:CalCmpSpotNs, 4.0 * $sig)
    $spots = @($cs | Where-Object { $cc = $_; [math]::Abs($e[$cc]) -gt $spotT -and @($zones | Where-Object { $cc -ge $_.Lo -and $cc -le $_.Hi }).Count -eq 0 } | ForEach-Object { @{ C = [int]$_; E = $e[$_] } })
    # Ecart maximal : a egalite, le plus petit cylindre (Sort-Object n est pas stable sous Windows PowerShell 5.1)
    $mc = @($cs | Sort-Object @{ Expression = { -[math]::Abs($e[$_]) } }, @{ Expression = { $_ } })[0]
    return @{ N = $cs.Count; Level = $lvl; Shape = $sd; Sigma = $sig; Zones = $zones; Spots = $spots; MaxC = [int]$mc; MaxE = $e[$mc] }
}

function Test-CalibRedoOffer([bool]$restore, [bool]$redoActive, [string[]]$kinds) {
    # Bouton « Refaire sur une autre disquette » : hors restauration et hors calibration B, pour une reserve qui peut venir
    # du support (toutes sauf la derive du lecteur, la courbe eloignee des mesures et, 12.7, la vitesse du lecteur)
    if ($restore -or $redoActive) { return $false }
    return (@(@($kinds) | Where-Object { $_ -and @('drift', 'dev', 'speed') -notcontains $_ }).Count -gt 0)
}

function Get-CalibRedoPick($dA, $dB, $sA, $sB, $surfA, $surfB, [int]$supA, [int]$supB, [int]$ncA, [int]$ncB, [bool]$zone) {
    # Courbe conseillee. Zone de desaccord entre A et B ($zone) : 1) ecart local moyen a la calibration precedente sur les
    # cylindres de la zone, niveau retire ($dA, $dB ; $null : non comparable), plus faible d au moins CalCmpLocalNs ; sinon
    # 2) seule disquette sans defaut au controle de surface ; sinon aucune (zone non attribuable). Sans zone : 1) forme
    # globale la plus proche de la calibration precedente ($sA, $sB), plus faible d au moins max(CalCmpPrefNs ;
    # CalCmpPrefFrac x l autre) ; 2) controle de surface ; 3) moins de reserves liees au support ; 4) moins de cylindres non
    # converges. Renvoie @{ Pick = 'A' | 'B' | $null ; By = 'zone' | 'prev' | 'surface' | 'support' | 'nonconv' | '' }
    $dfA = [bool]($surfA -and $surfA.Defective); $dfB = [bool]($surfB -and $surfB.Defective)
    $surfPick = $null
    if ($surfA -and $surfB -and $dfA -ne $dfB) { $surfPick = if ($dfA) { 'B' } else { 'A' } }
    if ($zone) {
        if ($null -ne $dA -and $null -ne $dB) {
            if ([double]$dA - [double]$dB -ge $script:CalCmpLocalNs) { return @{ Pick = 'B'; By = 'zone' } }
            if ([double]$dB - [double]$dA -ge $script:CalCmpLocalNs) { return @{ Pick = 'A'; By = 'zone' } }
        }
        if ($surfPick) { return @{ Pick = $surfPick; By = 'surface' } }
        return @{ Pick = $null; By = '' }
    }
    if ($null -ne $sA -and $null -ne $sB) {
        if ([double]$sB -le [double]$sA - [math]::Max($script:CalCmpPrefNs, $script:CalCmpPrefFrac * [double]$sA)) { return @{ Pick = 'B'; By = 'prev' } }
        if ([double]$sA -le [double]$sB - [math]::Max($script:CalCmpPrefNs, $script:CalCmpPrefFrac * [double]$sB)) { return @{ Pick = 'A'; By = 'prev' } }
    }
    if ($surfPick) { return @{ Pick = $surfPick; By = 'surface' } }
    if ($supA -ne $supB) { return @{ Pick = $(if ($supA -lt $supB) { 'A' } else { 'B' }); By = 'support' } }
    if ($ncA -ne $ncB) { return @{ Pick = $(if ($ncA -lt $ncB) { 'A' } else { 'B' }); By = 'nonconv' } }
    return @{ Pick = $null; By = '' }
}

function Get-CalibUnitKey($cal, $u) {
    # Cle de courbe d une unite de calibration : famille (courbe commune) ou famille_hN (une courbe par tete)
    if ($null -eq $u.Head) { return [string]$cal.Family }
    return "$($cal.Family)_h$($u.Head)"
}

function Get-CalibRedoMismatch($A, [string]$family, [int[]]$cyls, [bool]$slow, [bool]$fine, [string]$drive, [string]$img, $geom) {
    # Controle d identite de la calibration B avant le premier gw : '' si ses reglages sont ceux de la calibration A,
    # sinon le nom du premier reglage different
    if ([string]$A.Drive -ne $drive) { return (T 'lecteur') }
    if (([string]$A.Mode -eq 'fine') -ne $fine) { return (T 'mode de test') }
    if ([bool]$A.Slow -ne $slow) { return (T 'courbe par tête') }
    if ([string]$A.Family -ne $family) { return (T 'famille') }
    # Cylindres de test de depart de A (Cyls0) : Cyls s etend aux mesures complementaires du test standard (Start-CalibDensify)
    $a0 = if ($null -ne $A.Cyls0) { @($A.Cyls0) } else { @($A.Cyls) }
    if (($a0 -join ',') -ne (@($cyls) -join ',')) { return (T 'cylindres de test') }
    if ([bool]$A.Home -ne [bool]$geom) { return (T 'type de disquette') }
    if ($A.Home -and [string]$A.Geom.Fmt -ne [string]$geom.Fmt) { return (T 'type de disquette') }
    if (-not $A.Home -and [string]$A.Image -ne $img) { return (T 'image') }
    return ''
}

function Format-CalibSurfaceState($sf) {
    # Etat du controle de surface d une calibration, pour la fenetre de comparaison
    if (-not $sf) { return (T 'non fait') }
    $nb = @($sf.Bad).Count
    if ($sf.Defective) { return ((T "disquette douteuse, {0} piste(s) défectueuse(s)") -f "$nb") }
    if ($nb -gt 0) { return ((T "{0} piste(s) défectueuse(s)") -f "$nb") }
    return (T 'aucun défaut')
}

function Get-CalibRedoReport($r, $cal, [string[]]$issues, [string[]]$kinds) {
    # Comparaison des calibrations A ($r = $script:CalRedo : objet $cal de A, courbes et reserves) et B ($cal, deja
    # enregistree dans PrecompCurves), sans fusion : par face, niveau, forme, zones de desaccord et ecarts ponctuels sur
    # les estimations des passes de mesure (Get-FaceEstimates) ; par courbe, ecart des valeurs appliquees ; forme de A et
    # de B face a la calibration d avant A ; courbe conseillee (Get-CalibRedoPick). Rien n est enregistre : journal seul.
    # Renvoie @{ Text ; Log ; Curves (copies A puis B, champ Series) ; Zones (@{ Lo ; Hi ; Head }) ; Pick }.
    $A = $r.ACal
    $sup = @('nonconv', 'sat', 'floor', 'contra', 'contra-nodrift', 'surface')
    $k0 = Get-CalibUnitKey $cal $cal.Units[0]
    $bDate = if ($script:PrecompCurves[$k0]) { [string]$script:PrecompCurves[$k0].Date } else { '' }
    $L = New-Object System.Collections.Generic.List[string]
    $L.Add(((T "Comparaison des calibrations A ({0}) et B ({1}) du lecteur {2}, faites avec les mêmes réglages sur deux disquettes :") -f "$($r.ADate)", "$bDate", "$($cal.Drive)"))
    $zd = @(); $flag = @(); $maxShape = 0.0; $maxLvl = 0.0; $nCmp = 0
    for ($i = 0; $i -lt @($A.Units).Count; $i++) {
        $ua = $A.Units[$i]; $ub = $cal.Units[$i]
        $fa = Get-FaceEstimates $ua; $fb = Get-FaceEstimates $ub
        foreach ($h in 0, 1) {
            # Face absente des deux calibrations (unite de l autre tete) : rien ; absente d une seule : trop peu de cylindres
            if (-not $fa.ContainsKey($h) -and -not $fb.ContainsKey($h)) { continue }
            $c = if ($fa.ContainsKey($h) -and $fb.ContainsKey($h)) { Compare-CurveRecords $fa[$h] $fb[$h] } else { $null }
            if (-not $c) { $L.Add('  ' + ((T "face {0} : trop peu de cylindres encadrés par les deux calibrations pour les comparer") -f "$h")); continue }
            $nCmp++
            $zt = if (@($c.Zones).Count) { (T "zones de désaccord : {0}") -f ((@($c.Zones) | ForEach-Object { "c$($_.Lo)-c$($_.Hi) ($('{0:+0;-0;0}' -f [math]::Round($_.Mean)) ns)" }) -join ', ') } else { (T 'aucune zone de désaccord') }
            if (@($c.Spots).Count) { $zt += ' ; ' + ((T "écarts ponctuels : {0}") -f ((@($c.Spots) | ForEach-Object { "c$($_.C) ($('{0:+0;-0;0}' -f [math]::Round($_.E)) ns)" }) -join ', ')) }
            $L.Add('  ' + ((T "face {0} : niveau B − A {1} ns, écart de forme {2} ns (au plus {3} ns à c{4}), {5}") -f "$h", ('{0:+0;-0;0}' -f [math]::Round($c.Level)), (Format-UiNum $c.Shape), (Format-UiNum ([math]::Round([double]$c.MaxE, 1)) '+0.#;-0.#;0'), "$($c.MaxC)", $zt))
            foreach ($z in @($c.Zones)) { $zd += @{ Lo = [int]$z.Lo; Hi = [int]$z.Hi; Head = $h; Unit = $i }; $flag += ((T "face {0} : {1}") -f "$h", "c$($z.Lo)-c$($z.Hi)") }
            foreach ($s in @($c.Spots)) { $zd += @{ Lo = [int]$s.C; Hi = [int]$s.C; Head = $h; Unit = $i }; $flag += ((T "face {0} : {1}") -f "$h", "c$($s.C)") }
            if ($c.Shape -gt $maxShape) { $maxShape = $c.Shape }
            if ([math]::Abs($c.Level) -gt $maxLvl) { $maxLvl = [math]::Abs($c.Level) }
        }
        $key = Get-CalibUnitKey $cal $ub
        $cvA = $r.ACurves[$key]; $cvB = $script:PrecompCurves[$key]
        if ($cvA -and $cvB) {
            $pa = @($cvA.Values); $pb = @($cvB.Values); $nn = [math]::Min($pa.Count, $pb.Count)
            if ($nn -gt 0) {
                $dd = @(for ($k = 0; $k -lt $nn; $k++) { [int]$pb[$k] - [int]$pa[$k] }) | Measure-Object -Average -Minimum -Maximum
                $L.Add('  ' + ((T "{0}courbe B − A : de {1} à {2} ns, {3} ns en moyenne") -f "$($ub.Prefix)", ('{0:+0;-0;0}' -f $dd.Minimum), ('{0:+0;-0;0}' -f $dd.Maximum), ('{0:+0;-0;0}' -f [math]::Round($dd.Average))))
            }
        }
    }
    if ([string]$A.Mode -eq 'std') { $L.Add((T "Test standard : la comparaison ne porte que sur les cylindres testés ; un défaut situé entre deux cylindres testés n'est pas vu.")) }
    $L.Add(((T "Réserves de A : {0}") -f $(if (@($r.AIssues).Count) { @($r.AIssues) -join ' ; ' } else { (T 'aucune') })))
    $L.Add(((T "Réserves de B : {0}") -f $(if (@($issues).Count) { @($issues) -join ' ; ' } else { (T 'aucune') })))
    $L.Add(((T "Contrôle de surface de la première passe : A {0} ; B {1}.") -f (Format-CalibSurfaceState $A.Surf), (Format-CalibSurfaceState $cal.Surf)))
    # Calibration d avant A (meme lecteur, motif de test) : forme de A et de B, niveau retire
    $sA = @(); $sB = @(); $pvWhy = ''; $pvDate = ''; $pvDrive = ''; $lA = @(); $lB = @()
    for ($i = 0; $i -lt @($A.Units).Count; $i++) {
        $pv = $r.PrevA.Curves[(Get-CalibUnitKey $cal $cal.Units[$i])]
        if (-not $pv) { $pvWhy = 'none'; break }
        if ([string]$pv.Drive -ne [string]$A.Drive) { $pvWhy = 'drive'; $pvDrive = [string]$pv.Drive; break }
        if ($pv.Method -and [string]$pv.Method -ne 'motif') { $pvWhy = 'content'; break }
        $pr = ConvertTo-EstRecords $pv; $xa = Get-UnitEstRecords $A.Units[$i]; $xb = Get-UnitEstRecords $cal.Units[$i]
        $ca = Compare-CurveRecords $pr $xa; $cb = Compare-CurveRecords $pr $xb
        if (-not $ca -or -not $cb) { $pvWhy = 'few'; break }
        $sA += $ca.Shape; $sB += $cb.Shape; $pvDate = [string]$pv.Date
        # Zones et ecarts ponctuels de cette unite : ecart local de A et de B a la calibration precedente, niveau retire
        foreach ($z in @($zd | Where-Object { $_.Unit -eq $i })) {
            for ($c = $z.Lo; $c -le $z.Hi; $c++) {
                if (-not $pr.ContainsKey($c) -or -not $xa.ContainsKey($c) -or -not $xb.ContainsKey($c)) { continue }
                if ([string]$pr[$c].Kind -ne 'interp' -or [string]$xa[$c].Kind -ne 'interp' -or [string]$xb[$c].Kind -ne 'interp') { continue }
                $lA += [math]::Abs(([double]$xa[$c].Est - [double]$pr[$c].Est) - $ca.Level)
                $lB += [math]::Abs(([double]$xb[$c].Est - [double]$pr[$c].Est) - $cb.Level)
            }
        }
    }
    $mA = $null; $mB = $null; $dA = $null; $dB = $null
    if (-not $pvWhy) {
        $mA = ($sA | Measure-Object -Average).Average; $mB = ($sB | Measure-Object -Average).Average
        $L.Add(((T "Écart de forme avec la calibration précédente du {0} : A {1} ns, B {2} ns.") -f "$pvDate", (Format-UiNum $mA), (Format-UiNum $mB)))
        if ($lA.Count -gt 0) {
            $dA = ($lA | Measure-Object -Average).Average; $dB = ($lB | Measure-Object -Average).Average
            $L.Add(((T "Sur les cylindres en désaccord, écart à la calibration précédente du {0}, niveau retiré : A {1} ns, B {2} ns.") -f "$pvDate", (Format-UiNum $dA), (Format-UiNum $dB)))
        }
    } else {
        switch ($pvWhy) {
            'none'    { $L.Add((T 'Aucune calibration précédente de cette famille : pas de comparaison de forme avec elle.')) }
            'drive'   { $L.Add(((T "La calibration précédente de cette famille vient du lecteur {0} : elle ne sert pas de comparaison.") -f "$pvDrive")) }
            'content' { $L.Add((T "La calibration précédente a été mesurée sur le contenu d'une image : elle ne sert pas de comparaison.")) }
            default   { $L.Add((T 'Trop peu de cylindres encadrés en commun avec la calibration précédente : pas de comparaison de forme avec elle.')) }
        }
    }
    if ($flag.Count) { $L.Add(((T "Écart propre à une disquette ({0}) : défaut probable de l'une des deux disquettes ; la comparaison seule ne dit pas laquelle.") -f ($flag -join ' ; '))) }
    elseif ($nCmp -eq 0) { $L.Add((T "Aucune face n'a pu être comparée : pas de verdict de forme.")) }
    elseif ($maxShape -le $script:LevelTauOk) { $L.Add((T 'Forme commune aux deux disquettes : elle vient du lecteur.')) }
    elseif ($maxShape -le $script:LevelTauMax) { $L.Add(((T "Formes proches sur les deux disquettes (écart de forme jusqu'à {0} ns), sans zone de désaccord.") -f (Format-UiNum $maxShape))) }
    else { $L.Add(((T "Formes différentes sur les deux disquettes (écart de forme jusqu'à {0} ns), sans zone localisée : lecteur instable, ou supports très différents.") -f (Format-UiNum $maxShape))) }
    # Niveau tres different : seuil de la calibration rapide (double densite) ; haute densite : seuil x CalHdK, et pas de
    # calibration rapide pour mesurer ce niveau (12.7)
    $hdCmp = ([string]$cal.Family -eq 'hd')
    $fatNs = if ($hdCmp) { $script:LevelFatigueNs * $script:CalHdK } else { $script:LevelFatigueNs }
    if ($maxLvl -gt $fatNs) {
        if ($hdCmp) { $L.Add(((T "Niveau très différent d'une disquette à l'autre (jusqu'à {0} ns) : la haute densité n'a pas encore de calibration rapide pour mesurer ce niveau sur chaque disquette à écrire.") -f "$([math]::Round($maxLvl))")) }
        else { $L.Add(((T "Niveau très différent d'une disquette à l'autre (jusqu'à {0} ns) : la calibration rapide mesure ce niveau sur chaque disquette à écrire.") -f "$([math]::Round($maxLvl))")) }
    }
    $supA = @(@($r.AKinds) | Where-Object { $sup -contains $_ }).Count; $supB = @(@($kinds) | Where-Object { $sup -contains $_ }).Count
    # 12.9 (L2-d) : reserves de A et de B aux memes cylindres (a 1 pres, Get-CalibCommonReserve) : l ecart vient du lecteur ;
    # plus de conseil « deux disquettes defectueuses » dans ce cas (verdict et courbe conseillee inchanges)
    $cmnTxt = @()
    for ($i = 0; $i -lt [math]::Min(@($A.Units).Count, @($cal.Units).Count); $i++) {
        $ua = $A.Units[$i]; $ub = $cal.Units[$i]
        if (-not $ua.Warn -or -not $ub.Warn) { continue }
        $cm = [int[]]@(Get-CalibCommonReserve (Get-CalibUnitReserve $ua.Warn) (Get-CalibUnitReserve $ub.Warn))
        if ($cm.Count -gt 0) { $cmnTxt += "$(Format-CylList $cm)$(if ($ub.Prefix) { ' ' + ([string]$ub.Prefix).Trim() })" }
    }
    if ($cmnTxt.Count -gt 0) { $L.Add(((T "Même écart aux cylindres {0} sur les deux disquettes : il vient du lecteur, pas du support.") -f ($cmnTxt -join ' ; '))) }
    elseif ($supA -gt 0 -and $supB -gt 0) { $L.Add((T 'Les deux calibrations ont des réserves liées au support : deux disquettes défectueuses, ou un lecteur instable (préchauffage, têtes à nettoyer).')) }
    if (@(@($r.AKinds) + @($kinds)) -contains 'drift') { $L.Add(((T "Une des deux calibrations a une dérive du lecteur de plus de {0} ns : la comparaison est peu concluante.") -f "$(2 * $script:CalResidual)")) }
    $ncA = [int](@($A.Units | ForEach-Object { @($_.Warn.NonConv).Count }) | Measure-Object -Sum).Sum
    $ncB = [int](@($cal.Units | ForEach-Object { @($_.Warn.NonConv).Count }) | Measure-Object -Sum).Sum
    $pk = Get-CalibRedoPick $dA $dB $mA $mB $A.Surf $cal.Surf $supA $supB $ncA $ncB ($flag.Count -gt 0)
    switch ($pk.By) {
        'zone'    { $L.Add(((T "Courbe {0} conseillée : sur les cylindres en désaccord, elle est la plus proche de la calibration précédente du {1}. Ce critère suppose que cette calibration a été faite sur une disquette saine.") -f "$($pk.Pick)", "$pvDate")) }
        'prev'    { $L.Add(((T "Courbe {0} conseillée : sa forme est la plus proche de la calibration précédente du {1}. Ce critère suppose que cette calibration a été faite sur une disquette saine.") -f "$($pk.Pick)", "$pvDate")) }
        'surface' { $L.Add(((T "Courbe {0} conseillée : sa disquette n'a pas de défaut au contrôle de surface, contrairement à l'autre.") -f "$($pk.Pick)")) }
        'support' { $L.Add(((T 'Courbe {0} conseillée : elle a moins de réserves liées au support.') -f "$($pk.Pick)")) }
        'nonconv' { $L.Add(((T 'Courbe {0} conseillée : elle a moins de cylindres non convergés.') -f "$($pk.Pick)")) }
        default   {
            if ($flag.Count) { $L.Add((T "Aucune courbe n'est conseillée : rien ne permet d'attribuer la zone de désaccord à l'une des deux disquettes. Une troisième calibration, sur une autre disquette, peut trancher.")) }
            else { $L.Add((T "Aucune courbe n'est conseillée : choisissez d'après la comparaison et les réserves.")) }
        }
    }
    $log = @($L.ToArray())
    $L.Add('')
    $L.Add((T "Conserver la courbe B : elle reste enregistrée.`nConserver la courbe A : la courbe A est rétablie et enregistrée.`nAbandonner les deux : la calibration d'avant la calibration A est rétablie.`nFermer la fenêtre : la courbe B est conservée."))
    $cv = @()
    foreach ($k in @($r.AKeys)) { if ($r.ACurves[$k]) { $x = $r.ACurves[$k].Clone(); $x.Series = 'A'; $cv += $x } }
    foreach ($k in @($r.AKeys)) { if ($script:PrecompCurves[$k]) { $x = $script:PrecompCurves[$k].Clone(); $x.Series = 'B'; $cv += $x } }
    return @{ Text = ($L.ToArray() -join "`n"); Log = $log; Curves = $cv; Zones = $zd; Pick = $pk.Pick }
}
# ============================== FONCTIONS : CALIBRATION : FENETRES =============

function Show-CalibReview($cal, [string[]]$issues, [bool]$toWrite, [bool]$offerFull = $false, [bool]$noFields = $false, [bool]$offerRedo = $false, $compare = $null, [bool]$warnKeep = $false, $lvl2 = $null) {
    # Calibration au resultat douteux (non convergee, limite de 0 ou CalHardNs, ecart aux mesures, forme qui ne colle pas en
    # mode rapide) : la courbe obtenue est montree et l utilisateur decide. Pas de validation automatique : la decision
    # demande de regarder la courbe. Renvoie 'keep' (conserver / ecrire), 'stop' (abandonner) ou 'full' (calibration
    # complete, mode rapide seulement). Fermeture de la fenetre : arreter avant une ecriture, conserver sinon. noFields :
    # calibration rapide de la carte Calibration de l Accueil dont le profil n est pas place dans les champs --precomp.
    # 12.8 (lot 1c, point 2) : warnKeep (calibration rapide avant une ecriture, Complete-LevelCalib : niveau non verifie et
    # forme non conforme) : « Ecrire l image » sans le style principal, avertissement lblRevWarn au-dessus des boutons.
    # 12.7 point 2 : offerRedo : bouton « Refaire sur une autre disquette » ('redo'). compare = @{ Mode = 'ab' | 'aonly' ;
    # Curves ; Zones ; Text ; Pick } : fenetre de comparaison des calibrations A et B ('keep' : courbe B, 'keepA' : courbe
    # A, 'stop' : aucune ; fermeture : 'keep') ou decision sur la courbe A seule apres une calibration B interrompue
    # ('keep' : courbe A, 'stop' : aucune ; fermeture : 'keep'). Courbes dessinees : copies de $compare.Curves.
    # Get-FamilyCurves renvoie deja un tableau protege (operateur virgule) : pas de @() autour, sinon tableau imbrique
    # 12.8 (lot 1c, § 7 et 10.1) : lvl2 = @{ WarnText ; Info ; BrandAsk ; Brand ; Brands } (Get-LevelReviewPlan) : texte de
    # l avertissement (forme non conforme ou forme adaptee avec reserve) ; fenetre « information » (courbe adaptee et
    # verifiee : en-tete propre, « Ecrire l image » principal) ; champ de marque cmbRevBrand (« Memoriser cette forme pour
    # la marque »), lu dans $script:CalReviewBrand a la fermeture. 12.8 (S3) : lvl2.OfferDisk, DiskMin : bouton
    # btnRevDisk, « Mesure complete de cette disquette » ('disk', W-M1) ; $cal.DiskOnly : textes de la mesure complete de
    # cette disquette (reference du lecteur inchangee). 12.10 (etape 2, relecture) : calibration croisee ($cal.Cross) : texte
    # « Conserver la courbe » propre au croise (courbe « source>cible » enregistree pour les ecritures destinees a la cible,
    # courbe propre de la source inchangee), les autres textes sont ceux d une calibration complete ordinaire
    if ($script:CurveForm -and -not $script:CurveForm.IsDisposed) { $script:CurveForm.Close() }   # elle dessine ces memes donnees
    if ($compare) { $script:CurveData = @($compare.Curves); $script:CurveLevel = @{}; $script:CurveZones = @($compare.Zones) }
    else {
        $script:CurveData = Get-FamilyCurves $cal.Family $cal.Slow
        if ($cal.Cross) { $script:CurveData = Get-DriveFamilyCurves (Get-CalibStoreDrive $cal) $cal.Family $cal.Slow }   # 12.10 : courbes croisees « source>cible »
        Set-CurveLevelData $script:CurveData
        $script:CurveZones = @()
    }
    $ab = [bool]($compare -and $compare.Mode -eq 'ab'); $aonly = [bool]($compare -and $compare.Mode -eq 'aonly')
    # 12.8 (lot 5, A4 R1 a R8) : fenetre de taille fixe (FixedDialog) au modele de frmClean : bandeau (pictogramme, titre et
    # texte lblRevText, Label de premier niveau), courbe de 420 px, reduite jusqu a 260 px pour tenir dans la zone de travail
    # (puis defilement, Set-DlgFit), boutons a la largeur de leur texte, sens de la fermeture ecrit sous les boutons
    # (lblRevClose, dans tous les modes), Echap par CancelButton (bouton equivalent a la fermeture), images liberees
    $CW = 964; $W = $CW - 32
    $gdi = New-Object System.Collections.Generic.List[object]
    $dlg = New-Object System.Windows.Forms.Form
    $dlg.Name = 'frmCalibReview'; $dlg.Text = (T 'Calibration precomp')
    $dlg.FormBorderStyle = 'FixedDialog'; $dlg.MaximizeBox = $false; $dlg.MinimizeBox = $false; $dlg.ShowInTaskbar = $false
    $dlg.StartPosition = 'CenterParent'; $dlg.Icon = $form.Icon; $dlg.Font = $form.Font; $dlg.BackColor = [System.Drawing.Color]::White
    $lvl = ($cal.Mode -eq 'level')
    $infoWin = [bool]($lvl2 -and $lvl2.Info -and $lvl -and -not $compare)
    # 12.8 (FIX1C, constat 7) : « verifiee » seulement si le niveau de chaque tete adaptee a ete verifie (Verified) ; sinon
    # la reserve « niveau de la courbe adaptee non verifie » de la meme fenetre est rappelee
    # 12.10 (relecture de la RC) : lecteur cible choisi pour le lecteur calibre (Get-TargetDrive) : « Conserver la courbe »
    # dit que ses ecritures appliquent la courbe croisee, et non la courbe propre (avant : « appliquee aux prochaines
    # ecritures »)
    # 12.10 (relecture de la RC, fix1) : famille haute densite : ecritures haute densite en profil Auto refusees pour le
    # lecteur cible (Get-TargetWriteInfo, BlockKind 'hd'), et non « courbe croisee appliquee (refusees sans elle) »
    $tgtR = if ($cal.Cross -or $lvl) { '' } else { [string](Get-TargetDrive ([string]$cal.Drive)) }
    $head = if ($toWrite -and $lvl -and $infoWin -and $lvl2.Verified -ne $false) { (T "Écrire l'image : l'image est écrite avec la courbe adaptée à cette disquette, vérifiée par une écriture du motif.`nArrêter : l'image n'est pas écrite ; le niveau n'est pas conservé et les profils de la référence sont rétablis.") }
            elseif ($toWrite -and $lvl -and $infoWin) { (T "Écrire l'image : l'image est écrite avec la courbe adaptée à cette disquette ; son niveau a été décalé sans nouvelle écriture du motif (voir ci-dessus).`nArrêter : l'image n'est pas écrite ; le niveau n'est pas conservé et les profils de la référence sont rétablis.") }
            elseif ($toWrite -and $lvl) { (T "Écrire l'image : l'image est écrite avec le niveau mesuré.`nArrêter : l'image n'est pas écrite ; le niveau n'est pas conservé et les profils de la référence sont rétablis.") }
            elseif ($toWrite -and $cal.DiskOnly) { (T "Écrire l'image : l'image est écrite avec la courbe mesurée sur cette disquette.`nArrêter : l'image n'est pas écrite et cette mesure n'est pas conservée ; la référence du lecteur, inchangée, reste en place.") }
            elseif ($toWrite) { (T "Écrire l'image : la courbe est conservée et l'image est écrite avec elle.`nArrêter : l'image n'est pas écrite et cette calibration n'est pas conservée (la calibration précédente est rétablie).") }
            elseif ($lvl -and $noFields) { (T "Conserver le niveau : il est enregistré pour cette disquette et reste affiché dans la fenêtre Courbe ; les champs --precomp ne sont pas modifiés.`nAbandonner le niveau : il n'est pas enregistré.") }
            elseif ($lvl) { (T "Conserver le niveau : le profil décalé reste dans les champs --precomp, pour cette disquette seulement.`nAbandonner le niveau : les champs --precomp reprennent leurs valeurs d'avant la calibration rapide.") }
            elseif ($cal.Cross) { ((T "Conserver la courbe : elle est enregistrée pour les écritures du lecteur {0} destinées au lecteur {1} (courbe croisée « {0} → {1} »), sans modifier la courbe propre du lecteur {0}.`nAbandonner la courbe : la courbe croisée précédente, s'il y en avait une, est rétablie.") -f "$($cal.Cross.Src)", "$($cal.Cross.Tgt)") }
            elseif ($tgtR -and [string]$cal.Family -eq 'hd') { ((T "Conserver la courbe : elle est enregistrée comme courbe propre du lecteur {0}, appliquée à ses écritures haute densité sans lecteur cible ; avec le lecteur cible {1} choisi, ses écritures haute densité en profil Auto sont refusées (la calibration croisée n'existe qu'en double densité).`nAbandonner la courbe : la calibration précédente est rétablie.") -f "$($cal.Drive)", "$tgtR") }
            elseif ($tgtR) { ((T "Conserver la courbe : elle est enregistrée comme courbe propre du lecteur {0}, appliquée à ses écritures sans lecteur cible ; avec le lecteur cible {1} choisi, ses écritures appliquent la courbe croisée {0} → {1} (refusées sans elle).`nAbandonner la courbe : la calibration précédente est rétablie.") -f "$($cal.Drive)", "$tgtR") }
            elseif ($script:DriveReg.Count -gt 0 -and (Test-DriveRegistered ([string]$cal.Drive))) { ((T "Conserver la courbe : elle est enregistrée pour le lecteur {0} et appliquée à ses prochaines écritures.`nAbandonner la courbe : la calibration précédente est rétablie.") -f "$($cal.Drive)") }   # 12.11 (lot LN-b) : lecteur enregistre nomme
            else { (T "Conserver la courbe : elle est enregistrée et appliquée aux prochaines écritures.`nAbandonner la courbe : la calibration précédente est rétablie.") }
    if ($offerFull) { $head += "`n" + (T "Calibration complète : la courbe du lecteur est mesurée de nouveau en test fin, après un avertissement ; elle devient la nouvelle référence de forme.") }
    # 12.8 (S3, W-M1) : mesure complete de cette disquette proposee par la calibration rapide avant une ecriture lente
    # (Get-LevelReviewPlan, OfferDisk), a la place de « Calibration complete » ; reference du lecteur inchangee
    $offerDisk = [bool]($lvl2 -and $lvl2.OfferDisk -and $lvl -and $toWrite -and -not $compare)
    if ($offerDisk) { $head += "`n" + ((T "Mesure complète de cette disquette : la précompensation est mesurée sur tous ses cylindres (environ {0} min), après un avertissement, puis l'image est écrite ; la référence du lecteur n'est pas modifiée.") -f "$($lvl2.DiskMin)") }
    # 12.7 : ligne placee apres les autres (les fins de test n impriment que les premieres lignes, ou celles qui commencent
    # par Conserver, Abandonner ou Calibration complete)
    if ($offerRedo -and -not $compare) { $head += "`n" + $(if ($toWrite) { (T "Refaire sur une autre disquette : l'écriture est annulée ; cette courbe est mise de côté, la même calibration est refaite sur une autre disquette sacrifiée, puis vous choisissez la courbe. Relancez ensuite l'écriture depuis la Bibliothèque.") } else { (T "Refaire sur une autre disquette : cette courbe est mise de côté et la calibration précédente rétablie ; la même calibration est refaite sur une autre disquette sacrifiée, puis les deux courbes sont comparées et vous choisissez celle à conserver.") }) }
    $intro = if ($infoWin) { (T 'La calibration rapide a adapté la courbe à cette disquette :') } else { (T "La calibration ne donne pas un bon résultat :") }
    $txt = $intro + "`n" + ((@($issues) | ForEach-Object { "  - $_" }) -join "`n") + "`n`n" + $head
    if ($compare) { $txt = [string]$compare.Text }
    $warn = ($warnKeep -and $toWrite -and $lvl -and -not $compare)
    # Bandeau : information pour une comparaison ou une courbe adaptee, avertissement sinon (et sous lblRevWarn)
    $level = if ($warn) { 'warn' } elseif ($compare -or $infoWin) { 'info' } else { 'warn' }
    $heading = if ($ab) { (T 'Comparaison des calibrations A et B') } elseif ($aonly) { (T 'Calibration B interrompue : décision sur la courbe A') }
               elseif ($infoWin) { (T 'Courbe adaptée à cette disquette') } elseif ($toWrite) { (T "Résultat douteux : décidez avant l'écriture") } else { (T 'Résultat douteux : décidez de la suite') }
    $ban = New-DlgBanner $dlg 16 $W $heading $txt $level (New-DlgPicto $(if ($compare -or $infoWin) { 'curve' } else { 'warn' })) $gdi 'lblRevText'
    $tf = [System.Windows.Forms.TextFormatFlags]::WordBreak -bor [System.Windows.Forms.TextFormatFlags]::NoPrefix
    $pb = New-Object System.Windows.Forms.PictureBox
    $pb.BackColor = [System.Drawing.Color]::White
    $pb.Add_Paint({ Draw-PrecompCurve $_.Graphics $this.ClientSize })
    $bar = New-Object System.Windows.Forms.Panel
    $bar.Name = 'pnlRevButtons'; $bar.BackColor = $script:Theme.Page; $bar.Width = $CW
    # 12.8 (lot 1c, point 2) : avertissement au-dessus des boutons, boutons places dessous ($by), barre de 78 px au moins
    $by = 11
    if ($warn) {
        $lblWarn = New-Object System.Windows.Forms.Label
        $lblWarn.Name = 'lblRevWarn'; $lblWarn.AutoSize = $false; $lblWarn.UseMnemonic = $false; $lblWarn.Font = $bold; $lblWarn.ForeColor = $script:Theme.WarnInk
        $lblWarn.Text = if ($lvl2 -and $lvl2.WarnText) { [string]$lvl2.WarnText } else { (T "Attention : niveau non vérifié et forme non conforme. La courbe que « Écrire l'image » utiliserait n'a pas été vérifiée sur cette disquette ; vers le centre, elle peut s'écarter de son besoin de plusieurs dizaines de ns.") }
        $hW = [System.Windows.Forms.TextRenderer]::MeasureText($lblWarn.Text, $bold, (New-Object System.Drawing.Size(($CW - 32), 10000)), $tf).Height
        $lblWarn.Location = New-Object System.Drawing.Point(16, 8); $lblWarn.Size = New-Object System.Drawing.Size(($CW - 32), ($hW + 2))
        $bar.Controls.Add($lblWarn)
        $by = $lblWarn.Bottom + 8
    }
    # 12.8 (lot 1c, § 10.1) : fenetre « information » d une courbe adaptee et verifiee sur toutes les tetes : marque a
    # memoriser (champ libre, preremplie par la marque choisie, vide si la disquette s en ecarte), au-dessus des boutons
    $cmbBrand = $null
    if ($infoWin -and $lvl2.BrandAsk -and -not $warn) {
        $lblBrand = New-Object System.Windows.Forms.Label
        $lblBrand.Name = 'lblRevBrand'; $lblBrand.AutoSize = $true; $lblBrand.UseMnemonic = $false; $lblBrand.Text = (T 'Mémoriser cette forme pour la marque :')
        # 12.8 (FIX1C, constat 8) : police de la fenetre posee avant la mesure (la barre n est pas encore dans la fenetre :
        # sinon PreferredWidth est mesure dans la police par defaut et le libelle recouvre la liste)
        $lblBrand.Font = $dlg.Font
        $lblBrand.Location = New-Object System.Drawing.Point(16, 14)
        $bar.Controls.Add($lblBrand)
        $cmbBrand = New-Object System.Windows.Forms.ComboBox
        $cmbBrand.Name = 'cmbRevBrand'; $cmbBrand.DropDownStyle = 'DropDown'; $cmbBrand.Width = 300
        foreach ($bn in @($lvl2.Brands)) { if ($bn) { [void]$cmbBrand.Items.Add([string]$bn) } }
        $cmbBrand.Text = [string]$lvl2.Brand
        $cmbBrand.Location = New-Object System.Drawing.Point((16 + $lblBrand.PreferredWidth + 8), 10)
        $bar.Controls.Add($cmbBrand)
        if ($tip) { $tip.SetToolTip($cmbBrand, (T "Nom libre : marque, année ou lot. Une marque déjà mesurée sert de point de départ : sa forme et son niveau, mémorisés avec la référence actuelle du lecteur. La mesure reste faite sur la disquette insérée.")) }
        $by = 44
    }
    # Boutons (A4 R6) : a la largeur de leur texte, en bas a droite, espaces de 8 ; action principale avec glyphe ;
    # « Arreter » (avant une ecriture) en style danger
    $okGlyph = if ($toWrite -and -not $compare) { 'Save' } else { 'Check' }
    $stopDanger = ($toWrite -and -not $compare)
    $btnOk = New-Object System.Windows.Forms.Button
    $btnOk.Name = 'btnRevKeep'
    $btnOk.Text = if ($ab) { (T 'Conserver la courbe B') } elseif ($aonly) { (T 'Conserver la courbe A') } elseif ($toWrite) { (T "Écrire l'image") } elseif ($lvl) { (T 'Conserver le niveau') } else { (T 'Conserver la courbe') }
    $btnOk.Size = New-Object System.Drawing.Size((Get-DlgButtonWidth $btnOk.Text $okGlyph 150), 34)
    $btnOk.DialogResult = [System.Windows.Forms.DialogResult]::OK
    $btnNo = New-Object System.Windows.Forms.Button
    $btnNo.Name = 'btnRevStop'
    $btnNo.Text = if ($ab) { (T 'Abandonner les deux') } elseif ($aonly) { (T 'Abandonner la courbe') } elseif ($toWrite) { (T 'Arrêter') } elseif ($lvl) { (T 'Abandonner le niveau') } else { (T 'Abandonner la courbe') }
    $btnNo.Size = New-Object System.Drawing.Size((Get-DlgButtonWidth $btnNo.Text $(if ($stopDanger) { 'Stop' } else { '' }) 110), 34)
    $btnNo.DialogResult = [System.Windows.Forms.DialogResult]::Abort
    # Comparaison : style principal pour la courbe conseillee seulement (aucune mise en avant sans courbe conseillee)
    # 12.8 (lot 1c, point 2) : avertissement : « Ecrire l image » sans le style principal
    Set-Btn $btnOk $okGlyph $(if (($ab -and $compare.Pick -ne 'B') -or $warn) { 'normal' } else { 'primary' })
    if ($stopDanger) { Set-Btn $btnNo 'Stop' 'danger' } else { Set-Btn $btnNo '' 'normal' }
    $btnNo.Location = New-Object System.Drawing.Point(($CW - 16 - $btnNo.Width), $by)
    $btnOk.Location = New-Object System.Drawing.Point(($btnNo.Left - 8 - $btnOk.Width), $by)
    $bar.Controls.AddRange(@($btnOk, $btnNo))
    if ($offerFull) {
        $btnFull = New-Object System.Windows.Forms.Button
        $btnFull.Name = 'btnRevFull'; $btnFull.Text = (T 'Calibration complète'); $btnFull.DialogResult = [System.Windows.Forms.DialogResult]::Retry
        $btnFull.Size = New-Object System.Drawing.Size((Get-DlgButtonWidth $btnFull.Text '' 150), 34)
        Set-Btn $btnFull '' 'normal'
        $btnFull.Location = New-Object System.Drawing.Point(($btnOk.Left - 8 - $btnFull.Width), $by)
        $bar.Controls.Add($btnFull)
    }
    # 12.8 (S3, W-M1) : « Mesure complete de cette disquette (environ N min) » ('disk'), a gauche de btnRevKeep
    if ($offerDisk) {
        $btnDisk = New-Object System.Windows.Forms.Button
        $btnDisk.Name = 'btnRevDisk'; $btnDisk.Text = ((T 'Mesure complète de cette disquette (environ {0} min)') -f "$($lvl2.DiskMin)"); $btnDisk.DialogResult = [System.Windows.Forms.DialogResult]::No
        $btnDisk.Size = New-Object System.Drawing.Size((Get-DlgButtonWidth $btnDisk.Text '' 150), 34)
        Set-Btn $btnDisk '' 'normal'
        $btnDisk.Location = New-Object System.Drawing.Point(($btnOk.Left - 8 - $btnDisk.Width), $by)
        $bar.Controls.Add($btnDisk)
    }
    # 12.7 point 2 : « Refaire sur une autre disquette » (reserve qui peut venir du support), a gauche de btnRevKeep ;
    # comparaison A / B : « Conserver la courbe A » a gauche de « Conserver la courbe B »
    if ($offerRedo -and -not $compare) {
        $btnRedo = New-Object System.Windows.Forms.Button
        $btnRedo.Name = 'btnRevRedo'; $btnRedo.Text = (T 'Refaire sur une autre disquette'); $btnRedo.DialogResult = [System.Windows.Forms.DialogResult]::Ignore
        $btnRedo.Size = New-Object System.Drawing.Size((Get-DlgButtonWidth $btnRedo.Text '' 150), 34)
        Set-Btn $btnRedo '' 'normal'
        $btnRedo.Location = New-Object System.Drawing.Point(($btnOk.Left - 8 - $btnRedo.Width), $by)
        $bar.Controls.Add($btnRedo)
    }
    if ($ab) {
        $btnKeepA = New-Object System.Windows.Forms.Button
        $btnKeepA.Name = 'btnRevKeepA'; $btnKeepA.Text = (T 'Conserver la courbe A'); $btnKeepA.DialogResult = [System.Windows.Forms.DialogResult]::Yes
        $btnKeepA.Size = New-Object System.Drawing.Size((Get-DlgButtonWidth $btnKeepA.Text 'Check' 150), 34)
        Set-Btn $btnKeepA 'Check' $(if ($compare.Pick -eq 'A') { 'primary' } else { 'normal' })
        $btnKeepA.Location = New-Object System.Drawing.Point(($btnOk.Left - 8 - $btnKeepA.Width), $by)
        $bar.Controls.Add($btnKeepA)
    }
    # Sens de la fermeture sous les boutons (A4 R8 ; arbitrage 3 de la 12.7 pour la comparaison : courbe B deja enregistree ;
    # decision sur A seule : courbe A retablie), dans tous les modes depuis la 12.8
    $lblClose = New-Object System.Windows.Forms.Label
    $lblClose.Name = 'lblRevClose'; $lblClose.AutoSize = $false; $lblClose.UseMnemonic = $false; $lblClose.ForeColor = $script:Theme.Muted
    $lblClose.Text = if ($ab) { (T 'Fermer la fenêtre conserve la courbe B, déjà enregistrée.') } elseif ($aonly) { (T 'Fermer la fenêtre conserve la courbe A, qui est rétablie et enregistrée.') }
                     elseif ($toWrite) { (T 'Fermer la fenêtre ou Échap équivaut à « Arrêter ».') } elseif ($lvl) { (T 'Fermer la fenêtre ou Échap conserve le niveau, comme « Conserver le niveau ».') }
                     else { (T 'Fermer la fenêtre ou Échap conserve la courbe, comme « Conserver la courbe ».') }
    $lblClose.TextAlign = 'MiddleRight'
    $lblClose.Location = New-Object System.Drawing.Point(16, ($by + 34 + 6)); $lblClose.Size = New-Object System.Drawing.Size(($CW - 32), 20)
    $bar.Controls.Add($lblClose)
    $bar.Height = $lblClose.Bottom + 8
    # Hauteurs : courbe de 420 px, reduite jusqu a 260 px si la fenetre depasse la zone de travail, puis defilement
    $wa = [System.Windows.Forms.Screen]::FromControl($form).WorkingArea
    $top = $ban.Bottom + 10; $hc = 420
    $dlg.ClientSize = New-Object System.Drawing.Size($CW, ($top + $hc + 8 + $bar.Height))
    if ($dlg.Height -gt $wa.Height) { $hc = [math]::Max(260, $hc - ($dlg.Height - $wa.Height)) }
    $pb.Location = New-Object System.Drawing.Point(16, $top); $pb.Size = New-Object System.Drawing.Size($W, $hc)
    $bar.Location = New-Object System.Drawing.Point(0, ($pb.Bottom + 8))
    $dlg.ClientSize = New-Object System.Drawing.Size($CW, $bar.Bottom)
    $dlg.Controls.Add($pb); $dlg.Controls.Add($bar)
    [void](Set-DlgFit $dlg $wa)
    # Echap : bouton equivalent a la fermeture (Arreter avant une ecriture, sinon Conserver) ; pas d AcceptButton. Focus sur
    # le champ de marque, sinon sur ce bouton : Entree ne lance pas l ecriture
    $cancelBtn = if ($stopDanger) { $btnNo } else { $btnOk }
    $dlg.CancelButton = $cancelBtn
    $dlg.ActiveControl = if ($cmbBrand) { $cmbBrand } else { $cancelBtn }
    $dlg.Add_Shown({ $this.Activate(); try { [System.Media.SystemSounds]::Exclamation.Play() } catch { } })
    # 12.7 : zone de progression de l Accueil gardee pendant la decision (Update-HomeProgress, mode 'hold')
    $script:HomeProgHold = $true
    try { $dr = $dlg.ShowDialog($form); if ($cmbBrand) { $script:CalReviewBrand = [string]$cmbBrand.Text } } finally { Clear-DlgGdi $dlg $gdi; $script:HomeProgHold = $false; $script:CurveZones = @() }
    if ($dr -eq [System.Windows.Forms.DialogResult]::OK) { return 'keep' }
    if ($dr -eq [System.Windows.Forms.DialogResult]::Retry) { return 'full' }
    if ($dr -eq [System.Windows.Forms.DialogResult]::Ignore) { return 'redo' }
    if ($dr -eq [System.Windows.Forms.DialogResult]::Yes) { return 'keepA' }
    if ($dr -eq [System.Windows.Forms.DialogResult]::No -and $offerDisk) { return 'disk' }
    if ($dr -eq [System.Windows.Forms.DialogResult]::Abort) { return 'stop' }
    if ($compare) { return 'keep' }
    return $(if ($toWrite) { 'stop' } else { 'keep' })
}

function Get-CalibSnapshot([string[]]$keys) {
    # Etat des courbes et profils (retabli par Restore-CalibState) : courbes des cles donnees, niveaux, profil, champs --precomp
    # 12.10 : cles de magasin « lecteur|cle » (fin de calibration : lecteur de la calibration) ou cles de courbe (lecteur du
    # bandeau) ; courbes du magasin rangees par cle de courbe, lecteur garde (Drive) pour Set-DriveCurve au retablissement
    $s = @{ Std = $script:PrecompStd; Long = $script:PrecompLong; Curves = @{}; Drive = [string]$cmbDrive.Text; Levels = $script:LevelShifts.Clone()
            Prof = $cmbWProfile.SelectedIndex; On = $chkWPrecomp.Checked; P0 = $txtWPrecomp.Text; P1 = $txtWPrecomp1.Text; Lbl = (Get-WProfileText) }
    foreach ($k in @($keys)) { $p = Split-DriveCurveKey $k; $s.Drive = [string]$p.Drive; $s.Curves[$p.Key] = Get-DriveCurve $p.Drive $p.Key }
    return $s
}

function Restore-CalibState($prev) {
    # Retablit les courbes et profils d avant une calibration refusee par l utilisateur
    # 12.10 : courbes retablies dans le magasin du lecteur de la copie (Drive, sinon lecteur du bandeau), vue mise a jour
    $pd = if ($prev.Drive) { [string]$prev.Drive } else { [string]$cmbDrive.Text }
    # Profils de famille : ceux de la vue du lecteur du bandeau ; une copie d un autre lecteur (lecteur change dans le bandeau
    # pendant la calibration) ne les touche pas, Sync-PrecompCurves les tire de ses courbes au retour sur ce lecteur
    if ($pd -eq [string]$cmbDrive.Text) { $script:PrecompStd = $prev.Std; $script:PrecompLong = $prev.Long }
    foreach ($k in @($prev.Curves.Keys)) { Set-DriveCurve $pd $k $prev.Curves[$k] }
    if ($prev.Levels) { $script:LevelShifts = $prev.Levels }      # niveaux mesures avec la reference retablie
    if ($script:CurveForm -and -not $script:CurveForm.IsDisposed) { $script:CurveForm.Close() }
    # Choix du profil et champs --precomp d avant la calibration (profil Manuel compris)
    if ($null -ne $prev.Prof -and $cmbWProfile.SelectedIndex -ne $prev.Prof) { $cmbWProfile.SelectedIndex = $prev.Prof }
    Update-PrecompForImage $txtWFile.Text
    # 12.8 (FIX-PISTES-2) : Lbl $null quand le libelle portait l avis de la Bibliotheque (Get-WProfileText) : texte du
    # profil pose par Update-PrecompForImage
    if ($null -ne $prev.P0) { $chkWPrecomp.Checked = $prev.On; $txtWPrecomp.Text = $prev.P0; $txtWPrecomp1.Text = $prev.P1; if ($null -ne $prev.Lbl) { $lblWProfileInfo.Text = $prev.Lbl } }
    if (-not $script:Restore) { [void](Save-Config) }
}

function Show-TimedConfirm([string]$name, [string]$title, [string]$text, [string]$okText, [string]$okGlyph, [string]$countFmt, [string]$checkLabel, [string]$stopOn, [string]$stopOff, [int]$Seconds = 0, [switch]$NeedCheck, $Combo = $null, [string]$Heading = '', [string]$Level = 'warn', [string]$Picto = 'warn') {
    # Fenetre d avertissement a compte a rebours : $okText / Annuler ; sans reponse, validation automatique au bout de
    # $Seconds, seulement si l appelant passe un delai (> 0 : Get-CalibConfirmSeconds, ecriture sans surveillance ; 0 par
    # defaut : aucun delai, 12.9 S1), pour qu une sequence sans surveillance ne reste pas bloquee.
    # $countFmt : ligne du decompte ({0} = secondes). $checkLabel : case facultative ; la cocher ou la decocher arrete le
    # decompte (l utilisateur est present), la ligne affiche alors $stopOn ou $stopOff. Renvoie @{ Ok ; Checked ; Auto }.
    # 12.7 : Seconds : delai propre a cette fenetre (12.9 : 0 par defaut, aucun ; > 0 : delai) ; NeedCheck : $okText inactif tant
    # que la case n est pas cochee (calibration B : la disquette inseree doit etre une autre disquette sacrifiee)
    # 12.8 (lot 5, A4 R1 a R8, modele frmClean) : bandeau ($Heading, niveau $Level, pictogramme $Picto de New-DlgPicto) qui
    # porte le texte (Label de premier niveau lblCalText), case en gras, aucun AcceptButton (focus sur la case, sinon sur
    # Annuler : Entree ne lance rien), bouton principal grise par Set-PrimaryEnabled, ligne du decompte absente sans texte
    # (frmReinsert, D7), images liberees (Clear-DlgGdi), ajustement aux petits ecrans (Set-DlgFit). Largeur de 680 px : texte
    # de l avertissement de calibration le plus long sous 720 px de haut
    $W = 680
    $gdi = New-Object System.Collections.Generic.List[object]
    $dlg = New-Object System.Windows.Forms.Form
    $dlg.Name = $name; $dlg.Text = $title
    $dlg.FormBorderStyle = 'FixedDialog'; $dlg.MaximizeBox = $false; $dlg.MinimizeBox = $false; $dlg.ShowInTaskbar = $false
    $dlg.StartPosition = 'CenterParent'; $dlg.Icon = $form.Icon; $dlg.Font = $form.Font; $dlg.BackColor = [System.Drawing.Color]::White
    $ban = New-DlgBanner $dlg 16 $W $Heading $text $Level (New-DlgPicto $Picto) $gdi 'lblCalText'
    $tf = [System.Windows.Forms.TextFormatFlags]::WordBreak -bor [System.Windows.Forms.TextFormatFlags]::NoPrefix
    $y = $ban.Bottom + 14
    $chk = $null
    if ($checkLabel) {
        $chk = New-Object System.Windows.Forms.CheckBox
        $chk.Name = 'chkCalSwap'; $chk.Text = $checkLabel; $chk.AutoSize = $false; $chk.UseMnemonic = $false; $chk.Font = $bold
        $chk.CheckAlign = 'TopLeft'; $chk.TextAlign = 'TopLeft'
        $hc = [System.Windows.Forms.TextRenderer]::MeasureText($checkLabel, $bold, (New-Object System.Drawing.Size(($W - 24), 10000)), $tf).Height
        $chk.Size = New-Object System.Drawing.Size($W, [math]::Max(24, ($hc + 6))); $chk.Location = New-Object System.Drawing.Point(16, $y)
        $y = $chk.Bottom + 8
    }
    # 12.8 (lot 1c, § 10.1) : liste modifiable facultative ($Combo = @{ Label ; Items ; Text ; Tip }) : marque de la
    # disquette inseree (cmbCalBrand) ; saisir ou choisir arrete le compte a rebours, comme la case
    $cmb = $null; $lblCmb = $null
    if ($Combo) {
        $lblCmb = New-Object System.Windows.Forms.Label
        $lblCmb.Name = 'lblCalBrand'; $lblCmb.AutoSize = $true; $lblCmb.UseMnemonic = $false; $lblCmb.Text = [string]$Combo.Label
        # 12.8 (FIX1C, constat 8) : police de la fenetre posee avant la mesure de PreferredWidth (libelle ajoute plus tard)
        $lblCmb.Font = $dlg.Font
        $lblCmb.Location = New-Object System.Drawing.Point(16, ($y + 4))
        $cmb = New-Object System.Windows.Forms.ComboBox
        $cmb.Name = 'cmbCalBrand'; $cmb.DropDownStyle = 'DropDown'
        foreach ($it in @($Combo.Items)) { if ($it) { [void]$cmb.Items.Add([string]$it) } }
        $cmb.Text = [string]$Combo.Text
        $lx = 16 + $lblCmb.PreferredWidth + 8
        $cmb.Location = New-Object System.Drawing.Point($lx, $y); $cmb.Width = [math]::Max(160, 16 + $W - $lx)
        if ($Combo.Tip -and $tip) { $tip.SetToolTip($cmb, [string]$Combo.Tip) }
        $y = $cmb.Bottom + 10
    }
    # Ligne du decompte : hauteur du plus long de ses textes ; aucune ligne quand la fenetre n en a pas (frmReinsert)
    $lblCount = New-Object System.Windows.Forms.Label
    $lblCount.Name = 'lblCalCount'; $lblCount.AutoSize = $false; $lblCount.Font = $bold
    $lblCount.Location = New-Object System.Drawing.Point(16, $y); $lblCount.ForeColor = $script:Theme.WarnInk
    $hCount = 0
    foreach ($s in @(($countFmt -f '999'), $stopOn, $stopOff)) {
        if (-not $s) { continue }
        $lblCount.Text = $s
        $hCount = [math]::Max([math]::Max(22, $hCount), $lblCount.GetPreferredSize((New-Object System.Drawing.Size($W, 0))).Height)
    }
    $lblCount.Text = ''
    $lblCount.Size = New-Object System.Drawing.Size($W, $hCount)
    $y = if ($hCount -gt 0) { $lblCount.Bottom + 10 } else { $y + 4 }
    $btnOk = New-Object System.Windows.Forms.Button
    $btnOk.Name = 'btnCalOk'; $btnOk.Text = $okText; $btnOk.Size = New-Object System.Drawing.Size((Get-DlgButtonWidth $okText $okGlyph 170), 34)
    $btnOk.DialogResult = [System.Windows.Forms.DialogResult]::OK
    $btnNo = New-Object System.Windows.Forms.Button
    $btnNo.Name = 'btnCalCancel'; $btnNo.Text = (T 'Annuler'); $btnNo.Size = New-Object System.Drawing.Size(110, 34)
    $btnNo.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
    # Bouton principal : bleu et actif, sauf case obligatoire non cochee (style normal grise, Set-PrimaryEnabled)
    Set-PrimaryEnabled $btnOk (-not ($NeedCheck -and $chk)) $okGlyph; Set-Btn $btnNo '' 'normal'
    $btnNo.Location = New-Object System.Drawing.Point((16 + $W - $btnNo.Width), $y)
    $btnOk.Location = New-Object System.Drawing.Point(($btnNo.Left - 8 - $btnOk.Width), $y)
    $dlg.ClientSize = New-Object System.Drawing.Size(($W + 32), ($y + $btnOk.Height + 16))
    $dlg.CancelButton = $btnNo                        # pas d AcceptButton : Entree ne lance ni la calibration ni l ecriture
    $dlg.Controls.AddRange(@($lblCount, $btnOk, $btnNo))
    if ($chk) { $dlg.Controls.Add($chk) }
    if ($cmb) { $dlg.Controls.Add($lblCmb); $dlg.Controls.Add($cmb) }
    $dlg.ActiveControl = if ($chk) { $chk } else { $btnNo }
    [void](Set-DlgFit $dlg ([System.Windows.Forms.Screen]::FromControl($form).WorkingArea))
    $sec = [math]::Max(0, $Seconds)
    $script:CalConfirm = @{ Left = $sec; Auto = $false; Dlg = $dlg; Count = $lblCount; Tmr = $null; Fmt = $countFmt; StopOn = $stopOn; StopOff = $stopOff }
    if ($NeedCheck -and $chk) {
        $script:CalConfirm.OkBtn = $btnOk; $script:CalConfirm.Glyph = $okGlyph
        $chk.Add_CheckedChanged({ $c = $script:CalConfirm; if ($c -and $c.OkBtn) { Set-PrimaryEnabled $c.OkBtn $this.Checked $c.Glyph } })
    }
    if ($NeedCheck -and $sec -le 0 -and $stopOff) { $lblCount.Text = $stopOff }
    $tmr = $null
    if ($sec -gt 0) {
        $lblCount.Text = ($countFmt -f "$sec")
        $tmr = New-Object System.Windows.Forms.Timer
        $tmr.Interval = 1000
        $script:CalConfirm.Tmr = $tmr
        $tmr.Add_Tick({
            $c = $script:CalConfirm
            if (-not $c) { return }
            $c.Left--
            if ($c.Left -le 0) { $c.Auto = $true; $c.Dlg.DialogResult = [System.Windows.Forms.DialogResult]::OK; return }
            $c.Count.Text = ($c.Fmt -f "$($c.Left)")
        })
    }
    if ($chk -and $tmr) {
        $chk.Add_CheckedChanged({
            $c = $script:CalConfirm
            if (-not $c) { return }
            if ($c.Tmr) { $c.Tmr.Stop() }
            $c.Count.Text = if ($this.Checked) { $c.StopOn } else { $c.StopOff }
        })
    }
    if ($cmb -and $tmr) {
        # Gestionnaires poses apres le texte initial : seule une saisie ou un choix de l utilisateur arrete le decompte
        $script:CalConfirm.Chk = $chk
        $stopCmb = {
            $c = $script:CalConfirm
            if (-not $c -or -not $c.Tmr -or -not $c.Tmr.Enabled) { return }
            $c.Tmr.Stop()
            $c.Count.Text = if ($c.Chk -and $c.Chk.Checked) { $c.StopOn } else { $c.StopOff }
        }
        $cmb.Add_TextUpdate($stopCmb); $cmb.Add_SelectionChangeCommitted($stopCmb)
    }
    $dlg.Add_Shown({ $this.Activate(); try { [System.Media.SystemSounds]::Exclamation.Play() } catch { } })
    if ($tmr) { $tmr.Start() }
    try { $dr = $dlg.ShowDialog($form) }
    finally { if ($tmr) { $tmr.Stop(); $tmr.Dispose() } }
    $res = @{ Ok = ($dr -eq [System.Windows.Forms.DialogResult]::OK); Checked = [bool]($chk -and $chk.Checked); Auto = [bool]$script:CalConfirm.Auto; ComboText = $(if ($cmb) { [string]$cmb.Text } else { $null }) }
    $script:CalConfirm = $null
    Clear-DlgGdi $dlg $gdi
    return $res
}

function Get-CalibConfirmSeconds([string]$afterCalib, [bool]$unattended) {
    # 12.9 (S1) : delai de l avertissement de calibration (Show-CalibConfirm). CalibConfirmSeconds seulement pour la
    # calibration de la disquette a ecrire ($afterCalib 'write') d une ecriture sans surveillance (case chkWUnattended) ;
    # 0 sinon : une calibration seule (bouton « Calibrer », carte « Calibrer le lecteur » de l Accueil) n est jamais validee
    # seule, la disquette inseree est peut-etre un original
    if ($afterCalib -eq 'write' -and $unattended) { return [int]$script:CalibConfirmSeconds }
    return 0
}

function Show-CalibConfirm([string]$text, [string]$swapLabel, $brand = $null, [int]$Seconds = 0) {
    # Avertissement avant une calibration : la disquette inseree recoit le motif de test a chaque passe, ce qui use le
    # support. $swapLabel : case « disquette sacrifiee » (la disquette a ecrire est redemandee apres la calibration),
    # absente pour une calibration seule. 12.8 (lot 1c) : $brand = @{ Label ; Items ; Text ; Tip } : champ de la marque
    # de la disquette (calibration rapide). Renvoie @{ Ok ; Swap ; Auto ; Brand }.
    # 12.9 (S1) : $Seconds (Get-CalibConfirmSeconds) : 0 par defaut, sans decompte ni ligne de decompte (comme frmReinsert) ;
    # validation automatique seulement avec un delai
    $cf = ''; $sOn = ''; $sOff = ''
    if ($Seconds -gt 0) {
        $cf = (T "Sans réponse, la calibration démarre automatiquement dans {0} s.")
        $sOn = (T "Compte à rebours arrêté : insérez la disquette sacrifiée, puis cliquez sur « Lancer la calibration ».")
        $sOff = (T "Compte à rebours arrêté : cliquez sur « Lancer la calibration » pour calibrer avec la disquette insérée.")
    }
    $r = Show-TimedConfirm 'frmCalibConfirm' (T 'Calibration precomp') $text (T 'Lancer la calibration') 'Diagnostic' $cf $swapLabel $sOn $sOff -Seconds ([math]::Max(0, $Seconds)) -Combo $brand -Heading (T 'Calibration : la disquette insérée reçoit le motif de test') -Level 'warn' -Picto 'warn'
    return @{ Ok = $r.Ok; Swap = $r.Checked; Auto = $r.Auto; Brand = $r.ComboText }
}

function Start-UnattendedWrite([switch]$Restore, [switch]$Running) {
    # 12.9 (S1) : debut d une sequence d ecriture (bouton ECRIRE de l onglet Ecriture, boutons d ecriture de la
    # Bibliotheque, restauration) : case « Sans surveillance » cochee : ligne de journal et sequence suivie, la case est
    # decochee a sa fin (Update-CalibUnattended). Sans la case : rien.
    # Revue de la phase B (mineur 4) : ecriture que son point d entree va refuser (commande gw en cours ; -Restore :
    # toute operation, Get-AppBusy, comme Start-Restore) : ni ligne ni sequence suivie, la case reste cochee.
    # Mineur 3 : -Running, case cochee pendant une operation (520) : sequence en cours suivie, sans ce test
    if (-not $script:CalibUnattended) { return }
    if (-not $Running) {
        if ($script:GwProc -and -not $script:GwProc.HasExited) { return }
        if ($Restore -and (Get-AppBusy)) { return }
    }
    if (-not $script:UnattendedRun) {
        Append-Log ((T "Écriture sans surveillance : l'avertissement de calibration de la disquette à écrire sera validé seul après {0} s ; une calibration seule n'est jamais concernée.") -f "$([int]$script:CalibConfirmSeconds)")
    }
    $script:UnattendedRun = $true
}

function Test-UnattendedEnd([bool]$run, [bool]$idle, [bool]$gwDone, [bool]$canFocus) {
    # 12.9 (S1) : fin de la sequence d ecriture sans surveillance : sequence suivie et application au repos (Test-OpIdle :
    # ni gw, ni etape, ni calibration, ni controle, ni prechauffage, ni restauration, aucune fenetre modale), verifiee juste
    # apres la fin d une commande gw ou quand la fenetre principale peut recevoir le focus (aucune boite de message
    # ouverte), comme Update-OpOverride. Fin, annulation et erreur passent toutes par ce repos
    return ($run -and $idle -and ($gwDone -or $canFocus))
}

function Update-CalibUnattended([bool]$gwDone) {
    # 12.9 (S1) : minuteur principal : case « Sans surveillance » decochee a la fin de la sequence d ecriture
    if (-not $script:UnattendedRun) { return }
    if (-not (Test-UnattendedEnd $true (Test-OpIdle) $gwDone ([bool]$form.CanFocus))) { return }
    $script:UnattendedRun = $false
    $script:CalibUnattended = $false
    if ($chkWUnattended.Checked) { $chkWUnattended.Checked = $false }
    Append-Log (T "Écriture sans surveillance : option décochée (fin de l'écriture).")
}

function Show-CalibSurface($opt, [string]$text) {
    # Controle de surface : disquette de calibration douteuse a la premiere passe (Invoke-CalibAnalysis). Pas de compte a
    # rebours ni de decision automatique : la disquette inseree est peut-etre celle a ecrire. Fermeture (croix, Echap) :
    # Arreter. Renvoie @{ Choice = 'change' | 'continue' | 'stop' ; Swap }. 12.7 point 5 : $opt.Title, $opt.GoText (titre
    # et bouton « Continuer » de la variante 'level' : « Disquette a ecrire defectueuse », « Ecrire quand meme »)
    # 12.8 (lot 5, A4 R1 a R8, D15) : bandeau dont le pictogramme porte l icone d etat du lot 3, texte lblSurfText (Label de
    # premier niveau) ; etats du controle ($opt.States, Get-CalibSurfaceStates : faces, vitesse du lecteur, densite relue)
    # en icones ✓ / ! / ✗ ; cases en gras ; « Changer de disquette » en action principale, bleue et active seulement case
    # cochee (Set-PrimaryEnabled) ; sans elle, aucune action conseillee : « Continuer » ou « Ecrire quand meme » restent en
    # style normal (comme « Ecrire l image » sous l avertissement de frmCalibReview) ; « Arreter » en style danger ; images
    # liberees (Clear-DlgGdi) ; ajustement aux petits ecrans (Set-DlgFit). $opt.Speed : defaut de vitesse seul
    $W = 680
    $gdi = New-Object System.Collections.Generic.List[object]
    $dlg = New-Object System.Windows.Forms.Form
    $dlg.Name = 'frmCalibSurface'; $dlg.Text = $(if ($opt.Title) { [string]$opt.Title } else { (T 'Contrôle de surface') })
    $dlg.FormBorderStyle = 'FixedDialog'; $dlg.MaximizeBox = $false; $dlg.MinimizeBox = $false; $dlg.ShowInTaskbar = $false
    $dlg.StartPosition = 'CenterParent'; $dlg.Icon = $form.Icon; $dlg.Font = $form.Font; $dlg.BackColor = [System.Drawing.Color]::White
    $spd = [bool]$opt.Speed
    $heading = if ($spd) { (T 'Vitesse du lecteur hors tolérance') } elseif ([string]$opt.Variant -eq 'level') { (T 'Disquette à écrire défectueuse') } else { (T 'Disquette de calibration douteuse') }
    $ban = New-DlgBanner $dlg 16 $W $heading $text 'warn' (New-DlgPicto $(if ($spd) { 'drive' } else { 'disk' }) 'h2') $gdi 'lblSurfText'
    $tf = [System.Windows.Forms.TextFormatFlags]::WordBreak -bor [System.Windows.Forms.TextFormatFlags]::NoPrefix
    $y = $ban.Bottom + 12
    # Etats du controle, deux par ligne : icone d etat de 16 px (cache Get-QualityIcon, jamais liberee ici) et texte dans
    # l encre de son niveau (Get-QualInk) ; texte complet en infobulle s il est coupe (AutoEllipsis)
    $states = @(@($opt.States) | Where-Object { $_ })
    if ($states.Count -gt 0) {
        $pnlSt = New-Object System.Windows.Forms.Panel
        $pnlSt.Name = 'pnlSurfStates'; $pnlSt.Location = New-Object System.Drawing.Point(16, $y); $pnlSt.BackColor = [System.Drawing.Color]::White
        $colW = [int]($W / 2)
        for ($i = 0; $i -lt $states.Count; $i++) {
            $st = $states[$i]; $x = ($i % 2) * $colW; $ry = [int][math]::Floor($i / 2) * 24
            $ic = New-Object System.Windows.Forms.PictureBox
            $ic.Image = Get-QualityIcon ([string]$st.Kind) 16; $ic.Location = New-Object System.Drawing.Point($x, ($ry + 3)); $ic.Size = New-Object System.Drawing.Size(16, 16)
            $lt = New-Object System.Windows.Forms.Label
            $lt.Name = "lblSurfState$i"; $lt.Text = [string]$st.Text; $lt.AutoSize = $false; $lt.UseMnemonic = $false; $lt.AutoEllipsis = $true
            $lt.ForeColor = Get-QualInk $(switch ([string]$st.Kind) { 'h0' { 0 } 'h1' { 2 } default { 3 } })
            $lt.Location = New-Object System.Drawing.Point(($x + 22), ($ry + 2)); $lt.Size = New-Object System.Drawing.Size(($colW - 30), 20)
            $pnlSt.Controls.AddRange(@($ic, $lt))
        }
        $pnlSt.Size = New-Object System.Drawing.Size($W, ([int][math]::Ceiling($states.Count / 2) * 24))
        $dlg.Controls.Add($pnlSt)
        $y = $pnlSt.Bottom + 10
    }
    $chkNew = $null; $chkSwap = $null
    if ($opt.Change) {
        $chkNew = New-Object System.Windows.Forms.CheckBox
        $chkNew.Name = 'chkSurfNew'; $chkNew.Text = (T "J'ai inséré une autre disquette"); $chkNew.AutoSize = $true; $chkNew.UseMnemonic = $false; $chkNew.Font = $bold
        $chkNew.Location = New-Object System.Drawing.Point(16, $y); $dlg.Controls.Add($chkNew); $y += 28
        if ($opt.SwapBox) {
            $sl = (T "J'ai inséré une disquette sacrifiée : me redemander {0} après la calibration") -f (T 'la disquette à écrire')
            $chkSwap = New-Object System.Windows.Forms.CheckBox
            $chkSwap.Name = 'chkSurfSwap'; $chkSwap.Text = $sl; $chkSwap.AutoSize = $false; $chkSwap.UseMnemonic = $false; $chkSwap.Enabled = $false; $chkSwap.Font = $bold
            $chkSwap.CheckAlign = 'TopLeft'; $chkSwap.TextAlign = 'TopLeft'
            $hs = [System.Windows.Forms.TextRenderer]::MeasureText($sl, $bold, (New-Object System.Drawing.Size(($W - 44), 10000)), $tf).Height
            $chkSwap.Size = New-Object System.Drawing.Size(($W - 20), [math]::Max(24, ($hs + 6))); $chkSwap.Location = New-Object System.Drawing.Point(36, $y)
            $dlg.Controls.Add($chkSwap); $y = $chkSwap.Bottom + 4
        }
        $y += 6
    }
    $btnStop = New-Object System.Windows.Forms.Button
    $btnStop.Name = 'btnSurfStop'; $btnStop.Text = (T 'Arrêter'); $btnStop.DialogResult = [System.Windows.Forms.DialogResult]::Abort
    $btnStop.Size = New-Object System.Drawing.Size((Get-DlgButtonWidth $btnStop.Text 'Stop' 110), 34)
    $btnGo = New-Object System.Windows.Forms.Button
    $btnGo.Name = 'btnSurfContinue'; $btnGo.Text = $(if ($opt.GoText) { [string]$opt.GoText } else { (T 'Continuer') }); $btnGo.DialogResult = [System.Windows.Forms.DialogResult]::OK
    $btnGo.Size = New-Object System.Drawing.Size((Get-DlgButtonWidth $btnGo.Text '' 130), 34)
    Set-Btn $btnStop 'Stop' 'danger'; Set-Btn $btnGo '' 'normal'
    $btnStop.Location = New-Object System.Drawing.Point((16 + $W - $btnStop.Width), $y)
    $btnGo.Location = New-Object System.Drawing.Point(($btnStop.Left - 8 - $btnGo.Width), $y)
    $dlg.Controls.AddRange(@($btnGo, $btnStop))
    if ($opt.Change) {
        $btnCh = New-Object System.Windows.Forms.Button
        $btnCh.Name = 'btnSurfChange'; $btnCh.Text = (T 'Changer de disquette'); $btnCh.Size = New-Object System.Drawing.Size((Get-DlgButtonWidth (T 'Changer de disquette') 'Refresh' 170), 34)
        $btnCh.DialogResult = [System.Windows.Forms.DialogResult]::Retry
        Set-PrimaryEnabled $btnCh $false 'Refresh'
        $btnCh.Location = New-Object System.Drawing.Point(($btnGo.Left - 8 - $btnCh.Width), $y)
        $dlg.Controls.Add($btnCh)
        $chkNew.Add_CheckedChanged({
            $f = $this.FindForm()
            $b = $f.Controls.Find('btnSurfChange', $true); if ($b.Count) { Set-PrimaryEnabled $b[0] $this.Checked 'Refresh' }
            $s = $f.Controls.Find('chkSurfSwap', $true); if ($s.Count) { $s[0].Enabled = $this.Checked; if (-not $this.Checked) { $s[0].Checked = $false } }
        })
    }
    $dlg.ClientSize = New-Object System.Drawing.Size(($W + 32), ($y + 34 + 16))
    $dlg.CancelButton = $btnStop                   # Echap : Arreter ; croix : DialogResult Cancel, traite comme Arreter
    [void](Set-DlgFit $dlg ([System.Windows.Forms.Screen]::FromControl($form).WorkingArea))
    $dlg.Add_Shown({ $this.Activate(); $b = $this.Controls.Find('btnSurfStop', $true); if ($b.Count) { $this.ActiveControl = $b[0] }; try { [System.Media.SystemSounds]::Exclamation.Play() } catch { } })
    $swap = $false
    try { $dr = $dlg.ShowDialog($form); $swap = [bool]($chkSwap -and $chkSwap.Checked) } finally { Clear-DlgGdi $dlg $gdi }
    if ($dr -eq [System.Windows.Forms.DialogResult]::Retry) { return @{ Choice = 'change'; Swap = $swap } }
    if ($dr -eq [System.Windows.Forms.DialogResult]::OK) { return @{ Choice = 'continue'; Swap = $false } }
    return @{ Choice = 'stop'; Swap = $false }
}

function Show-CrossCalibDialog([string]$src, [string[]]$targets, [string]$family, [bool]$fine, [string]$imgInfo, [bool]$slow, [int]$minSwaps, [int]$maxSwaps, [string]$preselect = '') {
    # 12.10 : fenetre de choix d une calibration croisee (bouton de l onglet Ecriture, Start-CrossCalib, 270) : lecteur cible
    # (lecteurs du bandeau sauf la source $src), famille (standard ou long track, preselectionnee d apres l image de
    # l onglet Ecriture), test (standard ou fin, preselectionne d apres la liste « Calibration precomp »). Bandeau au
    # modele de frmClean (New-DlgBanner), trois listes, « Continuer » (principal) et « Annuler » (CancelButton : Echap et
    # la croix refusent ; aucun AcceptButton). L avertissement de la calibration (usure du support, case « disquette
    # sacrifiee dans la source » obligatoire) suit dans Start-PrecompCalib. Renvoie @{ Ok ; Target ; Family ('std' ou
    # 'long') ; Fine }. Banc : Name frmCrossCalib, cmbCrossTarget, cmbCrossFamily, cmbCrossTest, btnCrossOk, btnCrossCancel
    $W = 680
    $gdi = New-Object System.Collections.Generic.List[object]
    $dlg = New-Object System.Windows.Forms.Form
    $dlg.Name = 'frmCrossCalib'; $dlg.Text = (T 'Calibration precomp')
    $dlg.FormBorderStyle = 'FixedDialog'; $dlg.MaximizeBox = $false; $dlg.MinimizeBox = $false; $dlg.ShowInTaskbar = $false
    $dlg.StartPosition = 'CenterParent'; $dlg.Icon = $form.Icon; $dlg.Font = $form.Font; $dlg.BackColor = [System.Drawing.Color]::White
    $txt = ((T "Le lecteur {0}, choisi dans le bandeau, écrit le motif de test sur une disquette sacrifiée ; le lecteur cible relit chaque passe. À chaque demande de l'application, vous déplacez la disquette d'un lecteur à l'autre : {1} échanges au moins, {2} au plus si la courbe demande des passes supplémentaires. La courbe obtenue est enregistrée pour les écritures du lecteur {0} destinées au lecteur cible ; la courbe propre du lecteur {0} n'est pas modifiée.") -f "$src", "$minSwaps", "$maxSwaps")
    $txt += "`n" + $imgInfo
    $txt += "`n" + ((T "Courbes : {0} (case « Écriture lente » de l'onglet).") -f $(if ($slow) { (T 'une courbe par tête') } else { (T 'courbe commune') }))
    $ban = New-DlgBanner $dlg 16 $W (T 'Calibration croisée : écrire avec ce lecteur pour un autre lecteur') $txt 'info' (New-DlgPicto 'drive') $gdi 'lblCrossText'
    $y = $ban.Bottom + 14
    $rows = @(@{ Name = 'cmbCrossTarget'; Label = (T 'Lecteur cible :'); Items = @($targets); Index = (Get-CrossTargetIndex $targets $preselect) },   # 12.11 : $preselect, lecteur cible de l onglet Ecriture, preselectionne (240) ; sinon le premier
              @{ Name = 'cmbCrossFamily'; Label = (T 'Famille :'); Items = @((Get-CalibFamilyName 'std'), (Get-CalibFamilyName 'long')); Index = $(if ($family -eq 'long') { 1 } else { 0 }) },
              @{ Name = 'cmbCrossTest'; Label = (T 'Test :'); Items = @((T 'Test standard : 1 cylindre sur 10'), (T 'Test fin : tous les cylindres')); Index = $(if ($fine) { 1 } else { 0 }) })
    $lw = 0
    foreach ($r in $rows) { $lw = [math]::Max($lw, [System.Windows.Forms.TextRenderer]::MeasureText([string]$r.Label, $dlg.Font).Width) }
    $cmbs = @{}
    foreach ($r in $rows) {
        $lbl = New-Object System.Windows.Forms.Label
        $lbl.AutoSize = $true; $lbl.UseMnemonic = $false; $lbl.Text = [string]$r.Label; $lbl.Font = $dlg.Font
        $lbl.Location = New-Object System.Drawing.Point(16, ($y + 4))
        $cmb = New-Object System.Windows.Forms.ComboBox
        $cmb.Name = [string]$r.Name; $cmb.DropDownStyle = 'DropDownList'; $cmb.Width = 300
        foreach ($it in @($r.Items)) { if ($null -ne $it) { [void]$cmb.Items.Add([string]$it) } }
        if ($cmb.Items.Count -gt 0) { $cmb.SelectedIndex = [math]::Min([int]$r.Index, $cmb.Items.Count - 1) }
        $cmb.Location = New-Object System.Drawing.Point((16 + $lw + 12), $y)
        $dlg.Controls.Add($lbl); $dlg.Controls.Add($cmb)
        $cmbs[[string]$r.Name] = $cmb
        $y = $cmb.Bottom + 10
    }
    $y += 4
    $btnOk = New-Object System.Windows.Forms.Button
    $btnOk.Name = 'btnCrossOk'; $btnOk.Text = (T 'Continuer'); $btnOk.Size = New-Object System.Drawing.Size((Get-DlgButtonWidth (T 'Continuer') 'Diagnostic' 170), 34)
    $btnOk.DialogResult = [System.Windows.Forms.DialogResult]::OK
    $btnNo = New-Object System.Windows.Forms.Button
    $btnNo.Name = 'btnCrossCancel'; $btnNo.Text = (T 'Annuler'); $btnNo.Size = New-Object System.Drawing.Size(110, 34)
    $btnNo.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
    Set-Btn $btnOk 'Diagnostic' 'primary'; Set-Btn $btnNo '' 'normal'
    $btnNo.Location = New-Object System.Drawing.Point((16 + $W - $btnNo.Width), $y)
    $btnOk.Location = New-Object System.Drawing.Point(($btnNo.Left - 8 - $btnOk.Width), $y)
    $dlg.ClientSize = New-Object System.Drawing.Size(($W + 32), ($y + $btnOk.Height + 16))
    $dlg.CancelButton = $btnNo                        # pas d AcceptButton : Entree ne lance rien
    $dlg.Controls.AddRange(@($btnOk, $btnNo))
    $dlg.ActiveControl = $cmbs['cmbCrossTarget']
    [void](Set-DlgFit $dlg ([System.Windows.Forms.Screen]::FromControl($form).WorkingArea))
    $dlg.Add_Shown({ $this.Activate() })
    $res = @{ Ok = $false; Target = ''; Family = 'std'; Fine = $false }
    try {
        $dr = $dlg.ShowDialog($form)
        $res.Ok = ($dr -eq [System.Windows.Forms.DialogResult]::OK -and $cmbs['cmbCrossTarget'].SelectedIndex -ge 0)
        $res.Target = [string]$cmbs['cmbCrossTarget'].Text
        $res.Family = $(if ($cmbs['cmbCrossFamily'].SelectedIndex -eq 1) { 'long' } else { 'std' })
        $res.Fine = ($cmbs['cmbCrossTest'].SelectedIndex -eq 1)
    } finally { Clear-DlgGdi $dlg $gdi }
    return $res
}

function New-CalibBackDialog($items, [int]$nFiles, [string[]]$skipped) {
    # 12.11 (L7) : fenetre « Revenir a une calibration precedente » (frmCalibBack), construite sans etre affichee
    # (Show-CalibBackDialog l affiche), au modele de frmCrossCalib : bandeau (New-DlgBanner, lblCalBackText), liste
    # lvCalBack (une ligne par calibration, une seule selection), detail lblCalBackInfo, pied lblCalBackSkip (copies
    # illisibles ou sans courbe), « Retablir cette calibration » (btnCalBackGo, principal, inactif sans selection et pour
    # une ligne qui ne peut pas etre retablie) et « Fermer » (btnCalBackClose : CancelButton et focus initial ; aucun
    # AcceptButton, Entree ne retablit rien). Colonnes « Lecteur » et « Calcul », detail et bouton viennent de Get-CalibBackInfo (240), la
    # fonction qui decide : la fenetre ne decide rien. Rend @{ Dlg ; Lv ; Info ; Skip ; Go ; Close ; Items ; Infos ; Gdi }
    $W = 966
    $gdi = New-Object System.Collections.Generic.List[object]
    $dlg = New-Object System.Windows.Forms.Form
    $dlg.Name = 'frmCalibBack'; $dlg.Text = (T 'Revenir à une calibration précédente')
    $dlg.FormBorderStyle = 'FixedDialog'; $dlg.MaximizeBox = $false; $dlg.MinimizeBox = $false; $dlg.ShowInTaskbar = $false
    $dlg.StartPosition = 'CenterParent'; $dlg.Icon = $form.Icon; $dlg.Font = $form.Font; $dlg.BackColor = [System.Drawing.Color]::White
    $leaf = [System.IO.Path]::GetFileName([string]$script:ConfigFile)
    $txt = (T "Calibrations complètes trouvées dans {0} copie(s) de la configuration, différentes des courbes en place. Choisissez une ligne, puis « Rétablir cette calibration ». Seules les courbes de cette ligne changent ; l'état actuel est d'abord copié dans un fichier « {1}.ref-….bak », d'où ce retour s'annule de la même façon.") -f "$nFiles", "$leaf"
    $ban = New-DlgBanner $dlg 16 $W (T 'Quelle calibration rétablir ?') $txt 'info' (New-DlgPicto 'curve') $gdi 'lblCalBackText'
    $y = $ban.Bottom + 14
    $lv = New-Object System.Windows.Forms.ListView
    $lv.Name = 'lvCalBack'; $lv.View = 'Details'; $lv.FullRowSelect = $true; $lv.MultiSelect = $false; $lv.HideSelection = $false
    $lv.HeaderStyle = 'Nonclickable'; $lv.Font = $dlg.Font
    $lv.Location = New-Object System.Drawing.Point(16, $y); $lv.Size = New-Object System.Drawing.Size($W, 200)
    # Colonnes : la derniere (« Copie », nom de la copie sans celui du fichier de configuration) prend la largeur qui reste
    # quand la barre verticale parait (213 px : « ref-long+std-<date>.bak » entier). Largeurs mesurees en Segoe UI 9.75, marge
    # de 12 px : date, nom de lecteur le plus large admis, familles, tests, calcul « v12.10 (other calculation) » entiers ; un
    # texte plus long (lecteur avec son nom de l epoque, courbe conservee, copie a suffixe -r) est coupe dans la liste et se
    # lit en entier dans le detail
    $cols = @(@((T 'Calibration du'), 122), @((T 'Lecteur'), 138), @((T 'Famille'), 128), @((T 'Courbes'), 80), @((T 'Test'), 98), @((T 'Calcul'), 166))
    $used = 0
    foreach ($c in $cols) { [void]$lv.Columns.Add([string]$c[0], [int]$c[1]); $used += [int]$c[1] }
    [void]$lv.Columns.Add((T 'Copie'), [int][math]::Max(120, $W - 4 - [System.Windows.Forms.SystemInformation]::VerticalScrollBarWidth - $used))
    $infos = @()
    foreach ($it in @($items)) {
        $inf = Get-CalibBackInfo $it
        $infos += ,$inf
        $calc = [string]$inf.CalcText   # 12.11 (relecture) : texte decide par Get-CalibBackInfo
        $copy = [string]$it.FileName
        if ($leaf -and $copy.StartsWith($leaf + '.', [System.StringComparison]::OrdinalIgnoreCase)) { $copy = $copy.Substring($leaf.Length + 1) }
        $row = New-Object System.Windows.Forms.ListViewItem([string]$it.Date)
        foreach ($s in @([string]$inf.DriveText, (Get-CalibFamilyName ([string]$it.Family)), (Get-CalibBackHeadsText @($it.CurveKeys)), (Get-CalibBackTestText ([string]$it.Test)), $calc, $copy)) { [void]$row.SubItems.Add([string]$s) }
        if (-not $inf.Ok) { $row.ForeColor = [System.Drawing.Color]::Gray }
        [void]$lv.Items.Add($row)
    }
    $y = $lv.Bottom + 10
    # Detail : hauteur du plus long des textes, pour que rien ne bouge d une ligne a l autre
    $tf = [System.Windows.Forms.TextFormatFlags]::WordBreak -bor [System.Windows.Forms.TextFormatFlags]::NoPrefix
    $h = 3 * [System.Windows.Forms.TextRenderer]::MeasureText('X', $dlg.Font).Height
    foreach ($inf in $infos) { $h = [math]::Max($h, [System.Windows.Forms.TextRenderer]::MeasureText([string]$inf.Text, $dlg.Font, (New-Object System.Drawing.Size($W, 10000)), $tf).Height) }
    $lbl = New-Object System.Windows.Forms.Label
    $lbl.Name = 'lblCalBackInfo'; $lbl.AutoSize = $false; $lbl.UseMnemonic = $false; $lbl.Font = $dlg.Font
    $lbl.Location = New-Object System.Drawing.Point(16, $y); $lbl.Size = New-Object System.Drawing.Size($W, ($h + 4))
    $y = $lbl.Bottom + 8
    $skip = New-Object System.Windows.Forms.Label
    $skip.Name = 'lblCalBackSkip'; $skip.AutoSize = $false; $skip.UseMnemonic = $false; $skip.Font = $dlg.Font; $skip.ForeColor = [System.Drawing.Color]::DimGray
    $skip.Location = New-Object System.Drawing.Point(16, $y)
    if (@($skipped).Count -gt 0) {
        $skip.Text = (T 'Copies illisibles ou sans courbe, non listées : {0}.') -f ((@($skipped) | ForEach-Object { [string]$_ }) -join ', ')
        $skip.Size = New-Object System.Drawing.Size($W, ([System.Windows.Forms.TextRenderer]::MeasureText($skip.Text, $dlg.Font, (New-Object System.Drawing.Size($W, 10000)), $tf).Height + 4))
        $y = $skip.Bottom + 8
    } else { $skip.Size = New-Object System.Drawing.Size($W, 0); $skip.Visible = $false }
    $y += 4
    $btnGo = New-Object System.Windows.Forms.Button
    $btnGo.Name = 'btnCalBackGo'; $btnGo.Text = (T 'Rétablir cette calibration'); $btnGo.Size = New-Object System.Drawing.Size((Get-DlgButtonWidth (T 'Rétablir cette calibration') 'History' 170), 34)
    $btnGo.DialogResult = [System.Windows.Forms.DialogResult]::OK
    $btnCl = New-Object System.Windows.Forms.Button
    $btnCl.Name = 'btnCalBackClose'; $btnCl.Text = (T 'Fermer'); $btnCl.Size = New-Object System.Drawing.Size(110, 34)
    $btnCl.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
    Set-Btn $btnCl '' 'normal'
    Set-PrimaryEnabled $btnGo $false 'History'
    $btnCl.Location = New-Object System.Drawing.Point((16 + $W - $btnCl.Width), $y)
    $btnGo.Location = New-Object System.Drawing.Point(($btnCl.Left - 8 - $btnGo.Width), $y)
    $dlg.ClientSize = New-Object System.Drawing.Size(($W + 32), ($y + 34 + 16))
    $dlg.Controls.AddRange(@($lv, $lbl, $skip, $btnGo, $btnCl))
    $dlg.CancelButton = $btnCl; $dlg.ActiveControl = $btnCl   # pas d AcceptButton : Entree ne retablit rien
    $st = @{ Dlg = $dlg; Lv = $lv; Info = $lbl; Skip = $skip; Go = $btnGo; Close = $btnCl; Items = @($items); Infos = $infos; Gdi = $gdi }
    $lv.Tag = $st
    $lv.Add_SelectedIndexChanged({ Update-CalibBackDialog $this.Tag (Get-CalibBackDialogIndex $this) })
    return $st
}

function Get-CalibBackDialogIndex($lv) {
    # 12.11 (L7) : rang de la ligne selectionnee de lvCalBack, -1 sans selection ; lu sur les lignes elles-memes (Selected),
    # juste que la liste ait ou non son handle (SelectedIndices reste vide tant que la liste n a pas ete affichee)
    if (-not $lv) { return -1 }
    for ($i = 0; $i -lt $lv.Items.Count; $i++) { if ($lv.Items[$i].Selected) { return $i } }
    return -1
}

function Update-CalibBackDialog($st, [int]$i) {
    # 12.11 (L7) : selection de la liste de frmCalibBack : detail et bouton « Retablir cette calibration » de la ligne $i
    # (-1 : aucune), tires de Get-CalibBackInfo
    if (-not $st) { return }
    $infos = @($st.Infos)
    if ($i -ge 0 -and $i -lt $infos.Count) { $st.Info.Text = [string]$infos[$i].Text; Set-PrimaryEnabled $st.Go ([bool]$infos[$i].Ok) 'History' }
    else { $st.Info.Text = ''; Set-PrimaryEnabled $st.Go $false 'History' }
}

function Get-CalibBackDialogPick($st, $dr) {
    # 12.11 (L7) : ligne choisie dans frmCalibBack : « Retablir cette calibration » (OK) sur une ligne selectionnee que
    # Get-CalibBackInfo dit retablissable ; sinon $null (« Fermer », Echap, croix)
    if (-not $st -or $dr -ne [System.Windows.Forms.DialogResult]::OK) { return $null }
    $i = Get-CalibBackDialogIndex $st.Lv
    $items = @($st.Items); $infos = @($st.Infos)
    if ($i -lt 0 -or $i -ge $items.Count -or -not [bool]$infos[$i].Ok) { return $null }
    return $items[$i]
}

function Show-CalibBackDialog($items, [int]$nFiles, [string[]]$skipped) {
    # 12.11 (L7) : affiche frmCalibBack (New-CalibBackDialog) ; rend la ligne choisie ou $null
    $st = New-CalibBackDialog $items $nFiles $skipped
    $dlg = $st.Dlg
    [void](Set-DlgFit $dlg ([System.Windows.Forms.Screen]::FromControl($form).WorkingArea))
    $dlg.Add_Shown({ $this.Activate() })
    $pick = $null
    try {
        $dr = $dlg.ShowDialog($form)
        $pick = Get-CalibBackDialogPick $st $dr
    } finally { Clear-DlgGdi $dlg $st.Gdi }
    return $pick
}
# ============================== FONCTIONS : CALIBRATION RAPIDE (NIVEAU) ========

# ============================== CALIBRATION RAPIDE (NIVEAU PAR DISQUETTE) ======
# Observation sur materiel reel : la forme de la courbe tient au lecteur, son niveau au support. La courbe d une
# calibration complete (reference, jamais modifiee) est decalee d un niveau uniforme mesure sur la disquette qui va
# recevoir l image : 6 cylindres de niveau pris parmi les mesures verifiees de la reference, 2 temoins de marche et
# 1 temoin du plafond au plus, 1 a 3 passes qui ecrivent la reference decalee (le niveau retenu est celui d une passe
# ecrite et verifiee). Le resultat ne va que dans les champs --precomp de l ecriture qui suit et dans
# $script:LevelShifts (affichage, historique, niveau de depart).

function Format-LevelNum($x) {
    # Nombre d un texte de la calibration rapide : une decimale au plus, au format de la culture ; '-' si non defini
    if ($null -eq $x -or [double]::IsNaN([double]$x)) { return '-' }
    return ('{0:0.#}' -f [math]::Round([double]$x, 1))
}

function Get-WeightedMedian($v, $w) {
    $n = @($v).Count
    if ($n -eq 0) { return [double]::NaN }
    $idx = @(0..($n - 1) | Sort-Object { [double]$v[$_] })
    $tot = 0.0; foreach ($x in @($w)) { $tot += [double]$x }
    $acc = 0.0
    foreach ($i in $idx) { $acc += [double]$w[$i]; if ($acc -ge $tot / 2) { return [double]$v[$i] } }
    return [double]$v[$idx[-1]]
}

function Get-LevelZero($points, [double]$k) {
    # Zero d un cylindre en precomp absolue (k = pente en valeur absolue) : Get-CalibZero avec deux mesures ou plus ;
    # avec une seule, extrapolation par la pente, encadree si le decalage est dans deux erreurs-types
    if (-not $points) { return $null }
    $xs = @($points.Keys | ForEach-Object { [int]$_ })
    if ($xs.Count -ge 2) { return (Get-CalibZero $points (-$k)) }
    if ($xs.Count -eq 0) { return $null }
    $x = $xs[0]; $m = $points[$x]
    $e = if ($null -eq $m.SE -or [double]::IsNaN([double]$m.SE) -or [double]$m.SE -le 0) { 2.0 } else { [double]$m.SE }
    $x0 = $x + [double]$m.Shift / $k
    $sig = [math]::Sqrt([math]::Pow($e / $k, 2) + [math]::Pow(0.25 * [math]::Abs($x0 - $x), 2))
    if ([math]::Abs([double]$m.Shift) -le 2.0 * $e) { return (Limit-CalibZero $x0 $sig 'interp' (-$k) $false) }
    return (Limit-CalibZero $x0 ([math]::Max(5.0, $sig)) 'extrap' (-$k) $false)
}

function Get-LevelCands($cv, [int]$last) {
    # Cylindres candidats d une reference : mesures encadrees et verifiees, loin des changements de sens, voisinage plat ;
    # zone plafonnee terminale et son temoin ; temoins de marche (sommet et cylindre mesure suivant)
    $V = @($cv.Values); $cyls = @(@($cv.Cyls) | ForEach-Object { [int]$_ })
    $brk = @(@($cv.Breaks) | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_ })
    # Zone plafonnee : fin de la reference a la borne de SON calcul (300 ns avant le calcul 12.4, Get-CurveMaxNs)
    $max = Get-CurveMaxNs $cv
    $capLo = $V.Count
    for ($c = $V.Count - 1; $c -ge 0; $c--) { if ([int]$V[$c] -ge $max) { $capLo = $c } else { break } }
    $probe = $null; if ($capLo -le $last) { $probe = $last }
    $pick = {
        param([int]$lo, [double]$vLo, [double]$vHi, [double]$resMax)
        $out = @()
        for ($i = 0; $i -lt $cyls.Count; $i++) {
            $c = $cyls[$i]
            if ($c -lt $lo -or $c -gt $last -or $c -ge $capLo) { continue }
            $kind = if ($cv.Kinds -and $i -lt @($cv.Kinds).Count) { [string]$cv.Kinds[$i] } else { 'interp' }
            if ($kind -ne 'interp' -or (Test-CurvePointFlag $cv $i)) { continue }
            $res = if ($cv.Res -and $i -lt @($cv.Res).Count) { [double]$cv.Res[$i] } else { [double]::NaN }
            if ([double]::IsNaN($res) -or [math]::Abs($res) -gt $resMax) { continue }
            $vc = [double]$V[$c]
            if ($vc -lt $vLo -or $vc -gt $vHi) { continue }
            $near = $false; foreach ($b in $brk) { if ([math]::Abs($c - $b) -le 1 -or [math]::Abs($c - ($b + 1)) -le 1) { $near = $true } }
            if ($near) { continue }
            if ($c -gt 0 -and [math]::Abs($vc - [double]$V[$c - 1]) -gt $script:LevelSteep) { continue }
            if ($c + 1 -lt $V.Count -and [math]::Abs([double]$V[$c + 1] - $vc) -gt $script:LevelSteep) { continue }
            $out += $c
        }
        return $out
    }
    $cand = @(& $pick 2 $script:LevelLo $script:LevelHi $script:CalResidual)
    $fb = $false
    if ($cand.Count -lt $script:LevelMinCyls) { $cand = @(& $pick 0 5 290 12); $fb = $true }     # repli : 10 ns sous le plafond des passes de mesure (300 ns)
    $wit = @()
    if ($brk.Count -ge 1) {
        $pk = $brk[0]; $ip = [array]::IndexOf([int[]]$cyls, [int]$pk)
        if ($ip -ge 0 -and $ip + 1 -lt $cyls.Count) {
            $nx = $cyls[$ip + 1]
            $good = { param($i) ((-not $cv.Kinds) -or [string]$cv.Kinds[$i] -eq 'interp') -and -not (Test-CurvePointFlag $cv $i) }
            if (($nx - $pk) -le 3 -and $nx -le $last -and (& $good $ip) -and (& $good ($ip + 1)) -and ([double]$V[$pk] - [double]$V[$nx]) -ge 30) { $wit = @($pk, $nx) }
        }
    }
    return @{ Cands = $cand; CapLo = $capLo; Wit = $wit; Probe = $probe; Fallback = $fb }
}

function Select-LevelCyls([int[]]$cand, [int[]]$brk, [int]$n) {
    # Selection deterministe : extremites (bras de levier), voisins de chaque changement de sens, puis le plus eloigne
    $c = @($cand | Sort-Object -Unique)
    if ($c.Count -le $n) { return ,[int[]]$c }
    $sel = New-Object System.Collections.Generic.List[int]
    $sel.Add($c[0]); if (-not $sel.Contains($c[-1])) { $sel.Add($c[-1]) }
    foreach ($b in @($brk)) {
        $l = @($c | Where-Object { $_ -le $b }); $r = @($c | Where-Object { $_ -gt $b + 1 })
        if ($l.Count -gt 0 -and -not $sel.Contains($l[-1]) -and $sel.Count -lt $n) { $sel.Add($l[-1]) }
        if ($r.Count -gt 0 -and -not $sel.Contains($r[0]) -and $sel.Count -lt $n) { $sel.Add($r[0]) }
    }
    while ($sel.Count -lt $n) {
        $best = -1; $bd = -1
        foreach ($x in $c) {
            if ($sel.Contains($x)) { continue }
            $d = (@($sel) | ForEach-Object { [math]::Abs($x - $_) } | Measure-Object -Minimum).Minimum
            if ($d -gt $bd) { $bd = $d; $best = $x }
        }
        if ($best -lt 0) { break }
        $sel.Add($best)
    }
    return ,[int[]]@($sel | Sort-Object)
}

function Get-LevelRef([string]$fam, [bool]$heads, [string]$drive, [string]$img, [bool]$restore, [int]$NCyl = 0, [int]$Bits = 0, [switch]$ForHome) {
    # Reference de forme pour la calibration rapide. Class 'redo' : calibration complete necessaire ; 'domain' : image
    # hors du domaine de la reference (geometrie, densite), Short si la reference a moins de cylindres que l image. NCyl,
    # Bits (> 0) : cylindres et cellules par piste donnes a la place de ceux de l image (format d une image secteur,
    # fenetre de la carte Calibration sans image). ForHome : carte Calibration de l Accueil (type de disquette, sans image :
    # raisons et notes parlent du type). Variables locales $nc et $pbits : $nCyl et $bits designeraient les parametres
    # types [int] (noms insensibles a la casse)
    $res = @{ Ok = $false; Class = 'redo'; Why = ''; Units = @(); Notes = @(); NCyl = 80; MaxCyl = 79; Family = $fam; Short = $false }
    # 12.7 : pas de calibration rapide en haute densite (seuils regles sur des donnees double densite, non transposes) :
    # hors domaine, sans offre de calibration complete en boucle
    if ($fam -eq 'hd') { $res.Class = 'domain'; $res.Why = (T "la haute densité n'a pas encore de calibration rapide : faites une calibration complète"); return $res }
    $nc = if ($NCyl -gt 0) { $NCyl } else { Get-ImageCylinders $img }; if ($null -eq $nc) { $nc = 80 }
    $nc = [math]::Max(2, [math]::Min(84, [int]$nc)); $res.NCyl = $nc; $res.MaxCyl = $nc - 1
    $specs = @()
    if (-not $heads) {
        $cv = $script:PrecompCurves[$fam]
        if (-not $cv) { $res.Why = (T "aucune calibration commune pour la famille {0}") -f (Get-CalibFamilyName $fam); return $res }
        $specs = @(@{ Key = $fam; Tag = 'c'; Head = $null; Cv = $cv })
    } elseif (Test-HeadCurvesCurrent $fam) {
        $specs = @(@{ Key = "${fam}_h0"; Tag = '0'; Head = 0; Cv = $script:PrecompCurves["${fam}_h0"] }, @{ Key = "${fam}_h1"; Tag = '1'; Head = 1; Cv = $script:PrecompCurves["${fam}_h1"] })
    } elseif ($restore -and $script:PrecompCurves[$fam]) {
        $cv = $script:PrecompCurves[$fam]
        $specs = @(@{ Key = $fam; Tag = '0'; Head = 0; Cv = $cv }, @{ Key = $fam; Tag = '1'; Head = 1; Cv = $cv })
    } else { $res.Why = (T "aucune calibration par tête à jour pour la famille {0}") -f (Get-CalibFamilyName $fam); return $res }
    foreach ($s in $specs) {
        $cv = $s.Cv
        if ($cv.Method -ne 'motif') { $res.Why = (T 'référence mesurée sur le contenu d''une image, avant le motif de test'); return $res }
        if ([string]$cv.Drive -ne $drive) { $res.Why = (T "référence mesurée sur le lecteur {0}, et non {1}") -f "$($cv.Drive)", "$drive"; return $res }
        if ($null -eq $cv.Slope -or -not $cv.Bits) { $res.Why = (T 'référence antérieure à la calibration rapide (pente ou densité non enregistrée)'); return $res }
    }
    $vc = @($specs[0].Cv.Values).Count
    if ([math]::Abs($nc - $vc) -gt 4) {
        $res.Class = 'domain'; $res.Short = ($vc -lt $nc)
        $res.Why = $(if ($ForHome) { (T "type de {0} cylindres, référence de {1}") } else { (T "image de {0} cylindres, référence de {1}") }) -f "$nc", "$vc"; return $res
    }
    $pbits = [double]$(if ($Bits -gt 0) { $Bits } else { (Get-PatternBits $fam $img).Bits }); $rb = [double]$specs[0].Cv.Bits
    $dev = [math]::Abs($pbits - $rb) / $rb
    $devTxt = Format-UiNum ([math]::Round(100 * $dev, 1)) '0.#'
    if ($dev -gt $script:LevelBitsMax) { $res.Class = 'domain'; $res.Why = $(if ($ForHome) { (T "densité de ce type différente de celle de la référence de {0} % (5 % au plus)") } else { (T "densité de l'image différente de celle de la référence de {0} % (5 % au plus)") }) -f "$devTxt"; return $res }
    if ($dev -gt $script:LevelBitsNote) { $res.Notes += ($(if ($ForHome) { (T "Densité de ce type différente de celle de la référence de {0} %.") } else { (T "Densité de l'image différente de celle de la référence de {0} %.") }) -f "$devTxt") }
    $last = [math]::Min($nc - 1, $vc - 1)
    $cands = @(); foreach ($s in $specs) { $cands += ,(Get-LevelCands $s.Cv $last) }
    $common = $null
    if ($specs.Count -eq 2) {
        $inter = @(@($cands[0].Cands) | Where-Object { @($cands[1].Cands) -contains $_ })
        if ($inter.Count -ge $script:LevelMinCyls) {
            $brkU = @(@(@($specs[0].Cv.Breaks) + @($specs[1].Cv.Breaks)) | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_ } | Sort-Object -Unique)
            $common = Select-LevelCyls ([int[]]$inter) ([int[]]$brkU) $script:LevelCyls
        }
    }
    $units = @()
    for ($i = 0; $i -lt $specs.Count; $i++) {
        $s = $specs[$i]; $cd = $cands[$i]; $cv = $s.Cv
        $sel = if ($null -ne $common) { $common } else { Select-LevelCyls ([int[]]@($cd.Cands)) ([int[]]@(@($cv.Breaks) | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_ })) $script:LevelCyls }
        if (@($sel).Count -lt $script:LevelMinCyls) { $res.Why = (T "trop peu de cylindres de mesure fiables dans la référence ({0}, {1} au moins)") -f "$(@($sel).Count)", "$($script:LevelMinCyls)"; return $res }
        $kref = [math]::Max($script:LevelKMin, [math]::Min(3.0, -[double]$cv.Slope))
        $hk = "$($s.Key)|$($s.Tag)"; $old = $script:LevelShifts[$hk]
        $d0 = 0; $nh = 0
        if ($old -and [string]$old.RefDate -eq [string]$cv.Date -and @($old.Hist).Count -gt 0) {
            $hv = @(@($old.Hist) | Select-Object -Last 4 | ForEach-Object { [double]$_.Delta }); $nh = $hv.Count
            $d0 = [int][math]::Round((Get-Median (@(0.0) + $hv)))
        }
        $units += ,@{ RefKey = $s.Key; Tag = $s.Tag; Head = $s.Head; Cv = $cv; V = [int[]]@($cv.Values); KRef = $kref; LCyls = [int[]]@($sel)
                      Wit = [int[]]@($cd.Wit); Probe = $cd.Probe; CapLo = [int]$cd.CapLo; D0 = $d0; NHist = $nh }
    }
    if (@($specs | Where-Object { $_.Cv.Converged -eq $false }).Count -gt 0) { $res.Notes += (T 'Référence non convergée : ses cylindres hors tolérance sont exclus de la mesure ; une calibration complète en test fin est conseillée.') }
    $kcv = @($specs | Where-Object { (Get-CurveCalc $_.Cv) -ne (Get-CurveCalcRef $_.Cv) })
    if ($kcv.Count -gt 0) { $res.Notes += ((T "Référence faite avec le calcul de calibration {0}.") -f (Get-CurveCalcText $kcv[0].Cv)) }
    if (@($specs | Where-Object { [string]$_.Cv.Test -eq 'std' }).Count -gt 0) { $res.Notes += (T 'Référence en test standard : entre les cylindres mesurés, la forme est interpolée ; une référence en test fin est conseillée.') }
    if (@($cands | Where-Object { $_.Fallback }).Count -gt 0) { $res.Notes += (T "Trop peu de cylindres de mesure selon les règles habituelles : règles élargies (cylindres 0 et 1 admis, valeurs de 5 à 290 ns, résidu de référence jusqu'à 12 ns).") }
    $res.Ok = $true; $res.Units = $units; $res.Why = ''
    return $res
}

function Set-LevelTargets($u) {
    # Cibles de la passe : reference decalee du niveau courant (cylindres de niveau et temoins de marche) ; temoin du
    # plafond : reference decalee a la premiere passe, puis son zero estime tant qu il n est pas resolu. Valeurs ecrites
    # bornees a la borne absolue CalHardNs (le temoin d une reference plafonnee a 300 ns peut etre ecrit au-dela)
    $max = [int]$script:CalHardNs
    $t = @{}
    foreach ($c in @(@($u.LCyls) + @($u.Wit))) { $t[[int]$c] = [int][math]::Max(0, [math]::Min($max, [math]::Round([double]$u.V[[int]$c] + $u.D))) }
    if ($null -ne $u.Probe -and -not $u.ProbeDone) {
        $p = [int]$u.Probe
        $t[$p] = if ($null -ne $u.ProbeZ) { [int][math]::Max(0, [math]::Min($max, [math]::Round([double]$u.ProbeZ))) } else { [int][math]::Max(0, [math]::Min($max, [math]::Round([double]$u.V[$p] + $u.D))) }
    }
    $u.LTarget = $t
}

function Get-LevelEstimate($u, [int]$pass) {
    # Niveau estime (ecart entre zero mesure et reference, moyenne ponderee avec plancher tau0), ecart de forme, residu
    # moyen de la passe ecrite, temoins ; cibles a 0 ou a la borne CalHardNs (ecretees) hors pente et residu
    $max = [double]$script:CalHardNs
    $k = [double]$u.KRef; $kRaw = $null
    $kSpan = 0.0
    if ($pass -ge 2) {
        $sl = @(); $spans = @()
        foreach ($c in @($u.LCyls)) {
            $pts = $u.Results[[int]$c]; if (-not $pts) { continue }
            $xs = @($pts.Keys | ForEach-Object { [int]$_ } | Where-Object { $_ -gt 0 -and $_ -lt $max } | Sort-Object)
            if ($xs.Count -lt 2 -or ($xs[-1] - $xs[0]) -lt 4) { continue }
            $sl += ([double]$pts[$xs[-1]].Shift - [double]$pts[$xs[0]].Shift) / ($xs[-1] - $xs[0]); $spans += ($xs[-1] - $xs[0])
        }
        if ($sl.Count -gt 0) { $kSpan = [double](Get-Median $spans); $kRaw = [double](Get-Median $sl); if ($kRaw -lt -0.2) { $k = [math]::Max($script:LevelKMin, [math]::Min(3.0, -$kRaw)) } }
    }
    $ds = @{}; $sg = @{}; $kinds = @{}; $capped = @(); $floored = @()
    foreach ($c in @($u.LCyls)) {
        $z = Get-LevelZero $u.Results[[int]$c] $k
        if (-not $z) { continue }
        # Zero borne : a la borne CalHardNs (besoin au-dela) ou au plancher de 0 ns (precompensation nulle encore excessive)
        if ($z.Kind -eq 'cap') { if ([double]$z.Est -le 0) { $floored += [int]$c } else { $capped += [int]$c }; $kinds[[int]$c] = 'cap'; continue }
        $ds[[int]$c] = [double]$z.Est - [double]$u.V[[int]$c]; $sg[[int]$c] = [double]$z.Sig; $kinds[[int]$c] = [string]$z.Kind
    }
    # 12.8 (lot 1c) : partie statistique commune avec Get-LevelKrefEstimate (Get-LevelStats, calcul inchange)
    $st = Get-LevelStats $ds $sg
    $keep = $st.Keep; $n = $st.N
    $e = @{ N = $n; K = $k; KRaw = $kRaw; KSpan = $kSpan; Ds = $ds; Sigs = $sg; Kinds = $kinds; Capped = $capped; Floored = $floored; Outliers = $st.Outliers; Scatter = $st.Scatter; Keep = $keep; W = $st.W
            Delta = $st.Delta; SE = $st.SE; Tau = $st.Tau; Rbar = [double]::NaN; RTol = [double]$script:CalResidual * [math]::Min(1.0, $k / 2.0); Wit = @{}; ProbeZ = $null; ProbeKind = '' }
    if ($n -ge 1) {
        $rs = @()
        foreach ($c in $keep) {
            $tg = [int]$u.LTarget[[int]$c]
            if ($tg -le 0 -or $tg -ge [int]$max) { continue }
            $pt = $u.Results[[int]$c][$tg]; if ($pt) { $rs += [double]$pt.Shift }
        }
        if ($rs.Count -gt 0) {
            $mr = ($rs | Measure-Object -Average).Average; $e.Rbar = [double]$mr
            if ($rs.Count -ge 2) {
                $sd = [math]::Sqrt((@($rs | ForEach-Object { [math]::Pow($_ - $mr, 2) }) | Measure-Object -Sum).Sum / ($rs.Count - 1))
                $e.RTol = [math]::Max([double]$script:CalResidual * [math]::Min(1.0, $k / 2.0), 2.0 * $sd / [math]::Sqrt($rs.Count))
            }
        }
    }
    foreach ($c in @($u.Wit)) {
        $z = Get-LevelZero $u.Results[[int]$c] $k
        if ($z -and $z.Kind -ne 'cap') { $e.Wit[[int]$c] = @{ D = [double]$z.Est - [double]$u.V[[int]$c]; Sig = [double]$z.Sig; Z = [double]$z.Est } }
    }
    if ($null -ne $u.Probe) {
        $z = Get-LevelZero $u.Results[[int]$u.Probe] $k
        if ($z) { $e.ProbeZ = [double]$z.Est; $e.ProbeKind = [string]$z.Kind }
    }
    return $e
}

function Get-LevelStats($ds, $sg) {
    # Partie statistique de Get-LevelEstimate : poids avec plancher tau0 (LevelShapeFloor), ecart isole ou dispersion
    # (mediane ponderee), niveau, erreur-type, ecart de forme tau. 12.8 (lot 1c) : aussi pour Get-LevelKrefEstimate
    $cs = @($ds.Keys | ForEach-Object { [int]$_ } | Sort-Object)
    $t0 = [math]::Pow([double]$script:LevelShapeFloor, 2)
    $w = @{}; foreach ($c in $cs) { $w[$c] = 1.0 / ([math]::Pow($sg[$c], 2) + $t0) }
    $outl = @(); $scatter = 0
    if ($cs.Count -ge 1) {
        $m = Get-WeightedMedian ([double[]]@($cs | ForEach-Object { $ds[$_] })) ([double[]]@($cs | ForEach-Object { $w[$_] }))
        $iso = @($cs | Where-Object { [math]::Abs($ds[$_] - $m) -gt [math]::Max(15.0, 4.0 * $sg[$_]) })
        if ($iso.Count -eq 1 -and $cs.Count -ge 5) { $outl = $iso } elseif ($iso.Count -ge 2) { $scatter = $iso.Count }
    }
    $keep = @($cs | Where-Object { $outl -notcontains $_ })
    $n = $keep.Count
    $st = @{ N = $n; Ds = $ds; Sigs = $sg; Outliers = $outl; Scatter = $scatter; Keep = $keep; W = $w; Delta = [double]::NaN; SE = [double]::NaN; Tau = 0.0 }
    if ($n -ge 1) {
        $sw = 0.0; $swd = 0.0; foreach ($c in $keep) { $sw += $w[$c]; $swd += $w[$c] * $ds[$c] }
        $dh = $swd / $sw; $st.Delta = $dh
        if ($n -ge 2) {
            $chi = 0.0; $ss = 0.0; $ms = 0.0
            foreach ($c in $keep) { $chi += $w[$c] * [math]::Pow($ds[$c] - $dh, 2); $ss += [math]::Pow($ds[$c] - $dh, 2); $ms += [math]::Pow($sg[$c], 2) }
            $st.SE = [math]::Sqrt(1.0 / $sw) * [math]::Sqrt([math]::Max(1.0, $chi / ($n - 1)))
            $st.Tau = [math]::Sqrt([math]::Max(0.0, $ss / ($n - 1) - $ms / $n))
        } else { $st.SE = [math]::Sqrt(1.0 / $sw) }
    }
    return $st
}

function Test-LevelShape($e, $u, [double]$f = 1.0) {
    # Forme de la disquette comparee a la reference : dispersion, ecart de forme, inclinaison radiale, hauteur de marche,
    # temoins de marche. f = 2 : seuils doubles (bascule anticipee apres la premiere passe).
    $reasons = @(); $tilt = $null; $step = $null
    if ($e.Scatter -ge 2) { $reasons += ((T "écarts dispersés ({0} cylindres hors de la forme)") -f "$($e.Scatter)") }
    if ($e.Tau -gt $script:LevelTauMax * $f) { $reasons += ((T "écart de forme {0} ns") -f ('{0:0.#}' -f [math]::Round($e.Tau, 1))) }
    $keep = @($e.Keep); $w = $e.W; $ds = $e.Ds
    $maxC = [math]::Max(1, @($u.V).Count - 1)
    if ($keep.Count -ge 4) {
        $us = @{}; foreach ($c in $keep) { $us[$c] = [double]$c / $maxC }
        $uv = @($keep | ForEach-Object { $us[$_] })
        $range = ($uv | Measure-Object -Maximum).Maximum - ($uv | Measure-Object -Minimum).Minimum
        if ($range -ge 0.5) {
            $sw = 0.0; $su = 0.0; $sd = 0.0; foreach ($c in $keep) { $sw += $w[$c]; $su += $w[$c] * $us[$c]; $sd += $w[$c] * $ds[$c] }
            $ub = $su / $sw; $db = $sd / $sw
            $suu = 0.0; $sud = 0.0; foreach ($c in $keep) { $suu += $w[$c] * [math]::Pow($us[$c] - $ub, 2); $sud += $w[$c] * ($us[$c] - $ub) * ($ds[$c] - $db) }
            if ($suu -gt 0) {
                $b = $sud / $suu
                $chi = 0.0; foreach ($c in $keep) { $chi += $w[$c] * [math]::Pow($ds[$c] - ($db + $b * ($us[$c] - $ub)), 2) }
                $tilt = $b * $range
                $seT = [math]::Sqrt([math]::Max(1.0, $chi / [math]::Max(1, $keep.Count - 2)) / $suu) * $range
                if ([math]::Abs($tilt) -gt [math]::Max(15.0 * $f, 3.0 * $seT)) {
                    $c1 = ($keep | Measure-Object -Minimum).Minimum; $c2 = ($keep | Measure-Object -Maximum).Maximum
                    $reasons += ((T "le niveau varie avec le cylindre ({0} ns de c{1} à c{2})") -f ('{0:+0;-0;0}' -f [math]::Round($tilt, 0)), "$c1", "$c2")
                }
            }
        }
    }
    $brk = @(@($u.Cv.Breaks) | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_ })
    if ($brk.Count -ge 1) {
        $pk = $brk[0]
        $l = @($keep | Where-Object { $_ -le $pk }); $r = @($keep | Where-Object { $_ -gt $pk })
        if ($l.Count -ge 2 -and $r.Count -ge 2) {
            $wl = 0.0; $dl = 0.0; foreach ($c in $l) { $wl += $w[$c]; $dl += $w[$c] * $ds[$c] }
            $wr = 0.0; $dr = 0.0; foreach ($c in $r) { $wr += $w[$c]; $dr += $w[$c] * $ds[$c] }
            $step = $dr / $wr - $dl / $wl
            $seS = [math]::Sqrt(1.0 / $wl + 1.0 / $wr)
            if ([math]::Abs($step) -gt [math]::Max(15.0 * $f, 3.0 * $seS)) { $reasons += ((T "la marche de c{0} n'a pas la même hauteur ({1} ns d'écart de part et d'autre)") -f "$pk", ('{0:+0;-0;0}' -f [math]::Round($step, 0))) }
        }
    }
    if (@($u.Wit).Count -eq 2 -and -not [double]::IsNaN([double]$e.Delta)) {
        foreach ($c in @($u.Wit)) {
            $wz = $e.Wit[[int]$c]; if (-not $wz) { continue }
            if ([math]::Abs($wz.D - $e.Delta) -gt [math]::Max(15.0 * $f, 4.0 * $wz.Sig)) { $reasons += ((T "marche déplacée ou absente entre c{0} et c{1} (autre lecteur sous la même lettre ?)") -f "$($u.Wit[0])", "$($u.Wit[1])"); break }
        }
    }
    $verdict = if ($reasons.Count -gt 0) { 'mismatch' } elseif ($e.Tau -gt $script:LevelTauOk) { 'approx' } else { 'ok' }
    return @{ Verdict = $verdict; Reasons = $reasons; Tilt = $tilt; Step = $step }
}

function Build-LevelValues($u, [int]$d, $e, [int]$Hard = 0) {
    # Courbe appliquee : reference + niveau, bornee a 0..CalHardNs. Valeur de reference a la borne de SON calcul
    # (Get-CurveMaxNs : 300 ns avant le calcul 12.4) : borne basse du besoin, relevee d un niveau positif, jamais abaissee.
    # Zone plafonnee terminale de la reference (CapLo au temoin du plafond) :
    #  - temoin resolu (zero encadre ou extrapole, au plus CalHardNs) : zone interpolee lineairement jusqu a ce zero ;
    #  - temoin plafonne (besoin au-dela de CalHardNs) : zone portee jusqu a CalHardNs, jamais sous la reference relevee
    #    du niveau ; temoin compte dans Sat (reserve, fenetre de decision) ;
    #  - temoin non resolu, ou zero au plancher (invraisemblable a la borne) : regle generale ci-dessus.
    # Noms distincts de la reference ($ref) et de sa valeur ($rv) : PowerShell ignore la casse ($V et $v seraient une
    # seule variable)
    # 12.8 (F3R, decision 2) : Hard (> 0) : plafond des valeurs et de Sat (courbe de la forme d une marque dont le besoin
    # depasse CalHardNs : jusqu au plafond de la disquette) ; Clip reste decide contre CalHardNs (un reglage), et la zone
    # du temoin du plafond reste a CalHardNs (G6). RawMax : besoin le plus fort hors Clip (reference ou V' + niveau)
    $base = [int]$script:CalHardNs; $max = if ($Hard -gt 0) { $Hard } else { $base }
    $rmax = Get-CurveMaxNs $u.Cv; $ref = @($u.V); $n = $ref.Count
    # 12.8 (FIX1C, constat 4) : Clip decide sur la reference du lecteur (V0) ; avec le point de depart d une marque (V'),
    # une valeur de V' au-dela de la borne est un besoin de cette disquette : Sat (reserve « plafond »), jamais Clip
    $ref0 = if ($null -ne $u.V0 -and @($u.V0).Count -eq $n) { @($u.V0) } else { $ref }
    $out = New-Object int[] $n; $sat = @(); $floor = @(); $clip = @(); $rawMax = $null
    for ($c = 0; $c -lt $n; $c++) {
        $rv = [int]$ref[$c]
        # Reference au-dela de la borne actuelle (courbe calculee avec une borne plus haute) : ecretee a la borne, niveau
        # applique, sans Sat (la borne est un reglage, pas un besoin de cette disquette)
        if ([int]$ref0[$c] -gt $base) {
            $raw = if ($rv -ge $rmax) { $rv + [math]::Max(0, $d) } else { $rv + $d }
            # 12.8 (F3R-FIX, constat 1) : plafond porte au-dela de CalHardNs par le besoin d un autre cylindre (Hard) : ce
            # cylindre suit le plafond (Sat au-dela), sans entrer dans RawMax (il ne declenche rien)
            if ($max -gt $base) {
                if ($raw -gt $max) { $sat += $c }
                $out[$c] = [int][math]::Max(0, [math]::Min($max, $raw)); continue
            }
            if ($raw -gt $base) { $clip += $c }
            $out[$c] = [int][math]::Max(0, [math]::Min($base, $raw)); continue
        }
        if ($rv -ge $rmax) {
            $raw = $rv + [math]::Max(0, $d)
            if ($null -eq $rawMax -or $raw -gt $rawMax) { $rawMax = $raw }
            if ($raw -gt $max) { $sat += $c }
            $out[$c] = [int][math]::Min($max, $raw); continue
        }
        if ($rv -le 0) { $out[$c] = 0; continue }
        $raw = $rv + $d
        if ($null -eq $rawMax -or $raw -gt $rawMax) { $rawMax = $raw }
        if ($raw -gt $max) { $sat += $c } elseif ($raw -lt 0) { $floor += $c }
        $out[$c] = [int][math]::Max(0, [math]::Min($max, $raw))
    }
    $note = $null
    if ($null -ne $u.Probe -and [int]$u.CapLo -ge 1 -and [int]$u.CapLo -lt $n -and [int]$u.Probe -ge [int]$u.CapLo -and $e) {
        $p = [int]$u.Probe; $lo = [int]$u.CapLo; $y1 = $null
        if ($null -eq $e.ProbeZ -or ($e.ProbeKind -ne 'cap' -and -not $u.ProbeDone)) { $note = 'unresolved' }
        elseif ($e.ProbeKind -eq 'cap' -and [double]$e.ProbeZ -le 0) { $note = 'unresolved' }
        elseif ($e.ProbeKind -eq 'cap') { $note = 'cap'; $y1 = [double]$base }
        else { $note = 'interp'; $y1 = [double]$e.ProbeZ }
        if ($null -ne $y1) {
            # Zone recalculee : interpolation depuis le dernier cylindre hors zone ; au-dela du temoin (reference plus longue
            # que l image), valeur du temoin
            $y0 = [double]$out[$lo - 1]
            $sat = @($sat | Where-Object { $_ -lt $lo }); $clip = @($clip | Where-Object { $_ -lt $lo })
            for ($c = $lo; $c -lt $n; $c++) {
                $tt = [math]::Min(1.0, ($c - ($lo - 1)) / [double]($p - ($lo - 1)))
                $raw = [math]::Round($y0 + $tt * ($y1 - $y0))
                if ($note -eq 'cap') {
                    $lb = [double]$ref[$c] + [math]::Max(0, $d)
                    if ([double]$ref0[$c] -gt $base) { $clip += $c } elseif ($c -eq $p -or $lb -gt $base) { $sat += $c }
                    $raw = [math]::Max($raw, [math]::Min([double]$base, $lb))
                }
                $out[$c] = [int][math]::Max(0, [math]::Min($base, $raw))
            }
        }
    }
    return @{ Values = $out; Sat = $sat; Floor = $floor; ProbeNote = $note; Clip = $clip; RawMax = $rawMax; Hard = $max }
}

function New-LevelCalUnits($lr, [string]$brand, [string]$drive, [int]$Bits = 0) {
    # Unites de la calibration rapide (Start-LevelCalib ; suite calib-lvl2, sans interface) : une par tete ou une pour la
    # courbe commune, cibles de la premiere passe. 12.8 (lot 1c) : etat de la calibration rapide adaptative ; V0 :
    # reference du lecteur (ShapeV), V : reference ou point de depart de la marque (V', Set-LevelBrandStart) ; cylindres
    # de controle (ecriture lente) choisis sur la reference du lecteur (V0, FIX1C), les memes que ceux de l avertissement
    $units = @()
    $slow = ($null -ne @($lr.Units)[0].Head)
    foreach ($lu in @($lr.Units)) {
        $u = New-CalibUnit $lu.Head
        foreach ($key in 'RefKey', 'Tag', 'Cv', 'V', 'KRef', 'LCyls', 'Wit', 'Probe', 'CapLo', 'D0', 'NHist') { $u[$key] = $lu[$key] }
        $u.D = [int]$lu.D0; $u.LTarget = @{}; $u.Done = $false; $u.Conv = $false; $u.Fail = ''; $u.Early = $false; $u.Sat = $false; $u.Low = $false; $u.Few = $false; $u.ProbeOnly = $false
        $u.Level = $null; $u.Passes = 0; $u.ProbeDone = $false; $u.ProbeZ = $null; $u.Est = $null; $u.Shape = $null
        $u.Mode = 'lvl1'; $u.Raw = @{}; $u.V0 = [int[]]@($lu.V); $u.Memo = $null; $u.BrandEntry = $null; $u.AN = $null; $u.AV = $null; $u.VR = $null
        $u.Named = @{}; $u.Refus = ''; $u.Trig = $null; $u.Note = ''; $u.AdaptNote = ''; $u.AdaptLog = $null; $u.Ctl = [int[]]@()
        # 12.8 (F3R) : controles integres a l ajustement par une reprise e3 (CtlFit), reserve de controle e2 (motif, controles)
        $u.CtlFit = [int[]]@(); $u.CtlReserve = ''; $u.CtlBad = @(); $u.ImgBits = $Bits   # 12.11 : ImgBits, cellules de la piste ecrite (Get-DiskCapBits : celles du motif, ou du format gw au-dela de 250 kbit/s ; 0 sans densite ou cellule inconnue) : plafond par disquette (Get-UnitCapNs)
        Set-LevelBrandStart @{ Drive = $drive; Family = [string]$lr.Family } $u $brand
        $u.ShapeV = New-LevelShape $u.V0
        foreach ($c in @(@($u.LCyls) + @($u.Wit) + @($(if ($null -ne $u.Probe) { $u.Probe })))) { $u.Results[[int]$c] = @{} }
        Set-LevelTargets $u
        $units += ,$u
    }
    if ($slow) {
        $ctl = Get-LevelCtlCyls $units ([int]$lr.MaxCyl)
        foreach ($u in $units) { $u.Ctl = $ctl; foreach ($x in $ctl) { if (-not $u.Results.ContainsKey([int]$x)) { $u.Results[[int]$x] = @{} } } }
    }
    return ,$units
}

function Start-LevelCalib($lr, [switch]$NoConfirm, [switch]$NoFallback, $Geom = $null) {
    # Calibration rapide : avertissement (sauf NoConfirm), motif, unites, premiere passe. Geom : type de disquette de la
    # carte Calibration de l Accueil (image de geometrie, Start-HomeCalib) a la place de l image de l onglet Ecriture
    # 12.8 (S3) : $script:LevelNoBrand (garde de la passe 1, W-M2 : « Calibration rapide sur la reference ») : lu et remis a
    # $false ici, avant toute sortie ; aucune marque, meme sans avertissement (signature inchangee : enveloppes de make-test)
    $noBrand = [bool]$script:LevelNoBrand; $script:LevelNoBrand = $false
    if ($script:GwProc -and -not $script:GwProc.HasExited) { return }
    $script:Cal = $null
    # 12.11 (lot LN-b) : avec des lecteurs enregistres, lecteur branche confirme s il y a lieu (Confirm-DriveIdentity, 112) ;
    # refus : calibration non lancee ($script:Cal vide, que lisent les appelants)
    if ($script:DriveReg.Count -gt 0 -and -not (Confirm-DriveIdentity)) { return }
    $script:LevelPostForce = $false
    $chk = Test-CalibImage $Geom
    if (-not $chk) { return }
    $img = $chk.Img; $fam = $lr.Family
    $toWrite = ($script:AfterCalib -eq 'write')
    $target = if ($script:Restore) { (T 'la disquette de destination') } else { (T 'la disquette à écrire') }
    $units0 = @($lr.Units)
    $slow = ($null -ne $units0[0].Head)
    $all = @{}
    $sets = @()
    foreach ($lu in $units0) {
        $one = @(@(@($lu.LCyls) + @($lu.Wit) + @($(if ($null -ne $lu.Probe) { $lu.Probe }))) | ForEach-Object { [int]$_ } | Sort-Object -Unique)
        foreach ($c in $one) { $all[[int]$c] = $true }
        $sets += (Format-CylList ([int[]]$one))
    }
    $cyls = [int[]]@($all.Keys | Sort-Object)
    $cylTxt = if (@($sets | Sort-Object -Unique).Count -le 1) { $sets[0] } else { ((@(0..($units0.Count - 1) | ForEach-Object { (T "tête {0} : {1}") -f "$($units0[$_].Head)", "$($sets[$_])" })) -join ' ; ') }
    # 12.8 (lot 1c) : cylindres de controle de la calibration rapide adaptative (ecriture lente, une courbe par tete ; la
    # courbe commune n est pas adaptee, G6), choisis sous le dernier cylindre de l image
    $ctl0 = if ($slow) { Get-LevelCtlCyls $units0 ([int]$lr.MaxCyl) } else { [int[]]@() }
    $ctlTxt = if ($ctl0.Count -gt 0) { Format-CylList $ctl0 } else { '-' }
    $ref0 = $units0[0].Cv
    $testTxt = if ([string]$ref0.Test -eq 'fine') { (T 'test fin') } else { (T 'test standard') }
    # Calibration rapide avant une ecriture lente : prechauffage du lecteur avant la mesure du niveau (case « Prechauffer le
    # lecteur ») ; duree comprise dans l estimation (borne haute : reduit ou saute si le lecteur vient de servir)
    $warm = ($toWrite -and $chkWSlow.Checked -and $chkWWarm.Checked)
    $wu = if ($warm) { [math]::Max(0.0, [double]$script:CalWarmupMinutes) } else { 0.0 }
    # 12.8 (lot 1c) : 2 passes en general, 3 passes avec 2 cylindres de controle de plus quand la forme est adaptee
    # 12.8.2 (revue) : effacement haute frequence de chaque passe en double densite compris (Get-CalibEraseEst, 150)
    $estEr = Get-CalibEraseEst ([string]$fam -eq 'hd')
    $minLo = [math]::Max(1, [math]::Round($cyls.Count * 2 * (1.4 + $estEr) * 2 / 60 + $wu, 0))
    $minHi = [math]::Max($minLo, [math]::Round(($cyls.Count + $ctl0.Count) * 2 * (1.4 + $estEr) * 3 / 60 + $wu, 0))
    $minutes = if ($slow -and $minHi -gt $minLo) { (T '{0} à {1}') -f "$minLo", "$minHi" } else { "$minLo" }
    $script:AlignLoop = $false; $script:AlignNextAt = $null
    $ans = $null                        # 12.7 : jamais celle d un appelant (portee dynamique)
    $brand = ''
    if (-not $NoConfirm) {
        $intro = if ($toWrite) { ((T "Calibration rapide avant l'écriture : {0} reçoit le motif de test sur ces seuls cylindres, au plus 3 fois, puis l'image.") -f "$target") + "`n`n" } else { '' }
        # 12.8 (lot 1c) : courbe commune (ecriture rapide) : seul le niveau est mesure (G6), textes de la 12.7
        $bodyFmt = if (-not $slow -and $Geom) { (T "Calibration rapide de la précompensation sur le lecteur {0} : seul le niveau de la courbe est mesuré, sur la disquette insérée.`n`nRéférence : calibration complète du {1} ({2}), dont la forme est reprise telle quelle.`nType de disquette : {3}, famille {4}.`nCylindres mesurés : {5} (2 faces), ÉCRASÉS à chaque passe ; 1 à 3 passes, 2 en général. Durée estimée : {6} min.") }
                   elseif (-not $slow) { (T "Calibration rapide de la précompensation sur le lecteur {0} : seul le niveau de la courbe est mesuré, sur la disquette insérée.`n`nRéférence : calibration complète du {1} ({2}), dont la forme est reprise telle quelle.`nImage : {3}, famille {4}.`nCylindres mesurés : {5} (2 faces), ÉCRASÉS à chaque passe ; 1 à 3 passes, 2 en général. Durée estimée : {6} min.") }
                   elseif ($Geom) { (T "Calibration rapide de la précompensation sur le lecteur {0} : le niveau de la courbe est mesuré sur la disquette insérée, et sa forme aussi si elle diffère de la référence.`n`nRéférence : calibration complète du {1} ({2}) ; sa forme est reprise, puis adaptée à cette disquette si la mesure le demande.`nType de disquette : {3}, famille {4}.`nCylindres mesurés : {5} (2 faces), ÉCRASÉS à chaque passe, plus 2 cylindres de contrôle ({7}) si la forme est adaptée ; 1 à 3 passes, 2 en général, 3 quand la forme est adaptée. Durée estimée : {6} min.") }
                   else { (T "Calibration rapide de la précompensation sur le lecteur {0} : le niveau de la courbe est mesuré sur la disquette insérée, et sa forme aussi si elle diffère de la référence.`n`nRéférence : calibration complète du {1} ({2}) ; sa forme est reprise, puis adaptée à cette disquette si la mesure le demande.`nImage : {3}, famille {4}.`nCylindres mesurés : {5} (2 faces), ÉCRASÉS à chaque passe, plus 2 cylindres de contrôle ({7}) si la forme est adaptée ; 1 à 3 passes, 2 en général, 3 quand la forme est adaptée. Durée estimée : {6} min.") }
        $body = $bodyFmt -f "$($cmbDrive.Text)", "$($ref0.Date)", "$testTxt", "$($chk.Label)", (Get-CalibFamilyName $fam), "$cylTxt", "$minutes", "$ctlTxt"
        if ($wu -gt 0) { $body += "`n" + ((T "Préchauffage du lecteur avant la mesure du niveau : jusqu'à {0} de lecture sans écriture (moins si le lecteur vient de servir), compris dans la durée estimée.") -f (Format-CalDuration (60 * $wu))) }
        $tail = if ($toWrite) { (T "Le niveau dépend du support : il doit être mesuré sur la disquette qui recevra l'image. N'insérez pas de disquette sacrifiée. Une calibration complète écrit le motif 4 à 8 fois sur ses cylindres de test ; la calibration rapide, 3 fois au plus.") }
                elseif ($Geom) { (T "Aucune image n'est écrite. Insérez la disquette que vous allez écrire : le profil obtenu ne vaut que pour elle ; il est placé dans les champs --precomp de l'onglet Écriture si son image est de la même famille.") }
                else { (T "Aucune image n'est écrite. Insérez la disquette que vous allez écrire : le profil obtenu est placé dans les champs --precomp et ne vaut que pour elle.") }
        # 12.8 (lot 1c, § 10.1) : marque de la disquette inseree (champ libre, derniere marque choisie par defaut), ecriture
        # lente seulement (la courbe commune n est pas adaptee)
        $bi = $null
        if ($slow) {
            $bi = Get-LevelBrandItems ([string]$cmbDrive.Text) $units0 $fam
            $bi.Label = (T 'Marque de la disquette insérée :'); $bi.Text = [string]$script:LevelBrand
            $bi.Tip = (T "Nom libre : marque, année ou lot. Une marque déjà mesurée sert de point de départ : sa forme et son niveau, mémorisés avec la référence actuelle du lecteur. La mesure reste faite sur la disquette insérée.")
        }
        # 12.9 (S1) : delai seulement pour la disquette a ecrire d une ecriture sans surveillance (Get-CalibConfirmSeconds)
        $ans = Show-CalibConfirm ($intro + $body + "`n`n" + $tail) '' $bi -Seconds (Get-CalibConfirmSeconds ([string]$script:AfterCalib) ([bool]$script:CalibUnattended))
        if (-not $ans.Ok) { return }
        if ($ans.Auto) { Append-Log ((T "Calibration : avertissement validé automatiquement après {0} s sans réponse.") -f "$($script:CalibConfirmSeconds)") }
        if ($bi) { $brand = Get-LevelBrandName ([string]$ans.Brand) $bi.Map; $script:LevelBrand = $brand }
    } elseif ($slow -and -not $noBrand) {
        # Mesure apres une calibration sur disquette sacrifiee (sans avertissement) : derniere marque choisie
        $brand = [string]$script:LevelBrand
    }
    if ($script:GwProc -and -not $script:GwProc.HasExited) { return }
    if (-not (Test-Path -LiteralPath $script:TempDir)) { [void](New-Item -ItemType Directory -Path $script:TempDir -Force) }
    try { $pat = New-CalibPattern $fam $img $lr.NCyl }
    catch { [void](Show-AppMessage ((T "Calibration : motif de test impossible à créer : {0}") -f "$($_.Exception.Message)") (T 'Calibration precomp') 'OK' 'Error'); return }
    Set-CalibScale $fam     # 12.7 : bareme double densite (pas de calibration rapide en haute densite, Get-LevelRef)
    $units = New-LevelCalUnits $lr $brand ([string]$cmbDrive.Text) $(if ($Geom) { 0 } else { Get-DiskCapBits ([int]$pat.CapBits) ([string]$cmbWFmt.Text) ([bool]$pat.Known) })   # 12.11 : cellules de la piste ecrite (Get-DiskCapBits, sur CapBits, la piste la plus longue de l image ; 0 si elle n est pas connue : format hors de la table, ou aucun format et densite non tiree de l image) ; carte de l Accueil (Geom : type de disquette, pas l image a ecrire) : sans densite, plafond de 470 ns comme en 12.10 (son profil peut etre place dans les champs d une image d une autre densite, Complete-LevelCalib)
    $cylList = Format-CylList $cyls
    $script:Cal = @{
        Mode = 'level'; Stage = 'level'; LPass = 1; Cyls = $cyls; MaxCyl = $lr.MaxCyl; Family = $fam; Slow = $slow
        Image = $img; Pattern = $pat.Path; PatternBits = $pat.Bits; MaxCoarse = 0; Drive = $cmbDrive.Text; TSpec = "c=${cylList}:h=0-1"; CylList = $cylList
        Values = @(); Index = 0; Value = 0; ValueTxt = ''; Spec = ''; Units = $units; VerifyCount = 0; Swap = $false; LevelAfter = $false
        CanFallback = ($toWrite -and -not $NoFallback -and -not $script:Restore); Notes = @($lr.Notes)
        Scp = (Join-Path $script:TempDir 'precomp-calib.scp'); Writes = (New-Object System.Collections.Queue); ReadArgs = @()
        StartTime = (Get-Date); PassStart = (Get-Date); PhaseStart = (Get-Date); Phase = 'write'
        PassesDone = 0; TotalPasses = 2; WriteDurs = @(); ReadDurs = @(); EstTrack = 0.7; EstErase = $estEr; TrackWrites = 0
        # Carte Calibration de l Accueil (progression sur la carte). 12.8 (S3-FLUX) : Geom.NoHome (geometrie de la copie de flux
        # mesuree en restauration, F3R) retire avec cette mesure
        Home = [bool]$Geom; Geom = $Geom
        # 12.7 point 5 : controle de surface de la premiere passe (Invoke-LevelSurface)
        AutoStart = [bool]($ans -and $ans.Auto); SurfDone = $false; Surf = $null; Medium = $null; SurfGross = $false; SurfKept = $false; Hold = $false
        # 12.8 (lot 1c) : marque de la disquette inseree (§ 10)
        Brand = $brand
        # 12.8 (S3) : reference de cette calibration (mesure complete de cette disquette, W-M1 et W-M2) ; mesure complete
        # proposee avant une ecriture, hors restauration
        Lr = $lr; CanDisk = [bool]($toWrite -and -not $script:Restore)
    }
    $kind = if ($slow -and $units[0].RefKey -eq $units[1].RefKey) { (T 'forme commune, niveau mesuré par tête') } elseif ($slow) { (T 'une courbe par tête') } else { (T 'courbe commune') }
    $lf = if ($Geom) { (T "=== Calibration rapide : lecteur {0}, type {1} ({2}, {3}) ===") } else { (T "=== Calibration rapide : lecteur {0}, image {1} ({2}, {3}) ===") }
    Append-Log ($lf -f "$($cmbDrive.Text)", "$($chk.Label)", (Get-CalibFamilyName $fam), "$kind")
    if ($brand) { Append-Log $(if ($NoConfirm) { (T 'Marque de la disquette insérée : « {0} » (dernière marque choisie).') -f "$brand" } else { (T 'Marque de la disquette insérée : « {0} ».') -f "$brand" }) }
    foreach ($u in $units) {
        $tt = if ([string]$u.Cv.Test -eq 'fine') { (T 'test fin') } else { (T 'test standard') }
        Append-Log ((T "{0}Référence de forme : calibration complète ({1}) du {2}, lecteur {3} ; cylindres de niveau : {4}.") -f "$($u.Prefix)", "$tt", "$($u.Cv.Date)", "$($u.Cv.Drive)", (Format-CylList ([int[]]@($u.LCyls))))
        if (@($u.Wit).Count -eq 2) { Append-Log ((T "{0}Témoins de marche : c{1} et c{2} (contrôle de la forme, hors calcul du niveau).") -f "$($u.Prefix)", "$($u.Wit[0])", "$($u.Wit[1])") }
        if ($null -ne $u.Probe) { Append-Log ((T "{0}Témoin du plafond : c{1} (référence au plafond de {3} ns de son calcul, de c{2} à c{1}).") -f "$($u.Prefix)", "$($u.Probe)", "$($u.CapLo)", "$(Get-CurveMaxNs $u.Cv)") }
        if ($u.Memo -and $u.Memo.Curve) {
            # 12.8 (S3) : courbe complete de la marque (mesure complete d une disquette de cette marque)
            $mm = $u.Memo
            Append-Log ((T '{0}Point de départ : courbe complète mémorisée pour la marque « {1} » le {2} (niveau {3} ns ; {4} mesure(s), dernière le {5}).') -f "$($u.Prefix)", "$($mm.Brand)", "$($mm.CurveDate)", (Format-LevelSigned $mm.A), "$($mm.N)", "$($mm.LastDate)")
        }
        elseif ($u.Memo) {
            $mm = $u.Memo
            Append-Log ((T '{0}Point de départ : forme mémorisée pour la marque « {1} » (niveau {2} ns, échelle {3} %, pente {4} ns de c0 à c{5} ; {6} mesure(s), dernière le {7}).') -f "$($u.Prefix)", "$($mm.Brand)", (Format-LevelSigned $mm.A), (Format-UiNum ([math]::Round(100 * [double]$mm.S, 1)) '+0.0;-0.0;0.0'), (Format-LevelSigned $mm.B), "$(@($u.V0).Count - 1)", "$($mm.N)", "$($mm.LastDate)")
        }
        if ($u.D0 -ne 0 -and -not $u.Memo) { Append-Log ((T "{0}Niveau de départ : {1} ns (médiane de la référence et des {2} derniers niveaux mesurés avec elle).") -f "$($u.Prefix)", ('{0:+0;-0;0}' -f $u.D0), "$($u.NHist)") }
    }
    Append-Log (T 'Cylindres de niveau choisis parmi les cylindres mesurés et vérifiés de la référence ; exclus : cylindres 0 et 1, changements de sens et leurs voisins, pentes raides, valeurs hors de 20 à 260 ns, points isolés ou hors tolérance.')
    foreach ($nt in @($lr.Notes)) { Append-Log $nt }
    $pbWCal.Value = 0; $pbWCal.Visible = $true; $lblWCal.Visible = $true
    Update-CalibProgress
    # Avant une ecriture lente : prechauffage de l ecriture fait ici, avant la mesure du niveau, pour que le niveau soit
    # mesure dans l etat du lecteur ou l image sera ecrite (Start-CalibWarmup, retour a l etape 'level') ; seule ou avant
    # une ecriture rapide : aucun prechauffage
    if ($warm) { Start-CalibWarmup } else { New-CalibPass }
}

function Invoke-LevelDecide($cal, $u, $e, [int]$p, $J) {
    # Decision 12.7 d Invoke-LevelStep pour une unite apres l estimation $e de la passe p (arret : niveau verifie, echec,
    # bascule anticipee, dernier essai ; sinon cibles de la passe suivante). 12.8 (lot 1c) : lignes du journal ajoutees a
    # $J (@{ Est ; Text }), ecrites par l appelant ; renvoie le motif : nomeas, nowrite, few, verifie, probe (niveau
    # verifie, passe du seul temoin du plafond), repli, max_passes, stable ou next
    if ($e.N + @($e.Capped).Count + @($e.Floored).Count -lt 3) { $u.Fail = 'nomeas'; $u.Done = $true; return 'nomeas' }
    if ($null -ne $u.Head -and $p -ge 2 -and $null -ne $e.KRaw -and $e.KRaw -ge [math]::Max(-0.2, -0.5 * [double]$u.KRef) -and [double]$u.KRef * [double]$e.KSpan -ge 4.0) { $u.Fail = 'nowrite'; $u.Done = $true; return 'nowrite' }
    if ($e.N -lt 3) {
        $nm = $e.N + @($e.Capped).Count + @($e.Floored).Count
        if (2 * @($e.Floored).Count -gt $nm) { $u.Low = $true } elseif (2 * @($e.Capped).Count -gt $nm) { $u.Sat = $true } else { $u.Few = $true }
        $u.Level = if ($e.N -ge 1 -and -not [double]::IsNaN([double]$e.Delta)) { [int][math]::Round([double]$e.Delta) } else { [int]$u.D }
        $u.Conv = $false; $u.Done = $true; return 'few'
    }
    $dh = [double]$e.Delta
    $dv = @($e.Keep | ForEach-Object { $e.Ds[$_] })
    $J.Add(@{ Est = $true; Text = ($u.Prefix + ((T "Niveau estimé : {0} ns ± {1} ({2} cylindres ; écarts à la forme de {3} à {4} ns ; écart de forme {5} ns).") -f ('{0:+0.0;-0.0;0.0}' -f $dh), ('{0:0.#}' -f [math]::Round($e.SE, 1)), "$($e.N)", ('{0:+0.0;-0.0;0.0}' -f (($dv | Measure-Object -Minimum).Minimum - $dh)), ('{0:+0.0;-0.0;0.0}' -f (($dv | Measure-Object -Maximum).Maximum - $dh)), ('{0:0.#}' -f [math]::Round($e.Tau, 1)))) })
    if (-not [double]::IsNaN([double]$e.Rbar) -and [math]::Abs($e.Rbar) -le $e.RTol) {
        $u.Level = [int]$u.D; $u.Conv = $true
        $J.Add(@{ Est = $false; Text = ($u.Prefix + ((T "Niveau vérifié à la passe {0} : décalage résiduel moyen {1} ns (tolérance {2}) : niveau retenu {3} ns.") -f "$p", ('{0:0.#}' -f [math]::Round($e.Rbar, 1)), ('{0:0.#}' -f [math]::Round($e.RTol, 1)), ('{0:+0;-0;0}' -f $u.Level))) })
        if ($null -ne $u.Probe -and -not $u.ProbeDone -and $null -ne $u.ProbeZ -and $p -lt $script:LevelMaxPasses) {
            # Temoin du plafond non resolu : une passe de plus sur ce seul cylindre, ecrit a son zero estime
            $u.ProbeOnly = $true
            $u.LTarget = @{ ([int]$u.Probe) = [int][math]::Max(0, [math]::Min([int]$script:CalHardNs, [math]::Round([double]$u.ProbeZ))) }
            return 'probe'
        }
        $u.Done = $true
        return 'verifie'
    }
    if ($p -eq 1 -and $cal.CanFallback -and (Test-LevelShape $e $u 2.0).Verdict -eq 'mismatch') { $u.Level = [int][math]::Round($dh); $u.Conv = $false; $u.Early = $true; $u.Done = $true; return 'repli' }
    if ($p -ge $script:LevelMaxPasses) {
        $u.Level = [int][math]::Round($dh); $u.Conv = $false; $u.Done = $true
        $J.Add(@{ Est = $false; Text = ($u.Prefix + ((T "Niveau non vérifié après {0} passes (décalage résiduel moyen {1} ns, tolérance {2}) : niveau estimé {3} ns retenu.") -f "$p", ('{0:0.#}' -f [math]::Round($e.Rbar, 1)), ('{0:0.#}' -f [math]::Round($e.RTol, 1)), ('{0:+0;-0;0}' -f $u.Level))) })
        return 'max_passes'
    }
    $dn = [int][math]::Round($dh)
    $mv = [math]::Max([int]$script:LevelMinMove, [int][math]::Ceiling(4.0 / [double]$u.KRef))
    if ($p -eq 1 -and [math]::Abs($dn - $u.D) -lt $mv) {
        $sg = [math]::Sign($dh - $u.D); if ($sg -eq 0) { $sg = $(if ($e.Rbar -gt 0) { 1 } else { -1 }) }
        $dn = [int]$u.D + $mv * $sg
    }
    if ($dn -eq $u.D) {
        # [1] Estimation stable mais residu hors tolerance (ou non mesure) : niveau garde, non verifie
        $u.Level = [int]$u.D; $u.Conv = $false; $u.Done = $true
        $J.Add(@{ Est = $false; Text = ($u.Prefix + ((T "Niveau stable mais non vérifié à la passe {0} (décalage résiduel moyen {1} ns, tolérance {2}) : niveau {3} ns retenu.") -f "$p", (Format-LevelNum $e.Rbar), (Format-LevelNum $e.RTol), ('{0:+0;-0;0}' -f $u.Level))) })
        return 'stable'
    }
    $J.Add(@{ Est = $false; Text = ($u.Prefix + ((T "Niveau hors tolérance (décalage résiduel moyen {0} ns, tolérance {1}) : passe suivante à {2} ns.") -f ('{0:0.#}' -f [math]::Round($e.Rbar, 1)), ('{0:0.#}' -f [math]::Round($e.RTol, 1)), ('{0:+0;-0;0}' -f $dn))) })
    $u.D = $dn
    Set-LevelTargets $u
    return 'next'
}

function Write-LevelDecideLog($J, [switch]$NoEst, [switch]$EstOnly) {
    if ($null -eq $J) { return }
    foreach ($x in $J) {
        if ($NoEst -and $x.Est) { continue }
        if ($EstOnly -and -not $x.Est) { continue }
        Append-Log $x.Text
    }
}

function Invoke-LevelStep($cal, $tracks = $null) {
    # Apres chaque passe : estimation par unite, arret (niveau verifie, echec, bascule anticipee, dernier essai) ou passe suivante.
    # 12.7 point 5 : premiere passe, pistes relues ($tracks) : etat de la surface de la disquette d abord (Invoke-LevelSurface)
    # 12.8 (lot 1c) : calibration rapide adaptative (module 265, c1-design.md § 3.2) : decision 12.7 calculee sur une copie
    # de l unite ; forme non conforme et garde-fous respectes : passe de mesure (Mode 'meas'), puis de verification
    # ('verif') ; pente nulle sur une base etroite : passe de confirmation ('nwc') ; sinon decision 12.7 appliquee telle quelle
    if ($null -ne $tracks -and [int]$cal.LPass -eq 1 -and -not $cal.SurfDone) {
        if (-not (Invoke-LevelSurface $cal $tracks)) { return }
        # Pistes signalees par le controle de surface : nommees, ecartees d un ajustement eventuel
        if ($cal.Surf -and $cal.Surf.Faces) {
            foreach ($u in $cal.Units) {
                if ($null -eq $u.Head -or $null -eq $u.Named -or -not $cal.Surf.Faces[[int]$u.Head]) { continue }
                foreach ($b in @($cal.Surf.Faces[[int]$u.Head].Bad)) { if ($b) { $u.Named[[int]$b.C] = (T 'piste signalée par le contrôle de surface') } }
            }
        }
    }
    $p = [int]$cal.LPass
    foreach ($u in $cal.Units) {
        if ($u.Done) { continue }
        $u.Passes = $p
        $pfx = $u.Prefix
        if ($u.ProbeOnly) {
            # Passe du seul temoin du plafond, ecrit a son zero estime : le niveau est deja verifie
            $z = Get-LevelZero $u.Results[[int]$u.Probe] ([double]$u.Est.K)
            $pp = $u.Results[[int]$u.Probe]; $tg = [int]$u.LTarget[[int]$u.Probe]
            if ($z) {
                $u.Est.ProbeZ = [double]$z.Est; $u.Est.ProbeKind = [string]$z.Kind; $u.ProbeZ = [double]$z.Est
                $atTol = ($pp -and $pp.ContainsKey($tg) -and [math]::Abs([double]$pp[$tg].Shift) -le (Get-ResidualTol $pp[$tg]))
                if ($z.Kind -eq 'cap' -or ($z.Kind -eq 'interp' -and @($pp.Keys).Count -ge 2) -or $atTol) { $u.ProbeDone = $true }
            }
            $u.ProbeOnly = $false; $u.Done = $true; continue
        }
        if (-not $u.Mode) { $u.Mode = 'lvl1' }
        if ($u.Mode -eq 'lvl1') {
            $e = Get-LevelEstimate $u $p
            $u.Est = $e
            if ($null -ne $u.Probe -and -not $u.ProbeDone -and $null -ne $e.ProbeZ) {
                $pp = $u.Results[[int]$u.Probe]; $tg = [int]$u.LTarget[[int]$u.Probe]
                $atTol = ($pp -and $pp.ContainsKey($tg) -and [math]::Abs([double]$pp[$tg].Shift) -le (Get-ResidualTol $pp[$tg]))
                if ($e.ProbeKind -eq 'cap' -or ($e.ProbeKind -eq 'interp' -and @($pp.Keys).Count -ge 2) -or $atTol) { $u.ProbeDone = $true }
                $u.ProbeZ = $e.ProbeZ
            }
            # Decision 12.7 sur une copie de l unite (les objets mesures sont partages, la decision ne les modifie pas)
            $uc = $u.Clone()
            $J = New-Object System.Collections.Generic.List[object]
            $dec = Invoke-LevelDecide $cal $uc $e $p $J
            if ($dec -eq 'nowrite' -and $p -lt $script:LevelMaxPasses -and [double]$e.KSpan -lt $script:LevelAdaptDeltaMin -and
                @((Get-LevelFitCyls $u) | Where-Object { [int]$u.Writes[$_] -gt 2 }).Count -eq 0) {
                # Pente apparente nulle sur une base etroite : derive du lecteur possible ; confirmation sur LevelNwcDelta ns
                Append-Log ($pfx + ((T "Pente apparente nulle sur une base de {0} ns seulement (dérive du lecteur possible) : confirmation à la passe {1} sur une base de {2} ns.") -f (Format-UiNum ([math]::Round([double]$e.KSpan, 1)) '0.#'), "$($p + 1)", "$($script:LevelNwcDelta)"))
                Set-LevelNwcTargets $u
                continue
            }
            $trig = $null
            if (-not $uc.Fail) {
                if ($dec -eq 'repli') { $trig = @{ Type = 'A'; Reasons = @((Test-LevelShape $e $u 2.0).Reasons) } }
                elseif ($p -eq 1 -and -not $cal.CanFallback -and $dec -eq 'next' -and (Test-LevelShape $e $u 2.0).Verdict -eq 'mismatch') { $trig = @{ Type = 'A'; Reasons = @((Test-LevelShape $e $u 2.0).Reasons) } }
                elseif ($script:LevelAdaptTrigF1 -and $p -eq 1 -and $dec -eq 'next' -and (Test-LevelShape $e $u 1.0).Verdict -eq 'mismatch') { $trig = @{ Type = 'A'; Reasons = @((Test-LevelShape $e $u 1.0).Reasons) } }
                elseif ($p -le 2 -and (@('verifie', 'probe', 'stable', 'max_passes') -contains $dec -or ($dec -eq 'next' -and $p -eq 2))) {
                    $sh1 = Test-LevelShape $e $u 1.0
                    if ($sh1.Verdict -eq 'mismatch') {
                        # Declencheur B a la passe 2 : forme aussi non conforme avec les zeros a la pente de reference (une
                        # derive entre deux passes proches ne cree pas de forme fictive)
                        $pers = ($p -eq 1) -or ($script:LevelAdaptPersist -lt 2) -or ((Test-LevelShape (Get-LevelKrefEstimate $u) $u 1.0).Verdict -eq 'mismatch')
                        if ($pers) { $trig = @{ Type = 'B'; Reasons = @($sh1.Reasons) } }
                    }
                }
            }
            if ($trig) {
                $el = Test-LevelAdaptEligible $cal $u $e
                if (-not $el.Ok) {
                    if ($dec -eq 'repli' -or $trig.Type -eq 'B') {
                        $u.AdaptLog = $pfx + ((T "Calibration rapide adaptative non tentée : {0}.") -f "$($el.Why)")
                        if ($el.G6) { $uc.AdaptNote = $pfx + ((T 'calibration rapide adaptative non tentée : {0}') -f "$($el.Why)") }
                    }
                    $trig = $null
                }
            }
            if (-not $trig) {
                $al = $u.AdaptLog
                foreach ($k in @($uc.Keys)) { $u[$k] = $uc[$k] }
                Write-LevelDecideLog $J
                if ($al) { Append-Log $al; $u.AdaptLog = $null }
                continue
            }
            # Declenchement : la decision 12.7 est gardee pour un refus eventuel (declenchement a la passe 2) ; seule la ligne
            # « Niveau estime » est ecrite
            Write-LevelDecideLog $J -EstOnly
            $u.Trig = @{ Type = $trig.Type; Pass = $p; Reasons = $trig.Reasons; Dec = $dec; Unit = $uc; J = $J }
            $ctlTxt = if (@($u.Ctl).Count -gt 0) { Format-CylList ([int[]]@($u.Ctl)) } else { '-' }
            if ($p -eq 1) {
                Append-Log ($pfx + ((T "Forme non conforme à la passe 1 ({0}) : calibration rapide adaptative, passe 2 de mesure à une autre précompensation sur les mêmes cylindres (pente propre et vrai zéro de chaque cylindre) ; cylindres de contrôle hors ajustement : {1}.") -f (@($trig.Reasons) -join ' ; '), "$ctlTxt"))
                Set-LevelAdaptTargets $cal $u $e
                continue
            }
            # Passe 2 : les deux passes lvl1 servent de mesure, analyse immediate, verification a la passe 3
            Append-Log ($pfx + ((T "Forme non conforme à la passe 2 ({0}) : forme ajustée sur les passes 1 et 2, vérification à la passe 3 ; cylindres de contrôle : {1}.") -f (@($trig.Reasons) -join ' ; '), "$ctlTxt"))
            $u.Mode = 'meas'
            $cal.TotalPasses = [math]::Max([int]$cal.TotalPasses, [int]$script:LevelMaxPasses)
        }
        if ($u.Mode -eq 'nwc') {
            $e = Get-LevelEstimate $u $p
            $u.Est = $e
            $kr = if ($null -ne $e.KRaw) { Format-UiNum ([math]::Round(-[double]$e.KRaw / [double]$u.KRef, 1)) '0.#' } else { '-' }
            if ($null -ne $e.KRaw -and $e.KRaw -ge [math]::Max(-0.2, -0.5 * [double]$u.KRef) -and [double]$u.KRef * [double]$e.KSpan -ge 4.0) {
                Append-Log ($pfx + ((T 'Pente nulle confirmée sur une base de {0} ns.') -f (Format-UiNum ([math]::Round([double]$e.KSpan, 1)) '0.#')))
                $u.Fail = 'nowrite'; $u.Done = $true
                continue
            }
            $u.Level = [int][math]::Round([double]$e.Delta); $u.Conv = $false; $u.Done = $true; $u.Mode = 'lvl1'
            $u.Note = $pfx + ((T 'pente nulle de la passe {0} non confirmée sur une base de {1} ns (pente {2} fois la référence) : dérive du lecteur probable, niveau {3} ns non vérifié') -f "$($p - 1)", "$($script:LevelNwcDelta)", "$kr", ('{0:+0;-0;0}' -f [int]$u.Level))
            Append-Log ($pfx + ((T "Pente de la face confirmée sur une base de {0} ns ({1} fois la référence) : la pente nulle de la passe {2} venait d'une dérive du lecteur ou du bruit ; niveau estimé {3} ns, non vérifié.") -f (Format-UiNum ([math]::Round([double]$e.KSpan, 1)) '0.#'), "$kr", "$($p - 1)", ('{0:+0;-0;0}' -f [int]$u.Level)))
            continue
        }
        if ($u.Mode -eq 'meas') {
            $an = Get-LevelAdaptFit $u
            $u.AN = $an
            Write-LevelAdaptFitLog $u $an
            foreach ($k in @($an.Named.Keys)) { $u.Named[[int]$k] = $an.Named[$k] }
            if ($an.Why -eq 'nowrite') { $u.Fail = 'nowrite'; $u.Done = $true; continue }
            if (-not $an.Ok -and [int]$u.Trig.Pass -eq 1) {
                # 12.8 (F3R, e3) : refus de la passe de mesure (ecarts disperses, ecart isole, ecart de forme, bornes) repris
                # avec un terme de centre quand les controles s ecartent dans le meme sens que le centre : controles integres a
                # l ajustement, controle neuf hors ajustement, verification a la passe 3
                $ce = Get-LevelCenterRescue $u $an $cal
                if ($ce -and $ce.Ok) {
                    Append-Log ($pfx + ((T 'Adaptation reprise avec un terme de centre ({0}).') -f "$($an.Why)"))
                    Write-LevelCenterLog $u $ce
                    foreach ($c in @($ce.AN.Center.Reinc)) { [void]$u.Named.Remove([int]$c) }
                    $u.AN = $ce.AN; $an = $ce.AN
                    $u.CtlFit = [int[]]@($u.Ctl)
                    $fr = if ($script:LevelCenterFresh) { Get-LevelFreshCtl $u (Get-LevelFitCyls $u) $(if ($null -ne $cal.MaxCyl) { [int]$cal.MaxCyl } else { -1 }) } else { $null }
                    # 12.8 (F3R-FIX) : affectation par branche ; « $x = if (...) { [int[]]@() } » donnerait $null, puis
                    # [int[]]@($null) le cylindre 0 (Add-LevelCalCyls, enregistrement Ctl)
                    if ($null -ne $fr) { $u.Ctl = [int[]]@($fr) } else { $u.Ctl = [int[]]@() }
                    if ($null -ne $fr) {
                        if (-not $u.Results.ContainsKey([int]$fr)) { $u.Results[[int]$fr] = @{} }
                        Append-Log ($pfx + ((T "Contrôles {0} intégrés à l'ajustement ; contrôle neuf hors ajustement : c{1}.") -f ((@($u.CtlFit) | ForEach-Object { "c$_" }) -join ', '), "$fr"))
                    }
                    Set-LevelVerifTargets $cal $u $an
                    continue
                }
                if ($ce) { Append-Log ($pfx + ((T 'Reprise avec un terme de centre non retenue : {0}.') -f "$($ce.Why)")) }
            }
            if (-not $an.Ok) {
                $u.Refus = [string]$an.Why
                Append-Log ($pfx + ((T 'Adaptation refusée : {0}. Courbe de la référence décalée conservée.') -f "$($an.Why)"))
                $tr = $u.Trig
                if ([int]$tr.Pass -eq 2) {
                    # Declenchement a la passe 2 : decision 12.7 d origine appliquee (niveau verifie, stable, ou passe 3)
                    $mine = @{ AN = $u.AN; Named = $u.Named; Refus = $u.Refus; Trig = $u.Trig }
                    foreach ($k in @($tr.Unit.Keys)) { $u[$k] = $tr.Unit[$k] }
                    foreach ($k in @($mine.Keys)) { $u[$k] = $mine[$k] }
                    $u.Mode = 'lvl1'
                    Write-LevelDecideLog $tr.J -NoEst
                    continue
                }
                if ($tr.Type -eq 'B') {
                    # Declenche a la passe 1 apres un niveau verifie : niveau 12.7 garde, forme non conforme
                    $u.Level = $tr.Unit.Level; $u.Conv = $tr.Unit.Conv; $u.Done = $true; $u.Mode = 'refus'
                    continue
                }
                Set-LevelLevelOnly $u $an
                $u.Early = $true; $u.Done = $true; $u.Mode = 'refus'
                continue
            }
            Set-LevelVerifTargets $cal $u $an
            continue
        }
        if ($u.Mode -eq 'verif') {
            $vr = Test-LevelAdaptVerify $u $p
            $u.VR = $vr
            $an = $u.AN
            if ($vr.Why -and $vr.NewBad.Count -eq 0 -and -not $vr.NoMeas) {
                # 12.8 (F3R) : controle hors tolerance, sans nouveau cylindre hors de la forme : correction du centre par les
                # controles si l ecart est appuye et regulier ; courbe corrigee non verifiee par une ecriture du motif (reserve)
                $ce = Get-LevelCenterEval $u $an 3 $vr
                Write-LevelCenterLog $u $ce
                if ($ce -and $ce.Ok) {
                    foreach ($c in @($ce.AN.Center.Reinc)) { [void]$u.Named.Remove([int]$c) }
                    $u.AN = $ce.AN; $an = $ce.AN
                    $vr.Why = ''; $vr.BadCtl = @(); $vr.Delta = [double]$ce.Drift
                    $u.AV = Build-LevelAdaptValues $u $an.Fit ([string]$an.Model)
                    $an.Center.Verified = $false
                    $u.Conv = [bool]$vr.Conv
                    $u.Level = [int][math]::Round([double]$an.Fit.Coef['a'] + [double]$vr.Delta)
                    $u.Done = $true; $u.Mode = 'adapte'
                    continue
                }
            }
            if ($vr.Why -and $vr.NewBad.Count -eq 0 -and -not $vr.NoMeas -and [string]$an.Model -ne 'M0') {
                # 12.8 (F3R, e2) : refus par un controle seulement : courbe adaptee gardee avec reserve (au lieu du niveau seul),
                # controle apres ecriture impose (G1, modele autre que M0) ; jamais memorisee pour la marque (G5)
                $u.Refus = ''; $u.CtlReserve = [string]$vr.Why; $u.CtlBad = @($vr.BadCtl)
                Append-Log ($pfx + ((T 'Contrôle hors tolérance : {0} ; courbe adaptée gardée avec réserve (contrôle après écriture imposé).') -f "$($vr.Why)"))
                foreach ($x in @($vr.BadCtl)) { $u.Named[[int]$x] = (T 'contrôle hors tolérance') }
                # J4 : ecart isole du centre de meme sens que le controle le plus ecarte : besoin du centre plutot qu un defaut
                $xw = $null
                foreach ($x in @($vr.BadCtl | ForEach-Object { [int]$_ })) {
                    $ax = [math]::Abs([double]$vr.Ctl[$x].Dev)
                    if ($null -eq $xw -or $ax -gt [math]::Abs([double]$vr.Ctl[$xw].Dev) -or ($ax -eq [math]::Abs([double]$vr.Ctl[$xw].Dev) -and $x -gt $xw)) { $xw = $x }
                }
                if ($null -ne $xw -and $an.Iso) {
                    $sx = [math]::Sign([double]$vr.Ctl[$xw].Dev)
                    foreach ($c in @($an.Iso.Keys | ForEach-Object { [int]$_ } | Sort-Object)) {
                        if ($c -lt $script:LevelAdaptCtlLo -or [math]::Sign([double]$an.Iso[$c]) -ne $sx) { continue }
                        $jf = if ($sx -gt 0) { (T "Écart isolé à c{0} ({1} ns) et contrôle c{2} ({3} ns) de même sens : besoin plus fort vers le centre que la forme ajustée, plutôt qu'un défaut ponctuel.") } else { (T "Écart isolé à c{0} ({1} ns) et contrôle c{2} ({3} ns) de même sens : besoin plus faible vers le centre que la forme ajustée, plutôt qu'un défaut ponctuel.") }
                        Append-Log ($pfx + ($jf -f "$c", (Format-LevelSigned $an.Iso[$c]), "$xw", (Format-LevelSigned $vr.Ctl[$xw].Dev)))
                    }
                }
                $u.Conv = [bool]$vr.Conv
                $u.Level = [int][math]::Round([double]$an.Fit.Coef['a'] + [double]$vr.Delta)
                $u.Done = $true; $u.Mode = 'adapte'
                continue
            }
            if ($vr.Why) {
                $u.Refus = [string]$vr.Why
                Append-Log ($pfx + ((T 'Adaptation refusée : {0}. Courbe de la référence décalée conservée.') -f "$($vr.Why)"))
                Set-LevelLevelOnly $u $an
                $u.Early = $true; $u.Done = $true; $u.Mode = 'refus'
                foreach ($c in @($vr.NewBad)) { $u.Named[[int]$c] = (T 'hors de la forme à la vérification') }
                foreach ($x in @($vr.BadCtl)) { $u.Named[[int]$x] = (T 'contrôle hors tolérance') }
                continue
            }
            foreach ($c in @($vr.NonRep)) { $u.Named[[int]$c] = (T 'écart non reproduit à la vérification (non reproductible)') }
            # 12.8 (F3R, e3) : forme reprise avec un terme de centre a la passe de mesure, verifiee a cette passe
            if ($an.Center -and $null -eq $an.Center.Verified) { $an.Center.Verified = $true }
            $u.Conv = [bool]$vr.Conv
            $u.Level = [int][math]::Round([double]$an.Fit.Coef['a'] + [double]$vr.Delta)
            $u.Done = $true; $u.Mode = 'adapte'
            continue
        }
    }
    # 12.8 (S3, c4-design § 4.2) : garde de la passe 1 d une tete partie de la courbe complete d une marque : une disquette
    # qui ne lui ressemble pas arrete la calibration rapide, sans adaptation a partir de cette courbe (choix W-M2)
    if ($p -eq 1 -and @($cal.Units | Where-Object { $_.Memo -and $_.Memo.Curve }).Count -gt 0) {
        $gd = Get-LevelBrandCurveGuard $cal
        if ($gd) { Stop-LevelBrandCurve $cal $gd; return }
    }
    $adapting = (@($cal.Units | Where-Object { -not $_.Done -and @('meas', 'verif', 'nwc') -contains [string]$_.Mode }).Count -gt 0)
    $early = (@($cal.Units | Where-Object { $_.Early }).Count -gt 0)
    if ((@($cal.Units | Where-Object { $_.Fail }).Count -gt 0) -or ($early -and -not $adapting)) {
        # Echec d une tete, ou bascule anticipee sans autre face en cours d adaptation : l autre tete, non terminee, garde
        # son niveau estime (non verifie) ; une face en cours d adaptation garde le niveau seul de ses zeros mesures
        foreach ($u in @($cal.Units | Where-Object { -not $_.Done })) {
            if (@('meas', 'verif') -contains [string]$u.Mode) {
                Set-LevelLevelOnly $u $u.AN
                $u.Mode = 'refus'
                if (-not $u.Refus) { $u.Refus = (T "calibration arrêtée par l'autre face") }
            } else {
                $u.Level = [int][math]::Round([double]$u.Est.Delta); $u.Conv = $false
                if ($u.Mode) { $u.Mode = 'lvl1' }
            }
            $u.Done = $true
        }
        Complete-LevelCalib; return
    }
    if ($early) {
        # Repli d une face pendant l adaptation de l autre : la face adaptee termine sa verification (une passe), une face
        # encore en lvl1 s arrete comme apres une bascule anticipee (niveau estime, non verifie)
        foreach ($u in @($cal.Units | Where-Object { -not $_.Done -and (-not $_.Mode -or [string]$_.Mode -eq 'lvl1') })) { $u.Level = [int][math]::Round([double]$u.Est.Delta); $u.Conv = $false; $u.Done = $true }
    }
    if (@($cal.Units | Where-Object { -not $_.Done }).Count -gt 0) {
        $cal.LPass++; $cal.TotalPasses = [math]::Max([int]$cal.TotalPasses, [int]$cal.LPass)
        New-CalibPass; return
    }
    Complete-LevelCalib
}

function Get-LevelCylRole($u, [int]$c) {
    # 12.8 (lot 1c, point 1) : role d un cylindre de la calibration rapide dans les lignes du journal (Write-CalibPassLog,
    # Write-LevelPassLog) : temoin de marche, temoin du plafond ; cylindre de niveau : aucun
    if (@($u.Wit) -contains $c) { return ' ' + (T '(témoin)') }
    if ($null -ne $u.Probe -and [int]$u.Probe -eq $c) { return ' ' + (T '(plafond)') }
    # 12.8 (lot 1c) : cylindre de controle de la calibration rapide adaptative (hors ajustement)
    if (@($u.Ctl) -contains $c) { return ' ' + (T '(contrôle)') }
    return ''
}

function Write-LevelPassLog($cal, $u, [int]$p) {
    # 12.8 (lot 1c, point 1) : zeros de la calibration rapide apres la passe p, des qu un cylindre a ete mesure a deux
    # valeurs ecrites ou plus, au journal seulement (ni niveaux, ni historique, ni courbe), avant toute decision
    # (Invoke-LevelStep). Element « c<cyl>[ (role)] <zero><marque> ± <incertitude> (<pente propre / pente de reference>) » :
    # zero en ns de precompensation (Get-LevelZero, pente de l estimation de la passe, comme Invoke-LevelStep), marque *
    # (extrapole) ou ^ (borne a 0 ou CalHardNs) ; pente propre : corde des deux valeurs ecrites extremes, « - » sur moins de
    # 4 ns. Prefixe de l unite : « [tete h] », aucun pour la courbe commune (moyenne des deux faces)
    $cyls = @(@(@($u.LCyls) + @($u.Wit) + @($(if ($null -ne $u.Probe) { $u.Probe })) + @($u.Ctl)) | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_ } | Sort-Object -Unique)
    $two = @($cyls | Where-Object { $u.Results[$_] -and @($u.Results[$_].Keys).Count -ge 2 })
    if ($two.Count -eq 0) { return }
    $k = if ($u.ProbeOnly -and $u.Est) { [double]$u.Est.K } else { [double](Get-LevelEstimate $u $p).K }
    $mark = @{ interp = ''; extrap = '*'; cap = '^' }
    $items = @()
    foreach ($c in $two) {
        $pts = $u.Results[$c]
        $z = Get-LevelZero $pts $k
        if (-not $z) { continue }
        $xs = @($pts.Keys | ForEach-Object { [int]$_ } | Sort-Object)
        $ratio = '-'
        if (($xs[-1] - $xs[0]) -ge 4 -and [double]$u.KRef -gt 0) {
            $ko = -([double]$pts[$xs[-1]].Shift - [double]$pts[$xs[0]].Shift) / ($xs[-1] - $xs[0])
            $ratio = Format-UiNum ($ko / [double]$u.KRef) '0.00'
        }
        $sg = if ($null -eq $z.Sig -or [double]::IsNaN([double]$z.Sig)) { '-' } else { Format-UiNum ([double]$z.Sig) '0.0' }
        $items += "c$c$(Get-LevelCylRole $u $c) $(Format-UiNum ([double]$z.Est) '0.0')$($mark[[string]$z.Kind]) ± $sg ($ratio)"
    }
    if ($items.Count -eq 0) { return }
    Append-Log ((T "{0}Zéros après la passe {1} (pente propre, × référence) : {2}.") -f "$($u.Prefix)", "$p", ($items -join ' ; '))
}

function Get-LevelLabel($rec) {
    # « +12 ns » (profil commun) ou « tete 0 +12 ns » ; 12.8 (lot 1c) : « (forme adaptee) » pour une courbe adaptee
    $v = '{0:+0;-0;0} ns' -f [int]$rec.Delta
    # 12.8 (S3) : courbe d une mesure complete de cette disquette (ecart moyen a la reference)
    if ([string]$rec.Model -eq 'mesure') { $v += ' ' + (T '(mesure complète)') }
    elseif ($rec.Model -and [string]$rec.Model -ne 'M0') { $v += ' ' + (T '(forme adaptée)') }
    if ($null -eq $rec.Head) { return $v }
    return ((T "tête {0} {1}") -f "$($rec.Head)", "$v")
}

function Set-LevelFields($recs, [bool]$slow) {
    # Profils decales dans les champs --precomp (tetes physiques en ecriture lente) : pour cette disquette seulement
    $chkWPrecomp.Checked = $true
    $rs = @($recs)
    if ($slow) {
        $r0 = @($rs | Where-Object { $_.Head -eq 0 }); $r1 = @($rs | Where-Object { $_.Head -eq 1 })
        if ($r0.Count -gt 0) { $txtWPrecomp.Text = $r0[0].Spec }
        if ($r1.Count -gt 0) { $txtWPrecomp1.Text = $r1[0].Spec }
    } elseif ($rs.Count -gt 0) { $txtWPrecomp.Text = $rs[0].Spec; $txtWPrecomp1.Text = $rs[0].Spec }
}

function Get-LevelUnitResults($cal, [string]$date) {
    # Bilan de chaque tete de la calibration rapide sans echec : courbe, verdict, reserves, journal, enregistrement dans
    # $script:LevelShifts (historique, niveau de depart). 12.8 (lot 1c) : tetes adaptees ou refusees par
    # Get-LevelAdaptOutcome ; tetes lvl1 : regles 12.7. Info : reserve « information » (plafond, a surveiller, niveau de
    # la courbe adaptee non verifie) de la fenetre de decision. Sans fenetre ni configuration (suite calib-lvl2)
    $issues = New-Object System.Collections.Generic.List[string]
    $info = New-Object System.Collections.Generic.List[bool]
    $recs = @(); $prevRecs = @{}; $verdicts = @()
    foreach ($u in $cal.Units) {
        $e = $u.Est; $pfx = $u.Prefix
        $ad = (@('adapte', 'refus') -contains [string]$u.Mode)
        $model = 'M0'; $cs = 0.0; $cb = 0.0; $kk = if ($e) { [double]$e.K } else { $null }
        $hard = [int]$script:CalHardNs; $over = @(); $hcv = $null
        if ($ad) {
            $ao = Get-LevelAdaptOutcome $cal $u
            $shape = $ao.Shape; $u.Shape = $shape
            $bv = @{ Values = $ao.Values; Sat = @($ao.Sat); Floor = @($ao.Floor); Clip = @($ao.Clip) }
            $verdict = [string]$ao.Verdict
            foreach ($x in $ao.Issues) { $issues.Add([string]$x.Text); $info.Add([bool]$x.Info) }
            $model = [string]$ao.Model; $cs = [double]$ao.S; $cb = [double]$ao.B; if ($null -ne $ao.K) { $kk = [double]$ao.K }
            $hard = [int]$ao.Hard; $over = @($ao.Over); $hcv = $ao.Hc
        } else {
            $shape = Test-LevelShape $e $u 1.0; $u.Shape = $shape
            $bv = Build-LevelValues $u ([int]$u.Level) $e
            # 12.8 (F3R, decision 2) : courbe de la forme d une marque (V' + niveau, courbe adaptee, G1) dont le besoin depasse
            # CalHardNs : plafond porte a celui de cette disquette (12.11 : Get-UnitCapNs, quart de la cellule de l image ; 470 ns
            # avant) ; la reference seule reste a CalHardNs. 12.8 (F3R-FIX, constat 4) : seuil max(CalHardNsDefault, CalHardNs),
            # comme Get-LevelAdaptHard. 12.8 (S3-FLUX, decision 3) : borne precompMaxNs reglee sous CalHardNsDefault : respectee
            $memoExt = $false; $capD = Get-UnitCapNs $u
            $memoThr = [math]::Max([int]$script:CalHardNsDefault, [int]$script:CalHardNs)
            if ($u.Memo -and $capD -gt [int]$script:CalHardNs -and [int]$script:CalHardNs -ge [int]$script:CalHardNsDefault -and $null -ne $bv.RawMax -and [double]$bv.RawMax -gt $memoThr) {
                $bv = Build-LevelValues $u ([int]$u.Level) $e -Hard $capD
                $memoExt = $true; $hard = $capD
                $over = @(0..(@($bv.Values).Count - 1) | Where-Object { [int]$bv.Values[$_] -gt [int]$script:CalHardNs })
            }
            foreach ($c in @($e.Outliers)) { Append-Log ($pfx + ((T "Écart isolé à c{0} ({1} ns par rapport à la forme) : défaut ponctuel probable de cette disquette, écarté du niveau.") -f "$c", ('{0:+0;-0;0}' -f [math]::Round($e.Ds[[int]$c] - $e.Delta, 0)))) }
            $verdict = if ($u.Sat) { 'sat' } elseif ($u.Low) { 'low' } elseif ($u.Few) { 'few' } else { $shape.Verdict }
            switch ($shape.Verdict) {
                'ok'       { Append-Log ($pfx + ((T "Forme conforme à la référence (écart de forme {0} ns).") -f ('{0:0.#}' -f [math]::Round($e.Tau, 1)))) }
                'approx'   { Append-Log ($pfx + ((T "Forme approximative (écart de forme {0} ns) : courbe décalée appliquée ; une calibration complète de cette disquette serait plus précise.") -f ('{0:0.#}' -f [math]::Round($e.Tau, 1)))) }
                'mismatch' { Append-Log ($pfx + ((T "Forme non conforme à la référence : {0}.") -f ($shape.Reasons -join ' ; '))); $issues.Add($pfx + ((T "forme non conforme à la référence : {0}") -f ($shape.Reasons -join ' ; '))); $info.Add($false) }
            }
            if (-not $u.Conv) { $issues.Add($pfx + ((T "niveau non vérifié par une écriture du motif ({0} passe(s))") -f "$($u.Passes)")); $info.Add($false) }
            if ($u.Sat) { $issues.Add($pfx + ((T 'besoin au-delà de {0} ns sur la plupart des cylindres mesurés (support fatigué ?)') -f "$($script:CalHardNs)")); $info.Add($false) }
            if ($u.Low) { $issues.Add($pfx + (T 'précompensation nulle encore excessive sur la plupart des cylindres mesurés')); $info.Add($false) }
            if ($u.Few) { $issues.Add($pfx + ((T "niveau estimé sur {0} cylindre(s) de niveau seulement ({1} au plafond ou au plancher)") -f "$($e.N)", "$(@($e.Capped).Count + @($e.Floored).Count)")); $info.Add($false) }
            # [3] Cylindres de niveau bornes (zero au-dela de CalHardNs ou sous 0 ns) loin du niveau retenu : ecartes, signales
            $bnd = @(@(@($e.Capped) | Where-Object { [int]$u.V[[int]$_] + [int]$u.Level -lt [int]$script:CalHardNs - 15 }) + @(@($e.Floored) | Where-Object { [int]$u.V[[int]$_] + [int]$u.Level -gt 15 }))
            if (-not $u.Sat -and -not $u.Low -and $bnd.Count -gt 0) {
                $bt = (T "besoin hors de 0 à {1} ns aux cylindres de niveau {0}, loin du niveau de cette disquette : écartés du niveau") -f (Format-CylList ([int[]]@($bnd | Sort-Object))), "$($script:CalHardNs)"
                Append-Log ($pfx + $bt + '.'); $issues.Add($pfx + $bt); $info.Add($false)
            }
            # 12.8 (F3R) : plafond par disquette (memoExt) : lignes et reserves plus bas, apres celles de la zone plafonnee
            # 12.11 (L12a) : borne la plus haute a conseiller, jamais au-dela du plafond de l image (Get-BoundAdviceNs, 265)
            $adv = Get-BoundAdviceNs $u
            if ($bv.Sat.Count -gt 0 -and $u.Memo -and -not $memoExt -and [int]$script:CalHardNs -ge $adv) {
                # 12.8 (F3R-FIX, constat 9) : borne precompMaxNs deja a CalHardMaxNs : plus de conseil de la relever. 12.11
                # (L12a) : ni au-dela du plafond de l image ($adv)
                Append-Log ($pfx + ((T 'Plafond de {0} ns atteint aux cylindres {1} avec la courbe adaptée : ces cylindres resteront sous-compensés.') -f "$($script:CalHardNs)", (Format-CylList ([int[]]$bv.Sat))))
                $issues.Add($pfx + ((T 'plafond de {0} ns atteint aux cylindres {1} avec la courbe adaptée : ces cylindres resteront sous-compensés') -f "$($script:CalHardNs)", (Format-CylList ([int[]]$bv.Sat)))); $info.Add($true)
            } elseif ($bv.Sat.Count -gt 0 -and $u.Memo -and -not $memoExt) {
                # 12.8 (FIX1C, constat 5) : courbe de la marque (V', forme adaptee) : libelle neutre du plafond (§ 11.2)
                Append-Log ($pfx + ((T "Plafond de {0} ns atteint aux cylindres {1} avec la courbe adaptée : ces cylindres resteront sous-compensés ; la borne se règle jusqu'à {2} ns (precompMaxNs).") -f "$($script:CalHardNs)", (Format-CylList ([int[]]$bv.Sat)), "$adv"))
                $issues.Add($pfx + ((T "plafond de {0} ns atteint aux cylindres {1} avec la courbe adaptée : ces cylindres resteront sous-compensés ; la borne se règle jusqu'à {2} ns (precompMaxNs)") -f "$($script:CalHardNs)", (Format-CylList ([int[]]$bv.Sat)), "$adv")); $info.Add($true)
            } elseif ($bv.Sat.Count -gt 0 -and -not $u.Memo -and [string]$shape.Verdict -eq 'mismatch') {
                # 12.8 (F3R, decision du 21/10/2026) : forme non conforme : libelle neutre, autre type de disquette ou usure
                Append-Log ($pfx + ((T "Plafond de {0} ns atteint aux cylindres {1} avec le niveau de cette disquette ({2} ns par rapport à la référence), de forme différente : autre type de disquette ou usure, non distingués ; ces cylindres resteront sous-compensés.") -f "$($script:CalHardNs)", (Format-CylList ([int[]]$bv.Sat)), ('{0:+0;-0;0}' -f [int]$u.Level)))
                $issues.Add($pfx + ((T "plafond de {0} ns atteint aux cylindres {1} (autre type de disquette ou usure ?)") -f "$($script:CalHardNs)", (Format-CylList ([int[]]$bv.Sat)))); $info.Add($true)
            } elseif ($bv.Sat.Count -gt 0 -and -not $u.Memo) {
                Append-Log ($pfx + ((T "Plafond de {0} ns atteint aux cylindres {1} avec le niveau de cette disquette ({2} ns par rapport à la référence) : support probablement fatigué, ces cylindres resteront sous-compensés.") -f "$($script:CalHardNs)", (Format-CylList ([int[]]$bv.Sat)), ('{0:+0;-0;0}' -f [int]$u.Level)))
                $issues.Add($pfx + ((T "plafond de {0} ns atteint aux cylindres {1} (support fatigué ?)") -f "$($script:CalHardNs)", (Format-CylList ([int[]]$bv.Sat)))); $info.Add($true)
            }
            if (@($bv.Clip).Count -gt 0) {
                Append-Log ($pfx + ((T "Référence calculée avec une borne de {0} ns, au-delà de la borne actuelle (precompMaxNs = {1} ns) aux cylindres {2} : valeurs ramenées à {1} ns.") -f "$(Get-CurveMaxNs $u.Cv)", "$($script:CalHardNs)", (Format-CylList ([int[]]$bv.Clip))))
            }
            if ($bv.Floor.Count -gt 0) {
                Append-Log ($pfx + ((T "Précompensation nulle encore excessive aux cylindres {0} avec le niveau de cette disquette : ces cylindres resteront sur-compensés.") -f (Format-CylList ([int[]]$bv.Floor))))
                $issues.Add($pfx + ((T "précompensation nulle encore excessive aux cylindres {0}") -f (Format-CylList ([int[]]$bv.Floor)))); $info.Add($false)
            }
            if ($bv.ProbeNote -eq 'interp') { Append-Log ($pfx + ((T "Zone plafonnée de la référence (c{0} à c{1}) : besoin mesuré au témoin c{1} : {2} ns ; zone interpolée jusqu'à cette valeur.") -f "$($u.CapLo)", "$($u.Probe)", ('{0:0.#}' -f [math]::Round($e.ProbeZ, 0)))) }
            elseif ($bv.ProbeNote -eq 'unresolved') {
                $ut = (T "témoin du plafond c{0} non résolu : zone de c{1} à c{0} laissée à la référence ({2} ns, plafond de son calcul), relevée du niveau s'il est positif, sans mesure sur cette disquette") -f "$($u.Probe)", "$($u.CapLo)", "$(Get-CurveMaxNs $u.Cv)"
                Append-Log ($pfx + $ut + '.'); $issues.Add($pfx + $ut); $info.Add($false)
            }
            elseif ($bv.ProbeNote -eq 'cap') { Append-Log ($pfx + ((T "Zone plafonnée de la référence (c{0} à c{1}) : le besoin dépasse encore {2} ns au témoin c{1} ; zone portée jusqu'à {2} ns.") -f "$($u.CapLo)", "$($u.Probe)", "$($script:CalHardNs)")) }
            if ($memoExt) {
                # Plafond par disquette (forme d une marque) : plafond de la disquette ($hard) atteint, courbe au-dela de CalHardNs
                if ($bv.Sat.Count -gt 0) {
                    Append-Log ($pfx + ((T 'Plafond de {0} ns atteint aux cylindres {1} avec la courbe adaptée : ces cylindres resteront sous-compensés.') -f "$hard", (Format-CylList ([int[]]$bv.Sat))))
                    $issues.Add($pfx + ((T 'plafond de {0} ns atteint aux cylindres {1} avec la courbe adaptée : ces cylindres resteront sous-compensés') -f "$hard", (Format-CylList ([int[]]$bv.Sat)))); $info.Add($true)
                }
                if ($over.Count -gt 0) {
                    $top = (@($bv.Values) | Measure-Object -Maximum).Maximum
                    Append-Log ($pfx + ((T "Courbe adaptée au-delà de {0} ns aux cylindres {1} (jusqu'à {2} ns) : le besoin de cette disquette dépasse la borne precompMaxNs ; plafond porté à {3} ns pour cette disquette seulement ; contrôle après écriture imposé.") -f "$($script:CalHardNs)", (Format-CylList ([int[]]$over)), "$top", "$hard"))
                    Append-Log ($pfx + (Get-DiskOverAdviceText ([int]$script:CalHardNs)))   # 12.11 : conseil d essai sur la machine cible
                    $issues.Add($pfx + ((T "courbe adaptée au-delà de {0} ns aux cylindres {1} (jusqu'à {2} ns, plafond porté à {3} ns pour cette disquette seulement) : contrôle après écriture imposé") -f "$($script:CalHardNs)", (Format-CylList ([int[]]$over)), "$top", "$hard")); $info.Add($true)
                }
            }
            # 12.8 (lot 1c) : adaptation refusee apres un declenchement a la passe 2 (decision 12.7 appliquee), pente nulle non
            # confirmee (dérive du lecteur), adaptation non tentee (courbe commune, temoin du plafond : G6)
            if ($u.Refus) { $issues.Add($pfx + ((T 'adaptation refusée : {0}') -f "$($u.Refus)")); $info.Add($false) }
            if ($u.Note) { $issues.Add([string]$u.Note); $info.Add($false) }
            if ($u.AdaptNote) { $issues.Add([string]$u.AdaptNote); $info.Add($false) }
        }
        # Courbe de la marque (V') appliquee par une tete lvl1 ou refusee : forme de la marque enregistree
        if ([string]$u.Mode -ne 'adapte' -and $u.Memo) { $model = $(if ($u.Memo.Model) { [string]$u.Memo.Model } else { 'Msb' }); $cs = [double]$u.Memo.S; $cb = [double]$u.Memo.B }
        # Historique avec la meme reference : support fatigue (12.8, G4 : par rapport a la marque de depart), derive de la
        # reference ; courbe adaptee : libelle neutre a la place de l alerte de fatigue
        $hk = "$($u.RefKey)|$($u.Tag)"; $old = $script:LevelShifts[$hk]; $prevRecs[$hk] = $old
        $hist = @(); if ($old -and [string]$old.RefDate -eq [string]$u.Cv.Date) { $hist = @($old.Hist) }
        $fh = if ($u.Memo) { @($u.Memo.Hist) } else { $hist }
        if ($fh.Count -ge 3 -and $verdict -ne 'adapte' -and $null -ne $u.Level) {
            $hv = @($fh | Select-Object -Last 5 | ForEach-Object { [double]$_.Delta }); $med = [double](Get-Median $hv)
            if ([int]$u.Level - $med -gt $script:LevelFatigueNs) {
                $u.Fatigue = $true       # 12.8 (S3) : besoin bien plus fort que d habitude (J5) : « Mesure complete » proposee
                if ($u.Memo) { Append-Log ((T "{0}Cette disquette demande {1} ns de plus que la marque « {2} » (médiane de {3} mesures) : disquette probablement fatiguée, l'écriture y sera moins sûre.") -f "$pfx", ('{0:0.#}' -f [math]::Round([int]$u.Level - $med, 0)), "$($u.Memo.Brand)", "$($hv.Count)") }
                # 12.8 (F3R, decision du 21/10/2026) : forme non conforme, sans marque : autre type de disquette ou usure
                elseif ([string]$shape.Verdict -eq 'mismatch') { Append-Log ($pfx + ((T "Cette disquette demande {0} ns de plus que la médiane des {1} dernières disquettes mesurées avec cette référence, avec une forme différente : autre type de disquette ou usure, non distingués.") -f ('{0:0.#}' -f [math]::Round([int]$u.Level - $med, 0)), "$($hv.Count)")) }
                else { Append-Log ($pfx + ((T "Cette disquette demande {0} ns de plus que la médiane des {1} dernières disquettes mesurées avec cette référence : support probablement fatigué, l'écriture y sera moins sûre.") -f ('{0:0.#}' -f [math]::Round([int]$u.Level - $med, 0)), "$($hv.Count)")) }
            }
        }
        if (-not $ad -and -not $u.Memo -and $hist.Count -ge 3) {
            $l5 = @(@($hist | Select-Object -Last 4 | ForEach-Object { [double]$_.Delta }) + @([double]$u.Level))
            if ($l5.Count -ge 5 -and (@($l5 | Where-Object { $_ -gt $script:LevelFatigueNs }).Count -eq 5 -or @($l5 | Where-Object { $_ -lt -$script:LevelFatigueNs }).Count -eq 5)) {
                Append-Log ($pfx + ((T "Les {0} dernières disquettes s'écartent toutes de la référence dans le même sens (de {1} à {2} ns) : la référence a peut-être été mesurée sur une disquette atypique. Une nouvelle calibration complète en test fin, sur une disquette sacrifiée en bon état, est conseillée.") -f "$($l5.Count)", ('{0:+0;-0;0}' -f ($l5 | Measure-Object -Minimum).Minimum), ('{0:+0;-0;0}' -f ($l5 | Measure-Object -Maximum).Maximum)))
            }
        }
        # Niveau de depart des disquettes de cette reference (D0) : tete non adaptee, forme conforme ou approximative,
        # niveau verifie, sans forme de marque au depart (12.8 : une disquette d une autre marque ne le deplace pas)
        if (($verdict -eq 'ok' -or $verdict -eq 'approx') -and $u.Conv -and -not $u.Early -and -not $u.Memo) { $hist = @(@($hist) + @(@{ Date = $date; Delta = [int]$u.Level })) }
        if ($hist.Count -gt $script:LevelHistMax) { $hist = @($hist | Select-Object -Last $script:LevelHistMax) }
        # Mesures : cylindres de niveau, temoins de marche et du plafond ; tete adaptee : zeros mesures a deux precompensations
        $mc = @(); $mz = @(); $md = @(); $ms = @(); $mk = @()
        $an = $u.AN
        if ($ad -and $an -and $an.Zs -and $an.Zs.Count -gt 0) {
            foreach ($ci in @($an.Zs.Keys | ForEach-Object { [int]$_ } | Sort-Object)) {
                $z = $an.Zs[$ci]
                $mc += $ci; $mz += [math]::Round([double]$z.Est, 1); $md += [math]::Round([double]$z.Est - [double]$u.ShapeV.V[$ci], 1); $ms += [math]::Round([double]$z.Sig, 1)
                $mk += $(if ($u.Named.ContainsKey($ci)) { 'outlier' } elseif (@($u.Wit) -contains $ci) { 'witness' } else { [string]$z.Kind })
            }
        } else {
            foreach ($c in @($u.LCyls)) {
                $ci = [int]$c
                if ($e.Ds.ContainsKey($ci)) { $mc += $ci; $mz += [math]::Round([double]$u.V[$ci] + $e.Ds[$ci], 1); $md += [math]::Round($e.Ds[$ci], 1); $ms += [math]::Round($e.Sigs[$ci], 1); $mk += $(if (@($e.Outliers) -contains $ci) { 'outlier' } else { [string]$e.Kinds[$ci] }) }
                elseif (@($e.Capped) -contains $ci) { $mc += $ci; $mz += [double]$script:CalHardNs; $md += [math]::Round([double]$script:CalHardNs - [double]$u.V[$ci], 1); $ms += 0.0; $mk += 'cap' }
                elseif (@($e.Floored) -contains $ci) { $mc += $ci; $mz += 0.0; $md += [math]::Round(-[double]$u.V[$ci], 1); $ms += 0.0; $mk += 'cap' }
            }
            foreach ($c in @($u.Wit)) { $wz = $e.Wit[[int]$c]; if ($wz) { $mc += [int]$c; $mz += [math]::Round($wz.Z, 1); $md += [math]::Round($wz.D, 1); $ms += [math]::Round($wz.Sig, 1); $mk += 'witness' } }
            if ($null -ne $u.Probe -and $null -ne $e.ProbeZ) { $mc += [int]$u.Probe; $mz += [math]::Round([double]$e.ProbeZ, 1); $md += [math]::Round([double]$e.ProbeZ - [double]$u.V[[int]$u.Probe], 1); $ms += 0.0; $mk += 'probe' }
        }
        $rEst = [double]$e.Delta; $rSe = [double]$e.SE; $rTau = [double]$e.Tau
        if ([string]$u.Mode -eq 'adapte' -and $an -and $an.Fit) { $rEst = [double]$an.Fit.Coef['a']; $rSe = [math]::Sqrt([math]::Max(0.0, [double]$an.Fit.Cov[0][0])); $rTau = [double]$an.Fit.Tau }
        $rec = @{ RefKey = $u.RefKey; Tag = $u.Tag; Head = $u.Head; Drive = $cal.Drive; Date = $date; RefDate = [string]$u.Cv.Date; RefTest = [string]$u.Cv.Test
                  Delta = [int]$u.Level; Est = [math]::Round($rEst, 1); SE = [math]::Round($rSe, 1); Tau = [math]::Round($rTau, 1)
                  Verdict = $verdict; Shape = [string]$shape.Verdict; Reasons = [string[]]@($shape.Reasons); Conv = [bool]$u.Conv; Passes = [int]$u.Passes
                  Cyls = [int[]]$mc; Zs = [double[]]$mz; Ds = [double[]]$md; Sigs = [double[]]$ms; Kinds = [string[]]$mk
                  Values = [int[]]$bv.Values; Spec = (Build-CurveProfile $bv.Values); Sat = [int[]]@($bv.Sat); Floor = [int[]]@($bv.Floor)
                  Hist = @($hist); Version = $script:Version; Algo = $script:CalibAlgo
                  # 12.8 (lot 1c, G2) : 'lvl2' seulement pour une forme adaptee (une 12.7 relit les autres et ignore celles-ci)
                  LevelAlgo = $(if ($model -ne 'M0') { 'lvl2' } else { 'lvl1' }); Model = $model; S = [math]::Round($cs, 4); B = [math]::Round($cb, 2)
                  # 12.8 (F3R) : terme de centre (informatif), plafond de la courbe et cylindres au-dela de CalHardNs
                  Hc = $(if ($null -ne $hcv) { [math]::Round([double]$hcv, 2) } else { $null }); Hard = [int]$hard; Over = [int[]]@($over)
                  Mode = $(if ($u.Mode) { [string]$u.Mode } else { 'lvl1' }); Brand = [string]$cal.Brand; Ctl = [int[]]@($u.Ctl); K = $(if ($null -ne $kk) { [math]::Round($kk, 3) } else { $null }) }
        $script:LevelShifts[$hk] = $rec
        $recs += ,$rec; $verdicts += $verdict
    }
    # 12.7 point 5 : etat de la surface de la disquette a la premiere passe (Invoke-LevelSurface) : disquette douteuse,
    # defaut grossier poursuivi ou sans fenetre (calibration rapide sans ecriture) : reserve si la fenetre de decision
    # s ouvre pour une autre raison
    # Defaut de vitesse seul (arbitrage 12, Test-CalibSpeedOnly) : reserve qui nomme le controle de vitesse, pas le support
    if ($issues.Count -gt 0 -and $cal.Surf -and ($cal.Surf.Defective -or $cal.SurfGross)) {
        $issues.Add($(if ($cal.Surf.Defective) { Format-CalibSurfaceReserve $cal.Surf }
                      elseif (Test-CalibSpeedOnly $cal.Surf $cal.Medium) { (T "contrôle de vitesse et de densité : {0} à la première passe") -f (Format-CalibSurfaceVerdict $cal.Surf $cal.Medium) }
                      else { (T "support : {0} à la première passe") -f (Format-CalibSurfaceVerdict $cal.Surf $cal.Medium) }))
        $info.Add($false)
    }
    return @{ Issues = $issues; Info = $info; Recs = $recs; PrevRecs = $prevRecs; Verdicts = $verdicts }
}

function Get-LevelReviewPlan($cal, $res, [bool]$toWrite) {
    # 12.8 (lot 1c, § 7, G3) : fenetre de decision de la calibration rapide. Avertissement (point 2) : une tete a une forme
    # non conforme non adaptee ET un niveau non verifie, ou une forme adaptee avec reserve. « Calibration complete »
    # (G3) : seulement apres une forme non conforme non adaptee (repli ou refus), jamais pour un plafond, un « a
    # surveiller », un niveau adapte non verifie ou une reserve. Information : reserves d information seules et une tete
    # adaptee (ou partie de la forme d une marque, FIX1C) : « Ecrire l image » principal, en-tete de la courbe adaptee
    # (Verified : niveau verifie sur toutes les tetes adaptees), champ de marque si toutes les tetes sont verifiees
    # (adaptees sans reserve, ou niveau verifie)
    $units = @($cal.Units)
    $adapted = @($units | Where-Object { [string]$_.Mode -eq 'adapte' -and $_.AN -and [string]$_.AN.Model -ne 'M0' })
    # 12.8 (FIX1C, constat 5) : tete partie de la forme memorisee d une marque, sans nouvelle adaptation (courbe V' et
    # niveau) : courbe adaptee elle aussi, fenetre « information » aux memes conditions
    $memoCv = @($units | Where-Object { $_.Memo -and @('adapte', 'refus') -notcontains [string]$_.Mode })
    # 12.8 (FIX1C, constat 7) : en-tete « verifiee par une ecriture du motif » seulement si aucune tete adaptee (niveau seul
    # confirme compris) n a un niveau decale sans nouvelle ecriture
    $verified = (@($units | Where-Object { [string]$_.Mode -eq 'adapte' -and -not $_.Conv }).Count -eq 0)
    $mm = @($units | Where-Object { $_.Shape -and [string]$_.Shape.Verdict -eq 'mismatch' })
    $warnMm = (@($mm | Where-Object { -not $_.Conv }).Count -gt 0)
    $resv = @($adapted | Where-Object { $_.Conv -and @($_.AN.Reserve).Count -gt 0 })
    # 12.8 (F3R) : forme adaptee gardee avec reserve apres un controle hors tolerance (e2, W1), centre corrige par les
    # controles sans verification par une ecriture du motif (W2)
    $ctlR = @($adapted | Where-Object { $_.CtlReserve })
    $cenR = @($adapted | Where-Object { $_.AN.Center -and $_.AN.Center.Verified -eq $false })
    $warnText = if ($warnMm) { (T "Attention : niveau non vérifié et forme non conforme. La courbe que « Écrire l'image » utiliserait n'a pas été vérifiée sur cette disquette ; vers le centre, elle peut s'écarter de son besoin de plusieurs dizaines de ns.") }
                elseif ($resv.Count -gt 0) { (T "Attention : forme adaptée avec réserve (c{0} suspect). La courbe a été vérifiée, mais un défaut local de cette disquette est possible ; le contrôle après écriture sera fait.") -f "$($resv[0].AN.Suspect)" }
                elseif ($ctlR.Count -gt 0) { (T "Attention : forme adaptée avec réserve (contrôle c{0} hors tolérance). Vers le centre, la courbe peut s'écarter du besoin de cette disquette ; le contrôle après écriture sera fait.") -f "$(@(@($ctlR[0].CtlBad) | ForEach-Object { [int]$_ } | Sort-Object)[0])" }
                elseif ($cenR.Count -gt 0) { (T "Attention : forme adaptée avec réserve (centre corrigé par les contrôles {0}). Vers le centre, la courbe est extrapolée des contrôles, sans vérification par une écriture du motif ; le contrôle après écriture sera fait.") -f ((@($cenR[0].AN.Center.R.Keys | ForEach-Object { [int]$_ } | Sort-Object -Unique) | ForEach-Object { "c$_" }) -join ', ') }
                else { '' }
    $offerFull = [bool](($cal.CanFallback -or -not $toWrite) -and $mm.Count -gt 0)
    $infoOnly = ($res.Issues.Count -gt 0 -and -not ($res.Info -contains $false))
    $infoWin = [bool]($infoOnly -and -not $warnText -and -not $offerFull -and ($adapted.Count + $memoCv.Count) -gt 0)
    $brandAsk = [bool]($infoWin -and $cal.Slow -and @($units | Where-Object { -not (Get-LevelBrandVerified $_) }).Count -eq 0)
    $prefill = [string]$cal.Brand
    if ($brandAsk -and $prefill -and @(Get-LevelBrandPlan $cal $prefill | Where-Object { $_.Differs }).Count -gt 0) { $prefill = '' }
    $names = @(@($script:LevelBrands) | Where-Object { $_ -and [string]$_.Drive -eq [string]$cal.Drive } | Sort-Object { Get-CurveDate $_ } -Descending | ForEach-Object { [string]$_.Brand } | Select-Object -Unique)
    # 12.8 (S3, c4-design § 4.3) : « Mesure complete de cette disquette » (W-M1, OfferDisk) avant une ecriture lente hors
    # restauration (CanDisk), quand la disquette s ecarte de la reference : forme non conforme, forme adaptee avec reserve
    # (W1, W2, ecart suspect), courbe au-dela de CalHardNs (plafond par disquette) ou plafond atteint, besoin bien plus fort
    # que d habitude (J5, Fatigue). Complete-LevelCalib n affiche alors pas « Calibration complete » (OfferFull, inchange) :
    # elle remplacerait la reference du lecteur par une disquette d un autre type (risque G7)
    $over = @(@($res.Recs) | Where-Object { $_ -and (@($_.Over).Count -gt 0 -or @($_.Sat).Count -gt 0) })
    $fat = @($units | Where-Object { $_.Fatigue })
    $offerDisk = [bool]($toWrite -and $cal.CanDisk -and $cal.Slow -and $cal.Lr -and ($mm.Count + $resv.Count + $ctlR.Count + $cenR.Count + $over.Count + $fat.Count) -gt 0)
    $diskMin = if ($offerDisk) { Get-DiskMeasureMinutes ([int]$cal.MaxCyl + 1) ([string]$cal.Family -eq 'hd') } else { 0 }
    return @{ Warn = [bool]$warnText; WarnText = $warnText; OfferFull = $offerFull; Info = $infoWin; BrandAsk = $brandAsk; Brand = $prefill; Brands = $names; Adapted = $adapted; MemoCurve = $memoCv; Verified = $verified
              OfferDisk = $offerDisk; DiskMin = $diskMin }
}

function Complete-LevelCalib {
    $cal = $script:Cal; $script:Cal = $null
    if (-not $cal) { return }
    $pbWCal.Value = 100
    $elapsed = if ($cal.StartTime -is [datetime]) { ((Get-Date) - $cal.StartTime).TotalSeconds } else { 0 }
    $toWrite = ($script:AfterCalib -eq 'write')
    $famTxt = Get-CalibFamilyName $cal.Family
    $fails = @($cal.Units | Where-Object { $_.Fail })
    if ($fails.Count -gt 0) {
        foreach ($u in $fails) {
            if ($u.Fail -eq 'nowrite') { Append-Log ($u.Prefix + (T 'Calibration : le décalage ne varie pas avec la précompensation écrite, cette face n''a pas été écrite (tête ou circuit d''écriture défaillant ?).')) }
            else { Append-Log ((T "{0}Calibration rapide : moins de 3 cylindres mesurables, niveau impossible à estimer.") -f "$($u.Prefix)") }
        }
        $pbWCal.Visible = $false
        $nw = (@($fails | Where-Object { $_.Fail -eq 'nowrite' }).Count -gt 0)
        $lblWCal.Text = $(if ($nw) { (T 'Calibration rapide : une face ne réagit pas à la précompensation (voir le journal).') } else { (T 'Calibration rapide sans mesure exploitable.') })
        if ($toWrite -and $cal.SurfKept) {
            # 12.7 point 5 : « Ecrire quand meme » choisi dans la fenetre « Disquette a ecrire defectueuse » (face sans
            # cylindre mesurable, par exemple) : l image est ecrite comme annonce, avec la courbe du lecteur (champs
            # --precomp inchanges, aucun niveau mesure), comme une ecriture sans reference (decision 4)
            $script:AfterCalib = ''
            Append-Log (T "Mesure de la disquette sans niveau exploitable : écriture poursuivie à votre demande avec la courbe du lecteur, sans niveau mesuré.")
            if ($script:Restore) {
                $r = $script:Restore
                $nt = (T "niveau non mesuré : {0}") -f $(if ($nw) { (T 'une face ne réagit pas à la précompensation') } else { (T 'calibration rapide sans mesure exploitable') })
                $bt = if ($r.CalibUsed) { ((T "calibration existante ({0}), pas de recalibration") -f "$($r.CalibUsed.Text)") + ' ; ' } elseif ($r.CalSwap) { ((T "faite sur une disquette sacrifiée ({0})") -f "$($r.Calib)") + ' ; ' } else { '' }
                $r.Level = @{ State = 'warn'; Text = "$bt$nt"; Report = $nt }
                $r.InCall = $true
            }
            try { Start-ImageWrite -NoWarmup:([bool]$cal.WarmSkip); if ($script:Restore) { Set-RestoreRepRules } } finally { if ($script:Restore) { $script:Restore.InCall = $false; $script:Restore.Idle = Get-Date } }
            if ($script:Restore -and -not ($script:GwProc -and -not $script:GwProc.HasExited) -and $script:Chain.Count -eq 0) { Stop-Restore (T 'l''écriture n''a pas démarré après la calibration, voir le journal') }
            return
        }
        Set-HomeProgDone $cal 'stop'
        if ($toWrite) { $script:AfterCalib = ''; Append-Log $(if ($nw) { (T 'Écriture annulée : une face ne réagit pas à la précompensation.') } else { (T 'Écriture annulée : calibration rapide sans mesure exploitable.') }) }
        if ($script:Restore) { Stop-Restore $(if ($nw) { (T 'une face ne réagit pas à la précompensation') } else { (T 'calibration rapide sans mesure exploitable') }) }
        return
    }
    $date = Get-Date -Format 'dd/MM/yyyy HH:mm'
    $res = Get-LevelUnitResults $cal $date
    $issues = $res.Issues; $recs = $res.Recs; $prevRecs = $res.PrevRecs; $verdicts = $res.Verdicts
    if (-not $script:Restore) { [void](Save-Config) }
    # 12.8 (FIX-PISTES-2) : Lbl $null quand le libelle porte l avis de la Bibliotheque (Get-WProfileText)
    $fieldsPrev = @{ Prof = $cmbWProfile.SelectedIndex; On = $chkWPrecomp.Checked; P0 = $txtWPrecomp.Text; P1 = $txtWPrecomp1.Text; Lbl = (Get-WProfileText) }
    # Carte Calibration de l Accueil : profil place dans les champs --precomp seulement si l image de l onglet Ecriture est
    # de la famille calibree (sinon il reste affiche dans la fenetre Courbe, derniere calibration rapide)
    # 12.10 (relecture de la RC) : carte de l Accueil, lecteur cible avec effet sur l image de l onglet (Get-TargetWriteInfo,
    # celui de Start-ImageWrite, qui remettrait la courbe croisee dans les champs, ou refuserait l ecriture) : profil de
    # cette disquette non place dans les champs, ligne de journal qui le dit (le bouton « Calibrer » refuse ce cas :
    # Start-LevelCalibButton)
    $tgtL = if ($cal.Home) { Get-TargetWriteInfo $txtWFile.Text $cmbWFmt.Text ([bool]$chkWSlow.Checked) } else { $null }
    $toFields = (-not $cal.Home) -or ((Get-WriteTabFamily) -eq $cal.Family -and -not $tgtL.Applies)
    if ($toFields) {
        if ($cmbWProfile.SelectedIndex -ne 0) { $cmbWProfile.SelectedIndex = 0 }   # Auto : profil decale remplace au prochain changement d image
        Set-LevelFields $recs $cal.Slow
    }
    $plan = Get-LevelReviewPlan $cal $res $toWrite
    # 12.8 (lot 1c) : courbe adaptee a cette disquette (forme ajustee, ou forme d une marque memorisee au depart)
    $adCurve = ($plan.Adapted.Count -gt 0) -or (@($cal.Units | Where-Object { $_.Memo -and [string]$_.Mode -ne 'adapte' }).Count -gt 0)
    $lvlTxt = (@($recs | ForEach-Object { Get-LevelLabel $_ })) -join ', '
    $sv = @($cal.Units | ForEach-Object { [string]$_.Shape.Verdict })
    $shapeTxt = if ($sv -contains 'mismatch') { (T 'NON CONFORME') } elseif ($verdicts -contains 'sat' -or $verdicts -contains 'low') { ((T 'non vérifiée (limite de 0 ou {0} ns atteinte)') -f "$($script:CalHardNs)") } elseif ($verdicts -contains 'few') { (T 'non vérifiée (trop peu de cylindres mesurés)') } elseif ($sv -contains 'adapte' -or @($plan.MemoCurve).Count -gt 0) { (T 'adaptée à cette disquette') } elseif ($sv -contains 'approx') { (T 'approximative') } else { (T 'conforme') }
    $lblWCal.Text = ((T "Calibration rapide terminée en {0} : niveau {1}, forme {2}.") -f (Format-CalDuration $elapsed), "$lvlTxt", "$shapeTxt")
    if ($toFields) {
        if ($adCurve) { $lblWProfileInfo.Text = ((T "Profil {0} de cette disquette (calibration rapide du {1}, lecteur {2}) : référence du {3} adaptée à cette disquette ({4}){5}. À n'utiliser que pour cette disquette (bouton Courbe).") -f "$famTxt", "$date", "$($cal.Drive)", "$($recs[0].RefDate)", "$lvlTxt", $(if ($cal.Brand) { (T ', marque « {0} »') -f "$($cal.Brand)" } else { '' })) }
        else { $lblWProfileInfo.Text = ((T "Profil {0} de cette disquette (calibration rapide du {1}, lecteur {2}) : référence du {3} décalée de {4}. À n'utiliser que pour cette disquette (bouton Courbe).") -f "$famTxt", "$date", "$($cal.Drive)", "$($recs[0].RefDate)", "$lvlTxt") }
    }
    elseif ($tgtL -and $tgtL.Applies -and (Get-WriteTabFamily) -eq $cal.Family) { Append-Log ((T "Calibration rapide depuis l'Accueil : lecteur cible {0} choisi pour le lecteur {1}, dont l'écriture n'utilise pas cette mesure (courbe croisée {1} → {0} telle quelle, ou refus sans elle) : le profil de cette disquette n'est pas placé dans les champs --precomp ; il reste affiché dans la fenêtre Courbe (dernière calibration rapide).") -f "$($tgtL.Tgt)", "$($tgtL.Src)") }
    else { Append-Log ((T "Calibration rapide depuis l'Accueil : l'image de l'onglet Écriture n'est pas de la famille {0}, le profil de cette disquette n'est pas placé dans ses champs --precomp ; il reste affiché dans la fenêtre Courbe (dernière calibration rapide).") -f "$famTxt") }
    Append-Log ((T "Calibration rapide terminée en {0} : {1} passe(s), {2} écritures de piste sur {3} cylindres (2 faces), aucune ailleurs.") -f (Format-CalDuration $elapsed), "$($cal.PassesDone)", "$($cal.TrackWrites)", "$(@($cal.Cyls).Count)")
    Append-Log ((T "Niveau retenu : {0}.") -f "$lvlTxt")
    foreach ($rec in $recs) { $pp = if ($null -eq $rec.Head) { '' } else { (T '[tête {0}] ') -f "$($rec.Head)" }; Append-Log ((T "{0}Profil {1} de cette disquette : {2}") -f "$pp", "$famTxt", "$($rec.Spec)") }
    if ($script:Restore) {
        $r = $script:Restore
        $cn = $false
        $base = if ($r.CalibUsed) { ((T "calibration existante ({0}), pas de recalibration") -f "$($r.CalibUsed.Text)") + $(if ($r.CalibUsed.Notes.Count -gt 0) { ' ; ' + ($r.CalibUsed.Notes -join ' ; ') } else { '' }) }
                elseif ($r.CalSwap) {
                    # Calibration faite pendant cette restauration, sur une disquette sacrifiee : sa non-convergence reste signalee
                    $fo = Get-ImageFamily $r.Orig
                    $cn = (@(@(0, 1) | Where-Object { $cvn = $script:PrecompCurves["${fo}_h$_"]; $cvn -and $cvn.Converged -eq $false }).Count -gt 0)
                    $am = @(@(0, 1) | ForEach-Object { $script:PrecompCurves["${fo}_h$_"] } | Where-Object { Test-CurveAtMax $_ })
                    $bt = if ($cn) { (T 'faite, non convergée sur une tête : voir le journal') } else { (T "faite sur une disquette sacrifiée ({0})") -f "$($r.Calib)" }
                    if ($am.Count -gt 0) { $bt += ' ; ' + ((T "courbe au plafond de {0} ns de son calcul") -f "$(Get-CurveMaxNs $am[0])"); $cn = $true }
                    $bt
                } else { '' }
        $lt = (T "niveau mesuré sur la destination : {0} ({1} passe(s))") -f "$lvlTxt", "$($cal.PassesDone)"
        if ($shapeTxt -eq (T 'approximative')) { $lt += ' ; ' + ((T "forme {0}") -f "$shapeTxt") }
        if ($issues.Count -gt 0) { $lt += ' ; ' + ($issues -join ' ; ') }
        $r.Level = @{ State = $(if ($issues.Count -gt 0 -or $cn -or ($r.CalibUsed -and $r.CalibUsed.Notes.Count -gt 0)) { 'warn' } else { 'ok' }); Text = $(if ($base) { "$base ; $lt" } else { $lt }); Report = $lt }
    }
    $brandName = [string]$cal.Brand; $brandExplicit = $false
    if ($issues.Count -gt 0) {
        Append-Log ((T "Calibration : résultat douteux ({0}) : courbe affichée, décision demandée.") -f ($issues -join ' ; '))
        if ($script:Restore) { $script:Restore.InCall = $true }
        # Carte Calibration de l Accueil sans profil dans les champs --precomp : textes de la decision sans ces champs
        $noFields = ([bool]$cal.Home -and -not $toFields)
        # 12.8 (lot 1c, point 2, § 7, G3) : avertissement, « Calibration complete » et fenetre « information » (Get-LevelReviewPlan)
        $script:CalReviewBrand = $null
        # 12.8 (S3) : « Mesure complete de cette disquette » (W-M1) a la place de « Calibration complete » quand elle est proposee
        $lv2 = @{ WarnText = $plan.WarnText; Info = $plan.Info; BrandAsk = $plan.BrandAsk; Brand = $plan.Brand; Brands = $plan.Brands; Verified = $plan.Verified
                  OfferDisk = $plan.OfferDisk; DiskMin = $plan.DiskMin }
        $showFull = [bool]($plan.OfferFull -and -not $plan.OfferDisk)
        try { $choice = Show-CalibReview $cal @($issues) $toWrite $showFull $noFields $false $null $plan.Warn $lv2 }
        finally { if ($script:Restore) { $script:Restore.InCall = $false; $script:Restore.Idle = Get-Date } }
        if ($choice -eq 'stop' -or $choice -eq 'disk') {
            # Resultat refuse : niveaux precedents retablis, champs ramenes a la reference
            foreach ($k in @($prevRecs.Keys)) { if ($prevRecs[$k]) { $script:LevelShifts[$k] = $prevRecs[$k] } else { $script:LevelShifts.Remove($k) } }
            if (-not $script:Restore) { [void](Save-Config) }
            if ($cmbWProfile.SelectedIndex -ne $fieldsPrev.Prof) { $cmbWProfile.SelectedIndex = $fieldsPrev.Prof }
            Update-PrecompForImage $txtWFile.Text
            $chkWPrecomp.Checked = $fieldsPrev.On; $txtWPrecomp.Text = $fieldsPrev.P0; $txtWPrecomp1.Text = $fieldsPrev.P1
            if ($null -ne $fieldsPrev.Lbl) { $lblWProfileInfo.Text = $fieldsPrev.Lbl }
            if ($choice -eq 'disk') {
                # 12.8 (S3) : mesure complete de cette disquette, sur la reference en place (Start-DiskMeasure) ; la marque choisie
                # dans l avertissement de la calibration rapide est proposee de nouveau
                $pbWCal.Visible = $false
                Append-Log (T "Mesure complète de cette disquette demandée : le résultat de la calibration rapide n'est pas conservé.")
                $script:AfterCalib = ''
                Start-DiskMeasure $cal.Lr ([string]$cal.Brand)
                return
            }
            if ($script:Restore) { $script:Restore.Level = $null }     # niveau refuse : absent de l etape 4 et du rapport
            $pbWCal.Visible = $false
            if ($noFields) { $lblWCal.Text = (T 'Calibration rapide abandonnée.'); Append-Log (T 'Calibration rapide abandonnée à votre demande : niveau non conservé.') }
            else {
                $lblWCal.Text = (T 'Calibration rapide abandonnée : champs --precomp rétablis.')
                Append-Log (T 'Calibration rapide abandonnée à votre demande : niveau non conservé, champs --precomp rétablis.')
            }
            # 12.8 (lot 1c, point 1) : mesures des passes (Write-CalibPassLog, Write-LevelPassLog) gardees au journal
            Append-Log (T "Résultat refusé : les mesures ci-dessus restent au journal, rien n'est enregistré pour cette disquette.")
            if ($toWrite) { $script:AfterCalib = ''; Append-Log (T 'Écriture annulée : résultat de calibration refusé.'); if ($script:Restore) { Stop-Restore (T 'résultat de calibration refusé') } }
            Set-HomeProgDone $cal 'abandon' $issues[0]
            return
        }
        # Calibration complete demandee : bilan avec reserves, remplace par la progression si elle demarre
        if ($choice -eq 'full') { Set-HomeProgDone $cal 'warn' $issues[0]; Start-LevelFallback $cal ($issues -join ' ; ') $toWrite $noFields; return }
        Append-Log (T 'Calibration : résultat accepté malgré les réserves.')
        # 12.8 (lot 1c, § 10.1) : marque nommee dans la fenetre « information » (champ vide : rien n est memorise)
        if ($plan.BrandAsk -and $null -ne $script:CalReviewBrand) {
            $brandName = ([string]$script:CalReviewBrand).Trim(); $brandExplicit = [bool]$brandName
            Append-Log $(if ($brandName) { (T 'Marque nommée dans la fenêtre de décision : « {0} ».') -f "$brandName" } else { (T 'Marque non nommée dans la fenêtre de décision : forme non mémorisée.') })
        }
    }
    # 12.8 (lot 1c, § 10.4, G5) : memoire de la marque (resultat accepte)
    if ($brandName) {
        Update-LevelBrands $cal $brandName $brandExplicit
        if (-not $script:Restore) { [void](Save-Config) }
    }
    Set-HomeProgDone $cal $(if ($issues.Count -gt 0) { 'warn' } else { 'ok' }) $(if ($issues.Count -gt 0) { $issues[0] } else { '' })
    if ($toWrite) {
        $script:AfterCalib = ''
        Append-Log (T 'Calibration rapide terminée : écriture de l''image avec le niveau mesuré.')
        # 12.8 (lot 1c, G1) : courbe adaptee a cette disquette : controle apres ecriture impose, meme case decochee (parade au
        # risque residuel d un defaut confondu avec la forme, a c2, et a l usure lisse : la consequence se voit a l ecriture)
        if ($adCurve) { $script:LevelPostForce = $true; Append-Log (T 'Contrôle après écriture imposé : courbe adaptée à cette disquette.') }
        if ($script:Restore) { $script:Restore.InCall = $true }
        # Prechauffage passe pendant la calibration (bouton « Passer le prechauffage ») : pas de second prechauffage
        try { Start-ImageWrite -NoWarmup:([bool]$cal.WarmSkip); if ($script:Restore) { Set-RestoreRepRules } } finally { if ($script:Restore) { $script:Restore.InCall = $false; $script:Restore.Idle = Get-Date } }
        if ($script:Restore -and -not ($script:GwProc -and -not $script:GwProc.HasExited) -and $script:Chain.Count -eq 0) { Stop-Restore (T 'l''écriture n''a pas démarré après la calibration, voir le journal') }
        # Le profil decale ne vaut que pour cette disquette : remplace par celui de la reference quand l ecriture (controle
        # apres ecriture compris) est terminee (minuterie principale) ; positionne apres Start-ImageWrite, qui peut ouvrir
        # une fenetre avant de lancer gw
        if (-not $script:Restore) { $script:LevelFieldsPending = $true }
        return
    }
    $pbWCal.Visible = $false
    Show-PrecompCurve $cal.Family $cal.Slow
}

function Start-LevelFallback($cal, [string]$why, [bool]$toWrite, [bool]$noFields = $false) {
    # Calibration complete en test fin a la demande de l utilisateur, apres une calibration rapide douteuse : elle
    # devient la nouvelle reference ; sur disquette sacrifiee, le niveau de la disquette a ecrire est mesure ensuite.
    # noFields : calibration rapide de l Accueil dont le profil n est pas dans les champs --precomp (Complete-LevelCalib)
    Append-Log ((T "Calibration complète demandée après la calibration rapide ({0}).") -f "$why")
    # 12.8 (lot 1c, point 3, exception a D7 acceptee le 19/10) : confirmation sans compte a rebours, case « disquette
    # sacrifiee » obligatoire (Start-PrecompCalib, $script:CalFallbackAsk) ; avant une ecriture, la disquette a ecrire est
    # redemandee apres la calibration, puis mesuree (Swap, LevelAfter). Forme non conforme : texte du point 3 ; autre
    # reserve : texte de la 12.7, refus par « Fermer »
    $mm = (@($cal.Units | Where-Object { $_.Shape -and [string]$_.Shape.Verdict -eq 'mismatch' }).Count -gt 0)
    $introFmt = if ($mm) { (T "La forme de cette disquette ne correspond pas à la référence et n'a pas pu être adaptée ({0}). La calibration complète mesure de nouveau le lecteur sur une disquette sacrifiée : elle remplace la référence de forme du lecteur {1}, utilisée ensuite pour toutes vos disquettes. Une sauvegarde de la configuration est faite avant. Fermer : rien de plus n'est écrit.") }
                elseif ($noFields) { (T "La calibration rapide ne convient pas à cette disquette ({0}).`nCalibration complète en test fin ci-dessous : elle devient la nouvelle référence de forme du lecteur {1}. Fermer : rien de plus n'est écrit.") }
                else { (T "La calibration rapide ne convient pas à cette disquette ({0}).`nCalibration complète en test fin ci-dessous : elle devient la nouvelle référence de forme du lecteur {1}. Fermer : rien de plus n'est écrit ; le profil décalé reste dans les champs --precomp.") }
    $intro = ($introFmt -f "$why", "$($cal.Drive)") + "`n`n"
    $script:CalFallbackAsk = @{ Swap = [bool]($toWrite -and -not $cal.Home) }
    # Carte Calibration de l Accueil : meme type de disquette (image de geometrie), et non l image de l onglet Ecriture
    if ($cal.Home) {
        Start-PrecompCalib -ForceFine -Intro $intro -Geom $cal.Geom -Heads ([bool]$cal.Slow)
        if ($script:Cal) { $script:HomeCalBusy = $true }
        return
    }
    if ($toWrite) { $script:AfterCalib = 'write' }
    Start-PrecompCalib -ForceFine -Intro $intro -LevelAfter:$toWrite
    if (-not $script:Cal -and $toWrite) { $script:AfterCalib = ''; Append-Log (T 'Écriture annulée : la calibration n''a pas été lancée.') }
}

function Stop-LevelBrandCurve($cal, $gd) {
    # 12.8 (S3, c4-design § 4.2) : garde de la passe 1 (Get-LevelBrandCurveGuard) : calibration rapide arretee, journal
    # J-M2, fenetre W-M2 (frmConfirm) : « Calibration rapide sur la reference » (nouvelle calibration rapide sans marque,
    # budget d ecritures complet), « Mesure complete de cette disquette » (avant une ecriture, hors restauration) ou Fermer
    # (calibration interrompue, ecriture annulee). $script:Cal est encore cette calibration
    Append-Log ((T "Cette disquette ne ressemble pas à la courbe de la marque « {0} » ({1}) : calibration arrêtée après la passe 1.") -f "$($gd.Brand)", "$($gd.Why)")
    $toWrite = ($script:AfterCalib -eq 'write')
    $disk = [bool]($toWrite -and $cal.CanDisk -and $cal.Slow -and $cal.Lr)
    $min = if ($disk) { Get-DiskMeasureMinutes ([int]$cal.MaxCyl + 1) ([string]$cal.Family -eq 'hd') } else { 0 }
    $txt = if ($disk) { (T "Cette disquette ne ressemble pas à la marque « {0} ». Choisissez une calibration rapide sur la référence du lecteur (1 à 2 min) ou une mesure complète de cette disquette (environ {1} min).") -f "$($gd.Brand)", "$min" }
           else { (T "Cette disquette ne ressemble pas à la marque « {0} ». Relancez une calibration rapide sur la référence du lecteur (1 à 2 min), sans la marque.") -f "$($gd.Brand)" }
    $txt += "`n`n" + ((T 'Raison : {0}.') -f "$($gd.Why)") + "`n" + (T "Fermer : la calibration est interrompue et rien de plus n'est écrit.")
    $cq = @{ Title = (T 'Calibration precomp'); Heading = (T 'Disquette différente de la marque'); Level = 'warn'; Picto = 'warn'; Text = $txt
             GoText = (T 'Calibration rapide sur la référence'); GoGlyph = 'Diagnostic' }
    if ($disk) { $cq.AltText = (T 'Mesure complète de cette disquette (environ {0} min)') -f "$min" }
    $pbWCal.Visible = $false
    if ($script:Restore) { $script:Restore.InCall = $true }
    try { [void](Show-AppConfirm @cq) } finally { if ($script:Restore) { $script:Restore.InCall = $false; $script:Restore.Idle = Get-Date } }
    $choice = [string]$script:ConfirmChoice
    if ($choice -eq 'go') {
        $script:Cal = $null
        Append-Log (T 'Calibration rapide relancée sur la référence du lecteur, sans marque.')
        $script:LevelNoBrand = $true
        Start-LevelCalib $cal.Lr -NoConfirm -NoFallback:(-not $cal.CanFallback) -Geom $cal.Geom
        $script:LevelNoBrand = $false
        if (-not $script:Cal -and $toWrite) {
            $script:AfterCalib = ''; Append-Log (T 'Écriture annulée : la calibration rapide n''a pas été lancée.')
            if ($script:Restore) { Stop-Restore (T 'calibration interrompue') }
        }
        return
    }
    if ($choice -eq 'alt' -and $disk) {
        # Marque non proposee : cette disquette ne ressemble pas a la courbe de cette marque, que la mesure remplacerait
        $script:Cal = $null
        $script:AfterCalib = ''
        Start-DiskMeasure $cal.Lr ''
        return
    }
    Stop-PrecompCalib
}

function Get-LevelBeforeWriteKind([string]$mode, [bool]$restore, [bool]$measure) {
    # 12.10 (relecture de la RC) : mesure de la disquette que fait Start-LevelBeforeWrite ($mode 'slow' ou 'fast' ;
    # $restore : restauration ; $measure : case « Mesurer la disquette » au test standard ou fin), decision commune a son
    # code et aux textes qui l annoncent (regles et ligne « Regles » du rapport de la restauration, 300 ; case de la mesure
    # au « Test rapide », 140) : 'content' (liste « Mesure » sur l image a ecrire, ecriture lente demandee par la case, hors
    # restauration ; repli au motif si l image ne s y prete pas, Test-ContentMeasurable), 'complete' (liste « Mesure »
    # complete, ecriture lente : « Test rapide » et restauration compris, case cochee ou non en restauration), sinon
    # 'quick' (calibration rapide au motif). Avant : regles et infobulles annoncaient la calibration rapide au « Test
    # rapide » et en restauration, ou la mesure complete est faite
    $lm = [string](Get-Setting 'levelBeforeWriteMode')
    if ($lm -eq 'content' -and $measure -and $mode -eq 'slow' -and -not $restore) { return 'content' }
    if ($lm -eq 'complete' -and $mode -eq 'slow') { return 'complete' }
    return 'quick'
}

function Start-LevelBeforeWrite([string]$mode, [switch]$Restore, [switch]$Measure) {
    # Ecriture depuis la Bibliotheque, le bouton ECRIRE (12.8, D5) ou la restauration avec « Test rapide » : niveau mesure
    # sur la disquette a ecrire. 12.8 (validation du 19/10) : sans reference utilisable, ecriture refusee (Bibliotheque et
    # ECRIRE ; 12.7 : calibration complete en test fin d abord, sur la disquette a ecrire) ; restauration : ecriture avec
    # la calibration existante, jamais refaite.
    # 12.7 point 5, Measure : mesure ajoutee a une ecriture lente par la case « Mesurer la disquette » (liste au test
    # standard ou fin) : sans reference utilisable, aucune calibration complete imposee, ecriture avec la courbe du lecteur
    # 12.8.1 (spec-1281.md § A.1) : liste « Mesure : sur l image a ecrire » (levelBeforeWriteMode = content), ecriture
    # lente avec la case « Mesurer la disquette » (Measure), hors restauration : mesure de la disquette sur le contenu de
    # l image (276) si l image et le contexte s y pretent (Test-ContentMeasurable) ; sinon ligne de journal, puis la suite
    # de la 12.8 (calibration rapide au motif, ou courbe du lecteur sans reference). Test rapide et restauration : mesure
    # au motif, ligne de journal plus bas
    $content = ((Get-Setting 'levelBeforeWriteMode') -eq 'content')
    # 12.10 (relecture de la RC) : mesure choisie par Get-LevelBeforeWriteKind, decision dont sont tires les textes qui
    # l annoncent (regles et rapport de la restauration, case de la mesure au « Test rapide »). 12.11 (L10, correction B1
    # du plan) : mesure faite, repli et refus decides par Get-LevelBeforeWritePlan, dont la ligne « Ce qui va se passer »
    # tire aussi son segment ; memes lignes de journal, dans le meme ordre, et memes appels
    $lp = Get-LevelBeforeWritePlan $mode ([bool]$Restore) ([bool]$Measure)
    $fam = $lp.Fam
    if ($lp.Kind -eq 'content') { Start-ContentMeasure $lp.Cm; return }
    if ($lp.Cm) { Append-Log ((T "Mesure sur l'image non faite ({0}) : calibration rapide au motif avant cette écriture.") -f "$($lp.Cm.Why)") }
    $lr = $lp.Lr
    if ($lr.Ok) {
        # 12.8 (S3, decision du 21/10/2026) : liste « Mesure : complète » de l onglet Ecriture (levelBeforeWriteMode) : mesure
        # complete de cette disquette avant une ecriture lente (une courbe par tete) ; ecriture rapide : calibration rapide,
        # avec une ligne de journal. 12.8 (S3-FLUX, decision 2) : aussi en restauration, copie secteur (Restore : seul appel,
        # Start-PresetWrite -LevelOnly ; une copie de flux n est jamais mesuree), ecriture lente toujours
        if ($lp.Kind -eq 'complete') {
            if ($Restore) { Append-Log (T "Restauration : disquette de destination mesurée sur tous ses cylindres (mesure complète de cette disquette, liste « Mesure » de l'onglet Écriture), la calibration du lecteur n'est pas refaite.") }
            Start-DiskMeasure $lr ([string]$script:LevelBrand); return
        }
        if ((Get-Setting 'levelBeforeWriteMode') -eq 'complete') { Append-Log (T "Mesure complète de cette disquette réservée à l'écriture lente (une courbe par tête) : calibration rapide avant cette écriture rapide.") }
        # 12.8.1 (decision 5) : avec « sur l image a ecrire », le Test rapide et la restauration gardent la mesure au motif
        if ($content -and -not $Measure) {
            if ($Restore) { Append-Log (T "Restauration : destination mesurée au motif (calibration rapide) ; la mesure sur l'image ne se fait pas en restauration.") }
            else { Append-Log (T "Test rapide : mesure au motif (calibration rapide) ; la mesure sur l'image ne se fait qu'en test standard ou fin, avec la case « Mesurer la disquette avant l'écriture lente ».") }
        }
        $script:AfterCalib = 'write'
        # 12.8 (S3-FLUX, F3R-FIX) : ligne exacte, sans « (test rapide) » : la mesure de la destination ne depend plus du test
        if ($Restore) { Append-Log (T 'Restauration : niveau et forme mesurés sur la disquette de destination (calibration rapide), la calibration du lecteur n''est pas refaite.') }
        Start-LevelCalib $lr -NoFallback:([bool]$Restore)
        if (-not $script:Cal) { $script:AfterCalib = ''; Append-Log (T 'Écriture annulée : la calibration rapide n''a pas été lancée.') }
        return
    }
    if ($Restore) {
        Append-Log ((T "Restauration : niveau non mesuré ({0}) : écriture avec la calibration existante.") -f "$($lr.Why)")
        if ($script:Restore) { $script:Restore.LevelNote = $lr.Why }
        Start-ImageWrite; return
    }
    if ($Measure) {
        # Arbitrage 16 : sans aucune courbe applicable (Get-FamilyCurves, tableau protege : pas de @() autour), le mode Auto
        # ecrit avec le profil d origine
        if ((Get-FamilyCurves $fam ($mode -eq 'slow')).Count -gt 0) { Append-Log ((T "Mesure de la disquette avant l'écriture non faite : {0}. Écriture avec la courbe du lecteur ; une calibration complète en test fin servira de référence aux prochaines mesures.") -f "$($lr.Why)") }
        else { Append-Log ((T "Mesure de la disquette avant l'écriture non faite : {0}. Écriture avec le profil d'origine ; une calibration complète en test fin servira de référence aux prochaines mesures.") -f "$($lr.Why)") }
        Start-ImageWrite; return
    }
    # Hors domaine : ecriture avec la courbe du lecteur, sauf si elle est plus courte que l image (gw appliquerait la valeur
    # de son dernier cylindre a tous les suivants) : refus, comme sans reference (12.11, L10 : Refuse faux de
    # Get-LevelBeforeWritePlan, reference hors domaine et non plus courte que l image)
    if (-not $lp.Refuse) {
        Append-Log ((T "Calibration rapide non applicable à cette image : {0}. Écriture avec la courbe du lecteur, sans mesure du niveau.") -f "$($lr.Why)")
        Start-ImageWrite; return
    }
    # 12.8 (decisions128.md, validations du 19/10) : aucune reference utilisable (aucune courbe de la famille, autre lecteur,
    # mesure sur le contenu d une image, reference trop courte...) : ecriture refusee, rien n est ecrit ni calibre sur la
    # disquette a ecrire. La reference se fait a part, sur une disquette sacrifiee, par la carte « Calibrer le lecteur » de
    # l Accueil ; Oui : Accueil affiche (Show-Tab, la carte y est). Premiere ligne du message : ligne de journal du refus
    # (Show-AppMessage ecrit le message au journal)
    $script:AfterCalib = ''
    $msg = ((T "Écriture refusée : le test rapide n'a pas de référence utilisable pour cette image ({0}). Rien n'a été écrit.") -f "$($lr.Why)") + "`n`n" +
           ((T "Le test rapide mesure la disquette à écrire à partir d'une calibration complète du lecteur {0}, faite au préalable sur une disquette sacrifiée du même type que la disquette à écrire. Calibrez d'abord le lecteur : carte « Calibrer le lecteur » de l'Accueil, avec une disquette sacrifiée.") -f "$($cmbDrive.Text)") + "`n`n" +
           (T "Afficher maintenant l'Accueil et sa carte « Calibrer le lecteur » ?")
    if ("$(Show-AppMessage $msg (T 'Calibration precomp') 'YesNo' 'Warning')" -eq 'Yes') { Show-Tab $tabH }
}

function Get-LevelBeforeWritePlan([string]$mode, [bool]$restore, [bool]$measure) {
    # 12.11 (L10, correction B1 du plan ; extraite de Start-LevelBeforeWrite sans changement de comportement) : mesure de
    # la disquette avant l ecriture de l image de l onglet, decision commune a Start-LevelBeforeWrite et a la ligne « Ce qui
    # va se passer » (Get-WritePlan, 145) ; aucune ligne de journal, aucune fenetre. Arguments de Start-LevelBeforeWrite
    # ($restore : son switch Restore ; restauration en cours lue en plus pour Get-LevelBeforeWriteKind, comme lui). Rend
    # @{ Kind ; Refuse ; Why ; Lr ; Cm ; Fam ; Lk } :
    #  - Kind 'content' (mesure sur l image, Cm de Test-ContentMeasurable), 'complete' (mesure complete de cette disquette),
    #    'quick' (calibration rapide au motif ; apres un repli de la mesure sur l image, Cm non vide et Why sa raison),
    #    'none' (ecriture sans mesure : restauration, case de la mesure cochee ou image hors domaine de la reference, Why
    #    la raison de Get-LevelRef) ;
    #  - Refuse : « Test rapide » sans reference utilisable (Kind 'none', Why) : ecriture refusee, rien n est ecrit ;
    #  - Lr : reference de Get-LevelRef ; Fam : famille de l image ; Lk : Get-LevelBeforeWriteKind.
    # Lit l image (Test-ContentMeasurable, Get-LevelRef) : la ligne la garde en memoire par signature (Get-WritePlanCached)
    $img = $txtWFile.Text
    $fam = Get-ImageFamily $img
    $nfc = Get-CalibCylinders $img $cmbWFmt.Text      # image secteur sans geometrie : cylindres du format choisi
    $r = @{ Kind = 'none'; Refuse = $false; Why = ''; Lr = $null; Cm = $null; Fam = $fam; Lk = '' }
    $r.Lk = Get-LevelBeforeWriteKind $mode ($restore -or [bool]$script:Restore) $measure
    if ($r.Lk -eq 'content') {
        $r.Cm = Test-ContentMeasurable $img $cmbWFmt.Text
        if ($r.Cm.Ok) { $r.Kind = 'content'; return $r }
        $r.Why = [string]$r.Cm.Why
    }
    $r.Lr = Get-LevelRef $fam ($mode -eq 'slow') $cmbDrive.Text $img $restore -NCyl $(if ($null -ne $nfc.NCyl) { [int]$nfc.NCyl } else { 0 })
    if ($r.Lr.Ok) { $r.Kind = $(if ($r.Lk -eq 'complete') { 'complete' } else { 'quick' }); return $r }
    $r.Why = [string]$r.Lr.Why
    if ($restore -or $measure) { return $r }
    if ($r.Lr.Class -eq 'domain' -and -not $r.Lr.Short) { return $r }
    $r.Refuse = $true
    return $r
}

function Start-LevelCalibButton {
    # Bouton « Calibrer » avec « Test rapide » : niveau de la disquette inseree, sans ecriture d image
    $chk = Test-CalibImage
    if (-not $chk) { return }
    # 12.10 (relecture de la RC) : lecteur cible avec effet sur l ecriture de l onglet (Get-TargetWriteInfo, celui de
    # Start-ImageWrite) : calibration rapide refusee, comme la mesure avant l ecriture (Start-WriteTabWrite) : elle relirait
    # avec le lecteur du bandeau, et l ecriture remet la courbe croisee dans les champs --precomp (ou est refusee sans
    # elle). Avant : faite, et annoncee « a n utiliser que pour cette disquette »
    $tw = Get-TargetWriteInfo $chk.Img $cmbWFmt.Text ([bool]$chkWSlow.Checked)
    if ($tw.Applies) { [void](Show-AppMessage ((T "Calibration rapide non faite pour le lecteur cible {0} : elle relirait avec le lecteur {1}, et l'écriture pour le lecteur cible n'utilise pas sa mesure (courbe croisée telle quelle, ou refus sans elle). Pour mesurer cette disquette avec le lecteur {1}, choisissez « (même lecteur) » dans la liste « Lecteur cible ».") -f "$($tw.Tgt)", "$($tw.Src)") (T 'Calibration precomp') 'OK' 'Information'); return }
    $lr = Get-LevelRef $chk.Family ([bool]$chkWSlow.Checked) $cmbDrive.Text $chk.Img $false -NCyl ([int]$chk.NCyl)
    if ($lr.Ok) { $script:AfterCalib = ''; Start-LevelCalib $lr; return }
    if ($lr.Class -eq 'domain' -and -not $lr.Short) {
        [void](Show-AppMessage ((T "Calibration rapide non applicable à cette image : {0}.") -f "$($lr.Why)") (T 'Calibration precomp') 'OK' 'Information'); return
    }
    # 12.8 (D3) : confirmation par frmConfirm, sans case : l avertissement de la calibration suit, avec sa confirmation
    $cq = @{ Title = (T 'Calibration precomp'); Heading = (T 'Calibration rapide impossible'); Level = 'info'; Picto = 'data'
             Text = ((T "Raison : {0}.`n`nLa calibration rapide reprend la forme d'une calibration complète du lecteur {1}. Lancez d'abord une calibration complète en test fin : elle devient la référence de forme du lecteur, reprise ensuite par chaque calibration rapide.") -f "$($lr.Why)", "$($cmbDrive.Text)")
             GoText = (T 'Calibration complète'); GoGlyph = 'Stopwatch' }
    if (Show-AppConfirm @cq) { $script:AfterCalib = ''; Start-PrecompCalib -ForceFine }
}

function Get-CurveLevelRecs($cv) {
    # Niveaux de la derniere calibration rapide faits sur cette courbe (meme date de reference, meme lecteur)
    if (-not $cv) { return ,@() }
    $key = @($script:CurveKeys | Where-Object { [object]::ReferenceEquals($script:PrecompCurves[$_], $cv) })
    if ($key.Count -eq 0) { return ,@() }
    $rs = @(@($script:LevelShifts.Values) | Where-Object { $_ -and $_.RefKey -eq $key[0] -and [string]$_.RefDate -eq [string]$cv.Date -and [string]$_.Drive -eq [string]$cv.Drive })
    if ($rs.Count -eq 0) { return ,@() }
    $latest = @($rs | Sort-Object { Get-CurveDate $_ } -Descending)[0].Date
    return ,@($rs | Where-Object { $_.Date -eq $latest } | Sort-Object { if ($null -eq $_.Head) { -1 } else { [int]$_.Head } })
}

function Set-CurveLevelData($cvs) {
    # Niveaux a superposer aux courbes affichees (index de la courbe -> enregistrements)
    $script:CurveLevel = @{}
    $i = 0
    foreach ($cv in @($cvs)) { $script:CurveLevel[$i] = Get-CurveLevelRecs $cv; $i++ }
}

function Get-CalibCylinders([string]$img, [string]$fmt) {
    # Cylindres d une image pour la calibration : lus dans l image (ADF, IPF, HFE) ; image secteur sans geometrie (IMG, ST,
    # DSK...) avec un format gw explicite de la table : cylindres de sa definition, 35 au moins comme la carte Calibration
    # de l Accueil (Get-FormatCalibInfo : une courbe de famille de 15 cylindres serait appliquee a toutes les images de 80) ;
    # sinon NCyl = $null (80 par defaut). Origine (Src) sans parentheses : la ligne de journal Cylindres de test (270) la met
    # deja entre parentheses (relecture du banc 1210, comme CylSrc de Start-CrossCalib)
    $n = Get-ImageCylinders $img
    if ($null -ne $n) { return @{ NCyl = [int]$n; Src = ((T "{0} cylindres d'après l'image") -f "$n") } }
    if ($fmt -and $fmt -ne '(auto)' -and $script:GwFormats.Contains($fmt)) {
        $d = [int]$script:GwFormats[$fmt].Cyls; $c = [math]::Max(35, $d)
        if ($c -ne $d) { return @{ NCyl = $c; Src = ((T "{0} cylindres pour le format {1} : {2} dans la définition de gw, {0} au moins pour la calibration") -f "$c", "$fmt", "$d") } }
        return @{ NCyl = $c; Src = ((T "{0} cylindres d'après le format {1}") -f "$c", "$fmt") }
    }
    return @{ NCyl = $null; Src = (T "80 cylindres par défaut, nombre non lisible dans l'image") }
}

function Test-CalibImage($Geom = $null) {
    # Controles communs a la calibration complete et a la calibration rapide (memes messages) ; $null si refus. Geom :
    # type de disquette de la carte Calibration de l Accueil (image de geometrie de New-CalibGeometry, sans format gw) a la
    # place de l image et du format de l onglet Ecriture. Format gw explicite de la table non calibrable (FM, GCR, codage
    # propre, secteurs durs, ED, 360 tr/min, cellule hors plage : Get-FormatCalibInfo) : refus. 12.7 : image haute densite
    # admise si elle est calibrable (famille hd, Get-HdCalibFamily).
    # 12.10 (relecture de la RC) : controles de l image et des reglages dans Get-CalibImageCheck (sans fenetre), dont
    # Start-CrossCalib (270) tire aussi l image annoncee par sa fenetre de choix ; message du refus affiche ici, comme avant
    # 12.10 (verification finale de la RC) : module d analyse SCP et gw.exe controles par Get-CalibEnvBlock, lu aussi par
    # Start-CrossCalib (270) avant sa fenetre de choix ; messages et icones du refus inchanges
    $eb = Get-CalibEnvBlock
    if ($eb) { [void](Show-AppMessage ([string]$eb.Why) ([string]$eb.Title) 'OK' ([string]$eb.Icon)); return $null }
    $c = Get-CalibImageCheck $Geom
    if (-not $c.Ok) { [void](Show-AppMessage ([string]$c.Why) (T 'Calibration precomp') 'OK' 'Warning'); return $null }
    return @{ Img = $c.Img; Family = $c.Family; NCyl = $c.NCyl; MaxCyl = $c.MaxCyl; CylSrc = $c.CylSrc; Label = $c.Label }
}

function Get-CalibEnvBlock {
    # 12.10 (verification finale de la RC) : installation qui refuse toute calibration : module d analyse SCP indisponible
    # (Add-Type) ou gw.exe introuvable. @{ Why ; Title ; Icon } du refus, $null sinon. Decision commune a Test-CalibImage
    # (memes messages qu avant) et a Start-CrossCalib (270 : refus avant la fenetre de choix ; avant, la fenetre s ouvrait
    # et le refus n arrivait qu apres « Continuer »)
    if (-not $script:ScpStatsOk) { return @{ Why = (T 'Calibration : module d''analyse SCP indisponible (Add-Type).'); Title = (T 'Calibration precomp'); Icon = 'Warning' } }
    if (-not (Test-Path -LiteralPath $script:GwExe)) { return @{ Why = ((T "gw.exe introuvable : {0}`n`nPlacez ce script dans le même répertoire que gw.exe.") -f "$($script:GwExe)"); Title = (T 'Erreur'); Icon = 'Error' } }
    return $null
}

function Get-CalibSettingBlock {
    # 12.10 (relecture de la RC, fix1) : reglages de l onglet Ecriture qui refusent toute calibration, quelle que soit
    # l image : « Secteurs durs » ou « TG43 » coches (l analyse de flux est calibree pour le MFM double densite). Message du
    # refus, '' sinon. Decision commune a Get-CalibImageCheck (refus de Test-CalibImage, a sa place dans l ordre des
    # controles) et a Start-CrossCalib (270 : refus avant la fenetre de choix, image de l onglet absente ou refusee
    # comprise ; avant, la fenetre s ouvrait et le refus n arrivait qu apres « Continuer »)
    if ($chkWHard.Checked -or $chkWTG43.Checked) { return (T 'Calibration non prise en charge avec secteurs durs ou lecteur 8 pouces (TG43) : l''analyse de flux est calibrée pour le MFM double densité.') }
    return ''
}

function Get-CalibImageCheck($Geom = $null) {
    # 12.10 (relecture de la RC) : controles de l image (ou du type de la carte de l Accueil, Geom) et des reglages de
    # Test-CalibImage, dans le meme ordre, sans fenetre (testable) : @{ Ok ; Why (message du refus, celui que
    # Test-CalibImage affiche) ; Scope ('image', ou 'setting' : secteurs durs ou lecteur 8 pouces, refus de toute
    # calibration quelle que soit l image) ; Img ; Family ; NCyl ; MaxCyl ; CylSrc ; Label }. Lu aussi par Start-CrossCalib
    # (270) : image de l onglet Ecriture annoncee et reprise par la calibration croisee seulement si elle est acceptee ici.
    # Avant : famille de Get-WriteTabFamily, une image FM, GCR, a codage propre ou hors des plages mesurables etait
    # annoncee, puis la calibration refusee apres « Continuer »
    $img = if ($Geom) { [string]$Geom.Img } else { $txtWFile.Text }
    $fmt = if ($Geom) { '' } else { $cmbWFmt.Text }
    if (-not $img -or -not (Test-Path -LiteralPath $img)) {
        return @{ Ok = $false; Why = (T 'Choisissez d''abord l''image à écrire : elle fixe la famille (cellule) et le nombre de cylindres de la calibration.'); Scope = 'image' }
    }
    $ext = [System.IO.Path]::GetExtension($img).ToLower()
    if (@('.scp', '.raw', '.kf', '.a2r', '.ctr') -contains $ext) {
        return @{ Ok = $false; Why = ((T "Calibration impossible sur un flux ({0}) : la calibration ne détermine la densité que d'une image à bits ou secteurs (ADF, IPF, HFE, IMG...).") -f "$ext"); Scope = 'image' }
    }
    # 12.10 (lot 1, revue2, R-6) : profil Manuel avec --precomp coche (Test-ManualPrecomp) : raison sans « l image est
    # ecrite sans precompensation »
    $fci = if ($fmt -and $fmt -ne '(auto)' -and $script:GwFormats.Contains($fmt)) { Get-FormatCalibInfo $fmt (Test-ManualPrecomp) } else { $null }
    # 12.10 (lot 1, B1) : image FM, GCR ou a codage propre sans format explicite de la table (format implicite de
    # l extension, en-tete HFE, IMD ou D88 : Get-ImageEncoding) : refus, comme un format explicite non calibrable
    if (-not $Geom -and -not $fci) {
        $ie = Get-ImageEncoding $img $fmt
        if ($ie.NonMfm) {
            # 12.10 (lot 1, revue2, R-6) : profil Manuel avec --precomp coche (Test-ManualPrecomp) : champ transmis tel quel a
            # l ecriture, texte sans « ecriture sans precompensation »
            $nm = if (Test-ManualPrecomp) { (T "Image {0} en codage {1} : pas de calibration (elle ne mesure que le MFM).") } else { (T "Image {0} en codage {1} : pas de calibration (elle ne mesure que le MFM), écriture sans précompensation.") }
            return @{ Ok = $false; Why = ($nm -f "$([System.IO.Path]::GetFileName($img))", "$($ie.Name)"); Scope = 'image' }
        }
    }
    $hd = Get-HighDensityReason $img $fmt
    # 12.7 : haute densite calibrable (famille hd) admise ; sinon refus, avec la raison du format s il est explicite
    if ($hd -and -not (Get-HdCalibFamily $img $fmt)) {
        $msg = if ($fci -and -not $fci.Cal) { (T "Calibration non prise en charge pour le format {0} : {1}.") -f "$fmt", "$($fci.Why)" }
               else { (T "Calibration non prise en charge pour cette image haute densité ({0}) : seule la haute densité MFM à 1 us par cellule et à 300 tr/min se calibre ; la très haute densité (ED), les codages propres et la haute densité à 360 tr/min ne se calibrent pas.") -f "$hd" }
        return @{ Ok = $false; Why = $msg; Scope = 'image' }
    }
    # 12.10 (relecture de la RC, fix1) : reglages qui refusent toute calibration : Get-CalibSettingBlock, decision commune
    # avec Start-CrossCalib (270, refus avant sa fenetre de choix quelle que soit l image)
    $sb = Get-CalibSettingBlock
    if ($sb) { return @{ Ok = $false; Why = $sb; Scope = 'setting' } }
    $oor = Get-CellOutOfRange $img
    if ($null -ne $oor) {
        return @{ Ok = $false; Why = ((T "Calibration non prise en charge : cellule de l'image de {0} ns, hors des plages mesurables (900 à 1 100 ns en haute densité, 1 700 à 2 300 ns en double densité).") -f "$oor"); Scope = 'image' }
    }
    if ($fci -and -not $fci.Cal) {
        return @{ Ok = $false; Why = ((T "Calibration non prise en charge pour le format {0} : {1}.") -f "$fmt", "$($fci.Why)"); Scope = 'image' }
    }
    $family = Get-ImageFamily $img $fmt
    $cc = Get-CalibCylinders $img $fmt
    $nCyl = $cc.NCyl
    $cylSrc = if ($Geom) { [string]$Geom.CylSrc } else { [string]$cc.Src }
    if ($null -eq $nCyl) { $nCyl = 80 }
    $nCyl = [math]::Max(2, [math]::Min(84, [int]$nCyl))
    $maxCyl = $nCyl - 1
    $label = if ($Geom) { [string]$Geom.Label } else { [System.IO.Path]::GetFileName($img) }
    return @{ Ok = $true; Why = ''; Scope = ''; Img = $img; Family = $family; NCyl = $nCyl; MaxCyl = $maxCyl; CylSrc = $cylSrc; Label = $label }
}
# ============================== FONCTIONS : CALIBRATION RAPIDE ADAPTATIVE ======

# 12.8 (lot 1c) : calibration rapide adaptative (LevelAlgo 'lvl2', variante prudente V3, c1-design.md § 3). Deroulement
# lvl1 inchange tant que la forme est conforme. Forme non conforme (declencheur A : bascule anticipee de la passe 1 ;
# declencheur B : forme non conforme a f = 1 en fin de passe 1 ou 2, confirmee a la passe 2 par les zeros a la pente de
# reference) : passe de mesure a une deuxieme precompensation (pente propre et vrai zero de chaque cylindre), ajustement
# niveau / echelle / pente (moindres carres ponderes, choix par validation croisee ; ecart isole nomme et ecarte, jamais
# absorbe ; residus peu lisses : reserve ; au-dela : refus), puis passe de verification sur les cylindres ajustes et 2
# cylindres de controle hors ajustement. Au plus 3 ecritures par piste. Get-CalibZero, Limit-CalibZero, Get-ResidualTol,
# LevelTauOk et LevelTauMax sont lus, jamais modifies. Reference executable : v128\c1\v3-prudent.py (meme calcul,
# memes decisions ; oracle sans interface : suite calib-lvl2). Aucun Add-Type : systemes 3 x 3 resolus en PowerShell.
# 12.8 corrigee (F3R, decisions du 21/10/2026, reference v128\c3\final\v3f.py, oracle impl128\f3rport\oracle\calib-f3r.ps1) :
# terme de centre hc ((c - 60)+ / 19)^2 ajuste sur les controles a la passe de verification (Get-LevelCenterEval) ou
# repris d un refus de la passe de mesure (e3, Get-LevelCenterRescue) ; controle juge par la corde de ses deux ecritures
# (e1) ; courbe adaptee gardee avec reserve apres un refus par un controle (e2) ; derive corrigee avant le plafond (e4),
# gardee et niveau dit verifie dans la tolerance par cylindre (Bk) ; plafond par disquette, 12.11 : Get-DiskCapNs
# (Get-LevelAdaptHard) ; libelle neutre de la fatigue pour une forme non conforme ; reserve de controle ou de centre
# jamais memorisee pour la marque. Au plus 3 passes et 3 ecritures par piste ; disquettes habituelles inchangees.
# F3R-FIX (21/10/2026, reference alignee v128\c3\final2\v3f.py, oracle impl128\f3rfix\oracle\calib-f3r.ps1) : cylindres
# Clip hors du declenchement du plafond par disquette et qui le suivent quand il est porte au-dela de CalHardNs ; seuil
# max(400, CalHardNs) ; controle neuf au plus au dernier cylindre de l image. S3-FLUX (decision 3 du 21/10/2026) : borne
# precompMaxNs reglee sous 400 ns respectee, sans plafond par disquette.

function New-LevelShape($ref) {
    # Colonnes du modele de forme d une tete, relatives a sa reference : a (niveau), s (echelle centree sur la moyenne
    # RBar de la reference), b (pente du premier au dernier cylindre, centree)
    $vals = [double[]]@(@($ref) | ForEach-Object { [double]$_ })
    $sum = 0.0; foreach ($x in $vals) { $sum += $x }
    return @{ V = $vals; N = $vals.Count; RBar = $sum / $vals.Count }
}

function Get-LevelShapeRow($sh, [string[]]$names, [int]$c) {
    # 12.8 (F3R) : colonne hc, terme de centre ((c - LevelCenterC0)+ / (n - 1 - LevelCenterC0))^2, 0 jusqu a c60 et 1 au
    # dernier cylindre ; b (pente) explicite
    $row = New-Object double[] $names.Count
    for ($i = 0; $i -lt $names.Count; $i++) {
        if ($names[$i] -eq 'a') { $row[$i] = 1.0 }
        elseif ($names[$i] -eq 's') { $row[$i] = [double]$sh.V[$c] - [double]$sh.RBar }
        elseif ($names[$i] -eq 'hc') { $t = [math]::Max(0.0, $c - [double]$script:LevelCenterC0) / [double]($sh.N - 1 - $script:LevelCenterC0); $row[$i] = [math]::Pow($t, 2) }
        else { $row[$i] = ($c - ($sh.N - 1) / 2.0) / [double]($sh.N - 1) }
    }
    return ,$row
}

function Invoke-LevelSolve($A, $y) {
    # Resout A x = y (petit systeme, Gauss-Jordan a pivot partiel, comme v3-prudent.py) ; $null si singulier
    $n = $A.Count
    $M = New-Object 'object[]' $n
    for ($i = 0; $i -lt $n; $i++) { $r = New-Object double[] ($n + 1); for ($j = 0; $j -lt $n; $j++) { $r[$j] = [double]$A[$i][$j] }; $r[$n] = [double]$y[$i]; $M[$i] = $r }
    for ($col = 0; $col -lt $n; $col++) {
        $piv = $col; $best = [math]::Abs($M[$col][$col])
        for ($r = $col + 1; $r -lt $n; $r++) { if ([math]::Abs($M[$r][$col]) -gt $best) { $best = [math]::Abs($M[$r][$col]); $piv = $r } }
        if ($best -lt 1e-12) { return $null }
        $tmp = $M[$col]; $M[$col] = $M[$piv]; $M[$piv] = $tmp
        for ($r = 0; $r -lt $n; $r++) {
            if ($r -eq $col) { continue }
            $f = $M[$r][$col] / $M[$col][$col]
            for ($k = $col; $k -le $n; $k++) { $M[$r][$k] -= $f * $M[$col][$k] }
        }
    }
    $x = New-Object double[] $n
    for ($i = 0; $i -lt $n; $i++) { $x[$i] = $M[$i][$n] / $M[$i][$i] }
    return ,$x
}

function Get-LevelInverse($A) {
    $n = $A.Count
    $cols = @()
    for ($j = 0; $j -lt $n; $j++) {
        $e = New-Object double[] $n; $e[$j] = 1.0
        $x = Invoke-LevelSolve $A $e
        if ($null -eq $x) { return $null }
        $cols += ,$x
    }
    $inv = New-Object 'object[]' $n
    for ($i = 0; $i -lt $n; $i++) { $r = New-Object double[] $n; for ($j = 0; $j -lt $n; $j++) { $r[$j] = $cols[$j][$i] }; $inv[$i] = $r }
    return ,$inv
}

function Get-LevelWls($sh, [string[]]$names, [int[]]$cs, $d, $sig) {
    # Moindres carres ponderes (poids 1 / (sig^2 + LevelShapeFloor^2)) des ecarts d(c) a la reference : coefficients,
    # covariance (echelle max(1, chi2 / ddl)), residus, ecart de forme residuel tau ; $null si sous-determine ou singulier
    $p = $names.Count; $n = $cs.Count
    if ($n -lt $p) { return $null }
    $t02 = [math]::Pow([double]$script:LevelShapeFloor, 2)
    $w = @{}; foreach ($c in $cs) { $w[$c] = 1.0 / ([math]::Pow([double]$sig[$c], 2) + $t02) }
    $A = New-Object 'object[]' $p; for ($i = 0; $i -lt $p; $i++) { $A[$i] = New-Object double[] $p }
    $y = New-Object double[] $p
    foreach ($c in $cs) {
        $x = Get-LevelShapeRow $sh $names $c
        for ($i = 0; $i -lt $p; $i++) {
            $y[$i] += $w[$c] * $x[$i] * [double]$d[$c]
            for ($j = 0; $j -lt $p; $j++) { $A[$i][$j] += $w[$c] * $x[$i] * $x[$j] }
        }
    }
    $beta = Invoke-LevelSolve $A $y
    $inv = Get-LevelInverse $A
    if ($null -eq $beta -or $null -eq $inv) { return $null }
    $res = @{}
    foreach ($c in $cs) { $x = Get-LevelShapeRow $sh $names $c; $s = 0.0; for ($i = 0; $i -lt $p; $i++) { $s += $beta[$i] * $x[$i] }; $res[$c] = [double]$d[$c] - $s }
    $dof = $n - $p
    $chi = 0.0; foreach ($c in $cs) { $chi += $w[$c] * [math]::Pow($res[$c], 2) }
    $scale = if ($dof -gt 0) { [math]::Max(1.0, $chi / $dof) } else { 1.0 }
    $cov = New-Object 'object[]' $p
    for ($i = 0; $i -lt $p; $i++) { $r = New-Object double[] $p; for ($j = 0; $j -lt $p; $j++) { $r[$j] = $inv[$i][$j] * $scale }; $cov[$i] = $r }
    $ss = 0.0; foreach ($c in $cs) { $ss += [math]::Pow($res[$c], 2) }
    $ms = 0.0; foreach ($c in $cs) { $ms += [math]::Pow([double]$sig[$c], 2) }
    $tau = if ($dof -gt 0) { [math]::Sqrt([math]::Max(0.0, $ss / $dof - $ms / $n)) } else { 0.0 }
    $coef = @{}; for ($i = 0; $i -lt $p; $i++) { $coef[$names[$i]] = $beta[$i] }
    return @{ Names = $names; Coef = $coef; Beta = $beta; Cov = $cov; Res = $res; Cs = $cs; Tau = $tau; W = $w; N = $n; P = $p }
}

function Get-LevelPredict($sh, $fit, [int]$c) {
    # Valeur du modele au cylindre c (ecart a la reference) et son ecart-type
    $x = Get-LevelShapeRow $sh ([string[]]$fit.Names) $c
    $v = 0.0; for ($i = 0; $i -lt $x.Count; $i++) { $v += $fit.Beta[$i] * $x[$i] }
    $var = 0.0
    for ($i = 0; $i -lt $x.Count; $i++) { for ($j = 0; $j -lt $x.Count; $j++) { $var += $x[$i] * $fit.Cov[$i][$j] * $x[$j] } }
    return ,@($v, [math]::Sqrt([math]::Max(0.0, $var)))
}

function Get-LevelLoo($sh, [string[]]$names, [int[]]$cs, $d, $sig) {
    # Validation croisee, un cylindre retire : residu de prevision et son ecart-type ; $null si un ajustement manque
    $t02 = [math]::Pow([double]$script:LevelShapeFloor, 2)
    $out = @{}
    foreach ($c in $cs) {
        $rest = [int[]]@($cs | Where-Object { $_ -ne $c })
        $f = Get-LevelWls $sh $names $rest $d $sig
        if (-not $f) { return $null }
        $pr = Get-LevelPredict $sh $f $c
        $out[$c] = @{ R = [double]$d[$c] - $pr[0]; Sd = [math]::Sqrt([math]::Pow([double]$sig[$c], 2) + $t02 + [math]::Pow($pr[1], 2)) }
    }
    return $out
}

function Get-LevelMinFit([int]$p) {
    if ($p -eq 1) { return 3 }
    if ($p -eq 2) { return 5 }
    return [int]$script:LevelAdaptMinFit
}

function Select-LevelModel($sh, [int[]]$cs, $d, $sig) {
    # Choix du modele M0 {a}, Ms {a,s}, Mb {a,b}, Msb {a,s,b} : validation croisee ponderee (PRESS) penalisee par terme de
    # forme ; terme de forme retenu au-dela de LevelAdaptCoefZ erreurs-types ; modele admissible si aucun residu ne depasse
    # max(CalDevNs ; 4 et.). Renvoie @{ Best ; Cand } ou $null
    $models = @(@('M0', @('a')), @('Ms', @('a', 's')), @('Mb', @('a', 'b')), @('Msb', @('a', 's', 'b')))
    $cand = @()
    foreach ($m in $models) {
        $name = [string]$m[0]; $names = [string[]]@($m[1])
        if ($cs.Count -lt (Get-LevelMinFit $names.Count)) { continue }
        $f = Get-LevelWls $sh $names $cs $d $sig
        if (-not $f) { continue }
        $lv = Get-LevelLoo $sh $names $cs $d $sig
        if (-not $lv) { continue }
        $press = 0.0; foreach ($c in $cs) { $press += $f.W[$c] * [math]::Pow($lv[$c].R, 2) }
        $signif = $true
        for ($i = 0; $i -lt $names.Count; $i++) {
            if ($names[$i] -eq 'a') { continue }
            $se = [math]::Sqrt([math]::Max(1e-12, $f.Cov[$i][$i]))
            if ([math]::Abs($f.Beta[$i]) -lt $script:LevelAdaptCoefZ * $se) { $signif = $false }
        }
        $admit = $true; foreach ($c in $cs) { if ([math]::Abs($f.Res[$c]) -gt [math]::Max([double]$script:CalDevNs, 4.0 * [double]$sig[$c])) { $admit = $false } }
        $cand += ,@{ Name = $name; Fit = $f; Loo = $lv; Press = $press; Score = $press * (1.0 + $script:LevelAdaptParsimony * ($names.Count - 1)); Signif = $signif; Admit = $admit }
    }
    $ok = @($cand | Where-Object { $_.Signif -or $_.Name -eq 'M0' })
    if (@($ok | Where-Object { $_.Admit }).Count -gt 0) { $ok = @($ok | Where-Object { $_.Admit }) }
    if ($ok.Count -eq 0) { return $null }
    $best = $ok[0]; foreach ($x in $ok) { if ($x.Score -lt $best.Score) { $best = $x } }
    return @{ Best = $best; Cand = $cand }
}

function Get-LevelOwnSlope($pts) {
    # Pente propre (decalage par ns ecrit) entre les deux valeurs ecrites extremes, et leur ecart ; $null sous 2 mesures
    if (-not $pts) { return $null }
    $xs = @($pts.Keys | ForEach-Object { [int]$_ } | Sort-Object)
    if ($xs.Count -lt 2) { return $null }
    return @{ A = ([double]$pts[$xs[-1]].Shift - [double]$pts[$xs[0]].Shift) / [double]($xs[-1] - $xs[0]); Span = $xs[-1] - $xs[0] }
}

function Get-LevelNearest($pts) {
    # Valeur ecrite dont le decalage est le plus proche de zero (premiere dans l ordre croissant en cas d egalite)
    $best = $null; $bv = 0.0
    foreach ($x in @($pts.Keys | ForEach-Object { [int]$_ } | Sort-Object)) { $a = [math]::Abs([double]$pts[$x].Shift); if ($null -eq $best -or $a -lt $bv) { $best = $x; $bv = $a } }
    return $best
}

function Get-LevelAdaptZero($pts, [double]$k) {
    # Zero d un cylindre : Get-CalibZero (inchange) si les valeurs ecrites sont ecartees d au moins LevelAdaptDeltaMin ;
    # sinon point le plus proche du zero et pente donnee (une petite base rend la pente propre trop bruitee)
    if (-not $pts) { return $null }
    $xs = @($pts.Keys | ForEach-Object { [int]$_ } | Sort-Object)
    if ($xs.Count -eq 0) { return $null }
    if ($xs.Count -ge 2 -and ($xs[-1] - $xs[0]) -ge $script:LevelAdaptDeltaMin) { return (Get-CalibZero $pts (-$k)) }
    $x = Get-LevelNearest $pts
    return (Get-LevelZero @{ $x = $pts[$x] } $k)
}

function Get-LevelFitCyls($u) {
    # Cylindres d ajustement : cylindres de niveau et temoins de marche (les cylindres de controle en sont exclus). 12.8
    # (F3R, e3) : plus les controles integres a l ajustement par une reprise avec un terme de centre (CtlFit)
    return ,[int[]]@(@(@($u.LCyls) + @($u.Wit) + @($u.CtlFit)) | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_ } | Sort-Object -Unique)
}

function Get-LevelCtlCyls($units, [int]$maxCyl) {
    # Cylindres de controle hors ajustement, communs aux deux tetes : mesures fiables de la reference (memes regles que
    # Get-LevelCands, sans les bornes de 20 a 260 ns), hors cylindres de niveau, temoins et leurs voisins ; le premier dans
    # LevelAdaptCtlLo..(dernier - 4), au plus loin des cylindres de niveau et temoins, le second en bout de face (dernier - 1,
    # dernier, dernier - 2). Dernier : fin de la reference, au plus le dernier cylindre de l image (MaxCyl)
    # 12.8 (FIX1C, constat 1) : valeurs de la reference du lecteur (V0), jamais du point de depart d une marque (V') : un
    # seul choix, celui que l avertissement annonce (c1-design.md § 3.2 : controles choisis avant le point de depart)
    $us = @($units)
    if ($us.Count -eq 0) { return ,[int[]]@() }
    $last = [int](@($us | ForEach-Object { @($_.V).Count } | Measure-Object -Minimum).Minimum) - 1
    if ($maxCyl -ge 0) { $last = [math]::Min($last, $maxCyl) }
    $taken = @{}
    foreach ($u in $us) { foreach ($c in @(@($u.LCyls) + @($u.Wit))) { $taken[[int]$c] = $true } }
    $hard = [double]$script:CalHardNs
    $okc = {
        param([int]$c)
        if ($taken.ContainsKey($c) -or $taken.ContainsKey($c - 1) -or $taken.ContainsKey($c + 1)) { return $false }
        foreach ($u in $us) {
            $cv = $u.Cv
            $cyls = @(@($cv.Cyls) | ForEach-Object { [int]$_ })
            $i = -1; for ($q = 0; $q -lt $cyls.Count; $q++) { if ($cyls[$q] -eq $c) { $i = $q; break } }
            if ($i -lt 0) { return $false }
            if ($cv.Kinds -and $i -lt @($cv.Kinds).Count -and [string]$cv.Kinds[$i] -ne 'interp') { return $false }
            if (Test-CurvePointFlag $cv $i) { return $false }
            $vc = if ($null -ne $u.V0) { [double]$u.V0[$c] } else { [double]$u.V[$c] }
            if ($vc -le 5 -or $vc -ge $hard - 15) { return $false }
            foreach ($b in @(@($cv.Breaks) | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_ })) { if ([math]::Abs($c - $b) -le 1 -or [math]::Abs($c - ($b + 1)) -le 1) { return $false } }
        }
        return $true
    }
    $out = @()
    $end = @(@(($last - 1), $last, ($last - 2)) | Where-Object { $_ -ge 0 -and (& $okc $_) })
    $mid = @(); for ($c = [int]$script:LevelAdaptCtlLo; $c -lt $last - 3; $c++) { if (& $okc $c) { $mid += $c } }
    if ($mid.Count -gt 0) {
        $best = $null; $bd = -1
        foreach ($c in $mid) {
            $dm = [int]::MaxValue; foreach ($t in @($taken.Keys)) { $dt = [math]::Abs($c - [int]$t); if ($dt -lt $dm) { $dm = $dt } }
            if ($dm -gt $bd -or ($dm -eq $bd -and $c -gt $best)) { $bd = $dm; $best = $c }
        }
        $out += $best
    }
    if ($end.Count -gt 0) { $out += $end[0] }
    $out = @($out | Select-Object -First ([int]$script:LevelAdaptCtlCyls))
    return ,[int[]]@($out | Sort-Object)
}

function Get-LevelKrefEstimate($u) {
    # Estimation du niveau a la pente de reference sur le point le plus proche du zero de chaque cylindre : une derive
    # entre deux passes proches n y cree pas de forme fictive (la pente propre sur 4 a 20 ns l amplifierait). Meme forme
    # que Get-LevelEstimate pour Test-LevelShape
    $ds = @{}; $sg = @{}
    foreach ($c in @($u.LCyls)) {
        $pts = $u.Results[[int]$c]
        if (-not $pts -or $pts.Count -eq 0) { continue }
        $x = Get-LevelNearest $pts
        $z = Get-LevelZero @{ $x = $pts[$x] } ([double]$u.KRef)
        if ($z -and $z.Kind -ne 'cap') { $ds[[int]$c] = [double]$z.Est - [double]$u.V[[int]$c]; $sg[[int]$c] = [double]$z.Sig }
    }
    $e = Get-LevelStats $ds $sg
    $e.Wit = @{}
    foreach ($c in @($u.Wit)) {
        $pts = $u.Results[[int]$c]
        if (-not $pts -or $pts.Count -eq 0) { continue }
        $x = Get-LevelNearest $pts
        $z = Get-LevelZero @{ $x = $pts[$x] } ([double]$u.KRef)
        if ($z -and $z.Kind -ne 'cap') { $e.Wit[[int]$c] = @{ D = [double]$z.Est - [double]$u.V[[int]$c]; Sig = [double]$z.Sig; Z = [double]$z.Est } }
    }
    return $e
}

function Test-LevelAdaptEligible($cal, $u, $e) {
    # Garde-fous du declenchement (c1-design.md § 3.2, G6). Renvoie @{ Ok ; Why ; G6 } (G6 : courbe commune ou temoin du
    # plafond, comportement lvl1 avec une reserve)
    if ($null -eq $u.Head) { return @{ Ok = $false; G6 = $true; Why = (T "courbe commune aux deux faces : l'écriture lente adapte la courbe de chaque face") } }
    if ($null -ne $u.Probe) { return @{ Ok = $false; G6 = $true; Why = ((T 'référence plafonnée vers le centre (témoin c{0})') -f "$($u.Probe)") } }
    if ($cal.SurfGross) { return @{ Ok = $false; G6 = $false; Why = (T 'défaut grossier de surface à la première passe') } }
    if ($cal.Surf -and $cal.Surf.Faces -and $cal.Surf.Faces[[int]$u.Head] -and $cal.Surf.Faces[[int]$u.Head].Defective) { return @{ Ok = $false; G6 = $false; Why = (T 'disquette douteuse sur cette face à la première passe') } }
    if ($u.Fail -or $u.Sat -or $u.Low -or $u.Few -or [int]$e.N -lt 4 -or (@($e.Capped).Count + @($e.Floored).Count) -gt 2) { return @{ Ok = $false; G6 = $false; Why = (T 'trop peu de cylindres mesurables') } }
    foreach ($c in @(@($u.LCyls) + @($u.Wit))) { if ([int]$u.Writes[[int]$c] -gt 2) { return @{ Ok = $false; G6 = $false; Why = (T "budget d'écritures atteint") } } }
    return @{ Ok = $true; G6 = $false; Why = '' }
}

function Add-LevelCalCyls($cal, [int[]]$cyls) {
    # Cylindres de controle ajoutes aux cylindres lus de la calibration (Invoke-CalibAnalysis ne lit que $cal.Cyls)
    $all = @{}; foreach ($c in @($cal.Cyls)) { $all[[int]$c] = $true }
    foreach ($c in $cyls) { $all[[int]$c] = $true }
    $cal.Cyls = [int[]]@($all.Keys | Sort-Object)
}

function Set-LevelAdaptTargets($cal, $u, $e) {
    # Passe de mesure (declenchement a la passe 1) : chaque cylindre de niveau et temoin ecrit a w1 + LevelAdaptOvershoot
    # x (zero de la passe 1 - w1), a LevelAdaptDeltaMin au moins de w1, borne a 0..CalHardNs ; cylindres de controle a la
    # prediction d un ajustement des zeros de la passe 1 a la pente de reference (placement seulement)
    $t = @{}; $mx = [int]$script:CalHardNs; $dmin = [int]$script:LevelAdaptDeltaMin
    foreach ($c in (Get-LevelFitCyls $u)) {
        $pts = $u.Results[$c]
        if (-not $pts -or $pts.Count -eq 0) { continue }
        $w1 = [int](@($pts.Keys | ForEach-Object { [int]$_ } | Measure-Object -Maximum).Maximum)
        $z = Get-LevelZero $pts ([double]$u.KRef)
        $z1 = if ($z) { [double]$z.Est } else { [double]$w1 }
        $dz = ($z1 - $w1) * [double]$script:LevelAdaptOvershoot
        $sg = [math]::Sign($dz); if ($sg -eq 0) { $sg = $(if ([double]$pts[$w1].Shift -ge 0) { 1 } else { -1 }) }
        $w2 = if ([math]::Abs($dz) -ge $dmin) { [int][math]::Round($w1 + $dz) } else { $w1 + $sg * $dmin }
        if ($w2 -gt $mx -or $w2 -lt 0) {
            $w2 = [math]::Max(0, [math]::Min($mx, $w2))
            if ([math]::Abs($w2 - $w1) -lt $dmin) { $w2 = $w1 - $sg * $dmin }
        }
        $t[$c] = [int][math]::Max(0, [math]::Min($mx, $w2))
    }
    # Controles : modele ajuste sur les zeros de la passe 1 (pente de reference), sans garde-fou
    $sh = $u.ShapeV; $cs = @(); $d = @{}; $sgm = @{}
    foreach ($c in (Get-LevelFitCyls $u)) {
        $z = Get-LevelZero $u.Results[$c] ([double]$u.KRef)
        if ($z -and $z.Kind -ne 'cap') { $cs += $c; $d[$c] = [double]$z.Est - $sh.V[$c]; $sgm[$c] = [double]$z.Sig }
    }
    $sel = if ($cs.Count -ge 3) { Select-LevelModel $sh ([int[]]$cs) $d $sgm } else { $null }
    foreach ($x in @($u.Ctl)) {
        $v = if ($sel) { (Get-LevelPredict $sh $sel.Best.Fit ([int]$x))[0] } elseif (-not [double]::IsNaN([double]$e.Delta)) { [double]$e.Delta } else { [double]$u.D }
        $t[[int]$x] = [int][math]::Max(0, [math]::Min($mx, [math]::Round($sh.V[[int]$x] + $v)))
    }
    $u.LTarget = $t
    $u.Mode = 'meas'
    Add-LevelCalCyls $cal ([int[]]@($u.Ctl))
    $cal.TotalPasses = [math]::Max([int]$cal.TotalPasses, [int]$script:LevelMaxPasses)
}

function Format-LevelSigned([double]$x) { return ('{0:+0;-0;0}' -f [math]::Round($x, 0)) }

function Get-LevelAdaptFit($u) {
    # Zeros de toutes les passes, pente propre, choix et controle de la forme (analyse_fit de v3-prudent.py). Renvoie
    # @{ Ok ; Why ('nowrite' : pente nulle sur la base large) ; KPool ; Ks ; Named ; Model ; Fit ; Cs ; Eff ; Loo ; M0 ;
    # Reserve ; Zs ; D ; Sig ; Cap ; BadK ; Iso }
    $sh = $u.ShapeV; $mx = [int]$script:CalHardNs; $kref = [double]$u.KRef
    $klo = [double]$script:LevelAdaptKRatioLo * $kref; $khi = [double]$script:LevelAdaptKRatioHi * $kref
    $fc = Get-LevelFitCyls $u
    $ks = @{}; $kOrder = @()
    foreach ($c in $fc) {
        $os = Get-LevelOwnSlope $u.Results[$c]
        if ($os -and $os.Span -ge $script:LevelAdaptDeltaMin) { $ks[$c] = -[double]$os.A; $kOrder += $c }
    }
    $kv = @($kOrder | ForEach-Object { $ks[$_] } | Where-Object { $klo -le $_ -and $_ -le $khi })
    $kpool = if ($kv.Count -gt 0) { [math]::Max($klo, [math]::Min($khi, [double](Get-Median $kv))) } else { $kref }
    $out = @{ Ok = $false; Why = ''; WhyCode = 'other'; KPool = $kpool; Ks = $ks; KOrder = $kOrder; Named = @{}; Model = $null; Excl = @(); Reserve = @(); Iso = @{}; Zs = @{}; D = @{}; Sig = @{}; Cap = @(); BadK = @() }
    # Pente nulle : meme critere que Invoke-LevelStep, sur la base large de la passe de mesure
    $sl = @($kOrder | ForEach-Object { -$ks[$_] })
    if ($sl.Count -ge 3 -and [double](Get-Median $sl) -ge [math]::Max(-0.2, -0.5 * $kref) -and $kref * $script:LevelAdaptDeltaMin -ge 4.0) { $out.Why = 'nowrite'; return $out }
    $badK = @($kOrder | Where-Object { -not ($klo -le $ks[$_] -and $ks[$_] -le $khi) } | Sort-Object)
    $dOrder = @()
    foreach ($c in $fc) {
        $kk = if ($ks.ContainsKey($c) -and $badK -notcontains $c) { $ks[$c] } else { $kpool }
        $z = Get-LevelAdaptZero $u.Results[$c] $kk
        if (-not $z) { continue }
        $out.Zs[$c] = $z
        if ($z.Kind -eq 'cap') { $out.Cap += $c; continue }
        $out.D[$c] = [double]$z.Est - $sh.V[$c]; $out.Sig[$c] = [double]$z.Sig; $dOrder += $c
    }
    $out.BadK = $badK
    $d = $out.D; $sg = $out.Sig
    if ($badK.Count -ge 2) {
        $out.Why = (T 'pente propre invraisemblable aux cylindres {0} ({1} fois la référence)') -f (Format-CylList ([int[]]$badK)), ((@($badK | ForEach-Object { Format-UiNum ([math]::Round($ks[$_] / $kref, 1)) '0.#' })) -join ', ')
        return $out
    }
    foreach ($c in $badK) { $out.Named[$c] = (T 'pente propre invraisemblable ({0} fois la référence)') -f (Format-UiNum ([math]::Round($ks[$c] / $kref, 1)) '0.#') }
    $pre = @($fc | Where-Object { $u.Named -and $u.Named.ContainsKey($_) })
    $cs = @($dOrder | Where-Object { $badK -notcontains $_ -and $pre -notcontains $_ })
    if ($pre.Count + $badK.Count -ge 2) {
        $out.WhyCode = 'scatter'
        $out.Why = (T 'écarts dispersés ({0} cylindres signalés : {1})') -f "$($pre.Count + $badK.Count)", (Format-CylList ([int[]]@(@($pre) + @($badK))))
        return $out
    }
    $nexc = $pre.Count + $badK.Count
    if ($out.Cap.Count -gt 2) { $out.Why = (T 'besoin hors de 0 à {0} ns à {1} cylindres mesurés') -f "$mx", "$($out.Cap.Count)"; return $out }
    if ($cs.Count -lt $script:LevelAdaptMinFit) { $out.Why = (T 'trop peu de cylindres mesurables ({0})') -f "$($cs.Count)"; return $out }
    $sel = Select-LevelModel $sh ([int[]]$cs) $d $sg
    if (-not $sel) { $out.Why = (T 'forme impossible à ajuster'); return $out }
    $best = $sel.Best
    # Ecart isole en validation croisee : un seul, nomme et ecarte, puis nouveau choix ; deux ou plus : dispersion
    $outl = {
        param($b)
        $o = @()
        foreach ($c in @($b.Fit.Cs)) {
            $lv = $b.Loo[$c]
            $thr = [math]::Min([math]::Max([double]$script:LevelAdaptLooFloor, [double]$script:LevelAdaptLooK * $lv.Sd), [double]$script:LevelAdaptLooCap)
            if ([math]::Abs($lv.R) -gt $thr) { $o += ,@{ Q = [math]::Abs($lv.R) / $thr; C = [int]$c; R = [double]$lv.R; Thr = $thr } }
        }
        return ,@($o | Sort-Object -Property @{ Expression = { $_.Q }; Descending = $true }, @{ Expression = { $_.C }; Descending = $true })
    }
    $o = & $outl $best
    if ($o.Count -gt 0 -and $nexc -ge 1) {
        $out.WhyCode = 'scatter'
        $out.Why = (T 'écarts dispersés ({0} signalé, c{1} hors de la forme ajustée)') -f (Format-CylList ([int[]]@(@($pre) + @($badK)))), "$($o[0].C)"
        $out.Named[$o[0].C] = (T 'écart dispersé')
        return $out
    }
    if ($o.Count -gt 0) {
        $c0 = $o[0].C
        $cs2 = @($cs | Where-Object { $_ -ne $c0 })
        if ($cs2.Count -lt $script:LevelAdaptMinFit) {
            $out.WhyCode = 'iso'
            $out.Why = (T 'écart isolé à c{0} et trop peu de cylindres restants') -f "$c0"
            $out.Named[$c0] = (T 'écart isolé'); $out.Iso[$c0] = $o[0].R
            return $out
        }
        $sel2 = Select-LevelModel $sh ([int[]]$cs2) $d $sg
        if ($sel2) { $o2 = & $outl $sel2.Best } else { $o2 = @(@{ C = -1 }) }
        if ($o2.Count -gt 0) {
            $oc = @($o2 | Where-Object { $_.C -ge 0 } | ForEach-Object { $_.C })
            $out.WhyCode = 'scatter'
            $out.Why = (T 'écarts dispersés ({0} cylindres hors de la forme ajustée : {1})') -f "$(1 + $o2.Count)", (Format-CylList ([int[]]@(@($c0) + @($oc))))
            $out.Named[$c0] = (T 'écart isolé')
            foreach ($x in $oc) { $out.Named[$x] = (T 'écart dispersé') }
            return $out
        }
        $out.Iso[$c0] = $o[0].R; $out.Named[$c0] = (T 'écart isolé'); $out.Excl += $c0
        $best = $sel2.Best; $sel = $sel2
        $cs = $cs2
    }
    $f = $best.Fit
    $out.Cand = @($sel.Cand | ForEach-Object { "$($_.Name):$($_.Press):$($_.Signif)" })
    if ($f.Tau -gt [double]$script:LevelTauMax) {
        $out.WhyCode = 'tau'
        $out.Why = (T 'écart de forme résiduel {0} ns (au plus {1})') -f (Format-UiNum ([math]::Round($f.Tau, 1)) '0.#'), (Format-UiNum ([math]::Round([double]$script:LevelTauMax, 1)) '0.#')
        return $out
    }
    $s = if ($f.Coef.ContainsKey('s')) { [double]$f.Coef['s'] } else { 0.0 }
    $b = if ($f.Coef.ContainsKey('b')) { [double]$f.Coef['b'] } else { 0.0 }
    if ([math]::Abs($s) -gt $script:LevelAdaptSMax -or [math]::Abs($b) -gt $script:LevelAdaptBMax) {
        $out.WhyCode = 'bounds'
        $out.Why = (T 'forme hors des bornes (échelle {0} %, pente {1} ns)') -f (Format-UiNum ([math]::Round(100 * $s, 1)) '+0.0;-0.0;0.0'), (Format-LevelSigned $b)
        return $out
    }
    # Effet de la forme par rapport au niveau seul, sur toute la face ; sous LevelAdaptEffMin : niveau seul
    $m0 = Get-LevelWls $sh ([string[]]@('a')) ([int[]]$cs) $d $sg
    $eff = 0.0
    for ($c = 0; $c -lt $sh.N; $c++) { $ef = [math]::Abs((Get-LevelPredict $sh $f $c)[0] - $m0.Coef['a']); if ($ef -gt $eff) { $eff = $ef } }
    $name = [string]$best.Name
    $loo = $best.Loo
    if ($name -ne 'M0' -and $eff -lt $script:LevelAdaptEffMin) { $name = 'M0'; $f = $m0; $loo = Get-LevelLoo $sh ([string[]]@('a')) ([int[]]$cs) $d $sg }
    $out.Ok = $true; $out.Model = $name; $out.Fit = $f; $out.Cs = [int[]]$cs; $out.Eff = $eff; $out.Loo = $loo; $out.M0 = $m0
    # Zone de reserve : ecart de forme residuel au-dela de LevelTauOk (LevelTauMax pour le niveau seul), ou residu au-dela
    # de LevelAdaptResOk : courbe adaptee, cylindre du plus grand residu nomme « suspect », alerte
    $tok = if ($name -ne 'M0') { [double]$script:LevelTauOk } else { [double]$script:LevelTauMax }
    $cw = $null; $rw = -1.0
    foreach ($c in @($f.Cs)) { $ar = [math]::Abs($f.Res[$c]); if ($ar -gt $rw) { $rw = $ar; $cw = [int]$c } }
    $rs = @()
    if ($f.Tau -gt $tok) { $rs += ((T 'écart de forme résiduel {0} ns (au-delà de {1})') -f (Format-UiNum ([math]::Round($f.Tau, 1)) '0.#'), (Format-UiNum ([math]::Round($tok, 1)) '0.#')) }
    if ($rw -gt $script:LevelAdaptResOk) { $rs += ((T 'c{0} à {1} ns de la forme ajustée') -f "$cw", (Format-LevelSigned $f.Res[$cw])) }
    if ($rs.Count -gt 0) {
        $out.Reserve = $rs; $out.Suspect = $cw
        $out.Named[$cw] = (T 'suspect ({0} ns de la forme ajustée) : défaut local possible') -f (Format-LevelSigned $f.Res[$cw])
    }
    return $out
}

function Get-LevelModelText([string]$model) {
    # 12.8 (F3R) : suffixe '+c' (terme de centre) : texte du modele de base, puis « , centre »
    if ($model -like '*+c') { return (Get-LevelModelText ($model -replace '\+c$', '')) + (T ', centre') }
    switch ($model) { 'Ms' { return (T 'niveau et échelle') } 'Mb' { return (T 'niveau et pente') } 'Msb' { return (T 'niveau, échelle et pente') } default { return (T 'niveau seul') } }
}

function Get-LevelShapeTerms($fit, [int]$last) {
    # « niveau +45 ns, échelle +19,0 %, pente +22 ns de c0 à c79 » ; 12.8 (F3R) : « , centre +24 ns à c79 »
    $co = $fit.Coef
    $terms = @((T 'niveau {0} ns') -f (Format-LevelSigned $co['a']))
    if ($co.ContainsKey('s')) { $terms += ((T 'échelle {0} %') -f (Format-UiNum ([math]::Round(100 * [double]$co['s'], 1)) '+0.0;-0.0;0.0')) }
    if ($co.ContainsKey('b')) { $terms += ((T 'pente {0} ns de c0 à c{1}') -f (Format-LevelSigned $co['b']), "$last") }
    if ($co.ContainsKey('hc')) { $terms += ((T 'centre {0} ns à c{1}') -f (Format-LevelSigned $co['hc']), "$last") }
    return ($terms -join ', ')
}

function Write-LevelAdaptFitLog($u, $an) {
    $pfx = $u.Prefix; $kref = [double]$u.KRef
    if ($an.KOrder.Count -gt 0 -and $an.D.Count -gt 0) {
        $kk = @($an.KOrder | ForEach-Object { $an.Ks[$_] }) | Measure-Object -Minimum -Maximum
        $dd = @($an.D.Values) | Measure-Object -Minimum -Maximum
        Append-Log ($pfx + ((T 'Zéros mesurés à deux précompensations : pente propre de {0} à {1} fois celle de la référence ; écarts à la référence de {2} à {3} ns.') -f (Format-UiNum ([math]::Round($kk.Minimum / $kref, 1)) '0.#'), (Format-UiNum ([math]::Round($kk.Maximum / $kref, 1)) '0.#'), (Format-LevelSigned $dd.Minimum), (Format-LevelSigned $dd.Maximum)))
    }
    foreach ($c in @($an.Iso.Keys | Sort-Object)) {
        Append-Log ($pfx + ((T "Écart isolé à c{0} ({1} ns par rapport à la forme ajustée sans lui) : défaut ponctuel probable de cette disquette, écarté de l'ajustement et non compensé.") -f "$c", (Format-LevelSigned $an.Iso[$c])))
    }
    if (-not $an.Ok) { return }
    $f = $an.Fit
    $worst = $null; $wq = -1.0
    foreach ($c in @($f.Cs)) { $lv = $an.Loo[$c]; $q = [math]::Abs($lv.R) / [math]::Max([double]$script:LevelAdaptLooFloor, [double]$script:LevelAdaptLooK * $lv.Sd); if ($q -gt $wq) { $wq = $q; $worst = [int]$c } }
    $thr = [math]::Min([math]::Max([double]$script:LevelAdaptLooFloor, [double]$script:LevelAdaptLooK * $an.Loo[$worst].Sd), [double]$script:LevelAdaptLooCap)
    if ($an.Model -eq 'M0') {
        Append-Log ($pfx + ((T 'Forme de la référence confirmée par les zéros mesurés (écart de forme {0} ns) : niveau seul, {1} ns.') -f (Format-UiNum ([math]::Round($f.Tau, 1)) '0.#'), (Format-LevelSigned $f.Coef['a'])))
    } else {
        Append-Log ($pfx + ((T 'Forme ajustée ({0}) : {1} ; écart de forme résiduel {2} ns ; validation croisée : écart maximal {3} ns à c{4} (tolérance {5}).') -f (Get-LevelModelText $an.Model), (Get-LevelShapeTerms $f ($u.ShapeV.N - 1)), (Format-UiNum ([math]::Round($f.Tau, 1)) '0.#'), (Format-LevelSigned $an.Loo[$worst].R), "$worst", (Format-UiNum ([math]::Round($thr, 1)) '0.#')))
    }
}

function Get-LevelAdaptHard($u, [string]$model, $raw, [double]$delta = 0.0, $clip = @()) {
    # 12.8 (F3R, decision 2 du 21/10/2026) : plafond de la courbe adaptee d une tete. CalHardNs (write.precompMaxNs) par
    # defaut ; porte au plafond de la disquette (12.11 : Get-UnitCapNs, quart de la cellule de l image ; 470 ns jusqu a la
    # 12.10) quand le besoin modelise de cette disquette (Raw + delta, arrondi) depasse CalHardNs sur un cylindre de
    # reference non nulle hors Clip, pour une forme adaptee (modele autre que M0, M0+c compris) seulement. Une borne
    # precompMaxNs au moins egale a ce plafond reste telle quelle ; la reference, le niveau seul (M0), la courbe de refus
    # et toute calibration complete restent bornes a CalHardNs.
    # 12.8 (F3R-FIX, constat 4) : seuil de declenchement max(CalHardNsDefault, CalHardNs) : besoin au-dela de 400 ns, ou de
    # la borne reglee si elle est plus haute. 12.8 (S3-FLUX, decision 3 du 21/10/2026) : borne precompMaxNs reglee sous
    # CalHardNsDefault (400 ns) : respectee, sans relevement par disquette, comme Get-DiskHardNs
    $base = [int]$script:CalHardNs; $ext = Get-UnitCapNs $u
    if ($ext -le $base -or $base -lt [int]$script:CalHardNsDefault -or -not $model -or $model -eq 'M0') { return $base }
    $thr = [math]::Max([int]$script:CalHardNsDefault, $base)
    $V = $u.ShapeV.V; $need = $null
    for ($c = 0; $c -lt @($raw).Count; $c++) {
        if ([double]$V[$c] -le 0 -or @($clip) -contains $c) { continue }
        $x = [math]::Round([double]$raw[$c] + $delta)
        if ($null -eq $need -or $x -gt $need) { $need = $x }
    }
    if ($null -ne $need -and $need -gt $thr) { return $ext }
    return $base
}

function Build-LevelAdaptValues($u, $fit, [string]$model = '') {
    # Courbe adaptee : reference du lecteur + modele, bornee a 0..plafond ; valeur de reference a la borne de son calcul
    # (Get-CurveMaxNs) jamais abaissee, comme Build-LevelValues. Sat : besoin du modele au-dela du plafond ; Clip :
    # reference elle-meme au-dela de la borne actuelle (borne reglable, pas un besoin de cette disquette), ramenee a
    # CalHardNs. 12.8 (F3R, decision 2) : plafond de la tete (Get-LevelAdaptHard, Hard), CalHardNs sans modele ou pour M0.
    # 12.8 (F3R-FIX, constat 1) : Clip ne declenche jamais le plafond par disquette ; plafond porte au-dela de CalHardNs par
    # un autre cylindre : les cylindres Clip suivent ce plafond (Sat au-dela), au lieu de retomber a CalHardNs
    $sh = $u.ShapeV; $base = [int]$script:CalHardNs; $rmax = Get-CurveMaxNs $u.Cv
    $n = $sh.N
    $vals = New-Object int[] $n; $raw = New-Object double[] $n
    $sat = @(); $floor = @(); $clip = @()
    for ($c = 0; $c -lt $n; $c++) {
        $rv = [double]$sh.V[$c]
        $v = $rv + (Get-LevelPredict $sh $fit $c)[0]
        if ($rv -ge $rmax) { $v = [math]::Max($v, $rv) }
        $raw[$c] = $v
        if ($rv -gt $base) { $clip += $c }
    }
    $mx = Get-LevelAdaptHard $u $model $raw 0.0 $clip
    for ($c = 0; $c -lt $n; $c++) {
        $rv = [double]$sh.V[$c]; $v = $raw[$c]
        if ($mx -le $base -and $clip -contains $c) { $vals[$c] = [int][math]::Max(0, [math]::Min($base, [math]::Round($v))); continue }
        if ($v -gt $mx) { $sat += $c }
        elseif ($v -lt 0 -and $rv -gt 0) { $floor += $c }
        $vals[$c] = if ($rv -gt 0) { [int][math]::Max(0, [math]::Min($mx, [math]::Round($v))) } else { 0 }
    }
    return @{ Values = $vals; Raw = $raw; Sat = $sat; Floor = $floor; Clip = $clip; Hard = $mx }
}

function Set-LevelVerifTargets($cal, $u, $an) {
    # Passe de verification : courbe adaptee ecrite sur les cylindres d ajustement (controles integres d une reprise e3
    # compris) et les cylindres de controle
    $bv = Build-LevelAdaptValues $u $an.Fit ([string]$an.Model)
    $u.AV = $bv
    $t = @{}
    $fc = Get-LevelFitCyls $u
    foreach ($c in @(@($fc) + @($u.Ctl) | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_ } | Sort-Object -Unique)) { $t[$c] = [int]$bv.Values[$c] }
    $u.LTarget = $t
    $u.Mode = 'verif'
    Add-LevelCalCyls $cal ([int[]]@($u.Ctl))
}

function Get-LevelSE($m) {
    # Erreur-type d une mesure, 2 ns si elle n est pas mesuree (comme Get-LevelZero)
    if ($null -eq $m -or $null -eq $m.SE -or [double]::IsNaN([double]$m.SE) -or [double]$m.SE -le 0) { return 2.0 }
    return [double]$m.SE
}

function Test-LevelAdaptVerify($u, [int]$p) {
    # Passe de verification : niveau (decalage residuel moyen des cylindres ajustes, tolerance de Get-LevelEstimate),
    # acceptation cylindre par cylindre (Get-ResidualTol, sinon ecart a la forme), controles d extrapolation. Ligne de
    # journal ; Why non vide : refus (ou, depuis F3R, correction du centre, courbe gardee avec reserve : Invoke-LevelStep).
    # 12.8 (F3R, v3f.py analyse_verif) :
    #  - Bk : decalage moyen dans la moyenne des Get-ResidualTol des cylindres ajustes : correction delta gardee, niveau dit
    #    verifie (Corr) ; premier palier juge contre le decalage moyen quand delta n est pas nul ;
    #  - e1 : controle ecrit deux fois (passe de mesure et verification) : pente de la corde, la verification ramenee a
    #    l epoque de la mesure par la derive de la tete (Drift = decalage moyen / pente commune) ;
    #  - plafond de la courbe ecrite (Hv, AV.Hard) : controle et controle integre ecrits a ce plafond, besoin au-dela :
    #    non verifiables (au plafond) ;
    #  - aucune mesure (NoMeas) : refus, ni centre ni reserve
    $pfx = $u.Prefix; $an = $u.AN; $sh = $u.ShapeV; $kp = [double]$an.KPool; $kref = [double]$u.KRef
    $hv = if ($u.AV -and $null -ne $u.AV.Hard) { [int]$u.AV.Hard } else { [int]$script:CalHardNs }
    $klo = [double]$script:LevelAdaptKRatioLo * $kref; $khi = [double]$script:LevelAdaptKRatioHi * $kref
    $cfit = @(@($u.CtlFit) | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_ })
    $raw = @{}
    foreach ($c in @($u.LTarget.Keys | ForEach-Object { [int]$_ })) { $lst = $u.Raw[$c]; if ($lst -and @($lst).Count -gt 0 -and [int]$lst[-1][0] -eq $p) { $raw[$c] = $lst[-1] } }
    $fitc = @($an.Cs | Where-Object { $raw.ContainsKey([int]$_) -and -not ($cfit -contains [int]$_ -and [int]$raw[[int]$_][1] -ge $hv -and [double]$raw[[int]$_][2].Shift -gt 0) })
    $rs = @($fitc | ForEach-Object { [double]$raw[[int]$_][2].Shift })
    $vr = @{ Tier = @{}; Dev = @{}; Ctl = @{}; Conv = $false; RBar = [double]::NaN; RTol = [double]::NaN; Delta = 0.0; NewBad = @(); Confirmed = @(); NonRep = @(); BadCtl = @(); Why = ''
             NoMeas = $false; Corr = $false; GMean = [double]::NaN; Drift = 0.0; T1 = @(); T2 = @(); Hv = $hv; Pass = $p }
    if ($rs.Count -eq 0) { $vr.Why = (T 'aucune mesure à la vérification'); $vr.NoMeas = $true; return $vr }
    $sum = 0.0; foreach ($x in $rs) { $sum += $x }
    $rbar = $sum / $rs.Count
    $rtol = [double]$script:CalResidual * [math]::Min(1.0, $kp / 2.0)
    if ($rs.Count -ge 2) {
        $q = 0.0; foreach ($x in $rs) { $q += [math]::Pow($x - $rbar, 2) }
        $sd = [math]::Sqrt($q / ($rs.Count - 1))
        $rtol = [math]::Max($rtol, 2.0 * $sd / [math]::Sqrt($rs.Count))
    }
    $conv = ([math]::Abs($rbar) -le $rtol)
    $delta = if ($conv) { 0.0 } else { $rbar / $kp }
    # Bk : tolerance par cylindre de la verification (Get-ResidualTol), moyenne sur les cylindres ajustes
    $gs = 0.0; foreach ($c in $fitc) { $gs += [double](Get-ResidualTol $raw[[int]$c][2]) }
    $gmean = $gs / $fitc.Count
    $corr = $false
    if (-not $conv -and [math]::Abs($rbar) -le $gmean) { $conv = $true; $corr = $true }
    $vr.RBar = $rbar; $vr.RTol = $rtol; $vr.Conv = $conv; $vr.Delta = $delta; $vr.Corr = $corr; $vr.GMean = $gmean; $vr.Drift = $rbar / $kp
    foreach ($c in @($raw.Keys | Sort-Object)) {
        if (@($u.Ctl) -contains $c) { continue }
        $w = [int]$raw[$c][1]; $m = $raw[$c][2]
        $k = if ($an.Ks.ContainsKey($c)) { [double]$an.Ks[$c] } else { $kp }
        if (-not ($klo -le $k -and $k -le $khi)) { $k = $kp }
        $dev = [double]$m.Shift / $k - $delta
        $sgc = [math]::Max(1.0, (Get-LevelSE $m) / $k)
        $tol1 = Get-ResidualTol $m
        $tier = if ([math]::Abs([double]$m.Shift - $(if ($delta -ne 0) { $rbar } else { 0.0 })) -le $tol1) { 1 } elseif ([math]::Abs($dev) -gt [math]::Max([double]$script:CalDevNs, 4.0 * $sgc)) { 3 } else { 2 }
        # Controle integre (e3) ecrit au plafond, besoin au-dela : non verifiable (plafond)
        if ($tier -eq 3 -and $cfit -contains $c -and $w -ge $hv -and [double]$m.Shift -gt 0) { $tier = 2 }
        $vr.Tier[$c] = $tier; $vr.Dev[$c] = $dev
        if ($an.Named.ContainsKey($c)) { if ($tier -eq 3) { $vr.Confirmed += $c } else { $vr.NonRep += $c } }
        elseif ($tier -eq 3) { $vr.NewBad += $c }
    }
    foreach ($x in @($u.Ctl | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_ })) {
        if (-not $raw.ContainsKey($x)) { continue }
        $m = $raw[$x][2]
        # e1 : pente de la corde de ses deux ecritures (passe de mesure, verification ramenee a l epoque de la mesure)
        $kx = $kp
        $prev = @(@($u.Raw[$x]) | Where-Object { [int]$_[0] -lt $p })
        if ($prev.Count -gt 0) {
            $w0 = [double]$prev[-1][1]; $s0 = [double]$prev[-1][2].Shift
            $w1 = [double]$raw[$x][1] - [double]$vr.Drift
            if ([math]::Abs([int]$raw[$x][1] - [int]$prev[-1][1]) -ge $script:LevelAdaptDeltaMin -and [math]::Abs($w1 - $w0) -gt 1e-6) {
                $kc = ($s0 - [double]$m.Shift) / ($w1 - $w0)
                if ($klo -le $kc -and $kc -le $khi) { $kx = $kc }
            }
        }
        $dev = [double]$m.Shift / $kx - $delta
        $sp = (Get-LevelPredict $sh $an.Fit $x)[1]
        $tol = [math]::Min([double]$script:LevelAdaptCtlCap, [math]::Max([double]$script:LevelAdaptCtlFloor, [double]$script:LevelAdaptCtlK * [math]::Sqrt([math]::Pow($sp, 2) + [math]::Pow([double]$script:LevelShapeFloor, 2) + [math]::Pow((Get-LevelSE $m) / $kx, 2))))
        $capped = ([int]$u.LTarget[$x] -ge $hv -and [double]$m.Shift -gt 0)
        $vr.Ctl[$x] = @{ Dev = $dev; Tol = $tol; Ok = ([math]::Abs($dev) -le $tol -or $capped); Cap = $capped; K = $kx }
    }
    $vr.BadCtl = @($vr.Ctl.Keys | Sort-Object | Where-Object { -not $vr.Ctl[$_].Ok })
    $t1 = @($vr.Tier.Keys | Sort-Object | Where-Object { $vr.Tier[$_] -eq 1 -and -not $an.Named.ContainsKey($_) })
    $t2 = @($vr.Tier.Keys | Sort-Object | Where-Object { $vr.Tier[$_] -eq 2 -and -not $an.Named.ContainsKey($_) })
    $vr.T1 = $t1; $vr.T2 = $t2
    $ctlTxt = ''
    foreach ($x in @($vr.Ctl.Keys | Sort-Object)) { $ctlTxt += ' ; ' + ((T 'contrôle c{0} {1} ns (tolérance {2})') -f "$x", (Format-LevelSigned $vr.Ctl[$x].Dev), (Format-UiNum ([math]::Round($vr.Ctl[$x].Tol, 1)) '0.#')) }
    $none = '-'
    Append-Log ($pfx + ((T 'Vérification de la courbe adaptée à la passe {0} : décalage résiduel moyen {1} ns (tolérance {2}) ; cylindres vérifiés : {3} ; dans la forme : {4}{5}.') -f "$p", (Format-UiNum ([math]::Round($rbar, 1)) '0.#'), (Format-UiNum ([math]::Round($rtol, 1)) '0.#'), $(if ($t1.Count) { Format-CylList ([int[]]$t1) } else { $none }), $(if ($t2.Count) { Format-CylList ([int[]]$t2) } else { $none }), $ctlTxt))
    if ($vr.NewBad.Count -gt 0) {
        $vr.Why = (T 'vérification hors de la forme ajustée aux cylindres {0} ({1} ns)') -f (Format-CylList ([int[]]$vr.NewBad)), ((@($vr.NewBad | ForEach-Object { Format-LevelSigned $vr.Dev[$_] })) -join ', ')
    } elseif ($vr.BadCtl.Count -gt 0) {
        $vr.Why = ((@($vr.BadCtl | ForEach-Object { (T "contrôle d'extrapolation hors tolérance à c{0} ({1} ns, tolérance {2})") -f "$_", (Format-LevelSigned $vr.Ctl[$_].Dev), (Format-UiNum ([math]::Round($vr.Ctl[$_].Tol, 1)) '0.#') })) -join ', ')
    }
    return $vr
}

function Get-LevelPtsEpoch($u, [int]$c, $dmap) {
    # 12.8 (F3R, v3f.py _pts_epoch) : mesures d un cylindre, toutes passes : W (valeur ecrite ramenee a l epoque de la passe
    # de mesure par la derive de la passe, dmap), S (decalage), E (erreur-type), P (passe), WW (valeur ecrite)
    $out = @()
    if (-not $u.Raw.ContainsKey($c)) { return ,$out }
    foreach ($t in @($u.Raw[$c])) {
        if ($null -eq $t) { continue }
        $pp = [int]$t[0]; $dd = if ($dmap -and $dmap.ContainsKey($pp)) { [double]$dmap[$pp] } else { 0.0 }
        $out += ,@{ W = [double][int]$t[1] - $dd; S = [double]$t[2].Shift; E = (Get-LevelSE $t[2]); P = $pp; WW = [int]$t[1] }
    }
    return ,$out
}

function Get-LevelZeroPts($pts, [double]$kref, [double]$kp) {
    # 12.8 (F3R, v3f.py zero_pts) : zero d un cylindre sans borne a CalHardNs : corde des deux points qui encadrent le zero
    # si leurs valeurs ecrites sont a LevelAdaptDeltaMin au moins et la pente plausible ; sinon point le plus proche du zero,
    # pente de la corde la plus large (LevelAdaptDeltaMin, plausible) ou pente commune. Incertitude : erreurs-types, plus
    # 10 % (pente propre) ou 25 % (pente commune) du chemin
    if (-not $pts -or @($pts).Count -eq 0) { return $null }
    $xs = @(@($pts) | Sort-Object -Property @{ Expression = { $_.W } }, @{ Expression = { $_.S } }, @{ Expression = { $_.E } }, @{ Expression = { $_.P } }, @{ Expression = { $_.WW } })
    $lo = [double]$script:LevelAdaptKRatioLo * $kref; $hi = [double]$script:LevelAdaptKRatioHi * $kref
    for ($i = 0; $i -lt $xs.Count - 1; $i++) {
        $a1 = $xs[$i]; $a2 = $xs[$i + 1]
        if ($a1.S -gt 0 -and 0 -ge $a2.S -and [math]::Abs($a2.WW - $a1.WW) -ge $script:LevelAdaptDeltaMin -and $a2.W - $a1.W -gt 1e-6) {
            $a = ($a1.S - $a2.S) / ($a2.W - $a1.W)
            if ($lo -le $a -and $a -le $hi) { return @{ Est = $a1.W + $a1.S / $a; Sig = [math]::Max(1.0, [math]::Sqrt([math]::Pow($a1.E, 2) + [math]::Pow($a2.E, 2)) / $a); K = $a; Own = $true } }
        }
    }
    $best = $xs[0]; foreach ($t in $xs) { if ([math]::Abs($t.S) -lt [math]::Abs($best.S)) { $best = $t } }
    $far = $xs[0]; foreach ($t in $xs) { if ([math]::Abs($t.WW - $best.WW) -gt [math]::Abs($far.WW - $best.WW)) { $far = $t } }
    $k = $null
    if ([math]::Abs($far.WW - $best.WW) -ge $script:LevelAdaptDeltaMin -and [math]::Abs($far.W - $best.W) -gt 1e-6) {
        $a = ($far.S - $best.S) / ($best.W - $far.W)
        if ($lo -le $a -and $a -le $hi) { $k = $a }
    }
    $kk = if ($null -ne $k) { [double]$k } else { $kp }
    $z = $best.W + $best.S / $kk
    $sig = [math]::Sqrt([math]::Pow($best.E / $kk, 2) + [math]::Pow($(if ($null -ne $k) { 0.10 } else { 0.25 }) * [math]::Abs($best.S / $kk), 2))
    return @{ Est = $z; Sig = [math]::Max(1.0, $sig); K = $kk; Own = ($null -ne $k) }
}

function Get-LevelFreshCtl($u, $taken, [int]$maxCyl = -1) {
    # 12.8 (F3R, v3f.py fresh_ctl) : controle neuf apres une reprise avec un terme de centre : cylindre jamais ecrit de
    # LevelAdaptCtlLo au dernier, hors cylindres pris et leurs voisins, point de reference interpole et fiable, valeur de
    # 5 a CalHardNs - 15 ns ; le plus proche du centre. $null s il n y en a aucun. 12.8 (F3R-FIX, constat 2) : dernier :
    # fin de la reference, au plus le dernier cylindre de l image ($maxCyl, MaxCyl de la calibration), comme
    # Get-LevelCtlCyls
    $cv = $u.Cv; $last = @($u.V).Count - 1
    if ($maxCyl -ge 0) { $last = [math]::Min($last, $maxCyl) }
    $cyls = @(@($cv.Cyls) | ForEach-Object { [int]$_ })
    $tk = @{}; foreach ($t in @($taken)) { if ($null -ne $t) { $tk[[int]$t] = $true } }
    $best = $null
    for ($c = [int]$script:LevelAdaptCtlLo; $c -le $last; $c++) {
        if ($tk.ContainsKey($c) -or $tk.ContainsKey($c - 1) -or $tk.ContainsKey($c + 1) -or [int]$u.Writes[$c] -gt 0) { continue }
        $i = -1; for ($q = 0; $q -lt $cyls.Count; $q++) { if ($cyls[$q] -eq $c) { $i = $q; break } }
        if ($i -lt 0) { continue }
        if ($cv.Kinds -and $i -lt @($cv.Kinds).Count -and [string]$cv.Kinds[$i] -ne 'interp') { continue }
        if (Test-CurvePointFlag $cv $i) { continue }
        if ([double]$u.V[$c] -le 5 -or [double]$u.V[$c] -ge [double]$script:CalHardNs - 15) { continue }
        $best = $c
    }
    return $best
}

function Get-LevelCenterCtl($u) {
    # Controles de la tete ayant des mesures : integres (CtlFit), puis hors ajustement (Ctl)
    return ,@(@(@($u.CtlFit) + @($u.Ctl)) | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_ } | Where-Object { $u.Raw.ContainsKey($_) -and @($u.Raw[$_]).Count -gt 0 })
}

function Test-LevelCenterFit($u, $an, $names, [int[]]$cs2, $d, $sg, [int]$xs, [double]$s, [int[]]$reinc, [switch]$Bounds) {
    # Ajustement de la forme avec le terme de centre et ses refus (v3f.py center_eval / center_rescue) : significativite et
    # sens du terme, lissage, ecart de forme residuel, bornes, regularite (controle le plus ecarte et reintegres predits
    # sans eux). Renvoie @{ Fit ; Bh ; Se ; Why } (Why vide : retenu) ou $null (ajustement impossible)
    $sh = $u.ShapeV; $t0 = [double]$script:LevelShapeFloor
    $f = Get-LevelWls $sh ([string[]]$names) $cs2 $d $sg
    if (-not $f) { return $null }
    $ih = [array]::IndexOf([string[]]$names, 'hc')
    $bh = [double]$f.Beta[$ih]
    $seh = [math]::Sqrt([math]::Max(1e-12, [double]$f.Cov[$ih][$ih]))
    $o = @{ Fit = $f; Bh = $bh; Se = $seh; Why = '' }
    if ($bh * $s -le 0 -or [math]::Abs($bh) -lt [double]$script:LevelAdaptCoefZ * $seh) { $o.Why = (T 'terme de centre non significatif ({0} ± {1} ns)') -f (Format-LevelSigned $bh), (Format-UiNum ([math]::Round($seh, 1)) '0.#'); return $o }
    $cw = $null
    foreach ($c in $cs2) { $ar = [math]::Abs([double]$f.Res[$c]); if ($ar -gt [math]::Max([double]$script:LevelCenterResOk, 3.0 * [double]$sg[$c]) -and ($null -eq $cw -or $ar -gt [math]::Abs([double]$f.Res[$cw]))) { $cw = $c } }
    if ($null -ne $cw) { $o.Why = (T 'forme avec terme de centre peu lisse (c{0} à {1} ns)') -f "$cw", (Format-LevelSigned $f.Res[$cw]); return $o }
    if ([double]$f.Tau -gt [double]$script:LevelTauMax) { $o.Why = (T 'écart de forme résiduel {0} ns avec le terme de centre') -f (Format-UiNum ([math]::Round($f.Tau, 1)) '0.#'); return $o }
    $cs = if ($f.Coef.ContainsKey('s')) { [double]$f.Coef['s'] } else { 0.0 }
    $cb = if ($f.Coef.ContainsKey('b')) { [double]$f.Coef['b'] } else { 0.0 }
    if ([math]::Abs($cs) -gt $script:LevelAdaptSMax -or [math]::Abs($cb) -gt $script:LevelAdaptBMax) {
        $o.Why = if ($Bounds) { (T 'forme avec terme de centre hors des bornes (échelle {0} %, pente {1} ns)') -f (Format-UiNum ([math]::Round(100 * $cs, 1)) '+0.0;-0.0;0.0'), (Format-LevelSigned $cb) } else { (T 'forme avec terme de centre hors des bornes') }
        return $o
    }
    foreach ($c in @(@($xs) + @($reinc))) {
        $rest = [int[]]@($cs2 | Where-Object { $_ -ne $c })
        $g = Get-LevelWls $sh ([string[]]$names) $rest $d $sg
        if (-not $g) { $o.Why = (T 'régularité non vérifiable à c{0}') -f "$c"; return $o }
        $pr = Get-LevelPredict $sh $g $c
        $rl = [double]$d[$c] - $pr[0]
        $thr = [math]::Min([math]::Max([double]$script:LevelAdaptLooFloor, [double]$script:LevelAdaptLooK * [math]::Sqrt([math]::Pow([double]$sg[$c], 2) + [math]::Pow($t0, 2) + [math]::Pow($pr[1], 2))), [double]$script:LevelCenterLooCap)
        if ([math]::Abs($rl) -gt $thr) { $o.Why = (T 'écart à c{0} non prédit par les autres cylindres du centre ({1} ns, tolérance {2})') -f "$c", (Format-LevelSigned $rl), (Format-UiNum ([math]::Round($thr, 1)) '0.#'); return $o }
    }
    return $o
}

function Get-LevelCenterEval($u, $an, [int]$stage, $vr) {
    # 12.8 (F3R, v3f.py center_eval, stage 3) : correction du centre par les controles a la passe de verification.
    # Declenchement : controle hors tolerance (vr.BadCtl) sans nouveau cylindre hors de la forme ; appui : un autre
    # cylindre du centre (controle, cylindre ajuste ou ecart isole, c >= LevelCenterC0) ecarte dans le meme sens, aucun en
    # sens contraire ; ajustement de la forme retenue + terme de centre hc sur les cylindres ajustes, les controles et
    # l ecart isole du centre de meme sens (reintegre) ; zeros de toutes les passes, la verification ramenee a l epoque de
    # la mesure par la derive de la tete. Renvoie $null (rien a faire) ou @{ Ok ; Why ; Stage ; AN ; Drift }
    $sh = $u.ShapeV; $kref = [double]$u.KRef; $kp = [double]$an.KPool; $f0 = $an.Fit
    $c0 = [int]$script:LevelCenterC0; $t0 = [double]$script:LevelShapeFloor
    $dd = if ($stage -ge 3 -and $vr -and $null -ne $vr.Drift) { [double]$vr.Drift } else { 0.0 }
    $dmap = @{ 3 = $dd; 4 = $dd }
    $ctl = Get-LevelCenterCtl $u
    if ($ctl.Count -eq 0) { return $null }
    $iso = if ($an.Iso) { $an.Iso } else { @{} }
    $named = if ($u.Named) { $u.Named } else { @{} }
    $d = @{}; $sg = @{}; $ks = @{}
    foreach ($k in @($an.Ks.Keys)) { $ks[[int]$k] = [double]$an.Ks[$k] }
    $fcs = Get-LevelFitCyls $u
    foreach ($c in @(@(@($fcs) + @($ctl)) | Sort-Object -Unique)) {
        $z = Get-LevelZeroPts (Get-LevelPtsEpoch $u ([int]$c) $dmap) $kref $kp
        if ($null -eq $z) { continue }
        $d[[int]$c] = [double]$z.Est - [double]$sh.V[[int]$c]; $sg[[int]$c] = [double]$z.Sig
        if ($z.Own) { $ks[[int]$c] = [double]$z.K }
    }
    # Ecarts de la verification (besoin - courbe adaptee, epoque de la verification) : controles par la corde (e1), puis
    # cylindres ecrits, dans l ordre de v3f.py
    $r = @{}; $sd = @{}; $ro = @()
    foreach ($x in @($vr.Ctl.Keys | ForEach-Object { [int]$_ } | Sort-Object)) { $r[$x] = [double]$vr.Ctl[$x].Dev; $sd[$x] = [double]$vr.Ctl[$x].Tol / [double]$script:LevelAdaptCtlK; $ro += $x }
    foreach ($c in @($vr.Dev.Keys | ForEach-Object { [int]$_ } | Sort-Object)) {
        $m = $u.Raw[$c][-1][2]
        $k = if ($an.Ks.ContainsKey($c)) { [double]$an.Ks[$c] } else { $kp }
        $r[$c] = [double]$vr.Dev[$c]; $sd[$c] = [math]::Max(1.0, (Get-LevelSE $m) / $k); $ro += $c
    }
    $over = @($vr.BadCtl | ForEach-Object { [int]$_ })
    if ($over.Count -eq 0) { return $null }
    $xs = $over[0]; foreach ($x in $over) { if ([math]::Abs($r[$x]) / [double]$vr.Ctl[$x].Tol -gt [math]::Abs($r[$xs]) / [double]$vr.Ctl[$xs].Tol) { $xs = $x } }
    $s = if ($r[$xs] -gt 0) { 1.0 } else { -1.0 }
    $out = @{ Ok = $false; Why = ''; Stage = $stage; Xs = $xs; Drift = $dd; AN = $null }
    $zone = @($ro | Where-Object { $_ -ge $c0 -and $_ -ne $xs -and ($ctl -contains $_ -or @($an.Cs) -contains $_ -or $iso.ContainsKey($_)) })
    $sup = @($zone | Where-Object { $s * $r[$_] -ge [math]::Max([double]$script:LevelCenterMinOther, $(if ($ctl -contains $_) { $sd[$_] } else { 0.0 })) })
    $opp = @($zone | Where-Object { $s * $r[$_] -le -[math]::Max([double]$script:LevelCenterOpp, 2.0 * $sd[$_]) })
    if ($sup.Count -eq 0) { $out.Why = (T "écart du contrôle c{0} ({1} ns) sans appui d'un autre cylindre du centre") -f "$xs", (Format-LevelSigned $r[$xs]); return $out }
    if ($opp.Count -gt 0) { $out.Why = (T 'écarts de sens contraires au centre (c{0} {1} ns, c{2} {3} ns)') -f "$xs", (Format-LevelSigned $r[$xs]), "$($opp[0])", (Format-LevelSigned $r[$opp[0]]); return $out }
    $reinc = [int[]]@(@($iso.Keys | ForEach-Object { [int]$_ } | Sort-Object) | Where-Object { $d.ContainsKey($_) -and $r.ContainsKey($_) -and $s * $r[$_] -gt 0 -and $_ -ge $c0 })
    $cs2 = [int[]]@($d.Keys | ForEach-Object { [int]$_ } | Sort-Object | Where-Object { -not ($named.ContainsKey($_) -and $reinc -notcontains $_) -and (@($an.Cs) -contains $_ -or $ctl -contains $_ -or $reinc -contains $_) })
    $names = [string[]]@($f0.Names)
    if ($names -notcontains 'hc') { $names = [string[]]@(@($names) + @('hc')) }
    $tf = Test-LevelCenterFit $u $an $names $cs2 $d $sg $xs $s $reinc
    if ($null -eq $tf) { $out.Why = (T 'terme de centre impossible à ajuster'); return $out }
    if ($tf.Why) { $out.Why = $tf.Why; return $out }
    $f = $tf.Fit
    $an2 = $an.Clone()
    $m0 = Get-LevelWls $sh ([string[]]@('a')) $cs2 $d $sg
    $eff = 0.0
    for ($c = 0; $c -lt $sh.N; $c++) { $ef = [math]::Abs((Get-LevelPredict $sh $f $c)[0] - [double]$m0.Coef['a']); if ($ef -gt $eff) { $eff = $ef } }
    $loo = Get-LevelLoo $sh $names $cs2 $d $sg
    $an2.Fit = $f; $an2.Cs = $cs2; $an2.Model = $(if ([string]$an.Model -like '*+c') { [string]$an.Model } else { [string]$an.Model + '+c' })
    $an2.D = $d; $an2.Sig = $sg; $an2.Ks = $ks; $an2.Eff = $eff; $an2.Loo = $(if ($loo) { $loo } else { $an.Loo }); $an2.Reserve = @($an.Reserve)
    $rc = @{}; foreach ($x in $ctl) { if ($r.ContainsKey($x)) { $rc[$x] = $r[$x] } }
    $an2.Center = @{ Stage = $stage; Xs = $xs; R = $rc; Reinc = $reinc; Hc = $tf.Bh; Se = $tf.Se; Verified = $null; Drift = $dd; Sup = $sup; Rescue = '' }
    $nm = @{}; foreach ($k in @($an.Named.Keys)) { if ($reinc -notcontains [int]$k) { $nm[[int]$k] = $an.Named[$k] } }
    $an2.Named = $nm
    $out.Ok = $true; $out.AN = $an2
    return $out
}

function Get-LevelCenterRescue($u, $an, $cal) {
    # 12.8 (F3R, e3, v3f.py center_rescue) : adaptation refusee a la passe de mesure (ecarts disperses, ecart isole avec trop
    # peu de cylindres, ecart de forme residuel, forme hors des bornes) alors que les controles (un point, passe de mesure)
    # s ecartent dans le meme sens que les cylindres du centre ecartes : forme niveau, echelle, pente et centre ajustee sur
    # les cylindres non signales, les controles et les cylindres du centre de meme sens ; memes tests que la correction du
    # centre ; les cylindres signales sous LevelCenterC0, les pistes de la surface et les pentes invraisemblables restent
    # ecartes. Verification a la passe 3. Renvoie $null (rien a faire) ou @{ Ok ; Why ; Stage ; AN }
    if (@('scatter', 'iso', 'tau', 'bounds') -notcontains [string]$an.WhyCode -or -not $an.D -or $an.D.Count -eq 0) { return $null }
    $sh = $u.ShapeV; $kref = [double]$u.KRef; $kp = [double]$an.KPool
    $c0 = [int]$script:LevelCenterC0; $t0 = [double]$script:LevelShapeFloor
    $ctl = @(@($u.Ctl) | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_ } | Where-Object { $u.Raw.ContainsKey($_) -and @($u.Raw[$_]).Count -gt 0 })
    if ($ctl.Count -lt 2) { return $null }
    $d = @{}; foreach ($k in @($an.D.Keys)) { $d[[int]$k] = [double]$an.D[$k] }
    $sg = @{}; foreach ($k in @($an.Sig.Keys)) { $sg[[int]$k] = [double]$an.Sig[$k] }
    foreach ($x in $ctl) {
        $z = Get-LevelZeroPts (Get-LevelPtsEpoch $u $x @{}) $kref $kp
        if ($null -eq $z) { return $null }
        $d[$x] = [double]$z.Est - [double]$sh.V[$x]; $sg[$x] = [double]$z.Sig
    }
    $named = @{}
    foreach ($k in @($u.Named.Keys)) { $named[[int]$k] = $u.Named[$k] }
    foreach ($k in @($an.Named.Keys)) { $named[[int]$k] = $an.Named[$k] }
    # Ecartes pour de bon : pistes signalees par le controle de surface de cette face, pentes propres invraisemblables
    $hard = @{}
    foreach ($c in @($an.BadK)) { if ($null -ne $c) { $hard[[int]$c] = $true } }
    if ($cal -and $cal.Surf -and $cal.Surf.Faces -and $null -ne $u.Head -and $cal.Surf.Faces[[int]$u.Head]) { foreach ($b in @($cal.Surf.Faces[[int]$u.Head].Bad)) { if ($b) { $hard[[int]$b.C] = $true } } }
    $inner = @(@($named.Keys | ForEach-Object { [int]$_ } | Sort-Object) | Where-Object { $_ -ge $c0 -and -not $hard.ContainsKey($_) -and $d.ContainsKey($_) })
    $cs0 = [int[]]@((Get-LevelFitCyls $u) | Where-Object { $d.ContainsKey($_) -and -not $named.ContainsKey($_) -and $ctl -notcontains $_ })
    $out = @{ Ok = $false; Why = ''; Stage = 2; AN = $null }
    if ($cs0.Count -lt $script:LevelAdaptMinFit) { $out.Why = (T 'trop peu de cylindres non signalés ({0})') -f "$($cs0.Count)"; return $out }
    $f0 = Get-LevelWls $sh ([string[]]@('a', 's', 'b')) $cs0 $d $sg
    if (-not $f0) { return $null }
    $r = @{}; $sd = @{}; $ro = @()
    foreach ($c in @(@($ctl) + @($inner) + @($cs0 | Where-Object { $_ -ge $c0 }))) {
        $pr = Get-LevelPredict $sh $f0 $c
        $r[$c] = [double]$d[$c] - $pr[0]; $sd[$c] = [math]::Sqrt([math]::Pow([double]$sg[$c], 2) + [math]::Pow($t0, 2) + [math]::Pow($pr[1], 2)); $ro += $c
    }
    $tol = @{}; foreach ($x in $ctl) { $tol[$x] = [math]::Min([double]$script:LevelAdaptCtlCap, [math]::Max([double]$script:LevelAdaptCtlFloor, [double]$script:LevelAdaptCtlK * $sd[$x])) }
    $over = @($ctl | Where-Object { [math]::Abs($r[$_]) -gt $tol[$_] })
    if ($over.Count -eq 0) { $out.Why = (T 'contrôles dans la tolérance de la forme sans centre'); return $out }
    $xs = $over[0]; foreach ($x in $over) { if ([math]::Abs($r[$x]) / $tol[$x] -gt [math]::Abs($r[$xs]) / $tol[$xs]) { $xs = $x } }
    $s = if ($r[$xs] -gt 0) { 1.0 } else { -1.0 }
    $zone = @($ro | Where-Object { $_ -ne $xs })
    $sup = @($zone | Where-Object { $s * $r[$_] -ge [math]::Max([double]$script:LevelCenterMinOther, $(if ($ctl -contains $_) { $sd[$_] } else { 0.0 })) })
    $opp = @($zone | Where-Object { $s * $r[$_] -le -[math]::Max([double]$script:LevelCenterOpp, 2.0 * $sd[$_]) })
    if ($sup.Count -eq 0 -or $opp.Count -gt 0) { $out.Why = (T 'écart du centre irrégulier (c{0} {1} ns)') -f "$xs", (Format-LevelSigned $r[$xs]); return $out }
    $reinc = [int[]]@($inner | Where-Object { $s * $r[$_] -gt 0 })
    $cs2 = [int[]]@(@(@($cs0) + @($ctl) + @($reinc)) | Sort-Object -Unique)
    $names = [string[]]@('a', 's', 'b', 'hc')
    $tf = Test-LevelCenterFit $u $an $names $cs2 $d $sg $xs $s $reinc -Bounds
    if ($null -eq $tf) { return $null }
    if ($tf.Why) { $out.Why = $tf.Why; return $out }
    $f = $tf.Fit
    $m0 = Get-LevelWls $sh ([string[]]@('a')) $cs2 $d $sg
    $eff = 0.0
    for ($c = 0; $c -lt $sh.N; $c++) { $ef = [math]::Abs((Get-LevelPredict $sh $f $c)[0] - [double]$m0.Coef['a']); if ($ef -gt $eff) { $eff = $ef } }
    $loo = Get-LevelLoo $sh $names $cs2 $d $sg
    $an2 = $an.Clone()
    $an2.Ok = $true; $an2.Why = ''; $an2.WhyCode = ''; $an2.Fit = $f; $an2.Cs = $cs2; $an2.Model = 'Msb+c'; $an2.D = $d; $an2.Sig = $sg; $an2.Eff = $eff; $an2.M0 = $m0
    $an2.Loo = $(if ($loo) { $loo } else { @{} }); $an2.Reserve = @()
    $nm = @{}; foreach ($k in @($named.Keys)) { if ($reinc -notcontains [int]$k) { $nm[[int]$k] = $named[$k] } }
    $an2.Named = $nm
    $rc = @{}; foreach ($x in $ctl) { $rc[$x] = $r[$x] }
    $an2.Center = @{ Stage = 2; Xs = $xs; R = $rc; Reinc = $reinc; Hc = $tf.Bh; Se = $tf.Se; Verified = $null; Drift = 0.0; Sup = $sup; Rescue = [string]$an.Why }
    $out.Ok = $true; $out.AN = $an2
    return $out
}

function Write-LevelCenterLog($u, $ce) {
    # 12.8 (F3R) : correction du centre retenue (terme de centre, controles, appui, cylindres reintegres) ou non retenue
    if (-not $ce) { return }
    $pfx = $u.Prefix
    if (-not $ce.Ok) { Append-Log ($pfx + ((T 'Correction du centre non retenue : {0}.') -f "$($ce.Why)")); return }
    $cn = $ce.AN.Center
    $ctxt = (@(@($cn.R.Keys | ForEach-Object { [int]$_ } | Sort-Object) | ForEach-Object { "c$_ $(Format-LevelSigned $cn.R[$_]) ns" })) -join ', '
    $stxt = (@(@($cn.Sup) | ForEach-Object { "c$_" })) -join ', '
    $rtxt = if (@($cn.Reinc).Count -gt 0) { (T ' ; c{0} réintégré (écart de même sens, pas un défaut ponctuel)') -f ((@($cn.Reinc) | ForEach-Object { "$_" }) -join ',') } else { '' }
    $fmt = if ([double]$cn.Hc -gt 0) { (T 'Besoin plus fort vers le centre : contrôles {0}, appui {1}{2} ; terme de centre {3} ns à c{4} (± {5}), ajusté sur {6}.') } else { (T 'Besoin plus faible vers le centre : contrôles {0}, appui {1}{2} ; terme de centre {3} ns à c{4} (± {5}), ajusté sur {6}.') }
    Append-Log ($pfx + ($fmt -f "$ctxt", "$stxt", "$rtxt", (Format-LevelSigned $cn.Hc), "$($u.ShapeV.N - 1)", (Format-UiNum ([math]::Round([double]$cn.Se, 1)) '0.#'), (Format-CylList ([int[]]@($ce.AN.Cs)))))
}

function Set-LevelLevelOnly($u, $an) {
    # Refus d adaptation : niveau seul sur les zeros mesures (courbe de la reference decalee), non verifie
    $d = if ($an -and $an.D) { $an.D } else { @{} }
    $named = if ($an -and $an.Named) { $an.Named } else { @{} }
    $cs = @((Get-LevelFitCyls $u) | Where-Object { $d.ContainsKey($_) -and -not $named.ContainsKey($_) })
    if ($cs.Count -gt 0) {
        $m0 = Get-LevelWls $u.ShapeV ([string[]]@('a')) ([int[]]$cs) $d $an.Sig
        $u.Level = [int][math]::Round([double]$m0.Coef['a'])
    } elseif ($u.Est -and -not [double]::IsNaN([double]$u.Est.Delta)) { $u.Level = [int][math]::Round([double]$u.Est.Delta) }
    $u.Conv = $false
}

function Set-LevelNwcTargets($u) {
    # Pente apparente nulle sur une base etroite : confirmation sur LevelNwcDelta ns (zero de la passe 1 a la pente de
    # reference s il est assez loin, sinon premiere valeur ecrite +/- LevelNwcDelta, du cote du zero)
    $t = @{}; $mx = [int]$script:CalHardNs; $nd = [int]$script:LevelNwcDelta
    foreach ($c in (Get-LevelFitCyls $u)) {
        $pts = $u.Results[$c]
        if (-not $pts -or $pts.Count -eq 0 -or -not $u.Raw[$c]) { continue }
        $w1 = [int]$u.Raw[$c][0][1]
        $x = Get-LevelNearest $pts
        $z = Get-LevelZero @{ $x = $pts[$x] } ([double]$u.KRef)
        $z1 = if ($z) { [double]$z.Est } else { [double]$w1 }
        $sg = [math]::Sign($z1 - $w1); if ($sg -eq 0) { $sg = $(if ([double]$pts[$x].Shift -ge 0) { 1 } else { -1 }) }
        $w = if ([math]::Abs($z1 - $w1) -ge $nd) { [int][math]::Round($z1) } else { $w1 + $sg * $nd }
        if ($w -gt $mx -or $w -lt 0) { $w = $w1 - $sg * $nd }
        $t[$c] = [int][math]::Max(0, [math]::Min($mx, $w))
    }
    $u.LTarget = $t
    $u.Mode = 'nwc'
}

function Get-LevelAdaptOutcome($cal, $u) {
    # Bilan d une tete adaptee (Mode 'adapte' : forme ajustee et verifiee, ou niveau seul confirme a deux
    # precompensations) ou refusee (Mode 'refus' : courbe de la reference decalee), pour Complete-LevelCalib : courbe,
    # verdict, forme, reserves (Info : reserve « information » de la fenetre de decision), lignes du journal.
    # 12.8 (F3R, v3f.py complete) : tete adaptee :
    #  - e4 : correction de derive appliquee AVANT le plafond (cylindre plafonne a la verification : besoin + delta) ;
    #  - plafond par disquette (decision 2 ; 12.11 : Get-UnitCapNs) : courbe adaptee portee au-dela de CalHardNs par son besoin
    #    (Get-LevelAdaptHard) : reserve d information « au-dela de la borne », controle apres ecriture (G1, modele) ;
    #  - Bk : niveau corrige de la derive et dit verifie (J2) ;
    #  - reserve de centre (terme de centre non verifie par une ecriture du motif) et de controle (e2) : J3, R1 ;
    #  - reserves dans l ordre de v3f.py (niveau, centre ou controle, au-dela de la borne, forme, a surveiller, plafond)
    $pfx = $u.Prefix; $e = $u.Est; $an = $u.AN; $mx = [int]$script:CalHardNs
    # 12.11 (L12a) : borne precompMaxNs la plus haute a conseiller quand la courbe sature a la borne (Get-BoundAdviceNs :
    # jamais au-dela du plafond de l image) ; borne deja reglee a cette valeur ou plus haut : aucun conseil de la relever
    $adv = Get-BoundAdviceNs $u
    $iss = New-Object System.Collections.Generic.List[object]
    $r = @{ Values = $null; Sat = @(); Floor = @(); Clip = @(); Verdict = ''; Shape = $null; Issues = $iss; Model = 'M0'; S = 0.0; B = 0.0; Hc = $null; K = $null; Hard = $mx; Over = @(); Corr = $false }
    if ([string]$u.Mode -eq 'refus') {
        $bv = Build-LevelValues $u ([int]$u.Level) $e
        $r.Values = $bv.Values; $r.Sat = @($bv.Sat); $r.Floor = @($bv.Floor); $r.Clip = @($bv.Clip)
        $sh = if ($e) { Test-LevelShape $e $u 1.0 } else { @{ Reasons = @() } }
        $r.Shape = @{ Verdict = 'mismatch'; Reasons = @($sh.Reasons); Tilt = $sh.Tilt; Step = $sh.Step }
        $r.Verdict = 'mismatch'
        Append-Log ($pfx + ((T 'Forme non conforme à la référence et non adaptée : {0}.') -f "$($u.Refus)"))
        $iss.Add(@{ Text = $pfx + ((T 'adaptation refusée : {0}') -f "$($u.Refus)"); Info = $false })
        if (-not $u.Conv) { $iss.Add(@{ Text = $pfx + ((T "niveau non vérifié par une écriture du motif ({0} passe(s))") -f "$($u.Passes)"); Info = $false }) }
        if ($r.Sat.Count -gt 0 -and $u.Memo -and $mx -ge $adv) {
            # 12.8 (F3R-FIX, constat 9) : borne precompMaxNs deja a CalHardMaxNs : plus de conseil de la relever. 12.11 (L12a) :
            # ni au-dela du plafond de l image ($adv, Get-BoundAdviceNs)
            Append-Log ($pfx + ((T 'Plafond de {0} ns atteint aux cylindres {1} avec la courbe adaptée : ces cylindres resteront sous-compensés.') -f "$mx", (Format-CylList ([int[]]$r.Sat))))
            $iss.Add(@{ Text = $pfx + ((T 'plafond de {0} ns atteint aux cylindres {1} avec la courbe adaptée : ces cylindres resteront sous-compensés') -f "$mx", (Format-CylList ([int[]]$r.Sat))); Info = $true })
        } elseif ($r.Sat.Count -gt 0 -and $u.Memo) {
            # 12.8 (FIX1C, constat 5) : courbe de refus partie de la forme d une marque (V' + niveau) : libelle neutre
            Append-Log ($pfx + ((T "Plafond de {0} ns atteint aux cylindres {1} avec la courbe adaptée : ces cylindres resteront sous-compensés ; la borne se règle jusqu'à {2} ns (precompMaxNs).") -f "$mx", (Format-CylList ([int[]]$r.Sat)), "$adv"))
            $iss.Add(@{ Text = $pfx + ((T "plafond de {0} ns atteint aux cylindres {1} avec la courbe adaptée : ces cylindres resteront sous-compensés ; la borne se règle jusqu'à {2} ns (precompMaxNs)") -f "$mx", (Format-CylList ([int[]]$r.Sat)), "$adv"); Info = $true })
        } elseif ($r.Sat.Count -gt 0) {
            # 12.8 (F3R, decision du 21/10/2026) : forme non conforme : libelle neutre, autre type de disquette ou usure
            Append-Log ($pfx + ((T "Plafond de {0} ns atteint aux cylindres {1} avec le niveau de cette disquette ({2} ns par rapport à la référence), de forme différente : autre type de disquette ou usure, non distingués ; ces cylindres resteront sous-compensés.") -f "$mx", (Format-CylList ([int[]]$r.Sat)), ('{0:+0;-0;0}' -f [int]$u.Level)))
            $iss.Add(@{ Text = $pfx + ((T "plafond de {0} ns atteint aux cylindres {1} (autre type de disquette ou usure ?)") -f "$mx", (Format-CylList ([int[]]$r.Sat))); Info = $true })
        }
        if ($r.Floor.Count -gt 0) { $iss.Add(@{ Text = $pfx + ((T "précompensation nulle encore excessive aux cylindres {0}") -f (Format-CylList ([int[]]$r.Floor))); Info = $false }) }
        if ($an -and $an.KPool) { $r.K = [double]$an.KPool }
    } else {
        $bv = $u.AV; $vr = $u.VR; $sh = $u.ShapeV
        $vals = [int[]]@($bv.Values)
        $clip = @($bv.Clip)
        $hv = if ($null -ne $bv.Hard) { [int]$bv.Hard } else { $mx }
        $dl = [double]$vr.Delta
        $hh = Get-LevelAdaptHard $u ([string]$an.Model) $bv.Raw $dl $clip
        # 12.8 (F3R-FIX, constat 1) : plafond de la disquette porte au-dela de CalHardNs : les cylindres Clip le suivent
        # (e4 et Sat compris) ; sinon, comportement d avant (ramenes a CalHardNs, hors Sat)
        $cf = ($hh -gt $mx)
        if ($dl -ne 0 -or $hh -ne $hv) {
            $dd = [int][math]::Round($dl)
            for ($c = 0; $c -lt $vals.Count; $c++) {
                if ([double]$sh.V[$c] -le 0) { $vals[$c] = 0 }
                elseif (-not $cf -and $clip -contains $c) { $vals[$c] = [int][math]::Max(0, [math]::Min($mx, $vals[$c] + $dd)) }
                elseif ([double]$bv.Raw[$c] -gt $hv) { $vals[$c] = [int][math]::Max(0, [math]::Min($hh, [math]::Round([double]$bv.Raw[$c] + $dl))) }
                else { $vals[$c] = [int][math]::Max(0, [math]::Min($hh, $vals[$c] + $dd)) }
            }
        }
        $r.Values = $vals
        # Affectation par branche : « $x = if (...) { @() } » donnerait $null, et @($null).Count vaut 1
        if ($cf) { $r.Clip = @() } else { $r.Clip = $clip }
        $r.Sat = @(0..($vals.Count - 1) | Where-Object { ($cf -or $clip -notcontains $_) -and [double]$bv.Raw[$_] + $dl -gt $hh })
        $r.Floor = @($bv.Floor)
        $r.K = [double]$an.KPool
        $r.Hard = $hh
        $r.Over = @(if ($hh -gt $mx) { 0..($vals.Count - 1) | Where-Object { $vals[$_] -gt $mx } })
        $r.Corr = [bool]$vr.Corr
        $j2 = (T 'Niveau de la courbe adaptée corrigé de {0} ns (dérive entre deux passes ; décalage résiduel moyen {1} ns, dans la tolérance par cylindre {2}).') -f (Format-LevelSigned $dl), (Format-UiNum ([math]::Round([double]$vr.RBar, 1)) '0.#'), (Format-UiNum ([math]::Round([double]$vr.GMean, 1)) '0.#')
        if (-not $u.Conv) {
            $iss.Add(@{ Text = $pfx + ((T 'niveau de la courbe adaptée non vérifié (décalage résiduel moyen {0} ns, tolérance {1}) : décalé de {2} ns sans nouvelle écriture') -f (Format-UiNum ([math]::Round([double]$vr.RBar, 1)) '0.#'), (Format-UiNum ([math]::Round([double]$vr.RTol, 1)) '0.#'), (Format-LevelSigned $vr.Delta)); Info = $true })
        }
        if ([string]$an.Model -eq 'M0') {
            $r.Shape = @{ Verdict = $(if ([double]$an.Fit.Tau -gt [double]$script:LevelTauOk) { 'approx' } else { 'ok' }); Reasons = @() }
            $r.Verdict = $r.Shape.Verdict
            Append-Log ($pfx + ((T 'Forme de la référence confirmée après mesure à deux précompensations : niveau {0} ns{1}.') -f ('{0:+0;-0;0}' -f [int]$u.Level), $(if ($u.Conv) { '' } else { ' ' + (T '(non vérifié)') })))
            if ($vr.Corr) { Append-Log ($pfx + $j2) }
        } else {
            $r.Shape = @{ Verdict = 'adapte'; Reasons = @() }
            $r.Verdict = 'adapte'
            $r.Model = [string]$an.Model
            $r.S = if ($an.Fit.Coef.ContainsKey('s')) { [double]$an.Fit.Coef['s'] } else { 0.0 }
            $r.B = if ($an.Fit.Coef.ContainsKey('b')) { [double]$an.Fit.Coef['b'] } else { 0.0 }
            if ($an.Fit.Coef.ContainsKey('hc')) { $r.Hc = [double]$an.Fit.Coef['hc'] }
            # Reserve de centre (correction par les controles non verifiee par une ecriture du motif) ou de controle (e2)
            $cres = @()
            if ($an.Center -and $an.Center.Verified -eq $false) {
                $ct = (@(@($an.Center.R.Keys | ForEach-Object { [int]$_ } | Sort-Object) | ForEach-Object { "c$_ $(Format-LevelSigned $an.Center.R[$_]) ns" })) -join ', '
                $cres += ((T 'centre corrigé par les contrôles ({0}), non vérifié par une écriture du motif') -f "$ct")
            }
            if ($u.CtlReserve) { $cres += [string]$u.CtlReserve }
            if ($cres.Count -gt 0) {
                Append-Log ($pfx + ((T "Forme adaptée avec réserve : {0} : vers le centre, la courbe peut s'écarter du besoin de cette disquette ; contrôle après écriture imposé.") -f ($cres -join ' ; ')))
                $iss.Add(@{ Text = $pfx + ((T "forme adaptée avec réserve ({0}) : vers le centre, la courbe peut s'écarter du besoin ; contrôle après écriture imposé") -f ($cres -join ' ; ')); Info = $false })
            }
            if ($vr.Corr) { Append-Log ($pfx + $j2) }
            if ($r.Over.Count -gt 0) {
                # Plafond par disquette : reserve d information (comme le plafond atteint), controle apres ecriture deja impose
                $top = ($vals | Measure-Object -Maximum).Maximum
                Append-Log ($pfx + ((T "Courbe adaptée au-delà de {0} ns aux cylindres {1} (jusqu'à {2} ns) : le besoin de cette disquette dépasse la borne precompMaxNs ; plafond porté à {3} ns pour cette disquette seulement ; contrôle après écriture imposé.") -f "$mx", (Format-CylList ([int[]]$r.Over)), "$top", "$hh"))
                Append-Log ($pfx + (Get-DiskOverAdviceText $mx))   # 12.11 : conseil d essai sur la machine cible
                $iss.Add(@{ Text = $pfx + ((T "courbe adaptée au-delà de {0} ns aux cylindres {1} (jusqu'à {2} ns, plafond porté à {3} ns pour cette disquette seulement) : contrôle après écriture imposé") -f "$mx", (Format-CylList ([int[]]$r.Over)), "$top", "$hh"); Info = $true })
            }
            if (@($an.Reserve).Count -gt 0) {
                # 12.8 (G7) : reserve de forme : controle apres ecriture impose, et non calibration complete (elle ferait de
                # cette disquette la reference du lecteur)
                Append-Log ($pfx + ((T 'Forme adaptée avec réserve : {0} ; défaut local possible ou forme mal identifiée sur {1} cylindres : contrôle après écriture imposé.') -f (@($an.Reserve) -join ' ; '), "$(@($an.Cs).Count)"))
                $iss.Add(@{ Text = $pfx + ((T 'forme adaptée avec réserve ({0}) : défaut local possible ; contrôle après écriture imposé') -f (@($an.Reserve) -join ' ; ')); Info = $false })
            }
            $a0 = [double]$an.Fit.Coef['a']; $last = $sh.N - 1
            $dEnd = (Get-LevelPredict $sh $an.Fit $last)[0] - $a0
            $dLo = (Get-LevelPredict $sh $an.Fit 2)[0] - $a0
            $txt = if ($dEnd -gt 0) { (T 'Courbe adaptée retenue : besoin plus fort vers le centre ({0} ns à c{1}, {2} ns à c2) : autre type de disquette ou usure, non distingués ; à surveiller.') } else { (T 'Courbe adaptée retenue : besoin plus faible vers le centre ({0} ns à c{1}, {2} ns à c2) : autre type de disquette ou usure, non distingués ; à surveiller.') }
            Append-Log ($pfx + ($txt -f (Format-LevelSigned $dEnd), "$last", (Format-LevelSigned $dLo)))
            if ([double]$an.Eff -ge $script:LevelAdaptBigEffect) {
                $it = if ($dEnd -gt 0) { (T 'courbe adaptée à cette disquette (besoin plus fort vers le centre, {0} ns à c{1}) : autre type de disquette ou usure, non distingués ; à surveiller') } else { (T 'courbe adaptée à cette disquette (besoin plus faible vers le centre, {0} ns à c{1}) : autre type de disquette ou usure, non distingués ; à surveiller') }
                $iss.Add(@{ Text = $pfx + ($it -f (Format-LevelSigned $dEnd), "$last"); Info = $true })
            }
        }
        if ($r.Sat.Count -gt 0 -and ($hh -gt $mx -or $hh -ge $adv)) {
            # 12.11 : plafond de la disquette applique ($hh au-dela de la borne : Get-UnitCapNs), ou reglage precompMaxNs deja
            # a son maximum CalHardMaxNs (12.8, F3R-FIX, constat 9) : plus de conseil de relever la borne. 12.11 (L12a) : ni
            # au-dela du plafond de l image ($adv, Get-BoundAdviceNs : long track de cellule courte, borne reglee plus haut)
            Append-Log ($pfx + ((T 'Plafond de {0} ns atteint aux cylindres {1} avec la courbe adaptée : ces cylindres resteront sous-compensés.') -f "$hh", (Format-CylList ([int[]]$r.Sat))))
            $iss.Add(@{ Text = $pfx + ((T 'plafond de {0} ns atteint aux cylindres {1} avec la courbe adaptée : ces cylindres resteront sous-compensés') -f "$hh", (Format-CylList ([int[]]$r.Sat))); Info = $true })
        } elseif ($r.Sat.Count -gt 0) {
            Append-Log ($pfx + ((T "Plafond de {0} ns atteint aux cylindres {1} avec la courbe adaptée : ces cylindres resteront sous-compensés ; la borne se règle jusqu'à {2} ns (precompMaxNs).") -f "$hh", (Format-CylList ([int[]]$r.Sat)), "$adv"))
            $iss.Add(@{ Text = $pfx + ((T "plafond de {0} ns atteint aux cylindres {1} avec la courbe adaptée : ces cylindres resteront sous-compensés ; la borne se règle jusqu'à {2} ns (precompMaxNs)") -f "$hh", (Format-CylList ([int[]]$r.Sat)), "$adv"); Info = $true })
        }
        if (@($r.Clip).Count -gt 0) { Append-Log ($pfx + ((T "Référence calculée avec une borne de {0} ns, au-delà de la borne actuelle (precompMaxNs = {1} ns) aux cylindres {2} : valeurs ramenées à {1} ns.") -f "$(Get-CurveMaxNs $u.Cv)", "$mx", (Format-CylList ([int[]]$r.Clip)))) }
    }
    if ($u.Named -and $u.Named.Count -gt 0) {
        $nl = @($u.Named.Keys | ForEach-Object { [int]$_ } | Sort-Object | ForEach-Object { "c$_ $($u.Named[$_])" })
        $iss.Add(@{ Text = $pfx + ((T 'cylindres signalés : {0}') -f ($nl -join ' ; ')); Info = $false })
    }
    return $r
}

function Get-LevelBrandKey([string]$name) { return ([string]$name).Trim().ToLowerInvariant() }

function Find-LevelBrand([string]$name, [string]$drive, [string]$refKey, [string]$tag) {
    # Entree de la memoire de marque : meme marque (casse ignoree), meme lecteur, meme cle de reference et meme tete
    $k = Get-LevelBrandKey $name
    if (-not $k) { return $null }
    foreach ($en in @($script:LevelBrands)) {
        if ($en -and (Get-LevelBrandKey $en.Brand) -eq $k -and [string]$en.Drive -eq $drive -and [string]$en.RefKey -eq $refKey -and [string]$en.Tag -eq $tag) { return $en }
    }
    return $null
}

function Test-LevelBrandValid($en, $cv, [string]$fam) {
    # Entree valable comme point de depart : mesuree avec la reference en place (meme date) et de la meme famille
    return [bool]($en -and $cv -and [string]$en.RefDate -eq [string]$cv.Date -and [string]$en.Family -eq $fam)
}

function Update-LevelBrandStats($en) {
    # Point de depart d une entree : niveau = mediane des niveaux, echelle et pente = medianes des formes mesurees
    $lv = @(@($en.Levels) | Where-Object { $_ } | ForEach-Object { [double]$_.Delta })
    $sp = @(@($en.Shapes) | Where-Object { $_ })
    $en.A = if ($lv.Count -gt 0) { [double](Get-Median $lv) } else { 0.0 }
    $en.S = if ($sp.Count -gt 0) { [double](Get-Median @($sp | ForEach-Object { [double]$_.S })) } else { 0.0 }
    $en.B = if ($sp.Count -gt 0) { [double](Get-Median @($sp | ForEach-Object { [double]$_.B })) } else { 0.0 }
    $en.N = $lv.Count
}

function Get-LevelBrandItems([string]$drive, $units, [string]$fam) {
    # Elements de la liste de marques de l avertissement : marques valables pour ce lecteur et cette reference (« memorisee
    # le »), puis marques d une autre reference (« a remesurer »). Renvoie @{ Items ; Map (texte affiche -> marque) }
    $map = @{}; $ok = @(); $old = @()
    $keys = @{}; foreach ($u in @($units)) { if ($null -ne $u.Head) { $keys["$($u.RefKey)|$($u.Tag)"] = $u.Cv } }
    $seen = @{}
    $all = @(@($script:LevelBrands) | Where-Object { $_ } | Sort-Object { Get-CurveDate $_ } -Descending)
    foreach ($en in $all) {
        if ([string]$en.Drive -ne $drive) { continue }
        $kk = "$($en.RefKey)|$($en.Tag)"; if (-not $keys.ContainsKey($kk)) { continue }
        $bk = Get-LevelBrandKey $en.Brand; if ($seen.ContainsKey($bk)) { continue }
        $seen[$bk] = $true
        $valid = Test-LevelBrandValid $en $keys[$kk] $fam
        # 12.8 (S3) : courbe complete d une tete de la marque, mesuree par « Mesure complete de cette disquette » (L-M),
        # entrees valables de la marque pour ces tetes, quelle que soit la plus recente ; courbe d un autre calcul de
        # calibration ou d un autre nombre de cylindres : a remesurer
        $cvs = @($all | Where-Object { $null -ne $_.Curve -and [string]$_.Drive -eq $drive -and (Get-LevelBrandKey $_.Brand) -eq $bk -and $keys.ContainsKey("$($_.RefKey)|$($_.Tag)") -and (Test-LevelBrandValid $_ $keys["$($_.RefKey)|$($_.Tag)"] $fam) })
        $stale = [bool](@($cvs | Where-Object { -not (Test-LevelBrandCurve $_ @($keys["$($_.RefKey)|$($_.Tag)"].Values).Count) }).Count -gt 0)
        $txt = if ($valid -and $cvs.Count -gt 0 -and -not $stale) { (T '{0} - courbe complète mémorisée le {1}') -f "$($en.Brand)", "$($cvs[0].CurveDate)" }
               elseif ($valid -and $stale) { (T '{0} - à remesurer (calcul de calibration changé)') -f "$($en.Brand)" }
               elseif ($valid) { (T '{0} - mémorisée le {1}') -f "$($en.Brand)", "$($en.Date)" } else { (T '{0} - à remesurer (référence du lecteur changée)') -f "$($en.Brand)" }
        $map[$txt] = [string]$en.Brand
        if ($valid -and -not $stale) { $ok += $txt } else { $old += $txt }
    }
    $none = (T '(non précisée)'); $map[$none] = ''
    return @{ Items = @(@($none) + $ok + $old); Map = $map }
}

function Get-LevelBrandName([string]$text, $map) {
    # Marque saisie ou choisie : texte d un element de la liste ramene a la marque ; « (non precisee) » : aucune
    $t = ([string]$text).Trim()
    if ($map -and $map.ContainsKey($t)) { return [string]$map[$t] }
    return $t
}

function Set-LevelBrandStart($cal, $u, [string]$brand) {
    # 12.8 (lot 1c, § 10.3) : point de depart d une marque memorisee avec la reference en place (meme lecteur, meme cle,
    # meme date de reference, meme famille) et dont la forme n est pas celle de la reference (echelle ou pente non
    # nulle) : V' = V + s (V - RBar) + b (c - (n-1)/2) / (n-1), niveau de depart = mediane des niveaux de la marque,
    # historique de l alerte de fatigue = niveaux de la marque (G4). Sinon : V et niveau de depart de la 12.7 (une entree
    # de niveau seul, comme un enregistrement lvl1 relu avec s = b = 0, n a aucun effet). La forme memorisee ne remplace
    # jamais une mesure : le declencheur B l ecarte si la disquette ne lui ressemble pas
    if (-not $brand -or $null -eq $u.Head) { return }
    $en = Find-LevelBrand $brand ([string]$cal.Drive) ([string]$u.RefKey) ([string]$u.Tag)
    if (-not (Test-LevelBrandValid $en $u.Cv ([string]$cal.Family))) { return }
    Update-LevelBrandStats $en
    $u.BrandEntry = $en
    # 12.8 (S3, c4-design § 4.2) : courbe complete de la tete, mesuree par « Mesure complete de cette disquette » avec le meme
    # calcul de calibration : point de depart V = cette courbe (Get-LevelBrandCurveValues), bornee au plafond par disquette ;
    # forme d adaptation, Clip, cylindres de niveau et de controle : ceux de la reference (V0, FIX1C) ; niveau de depart :
    # mediane des niveaux mesures depuis avec cette courbe (0 a la mesure). Garde de la passe 1 : Get-LevelBrandCurveGuard
    if (Test-LevelBrandCurve $en @($u.V).Count) {
        $u.V = Get-LevelBrandCurveValues $en $u.V ([int]$u.ImgBits)   # 12.11 : plafond de l image (0 sans densite)
        $u.D0 = [int][math]::Round([double]$en.A); $u.D = $u.D0
        $ld = @(@($en.Levels) | Where-Object { $_ } | Sort-Object { Get-CurveDate $_ })
        $u.Memo = @{ Brand = [string]$en.Brand; A = [double]$en.A; S = 0.0; B = 0.0; N = [int]$en.N; Model = 'Mc'; Curve = $true; CurveDate = [string]$en.CurveDate
                     Hist = @(@($en.Levels) | Where-Object { $_ } | ForEach-Object { @{ Date = [string]$_.Date; Delta = [int]$_.Delta } })
                     LastDate = $(if ($ld.Count -gt 0) { [string]$ld[-1].Date } else { [string]$en.Date }) }
        return
    }
    if ([double]$en.S -eq 0 -and [double]$en.B -eq 0) { return }
    $sh = New-LevelShape $u.V
    $vals = New-Object int[] $sh.N
    for ($c = 0; $c -lt $sh.N; $c++) { $vals[$c] = [int][math]::Round($sh.V[$c] + [double]$en.S * (Get-LevelShapeRow $sh ([string[]]@('s')) $c)[0] + [double]$en.B * (Get-LevelShapeRow $sh ([string[]]@('b')) $c)[0]) }
    $u.V = $vals
    $u.D0 = [int][math]::Round([double]$en.A); $u.D = $u.D0
    $ld = @(@($en.Levels) | Where-Object { $_ } | Sort-Object { Get-CurveDate $_ })
    $u.Memo = @{ Brand = [string]$en.Brand; A = [double]$en.A; S = [double]$en.S; B = [double]$en.B; N = [int]$en.N; Model = [string]$en.Model
                 Hist = @(@($en.Levels) | Where-Object { $_ } | ForEach-Object { @{ Date = [string]$_.Date; Delta = [int]$_.Delta } })
                 LastDate = $(if ($ld.Count -gt 0) { [string]$ld[-1].Date } else { [string]$en.Date }) }
}

function Get-LevelBrandVerified($u) {
    # Tete verifiee pour la memoire de marque : forme adaptee sans reserve et niveau verifie, ou niveau verifie sans nouvelle
    # adaptation (forme conforme ou approximative, sans bascule ni borne)
    # 12.8 (F3R, G5) : jamais une tete avec reserve de controle (e2) ni terme de centre, meme verifie (le format a, s, b de
    # la memoire de marque le perdrait) ; une courbe au-dela de CalHardNs (plafond par disquette) n en est pas exclue
    if ($null -eq $u.Head -or $u.Fail -or -not $u.Conv -or $u.Early -or $u.Sat -or $u.Low -or $u.Few) { return $false }
    if ([string]$u.Mode -eq 'adapte') { return [bool](@($u.AN.Reserve).Count -eq 0 -and -not $u.CtlReserve -and -not $u.AN.Center) }
    if ([string]$u.Mode -eq 'refus') { return $false }
    return [bool]($u.Shape -and @('ok', 'approx') -contains [string]$u.Shape.Verdict)
}

function Get-LevelBrandPlan($cal, [string]$brand) {
    # Effet de la marque sur chaque tete verifiee (§ 10.4, G5) : Differs : la disquette s ecarte de la marque memorisee
    # (nouvelle adaptation par rapport a la reference, ou niveau a plus de LevelFatigueNs de la mediane de la marque)
    # 12.8 (FIX1C, constat 2) : tete partie de la forme de cette marque (Memo) qui a declenche une adaptation (Trig) : la
    # forme de la marque n a pas ete retrouvee sur cette disquette, quel que soit le modele obtenu (forme de la reference
    # confirmee, M0, comprise) : nouvelle adaptation par rapport a la reference, donc Differs
    $plan = @()
    if (-not $brand) { return }
    foreach ($u in @($cal.Units)) {
        if (-not (Get-LevelBrandVerified $u)) { continue }
        $adapted = ([string]$u.Mode -eq 'adapte' -and [string]$u.AN.Model -ne 'M0')
        $fromBrand = [bool]($u.Memo -and $u.Trig -and (Get-LevelBrandKey ([string]$u.Memo.Brand)) -eq (Get-LevelBrandKey $brand))
        $en = Find-LevelBrand $brand ([string]$cal.Drive) ([string]$u.RefKey) ([string]$u.Tag)
        $valid = Test-LevelBrandValid $en $u.Cv ([string]$cal.Family)
        # 12.8 (S3) : entree a courbe complete qui n a pas servi de depart a cette tete (courbe d un autre calcul de
        # calibration, autre nombre de cylindres) : remplacee, comme une entree d une autre reference ; ses niveaux sont
        # relatifs a la courbe, pas a la reference
        if ($valid -and $null -ne $en.Curve -and -not ($u.Memo -and $u.Memo.Curve)) { $valid = $false }
        $why = ''
        if ($valid) {
            Update-LevelBrandStats $en
            if ($adapted) { $why = (T 'nouvelle adaptation : {0}') -f (Get-LevelShapeTerms $u.AN.Fit ($u.ShapeV.N - 1)) }
            elseif ($fromBrand -and [string]$u.Mode -eq 'adapte') { $why = (T "forme de la référence confirmée : cette disquette n'a pas la forme de la marque") }
            elseif ($fromBrand) { $why = (T "forme de la marque non retrouvée à la passe {0}") -f "$($u.Trig.Pass)" }
            elseif ([math]::Abs([int]$u.Level - [double]$en.A) -gt [double]$script:LevelFatigueNs) { $why = (T 'niveau {0} ns, médiane de la marque {1} ns') -f ('{0:+0;-0;0}' -f [int]$u.Level), (Format-LevelSigned $en.A) }
        }
        $plan += ,@{ U = $u; Entry = $(if ($valid) { $en } else { $null }); Old = $en; Adapted = $adapted; Differs = [bool]$why; Why = $why }
    }
    return $plan
}

function Update-LevelBrands($cal, [string]$brand, [bool]$explicit) {
    # 12.8 (lot 1c, § 10.4, G5) : memoire de la marque mise a jour apres un resultat accepte, tete par tete verifiee :
    # disquette conforme a la marque : niveau ajoute (forme ajoutee si elle a ete mesuree) ; disquette qui s en ecarte :
    # rien, sauf marque nommee dans la fenetre de decision (explicit : l entree est remplacee) ; marque sans entree pour
    # cette reference (nouvelle, ou reference changee) : entree creee ou remplacee. Tete refusee, avec reserve ou non
    # verifiee : rien
    if (-not $brand) { return }
    $date = Get-Date -Format 'dd/MM/yyyy HH:mm'
    foreach ($pl in @(Get-LevelBrandPlan $cal $brand)) {
        $u = $pl.U; $pfx = $u.Prefix
        if ($pl.Differs -and -not $explicit) {
            # 12.8 (FIX1C, constat 6) : la ligne n est ecrite que sans champ de marque dans la fenetre de decision (champ
            # affiche : marque nommee, donc explicit, ou laissee vide, donc rien) : conseil faisable, la prochaine fois
            Append-Log ($pfx + ((T "Forme non mémorisée pour la marque « {0} » : cette disquette s'en écarte ({1}). Si elle est d'une autre marque, choisissez celle-ci, ou « (non précisée) », dans l'avertissement de la prochaine calibration rapide.") -f "$brand", "$($pl.Why)"))
            continue
        }
        $s = 0.0; $b = 0.0; $model = 'M0'
        if ($pl.Adapted) { $co = $u.AN.Fit.Coef; $s = if ($co.ContainsKey('s')) { [double]$co['s'] } else { 0.0 }; $b = if ($co.ContainsKey('b')) { [double]$co['b'] } else { 0.0 }; $model = [string]$u.AN.Model }
        $en = $pl.Entry
        if (-not $en -or $pl.Differs) {
            # Entree creee, ou remplacee (reference changee, ou disquette differente nommee dans la fenetre)
            if ($pl.Old) { $old = $pl.Old; $script:LevelBrands = @(@($script:LevelBrands) | Where-Object { -not [object]::ReferenceEquals($_, $old) }) }
            $en = @{ Brand = $brand; Drive = [string]$cal.Drive; RefKey = [string]$u.RefKey; Tag = [string]$u.Tag; Head = $u.Head; Family = [string]$cal.Family
                     RefDate = [string]$u.Cv.Date; LevelAlgo = 'lvl2'; Model = $model; A = 0.0; S = 0.0; B = 0.0; N = 0; Date = $date; Levels = @(); Shapes = @() }
            $script:LevelBrands = @(@($script:LevelBrands) + @($en))
        }
        $en.Levels = @(@(@($en.Levels) + @(@{ Date = $date; Delta = [int]$u.Level })) | Select-Object -Last ([int]$script:LevelBrandKeepLevels))
        if ($pl.Adapted) { $en.Shapes = @(@(@($en.Shapes) + @(@{ Date = $date; S = [math]::Round($s, 4); B = [math]::Round($b, 2) })) | Select-Object -Last ([int]$script:LevelBrandKeepShapes)); $en.Model = $model }
        $en.Date = $date; $en.Brand = $brand
        Update-LevelBrandStats $en
        # 12.8 (S3) : entree a courbe complete (depart de cette tete) : niveau ajoute, courbe gardee
        if ($null -ne $en.Curve) { Append-Log ((T '{0}Niveau mémorisé pour la marque « {1} », courbe complète du {2} : niveau {3} ns ({4} mesure(s)).') -f "$pfx", "$brand", "$($en.CurveDate)", (Format-LevelSigned $en.A), "$($en.N)") }
        else { Append-Log ((T '{0}Forme mémorisée pour la marque « {1} » : niveau {2} ns, échelle {3} %, pente {4} ns ({5} mesure(s)).') -f "$pfx", "$brand", (Format-LevelSigned $en.A), (Format-UiNum ([math]::Round(100 * [double]$en.S, 1)) '+0.0;-0.0;0.0'), (Format-LevelSigned $en.B), "$($en.N)") }
    }
    $script:LevelBrand = $brand
    # Entrees gardees : les LevelBrandMax plus recentes
    $all = @(@($script:LevelBrands) | Where-Object { $_ })
    if ($all.Count -gt $script:LevelBrandMax) { $script:LevelBrands = @($all | Sort-Object { Get-CurveDate $_ } -Descending | Select-Object -First ([int]$script:LevelBrandMax)) }
}

function Test-LevelAdaptedSpec([string[]]$specs) {
    # 12.8 (FIX1C, constat 3, G1) : un profil --precomp ecrit est-il la courbe adaptee d une calibration rapide
    # (enregistrement de $script:LevelShifts au modele autre que M0 : forme ajustee, ou forme d une marque au depart) ?
    # G1 suit la courbe ecrite, pas le chemin : bouton Calibrer au test rapide, puis ECRIRE sans nouvelle mesure (test
    # standard ou fin, profil Manuel) ; un profil modifie a la main n est plus cette courbe
    $set = @{}
    foreach ($s in @($specs)) { if ($s -and ([string]$s).Trim()) { $set[([string]$s).Trim()] = $true } }
    if ($set.Count -eq 0 -or -not $script:LevelShifts) { return $false }
    foreach ($k in @($script:LevelShifts.Keys)) {
        $r = $script:LevelShifts[$k]
        if ($r -and $r.Model -and [string]$r.Model -ne 'M0' -and $r.Spec -and $set.ContainsKey(([string]$r.Spec).Trim())) {
            # 12.8 (S3, c4-design § 4.2) : courbe d une mesure complete de cette disquette : mesuree sur tous ses cylindres,
            # controle impose seulement au-dela de 400 ns (ou de precompMaxNs reglee plus haut), comme le plafond par disquette
            if ([string]$r.Model -eq 'mesure') { if (@(@($r.Values) | Where-Object { [int]$_ -gt (Get-DiskOverNs) }).Count -gt 0) { return $true }; continue }
            return $true
        }
    }
    return $false
}

function Get-DiskCellNs([int]$bits) {
    # 12.11 : cellule (ns) d une piste de $bits cellules a 300 tr/min (un tour de 200 ms) : celle du plafond par disquette
    # (Get-DiskCapNs) et de la ligne de journal qui l annonce (Get-DiskBoundText) ; jamais appelee sans cellules ($bits a 0)
    return 200000000.0 / $bits
}

function Get-DiskCapNs([int]$bits = 0) {
    # 12.11 : plafond de precompensation d une disquette, seule decision : quart (CalDiskCapCell) de la cellule de la piste
    # ecrite, arrondi au ns inferieur, CalDiskCapMaxNs (500 ns) au plus. $bits : cellules par piste rendues par
    # Get-DiskCapBits (motif de la calibration en cours, ou format gw au-dela de 250 kbit/s). Au quart de la cellule, un
    # intervalle ecrit atteint sa frontiere de decision : 500 ns pour 2 us, 493 ns pour un ADF AmigaDOS (101 344 cellules),
    # 472 a 474 ns en long track (105 808 a 105 312 cellules), au lieu de CalHardMaxNs (470 ns) pour toutes jusqu a la
    # 12.10. Sans densite ($bits a 0 : suite sans interface, carte de l Accueil, cellule de la piste ecrite inconnue de Get-DiskCapBits) : CalHardMaxNs. Aucun cas particulier
    # pour la haute densite, qui n emprunte aucun chemin du plafond par disquette (Get-LevelRef la refuse). Aucune mesure
    # sur materiel au-dela de 470 ns : la regle repose sur la simulation du decodage (560)
    if ($bits -le 0) { return [int]$script:CalHardMaxNs }
    return [int][math]::Min([double]$script:CalDiskCapMaxNs, [math]::Floor([double]$script:CalDiskCapCell * (Get-DiskCellNs $bits)))
}

function Get-UnitCapNs($u) {
    # 12.11 : plafond par disquette d une unite de la calibration rapide : cellules de la piste ecrite gardees par
    # New-LevelCalUnits (ImgBits, Get-DiskCapBits) ; unite sans ce champ : repli de Get-DiskCapNs (CalHardMaxNs)
    $b = 0
    if ($u -and $null -ne $u.ImgBits) { $b = [int]$u.ImgBits }
    return (Get-DiskCapNs $b)
}

function Get-BoundAdviceNs($u) {
    # 12.11 (L12a) : borne precompMaxNs la plus haute que le journal et la fenetre de decision conseillent quand une courbe de
    # la calibration rapide sature a la borne (« la borne se regle jusqu a {2} ns », 260 et 265, forme adaptee, forme d une
    # marque, courbe de refus) : haut de la plage du reglage (CalHardMaxNs), jamais au-dela du plafond de l image de l unite
    # (Get-UnitCapNs : quart de la cellule de la piste ecrite, Get-DiskCapNs ; 470 ns sans densite, valeur de la 12.10).
    # Borne deja reglee a cette valeur ou plus haut : aucun conseil de la relever. Texte seul : aucune valeur de courbe
    return [int][math]::Min([int]$script:CalHardMaxNs, [int](Get-UnitCapNs $u))
}

function Get-DiskCapBits([int]$bits, [string]$fmt = '', [bool]$known = $false) {
    # 12.11 : cellules par piste retenues pour le plafond par disquette (Get-DiskCapNs) : celles de la piste ecrite. Le motif
    # d une image secteur est mesure a 2 us (100 000 cellules, Get-PatternBits) quel que soit le format ; un format gw double
    # densite dont le debit depasse 250 kbit/s (atari.130, atarist.440, atarist.880 : 260 et 261 kbit/s, Get-FormatCalibInfo)
    # ecrit 400 x debit cellules par piste : le plafond suit cette cellule, plus courte (478 ns et non 500 a 261 kbit/s).
    # $fmt : format de l onglet Ecriture. Sans densite ($bits a 0) : 0. $bits : champ CapBits du motif (Get-PatternBits, 240 :
    # piste la plus longue d un IPF ou d un HFE, donc cellule la plus courte ; sinon cellules du motif)
    # 12.11 (lot L4b) : 0 aussi (sans densite : plafond de 470 ns, comme en 12.10) quand la cellule de la piste ecrite n est
    # pas connue : format explicite absent de la table (gw plus recent, fichier diskdefs : la liste Format admet une saisie
    # libre), ou aucun format (vide, « (auto) ») et densite du motif non tiree de l image ($known : champ Known du motif,
    # Get-PatternBits : ADF, IPF, HFE dont la longueur des pistes est lue ; faux pour un HFE v3, et pour une image secteur
    # dont gw deduit ou exige le format : D81, FD, MGT, IMG, MSA..., que le bouton « Calibrer » en test rapide admet). Le
    # plafond ne depasse donc CalHardMaxNs que pour un format de la table ou une densite lue dans l image
    if ($bits -le 0) { return 0 }
    if ($fmt -and $fmt -ne '(auto)') {
        if (-not $script:GwFormats.Contains($fmt)) { return 0 }
        $e = $script:GwFormats[$fmt]
        # 12.11 : cellules du codec du format (Get-FormatCalibInfo, 200 : 101 344 pour amiga.amigados, que gw ecrit quelle que
        # soit l image, ADF ou non) : jamais moins que celles-ci
        $fb = [int](Get-FormatCalibInfo $fmt).Bits
        if ($fb -gt $bits) { $bits = $fb }
        if ([int]$e.Rpm -eq 300 -and [int]$e.Rate -gt 250 -and [int]$e.Rate -lt 450) { return [int][math]::Max($bits, 400 * [int]$e.Rate) }
        return $bits
    }
    if ($known) { return $bits }
    return 0
}

function Get-DiskBoundText([int]$hard, [int]$bits = 0, $pat = $null) {
    # 12.11 (lot L4b) : ligne de journal de la borne, au debut de la mesure complete de cette disquette (Start-PrecompCalib),
    # tiree de la decision du plafond. $hard : borne posee (Get-DiskHardNs) ; $bits : cellules de la piste ecrite
    # (Get-DiskCapBits). Borne au plus au seuil du controle impose (Get-DiskOverNs) : borne precompMaxNs ; au-dela, cellule
    # connue : quart de la cellule annonce ; cellule inconnue ($bits a 0, Get-DiskCapNs rend CalHardMaxNs) : ligne de la
    # 12.10, sans cellule (aucune division par zero : Get-DiskCellNs n est appelee qu avec des cellules)
    # 12.11 (L12a) : $pat, motif de la calibration (New-CalibPattern). Cellules retenues par Get-DiskCapBits egales a celles de
    # la piste la plus longue de l image (CapBits) quand elles depassent la densite du motif (Bits, mediane des pistes) : IPF
    # ou HFE aux pistes inegales ; la ligne nomme alors cette piste, la ligne « Motif de test » annoncant la densite mediane
    $thr = Get-DiskOverNs
    if ($hard -le $thr) { return ((T "Borne de la courbe de cette disquette : {0} ns (precompMaxNs).") -f "$hard") }
    if ($bits -le 0) { return ((T "Borne de la courbe de cette disquette : {0} ns ; au-delà de {1} ns, contrôle après écriture imposé.") -f "$hard", "$thr") }
    $cell = "$([int][math]::Round((Get-DiskCellNs $bits)))"
    if ($pat -and [int]$pat.CapBits -gt [int]$pat.Bits -and $bits -eq [int]$pat.CapBits) {
        return ((T "Borne de la courbe de cette disquette : {0} ns, le quart de la cellule de la piste la plus longue de l'image ({2} ns), {3} ns au plus ; au-delà de {1} ns, contrôle après écriture imposé.") -f "$hard", "$thr", $cell, "$($script:CalDiskCapMaxNs)")
    }
    return ((T "Borne de la courbe de cette disquette : {0} ns, le quart de la cellule de l'image ({2} ns), {3} ns au plus ; au-delà de {1} ns, contrôle après écriture imposé.") -f "$hard", "$thr", $cell, "$($script:CalDiskCapMaxNs)")
}

function Get-DiskOverAdviceText([int]$thr) {
    # 12.11 : conseil « machine cible », ecrit au journal apres chaque ligne « ... au-dela de {0} ns ... » d une courbe
    # portee au-dela de la borne pour une disquette (forme adaptee, forme d une marque, mesure complete de cette disquette)
    return ((T "Au-delà de {0} ns, la calibration ne compense que la chaîne d'écriture et de relecture de ce lecteur : essayez la disquette écrite sur la machine à laquelle elle est destinée (un vrai Amiga, par exemple) avant de vous y fier.") -f "$thr")
}

function Get-DiskHardNs([int]$bits = 0) {
    # 12.8 (S3, decisions du 21/10/2026) : borne de la courbe d une seule disquette (mesure complete de cette disquette,
    # courbe complete d une marque) : plafond par disquette (12.11 : Get-DiskCapNs de la densite $bits ; 470 ns jusqu a la
    # 12.10), ou la borne precompMaxNs si elle est plus haute ; borne reglee sous CalHardNsDefault (400 ns) : celle de l
    # utilisateur, sans relevement par disquette (decision 3)
    $user = [int]$script:CalHardNsUser
    if ($user -lt [int]$script:CalHardNsDefault) { return $user }
    return [int][math]::Max($user, (Get-DiskCapNs $bits))
}

function Get-DiskOverNs {
    # 12.8 (S3) : seuil du controle apres ecriture impose d une courbe de cette disquette : max(400 ns, precompMaxNs), comme
    # le declenchement du plafond par disquette de la calibration rapide (F3R-FIX, constat 4)
    return [int][math]::Max([int]$script:CalHardNsDefault, [int]$script:CalHardNsUser)
}

function Get-DiskRefUnit($cal, $u) {
    # 12.8 (S3) : reference en place d une tete de la mesure complete de cette disquette (unite de Get-LevelRef gardee dans
    # $cal.DiskRef : RefKey, Tag, Head, Cv) ; $null sans elle
    if (-not $cal -or -not $cal.DiskRef) { return $null }
    $m = @(@($cal.DiskRef.Units) | Where-Object { $_ -and $_.Head -eq $u.Head })
    if ($m.Count -gt 0) { return $m[0] }
    return $null
}

function Test-LevelBrandCurve($en, [int]$nRef) {
    # 12.8 (S3) : courbe complete d une entree de marque utilisable comme point de depart : calcul de calibration actuel
    # (CalibCalc ; un autre calcul : « a remesurer »), au moins 2 valeurs, 4 cylindres d ecart au plus avec la reference
    # (seuil de Get-LevelRef)
    if (-not $en -or $null -eq $en.Curve) { return $false }
    $n = @($en.Curve).Count
    return [bool]($n -ge 2 -and [string]$en.CurveCalc -eq [string]$script:CalibCalc -and [math]::Abs($n - $nRef) -le 4)
}

function Get-LevelBrandCurveValues($en, $vref, [int]$bits = 0) {
    # 12.8 (S3) : courbe de la marque ramenee aux cylindres de la reference : valeurs en trop retirees ; cylindres manquants
    # (reference plus longue) : reference decalee de l ecart du dernier cylindre de la courbe ; bornee a 0..Get-DiskHardNs
    # (12.11 : de la densite $bits de l image a ecrire)
    $cap = Get-DiskHardNs $bits
    $cv = @($en.Curve); $rv = @($vref); $n = $rv.Count; $m = $cv.Count
    $off = [double]$cv[$m - 1] - [double]$rv[[math]::Min($m, $n) - 1]
    $out = New-Object int[] $n
    for ($c = 0; $c -lt $n; $c++) {
        $x = if ($c -lt $m) { [double]$cv[$c] } else { [double]$rv[$c] + $off }
        $out[$c] = [int][math]::Max(0, [math]::Min($cap, [math]::Round($x)))
    }
    return ,$out
}

function Get-DiskSpotCyls($u, [int]$n) {
    # 12.8 (S3) : cylindres d une mesure complete exclus de la courbe d une marque : ecart isole (Outliers), zone non
    # reproductible (Contra), cylindres non reproductibles d une verification a l autre (NonRepro), ecarts locaux hors
    # tolerance non corriges (Spot) ; jamais un defaut de cette disquette dans la courbe de la marque
    $b = @{}
    foreach ($c in @($u.Outliers)) { if ($null -ne $c) { $b[[int]$c] = $true } }
    if ($u.Warn) {
        foreach ($c in @($u.Warn.Contra)) { if ($null -ne $c) { $b[[int]$c] = $true } }
        if ($u.Warn.Drift -and $u.Warn.Drift.NonRepro) { foreach ($k in @($u.Warn.Drift.NonRepro.Keys)) { $b[[int]$k] = $true } }
        foreach ($s in @($u.Warn.Spot)) { if ([string]$s -match '^c(\d+)') { $b[[int]$Matches[1]] = $true } }
    }
    return ,[int[]]@(@($b.Keys) | ForEach-Object { [int]$_ } | Where-Object { $_ -ge 0 -and $_ -lt $n } | Sort-Object)
}

function Update-LevelBrandCurve($cal, [string]$brand) {
    # 12.8 (S3, c4-design § 4.2) : memoire de la marque apres une mesure complete de cette disquette acceptee, tete par
    # tete : tete sans reserve (DiskOk, Complete-DiskMeasure), reference en place (Get-DiskRefUnit). Ecart a la reference
    # d(c) = courbe - reference, ajuste par niveau, echelle et pente (Get-LevelWls) hors cylindres exclus (Get-DiskSpotCyls) :
    # ecart de forme residuel jusqu a LevelTauMax et moins de 2 cylindres hors de la forme (forme conforme ou approximative
    # au sens de la calibration rapide) : entree (a, s, b) sans courbe, termes de forme gardes au-dela de LevelAdaptCoefZ
    # erreurs-types ; sinon : courbe
    # complete de la tete, cylindres exclus remplaces par l interpolation lineaire de leurs voisins dans leur segment
    # monotone, niveau 0 (J-M1). L entree de la marque pour cette tete (meme lecteur, cle, tete) est remplacee : la mesure
    # complete fait foi. Tete avec reserve : rien
    if (-not $brand) { return }
    $date = Get-Date -Format 'dd/MM/yyyy HH:mm'
    foreach ($u in @($cal.Units)) {
        if ($null -eq $u.Head -or -not $u.Fit) { continue }
        $pfx = $u.Prefix
        if (-not $u.DiskOk) { Append-Log ((T "{0}Rien n'est mémorisé pour la marque « {1} » : cette tête a une réserve.") -f "$pfx", "$brand"); continue }
        $ru = Get-DiskRefUnit $cal $u
        if (-not $ru) { continue }
        $vals = @($u.Fit.Values); $vref = @($ru.Cv.Values)
        $n = [math]::Min($vals.Count, $vref.Count)
        if ($n -lt 2) { continue }
        $bad = Get-DiskSpotCyls $u $n
        $cs = [int[]]@(0..($n - 1) | Where-Object { $bad -notcontains $_ })
        $d = @{}; $sig = @{}
        for ($c = 0; $c -lt $n; $c++) {
            $d[$c] = [double]$vals[$c] - [double]$vref[$c]
            $sig[$c] = if ($u.Sig -and $u.Sig.ContainsKey($c)) { [double]$u.Sig[$c] } else { 5.0 }
        }
        $sh = New-LevelShape ([int[]]@($vref[0..($n - 1)]))
        $fit = Get-LevelWls $sh ([string[]]@('a', 's', 'b')) $cs $d $sig
        # Forme expliquee par niveau, echelle et pente au sens de la calibration rapide (Test-LevelShape, Get-LevelStats) :
        # ecart de forme residuel jusqu a LevelTauMax et moins de 2 cylindres hors de la forme de plus de max(15 ns ; 4 et.)
        $nOut = 0
        if ($fit) { foreach ($c in $cs) { if ([math]::Abs([double]$fit.Res[$c]) -gt [math]::Max(15.0, 4.0 * [double]$sig[$c])) { $nOut++ } } }
        $old = Find-LevelBrand $brand ([string]$cal.Drive) ([string]$ru.RefKey) ([string]$ru.Tag)
        if ($old) { $script:LevelBrands = @(@($script:LevelBrands) | Where-Object { -not [object]::ReferenceEquals($_, $old) }) }
        $en = @{ Brand = $brand; Drive = [string]$cal.Drive; RefKey = [string]$ru.RefKey; Tag = [string]$ru.Tag; Head = $u.Head; Family = [string]$cal.Family
                 RefDate = [string]$ru.Cv.Date; LevelAlgo = 'lvl2'; Model = 'M0'; A = 0.0; S = 0.0; B = 0.0; N = 0; Date = $date; Levels = @(); Shapes = @()
                 Curve = $null; CurveDate = ''; CurveCalc = ''; CurveMaxNs = 0; CurveSrc = '' }
        if ($fit -and [double]$fit.Tau -le [double]$script:LevelTauMax -and $nOut -lt 2) {
            # Forme expliquee par niveau, echelle et pente : entree (a, s, b), termes non significatifs retires (nouvel ajustement)
            $names = @('a')
            for ($i = 1; $i -lt 3; $i++) { $se = [math]::Sqrt([math]::Max(1e-12, [double]$fit.Cov[$i][$i])); if ([math]::Abs([double]$fit.Beta[$i]) -ge $script:LevelAdaptCoefZ * $se) { $names += [string]$fit.Names[$i] } }
            $f2 = if ($names.Count -lt 3) { Get-LevelWls $sh ([string[]]$names) $cs $d $sig } else { $fit }
            if (-not $f2) { $f2 = $fit; $names = @('a', 's', 'b') }
            $co = $f2.Coef
            $s = if ($co.ContainsKey('s')) { [double]$co['s'] } else { 0.0 }; $b = if ($co.ContainsKey('b')) { [double]$co['b'] } else { 0.0 }
            $en.Model = switch ($names -join ',') { 'a,s' { 'Ms' } 'a,b' { 'Mb' } 'a,s,b' { 'Msb' } default { 'M0' } }
            $en.Levels = @(@{ Date = $date; Delta = [int][math]::Round([double]$co['a']) })
            if ($names.Count -gt 1) { $en.Shapes = @(@{ Date = $date; S = [math]::Round($s, 4); B = [math]::Round($b, 2) }) }
            Update-LevelBrandStats $en
            $script:LevelBrands = @(@($script:LevelBrands) + @($en))
            Append-Log ((T '{0}Forme mémorisée pour la marque « {1} » : niveau {2} ns, échelle {3} %, pente {4} ns ({5} mesure(s)).') -f "$pfx", "$brand", (Format-LevelSigned $en.A), (Format-UiNum ([math]::Round(100 * [double]$en.S, 1)) '+0.0;-0.0;0.0'), (Format-LevelSigned $en.B), "$($en.N)")
            continue
        }
        # Forme non expliquee par niveau, echelle et pente : courbe complete de la tete, cylindres exclus interpoles dans
        # leur segment (changements de sens Breaks de la courbe)
        $cur = New-Object int[] $vals.Count
        for ($c = 0; $c -lt $vals.Count; $c++) { $cur[$c] = [int]$vals[$c] }
        $brk = @(@(@($u.Fit.Breaks) + @(Get-FitDents $u.Fit | ForEach-Object { [int]$_.C2 })) | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_ } | Sort-Object)
        foreach ($c in $bad) {
            $lo = 0; $hi = $vals.Count - 1
            foreach ($bk in $brk) { if ($bk -le $c -and $bk -gt $lo) { $lo = $bk }; if ($bk -gt $c -and $bk - 1 -lt $hi) { $hi = $bk - 1 } }
            $l = $c - 1; while ($l -ge $lo -and $bad -contains $l) { $l-- }
            $r = $c + 1; while ($r -le $hi -and $bad -contains $r) { $r++ }
            if ($l -ge $lo -and $r -le $hi) { $cur[$c] = [int][math]::Round([double]$vals[$l] + ($c - $l) * ([double]$vals[$r] - [double]$vals[$l]) / ($r - $l)) }
            elseif ($l -ge $lo) { $cur[$c] = [int]$vals[$l] }
            elseif ($r -le $hi) { $cur[$c] = [int]$vals[$r] }
        }
        $en.Model = 'Mc'; $en.Levels = @(@{ Date = $date; Delta = 0 })
        $en.Curve = [int[]]$cur; $en.CurveDate = $date; $en.CurveCalc = [string]$script:CalibCalc; $en.CurveMaxNs = [int]$cal.HardNs; $en.CurveSrc = 'complete'
        Update-LevelBrandStats $en
        $script:LevelBrands = @(@($script:LevelBrands) + @($en))
        Append-Log ((T '{0}Courbe complète mémorisée pour la marque « {1} » ({2} cylindres ; écarts isolés exclus : {3}).') -f "$pfx", "$brand", "$($cur.Count)", $(if ($bad.Count -gt 0) { Format-CylList ([int[]]$bad) } else { (T 'aucun') }))
    }
    $script:LevelBrand = $brand
    $all = @(@($script:LevelBrands) | Where-Object { $_ })
    if ($all.Count -gt $script:LevelBrandMax) { $script:LevelBrands = @($all | Sort-Object { Get-CurveDate $_ } -Descending | Select-Object -First ([int]$script:LevelBrandMax)) }
}

function Get-LevelBrandCurveGuard($cal) {
    # 12.8 (S3, c4-design § 4.2) : garde de la passe 1 d une tete partie de la courbe complete d une marque (Memo.Curve) :
    # adaptation declenchee, forme non conforme a cette courbe, ou niveau a plus de LevelFatigueNs de celui de la marque.
    # Renvoie @{ Brand ; Why } (calibration rapide arretee, choix W-M2 : Stop-LevelBrandCurve), sinon $null
    foreach ($u in @($cal.Units)) {
        if (-not ($u.Memo -and $u.Memo.Curve) -or $u.Fail) { continue }
        $why = ''
        if ($u.Trig) { $why = (T 'adaptation déclenchée : {0}') -f (@($u.Trig.Reasons) -join ' ; ') }
        elseif ($u.Est) {
            $sh = Test-LevelShape $u.Est $u 1.0
            if ($sh.Verdict -eq 'mismatch') { $why = (T 'forme non conforme : {0}') -f (@($sh.Reasons) -join ' ; ') }
            elseif (-not [double]::IsNaN([double]$u.Est.Delta) -and [math]::Abs([double]$u.Est.Delta - [double]$u.Memo.A) -gt [double]$script:LevelFatigueNs) {
                $why = (T 'niveau {0} ns par rapport à la courbe de la marque') -f ('{0:+0;-0;0}' -f [math]::Round([double]$u.Est.Delta, 0))
            }
        }
        if ($why) { return @{ Brand = [string]$u.Memo.Brand; Why = ([string]$u.Prefix + $why) } }
    }
    return $null
}

function Get-LevelBrandsOfRef([string]$key, [string]$refDate, [string]$drive) {
    # Marques memorisees avec une reference (cle, date, lecteur) : invalidees par une nouvelle reference (§ 10.5)
    return @(@($script:LevelBrands) | Where-Object { $_ -and [string]$_.RefKey -eq $key -and [string]$_.RefDate -eq $refDate -and [string]$_.Drive -eq $drive } | ForEach-Object { [string]$_.Brand } | Sort-Object -Unique)
}
# ============================== FONCTIONS : CALIBRATION COMPLETE ===============

function Start-PrecompCalib([switch]$ForceFine, [string]$Intro = '', [switch]$LevelAfter, $Geom = $null, $Heads = $null, [string]$Test = '', [switch]$NoWarmup) {
    # ForceFine : test fin impose (reference de la calibration rapide) ; Intro : texte place en tete de l avertissement ;
    # LevelAfter : apres une calibration sur disquette sacrifiee, le niveau de la disquette a ecrire est mesure.
    # Carte Calibration de l Accueil : Geom (type de disquette, image de geometrie), Heads (une courbe par tete) et Test
    # ('std' ou 'fine') a la place de l image, de la case Ecriture lente et du mode de l onglet Ecriture ; NoWarmup :
    # prechauffage du lecteur desactive pour cette calibration (case de la fenetre de la carte).
    # 12.8 (lot 1c, point 3) : repli « Calibration complete » de la calibration rapide ($script:CalFallbackAsk, pose par
    # Start-LevelFallback ; lu et remis a $null ici, avant toute sortie) : confirmation commune frmConfirm (Show-AppConfirm),
    # sans compte a rebours, case « disquette sacrifiee » obligatoire. Variable et non parametre : signature inchangee
    # (enveloppes de make-test et des fins de test)
    $fb = $script:CalFallbackAsk; $script:CalFallbackAsk = $null
    # 12.8 (S3, decision du 21/10/2026) : « Mesure complete de cette disquette » ($script:CalDiskOnly, pose par
    # Start-DiskMeasure ; lu et remis a $null ici, avant toute sortie) : test fin, une courbe par tete, sur la disquette a
    # ecrire, borne par disquette ; confirmation frmConfirm sans compte a rebours, case « Cette disquette sera effacee »
    # obligatoire, marque de la disquette ; la reference du lecteur n est pas modifiee (Complete-DiskMeasure)
    $do = $script:CalDiskOnly; $script:CalDiskOnly = $null
    # 12.10 : calibration croisee ($script:CalCrossAsk = @{ Src ; Tgt }, pose par Start-CrossCalib ; lu et remis a $null ici,
    # avant toute sortie) : la source (lecteur du bandeau) ecrit, la cible relit, la disquette passe de l un a l autre a la
    # main (Invoke-CalibSwap) ; avertissement sans compte a rebours, case « disquette sacrifiee dans la source » obligatoire
    $cx = $script:CalCrossAsk; $script:CalCrossAsk = $null
    if ($script:GwProc -and -not $script:GwProc.HasExited) { return }
    $script:Cal = $null
    # 12.11 (lot LN-b) : avec des lecteurs enregistres, lecteur branche confirme s il y a lieu (Confirm-DriveIdentity, 112) ;
    # refus : calibration non lancee ($script:Cal vide, que lisent les appelants)
    if ($script:DriveReg.Count -gt 0 -and -not (Confirm-DriveIdentity)) { return }
    $chk = Test-CalibImage $Geom
    if (-not $chk) { return }
    $img = $chk.Img; $family = $chk.Family; $nCyl = $chk.NCyl; $maxCyl = $chk.MaxCyl; $cylSrc = $chk.CylSrc
    $fine = ([bool]$ForceFine -or $(if ($Test) { $Test -eq 'fine' } else { $cmbWCalMode.SelectedIndex -eq 1 }))
    $slow = if ($null -ne $Heads) { [bool]$Heads } else { [bool]$chkWSlow.Checked }
    if ($fine) { $cyls = @(0..$maxCyl) }
    else { $cyls = @(0..$maxCyl | Where-Object { $_ % 10 -eq 0 }); if ($cyls -notcontains $maxCyl) { $cyls += $maxCyl } }
    $cyls = @($cyls | Sort-Object -Unique)
    # 12.7 : calibration B (« Refaire sur une autre disquette ») : reglages de la calibration A controles avant le premier gw
    $redo = [bool]($script:CalRedo -and $script:CalRedo.Stage -eq 'confirm')
    if ($redo) {
        $why = Get-CalibRedoMismatch $script:CalRedo.ACal $family $cyls $slow $fine "$($cmbDrive.Text)" $img $Geom
        if ($why) { [void](Show-AppMessage ((T "Calibration B impossible : réglage différent de la calibration A ({0}). La décision sur la courbe A est rouverte.") -f "$why") (T 'Calibration precomp') 'OK' 'Warning'); return }
    }
    $nPassEst = $script:CalCoarse.Count + $script:CalMaxVerify
    # 12.8 (D6) : prechauffage avant une calibration complete : choix de l appelant (case de la carte « Calibrer le
    # lecteur », calibration B : celui de A), sinon reglage warmFullCalib (case de l onglet Ecriture : bouton Calibrer,
    # calibration automatique avant une ecriture, restauration)
    $noWarm = if ($PSBoundParameters.ContainsKey('NoWarmup')) { [bool]$NoWarmup } else { -not [bool](Get-Setting 'warmFullCalib') }
    # Duree estimee : passes d ecriture et de relecture, plus le prechauffage du lecteur (borne haute : il est reduit ou
    # saute si le lecteur vient de servir, plan recalcule apres l avertissement par Start-CalibWarmup)
    # 12.8.2 (revue) : effacement haute frequence de chaque passe en double densite compris (Get-CalibEraseEst, 150)
    $wu = if ($noWarm) { 0.0 } else { [math]::Max(0.0, [double]$script:CalWarmupMinutes) }
    $estEr = Get-CalibEraseEst ([string]$family -eq 'hd')
    # 12.9 (correction 1) : conditionnement du lecteur avant la passe 1 (double densite, bareme de la famille : Set-CalibScale
    # n est appele qu apres l avertissement) : une ecriture sans relecture de tous les cylindres de l image (2 faces),
    # effacement haute frequence compris, au rythme de la duree estimee (0,7 s par piste et par phase)
    $cond = [bool]$(if ([string]$family -eq 'hd') { $script:CalScaleHd.CalCondPass } else { $script:CalScaleDd.CalCondPass })
    $condMin = if ($cond) { ($maxCyl + 1) * 2 * (0.7 + $estEr) / 60 } else { 0.0 }
    $minutes = [math]::Max(1, [math]::Round($cyls.Count * 2 * (1.4 + $estEr) * $nPassEst / 60 + $condMin + $wu, 0))
    $modeTxt = if ($fine) { (T 'test fin, tous les cylindres') } else { (T 'test standard, un cylindre sur 10') }
    if ($slow) { $modeTxt += (T ', une courbe par tête (écriture lente)') }
    $famTxt = Get-CalibFamilyName $family
    $cylList = Format-CylList $cyls
    $script:AlignLoop = $false; $script:AlignNextAt = $null
    # Avertissement (usure du support) : validation automatique au bout du delai ; avant une ecriture, case « disquette
    # sacrifiee » : la disquette a ecrire est redemandee apres la calibration (Complete-PrecompCalib)
    $toWrite = ($script:AfterCalib -eq 'write')
    $target = if ($script:Restore) { (T 'la disquette de destination') } else { (T 'la disquette à écrire') }
    $auto = if ($toWrite) { (T "Calibration automatique avant l'écriture : la disquette insérée reçoit d'abord le motif de test, puis l'image.") + "`n`n" } else { '' }
    $bodyFmt = if ($Geom) { (T "Calibration de la précompensation sur le lecteur {0} ({1}).`n`nType de disquette : {2}, famille {3}, {4}.`nMotif de test : données pseudo-aléatoires générées à la densité de ce type.`nCylindres de test : {5} (2 faces), ÉCRASÉS à chaque passe. Durée estimée : {6} min pour {7} passes.") }
               else { (T "Calibration de la précompensation sur le lecteur {0} ({1}).`n`nImage : {2}, famille {3}, {4}.`nMotif de test : données pseudo-aléatoires générées à la densité de l'image, son contenu n'est pas écrit.`nCylindres de test : {5} (2 faces), ÉCRASÉS à chaque passe. Durée estimée : {6} min pour {7} passes.") }
    $body = $bodyFmt -f "$($cmbDrive.Text)", "$modeTxt", "$($chk.Label)", "$famTxt", "$cylSrc", "$cylList", "$minutes", "$nPassEst"
    # 12.8 (lot 1b) : nouvel essai automatique des cylindres non converges : supplement borne d une passe de verification
    # ciblee (Get-CalibRetestMinutes), et non un total (la duree estimee ne compte ni l encadrement ni les mesures
    # complementaires du test standard)
    $minRetest = Get-CalibRetestMinutes $cyls.Count $maxCyl $fine $estEr
    $body += "`n" + ((T "Si des cylindres restent non convergés, un nouvel essai automatique ajoute au plus {0} min (une passe de vérification ciblée).") -f "$minRetest")
    if ($wu -gt 0) { $body += "`n" + ((T "Préchauffage du lecteur avant la première passe : jusqu'à {0} de lecture sans écriture (moins si le lecteur vient de servir), compris dans la durée estimée.") -f (Format-CalDuration (60 * $wu))) }
    if ($cond) { $body += "`n" + ((T "Avant la première passe, le lecteur est conditionné par une écriture du motif sur les cylindres {0} (2 faces), sans relecture : environ {1} min, comprises dans la durée estimée.") -f "0-$maxCyl", "$([math]::Max(1, [math]::Round($condMin, 0)))") }
    # Courbe remplacee d un autre nombre de cylindres (plus de 4 d ecart, seuil de Get-LevelRef) : la nouvelle s applique
    # ensuite a toutes les images de la famille (meme phrase que la fenetre de la carte Calibration de l Accueil)
    $cvr = $script:PrecompCurves[$(if ($slow) { "${family}_h0" } else { $family })]
    if ($cx) { $cvr = Get-DriveCurve "$($cx.Src)>$($cx.Tgt)" $(if ($slow) { "${family}_h0" } else { $family }) }   # 12.10 : courbe croisee precedente
    if ($cvr -and [math]::Abs(@($cvr.Values).Count - $nCyl) -gt 4) { $body += "`n" + ((T "La courbe actuelle couvre {0} cylindres : elle sera remplacée par une courbe de {1} cylindres, appliquée à toutes les images de la famille {2}.") -f "$(@($cvr.Values).Count)", "$nCyl", "$famTxt") }
    # Passes supplementaires possibles : encadrement (1), mesures complementaires du test standard (2, 30 cylindres au plus).
    # Ecritures par piste au plus : $nPassMax, celui de la 12.7. 12.8 (lot 1b) : le nouvel essai des cylindres non converges
    # le respecte (decisions128.md : « nombre d ecritures par piste respecte ») : WriteMax, garde de Get-CalibRetestPlan et
    # de Add-DriftWitnesses ; une piste deja ecrite $nPassMax fois n est ni visee, ni relue, ni temoin. 12.9 (correction 1) :
    # une ecriture de plus par piste, celle du conditionnement du lecteur. 12.9 (banc cal2, G3-01 et G4-01, option A) :
    # calcul 12.9 de la double densite, reconnu au meme indicateur que le conditionnement ($cond : CalCondPass du bareme de
    # la famille, faux en haute densite) : l encadrement commence a 100 ns et prenait l ecriture que la 12.8 partageait
    # entre l encadrement et le nouvel essai, refuse alors aux cylindres encadres. Le nouvel essai est compte a part,
    # CalMaxRetest ecritures de plus (comme les nouveaux essais de la mesure complete, ci-dessous) : fin 7 -> 8, standard
    # 9 -> 10, texte « un encadrement et un nouvel essai ». Haute densite (CalibCalcHd 12.7) : plafond (6, 8) et texte
    # inchanges
    $nPassMax = $nPassEst + 1 + $(if ($fine) { 0 } else { 2 }) + $(if ($cond) { 1 } else { 0 }) + $(if ($cond) { [int]$script:CalMaxRetest } else { 0 })
    $extra = if ($cond -and $fine) { (T 'si la courbe demande un encadrement et un nouvel essai des cylindres non convergés') }
             elseif ($cond) { (T 'si la courbe demande un encadrement, des mesures complémentaires (30 cylindres au plus) et un nouvel essai des cylindres non convergés') }
             elseif ($fine) { (T 'si la courbe demande un encadrement ou un nouvel essai des cylindres non convergés') }
             else { (T 'si la courbe demande un encadrement, des mesures complémentaires (30 cylindres au plus) ou un nouvel essai des cylindres non convergés') }
    # 12.8 (S3-HIGH) : mesure complete de cette disquette (test fin) : passe de mesure directe des cylindres dont le besoin
    # depasse le plafond des passes de mesure (Start-DiskReach) et CalDiskMaxRetest nouveaux essais au plus : une ecriture
    # de plus par piste pour chacune (la disquette mesuree est celle a ecrire, reecrite ensuite par l image). Duree : passes
    # ciblees, chacune bornee par une passe sur tous les cylindres (Get-CalibRetestMinutes), en supplement de la duree estimee
    # (plafond des passes de mesure du bareme de la famille : Set-CalibScale n est appele qu apres l avertissement). Au plus :
    # encadrement (il precede toujours la mesure directe, les passes de mesure s arretant sous ce plafond), mesure directe et
    # CalDiskMaxRetest nouveaux essais, soit 2 + CalDiskMaxRetest passes ciblees (la duree estimee n en compte aucune)
    $minDisk = 0; $mxDisk = 0
    if ($do) {
        $mxDisk = [int]$(if ($family -eq 'hd') { $script:CalScaleHd.CalMaxNs } else { $script:CalScaleDd.CalMaxNs })
        $nPassMax = $nPassEst + 2 + [int]$script:CalDiskMaxRetest + $(if ($cond) { 1 } else { 0 })
        $extra = (T 'si la courbe demande un encadrement, une mesure directe au-delà de {0} ns ou de nouveaux essais des cylindres non convergés') -f "$mxDisk"
        $minDisk = $minutes + (2 + [int]$script:CalDiskMaxRetest) * $minRetest
    }
    # 12.9 (correction 1) : l ecriture de conditionnement du lecteur est nommee
    $wear = if ($cond) { (T "ATTENTION : la calibration écrit le motif de test sur les mêmes pistes à chaque passe ({0} passes prévues et une écriture de conditionnement du lecteur ; jusqu'à {1} écritures par piste {2}). Ces écritures répétées sollicitent le support magnétique et peuvent le fatiguer.") -f "$nPassEst", "$nPassMax", "$extra" }
            else { (T "ATTENTION : la calibration écrit le motif de test sur les mêmes pistes à chaque passe ({0} passes prévues, jusqu'à {1} {2}). Ces écritures répétées sollicitent le support magnétique et peuvent le fatiguer.") -f "$nPassEst", "$nPassMax", "$extra" }
    # 12.9 (S1) : delai de l avertissement (Get-CalibConfirmSeconds) : sans delai, pas de mention du compte a rebours
    $cfSec = Get-CalibConfirmSeconds ([string]$script:AfterCalib) ([bool]$script:CalibUnattended)
    $choice = if ($toWrite -and $cfSec -gt 0) { (T "Pour épargner {0}, cochez la case ci-dessous (le compte à rebours s'arrête), remplacez-la par une disquette sacrifiée (sans valeur, jamais l'original), puis cliquez sur « Lancer la calibration » : après la calibration, l'application vous demandera de remettre {0}. Sinon, la calibration utilise la disquette insérée.") -f "$target" }
              elseif ($toWrite) { (T "Pour épargner {0}, cochez la case ci-dessous, remplacez-la par une disquette sacrifiée (sans valeur, jamais l'original), puis cliquez sur « Lancer la calibration » : après la calibration, l'application vous demandera de remettre {0}. Sinon, la calibration utilise la disquette insérée.") -f "$target" }
              else { (T 'Insérez de préférence une disquette sacrifiée (vierge ou sans valeur), puis validez.') }
    $swapLabel = if ($toWrite) { (T "J'ai inséré une disquette sacrifiée : me redemander {0} après la calibration") -f "$target" } else { '' }
    if ($cx) {
        # 12.10 : calibration croisee : texte en tete (lecteurs, echanges de disquette estimes, duree hors echanges), case
        # obligatoire (la disquette est dans la source), jamais de demarrage automatique ; reponse au journal
        $sw = Get-CrossSwapEstimate $nPassEst $fine ([int]$script:CalMaxRetest) ([int]$script:CalMaxVerify)   # 12.11 : au moins : une seule verification
        $ci = ((T "Calibration croisée : le lecteur {0} écrit le motif de test, le lecteur {1} le relit. Avant chaque relecture, puis avant l'écriture suivante, l'application vous demande de déplacer la disquette d'un lecteur à l'autre : {2} échanges au moins, {3} au plus. La durée estimée ne compte pas ces échanges. La courbe obtenue sert aux écritures du lecteur {0} destinées au lecteur {1} ; la courbe propre du lecteur {0} n'est pas modifiée.") -f "$($cx.Src)", "$($cx.Tgt)", "$($sw.Min)", "$($sw.Max)") + "`n`n"
        $rc = Show-TimedConfirm 'frmCalibConfirm' (T 'Calibration precomp') ($Intro + $ci + $body + "`n`n" + $wear) (T 'Lancer la calibration') 'Diagnostic' '' ((T "J'ai inséré une disquette sacrifiée (sans valeur, jamais l'original) dans le lecteur {0}, celui qui écrit") -f "$($cx.Src)") '' (T "Pas de démarrage automatique : cochez la case, puis cliquez sur « Lancer la calibration ».") -Seconds 0 -NeedCheck -Heading (T 'Calibration croisée : la disquette sacrifiée reçoit le motif de test') -Level 'warn' -Picto 'warn'
        $ans = @{ Ok = ($rc.Ok -and $rc.Checked); Swap = $false; Auto = $false }
        Append-Log $(if ($ans.Ok) { (T "Calibration croisée : lancée (case « disquette sacrifiée dans le lecteur {0} » cochée).") -f "$($cx.Src)" } else { (T 'Calibration croisée : annulée.') })
    } elseif ($redo) {
        # Confirmation sans compte a rebours : la case est obligatoire (une disquette de valeur est peut-etre inseree)
        $rc = Show-TimedConfirm 'frmCalibRedo' (T 'Calibration sur une autre disquette') ($Intro + $body + "`n`n" + $wear) (T 'Lancer la calibration B') 'Diagnostic' '' (T "J'ai retiré la disquette de la calibration A et inséré une autre disquette sacrifiée") '' (T "Pas de démarrage automatique : cochez la case, puis cliquez sur « Lancer la calibration B ».") -Seconds 0 -NeedCheck -Heading (T 'Calibration B : insérez une autre disquette sacrifiée') -Level 'warn' -Picto 'warn'
        $ans = @{ Ok = ($rc.Ok -and $rc.Checked); Swap = $false; Auto = $false }
    } elseif ($do) {
        # Mesure complete de cette disquette (M1, M2) : la disquette inseree est celle a ecrire ; marque proposee (champ
        # modifiable, liste de l avertissement de la calibration rapide, L-M)
        $bi = Get-LevelBrandItems ([string]$cmbDrive.Text) @($do.Ref.Units) $family
        # 12.8 (S3-HIGH) : duree avec la mesure directe et les nouveaux essais, au plus ($minDisk)
        $m1 = (T "Mesure complète de cette disquette sur le lecteur {0} : la précompensation est mesurée sur ses {1} cylindres (2 faces), environ {2} min ({3} min au plus si des cylindres demandent plus de {4} ns ou restent non convergés), puis l'image est écrite. La référence du lecteur n'est pas modifiée. La courbe obtenue est mémorisée pour la marque choisie ci-dessous ; sans marque, elle ne sert qu'à cette écriture.") -f "$($cmbDrive.Text)", "$nCyl", "$minutes", "$minDisk", "$mxDisk"
        # Texte : M1 et usure du support (le detail de la calibration, $body, reste au journal)
        $cq = @{ Title = (T 'Calibration precomp'); Heading = (T 'Mesure complète de cette disquette'); Level = 'warn'; Picto = 'warn'
                 Text = ($m1 + "`n`n" + $wear)
                 Check = (T "Cette disquette sera effacée, puis l'image y sera écrite.")
                 GoText = (T 'Lancer la mesure complète'); GoGlyph = 'Diagnostic'
                 Combo = @{ Label = (T 'Marque de la disquette insérée :'); Items = $bi.Items; Text = [string]$do.Brand
                            Tip = (T "Nom libre : marque, année ou lot. La courbe mesurée est mémorisée pour cette marque : les disquettes suivantes de cette marque en partent, avec une calibration rapide. Sans marque, elle ne sert qu'à cette écriture.") } }
        $okD = [bool](Show-AppConfirm @cq)
        if ($okD) { $do.Brand = Get-LevelBrandName ([string]$script:ConfirmComboText) $bi.Map; $script:LevelBrand = [string]$do.Brand }
        $ans = @{ Ok = $okD; Swap = $false; Auto = $false }
    } elseif ($fb) {
        # Repli apres la calibration rapide : la disquette inseree est peut-etre celle a ecrire ; jamais de demarrage
        # automatique. Reponse au journal (Show-AppConfirm), puis ligne du point 3
        $cq = @{ Title = (T 'Calibration precomp'); Heading = (T 'Calibration complète sur une disquette sacrifiée'); Level = 'warn'; Picto = 'warn'
                 Text = ($Intro + $body + "`n`n" + $wear + "`n`n" + (T "Pas de démarrage automatique : cochez la case, puis cliquez sur « Lancer la calibration complète »."))
                 Check = (T "J'ai retiré la disquette à écrire et inséré une disquette sacrifiée, de la marque de mes disquettes habituelles : elle deviendra la référence du lecteur")
                 GoText = (T 'Lancer la calibration complète'); GoGlyph = 'Diagnostic' }
        $okFb = [bool](Show-AppConfirm @cq)
        Append-Log $(if ($okFb) { (T "Calibration complète après la calibration rapide : lancée (case « disquette sacrifiée » cochée).") } else { (T 'Calibration complète après la calibration rapide : annulée.') })
        $ans = @{ Ok = $okFb; Swap = ($okFb -and [bool]$fb.Swap); Auto = $false }
    } else { $ans = Show-CalibConfirm ($Intro + $auto + $body + "`n`n" + $wear + "`n`n" + $choice) $swapLabel -Seconds $cfSec }
    if (-not $ans.Ok) { return }
    if ($ans.Auto) { Append-Log ((T "Calibration : avertissement validé automatiquement après {0} s sans réponse.") -f "$($script:CalibConfirmSeconds)") }
    if ($ans.Swap) { Append-Log ((T "Calibration sur une disquette sacrifiée : {0} sera redemandée avant l'écriture.") -f "$target") }
    if ($script:GwProc -and -not $script:GwProc.HasExited) { return }
    if (-not (Test-Path -LiteralPath $script:TempDir)) { [void](New-Item -ItemType Directory -Path $script:TempDir -Force) }
    try { $pat = New-CalibPattern $family $img $nCyl }
    catch { [void](Show-AppMessage ((T "Calibration : motif de test impossible à créer : {0}") -f "$($_.Exception.Message)") (T 'Calibration precomp') 'OK' 'Error'); return }
    if ($redo -and [int]$pat.Bits -ne [int]$script:CalRedo.ACal.PatternBits) {
        [void](Show-AppMessage ((T "Calibration B impossible : réglage différent de la calibration A ({0}). La décision sur la courbe A est rouverte.") -f (T 'densité du motif')) (T 'Calibration precomp') 'OK' 'Warning'); return
    }
    if ($redo) {
        $script:CalRedo.Stage = 'running'
        Append-Log ((T "=== Calibration B sur une autre disquette, mêmes réglages que la calibration A du {0} : les deux courbes seront comparées ===") -f "$($script:CalRedo.ADate)")
        Append-Log (T "Calibration B : autre disquette sacrifiée déclarée insérée (case cochée) ; l'application ne peut pas distinguer deux disquettes.")
    }
    # Ecriture lente : une unite par tete (mesures, courbe et verification separees) ; sinon une unite pour les deux tetes
    # @() autour du if : une seule unite resterait sinon une hashtable nue ($cal.Units[0] = $null)
    Set-CalibScale $family     # 12.7 : bareme de la famille (amplitudes haute densite), apres les sorties anticipees
    # 12.8 (S3) : borne de la courbe de cette disquette (Get-DiskHardNs : plafond par disquette, ou precompMaxNs reglee sous
    # 400 ns) pendant la mesure complete, retablie a sa fin (Reset-DiskHardNs). 12.11 : calculee ici, le motif cree, sur les cellules de la piste ecrite (CapBits, Get-DiskCapBits : piste la plus longue de l image, codec du format, ou format gw au-dela de 250 kbit/s ; 0 si elle n est pas connue : 470 ns, comme en 12.10)
    if ($do) { $do.CapBits = Get-DiskCapBits ([int]$pat.CapBits) ([string]$cmbWFmt.Text) ([bool]$pat.Known); $do.HardNs = Get-DiskHardNs ([int]$do.CapBits); Set-DiskHardNs @{ DiskOnly = $true; HardNs = [int]$do.HardNs } }
    $units = @(if ($slow) { (New-CalibUnit 0), (New-CalibUnit 1) } else { New-CalibUnit $null })
    foreach ($u in $units) { foreach ($c in $cyls) { $u.Results[[int]$c] = @{} } }
    $script:Cal = @{
        Mode = $(if ($fine) { 'fine' } else { 'std' }); Cyls = $cyls; MaxCyl = $maxCyl; Family = $family; Slow = $slow
        Image = $img; Pattern = $pat.Path; PatternBits = $pat.Bits; MaxCoarse = [int](@(Get-CalLevels $family) | Measure-Object -Maximum).Maximum; Drive = $cmbDrive.Text; TSpec = "c=${cylList}:h=0-1"; CylList = $cylList
        # 12.10 : niveaux de la famille (Get-CalLevels, dans le litteral : les bancs l extraient tel quel)
        Stage = 'coarse'; Values = @(Get-CalLevels $family); Index = 0; Value = 0; ValueTxt = ''; Spec = ''
        Units = $units; VerifyCount = 0; Swap = [bool]$ans.Swap; LevelAfter = [bool]$LevelAfter
        Scp = (Join-Path $script:TempDir 'precomp-calib.scp'); Writes = (New-Object System.Collections.Queue); ReadArgs = @()
        # Progression globale : passes faites / prevues, durees mesurees par phase, estimation initiale 0,7 s par piste et par phase
        StartTime = (Get-Date); PassStart = (Get-Date); PhaseStart = (Get-Date); Phase = 'write'
        PassesDone = 0; TotalPasses = $nPassEst; WriteDurs = @(); ReadDurs = @(); EstTrack = 0.7; EstErase = $estEr
        Home = [bool]$Geom; Geom = $Geom; NoWarmup = [bool]$noWarm   # carte Calibration de l Accueil ; 12.8 : reglage warmFullCalib
        # 12.7 : controle de surface de la passe 1 (Invoke-CalibAnalysis) : avertissement valide seul, numero de la disquette
        # (Restart-PrecompCalib), bilan, defaut grossier, fenetre ouverte (Hold) ; Redo : calibration B (point 2) ; Cyls0 :
        # cylindres de test de depart, controle d identite de la calibration B (Cyls s etend aux mesures complementaires du
        # test standard, Start-CalibDensify)
        AutoStart = [bool]$ans.Auto; Disk = 1; SurfDone = $false; Surf = $null; Medium = $null; SurfGross = $false; SurfKept = $false; Hold = $false; Redo = $redo
        Cyls0 = [int[]]@($cyls)
        # 12.8 (lot 1b) : passes de nouvel essai faites (Start-CalibRetest) ; ecritures par piste annoncees au plus
        Retests = 0; WriteMax = [int]$nPassMax
        # 12.9 : conditionnement du lecteur (Cond, CondRun pendant ses ecritures, CondDone, CondSec duree mesuree, CondTracks
        # pistes ecrites), carre latin et decalages de passe (Latin, PassW : valeur ecrite par cylindre a la passe en cours),
        # dents (Dent) ; drapeaux du bareme de la famille, poses par Set-CalibScale (appel ci-dessus, apres les sorties anticipees)
        Cond = $cond; CondRun = $false; CondDone = $false; CondSec = 0.0; CondStart = $null; CondTracks = $(if ($cond) { 2 * ($maxCyl + 1) } else { 0 })
        # Carre latin seulement avec CalLatinMinCyl cylindres de test au moins : en dessous (image de 40 cylindres en test
        # standard : c0, 10, 20, 30, 39), les decalages de passe ne s estiment pas et des niveaux repartis sans estimation
        # donneraient une erreur par cylindre plus forte que des passes uniformes (validation C)
        Latin = ([bool]$script:CalLatin -and @($cyls).Count -ge [math]::Max([int]$script:CalLatinMinCyl, 2 * @($script:CalCoarse).Count))
        Dent = [bool]$script:CalDentOn; PassW = @{}
        # 12.9 : decalage commun de l ecriture d une verification complete retire des residus avant le jugement
        # (Get-VerifyOffset, Invoke-CalibAnalysis), bareme de la famille (double densite seulement)
        VOff = [bool]$script:CalVOffOn
        # 12.10 : erreur de modele aux forts besoins corrigee a la verification complete (Get-VerifySlope,
        # Invoke-CalibAnalysis), meme bareme que VOff (double densite)
        Slope = [bool]$script:CalSlopeOn
    }
    if ($cx) {
        # 12.10 : calibration croisee : source (Drive, le lecteur qui ecrit) et cible (le lecteur qui relit) ; disquette dans
        # la source au depart (DiskAt 'S', 'T' dans la cible), echanges comptes (Swaps), invite en cours (SwapHold) ; pas une
        # calibration de l Accueil, meme avec une image de geometrie (Home faux : ni carte ni bilan de l Accueil)
        $script:Cal.Cross = @{ Src = [string]$cx.Src; Tgt = [string]$cx.Tgt }
        $script:Cal.DiskAt = 'S'; $script:Cal.Swaps = 0; $script:Cal.SwapHold = $null; $script:Cal.Home = $false
        if ($Geom -and $Geom.BitsSrc) { $pat.Source = [string]$Geom.BitsSrc }
        if ($Geom) { Append-Log ((T "=== Calibration croisée : écriture par le lecteur {0}, relecture par le lecteur {1}, type {2} ({3}, {4}) ===") -f "$($cx.Src)", "$($cx.Tgt)", "$($chk.Label)", "$famTxt", "$modeTxt") }
        else { Append-Log ((T "=== Calibration croisée : écriture par le lecteur {0}, relecture par le lecteur {1}, image {2} ({3}, {4}) ===") -f "$($cx.Src)", "$($cx.Tgt)", "$([System.IO.Path]::GetFileName($img))", "$famTxt", "$modeTxt") }
        Append-Log ((T "Cylindres de test : {0} ({1})") -f "$cylList", "$cylSrc")
        Append-Log ((T "Motif de test : HFE de données pseudo-aléatoires généré, {0} cylindres, {1} cellules par piste ({2}), soit {3} ns par cellule à 300 tr/min. L'image ne fixe que la densité et le nombre de cylindres, son contenu n'est pas écrit.") -f "$nCyl", "$($pat.Bits)", "$($pat.Source)", "$([math]::Round($pat.CellNs, 1))")
        Append-Log ((T "Calibration croisée : la courbe mesure le besoin du lecteur {1} à la relecture des écritures du lecteur {0} ; elle est enregistrée sous la clé « {0}>{1} », pour les écritures du lecteur {0} destinées au lecteur {1}. Pour ces écritures, le contrôle après écriture relit avec le lecteur {0} (pas avec le lecteur cible) ; la mesure de la disquette et la calibration rapide ne sont pas faites.") -f "$($cx.Src)", "$($cx.Tgt)")
    }
    elseif ($do) {
        # 12.8 (S3) : mesure complete de cette disquette : marque, borne (12.11 : au-dela du seuil, quart de la cellule de la piste ecrite, Get-DiskCapNs et Get-DiskCapBits), reference en place (Get-LevelRef)
        $script:Cal.DiskOnly = $true; $script:Cal.Brand = [string]$do.Brand; $script:Cal.HardNs = [int]$do.HardNs; $script:Cal.DiskRef = $do.Ref
        Append-Log ((T "=== Mesure complète de cette disquette : lecteur {0}, image {1} ({2}, {3}) ; référence du lecteur inchangée ===") -f "$($cmbDrive.Text)", "$([System.IO.Path]::GetFileName($img))", "$famTxt", "$modeTxt")
        if ($do.Brand) { Append-Log ((T 'Marque de la disquette insérée : « {0} ».') -f "$($do.Brand)") }
        # 12.11 (lot L4b) : ligne de la borne tiree de la decision du plafond (Get-DiskBoundText, 265) : quart de la cellule de la
        # piste ecrite si elle est connue (CapBits), ligne de la 12.10 sinon (470 ns), borne precompMaxNs au plus au seuil.
        # 12.11 (L12a) : le motif dit si ces cellules sont celles de la piste la plus longue de l image (IPF, HFE aux pistes inegales)
        Append-Log (Get-DiskBoundText ([int]$do.HardNs) ([int]$do.CapBits) $pat)
        # 12.8 (S3-HIGH) : duree estimee et ecritures par piste au plus (avertissement M1)
        Append-Log ((T "Durée estimée de la mesure : environ {0} min ; {1} min au plus avec la mesure directe des cylindres dont le besoin dépasse {2} ns et {3} nouveaux essais au plus des cylindres non convergés.") -f "$minutes", "$minDisk", "$mxDisk", "$($script:CalDiskMaxRetest)")
        # 12.9 (correction 1) : l ecriture de conditionnement du lecteur est comptee
        $wpl = if ($cond) { (T "Écritures du motif de test par piste : {0} au plus (conditionnement du lecteur, {1} passes de mesure, encadrement, mesure directe, {2} vérifications, {3} nouveaux essais). La disquette mesurée est celle à écrire, réécrite ensuite par l'image : aucune disquette sacrifiée à épargner, chaque passe de plus reste bornée.") }
               else { (T "Écritures du motif de test par piste : {0} au plus ({1} passes de mesure, encadrement, mesure directe, {2} vérifications, {3} nouveaux essais). La disquette mesurée est celle à écrire, réécrite ensuite par l'image : aucune disquette sacrifiée à épargner, chaque passe de plus reste bornée.") }
        Append-Log ($wpl -f "$nPassMax", "$(@($script:CalCoarse).Count)", "$($script:CalMaxVerify)", "$($script:CalDiskMaxRetest)")
        Append-Log ((T "Cylindres de test : {0} ({1})") -f "$cylList", "$cylSrc")
        Append-Log ((T "Motif de test : HFE de données pseudo-aléatoires généré, {0} cylindres, {1} cellules par piste ({2}), soit {3} ns par cellule à 300 tr/min. L'image ne fixe que la densité et le nombre de cylindres, son contenu n'est pas écrit.") -f "$nCyl", "$($pat.Bits)", "$($pat.Source)", "$([math]::Round($pat.CellNs, 1))")
    }
    elseif ($Geom) {
        # Densite du type choisi (source de Get-FormatCalibInfo), et non « HFE, bits par piste de l image » de la geometrie
        if ($Geom.BitsSrc) { $pat.Source = [string]$Geom.BitsSrc }
        Append-Log ((T "=== Calibration precomp : lecteur {0}, type {1} ({2}, {3}) ===") -f "$($cmbDrive.Text)", "$($chk.Label)", "$famTxt", "$modeTxt")
        Append-Log ((T "Cylindres de test : {0} ({1})") -f "$cylList", "$cylSrc")
        Append-Log ((T "Motif de test : HFE de données pseudo-aléatoires généré, {0} cylindres, {1} cellules par piste ({2}), soit {3} ns par cellule à 300 tr/min, d'après le type de disquette choisi.") -f "$nCyl", "$($pat.Bits)", "$($pat.Source)", "$([math]::Round($pat.CellNs, 1))")
    } else {
        Append-Log ((T "=== Calibration precomp : lecteur {0}, image {1} ({2}, {3}) ===") -f "$($cmbDrive.Text)", "$([System.IO.Path]::GetFileName($img))", "$famTxt", "$modeTxt")
        Append-Log ((T "Cylindres de test : {0} ({1})") -f "$cylList", "$cylSrc")
        Append-Log ((T "Motif de test : HFE de données pseudo-aléatoires généré, {0} cylindres, {1} cellules par piste ({2}), soit {3} ns par cellule à 300 tr/min. L'image ne fixe que la densité et le nombre de cylindres, son contenu n'est pas écrit.") -f "$nCyl", "$($pat.Bits)", "$($pat.Source)", "$([math]::Round($pat.CellNs, 1))")
    }
    $pbWCal.Value = 0; $pbWCal.Visible = $true; $lblWCal.Visible = $true
    Update-CalibProgress
    Start-CalibWarmup      # prechauffage du lecteur s il y a lieu, puis premiere passe de mesure
}

function Start-CrossCalib {
    # 12.10 : bouton a icone « Calibrer pour un lecteur cible... » de l onglet Ecriture (btnWCross) : calibration croisee, le
    # lecteur du bandeau (source) ecrit le motif, un autre lecteur (cible) le relit, la disquette passant de l un a l autre
    # a la main (Invoke-CalibSwap). Fenetre de choix (Show-CrossCalibDialog, 250) : cible parmi les lecteurs du bandeau,
    # famille (preselectionnee d apres l image de l onglet, Get-CalibImageCheck : standard ou long track), test (liste
    # « Calibration precomp »). Avec l image de l onglet de la famille choisie : ses cylindres, comme « Calibrer » ; sinon
    # image de geometrie de 80 cylindres du type de la famille (amiga.amigados, app.long : New-CalibGeometry, comme la carte
    # de l Accueil). Demande posee dans $script:CalCrossAsk, lue par Start-PrecompCalib (signature inchangee : enveloppes
    # de make-test), qui affiche l avertissement d usure avec la case « disquette sacrifiee dans la source » obligatoire.
    # Pas de fenetre ici hors des refus (testable) : renvoie @{ Started ; Why }
    $res = @{ Started = $false; Why = '' }
    $busy = Get-AppBusy -Text
    if ($busy) { $res.Why = "$busy"; [void](Show-AppMessage ((T "Calibration croisée impossible : opération en cours ({0}).") -f "$busy") (T 'Calibration precomp') 'OK' 'Warning'); return $res }
    if ($script:CalRedo) { $res.Why = (T 'calibration B'); [void](Show-AppMessage (T "Calibration croisée impossible : une calibration B (« Refaire sur une autre disquette ») est en cours ou en attente de décision.") (T 'Calibration precomp') 'OK' 'Warning'); return $res }
    $src = [string]$cmbDrive.Text
    # 12.11 (lot LN-b) : -OtherConn : avec des lecteurs enregistres, les lecteurs de la connexion de la source ne sont pas
    # proposes (les deux lecteurs sont branches en meme temps, chacun sur sa connexion) ; la fenetre de choix le dit
    $targets = Get-CrossCalibTargets @($cmbDrive.Items | ForEach-Object { [string]$_ }) $src -OtherConn
    if ($targets.Count -eq 0) { $res.Why = (T 'aucun autre lecteur'); [void](Show-AppMessage (T 'Calibration croisée impossible : aucun autre lecteur dans la liste du bandeau.') (T 'Calibration precomp') 'OK' 'Warning'); return $res }
    # 12.10 (relecture de la RC) : image de l onglet Ecriture d apres le controle de la calibration elle-meme
    # (Get-CalibImageCheck, 260, celui de Test-CalibImage au debut de Start-PrecompCalib) : annoncee et reprise seulement si
    # elle est calibrable en standard ou en long track, sinon image de geometrie de 80 cylindres ; secteurs durs ou lecteur
    # 8 pouces (refus de toute calibration) : refus avant la fenetre. Avant : famille de Get-WriteTabFamily, une image FM,
    # GCR, a codage propre ou hors des plages mesurables etait annoncee, puis la calibration refusee apres « Continuer »
    # 12.10 (relecture de la RC, fix1) : reglages tires de Get-CalibSettingBlock (260), avant le controle de l image : refus
    # avant la fenetre quelle que soit l image (avant : seulement apres une image acceptee, Get-CalibImageCheck ne regardant
    # les cases qu apres les controles de l image)
    # 12.10 (verification finale de la RC) : installation sans module d analyse SCP ou sans gw.exe (Get-CalibEnvBlock, 260,
    # celui de Test-CalibImage) : refus avant la fenetre (avant : apres « Continuer », rien n etant ecrit)
    $eb = Get-CalibEnvBlock
    if ($eb) { $res.Why = [string]$eb.Why; [void](Show-AppMessage ([string]$eb.Why) ([string]$eb.Title) 'OK' ([string]$eb.Icon)); return $res }
    $sb = Get-CalibSettingBlock
    if ($sb) { $res.Why = $sb; [void](Show-AppMessage $sb (T 'Calibration precomp') 'OK' 'Warning'); return $res }
    $ic = Get-CalibImageCheck
    $imgFam = if ($ic.Ok) { [string]$ic.Family } else { '' }
    if (@('std', 'long') -notcontains $imgFam) { $imgFam = '' }
    $imgInfo = if ($imgFam) { (T "Image de l'onglet Écriture : {0} ({1}) ; avec cette famille, ses cylindres sont ceux de la calibration ; avec l'autre, 80 cylindres à la densité de la famille.") -f "$([System.IO.Path]::GetFileName($txtWFile.Text))", (Get-CalibFamilyName $imgFam) }
               else { (T "Aucune image calibrable dans l'onglet Écriture : 80 cylindres, à la densité de la famille choisie.") }
    if ($script:DriveReg.Count -gt 0) {
        $allT = Get-CrossCalibTargets @($cmbDrive.Items | ForEach-Object { [string]$_ }) $src
        $sameC = @($allT | Where-Object { $targets -cnotcontains $_ })
        if ($sameC.Count -gt 0) { $imgInfo += "`n" + ((T 'Non proposés, parce qu''ils sont sur la connexion {0} du lecteur qui écrit : {1}. Les deux lecteurs d''une calibration croisée sont branchés en même temps, chacun sur sa connexion.') -f (Get-DriveConn $src), (Format-ConnDrives $sameC)) }
    }
    $nPassEst = @($script:CalCoarse).Count + [int]$script:CalMaxVerify
    $swF = Get-CrossSwapEstimate $nPassEst $true ([int]$script:CalMaxRetest) ([int]$script:CalMaxVerify); $swS = Get-CrossSwapEstimate $nPassEst $false ([int]$script:CalMaxRetest) ([int]$script:CalMaxVerify)   # 12.11 : au moins : une seule verification
    $ch = Show-CrossCalibDialog $src $targets $(if ($imgFam) { $imgFam } else { 'std' }) ($cmbWCalMode.SelectedIndex -eq 1) $imgInfo ([bool]$chkWSlow.Checked) ([int]$swF.Min) ([int]$swS.Max) (Get-TargetDrive $src)   # 12.11 : lecteur cible de l onglet Ecriture preselectionne
    if (-not $ch.Ok) { $res.Why = (T 'annulée'); Append-Log (T "Calibration croisée : fenêtre de choix fermée, rien n'est lancé."); return $res }
    $tgt = [string]$ch.Target; $fam = [string]$ch.Family; $test = $(if ($ch.Fine) { 'fine' } else { 'std' })
    # 12.11 (lot LN-b) : lecteur cible confirme quand sa connexion porte plusieurs lecteurs (Confirm-DriveIdentity -Target,
    # 112), avant que la demande soit posee : refus, rien n est lance
    if ($script:DriveReg.Count -gt 0 -and -not (Confirm-DriveIdentity -Target $tgt)) { $res.Why = (T 'Opération annulée : lecteur branché non confirmé.'); return $res }
    Append-Log ((T "Calibration croisée demandée : écriture par le lecteur {0}, relecture par le lecteur {1}, famille {2}, {3}.") -f "$src", "$tgt", (Get-CalibFamilyName $fam), $(if ($ch.Fine) { (T 'test fin') } else { (T 'test standard') }))
    $geom = $null
    if ($fam -ne $imgFam) {
        # Image de geometrie du type de la famille (comme Start-HomeCalib) : amiga.amigados (standard, 101 344 cellules),
        # app.long (long track) ; seuil de famille de la configuration respecte (Get-ImageFamily)
        $name = if ($fam -eq 'long') { 'app.long' } else { 'amiga.amigados' }
        $info = Get-HomeCalibInfo $name
        try { $gimg = New-CalibGeometry $info 80 }
        catch { $res.Why = "$($_.Exception.Message)"; [void](Show-AppMessage ((T "Calibration croisée impossible : image de géométrie impossible à créer : {0}") -f "$($_.Exception.Message)") (T 'Calibration precomp') 'OK' 'Error'); return $res }
        if ((Get-ImageFamily $gimg) -ne $fam) { $res.Why = (T 'seuil de famille'); [void](Show-AppMessage ((T "Calibration croisée impossible : avec le seuil de famille precompThresholdNs de {0} ns, ce type serait calibré dans une autre famille que {1}.") -f "$($script:PrecompThresholdNs)", (Get-CalibFamilyName $fam)) (T 'Calibration precomp') 'OK' 'Warning'); return $res }
        # Origine des cylindres sans parentheses : la ligne de journal des cylindres de test la met deja entre parentheses
        $geom = @{ Img = $gimg; Label = [string]$info.Label; Fmt = $name; BitsSrc = [string]$info.BitsSrc; CylSrc = (T "80 cylindres, faute d'image de cette famille dans l'onglet Écriture") }
    }
    $script:AfterCalib = ''
    $script:CalCrossAsk = @{ Src = $src; Tgt = $tgt }
    if ($geom) { Start-PrecompCalib -Geom $geom -Test $test } else { Start-PrecompCalib -Test $test }
    $script:CalCrossAsk = $null
    $res.Started = [bool]($script:Cal -and $script:Cal.Cross)
    return $res
}

function Start-DiskMeasure($lr, [string]$brand) {
    # 12.8 (S3, decision du 21/10/2026, c4-design § 4.2) : « Mesure complete de cette disquette » avant une ecriture lente :
    # calibration complete en test fin, une courbe par tete, sur la disquette a ecrire, puis ecriture de l image avec ces
    # courbes ; la reference du lecteur ($lr : Get-LevelRef, une unite par tete) n est pas modifiee. Appelants : fenetre de
    # decision de la calibration rapide (W-M1), garde de la passe 1 (W-M2), liste « Mesure : complete » de l onglet
    # Ecriture (Start-LevelBeforeWrite). Marque proposee dans l avertissement (M1) : $brand
    if (-not $lr -or -not $lr.Ok -or @($lr.Units).Count -ne 2 -or $null -eq @($lr.Units)[0].Head) {
        $script:AfterCalib = ''
        Append-Log (T "Mesure complète de cette disquette impossible : elle demande la référence du lecteur par tête (écriture lente). Écriture annulée.")
        return
    }
    $script:CalDiskOnly = @{ Brand = [string]$brand; HardNs = 0; Ref = $lr }   # 12.11 : HardNs pose par Start-PrecompCalib (Get-DiskHardNs des cellules de la piste ecrite, qu il garde dans CapBits)
    $script:AfterCalib = 'write'
    Start-PrecompCalib -ForceFine -Heads $true
    $script:CalDiskOnly = $null      # deja remis a $null par Start-PrecompCalib (premiere instruction)
    if (-not $script:Cal) { $script:AfterCalib = ''; Append-Log (T "Écriture annulée : la mesure complète de cette disquette n'a pas été lancée.") }
}

function Get-DiskMeasureMinutes([int]$nCyl, [bool]$hd = $false) {
    # 12.8 (S3) : duree estimee de la mesure complete de cette disquette (W-M1, W-M2), au calcul de Start-PrecompCalib en
    # test fin : passes de mesure et de verification sur tous les cylindres, prechauffage du reglage warmFullCalib compris ;
    # 12.8.2 (revue) : effacement haute frequence de chaque passe en double densite compris (Get-CalibEraseEst) ; 12.9
    # (correction 1) : conditionnement du lecteur en double densite compris (ecriture sans relecture de tous les cylindres)
    $n = [math]::Max(2, [math]::Min(84, $nCyl))
    $wu = if ([bool](Get-Setting 'warmFullCalib')) { [math]::Max(0.0, [double]$script:CalWarmupMinutes) } else { 0.0 }
    $np = @($script:CalCoarse).Count + [int]$script:CalMaxVerify
    $cm = if (-not $hd -and [bool]$script:CalScaleDd.CalCondPass) { $n * 2 * (0.7 + (Get-CalibEraseEst $hd)) / 60 } else { 0.0 }
    return [int][math]::Max(1, [math]::Round($n * 2 * (1.4 + (Get-CalibEraseEst $hd)) * $np / 60 + $cm + $wu, 0))
}

function Set-DiskHardNs($x) {
    # 12.8 (S3) : borne de la courbe pendant la mesure complete de cette disquette (Get-DiskHardNs : plafond par
    # disquette, ou precompMaxNs reglee sous 400 ns), posee apres Set-CalibScale ; retablie par Reset-DiskHardNs
    if ($x -and $x.DiskOnly -and [int]$x.HardNs -gt 0) { $script:CalHardNs = [int]$x.HardNs }
}

function Reset-DiskHardNs {
    # 12.8 (S3) : borne de precompMaxNs retablie a la fin de la mesure complete de cette disquette (fin, arret, aucune
    # mesure exploitable) : bareme de la famille en cours
    Set-CalibScale $(if ([string]$script:CalScaleFam -eq 'hd') { 'hd' } else { '' })
}

function Start-DiskReach($cal) {
    # 12.8 (S3-HIGH, essai E1 du 23/10/2026) : mesure complete de cette disquette seulement. Un cylindre encore
    # sous-compense au plafond des passes de mesure (CalMaxNs), dont le zero estime depasse ce plafond, est MESURE autour
    # de son besoin au lieu d etre extrapole : une passe de plus l ecrit a cette estimation, au plus a la borne de cette
    # disquette (CalHardNs, posee par Set-DiskHardNs : Get-DiskHardNs). Sur une disquette a reponse convexe (pente qui
    # baisse quand le besoin monte, E1), l extrapolation depuis CalMaxNs sous-estime le besoin. Le zero est ensuite
    # recalcule par Get-CalibZero sur la corde des deux ecritures les plus proches (Invoke-CalibAnalysis, etape 'reach'),
    # sans tendance de la courbe (Get-TrendEstimates). Une seule passe (Reach pose sur chaque unite, meme vide) ; la
    # calibration complete de reference n en a aucune. Renvoie $true si la passe est lancee.
    if (-not $cal -or -not $cal.DiskOnly) { return $false }
    if (@($cal.Units | Where-Object { $null -ne $_.Reach }).Count -gt 0) { return $false }
    $hard = [int]$script:CalHardNs; $need = $false
    foreach ($u in $cal.Units) {
        $u.Reach = @{}
        foreach ($c in @($u.Est.Keys | ForEach-Object { [int]$_ } | Sort-Object)) {
            if ([string]$u.Kind[$c] -eq 'interp' -or [double]$u.Est[$c] -le [double]$script:CalMaxNs) { continue }
            $pts = $u.Results[$c]
            if (-not $pts -or $pts.Count -eq 0) { continue }
            $top = [int](@($pts.Keys | ForEach-Object { [int]$_ }) | Measure-Object -Maximum).Maximum
            if ([double]$pts[$top].Shift -le 0) { continue }          # deja encadre : zero mesure
            $v = [int][math]::Min($hard, [math]::Round([double]$u.Est[$c], 0))
            if ($v -le $top) { continue }                              # borne de cette disquette deja ecrite
            $u.Reach[$c] = $v; $need = $true
        }
    }
    if (-not $need) { return $false }
    $cal.Stage = 'reach'; $cal.TotalPasses++
    New-CalibPass
    return $true
}

function Write-DiskReachLog($u) {
    # 12.8 (S3-HIGH) : journal de la mesure directe (Start-DiskReach), une ligne par tete : pour chaque cylindre mesure, les
    # deux ecritures retenues par Get-CalibZero (paire qui encadre le zero, sinon les deux plus fortes) et le zero de leur
    # corde ; « prolonge » : encore sous-compense a l estimation, zero au-dela de la derniere ecriture sur la meme corde ;
    # « borne » : besoin au-dela de la borne de cette disquette (Limit-CalibZero)
    $items = @()
    foreach ($c in @($u.Reach.Keys | ForEach-Object { [int]$_ } | Sort-Object)) {
        if (-not $u.Est.ContainsKey($c) -or -not $u.Results.ContainsKey($c)) { continue }
        $pts = $u.Results[$c]
        $xs = @($pts.Keys | ForEach-Object { [int]$_ } | Sort-Object)
        if ($xs.Count -lt 2) { continue }
        $j = $xs.Count - 2
        for ($i = 0; $i -lt $xs.Count - 1; $i++) { if ([double]$pts[$xs[$i]].Shift -gt 0 -and [double]$pts[$xs[$i + 1]].Shift -le 0) { $j = $i; break } }
        $k = [string]$u.Kind[$c]
        $tag = if ($k -eq 'cap') { ', ' + (T 'borné') } elseif ($k -eq 'extrap') { ', ' + (T 'prolongé') } else { '' }
        $items += ((T 'c{0} {1} -> {2} et {3} -> {4} : {5} ns{6}') -f "$c", "$($xs[$j])", (Format-UiNum ([double]$pts[$xs[$j]].Shift) '+0.0;-0.0;0.0'), "$($xs[$j + 1])", (Format-UiNum ([double]$pts[$xs[$j + 1]].Shift) '+0.0;-0.0;0.0'), "$([math]::Round([double]$u.Est[$c], 0))", "$tag")
    }
    if ($items.Count -eq 0) { return }
    Append-Log ($u.Prefix + ((T "Mesure directe : zéro recalculé par la corde des deux écritures les plus proches (valeur écrite -> décalage, ns) : {0}. Prolongé : encore sous-compensé à l'estimation, zéro au-delà de la dernière écriture sur la même corde ; borné : besoin au-delà de la borne de {1} ns de cette disquette.") -f ($items -join ' ; '), "$($script:CalHardNs)"))
}

function New-DiskMeasureRecord($cal, $u, $ru, [string]$date) {
    # 12.8 (S3, c4-design § 4.2) : enregistrement de $script:LevelShifts d une tete mesuree par la mesure complete de cette
    # disquette : Model et Mode 'mesure', courbe = Fit.Values de la mesure, profil, reference en place (RefKey, Tag,
    # RefDate) ; niveau = ecart moyen a la reference (M4), historique de la reference garde (niveau de depart des
    # disquettes suivantes, Get-LevelRef) ; LevelAlgo 'lvl2' : une 12.7 l ignore (G2)
    $vals = [int[]]@($u.Fit.Values); $vref = @($ru.Cv.Values)
    $n = [math]::Min($vals.Count, $vref.Count)
    $dd = @(for ($c = 0; $c -lt $n; $c++) { [double]$vals[$c] - [double]$vref[$c] })
    $avg = if ($dd.Count -gt 0) { [double]($dd | Measure-Object -Average).Average } else { 0.0 }
    $sd = 0.0
    if ($dd.Count -ge 2) { $ss = 0.0; foreach ($x in $dd) { $ss += [math]::Pow($x - $avg, 2) }; $sd = [math]::Sqrt($ss / ($dd.Count - 1)) }
    $hk = "$($ru.RefKey)|$($ru.Tag)"; $old = $script:LevelShifts[$hk]
    $hist = @(); if ($old -and [string]$old.RefDate -eq [string]$ru.Cv.Date) { $hist = @($old.Hist) }
    $over = [int[]]@(0..($vals.Count - 1) | Where-Object { [int]$vals[$_] -gt [int]$script:CalHardNsUser })
    return @{ RefKey = [string]$ru.RefKey; Tag = [string]$ru.Tag; Head = $u.Head; Drive = [string]$cal.Drive; Date = $date; RefDate = [string]$ru.Cv.Date; RefTest = [string]$ru.Cv.Test
              Delta = [int][math]::Round($avg); Est = [math]::Round($avg, 1); SE = 0.0; Tau = [math]::Round($sd, 1)
              Verdict = 'mesure'; Shape = 'mesure'; Reasons = [string[]]@(); Conv = [bool]($u.Warn.NonConv.Count -eq 0); Passes = [int]$cal.PassesDone
              Cyls = [int[]]@(); Zs = [double[]]@(); Ds = [double[]]@(); Sigs = [double[]]@(); Kinds = [string[]]@()
              Values = $vals; Spec = (Build-CurveProfile $vals); Sat = [int[]]@(); Floor = [int[]]@()
              Hist = $hist; Version = $script:Version; Algo = $script:CalibAlgo; LevelAlgo = 'lvl2'; Model = 'mesure'; S = 0.0; B = 0.0
              Hc = $null; Hard = [int]$cal.HardNs; Over = $over; Mode = 'mesure'; Brand = [string]$cal.Brand; Ctl = [int[]]@()
              K = $(if ($null -ne $u.Slope) { [math]::Round([double]$u.Slope, 3) } else { $null })
              Calc = [string]$script:CalibCalc; MaxNs = [int]$cal.HardNs
              DevMin = $(if ($dd.Count) { [int](($dd | Measure-Object -Minimum).Minimum) } else { 0 }); DevMax = $(if ($dd.Count) { [int](($dd | Measure-Object -Maximum).Maximum) } else { 0 }) }
}

function Complete-DiskMeasure($cal, $issues, $kinds, [string]$surfIssue) {
    # 12.8 (S3, c4-design § 4.2) : fin de la mesure complete de cette disquette (Complete-PrecompCalib, apres les
    # diagnostics). Ni copie .bak, ni PrecompCurves, ni profil de famille, ni abandon des niveaux ou des marques : la
    # reference du lecteur reste en place. Un enregistrement 'mesure' par tete dans $script:LevelShifts (New-DiskMeasureRecord),
    # profils dans les champs --precomp (pour cette disquette seulement). Reserves : fenetre de decision ; « Arreter » :
    # enregistrements d avant retablis, ecriture annulee. Resultat accepte : memoire de la marque (Update-LevelBrandCurve,
    # tetes sans reserve), puis ecriture (chemin AfterCalib) ; courbe au-dela de 400 ns : controle apres ecriture impose.
    # Ecriture annulee pendant la mesure (S3-FIX) : mesure non conservee, rien n est modifie ni enregistre
    Reset-DiskHardNs
    $famTxt = Get-CalibFamilyName $cal.Family
    $date = Get-Date -Format 'dd/MM/yyyy HH:mm'
    $toWrite = ($script:AfterCalib -eq 'write')
    $elapsedTotal = if ($cal.StartTime -is [datetime]) { ((Get-Date) - $cal.StartTime).TotalSeconds } else { 0 }
    $lblWCal.Text = ((T "Mesure complète de cette disquette terminée en {0}") -f (Format-CalDuration $elapsedTotal))
    # 12.8 (S3-FIX) : ecriture annulee pendant la mesure (erreur gw pendant la passe du nouvel essai, Stop-PrecompCalib
    # -GwError ; restauration deja arretee) : la mesure, faite pour cette ecriture seulement, n est pas conservee : ni
    # enregistrement 'mesure', ni champs --precomp, ni marque, ni fenetre de decision ; rien n est enregistre (en
    # restauration, l onglet Ecriture de l utilisateur, retabli par Close-Restore, reste tel quel) ; reference intacte
    if (-not $toWrite) {
        $pbWCal.Visible = $false
        $lblWCal.Text = (T 'Mesure complète de cette disquette non conservée : écriture annulée.')
        Append-Log (T "Mesure complète de cette disquette non conservée : l'écriture a été annulée. Ni la courbe de cette disquette ni la marque ne sont enregistrées ; la référence du lecteur, inchangée, reste en place.")
        Set-HomeProgDone $cal 'stop'
        if ($script:Restore) { Stop-Restore (T 'écriture annulée pendant la mesure complète de cette disquette') }
        return
    }
    # Reserve de surface ou de vitesse (disquette douteuse, poursuivie a votre demande) : rien n est memorise pour la marque
    $surfBad = [bool]($surfIssue -or @(@($kinds) | Where-Object { $_ -eq 'surface' -or $_ -eq 'speed' }).Count -gt 0)
    $prevRecs = @{}; $recs = @()
    foreach ($u in $cal.Units) {
        $ru = Get-DiskRefUnit $cal $u
        if (-not $ru) {
            Append-Log (T "Mesure complète de cette disquette : référence du lecteur introuvable pour une tête, mesure non conservée.")
            foreach ($k in @($prevRecs.Keys)) { if ($prevRecs[$k]) { $script:LevelShifts[$k] = $prevRecs[$k] } else { $script:LevelShifts.Remove($k) } }
            if ($toWrite) { $script:AfterCalib = ''; Append-Log (T 'Écriture annulée : calibration sans mesure exploitable.') }
            $pbWCal.Visible = $false
            if ($script:Restore) { Stop-Restore (T 'calibration sans mesure exploitable') }     # 12.8 (S3-FLUX) : restauration, copie secteur
            return
        }
        $hk = "$($ru.RefKey)|$($ru.Tag)"
        $prevRecs[$hk] = $script:LevelShifts[$hk]
        $rec = New-DiskMeasureRecord $cal $u $ru $date
        $script:LevelShifts[$hk] = $rec
        $recs += ,$rec
        if ($surfBad) { $u.DiskOk = $false }
    }
    Append-Log (T "Mesure complète de cette disquette : courbe appliquée à cette écriture ; référence du lecteur inchangée.")
    foreach ($u in $cal.Units) {
        Append-Log ($u.Prefix + ((T "Calibration terminée : profil {0} = {1}") -f "$famTxt", "$($u.Profile)"))
        $v = @($u.Fit.Values)
        for ($c0 = 0; $c0 -lt $v.Count; $c0 += 10) {
            $hi = [math]::Min($v.Count - 1, $c0 + 9)
            $line = ((T "  Précomp cylindres {0}-{1} : {2} ns") -f "$c0", "$hi", "$((@($v[$c0..$hi])) -join ' ')")
            if ($u.Prefix) { $line = '  ' + $u.Prefix + $line.TrimStart() }
            Append-Log $line
        }
    }
    Append-Log ((T "Courbe obtenue avec le calcul de calibration v{0}.") -f "$($script:CalibCalc)")
    # Champs --precomp : profil de chaque tete de cette disquette (mode Auto ; remis a la reference apres l ecriture)
    $fieldsPrev = @{ Prof = $cmbWProfile.SelectedIndex; On = $chkWPrecomp.Checked; P0 = $txtWPrecomp.Text; P1 = $txtWPrecomp1.Text; Lbl = (Get-WProfileText) }
    if ($cmbWProfile.SelectedIndex -ne 0) { $cmbWProfile.SelectedIndex = 0 }
    Set-LevelFields $recs $true
    $r0 = @($recs | Where-Object { $_.Head -eq 0 })[0]; $r1 = @($recs | Where-Object { $_.Head -eq 1 })[0]
    $lblWProfileInfo.Text = ((T "Profils {0} de cette disquette (mesure complète du {1}, lecteur {2}) : tête 0 de {3} à {4} ns, tête 1 de {5} à {6} ns, une valeur par cylindre ; référence du lecteur inchangée. À n'utiliser que pour cette disquette (bouton Courbe).") -f "$famTxt", "$date", "$($cal.Drive)", "$(@($r0.Values)[0])", "$(@($r0.Values)[-1])", "$(@($r1.Values)[0])", "$(@($r1.Values)[-1])")
    if (-not $script:Restore) { [void](Save-Config) }
    if ($issues.Count -gt 0) {
        Append-Log ((T "Calibration : résultat douteux ({0}) : courbe affichée, décision demandée.") -f ($issues -join ' ; '))
        if ($script:Restore) { $script:Restore.InCall = $true }
        try { $choice = Show-CalibReview $cal @($issues) $toWrite $false $false $false $null }
        finally { if ($script:Restore) { $script:Restore.InCall = $false; $script:Restore.Idle = Get-Date } }
        if ($choice -eq 'stop') {
            # « Arreter » : enregistrements d avant retablis, champs ramenes, reference intacte
            foreach ($k in @($prevRecs.Keys)) { if ($prevRecs[$k]) { $script:LevelShifts[$k] = $prevRecs[$k] } else { $script:LevelShifts.Remove($k) } }
            if ($cmbWProfile.SelectedIndex -ne $fieldsPrev.Prof) { $cmbWProfile.SelectedIndex = $fieldsPrev.Prof }
            Update-PrecompForImage $txtWFile.Text
            $chkWPrecomp.Checked = $fieldsPrev.On; $txtWPrecomp.Text = $fieldsPrev.P0; $txtWPrecomp1.Text = $fieldsPrev.P1
            if ($null -ne $fieldsPrev.Lbl) { $lblWProfileInfo.Text = $fieldsPrev.Lbl }
            if (-not $script:Restore) { [void](Save-Config) }
            $pbWCal.Visible = $false
            $lblWCal.Text = (T 'Mesure complète de cette disquette abandonnée : référence du lecteur inchangée.')
            Append-Log (T "Mesure complète de cette disquette abandonnée à votre demande : courbe non conservée ; la référence du lecteur, inchangée, reste en place.")
            if ($toWrite) {
                $script:AfterCalib = ''
                Append-Log (T 'Écriture annulée : résultat de calibration refusé.')
                if ($script:Restore) { Stop-Restore (T 'résultat de calibration refusé') }
            }
            Set-HomeProgDone $cal 'abandon' $issues[0]
            return
        }
        Append-Log (T 'Calibration : résultat accepté malgré les réserves.')
    }
    # Memoire de la marque (c4-design § 4.2) : tetes sans reserve seulement
    if ([string]$cal.Brand) {
        Update-LevelBrandCurve $cal ([string]$cal.Brand)
        if (-not $script:Restore) { [void](Save-Config) }
    }
    else { Append-Log (T "Mesure complète de cette disquette sans marque : la courbe ne sert qu'à cette écriture, rien n'est mémorisé.") }
    Set-HomeProgDone $cal $(if ($issues.Count -gt 0 -or $surfIssue) { 'warn' } else { 'ok' }) $(if ($issues.Count -gt 0) { $issues[0] } else { $surfIssue })
    if ($script:Restore) {
        # 12.8 (S3-FLUX, decision 2) : restauration en copie secteur : etape 4 et ligne « Niveau » du rapport (Set-RsCalibDone,
        # Write-RestoreReport), comme apres la calibration rapide de la destination (Complete-LevelCalib)
        $r = $script:Restore
        $base = if ($r.CalibUsed) { ((T "calibration existante ({0}), pas de recalibration") -f "$($r.CalibUsed.Text)") + $(if ($r.CalibUsed.Notes.Count -gt 0) { ' ; ' + ($r.CalibUsed.Notes -join ' ; ') } else { '' }) }
                elseif ($r.CalSwap) { (T "faite sur une disquette sacrifiée ({0})") -f "$($r.Calib)" } else { '' }
        $lt = (T "courbe mesurée sur la destination (mesure complète de cette disquette, {0} passe(s))") -f "$($cal.PassesDone)"
        if ($issues.Count -gt 0) { $lt += ' ; ' + ($issues -join ' ; ') }
        $r.Level = @{ State = $(if ($issues.Count -gt 0 -or $surfIssue -or ($r.CalibUsed -and $r.CalibUsed.Notes.Count -gt 0)) { 'warn' } else { 'ok' }); Text = $(if ($base) { "$base ; $lt" } else { $lt }); Report = $lt }
    }
    if ($toWrite) {
        $script:AfterCalib = ''
        # G1 : courbe de cette disquette au-dela de 400 ns (ou de precompMaxNs reglee plus haut) : controle apres ecriture impose
        $thr = Get-DiskOverNs
        if (@($recs | Where-Object { @(@($_.Values) | Where-Object { [int]$_ -gt $thr }).Count -gt 0 }).Count -gt 0) {
            $script:LevelPostForce = $true
            Append-Log ((T "Contrôle après écriture imposé : courbe de cette disquette au-delà de {0} ns.") -f "$thr")
        }
        Append-Log (T "Mesure complète de cette disquette terminée : écriture de l'image avec la courbe de cette disquette.")
        if ($script:Restore) { $script:Restore.InCall = $true }
        try { Start-ImageWrite -NoWarmup:([bool]$cal.WarmSkip) } finally { if ($script:Restore) { $script:Restore.InCall = $false; $script:Restore.Idle = Get-Date } }
        if ($script:Restore -and -not ($script:GwProc -and -not $script:GwProc.HasExited) -and $script:Chain.Count -eq 0) { Stop-Restore (T 'l''écriture n''a pas démarré après la calibration, voir le journal') }
        # Profils de cette disquette remis a ceux de la reference apres l ecriture (minuteur principal), comme apres une
        # calibration rapide ; pose apres Start-ImageWrite, qui peut ouvrir une fenetre avant de lancer gw
        if (-not $script:Restore) { $script:LevelFieldsPending = $true }
        return
    }
}

function Get-CalibRetestMinutes([int]$nCyls, [int]$maxCyl, [bool]$fine, [double]$estErase = 0.0) {
    # 12.8 (lot 1b) : duree au plus du nouvel essai automatique des cylindres non converges (avertissement de
    # Start-PrecompCalib), au rythme de la duree estimee (2 pistes par cylindre, 1,4 s par piste et par passe) : une passe
    # de verification ciblee, bornee par une passe sur tous les cylindres que la calibration peut tester (test standard :
    # 30 cylindres complementaires au plus, Start-CalibDensify), arrondie a la minute superieure ; sans prechauffage (il
    # precede la premiere passe) ; 12.8.2 (revue) : $estErase, effacement haute frequence par piste (Get-CalibEraseEst)
    $n = [math]::Min($maxCyl + 1, $nCyls + $(if ($fine) { 0 } else { 30 }))
    return [int][math]::Max(1, [math]::Ceiling($n * 2 * (1.4 + $estErase) / 60))
}

function Format-CalDuration([double]$sec) {
    if ($sec -lt 0) { $sec = 0 }
    $m = [math]::Floor($sec / 60); $s = [math]::Round($sec - 60 * $m, 0)
    if ($m -gt 0) { return "$m min $('{0:00}' -f $s) s" }
    return "$s s"
}

function Update-CalibProgress {
    # Barre globale : passes terminees + fraction de la passe en cours, d apres les durees moyennes
    # mesurees (ecriture et relecture separees) ; avant toute mesure, 0,7 s par piste et par phase.
    $cal = $script:Cal
    if (-not $cal) { return }
    # 12.7 : fenetre du controle de surface ouverte (Invoke-CalibAnalysis) : libelle fige (la minuterie principale appelle
    # cette fonction pendant la boucle modale : la barre avancerait et le temps restant baisserait)
    # 12.10 (relecture de la RC) : texte court, entier sur la ligne de lblWCal (520 : largeur fixe, 439 px a la taille
    # minimale de la fenetre) : « controle de surface, decision demandee (lecteur A). » mesurait 445 px, la lettre du
    # lecteur passait sous les points de suspension
    # 12.11 (lot LN-b) : lecteur enregistre : texte court, le nom en tete (en fin de texte, il passerait sous les points de
    # suspension) ; de meme pour l echange de disquette ci-dessous
    if ($cal.Hold -and $script:DriveReg.Count -gt 0 -and (Test-DriveRegistered ([string]$cal.Drive))) { $lblWCal.Text = (T '{0} : contrôle de surface, décision demandée') -f "$($cal.Drive)"; return }
    if ($cal.Hold) { $lblWCal.Text = (T "Calibration en attente : décision sur le contrôle de surface (lecteur {0}).") -f "$($cal.Drive)"; return }
    # 12.10 : calibration croisee en attente d un echange de disquette (Invoke-CalibSwap). 12.10 (relecture des captures) :
    # texte court, sur une ligne a la taille minimale de la fenetre (439 px a x = 320), anglais compris
    if ($cal.SwapHold -and $script:DriveReg.Count -gt 0 -and ((Test-DriveRegistered ([string]$cal.SwapHold.From)) -or (Test-DriveRegistered ([string]$cal.SwapHold.To)))) { $lblWCal.Text = (T '{0} → {1} : déplacez la disquette') -f "$($cal.SwapHold.From)", "$($cal.SwapHold.To)"; return }
    if ($cal.SwapHold) { $lblWCal.Text = (T "Calibration croisée : déplacez la disquette du lecteur {0} vers le lecteur {1}") -f "$($cal.SwapHold.From)", "$($cal.SwapHold.To)"; return }
    # Libelles au format court du prechauffage de l ecriture : avancement et temps restant en tete, details ensuite entre
    # parentheses (libelle coupe a la largeur de l onglet a la taille minimale de la fenetre)
    if ($cal.Stage -eq 'warmup') {
        # Prechauffage : duree ecoulee sur la duree prevue (Get-WarmupLeft) ; passe a la demande : fin de la lecture en cours
        $g = Get-WarmupLeft $cal
        $pbWCal.Value = $g.Pct
        $lblWCal.Text = if ($cal.WarmSkip) { (T 'Préchauffage du lecteur {0} passé : fin de la lecture en cours.') -f "$($cal.Drive)" }
                        else { (T "Préchauffage avant la calibration : {2} %, reste environ {3} (lecteur {0}, lecture {1}, sans écriture)") -f "$($cal.Drive)", "$($cal.WarmReads)", "$($g.Pct)", (Format-CalDuration ([math]::Round($g.Left))) }
        return
    }
    $nTracks = $cal.Cyls.Count * 2
    # 12.8.2 (revue) : avant la premiere passe, effacement haute frequence de la phase d ecriture compris (EstErase)
    $avgW = if ($cal.WriteDurs.Count -gt 0) { ($cal.WriteDurs | Measure-Object -Average).Average } else { $nTracks * ($cal.EstTrack + [double]$cal.EstErase) }
    $avgR = if ($cal.ReadDurs.Count -gt 0)  { ($cal.ReadDurs  | Measure-Object -Average).Average } else { $nTracks * $cal.EstTrack }
    if ($avgW -lt 1) { $avgW = 1 }; if ($avgR -lt 1) { $avgR = 1 }
    $pass = $avgW + $avgR
    # Finalisation 12.10 (N4 du banc) : PhaseStart absent (etat de calibration simule par un test) : phase en cours a 0, sans
    # erreur ; toujours pose en usage normal (creation de l etat, chaque passe, chaque phase)
    $elapsed = if ($cal.PhaseStart -is [datetime]) { ((Get-Date) - $cal.PhaseStart).TotalSeconds } else { 0.0 }
    # 12.9 (correction 1) : conditionnement (ecriture sans relecture avant la passe 1), compte en fraction de passe : duree
    # estimee, puis mesuree, rapportee a celle d une passe ; libelle propre pendant ses ecritures
    $cw = 0.0
    if ($cal.Cond) {
        $csec = if ($cal.CondDone -and [double]$cal.CondSec -gt 0) { [double]$cal.CondSec } else { [double]$cal.CondTracks * ($cal.EstTrack + [double]$cal.EstErase) }
        $cw = $csec / $pass
    }
    $tp = [math]::Max(1, [int]$cal.TotalPasses)
    $total = $tp + $cw
    # 12.11 : avancement de l etape en cours (passe ou conditionnement) d apres les pistes que gw efface, ecrit puis relit
    # (plan de l etape, Get-ProgPlanFrac, 110), a la place du temps ecoule rapporte aux durees des passes precedentes, qui
    # restait a 98 % ou sautait quand une passe portait sur moins de pistes. $null sans plan, ou tant que le plan n a recu
    # aucune commande : calcul par le temps de la 12.10, a l identique. Passes comptees a parts egales et temps restant
    # inchanges ; affichage seulement
    $pf = if ($script:ProgPlan) { Get-ProgPlanFrac } else { $null }
    if ($cal.CondRun) { $done = $(if ($null -ne $pf) { [double]$pf } else { [math]::Min(0.98, $elapsed / [math]::Max(1.0, $cw * $pass)) }) * $cw }
    else {
        $frac = if ($null -ne $pf) { [double]$pf }
                elseif ($cal.Phase -eq 'write') { [math]::Min(0.98, $elapsed / $avgW) * ($avgW / $pass) }
                else { ($avgW / $pass) + [math]::Min(0.98, $elapsed / $avgR) * ($avgR / $pass) }
        $done = [math]::Min($total, $(if ($cal.Cond) { $cw } else { 0.0 }) + $cal.PassesDone + $frac)
    }
    $pct = [int][math]::Floor(100 * $done / $total)
    $remaining = $pass * ($total - $done)
    $pbWCal.Value = [math]::Max(0, [math]::Min(100, $pct))
    if ($cal.CondRun) {
        $fmtC = if ($cal.Redo) { (T "Calibration B : {0} %, reste environ {1} (conditionnement du lecteur, écriture sans relecture)") }
                elseif ($cal.DiskOnly) { (T "Mesure complète de cette disquette : {0} %, reste environ {1} (conditionnement du lecteur, écriture sans relecture)") }
                elseif ($cal.Cross) { (T "Calibration croisée : {0} %, reste environ {1} (conditionnement du lecteur, écriture sans relecture)") }   # 12.10
                else { (T "Calibration : {0} %, reste environ {1} (conditionnement du lecteur, écriture sans relecture)") }
        $lblWCal.Text = ($fmtC -f "$pct", (Format-CalDuration $remaining)); return
    }
    # 12.11 : « effacement » pendant un gw erase de la passe (commande en cours : $script:GwProc et $script:GwIsErase, 110) ;
    # avant, la phase d ecriture disait « ecriture » pendant son effacement haute frequence
    $phaseTxt = if ($script:GwProc -and $script:GwIsErase) { (T 'effacement') } elseif ($cal.Phase -eq 'write') { (T 'écriture') } else { (T 'relecture') }
    # 12.8.1 : mesure de la disquette sur l image (276) : ValueTxt « tete 0 puis tete 1 »
    $fmt = if ($cal.Mode -eq 'content') { (T "Mesure de la disquette sur l'image : {4} %, reste environ {5} (passe {0}/{1}, {2}, {3})") }
           elseif ($cal.Mode -eq 'level') { (T "Calibration rapide : {4} %, reste environ {5} (passe {0}/{1}, {2}, {3})") }
           elseif ($cal.Redo) { (T "Calibration B : {4} %, reste environ {5} (passe {0}/{1}, {2}, {3})") }
           elseif ($cal.DiskOnly) { (T "Mesure complète de cette disquette : {4} %, reste environ {5} (passe {0}/{1}, {2}, {3})") }
           elseif ($cal.Cross) { (T "Calibration croisée : {4} %, reste environ {5} (passe {0}/{1}, {2}, {3})") }   # 12.10
           else { (T "Calibration : {4} %, reste environ {5} (passe {0}/{1}, {2}, {3})") }
    $lblWCal.Text = ($fmt -f "$([math]::Min($tp, $cal.PassesDone + 1))", "$tp", "$($cal.ValueTxt)", "$phaseTxt", "$pct", (Format-CalDuration $remaining))
}

function Stop-PrecompCalib([switch]$GwError) {
    # Abandon (bouton Arreter, erreur gw, fichier manquant) : etat remis a zero, barre masquee ; bilan de l Accueil (12.7)
    # 12.7 point 2 : calibration B arretee : decision sur la courbe A seule, differee au minuteur principal (Resume-CalibRedo)
    # 12.8 (VAL01, decisions128.md) : GwError (code retour de gw, operation incomplete, gw non lance, releve absent ou
    # illisible) pendant la passe du nouvel essai : etat de la derniere verification retabli (Restore-CalibRetestPre), son
    # jugement est garde ; fin differee au minuteur principal (Complete-CalibRetestEnd : aucune fenetre modale pendant le
    # traitement de la fin de gw), sans ecrire l image. Calibration B : elle reste en cours, la comparaison A/B suit sa fin.
    # Restauration : deja arretee par l appelant, sinon arretee ici. Bouton Arreter (sans GwError) : abandon, comme en 12.7
    if ($GwError -and $script:Cal -and -not $script:Cal.RetestEnd -and (Restore-CalibRetestPre $script:Cal)) {
        $script:Cal.RetestEnd = $true
        Append-Log ((T "Calibration : erreur gw pendant la passe du nouvel essai : jugement de la vérification {0} conservé, la calibration se termine sans le nouvel essai.") -f "$($script:Cal.VerifyCount)")
        if ($script:AfterCalib) { $script:AfterCalib = ''; Append-Log (T 'Écriture annulée : erreur gw pendant le nouvel essai de la calibration.') }
        if ($script:Restore) { Stop-Restore (T 'erreur gw pendant le nouvel essai de la calibration') }
        return
    }
    if ($script:CalRedo -and $script:CalRedo.Stage -eq 'running') { $script:CalRedo.Stage = 'interrupted'; if (-not $script:CalRedo.Why) { $script:CalRedo.Why = (T 'calibration interrompue') } }
    $cal = $script:Cal
    $script:Cal = $null
    $script:ProgPlan = $null                              # 12.11 : plan de la passe interrompue retire (barre de progression)
    if ($cal -and $cal.DiskOnly) { Reset-DiskHardNs }     # 12.8 (S3) : borne de precompMaxNs retablie
    # 12.9 (D6) : statut du JSON compagnon ; synthese C (A5) : seulement apres une passe analysee (arret pendant le
    # prechauffage ou erreur gw a la premiere ecriture : aucun JSON seul, qui compterait comme une mesure gardee)
    if ($cal -and [string]$cal.Mode -eq 'content' -and [int]$cal.PassesDone -gt 0) { Save-ContentCompanion $cal 'arretee' }
    $pbWCal.Visible = $false
    $lblWCal.Text = (T 'Calibration precomp interrompue.')
    Append-Log (T 'Calibration precomp interrompue.')
    Set-HomeProgDone $cal 'stop'
    if ($script:AfterCalib) { $script:AfterCalib = ''; Append-Log (T 'Écriture annulée : calibration interrompue.') }
    if ($script:Restore) { Stop-Restore (T 'calibration interrompue') }
}

function Restart-PrecompCalib($cal, [bool]$swap) {
    # Controle de surface, « Changer de disquette » : meme calibration reprise a la premiere passe sur la disquette
    # nouvellement inseree, sans nouvel avertissement (la case de la fenetre l a confirme) ; seuls les unites, le compte des
    # passes et l heure de debut repartent de zero ; prechauffage selon l activite du lecteur (Get-CalWarmupPlan).
    Set-CalibScale ([string]$cal.Family)     # 12.7 : bareme de la famille (deja pose par Start-PrecompCalib)
    if ($cal.DiskOnly) { Set-DiskHardNs $cal }   # 12.8 (S3) : borne de cette disquette, de nouveau apres Set-CalibScale
    $units = @(if ($cal.Slow) { (New-CalibUnit 0), (New-CalibUnit 1) } else { New-CalibUnit $null })
    foreach ($u in $units) { foreach ($c in $cal.Cyls) { $u.Results[[int]$c] = @{} } }
    $cal.Units = $units; $cal.Stage = 'coarse'; $cal.Index = 0; $cal.Value = 0; $cal.ValueTxt = ''; $cal.Spec = ''; $cal.VerifyCount = 0
    $cal.PassesDone = 0; $cal.TotalPasses = $script:CalCoarse.Count + $script:CalMaxVerify; $cal.StartTime = Get-Date
    $cal.SurfDone = $false; $cal.Surf = $null; $cal.Medium = $null; $cal.SurfGross = $false; $cal.SurfKept = $false; $cal.Hold = $false
    # 12.9 (correction 1) : nouvelle disquette, nouveau conditionnement ; unites recreees ci-dessus (Coarse vide)
    $cal.CondRun = $false; $cal.CondDone = $false; $cal.CondSec = 0.0; $cal.PassW = @{}
    $cal.AutoStart = $false; $cal.Disk = 1 + [int]$cal.Disk; $cal.Retests = 0
    # 12.10 : calibration croisee : la nouvelle disquette est dans la source (le lecteur qui ecrit) ; echanges comptes gardes
    if ($cal.Cross) { $cal.DiskAt = 'S'; Append-Log ((T "Calibration croisée reprise : la nouvelle disquette est dans le lecteur {0}, celui qui écrit.") -f "$($cal.Cross.Src)") }
    Append-Log ((T "=== Calibration precomp reprise sur une autre disquette (disquette {0}) : mêmes réglages, cylindres {1} ===") -f "$($cal.Disk)", "$($cal.CylList)")
    if ($swap -and -not $cal.Swap) {
        $cal.Swap = $true
        Append-Log ((T "Calibration sur une disquette sacrifiée : {0} sera redemandée avant l'écriture.") -f (T 'la disquette à écrire'))
    }
    $pbWCal.Value = 0
    Update-CalibProgress
    Start-CalibWarmup
}

function Get-CalWarmupPlan([string]$key, [double]$minutes) {
    # Duree du prechauffage (s) pour le lecteur 'peripherique|lecteur' : reglage en minutes, reduit de la duree de la
    # derniere serie d activite continue du lecteur si sa derniere commande gw qui a fait tourner le moteur (code 0, ou au
    # moins une piste lue ou ecrite : une commande en echec immediat ne compte pas) s est terminee il y a moins de
    # CalWarmupGapMin (Active, Idle : depuis cette fin) ; Skip : il en reste moins de CalWarmupSkipMin. Reduced : duree
    # annoncee comme reduite (activite d au moins 1 s une fois arrondie : une commande tres courte, gw rpm ou nettoyage
    # arrete tout de suite, ne raccourcit le prechauffage que d une fraction de seconde)
    $p = @{ Sec = [math]::Max(0.0, 60.0 * $minutes); Recent = $false; Active = 0.0; Idle = 0.0; Skip = $false; Reduced = $false }
    if ($p.Sec -le 0) { return $p }
    $a = if ($key) { $script:DriveActivity[$key] } else { $null }
    if (-not $a -or $a.Start -isnot [datetime] -or $a.End -isnot [datetime]) { return $p }
    $idle = ((Get-Date) - $a.End).TotalSeconds
    if ($idle -ge 60.0 * $script:CalWarmupGapMin) { return $p }
    $p.Recent = $true; $p.Idle = [math]::Max(0.0, $idle); $p.Active = [math]::Max(0.0, ($a.End - $a.Start).TotalSeconds)
    $p.Sec = [math]::Max(0.0, $p.Sec - $p.Active)
    $p.Reduced = ([math]::Round($p.Active) -ge 1)
    if ($p.Sec -lt 60.0 * $script:CalWarmupSkipMin) { $p.Skip = $true }
    return $p
}

function Get-WarmupLeft($w) {
    # Prechauffage (calibration ou ecriture lente) : avancement (%) et temps restant (s) ; la lecture en cours peut depasser
    # la duree prevue (duree moyenne des lectures)
    $now = Get-Date
    $el = ($now - $w.WarmStart).TotalSeconds
    $left = [math]::Max(0.0, $w.WarmSec - $el)
    if (@($w.WarmDurs).Count -gt 0 -and $w.WarmReadStart -is [datetime]) {
        $avg = (@($w.WarmDurs) | Measure-Object -Average).Average
        $left = [math]::Max($left, $avg - ($now - $w.WarmReadStart).TotalSeconds)
    }
    $pct = [int][math]::Floor(100 * $el / [math]::Max(1.0, $el + $left))
    return @{ Pct = [math]::Max(0, [math]::Min(100, $pct)); Left = $left }
}

function Start-CalibWarmup {
    # Prechauffage du lecteur avant la premiere passe de mesure d une calibration complete (Start-PrecompCalib, apres
    # l avertissement et la remise eventuelle de la disquette sacrifiee) : lectures sans ecriture des cylindres de test,
    # deux tetes, vers un fichier temporaire, en boucle jusqu a la duree (Get-CalWarmupPlan). Etape 'warmup' de la
    # calibration : « Arreter » l interrompt comme une passe ; une lecture en echec (disquette vierge ou illisible) est
    # sans effet (GwSoft) ; seul l echec du lancement de gw arrete la calibration (Start-Gw, Reset-GwSequence). Apres
    # CalWarmupMaxFails lectures de suite sans aboutir (code non nul, ou code 0 et lecture incomplete : Greaseweazle,
    # lecteur ou disquette absent), le prechauffage est abrege et la calibration commence (Invoke-CalibWarmup).
    # Aussi appele par Start-LevelCalib avant une ecriture lente (mode 'level') : retour a l etape d appel (WarmNext).
    # Bouton « Passer le prechauffage » : fin apres la lecture en cours (WarmSkip).
    $cal = $script:Cal
    if (-not $cal) { return }
    if ([double]$script:CalWarmupMinutes -le 0) { New-CalibPass; return }
    # Case « Prechauffer » decochee dans la fenetre de la carte Calibration (Start-PrecompCalib -NoWarmup)
    if ($cal.NoWarmup) { Append-Log ((T "Préchauffage du lecteur {0} désactivé pour cette calibration.") -f "$($cal.Drive)"); New-CalibPass; return }
    $plan = Get-CalWarmupPlan (Get-GwDriveKey (@('read') + (Get-CalibDriveArgsFor 'warmup'))) ([double]$script:CalWarmupMinutes)   # 12.10 : calibration croisee : la source (le lecteur qui ecrit) est prechauffee
    $actTxt = Format-CalDuration ([math]::Round($plan.Active)); $idleTxt = Format-CalDuration ([math]::Round($plan.Idle))
    if ($plan.Skip) {
        Append-Log ((T "Préchauffage du lecteur {0} sauté : lecteur déjà en activité pendant {1} (dernière commande terminée il y a {2}).") -f "$($cal.Drive)", "$actTxt", "$idleTxt")
        New-CalibPass; return
    }
    $durTxt = Format-CalDuration ([math]::Round($plan.Sec))
    if ($cal.Mode -eq 'level') {
        if ($plan.Reduced) { Append-Log ((T "Préchauffage du lecteur {0} : {1} de lecture sans écriture avant la calibration rapide et l'écriture lente, pour que le niveau soit mesuré dans l'état du lecteur au moment de l'écriture (durée réduite : lecteur déjà en activité pendant {2}, dernière commande terminée il y a {3}).") -f "$($cal.Drive)", "$durTxt", "$actTxt", "$idleTxt") }
        else { Append-Log ((T "Préchauffage du lecteur {0} : {1} de lecture sans écriture avant la calibration rapide et l'écriture lente, pour que le niveau soit mesuré dans l'état du lecteur au moment de l'écriture.") -f "$($cal.Drive)", "$durTxt") }
    }
    elseif ($cal.Mode -eq 'content') {
        # 12.8.1 : mesure de la disquette sur l image (276), avant l ecriture lente ; retour au stade 'content' (WarmNext)
        if ($plan.Reduced) { Append-Log ((T "Préchauffage du lecteur {0} : {1} de lecture sans écriture avant la mesure de la disquette sur l'image et l'écriture lente (durée réduite : lecteur déjà en activité pendant {2}, dernière commande terminée il y a {3}).") -f "$($cal.Drive)", "$durTxt", "$actTxt", "$idleTxt") }
        else { Append-Log ((T "Préchauffage du lecteur {0} : {1} de lecture sans écriture avant la mesure de la disquette sur l'image et l'écriture lente.") -f "$($cal.Drive)", "$durTxt") }
    }
    elseif ($plan.Reduced) { Append-Log ((T "Préchauffage du lecteur {0} : {1} de lecture sans écriture avant la calibration, pour stabiliser sa température (durée réduite : lecteur déjà en activité pendant {2}, dernière commande terminée il y a {3}).") -f "$($cal.Drive)", "$durTxt", "$actTxt", "$idleTxt") }
    else { Append-Log ((T "Préchauffage du lecteur {0} : {1} de lecture sans écriture avant la calibration, pour stabiliser sa température.") -f "$($cal.Drive)", "$durTxt") }
    $cal.WarmNext = [string]$cal.Stage
    $cal.Stage = 'warmup'; $cal.WarmSec = [double]$plan.Sec; $cal.WarmStart = Get-Date; $cal.WarmReads = 0; $cal.WarmFails = 0
    $cal.WarmFailRun = 0; $cal.WarmSkip = $false
    $cal.WarmDurs = @(); $cal.WarmReadStart = $null
    $cal.WarmScp = Join-Path $script:TempDir 'precomp-warmup.scp'
    $cal.WarmArgs = @('read') + (Get-CalibDriveArgsFor 'warmup') + @(Get-DriveReadArgs) + @('--revs=3', "--tracks=$($cal.TSpec)", "`"$($cal.WarmScp)`"")
    Invoke-CalibWarmup
}

function Invoke-CalibWarmup {
    # Lecture de prechauffage suivante, ou premiere passe de mesure : CalWarmupMinReads lectures au moins, puis arret a la
    # duree, ou avant une lecture qui la depasserait de plus de la moitie de la duree moyenne d une lecture. Lecture sans
    # aboutir : code non nul, ou code 0 et lecture incomplete (GwLastIncomplete) ; CalWarmupMaxFails de suite : defaut
    # materiel probable (Greaseweazle, lecteur ou disquette absent), prechauffage abrege, la calibration commence et sa
    # premiere ecriture signale le defaut s il persiste
    $cal = $script:Cal
    if (-not $cal -or $cal.Stage -ne 'warmup') { return }
    if ($cal.WarmReadStart -is [datetime]) {
        $cal.WarmDurs += ((Get-Date) - $cal.WarmReadStart).TotalSeconds; $cal.WarmReadStart = $null
        $code = [int]$script:GwLastCode
        if ($code -ne 0 -or [bool]$script:GwLastIncomplete) {
            $cal.WarmFails++; $cal.WarmFailRun++
            if ($cal.WarmFails -eq 1) { Append-Log ((T "Préchauffage du lecteur {0} : la lecture n'a pas abouti (code {1}) ; sans effet sur la calibration, le préchauffage continue.") -f "$($cal.Drive)", "$code") }
        } else { $cal.WarmFailRun = 0 }
        if ($cal.WarmFailRun -ge $script:CalWarmupMaxFails) {
            if (Test-Path -LiteralPath $cal.WarmScp) { Remove-Item -LiteralPath $cal.WarmScp -Force -ErrorAction SilentlyContinue }
            Append-Log ((T "Préchauffage du lecteur {0} arrêté après {1} lectures de suite sans aboutir (Greaseweazle, lecteur ou disquette absent ?) : la calibration commence, sa première commande signalera le défaut s'il persiste.") -f "$($cal.Drive)", "$($cal.WarmFailRun)")
            $cal.Stage = if ($cal.WarmNext) { [string]$cal.WarmNext } else { 'coarse' }
            New-CalibPass; return
        }
    }
    $left = $cal.WarmSec - ((Get-Date) - $cal.WarmStart).TotalSeconds
    $avg = if (@($cal.WarmDurs).Count -gt 0) { (@($cal.WarmDurs) | Measure-Object -Average).Average } else { 0.0 }
    if (Test-Path -LiteralPath $cal.WarmScp) { Remove-Item -LiteralPath $cal.WarmScp -Force -ErrorAction SilentlyContinue }
    # Fin : duree atteinte, ou prechauffage passe a la demande (bouton « Passer le prechauffage », apres la lecture en cours)
    if (($cal.WarmSkip -and $cal.WarmReads -ge 1) -or ($cal.WarmReads -ge $script:CalWarmupMinReads -and ($left -le 0 -or $left -lt $avg / 2))) {
        $elTxt = Format-CalDuration ([math]::Round(((Get-Date) - $cal.WarmStart).TotalSeconds))
        if ($cal.WarmFails -gt 0) { Append-Log ((T "Préchauffage du lecteur {0} terminé : {1} lecture(s) en {2}, dont {3} sans aboutir (sans effet sur la calibration).") -f "$($cal.Drive)", "$($cal.WarmReads)", "$elTxt", "$($cal.WarmFails)") }
        else { Append-Log ((T "Préchauffage du lecteur {0} terminé : {1} lecture(s) en {2}.") -f "$($cal.Drive)", "$($cal.WarmReads)", "$elTxt") }
        $cal.Stage = if ($cal.WarmNext) { [string]$cal.WarmNext } else { 'coarse' }
        New-CalibPass; return
    }
    $cal.WarmReads++; $cal.WarmReadStart = Get-Date; $script:GwLastCode = 0; $script:GwLastIncomplete = $false
    Update-CalibProgress
    $script:Chain.Clear()
    $script:Chain.Enqueue({ Start-Gw ([string[]]$script:Cal.WarmArgs) })
    $script:Chain.Enqueue({ Invoke-CalibWarmup })
    Invoke-NextChainStep
}

function Set-CalibCoarsePlan($cal) {
    # 12.9 (corrections 2 et 3) : valeur ecrite par cylindre a la passe de mesure $cal.Index (PassW), profil --precomp
    # (Spec) et libelle de la barre (ValueTxt). Carre latin ($cal.Latin, double densite) : Get-CalibLatinW, une entree c=ns
    # par cylindre de test (Get-BracketSpec, comme l encadrement : gw applique chaque valeur a partir de son cylindre, et
    # seuls les cylindres de --tracks sont ecrits) ; sinon (haute densite) meme valeur pour tous, profil « 0=v » (12.8.2)
    $p = [int]$cal.Index
    $cal.Value = [int]$cal.Values[$p]
    if ($cal.Latin) {
        $cal.PassW = Get-CalibLatinW ([int[]]@($cal.Cyls)) ([int[]]@($cal.Values)) $p
        $cal.Spec = Get-BracketSpec $cal.PassW
        $cal.ValueTxt = "$(@($cal.Values) -join '/') ns"
    } else {
        $cal.PassW = @{}; foreach ($c in @($cal.Cyls)) { $cal.PassW[[int]$c] = $cal.Value }
        $cal.Spec = "0=$($cal.Value)"; $cal.ValueTxt = "$($cal.Value) ns"
    }
}

function Add-CalibWriteCmds($cal, $writes) {
    # Commandes d ecriture d une passe dans la file $cal.Writes ($writes : @(TSPEC, profil) par commande). 12.8.2 : double
    # densite (Get-EraseMode : famille autre que hd, motif de moins de 150 000 cellules comme Test-CurveHd, ni secteurs durs
    # ni TG43) : toutes les pistes ecrites (TSPEC des ecritures, Get-TSpecKeys) d abord effacees en haute frequence (gw erase
    # --hfreq, TSPEC exacts), puis motif sans --pre-erase ; haute densite : --pre-erase. 12.9 : partage par New-CalibPass et
    # le conditionnement du lecteur (Start-CalibCondition) ; texte deplace de New-CalibPass, inchange
    $cal.Writes.Clear()
    $hf = ((Get-EraseMode ([string]$cal.Family -eq 'hd' -or [int]$cal.PatternBits -ge 150000)) -eq 'hfreq')
    $ek = @{}
    if ($hf) {
        foreach ($w in $writes) {
            $wk = Get-TSpecKeys ([string]$w[0])
            if (@($wk).Count -eq 0) { $hf = $false; break }        # TSPEC illisible : pre-effacement pour cette passe
            foreach ($k in $wk) { $ek[[string]$k] = $true }
        }
    }
    if ($hf) {
        foreach ($ec in (New-HfreqEraseCmds @($ek.Keys) '' (@(Get-CalibDriveArgsFor 'erase') + @(Get-EraseDriveArgs)))) { $cal.Writes.Enqueue([string[]]$ec) }   # 12.10 : lecteur source en croise
        if (-not $cal.EraseNoted) { $cal.EraseNoted = $true; Append-Log (T "Calibration : disquette double densité, chaque passe efface d'abord en haute fréquence les pistes qu'elle écrit (gw erase --hfreq), puis écrit le motif sans pré-effacement.") }
    }
    $pe = if ($hf) { @('--no-verify') } else { @('--pre-erase', '--no-verify') }
    foreach ($w in $writes) {
        $cal.Writes.Enqueue([string[]](@('write') + (Get-CalibDriveArgsFor 'write') + $pe + (Get-CalibDriveArgs) + @("--tracks=$($w[0])", '--precomp', $w[1], "`"$($cal.Pattern)`"")))   # 12.10 : lecteur source en croise
    }
}

function Start-CalibCondition($cal) {
    # 12.9 (correction 1) : conditionnement du lecteur juste avant la premiere passe de mesure. La premiere ecriture qui
    # suit une periode sans ecriture (prechauffage en lecture seule compris) peut porter un transitoire de quelques ns de
    # decalage sur ses premieres pistes (emulation 80 cylindres du 31/10/2026 : jusqu a +5,5 ns sur c0-c19 ; intermittent) :
    # effacement haute frequence puis ecriture du motif sur tous les cylindres de l image (2 faces), avec le profil de la
    # passe 1, sans relecture ni analyse, pour que les passes de mesure partent d un lecteur en ecriture. Une fois par
    # disquette (CondDone ; Restart-PrecompCalib le remet a faux). Erreur gw : abandon, comme a la passe 1
    # (Stop-PrecompCalib -GwError)
    Set-CalibCoarsePlan $cal
    $cal.CondRun = $true; $cal.CondStart = Get-Date
    $cal.CondTSpec = "c=0-$([int]$cal.MaxCyl):h=0-1"
    # 12.9 (revue du 31/10/2026, m3) : texte selon l effacement que feront les commandes (meme expression que
    # Add-CalibWriteCmds) : pre-effacement (--pre-erase, sans gw erase) sous les options de lecteur que gw erase ne prend
    # pas en charge (Get-EraseFallbackNote : secteurs durs, TG43, --densel)
    $hfC = ((Get-EraseMode ([string]$cal.Family -eq 'hd' -or [int]$cal.PatternBits -ge 150000)) -eq 'hfreq')
    if ($hfC) { Append-Log ((T "Calibration : conditionnement du lecteur {0} avant la première passe de mesure : effacement haute fréquence puis écriture du motif sur les cylindres {1} (2 faces), sans relecture, pour que les passes de mesure partent d'un lecteur en écriture.") -f "$($cal.Drive)", "0-$([int]$cal.MaxCyl)") }
    else { Append-Log ((T "Calibration : conditionnement du lecteur {0} avant la première passe de mesure : écriture du motif avec pré-effacement sur les cylindres {1} (2 faces), sans relecture, pour que les passes de mesure partent d'un lecteur en écriture.") -f "$($cal.Drive)", "0-$([int]$cal.MaxCyl)") }
    Add-CalibWriteCmds $cal @(,@($cal.CondTSpec, $cal.Spec))
    New-ProgPlan @($cal.Writes.ToArray())   # 12.11 : plan du conditionnement pour la barre de progression (110)
    $cal.PassStart = Get-Date; $cal.PhaseStart = $cal.PassStart; $cal.Phase = 'write'
    Update-CalibProgress
    $script:Chain.Clear()
    if ($cal.Cross) { $script:Chain.Enqueue({ Invoke-CalibSwap 'S' }) }   # 12.10 : disquette dans la source avant d ecrire (sans effet si elle y est)
    $nCmd = $cal.Writes.Count
    for ($i = 0; $i -lt $nCmd; $i++) { $script:Chain.Enqueue({ Start-Gw ([string[]]$script:Cal.Writes.Dequeue()) }) }
    $script:Chain.Enqueue({ Complete-CalibCondition })
    Invoke-NextChainStep
}

function Complete-CalibCondition {
    # 12.9 (correction 1) : fin du conditionnement : une ecriture de plus par piste conditionnee (garde WriteMax :
    # Get-CalibRetestPlan, Add-DriftWitnesses), duree mesuree (barre de progression), puis premiere passe de mesure
    $cal = $script:Cal
    if (-not $cal -or -not $cal.CondRun) { return }
    $cal.CondRun = $false; $cal.CondDone = $true
    $cal.CondSec = ((Get-Date) - $cal.CondStart).TotalSeconds
    foreach ($u in @($cal.Units)) { for ($c = 0; $c -le [int]$cal.MaxCyl; $c++) { $u.Writes[$c] = 1 + [int]$u.Writes[$c] } }
    Append-Log ((T "Calibration : conditionnement du lecteur terminé en {0}.") -f (Format-CalDuration $cal.CondSec))
    New-CalibPass
}

function Invoke-CalibSwap([string]$to) {
    # 12.10 : etape de la chaine d une calibration croisee : la disquette doit etre dans la source ('S', le lecteur qui ecrit)
    # avant un effacement ou une ecriture, dans la cible ('T', le lecteur qui relit) avant une relecture. Deja au bon
    # endroit (ecritures consecutives : conditionnement puis passe 1) : etape suivante sans invite. Sinon invite frmCalibSwap
    # (Show-TimedConfirm sans compte a rebours, comme frmReinsert ; le banc y repond par OpenForms), libelle de la barre
    # fige pendant l attente (SwapHold, Update-CalibProgress), echange compte (Swaps), duree de l attente retiree de la
    # phase en cours (PhaseStart : durees des phases et estimation de la barre), puis etape suivante. Annuler, Echap ou la
    # croix : chaine videe, calibration arretee (Stop-PrecompCalib), la disquette reste ou elle est.
    # Configuration (constat du banc du 09/11/2026 : fichier reecrit apres une annulation, contenu identique hors _saved) :
    # ni cette annulation ni Stop-PrecompCalib n enregistrent rien ; le fichier a ete reecrit avant l invite, par Start-Gw
    # (110), qui appelle Save-Config avant chaque commande gw de toute operation hors restauration et detection (reglages
    # enregistres a chaque commande lancee, calibrations ordinaires comprises). Voulu, et laisse tel quel : retirer cet
    # enregistrement pour la seule calibration croisee changerait une regle commune a toutes les operations
    $cal = $script:Cal
    if (-not $cal) { return }
    if (-not $cal.Cross -or [string]$cal.DiskAt -eq $to) { Invoke-NextChainStep; return }
    $from = if ($to -eq 'T') { [string]$cal.Cross.Src } else { [string]$cal.Cross.Tgt }
    $dest = if ($to -eq 'T') { [string]$cal.Cross.Tgt } else { [string]$cal.Cross.Src }
    $role = if ($to -eq 'T') { (T 'celui qui relit') } else { (T 'celui qui écrit') }
    $n = 1 + [int]$cal.Swaps
    $txt = (T "Échange {0} : retirez la disquette du lecteur {1} et insérez-la dans le lecteur {2}, {3}, puis cliquez sur « J'ai déplacé la disquette ».`nAnnuler : la calibration s'arrête, rien de plus n'est écrit.") -f "$n", "$from", "$dest", "$role"
    Append-Log ((T "Calibration croisée, échange {0} : déplacez la disquette du lecteur {1} vers le lecteur {2} ({3}).") -f "$n", "$from", "$dest", "$role")
    $cal.SwapHold = @{ From = $from; To = $dest }
    Update-CalibProgress
    $t0 = Get-Date
    try { $q = Show-TimedConfirm 'frmCalibSwap' (T 'Calibration precomp') $txt (T "J'ai déplacé la disquette") 'Check' '' '' '' '' -Seconds 0 -Heading ((T 'Déplacez la disquette vers le lecteur {0}') -f "$dest") -Level 'info' -Picto 'drive' }
    finally { $cal.SwapHold = $null }
    if ($cal.PhaseStart -is [datetime]) { $cal.PhaseStart = $cal.PhaseStart.Add((Get-Date) - $t0) }
    if (-not $q.Ok) {
        $script:Chain.Clear()
        Append-Log ((T "Calibration croisée arrêtée à votre demande (échange {0} annulé) ; la disquette est dans le lecteur {1}.") -f "$n", "$from")
        Stop-PrecompCalib
        return
    }
    $cal.DiskAt = $to; $cal.Swaps = $n
    Append-Log ((T "Échange {0} fait : disquette dans le lecteur {1}.") -f "$n", "$dest")
    Invoke-NextChainStep
}

function New-CalibPass {
    # Une passe = une ou deux commandes gw write puis une relecture en flux.
    #  - mesure : une valeur par cylindre de test (carre latin en double densite, Set-CalibCoarsePlan), la meme pour les deux tetes, une commande ;
    #  - encadrement : cylindres encore sous-compenses a la plus forte valeur mesuree, ecrits a leur estimation +
    #    CalBracketMargin (une valeur par cylindre ; par tete en ecriture lente), relus seuls ;
    #  - verification : le profil obtenu ; en ecriture lente tete 0 puis tete 1, chacune avec son profil.
    # 12.8.1 (spec-1281.md § A.9) : mesure de la disquette sur l image (stade 'content' : premiere passe apres les fins du
    # prechauffage, Start-CalibWarmup et Invoke-CalibWarmup) : passes propres (New-ContentPass, 276)
    if ($script:Cal -and $script:Cal.Stage -eq 'content') { New-ContentPass; return }
    $cal = $script:Cal
    $writes = @(); $readTs = $cal.TSpec
    if ($cal.Stage -eq 'coarse') {
        # 12.9 (correction 1) : conditionnement du lecteur juste avant la premiere passe de mesure (une fois par disquette)
        if ($cal.Cond -and [int]$cal.Index -eq 0 -and -not $cal.CondDone) { Start-CalibCondition $cal; return }
        Set-CalibCoarsePlan $cal
        if ($cal.Latin) { Append-Log ((T "Calibration : passe de mesure {0}/{1}, niveaux {2} ns répartis sur les cylindres (chaque cylindre reçoit chaque niveau une fois en {1} passes)") -f "$($cal.Index + 1)", "$($cal.Values.Count)", "$(@($cal.Values) -join '/')") }
        else { Append-Log ((T "Calibration : passe de mesure {0}/{1}, precomp {2} ns") -f "$($cal.Index + 1)", "$($cal.Values.Count)", "$($cal.Value)") }
        $writes += ,@($cal.TSpec, $cal.Spec)
    } elseif ($cal.Stage -eq 'bracket') {
        $cal.ValueTxt = (T 'encadrement')
        $all = @{}
        foreach ($u in $cal.Units) { foreach ($c in @($u.Bracket.Keys)) { $all[[int]$c] = $true } }
        $cyls = [int[]]@($all.Keys | Sort-Object)
        if ($cal.Slow) {
            foreach ($u in $cal.Units) { if ($u.Bracket.Count -gt 0) { $writes += ,@("c=$(Format-CylList ([int[]]@($u.Bracket.Keys))):h=$($u.Head)", (Get-BracketSpec $u.Bracket)) } }
        } else {
            $writes += ,@("c=$(Format-CylList $cyls):h=0-1", (Get-BracketSpec $cal.Units[0].Bracket))
        }
        $readTs = "c=$(Format-CylList $cyls):h=0-1"
        $specTxt = (@($cal.Units | ForEach-Object { "$($_.Prefix)$(Get-BracketSpec $_.Bracket)" } | Where-Object { $_ -match '=' })) -join ' ; '
        Append-Log ((T "Calibration : passe d'encadrement des cylindres {0}, encore sous-compensés à {1} ns : precomp {2}") -f (Format-CylList $cyls), "$($cal.MaxCoarse)", "$specTxt")
    } elseif ($cal.Stage -eq 'densify') {
        $cal.ValueTxt = (T "mesure complémentaire {0}") -f "$($cal.DensePass)"
        $all = @{}
        foreach ($u in $cal.Units) { foreach ($c in @($u.Dense.Keys)) { $all[[int]$c] = $true } }
        $cyls = [int[]]@($all.Keys | Sort-Object)
        if ($cal.Slow) {
            foreach ($u in $cal.Units) { if ($u.Dense.Count -gt 0) { $writes += ,@("c=$(Format-CylList ([int[]]@($u.Dense.Keys))):h=$($u.Head)", (Get-BracketSpec $u.Dense)) } }
        } else {
            $writes += ,@("c=$(Format-CylList $cyls):h=0-1", (Get-BracketSpec $cal.Units[0].Dense))
        }
        $readTs = "c=$(Format-CylList $cyls):h=0-1"
        $specTxt = (@($cal.Units | ForEach-Object { "$($_.Prefix)$(Get-BracketSpec $_.Dense)" } | Where-Object { $_ -match '=' })) -join ' ; '
        Append-Log ((T "Calibration : mesure complémentaire {0} des cylindres {1} : precomp {2}") -f "$($cal.DensePass)", (Format-CylList $cyls), "$specTxt")
    } elseif ($cal.Stage -eq 'reach') {
        # 12.8 (S3-HIGH) : mesure complete de cette disquette : passe de mesure directe (Start-DiskReach) des cylindres dont
        # le zero estime depasse le plafond des passes de mesure, ecrits a cette estimation, au plus a la borne de cette
        # disquette (une valeur par cylindre ; par tete en ecriture lente), relus seuls
        $cal.ValueTxt = (T 'mesure directe')
        $all = @{}
        foreach ($u in $cal.Units) { foreach ($c in @($u.Reach.Keys)) { $all[[int]$c] = $true } }
        $cyls = [int[]]@($all.Keys | Sort-Object)
        if ($cal.Slow) {
            foreach ($u in $cal.Units) { if ($u.Reach.Count -gt 0) { $writes += ,@("c=$(Format-CylList ([int[]]@($u.Reach.Keys))):h=$($u.Head)", (Get-BracketSpec $u.Reach)) } }
        } else {
            $writes += ,@("c=$(Format-CylList $cyls):h=0-1", (Get-BracketSpec $cal.Units[0].Reach))
        }
        $readTs = "c=$(Format-CylList $cyls):h=0-1"
        $specTxt = (@($cal.Units | ForEach-Object { "$($_.Prefix)$(Get-BracketSpec $_.Reach)" } | Where-Object { $_ -match '=' })) -join ' ; '
        Append-Log ((T "Mesure complète : passe de mesure directe des cylindres {0}, besoin estimé au-delà de {1} ns (plafond des passes de mesure), écrits à leur estimation, au plus {2} ns : precomp {3}") -f (Format-CylList $cyls), "$($script:CalMaxNs)", "$($script:CalHardNs)", "$specTxt")
    } elseif ($cal.Stage -eq 'level') {
        # Calibration rapide : reference decalee du niveau courant sur les seuls cylindres de mesure ; ecriture rapide une
        # commande (h=0-1), ecriture lente une commande par tete non terminee
        $all = @{}; $parts = @()
        foreach ($u in $cal.Units) {
            if ($u.Done) { continue }
            $lc = [int[]]@($u.LTarget.Keys | ForEach-Object { [int]$_ } | Sort-Object)
            foreach ($c in $lc) { $all[$c] = $true }
            $lv = '{0:+0;-0;0}' -f [int]$u.D
            # 12.8 (lot 1c, § 11.2) : tete en passe de mesure, de verification ou de confirmation de la pente
            $md = [string]$u.Mode
            if ($null -eq $u.Head) { $parts += ((T "niveau {0} ns") -f "$lv") }
            elseif ($md -eq 'meas') { $parts += ((T 'tête {0} mesure adaptative') -f "$($u.Head)") }
            elseif ($md -eq 'verif') { $parts += ((T 'tête {0} courbe adaptée') -f "$($u.Head)") }
            elseif ($md -eq 'nwc') { $parts += ((T 'tête {0} confirmation de la pente') -f "$($u.Head)") }
            else { $parts += ((T "tête {0} {1} ns") -f "$($u.Head)", "$lv") }
            if ($cal.Slow) { $writes += ,@("c=$(Format-CylList $lc):h=$($u.Head)", (Get-BracketSpec $u.LTarget)); $cal.TrackWrites += $lc.Count }
            else { $writes += ,@("c=$(Format-CylList $lc):h=0-1", (Get-BracketSpec $u.LTarget)); $cal.TrackWrites += 2 * $lc.Count }
        }
        $cal.ValueTxt = $parts -join ', '
        $readTs = "c=$(Format-CylList ([int[]]@($all.Keys | Sort-Object))):h=0-1"
        Append-Log ((T "Calibration rapide : passe {0}/{1}, {2}") -f "$($cal.LPass)", "$($script:LevelMaxPasses)", "$($cal.ValueTxt)")
    } elseif ($cal.Slow) {
        # Verification : tous les cylindres estimes (V1), puis seulement ceux dont la valeur a change (V2, VerifyList)
        $cal.ValueTxt = (T 'profil')
        $all = @{}
        foreach ($u in $cal.Units) {
            $lst = if ($null -ne $u.VerifyList) { @($u.VerifyList) } else { @($cal.Cyls) }
            if ($lst.Count -eq 0) { continue }
            foreach ($c in $lst) { $all[[int]$c] = $true }
            $writes += ,@("c=$(Format-CylList ([int[]]$lst)):h=$($u.Head)", $u.Profile)
        }
        if ($null -ne $cal.Units[0].VerifyList) {
            $vlTxt = (@($cal.Units | Where-Object { @($_.VerifyList).Count -gt 0 } | ForEach-Object { $uu = $_; "$($uu.Prefix)$(Format-CylList ([int[]]@(@($uu.VerifyList) | Where-Object { @($uu.Witness) -notcontains $_ })))" })) -join ' ; '
            # 12.8 (lot 1b) : passe du nouvel essai (Start-CalibRetest), numerotee apres les verifications prevues
            if ([int]$cal.Retests -gt 0) { Append-Log ((T "Calibration : passe de vérification {0}/{1} du nouvel essai, cylindres relus (non convergés, voisins immédiats et cylindres modifiés) : {2}") -f "$($cal.VerifyCount)", "$([int]$cal.VerifyCount)", "$vlTxt") }
            else { Append-Log ((T "Calibration : passe de vérification {0}/{1} ciblée sur les cylindres modifiés : {2}") -f "$($cal.VerifyCount)", "$($script:CalMaxVerify)", "$vlTxt") }
            # 12.8 (lot 1b) : unites ecrites a cette passe seulement (passe du nouvel essai : une tete hors nouvel essai garde
            # les temoins de son jugement, sans etre ecrite)
            $wt = @($cal.Units | Where-Object { @($_.Witness).Count -gt 0 -and @($_.VerifyList).Count -gt 0 } | ForEach-Object { "$($_.Prefix)$(Format-CylList ([int[]]@($_.Witness)))" })
            if ($wt.Count -gt 0) { Append-Log ((T "Calibration : témoins de dérive, réécrits à leur valeur inchangée et relus pour mesurer l'écart du lecteur entre deux vérifications : {0}") -f ($wt -join ' ; ')) }
        } else {
            Append-Log ((T "Calibration : passe de vérification {0}/{1}, tête 0 puis tête 1, profils {2} et {3}") -f "$($cal.VerifyCount)", "$($script:CalMaxVerify)", "$($cal.Units[0].Profile)", "$($cal.Units[1].Profile)")
        }
        $readTs = "c=$(Format-CylList ([int[]]@($all.Keys | Sort-Object))):h=0-1"
    } else {
        $cal.Spec = $cal.Units[0].Profile; $cal.ValueTxt = (T 'profil')
        $u0 = $cal.Units[0]
        if ($null -ne $u0.VerifyList) {
            $lst = [int[]]@($u0.VerifyList)
            $vlTxt = Format-CylList ([int[]]@($lst | Where-Object { @($u0.Witness) -notcontains $_ }))
            # 12.8 (lot 1b) : passe du nouvel essai (Start-CalibRetest), numerotee apres les verifications prevues
            if ([int]$cal.Retests -gt 0) { Append-Log ((T "Calibration : passe de vérification {0}/{1} du nouvel essai, cylindres relus (non convergés, voisins immédiats et cylindres modifiés) : {2}") -f "$($cal.VerifyCount)", "$([int]$cal.VerifyCount)", "$vlTxt") }
            else { Append-Log ((T "Calibration : passe de vérification {0}/{1} ciblée sur les cylindres modifiés : {2}") -f "$($cal.VerifyCount)", "$($script:CalMaxVerify)", "$vlTxt") }
            if (@($u0.Witness).Count -gt 0) { Append-Log ((T "Calibration : témoins de dérive, réécrits à leur valeur inchangée et relus pour mesurer l'écart du lecteur entre deux vérifications : {0}") -f (Format-CylList ([int[]]@($u0.Witness)))) }
            $writes += ,@("c=$(Format-CylList $lst):h=0-1", $cal.Spec)
            $readTs = "c=$(Format-CylList $lst):h=0-1"
        } else {
            Append-Log ((T "Calibration : passe de vérification {0}/{1}, profil {2}") -f "$($cal.VerifyCount)", "$($script:CalMaxVerify)", "$($cal.Spec)")
            $writes += ,@($cal.TSpec, $cal.Spec)
        }
    }
    if (Test-Path -LiteralPath $cal.Scp) { Remove-Item -LiteralPath $cal.Scp -Force }
    # 12.8.2 : en double densite, les pistes que la passe ecrit sont d abord effacees en haute frequence (TSPEC exacts : une
    # piste non reecrite a cette passe garde son motif), puis le motif est ecrit sans --pre-erase ; haute densite :
    # --pre-erase. Toutes les calibrations passent ici : complete, test rapide, mesure complete de la disquette, carte de
    # l Accueil, calibration B, refaire, nouvel essai, verifications et temoins de derive. 12.9 : commandes construites par
    # Add-CalibWriteCmds, partagee avec le conditionnement du lecteur (Start-CalibCondition)
    Add-CalibWriteCmds $cal $writes
    $cal.ReadArgs  = @('read') + (Get-CalibDriveArgsFor 'read') + @(Get-DriveReadArgs) + @('--revs=3', "--tracks=$readTs", "`"$($cal.Scp)`"")   # 12.10 : lecteur cible en croise
    # 12.11 : plan de la passe pour la barre de progression (110) : ses effacements, ses ecritures, puis sa relecture,
    # tels qu ils viennent d etre construits ; ne lance rien et ne modifie aucune commande
    New-ProgPlan (@($cal.Writes.ToArray()) + ,$cal.ReadArgs)
    $cal.PassStart = Get-Date; $cal.PhaseStart = $cal.PassStart; $cal.Phase = 'write'
    Update-CalibProgress
    $script:Chain.Clear()
    # 12.10 : calibration croisee : disquette ramenee dans la source avant les ecritures, portee dans la cible avant la
    # relecture (Invoke-CalibSwap : invite seulement si elle n y est pas deja) ; calibration ordinaire : chaine inchangee
    $nCmd = $cal.Writes.Count
    if ($cal.Cross -and $nCmd -gt 0) { $script:Chain.Enqueue({ Invoke-CalibSwap 'S' }) }
    for ($i = 0; $i -lt $nCmd; $i++) { $script:Chain.Enqueue({ Start-Gw ([string[]]$script:Cal.Writes.Dequeue()) }) }
    if ($cal.Cross) { $script:Chain.Enqueue({ Invoke-CalibSwap 'T' }) }
    $script:Chain.Enqueue({
        $script:Cal.WriteDurs += ((Get-Date) - $script:Cal.PhaseStart).TotalSeconds
        $script:Cal.Phase = 'read'; $script:Cal.PhaseStart = Get-Date
        Start-Gw $script:Cal.ReadArgs
    })
    $script:Chain.Enqueue({ Invoke-CalibAnalysis })
    Invoke-NextChainStep
}

function Set-CalibEstimates($u, [string]$when = '') {
    # Valeur de precomp par cylindre teste (Get-CalibZero) d apres toutes ses mesures : passes de mesure, passe
    # d encadrement et passes de verification. Pente commune = mediane des pentes nettement negatives (-2 a defaut,
    # valeur theorique), utilisee seulement pour extrapoler un cylindre dont la pente locale n est pas fiable.
    $cal = $script:Cal
    $slopes = @(); $measured = 0
    foreach ($c in $cal.Cyls) {
        $pts = $u.Results[[int]$c]
        if ($pts.Count -lt 2) { continue }
        $measured++
        $xs = @($pts.Keys | ForEach-Object { [int]$_ } | Sort-Object); $ys = @($xs | ForEach-Object { [double]$pts[$_].Shift })
        $mx = ($xs | Measure-Object -Average).Average; $my = ($ys | Measure-Object -Average).Average
        $sxx = 0.0; $sxy = 0.0
        for ($i = 0; $i -lt $xs.Count; $i++) { $sxx += ($xs[$i] - $mx) * ($xs[$i] - $mx); $sxy += ($xs[$i] - $mx) * ($ys[$i] - $my) }
        if ($sxx -gt 0 -and $sxy / $sxx -lt -0.2) { $slopes += $sxy / $sxx }
    }
    if ($measured -eq 0) { Append-Log ($u.Prefix + (T 'Calibration : aucune mesure exploitable pour estimer la précompensation.')); return $false }
    # Tete seule sans aucune pente propre : le decalage ne suit pas la precomp ecrite, la face lue n a pas ete ecrite
    # (tete ou circuit d ecriture defaillant : le motif HFE a toujours deux faces) ; une pente de repli serait sans signification.
    if ($null -ne $u.Head -and $slopes.Count -eq 0) { Append-Log ($u.Prefix + (T 'Calibration : le décalage ne varie pas avec la précompensation écrite, cette face n''a pas été écrite (tête ou circuit d''écriture défaillant ?).')); return $false }
    $pooled = -2.0
    if ($slopes.Count -gt 0) { $sl = @($slopes | Sort-Object); $pooled = $sl[[int][math]::Floor($sl.Count / 2)] }
    $u.Slope = $pooled; $u.Est = @{}; $u.Sig = @{}; $u.Kind = @{}; $u.Own = @{}
    foreach ($c in $cal.Cyls) {
        $z = Get-CalibZero $u.Results[[int]$c] $pooled
        if (-not $z) { continue }
        $u.Est[[int]$c] = $z.Est; $u.Sig[[int]$c] = $z.Sig; $u.Kind[[int]$c] = $z.Kind
        $u.Own[[int]$c] = [bool]$z.Own             # pente propre fiable (sinon pente commune) : Get-TrendEstimates
    }
    foreach ($c in @($u.Outliers)) { if ($u.Kind.ContainsKey([int]$c)) { $u.Kind[[int]$c] = 'outlier' } }
    $mark = @{ interp = ''; extrap = '*'; cap = '^'; outlier = '!' }
    $estTxt = (@($u.Est.Keys | Sort-Object | ForEach-Object { "c$_=$([math]::Round($u.Est[$_], 0))$($mark[$u.Kind[$_]])" })) -join ' '
    Append-Log ($u.Prefix + $when + ((T "Pente moyenne : {0} ns de décalage par ns de precomp ; estimation par cylindre : {1}") -f "$([math]::Round($u.Slope, 2))", "$estTxt"))
    if (@($u.Kind.Values | Where-Object { $_ -ne 'interp' }).Count -gt 0) { Append-Log ($u.Prefix + ((T '  * extrapolée au-delà des mesures, ^ plafonnée à 0 ou {0} ns : valeur peu fiable.') -f "$($script:CalHardNs)")) }
    return $true
}

function Write-CalibPassLog($plog, [string]$label) {
    # 12.8 (lot 1c, point 1, etendu a la calibration complete) : mesures par cylindre d une passe de calibration, rapide
    # ou complete, au journal seulement (ni courbe, ni niveaux, ni historique). $plog : face -> mesures @{ C ; W ; Role ;
    # Shift ; SE } (Invoke-CalibAnalysis). Une ligne par face lue, prefixe « [tete h] », courbe commune comprise (la courbe
    # commune prend la moyenne des deux faces). Element « c<cyl>[ (role)] <valeur ecrite> -> <decalage> ± <erreur-type> »,
    # en ns, une decimale au format de la langue (Format-UiNum), « - » sans erreur-type ; cylindres croissants, separes
    # par « ; ». Format stable, lu par un script (c1\lin\analyze_percyl.py)
    foreach ($h in @($plog.Keys | Sort-Object)) {
        $items = @(@($plog[$h]) | Sort-Object { [int]$_.C } | ForEach-Object {
            $se = if ($null -eq $_.SE -or [double]::IsNaN([double]$_.SE)) { '-' } else { Format-UiNum ([double]$_.SE) '0.0' }
            "c$($_.C)$($_.Role) $($_.W) -> $(Format-UiNum ([double]$_.Shift) '+0.0;-0.0;0.0') ± $se"
        })
        if ($items.Count -eq 0) { continue }
        Append-Log ((T "{0}Mesures de la passe {1} (valeur écrite -> décalage ± erreur-type, ns) : {2}.") -f ((T '[tête {0}] ') -f "$h"), "$label", ($items -join ' ; '))
    }
}

function Set-CalibPassOffsets($cal) {
    # 12.9 (correction 2) : apres la derniere passe de mesure en carre latin (Invoke-CalibAnalysis), decalage propre a chaque
    # passe, par face (Get-CalibPassOffsets), retire de chaque mesure brute de la face (u.Coarse) ; puis, comme en 12.8.2,
    # point de chaque passe dans Results (moyenne des faces lues, erreur-type combinee), mesures de chaque face dans Face
    # (Get-FaceEstimates) et mesures de l unite par passe dans CoarseZ (Get-CalibDents). Estimation impossible pour une face
    # (trop peu de cylindres mesures a tous les niveaux, systeme singulier) : decalages nuls, ligne de journal.
    $n = @($cal.Values).Count
    $lv = [int[]]@($cal.Values)
    foreach ($u in @($cal.Units)) {
        $heads = if ($null -eq $u.Head) { @(0, 1) } else { @([int]$u.Head) }
        $u.PassAlpha = @{}; $u.CoarseZ = @{}
        foreach ($h in $heads) {
            $obs = @(foreach ($k in @($u.Coarse.Keys)) { foreach ($r in @($u.Coarse[$k])) { if ($r.F.ContainsKey([int]$h)) { @{ C = [int]$k; P = [int]$r.P; W = [int]$r.W; Y = [double]$r.F[[int]$h].Shift } } } })
            $fit = Get-CalibPassOffsets $obs $lv $n ([int]$script:CalLatinMinCyl)
            if ($fit.Ok) { $u.PassAlpha[[int]$h] = $fit; continue }
            $why = if ($fit.Why -eq 'singulier') { (T 'système singulier') } else { (T 'trop peu de cylindres mesurés à tous les niveaux') }
            Append-Log ($u.Prefix + ((T "Calibration : décalage des passes de mesure non estimé sur la face {0} ({1}) : mesures prises telles quelles.") -f "$h", "$why"))
        }
        foreach ($k in @($u.Coarse.Keys | ForEach-Object { [int]$_ } | Sort-Object)) {
            foreach ($r in @(@($u.Coarse[$k]) | Sort-Object { [int]$_.P })) {
                $sv = @(); $ev = @()
                foreach ($h in $heads) {
                    if (-not $r.F.ContainsKey([int]$h)) { continue }
                    $a = if ($u.PassAlpha.ContainsKey([int]$h)) { [double]$u.PassAlpha[[int]$h].Alpha[[int]$r.P] } else { 0.0 }
                    $s = [double]$r.F[[int]$h].Shift - $a
                    $sv += $s; $ev += $r.F[[int]$h].SE
                    if (-not $u.Face.ContainsKey([int]$h)) { $u.Face[[int]$h] = @{} }
                    if (-not $u.Face[[int]$h].ContainsKey($k)) { $u.Face[[int]$h][$k] = @{} }
                    Add-CalibPoint $u.Face[[int]$h][$k] ([int]$r.W) @{ Shift = $s; SE = $r.F[[int]$h].SE; Score = [double]::NaN }
                }
                if ($sv.Count -eq 0) { continue }
                $sh = ($sv | Measure-Object -Average).Average
                $se = [double]::NaN
                if (@($ev | Where-Object { [double]::IsNaN([double]$_) }).Count -eq 0) { $q = 0.0; foreach ($x in $ev) { $q += $x * $x }; $se = [math]::Sqrt($q) / $ev.Count }
                Add-CalibPoint $u.Results[$k] ([int]$r.W) @{ Shift = $sh; SE = $se; Score = $r.Score }
                if (-not $u.CoarseZ.ContainsKey($k)) { $u.CoarseZ[$k] = @() }
                $u.CoarseZ[$k] += ,@{ P = [int]$r.P; W = [int]$r.W; Shift = $sh }
            }
        }
        if ($u.PassAlpha.Count -eq 0) { continue }
        # Journal : decalages par face et par passe, erreur-type ; premiere passe encore nettement au-dessus des suivantes
        $faces = @(foreach ($h in @($u.PassAlpha.Keys | Sort-Object)) {
            $fa = $u.PassAlpha[$h]
            (T 'face {0} : {1}') -f "$h", ((@(for ($p = 0; $p -lt $n; $p++) { (T 'passe {0} {1}') -f "$($p + 1)", (Format-UiNum ([double]$fa.Alpha[$p]) '+0.0;-0.0;0.0') })) -join ', ')
        })
        $seMax = [double](@(foreach ($fa in @($u.PassAlpha.Values)) { foreach ($x in @($fa.SE)) { [double]$x } }) | Measure-Object -Maximum).Maximum
        Append-Log ($u.Prefix + ((T "Calibration : décalage propre à chaque passe de mesure, retiré des mesures avant le calcul des zéros (ns de décalage, erreur-type {1} au plus) : {0}. La moyenne de ces décalages, commune à toute la courbe, ne se mesure pas : elle reste dans le niveau de la courbe, que la vérification ne distingue pas de son propre décalage d'écriture.") -f ($faces -join ' ; '), (Format-UiNum $seMax '0.0')))
        foreach ($h in @($u.PassAlpha.Keys | Sort-Object)) {
            $fa = $u.PassAlpha[$h]
            $d1 = [double]$fa.Alpha[0] * $n / ($n - 1); $s1 = [double]$fa.SE[0] * $n / ($n - 1)
            if ($d1 -le [math]::Max([double]$script:CalCondWarnNs, 3.0 * $s1)) { continue }
            # Part commune restante : d1 / n ns de decalage sur toute la courbe, en ns de precompensation par la pente mediane
            # des cylindres (u.Slope n est pose qu ensuite, par Set-CalibEstimates)
            $sls = @(foreach ($k in @($u.CoarseZ.Keys)) {
                $rs = @($u.CoarseZ[$k]); if ($rs.Count -lt 2) { continue }
                $mx = 0.0; $my = 0.0; foreach ($r in $rs) { $mx += [double]$r.W; $my += [double]$r.Shift }; $mx /= $rs.Count; $my /= $rs.Count
                $sxx = 0.0; $sxy = 0.0; foreach ($r in $rs) { $sxx += ([double]$r.W - $mx) * ([double]$r.W - $mx); $sxy += ([double]$r.W - $mx) * ([double]$r.Shift - $my) }
                if ($sxx -gt 0 -and $sxy / $sxx -lt -0.2) { $sxy / $sxx }
            })
            $slp = if ($sls.Count -gt 0) { [math]::Abs([double](Get-Median $sls)) } else { 1.55 }
            Append-Log ($u.Prefix + ((T "Calibration : sur la face {1}, la première passe de mesure lit un décalage plus fort de {0} ns que les suivantes (effet possible de la première écriture). La différence entre les passes est retirée ; la part restante, 1/{3} de cet écart, soit environ {2} ns de précompensation, reste dans le niveau de toute la courbe, que la vérification ne distingue pas de son propre décalage d'écriture.") -f (Format-UiNum $d1 '0.0'), "$h", (Format-LevelNum ($d1 / $n / $slp)), "$n"))
        }
    }
}

function Invoke-CalibAnalysis {
    $cal = $script:Cal
    if (-not $cal) { return }
    # 12.8 (VAL01) : releve absent ou illisible : erreur de la passe (GwError : passe du nouvel essai, jugement de la
    # derniere verification garde ; sinon abandon, comme en 12.7)
    if (-not (Test-Path -LiteralPath $cal.Scp)) { Append-Log (T 'Calibration : fichier SCP absent, analyse impossible.'); Stop-PrecompCalib -GwError; return }
    try { $tracks = Read-ScpFile $cal.Scp ([int]$cal.PatternBits) } catch { Append-Log ((T "Calibration : {0}") -f "$($_.Exception.Message)"); Stop-PrecompCalib -GwError; return }
    $cal.ReadDurs += ((Get-Date) - $cal.PhaseStart).TotalSeconds
    $cal.PassesDone++
    $script:ProgPlan = $null   # 12.11 : passe comptee : son plan est retire (la barre ne compte pas la passe deux fois)
    # 12.10 : releve de l asymetrie du motif (12.11 : garde pour l etude, plus lu par l onglet Qualite) : rapports 3T/2T et
    # 4T/2T du motif relu a la premiere verification complete (tous les cylindres ecrits a la courbe), par piste
    if ($cal.Stage -eq 'verify' -and [int]$cal.VerifyCount -eq 1 -and [int]$cal.Retests -eq 0 -and $null -eq $cal.AsymRef) { $cal.AsymRef = Get-TracksAsym $tracks }
    foreach ($u in $cal.Units) {
        if ($cal.Stage -eq 'level' -and $u.Done) { continue }
        # 12.8 (lot 1b) : passe du nouvel essai : seules les unites concernees (InRetest) ; les autres gardent l etat de leur
        # derniere verification (VerifyPrev, ReadLast, temoins : jugement inchange)
        if ($cal.Stage -eq 'verify' -and [int]$cal.Retests -gt 0 -and -not $u.InRetest) { continue }
        # Moyenne des deux faces (profil commun) ou face de l unite seule (ecriture lente) ; erreur-type combinee
        $heads = if ($null -eq $u.Head) { @(0, 1) } else { @([int]$u.Head) }
        $shifts = @(); $scores = @(); $bad = @(); $one = @()
        $plog = @{}      # 12.8 (lot 1c, point 1) : face -> mesures de la passe (Write-CalibPassLog), journal seulement
        if ($cal.Stage -eq 'verify' -and $null -ne $u.VerifyList) {
            # Verification ciblee : la mesure de la passe precedente, prise a l ancienne valeur, ne vaut plus pour ces
            # cylindres ; non relus a cette passe, ils restent « non relus » (jamais juges sur un residu perime)
            # Mesure precedente gardee a part : la derive entre deux verifications (Get-VerifyDrift) la compare a la nouvelle
            $u.VerifyPrev = @{}; $u.ReadLast = @{}
            foreach ($c in @($u.VerifyList)) {
                $u.ReadLast[[int]$c] = $true
                if ($u.Verify.ContainsKey([int]$c) -and $u.VerifyP.ContainsKey([int]$c)) { $u.VerifyPrev[[int]$c] = @{ Shift = [double]$u.Verify[[int]$c].Shift; P = [double]$u.VerifyP[[int]$c]; Meas = $u.Verify[[int]$c] } }
                [void]$u.Verify.Remove([int]$c); [void]$u.VerifyP.Remove([int]$c)
            }
        }
        foreach ($c in $cal.Cyls) {
            if ($cal.Stage -eq 'bracket' -and -not $u.Bracket.ContainsKey([int]$c)) { continue }
            if ($cal.Stage -eq 'densify' -and -not $u.Dense.ContainsKey([int]$c)) { continue }
            if ($cal.Stage -eq 'reach' -and -not $u.Reach.ContainsKey([int]$c)) { continue }     # 12.8 (S3-HIGH)
            if ($cal.Stage -eq 'verify' -and $null -ne $u.VerifyList -and @($u.VerifyList) -notcontains [int]$c) { continue }
            if ($cal.Stage -eq 'level' -and -not $u.LTarget.ContainsKey([int]$c)) { continue }
            if ($null -ne $u.Writes) { $u.Writes[[int]$c] = 1 + [int]$u.Writes[[int]$c] }   # piste ecrite a cette passe
            $sv = @(); $ev = @(); $jv = @(); $fm = @{}; $miss = @()
            foreach ($h in $heads) {
                $tn = [int]$c * 2 + $h
                if (-not $tracks.ContainsKey($tn)) { $miss += $h; continue }
                $m = Get-CalibTrackMeasure $tracks[$tn]; if ($m) { $sv += $m.Shift; $ev += $m.SE; $fm[[int]$h] = $m } else { $miss += $h }
                $j = Get-CalibTrackScore $tracks[$tn]; if ($j -lt 9999) { $jv += $j }
            }
            if ($sv.Count -eq 0) { $bad += $c; continue }
            # 12.7 : courbe commune mesuree sur une seule face a cette passe (l autre illisible) : valeur inchangee (celle de la
            # face lue), signalee sur la ligne de la passe et au bilan
            if ($heads.Count -gt 1 -and $miss.Count -eq 1) { $one += ,@([int]$c, [int]$miss[0]); $u.OneFace["$c|$($miss[0])"] = $true }
            $sh = ($sv | Measure-Object -Average).Average
            $se = [double]::NaN
            if (@($ev | Where-Object { [double]::IsNaN([double]$_) }).Count -eq 0) { $q = 0.0; foreach ($x in $ev) { $q += $x * $x }; $se = [math]::Sqrt($q) / $ev.Count }
            $jt = if ($jv.Count -gt 0) { ($jv | Measure-Object -Average).Average } else { [double]::NaN }
            $meas = @{ Shift = $sh; SE = $se; Score = $jt }
            switch ($cal.Stage) {
                'coarse'  {
                    # 12.9 (correction 2) : carre latin : mesure brute gardee par face et par passe, decalage propre a chaque
                    # passe retire apres la derniere (Set-CalibPassOffsets) ; haute densite : point ajoute tout de suite
                    if ($cal.Latin) { if (-not $u.Coarse.ContainsKey([int]$c)) { $u.Coarse[[int]$c] = @() }; $u.Coarse[[int]$c] += ,@{ P = [int]$cal.Index; W = [int]$cal.PassW[[int]$c]; F = $fm; Score = $jt } }
                    else { Add-CalibPoint $u.Results[[int]$c] ([int]$cal.PassW[[int]$c]) $meas }
                }
                'bracket' { Add-CalibPoint $u.Results[[int]$c] ([int]$u.Bracket[[int]$c]) $meas }
                'densify' { Add-CalibPoint $u.Results[[int]$c] ([int]$u.Dense[[int]$c]) $meas }
                'reach'   { Add-CalibPoint $u.Results[[int]$c] ([int]$u.Reach[[int]$c]) $meas }      # 12.8 (S3-HIGH)
                'level'   {
                    Add-CalibPoint $u.Results[[int]$c] ([int]$u.LTarget[[int]$c]) $meas
                    # 12.8 (lot 1c) : mesures brutes de chaque passe (passe, valeur ecrite, mesure) : passe de verification
                    # de la calibration rapide adaptative
                    if ($null -ne $u.Raw) { if (-not $u.Raw.ContainsKey([int]$c)) { $u.Raw[[int]$c] = @() }; $u.Raw[[int]$c] += ,@([int]$cal.LPass, [int]$u.LTarget[[int]$c], $meas) }
                }
                default   { $u.Verify[[int]$c] = $meas; $u.VerifyP[[int]$c] = Get-SpecValue $u.Profile ([int]$c) }
            }
            # 12.8 (lot 1c, point 1) : mesure de chaque face lue avec la valeur ecrite a cette passe (journal seulement :
            # ni courbe, ni niveaux, ni historique) ; role du cylindre : temoin de marche ou du plafond (calibration rapide),
            # temoin de derive (verification ciblee)
            $xv = switch ($cal.Stage) { 'coarse' { [int]$cal.PassW[[int]$c] } 'bracket' { [int]$u.Bracket[[int]$c] } 'densify' { [int]$u.Dense[[int]$c] } 'reach' { [int]$u.Reach[[int]$c] } 'level' { [int]$u.LTarget[[int]$c] } default { [int]$u.VerifyP[[int]$c] } }
            $role = if ($cal.Stage -eq 'level') { Get-LevelCylRole $u ([int]$c) } elseif ($cal.Stage -eq 'verify' -and $null -ne $u.VerifyList -and @($u.Witness) -contains [int]$c) { ' ' + (T '(témoin)') } else { '' }
            foreach ($h in @($fm.Keys)) {
                if (-not $plog.ContainsKey([int]$h)) { $plog[[int]$h] = @() }
                $plog[[int]$h] += ,@{ C = [int]$c; W = $xv; Role = $role; Shift = [double]$fm[$h].Shift; SE = $fm[$h].SE }
            }
            # 12.7 : mesures des passes de mesure gardees par face (comparaison de deux calibrations, Get-FaceEstimates) ;
            # sans effet sur la courbe. 12.9 (correction 2) : passes de mesure en carre latin : faces remplies, decalage de
            # passe retire, par Set-CalibPassOffsets
            $xw = $null
            if ($cal.Stage -eq 'coarse') { $xw = [int]$cal.PassW[[int]$c] } elseif ($cal.Stage -eq 'bracket') { $xw = [int]$u.Bracket[[int]$c] } elseif ($cal.Stage -eq 'densify') { $xw = [int]$u.Dense[[int]$c] } elseif ($cal.Stage -eq 'reach') { $xw = [int]$u.Reach[[int]$c] }
            if ($null -ne $xw -and -not ($cal.Stage -eq 'coarse' -and $cal.Latin)) {
                foreach ($h in @($fm.Keys)) {
                    if (-not $u.Face.ContainsKey($h)) { $u.Face[$h] = @{} }
                    if (-not $u.Face[$h].ContainsKey([int]$c)) { $u.Face[$h][[int]$c] = @{} }
                    Add-CalibPoint $u.Face[$h][[int]$c] $xw @{ Shift = [double]$fm[$h].Shift; SE = $fm[$h].SE; Score = [double]::NaN }
                }
            }
            $shifts += $sh; if (-not [double]::IsNaN($jt)) { $scores += $jt }
        }
        if ($cal.Stage -eq 'verify' -and $null -ne $u.VerifyList -and @($u.Witness).Count -gt 0) {
            foreach ($c in @($u.Witness)) {
                $ci = [int]$c
                if ($u.Verify.ContainsKey($ci) -or -not $u.VerifyPrev.ContainsKey($ci)) { continue }
                $u.Verify[$ci] = $u.VerifyPrev[$ci].Meas; $u.VerifyP[$ci] = [int]$u.VerifyPrev[$ci].P
                [void]$u.VerifyPrev.Remove($ci); [void]$u.ReadLast.Remove($ci)
                $u.VerifyList = @(@($u.VerifyList) | Where-Object { [int]$_ -ne $ci })
            }
        }
        $badTxt = if ($bad.Count -gt 0) { ((T ", illisibles : {0}") -f "$($bad -join ',')") } else { '' }
        $oneTxt = ''
        foreach ($hm in @($one | ForEach-Object { $_[1] } | Sort-Object -Unique)) { $oneTxt += (T ", mesurés sans la face {0} : {1}") -f "$hm", (Format-CylList ([int[]]@($one | Where-Object { $_[1] -eq $hm } | ForEach-Object { $_[0] }))) }
        if ($shifts.Count -gt 0) {
            $st = $shifts | Measure-Object -Average -Minimum -Maximum
            $scTxt = if ($scores.Count -gt 0) { "$([math]::Round(($scores | Measure-Object -Average).Average, 0))" } else { '-' }
            Append-Log ((T "  {0} : décalage résiduel moyen {1} ns (de {2} à {3}), score jitter moyen {4}, {5} cylindre(s){6}") -f "$($u.Prefix)$($cal.ValueTxt)", (Format-LevelNum $st.Average), (Format-LevelNum $st.Minimum), (Format-LevelNum $st.Maximum), "$scTxt", "$($shifts.Count)", "$badTxt$oneTxt")
        } elseif (($cal.Stage -ne 'bracket' -or $u.Bracket.Count -gt 0) -and ($cal.Stage -ne 'densify' -or $u.Dense.Count -gt 0) -and ($cal.Stage -ne 'reach' -or $u.Reach.Count -gt 0) -and ($cal.Stage -ne 'verify' -or $null -eq $u.VerifyList -or @($u.VerifyList).Count -gt 0)) {
            Append-Log ((T "  {0} : aucun cylindre mesurable{1}") -f "$($u.Prefix)$($cal.ValueTxt)", "$badTxt$oneTxt")
        }
        # 12.8 (lot 1c, point 1, etendu a la calibration complete) : mesures par cylindre de la passe, une ligne par face,
        # ecrites avant toute decision ; calibration rapide : zeros des cylindres mesures deux fois ou plus
        $plab = switch ($cal.Stage) { 'coarse' { "$([int]$cal.Index + 1)" } 'level' { "$($cal.LPass)" } 'verify' { (T "vérification {0}") -f "$($cal.VerifyCount)" } default { "$($cal.ValueTxt)" } }
        Write-CalibPassLog $plog $plab
        # 12.9 : verification complete (VerifyList nul : une commande gw par unite, tous les cylindres estimes ecrits a la
        # suite) en double densite (VOff, bareme) : le decalage commun de cette ecriture (Get-VerifyOffset : mediane des
        # residus bruts) est retire de chaque residu avant le jugement et toute correction (Shift centre ; Raw brut : ligne
        # « Residu apres verification », Res de la courbe enregistree) ; la courbe n est pas deplacee. Ecrit apres les mesures
        # brutes de la passe (synthese, Write-CalibPassLog) : les donnees avant la conclusion ; une ligne de journal dans
        # chaque cas (retire, dans le bruit, au-dela de la borne, trop peu de cylindres exploitables). Verifications ciblees
        # (verification 2, nouvel essai) : rien ici, les temoins (Get-VerifyDrift) centrent deja leurs residus par rapport a ce
        # repere, desormais centre (D = decalage commun absolu de la passe ; Get-CalibDriftStep rend la difference)
        if ($cal.Stage -eq 'verify' -and $null -eq $u.VerifyList -and [bool]$cal.VOff -and $null -ne $u.Fit) {
            $vo = Get-VerifyOffset $u ([int]$script:CalVOffMinCyl) ([double]$script:CalVOffSigK) ([double]$script:CalVOffMaxNs) ([double]$cal.MaxCoarse)   # 12.10 : niveau maximal de la famille
            $u.VOff = @{ V = [int]$cal.VerifyCount; M = [double]$vo.M; E = [double]$vo.E; N = [int]$vo.N; Removed = [bool]$vo.Ok }
            if ($vo.Ok) {
                foreach ($k in @($u.Verify.Keys)) { $m = $u.Verify[$k]; $u.Verify[$k] = @{ Shift = [double]$m.Shift - [double]$vo.M; SE = $m.SE; Score = $m.Score; Raw = [double]$m.Shift } }
                Append-Log ($u.Prefix + ((T "Vérification {0} : décalage commun de l'écriture {1} ns de décalage (médiane des résidus de {2} cylindres, erreur-type {3}) : retiré des résidus avant le jugement et toute correction ; la courbe n'est pas déplacée.") -f "$($cal.VerifyCount)", ('{0:+0.0;-0.0;0.0}' -f [double]$vo.M), "$($vo.N)", (Format-LevelNum $vo.E)))
            }
            elseif ($vo.Why -eq 'borne') { Append-Log ($u.Prefix + ((T "Vérification {0} : décalage commun de l'écriture {1} ns de décalage (médiane des résidus de {2} cylindres), au-delà de {3} ns : non retiré, les résidus sont jugés tels quels (lecteur ou support instable depuis les passes de mesure ?) ; la vérification suivante contrôle la correction.") -f "$($cal.VerifyCount)", ('{0:+0.0;-0.0;0.0}' -f [double]$vo.M), "$($vo.N)", (Format-LevelNum ([double]$script:CalVOffMaxNs)))) }
            elseif ($vo.Why -eq 'nonsig') { Append-Log ($u.Prefix + ((T "Vérification {0} : décalage commun de l'écriture {1} ns de décalage (médiane des résidus de {2} cylindres, erreur-type {3}) : dans le bruit, non retiré.") -f "$($cal.VerifyCount)", ('{0:+0.0;-0.0;0.0}' -f [double]$vo.M), "$($vo.N)", (Format-LevelNum $vo.E))) }
            # 'cylindres' (moins de CalVOffMinCyl cylindres exploitables : image courte en test standard, ou test standard
            # dont un cylindre est un point isole, au plafond ou au plancher) : residus bruts, dit au journal
            elseif ($vo.Why -eq 'cylindres') { Append-Log ($u.Prefix + ((T "Vérification {0} : décalage commun de l'écriture non évalué ({1} cylindres exploitables, {2} au moins nécessaires) : les résidus sont jugés tels quels.") -f "$($cal.VerifyCount)", "$($vo.N)", "$([int]$script:CalVOffMinCyl)")) }
            # 'regional' (banc 129-voff2) : decalage des cylindres retenus different de celui du reste de la piste, ou d une moitie
            # a l autre : erreur regionale de la courbe, pas un decalage de l ecriture ; residus bruts, dit au journal
            elseif ($vo.Why -eq 'regional') { Append-Log ($u.Prefix + ((T "Vérification {0} : décalage de l'écriture {1} ns de décalage sur {2} cylindres, mais {3} ns d'écart avec le reste de la piste : il n'est pas commun à toute l'écriture, non retiré ; les résidus sont jugés tels quels.") -f "$($cal.VerifyCount)", ('{0:+0.0;-0.0;0.0}' -f [double]$vo.M), "$($vo.N)", (Format-LevelNum ([double]$vo.Dz)))) }
        }
        # 12.10 : erreur de modele aux forts besoins (Get-VerifySlope) : a la verification complete en double densite, pente du
        # residu juge avec la valeur ecrite sur les cylindres ecrits au-dela du niveau mesure ; etablie : les cylindres que la
        # droite ecarte de plus de CalSlopeMinNs sont retenus (SlopeBad, rejoint Get-ResidualFlags ci-dessous) et corriges a
        # leur zero mesure, puis controles par la verification suivante comme toute correction. Journal dans les deux cas
        # des qu il y a assez de cylindres au-dela du niveau mesure ; rien sur un lecteur a faible besoin
        $u.SlopeBad = $null
        if ($cal.Stage -eq 'verify' -and $null -eq $u.VerifyList -and [bool]$cal.Slope -and $null -ne $u.Fit) {
            $sp = Get-VerifySlope $u ([double]$cal.MaxCoarse) ([int]$script:CalSlopeMinCyl) ([double]$script:CalSlopeSigK) ([double]$script:CalSlopeMinNsNs) ([double]$script:CalSlopeMinNs)
            $u.VSlope = @{ V = [int]$cal.VerifyCount; B = [double]$sp.B; SB = [double]$sp.SB; A = [double]$sp.A; N = [int]$sp.N; Ok = [bool]$sp.Ok; Why = [string]$sp.Why }
            if ($sp.Ok -and $sp.Bad.Count -gt 0) {
                $u.SlopeBad = $sp.Bad
                $bc = @($sp.Bad.Keys | ForEach-Object { [int]$_ } | Sort-Object)
                Append-Log ($u.Prefix + ((T "Vérification {0} : erreur de modèle aux forts besoins : au-delà de {1} ns écrits, le résidu suit la valeur écrite, pente {2} ns/ns (incertitude {3}, {4} cylindres), de {5} ns à {6} ns d'une extrémité à l'autre ({7} à {8} ns écrits) : {9} cylindre(s) corrigé(s) à leur zéro mesuré, même dans la tolérance ({10}).") -f "$($cal.VerifyCount)", (Format-UiNum ([double]$sp.X0) '0'), (Format-UiNum ([double]$sp.B) '0.000'), (Format-UiNum ([double]$sp.SB) '0.000'), "$($sp.N)", (Format-UiNum ([double]$sp.FMin) '0.0'), (Format-UiNum ([double]$sp.FMax) '0.0'), (Format-UiNum ([double]$sp.PMin) '0'), (Format-UiNum ([double]$sp.PMax) '0'), "$($bc.Count)", (($bc | ForEach-Object { "c$_" }) -join ', ')))
            }
            # banc 1210-a (N1) : pente etablie mais aucun residu de la droite au-dela de CalSlopeMinNs : rien a corriger, dit tel quel
            elseif ($sp.Ok) { Append-Log ($u.Prefix + ((T "Vérification {0} : pente du résidu avec la valeur écrite au-delà de {1} ns : {2} ns/ns (incertitude {3}, {4} cylindres), établie mais sans résidu de la droite au-delà de {5} ns : aucune correction.") -f "$($cal.VerifyCount)", (Format-UiNum ([double]$sp.X0) '0'), (Format-UiNum ([double]$sp.B) '0.000'), (Format-UiNum ([double]$sp.SB) '0.000'), "$($sp.N)", (Format-UiNum ([double]$script:CalSlopeMinNs) '0'))) }
            elseif ($sp.Why -ne 'cylindres') { Append-Log ($u.Prefix + ((T "Vérification {0} : pas d'erreur de modèle aux forts besoins : pente du résidu avec la valeur écrite {1} ns/ns (incertitude {2}, {3} cylindres au-delà de {4} ns écrits), dans le bruit ou négligeable.") -f "$($cal.VerifyCount)", (Format-UiNum ([double]$sp.B) '0.000'), (Format-UiNum ([double]$sp.SB) '0.000'), "$($sp.N)", (Format-UiNum ([double]$sp.X0) '0'))) }
        }
        if ($cal.Stage -eq 'level') { Write-LevelPassLog $cal $u ([int]$cal.LPass) }
    }
    if ($cal.Stage -eq 'level') { Invoke-LevelStep $cal $tracks; return }
    if ($cal.Stage -eq 'coarse') {
        # 12.7 : controle de surface de la disquette de calibration sur la relecture de la passe 1 (motif ecrit aux niveaux
        # de la passe 1, 3 tours),
        # avec la vitesse du lecteur et la densite relue : bilan au journal a chaque calibration. Defaut grossier
        # (arbitrage 1) : fenetre sans compte a rebours (Show-CalibSurface) ; disquette douteuse sans defaut grossier :
        # reserve de la fenetre de decision (Complete-PrecompCalib), sans fenetre pendant la calibration
        if ([int]$cal.Index -eq 0 -and -not $cal.SurfDone) {
            $cal.SurfDone = $true
            $std = ([string]$cal.Mode -eq 'std')
            $rpm = if ($cal.Rpm) { [int]$cal.Rpm } else { 300 }
            $sf = Get-CalibSurface $tracks ([int[]]$cal.Cyls)
            $mc = Get-CalibMediumCheck $tracks ([int[]]$cal.Cyls) ([int]$cal.PatternBits) $rpm
            $gross = Test-CalibSurfaceGross $sf $mc
            $cal.Surf = $sf; $cal.Medium = $mc; $cal.SurfGross = $gross
            # Format-CalibSurfaceLog rend son tableau de lignes protege (operateur virgule) : pas de @() autour
            foreach ($l in (Format-CalibSurfaceLog $sf $std $(if ($gross) { 'none' } else { 'reserve' }) -Mixed ([bool]$cal.Latin))) { Append-Log $l }
            if ($mc.Log) { Append-Log $mc.Log }
            # Haute densite : decalage hors de la plage de mesure a la premiere passe (addendum HD de la 12.7)
            $hdFam = (@('hd', 'hd360') -contains [string]$cal.Family)
            if ($hdFam) {
                $lim = $script:CalHdShiftCells * 60000000000.0 / ([double]$rpm * [double]$cal.PatternBits)
                $oc = @()
                foreach ($c in $cal.Cyls) { foreach ($h in 0, 1) { $tn = [int]$c * 2 + $h; if ($tracks.ContainsKey($tn)) { $m = Get-CalibTrackMeasure $tracks[$tn]; if ($m -and [math]::Abs([double]$m.Shift) -gt $lim) { $oc += [int]$c } } } }
                if ($oc.Count) { Append-Log ((T "Haute densité : décalage de plus de {0} ns à la première passe (précompensation nulle) aux cylindres {1} : la mesure y sort de sa plage de validité (0,2 cellule) et sous-estime le besoin, qui dépasse probablement la borne de {2} ns.") -f (Format-UiNum $lim '0'), (Format-CylList ([int[]]@($oc | Sort-Object -Unique))), "$($script:CalHardNs)") }
            }
            if ($gross) {
                # 12.7 : defaut de vitesse seul : lecteur en cause, pas la disquette (Test-CalibSpeedOnly)
                $spd = Test-CalibSpeedOnly $sf $mc
                $notes = @()
                if ($mc.Rot) { $notes += (T "Vitesse du lecteur différente de celle du type de disquette : un format à 300 tr/min demande un lecteur à 300 tr/min (3,5 pouces, ou 5,25 pouces double densité), un format à 360 tr/min un lecteur à 360 tr/min (5,25 pouces haute densité, ou 3,5 pouces réglé à 360 tr/min). Changer de disquette n'y change rien.") }
                # 12.10 : calibration croisee : la disquette est dans la cible ; une autre disquette va dans la source
                if ($cal.Cross) { $notes += ((T "Calibration croisée : la disquette est dans le lecteur {0}, celui qui relit. Pour changer de disquette, insérez l'autre disquette sacrifiée dans le lecteur {1}, celui qui écrit.") -f "$($cal.Cross.Tgt)", "$($cal.Cross.Src)") }
                if ($hdFam -and -not $spd) { $notes += (T "En haute densité, ce résultat vient le plus souvent d'une disquette double densité (sans trou de densité), d'un lecteur sans mode haute densité, ou d'un lecteur resté en double densité (option « Densel » de l'onglet Écriture, pour un lecteur qui suit la broche 2). Utilisez une disquette haute densité sacrifiée dans un lecteur haute densité.") }
                if ($spd) { Append-Log ((T 'Contrôle de vitesse et de densité : {0} : décision demandée.') -f (Format-CalibSurfaceVerdict $sf $mc)) }
                elseif ($cal.DiskOnly) { Append-Log ((T 'Contrôle de surface : disquette à écrire défectueuse ({0}) : décision demandée.') -f (Format-CalibSurfaceVerdict $sf $mc)) }
                else { Append-Log ((T "Contrôle de surface : disquette de calibration douteuse ({0}) : décision demandée.") -f (Format-CalibSurfaceVerdict $sf $mc)) }
                $redo = [bool]($script:CalRedo -and $script:CalRedo.Stage -eq 'running')
                if ($cal.DiskOnly) {
                    # 12.8 (S3) : mesure complete de cette disquette : la disquette mesuree est celle a ecrire, ni disquette
                    # sacrifiee ni changement de disquette : fenetre « Disquette a ecrire defectueuse » de la calibration
                    # rapide (« Ecrire quand meme », « Arreter », fermeture = Arreter)
                    $opt = @{ Change = $false; SwapBox = $false; Variant = 'level'; Title = $(if ($spd) { (T 'Contrôle de surface') } else { (T 'Disquette à écrire défectueuse') }); GoText = (T 'Écrire quand même')
                              Speed = $spd; States = (Get-CalibSurfaceStates $sf $mc) }
                    $txt = Get-LevelSurfaceText $sf $mc ([bool]$script:Restore) $spd $notes -Disk
                }
                else {
                    $opt = Get-CalibSurfaceOptions ([bool]$script:Restore) $redo ($script:AfterCalib -eq 'write') ([bool]$cal.Swap)
                    if ($spd) { $opt.Speed = $true; $opt.Change = $false; $opt.SwapBox = $false }
                    $opt.States = Get-CalibSurfaceStates $sf $mc    # 12.8 (lot 5, D15) : icones d etat de frmCalibSurface
                    $txt = Get-CalibSurfaceText $sf $opt $std ([bool]$cal.AutoStart) -Extra @($mc.Lines) -Notes @($notes) -Medium $mc -Hd $hdFam -Mixed ([bool]$cal.Latin)
                }
                $cal.Hold = $true; Update-CalibProgress; if ($cal.Home) { Update-HomeCalibCard }
                if ($script:Restore) { $script:Restore.InCall = $true }
                try { $ch = Show-CalibSurface $opt $txt }
                finally { $cal.Hold = $false; if ($script:Restore) { $script:Restore.InCall = $false; $script:Restore.Idle = Get-Date } }
                if ($ch.Choice -eq 'change') { Restart-PrecompCalib $cal ([bool]$ch.Swap); return }
                if ($ch.Choice -eq 'stop') {
                    if ($redo) { $script:CalRedo.Why = $(if ($spd) { (T 'vitesse du lecteur différente de celle du type de disquette') } else { (T 'disquette B défectueuse au contrôle de surface') }) }
                    Append-Log (T "Contrôle de surface : calibration arrêtée à votre demande, rien de plus n'est écrit.")
                    Stop-PrecompCalib; return
                }
                $cal.SurfKept = $true
                Append-Log (T 'Contrôle de surface : calibration poursuivie sur cette disquette à votre demande.')
            }
        }
        $cal.Index++
        if ($cal.Index -lt $cal.Values.Count) { New-CalibPass; return }
        if ($cal.Latin) { Set-CalibPassOffsets $cal }        # 12.9 (correction 2)
        foreach ($u in $cal.Units) {
            if (-not (Set-CalibEstimates $u)) { $cal.TotalPasses = $cal.PassesDone; Complete-PrecompCalib; return }
        }
        # Encadrement : un cylindre encore sous-compense a la plus forte valeur mesuree a un zero extrapole, peu sur (la
        # pente varie hors de la plage mesuree) : une passe le mesure a son estimation + marge pour l encadrer, au plus au
        # plafond des passes de mesure (CalMaxNs) ; au-dela, zero extrapole de ces mesures, ecrit puis mesure par la verification.
        $cal.MaxCoarse = [int](@($cal.Values) | Measure-Object -Maximum).Maximum   # 12.10 : niveaux de la famille
        $need = $false
        foreach ($u in $cal.Units) {
            $u.Bracket = @{}
            foreach ($c in @($u.Est.Keys)) {
                $pts = $u.Results[[int]$c]
                $top = [int](@($pts.Keys | ForEach-Object { [int]$_ }) | Measure-Object -Maximum).Maximum
                if ($u.Kind[[int]$c] -ne 'interp' -and [double]$pts[$top].Shift -gt 0 -and $top -lt $script:CalMaxNs) {
                    $u.Bracket[[int]$c] = [int][math]::Min($script:CalMaxNs, [math]::Max($top + $script:CalBracketStep, [math]::Round([double]$u.Est[[int]$c] + $script:CalBracketMargin)))
                    $need = $true
                }
            }
        }
        if ($need) { $cal.Stage = 'bracket'; $cal.TotalPasses++; New-CalibPass; return }
        if (Start-DiskReach $cal) { return }       # 12.8 (S3-HIGH) : mesure complete de cette disquette seulement
        if (Start-CalibDensify $cal) { return }
        Start-CalibFit $cal; return
    }
    if ($cal.Stage -eq 'bracket') {
        foreach ($u in $cal.Units) { if ($u.Bracket.Count -gt 0) { [void](Set-CalibEstimates $u (T 'Après encadrement : ')) } }
        if (Start-DiskReach $cal) { return }       # 12.8 (S3-HIGH) : mesure complete de cette disquette seulement
        if (Start-CalibDensify $cal) { return }
        Start-CalibFit $cal; return
    }
    if ($cal.Stage -eq 'reach') {
        # 12.8 (S3-HIGH) : apres la mesure directe, zero recalcule par Get-CalibZero sur la corde des deux ecritures les plus
        # proches (plafond des passes de mesure et estimation ecrite), au lieu de l extrapolation au-dela de CalMaxNs
        foreach ($u in $cal.Units) { if ($u.Reach.Count -gt 0) { [void](Set-CalibEstimates $u (T 'Après mesure directe : ')); Write-DiskReachLog $u } }
        if (Start-CalibDensify $cal) { return }
        Start-CalibFit $cal; return
    }
    if ($cal.Stage -eq 'densify') {
        if ($cal.DensePass -eq 'A') { Set-CalibDenseB $cal; $cal.DensePass = 'B'; New-CalibPass; return }
        foreach ($u in $cal.Units) { [void](Set-CalibEstimates $u (T 'Après mesures complémentaires : ')) }
        Start-CalibFit $cal; return
    }
    # Verification : la mesure au profil applique devient un point de plus pour chaque cylindre verifie ; l estimation
    # est recalculee (en general encadree, donc interpolee avec la pente locale). Correction locale de la courbe aux
    # cylindres hors tolerance (estimation - valeur appliquee), interpolee entre cylindres verifies, lissage croissant.
    # Ecriture lente : chaque tete est corrigee d apres sa propre mesure ; une nouvelle passe reverifie les deux.
    $again = $false
    foreach ($u in $cal.Units) {
        # 12.8 (lot 1b) : apres la passe du nouvel essai, unites non concernees laissees telles quelles
        if ([int]$cal.Retests -gt 0 -and -not $u.InRetest) { continue }
        # Points de la passe : seulement les cylindres relus a cette passe (verification ciblee : VerifyList)
        $readNow = if ($null -ne $u.VerifyList) { @(@($u.VerifyList) | Where-Object { @($u.Witness) -notcontains [int]$_ }) } else { @($u.Verify.Keys | ForEach-Object { [int]$_ }) }
        foreach ($c in @($u.Verify.Keys)) { if ($readNow -contains [int]$c) { Add-CalibPoint $u.Results[[int]$c] ([int]$u.VerifyP[[int]$c]) $u.Verify[$c] } }
        [void](Set-CalibEstimates $u ((T "Vérification {0} : ") -f "$($cal.VerifyCount)"))
        # 12.9 (correction 4) : confirmation des dents par cette verification (hors passe du nouvel essai). Cylindres relus a
        # cette passe, temoins de derive compris (relus a leur valeur inchangee : leur zero vaut pour la baisse entre deux
        # cylindres, le decalage commun de la passe s annulant dans la difference) ; $readNow, lui, exclut les temoins (points
        # de Results). VerifyList est encore celle de la passe (remise a vide a la ligne suivante)
        $dentRedo = $false
        if ([int]$cal.Retests -eq 0 -and @(Get-FitDents $u.Fit).Count -gt 0) {
            $readAll = if ($null -ne $u.VerifyList) { [int[]]@(@($u.VerifyList) | ForEach-Object { [int]$_ }) } else { [int[]]@($u.Verify.Keys | ForEach-Object { [int]$_ }) }
            $dentRedo = Update-CalibDents $u ([int]$cal.VerifyCount) ([int]$cal.VerifyCount -ge $script:CalMaxVerify) $readAll
        }
        $u.VerifyList = @()
        $corr = 0; $delta = @{}
        $fl = Get-ResidualFlags $u           # residus retenus : ecart regional, marche au bord, residu tres grand ou cylindre epars (pas un ecart local)
        # 12.10 : cylindres de la tendance des forts besoins (Get-VerifySlope, SlopeBad) retenus meme dans la tolerance, et
        # retires des ecarts locaux isoles ; consomme ici (une verification)
        if ($u.SlopeBad -and $u.SlopeBad.Count -gt 0) {
            foreach ($c in @($u.SlopeBad.Keys)) { if ($u.Est.ContainsKey([int]$c)) { $fl.Bad[[int]$c] = $true } }
            $fl.Spot = @($fl.Spot | Where-Object { -not $u.SlopeBad.ContainsKey([int]$_) })
            $u.SlopeBad = $null
        }
        foreach ($c in @($u.Verify.Keys)) {
            if (@($u.Outliers) -contains [int]$c) { continue }              # point isole : la courbe ne le suit pas
            $d = 0.0
            if ($fl.Bad.ContainsKey([int]$c) -and $u.Est.ContainsKey([int]$c)) {
                $d = [double]$u.Est[[int]$c] - (Get-SpecValue $u.Profile ([int]$c))
                if ([math]::Abs($d) -ge 0.5) { $corr++ } else { $d = 0.0 }
            }
            $delta[[int]$c] = $d
        }
        # 12.8 (lot 1b) : aucune correction apres la passe du nouvel essai : jugement final
        if (($corr -eq 0 -and -not $dentRedo) -or $cal.VerifyCount -ge $script:CalMaxVerify -or [int]$cal.Retests -gt 0) { continue }
        # Courbe monotone par segments : pres d un changement de sens, les mesures des premieres passes (cylindres ecrits
        # seuls, loin du zero) et celles de la verification (profil complet ecrit dans l ordre, comme l image) peuvent
        # differer bien au-dela de leur incertitude. Une correction par l estimation combinee, dans des segments figes,
        # fondrait alors le sommet et ses voisins en palier (PAVA). La courbe est reajustee sur les zeros locaux de la
        # verification : precomp appliquee - residu / pente, mesures prises au plus pres du zero et dans les conditions
        # de l ecriture ; les changements de sens peuvent se deplacer.
        # 12.9 (correction 4) : aussi avec une dent dans la courbe, ou une dent retiree par cette verification (Update-CalibDents)
        if (@($u.Fit.Breaks).Count -gt 0 -or @(Get-FitDents $u.Fit).Count -gt 0 -or $dentRedo) {
            $sl = if ($null -ne $u.Slope -and [double]$u.Slope -lt -0.2) { [double]$u.Slope } else { -2.0 }
            $zv = @{}; $zs = @{}
            foreach ($c in @($u.Verify.Keys)) {
                $ci = [int]$c
                if (@($u.Outliers) -contains $ci -or -not $u.VerifyP.ContainsKey($ci)) { continue }
                $zv[$ci] = [math]::Max(0.0, [math]::Min([double]$script:CalHardNs, [double]$u.VerifyP[$ci] - [double]$u.Verify[$c].Shift / $sl))
                $se = $u.Verify[$c].SE
                $zs[$ci] = if ($null -ne $se -and -not [double]::IsNaN([double]$se)) { [math]::Max(1.0, [double]$se / [math]::Abs($sl)) } else { 2.0 }
            }
            $re = $null
            $dk = @(Get-FitDents $u.Fit -Admitted)
            if ($zv.Count -ge 4) { $re = Fit-PrecompCurve $zv $zs $cal.MaxCyl $null ($cal.Mode -eq 'fine' -or [bool]$cal.Densified) -Dents $dk }
            # 12.9 : dent que le reajustement ne coupe plus (hors d un segment croissant de la courbe reajustee, ou cylindres
            # non voisins dans les zeros de la verification) : journal
            if ($re) { foreach ($d in $dk) { if (@($re.Dents) -notcontains $d) { Append-Log ($u.Prefix + ((T "Dent entre c{0} et c{1} non reprise par le réajustement de la courbe sur la vérification (dent hors d'un segment croissant de la courbe réajustée, ou cylindres non voisins) : la courbe ne la suit plus.") -f "$($d.C1)", "$($d.C2)")) } } }
            if ($re -and (@($re.Breaks).Count -gt 0 -or @(Get-FitDents $re).Count -gt 0)) {
                # Forme reajustee, puis ancrage dans les nouveaux segments : un cylindre dans la tolerance garde sa valeur
                # appliquee (pas de reecriture inutile), un cylindre hors tolerance va a son zero mesure
                $dz = @{}
                foreach ($ci in @($zv.Keys)) {
                    $inTol = -not $fl.Bad.ContainsKey($ci)
                    $target = if ($inTol) { [double]$u.VerifyP[$ci] } else { [double]$zv[$ci] }
                    $dz[$ci] = $target - [double]$re.Values[$ci]
                }
                $re.Values = Add-CurveCorrection $re.Values $dz $re.Segs
                $newProfile = Build-CurveProfile $re.Values
                if ($newProfile -eq $u.Profile) { continue }
                $oldB = (@($u.Fit.Breaks) | ForEach-Object { "c$_" }) -join '/'
                $newB = (@($re.Breaks) | ForEach-Object { "c$_" }) -join '/'
                $u.Fit = @{ Model = 'seg+c'; A = $null; B = $null; Chi = $re.Chi; Values = $re.Values; Breaks = $re.Breaks; Segs = $re.Segs; Outliers = $u.Fit.Outliers; Dents = @(Get-FitDents $re) }
                $u.Profile = $newProfile
                $bTxt = if ($oldB -ne $newB) { (T "changement de sens déplacé de {0} à {1}") -f "$oldB", "$newB" } else { (T "changements de sens {0}") -f "$newB" }
                Append-Log ($u.Prefix + ((T "Vérification : {0} cylindre(s) hors tolérance, courbe réajustée sur les zéros mesurés par la vérification ({1}) : {2}") -f "$corr", "$bTxt", "$($u.Profile)"))
                $u.VerifyList = @($u.Est.Keys | ForEach-Object { [int]$_ } | Where-Object { $_ -lt @($re.Values).Count -and (-not $u.VerifyP.ContainsKey($_) -or [int]$re.Values[$_] -ne [int]$u.VerifyP[$_]) } | Sort-Object)
                Add-DriftWitnesses $u
                if ($u.VerifyList.Count -gt 0) { $again = $true }
                continue
            }
        }
        $newVals = Add-CurveCorrection $u.Fit.Values $delta $u.Fit.Segs
        $newProfile = Build-CurveProfile $newVals
        if ($newProfile -eq $u.Profile) { continue }
        $base = ([string]$u.Fit.Model) -replace '\+c$', ''
        $u.Fit = @{ Model = "$base+c"; A = $u.Fit.A; B = $u.Fit.B; Chi = $u.Fit.Chi; Values = $newVals; Breaks = $u.Fit.Breaks; Segs = $u.Fit.Segs; Outliers = $u.Fit.Outliers; Dents = @(Get-FitDents $u.Fit) }
        $u.Profile = $newProfile
        # 12.9 (revue du 31/10/2026, m2) : dent retiree par cette verification sans cylindre a corriger, courbe sans
        # changement de sens (reajustement sur les zeros de la verification ecarte ci-dessus, faute de Breaks et de dent) :
        # la courbe est seulement lissee, sans la dent, dans ses segments fusionnes (Merge-CurveDentSegs)
        if ($corr -eq 0 -and $dentRedo) { Append-Log ($u.Prefix + ((T "Courbe lissée sans la dent retirée, nouveau profil : {0}") -f "$($u.Profile)")) }
        else { Append-Log ($u.Prefix + ((T "{0} cylindre(s) corrigé(s), résidu hors tolérance, nouveau profil : {1}") -f "$corr", "$($u.Profile)")) }
        # Verification suivante ciblee : cylindres estimes dont la valeur appliquee change (au moins 1 ns)
        $u.VerifyList = @($u.Est.Keys | ForEach-Object { [int]$_ } | Where-Object { $_ -lt $newVals.Count -and (-not $u.VerifyP.ContainsKey($_) -or [int]$newVals[$_] -ne [int]$u.VerifyP[$_]) } | Sort-Object)
        Add-DriftWitnesses $u
        if ($u.VerifyList.Count -gt 0) { $again = $true }
    }
    if ($again) {
        $cal.VerifyCount++
        New-CalibPass; return
    }
    # 12.8 (VAL01) : apres la passe du nouvel essai : correction sans effet, valeur d avant retablie (Restore-CalibRetestNoEffect)
    if ([int]$cal.Retests -gt 0) { Restore-CalibRetestNoEffect $cal }
    # 12.8 (lot 1b) : cylindres encore non converges sans cause exclue : une passe de nouvel essai au plus, puis jugement
    # final (Start-CalibRetest). Sans cylindre non converge, rien ne change
    if (Start-CalibRetest $cal) { return }
    # Derniere verification : zones aux verifications contradictoires ramenees a la mediane (sans nouvelle passe)
    foreach ($u in $cal.Units) { [void](Set-VerifyContra $u) }
    $cal.TotalPasses = $cal.PassesDone
    Complete-PrecompCalib
}

function Get-CalibRetestCause([bool]$surf, [bool]$dftUse, [double]$driftStep, [bool]$hasPrev) {
    # 12.9 (L2-c) : cause qui exclut toute une unite du nouvel essai automatique (Get-CalibRetestPlan) : disquette douteuse
    # au controle de surface, ou forte derive du lecteur (au-dela de 2 tolerances) sur le dernier intervalle. Derive non
    # retiree faute de temoins : plus d exclusion (journaux du 27/10/2026) ; la passe du nouvel essai a ses propres temoins
    # (Add-DriftWitnesses) et son jugement retire la derive qu ils mesurent (NoDrift : ligne de journal). Fonction pure.
    # Renvoie @{ Why ('' : pas d exclusion) ; NoDrift }
    if ($surf) { return @{ Why = (T 'disquette de calibration douteuse au contrôle de surface'); NoDrift = $false } }
    if ($dftUse -and [math]::Abs($driftStep) -gt 2.0 * [double]$script:CalResidual) {
        return @{ Why = ((T 'forte dérive du lecteur entre deux vérifications ({0} ns)') -f ('{0:+0.0;-0.0;0.0}' -f $driftStep)); NoDrift = $false }
    }
    return @{ Why = ''; NoDrift = ((-not $dftUse) -and $hasPrev) }
}

function Get-CalibRetestPlan($cal) {
    # 12.8 (lot 1b, decisions128.md) : plan du nouvel essai automatique apres la derniere verification, sans rien modifier.
    # Par unite, cylindres non converges (Get-CalibWarnings : NonConvC, residu juge NonConvR) dont la cause n est pas
    # exclue. Causes exclues pour toute l unite : disquette douteuse au controle de surface de la premiere passe (reserve
    # « support » ; defaut de vitesse seul : non), derive du lecteur forte (au-dela de 2 tolerances, reserve « derive »).
    # 12.9 (L2-b, L2-c) : derive non retiree : plus exclue (Get-CalibRetestCause) ; zone non reproductible (Contra) et
    # cylindres non reproductibles : seuls les cylindres a 2 cylindres au plus d eux (Split-CalibRetestZone).
    # Pour un cylindre : valeur visee au plafond (CalHardNs) ou au plancher (0), ou piste deja ecrite le
    # nombre de fois annonce par l avertissement (WriteMax, maximum de la 12.7 : le nouvel essai ne le releve pas).
    # 12.9 (banc cal2, option A) : en double densite au calcul 12.9, WriteMax compte le nouvel essai a part
    # (Start-PrecompCalib) : un cylindre encadre n est plus refuse ; haute densite : maximum de la 12.7, inchange.
    # Valeur visee : zero de la mesure jugee, valeur ecrite - residu juge / pente de l unite (residu juge : derive retiree,
    # temoin sur sa mesure precedente, comme Get-CalibWarnings), bornee par les cylindres verifies non vises voisins dans le
    # sens du segment ; cylindre « non relu » : relu a sa valeur. Courbe corrigee comme a la verification
    # (Add-CurveCorrection : 0 aux autres cylindres verifies, monotonie par segments). Relus :
    # cylindres vises, leurs voisins immediats parmi les cylindres mesures (hors points isoles) et les cylindres dont la
    # valeur change ; temoins de derive ajoutes par Start-CalibRetest (Add-DriftWitnesses).
    # Renvoie @{ Go ; Skip } : plans @{ U ; NonConv ; Targets ; Why ; Values ; Profile ; List ; Corr ; NcR } (Skip : NonConv,
    # Why). NcR (12.8, VAL01) : residus juges et valeurs ecrites avant le nouvel essai (NonConvR), pour la correction sans
    # effet (Restore-CalibRetestNoEffect). 12.9 (banc cal2, G4-02 ; revue fix2) : cylindres de Skip, quel que soit le
    # motif, ni vises ni corriges, gardes par Start-CalibRetest (RtFull) s ils ne sont pas relus ; Full (piste deja
    # ecrite WriteMax fois, jamais relue) et Lim (valeur visee hors des limites) nomment deux de ces motifs.
    $go = @(); $skip = @()
    $surf = [bool](($cal.SurfKept -and $cal.Surf -and -not (Test-CalibSpeedOnly $cal.Surf $cal.Medium)) -or ($cal.Surf -and $cal.Surf.Defective -and -not $cal.SurfGross))
    $wmax = [int]$cal.WriteMax
    foreach ($u in @($cal.Units)) {
        if (-not $u.Fit -or -not $u.Profile) { continue }
        $w = Get-CalibWarnings $u ([int]$cal.MaxCyl)
        $nc = [int[]]@(@($w.NonConvC) | Where-Object { $null -ne $_ })
        if ($nc.Count -eq 0) { continue }
        $p = @{ U = $u; NonConv = $nc; Targets = @(); Why = ''; Values = $null; Profile = ''; List = @(); Corr = 0; NcR = $w.NonConvR; NoDrift = $false; Bound = @{}; Raw = @{}; Same = [int[]]@() }
        $dft = $w.Drift
        # 12.8 (S3-HIGH) : derive du dernier intervalle (Get-CalibDriftStep : apres un nouvel essai, la derive mesuree est
        # cumulee depuis le repere du jugement ; avant le premier, DriftBase est vide : derive mesuree telle quelle).
        # 12.9 (L2-c) : Get-CalibRetestCause (derive non retiree : nouvel essai juge sur ses propres temoins)
        $dStep = if ($dft.Use) { [double](Get-CalibDriftStep $u $dft) } else { 0.0 }
        $cz = Get-CalibRetestCause $surf ([bool]$dft.Use) $dStep ([bool]($u.VerifyPrev -and $u.VerifyPrev.Count -gt 0))
        $p.Why = $cz.Why; $p.NoDrift = $cz.NoDrift
        if ($p.Why) { $skip += $p; continue }
        # 12.9 (L2-b) : zone non reproductible (Contra), puis cylindres non reproductibles : seuls les cylindres non converges
        # a 2 cylindres au plus de l un d eux sont exclus (Split-CalibRetestZone), avec un message qui leur est propre
        $zc = [int[]]@(@($w.Contra) | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_ })
        if ($zc.Count -gt 0) {
            $sp = Split-CalibRetestZone $nc $zc 2
            if ($sp.Excl.Count -gt 0) { $skip += @{ U = $u; NonConv = [int[]]$sp.Excl; Why = ((T "à 2 cylindres au plus de la zone non reproductible d'une vérification à l'autre (c{0})") -f (Format-CylList $sp.Near)) } }
            $nc = [int[]]$sp.Keep
        }
        $nr = if ($dft.NonRepro) { [int[]]@(@($dft.NonRepro.Keys) | ForEach-Object { [int]$_ }) } else { [int[]]@() }
        if ($nr.Count -gt 0 -and $nc.Count -gt 0) {
            $sp = Split-CalibRetestZone $nc $nr 2
            if ($sp.Excl.Count -gt 0) { $skip += @{ U = $u; NonConv = [int[]]$sp.Excl; Why = ((T "à 2 cylindres au plus de cylindres non reproductibles d'une vérification à l'autre (c{0})") -f (Format-CylList $sp.Near)) } }
            $nc = [int[]]$sp.Keep
        }
        if ($nc.Count -eq 0) { continue }
        $p.NonConv = $nc
        $sl = if ($null -ne $u.Slope -and [double]$u.Slope -lt -0.2) { [double]$u.Slope } else { -2.0 }
        $vals = @($u.Fit.Values)
        $delta = @{}
        foreach ($k in @($u.Verify.Keys)) { $c = [int]$k; if (@($u.Outliers) -notcontains $c -and $c -lt $vals.Count) { $delta[$c] = 0.0 } }
        $lim = @(); $full = @(); $kept = @()
        foreach ($c in $nc) {
            if ($c -ge $vals.Count) { continue }
            if ($wmax -gt 0 -and $null -ne $u.Writes -and 1 + [int]$u.Writes[$c] -gt $wmax) { $full += $c; continue }
            # 12.8 (S3-HIGH) : mesure complete de cette disquette : cylindre d une correction sans effet a un nouvel essai
            # precedent (RtKept) : aucun progres, plus de nouvel essai
            if ($cal.DiskOnly -and @($u.RtKept) -contains $c) { $kept += $c; continue }
            if ($w.NonConvR -and $w.NonConvR.ContainsKey($c)) {
                $r = [double]$w.NonConvR[$c].R
                $z = [math]::Round([double]$w.NonConvR[$c].P - $r / $sl, 0)
                if (($r -gt 0 -and $z -ge [double]$script:CalHardNs) -or ($r -lt 0 -and $z -le 0)) {
                    # 12.8 (S3-HIGH) : mesure complete de cette disquette : valeur visee ramenee a la borne de cette disquette
                    # (ou a 0) si la valeur ecrite n y est pas encore ; au-dela, reserve « plafond atteint » (Get-CalibWarnings)
                    $pw = [double]$w.NonConvR[$c].P
                    if ($cal.DiskOnly -and $r -gt 0 -and $pw -lt [double]$script:CalHardNs) { $z = [double]$script:CalHardNs }
                    elseif ($cal.DiskOnly -and $r -lt 0 -and $pw -gt 0) { $z = 0.0 }
                    else { $lim += $c; continue }
                }
                $delta[$c] = $z - [double]$vals[$c]
            } else { $delta[$c] = 0.0 }               # non relu : relu a sa valeur
            $p.Targets += $c
        }
        $wTxt = (T 'pistes déjà écrites le nombre maximal de fois annoncé ({0})') -f "$wmax"
        $lTxt = (T 'précompensation visée hors de ses limites (0 ou {0} ns)') -f "$($script:CalHardNs)"
        if ($lim.Count) { $skip += @{ U = $u; NonConv = [int[]]$lim; Why = $lTxt; Lim = $true } }
        if ($full.Count) { $skip += @{ U = $u; NonConv = [int[]]$full; Why = $wTxt; Full = $true } }
        if ($kept.Count) { $skip += @{ U = $u; NonConv = [int[]]$kept; Why = (T "correction sans effet au nouvel essai précédent : aucun progrès") } }
        if ($p.Targets.Count -eq 0) { continue }
        # Valeur visee bornee par les cylindres verifies non vises les plus proches dans son segment, dans le sens du segment
        # (points fixes, meme regle que Set-VerifyContra) : le lissage croissant ne deplace aucun cylindre deja juge, et un
        # besoin que la courbe monotone ne peut pas suivre reste non converge sans degrader ses voisins (derniere passe :
        # aucun cylindre deplace ne pourrait etre corrige ensuite)
        $segs = if ($u.Fit.Segs) { @($u.Fit.Segs) } else { @(@{ Lo = 0; Hi = $vals.Count - 1; Dir = 1 }) }
        $fix = @($delta.Keys | ForEach-Object { [int]$_ } | Where-Object { @($p.Targets) -notcontains $_ } | Sort-Object)
        foreach ($c in @($p.Targets)) {
            $sg = $null; foreach ($g in $segs) { if ($c -ge [int]$g.Lo -and $c -le [int]$g.Hi) { $sg = $g; break } }
            if (-not $sg) { continue }
            $t = [double]$vals[$c] + [double]$delta[$c]
            $p.Raw[[int]$c] = $t                                         # 12.9 : valeur visee avant les bornes (journal)
            $fl = @($fix | Where-Object { $_ -ge [int]$sg.Lo -and $_ -lt $c }); $fr = @($fix | Where-Object { $_ -gt $c -and $_ -le [int]$sg.Hi })
            $a = if ($fl.Count) { [double]$vals[$fl[-1]] } else { $null }; $b = if ($fr.Count) { [double]$vals[$fr[0]] } else { $null }
            $ca = if ($fl.Count) { [int]$fl[-1] } else { $null }; $cb = if ($fr.Count) { [int]$fr[0] } else { $null }
            if ([int]$sg.Dir -lt 0) { $x = $a; $a = $b; $b = $x; $x = $ca; $ca = $cb; $cb = $x }
            $by = $null
            if ($null -ne $a -and $t -lt $a) { $t = $a; $by = $ca }
            if ($null -ne $b -and $t -gt $b) { $t = $b; $by = $cb }
            $delta[$c] = $t - [double]$vals[$c]
            if ($null -ne $by) { $p.Bound[[int]$c] = [int]$by }            # 12.9 : voisin verifie qui borne la valeur visee
        }
        $newVals = Add-CurveCorrection $u.Fit.Values $delta $u.Fit.Segs
        $p.Values = $newVals; $p.Profile = Build-CurveProfile $newVals
        $p.Corr = @($p.Targets | Where-Object { [int]$newVals[$_] -ne [int]$vals[$_] }).Count
        # 12.8 (S3-HIGH) : mesure complete de cette disquette, a partir du deuxieme nouvel essai : cylindre vise dont la
        # valeur ne change pas (bornee par ses voisins verifies dans le sens du segment) : aucun progres possible, plus de
        # nouvel essai (le premier nouvel essai le relit a sa valeur, comme la calibration de reference)
        if ($cal.DiskOnly -and [int]$cal.Retests -ge 1) {
            $same = [int[]]@($p.Targets | Where-Object { [int]$newVals[$_] -eq [int]$vals[$_] })
            if ($same.Count -gt 0) {
                $skip += @{ U = $u; NonConv = $same; Why = (T "valeur visée inchangée, bornée par les cylindres vérifiés voisins : aucun progrès") }
                $p.Targets = @($p.Targets | Where-Object { $same -notcontains [int]$_ })
                if ($p.Targets.Count -eq 0) { continue }
            }
        }
        $p.Same = [int[]]@($p.Targets | Where-Object { $w.NonConvR -and $w.NonConvR.ContainsKey([int]$_) -and [int]$newVals[$_] -eq [int]$vals[$_] })      # 12.9 : journal ; cibles non relues (ecart nul par construction, ligne « non relu : relu a sa valeur ») exclues
        $cs = [int[]]@($u.Est.Keys | ForEach-Object { [int]$_ } | Where-Object { @($u.Outliers) -notcontains $_ } | Sort-Object)
        $set = @{}
        foreach ($c in $p.Targets) {
            $set[[int]$c] = $true
            $i = [array]::IndexOf($cs, [int]$c)
            if ($i -gt 0) { $set[$cs[$i - 1]] = $true }
            if ($i -ge 0 -and $i + 1 -lt $cs.Count) { $set[$cs[$i + 1]] = $true }
        }
        $chg = @($u.Est.Keys | ForEach-Object { [int]$_ } | Where-Object { $_ -lt $newVals.Count -and (-not $u.VerifyP.ContainsKey($_) -or [int]$newVals[$_] -ne [int]$u.VerifyP[$_]) })
        foreach ($c in $chg) { $set[[int]$c] = $true }
        # Garde : un cylindre dont la valeur change doit etre relu ; voisin deja ecrit WriteMax fois : non relu
        $over = @($set.Keys | ForEach-Object { [int]$_ } | Where-Object { $wmax -gt 0 -and $null -ne $u.Writes -and 1 + [int]$u.Writes[$_] -gt $wmax })
        if (@($over | Where-Object { $chg -contains $_ }).Count -gt 0) { $skip += @{ U = $u; NonConv = [int[]]$p.Targets; Why = $wTxt }; continue }
        $p.List = [int[]]@($set.Keys | ForEach-Object { [int]$_ } | Where-Object { $over -notcontains $_ } | Sort-Object)
        $go += $p
    }
    return @{ Go = $go; Skip = $skip }
}

function Start-CalibRetest($cal) {
    # 12.8 (lot 1b) : nouvel essai automatique des cylindres non converges (Get-CalibRetestPlan), CalMaxRetest fois au plus :
    # passe de verification ciblee avec la correction tiree de la verification precedente, puis jugement final
    # (Invoke-CalibAnalysis, sans autre correction). Mesures des unites concernees ramenees au repere de leur jugement :
    # temoin juge sur sa mesure precedente, cylindre relu a la derniere verification derive retiree (residu brut garde dans
    # Raw : journal et courbe enregistree) ; la derive mesuree a la passe se compte depuis ce repere. Unites sans nouvel
    # essai : ni ecrites, ni relues, ni jugees a nouveau (InRetest). Le controle de surface reste celui de la premiere passe
    # (a6verify, synthese par. 44). Renvoie $true si la passe est lancee.
    # 12.8 (S3-HIGH) : mesure complete de cette disquette : CalDiskMaxRetest nouveaux essais au plus, jusqu a la convergence ;
    # arret des que tous les cylindres sont dans la tolerance (plan vide), ou sans progres (cylindres d une correction sans
    # effet, RtKept : exclus du plan). Calibration complete de reference : CalMaxRetest, inchange
    if (-not $cal) { return $false }
    $maxRt = if ($cal.DiskOnly) { [int]$script:CalDiskMaxRetest } else { [int]$script:CalMaxRetest }
    if ([int]$cal.Retests -ge $maxRt) {
        if ($cal.DiskOnly -and [int]$cal.Retests -gt 0) {
            $left = @(foreach ($u in @($cal.Units)) { if (-not $u.Fit -or -not $u.Profile) { continue }; $nc = [int[]]@(@((Get-CalibWarnings $u ([int]$cal.MaxCyl)).NonConvC) | Where-Object { $null -ne $_ }); if ($nc.Count) { "$($u.Prefix)$(Format-CylList $nc)" } })
            if ($left.Count -gt 0) { Append-Log ((T "Mesure complète : nombre maximal de nouveaux essais atteint ({0}) ; cylindres encore non convergés : {1}.") -f "$maxRt", ($left -join ' ; ')) }
        }
        return $false
    }
    $plan = Get-CalibRetestPlan $cal
    foreach ($p in @($plan.Skip)) { Append-Log ($p.U.Prefix + ((T "Calibration : pas de nouvel essai automatique des cylindres non convergés {0} : {1}.") -f (Format-CylList ([int[]]@($p.NonConv))), "$($p.Why)")) }
    # 12.9 (banc cal2, RT8, G4-02 ; revue fix2) : cylindres non converges exclus du nouvel essai, quel que soit le motif
    # (piste deja ecrite WriteMax fois, Full : ni reecrits ni relus ; valeur visee hors des limites, Lim ; proximite d une
    # zone ou de cylindres non reproductibles ; mesure complete : valeur visee inchangee, correction sans effet), et absents
    # des cylindres relus du plan de leur unite (cibles, voisins immediats, cylindres modifies ; un temoin de derive est
    # juge sur sa mesure precedente). Ils gardent le residu de la derniere verification : NON CONVERGES tant qu ils sont
    # hors tolerance (RtFull, Get-CalibWarnings, comme RtKept, FIXVAL01), meme si le voisinage corrige par la passe en
    # ferait un ecart local non retenu. Unite sans nouvel essai : ni relue ni jugee a nouveau, sans effet (ses cylindres
    # exclus sont deja non converges). Champ de l unite, recree avec elle comme RtKept (New-CalibUnit : nouvelle
    # calibration, calibration B, mesure complete, changement de disquette) ; jamais enregistre
    foreach ($p in @($plan.Skip)) {
        $rtRead = @(foreach ($gp in @($plan.Go)) { if ([object]::ReferenceEquals($gp.U, $p.U)) { @($gp.List) } })
        $rtNew = [int[]]@(@($p.NonConv) | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_ } | Where-Object { $p.Full -or $rtRead -notcontains $_ })
        if ($rtNew.Count -gt 0) { $p.U.RtFull = [int[]]@(@(@($p.U.RtFull) + @($rtNew)) | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_ } | Sort-Object -Unique) }
    }
    if (@($plan.Go).Count -eq 0) { return $false }
    $cal.Retests = 1 + [int]$cal.Retests
    $vLast = [int]$cal.VerifyCount             # derniere verification avant le nouvel essai
    $cal.VerifyCount++
    $cal.TotalPasses = $cal.PassesDone + 1
    $lt = (@($plan.Go | ForEach-Object { "$($_.U.Prefix)$(Format-CylList ([int[]]@($_.Targets)))" })) -join ' ; '
    if ($cal.DiskOnly) {
        # 12.8 (S3-HIGH) : une ligne par passe de nouvel essai, numerotee, avec les cylindres vises et leurs valeurs (avant -> apres)
        $lv = (@($plan.Go | ForEach-Object { $pp = $_; $ov = @($pp.U.Fit.Values); "$($pp.U.Prefix)" + ((@($pp.Targets | ForEach-Object { "c$_ $([int]$ov[[int]$_]) -> $([int]$pp.Values[[int]$_])" })) -join ', ') })) -join ' ; '
        Append-Log ((T "Mesure complète : nouvel essai automatique {0}/{1} des cylindres non convergés (vérification {2}), valeurs écrites (ns, avant -> après) : {3}") -f "$($cal.Retests)", "$maxRt", "$($cal.VerifyCount)", "$lv")
    }
    else { Append-Log ((T "Calibration : nouvel essai automatique des cylindres non convergés {0} (vérification {1})") -f "$lt", "$($cal.VerifyCount)") }
    # 12.9 : cylindres vises relus a leur valeur inchangee : bornes par leurs voisins verifies (dans le sens du segment), ou
    # ramenes par le lissage monotone ou l arrondi ; journal seulement
    foreach ($p in @($plan.Go)) {
        $ov = @($p.U.Fit.Values)
        $sm = [int[]]@(@($p.Same) | Where-Object { $null -ne $_ })
        foreach ($bd in $true, $false) {
            $l = [int[]]@($sm | Where-Object { $p.Bound.ContainsKey([int]$_) -eq $bd })
            if ($l.Count -eq 0) { continue }
            $vv = @($l | ForEach-Object { [int]$ov[$_] } | Sort-Object -Unique)
            $rv = @($l | ForEach-Object { [int][math]::Round([double]$p.Raw[[int]$_]) } | Sort-Object -Unique)
            $vTxt = if ($vv.Count -eq 1) { "$($vv[0])" } else { (T '{0} à {1}') -f "$($vv[0])", "$($vv[-1])" }
            $rTxt = if ($rv.Count -eq 1) { "$($rv[0])" } else { (T '{0} à {1}') -f "$($rv[0])", "$($rv[-1])" }
            if ($bd) {
                $byTxt = (@($l | ForEach-Object { [int]$p.Bound[[int]$_] } | Sort-Object -Unique | ForEach-Object { "c$_" })) -join ', '
                Append-Log ($p.U.Prefix + ((T "Calibration : nouvel essai des cylindres {0} à leur valeur inchangée ({1} ns) : valeur visée {2} ns, ramenée à la valeur écrite par les cylindres vérifiés voisins {3}, pour que la courbe reste monotone dans ce segment ; ils sont relus pour confirmer leur résidu, sans correction possible à ce nouvel essai.") -f (Format-CylList $l), $vTxt, $rTxt, $byTxt))
            }
            else { Append-Log ($p.U.Prefix + ((T "Calibration : nouvel essai des cylindres {0} à leur valeur inchangée ({1} ns) : valeur visée {2} ns, ramenée à la valeur écrite par le lissage monotone de la courbe ou par l'arrondi ; ils sont relus pour confirmer leur résidu.") -f (Format-CylList $l), $vTxt, $rTxt)) }
        }
    }
    # 12.9 (L2-c) : derive non retiree a la derniere verification : ligne ecrite apres le choix des temoins du nouvel essai (ci-dessous)
    foreach ($u in @($cal.Units)) { $u.InRetest = $false; $u.VerifyList = @() }
    # 12.8 (VAL01) : derniere verification d avant le nouvel essai (erreur gw pendant la passe : Restore-CalibRetestPre)
    $cal.RtVLast = $vLast
    foreach ($p in @($plan.Go)) {
        $u = $p.U
        # 12.8 (VAL01) : etat de la derniere verification, avant le repere du jugement et la correction (RtPre : erreur gw
        # pendant la passe, jugement de cette verification garde) ; references gardees, chaque champ est remplace ci-dessous
        # (jamais modifie en place), Verify et VerifyP copies
        $u.RtPre = @{ Verify = $u.Verify.Clone(); VerifyP = $u.VerifyP.Clone(); VerifyPrev = $u.VerifyPrev; ReadLast = $u.ReadLast; Witness = @($u.Witness)
                      Fit = $u.Fit; Profile = $u.Profile; WitCand = $u.WitCand; WitMin = $u.WitMin
                      DriftBase = $u.DriftBase; DriftBaseV = $u.DriftBaseV; DriftOrigV = $u.DriftOrigV    # 12.8 (S3-HIGH)
                      DriftHold = $u.DriftHold }                                                          # 12.9 (RT7)
        $dft = Get-VerifyDrift $u
        # 12.9 (RT7) : zone non reproductible et cylindres non reproductibles de cette verification (nouvel essai lance loin
        # d eux, Split-CalibRetestZone) gardes avec leur valeur ecrite pour le jugement final (Add-VerifyDriftHold) : la
        # passe du nouvel essai ne les compare plus ; zone ramenee a sa mediane par Set-VerifyContra, comme sans nouvel essai.
        # Use : derive mesuree a cette verification (zone trouvee sans derive mesuree : reserve « contra-nodrift » gardee).
        # Cylindre non reproductible au plafond ou au plancher, hors tolerance : Sat ou Floor de Get-CalibWarnings (jugees
        # avant NonRepro ; jamais une zone, besoin entre les deux valeurs ecrites), pas garde. Aucun cylindre garde : aucun
        # DriftHold (cas ou la 12.8.2 lancait deja le nouvel essai)
        $hp = @{}
        foreach ($k in @($dft.Contra.Keys)) { if ($u.VerifyP.ContainsKey([int]$k)) { $hp[[int]$k] = [int]$u.VerifyP[[int]$k] } }
        foreach ($k in @($dft.NonRepro.Keys)) {
            $c = [int]$k
            if (-not $u.VerifyP.ContainsKey($c) -or -not $u.Verify.ContainsKey($c)) { continue }
            $pw = [int]$u.VerifyP[$c]
            if ($pw -ge $script:CalHardNs -or $pw -le 0) {
                $r = [double]$u.Verify[$c].Shift; if ($dft.Use -and $u.ReadLast -and $u.ReadLast.ContainsKey($c)) { $r -= [double]$dft.D }
                if ([math]::Abs($r) -gt (Get-ResidualTol $u.Verify[$c]) -and (($r -gt 0 -and $pw -ge $script:CalHardNs) -or ($r -lt 0 -and $pw -le 0))) { continue }
            }
            $hp[$c] = $pw
        }
        $u.DriftHold = if ($hp.Count -gt 0) { @{ Contra = $dft.Contra; NonRepro = $dft.NonRepro; P = $hp; Use = ([bool]$dft.Use -and -not [bool]$dft.ContraNoDrift) } } else { $null }
        # Derive deja mesuree a la derniere verification (DriftBase, DriftBaseV) : celle du nouvel essai se compte depuis le
        # meme repere, cumulee ; la reserve « derive » de Complete-PrecompCalib juge le dernier intervalle seul. Sans derive
        # mesuree : aucune (chemins de la 12.7). 12.8 (S3-HIGH) : DriftOrigV, verification du repere (celle d avant la
        # premiere verification ciblee), gardee d un nouvel essai a l autre (mesure complete de cette disquette)
        $u.DriftBase = $null; $u.DriftBaseV = $null
        if ($dft.Use) { $u.DriftBase = [double]$dft.D; $u.DriftBaseV = $vLast; if ($null -eq $u.DriftOrigV) { $u.DriftOrigV = $vLast - 1 } }
        foreach ($k in @($u.Verify.Keys)) {
            $c = [int]$k
            # Temoin : jugement sur sa mesure precedente ; sa derniere mesure brute reste celle du journal (LogRaw, lu
            # seulement par la ligne « Residu apres verification » ; Res de la courbe : mesure precedente, comme en 12.7).
            # 12.9 : Raw deja pose (decalage commun de l ecriture retire a la verification complete, Invoke-CalibAnalysis) : garde
            # brut, jamais une valeur centree
            if (@($u.Witness) -contains $c -and $u.VerifyPrev -and $u.VerifyPrev.ContainsKey($c) -and -not $dft.Sys.ContainsKey($c)) { $m = $u.VerifyPrev[$c].Meas.Clone(); $m.LogRaw = [double]$u.Verify[$c].Shift; $u.Verify[$c] = $m; $u.VerifyP[$c] = [int]$u.VerifyPrev[$c].P }
            elseif ($dft.Use -and $u.ReadLast -and $u.ReadLast.ContainsKey($c)) { $m = $u.Verify[$c]; $u.Verify[$c] = @{ Shift = [double]$m.Shift - [double]$dft.D; SE = $m.SE; Score = $m.Score; Raw = $(if ($null -ne $m.Raw) { [double]$m.Raw } else { [double]$m.Shift }) } }
        }
        $u.VerifyPrev = @{}; $u.ReadLast = @{}; $u.Witness = @()
        # 12.8 (VAL01) : avant la correction, pour la correction sans effet (Restore-CalibRetestNoEffect) : courbe, estimations
        # (Set-CalibEstimates les remplace), residus juges des cylindres vises (NcR) et, pour chaque cylindre relu, mesure dans
        # le repere du jugement, valeur ecrite et mesures des passes (Add-CalibPoint les complete en place : copie)
        $cy = @{}
        foreach ($c in @($p.List)) {
            $ci = [int]$c; $has = $u.Verify.ContainsKey($ci)
            $rs = @{}; if ($u.Results.ContainsKey($ci)) { foreach ($x in @($u.Results[$ci].Keys)) { $rs[$x] = $u.Results[$ci][$x] } }
            $cy[$ci] = @{ Has = $has; M = $(if ($has) { $u.Verify[$ci] } else { $null }); P = $(if ($u.VerifyP.ContainsKey($ci)) { $u.VerifyP[$ci] } else { $null }); Res = $rs }
        }
        $bf = @{}
        foreach ($c in @($p.Targets)) { $ci = [int]$c; if ($p.NcR -and $p.NcR.ContainsKey($ci) -and $u.Verify.ContainsKey($ci)) { $bf[$ci] = @{ R = [double]$p.NcR[$ci].R; P = $p.NcR[$ci].P; SE = $u.Verify[$ci].SE } } }
        $u.RtSnap = @{ Fit = $u.Fit; Profile = $u.Profile; Est = $u.Est; Sig = $u.Sig; Kind = $u.Kind; Own = $u.Own; Slope = $u.Slope; Cyl = $cy; Before = $bf
                       VKeys = [int[]]@($u.Verify.Keys | ForEach-Object { [int]$_ } | Where-Object { @($u.Outliers) -notcontains $_ }) }
        if ($p.Profile -ne $u.Profile) {
            $base = ([string]$u.Fit.Model) -replace '\+c$', ''
            $u.Fit = @{ Model = "$base+c"; A = $u.Fit.A; B = $u.Fit.B; Chi = $u.Fit.Chi; Values = $p.Values; Breaks = $u.Fit.Breaks; Segs = $u.Fit.Segs; Outliers = $u.Fit.Outliers; Dents = @(Get-FitDents $u.Fit) }
            $u.Profile = $p.Profile
            Append-Log ($u.Prefix + ((T "{0} cylindre(s) corrigé(s), résidu hors tolérance, nouveau profil : {1}") -f "$($p.Corr)", "$($u.Profile)"))
        }
        $u.VerifyList = @($p.List)
        Add-DriftWitnesses $u
        # 12.9 (L2-c, banc final D-L2c) : derive non retiree a la derniere verification : ligne ecrite apres le choix des
        # temoins du nouvel essai (Add-DriftWitnesses : aucun temoin sous WitMin candidats)
        if ($p.NoDrift) {
            if (@($u.Witness).Count -gt 0) { Append-Log ($u.Prefix + (T "Calibration : dérive du lecteur non retirée à la dernière vérification (témoins insuffisants) : le nouvel essai est jugé sur ses propres témoins de dérive.")) }
            else { Append-Log ($u.Prefix + (T "Calibration : dérive du lecteur non retirée à la dernière vérification (témoins insuffisants), et aucun témoin possible pour le nouvel essai : il est jugé sans correction de dérive.")) }
        }
        $u.InRetest = $true
    }
    New-CalibPass
    return $true
}

function Get-CalibDriftStep($u, $dft) {
    # 12.8 (lot 1b) : derive du lecteur du dernier intervalle entre deux verifications (ns de decalage), jugee par la
    # reserve « derive » de Complete-PrecompCalib (seuil fait pour un intervalle, comme l exclusion du nouvel essai). Apres
    # un nouvel essai, la derive mesuree (Get-VerifyDrift) se compte depuis le repere du jugement, cumulee : la part deja
    # mesuree a la derniere verification d avant le nouvel essai (DriftBase, Start-CalibRetest) en est retiree. Sans
    # DriftBase : derive mesuree telle quelle (12.7). 12.9 : la verification complete d avant etant centree par son decalage
    # commun (VOff, Invoke-CalibAnalysis), D est le decalage commun absolu de la passe ciblee (repere des passes de mesure) ;
    # la derive entre les deux verifications, difference de leurs decalages, en retire celui de la verification complete
    # (Get-VerifyOffsetM : 0 sans retrait, chemins inchanges) ; avec DriftBase, D - DriftBase est deja une difference
    if ($null -ne $u.DriftBase) { return [double]$dft.D - [double]$u.DriftBase }
    return [double]$dft.D - (Get-VerifyOffsetM $u)
}

function Restore-CalibRetestNoEffect($cal) {
    # 12.8 (VAL01, decisions128.md) : apres la passe du nouvel essai, correction sans effet : un cylindre vise encore non
    # converge dont le residu juge n a pas bouge, au bruit pres, alors que sa valeur ecrite a change, reprend sa valeur
    # d avant le nouvel essai, avec la mesure, les mesures des passes et l estimation qui vont avec (RtSnap,
    # Start-CalibRetest) : il reste non converge, juge sur sa derniere verification d avant (repere du jugement).
    # Critere, par cylindre : dP = valeur ecrite a la passe - valeur d avant, dR = residu juge apres - residu juge avant ;
    # seuil s = max(2 ns ; 2 x ecart-type de dR), ecart-type de dR = racine(SE avant^2 + SE apres^2), au moins racine(2) x
    # bruit de mesure estime de l unite (Get-ResidualFlags : dispersion des residus voisins, bien plus forte que l erreur-type
    # d une piste) ; sans effet si |dR| < s et si la correction devait deplacer le residu d au moins s (|pente x dP| >= s ;
    # sinon, effet trop faible pour etre distingue du bruit : rien n est retabli). Courbe : valeurs d avant si aucun
    # cylindre vise n a repondu, sinon corrections des seuls cylindres qui ont repondu (Add-CurveCorrection, segments
    # d avant) ; retablissement abandonne si un cylindre mesure ne garde ni sa valeur de la passe ni celle d avant
    # (monotonie avec un voisin corrige : ligne de journal). Ecritures par piste : inchangees (pistes ecrites).
    # FIXVAL01 : cylindres retablis gardes dans RtKept : Get-CalibWarnings les juge NON CONVERGES tant qu ils sont hors
    # tolerance, meme si leur voisinage apres la passe (cylindres corriges, bruit) en ferait un ecart local non retenu.
    foreach ($u in @($cal.Units)) {
        $s = $u.RtSnap
        if ($null -ne $u.RtSnap) { $u.RtSnap = $null }
        if ($null -ne $u.RtPre) { $u.RtPre = $null }
        if (-not $u.InRetest -or -not $s -or $s.Before.Count -eq 0) { continue }
        $w = Get-CalibWarnings $u ([int]$cal.MaxCyl)
        $sl = if ($null -ne $s.Slope -and [double]$s.Slope -lt -0.2) { [double]$s.Slope } else { -2.0 }
        $sig = [double]$w.Sigma
        $old = [int[]]@($s.Fit.Values); $cur = [int[]]@($u.Fit.Values)
        $no = @(); $thrMax = 0.0
        foreach ($c in @($s.Before.Keys | ForEach-Object { [int]$_ } | Sort-Object)) {
            if (-not $w.NonConvR -or -not $w.NonConvR.ContainsKey($c) -or $c -ge $cur.Count) { continue }
            $b = $s.Before[$c]; $a = $w.NonConvR[$c]
            if ($null -eq $a.P -or $null -eq $b.P) { continue }
            $dP = [double]$a.P - [double]$b.P
            if ([math]::Abs($dP) -lt 1) { continue }
            $q = 0.0
            foreach ($x in @($b.SE, $u.Verify[$c].SE)) { if ($null -ne $x -and -not [double]::IsNaN([double]$x)) { $q += [double]$x * [double]$x } }
            $sd = [math]::Sqrt($q)
            if (-not [double]::IsNaN($sig)) { $sd = [math]::Max($sd, [math]::Sqrt(2.0) * $sig) }
            $thr = [math]::Max(2.0, 2.0 * $sd)
            if ([math]::Abs([double]$a.R - [double]$b.R) -lt $thr -and [math]::Abs($sl * $dP) -ge $thr) { $no += $c; $thrMax = [math]::Max($thrMax, $thr) }
        }
        if ($no.Count -eq 0) { continue }
        $resp = @(@($s.Before.Keys) | ForEach-Object { [int]$_ } | Where-Object { $no -notcontains $_ -and $_ -lt $cur.Count -and $cur[$_] -ne $old[$_] })
        $full = ($resp.Count -eq 0)
        if ($full) { $new = [int[]]$old.Clone() }
        else {
            $delta = @{}
            foreach ($c in @($s.VKeys)) { if ($c -lt $old.Count) { $delta[[int]$c] = 0.0 } }
            foreach ($c in $resp) { $delta[$c] = [double]$cur[$c] - [double]$old[$c] }
            $new = [int[]](Add-CurveCorrection $old $delta $s.Fit.Segs)
        }
        # Coherence : chaque cylindre mesure garde la valeur de sa mesure (celle de la passe, ou celle d avant retablie)
        $ok = ($new.Count -eq $cur.Count)
        foreach ($c in @($no)) { if ($ok -and $new[$c] -ne $old[$c]) { $ok = $false } }
        foreach ($k in @($u.Verify.Keys)) {
            $c = [int]$k
            if (-not $ok -or $c -ge $new.Count -or $new[$c] -eq $cur[$c]) { continue }
            if (-not ($new[$c] -eq $old[$c] -and $s.Cyl.ContainsKey($c))) { $ok = $false }
        }
        if (-not $ok) {
            Append-Log ($u.Prefix + ((T "Calibration : correction du nouvel essai sans effet aux cylindres {0}, valeur d'avant le nouvel essai non rétablie : la courbe ne resterait pas monotone avec les cylindres corrigés voisins.") -f (Format-CylList ([int[]]$no))))
            continue
        }
        for ($c = 0; $c -lt $new.Count; $c++) {
            if ($new[$c] -eq $cur[$c] -or -not $s.Cyl.ContainsKey($c)) { continue }
            $y = $s.Cyl[$c]
            if ($y.Has) { $u.Verify[$c] = $y.M; if ($null -ne $y.P) { $u.VerifyP[$c] = $y.P } } else { [void]$u.Verify.Remove($c); [void]$u.VerifyP.Remove($c) }
            [void]$u.VerifyPrev.Remove($c); [void]$u.ReadLast.Remove($c)
            $u.VerifyList = @(@($u.VerifyList) | Where-Object { [int]$_ -ne $c })
            $u.Results[$c] = $y.Res
            foreach ($f in 'Est', 'Sig', 'Kind', 'Own') { if ($s[$f].ContainsKey($c)) { $u[$f][$c] = $s[$f][$c] } }
        }
        if ($full) { $u.Fit = $s.Fit; $u.Profile = $s.Profile; $u.Slope = $s.Slope }
        else {
            $base = ([string]$u.Fit.Model) -replace '\+c$', ''
            $u.Fit = @{ Model = "$base+c"; A = $u.Fit.A; B = $u.Fit.B; Chi = $u.Fit.Chi; Values = $new; Breaks = $u.Fit.Breaks; Segs = $u.Fit.Segs; Outliers = $u.Fit.Outliers; Dents = @(Get-FitDents $u.Fit) }
            $u.Profile = Build-CurveProfile $new
        }
        # 12.8 (S3-HIGH) : mesure complete de cette disquette, plusieurs nouveaux essais : cylindres retablis aux essais
        # precedents gardes (union ; un seul nouvel essai : $no, comme avant)
        $u.RtKept = [int[]]@(@(@($u.RtKept) + @($no)) | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_ } | Sort-Object -Unique)
        Append-Log ($u.Prefix + ((T "Calibration : correction du nouvel essai sans effet aux cylindres {0} (résidu inchangé à {1} ns près alors que la valeur écrite a changé) : valeur d'avant le nouvel essai rétablie, ces cylindres restent non convergés.") -f (Format-CylList ([int[]]$no)), (Format-LevelNum $thrMax)))
    }
}

function Restore-CalibRetestPre($cal) {
    # 12.8 (VAL01) : passe du nouvel essai interrompue par une erreur gw (Stop-PrecompCalib -GwError) : unites remises dans
    # l etat de leur derniere verification (RtPre, Start-CalibRetest), avant le repere du jugement et la correction ; les
    # mesures des passes n ont pas change (la passe n a pas ete analysee). $true si une passe du nouvel essai etait en cours.
    if (-not $cal -or [string]$cal.Stage -ne 'verify' -or [int]$cal.Retests -le 0 -or $null -eq $cal.RtVLast) { return $false }
    $us = @($cal.Units | Where-Object { $_.RtPre })
    if ($us.Count -eq 0) { return $false }
    foreach ($u in $us) {
        $s = $u.RtPre
        $u.Verify = $s.Verify; $u.VerifyP = $s.VerifyP; $u.VerifyPrev = $s.VerifyPrev; $u.ReadLast = $s.ReadLast; $u.Witness = @($s.Witness)
        # 12.8 (S3-HIGH) : derive de repere d avant cette passe (vide avant le premier nouvel essai, comme avant)
        $u.Fit = $s.Fit; $u.Profile = $s.Profile; $u.WitCand = $s.WitCand; $u.WitMin = $s.WitMin; $u.DriftBase = $s.DriftBase; $u.DriftBaseV = $s.DriftBaseV; $u.DriftOrigV = $s.DriftOrigV
        $u.DriftHold = $s.DriftHold         # 12.9 (RT7) : zone gardee d avant cette passe (vide avant le premier nouvel essai)
        $u.RtPre = $null; $u.RtSnap = $null
    }
    foreach ($u in @($cal.Units)) { $u.InRetest = $false; $u.VerifyList = @() }
    $cal.VerifyCount = [int]$cal.RtVLast; $cal.RtVLast = $null
    $cal.TotalPasses = $cal.PassesDone
    return $true
}

function Complete-CalibRetestEnd {
    # 12.8 (VAL01) : fin differee d une calibration dont la passe du nouvel essai a echoue (Stop-PrecompCalib -GwError),
    # appelee par le minuteur principal une fois gw fini et sans autre fenetre modale : comme la fin d une derniere
    # verification sans nouvel essai (zones contradictoires, puis Complete-PrecompCalib et sa fenetre de decision)
    $cal = $script:Cal
    if (-not $cal -or -not $cal.RetestEnd) { return }
    $cal.RetestEnd = $false
    foreach ($u in $cal.Units) { [void](Set-VerifyContra $u) }
    $cal.TotalPasses = $cal.PassesDone
    Complete-PrecompCalib
}

function Write-CalibDentLog($u) {
    # 12.9 (correction 4) : bilan des dents locales du besoin suivies par la courbe d une unite (Warn.Dents, Get-CalibWarnings :
    # toujours un tableau ; filtre par securite : unite ou fixture sans ce champ, ou @($null) compte 1)
    if (-not $u -or -not $u.Warn) { return }
    foreach ($d in @(@($u.Warn.Dents) | Where-Object { $null -ne $_ })) {
        if ($d.Conf -eq $true) { Append-Log ($u.Prefix + ((T "Dent locale du besoin admise entre c{0} et c{1} ({2} ns) : mesurée par les passes de mesure, confirmée par la vérification {3}. La calibration mesure le besoin tel que le lecteur relit ses propres écritures : la courbe la suit, que la dent vienne de l'écriture ou de la lecture.") -f "$($d.C1)", "$($d.C2)", (Format-LevelNum $d.Drop), "$($d.V)")) }
        elseif ($null -ne $d.Conf) { Append-Log ($u.Prefix + ((T "Dent locale du besoin entre c{0} et c{1} ({2} ns), mesurée par les passes de mesure et suivie par la courbe, non confirmée par la dernière vérification ({3} ns entre leurs zéros) : ses résidus sont jugés normalement.") -f "$($d.C1)", "$($d.C2)", (Format-LevelNum $d.Drop), (Format-LevelNum $d.DV))) }
        else { Append-Log ($u.Prefix + ((T "Dent locale du besoin entre c{0} et c{1} ({2} ns), mesurée par les passes de mesure et suivie par la courbe, non confirmée : la vérification n'a pas relu ces deux cylindres.") -f "$($d.C1)", "$($d.C2)", (Format-LevelNum $d.Drop))) }
    }
}

function Complete-PrecompCalib {
    $cal = $script:Cal; $script:Cal = $null
    if (-not $cal) { return }
    $pbWCal.Value = 100
    $elapsedTotal = if ($cal.StartTime -is [datetime]) { ((Get-Date) - $cal.StartTime).TotalSeconds } else { 0 }
    $lblWCal.Text = ((T "Calibration terminée en {0}") -f (Format-CalDuration $elapsedTotal))
    if ($cal.Cross) { $lblWCal.Text = ((T "Calibration croisée terminée en {0}, {1} échange(s) de disquette") -f (Format-CalDuration $elapsedTotal), "$([int]$cal.Swaps)") }   # 12.10
    if (@($cal.Units | Where-Object { -not $_.Profile -or -not $_.Fit }).Count -gt 0) {
        if ($cal.DiskOnly) { Reset-DiskHardNs }     # 12.8 (S3) : borne de precompMaxNs retablie
        Append-Log (T 'Calibration precomp : aucune mesure exploitable, profil inchangé.')
        Set-HomeProgDone $cal 'stop' (T 'Calibration precomp : aucune mesure exploitable, profil inchangé.')
        if ($script:AfterCalib) { $script:AfterCalib = ''; Append-Log (T 'Écriture annulée : calibration sans mesure exploitable.') }
        if ($script:Restore) { Stop-Restore (T 'calibration sans mesure exploitable') }
        # 12.7 point 2 : calibration B sans mesure exploitable : decision sur la courbe A seule, ouverte tout de suite
        if ($script:CalRedo -and $script:CalRedo.Stage -eq 'running') { $script:CalRedo.Stage = 'interrupted'; $script:CalRedo.Why = (T 'aucune mesure exploitable'); Resume-CalibRedo }
        return
    }
    $famTxt = Get-CalibFamilyName $cal.Family
    $allConv = $true; $anySat = $false; $anyCeil = $false
    $issues = New-Object System.Collections.Generic.List[string]
    # 12.7 : nature de chaque reserve, tenue en parallele de $issues (drift, contra, contra-nodrift, nonconv, sat, floor,
    # dev, surface) : reserves liees au support (« Refaire sur une autre disquette », point 2)
    $kinds = New-Object System.Collections.Generic.List[string]
    foreach ($u in $cal.Units) {
        $kn0 = $kinds.Count      # 12.8 (S3) : reserves de cette unite (memoire de la marque, Complete-DiskMeasure)
        if ($u.Verify.Count -gt 0) {
            # 12.8 (lot 1b) : derniere mesure brute d une mesure ramenee au repere du jugement avant un nouvel essai (LogRaw :
            # temoin, Raw : cylindre relu, derive retiree)
            $resTxt = (@($u.Verify.Keys | Sort-Object | ForEach-Object { "c$_=$('{0:+0.0;-0.0;0.0}' -f $(if ($null -ne $u.Verify[$_].LogRaw) { [double]$u.Verify[$_].LogRaw } elseif ($null -ne $u.Verify[$_].Raw) { [double]$u.Verify[$_].Raw } else { [double]$u.Verify[$_].Shift }))" + $(if (@($u.Outliers) -contains [int]$_) { " ($(Get-KindName 'outlier'))" } else { '' }) })) -join ' '
            # 12.9 : decalage commun de l ecriture retire a la verification complete (VOff) : les residus de cette ligne restent
            # bruts (Raw), le rappel du decalage retire explique l ecart avec les residus juges des lignes de reserve
            $resNote = if ($null -ne $u.VOff -and [bool]$u.VOff.Removed) { (T " Résidus bruts, décalage commun de chaque écriture compris (vérification {0} : {1} ns, retiré avant le jugement).") -f "$($u.VOff.V)", ('{0:+0.0;-0.0;0.0}' -f [double]$u.VOff.M) } else { '' }
            Append-Log ($u.Prefix + ((T "Résidu après vérification (ns, tolérance {0}, élargie à 3 erreurs-types si la mesure est plus bruitée) : {1}") -f "$($script:CalResidual)", "$resTxt") + $resNote)
        }
        $u.Warn = Get-CalibWarnings $u $cal.MaxCyl
        $dft = $u.Warn.Drift
        if ($dft.Use) {
            $sla = if ($null -ne $u.Slope -and [double]$u.Slope -lt -0.2) { [math]::Abs([double]$u.Slope) } else { 2.0 }
            $dsp = if ([double]$dft.SRaw -ge 1.0) { "$(Format-LevelNum $dft.SRaw) ns" } else { (T 'moins de 1 ns') }
            # 12.8 (lot 1b) : apres un nouvel essai, derive comptee depuis le repere du jugement (DriftBase : part deja mesuree
            # a la derniere verification d avant le nouvel essai) ; $dIv : dernier intervalle seul, juge par la reserve
            $dIv = Get-CalibDriftStep $u $dft
            # 12.9 : la verification complete etant centree par son decalage commun m1 (VOff, Invoke-CalibAnalysis), D est le
            # decalage commun absolu de la derniere passe ; les lignes gardent leur sens (derive = difference des decalages des
            # deux verifications) : D - m1 en tout, DriftBase - m1 jusqu a la verification d avant le nouvel essai, $dIv pour le
            # dernier intervalle, DC - m1 pour les cylindres corriges ; le decalage absolu de la passe est ajoute a la fin quand
            # m1 a ete retire. Sans retrait (m1 = 0) : lignes identiques a celles d avant
            $m1 = Get-VerifyOffsetM $u; $dAll = [double]$dft.D - $m1
            if ($null -ne $u.DriftBase) {
                $lt = (T "Dérive du lecteur depuis la vérification {0}, nouvel essai compris : {1} ± {2} ns de décalage commun sur {3} cylindres témoins (dispersion {4}), soit {5} ns jusqu'à la vérification {6}, puis {7} ns jusqu'à la vérification {8}.") -f "$(if ($null -ne $u.DriftOrigV) { [int]$u.DriftOrigV } else { [int]$u.DriftBaseV - 1 })", ('{0:+0.0;-0.0;0.0}' -f $dAll), (Format-LevelNum $dft.E), "$($dft.NW)", "$dsp", ('{0:+0.0;-0.0;0.0}' -f ([double]$u.DriftBase - $m1)), "$([int]$u.DriftBaseV)", ('{0:+0.0;-0.0;0.0}' -f $dIv), "$($cal.VerifyCount)"
            }
            else { $lt = (T "Dérive du lecteur entre les deux vérifications : {0} ± {1} ns de décalage commun sur {2} cylindres témoins (dispersion {3}).") -f ('{0:+0.0;-0.0;0.0}' -f $dAll), (Format-LevelNum $dft.E), "$($dft.NW)", "$dsp" }
            $pdv = [math]::Round([math]::Abs($dAll) / $sla, 1); $pd = Format-LevelNum $pdv
            if ($pdv -le 0) { }
            elseif ($dAll -gt 0) { $lt += (T " Le besoin de précompensation était plus élevé de {0} ns à la dernière vérification.") -f "$pd" }
            elseif ($dAll -lt 0) { $lt += (T " Le besoin de précompensation était plus faible de {0} ns à la dernière vérification.") -f "$pd" }
            if ([int]$dft.NC -gt 0) { $lt += (T " Écart des cylindres corrigés à leur prédiction, dérive comprise : {0} ns en médiane sur {1}.") -f ('{0:+0.0;-0.0;0.0}' -f ([double]$dft.DC - $m1)), "$($dft.NC)" }
            $lt += (T " Les résidus des cylindres relus à la dernière vérification sont jugés sans ce décalage ; les témoins, inchangés, sur leur mesure précédente, sauf ceux d'un écart systématique, jugés sur leur relecture.")
            if ($null -ne $u.VOff -and [bool]$u.VOff.Removed) { $lt += (T " Décalage commun de la vérification {0} : {1} ns, retiré de ses résidus.") -f "$($cal.VerifyCount)", ('{0:+0.0;-0.0;0.0}' -f [double]$dft.D) }
            Append-Log ($u.Prefix + $lt)
            # Derive forte : retiree du jugement, mais signalee (lecteur ou support instable d une passe a l autre) ; seuil
            # fait pour un intervalle entre deux verifications (12.8 : le dernier, apres un nouvel essai)
            if ([math]::Abs($dIv) -gt 2.0 * [double]$script:CalResidual) { $issues.Add($u.Prefix + ((T "dérive du lecteur de {0} ns entre deux vérifications (lecteur ou support instable ?)") -f ('{0:+0.0;-0.0;0.0}' -f $dIv))); $kinds.Add('drift') }
        }
        elseif (@($u.Witness).Count -gt 0 -and $u.VerifyPrev.Count -gt 0) {
            Append-Log ($u.Prefix + ((T "Dérive du lecteur non mesurée : {0} témoin(s) exploitable(s) sur {1}, {2} au moins nécessaires ; résidus jugés sans correction de dérive, témoins sur leur mesure précédente.") -f "$($dft.NW)", "$(@($u.Witness).Count)", "$([int]$u.WitMin)"))
        }
        elseif (@($u.Witness).Count -eq 0 -and $u.VerifyPrev -and $u.VerifyPrev.Count -gt 0) {
            Append-Log ($u.Prefix + ((T "Dérive du lecteur non mesurée : {0} cylindre(s) non modifié(s) disponible(s) comme témoins, {1} au moins nécessaires ; résidus jugés sans correction de dérive.") -f "$([int]$u.WitCand)", "$([int]$u.WitMin)"))
        }
        # Zone non reproductible : verifications contradictoires, courbe a la mediane (Set-VerifyContra) ; liste de
        # Get-CalibWarnings (jamais un cylindre deja signale au plafond ou au plancher). Fenetre de decision si les deux
        # verifications s ecartent de plus de CalContraMaxNs, ou si la derive du lecteur n a pas ete mesuree (sans temoins,
        # une derive entre les deux verifications ne se distingue pas d une contradiction : l utilisateur tranche)
        $cn = [int[]]@(@($u.Warn.Contra) | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_ } | Sort-Object)
        if ($cn.Count -gt 0) {
            $em = [double](@($cn | ForEach-Object { [double]$dft.Contra[$_].E }) | Measure-Object -Maximum).Maximum
            $cl = Format-CylList $cn
            Append-Log ($u.Prefix + ((T "Zone non reproductible d'une vérification à l'autre aux cylindres {0} : les deux vérifications placent le besoin de part et d'autre de la valeur écrite. La courbe y prend la médiane des passes de mesure et des deux vérifications, dans l'intervalle des deux valeurs écrites et sans dépasser les cylindres vérifiés voisins (écart entre les vérifications jusqu'à {1} ns de précompensation).") -f "$cl", (Format-LevelNum $em)))
            if ($em -gt [double]$script:CalContraMaxNs) { $issues.Add($u.Prefix + ((T "vérifications contradictoires aux cylindres {0} (écart jusqu'à {1} ns : lecteur ou support instable ?)") -f "$cl", (Format-LevelNum $em))); $kinds.Add('contra') }
            elseif (-not $dft.Use -or $dft.ContraNoDrift) { $issues.Add($u.Prefix + ((T "vérifications contradictoires aux cylindres {0} sans mesure de la dérive du lecteur (écart jusqu'à {1} ns : dérive du lecteur ou zone non reproductible ?)") -f "$cl", (Format-LevelNum $em))); $kinds.Add('contra-nodrift') }
        }
        # Filet du lissage de la zone : cylindre verifie hors zone deplace malgre tout (test standard : cylindre interpole
        # entre la zone et lui), sans nouvelle mesure ; son residu n est pas enregistre
        $mv = [int[]]@(@($u.ContraMoved) | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_ } | Sort-Object)
        if ($mv.Count -gt 0) {
            Append-Log ($u.Prefix + ((T "Cylindres vérifiés {0} déplacés par le lissage croissant de la courbe autour de la zone non reproductible, sans nouvelle mesure : leur résidu n'est pas enregistré avec la courbe.") -f (Format-CylList $mv)))
        }
        if (@($u.Warn.NonRepro).Count -gt 0) {
            Append-Log ($u.Prefix + ((T "Cylindres non reproductibles d'une vérification à l'autre (zéro estimé à la pente commune par la vérification précédente, puis par la dernière, dérive retirée) : {0}. Ils ne comptent pas pour la convergence ; une nouvelle calibration peut leur donner une autre valeur.") -f (@($u.Warn.NonRepro) -join ', ')))
        }
        if (-not [double]::IsNaN([double]$u.Warn.Sigma)) {
            Append-Log ($u.Prefix + ((T "Bruit de mesure estimé : {0} ns, sur {1} écarts entre cylindres vérifiés distants de 2 au plus. Un écart est retenu si la moyenne des résidus voisins (2 cylindres au plus) dépasse {2} ns, si un résidu dépasse {3} ns, s'il s'étend sur 3 cylindres ou plus, ou 2 en bord de piste ou de segment, au-delà de {2} ns, ou s'il couvre 2 cylindres au-delà de {4} ns. Seuils relevés quand le bruit est fort. Un écart dont un cylindre a moins de 2 autres cylindres vérifiés à 2 cylindres au plus est retenu sur sa seule tolérance ; les points isolés et les cylindres au plafond ou au plancher ne comptent ni dans le bruit ni dans le voisinage, les cylindres non reproductibles ni dans le bruit ni dans les moyennes.") -f (Format-LevelNum $u.Warn.Sigma), "$($u.Warn.NDiff)", (Format-LevelNum $script:CalResidual), (Format-LevelNum $u.Warn.Hard), (Format-LevelNum $u.Warn.HardPair)))
        }
        if (@($u.Warn.Spot).Count -gt 0) {
            Append-Log ($u.Prefix + ((T "Écarts locaux non retenus : {0}. Hors tolérance, mais sous les seuils ci-dessus : ces écarts ne sont pas corrigés.") -f (@($u.Warn.Spot) -join ', ')))
        }
        if ($u.Warn.NonConv.Count -gt 0) { $issues.Add($u.Prefix + ((T "non convergée aux cylindres {0}") -f ($u.Warn.NonConv -join ', '))); $kinds.Add('nonconv') }
        # 12.10 (lot 1, A13a) : mesure de la disquette seule : plafond de cette disquette (Get-DiskHardNs), libelle neutre
        # de la calibration rapide (autre type de disquette ou usure), sans mettre en cause une disquette sacrifiee
        if ($u.Warn.Sat.Count -gt 0) {
            $satTxt = if ($cal.DiskOnly) { (T "plafond de {0} ns atteint aux cylindres {1} (autre type de disquette ou usure ?)") } else { (T "plafond de {0} ns atteint aux cylindres {1} (support fatigué ?)") }
            $issues.Add($u.Prefix + ($satTxt -f "$($script:CalHardNs)", ($u.Warn.Sat -join ', '))); $kinds.Add('sat')
        }
        if ($u.Warn.Floor.Count -gt 0) { $issues.Add($u.Prefix + ((T "précompensation nulle encore excessive aux cylindres {0}") -f ($u.Warn.Floor -join ', '))); $kinds.Add('floor') }
        if ($u.Warn.Dev.Count -gt 0) { $issues.Add($u.Prefix + ((T "courbe éloignée des mesures (courbe moins mesure) : {0}") -f ($u.Warn.Dev -join ', '))); $kinds.Add('dev') }
        if ($u.Warn.NonConv.Count -gt 0) {
            $allConv = $false
            # 12.8 (S3) : mesure complete de cette disquette : pas de disquette sacrifiee a conseiller
            if ($cal.DiskOnly) { Append-Log ($u.Prefix + ((T "Mesure non convergée aux cylindres {0} : résidu hors tolérance après la dernière vérification, la courbe ne suit pas la mesure de cette disquette à ces cylindres.") -f ($u.Warn.NonConv -join ', '))) }
            else {
                # 12.9 (L2-a, L2-d) : conseil selon la cause, verdict inchange. Marche du besoin non suivie par la courbe
                # (Get-CalibNeedSteps) ou meme ecart que la calibration A aux memes cylindres (calibration B,
                # Get-CalibCommonReserve) : signature du lecteur, pas de conseil de refaire sur une autre disquette
                $stC = @(); foreach ($st in @($u.Warn.Steps)) { if ($st) { $stC += @($st.Cyls) } }
                $ncU = [int[]]@(@($u.Warn.NonConvC) | Where-Object { $null -ne $_ })
                $cmn = [int[]]@()
                if ($cal.Redo -and $script:CalRedo -and $script:CalRedo.ACal) {
                    $ui = [array]::IndexOf(@($cal.Units), $u)
                    $ua = if ($ui -ge 0 -and $ui -lt @($script:CalRedo.ACal.Units).Count) { @($script:CalRedo.ACal.Units)[$ui] } else { $null }
                    if ($ua -and $ua.Warn) { $cmn = [int[]]@(Get-CalibCommonReserve (Get-CalibUnitReserve $ua.Warn) (Get-CalibUnitReserve $u.Warn)) }
                }
                $drv = @($ncU | Where-Object { $stC -notcontains $_ -and $cmn -notcontains $_ }).Count -eq 0
                if ($drv) { Append-Log ($u.Prefix + ((T "Calibration non convergée aux cylindres {0} : résidu hors tolérance après la dernière vérification, la courbe ne suit pas la mesure à ces cylindres.") -f ($u.Warn.NonConv -join ', '))) }
                else { Append-Log ($u.Prefix + ((T "Calibration non convergée aux cylindres {0} : résidu hors tolérance après la dernière vérification, la courbe ne suit pas la mesure à ces cylindres. Refaire la calibration en test fin, ou sur une autre disquette sacrifiée.") -f ($u.Warn.NonConv -join ', '))) }
                foreach ($st in @($u.Warn.Steps)) {
                    if (-not $st) { continue }
                    Append-Log ($u.Prefix + ((T "Marche du besoin de {0} ns entre c{1} et c{2}, sous le seuil de rupture de la courbe ({3} ns) : la courbe garde un palier, écart de {4} ns au plus sur ces cylindres. Signature du lecteur si elle revient sur une autre disquette ; refaire la calibration n'y change rien.") -f (Format-LevelNum $st.Drop), "$($st.C1)", "$($st.C2)", (Format-LevelNum $u.Warn.StepBreak), (Format-LevelNum $st.Dev)))
                }
                if ($cmn.Count -gt 0) { Append-Log ($u.Prefix + ((T "Même écart aux cylindres {0} sur les deux disquettes : il vient du lecteur, pas du support.") -f (Format-CylList $cmn))) }
            }
        }
        if ($u.Warn.Sat.Count -gt 0) {
            $anySat = $true; $anyCeil = $true
            # 12.10 (lot 1, A13a) : mesure de la disquette seule : libelle neutre, l usure n est pas presumee
            if ($cal.DiskOnly) { Append-Log ($u.Prefix + ((T "Plafond de {0} ns atteint aux cylindres {1} : le besoin de cette disquette dépasse la précompensation maximale, la courbe reste au plafond et une nouvelle mesure n'y changera rien. Autre type de disquette ou usure, non distingués ; si d'autres disquettes saturent aussi, c'est le lecteur.") -f "$($script:CalHardNs)", ($u.Warn.Sat -join ', '))) }
            else { Append-Log ($u.Prefix + ((T "Plafond de {0} ns atteint aux cylindres {1} : le besoin dépasse la précompensation maximale, la courbe reste au plafond et une nouvelle calibration n'y changera rien. Si une disquette en bon état sature aussi, c'est le lecteur ; sinon, c'est le support, probablement fatigué.") -f "$($script:CalHardNs)", ($u.Warn.Sat -join ', '))) }
        }
        if ($u.Warn.Floor.Count -gt 0) {
            $anySat = $true
            Append-Log ($u.Prefix + ((T "Précompensation nulle encore excessive aux cylindres {0} : la courbe reste à 0 ns et une nouvelle calibration n'y changera rien. La même mesure sur une autre disquette désigne le lecteur, sinon le support.") -f ($u.Warn.Floor -join ', ')))
        }
        if (@($u.Warn.Beyond).Count -gt 0) {
            # Courbe au-dela du plafond des passes de mesure : information (valeurs verifiees), sans fenetre de decision
            $anyCeil = $true
            $bmax = [int](@($u.Warn.Beyond | ForEach-Object { [int]$u.Fit.Values[$_] }) | Measure-Object -Maximum).Maximum
            $how = if ($u.Trend -and @($u.Trend.Keys).Count -gt 0) { (T ' et par la tendance de la courbe') } else { '' }
            # 12.8 (S3) : mesure complete de cette disquette : pas de support de calibration a mettre en cause
            # 12.8 (S3-HIGH) : cylindres mesures autour de leur besoin par la mesure directe (Start-DiskReach)
            $rch = [int[]]@(if ($u.Reach) { @($u.Reach.Keys | ForEach-Object { [int]$_ } | Sort-Object) })
            if ($cal.DiskOnly -and $rch.Count -gt 0) { Append-Log ($u.Prefix + ((T "Besoin au-delà de {0} ns, plafond des passes de mesure, aux cylindres {1} : courbe de cette disquette jusqu'à {2} ns, mesurée directement autour du besoin aux cylindres {3} (mesure directe), puis contrôlée par la vérification.") -f "$($script:CalMaxNs)", (Format-CylList ([int[]]$u.Warn.Beyond)), "$bmax", (Format-CylList $rch))) }
            elseif ($cal.DiskOnly) { Append-Log ($u.Prefix + ((T "Besoin au-delà de {0} ns, plafond des passes de mesure, aux cylindres {1} : courbe de cette disquette jusqu'à {2} ns, déduite par extrapolation des mesures{3}, puis contrôlée par la vérification.") -f "$($script:CalMaxNs)", (Format-CylList ([int[]]$u.Warn.Beyond)), "$bmax", "$how")) }
            else { Append-Log ($u.Prefix + ((T "Besoin au-delà de {0} ns, plafond des passes de mesure, aux cylindres {1} : courbe jusqu'à {2} ns, déduite par extrapolation des mesures{3}, puis contrôlée par la vérification. Un besoin aussi fort est inhabituel : si une disquette en bon état ne l'atteint pas, le support de calibration est probablement fatigué.") -f "$($script:CalMaxNs)", (Format-CylList ([int[]]$u.Warn.Beyond)), "$bmax", "$how")) }
        }
        if ($cal.DiskOnly) {
            # 12.8 (S3) : courbe de cette disquette au-dela de 400 ns (Get-DiskOverNs) : reserve d information, controle apres
            # ecriture impose (Complete-DiskMeasure) ; plafond porte par disquette (Get-DiskHardNs)
            $thr = Get-DiskOverNs
            $ov = [int[]]@(0..(@($u.Fit.Values).Count - 1) | Where-Object { [int]$u.Fit.Values[$_] -gt $thr })
            if ($ov.Count -gt 0) {
                $top = [int](@($u.Fit.Values) | Measure-Object -Maximum).Maximum
                Append-Log ($u.Prefix + ((T "Courbe de cette disquette au-delà de {0} ns aux cylindres {1} (jusqu'à {2} ns) : plafond porté à {3} ns pour cette disquette seulement ; contrôle après écriture imposé.") -f "$thr", (Format-CylList $ov), "$top", "$($cal.HardNs)"))
                Append-Log ($u.Prefix + (Get-DiskOverAdviceText $thr))   # 12.11 : conseil d essai sur la machine cible
                $issues.Add($u.Prefix + ((T "courbe de cette disquette au-delà de {0} ns aux cylindres {1} (jusqu'à {2} ns, plafond porté à {3} ns pour cette disquette seulement) : contrôle après écriture imposé") -f "$thr", (Format-CylList $ov), "$top", "$($cal.HardNs)")); $kinds.Add('over')
            }
        }
        $bk = @($u.Warn.Breaks)
        if ($bk.Count -ge 2) { Append-Log ($u.Prefix + ((T "Changement de sens du besoin entre c{0} et c{1} : courbe monotone par segments. La même signature sur une autre disquette désigne le lecteur, sinon le support.") -f "$($bk[0])", "$($bk[1])")) }
        elseif ($bk.Count -eq 1) { Append-Log ($u.Prefix + ((T "Le besoin redescend à partir de c{0} : courbe monotone par segments. La même signature sur une autre disquette désigne le lecteur, sinon le support.") -f "$($bk[0])")) }
        Write-CalibDentLog $u        # 12.9 (correction 4)
        if ($u.Warn.Dev.Count -gt 0) { Append-Log ($u.Prefix + ((T "Écart à la courbe de plus de {1} ns et de trois incertitudes (courbe moins mesure) : {0}.") -f ($u.Warn.Dev -join ', '), (Format-UiNum $script:CalDevNs))) }
        # Calibration precedente du meme lecteur (encore en memoire, remplacee plus bas) : la forme de la courbe tient au
        # lecteur, son niveau au support ; un ecart net, ou un plafond nouveau, designe le support de calibration
        $pkey = if ($null -eq $u.Head) { $cal.Family } else { "$($cal.Family)_h$($u.Head)" }
        $prev = $script:PrecompCurves[$pkey]   # 12.10 : vue du lecteur courant, lecteur de la courbe controle ci-dessous (les bancs remettent la vue a zero)
        if ($cal.Cross) { $prev = Get-DriveCurve (Get-CalibStoreDrive $cal) $pkey }   # 12.10 : courbe croisee precedente (meme source, meme cible)
        # 12.8 (S3-FIX, M4) : mesure complete de cette disquette : reference reellement utilisee par la mesure (Get-DiskRefUnit :
        # courbe par tete, ou courbe commune pour les deux tetes en restauration), celle de l enregistrement 'mesure'
        if ($cal.DiskOnly) { $ru = Get-DiskRefUnit $cal $u; $prev = if ($ru) { $ru.Cv } else { $null } }
        if ($prev -and [string]$prev.Drive -eq [string]$cal.Drive -and @($prev.Values).Count -gt 0 -and $u.Fit) {
            $pv = @($prev.Values); $nv = @($u.Fit.Values); $nn = [math]::Min($pv.Count, $nv.Count)
            if ($nn -gt 0) {
                $dd = @(for ($c = 0; $c -lt $nn; $c++) { [int]$nv[$c] - [int]$pv[$c] })
                $ds = $dd | Measure-Object -Average -Minimum -Maximum
                if ($cal.DiskOnly) {
                    # 12.8 (S3, M4) : la courbe en place est la reference du lecteur, gardee ; ecart de cette disquette, sans
                    # diagnostic du support de calibration
                    Append-Log ($u.Prefix + ((T "Écart de cette disquette à la référence du lecteur ({0}) : {1} ns en moyenne (de {2} à {3} ns).") -f "$($prev.Date)", ('{0:+0;-0;0}' -f [math]::Round($ds.Average, 0)), ('{0:+0;-0;0}' -f $ds.Minimum), ('{0:+0;-0;0}' -f $ds.Maximum)))
                    $nn = 0
                }
                else { Append-Log ($u.Prefix + ((T "Écart avec la calibration précédente du lecteur {0} ({1}) : {2} ns en moyenne (de {3} à {4} ns).") -f "$($cal.Drive)", "$($prev.Date)", ('{0:+0;-0;0}' -f [math]::Round($ds.Average, 0)), ('{0:+0;-0;0}' -f $ds.Minimum), ('{0:+0;-0;0}' -f $ds.Maximum))) }
            }
            if ($nn -gt 0) {
                # Plafond de la courbe precedente : borne de SON calcul (300 ns avant le calcul 12.4)
                $pmax = [math]::Min((Get-CurveMaxNs $prev), [int]$script:CalHardNs)   # ramenee a la borne actuelle
                $ptop = [int](@($pv[0..($nn - 1)]) | Measure-Object -Maximum).Maximum
                if ($u.Warn.Sat.Count -gt 0 -and $ptop -lt $pmax) {
                    Append-Log ($u.Prefix + (T "Plafond atteint alors que la calibration précédente du même lecteur ne l'atteignait pas : support de calibration probablement fatigué (sinon têtes à nettoyer, ou autre lecteur sous la même lettre)."))
                }
                # Besoin au-dela du plafond des mesures : signale seulement une hausse nette (plus de CalDevNs, 15 ns en double
                # densite, sur le maximum des cylindres communs), pas une courbe qui passe de 298 a 305 ns
                elseif (@($u.Warn.Beyond).Count -gt 0 -and $ptop -le $script:CalMaxNs -and $ptop -lt $pmax -and [int](@($nv[0..($nn - 1)]) | Measure-Object -Maximum).Maximum - $ptop -gt $script:CalDevNs) {
                    Append-Log ($u.Prefix + ((T "Besoin au-delà de {0} ns alors que la calibration précédente du même lecteur ne dépassait pas cette valeur : support de calibration probablement fatigué (sinon têtes à nettoyer, ou autre lecteur sous la même lettre).") -f "$($script:CalMaxNs)"))
                }
            }
        }
        # Diagnostic de forme (calibration rapide) : sur les cylindres mesures par les deux calibrations, ecart de niveau
        # et ecart de forme (dispersion apres retrait du niveau) ; donnees pour recaler les seuils sur materiel reel. 12.8 (S3) :
        # pas pour une mesure complete de cette disquette (M4 ci-dessus)
        if (-not $cal.DiskOnly -and $prev -and [string]$prev.Drive -eq [string]$cal.Drive -and $prev.Cyls -and $prev.Ys) {
            $dd2 = @{}
            for ($i = 0; $i -lt @($prev.Cyls).Count; $i++) {
                $c = [int]$prev.Cyls[$i]
                $pk2 = if ($prev.Kinds -and $i -lt @($prev.Kinds).Count) { [string]$prev.Kinds[$i] } else { 'interp' }
                if ($pk2 -ne 'interp' -or -not $u.Est.ContainsKey($c) -or [string]$u.Kind[$c] -ne 'interp') { continue }
                $dd2[$c] = [double]$u.Est[$c] - [double]$prev.Ys[$i]
            }
            if ($dd2.Count -ge 4) {
                $mv = (@($dd2.Values) | Measure-Object -Average).Average
                $sdv = [math]::Sqrt((@($dd2.Values | ForEach-Object { [math]::Pow($_ - $mv, 2) }) | Measure-Object -Sum).Sum / ($dd2.Count - 1))
                $wc = @($dd2.Keys | Sort-Object { -[math]::Abs($dd2[$_] - $mv) })[0]
                Append-Log ($u.Prefix + ((T "Forme comparée à la calibration précédente du lecteur {0} ({1}), sur {2} cylindres mesurés par les deux : niveau {3} ns, écart de forme {4} ns (au plus {5} ns, à c{6}).") -f "$($cal.Drive)", "$($prev.Date)", "$($dd2.Count)", ('{0:+0;-0;0}' -f [math]::Round($mv, 0)), ('{0:0.#}' -f [math]::Round($sdv, 1)), ('{0:+0;-0;0}' -f [math]::Round($dd2[$wc] - $mv, 0)), "$wc"))
            }
        }
        # 12.7 : courbe commune mesuree sur une seule face a au moins une passe (valeur de l autre face, ecart des tetes non compense)
        if ($null -eq $u.Head -and $u.OneFace -and $u.OneFace.Count -gt 0) {
            foreach ($hm in 0, 1) {
                $oc = [int[]]@(@($u.OneFace.Keys) | Where-Object { $_ -like "*|$hm" } | ForEach-Object { [int](($_ -split '\|')[0]) } | Sort-Object -Unique)
                if ($oc.Count) { Append-Log ($u.Prefix + ((T "Cylindres mesurés sans la face {0} à au moins une passe : {1}. En courbe commune, leur valeur vient de l'autre face seule : l'écart entre les têtes n'y est pas compensé. Refaire la calibration en écriture lente (une courbe par tête), ou sur une autre disquette.") -f "$hm", (Format-CylList $oc))) }
            }
        }
        if ($u.Warn.Extrap.Count + $u.Warn.Cap.Count -gt 0) {
            Append-Log ($u.Prefix + ((T "Valeurs peu fiables : {0} extrapolée(s) au-delà des mesures ({1}), {2} plafonnée(s) à 0 ou {3} ns ({4}).") -f "$($u.Warn.Extrap.Count)", ($(if ($u.Warn.Extrap.Count) { $u.Warn.Extrap -join ',' } else { '-' })), "$($u.Warn.Cap.Count)", "$($script:CalHardNs)", ($(if ($u.Warn.Cap.Count) { $u.Warn.Cap -join ',' } else { '-' }))))
        }
        # 12.8 (S3) : tete sans reserve pour la memoire de la marque (Update-LevelBrandCurve) : aucune reserve de cette unite,
        # sauf la courbe au-dela de 400 ns (reserve d information), convergee
        if ($cal.DiskOnly) {
            $own = @(); for ($ki = $kn0; $ki -lt $kinds.Count; $ki++) { if ($kinds[$ki] -ne 'over') { $own += $kinds[$ki] } }
            $u.DiskOk = [bool]($own.Count -eq 0 -and $u.Warn.NonConv.Count -eq 0)
        }
    }
    # 12.7 : controle de surface de la passe 1. Defaut grossier, calibration poursuivie a la demande de l utilisateur :
    # journal, et reserve si la fenetre de decision s ouvre pour une autre raison. Disquette douteuse sans defaut grossier
    # (arbitrage 1) : reserve « support », qui ouvre la fenetre de decision
    # Defaut de vitesse seul (Test-CalibSpeedOnly) : bilan et reserve qui nomment le lecteur, reserve 'speed' (pas liee au
    # support : pas de « Refaire sur une autre disquette » pour elle seule). $surfIssue : bilan de l Accueil
    $surfIssue = ''
    if ($cal.SurfKept -and $cal.Surf) {
        $st = Format-CalibSurfaceVerdict $cal.Surf $cal.Medium
        if (Test-CalibSpeedOnly $cal.Surf $cal.Medium) {
            Append-Log ((T 'Contrôle de vitesse et de densité de la première passe : {0} ; calibration poursuivie à votre demande : la courbe a été mesurée avec un lecteur qui ne tourne pas à la vitesse de ce type de disquette.') -f "$st")
            $surfIssue = (T 'contrôle de vitesse et de densité : {0}, calibration poursuivie à votre demande') -f "$st"; $surfKind = 'speed'
        } else {
            Append-Log ((T "Contrôle de surface de la première passe : disquette jugée douteuse ({0}), calibration poursuivie à votre demande : la courbe peut refléter ce support plutôt que le lecteur.") -f "$st")
            $surfIssue = (T "contrôle de surface : disquette de calibration douteuse ({0}), calibration poursuivie à votre demande") -f "$st"; $surfKind = 'surface'
        }
        if ($issues.Count -gt 0) { $issues.Add($surfIssue); $kinds.Add($surfKind) }
    }
    elseif ($cal.Surf -and $cal.Surf.Defective -and -not $cal.SurfGross) { $issues.Add((Format-CalibSurfaceReserve $cal.Surf)); $kinds.Add('surface') }
    if ($anyCeil -and $cal.Swap) { Append-Log ((T "Calibration faite sur une disquette sacrifiée dont le besoin dépasse {0} ns : si elle est fatiguée, la courbe surestime le besoin de la disquette à écrire. Préférez une disquette sacrifiée en bon état.") -f "$($script:CalMaxNs)") }
    # 12.8 (S3, c4-design § 4.2) : mesure complete de cette disquette : la reference du lecteur n est pas modifiee (ni
    # copie .bak, ni PrecompCurves, ni abandon des niveaux et des marques) ; fin propre (Complete-DiskMeasure)
    if ($cal.DiskOnly) { Complete-DiskMeasure $cal $issues $kinds $surfIssue; return }
    # 12.8 (lot 1c, point 4) : copie du fichier de configuration avant le remplacement de la reference (toute calibration
    # complete : bouton Calibrer, carte de l Accueil, calibration avant une ecriture, repli du point 3, calibration B,
    # restauration) ; sans courbe a remplacer : rien
    # 12.10 : cles de magasin du lecteur de la calibration (courbes par lecteur)
    # Calibration croisee : lecteur de magasin « source>cible » (Get-CalibStoreDrive)
    [void](Backup-ConfigBeforeRef @($cal.Units | ForEach-Object { Get-DriveCurveKey (Get-CalibStoreDrive $cal) (Get-CalibUnitKey $cal $_) }) 'replace')
    # Etat precedent (courbes et profils remplaces ci-dessous) : retabli si l utilisateur refuse un resultat douteux
    $prevCal = Get-CalibSnapshot @($cal.Units | ForEach-Object { Get-DriveCurveKey (Get-CalibStoreDrive $cal) (Get-CalibUnitKey $cal $_) })
    # Profil commun : remplace celui de la famille. Ecriture lente : courbes par tete, le profil commun est conserve.
    # 12.10 : courbe croisee : le profil de famille du lecteur (sa courbe propre) n est pas touche
    if (-not $cal.Slow -and -not $cal.Cross) {
        $spec = $cal.Units[0].Profile
        # 12.7 : haute densite : profil tire de sa courbe commune (Get-HdProfile), aucun profil de famille a remplacer
        # 12.10 : profil de la vue du lecteur du bandeau seulement ; pour un autre lecteur (lecteur change dans le bandeau
        # pendant la calibration), Sync-PrecompCurves le tire de la courbe commune au retour sur ce lecteur
        if ([string]$cal.Drive -eq [string]$cmbDrive.Text) {
            if ($cal.Family -eq 'long') { $script:PrecompLong = $spec } elseif ([string]$cal.Family -ne 'hd') { $script:PrecompStd = $spec }
        }
    }
    $date = Get-Date -Format 'dd/MM/yyyy HH:mm'
    foreach ($u in $cal.Units) {
        $key = if ($null -eq $u.Head) { $cal.Family } else { "$($cal.Family)_h$($u.Head)" }
        $cs = @($u.Est.Keys | ForEach-Object { [int]$_ } | Sort-Object)
        $maxX = 0
        foreach ($c in $cs) { foreach ($x in @($u.Results[$c].Keys)) { if ([int]$x -gt $maxX) { $maxX = [int]$x } } }
        $asym = Get-UnitAsymRef $cal $u     # 12.10 : asymetrie de reference (motif relu a la verification 1)
        # 12.10 : courbe rangee sous le lecteur de la calibration (Set-DriveCurve : magasin, puis vue du lecteur courant) ;
        # calibration croisee : sous « source>cible » (Get-CalibStoreDrive), Drive = source (qui ecrit), Target = cible (qui relit)
        Set-DriveCurve (Get-CalibStoreDrive $cal) $key @{
            Family = $famTxt; Head = $u.Head; Drive = $cal.Drive; Target = $(if ($cal.Cross) { [string]$cal.Cross.Tgt } else { '' }); Date = $date; Model = $u.Fit.Model; Spec = $u.Profile; Method = 'motif'
            Version = $script:Version; Algo = $script:CalibAlgo; Calc = $(if ([string]$cal.Family -eq 'hd') { $script:CalibCalcHd } else { $script:CalibCalc }); Breaks = [int[]]@($u.Fit.Breaks)
            Values = [int[]]@($u.Fit.Values); Cyls = [int[]]$cs
            Ys = [double[]]@($cs | ForEach-Object { [math]::Round([double]$u.Est[$_], 1) })
            Sig = [double[]]@($cs | ForEach-Object { [math]::Round($(if ($u.Sig.ContainsKey($_)) { [double]$u.Sig[$_] } else { 5.0 }), 1) })
            Kinds = [string[]]@($cs | ForEach-Object { [string]$u.Kind[$_] })
            # 12.9 (voff, revue M2) : Res = residu juge (Shift centre du decalage commun de l ecriture ; temoin : son jugement
            # precedent), lu comme tel par la calibration rapide (260), Test-CurveAtMax et la fenetre Courbe (230) ; le brut
            # reste au journal (« Residu apres verification ») ; hors VOff (haute densite, calcul 12.7) : regle de la 12.8, brut des relus
            Res = [double[]]@($cs | ForEach-Object { if (@($u.Warn.Contra) -contains $_ -or @($u.ContraMoved) -contains $_) { [double]::NaN } elseif (@($u.Witness) -contains $_ -and $u.VerifyPrev.ContainsKey($_) -and -not $u.Warn.Drift.Sys.ContainsKey($_)) { [math]::Round($(if ([bool]$cal.VOff) { [double]$u.VerifyPrev[$_].Shift } elseif ($u.VerifyPrev[$_].Meas -and $null -ne $u.VerifyPrev[$_].Meas.Raw) { [double]$u.VerifyPrev[$_].Meas.Raw } else { [double]$u.VerifyPrev[$_].Shift }), 1) } elseif ($u.Verify.ContainsKey($_)) { [math]::Round($(if ([bool]$cal.VOff -or $null -eq $u.Verify[$_].Raw) { [double]$u.Verify[$_].Shift } else { [double]$u.Verify[$_].Raw }), 1) } else { [double]::NaN } })
            Converged = ($u.Warn.NonConv.Count -eq 0); MaxX = $maxX; MaxNs = [int]$script:CalHardNs
            # 12.10 : asymetrie de reference de la famille sur ce lecteur (Get-UnitAsymRef) : cylindres, ecarts 3T/2T - 1,5 et
            # 4T/2T - 2 du motif relu a la verification 1 ; 12.11 : gardes pour l etude, plus lus par l onglet Qualite
            AsymCyl = [int[]]@($asym.Cyl); AsymD3 = [double[]]@($asym.D3); AsymD4 = [double[]]@($asym.D4)
            Contra = [int[]]@(@($u.Warn.Contra) | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_ } | Sort-Object)
            # 12.9 (correction 4) : toutes les dents de la courbe (confirmees, en attente, ou non confirmees a la derniere
            # verification et gardees), memes regles que Contra
            DentLo = [int[]]@(@($u.Warn.Dents) | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_.C1 })
            DentHi = [int[]]@(@($u.Warn.Dents) | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_.C2 })
            DentNs = [double[]]@(@($u.Warn.Dents) | Where-Object { $null -ne $_ } | ForEach-Object { [math]::Round([double]$_.Drop, 1) })
            Slope =$(if ($null -ne $u.Slope) { [math]::Round([double]$u.Slope, 3) } else { $null }); Bits = [int]$cal.PatternBits; Test = [string]$cal.Mode
        }
    }
    # 12.8 (lot 1c, § 10.5) : marques memorisees avec la reference remplacee : gardees, mais plus point de depart (date de
    # reference differente) ; une copie .bak retablie ou l abandon de la nouvelle courbe les rend de nouveau valables
    $brOld = @()
    foreach ($u in $cal.Units) {
        $key = if ($null -eq $u.Head) { $cal.Family } else { "$($cal.Family)_h$($u.Head)" }
        $pc = $prevCal.Curves[$key]
        if ($pc -and -not $cal.Cross) { $brOld += @(Get-LevelBrandsOfRef $key ([string]$pc.Date) ([string]$cal.Drive)) }   # 12.10 : aucune marque liee a une courbe croisee
    }
    $brOld = @($brOld | Sort-Object -Unique)
    if ($brOld.Count -gt 0) { Append-Log ((T 'Marques mémorisées avec la référence précédente ({0}) : elles seront mesurées de nouveau à leur prochaine calibration rapide.') -f ($brOld -join ', ')) }
    # Nouvelle reference de forme : les niveaux mesures avec la precedente sont abandonnes
    $dropped = @()
    foreach ($u in $cal.Units) {
        $key = if ($null -eq $u.Head) { $cal.Family } else { "$($cal.Family)_h$($u.Head)" }
        # 12.10 : niveaux de ce lecteur seulement (courbes par lecteur : la reference de l autre lecteur ne change pas) ; une
        # courbe croisee n est la reference d aucun niveau : rien d abandonne
        foreach ($k in @($script:LevelShifts.Keys)) { if (-not $cal.Cross -and $script:LevelShifts[$k] -and $script:LevelShifts[$k].RefKey -eq $key -and [string]$script:LevelShifts[$k].Drive -eq [string]$cal.Drive) { $script:LevelShifts.Remove($k); $dropped += $key } }
    }
    if ($dropped.Count -gt 0) { Append-Log ((T "Nouvelle référence de forme ({0}) : les niveaux mesurés avec la précédente sont abandonnés.") -f ((@($dropped | Sort-Object -Unique | ForEach-Object { Get-CurveKeyLabel $_ })) -join ', ')) }
    # Auto : applique le profil de la famille de l image ; carte Calibration de l Accueil : profil choisi dans l onglet
    # Ecriture respecte (Manuel compris), libelle du profil seulement pour une image de l onglet de la famille calibree
    # 12.10 : courbe croisee : profil de l image et champs --precomp inchanges (la courbe propre du lecteur ne change pas)
    if (-not $cal.Home -and -not $cal.Cross) { $cmbWProfile.SelectedIndex = 0 }
    if (-not $cal.Cross) { Update-PrecompForImage $txtWFile.Text }
    else {
        # 12.10 (relecture de la RC, fix2) : courbe croisee enregistree : bouton « Courbe » de l onglet (Update-CurveButton :
        # courbes que l ecriture applique, Get-WCurveSet ; cadre « Calibration du lecteur » de la restauration avec lui,
        # Update-RsCalib) et case de la mesure (Update-WLevelUi : infobulle du refus) recalcules d apres le refus de
        # l ecriture refait (Get-TargetWriteInfo), comme apres les autres changements de courbes ; libelle du profil (bilan
        # ci-dessous) et champs --precomp inchanges. Avant : rien de refait, bouton grise et infobulle « Ecriture refusee »
        # apres la calibration croisee qui leve ce refus
        Update-CurveButton $txtWFile.Text; Update-WLevelUi
    }
    $convTxt = if (-not $allConv) { (T ' NON CONVERGÉE : voir le journal et la fenêtre Courbe.') } elseif ($anySat) { ((T ' Limite de précompensation atteinte (0 ou {0} ns) : voir le journal.') -f "$($script:CalHardNs)") } else { '' }
    # 12.10 (relecture de la RC) : avertissement en tete des libelles de fin ($convHead), et non a leur suite : apres un
    # texte long (calibration croisee, profils par tete), il etait cache par les points de suspension de lblWCal (une
    # ligne, 520) et du libelle du profil (deux lignes)
    $convHead = if ($convTxt) { $convTxt.Trim() + ' ' } else { '' }
    $showLbl = (-not $cal.Home) -or ($cmbWProfile.SelectedIndex -eq 0 -and (Get-WriteTabFamily) -eq $cal.Family)
    # 12.10 (relecture de la RC) : lecteur cible choisi pour ce lecteur (Get-TargetDrive ; sans etat des lecteurs cibles,
    # 560 : aucun) : avec effet sur l image de l onglet (Get-TargetWriteInfo, celui de Start-ImageWrite), le libelle
    # d Update-PrecompForImage (courbe croisee nommee, ou refus en tete) reste : l ecriture suivante n applique pas la
    # courbe propre que la calibration vient de mesurer ; ligne de journal qui le dit. Avant : libelle « Profil ... calibre
    # ... (bouton Courbe) » a la place, refus du lecteur cible compris, et « applique par le mode Auto a toute image »
    $tgtC = if ($cal.Cross -or $null -eq $script:TargetDrives) { '' } else { [string](Get-TargetDrive ([string]$cal.Drive)) }
    if ($tgtC -and (Get-TargetWriteInfo $txtWFile.Text $cmbWFmt.Text ([bool]$chkWSlow.Checked)).Applies) { $showLbl = $false }
    if ($cal.Cross -and $cal.Slow) {
        # 12.10 : courbes croisees par tete
        $v0 = @($cal.Units[0].Fit.Values); $v1 = @($cal.Units[1].Fit.Values)
        $lblWProfileInfo.Text = $convHead + ((T "Courbes croisées {0} par tête calibrées le {1}, écriture par le lecteur {2} pour le lecteur {3} : tête 0 de {4} à {5} ns, tête 1 de {6} à {7} ns ; courbe propre du lecteur {2} inchangée.") -f "$famTxt", "$date", "$($cal.Cross.Src)", "$($cal.Cross.Tgt)", "$($v0[0])", "$($v0[-1])", "$($v1[0])", "$($v1[-1])")
    } elseif ($cal.Cross) {
        $v = @($cal.Units[0].Fit.Values)
        $lblWProfileInfo.Text = $convHead + ((T "Courbe croisée {0} calibrée le {1}, écriture par le lecteur {2} pour le lecteur {3} : de {4} à {5} ns, une valeur par cylindre ; courbe propre du lecteur {2} inchangée.") -f "$famTxt", "$date", "$($cal.Cross.Src)", "$($cal.Cross.Tgt)", "$($v[0])", "$($v[-1])")
    } elseif ($showLbl -and $cal.Slow) {
        $v0 = @($cal.Units[0].Fit.Values); $v1 = @($cal.Units[1].Fit.Values)
        $lblWProfileInfo.Text = $convHead + ((T "Profils {0} par tête calibrés le {1} sur le lecteur {2} : tête 0 de {3} à {4} ns, tête 1 de {5} à {6} ns, une valeur par cylindre (bouton Courbe).") -f "$famTxt", "$date", "$($cal.Drive)", "$($v0[0])", "$($v0[-1])", "$($v1[0])", "$($v1[-1])")
    } elseif ($showLbl) {
        $v = @($cal.Units[0].Fit.Values)
        $lblWProfileInfo.Text = $convHead + ((T "Profil {0} calibré le {1} sur le lecteur {2} : courbe {3}, de {4} à {5} ns, une valeur par cylindre (bouton Courbe).") -f "$famTxt", "$date", "$($cal.Drive)", (Get-CurveModelName $cal.Units[0].Fit.Model), "$($v[0])", "$($v[-1])")
    }
    if ($convTxt) { $lblWCal.Text = $convHead + $lblWCal.Text }
    foreach ($u in $cal.Units) {
        if ($cal.Cross) { Append-Log ($u.Prefix + ((T "Calibration croisée terminée : courbe {0} {1} → {2} = {3}") -f "$famTxt", "$($cal.Cross.Src)", "$($cal.Cross.Tgt)", "$($u.Profile)")) }   # 12.10
        else { Append-Log ($u.Prefix + ((T "Calibration terminée : profil {0} = {1}") -f "$famTxt", "$($u.Profile)")) }
        $v = @($u.Fit.Values)
        for ($c0 = 0; $c0 -lt $v.Count; $c0 += 10) {
            $hi = [math]::Min($v.Count - 1, $c0 + 9)
            $line = ((T "  Précomp cylindres {0}-{1} : {2} ns") -f "$c0", "$hi", "$((@($v[$c0..$hi])) -join ' ')")
            if ($u.Prefix) { $line = '  ' + $u.Prefix + $line.TrimStart() }
            Append-Log $line
        }
    }
    Append-Log ((T "Courbe obtenue avec le calcul de calibration v{0}.") -f "$(if ([string]$cal.Family -eq 'hd') { $script:CalibCalcHd } else { $script:CalibCalc })")
    if ($cal.Cross) {
        # 12.10 : bilan de la calibration croisee : cle de magasin, echanges de disquette, lecteur ou se trouve la disquette
        Append-Log ((T "Courbe croisée {0} enregistrée dans la configuration (clé « {1}>{2} ») pour les écritures du lecteur {1} destinées au lecteur {2} ; {3} échange(s) de disquette ; la disquette sacrifiée est dans le lecteur {4}.") -f "$famTxt", "$($cal.Cross.Src)", "$($cal.Cross.Tgt)", "$([int]$cal.Swaps)", $(if ([string]$cal.DiskAt -eq 'T') { "$($cal.Cross.Tgt)" } else { "$($cal.Cross.Src)" }))
    }
    elseif ($script:Restore) {
        if ($cal.Slow) { Append-Log ((T "Profils par tête appliqués par le mode Auto en écriture lente à toute image {0} ; ils seront enregistrés dans la configuration à la fin de la restauration.") -f "$famTxt") }
        else { Append-Log ((T "Profil appliqué par le mode Auto à toute image {0} ; il sera enregistré dans la configuration à la fin de la restauration.") -f "$famTxt") }
    }
    # 12.10 (relecture de la RC, fix1) : famille haute densite : ses ecritures haute densite en profil Auto pour le lecteur
    # cible sont refusees (Get-TargetWriteInfo, BlockKind 'hd' : la calibration croisee n existe qu en double densite),
    # courbe croisee double densite presente ou non ; avant : « appliquent la courbe croisee, et sont refusees sans elle »
    elseif ($tgtC -and [string]$cal.Family -eq 'hd' -and $cal.Slow) { Append-Log ((T "Profils par tête enregistrés dans la configuration et appliqués par le mode Auto en écriture lente à toute image {0} écrite par le lecteur {1} sans lecteur cible ; lecteur cible {2} choisi pour le lecteur {1} : ses écritures haute densité en profil Auto sont refusées, la calibration croisée n'existant qu'en double densité (liste « Lecteur cible » de l'onglet Écriture).") -f "$famTxt", "$($cal.Drive)", "$tgtC") }
    elseif ($tgtC -and [string]$cal.Family -eq 'hd') { Append-Log ((T "Profil enregistré dans la configuration et appliqué par le mode Auto à toute image {0} écrite par le lecteur {1} sans lecteur cible ; lecteur cible {2} choisi pour le lecteur {1} : ses écritures haute densité en profil Auto sont refusées, la calibration croisée n'existant qu'en double densité (liste « Lecteur cible » de l'onglet Écriture).") -f "$famTxt", "$($cal.Drive)", "$tgtC") }
    elseif ($tgtC -and $cal.Slow) { Append-Log ((T "Profils par tête enregistrés dans la configuration et appliqués par le mode Auto en écriture lente à toute image {0} écrite par le lecteur {1} sans lecteur cible ; lecteur cible {2} choisi pour le lecteur {1} : ses écritures précompensées appliquent la courbe croisée {1} → {2}, et sont refusées sans elle (liste « Lecteur cible » de l'onglet Écriture).") -f "$famTxt", "$($cal.Drive)", "$tgtC") }
    elseif ($tgtC) { Append-Log ((T "Profil enregistré dans la configuration et appliqué par le mode Auto à toute image {0} écrite par le lecteur {1} sans lecteur cible ; lecteur cible {2} choisi pour le lecteur {1} : ses écritures précompensées appliquent la courbe croisée {1} → {2}, et sont refusées sans elle (liste « Lecteur cible » de l'onglet Écriture).") -f "$famTxt", "$($cal.Drive)", "$tgtC") }
    elseif ($cal.Slow) { Append-Log ((T "Profils par tête enregistrés dans la configuration et appliqués par le mode Auto en écriture lente à toute image {0}.") -f "$famTxt") }
    else { Append-Log ((T "Profil enregistré dans la configuration et appliqué par le mode Auto à toute image {0}.") -f "$famTxt") }
    if (-not $script:Restore) { [void](Save-Config) }      # restauration : enregistree par Close-Restore, onglet Ecriture retabli
    # 12.7 : fin de la calibration B : comparaison avec la courbe A et choix, meme sans reserve
    if ($script:CalRedo -and $script:CalRedo.Stage -eq 'running') { Complete-CalibRedo $cal @($issues) @($kinds) $prevCal; return }
    if ($issues.Count -gt 0) {
        # Resultat douteux : courbe montree, l utilisateur choisit de continuer (ecrire, ou conserver la courbe), d arreter
        # (calibration precedente retablie) ou, pour une reserve qui peut venir du support, de refaire la calibration sur une
        # autre disquette (Start-CalibRedo). Restauration : sequence occupee pendant la fenetre (chien de garde).
        $toWrite = ($script:AfterCalib -eq 'write')
        Append-Log ((T "Calibration : résultat douteux ({0}) : courbe affichée, décision demandée.") -f ($issues -join ' ; '))
        $offerRedo = Test-CalibRedoOffer ([bool]$script:Restore) ([bool]$script:CalRedo) @($kinds)
        if ($cal.Cross) { $offerRedo = $false }   # 12.10 : pas de calibration B (« Refaire sur une autre disquette ») en croise
        while ($true) {
            if ($script:Restore) { $script:Restore.InCall = $true }
            try { $choice = Show-CalibReview $cal @($issues) $toWrite $false $false $offerRedo $null }
            finally { if ($script:Restore) { $script:Restore.InCall = $false; $script:Restore.Idle = Get-Date } }
            if ($choice -ne 'redo') { break }
            # B lancee : la suite (comparaison, choix) a lieu a la fin de B ; sinon la fenetre de A se rouvre
            if (Start-CalibRedo $cal @($issues) @($kinds) $prevCal $toWrite) { return }
        }
        if ($choice -eq 'stop') {
            Restore-CalibState $prevCal
            $lblWCal.Text = (T 'Calibration abandonnée : la calibration précédente est rétablie.')
            Append-Log (T 'Calibration abandonnée à votre demande : courbe non conservée, calibration précédente rétablie.')
            if ($toWrite) {
                $script:AfterCalib = ''
                Append-Log (T 'Écriture annulée : résultat de calibration refusé.')
                if ($script:Restore) { Stop-Restore (T 'résultat de calibration refusé') }
            }
            Set-HomeProgDone $cal 'abandon' $issues[0]
            return
        }
        Append-Log (T 'Calibration : résultat accepté malgré les réserves.')
    }
    # Accueil : bilan avec reserves aussi apres « Continuer » sur un defaut grossier, sans autre reserve (12.7)
    Set-HomeProgDone $cal $(if ($issues.Count -gt 0 -or $surfIssue) { 'warn' } else { 'ok' }) $(if ($issues.Count -gt 0) { $issues[0] } else { $surfIssue })
    if ($script:AfterCalib -eq 'write') {
        # Ecriture rapide ou lente : l image est ecrite tout de suite avec le profil obtenu (courbe visible par le bouton Courbe)
        $script:AfterCalib = ''
        if ($cal.Swap) {
            # Calibration faite sur une disquette sacrifiee : la disquette a ecrire est redemandee (frmReinsert). 12.8 (D7) :
            # sans compte a rebours : une ecriture lancee seule ne peut pas savoir quelle disquette est dans le lecteur ;
            # restauration : remise sans delai depuis le lot 2, puis nouvelle sonde de la destination avant l ecriture
            if ($script:Restore) { Enter-RestoreSwapBack; return }
            $lrA = if ($cal.LevelAfter) { Get-LevelRef $cal.Family $cal.Slow $cal.Drive $cal.Image $false -NCyl ([int]$cal.MaxCyl + 1) } else { $null }
            if ($lrA -and -not $lrA.Ok) { Append-Log ((T "Calibration rapide impossible : {0}. Écriture avec la nouvelle calibration complète.") -f "$($lrA.Why)") }
            if ($lrA -and $lrA.Ok) {
                # Reference faite sur la disquette sacrifiee : le niveau de la disquette a ecrire est mesure apres sa remise
                $lr = $lrA
                $lc = if ($lr.Ok) { (@($lr.Units | ForEach-Object { Format-CylList ([int[]]@(@(@($_.LCyls) + @($_.Wit) + @($(if ($null -ne $_.Probe) { $_.Probe }))) | Sort-Object -Unique)) } | Sort-Object -Unique)) -join ' ; ' } else { '-' }
                $q = Show-TimedConfirm 'frmReinsert' (T 'Calibration precomp') ((T "Calibration terminée : elle devient la référence de forme du lecteur {0}.`n`nRetirez la disquette sacrifiée et insérez la disquette à écrire, puis cliquez sur « Mesurer le niveau et écrire » : son niveau de précompensation est mesuré sur les cylindres {1} (2 faces, 1 à 3 écritures du motif par piste), puis l'image est écrite.`nAnnuler : l'image n'est pas écrite.") -f "$($cal.Drive)", "$lc") (T 'Mesurer le niveau et écrire') 'Diagnostic' '' '' '' '' -Seconds 0 -Heading (T 'Insérez la disquette à écrire') -Level 'info' -Picto 'data'
                if (-not $q.Ok) { Append-Log (T 'Écriture annulée : la disquette à écrire n''a pas été remise après la calibration.'); return }
                if ($lr.Ok) {
                    $script:AfterCalib = 'write'
                    Start-LevelCalib $lr -NoConfirm -NoFallback
                    if (-not $script:Cal) { $script:AfterCalib = ''; Append-Log (T 'Écriture annulée : la calibration rapide n''a pas été lancée.') }
                    return
                }
            } else {
            $q = Show-TimedConfirm 'frmReinsert' (T 'Calibration precomp') ((T "Calibration terminée.`n`nRetirez la disquette sacrifiée du lecteur {0} et insérez la disquette à écrire, puis cliquez sur « Écrire l'image ».`nAnnuler : l'image n'est pas écrite.") -f "$($cal.Drive)") (T "Écrire l'image") 'Save' '' '' '' '' -Seconds 0 -Heading (T 'Insérez la disquette à écrire') -Level 'info' -Picto 'data'
            if (-not $q.Ok) { Append-Log (T 'Écriture annulée : la disquette à écrire n''a pas été remise après la calibration.'); return }
            }
        }
        Append-Log (T 'Calibration terminée : écriture de l''image avec le profil obtenu.')
        if ($script:Restore) { $script:Restore.InCall = $true }
        # Prechauffage passe pendant la calibration (bouton « Passer le prechauffage ») : pas de second prechauffage
        try { Start-ImageWrite -NoWarmup:([bool]$cal.WarmSkip) } finally { if ($script:Restore) { $script:Restore.InCall = $false; $script:Restore.Idle = Get-Date } }
        if ($script:Restore -and -not ($script:GwProc -and -not $script:GwProc.HasExited) -and $script:Chain.Count -eq 0) { Stop-Restore (T 'l''écriture n''a pas démarré après la calibration, voir le journal') }
        return
    }
    # 12.10 : courbes croisees « source>cible » (Show-CurvesWindow), sinon courbes du lecteur courant
    if ($cal.Cross) { Show-CurvesWindow (Get-DriveFamilyCurves (Get-CalibStoreDrive $cal) $cal.Family $cal.Slow) } else { Show-PrecompCurve $cal.Family $cal.Slow }
}
# ============================== FONCTIONS : MESURE SUR L IMAGE, CALCUL ==========

# 12.8.1 (lot A, spec-1281.md § A et B.2) : calcul de la mesure de la disquette sur l image, sans interface ni texte T().
# Blocs de cylindres et plan en carre latin (A.3, A.4) ; pistes exclues avant l ecriture (IPF) et apres la relecture
# (A.2) ; donnees minimales et facteur k* de chaque tete (effets fixes passe + cylindre, quadratique en k, comme
# revue_sony.Jeu et motif_analyse.py) ; facteur applique a un profil --precomp (A.10, C.3) ; k du lecteur, mediane des
# 3 derniers k* mesures du lecteur, de la famille et de la tete (decision de l utilisateur du 25/10/2026, au lieu du
# dernier de la spec) ; conversions de la configuration (C.5) ; arret « Failed to verify Track » de gw (A.7).
# Constantes en parametres, defauts de 565 (B.4). References executables : v1281\verif_spec1281.py (plan, ajustement)
# et v1281\verif_scaled.py (profils mis a l echelle).
# 12.9 (critique de la phase A, § 3.2) : ajustement « K-ns » (courbure commune en ns, sommet k = besoin / courbe, borne a
# [0 ; 2]) pondere par Huber, optimums par zone de 5 cylindres (idee de l utilisateur), etats de la tete, 4e passe
# adaptative (niveaux 1,6 et 1), memoire par marque (etat 'mesure' seulement, jamais d emprunt), plafonds 5 / 80 / 20,
# relectures gardees (D6). Reference executable : v129\calib\modeles\modele_mesure.py.
# 12.10 : la correction « lecteur cible » Dk (C.4 : valeur par tete et par lecteur, bloc targetCorrection de la
# configuration) est retiree ; une ecriture pour un autre lecteur applique la courbe croisee (140, 220).

function Get-ContentBlocks([int]$nCyl, [int]$nBlocks = 8, [int]$len = 5, [int]$maxCyl = 80, [int]$minBlocks = 4) {
    # Blocs de len cylindres mesures (A.3) : B = floor(min(nCyl, maxCyl) / len) ; B >= nBlocks : blocs
    # floor(i (B - 1) / (nBlocks - 1) + 1/2), i = 0..nBlocks-1 (les deux bords et des blocs repartis entre eux) ;
    # minBlocks <= B < nBlocks : tous ; moins : image non mesurable (Ok = $false). Cylindres maxCyl et au-dela jamais
    # mesures (pistes vides de l IPF, courbe V prolongee). Cyls : cylindres des blocs, dans l ordre des blocs
    if ($len -le 0 -or $nBlocks -le 0) { return @{ Ok = $false; Idx = [int[]]@(); Cyls = [int[]]@() } }
    $nb = [int][math]::Floor([math]::Min($nCyl, $maxCyl) / [double]$len)
    if ($nb -lt [math]::Max(1, $minBlocks)) { return @{ Ok = $false; Idx = [int[]]@(); Cyls = [int[]]@() } }
    if ($nb -ge $nBlocks -and $nBlocks -ge 2) { $idx = @(0..($nBlocks - 1) | ForEach-Object { [int][math]::Floor($_ * ($nb - 1) / [double]($nBlocks - 1) + 0.5) } | Sort-Object -Unique) }
    elseif ($nb -ge $nBlocks) { $idx = @(0) }
    else { $idx = @(0..($nb - 1)) }
    $cyls = foreach ($b in $idx) { for ($j = 0; $j -lt $len; $j++) { $len * $b + $j } }
    return @{ Ok = $true; Idx = [int[]]$idx; Cyls = [int[]]@($cyls) }
}

function Get-ContentLevel([int]$b, [int]$p, [double[]]$levels) {
    # Niveau k du bloc de rang b (0..B-1) a la passe p (0..2) : carre latin, chaque bloc recoit chaque niveau une fois et
    # deux blocs voisins n ont jamais le meme niveau a une passe
    return [double]$levels[($b + $p) % $levels.Count]
}

function Get-ContentPlan([int[]]$v0, [int[]]$v1, [int]$nCyl, [double[]]$levels, [int]$hard, $preSkip = @{}) {
    # Plan de la mesure (A.4), meme plan pour les deux tetes : passe p (une par niveau), tete h, cylindres de la tete (sans
    # les cles 'c.h' de $preSkip), niveau du bloc levels[(rang + p) mod n] et valeur ecrite w = max(0, min(hard,
    # round(k x V_h(c)))) (arrondi au pair), V bornee a 0..hard (comme Get-LevelRef ; au-dela de la courbe, sa derniere
    # valeur) ; Spec : profil --precomp de la passe et de la tete (Get-BracketSpec : entrees c=w triees, jointes par :).
    # NCylHead : cylindres ecrits par tete a chaque passe
    $bl = Get-ContentBlocks $nCyl
    $lv = [double[]]@($levels)
    $vs = @{ 0 = [int[]]@($v0); 1 = [int[]]@($v1) }
    if (-not $bl.Ok -or $lv.Count -eq 0 -or $vs[0].Count -eq 0 -or $vs[1].Count -eq 0) { return @{ Ok = $false; Blocks = $bl.Idx; Cyls = $bl.Cyls; Levels = $lv; Pass = @(); NCylHead = @{ 0 = 0; 1 = 0 } } }
    if ($null -eq $preSkip) { $preSkip = @{} }
    $len = [int]($bl.Cyls.Count / $bl.Idx.Count)
    $passes = @(); $nh = @{ 0 = 0; 1 = 0 }
    for ($p = 0; $p -lt $lv.Count; $p++) {
        $hh = @{}
        foreach ($h in 0, 1) {
            $v = $vs[$h]; $cs = New-Object 'System.Collections.Generic.List[int]'; $w = @{}; $kk = @{}
            for ($bi = 0; $bi -lt $bl.Idx.Count; $bi++) {
                $k = Get-ContentLevel $bi $p $lv
                for ($j = 0; $j -lt $len; $j++) {
                    $c = [int]$bl.Cyls[$bi * $len + $j]
                    if ($preSkip.Contains("$c.$h")) { continue }
                    $vc = if ($c -lt $v.Count) { $v[$c] } else { $v[$v.Count - 1] }
                    $vc = [math]::Max(0, [math]::Min($hard, $vc))
                    $w[$c] = [int][math]::Max(0.0, [math]::Min([double]$hard, [math]::Round($k * $vc)))
                    $kk[$c] = $k; $cs.Add($c)
                }
            }
            $cyls = [int[]]@($cs | Sort-Object)
            $hh[$h] = @{ Cyls = $cyls; W = $w; K = $kk; Spec = $(if ($cyls.Count) { Get-BracketSpec $w } else { '' }) }
            $nh[$h] = $cyls.Count
        }
        $passes += @{ H = $hh }
    }
    return @{ Ok = $true; Blocks = $bl.Idx; Cyls = $bl.Cyls; Levels = $lv; Pass = $passes; NCylHead = $nh }
}

function Get-IpfTrackInfo([string]$path) {
    # Enregistrements IMGE d un IPF (meme parcours que Get-ImageTrackSet, 150 ; lecture des champs seulement) :
    # 'c.h' -> @{ Bits (trkbits) ; Blocks (blkcnt, 0 = piste vide) ; Den (densite, offset 8 des donnees : 1 bruit, 2 auto,
    # 3 et plus protections Copylock, Speedlock... valeurs a confirmer, spec § H.13) } ; $null : illisible ou sans CAPS
    try {
        $d = [System.IO.File]::ReadAllBytes($path)
        if ($d.Length -lt 12 -or [System.Text.Encoding]::ASCII.GetString($d, 0, 4) -ne 'CAPS') { return $null }
        $info = @{}; $pos = 0
        while ($pos + 12 -le $d.Length) {
            $id = [System.Text.Encoding]::ASCII.GetString($d, $pos, 4); $ln = Get-BE32 $d ($pos + 4)
            if ($ln -lt 12) { break }
            if ($id -eq 'IMGE' -and $pos + 12 + 44 -le $d.Length) {
                $cyl  = Get-BE32 $d ($pos + 12)          # piste (cylindre)
                $side = Get-BE32 $d ($pos + 16)          # face
                $den  = Get-BE32 $d ($pos + 20)          # densite
                $bits = Get-BE32 $d ($pos + 12 + 36)     # bits de la piste
                $blk  = Get-BE32 $d ($pos + 12 + 40)     # nombre de blocs : 0 = piste vide
                if ($cyl -lt 200 -and $side -le 1) { $info["$cyl.$side"] = @{ Bits = [int64]$bits; Blocks = [int64]$blk; Den = [int64]$den } }
            } elseif ($id -eq 'DATA' -and $pos + 16 -le $d.Length) { $ln += Get-BE32 $d ($pos + 12) }
            $pos += $ln
        }
        return $info
    } catch { return $null }
}

function Get-ContentImageSkip([string]$img, [int[]]$cyls) {
    # Pistes des cylindres mesures exclues avant l ecriture (A.2), 'c.h' -> raison : 'absente' (hors de Get-ImageTrackSet :
    # IPF blkcnt ou trkbits nul, cylindre hors de l image), 'longue' (IPF : trkbits > 1,02 x mediane des trkbits de
    # l image, meme rang que Get-IpfCellInfo), 'protegee' (IPF : densite autre que 2, auto). Image sans table de pistes
    # lisible (IMG, ST, DSK...) : aucune exclusion, gw encode lui-meme du MFM standard
    $skip = @{}
    $set = Get-ImageTrackSet $img
    $ipf = $null; $med = 0
    if ([System.IO.Path]::GetExtension($img).ToLower() -eq '.ipf') {
        $ipf = Get-IpfTrackInfo $img
        if ($ipf) {
            $bs = @($ipf.Values | Where-Object { $_.Blocks -gt 0 -and $_.Bits -gt 0 } | ForEach-Object { [int64]$_.Bits } | Sort-Object)
            if ($bs.Count) { $med = [int64]$bs[[int]($bs.Count / 2)] }
        }
    }
    foreach ($c in @($cyls)) {
        foreach ($h in 0, 1) {
            $key = "$c.$h"
            if ($set -and -not $set.ContainsKey($key)) { $skip[$key] = 'absente'; continue }
            if ($ipf -and $ipf.ContainsKey($key)) {
                $r = $ipf[$key]
                if ($r.Blocks -le 0 -or $r.Bits -le 0) { $skip[$key] = 'absente' }
                elseif ($med -gt 0 -and $r.Bits -gt 1.02 * $med) { $skip[$key] = 'longue' }
                elseif ($r.Den -ne 2) { $skip[$key] = 'protegee' }
            }
        }
    }
    return $skip
}

function Get-ContentExclusions($obs, [double]$zMax = 5e-4, [double]$cellsTol = 0.02, [double]$fluxMin = 0.5) {
    # Pistes exclues apres la relecture (A.2), pour toute la mesure (aux 3 niveaux), 'c.h' -> raison, d apres les lectures
    # de la piste aux passes ($obs : @{ C ; H ; P ; NRev ; N ; Z ; Cells ; Flux }) ; medianes prises sur toutes les lectures
    # a tour exploitable de la mesure :
    #  - 'vide' : aucune lecture a tour exploitable, ou intervalles moyens par tour sous fluxMin x la mediane a CHAQUE
    #    lecture (piste effacee ou non formatee) ;
    #  - 'longueur' : mediane des cellules par tour de la piste hors de [1 - cellsTol ; 1 + cellsTol] x la mediane ;
    #  - 'nonmfm' : MINIMUM sur les lectures de Z/N au-dessus de zMax (une piste mal ecrite a un seul niveau reste dans
    #    la mesure : sa marge basse est l information cherchee).
    $per = [ordered]@{}
    $fl = New-Object 'System.Collections.Generic.List[double]'; $ce = New-Object 'System.Collections.Generic.List[double]'
    foreach ($o in $obs) {
        if ($null -eq $o) { continue }
        $key = "$([int]$o.C).$([int]$o.H)"
        if (-not $per.Contains($key)) { $per[$key] = New-Object 'System.Collections.Generic.List[object]' }
        $fx = @($o.Flux | Where-Object { $null -ne $_ }); $cx = @($o.Cells | Where-Object { $null -ne $_ })
        if ([int]$o.NRev -gt 0 -and [double]$o.N -gt 0 -and $fx.Count -gt 0 -and $cx.Count -gt 0) {
            $f = 0.0; foreach ($x in $fx) { $f += [double]$x }; $f /= $fx.Count
            $mc = Get-Median $cx
            $per[$key].Add(@{ Flux = $f; Cells = $mc; ZFrac = [double]$o.Z / [double]$o.N })
            $fl.Add($f); $ce.Add($mc)
        }
    }
    $mFlux = Get-Median $fl; $mCells = Get-Median $ce
    $ex = @{}
    foreach ($key in $per.Keys) {
        $rs = $per[$key]
        if ($rs.Count -eq 0) { $ex[$key] = 'vide'; continue }
        $fMax = 0.0; $zMin = [double]::PositiveInfinity; $cs = @()
        foreach ($r in $rs) { if ($r.Flux -gt $fMax) { $fMax = $r.Flux }; if ($r.ZFrac -lt $zMin) { $zMin = $r.ZFrac }; $cs += $r.Cells }
        if ($fMax -lt $fluxMin * $mFlux) { $ex[$key] = 'vide' }
        elseif ($mCells -gt 0 -and [math]::Abs((Get-Median $cs) / $mCells - 1.0) -gt $cellsTol) { $ex[$key] = 'longueur' }
        elseif ($zMin -gt $zMax) { $ex[$key] = 'nonmfm' }
    }
    return $ex
}

function Get-ContentHeadCheck($rows, [int]$minCyl = 20, [int]$minLevelCyl = 6) {
    # Donnees minimales d une tete (A.2), lignes retenues @{ P ; C ; K ; Y } : au moins minCyl cylindres a 2 lectures ou
    # plus ('peu' sinon) ; parmi eux, 3 niveaux au moins (la quadratique en k en demande 3) sur minLevelCyl cylindres
    # chacun ('niveaux' sinon). 12.9 (synthese C, D2) : un niveau moins represente (4e passe tronquee par un arret de gw)
    # reste dans l ajustement sans le faire refuser
    $byC = @{}
    foreach ($r in $rows) {
        if ($null -eq $r) { continue }
        $c = [int]$r.C
        if (-not $byC.ContainsKey($c)) { $byC[$c] = New-Object 'System.Collections.Generic.List[object]' }
        $byC[$c].Add($r)
    }
    $cs = @($byC.Keys | Where-Object { $byC[$_].Count -ge 2 })
    if ($cs.Count -lt $minCyl) { return @{ Ok = $false; NCyl = $cs.Count; Why = 'peu' } }
    $lv = @{}
    foreach ($c in $cs) { foreach ($k in @($byC[$c] | ForEach-Object { [int64][math]::Round([double]$_.K * 1e6) } | Sort-Object -Unique)) { $lv[$k] = 1 + [int]$lv[$k] } }
    if (@($lv.Values | Where-Object { $_ -ge $minLevelCyl }).Count -lt 3) { return @{ Ok = $false; NCyl = $cs.Count; Why = 'niveaux' } }
    return @{ Ok = $true; NCyl = $cs.Count; Why = '' }
}

function Get-ContentFeFit($rows, [string]$mode = 'K', $w = $null, $zones = $null, [int]$zoneLen = 5) {
    # 12.9 (critique § 3.2, reference modele_mesure.fit_fe) : y = a_passe + g_cylindre + somme b_j f_j + e, moindres carres
    # ponderes par $w (un poids par ligne, $null : 1), sur les lignes @{ P ; C ; W ; V ; Y } (W : precomp ecrite, V : courbe
    # du lecteur, ns). Passes en indicatrices dans l ordre de premiere apparition (la premiere en reference) ; cylindre
    # absorbe exactement (colonnes et y centres dans le cylindre par moyenne ponderee ; cylindre a moins de 2 lignes ou de
    # poids nul ignore). Regresseurs : mode 'K' W^2 et V W ; mode 'U' (idee de l utilisateur) W^2 puis W x 1(zone z) pour
    # chaque zone de zoneLen cylindres ($zones : numeros floor(C / zoneLen), tous ceux des lignes par defaut). Rend Ok, Why
    # ('vide', 'niveaux', 'singulier', 'ddl'), B (coefficients des regresseurs), Cov (s^2 G^-1 des regresseurs), S, Df, N
    # (lignes de poids non nul), NCyl, Res (residus centres, non ponderes) et Idx (lignes correspondantes), PassEff, Zones
    $rs = @($rows | Where-Object { $null -ne $_ })
    $nan = [double]::NaN
    $out = @{ Ok = $false; Why = ''; B = [double[]]@(); Cov = $null; S = $nan; Df = 0; N = 0; NCyl = 0; Res = [double[]]@(); Idx = [int[]]@(); PassEff = @{}; Zones = [int[]]@() }
    if ($rs.Count -eq 0) { $out.Why = 'vide'; return $out }
    if ($zoneLen -le 0) { $zoneLen = 5 }
    $zs = [int[]]@()
    if ($mode -eq 'U') {
        if ($null -eq $zones) { $zs = [int[]]@($rs | ForEach-Object { [int][math]::Floor([int]$_.C / [double]$zoneLen) } | Sort-Object -Unique) } else { $zs = [int[]]@($zones) }
    }
    $out.Zones = $zs
    $passes = New-Object 'System.Collections.Generic.List[string]'
    foreach ($r in $rs) { $p = [string]$r.P; if (-not $passes.Contains($p)) { $passes.Add($p) } }
    $np = $passes.Count
    $nf = if ($mode -eq 'U') { 1 + $zs.Count } else { 2 }
    $q = $np - 1 + $nf; $nr = $rs.Count
    # Noms distincts sans tenir compte de la casse (variables PowerShell) : $Xm (lignes), $xw (precomp ecrite)
    $Xm = New-Object 'double[][]' $nr; $Yv = New-Object double[] $nr; $wt = New-Object double[] $nr
    for ($i = 0; $i -lt $nr; $i++) {
        $r = $rs[$i]; $row = New-Object double[] $q
        for ($j = 1; $j -lt $np; $j++) { if ([string]$r.P -eq $passes[$j]) { $row[$j - 1] = 1.0 } }
        $xw = [double]$r.W
        $row[$np - 1] = $xw * $xw
        if ($mode -eq 'U') { $zi = [array]::IndexOf($zs, [int][math]::Floor([int]$r.C / [double]$zoneLen)); if ($zi -ge 0) { $row[$np + $zi] = $xw } }
        else { $row[$np] = [double]$r.V * $xw }
        $Xm[$i] = $row; $Yv[$i] = [double]$r.Y
        $wt[$i] = if ($null -eq $w) { 1.0 } else { [double]$w[$i] }
    }
    $byC = @{}
    for ($i = 0; $i -lt $nr; $i++) { $c = [int]$rs[$i].C; if (-not $byC.ContainsKey($c)) { $byC[$c] = New-Object 'System.Collections.Generic.List[int]' }; $byC[$c].Add($i) }
    $Gm = New-Object 'double[][]' $q; for ($i = 0; $i -lt $q; $i++) { $Gm[$i] = New-Object double[] $q }
    $gv = New-Object double[] $q; $n = 0; $ncyl = 0
    $zl = New-Object 'System.Collections.Generic.List[object]'
    foreach ($c in @($byC.Keys | Sort-Object)) {
        $ix = $byC[$c]; $sw = 0.0; foreach ($i in $ix) { $sw += $wt[$i] }
        if ($ix.Count -lt 2 -or $sw -le 0) { continue }
        $ncyl++
        $mx = New-Object double[] $q; $my = 0.0
        for ($j = 0; $j -lt $q; $j++) { $sx = 0.0; foreach ($i in $ix) { $sx += $wt[$i] * $Xm[$i][$j] }; $mx[$j] = $sx / $sw }
        foreach ($i in $ix) { $my += $wt[$i] * $Yv[$i] }; $my /= $sw
        foreach ($i in $ix) {
            $wk = $wt[$i]; $zr = New-Object double[] $q
            for ($j = 0; $j -lt $q; $j++) { $zr[$j] = $Xm[$i][$j] - $mx[$j] }
            $zy = $Yv[$i] - $my
            $zl.Add(@{ I = $i; Z = $zr; Zy = $zy; Wk = $wk })
            if ($wk -gt 0) { $n++ }
            for ($a = 0; $a -lt $q; $a++) {
                if ($zr[$a] -eq 0) { continue }
                $gv[$a] += $wk * $zr[$a] * $zy; $za = $wk * $zr[$a]; $ga = $Gm[$a]
                for ($b = 0; $b -lt $q; $b++) { $ga[$b] += $za * $zr[$b] }
            }
        }
    }
    $out.N = $n; $out.NCyl = $ncyl
    $keep = [int[]]@(0..($q - 1) | Where-Object { $Gm[$_][$_] -gt 1e-9 })
    for ($j = $np - 1; $j -lt $q; $j++) { if ($keep -notcontains $j) { $out.Why = 'niveaux'; return $out } }
    $nk = $keep.Count
    $Gkm = New-Object 'double[][]' $nk; $gkv = New-Object double[] $nk
    for ($i = 0; $i -lt $nk; $i++) { $Gkm[$i] = New-Object double[] $nk; for ($j = 0; $j -lt $nk; $j++) { $Gkm[$i][$j] = $Gm[$keep[$i]][$keep[$j]] }; $gkv[$i] = $gv[$keep[$i]] }
    $sol = Solve-ContentLinear $Gkm $gkv
    if ($null -eq $sol) { $out.Why = 'singulier'; return $out }
    $beta = New-Object double[] $q
    for ($i = 0; $i -lt $nk; $i++) { $beta[$keep[$i]] = $sol[$i] }
    $ssr = 0.0; $res = New-Object double[] $zl.Count; $idx = New-Object int[] $zl.Count
    for ($t = 0; $t -lt $zl.Count; $t++) {
        $e = $zl[$t]; $rv = [double]$e.Zy
        for ($j = 0; $j -lt $q; $j++) { $rv -= $e.Z[$j] * $beta[$j] }
        $res[$t] = $rv; $idx[$t] = [int]$e.I; $ssr += [double]$e.Wk * $rv * $rv
    }
    $df = $n - $ncyl - $nk
    if ($df -le 0) { $out.Why = 'ddl'; return $out }
    $s2 = $ssr / $df
    $inv = New-Object 'double[][]' $nk; for ($i = 0; $i -lt $nk; $i++) { $inv[$i] = New-Object double[] $nk }
    for ($j = 0; $j -lt $nk; $j++) {
        $ej = New-Object double[] $nk; $ej[$j] = 1.0
        $col = Solve-ContentLinear $Gkm $ej
        if ($null -eq $col) { $out.Why = 'singulier'; return $out }
        for ($i = 0; $i -lt $nk; $i++) { $inv[$i][$j] = $col[$i] }
    }
    # Regresseurs (tous gardes) : positions $np - 1 .. $q - 1 dans $keep
    $fp = [int[]]@(for ($j = $np - 1; $j -lt $q; $j++) { [array]::IndexOf($keep, $j) })
    $cov = New-Object 'double[][]' $nf
    for ($i = 0; $i -lt $nf; $i++) { $cov[$i] = New-Object double[] $nf; for ($j = 0; $j -lt $nf; $j++) { $cov[$i][$j] = $s2 * $inv[$fp[$i]][$fp[$j]] } }
    $pe = @{ ([string]$passes[0]) = 0.0 }; for ($i = 1; $i -lt $np; $i++) { $pe[[string]$passes[$i]] = $beta[$i - 1] }
    $out.Ok = $true; $out.B = [double[]]@(for ($j = $np - 1; $j -lt $q; $j++) { $beta[$j] }); $out.Cov = $cov
    $out.S = [math]::Sqrt([math]::Max($s2, 0.0)); $out.Df = $df; $out.Res = $res; $out.Idx = $idx; $out.PassEff = $pe
    return $out
}

function Get-ContentMad($v) {
    # Ecart absolu median ramene a un ecart-type (1,4826 x MAD, loi normale) ; 0 sans valeur
    $a = @($v | Where-Object { $null -ne $_ } | ForEach-Object { [double]$_ })
    if ($a.Count -eq 0) { return 0.0 }
    $m = [double](Get-Median $a)
    return 1.4826 * [double](Get-Median @($a | ForEach-Object { [math]::Abs($_ - $m) }))
}

function Get-ContentHuberWeights($rows) {
    # 12.9 (D4, critique § 3.2, reference modele_mesure.poids_robustes) : poids de Huber des lignes d une tete, par
    # moindres carres ponderes iteres sur le modele 'K' (Get-ContentFeFit) : residu centre corrige du centrage dans le
    # cylindre (x racine(m / (m - 1)), m lignes du cylindre), sigma = 1,4826 x MAD des residus, poids min(1, c / |z|),
    # c = ContentHuberC (1,345) ; au plus ContentHuberIt iterations (10), arret quand les poids varient de moins de 1e-4.
    # Ajustement impossible ou sigma nul : poids de l iteration precedente (1 au depart). Rend un double[] aligne sur $rows
    $rs = @($rows | Where-Object { $null -ne $_ })
    $hc = if ([double]$script:ContentHuberC -gt 0) { [double]$script:ContentHuberC } else { 1.345 }
    $nIt = if ([int]$script:ContentHuberIt -gt 0) { [int]$script:ContentHuberIt } else { 10 }
    $nr = $rs.Count
    $wv = New-Object double[] $nr; for ($i = 0; $i -lt $nr; $i++) { $wv[$i] = 1.0 }
    $mc = @{}; foreach ($r in $rs) { $c = [int]$r.C; $mc[$c] = 1 + [int]$mc[$c] }
    for ($it = 0; $it -lt $nIt; $it++) {
        $fit = Get-ContentFeFit $rs 'K' $(if ($it -gt 0) { $wv } else { $null })
        if (-not $fit.Ok) { return ,$wv }
        $sc = New-Object double[] $fit.Idx.Count
        for ($t = 0; $t -lt $fit.Idx.Count; $t++) {
            $m = [int]$mc[[int]$rs[$fit.Idx[$t]].C]; $rv = [double]$fit.Res[$t]
            if ($m -gt 1) { $rv *= [math]::Sqrt($m / ($m - 1.0)) }
            $sc[$t] = $rv
        }
        $sig = Get-ContentMad $sc
        if (-not ($sig -gt 0)) { return ,$wv }
        $nw = New-Object double[] $nr; for ($i = 0; $i -lt $nr; $i++) { $nw[$i] = 1.0 }
        for ($t = 0; $t -lt $fit.Idx.Count; $t++) { $zz = [math]::Abs($sc[$t]) / $sig; $nw[$fit.Idx[$t]] = $(if ($zz -le $hc) { 1.0 } else { $hc / $zz }) }
        $dm = 0.0; for ($i = 0; $i -lt $nr; $i++) { $d = [math]::Abs($wv[$i] - $nw[$i]); if ($d -gt $dm) { $dm = $d } }
        $wv = $nw
        if ($dm -lt 1e-4) { break }
    }
    return ,$wv
}

function Get-ContentFactorNs($rows, $w = $null, [double]$kMax = 0, [int]$zoneLen = 5) {
    # 12.9 (modele « K-ns », critique § 3.2, reference modele_mesure.profil_tete) : y = a_passe + g_cylindre - Q (W - k V)^2,
    # soit les regresseurs W^2 (b0) et V W (b1) ; Q = -b0 (courbure commune en ns, ns^-1), k = -b1 / (2 b0) si Q > 0 (NaN
    # sinon), SeMod par la methode delta (dk/db0 = b1 / (2 b0^2), dk/db1 = -1 / (2 b0)), TQ = Q / se(Q). Idee de
    # l utilisateur (variante U) : courbure commune et terme propre a chaque zone de zoneLen cylindres, optimum x*_z = b_z /
    # 2Q (ns, methode delta), puis droite x* = k V par l origine, ponderee par 1 / max(var, 1 ns^2) (optimums hors de
    # -400..800 ns ecartes ; 2 zones au moins), variance x max(1, chi2 / ddl) : SeU, Chi2Ddl, KZones, Zones (@{ Z ; Cyl ; V
    # (moyenne de la zone) ; X ; SeX ; K = X / V ; Se = SeX / V }, vide si la variante echoue). SeK = max(SeMod, SeU).
    # $w : poids de Huber (Get-ContentHuberWeights) ; NPond : lignes de poids < 1 ; Low / NLow : lignes de poids <
    # ContentLowWeight (0,5), @{ C ; P ; W } par cylindre et passe. Etat : Get-ContentHeadState
    if (-not ($kMax -gt 0)) { $kMax = if ([double]$script:ContentKMax -gt 0) { [double]$script:ContentKMax } else { 2.0 } }
    if ($zoneLen -le 0) { $zoneLen = 5 }
    $nan = [double]::NaN
    $rs = @($rows | Where-Object { $null -ne $_ })
    $out = @{ Ok = $false; Why = ''; K = $nan; SeK = $nan; SeMod = $nan; SeU = $nan; Q = $nan; SeQ = $nan; TQ = $nan; S = $nan; Chi2Ddl = $nan; KZones = $nan
              Zones = @(); N = 0; NCyl = 0; NPond = 0; NLow = 0; Low = @(); Etat = 'echec'; PassEff = @{} }
    $lowW = if ([double]$script:ContentLowWeight -gt 0) { [double]$script:ContentLowWeight } else { 0.5 }
    if ($null -ne $w) {
        $low = @()
        for ($i = 0; $i -lt $rs.Count; $i++) {
            $wi = [double]$w[$i]
            if ($wi -lt 1.0 -and $wi -gt 0) { $out.NPond++ }
            if ($wi -lt $lowW) { $low += ,@{ C = [int]$rs[$i].C; P = [string]$rs[$i].P; W = $wi } }
        }
        $out.Low = @($low | Sort-Object { [int]$_.C }, { [string]$_.P }); $out.NLow = $low.Count
    }
    $fit = Get-ContentFeFit $rs 'K' $w
    if (-not $fit.Ok) { $out.Why = [string]$fit.Why; return $out }
    $b0 = [double]$fit.B[0]; $b1 = [double]$fit.B[1]; $cv = $fit.Cov
    $qq = -$b0; $seQ = [math]::Sqrt([math]::Max([double]$cv[0][0], 0.0))
    $k = $nan; $seMod = $nan
    if ($qq -gt 0) {
        $k = $b1 / (2.0 * $qq)
        $g0 = $b1 / (2.0 * $b0 * $b0); $g1 = -1.0 / (2.0 * $b0)
        $seMod = [math]::Sqrt([math]::Max(0.0, $g0 * $g0 * $cv[0][0] + $g1 * $g1 * $cv[1][1] + 2.0 * $g0 * $g1 * $cv[0][1]))
    }
    $out.Ok = $true; $out.K = $k; $out.SeMod = $seMod; $out.Q = $qq; $out.SeQ = $seQ; $out.TQ = $(if ($seQ -gt 0) { $qq / $seQ } else { $nan })
    $out.S = [double]$fit.S; $out.N = [int]$fit.N; $out.NCyl = [int]$fit.NCyl; $out.PassEff = $fit.PassEff
    # Variante U : optimums par zone, puis droite par l origine
    # Synthese C (D1) : zones identifiables seulement (un cylindre au moins ecrit a 2 precomp distinctes) : une zone sans
    # variation de W (courbe nulle, cylindres lus une seule fois) ne fait plus echouer toute la variante U
    $byCW = @{}; foreach ($ru in $rs) { $cc = [int]$ru.C; if (-not $byCW.ContainsKey($cc)) { $byCW[$cc] = @{} }; $byCW[$cc][[int]$ru.W] = $true }
    $zid = @{}; foreach ($cc in @($byCW.Keys)) { if ($byCW[$cc].Count -ge 2) { $zid[[int][math]::Floor($cc / [double]$zoneLen)] = $true } }
    $fu = Get-ContentFeFit $rs 'U' $w ([int[]]@($zid.Keys | Sort-Object)) $zoneLen
    $seU = $nan
    if ($fu.Ok) {
        $bq = [double]$fu.B[0]; $cu = $fu.Cov
        $zl = @(); $pts = @()
        for ($iz = 0; $iz -lt $fu.Zones.Count; $iz++) {
            $z = [int]$fu.Zones[$iz]
            $vz = @($rs | Where-Object { [int][math]::Floor([int]$_.C / [double]$zoneLen) -eq $z } | ForEach-Object { [double]$_.V })
            $vm = 0.0; foreach ($v in $vz) { $vm += $v }; if ($vz.Count) { $vm /= $vz.Count }
            $bz = [double]$fu.B[1 + $iz]; $xs = $nan; $vx = $nan
            if ($bq -lt 0) {
                $xs = $bz / (-2.0 * $bq)
                $h0 = $bz / (2.0 * $bq * $bq); $h1 = -1.0 / (2.0 * $bq)
                $vx = [math]::Max(0.0, $h0 * $h0 * $cu[0][0] + $h1 * $h1 * $cu[1 + $iz][1 + $iz] + 2.0 * $h0 * $h1 * $cu[0][1 + $iz])
            }
            $sx = if ([double]::IsNaN($vx)) { $nan } else { [math]::Sqrt($vx) }
            $zl += ,@{ Z = $z; Cyl = "$($z * $zoneLen)-$($z * $zoneLen + $zoneLen - 1)"; V = $vm; X = $xs; SeX = $sx
                       K = $(if ($vm -gt 0) { $xs / $vm } else { $nan }); Se = $(if ($vm -gt 0) { $sx / $vm } else { $nan }) }
            if (-not [double]::IsNaN($xs) -and -not [double]::IsNaN($vx) -and $vx -gt 0 -and $xs -ge -400 -and $xs -le 800) { $pts += ,@{ V = $vm; X = $xs; Var = $vx } }
        }
        if ($pts.Count -ge 2) {
            $sa = 0.0; $sb = 0.0
            foreach ($pt in $pts) { $pw = 1.0 / [math]::Max([double]$pt.Var, 1.0); $sa += $pw * $pt.V * $pt.V; $sb += $pw * $pt.V * $pt.X }
            if ([math]::Abs($sa) -ge 1e-12) {
                $kU = $sb / $sa; $chi = 0.0
                foreach ($pt in $pts) { $pw = 1.0 / [math]::Max([double]$pt.Var, 1.0); $dd = $pt.X - $kU * $pt.V; $chi += $pw * $dd * $dd }
                $ddl = $pts.Count - 1
                $scl = if ($ddl -gt 0) { [math]::Max(1.0, $chi / $ddl) } else { 1.0 }
                $seU = [math]::Sqrt([math]::Max($scl / $sa, 0.0))
                $out.KZones = $kU; $out.Chi2Ddl = $(if ($ddl -gt 0) { $chi / $ddl } else { $nan }); $out.Zones = $zl
            }
        }
    }
    $out.SeU = $seU
    $out.SeK = if ([double]::IsNaN($seU)) { $seMod } else { [math]::Max($seMod, $seU) }
    $out.Etat = Get-ContentHeadState $out $kMax
    return $out
}

function Get-ContentHeadState($fit, [double]$kMax = 0) {
    # 12.9 (critique § 3.2.4) : etat d une tete apres Get-ContentFactorNs : 'echec' (ajustement impossible), 'plate' (Q <= 0,
    # k NaN ou TQ < ContentFlatT, 2 : critere de Fieller, l intervalle de k n est pas borne), 'peu' (SeK > ContentSeKMax,
    # 0,25), 'haute' (k > kMax, 2), 'basse' (k < 0), sinon 'mesure'
    if (-not ($kMax -gt 0)) { $kMax = if ([double]$script:ContentKMax -gt 0) { [double]$script:ContentKMax } else { 2.0 } }
    if (-not $fit -or -not $fit.Ok) { return 'echec' }
    $ft = if ([double]$script:ContentFlatT -gt 0) { [double]$script:ContentFlatT } else { 2.0 }
    $sm = if ([double]$script:ContentSeKMax -gt 0) { [double]$script:ContentSeKMax } else { 0.25 }
    $k = [double]$fit.K
    if (-not ([double]$fit.TQ -ge $ft) -or -not ([double]$fit.Q -gt 0) -or [double]::IsNaN($k)) { return 'plate' }
    if (-not ([double]$fit.SeK -le $sm)) { return 'peu' }
    if ($k -gt $kMax) { return 'haute' }
    if ($k -lt 0) { return 'basse' }
    return 'mesure'
}

function Get-ContentAppliedK([string]$etat, [double]$k, $memK = $null, [double]$kMax = 0) {
    # 12.9 : facteur applique a une tete selon son etat : k borne a [0 ; kMax] ('mesure', 'haute', 'basse' ; Src 'mesure') ;
    # sinon k memorise du lecteur pour la marque ($memK, Get-DriveK ; Src 'lecteur'), a defaut 1 (Src 'defaut')
    if (-not ($kMax -gt 0)) { $kMax = if ([double]$script:ContentKMax -gt 0) { [double]$script:ContentKMax } else { 2.0 } }
    if (@('mesure', 'haute', 'basse') -contains $etat -and -not [double]::IsNaN($k)) { return @{ K = [math]::Min([math]::Max($k, 0.0), $kMax); Src = 'mesure' } }
    $m = ConvertTo-FiniteOrNull $memK
    if ($null -ne $m) { return @{ K = [double]$m; Src = 'lecteur' } }
    return @{ K = 1.0; Src = 'defaut' }
}

function Get-ContentScaledValues($v, [double]$f, [int]$hard) {
    # Courbe ecrite d une tete : w = round(f x v) (arrondi au pair), au plus max(hard, v), au moins 0 (comme
    # ConvertTo-ScaledSpec) ; enregistrement de mesure et profil des tests
    return ,([int[]]@(foreach ($x in @($v)) { [int][math]::Max(0.0, [math]::Min([math]::Round($f * [double]$x), [double][math]::Max($hard, [int]$x))) }))
}

function Test-ContentNeedFourth($fits, [double]$trigger = 0) {
    # 12.9 (D3, critique § 3.2.5) : 4e passe adaptative apres les 3 premieres : une tete dont l ajustement (Get-ContentFactorNs,
    # $fits : @{ 0 ; 1 }) a un k >= ContentFourthTrigger (0,9) ou pas de sommet (Q <= 0), quel que soit son etat. Tete sans
    # ajustement : non. Rend @{ Need ; Heads (tetes concernees) ; K (tete -> k, NaN sans sommet) }
    if (-not ($trigger -gt 0)) { $trigger = if ([double]$script:ContentFourthTrigger -gt 0) { [double]$script:ContentFourthTrigger } else { 0.9 } }
    $heads = @(); $ks = @{}
    foreach ($h in 0, 1) {
        $f = if ($fits) { $fits[$h] } else { $null }
        if (-not $f -or -not $f.Ok) { continue }
        $k = [double]$f.K
        if (-not ([double]$f.Q -gt 0) -or [double]::IsNaN($k) -or $k -ge $trigger) { $heads += $h; $ks[$h] = $k }
    }
    return @{ Need = ($heads.Count -gt 0); Heads = [int[]]$heads; K = $ks }
}

function Get-ContentFourthPass($plan, [int[]]$v0, [int[]]$v1, [int]$hard, $preSkip = @{}, $levels = $null) {
    # 12.9 (D3, critique § 3.2.6) : 4e passe du plan, memes cylindres que les passes precedentes (blocs du plan, sans les
    # cles 'c.h' de $preSkip), bloc de rang bi au niveau levels[bi mod n] (ContentFourthLevels : 1,6 et 1, alternes : l effet
    # de passe reste identifie par la repetition du niveau 1), valeur ecrite w = max(0, min(hard, round(k x V_h(c)))) comme
    # Get-ContentPlan. Rend la passe @{ H = @{ 0 ; 1 } (Cyls ; W ; K ; Spec) ; BlockK (niveau de chaque bloc) ; NCylHead }
    $lv = if ($null -ne $levels) { [double[]]@($levels) } else { [double[]]@($script:ContentFourthLevels) }
    if ($lv.Count -eq 0) { $lv = [double[]]@(1.6, 1.0) }
    if ($null -eq $preSkip) { $preSkip = @{} }
    $bi0 = @($plan.Blocks); $cy = @($plan.Cyls); $nb = $bi0.Count
    $len = if ($nb -gt 0) { [int]($cy.Count / $nb) } else { 0 }
    $bk = [double[]]@(for ($bi = 0; $bi -lt $nb; $bi++) { $lv[$bi % $lv.Count] })
    $vs = @{ 0 = [int[]]@($v0); 1 = [int[]]@($v1) }
    $hh = @{}; $nh = @{ 0 = 0; 1 = 0 }
    foreach ($h in 0, 1) {
        $v = $vs[$h]; $cs = New-Object 'System.Collections.Generic.List[int]'; $wv = @{}; $kk = @{}
        for ($bi = 0; $bi -lt $nb; $bi++) {
            for ($j = 0; $j -lt $len; $j++) {
                $c = [int]$cy[$bi * $len + $j]
                if ($preSkip.Contains("$c.$h") -or $v.Count -eq 0) { continue }
                $vc = if ($c -lt $v.Count) { $v[$c] } else { $v[$v.Count - 1] }
                $vc = [math]::Max(0, [math]::Min($hard, $vc))
                $wv[$c] = [int][math]::Max(0.0, [math]::Min([double]$hard, [math]::Round($bk[$bi] * $vc)))
                $kk[$c] = $bk[$bi]; $cs.Add($c)
            }
        }
        $cyls = [int[]]@($cs | Sort-Object)
        $hh[$h] = @{ Cyls = $cyls; W = $wv; K = $kk; Spec = $(if ($cyls.Count) { Get-BracketSpec $wv } else { '' }) }
        $nh[$h] = $cyls.Count
    }
    return @{ H = $hh; BlockK = $bk; NCylHead = $nh }
}

function Solve-ContentLinear([double[][]]$a, [double[]]$b) {
    # Systeme a x = b (petit, dense) : elimination de Gauss a pivot partiel puis remontee (port de revue_sony.solve) ;
    # $null si un pivot est inferieur a 1e-10 en valeur absolue. a et b ne sont pas modifies
    $n = $b.Count
    $M = New-Object 'double[][]' $n
    for ($i = 0; $i -lt $n; $i++) { $row = New-Object double[] ($n + 1); for ($j = 0; $j -lt $n; $j++) { $row[$j] = $a[$i][$j] }; $row[$n] = $b[$i]; $M[$i] = $row }
    for ($c = 0; $c -lt $n; $c++) {
        $piv = $c
        for ($r = $c + 1; $r -lt $n; $r++) { if ([math]::Abs($M[$r][$c]) -gt [math]::Abs($M[$piv][$c])) { $piv = $r } }
        if ([math]::Abs($M[$piv][$c]) -lt 1e-10) { return $null }
        $t = $M[$c]; $M[$c] = $M[$piv]; $M[$piv] = $t
        for ($r = $c + 1; $r -lt $n; $r++) {
            $f = $M[$r][$c] / $M[$c][$c]
            for ($k = $c; $k -le $n; $k++) { $M[$r][$k] -= $f * $M[$c][$k] }
        }
    }
    $x = New-Object double[] $n
    for ($c = $n - 1; $c -ge 0; $c--) {
        $s = 0.0; for ($k = $c + 1; $k -lt $n; $k++) { $s += $M[$c][$k] * $x[$k] }
        $x[$c] = ($M[$c][$n] - $s) / $M[$c][$c]
    }
    return ,$x
}

function Limit-WriteFactor([double]$f, [double]$fMax = 0) {
    # Facteur d une ecriture (k) ramene a [0 ; fMax] ; fMax absent ou nul : ContentFMax (plafond unique, 040) ; NaN :
    # 1 (courbe telle quelle). Clamped : valeur changee
    if (-not ($fMax -gt 0)) { $fMax = [double]$script:ContentFMax }
    if ([double]::IsNaN($f)) { return @{ F = 1.0; Clamped = $true } }
    $v = [math]::Min([math]::Max($f, 0.0), $fMax)
    return @{ F = $v; Clamped = ($v -ne $f) }
}

function ConvertTo-ScaledSpec([string]$spec, [double]$f, [int]$hard) {
    # Profil --precomp mis a l echelle (C.3) : chaque entree c=v devient c=w, w = round(f x v) (arrondi au pair), au plus
    # max(hard, v) (une valeur au-dessus de la borne, venue d une mesure complete, n est jamais augmentee), au moins 0 ;
    # cylindres et ordre des entrees gardes, entree illisible gardee telle quelle. f = 1 : $spec rendu tel quel (meme
    # chaine : profils transmis a gw identiques a l octet a ceux de la v12.8)
    if ($f -eq 1.0 -or -not $spec) { return $spec }
    $parts = foreach ($e in ($spec -split ':')) {
        if ($e -match '^\s*(\d+)\s*=\s*(\d+)\s*$') {
            $v = [int]$Matches[2]
            $w = [math]::Max(0.0, [math]::Min([math]::Round($f * $v), [double][math]::Max($hard, $v)))
            "$([int]$Matches[1])=$([int]$w)"
        } else { $e }
    }
    return (@($parts) -join ':')
}

function Get-DriveK([string]$drive, [string]$fam, [int]$h, $brand = $null) {
    # k du lecteur pour une ecriture sans mesure sur l image (C.3 ; decision de l utilisateur du 25/10/2026) : MEDIANE des
    # k* des 3 derniers enregistrements de ce lecteur, de cette famille et de cette tete (date de mesure, ordre d ajout a
    # date egale), de version ContentCalc et de calcul CalibCalc courants ; date de la courbe V non exigee (k garde apres
    # une recalibration du lecteur). Rec : le plus recent ; N : enregistrements retenus (3 au plus), Ks : leurs k*.
    # Sans enregistrement : K = 1, Src 'defaut' (ecriture de la v12.8). Revue 12.8.2 : Old, enregistrements de ce lecteur,
    # de cette famille et de cette tete ecartes parce qu ils viennent d un autre calcul (CalibCalc ou ContentCalc) : textes
    # « mesures faites avec un autre calcul, a refaire » au lieu de « aucune mesure ».
    # 12.9 (N13, critique § 3.2.7) : par marque ($brand ; $null : derniere marque choisie, $script:LevelBrand ; '' :
    # « non precisee », distincte de toute marque nommee ; Get-LevelBrandKey : casse et espaces des bords ignores), seuls
    # les enregistrements d etat 'mesure' ; jamais le facteur d une autre marque (k = 1). Old : enregistrements d un autre
    # calcul de cette marque ou sans marque (12.8.x) ; Other : mesures d autres marques pour ce lecteur, cette famille et
    # cette tete, OtherBrands leurs noms (bruts : '' pour « non precisee », a afficher par Format-ContentBrand, 276) ;
    # Brand : marque cherchee. Revue de la phase B (mineur 1) : OldContent, ceux de Old ecartes seulement par ContentCalc
    # (CalibCalc courant : mesures d avant la 12.9, calibration inchangee ; texte « calcul de la mesure change »)
    $br = if ($null -eq $brand) { [string]$script:LevelBrand } else { [string]$brand }
    $bk = Get-LevelBrandKey $br
    $cand = @(); $i = 0; $old = 0; $oldC = 0; $nOth = 0; $oth = @{}
    foreach ($r in $script:ContentMeasures) {
        $i++
        if ($null -eq $r -or $null -eq $r.Head -or $null -eq $r.K) { continue }
        if ([string]$r.Drive -ne $drive -or [string]$r.Family -ne $fam -or [int]$r.Head -ne $h) { continue }
        $rk = Get-LevelBrandKey ([string]$r.Brand)
        if ([string]$r.ContentCalc -ne [string]$script:ContentCalc -or [string]$r.Calc -ne [string]$script:CalibCalc) {
            if ($rk -eq $bk -or -not $rk) { $old++; if ([string]$r.Calc -eq [string]$script:CalibCalc) { $oldC++ } }
            continue
        }
        if ([string]$r.Etat -ne 'mesure') { continue }
        $k = [double]$r.K
        if ([double]::IsNaN($k) -or [double]::IsInfinity($k)) { continue }
        if ($rk -ne $bk) { $nOth++; if (-not $oth.ContainsKey($rk)) { $oth[$rk] = ([string]$r.Brand).Trim() }; continue }
        $cand += @{ R = $r; D = (Get-CurveDate $r); I = $i; K = $k }
    }
    $ob = [string[]]@($oth.Values | Sort-Object)
    if ($cand.Count -eq 0) { return @{ K = 1.0; Src = 'defaut'; Rec = $null; N = 0; Ks = [double[]]@(); Old = $old; OldContent = $oldC; Other = $nOth; OtherBrands = $ob; Brand = $br } }
    $last = @($cand | Sort-Object -Property @{ Expression = { $_.D }; Descending = $true }, @{ Expression = { $_.I }; Descending = $true } | Select-Object -First 3)
    $ks = [double[]]@($last | ForEach-Object { $_.K })
    return @{ K = [double](Get-Median $ks); Src = 'lecteur'; Rec = $last[0].R; N = $last.Count; Ks = $ks; Old = $old; OldContent = $oldC; Other = $nOth; OtherBrands = $ob; Brand = $br }
}

function Get-StaleDriveFactors {
    # Revue 12.8.2 : lecteurs dont les facteurs mesures ne sont plus appliques (Get-DriveK) : enregistrements d un autre
    # calcul (CalibCalc ou ContentCalc) pour un lecteur, une famille et une tete sans aucun enregistrement du calcul
    # actuel. Renvoie @{ N : enregistrements ecartes ; Drives : lecteurs concernes, tries } (ligne de journal de Load-Config).
    # 12.9 : Content, ceux d un autre ContentCalc (texte « facteurs mesures avant la 12.9 » de Load-Config)
    $cur = @{}; $old = @{}; $oc = @{}
    foreach ($r in @($script:ContentMeasures)) {
        if ($null -eq $r -or $null -eq $r.Head -or $null -eq $r.K) { continue }
        $key = "$($r.Drive)|$($r.Family)|$([int]$r.Head)"
        if ([string]$r.ContentCalc -eq [string]$script:ContentCalc -and [string]$r.Calc -eq [string]$script:CalibCalc) { $cur[$key] = $true }
        else {
            if (-not $old.ContainsKey($key)) { $old[$key] = 0; $oc[$key] = 0 }
            $old[$key]++; if ([string]$r.ContentCalc -ne [string]$script:ContentCalc) { $oc[$key]++ }
        }
    }
    $n = 0; $nc = 0; $drv = @{}
    foreach ($key in @($old.Keys)) { if (-not $cur.ContainsKey($key)) { $n += [int]$old[$key]; $nc += [int]$oc[$key]; $drv[($key -split '\|')[0]] = $true } }
    return @{ N = $n; Content = $nc; Drives = @($drv.Keys | Sort-Object) }
}

function Add-ContentMeasure($rec) {
    # Ajoute un enregistrement de mesure (C.2) a $script:ContentMeasures. 12.9 (critique § 3.2.8) : plafonds, du plus recent
    # au plus ancien (date de mesure, ordre d ajout a date egale) : ContentRecPerKey (5) par lecteur, famille, tete, marque
    # (Get-LevelBrandKey) et ContentCalc, les enregistrements d etat 'mesure' gardes avant les autres (la memoire de la
    # marque n en perd aucun au profit d une marge plate) ; ContentRecOldMax (20) d un autre calcul (ContentCalc ou
    # CalibCalc) ; ContentRecMax (80) en tout. Ordre des enregistrements gardes inchange
    if ($null -eq $rec) { return }
    $all = @($script:ContentMeasures | Where-Object { $null -ne $_ })
    $all += $rec
    $perKey = if ([int]$script:ContentRecPerKey -gt 0) { [int]$script:ContentRecPerKey } else { 5 }
    $max = if ([int]$script:ContentRecMax -gt 0) { [int]$script:ContentRecMax } else { 80 }
    $oldMax = if ($null -ne $script:ContentRecOldMax -and [int]$script:ContentRecOldMax -ge 0) { [int]$script:ContentRecOldMax } else { 20 }
    $ix = @(for ($j = 0; $j -lt $all.Count; $j++) {
        $r = $all[$j]
        @{ R = $r; D = (Get-CurveDate $r); I = $j; M = ([string]$r.Etat -eq 'mesure')
           Key = "$($r.Drive)|$($r.Family)|$([int]$r.Head)|$(Get-LevelBrandKey ([string]$r.Brand))|$($r.ContentCalc)"
           Old = ([string]$r.ContentCalc -ne [string]$script:ContentCalc -or [string]$r.Calc -ne [string]$script:CalibCalc) }
    })
    $kept = @(); $grp = @{}
    foreach ($e in $ix) { if (-not $grp.ContainsKey($e.Key)) { $grp[$e.Key] = @() }; $grp[$e.Key] += ,$e }
    foreach ($g in @($grp.Keys)) {
        $kept += @($grp[$g] | Sort-Object -Property @{ Expression = { $_.M }; Descending = $true }, @{ Expression = { $_.D }; Descending = $true }, @{ Expression = { $_.I }; Descending = $true } | Select-Object -First $perKey)
    }
    $ko = @($kept | Where-Object { $_.Old } | Sort-Object -Property @{ Expression = { $_.D }; Descending = $true }, @{ Expression = { $_.I }; Descending = $true } | Select-Object -First $oldMax)
    $kept = @(@($kept | Where-Object { -not $_.Old }) + $ko)
    # Synthese C (A3) : les 3 derniers enregistrements 'mesure' de chaque cle du calcul courant (fenetre de la mediane de
    # Get-DriveK) passent avant les autres au plafond ContentRecMax : une marque mesuree n est pas evincee par des mesures
    # plus recentes d autres marques ou d autres lecteurs, ni par des marges plates
    $pk = @{}
    foreach ($e in @($kept | Where-Object { -not $_.Old -and $_.M } | Sort-Object -Property @{ Expression = { $_.D }; Descending = $true }, @{ Expression = { $_.I }; Descending = $true })) {
        if (-not $pk.ContainsKey($e.Key)) { $pk[$e.Key] = 0 }
        if ($pk[$e.Key] -lt 3) { $pk[$e.Key]++; $e.P = $true }
    }
    $kept = @($kept | Sort-Object -Property @{ Expression = { [bool]$_.P }; Descending = $true }, @{ Expression = { $_.D }; Descending = $true }, @{ Expression = { $_.I }; Descending = $true } | Select-Object -First $max)
    $ki = @{}; foreach ($e in $kept) { $ki[[int]$e.I] = $true }
    $script:ContentMeasures = @($ix | Where-Object { $ki.ContainsKey([int]$_.I) } | ForEach-Object { $_.R })
}

function ConvertTo-FiniteOrNull($x) {
    # Nombre fini (double), sinon $null (absent, texte illisible, NaN, infini : le JSON n admet ni NaN ni l infini)
    if ($null -eq $x -or $x -is [bool]) { return $null }
    try { $d = [double]$x } catch { return $null }
    if ([double]::IsNaN($d) -or [double]::IsInfinity($d)) { return $null }
    return $d
}

function Get-ConfigDouble($x, [double]$def) {
    # Nombre de la configuration : valeur finie, sinon $def
    $d = ConvertTo-FiniteOrNull $x
    if ($null -eq $d) { return $def }
    return [double]$d
}

function Get-RecValues($o) {
    # Champ Values d un enregistrement (mesure C.2, courbe V, entree de write.driveFactors) : lu par l index sur une table
    # (IDictionary). Sans la cle, $o.Values rendrait la propriete Values de la Hashtable, c est-a-dire toutes les valeurs
    # de l enregistrement (revue 12.8.1, I1) ; objet de ConvertFrom-Json : propriete. Champ absent ou $null : rien dans
    # le pipeline (@(Get-RecValues $x) vide)
    if ($null -eq $o) { return }
    $v = $null
    if ($o -is [System.Collections.IDictionary]) { $v = $o['Values'] } else { $v = $o.Values }
    if ($null -eq $v) { return }
    return $v
}

function ConvertTo-ContentConfig($rec) {
    # Enregistrement de mesure (C.2) -> entree de write.driveFactors (C.5) ; nombres non finis ecrits null ; Values par
    # Get-RecValues (enregistrement sans cle Values : liste vide)
    if ($null -eq $rec) { return $null }
    return [ordered]@{ model = [string]$rec.Model; drive = [string]$rec.Drive; family = [string]$rec.Family; head = [int]$rec.Head
                       date = [string]$rec.Date; image = [string]$rec.Image; k = (ConvertTo-FiniteOrNull $rec.K); kVertex = (ConvertTo-FiniteOrNull $rec.KVertex)
                       bound = [string]$rec.Bound; flat = [bool]$rec.Flat; seK = (ConvertTo-FiniteOrNull $rec.SeK); b1 = (ConvertTo-FiniteOrNull $rec.B1)
                       b2 = (ConvertTo-FiniteOrNull $rec.B2); gain = (ConvertTo-FiniteOrNull $rec.Gain); s = (ConvertTo-FiniteOrNull $rec.S)
                       nCyl = [int]$rec.NCyl; nObs = [int]$rec.NObs; nExcl = [int]$rec.NExcl
                       levels = @($rec.Levels | Where-Object { $null -ne $_ } | ForEach-Object { [double]$_ })
                       f = (ConvertTo-FiniteOrNull $rec.F)   # 12.10 : plus de champ dk (correction Dk retiree)
                       values = @(Get-RecValues $rec | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_ }); spec = [string]$rec.Spec
                       refKey = [string]$rec.RefKey; refDate = [string]$rec.RefDate; calc = [string]$rec.Calc; contentCalc = [string]$rec.ContentCalc
                       version = [string]$rec.Version
                       # 12.9 : marque, etat de la tete, courbure en ns, t, dispersion des zones, passes, k par zone (2 decimales)
                       brand = [string]$rec.Brand; etat = [string]$rec.Etat; q = (ConvertTo-FiniteOrNull $rec.Q); tQ = (ConvertTo-FiniteOrNull $rec.TQ)
                       chi2Ddl = (ConvertTo-FiniteOrNull $rec.Chi2Ddl); nPass = [int]$rec.NPass
                       zones = @(@($rec.Zones) | Where-Object { $null -ne $_ } | ForEach-Object { $zk = ConvertTo-FiniteOrNull $_.K; [ordered]@{ z = [int]$_.Z; k = $(if ($null -ne $zk) { [math]::Round([double]$zk, 2) } else { $null }) } }) }
}

function ConvertFrom-ContentConfig($o) {
    # Entree de write.driveFactors -> enregistrement de mesure (C.2) ; $null (ignoree par Load-Config, ligne T-C14) sans
    # drive ou family, avec head autre que 0 ou 1, ou avec k non fini ou hors de [0 ; 1]. KVertex : $null sans sommet ;
    # autres nombres absents : NaN (F : k ; 12.10 : le champ dk n est plus lu). 12.9 : k de 0 a ContentKMax (2) pour les
    # etats 'mesure', 'haute', 'basse' et les enregistrements sans etat (avant la 12.9) ; autre etat (marge plate, peu
    # determine) : k absent admis (NaN). Marque absente : '' (« non precisee ») ; Zones : @{ Z ; K }
    if ($null -eq $o) { return $null }
    try {
        $k = ConvertTo-FiniteOrNull $o.k; $hd = ConvertTo-FiniteOrNull $o.head
        $etat = [string]$o.etat
        $kMax = if ([double]$script:ContentKMax -gt 0) { [double]$script:ContentKMax } else { 2.0 }
        $kBad = if (@('', 'mesure', 'haute', 'basse') -contains $etat) { $null -eq $k -or $k -lt 0 -or $k -gt $kMax } else { $false }
        if (-not [string]$o.drive -or -not [string]$o.family -or $null -eq $hd -or ($hd -ne 0 -and $hd -ne 1) -or $kBad) { return $null }
        $nan = [double]::NaN
        $kd = if ($null -ne $k) { [double]$k } else { $nan }
        return @{ Model = $(if ($o.model) { [string]$o.model } else { 'contenu' }); Drive = [string]$o.drive; Family = [string]$o.family; Head = [int]$hd
                  Date = [string]$o.date; Image = [string]$o.image; K = $kd; KVertex = (ConvertTo-FiniteOrNull $o.kVertex); Bound = [string]$o.bound
                  Flat = ($o.flat -eq $true); SeK = (Get-ConfigDouble $o.seK $nan); B1 = (Get-ConfigDouble $o.b1 $nan); B2 = (Get-ConfigDouble $o.b2 $nan)
                  Gain = (Get-ConfigDouble $o.gain $nan); S = (Get-ConfigDouble $o.s $nan); NCyl = [int]$o.nCyl; NObs = [int]$o.nObs; NExcl = [int]$o.nExcl
                  Levels = [double[]]@($o.levels | Where-Object { $null -ne $_ } | ForEach-Object { [double]$_ })
                  F = (Get-ConfigDouble $o.f $kd); Values = [int[]]@(Get-RecValues $o | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_ })
                  Spec = [string]$o.spec; RefKey = [string]$o.refKey; RefDate = [string]$o.refDate; Calc = [string]$o.calc
                  ContentCalc = [string]$o.contentCalc; Version = [string]$o.version
                  Brand = ([string]$o.brand).Trim(); Etat = $etat; Q = (Get-ConfigDouble $o.q $nan); TQ = (Get-ConfigDouble $o.tQ $nan)
                  Chi2Ddl = (Get-ConfigDouble $o.chi2Ddl $nan); NPass = [int]$o.nPass
                  Zones = @(@($o.zones) | Where-Object { $null -ne $_ } | ForEach-Object { @{ Z = [int]$_.z; K = (Get-ConfigDouble $_.k $nan) } }) }
    } catch { return $null }
}

function Get-ContentBrandItems([string]$drive, [string]$fam) {
    # 12.9 (code-et-calibration § 2.1) : elements de la liste « Marque » de la fenetre « Mesure de la disquette », dans
    # l ordre : « (non precisee) » ; marques mesurees (etat 'mesure') avec le calcul actuel pour ce lecteur et cette famille,
    # de la plus recente a la plus ancienne (« {0} - facteur memorise le {1} ») ; marques mesurees avec un autre calcul
    # seulement (« {0} - a remesurer (calcul change) ») ; autres marques des mesures, puis noms de la memoire de marque
    # (levelBrands, tous lecteurs). Dedoublonnage par Get-LevelBrandKey. Rend @{ Items ; Map (texte -> marque) }
    $none = (T '(non précisée)'); $map = @{ $none = '' }; $items = @($none); $seen = @{ '' = $true }
    $ok = [ordered]@{}; $stale = [ordered]@{}; $plain = [ordered]@{}
    $recs = @(@($script:ContentMeasures) | Where-Object { $null -ne $_ -and [string]$_.Drive -eq $drive -and [string]$_.Family -eq $fam } | Sort-Object { Get-CurveDate $_ } -Descending)
    foreach ($r in $recs) {
        $bk = Get-LevelBrandKey ([string]$r.Brand); if (-not $bk) { continue }
        $nm = ([string]$r.Brand).Trim()
        $cur = ([string]$r.ContentCalc -eq [string]$script:ContentCalc -and [string]$r.Calc -eq [string]$script:CalibCalc)
        if ($cur -and [string]$r.Etat -eq 'mesure') { if (-not $ok.Contains($bk)) { $ok[$bk] = @{ Name = $nm; Date = [string]$r.Date } } }
        elseif (-not $cur) { if (-not $stale.Contains($bk)) { $stale[$bk] = $nm } }
        elseif (-not $plain.Contains($bk)) { $plain[$bk] = $nm }
    }
    foreach ($bk in @($ok.Keys)) { $t = (T '{0} - facteur mémorisé le {1}') -f "$($ok[$bk].Name)", "$($ok[$bk].Date)"; $map[$t] = [string]$ok[$bk].Name; $items += $t; $seen[$bk] = $true }
    foreach ($bk in @($stale.Keys)) { if ($seen.ContainsKey($bk)) { continue }; $t = (T '{0} - à remesurer (calcul changé)') -f "$($stale[$bk])"; $map[$t] = [string]$stale[$bk]; $items += $t; $seen[$bk] = $true }
    foreach ($bk in @($plain.Keys)) { if ($seen.ContainsKey($bk)) { continue }; $map[[string]$plain[$bk]] = [string]$plain[$bk]; $items += [string]$plain[$bk]; $seen[$bk] = $true }
    foreach ($en in @(@($script:LevelBrands) | Where-Object { $_ } | Sort-Object { Get-CurveDate $_ } -Descending)) {
        $nm = ([string]$en.Brand).Trim(); $bk = Get-LevelBrandKey $nm
        if (-not $bk -or $seen.ContainsKey($bk)) { continue }
        $map[$nm] = $nm; $items += $nm; $seen[$bk] = $true
    }
    return @{ Items = $items; Map = $map }
}

function Get-ContentScpPath([string]$dir, [string]$stamp, [string]$drive, [int]$pass) {
    # 12.9 (D6) : relecture gardee de la passe $pass (1..4) d une mesure sur l image, contenu-AAAAMMJJ-HHMMSS-<lecteur>-p<n>.scp
    # dans $dir (TempDir\mesures-image) ; $pass <= 0 : fichier compagnon contenu-AAAAMMJJ-HHMMSS-<lecteur>.json
    $d = ([string]$drive) -replace '[^A-Za-z0-9]', ''
    if ($pass -le 0) { return (Join-Path $dir "contenu-$stamp-$d.json") }
    return (Join-Path $dir "contenu-$stamp-$d-p$pass.scp")
}

function Get-ContentKeepPlan($files, [int]$n) {
    # 12.9 (D6) : fichiers a supprimer pour ne garder que les $n mesures les plus recentes (0 : toutes supprimees) ; seuls
    # les fichiers contenu-AAAAMMJJ-HHMMSS-<lecteur>-p<n>.scp et contenu-AAAAMMJJ-HHMMSS-<lecteur>.json comptent (autres
    # noms ignores), regroupes par mesure (horodatage et lecteur), la plus recente d abord
    $grp = @{}
    foreach ($f in @($files)) {
        if (-not $f) { continue }
        $m = [regex]::Match([System.IO.Path]::GetFileName([string]$f), '^contenu-(\d{8}-\d{6})-([A-Za-z0-9]+)(?:-p\d+\.scp|\.json)$')
        if (-not $m.Success) { continue }
        $g = "$($m.Groups[1].Value)-$($m.Groups[2].Value)"
        if (-not $grp.ContainsKey($g)) { $grp[$g] = New-Object 'System.Collections.Generic.List[string]' }
        $grp[$g].Add([string]$f)
    }
    # Rendu dans le pipeline, un chemin par element (l appelant l enveloppe dans @() ; aucun : rien)
    $ks = @($grp.Keys | Sort-Object -Descending)
    $del = @(); for ($i = [math]::Max(0, $n); $i -lt $ks.Count; $i++) { $del += @($grp[$ks[$i]]) }
    return $del
}

function Get-GwVerifyStop([string[]]$lines) {
    # Arret de gw 1.23 sur une piste refusee a la verification apres les nouveaux essais (A.7) : @{ C ; H } de la premiere
    # ligne « Failed to verify Track C.H » (sans ancre : « ** FATAL ERROR: » peut la preceder), $null sinon
    foreach ($l in @($lines)) {
        if ($null -eq $l) { continue }
        $m = [regex]::Match($l, 'Failed to verify Track (\d+)\.([01])')
        if ($m.Success) { return @{ C = [int]$m.Groups[1].Value; H = [int]$m.Groups[2].Value } }
    }
    return $null
}
# ============================== FONCTIONS : MESURE SUR L IMAGE, DEROULE ==========

# 12.8.1 (lot B, spec-1281.md § A et B.3) : mesure de la disquette sur l image avant une ecriture lente (liste « Mesure :
# sur l image a ecrire », reglage levelBeforeWriteMode = content). Eligibilite de l image et du contexte
# (Test-ContentMeasurable), confirmation frmConfirm, etat de calibration au mode 'content' ($script:Cal : barre, bouton
# Arreter, prechauffage et minuteur de la calibration complete ; New-CalibPass renvoie le stade 'content' a
# New-ContentPass), 3 passes des 40 cylindres du plan ecrits avec l image elle-meme a k x V (carre latin, Get-ContentPlan),
# une commande gw write par tete puis une relecture de 3 tours ; arret « Failed to verify Track » de gw (110, 600) : piste
# gardee a son niveau, reprise de la tete une fois par passe ; marge fixe de chaque piste relue (Get-ContentPassStats),
# exclusions, facteur k* par tete (Get-ContentFactorNs depuis la 12.9), enregistrements de mesure, puis facteur de
# l ecriture qui suit ($script:WriteFactorNext, lu une fois par Start-ImageWrite) et ecriture de l image. Calcul : 192 et
# 274 (lot A) ; constantes et etat : 565 ; textes : 012.
# 12.9 (critique de la phase A, § 3.3) : marque de la disquette dans la fenetre (sautee en ecriture sans surveillance,
# $script:CalibUnattended, 560), 4e passe adaptative, relectures gardees et fichier compagnon JSON (D6) ; textes : 016.

function Get-ContentLevels {
    # Niveaux k du plan (A.4) : 1, k_mid, k_low ; reglages contentKMid et contentKLow (variables ContentKMid et ContentKLow,
    # controlees au chargement par Load-Config), sinon defauts de 565. Garde : 0 <= k_low <= k_mid - 0,2 et k_mid <= 0,8
    $d = [double[]]@($script:ContentLevelsDefault)
    $m = ConvertTo-FiniteOrNull $script:ContentKMid; $l = ConvertTo-FiniteOrNull $script:ContentKLow
    if ($null -eq $m -or $null -eq $l -or $l -lt 0 -or $l -gt $m - 0.2 + 1e-9 -or $m -gt 0.8 + 1e-9) { return ,$d }
    return ,([double[]]@(1.0, [double]$m, [double]$l))
}

function Format-ContentLevels([double[]]$levels) {
    # Niveaux au format de la langue, separes par « ; » (confirmation et journal) : « 1 ; 0,6 ; 0,25 »
    return ((@($levels) | ForEach-Object { Format-UiNum ([double]$_) '0.##' }) -join ' ; ')
}

function Format-CylRanges([int[]]$cyls) {
    # Cylindres en plages, syntaxe de gw (« 0-4,10-14,20-24 ») : --tracks=c= des commandes de la mesure et journal
    $s = @($cyls | Sort-Object -Unique)
    if ($s.Count -eq 0) { return '' }
    $parts = @(); $a = [int]$s[0]; $b = [int]$s[0]
    for ($i = 1; $i -le $s.Count; $i++) {
        if ($i -lt $s.Count -and [int]$s[$i] -eq $b + 1) { $b = [int]$s[$i]; continue }
        $parts += $(if ($a -eq $b) { "$a" } else { "$a-$b" })
        if ($i -lt $s.Count) { $a = [int]$s[$i]; $b = $a }
    }
    return ($parts -join ',')
}

function Test-ContentMeasurable([string]$img, [string]$fmt) {
    # Image et contexte de la mesure sur l image (A.2), conditions dans l ordre du tableau ; ecriture lente hors
    # restauration, profil Auto et --precomp coche, image a deux faces : controles des appelants (Start-LevelBeforeWrite,
    # Start-WriteTabWrite, Start-PresetWrite, Get-LevelWriteSkip) :
    #  - image double densite MFM calibrable (Get-WriteLevelKind 'dd' : ni flux, ni haute densite, ni secteurs durs ou
    #    TG43, densite etablie, cellule de 1 700 a 2 300 ns, module ScpStats), famille std ou long ;
    #  - champ Pistes vide (c=, h=, step= deja ecartes par Get-LevelWriteSkip ; hswap, h0.off... : pistes physiques que le
    #    plan, sans ces elements, ne viserait pas) ;
    #  - courbe(s) V du lecteur du bandeau (Get-FamilyCurves : par tete a jour, sinon la courbe commune pour les deux
    #    tetes, comme Set-PrecompFields), d au moins min(80, NCyl) valeurs ;
    #  - 20 cylindres au moins dans l image (4 blocs), et 20 par tete apres les exclusions d avant l ecriture.
    # Sortie : @{ Ok ; Why (raison du journal, T-B22) ; Img ; Drive ; Fam ; V = @{ 0 ; 1 } (int[]) ; RefKeys ; RefDates ;
    # Common ; NCyl ; Ncell0 ; PreSkip ; Levels ; Hard ; Plan } (plan construit ici pour compter les pistes par tete)
    $r = @{ Ok = $false; Why = ''; Img = $img; Drive = [string]$cmbDrive.Text; Fam = ''; V = @{}; RefKeys = @{}; RefDates = @{}; Common = $false
            NCyl = 0; Ncell0 = 0; PreSkip = @{}; Levels = [double[]]@(); Hard = 0; Plan = $null }
    $whyKind = (T 'image non mesurable sur son contenu (haute densité, flux, FM ou GCR)')
    if ((Get-WriteLevelKind $img $fmt) -ne 'dd') { $r.Why = $whyKind; return $r }
    $fam = Get-ImageFamily $img $fmt
    if (@('std', 'long') -notcontains $fam) { $r.Why = $whyKind; return $r }
    $r.Fam = $fam
    $ts = ([string]$txtWTracks.Text).Trim()
    if ($ts) { $r.Why = (T 'champ Pistes : {0}') -f "$ts"; return $r }
    $nc = (Get-CalibCylinders $img $fmt).NCyl
    $nc = if ($null -eq $nc) { 80 } else { [math]::Max(2, [math]::Min(84, [int]$nc)) }
    $r.NCyl = $nc
    # Get-FamilyCurves : tableau protege (pas de @() autour)
    $cvs = Get-FamilyCurves $fam $true
    if ($cvs.Count -eq 0) { $r.Why = (T 'aucune courbe du lecteur {0}') -f "$($r.Drive)"; return $r }
    foreach ($cv in $cvs) { if ([string]$cv.Drive -ne $r.Drive) { $r.Why = (T "courbe d'un autre lecteur ({0})") -f "$($cv.Drive)"; return $r } }
    $need = [math]::Min([int]$script:ContentMaxCyl, $nc)
    # Valeurs des courbes par Get-RecValues (274) : une courbe sans cle Values compte 0 valeur
    foreach ($cv in $cvs) {
        $nv = @(Get-RecValues $cv).Count
        if ($nv -lt $need) { $r.Why = (T "courbe du lecteur plus courte que l'image ({0} cylindres, {1} dans l'image)") -f "$nv", "$nc"; return $r }
    }
    if ($nc -lt [int]$script:ContentMinCyl) { $r.Why = (T "moins de 20 cylindres dans l'image"); return $r }
    $common = ($cvs.Count -eq 1)
    $c0 = $cvs[0]; $c1 = if ($common) { $cvs[0] } else { $cvs[1] }
    $bl = Get-ContentBlocks $nc ([int]$script:ContentBlocks) ([int]$script:ContentBlockLen) ([int]$script:ContentMaxCyl) ([int]$script:ContentMinBlocks)
    if (-not $bl.Ok) { $r.Why = (T "moins de 20 cylindres dans l'image"); return $r }
    # Borne des valeurs ecrites : precompMaxNs de la double densite (CalHardNsUser, comme Get-WriteFactorPlan), a defaut
    # CalHardNs (bareme d une calibration haute densite pas encore retabli par le minuteur)
    $hard = [int]$script:CalHardNsUser; if ($hard -le 0) { $hard = [int]$script:CalHardNs }
    $lv = Get-ContentLevels
    $pre = Get-ContentImageSkip $img ([int[]]$bl.Cyls)
    $plan = Get-ContentPlan ([int[]]@(Get-RecValues $c0)) ([int[]]@(Get-RecValues $c1)) $nc $lv $hard $pre
    if (-not $plan.Ok -or [int]$plan.NCylHead[0] -lt [int]$script:ContentMinCyl -or [int]$plan.NCylHead[1] -lt [int]$script:ContentMinCyl) {
        $r.Why = (T "trop de pistes exclues de l'image (protégées, longues ou vides)"); return $r
    }
    $r.V = @{ 0 = [int[]]@(Get-RecValues $c0); 1 = [int[]]@(Get-RecValues $c1) }
    $r.RefKeys = @{ 0 = $(if ($common) { $fam } else { "${fam}_h0" }); 1 = $(if ($common) { $fam } else { "${fam}_h1" }) }
    $r.RefDates = @{ 0 = [string]$c0.Date; 1 = [string]$c1.Date }
    $r.Common = $common; $r.Ncell0 = [int](Get-PatternBits $fam $img).Bits; $r.PreSkip = $pre; $r.Levels = $lv; $r.Hard = $hard; $r.Plan = $plan
    $r.Ok = $true
    return $r
}

function Get-ContentWriteArgs($cal, $w) {
    # Commande gw write d une tete a la passe en cours (A.5) : memes options que l ecriture lente (Start-ImageWrite,
    # 140:135-162 : --pre-erase, --erase-empty et --no-verify selon les cases, --retries, Get-WriteFormatArgs), puis le
    # --precomp du plan de la passe et de la tete restreint aux cylindres de la commande ($w = @{ H ; Cyls ; Resume } :
    # commande complete, ou reprise apres un arret de gw), --tracks=c=<cylindres>:h=<tete> et l image. Jamais --tracks=h=
    # seul : ces commandes ne se confondent pas avec l ecriture finale (regex de rpm_analyse.precomp_journal).
    # 12.8.2 : double densite (Content.EraseMode 'hfreq', Start-ContentMeasure) : jamais --pre-erase, la passe commence par
    # un effacement haute frequence de ses pistes (New-ContentPass) ; autre mode : --pre-erase selon la case, comme avant
    $ct = $cal.Content
    $ph = $ct.Plan.Pass[[int]$ct.Pass].H[[int]$w.H]
    $sel = @{}
    foreach ($c in @($w.Cyls)) { $sel[[int]$c] = [int]$ph.W[[int]$c] }
    $a = @('write') + (Get-CommonArgs)
    if ($chkWPreErase.Checked -and [string]$ct.EraseMode -ne 'hfreq') { $a += '--pre-erase' }
    if ($chkWEraseEmpty.Checked) { $a += '--erase-empty' }
    if ($chkWNoVerify.Checked)   { $a += '--no-verify' }
    $a += "--retries=$($numWRetries.Value)"
    $a += Get-WriteFormatArgs
    $a += @('--precomp', (Get-BracketSpec $sel), "--tracks=c=$(Format-CylRanges ([int[]]@($w.Cyls))):h=$([int]$w.H)", "`"$($cal.Image)`"")
    return ,([string[]]$a)
}

function Get-ContentMeasureMinutes([int]$nTracks, [int]$passes = 3, [switch]$NoWarmup) {
    # Duree estimee de la mesure avant l ecriture de l image (A.6) : 3 passes de nTracks pistes ecrites (ContentEstWrite,
    # 1,25 s par piste, ecriture verifiee) et relues (ContentEstRead, 0,85 s par piste, 3 tours), plus le prechauffage du
    # reglage warmFullCalib (borne haute : reduit ou saute si le lecteur vient de servir). 12.8.2 (revue) : effacement haute
    # frequence de chaque passe compris (Get-ContentEraseEst). 12.9 : $passes (1 : 4e passe adaptative), NoWarmup : sans
    # le prechauffage
    $wu = if (-not $NoWarmup -and [bool](Get-Setting 'warmFullCalib')) { [math]::Max(0.0, [double]$script:CalWarmupMinutes) } else { 0.0 }
    return [int][math]::Max(1, [math]::Round($passes * $nTracks * ([double]$script:ContentEstWrite + [double]$script:ContentEstRead + (Get-ContentEraseEst)) / 60 + $wu, 0))
}

function Get-ContentEraseEst {
    # 12.8.2 (revue) : duree estimee, en s par piste et par passe, de l effacement haute frequence de la mesure sur l image
    # (New-ContentPass : case « Effacer avant d ecrire » cochee, double densite, seule densite mesuree ici) ; 0 sinon
    if ($chkWPreErase.Checked -and (Get-EraseMode $false) -eq 'hfreq') { return [double]$script:EraseEstTrack }
    return 0.0
}

function Format-ContentNum($x, [string]$fmt) {
    # 12.9 : nombre du journal de la mesure au format de la langue (Format-UiNum), « - » s il n est pas fini
    $d = ConvertTo-FiniteOrNull $x
    if ($null -eq $d) { return '-' }
    return (Format-UiNum ([double]$d) $fmt)
}

function Format-ContentBrand([string]$brand) {
    # 12.9 : marque dans les textes, « (non precisee) » quand elle est vide
    $b = ([string]$brand).Trim()
    if ($b) { return $b }
    return (T '(non précisée)')
}

function Get-ContentBrandKText($dr) {
    # 12.9 : origine du k memorise (Get-DriveK, par marque) dans le journal de la mesure : mediane des N >= 2 dernieres
    # mesures, derniere mesure, mesures d un autre calcul a refaire, ou aucune mesure de la marque (nombre de mesures
    # d autres marques, jamais empruntees)
    $kTxt = Format-UiNum ([double]$dr.K) '0.00'; $bn = Format-ContentBrand ([string]$dr.Brand)
    if ([string]$dr.Src -eq 'lecteur') {
        if ([int]$dr.N -ge 2) { return ((T 'k {0}, médiane des {1} dernières mesures du lecteur pour la marque « {2} »') -f "$kTxt", "$($dr.N)", "$bn") }
        return ((T 'k {0} de la dernière mesure du lecteur pour la marque « {1} », du {2}') -f "$kTxt", "$bn", $(if ($dr.Rec -and $dr.Rec.Date) { [string]$dr.Rec.Date } else { '?' }))
    }
    # Revue de la phase B (mineur 1) : mesures ecartees seulement par ContentCalc (OldContent) : calcul de la mesure change,
    # calibration inchangee
    if ([int]$dr.Old -gt 0 -and [int]$dr.OldContent -ge [int]$dr.Old) { return ((T 'k 1, mesures de ce lecteur faites avant la {0} (calcul de la mesure changé), à refaire pour la marque « {1} »') -f "$($script:ContentCalc)", "$bn") }
    if ([int]$dr.Old -gt 0) { return (T 'k 1, mesures de ce lecteur faites avec un autre calcul de calibration, à refaire') }
    $oth = if ([int]$dr.Other -gt 0) { (T ' ; {0} mesure(s) d''autres marques') -f "$($dr.Other)" } else { '' }
    return ((T 'k 1, aucune mesure de ce lecteur pour la marque « {0} »{1}') -f "$bn", "$oth")
}

function Start-ContentMeasure($chk) {
    # Lancement de la mesure sur l image (A.8, A.9), $chk : Test-ContentMeasurable. Refus si gw tourne ; confirmation
    # frmConfirm sans case ni compte a rebours, reponse notee au journal par Show-AppConfirm : « Mesurer puis ecrire »
    # (mesure), « Ecrire sans mesure » (ecriture avec le facteur du lecteur), Fermer (ecriture annulee). Etat $script:Cal
    # au mode et au stade 'content' (barre, bouton Arreter, prechauffage et minuteur communs ; champs lus par
    # Update-CalibProgress, Start-CalibWarmup, Invoke-CalibWarmup, Stop-PrecompCalib), ecriture apres la mesure
    # (AfterCalib 'write', Complete-ContentMeasure), puis prechauffage s il y a lieu et premiere passe. Refus (gw en cours,
    # avant ou apres la confirmation) : ecriture annulee, une ligne de journal (revue 12.8.1, point 7)
    $refusTxt = (T 'Écriture annulée : une commande gw est déjà en cours, mesure de la disquette non lancée.')
    if ($script:GwProc -and -not $script:GwProc.HasExited) { $script:AfterCalib = ''; Append-Log $refusTxt; return }
    # 12.11 (lot LN-b) : avec des lecteurs enregistres, lecteur branche confirme s il y a lieu (Confirm-DriveIdentity, 112) ;
    # refus : ecriture annulee, comme le refus qui precede
    if ($script:DriveReg.Count -gt 0 -and -not (Confirm-DriveIdentity)) { $script:AfterCalib = ''; return }
    $drive = [string]$chk.Drive; $img = [string]$chk.Img; $fam = [string]$chk.Fam; $plan = $chk.Plan
    $lv = [double[]]@($chk.Levels)
    $cyls = [int[]]@($plan.Cyls | Sort-Object -Unique)
    $min = Get-ContentMeasureMinutes ([int]$plan.NCylHead[0] + [int]$plan.NCylHead[1])
    $lvTxt = Format-ContentLevels $lv
    # 12.9 (D3) : duree d une 4e passe adaptative, annoncee en plus
    $min4 = Get-ContentMeasureMinutes ([int]$plan.NCylHead[0] + [int]$plan.NCylHead[1]) 1 -NoWarmup
    if ([bool]$script:CalibUnattended) {
        # 12.9 (S1, decision du 30/10/2026) : ecriture sans surveillance : fenetre non affichee, mesure avec la derniere marque
        $go = $true
        Append-Log ((T "Mesure de la disquette : fenêtre non affichée (écriture sans surveillance) : mesure sur l'image, marque « {0} ».") -f (Format-ContentBrand ([string]$script:LevelBrand)))
    } else {
        # 12.9 (N13) : marque de la disquette inseree (liste pre-remplie avec la derniere marque, Get-ContentBrandItems)
        $bi = Get-ContentBrandItems $drive $fam
        $cq = @{ Title = (T 'Mesure de la disquette'); Heading = (T "Mesure de la disquette sur l'image"); Level = 'info'; Picto = 'data'
                 Text = ((T "Avant l'écriture lente, la précompensation est mesurée sur le contenu même de l'image, sur le lecteur {0} : {1} cylindres répartis sur le disque sont écrits 3 fois, à 3 niveaux de la courbe du lecteur ({2}), et relus après chaque passe. L'image est ensuite écrite avec, pour chaque tête, le niveau qui donne la meilleure marge de lecture.`n`nDurée : environ {3} min avant l'écriture de l'image (+ environ {4} min si l'optimum dépasse le plan). Ces pistes reçoivent 3 écritures de plus (4 si l'optimum dépasse le plan).`n`n« Écrire sans mesure » : facteur mémorisé pour ce lecteur et la marque choisie ci-dessous ; sans mesure de cette marque, courbe du lecteur telle quelle (× 1).") -f "$drive", "$($cyls.Count)", "$lvTxt", "$min", "$min4")
                 GoText = (T 'Mesurer puis écrire'); GoGlyph = 'Diagnostic'; AltText = (T 'Écrire sans mesure')
                 Combo = @{ Label = (T 'Marque de la disquette insérée :'); Items = $bi.Items; Text = [string]$script:LevelBrand
                            Tip = (T "Nom libre : marque, année ou lot. Le facteur mesuré est mémorisé pour ce lecteur et cette marque ; « Écrire sans mesure » applique celui de la marque choisie (courbe du lecteur telle quelle si la marque n'a pas de mesure).") } }
        # 12.8.2 (revue) : effacement haute frequence de chaque passe (New-ContentPass), compris dans la duree
        if ((Get-ContentEraseEst) -gt 0) { $cq.Text += "`n`n" + (T "Case « Effacer avant d'écrire » cochée : ces pistes sont effacées en haute fréquence avant chaque passe, durée comprise.") }
        $script:ConfirmChoice = $null
        $go = [bool](Show-AppConfirm @cq)
        if ($go -or [string]$script:ConfirmChoice -eq 'alt') { $script:LevelBrand = Get-LevelBrandName ([string]$script:ConfirmComboText) $bi.Map }
    }
    if (-not $go) {
        $script:AfterCalib = ''
        if ([string]$script:ConfirmChoice -eq 'alt') {
            # Ecriture sans mesure : facteur memorise du lecteur pour la marque choisie (Start-ImageWrite, Get-DriveK)
            $script:WriteFactorNext = @{ Drive = $drive; Fam = $fam; Img = $img; Brand = [string]$script:LevelBrand; K = $null }
            Append-Log (T "Mesure sur l'image non faite à votre demande : écriture avec le facteur du lecteur.")
            Start-ImageWrite
            return
        }
        Append-Log (T 'Écriture annulée : mesure de la disquette non lancée.')
        return
    }
    if ($script:GwProc -and -not $script:GwProc.HasExited) { $script:AfterCalib = ''; Append-Log $refusTxt; return }
    if (-not (Test-Path -LiteralPath $script:TempDir)) { [void](New-Item -ItemType Directory -Path $script:TempDir -Force) }
    $cylList = Format-CylRanges $cyls
    # 12.9 (D6) : relectures gardees, une par passe, dans TempDir\mesures-image, plus un fichier compagnon JSON ; mesures
    # au-dela de contentKeepMeasures supprimees au lancement (celle-ci comprise) ; 0 : relecture unique (12.8.2)
    $keep = [math]::Max(0, [math]::Min(20, [int]$script:ContentKeepMeasures))
    $mDir = Join-Path $script:TempDir ([string]$script:ContentScpDir)
    $stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
    try {
        if (Test-Path -LiteralPath $mDir) {
            $old = @(Get-ChildItem -LiteralPath $mDir -File -ErrorAction Stop | ForEach-Object { $_.FullName })
            foreach ($f in @(Get-ContentKeepPlan $old ([math]::Max(0, $keep - 1)))) { Remove-Item -LiteralPath $f -Force -ErrorAction SilentlyContinue }
        }
        if ($keep -gt 0 -and -not (Test-Path -LiteralPath $mDir)) { [void](New-Item -ItemType Directory -Path $mDir -Force -ErrorAction Stop) }
    } catch { $keep = 0 }
    $scp = if ($keep -gt 0) { Get-ContentScpPath $mDir $stamp $drive 1 } else { Join-Path $script:TempDir $script:ContentScpName }
    $script:AlignLoop = $false; $script:AlignNextAt = $null
    # Etat propre de la mesure : plan, passe en cours (0..2), file des commandes de la passe et commande en cours, reprises
    # par passe et tete ('p|h'), cylindres non ecrits ('p|c|h' -> 'nonecrite'), exclusions d avant l ecriture ('c.h'),
    # lectures de toutes les passes (List : jamais @() autour, pwsh 7.6), courbes V, references et bornes. 12.8.2 : mode
    # de l effacement avant les ecritures (EraseMode, 150 : 'hfreq' en double densite, seule densite mesuree ici)
    $ct = @{ Plan = $plan; Pass = 0; Todo = [System.Collections.Generic.List[hashtable]]::new(); Current = $null; Resumes = @{}; Skip = @{}
             PreSkip = $chk.PreSkip; Obs = [System.Collections.Generic.List[object]]::new(); Ncell0 = [int]$chk.Ncell0; Levels = $lv
             KMin = [double](@($lv) | Measure-Object -Minimum).Minimum; V = $chk.V; RefKeys = $chk.RefKeys; RefDates = $chk.RefDates
             Common = [bool]$chk.Common; Fam = $fam; Img = $img; Hard = [int]$chk.Hard
             EraseMode = (Get-EraseMode (Test-ImageHighDensity $img ([string]$cmbWFmt.Text)))
             # 12.9 : marque de la mesure, relectures gardees (Keep mesures, dossier, horodatage), 4e passe faite, resultat
             Brand = [string]$script:LevelBrand; Keep = $keep; Dir = $mDir; Stamp = $stamp; Fourth = $false; Res = $null }
    $script:Cal = @{
        Mode = 'content'; Stage = 'content'; Drive = $drive; Family = $fam; Slow = $true; Image = $img; Cyls = $cyls; CylList = $cylList
        TSpec = "c=${cylList}:h=0-1"; Scp = $scp; Writes = (New-Object System.Collections.Queue)
        ReadArgs = @(@('read') + (Get-CommonArgs) + @(Get-DriveReadArgs) + @('--revs=3', "--tracks=c=${cylList}:h=0-1", "`"$scp`""))
        # Progression : passes faites / prevues, durees mesurees par phase ; estimation initiale par piste et par phase :
        # moyenne de l ecriture et de la relecture (Update-CalibProgress compte Cyls x 2 pistes par phase)
        StartTime = (Get-Date); PassStart = (Get-Date); PhaseStart = (Get-Date); Phase = 'write'; Value = 0; ValueTxt = (T 'tête 0 puis tête 1'); Spec = ''
        PassesDone = 0; TotalPasses = $lv.Count; WriteDurs = @(); ReadDurs = @(); EstTrack = (([double]$script:ContentEstWrite + [double]$script:ContentEstRead) / 2); EstErase = (Get-ContentEraseEst)
        Home = $false; Geom = $null; NoWarmup = (-not [bool](Get-Setting 'warmFullCalib')); Hold = $false; Redo = $false; DiskOnly = $false
        Units = @(); Swap = $false; LevelAfter = $false; VerifyCount = 0; Retests = 0; Content = $ct
    }
    $script:AfterCalib = 'write'
    Append-Log ((T "=== Mesure de la disquette sur l'image : lecteur {0}, marque « {1} », image {2} ({3}) ; {4} cylindres ({5}), niveaux {6} × courbe du lecteur ; calibration du lecteur inchangée ===") -f "$drive", (Format-ContentBrand $ct.Brand), "$([System.IO.Path]::GetFileName($img))", (Get-CalibFamilyName $fam), "$($cyls.Count)", "$cylList", "$lvTxt")
    # Revue des correctifs du 30/10/2026 (m2) : une seule mesure gardee (contentKeepMeasures 1) : texte au singulier
    if ($keep -gt 1) { Append-Log ((T "Mesure sur l'image : relectures gardées dans {0} ({1} ; {2} dernières mesures conservées).") -f "$mDir", "contenu-$stamp-$(([string]$drive) -replace '[^A-Za-z0-9]', '')-p*.scp, .json", "$keep") }
    elseif ($keep -eq 1) { Append-Log ((T "Mesure sur l'image : relectures gardées dans {0} ({1} ; seule cette mesure est conservée).") -f "$mDir", "contenu-$stamp-$(([string]$drive) -replace '[^A-Za-z0-9]', '')-p*.scp, .json") }
    $dates = if ($ct.Common) { [string]$ct.RefDates[0] } else { "$($ct.RefDates[0]) / $($ct.RefDates[1])" }
    $kind = if ($ct.Common) { (T 'courbe commune') } else { (T 'une courbe par tête') }
    Append-Log ((T "Mesure sur l'image : courbe du lecteur du {0} ({1}) ; précompensation écrite bornée à 0..{2} ns.") -f "$dates", "$kind", "$($ct.Hard)")
    if ($chkWPreErase.Checked -and [string]$ct.EraseMode -eq 'hfreq') { Append-Log (T "Mesure sur l'image : disquette double densité, chaque passe commence par un effacement haute fréquence de ses pistes (gw erase --hfreq) ; écritures sans pré-effacement.") }
    $pbWCal.Value = 0; $pbWCal.Visible = $true; $lblWCal.Visible = $true
    Update-CalibProgress
    Start-CalibWarmup      # prechauffage du lecteur s il y a lieu, puis premiere passe (New-CalibPass, stade 'content')
}

function New-ContentPass {
    # Passe suivante de la mesure (New-CalibPass au stade 'content', apres le prechauffage ou la passe precedente) : file des
    # commandes, tete 0 puis tete 1 comme l ecriture lente (cylindres de la passe dans le plan, sans les pistes exclues
    # avant l ecriture), journal (passe, niveau de chaque bloc), phase d ecriture, premiere commande
    $cal = $script:Cal
    if (-not $cal -or -not $cal.Content) { return }
    $ct = $cal.Content; $p = [int]$ct.Pass
    $ct.Todo.Clear(); $ct.Current = $null
    # 12.9 (D6) : relecture de la passe dans son propre fichier (contentKeepMeasures > 0), commande de relecture refaite
    if ([int]$ct.Keep -gt 0) {
        $cal.Scp = Get-ContentScpPath ([string]$ct.Dir) ([string]$ct.Stamp) ([string]$cal.Drive) ($p + 1)
        $cal.ReadArgs = @(@('read') + (Get-CommonArgs) + @(Get-DriveReadArgs) + @('--revs=3', "--tracks=c=$($cal.CylList):h=0-1", "`"$($cal.Scp)`""))
    }
    foreach ($h in 0, 1) {
        $cs = [int[]]@($ct.Plan.Pass[$p].H[$h].Cyls)
        if ($cs.Count -gt 0) { $ct.Todo.Add(@{ H = $h; Cyls = $cs; Resume = $false }) }
    }
    # 12.8.2 : double densite, case « Effacer avant d ecrire » cochee : effacement haute frequence des pistes de la passe
    # (cylindres de chaque tete dans le plan, sans les pistes exclues avant l ecriture), en tete de file (@{ Erase }) ;
    # champ Pistes vide (Test-ContentMeasurable) : aucun element de lecteur
    if ($chkWPreErase.Checked -and [string]$ct.EraseMode -eq 'hfreq') {
        $ks = @(foreach ($t in $ct.Todo) { foreach ($c in @($t.Cyls)) { "$c.$($t.H)" } })
        $ers = New-HfreqEraseCmds $ks ''
        for ($i = $ers.Count - 1; $i -ge 0; $i--) { $ct.Todo.Insert(0, @{ Erase = [string[]]$ers[$i] }) }
    }
    $bc = @($ct.Plan.Cyls); $nb = @($ct.Plan.Blocks).Count
    $len = if ($nb -gt 0) { [int]($bc.Count / $nb) } else { 0 }
    # 12.9 (D3) : 4e passe, niveau de chaque bloc dans la passe (BlockK, Get-ContentFourthPass)
    $pk = @($ct.Plan.Pass[$p].BlockK | Where-Object { $null -ne $_ })
    $bk = @(for ($bi = 0; $bi -lt $nb; $bi++) { $c0 = [int]$bc[$bi * $len]; $lk = if ($pk.Count -gt $bi) { [double]$pk[$bi] } else { Get-ContentLevel $bi $p ([double[]]$ct.Levels) }; "c$c0-$($c0 + $len - 1) × $(Format-UiNum $lk '0.##')" })
    $cal.ValueTxt = (T 'tête 0 puis tête 1')
    Append-Log ((T "Mesure sur l'image : passe {0}/{1}, {2}") -f "$($p + 1)", "$($cal.TotalPasses)", "$($cal.ValueTxt), $($bk -join ' ; ')")
    $cal.Phase = 'write'; $cal.PassStart = Get-Date; $cal.PhaseStart = $cal.PassStart
    # 12.11 : plan de la passe pour la barre de progression (110) : ses effacements, une ecriture par tete (memes
    # arguments que la commande lancee, Get-ContentWriteArgs), puis sa relecture ; une reprise apres un arret de gw
    # (Register-ContentWriteStop) n y est pas prevue : elle allonge le plan sans faire reculer la barre
    New-ProgPlan (@(foreach ($w in $ct.Todo) { if ($w.Erase) { ,([string[]]$w.Erase) } else { ,(Get-ContentWriteArgs $cal $w) } }) + ,([string[]]$cal.ReadArgs))
    Update-CalibProgress
    $script:Chain.Clear()
    Invoke-ContentWriteNext
}

function Invoke-ContentWriteNext {
    # Etape de la chaine apres chaque commande gw write de la mesure (et au debut de la passe) : (1) bilan de la commande
    # finie : arret « Failed to verify Track » de gw ($script:GwVerifyFail, pose par Read-GwOutput, la commande ayant ete
    # traitee comme une lecture de prechauffage par le minuteur, 600) lu et remis a $null, Register-ContentWriteStop ;
    # (2) commande suivante de la file ; (3) file vide : relecture de 3 tours des cylindres du plan, deux tetes (SCP
    # supprime avant, il garde la derniere passe), puis Invoke-ContentAnalysis
    $cal = $script:Cal
    if (-not $cal -or [string]$cal.Mode -ne 'content') { return }
    $ct = $cal.Content
    if ($null -ne $ct.Current) {
        # $vStop, jamais $stop : meme nom que $stOp (barre d etat) pour PowerShell, qui ignore la casse ; Start-Progress,
        # appele par Start-Gw plus bas, lirait cette variable locale (portee dynamique) au lieu du libelle
        $vStop = $script:GwVerifyFail; $script:GwVerifyFail = $null
        if ($vStop) { Register-ContentWriteStop $cal $ct.Current $vStop }
        $ct.Current = $null
    }
    if ($ct.Todo.Count -gt 0) {
        $w = $ct.Todo[0]; $ct.Todo.RemoveAt(0)
        $script:Chain.Enqueue({ Invoke-ContentWriteNext })
        # 12.8.2 : effacement haute frequence de la passe (New-ContentPass) : aucun arret de verification a relever ensuite
        if ($w.Erase) { $ct.Current = $null; Start-Gw ([string[]]$w.Erase); return }
        $ct.Current = $w
        Start-Gw (Get-ContentWriteArgs $cal $w)
        return
    }
    $cal.WriteDurs += ((Get-Date) - $cal.PhaseStart).TotalSeconds
    $cal.Phase = 'read'; $cal.PhaseStart = Get-Date
    # 12.9 (D6) : relecture unique supprimee avant la relecture seulement sans relectures gardees (contentKeepMeasures 0)
    if ([int]$ct.Keep -le 0 -and (Test-Path -LiteralPath $cal.Scp)) { Remove-Item -LiteralPath $cal.Scp -Force }
    $script:Chain.Enqueue({ Invoke-ContentAnalysis })
    Start-Gw ([string[]]$cal.ReadArgs)
}

function Register-ContentWriteStop($cal, $w, $vStop) {
    # Arret de gw sur une piste refusee a la verification apres les nouveaux essais (A.7), $w : commande finie, $vStop :
    # @{ C ; H } (Get-GwVerifyStop). La piste en echec reste dans la mesure, a son niveau (sa marge basse est
    # l information cherchee ; l exclure favoriserait les niveaux qui reussissent). Cylindres suivants de la commande, non
    # ecrits : premier arret de la tete a cette passe (ContentResumeMax reprises), commande de reprise en tete de file,
    # memes valeurs, cylindres restants ; arret suivant : cylindres restants ecartes de cette passe (Skip 'nonecrite').
    # Arret annonce hors de la commande (autre tete ou cylindre absent, incoherence) : tous ses cylindres ecartes de cette
    # passe
    $ct = $cal.Content; $p = [int]$ct.Pass; $h = [int]$w.H
    $cs = [int[]]@($w.Cyls | Sort-Object)
    $sc = [int]$vStop.C; $sh = [int]$vStop.H
    if ($sh -ne $h -or $cs -notcontains $sc) {
        foreach ($c in $cs) { $ct.Skip["$p|$c|$h"] = 'nonecrite' }
        Append-Log ((T "Mesure sur l'image : arrêt de gw annoncé sur la piste {0}.{1}, hors de la commande de la tête {2} : cylindres {3} non écrits à cette passe, écartés de la mesure.") -f "$sc", "$sh", "$h", (Format-CylRanges $cs))
        return
    }
    $rest = [int[]]@($cs | Where-Object { $_ -gt $sc })
    if ($rest.Count -eq 0) {
        Append-Log ((T "Mesure sur l'image : gw s'est arrêté sur la piste {0}.{1} (vérification refusée après les nouveaux essais), dernière de la commande ; elle reste dans la mesure, à son niveau.") -f "$sc", "$h")
        return
    }
    $key = "$p|$h"
    $n = [int]$ct.Resumes[$key]
    if ($n -lt [int]$script:ContentResumeMax) {
        $ct.Resumes[$key] = $n + 1
        $ct.Todo.Insert(0, @{ H = $h; Cyls = $rest; Resume = $true })
        Append-Log ((T "Mesure sur l'image : gw s'est arrêté sur la piste {0}.{1} (vérification refusée après les nouveaux essais) ; elle reste dans la mesure, à son niveau. Reprise de la tête {1} aux cylindres {2}.") -f "$sc", "$h", (Format-CylRanges $rest))
        return
    }
    foreach ($c in $rest) { $ct.Skip["$p|$c|$h"] = 'nonecrite' }
    Append-Log ((T "Mesure sur l'image : nouvel arrêt de gw sur la tête {0} à cette passe (piste {1}.{0}) : cylindres {2} non écrits à cette passe, écartés de la mesure.") -f "$h", "$sc", (Format-CylRanges $rest))
}

function Get-ContentPassStats([string]$scp, $ct, [int]$pass) {
    # Bilan de la relecture d une passe (point de substitution des fins de test) : tours bruts du SCP (Read-ScpTrackRevs,
    # ScpStats.Decode), puis, pour chaque piste ecrite a la passe (cylindres de chaque tete dans le plan, sans les
    # cylindres non ecrits apres un arret de gw), marge fixe et comptes (Get-ContentTrackStats). Ecrit dans le pipeline une
    # lecture @{ C ; H ; P ; K ; W ; NRev ; Mfix ; N ; Z ; ZFrac ; Cells ; Flux } par piste ; piste absente du SCP : NRev = 0.
    # Fichier sans en-tete SCP : exception (relecture illisible, T-B25 dans Invoke-ContentAnalysis)
    $revs = Read-ScpTrackRevs $scp
    if ($null -eq $revs) { throw (T 'fichier sans en-tête SCP') }
    $ph = $ct.Plan.Pass[$pass]
    foreach ($h in 0, 1) {
        foreach ($c in @($ph.H[$h].Cyls)) {
            if ($ct.Skip.ContainsKey("$pass|$c|$h")) { continue }
            $tn = [int]$c * 2 + $h
            $tr = if ($revs.Tracks.ContainsKey($tn)) { $revs.Tracks[$tn] } else { $null }
            $st = Get-ContentTrackStats $tr ([int]$revs.Res) ([int]$ct.Ncell0)
            @{ C = [int]$c; H = $h; P = $pass; K = [double]$ph.H[$h].K[[int]$c]; W = [int]$ph.H[$h].W[[int]$c]; NRev = [int]$st.NRev; Mfix = [double]$st.Mfix
               N = [int64]$st.N; Z = [int64]$st.Z; ZFrac = [double]$st.ZFrac; Cells = $st.Cells; Flux = $st.Flux }
        }
    }
}

function Invoke-ContentAnalysis {
    # Fin de la relecture d une passe : SCP absent, sans en-tete SCP ou exception de lecture : T-B25 et arret
    # (Stop-PrecompCalib -GwError : Restore-CalibRetestPre rend $false hors du stade 'verify', mesure arretee, ecriture
    # annulee, rien n est enregistre, comme la mesure complete) ; sinon lectures ajoutees a la mesure, journal par tete,
    # passe suivante ou fin
    $cal = $script:Cal
    if (-not $cal -or [string]$cal.Mode -ne 'content') { return }
    $ct = $cal.Content
    $cal.ReadDurs += ((Get-Date) - $cal.PhaseStart).TotalSeconds
    $fail = (T "Mesure sur l'image : relecture absente ou illisible ({0}) : mesure arrêtée.")
    if (-not (Test-Path -LiteralPath $cal.Scp)) { Append-Log ($fail -f (T 'fichier absent')); Stop-PrecompCalib -GwError; return }
    try { $stats = @(Get-ContentPassStats ([string]$cal.Scp) $ct ([int]$ct.Pass)) }
    catch { Append-Log ($fail -f "$($_.Exception.Message)"); Stop-PrecompCalib -GwError; return }
    foreach ($s in $stats) { if ($null -ne $s) { $ct.Obs.Add($s) } }
    Write-ContentPassLog $cal $stats
    $cal.PassesDone++
    $script:ProgPlan = $null   # 12.11 : passe comptee : son plan est retire (270, Invoke-CalibAnalysis)
    $ct.Pass = [int]$ct.Pass + 1
    # 12.9 (D6) : fichier compagnon a jour apres chaque passe (statut « en cours » si la mesure s arrete ensuite)
    Save-ContentCompanion $cal 'en cours'
    if ([int]$ct.Pass -lt [int]$cal.TotalPasses) { New-ContentPass; return }
    # 12.9 (D3, critique § 3.3.4) : apres les 3 passes du plan, 4e passe aux niveaux 1,6 et 1 (alternes par bloc) si une
    # tete a un optimum k >= 0,9 ou pas de sommet (Test-ContentNeedFourth) ; une seule fois
    if ([int]$cal.TotalPasses -eq 3 -and -not $ct.Fourth) {
        # Revue de la phase B (mineur 5) : ajustements gardes pour Complete-ContentMeasure tant qu aucune passe ne s ajoute
        $hf = Get-ContentHeadFits $ct
        $ct.HF = $hf; $ct.HFPass = [int]$ct.Pass
        $nf = Test-ContentNeedFourth $hf.Fit
        if ($nf.Need) {
            $fp = Get-ContentFourthPass $ct.Plan ([int[]]@($ct.V[0])) ([int[]]@($ct.V[1])) ([int]$ct.Hard) $ct.PreSkip
            $ct.Plan.Pass = @(@($ct.Plan.Pass) + @($fp))
            $ct.Fourth = $true; $cal.TotalPasses = 4
            $m4 = Get-ContentMeasureMinutes ([int]$fp.NCylHead[0] + [int]$fp.NCylHead[1]) 1 -NoWarmup
            # Banc 12.9 (30/10/2026, defaut 3) : les deux tetes concernees : une seule ligne qui les nomme, groupees par
            # raison (deux lignes laissaient lire deux passes et le double de la duree) ; une tete : ligne inchangee
            $hs = [int[]]@($nf.Heads)
            if ($hs.Count -ge 2) {
                $hp = [int[]]@($hs | Where-Object { -not [double]::IsNaN([double]$nf.K[$_]) }); $hn = [int[]]@($hs | Where-Object { [double]::IsNaN([double]$nf.K[$_]) })
                if ($hp.Count -eq 0) { Append-Log ((T "Mesure sur l'image : marge sans sommet dans les niveaux mesurés (têtes {0} et {1}) : 4e passe aux niveaux 1,6 et 1 (environ {2} min de plus).") -f "$($hn[0])", "$($hn[1])", "$m4") }
                elseif ($hn.Count -eq 0) { Append-Log ((T "Mesure sur l'image : optimum au-dessus des niveaux mesurés (tête {0} : k ≈ {1} ; tête {2} : k ≈ {3}) : 4e passe aux niveaux 1,6 et 1 (environ {4} min de plus).") -f "$($hp[0])", (Format-UiNum ([double]$nf.K[$hp[0]]) '0.00'), "$($hp[1])", (Format-UiNum ([double]$nf.K[$hp[1]]) '0.00'), "$m4") }
                else { Append-Log ((T "Mesure sur l'image : optimum au-dessus des niveaux mesurés (tête {0} : k ≈ {1}) et marge sans sommet (tête {2}) : 4e passe aux niveaux 1,6 et 1 (environ {3} min de plus).") -f "$($hp[0])", (Format-UiNum ([double]$nf.K[$hp[0]]) '0.00'), "$($hn[0])", "$m4") }
            }
            else {
                foreach ($h in $hs) {
                    $kh = [double]$nf.K[$h]
                    if ([double]::IsNaN($kh)) { Append-Log ((T "Mesure sur l'image : marge sans sommet dans les niveaux mesurés (tête {0}) : 4e passe aux niveaux 1,6 et 1 (environ {1} min de plus).") -f "$h", "$m4") }
                    else { Append-Log ((T "Mesure sur l'image : optimum au-dessus des niveaux mesurés (tête {0} : k ≈ {1}) : 4e passe aux niveaux 1,6 et 1 (environ {2} min de plus).") -f "$h", (Format-UiNum $kh '0.00'), "$m4") }
                }
            }
            New-ContentPass
            return
        }
    }
    Complete-ContentMeasure $cal
}

function Get-ContentHeadFits($ct) {
    # 12.9 : exclusions apres la relecture (Get-ContentExclusions, a tous les niveaux) et lignes retenues par tete @{ P ; C ;
    # K ; W (precomp ecrite) ; V (courbe du lecteur au cylindre, bornee a 0..Hard comme le plan) ; Y = Mfix }, sans les
    # pistes exclues ni les lectures sans tour ; puis, par tete aux donnees suffisantes (Get-ContentHeadCheck), poids de
    # Huber et ajustement « K-ns » (Get-ContentFactorNs, etat compris). Rend @{ Ex ; Rows ; HC ; W ; Fit } (tables par tete,
    # Fit $null sans donnees suffisantes)
    $ex = Get-ContentExclusions $ct.Obs ([double]$script:ContentZMax) ([double]$script:ContentCellsTol) ([double]$script:ContentFluxMin)
    $rows = @{ 0 = @(); 1 = @() }
    foreach ($o in $ct.Obs) {
        if ($null -eq $o) { continue }
        $h = [int]$o.H; $c = [int]$o.C
        if ($ex.ContainsKey("$c.$h") -or [int]$o.NRev -le 0 -or [double]::IsNaN([double]$o.Mfix)) { continue }
        $vv = @($ct.V[$h]); $vc = 0.0
        if ($vv.Count -gt 0) { $vc = if ($c -lt $vv.Count) { [double]$vv[$c] } else { [double]$vv[$vv.Count - 1] } }
        $vc = [math]::Max(0.0, [math]::Min([double]$ct.Hard, $vc))
        $rows[$h] += ,@{ P = [string]$o.P; C = $c; K = [double]$o.K; W = [int]$o.W; V = $vc; Y = [double]$o.Mfix }
    }
    $hc = @{}; $wts = @{}; $fit = @{ 0 = $null; 1 = $null }
    foreach ($h in 0, 1) {
        $hc[$h] = Get-ContentHeadCheck $rows[$h] ([int]$script:ContentMinCyl) ([int]$script:ContentMinLevelCyl)
        if ($hc[$h].Ok) { $wts[$h] = Get-ContentHuberWeights $rows[$h]; $fit[$h] = Get-ContentFactorNs $rows[$h] $wts[$h] }
    }
    return @{ Ex = $ex; Rows = $rows; HC = $hc; W = $wts; Fit = $fit }
}

function Get-ContentCompanion($cal, [string]$status) {
    # 12.9 (D6) : contenu du fichier compagnon JSON d une mesure sur l image : versions, lecteur, marque, image, famille,
    # niveaux, plan (k et precomp ecrite par passe, tete et cylindre), lectures (Mfix, N, Z, tours par piste et par passe),
    # exclusions (avant l ecriture, cylindres non ecrits), resultat par tete (Content.Res, Complete-ContentMeasure) et
    # statut ('en cours', 'terminee', 'arretee'). Nombres non finis ecrits null ; aucune cle numerique (ConvertTo-Json de
    # Windows PowerShell 5.1). Revue de la phase B (mineur 6) : low, liste vide (et non [""]) pour une tete non mesuree
    $ct = $cal.Content
    $plan = @(for ($p = 0; $p -lt @($ct.Plan.Pass).Count; $p++) {
        foreach ($h in 0, 1) {
            $ph = $ct.Plan.Pass[$p].H[$h]; $cs = [int[]]@($ph.Cyls)
            [ordered]@{ p = $p + 1; h = $h; c = $cs; k = [double[]]@($cs | ForEach-Object { [double]$ph.K[$_] }); w = [int[]]@($cs | ForEach-Object { [int]$ph.W[$_] }) }
        }
    })
    $reads = @(foreach ($o in $ct.Obs) {
        if ($null -eq $o) { continue }
        [ordered]@{ p = [int]$o.P + 1; c = [int]$o.C; h = [int]$o.H; k = [double]$o.K; w = [int]$o.W; nRev = [int]$o.NRev
                    mfix = (ConvertTo-FiniteOrNull $o.Mfix); n = [int64]$o.N; z = [int64]$o.Z }
    })
    $res = @(foreach ($r in @($ct.Res)) {
        if ($null -eq $r) { continue }
        [ordered]@{ h = [int]$r.H; etat = [string]$r.Etat; k = (ConvertTo-FiniteOrNull $r.K); seK = (ConvertTo-FiniteOrNull $r.SeK); q = (ConvertTo-FiniteOrNull $r.Q)
                    tQ = (ConvertTo-FiniteOrNull $r.TQ); chi2Ddl = (ConvertTo-FiniteOrNull $r.Chi2Ddl); s = (ConvertTo-FiniteOrNull $r.S); nCyl = [int]$r.NCyl; nObs = [int]$r.N
                    kApplied = (ConvertTo-FiniteOrNull $r.KApplied); src = [string]$r.Src; low = [string[]]@(@($r.LowTxt) | Where-Object { $_ })
                    zones = @(@($r.Zones) | Where-Object { $null -ne $_ } | ForEach-Object { [ordered]@{ z = [int]$_.Z; v = (ConvertTo-FiniteOrNull $_.V); x = (ConvertTo-FiniteOrNull $_.X); seX = (ConvertTo-FiniteOrNull $_.SeX) } }) }
    })
    $ne = @(@($ct.Skip.Keys) | Sort-Object | ForEach-Object { [string]$_ })
    $pre = @(@($ct.PreSkip.Keys) | Sort-Object | ForEach-Object { "$_=$($ct.PreSkip[$_])" })
    return [ordered]@{ status = $status; version = [string]$script:Version; contentCalc = [string]$script:ContentCalc; calibCalc = [string]$script:CalibCalc
                       drive = [string]$cal.Drive; brand = [string]$ct.Brand; image = [System.IO.Path]::GetFileName([string]$cal.Image); family = [string]$ct.Fam
                       stamp = [string]$ct.Stamp; levels = [double[]]@($ct.Levels); fourth = [bool]$ct.Fourth; hard = [int]$ct.Hard
                       curves = [ordered]@{ h0 = [int[]]@($ct.V[0]); h1 = [int[]]@($ct.V[1]) }
                       plan = $plan; reads = $reads; preSkip = $pre; notWritten = $ne; result = $res }
}

function Save-ContentCompanion($cal, [string]$status) {
    # 12.9 (D6) : ecrit le fichier compagnon JSON (Get-ContentCompanion) a cote des relectures gardees, UTF-8 sans BOM ;
    # rien sans relectures gardees (contentKeepMeasures 0) ; echec d ecriture ignore (la mesure continue). Appele apres
    # chaque passe ('en cours'), en fin de mesure ('terminee') et a l arret (Stop-PrecompCalib, 'arretee')
    if (-not $cal -or -not $cal.Content -or [int]$cal.Content.Keep -le 0) { return }
    $ct = $cal.Content
    try {
        $path = Get-ContentScpPath ([string]$ct.Dir) ([string]$ct.Stamp) ([string]$cal.Drive) 0
        $js = ConvertTo-Json -InputObject (Get-ContentCompanion $cal $status) -Depth 6
        [System.IO.File]::WriteAllText($path, $js, (New-Object System.Text.UTF8Encoding($false)))
    } catch { }
}

function Write-ContentPassLog($cal, $stats) {
    # Lectures d une passe au journal, une ligne par tete, format stable lu par script (T-B10) : elements
    # « c<cylindre> <niveau k> <precomp ecrite> -> <marge fixe> », en ns, k a deux decimales et Mfix a une, au format de la
    # langue (Format-UiNum) ; piste sans tour exploitable : « -> - » ; cylindres croissants, separes par « ; »
    $p = [int]$cal.Content.Pass
    foreach ($h in 0, 1) {
        $items = @(@($stats) | Where-Object { $null -ne $_ -and [int]$_.H -eq $h } | Sort-Object { [int]$_.C } | ForEach-Object {
            $m = if ([int]$_.NRev -le 0 -or [double]::IsNaN([double]$_.Mfix)) { '-' } else { Format-UiNum ([double]$_.Mfix) '0.0' }
            "c$($_.C) $(Format-UiNum ([double]$_.K) '0.00') $($_.W) -> $m"
        })
        if ($items.Count -eq 0) { continue }
        Append-Log ((T "[tête {0}] Mesure sur l'image, passe {1}/{2} (cylindre, niveau, précomp écrite -> marge fixe, ns) : {3}") -f "$h", "$($p + 1)", "$($cal.TotalPasses)", ($items -join ' ; '))
    }
}

function Complete-ContentMeasure($cal) {
    # Fin de la mesure (A.10). Exclusions apres la relecture (Get-ContentExclusions, aux 3 niveaux), puis lignes retenues
    # par tete (sans les pistes exclues, avant ou apres l ecriture, ni les cylindres non ecrits, ni les lectures sans tour)
    # ; donnees minimales (Get-ContentHeadCheck), puis facteur k* (Get-ContentFactorNs, 12.9) ; tete non
    # mesuree : k du lecteur (Get-DriveK). Journal : pistes ecartees par raison (T-B14), facteur et reserves de chaque tete
    # (T-B15 a T-B19). Pas de fenetre de decision : le resultat est applique. Enregistrements de mesure des tetes mesurees
    # (C.2 : k du lecteur des ecritures suivantes, Add-ContentMeasure, Save-Config), puis facteur de l ecriture qui suit
    # ($script:WriteFactorNext, lu une fois par Start-ImageWrite) et ecriture de l image ; prechauffage de l ecriture lente
    # reduit ou saute, le lecteur venant de servir (comme Complete-DiskMeasure)
    # 12.9 (critique § 3.3.5) : lignes avec la precomp ecrite et la courbe, poids de Huber, ajustement « K-ns » et etat de
    # chaque tete (Get-ContentHeadFits) ; journal : resultat, optimums par zone, etat, pistes peu prises en compte ;
    # facteur applique selon l etat (Get-ContentAppliedK : k borne a [0 ; 2], sinon k memorise de la marque, sinon 1) ;
    # enregistrements avec la marque et l etat ; fichier compagnon JSON (D6)
    $ct = $cal.Content; $drive = [string]$cal.Drive; $fam = [string]$cal.Family
    # Revue de la phase B (mineur 5) : ajustements du test de la 4e passe repris s ils portent sur les memes passes
    $hf = if ($ct.HF -and [int]$ct.HFPass -eq [int]$ct.Pass) { $ct.HF } else { Get-ContentHeadFits $ct }
    $ex = $hf.Ex
    # Pistes ecartees, par raison : avant l ecriture (PreSkip), apres la relecture (exclusions), non ecrites a une passe
    $byWhy = [ordered]@{ absente = @(); longue = @(); protegee = @(); vide = @(); longueur = @(); nonmfm = @(); nonecrite = @() }
    foreach ($k in @($ct.PreSkip.Keys)) { $wy = [string]$ct.PreSkip[$k]; if ($byWhy.Contains($wy)) { $byWhy[$wy] += [string]$k } }
    foreach ($k in @($ex.Keys)) { $wy = [string]$ex[$k]; if ($byWhy.Contains($wy)) { $byWhy[$wy] += [string]$k } }
    $ne = @{}
    foreach ($k in @($ct.Skip.Keys)) { $pp = ([string]$k) -split '\|'; $ne["$($pp[1]).$($pp[2])"] = $true }
    $byWhy['nonecrite'] = @($ne.Keys)
    $whyTxt = @{ absente = (T "absentes de l'image : {0}"); longue = (T 'longues : {0}'); protegee = (T 'protégées (IPF) : {0}'); vide = (T 'vides ou effacées : {0}')
                 longueur = (T 'longueur hors norme : {0}'); nonmfm = (T 'non MFM ou illisibles à tous les niveaux : {0}'); nonecrite = (T 'non écrites (arrêt de gw) : {0}') }
    $parts = @(foreach ($wy in @($byWhy.Keys)) { if (@($byWhy[$wy]).Count -gt 0) { $whyTxt[$wy] -f (Format-TrackList (Sort-TrackKeys @($byWhy[$wy]))) } })
    if ($parts.Count -gt 0) { Append-Log ((T "Mesure sur l'image : pistes écartées : {0}.") -f ($parts -join ' ; ')) }
    $date = Get-Date -Format 'dd/MM/yyyy HH:mm'
    $brand = [string]$ct.Brand
    $kk = @{ 0 = 1.0; 1 = 1.0 }; $src = @{ 0 = 'defaut'; 1 = 'defaut' }; $recs = @(); $res = @(); $sum = @{}
    $kMax = if ([double]$script:ContentKMax -gt 0) { [double]$script:ContentKMax } else { 2.0 }
    foreach ($h in 0, 1) {
        $pre = (T '[tête {0}] ') -f "$h"
        $hc = $hf.HC[$h]; $fit = $hf.Fit[$h]
        # k memorise du lecteur pour la marque (avant l enregistrement de cette mesure), repli des etats plate, peu, echec
        $dr = Get-DriveK $drive $fam $h $brand
        $mem = if ([string]$dr.Src -eq 'lecteur') { [double]$dr.K } else { $null }
        if ($fit -and $fit.Ok) {
            $etat = [string]$fit.Etat
            $ap = Get-ContentAppliedK $etat ([double]$fit.K) $mem $kMax
            $kk[$h] = [double]$ap.K; $src[$h] = [string]$ap.Src
            Append-Log ((T '{0}Facteur mesuré : k = {1} ± {2} (courbure commune en ns {3} /ns, t = {4} ; écart entre zones χ²/ddl {5} ; {6} cylindres, {7} pistes dont {8} pondérées ; écart-type résiduel {9} ns).') -f "$pre", (Format-ContentNum $fit.K '0.00'), (Format-ContentNum $fit.SeK '0.00'), (Format-ContentNum $fit.Q '0.0000'), (Format-ContentNum $fit.TQ '0.0'), (Format-ContentNum $fit.Chi2Ddl '0.0'), "$($fit.NCyl)", "$($fit.N)", "$($fit.NPond)", (Format-ContentNum $fit.S '0.0'))
            if (@($fit.Zones).Count -gt 0) { Append-Log ((T '{0}Optimums par zone (cylindres : k) : {1}.') -f "$pre", ((@($fit.Zones) | ForEach-Object { "c$($_.Cyl) : $(Format-ContentNum $_.K '0.00')" }) -join ' ; ')) }
            $kAp = Format-UiNum ([double]$ap.K) '0.00'
            $apTxt = Get-ContentBrandKText $dr
            switch ($etat) {
                'plate' { Append-Log ((T '{0}Marge plate : la marge de lecture varie trop peu avec le niveau de précompensation pour situer l''optimum (t = {1}, il faut au moins 2). Facteur appliqué : {2}.') -f "$pre", (Format-ContentNum $fit.TQ '0.0'), "$apTxt") }
                'peu' { Append-Log ((T '{0}Facteur peu déterminé : k = {1} ± {2} (incertitude au-delà de 0,25). Facteur appliqué : {3}.') -f "$pre", (Format-ContentNum $fit.K '0.00'), (Format-ContentNum $fit.SeK '0.00'), "$apTxt") }
                'haute' { Append-Log ((T '{0}Optimum au-delà de la borne {1} du facteur : k = {1} retenu.') -f "$pre", (Format-UiNum $kMax '0.##')) }
                'basse' { Append-Log ((T '{0}Optimum au-delà de la borne {1} du facteur : k = {1} retenu.') -f "$pre", (Format-UiNum 0.0 '0.##')) }
            }
            $lowTxt = [string[]]@(@($fit.Low) | ForEach-Object { "c$($_.C) p$([int]$_.P + 1)" })
            if ($lowTxt.Count -gt 0) { Append-Log ((T '{0}Pistes à marge anormale, moins prises en compte : {1}.') -f "$pre", ($lowTxt -join ' ; ')) }
            $sum[$h] = switch ($etat) {
                'plate' { if ([string]$ap.Src -eq 'lecteur') { (T 'marge plate, k {0} de la marque') -f "$kAp" } else { (T 'k 1 par défaut') } }
                'peu' { if ([string]$ap.Src -eq 'lecteur') { (T 'peu déterminé, k {0} de la marque') -f "$kAp" } else { (T 'k 1 par défaut') } }
                default { (T 'k {0} mesuré') -f "$kAp" }
            }
            # Enregistrement de mesure (C.2) avec la marque et l etat : k mesure (borne a [0 ; kMax] sauf marge plate ou peu
            # determinee), courbe ecrite W_h = facteur applique x V_h, bornee a 0..max(borne, v) (Get-ContentScaledValues)
            $f = [double](Limit-WriteFactor ([double]$ap.K) ([double]$script:ContentFMax)).F   # 12.10 : sans la correction Dk
            $vals = Get-ContentScaledValues @($ct.V[$h]) $f ([int]$ct.Hard)
            $nEx = @(@(@($ct.PreSkip.Keys) + @($ex.Keys)) | Where-Object { (([string]$_) -split '\.')[1] -eq "$h" }).Count
            $kr = [double]$fit.K
            if (@('mesure', 'haute', 'basse') -contains $etat) { $kr = [math]::Min([math]::Max($kr, 0.0), $kMax) }
            $recs += ,@{ Model = 'contenu'; Drive = $drive; Family = $fam; Head = $h; Date = $date; Image = [System.IO.Path]::GetFileName([string]$cal.Image)
                         K = $(if ([double]::IsNaN($kr)) { $kr } else { [math]::Round($kr, 3) }); KVertex = $(if ([double]::IsNaN([double]$fit.K)) { $null } else { [math]::Round([double]$fit.K, 3) })
                         Bound = $(switch ($etat) { 'haute' { 'high' } 'basse' { 'low' } default { '' } }); Flat = ($etat -eq 'plate')
                         SeK = [double]$fit.SeK; B1 = [double]::NaN; B2 = [double]::NaN; Gain = [double]::NaN; S = [double]$fit.S
                         NCyl = [int]$fit.NCyl; NObs = [int]$fit.N; NExcl = [int]$nEx; Levels = [double[]]@($ct.Levels); F = $f
                         Values = $vals; Spec = (Build-CurveProfile $vals); RefKey = [string]$ct.RefKeys[$h]; RefDate = [string]$ct.RefDates[$h]
                         Calc = [string]$script:CalibCalc; ContentCalc = [string]$script:ContentCalc; Version = [string]$script:Version
                         Brand = $brand; Etat = $etat; Q = [double]$fit.Q; TQ = [double]$fit.TQ; Chi2Ddl = [double]$fit.Chi2Ddl; NPass = @($ct.Plan.Pass).Count
                         Zones = @(@($fit.Zones) | ForEach-Object { @{ Z = [int]$_.Z; K = [double]$_.K } }) }
            $res += ,@{ H = $h; Etat = $etat; K = [double]$fit.K; SeK = [double]$fit.SeK; Q = [double]$fit.Q; TQ = [double]$fit.TQ; Chi2Ddl = [double]$fit.Chi2Ddl
                        S = [double]$fit.S; NCyl = [int]$fit.NCyl; N = [int]$fit.N; KApplied = [double]$ap.K; Src = [string]$ap.Src; LowTxt = $lowTxt; Zones = @($fit.Zones) }
        } else {
            # Tete non mesuree (donnees insuffisantes ou ajustement impossible) : k memorise du lecteur pour la marque, 1 sans
            # mesure de la marque (jamais celui d une autre marque)
            $kk[$h] = [double]$dr.K; $src[$h] = [string]$dr.Src
            $why = if (-not $hc.Ok -and [string]$hc.Why -eq 'peu') { (T 'trop peu de pistes exploitables ({0} cylindres)') -f "$($hc.NCyl)" } else { (T 'ajustement impossible') }
            Append-Log ((T '{0}Facteur non mesuré ({1}) : facteur du lecteur appliqué ({2}).') -f "$pre", "$why", (Get-ContentBrandKText $dr))
            $sum[$h] = if ([string]$dr.Src -eq 'lecteur') { (T 'non mesuré, k {0} de la marque') -f (Format-UiNum ([double]$dr.K) '0.00') } else { (T 'k 1 par défaut') }
            $res += ,@{ H = $h; Etat = 'echec'; K = [double]::NaN; KApplied = [double]$dr.K; Src = [string]$dr.Src }
        }
    }
    $ct.Res = $res
    foreach ($rc in $recs) { Add-ContentMeasure $rc }
    if ($recs.Count -gt 0 -and -not $script:Restore) { [void](Save-Config) }
    # Complement « facteur applique » du libelle du profil refait avec le nouveau k du lecteur (revue 12.8.1, point 6)
    if ($recs.Count -gt 0) { Update-WriteFactorNote }
    Save-ContentCompanion $cal 'terminee'
    $el = if ($cal.StartTime -is [datetime]) { ((Get-Date) - $cal.StartTime).TotalSeconds } else { 0 }
    $durTxt = Format-CalDuration $el
    $pbWCal.Visible = $false
    $lblWCal.Text = ((T "Mesure sur l'image terminée en {0} : tête 0 {1}, tête 1 {2}.") -f "$durTxt", "$($sum[0])", "$($sum[1])")
    $script:Cal = $null
    if ($script:AfterCalib -ne 'write') { $script:WriteFactorNext = $null; return }
    $script:AfterCalib = ''
    $script:WriteFactorNext = @{ Drive = $drive; Fam = $fam; Img = [string]$cal.Image; K = @{ 0 = [double]$kk[0]; 1 = [double]$kk[1] }
                                 Src = @{ 0 = [string]$src[0]; 1 = [string]$src[1] }; Date = $date; Brand = $brand }
    Append-Log ((T "Mesure de la disquette sur l'image terminée en {0} : écriture de l'image avec le facteur mesuré.") -f "$durTxt")
    Start-ImageWrite -NoWarmup:([bool]$cal.WarmSkip)
}
# ============================== FONCTIONS : CALIBRATION : CONTROLE DE SURFACE ET DE VITESSE ===

# 12.7 : controle de surface de la disquette de calibration a la passe 1 (fonctions pures, appelees par Invoke-CalibAnalysis
# et Complete-PrecompCalib). Defaut grossier (arbitrage 1) : fenetre sans compte a rebours pendant la calibration ;
# disquette douteuse sans defaut grossier : reserve « support » de la fenetre de decision ; bilan par face toujours au journal
function Get-CalibSurface($tracks, [int[]]$cyls) {
    # Controle de surface de la disquette de calibration sur la relecture de la passe 1 (motif ecrit aux niveaux de la
    # passe 1, 3 tours) :
    # par face et par cylindre teste, trous de signal (Dropouts), hors classe (OutOfClass, juges seulement sous
    # CalSurfShiftMax ns de decalage), ecart du nombre de flux entre tours (NFlux), piste illisible (absente ou sans tour
    # mesurable). Face douteuse : CalSurfMinBad pistes defectueuses au moins, ou CalSurfFrac des cylindres testes, ou
    # CalSurfRun cylindres testes consecutifs, ou hors classe sur toute la face. Seuils provisoires (H). Par face aussi :
    # tours avec trous de signal (DropTot) sur les tours relus (RevTot), pour le journal.
    $res = @{ Faces = @{}; Bad = @(); Defective = $false; Why = @() }
    foreach ($h in 0, 1) {
        $rows = @()
        foreach ($c in $cyls) {
            $tn = [int]$c * 2 + $h
            $r = @{ C = [int]$c; Missing = $true; Valid = 0; NRev = 0; DropRevs = 0; Ooc = 0.0; Stab = 0; Shift = [double]::NaN }
            if ($tracks.ContainsKey($tn)) {
                $revs = @($tracks[$tn] | Where-Object { $null -ne $_ })
                $r.NRev = $revs.Count; $r.Missing = ($revs.Count -eq 0)
                $sh = @(); $oc = @(); $nf = @()
                foreach ($x in $revs) {
                    if ([int]$x.Dropouts -gt 0) { $r.DropRevs++ }
                    $oc += [double]$x.OutOfClass; $nf += [int]$x.NFlux
                    if ($null -ne $x.Shift -and -not [double]::IsNaN([double]$x.Shift)) { $sh += [double]$x.Shift }
                }
                $r.Valid = $sh.Count
                if ($oc.Count -gt 0) { $r.Ooc = Get-Median $oc }
                if ($nf.Count -gt 0) { $r.Stab = [int](($nf | Measure-Object -Maximum).Maximum - ($nf | Measure-Object -Minimum).Minimum) }
                if ($sh.Count -gt 0) { $r.Shift = ($sh | Measure-Object -Average).Average }
            }
            $rows += $r
        }
        # Reference de la face : pistes mesurables (et, pour les hors classe, de decalage jugeable)
        $ok = @($rows | Where-Object { $_.Valid -gt 0 })
        $jo = @($ok | Where-Object { [math]::Abs($_.Shift) -le $script:CalSurfShiftMax })
        $mo = if ($jo.Count) { Get-Median @($jo | ForEach-Object { $_.Ooc }) } else { 0.0 }
        $ao = if ($jo.Count) { 1.4826 * (Get-Median @($jo | ForEach-Object { [math]::Abs($_.Ooc - $mo) })) } else { 0.0 }
        $ms = if ($ok.Count) { Get-Median @($ok | ForEach-Object { $_.Stab }) } else { 0.0 }
        $as = if ($ok.Count) { 1.4826 * (Get-Median @($ok | ForEach-Object { [math]::Abs($_.Stab - $ms) })) } else { 0.0 }
        $to = [math]::Max([double]$script:CalSurfOocFloor, $mo + $script:CalSurfMadK * [math]::Max(1.0, $ao))
        $ts = [math]::Max([double]$script:CalSurfStabFloor, $ms + $script:CalSurfMadK * [math]::Max(1.0, $as))
        $bad = @(); $part = @(); $nj = @(); $run = 0; $top = 0; $smax = 0; $dt = 0; $rt = 0
        foreach ($r in $rows) {
            $why = @()
            $dt += [int]$r.DropRevs; $rt += [int]$r.NRev
            if ($r.Missing -or $r.Valid -eq 0) { $why += 'unread' }
            else {
                if ($r.Valid -lt $r.NRev) { $part += $r.C }
                if ($r.DropRevs -ge $script:CalSurfDropRevs) { $why += 'drop' }
                if ([math]::Abs($r.Shift) -gt $script:CalSurfShiftMax) { $nj += $r.C }
                elseif ($r.Ooc -gt $to) { $why += 'ooc' }
                if ($r.Stab -gt $ts) { $why += 'stab' }
                if ($r.Stab -gt $smax) { $smax = $r.Stab }
            }
            if ($why.Count) { $bad += @{ C = $r.C; H = $h; Why = $why }; $run++; if ($run -gt $top) { $top = $run } } else { $run = 0 }
        }
        $need = [math]::Max([int]$script:CalSurfMinBad, [int][math]::Ceiling($script:CalSurfFrac * $rows.Count))
        $noisy = ($jo.Count -ge 3 -and $mo -gt $script:CalSurfOocFloor)
        $def = ($bad.Count -ge $need) -or ($top -ge $script:CalSurfRun) -or $noisy
        $res.Faces[$h] = @{ N = $rows.Count; Bad = $bad; Part = $part; NotJudged = $nj; OocMed = $mo; OocThr = $to; StabMax = $smax; StabThr = $ts; Run = $top; Need = $need; Noisy = $noisy; Defective = $def
                            DropTot = $dt; RevTot = $rt }
        $res.Bad += $bad
        if ($def) { $res.Defective = $true; $res.Why += $h }
    }
    return $res
}

function Get-CalibSurfaceOptions([bool]$restore, [bool]$redo, [bool]$toWrite, [bool]$swap) {
    # Boutons et texte de la fenetre du controle de surface selon le contexte. Restauration sans disquette sacrifiee :
    # la destination, deja sondee, ne peut pas etre changee ici.
    if ($restore) { return @{ Change = $swap; SwapBox = $false; Variant = $(if ($swap) { 'restore-swap' } else { 'restore' }) } }
    if ($redo) { return @{ Change = $true; SwapBox = $false; Variant = 'redo' } }
    if ($toWrite -and $swap) { return @{ Change = $true; SwapBox = $false; Variant = 'swap' } }
    if ($toWrite) { return @{ Change = $true; SwapBox = $true; Variant = 'write' } }
    return @{ Change = $true; SwapBox = $false; Variant = 'normal' }
}

function Get-CalibSurfaceReasons($bad) {
    # Defauts d une face regroupes par nature : « trous de signal aux cylindres 9-11 ; illisible aux cylindres 40 »
    $names = [ordered]@{ unread = (T 'illisible'); drop = (T 'trous de signal'); ooc = (T 'intervalles hors classe'); stab = (T "lecture différente d'un tour à l'autre") }
    $parts = @()
    foreach ($k in @($names.Keys)) {
        $cs = [int[]]@(@($bad) | Where-Object { @($_.Why) -contains $k } | ForEach-Object { [int]$_.C } | Sort-Object -Unique)
        if ($cs.Count) { $parts += ((T "{0} aux cylindres {1}") -f "$($names[$k])", (Format-CylList $cs)) }
    }
    return ($parts -join ' ; ')
}

function Format-CalibSurfaceShort($sf) {
    # Resume du verdict : « face 1 : 3 piste(s) défectueuse(s) sur 80 ; face 0 : hors classe sur toute la face »
    $p = @()
    foreach ($h in 0, 1) {
        $f = $sf.Faces[$h]
        if (-not $f -or -not $f.Defective) { continue }
        if ($f.Noisy) { $p += ((T "face {0} : hors classe sur toute la face") -f "$h") }
        else { $p += ((T "face {0} : {1} piste(s) défectueuse(s) sur {2}") -f "$h", "$(@($f.Bad).Count)", "$($f.N)") }
    }
    return ($p -join ' ; ')
}

function Get-CalibSurfaceFaceLines($sf) {
    # Bilan de chaque face, tous ses compteurs (journal ; 12.7 point 5 : fenetre de la disquette a ecrire)
    $faces = @()
    foreach ($h in 0, 1) {
        $f = $sf.Faces[$h]
        $det = if (@($f.Bad).Count) { ' (' + (Get-CalibSurfaceReasons $f.Bad) + ')' } else { '' }
        $s = (T "face {0} : {1} cylindres, {2} défectueux{3}, trous de signal dans {4} tour(s) sur {5}, hors classe {6} par tour en médiane (seuil {7}), écart du nombre de flux entre tours jusqu'à {8} (seuil {9})") -f "$h", "$($f.N)", "$(@($f.Bad).Count)", $det, "$([int]$f.DropTot)", "$([int]$f.RevTot)", (Format-UiNum $f.OocMed), (Format-UiNum $f.OocThr), "$($f.StabMax)", (Format-UiNum $f.StabThr)
        if (@($f.NotJudged).Count) { $s += (T ", non jugés sur les hors classe aux cylindres {0} (décalage au-delà de {1} ns)") -f (Format-CylList ([int[]]$f.NotJudged)), "$($script:CalSurfShiftMax)" }
        if (@($f.Part).Count) { $s += (T ", lecture partielle aux cylindres {0}") -f (Format-CylList ([int[]]$f.Part)) }
        $faces += $s
    }
    return ,$faces
}

function Format-CalibSurfaceFaceDefect($f, [int]$h) {
    # 12.7, arbitrage 14 : defauts d une face douteuse dans la fenetre du controle de surface, avec tous les compteurs
    # releves : hors classe sur toute la face, pistes defectueuses par nature, tours avec trous de signal
    $p = @()
    if ($f.Noisy) { $p += ((T 'intervalles hors classe sur toute la face ({0} par tour en médiane)') -f (Format-UiNum $f.OocMed)) }
    if (@($f.Bad).Count) { $p += (Get-CalibSurfaceReasons $f.Bad) }
    if ([int]$f.DropTot -gt 0) { $p += ((T 'trous de signal dans {0} tour(s) sur {1}') -f "$([int]$f.DropTot)", "$([int]$f.RevTot)") }
    return ((T "face {0} : {1}") -f "$h", ($p -join ' ; '))
}

function Test-CalibCleanHint($sf, $mc, [bool]$hd) {
    # 12.7, arbitrage 14 : conseil de nettoyer les tetes seulement pour des trous de signal (pistes defectueuses par trous
    # reproductibles) sur les deux faces d un support a la bonne densite : vitesse et densite relues conformes
    # (Get-CalibMediumCheck). Jamais en haute densite : des trous sur les deux faces y viennent le plus souvent d une
    # disquette double densite, que le nombre de flux relu ne distingue pas (cas D2 de l addendum HD : flux a 99 %, cas X3
    # de cross127) ; le paragraphe haute densite de la fenetre donne alors la cause probable
    if ($hd) { return $false }
    foreach ($h in 0, 1) {
        $f = $sf.Faces[$h]
        if (-not $f -or @(@($f.Bad) | Where-Object { @($_.Why) -contains 'drop' }).Count -eq 0) { return $false }
    }
    if ($mc -and ($mc.Flux -or $mc.Rot)) { return $false }
    return $true
}

function Format-CalibSurfaceLog($sf, [bool]$std, [string]$verdict = 'hold', [bool]$Mixed = $false) {
    # Lignes du journal : bilan des deux faces (toujours, donnees pour recaler les seuils), puis verdict. $verdict : 'hold'
    # (disquette douteuse : decision demandee), 'reserve' (douteuse sans defaut grossier : reserve au bilan, arbitrage 1 de
    # la 12.7), 'none' (bilan seul : l appelant ecrit le verdict d un defaut grossier). 12.9 (correction 2) : $Mixed, passe 1
    # en carre latin (niveaux repartis par cylindre, double densite) : texte sans « sans precompensation »
    $faces = Get-CalibSurfaceFaceLines $sf
    $sfx = if ($std) { (T ' ; contrôle partiel en test standard, cylindres de test seulement') } else { '' }
    $fmt = if ($Mixed) { (T "Contrôle de surface (passe 1, motif de test relu sur 3 tours) : {0}{1}.") } else { (T "Contrôle de surface (passe 1, motif écrit sans précompensation) : {0}{1}.") }
    $lines = @($fmt -f ($faces -join ' ; '), $sfx)
    if ($verdict -eq 'none') { return ,$lines }
    if ($sf.Defective) {
        if ($verdict -eq 'reserve') { $lines += ((T "Contrôle de surface : disquette de calibration douteuse ({0}) ; la calibration continue, avec une réserve au bilan.") -f (Format-CalibSurfaceShort $sf)) }
        else { $lines += ((T "Contrôle de surface : disquette de calibration douteuse ({0}) : décision demandée.") -f (Format-CalibSurfaceShort $sf)) }
    }
    elseif (@($sf.Bad).Count) {
        $p = @(); foreach ($h in 0, 1) { $b = @($sf.Faces[$h].Bad); if ($b.Count) { $p += ((T "face {0} : {1}") -f "$h", (Get-CalibSurfaceReasons $b)) } }
        $lines += ((T "Contrôle de surface : défaut ponctuel de la disquette de calibration ({0}) ; la calibration continue.") -f ($p -join ' ; '))
    }
    return ,$lines
}

function Get-CalibSurfaceText($sf, $opt, [bool]$std, [bool]$autoStart, [string[]]$Extra = @(), [string[]]$Notes = @(), $Medium = $null, [bool]$Hd = $false, [bool]$Mixed = $false) {
    # Texte de la fenetre du controle de surface (lblSurfText). Extra : lignes de la vitesse du lecteur et de la densite
    # relue (Get-CalibMediumCheck) apres celles des faces ; Notes : paragraphes qui les expliquent. 12.7 : $opt.Speed (defaut
    # de vitesse seul, Test-CalibSpeedOnly) : en-tete qui nomme le lecteur, sans la phrase sur le support ; $opt.Change
    # faux hors restauration : premiere ligne des choix (« Changer de disquette ») retiree. Arbitrage 14 : chaque face
    # douteuse avec tous ses compteurs (Format-CalibSurfaceFaceDefect) ; conseil de nettoyer les tetes seulement pour des
    # trous de signal sur les deux faces a la bonne densite (Test-CalibCleanHint ; Medium, Hd : famille haute densite)
    $spd = [bool]$opt.Speed
    # 12.9 (correction 2) : $Mixed, passe 1 en carre latin (niveaux repartis par cylindre) : texte sans « sans precompensation »
    if ($Mixed) { $t = if ($spd) { (T "Le lecteur ne tourne pas à la vitesse de ce type de disquette. Le contrôle de la première passe, où le motif de test est écrit puis relu sur 3 tours, a trouvé :") } else { (T "La disquette de calibration semble défectueuse. Le contrôle de surface de la première passe, où le motif de test est écrit puis relu sur 3 tours, a trouvé :") } }
    else { $t = if ($spd) { (T 'Le lecteur ne tourne pas à la vitesse de ce type de disquette. Le contrôle de la première passe, où le motif de test est écrit sans précompensation puis relu sur 3 tours, a trouvé :') } else { (T "La disquette de calibration semble défectueuse. Le contrôle de surface de la première passe, où le motif de test est écrit sans précompensation puis relu sur 3 tours, a trouvé :") } }
    foreach ($h in 0, 1) {
        $f = $sf.Faces[$h]
        if (-not $f.Defective) { continue }
        $t += "`n  - " + (Format-CalibSurfaceFaceDefect $f $h)
    }
    foreach ($x in @($Extra)) { if ($x) { $t += "`n  - " + $x } }
    if ($spd) { $t += "`n" } else { $t += "`n`n" + (T "Sur une telle disquette, la calibration risque de mesurer le défaut du support plutôt que le besoin du lecteur.") }
    foreach ($x in @($Notes)) { if ($x) { $t += "`n" + $x } }
    if (Test-CalibCleanHint $sf $Medium $Hd) { $t += "`n" + (T "Des trous de signal sur les deux faces viennent souvent de têtes sales : nettoyez-les (carte « Nettoyer les têtes du lecteur » de l'Accueil), puis recommencez.") }
    if ($std) { $t += "`n" + (T 'Test standard : seuls les cylindres de test ont été contrôlés.') }
    $t += "`n`n"
    $pre = ''
    switch ($opt.Variant) {
        'write' {
            $pre = (T "La disquette insérée est la disquette à écrire : elle recevra le motif de test, puis l'image.") + "`n"
            if ($autoStart) { $pre += (T "L'avertissement a été validé automatiquement : la disquette insérée est donc celle à écrire.") + "`n" }
            $act = (T "Changer de disquette : insérez une autre disquette et cochez la première case ; cochez aussi la seconde si c'est une disquette sacrifiée, la disquette à écrire vous sera alors redemandée après la calibration. La calibration reprend à la première passe, avec les mêmes réglages et sans nouvel avertissement.`nContinuer : la calibration se poursuit sur cette disquette, puis l'image y est écrite.`nArrêter : la calibration s'arrête et l'image n'est pas écrite.")
        }
        'swap' { $act = (T "Changer de disquette : insérez une autre disquette sacrifiée, cochez la case, puis cliquez sur « Changer de disquette » ; la calibration reprend à la première passe, avec les mêmes réglages, et la disquette à écrire vous sera redemandée ensuite.`nContinuer : la calibration se poursuit sur cette disquette.`nArrêter : la calibration s'arrête et l'image n'est pas écrite.") }
        'restore-swap' { $act = (T "Changer de disquette : insérez une autre disquette sacrifiée, cochez la case, puis cliquez sur « Changer de disquette » ; la calibration reprend à la première passe, et la disquette de destination vous sera redemandée ensuite.`nContinuer : la calibration se poursuit sur cette disquette.`nArrêter : la calibration et la restauration s'arrêtent.") }
        'restore' {
            # Defaut de vitesse seul (arbitrage 12) : une autre disquette de destination n y changerait rien
            $act = if ($spd) { (T "Continuer : la calibration se poursuit sur cette disquette, puis la copie y est écrite.`nArrêter : la calibration et la restauration s'arrêtent.") }
                   else { (T "La calibration se fait sur la disquette de destination, déjà contrôlée par la restauration : elle ne peut pas être changée ici.`nContinuer : la calibration se poursuit sur cette disquette, puis la copie y est écrite.`nArrêter : la calibration et la restauration s'arrêtent ; relancez la restauration avec une autre disquette de destination.") }
        }
        'redo' { $act = (T "Changer de disquette : insérez une autre disquette sacrifiée, cochez la case, puis cliquez sur « Changer de disquette » ; la calibration B reprend à la première passe.`nContinuer : la calibration B se poursuit sur cette disquette.`nArrêter : la calibration B s'arrête, puis vous décidez de la courbe A.") }
        default { $act = (T "Changer de disquette : insérez une autre disquette sacrifiée, cochez la case, puis cliquez sur « Changer de disquette » ; la calibration reprend à la première passe, avec les mêmes réglages et sans nouvel avertissement.`nContinuer : la calibration se poursuit sur cette disquette.`nArrêter : la calibration s'arrête, rien de plus n'est écrit.") }
    }
    if (-not $opt.Change -and $opt.Variant -ne 'restore') { $act = (@($act -split "`n") | Select-Object -Skip 1) -join "`n" }
    $t += $pre + $act
    $t += "`n`n" + (T "Pas de décision automatique : la calibration attend votre réponse. Fermer la fenêtre équivaut à « Arrêter ».")
    return $t
}

function Get-CalibMediumCheck($tracks, [int[]]$cyls, [int]$bits, [int]$rpm) {
    # 12.7 : vitesse du lecteur et densite relue a la passe 1 (champs IndexMs et NFlux de ScpRev, deja lus), toutes
    # familles. En calibration, la cellule mesuree vaut duree du tour / cellules du motif : « cellule a +/- 10 % de celle
    # du motif » (arbitrage 1) equivaut a « tour a +/- 10 % de 60 000 / tr/min ms ». Flux attendus par tour :
    # CalFluxPerCell x cellules. Par piste : mediane des tours ; tour sans IndexMs positif (objets simules des tests) :
    # ignore ; face sans piste mesuree : non jugee, absente de la ligne de journal (aucune ligne si aucune face).
    $revMs = 60000.0 / [double]$rpm; $nfx = $script:CalFluxPerCell * [double]$bits
    $res = @{ Faces = @{}; Gross = $false; Rot = $false; Flux = $false; Lines = @(); Log = $null; RevMs = $revMs }
    $parts = @()
    foreach ($h in 0, 1) {
        $tr = @(); $fr = @(); $im = @()
        foreach ($c in $cyls) {
            $tn = [int]$c * 2 + $h
            if (-not $tracks.ContainsKey($tn)) { continue }
            $revs = @($tracks[$tn] | Where-Object { $null -ne $_ -and $null -ne $_.IndexMs -and [double]$_.IndexMs -gt 0 })
            if ($revs.Count -eq 0) { continue }
            $m = [double](Get-Median @($revs | ForEach-Object { [double]$_.IndexMs }))
            $im += $m; $tr += $m / $revMs
            $fr += [double](Get-Median @($revs | ForEach-Object { [double]$_.NFlux })) / $nfx
        }
        $n = $tr.Count
        $f = @{ N = $n; RevMed = [double]::NaN; FluxMed = [double]::NaN; RotBad = 0; FluxBad = 0; RotGross = $false; FluxGross = $false }
        if ($n -gt 0) {
            $f.RevMed = [double](Get-Median $im); $f.FluxMed = [double](Get-Median $fr)
            $f.RotBad = @($tr | Where-Object { [math]::Abs($_ - 1.0) -gt $script:CalSurfRotTol }).Count
            $f.FluxBad = @($fr | Where-Object { [math]::Abs($_ - 1.0) -gt $script:CalSurfFluxTol }).Count
            $need = [math]::Max(1, [int][math]::Ceiling($script:CalSurfGrossFrac * $n))
            $f.RotGross = ($f.RotBad -ge $need); $f.FluxGross = ($f.FluxBad -ge $need)
            $parts += ((T "face {0} : tour de {1} ms en médiane ({2} ms attendues), flux à {3} % du motif") -f "$h", (Format-UiNum $f.RevMed '0.00'), (Format-UiNum $revMs '0.#'), (Format-UiNum (100.0 * $f.FluxMed) '0.0'))
            if ($f.RotGross) { $res.Rot = $true; $res.Lines += ((T "face {0} : tour de {1} ms en médiane au lieu de {2} ms ({3} piste(s) sur {4}) : lecteur à environ {5} tr/min, ce type de disquette en demande {6}") -f "$h", (Format-UiNum $f.RevMed '0.0'), (Format-UiNum $revMs '0.#'), "$($f.RotBad)", "$n", "$([int][math]::Round(60000.0 / $f.RevMed))", "$rpm") }
            if ($f.FluxGross) { $res.Flux = $true; $res.Lines += ((T "face {0} : nombre de flux à {1} % de celui du motif en médiane ({2} piste(s) sur {3} à plus de {4} % d'écart) : la densité relue n'est pas celle du motif écrit") -f "$h", (Format-UiNum (100.0 * $f.FluxMed) '0'), "$($f.FluxBad)", "$n", (Format-UiNum (100.0 * $script:CalSurfFluxTol) '0')) }
        }
        $res.Faces[$h] = $f
    }
    $res.Gross = ($res.Rot -or $res.Flux)
    if ($parts.Count -gt 0) { $res.Log = ((T "Contrôle de vitesse et de densité (passe 1) : {0}.") -f ($parts -join ' ; ')) }
    return $res
}

function Test-CalibSurfaceGross($sf, $mc) {
    # Arbitrage 1 de la 12.7 : defaut grossier de la disquette de calibration, qui ouvre la fenetre du controle de surface
    # pendant la calibration ; une face suffit : au moins CalSurfGrossFrac de ses cylindres testes defectueux selon les
    # regles de Get-CalibSurface (une face sans aucun tour mesurable en fait partie : toutes ses pistes sont illisibles),
    # ou vitesse du lecteur ou densite relue hors tolerance (Get-CalibMediumCheck, arbitrage 10). Disquette douteuse
    # sans defaut grossier : reserve au bilan (Format-CalibSurfaceReserve), sans fenetre pendant la calibration.
    if ($mc -and $mc.Gross) { return $true }
    foreach ($h in 0, 1) {
        $f = $sf.Faces[$h]
        if (-not $f -or [int]$f.N -le 0) { continue }
        if (@($f.Bad).Count -ge [math]::Max(1, [int][math]::Ceiling($script:CalSurfGrossFrac * [int]$f.N))) { return $true }
    }
    return $false
}

function Test-CalibSpeedOnly($sf, $mc) {
    # 12.7 : defaut grossier de la seule vitesse du lecteur (duree du tour hors tolerance, Get-CalibMediumCheck), sans face
    # defectueuse au controle de surface : le lecteur est en cause, pas la disquette (addendum HD, § 4.4 : paragraphe de
    # vitesse). Fenetre sans « Changer de disquette » ni paragraphe haute densite, verdicts qui nomment le lecteur
    if (-not $mc -or -not $mc.Rot) { return $false }
    if ($sf -and ($sf.Defective -or (Test-CalibSurfaceGross $sf $null))) { return $false }
    return $true
}

function Format-CalibSurfaceVerdict($sf, $mc) {
    # Resume d un defaut grossier (journal, bilan d une calibration poursuivie) : faces douteuses, puis vitesse du lecteur
    # et densite relue hors tolerance
    $p = @()
    $s = Format-CalibSurfaceShort $sf; if ($s) { $p += $s }
    if ($mc -and $mc.Rot) { $p += (T 'vitesse du lecteur différente de celle du type de disquette') }
    if ($mc -and $mc.Flux) { $p += (T 'densité relue différente de celle du motif') }
    return ($p -join ' ; ')
}

function Format-CalibSurfaceReserve($sf) {
    # Arbitrage 1 de la 12.7 : reserve de la fenetre de decision pour une disquette douteuse sans defaut grossier (pistes
    # defectueuses de la passe 1 par face et par nature ; intervalles hors classe sur toute une face)
    $p = @(); $n = 0
    foreach ($h in 0, 1) {
        $f = $sf.Faces[$h]
        if (-not $f) { continue }
        if ($f.Noisy) { $p += ((T "face {0} : intervalles hors classe sur toute la face ({1} par tour en médiane)") -f "$h", (Format-UiNum $f.OocMed)) }
        $b = @($f.Bad); $n += $b.Count
        if ($b.Count) { $p += ((T "face {0} : {1}") -f "$h", (Get-CalibSurfaceReasons $b)) }
    }
    if ($n -eq 0) { return ((T "support : {0} à la première passe") -f ($p -join ' ; ')) }
    return ((T "support : {0} piste(s) défectueuse(s) à la première passe ({1})") -f "$n", ($p -join ' ; '))
}

function Get-CalibSurfaceStates($sf, $mc) {
    # 12.8 (lot 5, D15) : etats du controle pour frmCalibSurface (icones d etat du lot 3, h0 ✓, h1 !, h2 ✗) : une ligne par
    # face mesuree (defectueuse ✗, pistes defectueuses sans defaut de la face !, saine ✓), puis vitesse du lecteur et densite
    # relue quand au moins une face a ete mesuree (Get-CalibMediumCheck). Renvoie un tableau de @{ Kind ; Text }.
    $r = @()
    foreach ($h in 0, 1) {
        $f = $sf.Faces[$h]
        if (-not $f -or [int]$f.N -le 0) { continue }
        $n = @($f.Bad).Count
        if ($f.Defective -and $n -eq 0) { $r += ,@{ Kind = 'h2'; Text = ((T 'Face {0} : défectueuse (hors classe sur toute la face)') -f "$h") } }
        elseif ($f.Defective) { $r += ,@{ Kind = 'h2'; Text = ((T 'Face {0} : défectueuse ({1} piste(s) sur {2})') -f "$h", "$n", "$($f.N)") } }
        elseif ($n -gt 0) { $r += ,@{ Kind = 'h1'; Text = ((T 'Face {0} : défaut ponctuel ({1} piste(s) sur {2})') -f "$h", "$n", "$($f.N)") } }
        else { $r += ,@{ Kind = 'h0'; Text = ((T 'Face {0} : saine') -f "$h") } }
    }
    if ($mc -and $mc.Faces -and @(@($mc.Faces.Values) | Where-Object { $_ -and [int]$_.N -gt 0 }).Count -gt 0) {
        $r += ,$(if ($mc.Rot) { @{ Kind = 'h2'; Text = (T 'Vitesse du lecteur : hors tolérance') } } else { @{ Kind = 'h0'; Text = (T 'Vitesse du lecteur : conforme') } })
        $r += ,$(if ($mc.Flux) { @{ Kind = 'h2'; Text = (T 'Densité relue : différente du motif') } } else { @{ Kind = 'h0'; Text = (T 'Densité relue : conforme') } })
    }
    return ,$r
}

function Get-LevelSurface($tracks, $cal, [int]$rpm) {
    # 12.7 point 5 : controle de surface (Get-CalibSurface) et de vitesse et de densite (Get-CalibMediumCheck) de la
    # premiere passe de la calibration rapide, chaque face sur ses cylindres ecrits a cette passe (cibles de ses unites :
    # cylindres de niveau, temoins de marche et du plafond ; courbe commune : memes cylindres pour les deux faces). Les
    # deux fonctions jugent chaque face a part : appel par face quand les cylindres different (pistes de la seule face
    # pour Get-CalibMediumCheck : une ligne de vitesse par face). Renvoie @{ Surf ; Medium ; Logs }.
    $cy = @{ 0 = @{}; 1 = @{} }
    foreach ($u in @($cal.Units)) {
        $hs = if ($null -eq $u.Head) { @(0, 1) } else { @([int]$u.Head) }
        foreach ($c in @($u.LTarget.Keys)) { foreach ($h in $hs) { $cy[$h][[int]$c] = $true } }
    }
    $c0 = [int[]]@($cy[0].Keys | Sort-Object); $c1 = [int[]]@($cy[1].Keys | Sort-Object)
    $bits = [int]$cal.PatternBits
    if (($c0 -join ',') -eq ($c1 -join ',')) {
        $mc = Get-CalibMediumCheck $tracks $c0 $bits $rpm
        return @{ Surf = (Get-CalibSurface $tracks $c0); Medium = $mc; Logs = @($(if ($mc.Log) { $mc.Log })) }
    }
    $sf = @{ Faces = @{}; Bad = @(); Defective = $false; Why = @() }
    $mc = @{ Faces = @{}; Gross = $false; Rot = $false; Flux = $false; Lines = @(); Log = $null; RevMs = 60000.0 / [double]$rpm }
    $logs = @()
    foreach ($h in 0, 1) {
        $cs = if ($h -eq 0) { $c0 } else { $c1 }
        $f = (Get-CalibSurface $tracks $cs).Faces[$h]
        $sf.Faces[$h] = $f; $sf.Bad += @($f.Bad)
        if ($f.Defective) { $sf.Defective = $true; $sf.Why += $h }
        $th = @{}; foreach ($c in $cs) { $tn = [int]$c * 2 + $h; if ($tracks.ContainsKey($tn)) { $th[$tn] = $tracks[$tn] } }
        $m1 = Get-CalibMediumCheck $th $cs $bits $rpm
        $mc.Faces[$h] = $m1.Faces[$h]
        if ($m1.Rot) { $mc.Rot = $true }
        if ($m1.Flux) { $mc.Flux = $true }
        $mc.Lines += @($m1.Lines)
        if ($m1.Log) { $logs += $m1.Log }
    }
    $mc.Gross = ($mc.Rot -or $mc.Flux)
    return @{ Surf = $sf; Medium = $mc; Logs = $logs }
}

function Get-LevelSurfaceText($sf, $mc, [bool]$restore, [bool]$spd, [string[]]$notes, [switch]$Disk) {
    # 12.7 point 5 : texte de la fenetre « Disquette a ecrire defectueuse » : synthese par face (compteurs du journal),
    # vitesse et densite relue, risque, conseil de nettoyage (arbitrage 14), choix, absence de decision automatique.
    # 12.8 (S3) : Disk : mesure complete de cette disquette (Invoke-CalibAnalysis) ; en restauration (copie secteur, liste
    # « Mesure : complete », S3-FLUX), choix propres a la restauration (S3-FIX)
    $t = if ($Disk -and $spd) { (T 'Le lecteur ne tourne pas à la vitesse de ce type de disquette. La première passe de la mesure complète de cette disquette, où le motif de test est écrit sur tous ses cylindres puis relu sur 3 tours, a trouvé :') }
         elseif ($Disk) { (T 'La disquette à écrire semble défectueuse. La première passe de la mesure complète de cette disquette, où le motif de test est écrit sur tous ses cylindres puis relu sur 3 tours, a trouvé :') }
         elseif ($spd) { (T 'Le lecteur ne tourne pas à la vitesse de ce type de disquette. La première passe de la mesure du niveau, où le motif de test est écrit sur les cylindres mesurés puis relu sur 3 tours, a trouvé :') }
         else { (T 'La disquette à écrire semble défectueuse. La première passe de la mesure du niveau, où le motif de test est écrit sur les cylindres mesurés puis relu sur 3 tours, a trouvé :') }
    foreach ($x in (Get-CalibSurfaceFaceLines $sf)) { $t += "`n  - " + $x }
    foreach ($x in @($mc.Lines)) { if ($x) { $t += "`n  - " + $x } }
    if ($spd) { $t += "`n" } else { $t += "`n`n" + (T "Sur une telle disquette, l'image risque d'être mal écrite et mal relue.") }
    foreach ($x in @($notes)) { if ($x) { $t += "`n" + $x } }
    if (Test-CalibCleanHint $sf $mc $false) { $t += "`n" + (T "Des trous de signal sur les deux faces viennent souvent de têtes sales : nettoyez-les (carte « Nettoyer les têtes du lecteur » de l'Accueil), puis recommencez.") }
    # Restauration, defaut de vitesse seul (arbitrage 12) : une autre disquette de destination n y changerait rien
    $t += "`n`n" + $(if ($Disk -and $restore -and $spd) { (T "Écrire quand même : la mesure complète se poursuit, puis la copie est écrite sur cette disquette.`nArrêter : la restauration s'arrête.") }
                     elseif ($Disk -and $restore) { (T "Écrire quand même : la mesure complète se poursuit, puis la copie est écrite sur cette disquette.`nArrêter : la restauration s'arrête ; relancez-la avec une autre disquette de destination.") }
                     elseif ($Disk) { (T "Écrire quand même : la mesure complète se poursuit, puis l'image est écrite sur cette disquette.`nArrêter : rien de plus n'est écrit, l'image n'est pas écrite.") }
                     elseif ($restore -and $spd) { (T "Écrire quand même : la mesure du niveau se poursuit, puis la copie est écrite sur cette disquette.`nArrêter : la restauration s'arrête.") }
                     elseif ($restore) { (T "Écrire quand même : la mesure du niveau se poursuit, puis la copie est écrite sur cette disquette.`nArrêter : la restauration s'arrête ; relancez-la avec une autre disquette de destination.") }
                     else { (T "Écrire quand même : la mesure du niveau se poursuit, puis l'image est écrite sur cette disquette.`nArrêter : rien de plus n'est écrit, l'image n'est pas écrite.") })
    $t += "`n`n" + (T "Pas de décision automatique : l'écriture attend votre réponse. Fermer la fenêtre équivaut à « Arrêter ».")
    return $t
}

function Invoke-LevelSurface($cal, $tracks) {
    # 12.7 point 5 : etat de la surface de la disquette sur la relecture de la premiere passe de la calibration rapide
    # (regles du controle de surface du point 1, cylindres mesures : Get-LevelSurface). Bilan par face toujours au
    # journal. Defaut grossier (arbitrage 1 ; vitesse et densite : arbitrage 10) avant une ecriture : fenetre bloquante sans
    # compte a rebours (Show-CalibSurface, variante 'level' : « Ecrire quand meme », « Arreter », fermeture = Arreter),
    # avant l ecriture de l image ; defaut modere, ou defaut grossier d une calibration rapide sans ecriture : journal, et
    # reserve de la fenetre de decision si elle s ouvre (Complete-LevelCalib). Renvoie $false si l ecriture est arretee.
    $cal.SurfDone = $true
    $rpm = if ($cal.Rpm) { [int]$cal.Rpm } else { 300 }
    $r = Get-LevelSurface $tracks $cal $rpm
    $sf = $r.Surf; $mc = $r.Medium
    $gross = Test-CalibSurfaceGross $sf $mc
    $cal.Surf = $sf; $cal.Medium = $mc; $cal.SurfGross = $gross
    Append-Log ((T 'Contrôle de surface de la disquette (calibration rapide, passe 1, cylindres mesurés seulement) : {0}.') -f ((Get-CalibSurfaceFaceLines $sf) -join ' ; '))
    foreach ($l in @($r.Logs)) { Append-Log $l }
    $verdict = Format-CalibSurfaceVerdict $sf $mc
    # Decision 3 de decisions127-p5.md : liste « Calibration precomp » au test rapide (index 2 ; en restauration, celle d avant
    # la restauration) : chemins de la 12.6, sans fenetre ; journal et reserve seulement
    $cm = if ($script:Restore -and $script:Restore.Saved) { [int]$script:Restore.Saved.CalMode } else { [int]$cmbWCalMode.SelectedIndex }
    if ($gross -and $script:AfterCalib -eq 'write' -and $cm -ne 2) {
        # Arbitrage 12 : defaut de vitesse seul : journal et titre qui ne mettent pas la disquette en cause
        $spd = Test-CalibSpeedOnly $sf $mc
        if ($spd) { Append-Log ((T 'Contrôle de vitesse et de densité : {0} : décision demandée.') -f "$verdict") }
        else { Append-Log ((T 'Contrôle de surface : disquette à écrire défectueuse ({0}) : décision demandée.') -f "$verdict") }
        $notes = @()
        if ($mc.Rot) { $notes += (T "Vitesse du lecteur différente de celle du type de disquette : un format à 300 tr/min demande un lecteur à 300 tr/min (3,5 pouces, ou 5,25 pouces double densité), un format à 360 tr/min un lecteur à 360 tr/min (5,25 pouces haute densité, ou 3,5 pouces réglé à 360 tr/min). Changer de disquette n'y change rien.") }
        # 12.8 (lot 5, D15) : Speed et States : titre du bandeau et icones d etat de frmCalibSurface
        $opt = @{ Change = $false; SwapBox = $false; Variant = 'level'; Title = $(if ($spd) { (T 'Contrôle de surface') } else { (T 'Disquette à écrire défectueuse') }); GoText = (T 'Écrire quand même')
                  Speed = $spd; States = (Get-CalibSurfaceStates $sf $mc) }
        $txt = Get-LevelSurfaceText $sf $mc ([bool]$script:Restore) $spd $notes
        $cal.Hold = $true; Update-CalibProgress; if ($cal.Home) { Update-HomeCalibCard }
        if ($script:Restore) { $script:Restore.InCall = $true }
        try { $ch = Show-CalibSurface $opt $txt }
        finally { $cal.Hold = $false; if ($script:Restore) { $script:Restore.InCall = $false; $script:Restore.Idle = Get-Date } }
        if ($ch.Choice -ne 'continue') {
            Append-Log (T "Contrôle de surface : écriture arrêtée à votre demande, l'image n'est pas écrite.")
            Stop-PrecompCalib; return $false
        }
        $cal.SurfKept = $true
        Append-Log (T 'Contrôle de surface : écriture poursuivie sur cette disquette à votre demande.')
        return $true
    }
    if ($gross -or $sf.Defective) { Append-Log ((T "Contrôle de surface : disquette douteuse ({0}) ; la calibration rapide continue, avec une réserve si la fenêtre de décision s'ouvre.") -f "$verdict") }
    elseif (@($sf.Bad).Count) {
        $p = @(); foreach ($h in 0, 1) { $b = @($sf.Faces[$h].Bad); if ($b.Count) { $p += ((T "face {0} : {1}") -f "$h", (Get-CalibSurfaceReasons $b)) } }
        Append-Log ((T 'Contrôle de surface : défaut ponctuel de la disquette ({0}) ; la calibration rapide continue.') -f ($p -join ' ; '))
    }
    return $true
}
# ============================== FONCTIONS : CALIBRATION B ======================

# ============================== CALIBRATION B (12.7) ===========================
# « Refaire sur une autre disquette » (fenetre de decision d une calibration complete) : la courbe A est mise de cote en
# memoire, la calibration d avant A est retablie, la meme calibration (B) est refaite sur une autre disquette sacrifiee,
# puis les deux courbes sont comparees face par face et l utilisateur choisit A, B ou aucune, sans fusion des mesures.
# Sur disque pendant B : la calibration d avant A (A perdue si l application est fermee, limite acceptee). Etat :
# $script:CalRedo (Stage 'confirm', 'running', 'interrupted'), en memoire seulement.

function Start-CalibRedo($cal, [string[]]$issues, [string[]]$kinds, $prevCal, [bool]$toWrite) {
    # « Refaire sur une autre disquette » (fenetre de decision de la calibration A, Complete-PrecompCalib) : courbe A mise de
    # cote en memoire, calibration d avant A retablie, meme calibration (B) relancee sur une autre disquette sacrifiee apres
    # une confirmation sans compte a rebours ; aucune fusion des mesures. Ecriture qui suivait A : annulee si B est lancee.
    # $true : B lancee ; $false : B non lancee, courbe A retablie (la fenetre de A se rouvre).
    $keys = @($cal.Units | ForEach-Object { Get-CalibUnitKey $cal $_ })
    # 12.10 : courbe A lue dans le magasin du lecteur de la calibration (courbes par lecteur), copie d etat sur ses cles de magasin
    $aCurves = @{}; foreach ($k in $keys) { $acv = Get-DriveCurve ([string]$cal.Drive) $k; if ($acv) { $aCurves[$k] = $acv.Clone() } }
    $aDate = if ($aCurves.ContainsKey($keys[0])) { [string]$aCurves[$keys[0]].Date } else { '' }
    $script:CalRedo = @{ Stage = 'confirm'; ACal = $cal; AIssues = @($issues); AKinds = @($kinds); AKeys = $keys; ACurves = $aCurves
                         AState = (Get-CalibSnapshot @($keys | ForEach-Object { Get-DriveCurveKey ([string]$cal.Drive) $_ })); PrevA = $prevCal; ADate = $aDate; Why = '' }
    Restore-CalibState $prevCal
    Append-Log ((T "Calibration : « Refaire sur une autre disquette » : courbe A du {0} mise de côté, calibration précédente rétablie pendant la calibration B.") -f "$aDate")
    $svAfter = $script:AfterCalib; $script:AfterCalib = ''
    # Arbitrage 2 : courbe A perdue si l application est fermee pendant B, dit dans la confirmation
    $intro = ((T "Calibration B sur une autre disquette sacrifiée, avec les réglages de la calibration A du {0}.`n`nRetirez la disquette de la calibration A et insérez une AUTRE disquette sacrifiée : sans valeur, jamais l'original ni la disquette à écrire. L'application ne peut pas distinguer deux disquettes : la case ci-dessous fait foi. Les deux courbes seront ensuite comparées face par face, et vous choisirez celle à conserver.") -f "$aDate") + "`n`n" +
             (T "Pendant la calibration B, la configuration garde la calibration d'avant la calibration A : si vous fermez l'application avant la fin de la calibration B, la courbe A est perdue.") + "`n`n"
    if ($cal.Home) {
        if ($cal.Geom -and -not (Test-Path -LiteralPath ([string]$cal.Geom.Img))) { try { [void](New-CalibGeometry (Get-HomeCalibInfo ([string]$cal.Geom.Fmt)) ([int]$cal.MaxCyl + 1)) } catch { } }
        Start-PrecompCalib -Intro $intro -Geom $cal.Geom -Heads ([bool]$cal.Slow) -Test ([string]$cal.Mode) -NoWarmup:([bool]$cal.NoWarmup)
    } else {
        Start-PrecompCalib -Intro $intro -Heads ([bool]$cal.Slow) -Test ([string]$cal.Mode) -NoWarmup:([bool]$cal.NoWarmup)
    }
    if ($script:Cal) {
        if ($toWrite) { Append-Log (T "Écriture annulée : calibration refaite sur une autre disquette ; relancez l'écriture depuis la Bibliothèque une fois la courbe choisie.") }
        if ($cal.Home) { $script:HomeCalBusy = $true }
        return $true
    }
    Restore-CalibState $script:CalRedo.AState
    $script:CalRedo = $null; $script:AfterCalib = $svAfter
    Append-Log (T 'Calibration B non lancée : la courbe A est rétablie, décision sur la courbe A.')
    return $false
}

function Complete-CalibRedo($cal, [string[]]$issues, [string[]]$kinds, $prevCal) {
    # Fin de la calibration B (Complete-PrecompCalib, B deja enregistree) : comparaison avec la courbe A, toujours montree, puis
    # choix : courbe B (rien a faire), courbe A (etat « A appliquee » retabli) ou aucune (calibration d avant A retablie).
    # Bilan de la zone de progression de l Accueil (Set-HomeProgDone) selon le choix.
    $r = $script:CalRedo; $script:CalRedo = $null
    $rep = Get-CalibRedoReport $r $cal @($issues) @($kinds)
    foreach ($l in @($rep.Log)) { Append-Log $l }
    $choice = Show-CalibReview $cal @($issues) $false $false $false $false @{ Mode = 'ab'; Curves = $rep.Curves; Zones = $rep.Zones; Text = $rep.Text; Pick = $rep.Pick }
    switch ($choice) {
        'keepA' { Restore-CalibState $r.AState; $lblWCal.Text = (T "Courbe A conservée : la calibration B n'est pas retenue."); Append-Log (T 'Calibration B : courbe A conservée à votre demande, courbe B abandonnée.'); $hk = 'warn' }
        'stop'  { Restore-CalibState $prevCal; $lblWCal.Text = (T 'Calibrations A et B abandonnées : la calibration précédente est rétablie.'); Append-Log (T 'Calibrations A et B abandonnées à votre demande : la calibration précédente est rétablie.'); $hk = 'abandon' }
        default { $lblWCal.Text = (T 'Courbe B conservée : calibration refaite sur une autre disquette.'); Append-Log (T 'Calibration B : courbe B conservée.'); $hk = $(if (@($issues).Count -gt 0) { 'warn' } else { 'ok' }) }
    }
    Set-HomeProgDone $cal $hk
    if ($r.ACal.Home) { Update-HomeCalibCard }
    if ($choice -ne 'stop') { Show-PrecompCurve $cal.Family $cal.Slow }
}

function Resume-CalibRedo {
    # Calibration B arretee avant sa fin (bouton Arreter, erreur gw, controle de surface, aucune mesure exploitable) : decision
    # sur la courbe A seule. Minuteur principal (application au repos, aucune fenetre modale) ou Complete-PrecompCalib.
    $r = $script:CalRedo
    if (-not $r -or $r.Stage -ne 'interrupted') { return }
    $script:CalRedo = $null                                   # avant la fenetre : le minuteur ne la rouvre pas
    Append-Log ((T "Calibration B arrêtée avant sa fin ({0}) : décision sur la courbe A.") -f "$($r.Why)")
    $iss = @($r.AIssues)
    $txt = ((T "La calibration B s'est arrêtée avant sa fin ({0}) : aucune comparaison n'est possible.") -f "$($r.Why)") + "`n" + ((T "Réserves de la courbe A ({0}) :") -f "$($r.ADate)") + "`n" +
           ((@($iss) | ForEach-Object { "  - $_" }) -join "`n") + "`n`n" + (T "Conserver la courbe A : elle est rétablie et enregistrée.`nAbandonner la courbe : la calibration d'avant la calibration A reste en place.`nFermer la fenêtre : la courbe A est conservée.")
    $cvs = @($r.AKeys | ForEach-Object { $r.ACurves[$_] } | Where-Object { $_ })
    $choice = Show-CalibReview $r.ACal $iss $false $false $false $false @{ Mode = 'aonly'; Curves = $cvs; Zones = @(); Text = $txt; Pick = $null }
    if ($choice -eq 'stop') { $lblWCal.Text = (T 'Calibration B arrêtée : la courbe A est abandonnée, la calibration précédente reste en place.'); Append-Log (T 'Courbe A abandonnée à votre demande : la calibration précédente reste en place.'); $hk = 'abandon' }
    else { Restore-CalibState $r.AState; $lblWCal.Text = (T 'Calibration B arrêtée : la courbe A est conservée.'); Append-Log (T 'Courbe A conservée à votre demande.'); $hk = 'warn' }
    Set-HomeProgDone $r.ACal $hk
    if ($r.ACal.Home) { Update-HomeCalibCard }
}
# ============================== FONCTIONS : RESTAURATION =======================

function Get-RestoreDefaultDir {
    return (Join-Path ([Environment]::GetFolderPath('MyDocuments')) ('Greaseweazle Studio\' + (T 'Restaurations')))
}

function Get-RestoreFormat {
    # 12.8 (D13) : choix de la liste du cadre 1 (reglage restoreFormat, cle restore.formatChoice) : 'auto' (detection du
    # format a la lecture), '' (copie exacte du flux) ou le nom du format. Piege : l index 0 de cmbRsFmt designe la
    # detection automatique, et non plus le flux ($script:RsFluxItem)
    $c = [string](Get-Setting 'restoreFormat')
    if ($c -eq 'flux') { return '' }
    if (-not $c) { return 'auto' }
    return $c
}

function Get-RestoreStem([string]$dir, [string]$name) {
    # Debut commun des chemins de la restauration (« <dossier>\<nom> »), calcule une seule fois par restauration (Start-
    # Restore) ; jamais d ecrasement : suffixe (2), (3)... si une restauration du meme nom existe deja, quel que soit son
    # mode (12.8, FIX2 : rapport, original ou lecture secteur incomplete de toute extension ; avant : original de la meme
    # extension seulement, d ou un rapport ecrase apres une relance D12 ou un autre mode)
    $tails = @(' - ' + (T 'rapport') + '.txt')
    foreach ($e in @('.adf', '.st', '.img', '.scp')) { $tails += @((' - ' + (T 'original') + $e), (' - ' + (T 'lecture secteur incomplète') + $e)) }
    $stem = Join-Path $dir $name; $k = 1
    while (@($tails | Where-Object { Test-Path -LiteralPath ($stem + $_) }).Count -gt 0) { $k++; $stem = (Join-Path $dir $name) + " ($k)" }
    return $stem
}

function Set-RestoreFormat([string]$fmt) {
    # Format de la restauration ($fmt : nom du format, '' : copie exacte du flux), choisi dans la liste ou retenu par la
    # detection (Complete-RestoreDetect) : mode, extension et chemins (Orig, Back, Report, Probe). 12.8 : les chemins se
    # calculent apres la detection, l extension dependant du format ; debut des chemins fixe pour toute la restauration
    # ($r.Stem), la relance D12 ne changeant que l extension
    $r = $script:Restore
    $r.Fmt = $fmt
    $r.Mode = $(if ($fmt) { 'sector' } else { 'flux' })
    $r.Ext = $(if ($fmt) { Get-DecodedExt $fmt } else { '.scp' })
    if (-not $r.Stem) { $r.Stem = Get-RestoreStem $r.Dir $r.Name }
    $stem = $r.Stem
    $r.Orig = ($stem + ' - ' + (T 'original') + $r.Ext); $r.Back = ($stem + ' - ' + (T 'copie relue') + $r.Ext)
    $r.Report = ($stem + ' - ' + (T 'rapport') + '.txt')
    $r.Probe = (Join-Path $script:TempDir ("restore-probe-" + (Get-Date -Format 'yyyyMMdd-HHmmss') + $r.Ext))
}

function Update-RsDrive {
    # 12.8 (D10) : lecteur de la restauration, celui du bandeau (Update-SettingDependents 'drive')
    if (-not $lblRsDrive) { return }
    # 12.11 (lot LN-b) : lecteur enregistre dans le bandeau : texte court, son nom et sa connexion (Get-DriveLabel, 112) :
    # avec un nom, le texte de la 12.10 depasserait les 290 px du libelle
    if ($script:DriveReg.Count -gt 0 -and (Test-DriveRegistered ([string]$cmbDrive.Text))) { $lblRsDrive.Text = (T '{0}  (bandeau)') -f (Get-DriveLabel ([string]$cmbDrive.Text)); return }
    $lblRsDrive.Text = (T "{0}  (choix « Lecteur » du bandeau)") -f "$(Get-Setting 'drive')"
}

function Update-RsFmtFound {
    # 12.8 (D11) : ligne sous la liste du format (Update-SettingDependents 'restoreFormat'). Detection automatique :
    # « Format detecte a la lecture », puis le resultat de la detection (Complete-RestoreDetect), garde jusqu au prochain
    # choix ou a la prochaine restauration ; format choisi ou flux : vide
    if (-not $lblRsFmtFound -or $script:Restore) { return }
    $t = $(if ((Get-RestoreFormat) -eq 'auto') { (T 'Format détecté à la lecture') } else { '' })
    $lblRsFmtFound.Text = $t; $tip.SetToolTip($lblRsFmtFound, $t)      # FIX2 : infobulle d une detection precedente retiree
}

function Get-RsFmtFoundLine($res) {
    # 12.8 (FIX2, A1 § 2.6 et 3.5) : ligne courte du cadre 1 (360 px, une ligne) apres la detection ; le texte complet de la
    # detection reste dans l infobulle, le rapport et le journal. $res : resultat de Select-DiskFormat (Name, Format,
    # Action, Why)
    if ($res.Action -eq 'stop') { return ((T "Arrêt : {0}") -f "$($res.Why)") }
    if ($res.Action -eq 'flux') {
        if ($res.Name) { return ((T "Format détecté : {0}, copie exacte du flux") -f "$($res.Name)") }
        # Sans format reconnu : raison courte en tete (« Format non reconnu », « Piste 0 non formatee »)
        $w = $(if ($res.Why) { [string]$res.Why } else { (T 'format non reconnu') })
        return ((T "{0} : copie exacte du flux") -f ($w.Substring(0, 1).ToUpper() + $w.Substring(1)))
    }
    return ((T "Format détecté : {0} ({1})") -f "$($res.Name)", "$($res.Format)")
}

function Get-RsCalibText {
    # 12.8 (D11) : cadre « 2. Calibration du lecteur » : courbes qu appliquerait la restauration (ecriture tete par tete :
    # par tete si elles sont a jour, sinon la courbe commune, Get-FamilyCurves), double densite (famille std, celle des
    # formats double densite de la liste) puis haute densite (famille hd) : type, date, lecteur, non-convergence
    $parts = @()
    foreach ($fd in @(@('std', (T 'Double densité')), @('hd', (T 'Haute densité')))) {
        $cvs = Get-FamilyCurves $fd[0] $true
        if ($cvs.Count -eq 0) { $parts += ((T "{0} : aucune courbe.") -f $fd[1]); continue }
        $d = @($(if ($cvs.Count -gt 1) { (T 'par tête') } else { (T 'commune aux deux têtes') }))
        $dt = Get-CurveDate $cvs[0]
        if ($dt -gt [datetime]::MinValue) { $d += $dt.ToString('dd/MM/yyyy') }
        if ($cvs[0].Drive) { $d += ((T 'lecteur {0}') -f "$($cvs[0].Drive)") }
        if (@($cvs | Where-Object { $_.Converged -eq $false }).Count -gt 0) { $d += (T 'non convergée') }
        $parts += ((T "{0} : {1}.") -f $fd[1], ($d -join ', '))
    }
    # 12.10 : lecteur cible choisi pour le lecteur du bandeau (Get-TargetDrive) : courbes croisees qu appliquerait l ecriture
    # d une copie secteur double densite (famille std, par tete si elles sont a jour : Get-TargetCurves). 12.10 (relecture
    # de la RC) : phrase en tete du cadre (libelle a points de suspension, 540 : apres les phrases des familles, elle etait
    # cachee : refus annonce ou courbe croisee nommee visibles seulement au survol)
    # 12.10 (relecture de la RC) : phrase d apres la decision de la restauration (Get-RestorePlan, celle de Start-Restore et
    # de Start-RestoreWrite) : format haute densite choisi : refus au lancement ; copie secteur pour le lecteur cible : refus
    # faute de courbe croisee standard (Get-RestoreTargetInfo), sinon courbe croisee nommee ; copie de flux, ecrite telle
    # quelle (lecteur cible sans effet) : aucune phrase. Avant : courbe croisee annoncee quel que soit le format
    $src = [string]$cmbDrive.Text; $tg = Get-TargetDrive $src
    # 12.10 (relecture de la RC, fix1) : les deux refus tires de Kind 'refused' et de sa nature (Ti.BlockKind : 'hd' format
    # haute densite choisi, 'none' aucune courbe croisee standard), comme les regles de la copie (Update-RsRules) et le
    # bouton « Courbe » (Get-RsCurveSet) ; 'target' : copie ecrite avec la courbe croisee, toujours presente
    # 12.10 (relecture de la RC, fix2) : refus faute de courbe croisee standard (BlockKind 'none') : refus de toute la
    # restauration au lancement (Start-Restore, avant la lecture, detection automatique comprise), comme le disent les
    # regles de la copie ; avant : « l ecriture d une copie secteur sera refusee »
    $pl = if ($tg) { Get-RestorePlan $src $tg (Get-RestoreFormat) } else { $null }
    if ($pl -and $pl.Kind -eq 'refused' -and $pl.Ti.BlockKind -eq 'hd') { $parts = @(((T "Lecteur cible {0} : aucune calibration croisée en haute densité, la restauration au format {1} sera refusée.") -f "$tg", "$($pl.Fmt)")) + $parts }
    elseif ($pl -and $pl.Kind -eq 'refused') { $parts = @(((T "Lecteur cible {0} : aucune courbe croisée standard {1} → {0}, la restauration sera refusée au lancement.") -f "$tg", "$src")) + $parts }
    elseif ($pl -and $pl.Kind -eq 'target') {
        $cc = @(Get-TargetCurves 'std' $true $src $tg)
        if ($cc.Count -gt 0) {
            # 12.10 (relecture de la RC) : phrase raccourcie (« commune », « a la place de celle du lecteur ») : entiere dans
            # les trois lignes du cadre (262 x 54 px) ; avec « commune aux deux tetes » et « ecrite a la place de la courbe du
            # lecteur », 139 caracteres en francais, fin « sans calibration. » cachee par les points de suspension
            $dt = Get-CurveDate $cc[0]
            $kd = if ($cc.Count -gt 1) { (T 'par tête') } else { (T 'commune') }
            if ($dt -gt [datetime]::MinValue) { $kd += ', ' + $dt.ToString('dd/MM/yyyy') }
            $parts = @(((T "Lecteur cible {0} : courbe croisée {1} → {0} ({2}), à la place de celle du lecteur {1}, sans calibration.") -f "$tg", "$src", "$kd")) + $parts
        }
    }
    return ($parts -join ' ')
}

function Get-RestoreTargetInfo([string]$drv, [string]$tgt, [string]$fmt) {
    # 12.10 (relecture de l etape 3) : lecteur cible $tgt d une restauration du lecteur $drv au format $fmt (Get-RestoreFormat :
    # auto, vide pour la copie de flux, ou le nom du format), avant la lecture de l original (Start-Restore) : @{ Applies
    # (courbe croisee ecrite : ligne de journal) ; Block (raison du refus, vide sinon) }. Sans effet : pas de lecteur cible,
    # copie de flux (ecrite sans precompensation), format explicite non MFM (FM, GCR : Get-ImageEncoding). Refus : format
    # haute densite explicite (Test-HdFormat : pas de calibration croisee en haute densite) ; copie secteur double densite
    # (famille standard, ecrite tete par tete) sans courbe croisee standard « source>cible » par tete a jour ni commune
    # (Get-TargetCurves, comme Start-RestoreWrite et Get-RsCalibText). Avant : une courbe croisee de n importe quelle
    # famille suffisait (long track seule comprise), et l original etait lu pour un echec a l etape 4. Format detecte a la
    # lecture (auto) : regle de la double densite ; une haute densite detectee echoue a l etape 4 (Start-RestoreWrite).
    # 12.10 (relecture de la RC) : BlockKind, nature du refus ('hd' : format haute densite, 'none' : aucune courbe croisee
    # standard ; '' sans refus), lue par Get-RestorePlan
    $r = @{ Applies = $false; Block = ''; BlockKind = '' }
    if (-not $tgt -or -not $fmt) { return $r }
    if ($fmt -ne 'auto' -and (Get-ImageEncoding '' $fmt).NonMfm) { return $r }
    $r.Applies = $true
    if ($fmt -ne 'auto' -and (Test-HdFormat $fmt)) {
        $r.Block = (T "Restauration refusée : lecteur cible {1} choisi pour le lecteur {0} dans l'onglet Écriture, et format haute densité {2} : la calibration croisée n'existe qu'en double densité. Choisissez « (même lecteur) » dans la liste « Lecteur cible » de l'onglet Écriture.") -f "$drv", "$tgt", "$fmt"; $r.BlockKind = 'hd'
        return $r
    }
    if (@(Get-TargetCurves 'std' $true $drv $tgt).Count -eq 0) {
        $r.Block = (T "Restauration refusée : lecteur cible {1} choisi pour le lecteur {0} dans l'onglet Écriture, sans courbe croisée {0} → {1} pour la famille {2} (copie secteur double densité). Lancez « Calibrer pour un lecteur cible… » (onglet Écriture, lecteur {0} dans le bandeau, lecteur cible {1}, famille {2}), ou choisissez « (même lecteur) » dans la liste « Lecteur cible ».") -f "$drv", "$tgt", (Get-CalibFamilyName 'std'); $r.BlockKind = 'none'
    }
    return $r
}

function Get-RestorePlan([string]$drv, [string]$tgt, [string]$fmt) {
    # 12.10 (relecture de la RC) : ce que fera la restauration du lecteur $drv au format $fmt (Get-RestoreFormat : auto, vide
    # pour la copie de flux, ou le nom du format) avec le lecteur cible $tgt, d apres les decisions de Start-Restore (refus :
    # Get-RestoreTargetInfo) et de Start-RestoreWrite : @{ Kind ; Ti (Get-RestoreTargetInfo) ; Fmt }. Kind : 'flux' (copie
    # exacte du flux, Set-RestoreFormat '' : ecrite telle quelle par gw, sans precompensation ni verification gw, ni
    # calibration ni mesure, ni comparaison secteur par secteur ; lecteur cible sans effet) ; 'refused' (refus au lancement
    # pour un lecteur cible, Ti.Block : format haute densite choisi ou aucune courbe croisee standard, Ti.BlockKind ; aucune
    # copie possible) ; 'target' (copie secteur avec la courbe croisee, ni calibration ni mesure) ; 'hd' (format haute
    # densite sans lecteur cible : courbe haute densite existante, jamais de calibration ni de mesure, controle des pistes
    # non applicable : Start-PresetWrite, Get-WriteCheckBlocker) ; 'sector' (copie secteur double densite, ou format detecte
    # a la lecture : calibration existante, sinon par tete, mesure de la destination quand c est possible). En derivent : la
    # phrase du lecteur cible du cadre 2 (Get-RsCalibText), la note de son infobulle (Update-RsCalib), les regles de la copie
    # (Update-RsRules) et, avant l ecriture, la ligne « Regles » du rapport (Write-RestoreReport ; apres : $r.Plan, decision
    # de Start-RestoreWrite)
    $ti = Get-RestoreTargetInfo $drv $tgt $fmt
    # 12.10 (relecture de la RC, fix1) : 'refused' pour tout refus de Start-Restore (Ti.Block), nature dans Ti.BlockKind ;
    # avant : refus faute de courbe croisee range sous 'target', regles de la copie qui annoncaient l ecriture avec la
    # courbe croisee a cote du refus annonce par le cadre
    $k = if (-not $fmt) { 'flux' } elseif ($ti.Block) { 'refused' } elseif ($ti.Applies) { 'target' } elseif ($fmt -ne 'auto' -and (Test-HdFormat $fmt)) { 'hd' } else { 'sector' }
    return @{ Kind = $k; Ti = $ti; Fmt = $fmt }
}

function Update-RsCalib {
    # Cadre 2 : resume des courbes et bouton « Courbe » (actif avec au moins une courbe) ; a l entree dans l onglet, a la
    # fin d une restauration et a chaque mise a jour du bouton « Courbe » de l onglet Ecriture (Update-CurveButton : fin
    # de calibration, effacement des calibrations, configuration chargee). 12.10 (relecture de la RC) : aussi au changement
    # du format de la restauration (Update-SettingDependents) ; infobulle et regles de la copie (Update-RsRules) selon le
    # lecteur cible : avec effet sur la restauration (Get-RestoreTargetInfo : copie secteur ecrite avec la courbe croisee
    # telle quelle, Start-RestoreWrite), l infobulle ne dit plus que le lecteur sans courbe est calibre, ce qui n a pas lieu
    # (avant : annonce a cote de « sans calibration », infobulle refaite seulement au changement du texte du cadre)
    if (-not $lblRsCal) { return }
    $t = Get-RsCalibText
    $src = [string]$cmbDrive.Text
    $tt = $t
    # 12.10 (relecture de la RC) : note d apres la decision de la restauration (Get-RestorePlan) : copie secteur double
    # densite ou format detecte, sans lecteur cible : calibration existante, sinon par tete ; format haute densite : jamais
    # de calibration ; copie de flux : ecrite telle quelle, sans ces courbes ; lecteur cible avec effet ou refus : aucune
    # note. Avant : note de la calibration d un lecteur sans courbe pour une copie de flux ou haute densite aussi
    $pk = (Get-RestorePlan $src (Get-TargetDrive $src) (Get-RestoreFormat)).Kind
    $note = if ($pk -eq 'sector') { (T "Une calibration existante n'est jamais refaite par la restauration. Sans courbe, le lecteur est calibré tête par tête en test fin, éventuellement sur une disquette sacrifiée, avant l'écriture de la copie.") }
            elseif ($pk -eq 'hd') { (T "La restauration ne calibre jamais le lecteur en haute densité : la copie est écrite avec la courbe haute densité existante, sinon avec le profil d'origine.") }
            elseif ($pk -eq 'flux') { (T "Une copie exacte du flux est écrite telle quelle par gw, sans précompensation : aucune de ces courbes ne s'y applique, et la restauration ne calibre pas le lecteur ni ne mesure la destination.") }
            else { '' }
    if ($note) { $tt += "`n`n" + $note }
    if ($lblRsCal.Text -ne $t) { $lblRsCal.Text = $t }
    if ([string]$tip.GetToolTip($lblRsCal) -ne $tt) { $tip.SetToolTip($lblRsCal, $tt) }
    # 12.10 (relecture de la RC) : courbes du bouton (Get-RsCurveSet, celles du clic) : courbe croisee ecrite pour un
    # lecteur cible avec effet ; avant : courbes du lecteur seulement, bouton grise sans elles
    $btnRsCurve.Enabled = (Get-RsCurveSet).Count -gt 0
    Update-RsRules
}

function Get-RsCurveSet {
    # 12.10 (relecture de la RC) : courbes du bouton « Courbe » du cadre 2 (etat actif : Update-RsCalib ; clic : Show-RsCurve) :
    # courbes croisees standard « source>cible » que la restauration ecrit pour un lecteur cible avec effet (Get-RestorePlan
    # 'target' sans refus : Start-RestoreWrite, Get-TargetWriteInfo), sinon courbes du lecteur (par tete si elles sont a
    # jour) de la famille de la copie (voir plus bas). Tableau protege par la virgule (pas de @() autour de l appel). Avant :
    # courbes du lecteur seulement
    $src = [string]$cmbDrive.Text; $tg = Get-TargetDrive $src
    # 12.10 (relecture de la RC, fix2) : decision de la restauration avec ou sans lecteur cible (Get-RestorePlan ; sans
    # lecteur cible : 'flux', 'hd' ou 'sector')
    $pl = Get-RestorePlan $src $tg (Get-RestoreFormat)
    # 12.10 (relecture de la RC, fix1) : aucune courbe quand la restauration n en ecrit aucune : refus pour le lecteur cible
    # (Get-RestorePlan 'refused' : haute densite, aucune courbe croisee) et copie exacte du flux (ecrite telle quelle, sans
    # precompensation) : bouton grise ; avant : courbes du lecteur, que rien n ecrirait
    $pk = [string]$pl.Kind
    if ($pk -eq 'refused' -or $pk -eq 'flux') { return ,@() }
    if ($pk -eq 'target') { return ,@(Get-TargetCurves 'std' $true $src $tg) }
    # 12.10 (relecture de la RC, fix2) : familles de la copie d apres la meme decision : 'hd' (format haute densite choisi) :
    # famille haute densite du format seule (Get-HdCalibFamily ; Start-RestoreWrite : courbe haute densite existante, sinon
    # le profil d origine) ; 'sector' au format double densite choisi : double densite seule (sans courbe, la copie calibre
    # d abord chaque tete) ; format detecte a la lecture ('auto') : double densite, a defaut haute densite. Avant : repli
    # sur l autre famille pour tout format (courbe double densite montree pour une copie haute densite, haute densite pour
    # une copie double densite)
    $hf = Get-HdCalibFamily '' ([string]$pl.Fmt)
    $fams = if ($pk -eq 'hd') { @($hf) } elseif ([string]$pl.Fmt -eq 'auto') { @('std', 'hd') } else { @('std') }
    foreach ($f in $fams) { if (-not $f) { continue }; $c = Get-FamilyCurves $f $true; if ($c.Count -gt 0) { return ,$c } }
    return ,@()
}

function Show-RsCurve {
    # Bouton « Courbe » du cadre 2 : courbes appliquees par la restauration (Get-RsCurveSet ; 12.10, relecture de la RC :
    # courbe croisee pour un lecteur cible avec effet, fenetre commune Show-CurvesWindow, titre « croisee »)
    $c = Get-RsCurveSet
    if ($c.Count -gt 0) { Show-CurvesWindow $c }
}

function Get-SafeFileName([string]$s) {
    $bad = [System.IO.Path]::GetInvalidFileNameChars()
    $o = -join @($s.ToCharArray() | ForEach-Object { if ($bad -contains $_) { '_' } else { $_ } })
    return $o.Trim().TrimEnd('.')
}

function Update-RsRules {
    # Texte gris des regles de la copie : Set-Defaults ; 12.10 (relecture de la RC) : aussi Update-RsCalib (entree dans
    # l onglet, lecteur du bandeau, lecteur cible ou format de la restauration changes). Lecteur cible avec effet sur la
    # restauration (Get-RestoreTargetInfo, format detecte a la lecture compris) : regles de Start-RestoreWrite pour lui,
    # courbe croisee telle quelle, ni calibration du lecteur ni mesure de la destination ; avant, le texte annoncait la
    # mesure et la calibration du lecteur, que la restauration ne fait pas dans ce cas
    if (-not $lblRsRules) { return }
    $r = $script:RestoreRules
    $src = [string]$cmbDrive.Text; $tg = Get-TargetDrive $src
    # 12.10 (relecture de la RC) : regles d apres la decision de la restauration (Get-RestorePlan, celle de Start-Restore et
    # de Start-RestoreWrite) : lecteur cible avec effet ; copie de flux (ecrite telle quelle par gw, sans precompensation ni
    # verification gw, ni calibration ni mesure, sans comparaison secteur par secteur) ; format haute densite refuse pour un
    # lecteur cible ; format haute densite (jamais de calibration ni de mesure, pre-effacement, controle des pistes non
    # applicable) ; sinon copie secteur double densite. Avant : regles de la copie secteur double densite pour une copie de
    # flux ou haute densite, et ecriture avec la courbe croisee pour un format haute densite refuse
    $pl = Get-RestorePlan $src $tg (Get-RestoreFormat)
    if ($pl.Kind -eq 'target') {
        $t = (T "Règles appliquées à la copie : écriture tête par tête par le lecteur {0} avec la courbe croisée {0} → {1}, telle quelle, sans calibration ni mesure de la destination, effacement avant l'écriture, vérification par gw, {2} essais par piste, contrôle de toutes les pistes ({3} passes de réécriture au plus), puis relecture par le lecteur {0} et comparaison avec l'original.") -f "$src", "$tg", "$($r.WriteRetries)", "$($r.RepairPasses)"
    } elseif ($pl.Kind -eq 'flux') {
        $t = (T "Règles appliquées à la copie : copie exacte du flux, écrite telle quelle par gw (ni précompensation, ni vérification par gw), sans calibration du lecteur ni mesure de la destination, écriture tête par tête, effacement avant l'écriture, contrôle de toutes les pistes ({0} passes de réécriture au plus), sans comparaison secteur par secteur avec l'original.") -f "$($r.RepairPasses)"
    } elseif ($pl.Kind -eq 'refused' -and $pl.Ti.BlockKind -eq 'hd') {
        $t = (T "Règles appliquées à la copie : aucune avec le lecteur cible {0}, la restauration au format haute densité {1} sera refusée au lancement (la calibration croisée n'existe qu'en double densité). Choisissez « (même lecteur) » dans la liste « Lecteur cible » de l'onglet Écriture.") -f "$tg", "$($pl.Fmt)"
    } elseif ($pl.Kind -eq 'refused') {
        # 12.10 (relecture de la RC, fix1) : refus faute de courbe croisee standard (Ti.BlockKind 'none', Start-Restore) ;
        # avant : range sous 'target', ecriture avec la courbe croisee annoncee a cote du refus annonce par le cadre
        $t = (T "Règles appliquées à la copie : aucune avec le lecteur cible {0} : sans courbe croisée standard {1} → {0}, la restauration sera refusée au lancement. Lancez « Calibrer pour un lecteur cible… », ou choisissez « (même lecteur) » dans la liste « Lecteur cible » de l'onglet Écriture.") -f "$tg", "$src"
    } elseif ($pl.Kind -eq 'hd') {
        $t = (T "Règles appliquées à la copie : écriture tête par tête avec la courbe haute densité existante du lecteur, sinon le profil d'origine, sans calibration ni mesure de la destination (jamais en haute densité), pré-effacement de chaque piste, vérification par gw, {0} essais par piste, sans contrôle des pistes (non applicable à la haute densité), puis relecture et comparaison avec l'original.") -f "$($r.WriteRetries)"
    } elseif ((Get-LevelBeforeWriteKind 'slow' $true $false) -eq 'complete') {
        # 12.10 (relecture de la RC) : liste « Mesure » de l onglet Ecriture a « complete, au motif » : mesure complete de la
        # destination (Get-LevelBeforeWriteKind, decision de Start-LevelBeforeWrite -Restore : ecriture lente), case « Mesurer
        # la disquette » cochee ou non. Avant : « calibration rapide » annoncee dans ce cas aussi
        $t = (T "Règles appliquées à la copie : disquette de destination mesurée avant l'écriture quand c'est possible (mesure complète de cette disquette, liste « Mesure » de l'onglet Écriture), écriture tête par tête avec la calibration existante du lecteur (calibration par tête si aucune n'existe), effacement avant l'écriture, vérification par gw, {0} essais par piste, contrôle de toutes les pistes ({1} passes de réécriture au plus), puis relecture et comparaison avec l'original.") -f "$($r.WriteRetries)", "$($r.RepairPasses)"
    } else {
        $t = (T "Règles appliquées à la copie : disquette de destination mesurée avant l'écriture quand c'est possible (calibration rapide), écriture tête par tête avec la calibration existante du lecteur (calibration par tête si aucune n'existe), effacement avant l'écriture, vérification par gw, {0} essais par piste, contrôle de toutes les pistes ({1} passes de réécriture au plus), puis relecture et comparaison avec l'original.") -f "$($r.WriteRetries)", "$($r.RepairPasses)"
    }
    if ($lblRsRules.Text -ne $t) { $lblRsRules.Text = $t }
}

function Set-RsStep([int]$i, [string]$state, [string]$detail = '') {
    # 12.8 (lot 3b) : glyphe garde dans le texte (infobulle, rapport) ; l etape est dessinee avec l icone d etat de 16 px
    # (Draw-RsStepLabel, d apres Tag) ; « ! » en Theme.WarnInk (Theme.Warn : 2,75:1 sur blanc, sous le minimum du texte)
    $g = @{ pending = '○'; run = '▶'; ok = '✓'; fail = '✗'; skip = '–'; warn = '!' }[$state]
    $c = @{ pending = $script:Theme.Muted; run = $script:Theme.Accent; ok = $script:Theme.Ok; fail = $script:Theme.Danger; skip = $script:Theme.Muted; warn = $script:Theme.WarnInk }[$state]
    $l = $script:RsStepLabels[$i]
    $l.Tag = $state
    $l.Text = "$g  " + $script:RsStepNames[$i] + $(if ($detail) { "  -  $detail" } else { '' })
    $l.ForeColor = $c
    $l.Invalidate()
    $l.Font = if ($state -eq 'run') { $bold } else { $form.Font }
    $tip.SetToolTip($l, $l.Text)
    if ($script:Restore) {
        $script:Restore.Steps[$i] = @{ State = $state; Detail = $detail }
        if ($state -eq 'run') { $script:Restore.Cur = $i }
    }
}

function Reset-RsSteps {
    for ($i = 0; $i -lt $script:RsStepNames.Count; $i++) { Set-RsStep $i 'pending' }
    $pnlRsWait.Visible = $false; $lblRsResult.Visible = $false; $lblRsNow.Text = ''; $lblRsRules.Visible = $true
}

function Set-RsLock([bool]$lock) {
    # Pendant une restauration : seuls l onglet Restauration et le bouton Arreter restent utilisables ; le lecteur du
    # bandeau, celui de la restauration (12.8, D10), ne change pas
    foreach ($p in $script:AllTabs) { if ($p -ne $tabRs) { $p.Enabled = -not $lock } }
    foreach ($c in @($grpRsSrc, $grpRsCal, $grpRsDir, $btnRsStart, $cmbDrive, $chkExpert)) { $c.Enabled = -not $lock }
    $btnCfgReset.Enabled = -not $lock -and -not ($script:GwProc -and -not $script:GwProc.HasExited)
    $btnCfgSave.Enabled = $btnCfgReset.Enabled
}

function Save-WriteTabState {
    return @{ File = $txtWFile.Text; Fmt = $cmbWFmt.Text; Slow = $chkWSlow.Checked; Pre = $chkWPreErase.Checked; Empty = $chkWEraseEmpty.Checked
              NoVer = $chkWNoVerify.Checked; Retries = $numWRetries.Value; Precomp = $chkWPrecomp.Checked; Post = $chkWPostCheck.Checked
              Repair = $numWRepair.Value; Tracks = $txtWTracks.Text; CalMode = $cmbWCalMode.SelectedIndex; Profile = $cmbWProfile.SelectedIndex
              P0 = $txtWPrecomp.Text; P1 = $txtWPrecomp1.Text; Drive = $cmbDrive.Text; Source = $script:PresetSource }
}

function Restore-WriteTabState($s) {
    # Onglet Ecriture et lecteur remis tels qu avant la restauration (les calibrations obtenues restent enregistrees)
    if (-not $s) { return }
    # 12.10 (relecture de la RC) : format remis sous la garde des liaisons (gestionnaires de la liste, 520, sans effet) :
    # Update-PrecompForImage, plus bas, recalcule avec tous les reglages remis, sans calcul du au format ; la case « Ecriture
    # lente » et le profil, remis apres la garde, gardent leurs liaisons (un calcul chacun quand ils changent, comme en 12.9)
    $txtWFile.Text = $s.File
    $sv = $script:SettingSync; $script:SettingSync = $true
    try { Set-Combo $cmbWFmt $s.Fmt; if ($cmbWFmt.Text -ne $s.Fmt) { $cmbWFmt.Text = $s.Fmt } } finally { $script:SettingSync = $sv }
    $chkWSlow.Checked = $s.Slow; $chkWPreErase.Checked = $s.Pre; $chkWEraseEmpty.Checked = $s.Empty; $chkWNoVerify.Checked = $s.NoVer
    Set-Num $numWRetries $s.Retries; $chkWPrecomp.Checked = $s.Precomp; $chkWPostCheck.Checked = $s.Post; Set-Num $numWRepair $s.Repair
    $txtWTracks.Text = $s.Tracks; $cmbWCalMode.SelectedIndex = $s.CalMode; $cmbWProfile.SelectedIndex = $s.Profile
    $script:PresetSource = $s.Source
    $cmbDrive.SelectedItem = $s.Drive
    Update-PrecompForImage $txtWFile.Text
    if ($cmbWProfile.Text -eq (T 'Manuel')) { $txtWPrecomp.Text = $s.P0; $txtWPrecomp1.Text = $s.P1 }
    $chkWPrecomp.Checked = $s.Precomp                      # Set-PrecompFields la recoche
}

function Start-Restore {
    if ($script:Restore) { return }
    # 12.8 (D20) : test d occupation unique (Get-AppBusy) ; boites par Show-AppMessage (texte aussi ecrit au journal)
    $busy = Get-AppBusy -Text
    if ($busy) {
        Append-Log ((T "Restauration refusée : opération en cours ({0}).") -f "$busy")
        [void](Show-AppMessage (T 'Une opération est déjà en cours : attendez sa fin ou cliquez sur « Arrêter ».') (T 'Restauration') 'OK' 'Information'); return
    }
    # 12.11 (lot LN-b) : avec des lecteurs enregistres, lecteur branche confirme s il y a lieu (Confirm-DriveIdentity, 112) ;
    # refus : restauration non lancee
    if ($script:DriveReg.Count -gt 0 -and -not (Confirm-DriveIdentity)) { return }
    if (-not (Test-Path -LiteralPath $script:GwExe)) {
        [void](Show-AppMessage ((T "gw.exe introuvable : {0}`n`nPlacez ce script dans le même répertoire que gw.exe.") -f "$($script:GwExe)") (T 'Erreur') 'OK' 'Error'); return
    }
    if (-not $script:ScpStatsOk) {
        [void](Show-AppMessage (T "Restauration impossible : le module d'analyse de flux n'a pas pu être compilé, le contrôle strict des pistes n'est donc pas disponible.") (T 'Restauration') 'OK' 'Warning'); return
    }
    if ($chkWHard.Checked -or $chkWTG43.Checked) {
        [void](Show-AppMessage (T 'Restauration non prise en charge avec « Secteurs durs » ou « TG43 » cochés dans les options avancées de l''onglet Écriture : le contrôle des pistes est calibré pour le MFM double densité.') (T 'Restauration') 'OK' 'Warning'); return
    }
    $fmt = Get-RestoreFormat
    $dir = $txtRsDir.Text.Trim()
    if (-not $dir) { $dir = Get-RestoreDefaultDir }
    if (-not [System.IO.Path]::IsPathRooted($dir)) { $dir = Join-Path $script:AppDir $dir }
    try { $dir = [System.IO.Path]::GetFullPath($dir) } catch { }
    try { New-Item -ItemType Directory -Force -Path $dir -ErrorAction Stop | Out-Null }
    catch { [void](Show-AppMessage ((T "Dossier de sauvegarde inaccessible : {0}") -f "$($_.Exception.Message)") (T 'Restauration') 'OK' 'Warning'); return }
    $name = Get-SafeFileName $txtRsName.Text
    if (-not $name) { $name = (T 'disquette') + ' ' + (Get-Date -Format "yyyy-MM-dd HH'h'mm") }
    # 12.8 (D10) : un seul lecteur, celui du bandeau, fige pour toute la restauration (Set-RsLock verrouille le bandeau)
    $drv = [string]$cmbDrive.Text
    # 12.10 : lecteur cible choisi pour ce lecteur (liste « Lecteur cible » de l onglet Ecriture) : une copie secteur est
    # ecrite avec la courbe croisee de sa famille (Start-RestoreWrite) ; refus avant la lecture de l original quand
    # l ecriture serait refusee (Get-RestoreTargetInfo : haute densite, aucune courbe croisee standard du couple)
    $rtg = Get-TargetDrive $drv
    $rti = Get-RestoreTargetInfo $drv $rtg $fmt
    if ($rti.Block) { [void](Show-AppMessage $rti.Block (T 'Restauration') 'OK' 'Warning'); return }
    $modeTxt = if ($fmt -eq 'auto') { (T 'format détecté à la lecture') } elseif ($fmt) { (T "secteur par secteur, format {0}") -f "$fmt" } else { (T 'copie exacte du flux, sans précompensation ni comparaison par secteur') }
    $swap = (T "Le lecteur {0} lit l'original, puis vous changez de disquette quand l'application vous le demande.") -f "$drv"
    $msg = ((T "Restauration ({0}).`n`n{1}`n`n1. Insérez maintenant la disquette d'ORIGINE dans le lecteur {2}, de préférence protégée en écriture.`n2. Sa lecture est enregistrée dans :`n   {3}`n3. La disquette de destination sera entièrement effacée puis écrite.`n`nCommencer la lecture ?") -f "$modeTxt", "$swap", "$drv", "$dir")
    # 12.8 (D3) : confirmation par frmConfirm, case qui nomme le lecteur de l original
    $cq = @{ Title = (T 'Restauration'); Heading = (T 'Restaurer une disquette'); Text = $msg; Level = 'info'; Picto = 'data'
             Check = ((T "La disquette d'ORIGINE est dans le lecteur {0}") -f "$drv"); GoText = (T 'Commencer la lecture'); GoGlyph = 'Download' }
    if (-not (Show-AppConfirm @cq)) { return }
    $txtRsDir.Text = $dir
    # 12.8 (D4, L1 ecart 8) : reglages de l onglet Ecriture en surcharge d operation, ecrits a leur place dans la
    # configuration pendant la restauration, retablis par Close-Restore ; surcharge precedente terminee d abord
    if ($script:OpOverride) { Exit-OpOverride }
    Enter-OpOverride 'restore'
    # Mode, format, extension et chemins : Set-RestoreFormat, tout de suite pour un format choisi ou le flux, apres la
    # detection en mode automatique (Complete-RestoreDetect)
    $script:Restore = @{
        Mode = ''; Fmt = ''; Ext = ''; Choice = $fmt; Drive = $drv; Name = $name; Dir = $dir; Found = ''; FluxRetry = $false
        Orig = ''; Back = ''; Report = ''; Probe = ''; FakeIndex = $false   # 12.8.2 : FakeIndex, Invoke-RestoreRead
        # FIX2 : debut des chemins fixe des le lancement (Get-RestoreStem) ; FluxWhy : raison courte d une copie de flux
        # decidee par la detection ou par la relance D12 (etape 2 en « ! ») ; FmtName : nom court du format detecte ;
        # SectorRead : lecture secteur incomplete conservee avant une relance D12 (Path, Miss, Extra)
        Stem = (Get-RestoreStem $dir $name); FluxWhy = ''; FmtName = ''; SectorRead = $null
        Stage = 'read'; Waiting = $false; Override = $false; InCall = $false; Idle = (Get-Date); Start = (Get-Date); Cur = 0
        Steps = @{}; Saved = $script:OpOverride.Saved; Read = $null; Cmp = $null; Calib = ''; HD = ''
        CalibUsed = $null; CalibDone = $false; CalSwap = $false; SwapBack = $false
        Target = ''                                       # 12.10 : lecteur cible de l ecriture (Start-RestoreWrite)
        Plan = ''; TgtChoice = $rtg                       # 12.10 (relecture de la RC) : decision de l ecriture (Start-RestoreWrite) et lecteur cible du lancement : ligne « Regles » du rapport
        Finger = $null; OnOriginal = $false; Preserved = @()   # flux : empreinte de l original, ecriture sur l original, cylindres preserves
        Extras = (Get-TSpecExtras $txtWTracks.Text)       # step, hswap, h0.off, h1.off : geometrie du lecteur
    }
    $script:LastCheck = $null
    Reset-RsSteps; Set-RsLock $true
    if (-not (Test-Path -LiteralPath $script:TempDir)) { New-Item -ItemType Directory -Force -Path $script:TempDir | Out-Null }
    Append-Log ''
    Append-Log ((T "=== RESTAURATION : {0} ({1}) ===") -f "$name", "$modeTxt")
    if ($rti.Applies) { Append-Log ((T "Restauration pour le lecteur cible {0} : une copie secteur sera écrite par le lecteur {1} avec la courbe croisée {1} → {0} de sa famille, sans calibration ni mesure de la destination ; le contrôle après écriture relit avec le lecteur {1}.") -f "$rtg", "$drv") }
    if ($fmt -eq 'auto') { $lblRsFmtFound.Text = (T 'Format détecté à la lecture'); $tip.SetToolTip($lblRsFmtFound, $lblRsFmtFound.Text); Start-RestoreDetect; return }
    Set-RestoreFormat $fmt
    Append-Log ((T "Original : lecteur {0} -> {1}") -f "$drv", "$($script:Restore.Orig)")
    Invoke-RestoreRead
}

function Start-RestoreDetect {
    # 12.8 (point 4, D12) : detection automatique du format, phase de l etape 1 (« Lire la disquette d origine ») : les
    # huit etapes et leurs index ne changent pas. Lecture de deux pistes et decodages hors ligne (Invoke-DiskFormatDetect,
    # 185), decision (Select-DiskFormat), puis Complete-RestoreDetection : format retenu, copie exacte du flux (format
    # inconnu en double densite, protection probable : D12) ou arret avant toute ecriture (disquette vierge, format haute
    # densite inconnu). Geometrie du lecteur (step, hswap) comme la lecture complete et la sonde
    $r = $script:Restore
    $r.Stage = 'detect'
    Set-RsStep 0 'run' (T 'identification du format (pistes 0.0 et 0.1)')
    Invoke-DiskFormatDetect 'restore' $r.Extras
}

function Complete-RestoreDetection($res) {
    # Fin de la detection (Complete-DiskFormatDetect) : arret (etape 1, rien n est ecrit, rapport sans chemin d original),
    # copie exacte du flux, ou lecture secteur du format retenu
    $r = $script:Restore
    if (-not $r -or $r.Stage -ne 'detect') { return }
    # FIX2 : ligne courte du cadre 1 (Get-RsFmtFoundLine), texte complet en infobulle ; raison d une copie de flux gardee
    # pour l etape 2 (« ! »)
    $short = Get-RsFmtFoundLine $res
    $r.FmtName = [string]$res.Name
    if ($res.Action -eq 'stop') { $lblRsFmtFound.Text = $short; $tip.SetToolTip($lblRsFmtFound, $res.Text); $r.Found = $res.Text; Fail-Restore 0 $res.Text; return }
    if ($res.Action -eq 'flux') { $r.FluxWhy = [string]$res.Why; Complete-RestoreDetect '' $res.Text $short; return }
    Complete-RestoreDetect $res.Format $res.Text $short
}

function Complete-RestoreDetect([string]$fmt, [string]$found, [string]$short = '') {
    # Fin de la detection, ou relance d office en copie de flux apres une lecture secteur incomplete (D12) : format retenu
    # ($fmt ; '' = copie exacte du flux), texte du rapport et de l infobulle du cadre 1 ($found), ligne courte du cadre 1
    # ($short, a defaut $found), chemins calcules (Set-RestoreFormat), puis lecture complete, comme pour un choix manuel
    $r = $script:Restore
    if (-not $r) { return }
    $r.Stage = 'read'; $r.Found = $found
    Set-RestoreFormat $fmt
    $lblRsFmtFound.Text = $(if ($short) { $short } else { $found })
    $tip.SetToolTip($lblRsFmtFound, $found)
    Append-Log ((T "Original : lecteur {0} -> {1}") -f "$($r.Drive)", "$($r.Orig)")
    Invoke-RestoreRead
}

function Invoke-RestoreRead {
    $r = $script:Restore
    Set-RsStep 0 'run'
    $a = @('read') + (Get-CommonArgs) + @(Get-DriveReadArgs)
    # 12.8.2 : original lu avec un index simule (--fake-index) : zone de l index comptee a l analyse du flux (Read-ScpFile)
    $r.FakeIndex = (@($a | Where-Object { "$_" -match '^--fake-index=' }).Count -gt 0)
    if ($r.Mode -eq 'sector') {
        $a += @("--format=$($r.Fmt)", "--revs=$($script:RestoreRules.ReadRevs)", "--retries=$($script:RestoreRules.ReadRetries)", "--seek-retries=$($script:RestoreRules.SeekRetries)")
    } else {
        $a += "--revs=$($script:RestoreRules.ReadRevs)"
    }
    if ($r.Extras) { $a += "--tracks=$($r.Extras.TrimStart(':'))" }
    $a += "`"$($r.Orig)`""
    $script:RestoreArgs = $a
    $script:GwCapture = New-Object System.Collections.Generic.List[string]
    $script:Chain.Clear()
    $script:Chain.Enqueue({ Start-Gw $script:RestoreArgs })
    $script:Chain.Enqueue({ Invoke-RestoreNext })
    Invoke-NextChainStep
}

function Invoke-RestoreNext {
    $r = $script:Restore
    if (-not $r) { return }
    $r.Idle = Get-Date
    switch ($r.Stage) {
        'read'    { Complete-RestoreRead }
        'probe'   { Complete-RestoreProbe }
        'write'   { Start-RestoreCompare }
        'compare' { Complete-RestoreCompare }
    }
}

function Get-GwSectorSummary($lines) {
    # Bilan d une lecture gw avec format : « T0.0: AmigaDOS (11/11 sectors) from ... » (derniere ligne de la piste),
    # « T0.0: Giving up: 2 sectors missing », « Found 1758 sectors of 1760 (99%) ». 12.8 (FIX2) : « T1.0: Ignoring unexpected
    # sector C:1 H:0 R:10 N:2 » (decodeur IBM a format fixe de gw : secteur valide hors du format, ni compte ni copie,
    # imprime a chaque essai) : Extra, cle « cyl.tete » -> secteurs distincts (C:H:R:N)
    $tracks = @{}; $gaveUp = @{}; $extra = @{}; $found = -1; $total = -1
    foreach ($l in @($lines)) {
        if ($l -match '^T(\d+)\.(\d+)\b[^:]*: Ignoring unexpected sector (C:\d+ H:\d+ R:\d+ N:\d+)') {
            $k = "$([int]$Matches[1]).$([int]$Matches[2])"
            if (-not $extra.ContainsKey($k)) { $extra[$k] = @{} }
            $extra[$k][$Matches[3]] = $true
        }
        elseif ($l -match '^T(\d+)\.(\d+)\b[^:]*: Giving up: (\d+) sectors? missing') { $gaveUp["$($Matches[1]).$($Matches[2])"] = [int]$Matches[3] }
        elseif ($l -match '^T(\d+)\.(\d+)\b[^:]*: .*\((\d+)/(\d+) sectors\)') { $tracks["$($Matches[1]).$($Matches[2])"] = @([int]$Matches[3], [int]$Matches[4]) }
        elseif ($l -match '^Found (\d+) sectors of (\d+)') { $found = [int]$Matches[1]; $total = [int]$Matches[2] }
    }
    $nx = 0; foreach ($k in @($extra.Keys)) { $nx += $extra[$k].Count }
    return @{ Tracks = $tracks; GaveUp = $gaveUp; Found = $found; Total = $total; Extra = $extra; ExtraCount = $nx }
}

function Get-BadSectorBlocks([string]$path) {
    # Blocs de 512 octets remplis par gw du motif « -=[BAD SECTOR]=- » (secteur manquant a la lecture) ; meme test que la
    # comparaison (Get-BadSectorIndexes, 180)
    return ,(Get-BadSectorIndexes ([System.IO.File]::ReadAllBytes($path)))
}

function Get-BlockTracks([int[]]$blocks, [string]$fmt) {
    # Pistes « cyl.tete » des blocs (image double face entrelacee, secteurs par piste du format)
    $spt = Get-SectorsPerTrack $fmt
    $set = @{}
    if ($spt -le 0) { return @() }
    foreach ($b in $blocks) { $t = [math]::Floor($b / $spt); $set["$([math]::Floor($t / 2)).$($t % 2)"] = $true }
    return (Sort-TrackKeys @($set.Keys))         # elements emis un par un : @() chez l appelant reste plat
}

function Complete-RestoreRead {
    $r = $script:Restore
    $lines = @(); if ($script:GwCapture) { $lines = @($script:GwCapture) }
    $script:GwCapture = $null
    if (-not (Test-Path -LiteralPath $r.Orig) -or (Get-Item -LiteralPath $r.Orig).Length -eq 0) {
        Fail-Restore 0 (T 'la lecture n''a produit aucun fichier (disquette absente ou lecteur incorrect ?)'); return
    }
    Set-RsStep 0 'ok' (Split-Path -Leaf $r.Orig)
    Set-RsStep 1 'run'
    if ($r.Mode -eq 'sector') {
        $sum = Get-GwSectorSummary $lines
        $bad = Get-BadSectorBlocks $r.Orig
        $miss = @($sum.GaveUp.Keys) + @(Get-BlockTracks $bad $r.Fmt)
        $miss = Sort-TrackKeys @($miss | Select-Object -Unique)
        # FIX2 : secteurs valides hors du format, ignores par gw (« Ignoring unexpected sector ») : une copie secteur par
        # secteur les perdrait, ils comptent comme des secteurs illisibles
        $nX = [int]$sum.ExtraCount
        $xTk = Sort-TrackKeys @($sum.Extra.Keys)
        $r.Read = @{ Found = $sum.Found; Total = $sum.Total; Bad = $bad.Count; Tracks = $miss; Extra = $nX; ExtraTracks = $xTk }
        if ($sum.Total -le 0) { Fail-Restore 1 (T 'gw n''a imprimé aucun bilan de secteurs : format incorrect, ou disquette illisible ?'); return }
        $nMiss = [math]::Max($bad.Count, $sum.Total - $sum.Found)
        if (($nMiss -gt 0 -or $nX -gt 0) -and $r.Choice -eq 'auto' -and -not $r.FluxRetry -and -not (Test-HdFormat $r.Fmt)) {
            # 12.8 (D12) : detection automatique, double densite : protection contre la copie hors des pistes 0.0 et 0.1
            # probable (ou tetes sales) : relance d office de la lecture en copie exacte du flux, une lecture ne detruisant
            # rien ; le flux est ensuite juge piste par piste comme une copie de flux choisie (tetes sales : pistes
            # critiques, arret avant l ecriture). Haute densite : arret de la 12.7 (copie de flux non controlable).
            # FIX2 : la lecture secteur est gardee sous « <nom> - lecture secteur incomplete.<ext> » et citee au rapport ;
            # secteurs hors du format : meme relance
            $r.FluxRetry = $true
            $all = Sort-TrackKeys @(@($miss) + @($xTk) | Select-Object -Unique)
            if ($nX -gt 0) {
                $t = (T "{0} secteur(s) hors du format {1} ignoré(s) par gw en lecture secteur (pistes {2}), {3} secteur(s) illisible(s) : protection contre la copie ou format étendu probable. Relance automatique de la lecture en copie exacte du flux, sans comparaison par secteur.") -f "$nX", "$($r.Fmt)", "$(Format-TrackList $all)", "$nMiss"
                $r.FluxWhy = (T 'relance : secteurs hors du format')
            } else {
                $t = (T "{0} secteur(s) illisible(s) en lecture secteur (pistes {1}) : protection contre la copie probable, ou têtes sales. Relance automatique de la lecture en copie exacte du flux, sans comparaison par secteur.") -f "$nMiss", "$(Format-TrackList $miss)"
                $r.FluxWhy = (T 'relance après une lecture secteur incomplète')
            }
            Append-Log ((T "Restauration : {0}") -f $t)
            $keep = $r.Stem + ' - ' + (T 'lecture secteur incomplète') + $r.Ext
            try { [System.IO.File]::Move($r.Orig, $keep) } catch { $keep = $r.Orig }
            $r.SectorRead = @{ Path = $keep; Miss = $nMiss; Extra = $nX }
            Append-Log ((T "Restauration : lecture secteur incomplète conservée : {0}") -f $keep)
            Set-RsStep 1 'pending'
            $f = $(if ($r.Found) { $r.Found + ' ' } else { '' }) + $t
            Complete-RestoreDetect '' $f (Get-RsFmtFoundLine @{ Action = 'flux'; Name = $(if ($r.FmtName) { $r.FmtName } else { $r.Fmt }) })
            return
        }
        if ($nMiss -eq 0 -and $nX -gt 0) {
            # FIX2 : choix manuel ou haute densite : arret avant toute ecriture (12.7 : copie sans ces secteurs, reussie)
            $tx = (T "{0} secteur(s) hors du format {1} ignoré(s) par gw (pistes {2}) : une copie secteur par secteur les perdrait (protection contre la copie, ou format étendu probable).") -f "$nX", "$($r.Fmt)", "$(Format-TrackList $xTk)"
            if (-not (Test-HdFormat $r.Fmt)) { $tx += ' ' + (T 'Relancez avec « Copie exacte du flux », ou choisissez le format exact de la disquette.') }
            Fail-Restore 1 $tx
            return
        }
        if ($nMiss -gt 0) {
            # Secteurs illisibles regroupes sur une ou deux pistes : protection contre la copie probable
            $nTk = @($miss).Count
            $fmtMiss = if ($nTk -ge 1 -and $nTk -le 2) { (T "{0} secteur(s) illisible(s), regroupés sur la ou les pistes {1} : c'est souvent une protection contre la copie (secteurs volontairement illisibles), qu'une copie secteur par secteur ne peut pas reproduire. Relancez avec « Copie exacte du flux ».") }
                       else { (T "{0} secteur(s) illisible(s) sur l'original (pistes {1}) : une copie fidèle est impossible. Nettoyez les têtes du lecteur et relancez, ou choisissez « Copie exacte du flux » si la disquette est protégée contre la copie.") }
            Fail-Restore 1 ($fmtMiss -f "$nMiss", "$(Format-TrackList $miss)")
            return
        }
        Set-RsStep 1 'ok' ((T "{0}/{1} secteurs lus") -f "$($sum.Found)", "$($sum.Total)")
        Append-Log ((T "Restauration : original lu en entier, {0}/{1} secteurs.") -f "$($sum.Found)", "$($sum.Total)")
    } else {
        # Flux : qualite piste par piste (MFM double densite) ; la decision revient a l utilisateur au changement de disquette
        if (Test-ScpHighDensity $r.Orig) {
            # Copie de flux HD : ni precompensation, ni verification gw, ni controle des pistes -> rien ne serait verifie
            Fail-Restore 1 (T 'flux haute densité : une copie de flux ne pourrait pas être contrôlée. Choisissez un format haute densité (amiga.amigados_hd, ibm.1440) pour une copie vérifiée secteur par secteur.'); return
        } else {
            try { $t = Read-ScpFile $r.Orig -Finger -NoIndexZone:([bool]$r.FakeIndex) } catch { Fail-Restore 1 ((T "flux illisible : {0}") -f "$($_.Exception.Message)"); return }
            $n = 0; $sane = 0; $watch = 0; $crit = 0; $critKeys = @{}; $weakKeys = @{}; $unstKeys = @{}; $noMeas = @{}; $overKeys = @{}; $fp = $null; $maxTn = 0
            foreach ($tn in @($t.Keys | Sort-Object)) {
                # Original juge aux seuils Standard (120 / 250 ns), independants du reglage du jitter
                $m = Get-TrackMetrics $t[$tn]; $n++
                $lv = if ($m.Bad) { 2 } else { Get-HealthLevel $m.Ooc $m.Dr $m.Stab $m.J $script:JitterStdOk $script:JitterStdWatch }
                $key = "$([math]::Floor([int]$tn / 2)).$([int]$tn % 2)"
                if ([int]$tn -gt $maxTn) { $maxTn = [int]$tn }
                if ($lv -ge 2) { $crit++; $critKeys[$key] = $true } elseif ($lv -ge 1) { $watch++ } else { $sane++ }
                # Zone instable d un tour a l autre : bits faibles d une protection probable, non reproductibles
                if ($m.Weak) { $weakKeys[$key] = $true } elseif ($m.ShortUnstable -and $lv -lt 2) { $unstKeys[$key] = $true }
                elseif ($lv -lt 2 -and $m.Blocks -eq 0) { $noMeas[$key] = $true }
                # 12.8.2 (decision du 27/10/2026) : deja hors norme par ses erreurs (Copylock, defaut d origine), ni critique
                # ni a zone instable : une reecriture ne peut pas la corriger, ignoree au controle de la copie
                if ($lv -lt 2 -and -not $m.Weak -and (Test-SrcOverErr $m)) { $overKeys[$key] = $true }
                # Empreinte : piste stable la plus riche en motifs, pour reconnaitre l original dans le lecteur de destination
                $r0 = $t[$tn][0]
                if ($lv -lt 2 -and -not $m.Weak -and $r0.Finger -and $r0.Finger.Count -ge 6 -and (-not $fp -or $r0.Rich -gt $fp.Rich)) {
                    $fp = @{ Tn = [int]$tn; Cyl = [int][math]::Floor([int]$tn / 2); Head = [int]$tn % 2; Fp = [string[]]$r0.Finger; Cell = [double]$r0.Cell; Rich = [int]$r0.Rich }
                }
            }
            if ($n -eq 0) { Fail-Restore 1 (T 'aucune piste dans le flux lu.'); return }
            if ($sane -eq 0 -or $crit * 2 -gt $n) {
                # 12.8 (L6-TEXTES) : un seul lecteur depuis le lot 2 : « lecteurs inverses » devient l original laisse dans un
                # autre lecteur que celui du bandeau (le lecteur lu porte alors une autre disquette)
                Fail-Restore 1 ((T "lecture sans données exploitables : {0} piste(s) critique(s) sur {1}. Disquette vierge, original dans un autre lecteur que le lecteur {2}, ou têtes sales ?") -f "$crit", "$n", "$($r.Drive)"); return
            }
            # Pistes deja critiques (cylindres non formates, protection) ou a zone instable (bits faibles) sur l original :
            # ni reecrites ni comptees au controle de la copie, jamais reecrites sur une disquette identique a l original
            $r.Read = @{ Tracks = $n; Sane = $sane; Watch = $watch; Crit = $crit; CritKeys = $critKeys; WeakKeys = $weakKeys; UnstKeys = $unstKeys; NoMeas = $noMeas; OverKeys = $overKeys; MaxCyl = [int][math]::Floor($maxTn / 2) }
            $r.Finger = $fp
            $txt = if ($weakKeys.Count -gt 0) { (T "{0} pistes : {1} saines, {2} à surveiller, {3} critiques, {4} à zone instable") -f "$n", "$sane", "$watch", "$crit", "$($weakKeys.Count)" }
                   else { (T "{0} pistes : {1} saines, {2} à surveiller, {3} critiques") -f "$n", "$sane", "$watch", "$crit" }
            # FIX2 (A1 § 3.5) : copie de flux decidee par la detection automatique ou par la relance D12 : etape en « ! », raison
            $st2 = $(if ($crit -gt 0 -or $weakKeys.Count -gt 0) { 'warn' } else { 'ok' }); $d2 = $txt
            if ($r.Choice -eq 'auto' -and $r.FluxWhy) { $st2 = 'warn'; $d2 = ((T "copie exacte du flux, {0}") -f "$($r.FluxWhy)") + ' ; ' + $txt }
            Set-RsStep 1 $st2 $d2
            Append-Log ((T "Restauration : flux de l'original, {0}.") -f "$txt")
            if ($weakKeys.Count -gt 0) {
                Append-Log ((T "Restauration : {0} piste(s) non reproductible(s) sur l'original, zone instable d'un tour à l'autre ({1}) : bits faibles d'une protection contre la copie probable, ou défaut localisé. La copie n'en recevra qu'un tour figé : la protection risque de ne pas fonctionner. Ces pistes ne sont jamais réécrites sur une disquette identique à l'original.") -f "$($weakKeys.Count)", "$(Format-TrackList (Sort-TrackKeys @($weakKeys.Keys)))")
            }
            if ($unstKeys.Count -gt 0) {
                Append-Log ((T "Restauration : {0} piste(s) avec une courte zone instable ({1}) : raccord d'écriture ou protection possible. Elles ne seront jamais réécrites sur une disquette identique à l'original.") -f "$($unstKeys.Count)", "$(Format-TrackList (Sort-TrackKeys @($unstKeys.Keys)))")
            }
            if ($fp) { Append-Log ((T "Restauration : empreinte de l'original prise sur la piste {0}.{1} ({2} blocs de référence) : la disquette de destination y sera comparée.") -f "$($fp.Cyl)", "$($fp.Head)", "$($fp.Fp.Count)") }
            else { Append-Log (T "Restauration : aucune piste de l'original ne permet une empreinte fiable : la disquette de destination ne pourra pas être comparée à l'original.") }
        }
    }
    Enter-RestoreWait ''
}

function Enter-RestoreWait([string]$extra) {
    $r = $script:Restore
    $r.Stage = 'wait'; $r.Waiting = $true
    Set-RsStep 2 'run'
    # 12.8 (D10) : un seul lecteur, le changement de disquette est toujours demande
    $msg = if ($r.SwapBack) { (T "Calibration terminée. Retirez la disquette sacrifiée du lecteur {0} et insérez la disquette de DESTINATION : tout son contenu sera remplacé. Elle sera de nouveau vérifiée avant l'écriture.") -f "$($r.Drive)" }
           else { (T "Retirez l'ORIGINAL du lecteur {0} et rangez-le. Insérez la disquette de DESTINATION : tout son contenu sera remplacé.") -f "$($r.Drive)" }
    if ($extra) { $msg = $extra + "`n" + $msg }
    if ($r.Mode -eq 'flux' -and $r.Read -and $r.Read.WeakKeys -and $r.Read.WeakKeys.Count -gt 0) { $msg = ((T "PROTECTION PROBABLE : {0} piste(s) de l'original changent d'un tour à l'autre (bits faibles) : une copie ne peut pas les reproduire et risque de ne pas fonctionner.") -f "$($r.Read.WeakKeys.Count)") + "`n" + $msg }
    if ($r.Mode -eq 'flux' -and $r.Read -and $r.Read.Crit -gt 0) { $msg = ((T "{0} piste(s) critique(s) dans la lecture : normal pour une protection, sinon nettoyez le lecteur et relancez.") -f "$($r.Read.Crit)") + "`n" + $msg }
    $lblRsWait.Text = $msg + ' ' + (T 'Puis cliquez sur « Continuer ».')
    $btnRsForce.Visible = [bool]$r.Override
    # Boutons sous le texte (hauteur variable) ; « Ecraser quand meme » seul sur une seconde ligne
    $y = $lblRsWait.Bottom + 8
    $btnRsGo.Location = New-Object System.Drawing.Point(8, $y)
    $btnRsCancel.Location = New-Object System.Drawing.Point(($btnRsGo.Right + 8), $y)
    $bottom = $btnRsGo.Bottom
    if ($r.Override) { $btnRsForce.Location = New-Object System.Drawing.Point(8, ($btnRsGo.Bottom + 8)); $bottom = $btnRsForce.Bottom }
    $pnlRsWait.Height = $bottom + 8
    $pnlRsWait.Visible = $true; $pnlRsWait.BringToFront(); $lblRsRules.Visible = $false
    $lblRsNow.Text = ''
    Show-Tab $tabRs
    $tabRs.ScrollControlIntoView($pnlRsWait)                 # fenetre basse : l encadre et son bouton Continuer restent visibles
    # 12.10 (verification finale de la RC) : compteur de pistes et barre de progression de la lecture terminee effaces,
    # consigne plus courte (l onglet Restauration est affiche) : a la largeur de la fenetre, le compteur la coupait ;
    # (relecture de la RC9) icone neutre a cote de la consigne, au lieu de la coche de la lecture terminee
    $stTrack.Text = ''; $stBar.Visible = $false; $stOp.Image = $script:StIcons.idle
    $stOp.Text = (T 'Restauration : changez de disquette, puis cliquez sur « Continuer ».')
    Clear-SeqEnd    # 12.11 : la consigne remplace l etat de fin de sequence en attente (calibration terminee juste avant, 110)
    Append-Log ((T "Restauration : en attente de la disquette de destination dans le lecteur {0}.") -f "$($r.Drive)")
    try { [System.Media.SystemSounds]::Exclamation.Play() } catch { }
}

function Get-RestoreKeepCyls {
    # Flux : cylindres portant une piste non reproductible (zone instable, meme courte), deja critique ou deja hors norme
    # par ses erreurs sur l original (12.8.2 : OverKeys, par exemple Copylock), jamais reecrits sur une disquette identique
    # a l original
    $r = $script:Restore; $set = @{}
    if (-not $r -or $r.Mode -ne 'flux' -or -not $r.Read) { return @() }
    $src = @(@($r.Read.CritKeys.Keys) + @($r.Read.WeakKeys.Keys))
    if ($r.Read.UnstKeys) { $src += @($r.Read.UnstKeys.Keys) }
    if ($r.Read.OverKeys) { $src += @($r.Read.OverKeys.Keys) }
    foreach ($k in $src) { $set[[int](([string]$k -split '\.')[0])] = $true }
    return @($set.Keys | Sort-Object)
}

function Resume-Restore([bool]$force) {
    # 12.8 (D7) : reprise seulement par « Continuer » ou « Ecraser quand meme » ; plus de reprise automatique apres la
    # remise de la destination qui suit une calibration sur disquette sacrifiee (la disquette inseree n est pas connue)
    $r = $script:Restore
    if (-not $r -or -not $r.Waiting) { return }
    if ($script:GwProc -and -not $script:GwProc.HasExited) {
        [void](Show-AppMessage (T 'Une commande gw est encore en cours : attendez sa fin.') (T 'Restauration') 'OK' 'Information'); return
    }
    if ($force) {
        # « Ecraser quand meme » : la disquette inseree a le contenu de l original, c est peut-etre l original lui-meme.
        # Flux : les cylindres non reproductibles ne seront pas reecrits ; secteur : toute protection hors secteurs serait detruite.
        if ($r.Mode -eq 'sector') { $msg = (T "La disquette insérée a le même contenu que l'original : c'est peut-être l'ORIGINAL lui-même.`n`nEn mode secteur, chaque piste est réécrite au format standard : si la disquette porte une protection contre la copie (piste non standard, bits faibles), elle sera définitivement détruite. Pour une disquette protégée, utilisez « Copie exacte du flux ».`n`nÉcraser quand même cette disquette ?") }
        else {
            $keep = @(Get-RestoreKeepCyls)
            # Chaque cylindre a preserver : aucune ecriture possible sans detruire la protection -> refus
            $incF = @(); if ($r.Read) { $incF = @(0..([int]$r.Read.MaxCyl) | Where-Object { $keep -notcontains $_ }) }
            if ($keep.Count -gt 0 -and $incF.Count -eq 0) {
                [void](Show-AppMessage ((T "La disquette insérée a le même contenu que l'original. Chaque cylindre ({0}) porte une piste non reproductible ou critique : aucun cylindre ne peut être réécrit sans détruire la protection. Écriture refusée : insérez une autre disquette.") -f "$(Format-CylList $keep)") (T 'Restauration') 'OK' 'Warning')
                return
            }
            $msg = if ($keep.Count -gt 0) { (T "La disquette insérée a le même contenu que l'original : c'est peut-être l'ORIGINAL lui-même.`n`nLes cylindres qui portent des pistes non reproductibles ou déjà critiques sur l'original ({0}) ne seront pas réécrits : leur protection éventuelle est préservée. Les autres pistes seront effacées puis réécrites à partir de la lecture.`n`nÉcraser quand même cette disquette ?") -f "$(Format-CylList $keep)" }
                   else { (T "La disquette insérée a le même contenu que l'original : c'est peut-être l'ORIGINAL lui-même.`n`nAucune piste non reproductible n'a été détectée : toutes les pistes seront effacées puis réécrites à partir de la lecture.`n`nÉcraser quand même cette disquette ?") }
        }
        # 12.8 (D3) : confirmation par frmConfirm, case qui nomme le lecteur de destination
        $cq = @{ Title = (T 'Restauration'); Heading = (T "C'est peut-être l'ORIGINAL"); Text = $msg; Level = 'danger'; Picto = 'forbid'
                 Check = ((T 'La disquette du lecteur {0} peut être écrasée') -f "$($r.Drive)"); GoText = (T 'Écraser quand même'); GoGlyph = 'Save' }
        if (-not (Show-AppConfirm @cq)) { return }
    } elseif ($r.Mode -eq 'flux' -and -not $r.Finger) {
        # Copie de flux sans empreinte exploitable : aucune sonde possible, confirmation explicite que l original a ete retire
        # (12.8, D3 : frmConfirm, case qui nomme le lecteur de destination)
        $cq = @{ Title = (T 'Restauration'); Heading = (T 'Changement de disquette non vérifiable'); Level = 'warn'; Picto = 'data'
                 Text = (T "Copie de flux : l'application ne peut pas vérifier que la disquette insérée n'est pas l'original.`n`nAvez-vous bien retiré l'ORIGINAL et inséré la disquette de DESTINATION ?")
                 Check = ((T "J'ai retiré l'ORIGINAL et inséré la disquette de DESTINATION dans le lecteur {0}") -f "$($r.Drive)"); GoText = (T 'Écrire la copie'); GoGlyph = 'Save' }
        if (-not (Show-AppConfirm @cq)) { return }
    }
    $r.Waiting = $false; $r.SwapBack = $false; $pnlRsWait.Visible = $false; $r.Idle = Get-Date; $r.Override = $false
    # 12.8 (F3R-FIX, constat 3) : une disquette jugee differente par la sonde, ou confirmee comme changee, n est plus
    # l original, meme apres un « Ecraser quand meme » sur une disquette precedente (mesure de la destination, cylindres
    # preserves d une copie de flux)
    if (-not $force) { $r.OnOriginal = $false }
    Set-RsStep 2 'ok'
    if (-not $force -and ($r.Mode -eq 'sector' -or $r.Finger)) { Start-RestoreProbe; return }
    if ($force) { $r.OnOriginal = $true; Set-RsStep 3 'warn' (T 'contrôle ignoré à votre demande') }
    else { Set-RsStep 3 'skip' (T "non vérifiable : aucune empreinte exploitable sur l'original") }
    Start-RestoreWrite
}

function Start-RestoreProbe {
    # Lecture du seul cylindre 0 de la disquette inseree (3 tours, 2 essais) : identique a l original -> c est l original
    $r = $script:Restore
    $r.Stage = 'probe'
    Set-RsStep 3 'run'
    Remove-Item -LiteralPath $r.Probe -ErrorAction SilentlyContinue
    if ($r.Mode -eq 'flux') {
        # Flux : lecture de la piste de l empreinte (2 tours), comparee aux blocs de reference de l original
        $f = $r.Finger
        $script:RestoreArgs = @('read') + (Get-CommonArgs) + @(Get-DriveReadArgs) + @("--tracks=c=$($f.Cyl):h=$($f.Head)$($r.Extras)", '--revs=2', "`"$($r.Probe)`"")
    } else {
        $script:RestoreArgs = @('read') + (Get-CommonArgs) + @(Get-DriveReadArgs) + @("--format=$($r.Fmt)", "--tracks=c=0:h=0-1$($r.Extras)", '--revs=3', '--retries=2', "`"$($r.Probe)`"")
    }
    $script:Chain.Clear()
    $script:Chain.Enqueue({ Start-Gw $script:RestoreArgs })
    $script:Chain.Enqueue({ Invoke-RestoreNext })
    Invoke-NextChainStep
}

function Restore-ProbeFailed {
    # Sonde sans resultat (pas de disquette, pas d index) : retour a l attente plutot qu un abandon
    $r = $script:Restore
    $script:Chain.Clear()
    $r.Override = $false
    Set-RsStep 3 'pending'
    Enter-RestoreWait (T 'Aucune disquette lisible n''a été détectée dans le lecteur de destination.')
}

function Complete-RestoreProbe {
    $r = $script:Restore
    if (-not (Test-Path -LiteralPath $r.Probe)) { Restore-ProbeFailed; return }
    if ($r.Mode -eq 'flux') {
        # Empreinte : au moins les trois quarts des blocs de reference retrouves -> memes donnees que l original
        $f = $r.Finger; $fl = $null
        try { $fl = Read-ScpTrackFlux $r.Probe $f.Tn } catch { $fl = $null }
        if (-not $fl -or $fl.Count -eq 0) { Restore-ProbeFailed; return }
        $hit = [ScpStats]::Match($fl, [double]$f.Cell, [string[]]$f.Fp)
        Append-Log ((T "Restauration : empreinte de la piste {0}.{1} retrouvée {2} fois sur {3} sur la disquette insérée.") -f "$($f.Cyl)", "$($f.Head)", "$hit", "$($f.Fp.Count)")
        if ($hit * 4 -ge $f.Fp.Count * 3) {
            Set-RsStep 3 'fail' (T 'la disquette insérée semble être l''original')
            Append-Log ((T "Restauration : la disquette de destination porte les mêmes données que l'original (empreinte de la piste {0}.{1}). Écriture refusée.") -f "$($f.Cyl)", "$($f.Head)")
            $r.Override = $true
            Enter-RestoreWait (T "ATTENTION : la disquette insérée porte les mêmes données que l'original, c'est probablement l'ORIGINAL. Changez de disquette. S'il s'agit d'une ancienne copie à remplacer entièrement, cliquez sur « Annuler », effacez-la (case « Mode expert », onglet Outils, bouton « EFFACER »), puis relancez la restauration. « Écraser quand même » sert à rafraîchir l'original : les cylindres non reproductibles ou critiques ne sont ni réécrits ni contrôlés.")
            return
        }
        Set-RsStep 3 'ok' (T 'ce n''est pas l''original')
        Start-RestoreWrite
        return
    }
    # Cylindre 0, secteur par secteur : un secteur non relu par la sonde (motif BAD SECTOR de gw) ne compte pas ;
    # au moins un secteur lu et tous les secteurs lus identiques a l original -> c est l original (meme abime)
    $a = [System.IO.File]::ReadAllBytes($r.Orig); $p = [System.IO.File]::ReadAllBytes($r.Probe)
    $spt = Get-SectorsPerTrack $r.Fmt
    $n = if ($spt -gt 0) { 2 * $spt * 512 } else { 1024 }
    $n = [math]::Min($n, [math]::Min($a.Length, $p.Length))
    $pat = [System.Text.Encoding]::ASCII.GetBytes('-=[BAD SECTOR]=-')
    $readable = 0; $differ = 0
    for ($s = 0; $s + 512 -le $n; $s += 512) {
        $isBad = $true
        for ($i = 0; $i -lt 512; $i++) { if ($p[$s + $i] -ne $pat[$i % 16]) { $isBad = $false; break } }
        if ($isBad) { continue }
        $readable++
        for ($i = 0; $i -lt 512; $i++) { if ($a[$s + $i] -ne $p[$s + $i]) { $differ++; break } }
    }
    $same = ($readable -gt 0 -and $differ -eq 0)
    if ($same) {
        Set-RsStep 3 'fail' (T 'la disquette insérée semble être l''original')
        Append-Log (T 'Restauration : la disquette de destination contient les mêmes données que l''original sur le cylindre 0. Écriture refusée.')
        $r.Override = $true
        Enter-RestoreWait (T "ATTENTION : la disquette insérée a le même contenu que l'original sur le cylindre 0, c'est probablement l'ORIGINAL. Changez de disquette. S'il s'agit bien d'une copie à remplacer, cliquez sur « Écraser quand même ».")
        return
    }
    Set-RsStep 3 'ok' (T 'ce n''est pas l''original')
    Start-RestoreWrite
}

function Get-RestoreCalibInfo([string]$fam, [int]$nCyl = 0) {
    # Calibration de l ecriture stricte : une calibration existante (par tete si a jour, sinon commune, comme l applique
    # l ecriture lente) n est jamais refaite ; Need seulement si la famille n en a aucune. Notes : reserves a signaler,
    # dont une courbe plus courte que l image de nCyl cylindres (> 0) de plus de 4 cylindres (Get-CalibState 'short')
    $cvs = Get-FamilyCurves $fam $true
    if ($cvs.Count -eq 0) { return @{ Need = $true; Text = (T 'aucune calibration existante'); Notes = @() } }
    $text = if ($cvs.Count -gt 1) { (T 'par tête') } else { (T 'commune aux deux têtes') }
    $notes = New-Object System.Collections.Generic.List[string]
    foreach ($cv in $cvs) {
        $n = @()
        if ($cv.Method -ne 'motif') { $n += (T 'mesurée sur le contenu d''une image, avant le motif de test') }
        if ($cv.Drive -and [string]$cv.Drive -ne $script:Restore.Drive) { $n += ((T "mesurée sur le lecteur {0}") -f "$($cv.Drive)") }
        if ($cv.Converged -eq $false) { $n += (T 'non convergée') }
        if ((Get-CurveCalc $cv) -ne (Get-CurveCalcRef $cv)) { $n += ((T "calcul de calibration {0}") -f (Get-CurveCalcText $cv)) }
        if (Test-CurveAtMax $cv) { $n += ((T "courbe au plafond de {0} ns de son calcul") -f "$(Get-CurveMaxNs $cv)") }
        $vc = @($cv.Values).Count
        if ($nCyl -gt 0 -and $vc -lt $nCyl - 4) { $n += ((T "courbe de {0} cylindres pour une image de {1}") -f "$vc", "$nCyl") }
        foreach ($x in $n) { if (-not $notes.Contains($x)) { $notes.Add($x) } }
    }
    return @{ Need = $false; Text = $text; Notes = $notes.ToArray() }
}

function Set-RestoreRepRules {
    # Copie de flux : pistes deja critiques ou non reproductibles sur l original ni reecrites ni comptees au controle ;
    # zones instables relues sur la copie (courtes zones, pistes non mesurables de l original) non jugees. 12.8
    # (decision 3) : aussi apres la mesure de la destination (Complete-LevelCalib lance alors l ecriture)
    $r = $script:Restore
    if (-not $r -or $r.Mode -ne 'flux' -or -not $script:Rep -or -not $r.Read) { return }
    # 12.8.2 (decision du 27/10/2026) : aussi les pistes deja hors norme par leurs erreurs (OverKeys, Rep.SrcOver)
    $ov = if ($r.Read.OverKeys) { $r.Read.OverKeys } else { @{} }
    $ign = @{}
    foreach ($k in @(@($r.Read.CritKeys.Keys) + @($r.Read.WeakKeys.Keys) + @($ov.Keys))) { $ign[[string]$k] = $true }
    if ($ign.Count -gt 0) { $script:Rep.Ignore = $ign }
    $script:Rep.SrcWeak = $r.Read.WeakKeys; $script:Rep.SrcOver = $ov
    $nj = @{}; foreach ($k in @(@($r.Read.UnstKeys.Keys) + @($(if ($r.Read.NoMeas) { $r.Read.NoMeas.Keys } else { @() })))) { $nj[[string]$k] = $true }
    $script:Rep.NoJudge = $nj
}

function Start-RestoreWrite {
    $r = $script:Restore
    $r.Stage = 'write'; $r.Idle = Get-Date
    $script:LastCheck = $null
    $script:EraseLog = $null          # 12.8.2 : seul celui de l ecriture de cette restauration compte (Fail-Restore)
    $r.InCall = $true
    try {
        # Regles strictes dans l onglet Ecriture (etat d origine remis en fin de restauration)
        Set-WritePreset 'slow' $r.Orig ("restore|" + $r.Orig)
        # 12.10 (relecture de la RC) : format sous la garde des liaisons, profil recalcule plus bas (Update-PrecompForImage)
        if ($r.Mode -eq 'sector') { $sv = $script:SettingSync; $script:SettingSync = $true; try { Set-Combo $cmbWFmt $r.Fmt } finally { $script:SettingSync = $sv } }
        if ($r.Mode -eq 'flux' -and $r.OnOriginal -and $r.Read) {
            # Ecriture sur une disquette identique a l original (« Ecraser quand meme ») : cylindres non reproductibles exclus
            $keep = @(Get-RestoreKeepCyls)
            if ($keep.Count -gt 0) {
                $inc = @(0..([int]$r.Read.MaxCyl) | Where-Object { $keep -notcontains $_ })
                if ($inc.Count -eq 0) {
                    # Garde : jamais d ecriture complete sur l original quand tout est a preserver
                    $r.InCall = $false
                    Fail-Restore 3 (T "aucun cylindre réécrivable sans toucher aux pistes non reproductibles : rien n'a été écrit")
                    return
                }
                if ($inc.Count -gt 0) {
                    $txtWTracks.Text = "c=$(Format-CylList $inc)$($r.Extras)"
                    $r.Preserved = $keep
                    Append-Log ((T "Restauration : écriture sur une disquette identique à l'original : cylindres {0} non réécrits (pistes non reproductibles, protection préservée).") -f "$(Format-CylList $keep)")
                }
            }
        }
        Set-Num $numWRetries $script:RestoreRules.WriteRetries
        Set-Num $numWRepair $script:RestoreRules.RepairPasses
        $chkWNoVerify.Checked = $false; $chkWPostCheck.Checked = $true; $chkWPrecomp.Checked = $true
        # 12.8 (decision 3 du 21/10/2026) : destination qui n est pas l original (empreinte non retrouvee, cylindre 0
        # different, ou changement de disquette confirme quand il n est pas verifiable) : mesuree avant l ecriture, en copie
        # secteur, quand une calibration existe (ou apres une calibration sur disquette sacrifiee) : calibration rapide
        # (adaptative, avec la marque) ou, selon la liste « Mesure » de l onglet Ecriture (write.levelBeforeWriteMode, S3-FLUX),
        # mesure complete de cette disquette (Start-LevelBeforeWrite) ; une calibration n est jamais refaite. Regles de
        # « Mesurer la disquette avant l ecriture lente » et du test rapide (D5) ; toute mesure non faite a sa ligne de
        # journal. 12.8 avant cette decision : mesure seulement avec le test rapide ou la case « Mesurer la disquette ».
        # 12.8 (S3-FLUX, decision 2 du 21/10/2026) : copie de flux jamais mesuree : gw n applique pas --precomp a un flux
        # brut (Test-RawFluxWrite) ; ligne de journal (F3R : mesure par Get-RestoreFluxLevel, sans effet sur l ecriture)
        $measure = -not $r.OnOriginal
        $r.LevelNote = ''   # 12.8 (F3R-FIX) : raison d une ecriture precedente (autre disquette) oubliee
        $skipFmt = (T "Restauration : disquette de destination non mesurée avant l'écriture : {0}.")
        if ($r.Mode -eq 'flux') { $measure = $false; Append-Log ($skipFmt -f (T "copie exacte du flux, écrite telle quelle par gw, sans précompensation ; la mesure ne servirait pas")) }
        elseif (-not $measure) { $r.LevelNote = (T "elle a le contenu de l'original, écrasée à votre demande : la mesure ne se fait que sur une autre disquette"); Append-Log ($skipFmt -f $r.LevelNote) }
        $cmbWCalMode.SelectedIndex = 1
        Update-PrecompForImage $r.Orig
        $r.SwapBack = $false
        $noCalib = $false
        # 12.10 : lecteur cible avec effet sur cette ecriture (Get-TargetWriteInfo : copie secteur MFM) : courbe croisee
        # telle quelle, ni calibration du lecteur ni mesure de la destination (elles reliraient avec le lecteur de la
        # restauration) ; sans courbe croisee de la famille, ou en haute densite : echec avant toute ecriture
        $tw = Get-TargetWriteInfo $r.Orig $cmbWFmt.Text $true
        $r.Target = if ($tw.Applies) { [string]$tw.Tgt } else { '' }
        if ($r.Target -and $tw.Block) {
            $r.InCall = $false; $r.Plan = 'refused'          # 12.10 (relecture de la RC) : ligne « Regles » du rapport
            # Haute densite (reconnue a la lecture de l original : un format haute densite explicite est refuse des le
            # lancement, Get-RestoreTargetInfo ; famille vide, profil Auto impose par Set-WritePreset) : raison propre a la
            # restauration, sans le profil Manuel que propose celle de l onglet Ecriture et que la restauration n offre pas
            $why = [string]$tw.Block
            $hdT = Get-HighDensityReason $r.Orig $cmbWFmt.Text
            if ($hdT -and -not $tw.Fam) { $why = (T "l'original lu est en haute densité ({0}), et la calibration croisée n'existe qu'en double densité (standard, long track). Choisissez « (même lecteur) » dans la liste « Lecteur cible » de l'onglet Écriture, puis relancez la restauration.") -f "$hdT" }
            Fail-Restore 4 ((T "écriture pour le lecteur cible {0} refusée, rien n'a été écrit : {1}") -f "$($r.Target)", "$why")
            return
        }
        if ($r.Mode -eq 'sector') {
            $r.HD = [string](Get-HighDensityReason $r.Orig $r.Fmt)
            if ($r.HD) {
                if ($measure) { $r.LevelNote = (T "haute densité ({0}), sans calibration rapide") -f "$($r.HD)"; Append-Log ($skipFmt -f $r.LevelNote) }
            } elseif ($r.Target) {
                $noCalib = $true
                if ($measure) { $measure = $false; $r.LevelNote = (T "écriture pour le lecteur cible {0}, la mesure relirait avec le lecteur {1}") -f "$($r.Target)", "$($r.Drive)"; Append-Log ($skipFmt -f $r.LevelNote) }
                Append-Log ((T "Restauration : écriture pour le lecteur cible {0} avec la courbe croisée, le lecteur {1} n'est pas calibré.") -f "$($r.Target)", "$($r.Drive)")
            } else {
                if ($r.CalibDone) { $noCalib = $true }          # calibration faite sur une disquette sacrifiee, destination remise
                else {
                    $rc = (Get-CalibCylinders $r.Orig $r.Fmt).NCyl
                    $ci = Get-RestoreCalibInfo (Get-ImageFamily $r.Orig) $(if ($null -eq $rc) { 80 } else { [math]::Max(2, [math]::Min(84, [int]$rc)) })
                    if ($ci.Need) {
                        $r.Calib = $ci.Text; Append-Log ((T "Restauration : calibration par tête en test fin ({0}).") -f "$($ci.Text)")
                        if ($measure) { Append-Log (T "Restauration : la disquette de destination sera mesurée après la calibration si celle-ci est faite sur une disquette sacrifiée ; faite sur la destination elle-même, la calibration complète en tient lieu.") }
                    }
                    else {
                        $noCalib = $true; $r.CalibUsed = $ci
                        Append-Log ((T "Restauration : calibration existante utilisée ({0}), le lecteur n'est pas recalibré.") -f "$($ci.Text)")
                        if ($ci.Notes.Count -gt 0) { Append-Log ((T "Remarque sur cette calibration : {0}. Pour la refaire, lancez « Calibrer » dans l'onglet Écriture, « Écriture lente » cochée, avant la restauration.") -f "$($ci.Notes -join ' ; ')") }
                    }
                }
            }
        }
        # 12.10 (relecture de la RC) : decision de cette ecriture (ligne « Regles » du rapport, Write-RestoreReport ; ligne de
        # journal ci-dessous) : copie de flux, haute densite, lecteur cible avec effet, sinon copie secteur ordinaire. Avant :
        # ligne de la copie secteur double densite pour une copie de flux (sans verification gw, donc sans essais) ou haute
        # densite (sans controle des pistes)
        $r.Plan = if ($r.Mode -ne 'sector') { 'flux' } elseif ($r.HD) { 'hd' } elseif ($r.Target) { 'target' } else { 'sector' }
        if ($r.Plan -eq 'flux') { Append-Log ((T "Restauration : copie exacte du flux écrite tête par tête, telle quelle, contrôle de toutes les pistes ({0} passes au plus).") -f "$($script:RestoreRules.RepairPasses)") }
        elseif ($r.Plan -eq 'hd') { Append-Log ((T "Restauration : écriture tête par tête, {0} essais par piste, sans contrôle des pistes (non applicable à la haute densité).") -f "$($script:RestoreRules.WriteRetries)") }
        else { Append-Log ((T "Restauration : écriture tête par tête, {0} essais par piste, contrôle de toutes les pistes ({1} passes au plus).") -f "$($script:RestoreRules.WriteRetries)", "$($script:RestoreRules.RepairPasses)") }
        Start-PresetWrite 'slow' -NoCalib:$noCalib -LevelOnly:($measure -and $noCalib -and $r.Mode -eq 'sector' -and -not $r.HD)
        Set-RestoreRepRules
    } finally { $r.InCall = $false; $r.Idle = Get-Date }
    if (-not $script:Restore) { return }
    if ($script:Cal) { Set-RsStep 4 'run' }
    elseif ($script:GwProc -and -not $script:GwProc.HasExited) {
        if ($r.Mode -ne 'sector') { Set-RsStep 4 'skip' $(if ($r.LevelNote) { (T "niveau non mesuré : {0}") -f "$($r.LevelNote)" } else { (T 'non applicable à une copie de flux') }) }
        elseif ($r.HD) { Set-RsStep 4 'skip' ((T "non applicable : {0}") -f "$($r.HD)") }
        elseif ($r.Target) { Set-RsStep 4 'skip' ((T "écriture pour le lecteur cible {0} : courbe croisée {1} → {0}, ni calibration ni mesure de la destination") -f "$($r.Target)", "$($r.Drive)") }
        elseif ($r.CalibUsed) {
            $d = (T "calibration existante ({0}), pas de recalibration") -f "$($r.CalibUsed.Text)"
            if ($r.CalibUsed.Notes.Count -gt 0) { $d += ' ; ' + ($r.CalibUsed.Notes -join ' ; ') }
            if ($r.LevelNote) { $d += ' ; ' + ((T "niveau non mesuré : {0}") -f "$($r.LevelNote)") }
            Set-RsStep 4 $(if ($r.CalibUsed.Notes.Count -gt 0 -or $r.LevelNote) { 'warn' } else { 'ok' }) $d
        }
        elseif ($r.CalibDone -and $r.LevelNote) {
            $s4 = $r.Steps[4]
            $d = if ($s4 -and $s4.Detail) { $s4.Detail } else { (T "faite sur une disquette sacrifiée ({0})") -f "$($r.Calib)" }
            Set-RsStep 4 'warn' ($d + ' ; ' + ((T "niveau non mesuré : {0}") -f "$($r.LevelNote)"))
        }
        Set-RsStep 5 'run' $(if ($script:WriteWarm) { (T 'préchauffage du lecteur') } else { '' })
    } else {
        Fail-Restore 4 (T 'l''écriture n''a pas démarré (calibration refusée ou annulée ? voir le journal)')
    }
}

function Set-RsCalibDone {
    # Calibration terminee pendant la restauration : convergence des deux courbes par tete, courbe a la borne de son
    # calcul (meme reserve que Get-RestoreCalibInfo a la restauration suivante)
    $r = $script:Restore
    if ($r.Level) { Set-RsStep 4 $r.Level.State $r.Level.Text; return }
    $fam = Get-ImageFamily $r.Orig
    $nc = @(@(0, 1) | Where-Object { $cv = $script:PrecompCurves["${fam}_h$_"]; $cv -and $cv.Converged -eq $false })
    $am = @(@(0, 1) | ForEach-Object { $script:PrecompCurves["${fam}_h$_"] } | Where-Object { Test-CurveAtMax $_ })
    $d = if ($nc.Count -gt 0) { (T 'faite, non convergée sur une tête : voir le journal') }
         elseif ($r.CalSwap) { (T "faite sur une disquette sacrifiée ({0})") -f "$($r.Calib)" }
         elseif ($r.Calib) { (T "faite ({0})") -f "$($r.Calib)" } else { '' }
    if ($am.Count -gt 0) {
        $ct = (T "courbe au plafond de {0} ns de son calcul") -f "$(Get-CurveMaxNs $am[0])"
        $d = if ($d) { "$d ; $ct" } else { $ct }
    }
    Set-RsStep 4 $(if ($nc.Count -gt 0 -or $am.Count -gt 0) { 'warn' } else { 'ok' }) $d
}

function Enter-RestoreSwapBack {
    # Calibration faite sur une disquette sacrifiee : etape terminee, la destination est redemandee puis de nouveau
    # sondee (Resume-Restore -> Start-RestoreProbe) ; l ecriture reprend ensuite sans recalibrer (CalibDone).
    $r = $script:Restore
    $r.CalSwap = $true
    Set-RsCalibDone
    $r.CalibDone = $true; $r.SwapBack = $true
    # 12.8 (D7) : attente de « Continuer », sans compte a rebours ni reprise automatique (12.7 : reprise au bout du delai
    # de l avertissement de calibration)
    Set-RsStep 3 'pending'
    Append-Log (T 'Restauration : calibration terminée sur la disquette sacrifiée.')
    Enter-RestoreWait ''
}

function Update-RestoreProgress {
    # Appele par le timer : etape en cours pendant l ecriture deleguee, ligne d avancement, chien de garde
    $r = $script:Restore
    if (-not $r) { return }
    $busy = (($script:GwProc -and -not $script:GwProc.HasExited) -or $script:Chain.Count -gt 0 -or $script:Rep -or $script:Cal -or $script:WriteWarm -or $r.Waiting -or $r.InCall)
    if ($busy) { $r.Idle = Get-Date }
    elseif (((Get-Date) - $r.Idle).TotalSeconds -gt 5) { Stop-Restore (T 'séquence arrêtée sans suite, voir le journal'); return }
    if ($r.Stage -eq 'write') {
        if ($script:Cal) {
            if ($r.Cur -ne 4) { Set-RsStep 4 'run' }
        } elseif ($script:Rep -and $null -ne $script:Rep.Scope) {
            if ($r.Cur -lt 6) {
                if ($r.Steps.ContainsKey(4) -and $r.Steps[4].State -eq 'run') { Set-RsCalibDone }
                Set-RsStep 5 'ok'; Set-RsStep 6 'run'
            }
        } elseif ($script:GwProc -and $r.Cur -lt 5) {
            if ($r.Steps.ContainsKey(4) -and $r.Steps[4].State -eq 'run') { Set-RsCalibDone }
            Set-RsStep 5 'run' $(if ($script:WriteWarm) { (T 'préchauffage du lecteur') } else { '' })
        }
    }
    $now = if ($script:Cal -or $script:WriteWarm) { $lblWCal.Text } elseif ($script:GwProc) { ($stOp.Text + '   ' + $stTrack.Text).Trim() } else { '' }
    if ($lblRsNow.Text -ne $now) { $lblRsNow.Text = $now }
}

function Start-RestoreCompare {
    # Ecriture et controle termines (accroches) : bilan, puis relecture de la copie sans nouvel essai
    $r = $script:Restore
    $chk = $script:LastCheck
    if ($r.Steps.ContainsKey(4) -and $r.Steps[4].State -eq 'run') { Set-RsCalibDone }
    Set-RsStep 5 'ok'
    if ($chk) { Set-RsStep 6 $(if ($chk.Ok) { 'ok' } else { 'fail' }) $chk.Short }
    else { Set-RsStep 6 'skip' (T 'non applicable à ce format') }
    if ($r.Mode -ne 'sector') { Set-RsStep 7 'skip' (T 'non applicable à une copie de flux'); Finish-Restore; return }
    $r.Stage = 'compare'
    Set-RsStep 7 'run'
    Remove-Item -LiteralPath $r.Back -ErrorAction SilentlyContinue
    $script:RestoreArgs = @('read') + (Get-CommonArgs) + @(Get-DriveReadArgs) + @("--format=$($r.Fmt)", "--retries=$($script:RestoreRules.FinalRetries)")
    if ($r.Extras) { $script:RestoreArgs += "--tracks=$($r.Extras.TrimStart(':'))" }
    $script:RestoreArgs += "`"$($r.Back)`""
    $script:GwCapture = New-Object System.Collections.Generic.List[string]
    $script:Chain.Clear()
    $script:Chain.Enqueue({ Start-Gw $script:RestoreArgs })
    $script:Chain.Enqueue({ Invoke-RestoreNext })
    Invoke-NextChainStep
}

function Complete-RestoreCompare {
    $r = $script:Restore
    $script:GwCapture = $null
    if (-not (Test-Path -LiteralPath $r.Back)) {
        $r.Cmp = @{ Ok = $false; Text = (T 'relecture de la copie impossible') }
        Set-RsStep 7 'fail' $r.Cmp.Text; Finish-Restore; return
    }
    $a = [System.IO.File]::ReadAllBytes($r.Orig); $b = [System.IO.File]::ReadAllBytes($r.Back)
    if ($script:FastCompare) { $diff = @([GwCompare]::DiffSectors($a, $b, 512)) }
    else {
        $set = New-Object System.Collections.Generic.HashSet[int]
        $n = [Math]::Max($a.Length, $b.Length)
        for ($i = 0; $i -lt $n; $i++) { if ($i -ge $a.Length -or $i -ge $b.Length -or $a[$i] -ne $b[$i]) { [void]$set.Add([int][Math]::Floor($i / 512)) } }
        $diff = @($set | Sort-Object)
    }
    $unread = Get-BadSectorBlocks $r.Back
    $total = [int][math]::Ceiling([math]::Max($a.Length, $b.Length) / 512)
    if ($diff.Count -eq 0) {
        $r.Cmp = @{ Ok = $true; Text = ((T "identique, {0} secteurs") -f "$total") }
        Set-RsStep 7 'ok' $r.Cmp.Text
        Append-Log ((T "Restauration : copie IDENTIQUE à l'original, {0} secteurs relus du premier coup.") -f "$total")
    } else {
        $trk = Get-BlockTracks ([int[]]$diff) $r.Fmt
        $r.Cmp = @{ Ok = $false; Text = ((T "{0} secteur(s) différent(s) sur {1}, dont {2} non relu(s) du premier coup ; pistes {3}") -f "$($diff.Count)", "$total", "$($unread.Count)", "$(Format-TrackList $trk)") }
        Set-RsStep 7 'fail' ((T "{0} secteur(s) différent(s)") -f "$($diff.Count)")
        Append-Log ((T "Restauration : copie DIFFÉRENTE de l'original : {0}.") -f "$($r.Cmp.Text)")
    }
    Finish-Restore
}

function Write-RestoreReport([bool]$ok, [string]$verdict) {
    $r = $script:Restore
    $L = New-Object System.Collections.Generic.List[string]
    $L.Add(((T "Greaseweazle Studio v{0} - rapport de restauration") -f "$($script:Version)"))
    $L.Add(((T "Date        : {0}, durée {1} min") -f (Get-Date -Format 'dd/MM/yyyy HH:mm'), "$([math]::Round(((Get-Date) - $r.Start).TotalMinutes, 1))"))
    $L.Add(((T "Disquette   : {0}") -f "$($r.Name)"))
    $L.Add(((T "Mode        : {0}") -f $(if ($r.Mode -eq 'sector') { (T "secteur par secteur, format {0}") -f "$($r.Fmt)" } elseif ($r.Mode -eq 'flux') { (T 'copie exacte du flux') } else { (T 'format détecté à la lecture') })))
    # 12.8 : format de la detection automatique ; un seul lecteur (D10)
    if ($r.Choice -eq 'auto' -and $r.Found) { $L.Add(((T "Détection   : {0}") -f "$($r.Found)")) }
    $L.Add(((T "Lecteur     : {0}") -f "$($r.Drive)"))
    if ($r.Orig) { $L.Add(((T "Original lu : {0}") -f "$($r.Orig)")) }
    # FIX2 : lecture secteur incomplete gardee avant la relance D12
    if ($r.SectorRead) { $L.Add(((T "Incomplète  : {0} (lecture secteur, {1} secteur(s) illisible(s), {2} hors du format ; relancée en copie exacte du flux)") -f "$($r.SectorRead.Path)", "$($r.SectorRead.Miss)", "$($r.SectorRead.Extra)")) }
    if ($r.Mode -eq 'sector') { $L.Add(((T "Copie relue : {0}") -f "$($r.Back)")) }
    if ($r.Read -and $r.Read.WeakKeys -and $r.Read.WeakKeys.Count -gt 0) { $L.Add(((T "Instables   : {0} (zone instable d'un tour à l'autre : protection contre la copie probable, non reproductible)") -f "$(Format-TrackList (Sort-TrackKeys @($r.Read.WeakKeys.Keys)))")) }
    if ($r.Level) { $L.Add(((T "Niveau      : {0}") -f "$($r.Level.Report)")) }
    if ($r.Preserved -and @($r.Preserved).Count -gt 0) { $L.Add(((T "Préservés   : cylindres {0}, non réécrits sur la disquette identique à l'original") -f "$(Format-CylList @($r.Preserved))")) }
    $rr = $script:RestoreRules
    # 12.10 (relecture de la RC) : ligne « Regles » d apres la decision de cette restauration : celle de l ecriture
    # (Start-RestoreWrite : $r.Plan), sinon, avant l ecriture, celle du lancement refaite avec le format connu a cet instant
    # (Get-RestorePlan, lecteur cible du lancement : detection faite ou relance en copie de flux comprises). Copie de flux :
    # lecture sans nouvel essai, ni precompensation, ni verification gw, ni calibration, ni mesure, ni relecture finale ;
    # lecteur cible : courbe croisee telle quelle, relecture par le lecteur de la restauration ; refus de l ecriture pour le
    # lecteur cible ; haute densite : ni calibration, ni mesure, ni controle des pistes. Avant : regles de la copie secteur
    # double densite sans lecteur cible pour toute restauration
    $pk = [string]$r.Plan
    # 12.10 (relecture de la RC, fix1) : decision refaite avant l ecriture ($pp) : un refus n a pas eu lieu, ligne
    # conditionnelle (« non atteinte », elle serait refusee) d apres sa nature (Ti.BlockKind) ; avant : « refusee, rien n a
    # ete ecrit » pour une restauration arretee plus tot (lecture, changement de disquette)
    $pp = $null
    if (-not $pk) { $pp = Get-RestorePlan ([string]$r.Drive) ([string]$r.TgtChoice) $(if ($r.Mode -eq 'flux') { '' } elseif ($r.Mode -eq 'sector') { [string]$r.Fmt } else { 'auto' }); $pk = [string]$pp.Kind }
    $rtg = if ($r.Target) { [string]$r.Target } else { [string]$r.TgtChoice }
    if ($pk -eq 'flux') { $rl = (T "Règles      : lecture {0} tours ; copie exacte du flux, écrite telle quelle par gw (ni précompensation, ni vérification gw), sans calibration du lecteur ni mesure de la destination ; écriture tête par tête, effacement avant l'écriture ; contrôle de toutes les pistes, {1} passes de réécriture au plus ; pas de comparaison secteur par secteur.") -f "$($rr.ReadRevs)", "$($rr.RepairPasses)" }
    elseif ($pk -eq 'target') { $rl = (T "Règles      : lecture {0} tours, {1} essais x {2} séries ; écriture tête par tête par le lecteur {5} avec la courbe croisée {5} → {6}, telle quelle, sans calibration ni mesure de la destination, effacement avant l'écriture, vérification gw, {3} essais par piste ; contrôle de toutes les pistes, {4} passes de réécriture au plus ; relecture finale par le lecteur {5} sans nouvel essai.") -f "$($rr.ReadRevs)", "$($rr.ReadRetries)", "$($rr.SeekRetries + 1)", "$($rr.WriteRetries)", "$($rr.RepairPasses)", "$($r.Drive)", "$rtg" }
    elseif ($pk -eq 'refused' -and $pp -and $pp.Ti.BlockKind -eq 'hd') { $rl = (T "Règles      : lecture {0} tours, {1} essais x {2} séries ; écriture pour le lecteur cible {3} non atteinte (elle serait refusée en haute densité : la calibration croisée n'existe qu'en double densité).") -f "$($rr.ReadRevs)", "$($rr.ReadRetries)", "$($rr.SeekRetries + 1)", "$rtg" }
    elseif ($pk -eq 'refused' -and $pp) { $rl = (T "Règles      : lecture {0} tours, {1} essais x {2} séries ; écriture pour le lecteur cible {3} non atteinte (elle serait refusée sans courbe croisée standard {4} → {3}).") -f "$($rr.ReadRevs)", "$($rr.ReadRetries)", "$($rr.SeekRetries + 1)", "$rtg", "$($r.Drive)" }
    elseif ($pk -eq 'refused') { $rl = (T "Règles      : lecture {0} tours, {1} essais x {2} séries ; écriture pour le lecteur cible {3} refusée, rien n'a été écrit.") -f "$($rr.ReadRevs)", "$($rr.ReadRetries)", "$($rr.SeekRetries + 1)", "$rtg" }
    elseif ($pk -eq 'hd') { $rl = (T "Règles      : lecture {0} tours, {1} essais x {2} séries ; écriture tête par tête avec la courbe haute densité existante du lecteur, sinon le profil d'origine, sans calibration ni mesure de la destination (jamais en haute densité), pré-effacement de chaque piste, vérification gw, {3} essais par piste ; pas de contrôle des pistes (non applicable à la haute densité) ; relecture finale sans nouvel essai.") -f "$($rr.ReadRevs)", "$($rr.ReadRetries)", "$($rr.SeekRetries + 1)", "$($rr.WriteRetries)" }
    # 12.10 (relecture de la RC) : copie secteur, liste « Mesure » a « complete, au motif » : mesure complete de la
    # destination (Get-LevelBeforeWriteKind ; liste figee pendant la restauration, onglets verrouilles : Set-RsLock)
    elseif ((Get-LevelBeforeWriteKind 'slow' $true $false) -eq 'complete') { $rl = (T "Règles      : lecture {0} tours, {1} essais x {2} séries ; destination mesurée avant l'écriture quand c'est possible (mesure complète de cette disquette, liste « Mesure » de l'onglet Écriture) ; écriture tête par tête, calibration existante conservée (calibration par tête en test fin si aucune n'existe), effacement avant l'écriture (haute fréquence en double densité, pré-effacement en haute densité), vérification gw, {3} essais par piste ; contrôle de toutes les pistes, {4} passes de réécriture au plus ; relecture finale sans nouvel essai.") -f "$($rr.ReadRevs)", "$($rr.ReadRetries)", "$($rr.SeekRetries + 1)", "$($rr.WriteRetries)", "$($rr.RepairPasses)" }
    else { $rl = (T "Règles      : lecture {0} tours, {1} essais x {2} séries ; destination mesurée avant l'écriture quand c'est possible (calibration rapide) ; écriture tête par tête, calibration existante conservée (calibration par tête en test fin si aucune n'existe), effacement avant l'écriture (haute fréquence en double densité, pré-effacement en haute densité), vérification gw, {3} essais par piste ; contrôle de toutes les pistes, {4} passes de réécriture au plus ; relecture finale sans nouvel essai.") -f "$($rr.ReadRevs)", "$($rr.ReadRetries)", "$($rr.SeekRetries + 1)", "$($rr.WriteRetries)", "$($rr.RepairPasses)" }
    $L.Add($rl)
    $L.Add('')
    $L.Add((T 'Étapes :'))
    $marks = @{ pending = '[ ]'; run = '[>]'; ok = '[OK]'; fail = '[ECHEC]'; skip = '[-]'; warn = '[!]' }
    for ($i = 0; $i -lt $script:RsStepNames.Count; $i++) {
        $s = if ($r.Steps.ContainsKey($i)) { $r.Steps[$i] } else { @{ State = 'pending'; Detail = '' } }
        $L.Add(("  {0,-7} {1}{2}" -f $marks[$s.State], $script:RsStepNames[$i], $(if ($s.Detail) { ' : ' + $s.Detail } else { '' })))
    }
    if ($script:LastCheck) { $L.Add(''); $L.Add($script:LastCheck.Text) }
    $L.Add('')
    $L.Add(((T "Verdict     : {0}") -f "$verdict"))
    # Echec avant la fin de la detection (format pas encore connu) : rapport sous le nom de la restauration, sans ecrasement
    if (-not $r.Report) { $r.Report = $(if ($r.Stem) { $r.Stem } else { Get-RestoreStem $r.Dir $r.Name }) + ' - ' + (T 'rapport') + '.txt' }
    try { [System.IO.File]::WriteAllLines($r.Report, $L, (New-Object System.Text.UTF8Encoding($true))); Append-Log ((T "Rapport     : {0}") -f "$($r.Report)") }
    catch { Append-Log ((T "Rapport non enregistré : {0}") -f "$($_.Exception.Message)") }
}

function Show-RestoreResult([bool]$ok, [string]$text, [string]$icon = '') {
    # 12.8 (lot 3b) : icone d etat de 48 px dans la marge gauche du verdict : h0 reussie, h1 reussie avec reserve, h2 echouee
    $script:RsResultIcon = $(if ($icon) { $icon } elseif ($ok) { 'h0' } else { 'h2' })
    $lblRsResult.Text = $text
    # 12.8 (FIX3) : reussie avec reserve (h1) : teinte « stop » de frmClean et encre Theme.WarnInk (4,84:1), comme l icone h1
    # de la carte et de l onglet Ecriture, et non le vert de la reussite
    $warnRes = ($ok -and $script:RsResultIcon -eq 'h1')
    $lblRsResult.BackColor = if ($warnRes) { [System.Drawing.Color]::FromArgb(253, 243, 228) } elseif ($ok) { [System.Drawing.Color]::FromArgb(222, 244, 228) } else { [System.Drawing.Color]::FromArgb(252, 226, 224) }
    $lblRsResult.ForeColor = if ($warnRes) { $script:Theme.WarnInk } elseif ($ok) { [System.Drawing.Color]::FromArgb(20, 90, 45) } else { [System.Drawing.Color]::FromArgb(140, 30, 25) }
    $pnlRsWait.Visible = $false; $lblRsNow.Text = ''
    $lblRsResult.Visible = $true; $lblRsResult.BringToFront(); $lblRsRules.Visible = $false
    $tabRs.ScrollControlIntoView($lblRsResult)
}

function Finish-Restore {
    $r = $script:Restore
    if (-not $r) { return }
    $chk = $script:LastCheck
    $reasons = @()
    if ($chk -and -not $chk.Ok) { $reasons += $chk.Short }
    if ($r.Mode -eq 'sector' -and -not ($r.Cmp -and $r.Cmp.Ok)) { $reasons += $(if ($r.Cmp) { $r.Cmp.Text } else { (T 'comparaison non faite') }) }
    $ok = ($reasons.Count -eq 0)
    if ($ok) {
        $verdict = (T 'RESTAURATION RÉUSSIE')
        # Pistes instables reellement reecrites (un tour fige) et pistes instables preservees (cylindres non reecrits)
        $pres = @{}; foreach ($c in @($r.Preserved)) { if ($null -ne $c) { $pres[[int]$c] = $true } }
        $weakAll = if ($r.Read -and $r.Read.WeakKeys) { @($r.Read.WeakKeys.Keys) } else { @() }
        $nWeak = @($weakAll | Where-Object { -not $pres.ContainsKey([int](([string]$_ -split '\.')[0])) }).Count
        $nKept = $weakAll.Count - $nWeak
        $nPres = $pres.Count
        if ($nWeak -gt 0 -or $nPres -gt 0) { $verdict += (T ' (avec réserve : protection non reproductible)') }
        $detail = if ($r.Mode -eq 'sector' -and -not $chk) { (T 'La copie a été écrite tête par tête et elle est identique à l''original, secteur par secteur. Le contrôle des pistes ne s''applique pas à ce format (haute densité).') }
                  elseif ($r.Mode -eq 'sector') { (T 'La copie a été écrite tête par tête, toutes ses pistes sont saines et elle est identique à l''original, secteur par secteur.') }
                  else { (T 'Le flux a été recopié et toutes les pistes de la copie sont saines. Sans format, la copie n''est pas comparée secteur par secteur : essayez-la sur la machine d''origine.') }
        if ($nWeak -gt 0) { $detail += ((T " Attention : {0} piste(s) de l'original non reproductible(s) (zone instable, protection contre la copie probable) : la copie n'en a reçu qu'un tour figé et risque de ne pas fonctionner.") -f "$nWeak") }
        if ($nKept -gt 0) { $detail += ((T " {0} piste(s) non reproductible(s) de l'original préservée(s), non réécrite(s) : protection d'origine intacte.") -f "$nKept") }
        if ($nPres -gt 0) { $detail += ((T " Cylindres {0} ni réécrits ni contrôlés (disquette reconnue comme l'original) : s'il s'agissait d'une copie, elle est incomplète ; effacez-la puis relancez la restauration.") -f "$(Format-CylList @($pres.Keys | Sort-Object))") }
    } else {
        $verdict = (T 'RESTAURATION ÉCHOUÉE') + ' : ' + ($reasons -join ' ; ')
        $detail = (T 'Essayez une autre disquette de destination ; si le problème persiste, nettoyez les têtes du lecteur. Le détail est dans le rapport.')
    }
    Append-Log $verdict
    Write-RestoreReport $ok $verdict
    Show-RestoreResult $ok ($verdict + "`n`n" + $detail) $(if ($ok -and ($nWeak -gt 0 -or $nPres -gt 0)) { 'h1' } else { '' })
    Close-Restore
}

function Fail-Restore([int]$step, [string]$why) {
    $r = $script:Restore
    if (-not $r) { return }
    # Revue 12.8.2 : echec pendant l ecriture sur une disquette identique a l original (« Ecraser quand meme ») : pistes
    # effacees en haute frequence par cette ecriture (EraseLog de Start-ImageWrite, remis a $null par Start-RestoreWrite)
    # et jamais ecrites ensuite : citees au journal et dans le resultat, avec l image lue qui les contient
    $lost = @()
    if ($r.OnOriginal -and [string]$r.Stage -eq 'write' -and $script:EraseLog -and [string]$script:EraseLog.Owner -eq 'write') {
        $el = $script:EraseLog
        $lost = Sort-TrackKeys @(@($el.Erased.Keys) | Where-Object { -not $el.Written.ContainsKey([string]$_) })
    }
    $r.Stage = 'failed'
    $script:Chain.Clear(); $script:WriteQueue.Clear(); $script:GwCapture = $null; $script:AfterCalib = ''
    if ($script:FmtDetect -and $script:FmtDetect.Owner -eq 'restore') { $script:FmtDetect = $null }   # FIX2 : detection interrompue (erreur gw)
    Stop-WriteWarmup
    if ($step -ge 0) { Set-RsStep $step 'fail' $why }
    $verdict = (T 'RESTAURATION ÉCHOUÉE') + ' : ' + $why
    Append-Log $verdict
    $lostTxt = ''
    if (@($lost).Count -gt 0) {
        $lostTxt = (T "Pistes de la disquette d'origine effacées et non réécrites : {0}. Leur contenu est dans l'image lue {1} : écrivez cette image sur la disquette pour les rétablir.") -f "$(Format-TrackList $lost)", "$([System.IO.Path]::GetFileName([string]$r.Orig))"
        Append-Log $lostTxt
    }
    Write-RestoreReport $false $verdict
    $note = if ($step -le 1) { (T 'Rien n''a été écrit : la disquette de destination n''a pas été touchée.') } else { (T 'Le détail est dans le journal et dans le rapport.') }
    if ($lostTxt) { $note = $lostTxt + "`n`n" + $note }
    Show-RestoreResult $false ($verdict + "`n`n" + $note)
    Close-Restore
}

function Stop-Restore([string]$why) {
    # Abandon (bouton Arreter ou Annuler, erreur gw, operation incomplete, sequence bloquee) ; sans effet hors restauration
    $r = $script:Restore
    if (-not $r) { return }
    Fail-Restore ([int]$r.Cur) $why
}

function Close-Restore {
    $r = $script:Restore
    $script:Restore = $null
    # Reglages de l onglet Ecriture retablis, puis enregistres : fin de la surcharge d operation (12.8, D4)
    if ($r) {
        if ($script:OpOverride) { Exit-OpOverride }
        else { Restore-WriteTabState $r.Saved; [void](Save-Config) }
    }
    Set-RsLock $false
    $pnlRsWait.Visible = $false
    # 12.10 (relecture de la RC8 et de la RC9) : restauration close sans commande gw depuis l attente de la disquette de
    # destination (« Annuler » pendant l attente, « Arreter » y etant inactif ; « Ecraser quand meme » puis echec avant
    # toute commande gw, par exemple fenetre « Calibration precomp » annulee) : la consigne d Enter-RestoreWait, que seule
    # une commande gw remplace (Start-Progress), ne reste pas dans la barre d etat ; etat neutre du demarrage
    if ($r -and ($r.Waiting -or [string]$stOp.Text -eq (T 'Restauration : changez de disquette, puis cliquez sur « Continuer ».'))) { $stOp.Text = (T 'Prêt.'); $stOp.Image = $script:StIcons.idle }
    # 12.11 : autre fin : la barre d etat annoncera le resultat de la restauration une fois l application au repos
    # (Set-SeqEnd, 110), d apres l icone du verdict que Show-RestoreResult vient de poser (h0 reussie, h1 reussie avec
    # reserve, h2 echouee). Elle gardait « Lecture termine(e) », le compteur et la barre de la derniere relecture. Echec
    # sur une erreur gw ou gw non lance : l etat de la commande reste affiche (Update-SeqEnd, Set-GwLaunchFailedStatus)
    elseif ($r) {
        switch ([string]$script:RsResultIcon) {
            'h0' { Set-SeqEnd (T 'Restauration réussie') 'ok' }
            'h1' { Set-SeqEnd (T 'Restauration réussie avec réserve') 'idle' }
            'h2' { Set-SeqEnd (T 'Restauration échouée') 'err' }
        }
    }
    Update-RsCalib
}
# --- Fenetre -------------------------------------------------------------------
$form = New-Object System.Windows.Forms.Form
$form.Text = "Greaseweazle Studio v$($script:Version)"
# Largeur : cartes de l Accueil (colonne de droite jusqu a 770 px) sans defilement horizontal avec la barre verticale,
# a la taille par defaut comme a la taille minimale (12.6 : 790 et 800 px auparavant, 5 et 11 px de defilement)
$form.ClientSize = New-Object System.Drawing.Size(800, 682)
$form.MinimumSize = New-Object System.Drawing.Size(816, 620)
$form.StartPosition = 'CenterScreen'
$form.Font = New-Object System.Drawing.Font('Segoe UI', 9.75)
$form.BackColor = [System.Drawing.Color]::FromArgb(236, 239, 244)
$mono     = New-Object System.Drawing.Font('Consolas', 9.5)
$monoBig  = New-Object System.Drawing.Font('Consolas', 10.5)
$tip  = New-Object System.Windows.Forms.ToolTip
$bold = New-Object System.Drawing.Font('Segoe UI', 9.75, [System.Drawing.FontStyle]::Bold)   # utilise des la bibliotheque
# Infobulles : delai de lecture suffisant pour les textes longs (5 s par defaut sous WinForms)
$tip.AutoPopDelay = 30000; $tip.InitialDelay = 400; $tip.ReshowDelay = 100

# Textes indicatifs gris dans les champs vides (EM_SETCUEBANNER) : appliques a l affichage de la fenetre, une fois
# les poignees Windows creees. Sans effet sur une zone multiligne.
$script:CueOk = $false
try {
    Add-Type -Namespace GwUi -Name Native -MemberDefinition '[DllImport("user32.dll", CharSet = CharSet.Unicode)] public static extern IntPtr SendMessage(IntPtr hWnd, int msg, IntPtr wParam, string lParam);' -ErrorAction Stop
    $script:CueOk = $true
} catch { }
$script:CueText = @{}

# Aide en ligne : page du wiki associee a l onglet courant (TabPage.Tag), touche F1 ou bouton Aide du bandeau
$script:WikiBase = 'https://github.com/Bartozorus/GreaseweazleGUI_Studio/wiki/'


# ============================== THEME, ICONES & LOGO ===========================
# Aucun fichier image externe : les icones sont rendues a l'execution a partir de la police
# d'icones de Windows (Segoe Fluent Icons sur Windows 11, Segoe MDL2 Assets sur Windows 10),
# le logo est dessine en GDI+.
$script:Theme = @{
    Accent  = [System.Drawing.Color]::FromArgb(37, 99, 168)
    Accent2 = [System.Drawing.Color]::FromArgb(22, 54, 98)
    Danger  = [System.Drawing.Color]::FromArgb(196, 60, 52)
    Ok      = [System.Drawing.Color]::FromArgb(46, 139, 87)
    Good    = [System.Drawing.Color]::FromArgb(96, 140, 44)    # 12.8 (D17) : niveau BON des icones de score ; 3,97:1 sur blanc (element graphique, >= 3:1)
    Warn    = [System.Drawing.Color]::FromArgb(214, 140, 30)
    WarnInk = [System.Drawing.Color]::FromArgb(156, 92, 8)     # 12.8 (D17) : texte d avertissement sur fond clair ; contraste WCAG 5,14:1 sur Page, 5,32:1 sur blanc, 4,61:1 sur Window (176,104,10 : 4,20:1 sur Page)
    Muted   = [System.Drawing.Color]::FromArgb(110, 116, 128)
    Page    = [System.Drawing.Color]::FromArgb(250, 251, 253)
    Window  = [System.Drawing.Color]::FromArgb(236, 239, 244)
    Floppy  = [System.Drawing.Color]::FromArgb(44, 58, 85)
    Flux    = [System.Drawing.Color]::FromArgb(255, 150, 50)
    Folder  = [System.Drawing.Color]::FromArgb(222, 170, 60)
    Zip     = [System.Drawing.Color]::FromArgb(130, 90, 170)
}
$script:IconFont = $null
try {
    $fams = @((New-Object System.Drawing.Text.InstalledFontCollection).Families | ForEach-Object { $_.Name })
    foreach ($f in @('Segoe Fluent Icons','Segoe MDL2 Assets')) { if ($fams -contains $f) { $script:IconFont = $f; break } }
} catch { }
$script:Glyph = @{
    Library=0xE8F1; Save=0xE74E; Download=0xE896; Switch=0xE8AB; Copy=0xE8C8; Diagnostic=0xE9D9
    Repair=0xE90F; Stopwatch=0xE916; Cmd=0xE756; Folder=0xE8B7; FolderOpen=0xE838; Search=0xE721
    Refresh=0xE72C; Sync=0xE895; OpenFile=0xE8E5; Document=0xE8A5; Package=0xE7B8; Page=0xE7C3
    Stop=0xE71A; Delete=0xE74D; Setting=0xE713; Info=0xE946; Error=0xE783; Check=0xE73E
    Play=0xE768; Pin=0xE718; Usb=0xE88E; Add=0xE710; Remove=0xE738; Home=0xE80F; Help=0xE897; History=0xE81C
}

$script:BtnHoverNormal = [System.Drawing.Color]::FromArgb(232, 238, 247)

$script:LogoBig   = New-LogoBitmap 48
$script:LogoIcon  = New-LogoBitmap 32

# Les TabPage recoivent une taille explicite AVANT l ajout des controles :
# WinForms calcule les decalages d ancrage a ce moment-la. Sans cela, un
# controle ancre a droite est positionne par rapport a une page de 200 px
# et se retrouve hors ecran une fois la page etiree.
$script:PageW = 782
$script:PageH = 340

# --- Bandeau (logo, titre, lecteur) --------------------------------------------
$pnlTop = New-Object System.Windows.Forms.Panel
$pnlTop.Size = New-Object System.Drawing.Size(790, 64)
$pnlTop.Dock = 'Top'
$pnlTop.BackgroundImageLayout = 'None'
$pnlTop.Add_Resize({ Render-Banner })

$lblGwStatus = New-BannerLabel '' '556,10'
$lblGwStatus.Font = New-Object System.Drawing.Font('Segoe UI Semibold', 9)
if (Test-Path -LiteralPath $script:GwExe) {
    $lblGwStatus.Text = (T '●  gw.exe prêt'); $lblGwStatus.ForeColor = [System.Drawing.Color]::FromArgb(150, 235, 160)
} else {
    $lblGwStatus.Text = (T '●  gw.exe introuvable'); $lblGwStatus.ForeColor = [System.Drawing.Color]::FromArgb(255, 160, 150)
}
$tip.SetToolTip($lblGwStatus, $script:GwExe)

$cmbDrive = New-Object System.Windows.Forms.ComboBox
$cmbDrive.Location = '556,34'; $cmbDrive.Width = 45; $cmbDrive.DropDownStyle = 'DropDownList'
$cmbDrive.Anchor = 'Top,Right'
[void]$cmbDrive.Items.AddRange(@('A','B','0','1','2','3'))
$tip.SetToolTip($cmbDrive, (T "A/B = bus IBM-PC (nappe avec twist) - typiquement le lecteur PC`n0 à 3 = bus Shugart (nappe droite) - typiquement le lecteur Amiga`nAu démarrage, l'application sélectionne le premier lecteur qui répond."))
Register-SettingCtl 'drive' $cmbDrive          # 12.8 (point 7) : lecteur de toute l application (fenetre de nettoyage comprise)
# 12.11 (lot LN-b) : lecteurs enregistres (112). Seul un choix fait dans la liste deroulee vaut confirmation du lecteur
# branche (Set-DriveHandChoice) ; molette sans effet sur la liste fermee, avec ou sans lecteur enregistre (un geste
# involontaire changeait de lecteur) : evenement marque traite ; liste deroulee, la molette la fait defiler comme avant
$cmbDrive.Add_SelectionChangeCommitted({ Set-DriveHandChoice $this.DroppedDown })
$cmbDrive.Add_MouseWheel({ if (-not $this.DroppedDown -and $_ -is [System.Windows.Forms.HandledMouseEventArgs]) { $_.Handled = $true } })

$txtDev = New-Object System.Windows.Forms.TextBox
$txtDev.Location = '652,34'; $txtDev.Width = 50; $txtDev.Anchor = 'Top,Right'
$tip.SetToolTip($txtDev, (T 'Port COM du Greaseweazle. Vide = détection automatique.'))

$chkTime = New-Object System.Windows.Forms.CheckBox
$chkTime.Text = (T 'Chrono'); $chkTime.Location = '712,35'; $chkTime.Width = 70; $chkTime.Anchor = 'Top,Right'
$chkTime.BackColor = [System.Drawing.Color]::Transparent; $chkTime.ForeColor = [System.Drawing.Color]::White
$tip.SetToolTip($chkTime, (T 'Affiche le temps écoulé après chaque commande gw (option --time).'))

# Mode expert : affiche aussi les onglets techniques (Conversion, Comparaison, Outils, Délais, Commande libre)
$chkExpert = New-Object System.Windows.Forms.CheckBox
$chkExpert.Text = (T 'Mode expert'); $chkExpert.Location = '404,5'; $chkExpert.AutoSize = $true; $chkExpert.Anchor = 'Top,Right'
$chkExpert.BackColor = [System.Drawing.Color]::Transparent; $chkExpert.ForeColor = [System.Drawing.Color]::White
$tip.SetToolTip($chkExpert, (T "Décoché : seuls les onglets utiles au quotidien sont affichés (Accueil, Restauration, Bibliothèque, Écriture, Lecture, Qualité).`nCoché : tous les onglets, y compris Conversion, Comparaison, Outils, Délais et Commande libre.") + "`n" + (T "Coché : affiche aussi les options avancées de l'onglet Écriture."))   # 12.11 (L9) : options avancees de l onglet Ecriture (Set-WriteTabLayout, 145)

# Aide en ligne (wiki) pour l onglet affiche ; touche F1. 12.8 (lot 5) : hauteur de 34 px (deux hauteurs de bouton, 34 et
# 40 px), centree sur la rangee du lecteur ; case « Mode expert » remontee de 4 px au-dessus
$btnHelpTop = New-Object System.Windows.Forms.Button
$btnHelpTop.Text = (T 'Aide'); $btnHelpTop.Location = '404,28'; $btnHelpTop.Size = '84,34'; $btnHelpTop.Anchor = 'Top,Right'
$btnHelpTop.Add_Click({ Open-HelpForTab })
$tip.SetToolTip($btnHelpTop, (T 'Ouvre le guide en ligne de l''onglet affiché (touche F1).'))

# 12.11 (lot LN-b) : libelles nommes : texte et place du libelle du lecteur, place de « COM : » selon les lecteurs
# enregistres (Set-DriveBannerLayout, 112 : positions de la 12.10 sans lecteur enregistre ayant une connexion)
$lblDrive = New-BannerLabel (T 'Lecteur :') '500,37'
$lblCom = New-BannerLabel (T 'COM :') '612,37'
$pnlTop.Controls.AddRange(@($lblGwStatus, $lblDrive, $cmbDrive,
    $lblCom, $txtDev, $chkTime, $chkExpert, $btnHelpTop))
$script:DriveBanner = $null      # 12.11 (lot LN-b) : positions de la 12.10, relevees au premier appel de Set-DriveBannerLayout

# --- Separateur onglets / journal ----------------------------------------------
$split = New-Object System.Windows.Forms.SplitContainer
$split.Orientation = 'Horizontal'
$split.Size = New-Object System.Drawing.Size(790, 644)
$split.Panel1MinSize = 300
$split.Panel2MinSize = 80
$split.SplitterWidth = 6
$split.SplitterDistance = 372
$split.Dock = 'Fill'

$tabs = New-Object System.Windows.Forms.TabControl
$tabs.Dock = 'Fill'
$tabs.Padding = New-Object System.Drawing.Point(12, 5)
# 12.11 (L9) : onglets sur plusieurs rangees plutot que des fleches : en mode expert, les onze onglets sur deux rangees a la
# taille par defaut de la fenetre (26 px de hauteur en moins pour chaque onglet) ; les six onglets courants tiennent sur une
# rangee. Comportement de Windows : la rangee de l onglet choisi passe devant
$tabs.Multiline = $true

# ============================== BIBLIOTHEQUE ===================================
$tabL = New-TabPage (T 'Bibliothèque')

$txtLibRoot = New-Object System.Windows.Forms.TextBox
$txtLibRoot.Location = '85,11'; $txtLibRoot.Width = 240; $txtLibRoot.Anchor = 'Top,Left,Right'

$btnLibRoot = New-Object System.Windows.Forms.Button
$btnLibRoot.Text = (T 'Choisir le dossier racine'); $btnLibRoot.Location = '330,10'; $btnLibRoot.Width = 36; $btnLibRoot.Anchor = 'Top,Right'
$btnLibRoot.Add_Click({
    $d = New-Object System.Windows.Forms.FolderBrowserDialog
    $d.Description = (T 'Répertoire racine de la bibliothèque d''images')
    if ($txtLibRoot.Text -and (Test-Path -LiteralPath $txtLibRoot.Text)) { $d.SelectedPath = $txtLibRoot.Text }
    if ($d.ShowDialog() -eq 'OK') { $txtLibRoot.Text = $d.SelectedPath; Update-Library }
})

$btnLibRefresh = New-Object System.Windows.Forms.Button
$btnLibRefresh.Text = (T 'Actualiser l''arborescence'); $btnLibRefresh.Location = '372,10'; $btnLibRefresh.Width = 36; $btnLibRefresh.Anchor = 'Top,Right'
$btnLibRefresh.Add_Click({ Update-Library })

# 12.8 (lot 4b, D19, A3 § 3.4 B) : liste de reference (DAT) choisie par l utilisateur sur son ordinateur ; etat a cote du
# bouton (aucune, nom et nombre d entrees, illisible) ; retrait par la croix (le fichier n est pas supprime)
$btnLibDat = New-Object System.Windows.Forms.Button
$btnLibDat.Text = (T 'Liste de référence…'); $btnLibDat.Location = '414,10'; $btnLibDat.Width = 168; $btnLibDat.Anchor = 'Top,Right'
$tip.SetToolTip($btnLibDat, (T "Choisit une liste de référence (fichier DAT) sur votre ordinateur : format Logiqx XML (TOSEC, No-Intro) ou clrmamepro.`nLes images et les archives ZIP sont identifiées par leur taille puis leur empreinte (CRC-32, MD5 ou SHA-1) :`nofficiel (identique à une entrée de la liste), modifié (même nom qu'une entrée, contenu différent) ou inconnu.`nAucune liste n'est fournie ni téléchargée par l'application."))
$btnLibDat.Add_Click({ Select-LibDatFile })

$lblLibDat = New-Object System.Windows.Forms.Label
$lblLibDat.Location = '586,14'; $lblLibDat.Size = '164,18'; $lblLibDat.Anchor = 'Top,Right'; $lblLibDat.AutoEllipsis = $true
$lblLibDat.Font = New-Object System.Drawing.Font('Segoe UI', 9); $lblLibDat.ForeColor = $script:Theme.Muted; $lblLibDat.Text = (T 'aucune')

$btnLibDatClear = New-Object System.Windows.Forms.Button
$btnLibDatClear.Text = (T 'Retirer la liste de référence (le fichier n''est pas supprimé).'); $btnLibDatClear.Location = '752,10'; $btnLibDatClear.Width = 26
$btnLibDatClear.Anchor = 'Top,Right'; $btnLibDatClear.Visible = $false
$btnLibDatClear.Add_Click({ Set-LibDatPath '' })

$txtLibFilter = New-Object System.Windows.Forms.TextBox
$txtLibFilter.Location = '85,41'; $txtLibFilter.Width = 210
$tip.SetToolTip($txtLibFilter, (T "Recherche sur le nom des fichiers : plusieurs mots = tous requis (ex. : monkey 2 fr). La casse est ignorée ; la ponctuation compte : king quest trouve KingsQuest et King's Quest, kings ne trouve pas King's.`nCase « Aussi dans les dossiers » : les mots peuvent aussi être dans le nom des dossiers.`nRésultats au fil de la frappe une fois l'index construit, groupés par jeu. Vide = arborescence."))
$txtLibFilter.Add_KeyDown({ if ($_.KeyCode -eq 'Enter') { $script:LibSearchAt = $null; Update-Library } })
$txtLibFilter.Add_TextChanged({ $script:LibSearchAt = (Get-Date).AddMilliseconds(350) })

$btnLibFilter = New-Object System.Windows.Forms.Button
$btnLibFilter.Text = (T 'Chercher'); $btnLibFilter.Location = '300,40'; $btnLibFilter.Width = 36
$btnLibFilter.Add_Click({ $script:LibSearchAt = $null; Update-Library })

# 12.8 (lot 4a, A3 § 4.2 n° 8) : recherche sur le nom du fichier par defaut ; ancienne regle (chemin complet) sur demande
$chkLibInDirs = New-Object System.Windows.Forms.CheckBox
$chkLibInDirs.Text = (T 'Aussi dans les dossiers'); $chkLibInDirs.Location = '344,42'; $chkLibInDirs.Width = 170
$tip.SetToolTip($chkLibInDirs, (T 'Cherche aussi les mots dans le nom des dossiers (chemin complet depuis la racine), comme avant la version 12.8.'))
$chkLibInDirs.Add_CheckedChanged({ if ($txtLibFilter.Text.Trim()) { Update-Library } })

$chkLibImgOnly = New-Object System.Windows.Forms.CheckBox
$chkLibImgOnly.Text = (T 'Images seulement'); $chkLibImgOnly.Location = '520,42'; $chkLibImgOnly.Width = 140
$chkLibImgOnly.Add_CheckedChanged({ Update-Library })

$btnLibReindex = New-Object System.Windows.Forms.Button
$btnLibReindex.Text = (T 'Réindexer'); $btnLibReindex.Location = '683,40'; $btnLibReindex.Width = 95; $btnLibReindex.Anchor = 'Top,Right'
$tip.SetToolTip($btnLibReindex, (T "Reconstruit l'index de la racine (en arrière-plan). À faire après l'ajout ou le déplacement de fichiers."))
$btnLibReindex.Add_Click({ Start-LibIndex $true })

# 12.8 (lot 4a, A3 § 4.2 n° 7) : filtres de la liste des resultats (inactifs dans l arborescence), en ligne
# (FlowLayoutPanel : largeurs ajustees aux textes francais et anglais) ; compteur sous la liste (FIX4B)
$flpLib = New-Object System.Windows.Forms.FlowLayoutPanel
$flpLib.Location = '6,68'; $flpLib.Size = '776,28'; $flpLib.Anchor = 'Top,Left,Right'; $flpLib.WrapContents = $false

$lblLibFmt = New-Object System.Windows.Forms.Label
$lblLibFmt.Text = (T 'Format :'); $lblLibFmt.AutoSize = $true; $lblLibFmt.Margin = New-Object System.Windows.Forms.Padding(4, 6, 0, 0)
$cmbLibFmt = New-Object System.Windows.Forms.ComboBox
$cmbLibFmt.DropDownStyle = 'DropDownList'; $cmbLibFmt.Width = 76; $cmbLibFmt.Margin = New-Object System.Windows.Forms.Padding(3, 2, 10, 0)
[void]$cmbLibFmt.Items.Add((T 'Tous')); $cmbLibFmt.SelectedIndex = 0
$tip.SetToolTip($cmbLibFmt, (T 'Formats présents dans les résultats de la recherche.'))
$cmbLibFmt.Add_SelectedIndexChanged({ Update-LibFilters })

$lblLibLang = New-Object System.Windows.Forms.Label
$lblLibLang.Text = (T 'Langue :'); $lblLibLang.AutoSize = $true; $lblLibLang.Margin = New-Object System.Windows.Forms.Padding(0, 6, 0, 0)
$cmbLibLang = New-Object System.Windows.Forms.ComboBox
$cmbLibLang.DropDownStyle = 'DropDownList'; $cmbLibLang.Width = 66; $cmbLibLang.Margin = New-Object System.Windows.Forms.Padding(3, 2, 10, 0)
[void]$cmbLibLang.Items.Add((T 'Toutes')); $cmbLibLang.SelectedIndex = 0
$tip.SetToolTip($cmbLibLang, (T "Langues indiquées dans le nom (TOSEC : (fr), (en-de) ; No-Intro : (En,Fr)), ou langue du pays (TOSEC : (DE) ; en gris dans la liste). « M3 » : trois langues, non détaillées."))
$cmbLibLang.Add_SelectedIndexChanged({ Update-LibFilters })

$chkLibHideMod = New-Object System.Windows.Forms.CheckBox
$chkLibHideMod.Text = (T 'Masquer les copies modifiées'); $chkLibHideMod.AutoSize = $true; $chkLibHideMod.Margin = New-Object System.Windows.Forms.Padding(0, 4, 8, 0)
$tip.SetToolTip($chkLibHideMod, (T 'Masque les copies dont le nom porte une mention TOSEC de modification : [cr] déplombée, [f] corrigée, [h] et [m] modifiée, [p] pirate, [t] entraîneur, [tr] traduite.'))
$chkLibHideMod.Add_CheckedChanged({ Update-LibFilters })

$chkLibOrig = New-Object System.Windows.Forms.CheckBox
$chkLibOrig.Text = (T 'Originaux seulement'); $chkLibOrig.AutoSize = $true; $chkLibOrig.Margin = New-Object System.Windows.Forms.Padding(0, 4, 8, 0)
$tip.SetToolTip($chkLibOrig, (T "Sans liste de référence : ne garde que les IPF de structure SPS (bloc INFO lu dans le fichier : publication, révision, disquette). C'est un indice d'origine, pas une preuve.`nAvec une liste de référence (bouton « Liste de référence… ») : ne garde que les fichiers officiels, identiques à une entrée de la liste."))
$chkLibOrig.Add_CheckedChanged({ Update-LibFilters })

$flpLib.Controls.AddRange(@($lblLibFmt, $cmbLibFmt, $lblLibLang, $cmbLibLang, $chkLibHideMod, $chkLibOrig))

# FIX4B (revue du lot 4) : compteur sous la liste, sur toute sa largeur (dans la ligne des filtres, il ne restait que
# 142 px a 800 px de large : « 2 affiché(s), 3 masqué(s) » et l avancement de l analyse etaient coupes)
$lblLibCount = New-Object System.Windows.Forms.Label
$lblLibCount.Location = '10,316'; $lblLibCount.Size = '448,18'; $lblLibCount.Anchor = 'Bottom,Left,Right'; $lblLibCount.AutoEllipsis = $true
$lblLibCount.Text = ''; $lblLibCount.ForeColor = 'DimGray'

